async function resetAllTestData(tenantId: string, mode: BusinessMode) {
  const testData = INDUSTRY_TEST_DATA[mode];
  const config = BUSINESS_MODES[mode];
  
  // 1. Update tenant name, mode, and modules (preserve phone_public)
  const { error: tenantError } = await supabase
    .from("tenants")
    .update({
      name: testData.tenantName,
      business_mode: mode,
      enabled_modules: config.modules,
      hipaa_mode: config.hipaa,
      // phone_public is explicitly NOT updated to preserve it
    })
    .eq("id", tenantId);
  
  if (tenantError) throw tenantError;
  
  // Note: assistant_settings (phone numbers, Twilio config) are NOT touched
  // to preserve the phone connection for AI calls

  // 2. Clear ALL industry-specific tables first
  await clearAllIndustrySpecificData(tenantId);

  // 3. Replace common tables (services, FAQs, knowledge base, etc.)
  await supabase.from("services").delete().eq("tenant_id", tenantId);
  if (testData.services.length > 0) {
    const { error: servicesError } = await supabase
      .from("services")
      .insert(testData.services.map(s => ({
        tenant_id: tenantId,
        name: s.name,
        description: s.description,
        duration_minutes: s.duration_minutes,
        price_amount: s.price_amount,
        price_type: s.price_type,
        is_active: true,
      })));
    if (servicesError) throw new Error(`Services: ${servicesError.message}`);
  }

  // 4. Replace FAQs
  await supabase.from("business_faqs").delete().eq("tenant_id", tenantId);
  if (testData.faqs.length > 0) {
    const { error: faqsError } = await supabase
      .from("business_faqs")
      .insert(testData.faqs.map((f, i) => ({
        tenant_id: tenantId,
        question: f.question,
        answer: f.answer,
        priority_weight: testData.faqs.length - i,
      })));
    if (faqsError) throw new Error(`FAQs: ${faqsError.message}`);
  }

  // 5. Replace knowledge base policies
  await supabase.from("ai_knowledge_base").delete().eq("tenant_id", tenantId);
  if (testData.policies.length > 0) {
    const { error: policiesError } = await supabase
      .from("ai_knowledge_base")
      .insert(testData.policies.map((p, i) => ({
        tenant_id: tenantId,
        title: p.title,
        content: p.content,
        type: p.type,
        priority_weight: testData.policies.length - i,
      })));
    if (policiesError) throw new Error(`Policies: ${policiesError.message}`);
  }

  // 6. Replace objection responses
  await supabase.from("objection_responses").delete().eq("tenant_id", tenantId);
  if (testData.objections.length > 0) {
    const { error: objectionsError } = await supabase
      .from("objection_responses")
      .insert(testData.objections.map((o, i) => ({
        tenant_id: tenantId,
        objection: o.objection,
        response: o.response,
        priority_weight: testData.objections.length - i,
      })));
    if (objectionsError) throw new Error(`Objections: ${objectionsError.message}`);
  }

  // 7. Replace availability hours
  await supabase.from("availability_slots").delete().eq("tenant_id", tenantId);
  if (testData.hours.length > 0) {
    const { error: hoursError } = await supabase
      .from("availability_slots")
      .insert(testData.hours.map(h => ({
        tenant_id: tenantId,
        day_of_week: h.day_of_week,
        start_time: h.start_time,
        end_time: h.end_time,
        is_available: h.is_available,
      })));
    if (hoursError) throw new Error(`Hours: ${hoursError.message}`);
  }

  // 8. Replace call sessions
  await supabase.from("ai_call_sessions").delete().eq("tenant_id", tenantId);
  const now = new Date();
  const callRecords = testData.calls.map((data, index) => ({
    tenant_id: tenantId,
    caller_phone: TEST_PHONES[index % TEST_PHONES.length],
    call_direction: "inbound" as const,
    started_at: new Date(now.getTime() - (index + 1) * 3600000).toISOString(),
    ended_at: new Date(now.getTime() - (index + 1) * 3600000 + 300000).toISOString(),
    outcome: data.outcome,
    summary: data.summary,
    context_json: {
      customer_name: data.customer_name,
      service_requested: data.service_requested,
      booking_confirmed: data.outcome === "booked",
      ...data.context_extra,
    },
  }));

  const { error: callsError } = await supabase
    .from("ai_call_sessions")
    .insert(callRecords);

  if (callsError) throw new Error(`Calls: ${callsError.message}`);

  // 9. Insert industry-specific data based on mode
  if (mode === "food") {
    await insertFoodModeData(tenantId);
  } else if (mode === "dispatch") {
    await insertDispatchModeData(tenantId);
  } else if (mode === "medical") {
    await insertMedicalModeData(tenantId);
  }
}

export function AdminModeSwitcher() {
  const { tenant, user, isSuperAdmin } = useAuth();
  const adminMode = useAdminMode();
  const [isLoading, setIsLoading] = useState(false);

  // P0-1: Only show for super_admin users - this component injects test data
  // and should NEVER be visible to regular tenants in production
  if (!tenant || !user || !isSuperAdmin) return null;

  const currentMode = (adminMode?.selectedMode ?? (tenant.business_mode as BusinessMode) ?? "service");
  const CurrentIcon = BUSINESS_MODES[currentMode]?.icon || Briefcase;

  const handleModeChange = async (newMode: BusinessMode) => {
    if (newMode === currentMode || isLoading) return;
    
    setIsLoading(true);
    try {
      // 1) Persist selected mode
      if (adminMode) await adminMode.setSelectedMode(newMode);

      // 2) Validate we have at least one tenant for that mode.
      // The actual active-tenant switch happens in AdminTenantSwitcher (auto-picks first match).
      const { data, error } = await supabase
        .from("tenants")
        .select("id")
        .eq("business_mode", newMode)
        .limit(1);

      if (error) throw error;
      if (!data || data.length === 0) {
        toast.error(`No ${BUSINESS_MODES[newMode].label} tenant found. Create one from the tenant dropdown.`);
      }
    } catch (error) {
      console.error("Failed to switch mode:", error);
      toast.error("Failed to switch business mode");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="bg-warning/10 border-b border-warning/20">
      <div className="flex items-center justify-center gap-3 px-4 py-2 text-sm">
        <FlaskConical className="h-4 w-4 text-warning" />
        <span className="text-warning font-medium">
          Testing Mode:
        </span>
        
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button 
              variant="outline" 
              size="sm" 
              disabled={isLoading}
              className="h-7 gap-1.5 bg-background border-warning/30 hover:bg-warning/10"
            >
              {isLoading ? (
                <Loader2 className="h-3.5 w-3.5 animate-spin" />
              ) : (
                <CurrentIcon className="h-3.5 w-3.5" />
              )}
              {BUSINESS_MODES[currentMode]?.label || "Select Mode"}
              <ChevronDown className="h-3.5 w-3.5" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="center" className="w-48">
            {Object.entries(BUSINESS_MODES).map(([mode, config]) => {
              const Icon = config.icon;
              return (
                <DropdownMenuItem
                  key={mode}
                  onClick={() => handleModeChange(mode as BusinessMode)}
                  className={mode === currentMode ? "bg-accent" : ""}
                  disabled={isLoading}
                >
                  <Icon className="h-4 w-4 mr-2" />
                  {config.label}
                </DropdownMenuItem>
              );
            })}
          </DropdownMenuContent>
        </DropdownMenu>
        
        <span className="text-muted-foreground text-xs hidden sm:inline">
          ({tenant.name})
        </span>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Phone, Check, Loader2, AlertCircle, Info } from "lucide-react";
import { toast } from "sonner";

// Normalize phone number to E.164 format
function normalizeToE164(phone: string): string {
  if (!phone) return "";
  const digits = phone.replace(/\D/g, "");
  if (digits.length === 11 && digits.startsWith("1")) return `+${digits}`;
  if (digits.length === 10) return `+1${digits}`;
  if (phone.startsWith("+")) return phone;
  return digits.length > 0 ? `+${digits}` : "";
}

// Format phone for display
function formatPhoneDisplay(phone: string): string {
  if (!phone) return "";
  const digits = phone.replace(/\D/g, "");
  if (digits.length === 11 && digits.startsWith("1")) {
    return `+1 (${digits.slice(1, 4)}) ${digits.slice(4, 7)}-${digits.slice(7)}`;
  }
  if (digits.length === 10) {
    return `+1 (${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`;
  }
  return phone;
}

export function AdminPhoneSettings() {
  const { user, isSuperAdmin } = useAuth();
  const [phoneNumber, setPhoneNumber] = useState("");
  const [savedPhone, setSavedPhone] = useState<string | null>(null);
  const [isVerified, setIsVerified] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);

  // Fetch current admin phone settings
  useEffect(() => {
    if (!user || !isSuperAdmin) return;

    const fetchSettings = async () => {
      setIsLoading(true);
      try {
        const { data, error } = await supabase
          .from("admin_settings")
          .select("admin_phone_e164, admin_phone_verified")
          .eq("user_id", user.id)
          .maybeSingle();

        if (error) throw error;

        if (data?.admin_phone_e164) {
          setSavedPhone(data.admin_phone_e164);
          setPhoneNumber(formatPhoneDisplay(data.admin_phone_e164));
          setIsVerified(data.admin_phone_verified || false);
        }
      } catch (error) {
        console.error("Failed to fetch admin phone settings:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchSettings();
  }, [user, isSuperAdmin]);

  const handleSavePhone = async () => {
    if (!user || !phoneNumber.trim()) return;

    const normalizedPhone = normalizeToE164(phoneNumber);
    if (!normalizedPhone || normalizedPhone.length < 10) {
      toast.error("Please enter a valid phone number");
      return;
    }

    setIsSaving(true);
    try {
      const { error } = await supabase
        .from("admin_settings")
        .upsert({
          user_id: user.id,
          admin_phone_e164: normalizedPhone,
          admin_phone_verified: false, // Reset verification on change
          updated_at: new Date().toISOString(),
        }, {
          onConflict: "user_id",
        });

      if (error) throw error;

      setSavedPhone(normalizedPhone);
      setIsVerified(false);
      toast.success("Admin phone number saved! Calls from this number will route to your selected tenant.");
    } catch (error: any) {
      console.error("Failed to save admin phone:", error);
      toast.error("Failed to save phone number");
    } finally {
      setIsSaving(false);
    }
  };

  const handleMarkVerified = async () => {
    if (!user || !savedPhone) return;

    setIsSaving(true);
    try {
      const { error } = await supabase
        .from("admin_settings")
        .update({
          admin_phone_verified: true,
          updated_at: new Date().toISOString(),
        })
        .eq("user_id", user.id);

      if (error) throw error;

      setIsVerified(true);
      toast.success("Phone marked as verified!");
    } catch (error: any) {
      console.error("Failed to verify phone:", error);
      toast.error("Failed to verify phone");
    } finally {
      setIsSaving(false);
    }
  };

  if (!isSuperAdmin) return null;

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Phone className="h-5 w-5" />
          Admin Test Phone
        </CardTitle>
        <CardDescription>
          Register your personal phone number to use the universal test line. When you call{" "}
          <span className="font-mono font-medium">+1 (855) 329-7357</span>, calls will route to your currently selected tenant.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {isLoading ? (
          <div className="flex items-center gap-2 text-muted-foreground">
            <Loader2 className="h-4 w-4 animate-spin" />
            Loading...
          </div>
        ) : (
          <>
            <div className="space-y-2">
              <Label htmlFor="admin-phone">Your Phone Number</Label>
              <div className="flex gap-2">
                <Input
                  id="admin-phone"
                  type="tel"
                  placeholder="+1 (555) 123-4567"
                  value={phoneNumber}
                  onChange={(e) => setPhoneNumber(e.target.value)}
                  className="flex-1"
                />
                <Button
                  onClick={handleSavePhone}
                  disabled={isSaving || !phoneNumber.trim()}
                >
                  {isSaving ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    "Save"
                  )}
                </Button>
              </div>
            </div>

            {savedPhone && (
              <div className="flex items-center justify-between p-3 bg-muted/50 rounded-lg">
                <div className="flex items-center gap-2">
                  <span className="text-sm">Registered:</span>
                  <span className="font-mono text-sm font-medium">
                    {formatPhoneDisplay(savedPhone)}
                  </span>
                  {isVerified ? (
                    <Badge variant="default" className="gap-1">
                      <Check className="h-3 w-3" />
                      Verified
                    </Badge>
                  ) : (
                    <Badge variant="secondary" className="gap-1">
                      <AlertCircle className="h-3 w-3" />
                      Unverified
                    </Badge>
                  )}
                </div>
                {!isVerified && (
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleMarkVerified}
                    disabled={isSaving}
                  >
                    Mark Verified
                  </Button>
                )}
              </div>
            )}

            <div className="flex items-start gap-2 p-3 bg-primary/5 rounded-lg text-sm">
              <Info className="h-4 w-4 mt-0.5 text-primary" />
              <div className="space-y-1">
                <p className="font-medium">How it works:</p>
                <ol className="list-decimal list-inside space-y-1 text-muted-foreground">
                  <li>Register your personal cell phone number above</li>
                  <li>Select any tenant in the Admin Tenant Switcher</li>
                  <li>Call <span className="font-mono">+1 (855) 329-7357</span> from your phone</li>
                  <li>The AI will answer as the selected business</li>
                </ol>
              </div>
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Loader2, FlaskConical, Wand2 } from "lucide-react";
import { toast } from "sonner";
import type { BusinessMode } from "@/types/database";

interface CreateTestTenantDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onTenantCreated: (tenantId: string) => void;
  defaultMode: BusinessMode;
}

const BUSINESS_MODES: { value: BusinessMode; label: string; description: string }[] = [
  { value: "service", label: "Service & Booking", description: "Plumbing, HVAC, contractors" },
  { value: "dispatch", label: "Dispatch", description: "Towing, roadside, delivery" },
  { value: "food", label: "Food & Restaurant", description: "Restaurants, cafes, catering" },
  { value: "medical", label: "Medical Intake", description: "Clinics, healthcare (HIPAA)" },
  { value: "general", label: "General", description: "Callback and messaging" },
  { value: "sales", label: "Sales", description: "Dealerships, real estate, high-ticket" },
];

const TIMEZONES = [
  { value: "America/New_York", label: "Eastern (ET)" },
  { value: "America/Chicago", label: "Central (CT)" },
  { value: "America/Denver", label: "Mountain (MT)" },
  { value: "America/Los_Angeles", label: "Pacific (PT)" },
  { value: "America/Phoenix", label: "Arizona (MST)" },
];

export function CreateTestTenantDialog({ 
  open, 
  onOpenChange, 
  onTenantCreated,
  defaultMode
}: CreateTestTenantDialogProps) {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [isCreating, setIsCreating] = useState(false);
  const [businessName, setBusinessName] = useState("");
  const [timezone, setTimezone] = useState("America/New_York");
  
  // Use the defaultMode prop directly - mode is determined by admin mode selector
  const businessMode = defaultMode;

  const handleQuickCreate = async () => {
    if (!user || !businessName.trim()) {
      toast.error("Business name is required");
      return;
    }

    setIsCreating(true);
    try {
      // Create tenant via edge function (handles RLS bypass and membership creation)
      const { data: createResult, error: createError } = await supabase.functions.invoke(
        "create-tenant",
        {
          body: {
            name: businessName.trim(),
            business_mode: businessMode,
            timezone,
            enabled_modules: getDefaultModules(businessMode),
            hipaa_mode: businessMode === "medical",
          },
        }
      );

      // Handle transport error
      if (createError) {
        console.error("Tenant creation transport error:", createError);
        throw new Error(createError.message || "Failed to create tenant");
      }

      // Handle application error from edge function
      if (createResult?.error) {
        console.error("Tenant creation app error:", createResult.error);
        throw new Error(createResult.error);
      }

      const tenantId = createResult.tenant_id;
      if (!tenantId) {
        throw new Error("No tenant ID returned from server");
      }

      // Create assistant_settings for the tenant (now allowed since membership exists)
      const { error: settingsError } = await supabase
        .from("assistant_settings")
        .insert({
          tenant_id: tenantId,
          voice_ai_enabled: true,
          instant_text_enabled: true,
        });

      if (settingsError) {
        console.warn("Failed to create assistant_settings:", settingsError);
      }

      toast.success(`Created test tenant: ${businessName}`);
      onTenantCreated(tenantId);

      // Reset form
      setBusinessName("");
      setTimezone("America/New_York");
    } catch (error: any) {
      console.error("Failed to create test tenant:", error);
      toast.error(error.message || "Failed to create tenant");
    } finally {
      setIsCreating(false);
    }
  };

  const handleFullOnboarding = () => {
    // Navigate to the admin test onboarding page
    onOpenChange(false);
    navigate(`/admin/test-onboarding?mode=${businessMode}`);
  };

  const getDefaultModules = (mode: BusinessMode): string[] => {
    switch (mode) {
      case "service":
        return ["ai_voice", "instant_text_back", "booking"];
      case "dispatch":
        return ["ai_voice", "instant_text_back", "dispatch_queue"];
      case "food":
        return ["ai_voice", "instant_text_back", "food_orders", "menu_knowledge", "reservations"];
      case "medical":
        return ["ai_voice", "instant_text_back", "medical_intake"];
      case "sales":
        return ["ai_voice", "instant_text_back", "sales_leads", "booking"];
      case "general":
      default:
        return ["ai_voice", "instant_text_back"];
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FlaskConical className="h-5 w-5 text-warning" />
            Create Test Tenant
          </DialogTitle>
          <DialogDescription>
            Create a new test tenant to test different business modes and configurations.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="business-name">Business Name</Label>
            <Input
              id="business-name"
              placeholder="e.g., Test Plumbing Co"
              value={businessName}
              onChange={(e) => setBusinessName(e.target.value)}
            />
          </div>

          <div className="space-y-2">
            <Label>Business Mode</Label>
            <div className="flex items-center gap-2 h-10 px-3 rounded-md border bg-muted/50 text-sm">
              <span className="font-medium">
                {BUSINESS_MODES.find(m => m.value === businessMode)?.label}
              </span>
              <span className="text-muted-foreground">
                ({BUSINESS_MODES.find(m => m.value === businessMode)?.description})
              </span>
            </div>
            <p className="text-xs text-muted-foreground">
              Mode is set by the current admin mode selection
            </p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="timezone">Timezone</Label>
            <Select value={timezone} onValueChange={setTimezone}>
              <SelectTrigger id="timezone">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {TIMEZONES.map((tz) => (
                  <SelectItem key={tz.value} value={tz.value}>
                    {tz.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        <DialogFooter className="flex-col sm:flex-row gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)} className="sm:flex-1">
            Cancel
          </Button>
          <Button 
            variant="secondary"
            onClick={handleFullOnboarding}
            disabled={isCreating}
            className="sm:flex-1"
          >
            <Wand2 className="h-4 w-4 mr-2" />
            Full Onboarding
          </Button>
          <Button 
            onClick={handleQuickCreate} 
            disabled={isCreating || !businessName.trim()}
            className="sm:flex-1"
          >
            {isCreating ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Creating...
              </>
            ) : (
              "Quick Create"
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

