  general: <Phone className="h-4 w-4" />,
};

const categoryColors: Record<string, string> = {
  provisioning: "bg-blue-500/10 text-blue-700 dark:text-blue-300 border-blue-500/30",
  telephony: "bg-indigo-500/10 text-indigo-700 dark:text-indigo-300 border-indigo-500/30",
  webhook: "bg-purple-500/10 text-purple-700 dark:text-purple-300 border-purple-500/30",
  extraction: "bg-orange-500/10 text-orange-700 dark:text-orange-300 border-orange-500/30",
  entity: "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 border-emerald-500/30",
  calendar: "bg-amber-500/10 text-amber-700 dark:text-amber-300 border-amber-500/30",
  automation: "bg-rose-500/10 text-rose-700 dark:text-rose-300 border-rose-500/30",
};

export function GoldenPathTestRunner() {
  const [tenants, setTenants] = useState<Tenant[]>([]);
  const [selectedTenantId, setSelectedTenantId] = useState<string>("");
  const [loadingTenants, setLoadingTenants] = useState(true);
  const [pastRuns, setPastRuns] = useState<GoldenPathRun[]>([]);
  const { runTests, isRunning, currentRun } = useGoldenPathRunner();

  useEffect(() => {
    loadTenants();
  }, []);

  useEffect(() => {
    if (selectedTenantId) {
      loadPastRuns(selectedTenantId);
    }
  }, [selectedTenantId]);

  const loadTenants = async () => {
    setLoadingTenants(true);
    const { data } = await supabase
      .from("tenants")
      .select("id, name, business_mode, hipaa_mode")
      .order("name");
    setTenants(data || []);
    setLoadingTenants(false);
  };

  const loadPastRuns = async (tenantId: string) => {
    const { data } = await supabase
      .from("golden_path_runs")
      .select("*")
      .eq("tenant_id", tenantId)
      .order("created_at", { ascending: false })
      .limit(10);
    
    // Map the results to GoldenPathRun type
    setPastRuns((data || []).map(run => ({
      id: run.id,
      tenant_id: run.tenant_id,
      started_at: run.started_at,
      finished_at: run.finished_at,
      overall_status: run.overall_status as "running" | "passed" | "partial" | "failed",
      results_json: (run.results_json as unknown as TestResult[]) || [],
      pass_count: run.pass_count || 0,
      fail_count: run.fail_count || 0,
      mode: run.mode,
    })));
  };

  const handleRunTests = async () => {
    if (!selectedTenantId) return;
    await runTests(selectedTenantId);
    loadPastRuns(selectedTenantId);
  };

  const selectedTenant = tenants.find(t => t.id === selectedTenantId);
  const displayRun = currentRun?.tenant_id === selectedTenantId ? currentRun : null;

  // Group results by category
  const groupedResults: Record<string, TestResult[]> = {};
  if (displayRun?.results_json) {
    for (const result of displayRun.results_json) {
      if (!groupedResults[result.category]) {
        groupedResults[result.category] = [];
      }
      groupedResults[result.category].push(result);
    }
  }

  const categoryOrder = ["provisioning", "telephony", "webhook", "extraction", "entity", "automation", "calendar"];

  return (
    <div className="space-y-6">
      {/* Tenant Selector */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-lg flex items-center gap-2">
            <Play className="h-5 w-5" />
            Golden Path Test Runner
          </CardTitle>
          <CardDescription>
            Select a tenant and run automated tests to validate core flows
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-4">
            <Select value={selectedTenantId} onValueChange={setSelectedTenantId}>
              <SelectTrigger className="w-[300px]">
                <SelectValue placeholder={loadingTenants ? "Loading..." : "Select a tenant"} />
              </SelectTrigger>
              <SelectContent>
                {tenants.map((tenant) => (
                  <SelectItem key={tenant.id} value={tenant.id}>
                    <div className="flex items-center gap-2">
                      {modeIcons[tenant.business_mode] || modeIcons.general}
                      <span>{tenant.name}</span>
                      <Badge variant="outline" className="ml-2 text-xs">
                        {tenant.business_mode}
                      </Badge>
                      {tenant.hipaa_mode && (
                        <Badge variant="secondary" className="text-xs">HIPAA</Badge>
                      )}
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>

            <Button 
              onClick={handleRunTests} 
              disabled={!selectedTenantId || isRunning}
              className="gap-2"
            >
              {isRunning ? (
                <>
                  <Loader2 className="h-4 w-4 animate-spin" />
                  Running...
                </>
              ) : (
                <>
                  <Play className="h-4 w-4" />
                  Run All Tests
                </>
              )}
            </Button>

            <Button 
              variant="outline" 
              size="icon"
              onClick={loadTenants}
              disabled={loadingTenants}
            >
              <RefreshCw className={`h-4 w-4 ${loadingTenants ? "animate-spin" : ""}`} />
            </Button>
          </div>

          {selectedTenant && (
            <div className="mt-4 p-3 bg-muted/50 rounded-lg flex items-center gap-4">
              <div className="flex items-center gap-2">
                {modeIcons[selectedTenant.business_mode] || modeIcons.general}
                <span className="font-medium">{selectedTenant.name}</span>
              </div>
              <Badge>{selectedTenant.business_mode}</Badge>
              {selectedTenant.hipaa_mode && <Badge variant="secondary">HIPAA</Badge>}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Test Results */}
      {displayRun && (
        <Card>
          <CardHeader className="pb-3">
            <div className="flex items-center justify-between">
              <CardTitle className="text-lg flex items-center gap-2">
                Test Results
                <Badge 
                  variant={
                    displayRun.overall_status === "passed" ? "default" :
                    displayRun.overall_status === "partial" ? "secondary" :
                    "destructive"
                  }
                  className={
                    displayRun.overall_status === "passed" ? "bg-green-600" :
                    displayRun.overall_status === "partial" ? "bg-yellow-600" :
                    undefined
                  }
                >
                  {displayRun.overall_status === "passed" ? "All Passed" :
                   displayRun.overall_status === "partial" ? "Partial" :
                   "Failed"}
                </Badge>
              </CardTitle>
              <div className="text-sm text-muted-foreground">
                <span className="text-primary font-medium">{displayRun.pass_count}</span>
                {" passed, "}
                <span className="text-destructive font-medium">{displayRun.fail_count}</span>
                {" failed"}
              </div>
            </div>
          </CardHeader>
          <CardContent>
            <ScrollArea className="h-[500px] pr-4">
              <div className="space-y-6">
                {categoryOrder.map((category) => {
                  const results = groupedResults[category];
                  if (!results?.length) return null;

                  const passed = results.filter(r => r.passed).length;
                  const total = results.length;

                  return (
                    <div key={category}>
                      <div className="flex items-center gap-2 mb-3">
                        <Badge className={`${categoryColors[category]} border`} variant="outline">
                          {categoryIcons[category]}
                          <span className="ml-1.5 capitalize">{category}</span>
                        </Badge>
                        <span className="text-sm text-muted-foreground">
                          {passed}/{total} passed
                        </span>
                      </div>
                      <div className="space-y-2">
                        {results.map((result) => (
                          <div
                            key={result.id}
                            className={`p-3 rounded-lg border transition-colors ${
                              result.passed
                                ? "bg-primary/5 border-primary/20"
                                : "bg-destructive/5 border-destructive/20"
                            }`}
                          >
                            <div className="flex items-start gap-3">
                              {result.passed ? (
                                <CheckCircle2 className="h-5 w-5 text-primary shrink-0 mt-0.5" />
                              ) : (
                                <XCircle className="h-5 w-5 text-destructive shrink-0 mt-0.5" />
                              )}
                              <div className="flex-1 min-w-0">
                                <p className="font-medium">{result.label}</p>
                                <p className="text-sm text-muted-foreground">{result.description}</p>
                                {result.details && (
                                  <p className="text-xs text-muted-foreground mt-1 font-mono bg-muted/50 px-2 py-1 rounded">
                                    {result.details}
                                  </p>
                                )}
                                {!result.passed && result.fixSuggestion && (
                                  <div className="mt-2 flex items-center gap-2">
                                    <AlertTriangle className="h-4 w-4 text-warning" />
                                    <span className="text-sm text-warning">{result.fixSuggestion}</span>
                                    {result.fixLink && (
                                      <Button variant="link" size="sm" className="h-auto p-0" asChild>
                                        <Link to={result.fixLink}>
                                          <Wrench className="h-3 w-3 mr-1" />
                                          Fix
                                          <ExternalLink className="h-3 w-3 ml-1" />
                                        </Link>
                                      </Button>
                                    )}
                                  </div>
                                )}
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            </ScrollArea>
          </CardContent>
        </Card>
      )}

      {/* Past Runs History */}
      {selectedTenantId && pastRuns.length > 0 && (
        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-lg flex items-center gap-2">
              <History className="h-5 w-5" />
              Past Test Runs
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
                {pastRuns.slice(0, 5).map((run) => (
                  <div
                    key={run.id}
                    className="flex items-center justify-between p-3 bg-muted/50 rounded-lg"
                  >
                    <div className="flex items-center gap-3">
                      <Badge 
                        variant={
                          run.overall_status === "passed" ? "default" :
                          run.overall_status === "partial" ? "secondary" :
                          "destructive"
                        }
                        className={
                          run.overall_status === "passed" ? "bg-primary" :
                          run.overall_status === "partial" ? "bg-secondary text-secondary-foreground" :
                          undefined
                        }
                    >
                      {run.overall_status}
                    </Badge>
                    <span className="text-sm">
                      {run.pass_count} passed, {run.fail_count} failed
                    </span>
                  </div>
                  <span className="text-sm text-muted-foreground">
                    {new Date(run.started_at).toLocaleString()}
                  </span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Quick Links */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-sm font-medium">Debug Pages</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-2">
            <Button variant="outline" size="sm" asChild>
              <Link to="/debug/telephony">Telephony Debug</Link>
            </Button>
            <Button variant="outline" size="sm" asChild>
              <Link to="/debug/ai-context">AI Context Inspector</Link>
            </Button>
            <Button variant="outline" size="sm" asChild>
              <Link to="/debug/extraction">Extraction Debug</Link>
            </Button>
            <Button variant="outline" size="sm" asChild>
              <Link to="/debug/availability">Availability Debug</Link>
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Search, Globe, Phone, Star, Loader2, MapPin, Bookmark, Check, Trash2, Handshake, Mail } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { useAuth } from "@/contexts/AuthContext";
import {
  scoreResellerLead,
  getResellerTemperatureColor,
  getResellerTemperatureIcon,
  type ResellerTemperature,
} from "./reseller-finder/resellerScoring";
import { RESELLER_INDUSTRIES, PARTNERSHIP_SIGNAL_LABELS, RESELLER_STATUS_LABELS } from "./reseller-finder/resellerConstants";
import {
  useAdminResellerSavedLeads,
  useAdminSaveResellerLead,
  useAdminSaveResellerLeadsBatch,
  useAdminUpdateResellerLead,
  useAdminDeleteResellerLead,
  type AdminResellerLead,
} from "@/hooks/useAdminResellerLeads";
import { useEnrollLeads, useOutreachCampaigns } from "@/hooks/useAdminOutreach";

interface ResellerResult {
  name: string;
  phone: string | null;
  website: string | null;
  address: string | null;
  company_type: string;
  services_offered: string[];
  partnership_signals: string[];
  client_base_size: string | null;
  rating: number | null;
  review_count: number | null;
  employee_estimate: string | null;
  reason: string;
  confidence: "high" | "medium" | "low";
  score?: { temperature: ResellerTemperature; score: number; reasons: string[] };
}

export function ResellerLeadFinder() {
  const { user } = useAuth();
  const userId = user?.id;
  const [companyType, setCompanyType] = useState("");
  const [location, setLocation] = useState("");
  const [leads, setLeads] = useState<ResellerResult[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [tempFilter, setTempFilter] = useState<"all" | ResellerTemperature>("all");
  const [mainTab, setMainTab] = useState("search");
  const [deleteTarget, setDeleteTarget] = useState<AdminResellerLead | null>(null);

  const savedLeads = useAdminResellerSavedLeads(userId);
  const saveLead = useAdminSaveResellerLead(userId);
  const saveLeadsBatch = useAdminSaveResellerLeadsBatch(userId);
  const updateLead = useAdminUpdateResellerLead(userId);
  const deleteLead = useAdminDeleteResellerLead(userId);
  const enrollLeads = useEnrollLeads();
  const { data: campaigns } = useOutreachCampaigns();
  const defaultResellerCampaign = (campaigns ?? []).find((c) => c.target_type === "reseller" && c.status === "active");

  const handleStartOutreach = (lead: AdminResellerLead) => {
    if (!defaultResellerCampaign) { toast.error("No active reseller campaign. Create one in Growth Engine."); return; }
    enrollLeads.mutate({
      campaign_id: defaultResellerCampaign.id,
      leads: [{
        lead_id: lead.id,
        lead_type: "reseller",
        lead_name: lead.name,
        lead_email: (lead as any).email || undefined,
        lead_phone: lead.phone || undefined,
        lead_metadata: {
          industry: (lead as any).company_type || "",
          friction_signals: lead.partnership_signals || [],
          score: lead.score || 0,
          score_reasons: lead.score_reasons || [],
          website: lead.website || "",
        },
      }],
    });
  };

  const savedNames = useMemo(() => {
    const set = new Set<string>();
    (savedLeads.data ?? []).forEach((l) => set.add(l.name.toLowerCase().trim()));
    return set;
  }, [savedLeads.data]);

  const isLeadSaved = (name: string) => savedNames.has(name.toLowerCase().trim());

  const handleSearch = async () => {
    if (!companyType || !location) {
      toast.error("Select a company type and enter a location");
      return;
    }

    setIsSearching(true);
    setLeads([]);
    setTempFilter("all");

    try {
      const { data, error } = await supabase.functions.invoke("reseller-lead-search", {
        body: { company_type: companyType, location, count: 30 },
      });
      if (error) throw error;

      const rawLeads: ResellerResult[] = (data.leads || []).map((l: any) => ({
        ...l,
        company_type: l.company_type || companyType,
        score: scoreResellerLead({
          partnership_signals: l.partnership_signals,
          rating: l.rating,
          review_count: l.review_count,
          client_base_size: l.client_base_size,
          services_offered: l.services_offered,
          employee_estimate: l.employee_estimate,
          website: l.website,
        }),
      }));

      rawLeads.sort((a, b) => (b.score?.score ?? 0) - (a.score?.score ?? 0));
      setLeads(rawLeads);
      setHasSearched(true);

      if (rawLeads.length === 0) {
        toast.info("No leads found. Try a different location or company type.");
      } else {
        toast.success(`Found ${rawLeads.length} potential partners`);
      }
    } catch (err) {
      console.error("Reseller search failed:", err);
      toast.error("Search failed. Please try again.");
    } finally {
      setIsSearching(false);
    }
  };

  const filteredLeads = useMemo(() => {
    if (tempFilter === "all") return leads;
    return leads.filter((l) => l.score?.temperature === tempFilter);
  }, [leads, tempFilter]);

  const tempCounts = useMemo(() => {
    const counts = { hot: 0, warm: 0, cold: 0 };
    leads.forEach((l) => {
      if (l.score?.temperature) counts[l.score.temperature]++;
    });
    return counts;
  }, [leads]);

  const buildSavePayload = (lead: ResellerResult) => ({
    name: lead.name,
    phone: lead.phone,
    website: lead.website,
    address: lead.address,
    company_type: lead.company_type || null,
    services_offered: lead.services_offered || [],
    partnership_signals: lead.partnership_signals || [],
    client_base_size: lead.client_base_size || null,
    rating: lead.rating,
    review_count: lead.review_count,
    employee_estimate: lead.employee_estimate || null,
    reason: lead.reason,
    confidence: lead.confidence,
    score: lead.score?.score ?? null,
    temperature: lead.score?.temperature ?? null,
    score_reasons: lead.score?.reasons ?? [],
  });

  const handleSaveAll = () => {
    const unsaved = filteredLeads.filter((l) => !isLeadSaved(l.name));
    if (unsaved.length === 0) {
      toast.info("All leads are already saved");
      return;
    }
    saveLeadsBatch.mutate(unsaved.map(buildSavePayload));
  };

  const handleSaveSingle = (lead: ResellerResult) => {
    saveLead.mutate(buildSavePayload(lead), {
      onSuccess: () => toast.success(`"${lead.name}" saved`),
    });
  };

  return (
    <div className="space-y-4">
      <div>
        <h2 className="text-lg font-semibold">Reseller / Agency Partner Finder</h2>
        <p className="text-sm text-muted-foreground">
          Find marketing agencies, consultants, and resellers who could become CloseLoop channel partners.
        </p>
      </div>

      <Tabs value={mainTab} onValueChange={setMainTab}>
        <TabsList className="h-9">
          <TabsTrigger value="search" className="text-xs px-4">Search</TabsTrigger>
          <TabsTrigger value="saved" className="text-xs px-4">
            Saved {savedLeads.data?.length ? `(${savedLeads.data.length})` : ""}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="search" className="mt-4 space-y-4">
          <div className="flex flex-col sm:flex-row gap-3">
            <div className="flex-1">
              <Label className="text-xs mb-1.5 block">Company Type</Label>
              <Select value={companyType} onValueChange={setCompanyType}>
                <SelectTrigger><SelectValue placeholder="Select type" /></SelectTrigger>
                <SelectContent>
                  {RESELLER_INDUSTRIES.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>{opt.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="flex-1">
              <Label className="text-xs mb-1.5 block">Location</Label>
              <Input
                placeholder="e.g. Austin, TX"
                value={location}
                onChange={(e) => setLocation(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleSearch()}
              />
            </div>
            <div className="flex items-end">
              <Button onClick={handleSearch} disabled={isSearching || !companyType || !location}>
                {isSearching ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : <Search className="h-4 w-4 mr-2" />}
                {isSearching ? "Searching..." : "Find Partners"}
              </Button>
            </div>
          </div>

          {isSearching && (
            <div className="text-center py-12 text-muted-foreground text-sm">
              <Loader2 className="h-8 w-8 animate-spin mx-auto mb-3" />
              <p>Searching for {companyType} companies in {location}...</p>
            </div>
          )}

          {!isSearching && leads.length > 0 && (
            <div className="space-y-3">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                <Tabs value={tempFilter} onValueChange={(v) => setTempFilter(v as "all" | ResellerTemperature)}>
                  <TabsList className="h-8">
                    <TabsTrigger value="all" className="text-xs px-3 h-6">All ({leads.length})</TabsTrigger>
                    <TabsTrigger value="hot" className="text-xs px-3 h-6">Hot ({tempCounts.hot})</TabsTrigger>
                    <TabsTrigger value="warm" className="text-xs px-3 h-6">Warm ({tempCounts.warm})</TabsTrigger>
                    <TabsTrigger value="cold" className="text-xs px-3 h-6">Cold ({tempCounts.cold})</TabsTrigger>
                  </TabsList>
                </Tabs>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted-foreground">{filteredLeads.length} results</span>
                  <Button size="sm" variant="outline" onClick={handleSaveAll} disabled={saveLeadsBatch.isPending}>
                    <Bookmark className="h-3.5 w-3.5 mr-1.5" /> Save All
                  </Button>
                </div>
              </div>

              <div className="grid gap-2">
                {filteredLeads.map((lead) => {
                  const saved = isLeadSaved(lead.name);
                  return (
                    <Card key={`${lead.name}-${lead.address || ""}`} className="hover:border-primary/40 transition-colors">
                      <CardContent className="p-3">
                        <div className="flex items-start gap-3">
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 flex-wrap">
                              <h3 className="font-medium text-sm truncate">{lead.name}</h3>
                              {lead.score && (
                                <Badge variant="outline" className={`text-[10px] px-1.5 py-0 ${getResellerTemperatureColor(lead.score.temperature)}`}>
                                  {getResellerTemperatureIcon(lead.score.temperature)} {lead.score.temperature} {lead.score.score}
                                </Badge>
                              )}
                              {saved && (
                                <Badge variant="outline" className="text-[10px] px-1.5 py-0 bg-green-500/10 text-green-700 border-green-500/20">
                                  <Check className="h-2.5 w-2.5 mr-0.5" /> Saved
                                </Badge>
                              )}
                              <span className="text-[10px] text-muted-foreground capitalize">{lead.company_type}</span>
                            </div>
                            <p className="text-xs text-muted-foreground mt-1 line-clamp-1">{lead.reason}</p>
                            <div className="flex items-center gap-3 mt-1.5 text-[11px] text-muted-foreground">
                              {lead.rating != null && (
                                <span className="flex items-center gap-0.5">
                                  <Star className="h-3 w-3 fill-amber-400 text-amber-400" /> {lead.rating}
                                </span>
                              )}
                              {lead.phone && (
                                <span className="flex items-center gap-0.5">
                                  <Phone className="h-3 w-3" /> {lead.phone}
                                </span>
                              )}
                              {lead.address && (
                                <span className="flex items-center gap-0.5 truncate">
                                  <MapPin className="h-3 w-3 shrink-0" /> <span className="truncate">{lead.address}</span>
                                </span>
                              )}
                            </div>
                          </div>
                          <div className="flex items-center gap-2">
                            <div className="hidden sm:flex flex-wrap gap-1 max-w-[180px] justify-end">
                              {lead.partnership_signals?.slice(0, 3).map((signal) => (
                                <Badge key={signal} variant="secondary" className="text-[9px] px-1 py-0 whitespace-nowrap">
                                  {PARTNERSHIP_SIGNAL_LABELS[signal] || signal}
                                </Badge>
                              ))}
                            </div>
                            {!saved && (
                              <Button
                                variant="ghost" size="icon" className="h-7 w-7 shrink-0"
                                onClick={(e) => { e.stopPropagation(); handleSaveSingle(lead); }}
                              >
                                <Bookmark className="h-3.5 w-3.5" />
                              </Button>
                            )}
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}
              </div>
            </div>
          )}

          {!isSearching && hasSearched && leads.length === 0 && (
            <div className="text-center py-8 text-sm text-muted-foreground">
              No partners found. Try a different company type or location.
            </div>
          )}
        </TabsContent>

        <TabsContent value="saved" className="mt-4">
          {savedLeads.data?.length === 0 ? (
            <div className="text-center py-12 text-sm text-muted-foreground">
              <Handshake className="h-10 w-10 mx-auto mb-3 opacity-40" />
              <p>No saved partner leads yet.</p>
            </div>
          ) : (
            <div className="grid gap-2">
              {(savedLeads.data ?? []).map((lead) => (
                <Card key={lead.id} className="hover:border-primary/40 transition-colors">
                  <CardContent className="p-3">
                    <div className="flex items-center gap-3">
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <h3 className="font-medium text-sm truncate">{lead.name}</h3>
                          {lead.temperature && (
                            <Badge variant="outline" className={`text-[10px] px-1.5 py-0 ${getResellerTemperatureColor(lead.temperature as ResellerTemperature)}`}>
                              {getResellerTemperatureIcon(lead.temperature as ResellerTemperature)} {lead.score}
                            </Badge>
                          )}
                          <span className="text-[10px] text-muted-foreground capitalize">{lead.company_type}</span>
                        </div>
                        <div className="flex items-center gap-3 mt-1 text-[11px] text-muted-foreground">
                          {lead.phone && <span className="flex items-center gap-0.5"><Phone className="h-3 w-3" /> {lead.phone}</span>}
                          {lead.address && <span className="truncate">{lead.address}</span>}
                        </div>
                      </div>
                      <div onClick={(e) => e.stopPropagation()}>
                        <Select value={lead.status} onValueChange={(v) => updateLead.mutate({ id: lead.id, status: v })}>
                          <SelectTrigger className="h-7 text-xs w-[130px]"><SelectValue /></SelectTrigger>
                          <SelectContent>
                            {Object.entries(RESELLER_STATUS_LABELS).map(([k, v]) => (
                              <SelectItem key={k} value={k} className="text-xs">{v}</SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                      {defaultResellerCampaign && lead.status === "new" && (
                        <Button variant="ghost" size="icon" className="h-7 w-7 shrink-0" title="Start Outreach"
                          onClick={(e) => { e.stopPropagation(); handleStartOutreach(lead); }}>
                          <Mail className="h-3.5 w-3.5 text-primary" />
                        </Button>
                      )}
                      <Button variant="ghost" size="icon" className="h-7 w-7 shrink-0"
                        onClick={(e) => { e.stopPropagation(); setDeleteTarget(lead); }}>
                        <Trash2 className="h-3.5 w-3.5 text-muted-foreground" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>

      <AlertDialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove lead?</AlertDialogTitle>
            <AlertDialogDescription>Remove "{deleteTarget?.name}" from saved partners?</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => { if (deleteTarget) deleteLead.mutate(deleteTarget.id); setDeleteTarget(null); }}>
              Remove
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Loader2, Save, X } from "lucide-react";
import { useAdminGrowthSettings, useUpdateAdminGrowthSettings, type AdminGrowthSettings } from "@/hooks/useAdminGrowthSettings";

const ALL_INDUSTRIES = [
  "towing", "plumber", "hvac", "electrician", "locksmith",
  "auto repair", "dental", "med spa", "salon", "pest control",
  "landscaping", "roofing", "mobile detailing", "cleaning service",
  "restaurant", "veterinary", "real estate", "insurance agency",
  "law firm", "fitness studio",
];

const ALL_PLATFORMS = ["linkedin", "twitter", "facebook", "instagram", "tiktok"];
const AD_PLATFORMS = ["google", "meta", "linkedin"];
const DAYS = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];

interface GrowthSettingsPanelProps {
  open: boolean;
  onClose: () => void;
}

export function GrowthSettingsPanel({ open, onClose }: GrowthSettingsPanelProps) {
  const { data: settings, isLoading } = useAdminGrowthSettings();
  const updateSettings = useUpdateAdminGrowthSettings();
  const [form, setForm] = useState<Partial<AdminGrowthSettings>>({});
  const [locationInput, setLocationInput] = useState("");

  useEffect(() => {
    if (settings) setForm(settings);
  }, [settings]);

  if (!open) return null;

  const update = (key: keyof AdminGrowthSettings, value: any) => {
    setForm((prev) => ({ ...prev, [key]: value }));
  };

  const toggleArrayItem = (key: keyof AdminGrowthSettings, item: string) => {
    const arr = (form[key] as string[]) || [];
    update(key, arr.includes(item) ? arr.filter((i) => i !== item) : [...arr, item]);
  };

  const addLocation = () => {
    const loc = locationInput.trim();
    if (!loc) return;
    const locs = (form.discovery_locations as string[]) || [];
    if (!locs.includes(loc)) update("discovery_locations", [...locs, loc]);
    setLocationInput("");
  };

  const removeLocation = (loc: string) => {
    update("discovery_locations", ((form.discovery_locations as string[]) || []).filter((l) => l !== loc));
  };

  const handleSave = () => {
    const { id, created_at, updated_at, ...rest } = form as any;
    updateSettings.mutate(rest, { onSuccess: onClose });
  };

  if (isLoading) {
    return (
      <div className="fixed inset-0 z-50 bg-black/50 flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-white" />
      </div>
    );
  }

  return (
    <div className="fixed inset-0 z-50 bg-black/50 flex items-end sm:items-center justify-center">
      <div className="bg-background w-full max-w-2xl max-h-[90vh] overflow-y-auto rounded-t-xl sm:rounded-xl border shadow-xl">
        <div className="sticky top-0 bg-background border-b p-4 flex items-center justify-between z-10">
          <h2 className="text-lg font-semibold">Growth Engine Settings</h2>
          <div className="flex items-center gap-2">
            <Button size="sm" onClick={handleSave} disabled={updateSettings.isPending}>
              {updateSettings.isPending ? <Loader2 className="h-4 w-4 animate-spin mr-1" /> : <Save className="h-4 w-4 mr-1" />}
              Save
            </Button>
            <Button variant="ghost" size="icon" onClick={onClose}>
              <X className="h-4 w-4" />
            </Button>
          </div>
        </div>

        <div className="p-4 space-y-6">
          {/* Discovery */}
          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm">Auto-Discovery</CardTitle>
                <Switch
                  checked={form.auto_discovery_enabled ?? false}
                  onCheckedChange={(v) => update("auto_discovery_enabled", v)}
                />
              </div>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <Label className="text-xs">Industries</Label>
                <div className="flex flex-wrap gap-1.5 mt-1">
                  {ALL_INDUSTRIES.map((ind) => (
                    <Badge
                      key={ind}
                      variant={(form.discovery_industries || []).includes(ind) ? "default" : "outline"}
                      className="cursor-pointer text-xs capitalize"
                      onClick={() => toggleArrayItem("discovery_industries", ind)}
                    >
                      {ind}
                    </Badge>
                  ))}
                </div>
              </div>
              <div>
                <Label className="text-xs">Locations</Label>
                <div className="flex gap-2 mt-1">
                  <Input
                    placeholder="e.g. Austin, TX"
                    value={locationInput}
                    onChange={(e) => setLocationInput(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && (e.preventDefault(), addLocation())}
                    className="h-8 text-sm"
                  />
                  <Button size="sm" variant="outline" onClick={addLocation}>Add</Button>
                </div>
                <div className="flex flex-wrap gap-1.5 mt-2">
                  {(form.discovery_locations || []).map((loc) => (
                    <Badge key={loc} variant="secondary" className="text-xs">
                      {loc}
                      <button className="ml-1" onClick={() => removeLocation(loc)}><X className="h-3 w-3" /></button>
                    </Badge>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs">Frequency (hours)</Label>
                  <Input type="number" value={form.discovery_frequency_hours ?? 24} onChange={(e) => update("discovery_frequency_hours", Number(e.target.value))} className="h-8 text-sm mt-1" />
                </div>
                <div>
                  <Label className="text-xs">Max per run</Label>
                  <Input type="number" value={form.discovery_max_per_run ?? 50} onChange={(e) => update("discovery_max_per_run", Number(e.target.value))} className="h-8 text-sm mt-1" />
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Outreach */}
          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm">Outreach</CardTitle>
                <Switch
                  checked={form.auto_outreach_enabled ?? false}
                  onCheckedChange={(v) => update("auto_outreach_enabled", v)}
                />
              </div>
            </CardHeader>
            <CardContent className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs">From Email</Label>
                  <Input value={form.outreach_from_email ?? ""} onChange={(e) => update("outreach_from_email", e.target.value)} className="h-8 text-sm mt-1" />
                </div>
                <div>
                  <Label className="text-xs">From Name</Label>
                  <Input value={form.outreach_from_name ?? ""} onChange={(e) => update("outreach_from_name", e.target.value)} className="h-8 text-sm mt-1" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs">Daily Email Limit</Label>
                  <Input type="number" value={form.outreach_daily_email_limit ?? 50} onChange={(e) => update("outreach_daily_email_limit", Number(e.target.value))} className="h-8 text-sm mt-1" />
                </div>
                <div>
                  <Label className="text-xs">Daily SMS Limit</Label>
                  <Input type="number" value={form.outreach_daily_sms_limit ?? 20} onChange={(e) => update("outreach_daily_sms_limit", Number(e.target.value))} className="h-8 text-sm mt-1" />
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs">Quiet Hours Start</Label>
                  <Input value={form.outreach_quiet_hours_start ?? "21:00"} onChange={(e) => update("outreach_quiet_hours_start", e.target.value)} className="h-8 text-sm mt-1" placeholder="21:00" />
                </div>
                <div>
                  <Label className="text-xs">Quiet Hours End</Label>
                  <Input value={form.outreach_quiet_hours_end ?? "08:00"} onChange={(e) => update("outreach_quiet_hours_end", e.target.value)} className="h-8 text-sm mt-1" placeholder="08:00" />
                </div>
              </div>
              <div>
                <Label className="text-xs">Quiet Days</Label>
                <div className="flex flex-wrap gap-1.5 mt-1">
                  {DAYS.map((day) => (
                    <Badge
                      key={day}
                      variant={(form.outreach_quiet_days || []).includes(day) ? "default" : "outline"}
                      className="cursor-pointer text-xs capitalize"
                      onClick={() => toggleArrayItem("outreach_quiet_days", day)}
                    >
                      {day}
                    </Badge>
                  ))}
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Social */}
          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm">Social Content</CardTitle>
                <Switch
                  checked={form.auto_social_enabled ?? false}
                  onCheckedChange={(v) => update("auto_social_enabled", v)}
                />
              </div>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <Label className="text-xs">Platforms</Label>
                <div className="flex flex-wrap gap-1.5 mt-1">
                  {ALL_PLATFORMS.map((p) => (
                    <Badge
                      key={p}
                      variant={(form.social_platforms || []).includes(p) ? "default" : "outline"}
                      className="cursor-pointer text-xs capitalize"
                      onClick={() => toggleArrayItem("social_platforms", p)}
                    >
                      {p === "twitter" ? "Twitter/X" : p}
                    </Badge>
                  ))}
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <Label className="text-xs">Posts per Week</Label>
                  <Input type="number" value={form.social_posts_per_week ?? 5} onChange={(e) => update("social_posts_per_week", Number(e.target.value))} className="h-8 text-sm mt-1" />
                </div>
                <div>
                  <Label className="text-xs">Tone</Label>
                  <Select value={form.social_tone ?? "professional"} onValueChange={(v) => update("social_tone", v)}>
                    <SelectTrigger className="h-8 text-sm mt-1"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="professional">Professional</SelectItem>
                      <SelectItem value="casual">Casual</SelectItem>
                      <SelectItem value="educational">Educational</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <Switch checked={form.social_auto_post ?? false} onCheckedChange={(v) => update("social_auto_post", v)} />
                <Label className="text-xs">Auto-post (vs draft-only)</Label>
              </div>
            </CardContent>
          </Card>

          {/* Ads */}
          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm">Ad Campaigns</CardTitle>
                <Switch
                  checked={form.auto_ads_enabled ?? false}
                  onCheckedChange={(v) => update("auto_ads_enabled", v)}
                />
              </div>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <Label className="text-xs">Platforms</Label>
                <div className="flex flex-wrap gap-1.5 mt-1">
                  {AD_PLATFORMS.map((p) => (
                    <Badge
                      key={p}
                      variant={(form.ads_platforms || []).includes(p) ? "default" : "outline"}
                      className="cursor-pointer text-xs capitalize"
                      onClick={() => toggleArrayItem("ads_platforms", p)}
                    >
                      {p}
                    </Badge>
                  ))}
                </div>
              </div>
              <div>
                <Label className="text-xs">Weekly Budget Hint ($)</Label>
                <Input type="number" value={form.ads_weekly_budget_hint ?? ""} onChange={(e) => update("ads_weekly_budget_hint", e.target.value ? Number(e.target.value) : null)} className="h-8 text-sm mt-1" placeholder="Optional" />
              </div>
            </CardContent>
          </Card>

          {/* Links */}
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-sm">Outreach Links</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <Label className="text-xs">Demo Link (used in {"{{demo_link}}"} token)</Label>
                <Input value={form.demo_link ?? "https://closeloop.ai"} onChange={(e) => update("demo_link", e.target.value)} className="h-8 text-sm mt-1" placeholder="https://closeloop.ai" />
              </div>
              <div>
                <Label className="text-xs">Trial Link (used in {"{{trial_link}}"} token)</Label>
                <Input value={form.trial_link ?? "https://closeloop.ai/signup"} onChange={(e) => update("trial_link", e.target.value)} className="h-8 text-sm mt-1" placeholder="https://closeloop.ai/signup" />
              </div>
            </CardContent>
          </Card>

          {/* Notifications */}
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-sm">Notifications</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <Label className="text-xs">Alert Email</Label>
                <Input value={form.notification_email ?? ""} onChange={(e) => update("notification_email", e.target.value || null)} className="h-8 text-sm mt-1" placeholder="admin@example.com" />
              </div>
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-2">
                  <Switch checked={form.notify_on_response ?? true} onCheckedChange={(v) => update("notify_on_response", v)} />
                  <Label className="text-xs">Notify on response</Label>
                </div>
                <div className="flex items-center gap-2">
                  <Switch checked={form.notify_on_conversion ?? true} onCheckedChange={(v) => update("notify_on_conversion", v)} />
                  <Label className="text-xs">Notify on conversion</Label>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  CheckCircle2, Circle, Mail, Share2, Megaphone, Search,
  ChevronRight, ChevronDown, Loader2, Save, Rocket, Key, X,
  AlertTriangle, ExternalLink, Sparkles, Globe,
} from "lucide-react";
import { useAdminGrowthSettings, useUpdateAdminGrowthSettings, type AdminGrowthSettings } from "@/hooks/useAdminGrowthSettings";
import { supabase } from "@/integrations/supabase/client";
import { useQuery } from "@tanstack/react-query";
import { toast } from "sonner";

const ALL_INDUSTRIES = [
  "towing", "plumber", "hvac", "electrician", "locksmith",
  "auto repair", "dental", "med spa", "salon", "pest control",
  "landscaping", "roofing", "mobile detailing", "cleaning service",
  "restaurant", "veterinary", "real estate", "insurance agency",
  "law firm", "fitness studio",
];

const ALL_PLATFORMS = ["linkedin", "twitter", "facebook", "instagram", "tiktok"];
const DAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const DAY_FULL = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];

interface StepConfig {
  id: string;
  title: string;
  subtitle: string;
  icon: any;
  color: string;
  checkConnected: (secrets: string[], settings: AdminGrowthSettings | null) => boolean;
}

const STEPS: StepConfig[] = [
  {
    id: "email",
    title: "Email Sending",
    subtitle: "Connect Resend to send outreach emails automatically",
    icon: Mail,
    color: "text-blue-600",
    checkConnected: (secrets) => secrets.includes("RESEND_API_KEY"),
  },
  {
    id: "discovery",
    title: "Lead Discovery",
    subtitle: "Pick industries & locations to auto-find new leads",
    icon: Search,
    color: "text-emerald-600",
    checkConnected: (_, settings) => !!(settings?.auto_discovery_enabled && (settings?.discovery_industries?.length ?? 0) > 0 && (settings?.discovery_locations?.length ?? 0) > 0),
  },
  {
    id: "social",
    title: "Social Media",
    subtitle: "Connect accounts to auto-post content",
    icon: Share2,
    color: "text-purple-600",
    checkConnected: (secrets) => secrets.includes("TWITTER_ACCESS_TOKEN") || secrets.includes("LINKEDIN_ACCESS_TOKEN"),
  },
  {
    id: "ads",
    title: "Paid Ads",
    subtitle: "Connect Google or Meta to run ad campaigns",
    icon: Megaphone,
    color: "text-pink-600",
    checkConnected: (secrets) => secrets.includes("GOOGLE_ADS_CLIENT_ID") || secrets.includes("META_MARKETING_TOKEN"),
  },
];

function useSecretNames() {
  return useQuery({
    queryKey: ["growth-secret-names"],
    queryFn: async () => {
      // We can't read secret values, but we can check if they exist via edge function
      // For now, we'll use a lightweight check
      const { data } = await supabase.functions.invoke("admin-check-secrets", {
        body: { keys: ["RESEND_API_KEY", "TWITTER_ACCESS_TOKEN", "TWITTER_CONSUMER_KEY", "LINKEDIN_ACCESS_TOKEN", "GOOGLE_ADS_CLIENT_ID", "META_MARKETING_TOKEN"] },
      });
      return (data?.found ?? []) as string[];
    },
    staleTime: 60_000,
    retry: false,
    // If edge function doesn't exist yet, return empty
    placeholderData: [],
  });
}

export function GrowthSetupWizard() {
  const { data: settings, isLoading: settingsLoading } = useAdminGrowthSettings();
  const updateSettings = useUpdateAdminGrowthSettings();
  const { data: secretNames = [] } = useSecretNames();
  const [expandedStep, setExpandedStep] = useState<string | null>(null);
  const [form, setForm] = useState<Partial<AdminGrowthSettings>>({});
  const [locationInput, setLocationInput] = useState("");

  useEffect(() => {
    if (settings) setForm(settings);
  }, [settings]);

  const completedCount = STEPS.filter((s) => s.checkConnected(secretNames, settings ?? null)).length;
  const allDone = completedCount === STEPS.length;

  const update = (key: keyof AdminGrowthSettings, value: any) => {
    setForm((prev) => ({ ...prev, [key]: value }));
  };

  const toggleArrayItem = (key: keyof AdminGrowthSettings, item: string) => {
    const arr = (form[key] as string[]) || [];
    update(key, arr.includes(item) ? arr.filter((i) => i !== item) : [...arr, item]);
  };

  const saveSettings = () => {
    const { id, created_at, updated_at, discovery_stats, best_industries, best_locations, ...rest } = form as any;
    updateSettings.mutate(rest);
  };

  const addLocation = () => {
    const loc = locationInput.trim();
    if (!loc) return;
    const locs = (form.discovery_locations as string[]) || [];
    if (!locs.includes(loc)) update("discovery_locations", [...locs, loc]);
    setLocationInput("");
  };

  if (settingsLoading) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center py-12">
          <Loader2 className="h-6 w-6 animate-spin" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-primary/20">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary/10">
              <Sparkles className="h-5 w-5 text-primary" />
            </div>
            <div>
              <CardTitle className="text-base">Setup Your Growth Engine</CardTitle>
              <p className="text-xs text-muted-foreground mt-0.5">
                {allDone
                  ? "All systems connected! Your engine is running."
                  : `${completedCount} of ${STEPS.length} steps complete — finish setup to go fully autonomous`}
              </p>
            </div>
          </div>
          {!allDone && (
            <Badge variant="outline" className="text-xs text-amber-600 border-amber-300 bg-amber-50">
              <AlertTriangle className="h-3 w-3 mr-1" /> Setup Incomplete
            </Badge>
          )}
          {allDone && (
            <Badge className="text-xs bg-emerald-500">
              <CheckCircle2 className="h-3 w-3 mr-1" /> All Connected
            </Badge>
          )}
        </div>
        {/* Progress bar */}
        <div className="w-full h-2 bg-muted rounded-full mt-3 overflow-hidden">
          <div
            className="h-full bg-primary rounded-full transition-all duration-500"
            style={{ width: `${(completedCount / STEPS.length) * 100}%` }}
          />
        </div>
      </CardHeader>
      <CardContent className="space-y-2 pb-4">
        {STEPS.map((step, idx) => {
          const isConnected = step.checkConnected(secretNames, settings ?? null);
          const isExpanded = expandedStep === step.id;
          const Icon = step.icon;

          return (
            <div key={step.id} className="border rounded-lg overflow-hidden">
              {/* Step Header */}
              <button
                className="w-full flex items-center gap-3 p-3 hover:bg-muted/50 transition-colors text-left"
                onClick={() => setExpandedStep(isExpanded ? null : step.id)}
              >
                <div className="flex items-center justify-center">
                  {isConnected ? (
                    <CheckCircle2 className="h-5 w-5 text-emerald-500" />
                  ) : (
                    <div className="h-5 w-5 rounded-full border-2 border-muted-foreground/30 flex items-center justify-center text-[10px] font-bold text-muted-foreground">
                      {idx + 1}
                    </div>
                  )}
                </div>
                <Icon className={`h-4 w-4 ${step.color}`} />
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium">{step.title}</span>
                    {isConnected && <Badge variant="outline" className="text-[9px] text-emerald-600 border-emerald-300">Connected</Badge>}
                  </div>
                  <p className="text-xs text-muted-foreground">{step.subtitle}</p>
                </div>
                {isExpanded ? <ChevronDown className="h-4 w-4 text-muted-foreground" /> : <ChevronRight className="h-4 w-4 text-muted-foreground" />}
              </button>

              {/* Step Content */}
              {isExpanded && (
                <div className="border-t px-4 py-4 bg-muted/20 space-y-4">
                  {step.id === "email" && <EmailStep isConnected={isConnected} />}
                  {step.id === "discovery" && (
                    <DiscoveryStep
                      form={form}
                      update={update}
                      toggleArrayItem={toggleArrayItem}
                      locationInput={locationInput}
                      setLocationInput={setLocationInput}
                      addLocation={addLocation}
                      onSave={saveSettings}
                      isSaving={updateSettings.isPending}
                    />
                  )}
                  {step.id === "social" && <SocialStep isConnected={isConnected} />}
                  {step.id === "ads" && <AdsStep isConnected={isConnected} />}
                </div>
              )}
            </div>
          );
        })}

        {/* Quick Settings */}
        <div className="border rounded-lg p-3 mt-3">
          <div className="flex items-center gap-2 mb-3">
            <Globe className="h-4 w-4 text-muted-foreground" />
            <span className="text-sm font-medium">Quick Settings</span>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <Label className="text-xs">From Email</Label>
              <Input value={form.outreach_from_email ?? ""} onChange={(e) => update("outreach_from_email", e.target.value)} className="h-8 text-sm mt-1" placeholder="hello@closeloop.ai" />
            </div>
            <div>
              <Label className="text-xs">From Name</Label>
              <Input value={form.outreach_from_name ?? ""} onChange={(e) => update("outreach_from_name", e.target.value)} className="h-8 text-sm mt-1" placeholder="CloseLoop" />
            </div>
            <div>
              <Label className="text-xs">Demo Link</Label>
              <Input value={form.demo_link ?? ""} onChange={(e) => update("demo_link", e.target.value)} className="h-8 text-sm mt-1" placeholder="https://closeloop.ai" />
            </div>
            <div>
              <Label className="text-xs">Trial / Signup Link</Label>
              <Input value={form.trial_link ?? ""} onChange={(e) => update("trial_link", e.target.value)} className="h-8 text-sm mt-1" placeholder="https://closeloop.ai/signup" />
            </div>
            <div>
              <Label className="text-xs">Alert Email</Label>
              <Input value={form.notification_email ?? ""} onChange={(e) => update("notification_email", e.target.value || null)} className="h-8 text-sm mt-1" placeholder="admin@closeloop.ai" />
            </div>
            <div>
              <Label className="text-xs">Quiet Hours</Label>
              <div className="flex items-center gap-1 mt-1">
                <Input value={form.outreach_quiet_hours_start ?? "21:00"} onChange={(e) => update("outreach_quiet_hours_start", e.target.value)} className="h-8 text-sm" placeholder="21:00" />
                <span className="text-xs text-muted-foreground">to</span>
                <Input value={form.outreach_quiet_hours_end ?? "08:00"} onChange={(e) => update("outreach_quiet_hours_end", e.target.value)} className="h-8 text-sm" placeholder="08:00" />
              </div>
            </div>
          </div>
          <div className="mt-3">
            <Label className="text-xs">Quiet Days (no outreach)</Label>
            <div className="flex flex-wrap gap-1.5 mt-1">
              {DAYS.map((day, i) => (
                <Badge
                  key={day}
                  variant={(form.outreach_quiet_days || []).includes(DAY_FULL[i]) ? "default" : "outline"}
                  className="cursor-pointer text-xs"
                  onClick={() => toggleArrayItem("outreach_quiet_days", DAY_FULL[i])}
                >
                  {day}
                </Badge>
              ))}
            </div>
          </div>
          <div className="flex items-center gap-4 mt-3">
            <div className="flex items-center gap-2">
              <Switch checked={form.notify_on_response ?? true} onCheckedChange={(v) => update("notify_on_response", v)} />
              <Label className="text-xs">Notify on response</Label>
            </div>
            <div className="flex items-center gap-2">
              <Switch checked={form.notify_on_conversion ?? true} onCheckedChange={(v) => update("notify_on_conversion", v)} />
              <Label className="text-xs">Notify on conversion</Label>
            </div>
          </div>
          <div className="mt-4 flex justify-end">
            <Button size="sm" onClick={saveSettings} disabled={updateSettings.isPending}>
              {updateSettings.isPending ? <Loader2 className="h-4 w-4 animate-spin mr-1" /> : <Save className="h-4 w-4 mr-1" />}
              Save Settings
            </Button>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

/* ───────── Step: Email ───────── */
function EmailStep({ isConnected }: { isConnected: boolean }) {
  return (
    <div className="space-y-3">
      <div className="bg-background rounded-lg p-3 border space-y-2">
        <div className="flex items-center gap-2">
          <Key className="h-4 w-4 text-blue-600" />
          <span className="text-sm font-medium">Resend API Key</span>
          {isConnected && <Badge className="text-[9px] bg-emerald-500">Added</Badge>}
        </div>
        <p className="text-xs text-muted-foreground">
          Resend sends your outreach emails. Here's how to get your API key:
        </p>
        <ol className="text-xs text-muted-foreground space-y-1 ml-4 list-decimal">
          <li>Go to <a href="https://resend.com/signup" target="_blank" rel="noreferrer" className="text-primary underline">resend.com</a> and create a free account</li>
          <li>Navigate to <strong>API Keys</strong> in the left sidebar</li>
          <li>Click <strong>"Create API Key"</strong>, name it "CloseLoop Growth"</li>
          <li>Copy the key and click the button below to paste it in</li>
        </ol>
        {!isConnected && (
          <AddSecretButton secretName="RESEND_API_KEY" label="Add Resend API Key" />
