                </div>
              </div>
            ))}
          </div>
        )
      )}

      {view === "activity" && <OutreachActivityLog campaignId={campaign.id} />}
    </div>
  );
}

import { useState, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Plus, Trash2, Save, Mail, MessageSquare, Clock, GitBranch, Loader2, ArrowLeft } from "lucide-react";
import {
  useOutreachSequences,
  useOutreachSequenceSteps,
  useCreateOutreachSequence,
  useUpdateOutreachSequence,
  useDeleteOutreachSequence,
  useSaveSequenceSteps,
  type OutreachSequence,
  type OutreachSequenceStep,
} from "@/hooks/useAdminOutreach";

const STEP_TYPE_ICONS: Record<string, any> = {
  email: Mail,
  sms: MessageSquare,
  wait: Clock,
  condition: GitBranch,
};

const STEP_TYPE_LABELS: Record<string, string> = {
  email: "Email",
  sms: "SMS",
  wait: "Wait",
  condition: "Condition",
};

interface StepDraft {
  step_order: number;
  step_type: string;
  delay_hours: number;
  subject: string;
  message_template: string;
  use_ai_personalization: boolean;
  skip_if_responded: boolean;
  sequence_id: string;
}

export function OutreachSequenceEditor() {
  const { data: sequences, isLoading } = useOutreachSequences();
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<OutreachSequence | null>(null);
  const createSeq = useCreateOutreachSequence();
  const updateSeq = useUpdateOutreachSequence();
  const deleteSeq = useDeleteOutreachSequence();

  const selected = sequences?.find((s) => s.id === selectedId);

  if (isLoading) {
    return <div className="flex items-center justify-center py-12"><Loader2 className="h-6 w-6 animate-spin" /></div>;
  }

  if (selectedId && selected) {
    return (
      <StepEditor
        sequence={selected}
        onBack={() => setSelectedId(null)}
        onUpdateName={(name) => updateSeq.mutate({ id: selected.id, name })}
      />
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="font-semibold">Outreach Sequences</h3>
          <p className="text-xs text-muted-foreground">Multi-step email and SMS outreach templates</p>
        </div>
        <Button
          size="sm"
          onClick={() => {
            createSeq.mutate(
              { name: "New Sequence", target_type: "business" },
              { onSuccess: (data) => setSelectedId(data.id) }
            );
          }}
          disabled={createSeq.isPending}
        >
          <Plus className="h-4 w-4 mr-1" /> New Sequence
        </Button>
      </div>

      <div className="grid gap-2">
        {(sequences ?? []).map((seq) => (
          <Card
            key={seq.id}
            className="cursor-pointer hover:border-primary/40 transition-colors"
            onClick={() => setSelectedId(seq.id)}
          >
            <CardContent className="p-3 flex items-center justify-between">
              <div>
                <div className="flex items-center gap-2">
                  <h4 className="font-medium text-sm">{seq.name}</h4>
                  {seq.is_default && <Badge variant="secondary" className="text-[10px]">Default</Badge>}
                  <Badge variant="outline" className="text-[10px] capitalize">{seq.target_type}</Badge>
                </div>
                {seq.description && (
                  <p className="text-xs text-muted-foreground mt-0.5">{seq.description}</p>
                )}
              </div>
              <div className="flex items-center gap-1">
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-7 w-7"
                  onClick={(e) => { e.stopPropagation(); setDeleteTarget(seq); }}
                >
                  <Trash2 className="h-3.5 w-3.5 text-muted-foreground" />
                </Button>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      <AlertDialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete sequence?</AlertDialogTitle>
            <AlertDialogDescription>
              Delete "{deleteTarget?.name}"? This will remove all steps and cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => { if (deleteTarget) deleteSeq.mutate(deleteTarget.id); setDeleteTarget(null); }}
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

function StepEditor({ sequence, onBack, onUpdateName }: {
  sequence: OutreachSequence;
  onBack: () => void;
  onUpdateName: (name: string) => void;
}) {
  const { data: existingSteps, isLoading } = useOutreachSequenceSteps(sequence.id);
  const saveSteps = useSaveSequenceSteps();
  const [steps, setSteps] = useState<StepDraft[]>([]);
  const [name, setName] = useState(sequence.name);

  useEffect(() => {
    if (existingSteps) {
      setSteps(existingSteps.map((s) => ({
        step_order: s.step_order,
        step_type: s.step_type,
        delay_hours: s.delay_hours,
        subject: s.subject || "",
        message_template: s.message_template || "",
        use_ai_personalization: s.use_ai_personalization,
        skip_if_responded: s.skip_if_responded,
        sequence_id: sequence.id,
      })));
    }
  }, [existingSteps, sequence.id]);

  const addStep = (type: string) => {
    const newOrder = steps.length + 1;
    setSteps([...steps, {
      step_order: newOrder,
      step_type: type,
      delay_hours: type === "wait" ? 72 : 0,
      subject: "",
      message_template: "",
      use_ai_personalization: type === "email",
      skip_if_responded: true,
      sequence_id: sequence.id,
    }]);
  };

  const removeStep = (index: number) => {
    const newSteps = steps.filter((_, i) => i !== index).map((s, i) => ({ ...s, step_order: i + 1 }));
    setSteps(newSteps);
  };

  const updateStep = (index: number, updates: Partial<StepDraft>) => {
    setSteps(steps.map((s, i) => i === index ? { ...s, ...updates } : s));
  };

  const handleSave = () => {
    if (name !== sequence.name) onUpdateName(name);
    saveSteps.mutate({ sequenceId: sequence.id, steps });
  };

  if (isLoading) {
    return <div className="flex items-center justify-center py-12"><Loader2 className="h-6 w-6 animate-spin" /></div>;
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={onBack}>
          <ArrowLeft className="h-4 w-4" />
        </Button>
        <Input
          value={name}
          onChange={(e) => setName(e.target.value)}
          className="h-8 text-sm font-semibold max-w-xs"
        />
        <Button size="sm" onClick={handleSave} disabled={saveSteps.isPending}>
          {saveSteps.isPending ? <Loader2 className="h-4 w-4 animate-spin mr-1" /> : <Save className="h-4 w-4 mr-1" />}
          Save
        </Button>
      </div>

      <div className="space-y-2">
        {steps.map((step, i) => {
          const Icon = STEP_TYPE_ICONS[step.step_type] || Clock;
          return (
            <Card key={i}>
              <CardContent className="p-3 space-y-2">
                <div className="flex items-center gap-2">
                  <Badge variant="outline" className="text-xs">
                    <Icon className="h-3 w-3 mr-1" />
                    Step {step.step_order}: {STEP_TYPE_LABELS[step.step_type]}
                  </Badge>
                  <div className="flex-1" />
                  <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => removeStep(i)}>
                    <Trash2 className="h-3 w-3 text-muted-foreground" />
                  </Button>
                </div>

                {step.step_type === "wait" && (
                  <div className="flex items-center gap-2">
                    <Label className="text-xs">Wait</Label>
                    <Input
                      type="number"
                      value={step.delay_hours}
                      onChange={(e) => updateStep(i, { delay_hours: Number(e.target.value) })}
                      className="h-7 text-xs w-20"
                    />
                    <span className="text-xs text-muted-foreground">hours ({Math.round(step.delay_hours / 24)}d)</span>
                  </div>
                )}

                {step.step_type === "email" && (
                  <>
                    <div>
                      <Label className="text-xs">Subject</Label>
                      <Input
                        value={step.subject}
                        onChange={(e) => updateStep(i, { subject: e.target.value })}
                        className="h-7 text-xs mt-1"
                        placeholder="Email subject with {{tokens}}"
                      />
                    </div>
                    <div>
                      <Label className="text-xs">Body</Label>
                      <Textarea
                        value={step.message_template}
                        onChange={(e) => updateStep(i, { message_template: e.target.value })}
                        className="text-xs mt-1 min-h-[80px]"
                        placeholder="Email body with {{business_name}}, {{reason_snippet}}, etc."
                      />
                    </div>
                    <div className="flex items-center gap-4">
                      <div className="flex items-center gap-1.5">
                        <Switch
                          checked={step.use_ai_personalization}
                          onCheckedChange={(v) => updateStep(i, { use_ai_personalization: v })}
                        />
                        <Label className="text-xs">AI personalization</Label>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <Switch
                          checked={step.skip_if_responded}
                          onCheckedChange={(v) => updateStep(i, { skip_if_responded: v })}
                        />
                        <Label className="text-xs">Skip if responded</Label>
                      </div>
                    </div>
                  </>
                )}

                {step.step_type === "sms" && (
                  <>
                    <div>
                      <Label className="text-xs">Message</Label>
                      <Textarea
                        value={step.message_template}
                        onChange={(e) => updateStep(i, { message_template: e.target.value })}
                        className="text-xs mt-1 min-h-[60px]"
                        placeholder="SMS message with {{tokens}}"
                      />
                    </div>
                    <div className="flex items-center gap-1.5">
                      <Switch
                        checked={step.skip_if_responded}
                        onCheckedChange={(v) => updateStep(i, { skip_if_responded: v })}
                      />
                      <Label className="text-xs">Skip if responded</Label>
                    </div>
                  </>
                )}

                {step.step_type === "condition" && (
                  <p className="text-xs text-muted-foreground">
                    Skips remaining steps if the lead has responded.
                  </p>
                )}
              </CardContent>
            </Card>
          );
        })}
      </div>

      <div className="flex items-center gap-2">
        <span className="text-xs text-muted-foreground">Add step:</span>
        <Button size="sm" variant="outline" onClick={() => addStep("email")}>
          <Mail className="h-3.5 w-3.5 mr-1" /> Email
        </Button>
        <Button size="sm" variant="outline" onClick={() => addStep("sms")}>
          <MessageSquare className="h-3.5 w-3.5 mr-1" /> SMS
        </Button>
        <Button size="sm" variant="outline" onClick={() => addStep("wait")}>
          <Clock className="h-3.5 w-3.5 mr-1" /> Wait
        </Button>
        <Button size="sm" variant="outline" onClick={() => addStep("condition")}>
          <GitBranch className="h-3.5 w-3.5 mr-1" /> Condition
        </Button>
      </div>

      <div className="text-xs text-muted-foreground">
        Available tokens: {"{{business_name}}"}, {"{{from_name}}"}, {"{{reason_snippet}}"}, {"{{demo_link}}"}, {"{{trial_link}}"}
      </div>
    </div>
  );
}

import { useState, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { ChevronLeft, ChevronRight, Trash2, Loader2 } from "lucide-react";
import { format, startOfWeek, addDays, isSameDay } from "date-fns";
import { useAdminSocialPosts, useDeleteSocialPost, type AdminSocialPost } from "@/hooks/useAdminSocialPosts";
import { SocialPostEditor } from "./SocialPostEditor";
import { SocialPostGenerator } from "./SocialPostGenerator";

const PLATFORM_COLORS: Record<string, string> = {
  linkedin: "bg-blue-500/10 text-blue-700 border-blue-500/20",
  twitter: "bg-sky-500/10 text-sky-700 border-sky-500/20",
  facebook: "bg-indigo-500/10 text-indigo-700 border-indigo-500/20",
  instagram: "bg-pink-500/10 text-pink-700 border-pink-500/20",
  tiktok: "bg-purple-500/10 text-purple-700 border-purple-500/20",
};

const PLATFORM_LABELS: Record<string, string> = {
  linkedin: "LinkedIn",
  twitter: "Twitter/X",
  facebook: "Facebook",
  instagram: "Instagram",
  tiktok: "TikTok",
};

const STATUS_COLORS: Record<string, string> = {
  draft: "bg-yellow-500/10 text-yellow-700",
  scheduled: "bg-blue-500/10 text-blue-700",
  posted: "bg-green-500/10 text-green-700",
  failed: "bg-red-500/10 text-red-700",
};

export function SocialContentCalendar() {
  const { data: posts, isLoading } = useAdminSocialPosts();
  const deletePost = useDeleteSocialPost();
  const [weekStart, setWeekStart] = useState(() => startOfWeek(new Date(), { weekStartsOn: 1 }));
  const [editPost, setEditPost] = useState<AdminSocialPost | null>(null);
  const [deleteTarget, setDeleteTarget] = useState<AdminSocialPost | null>(null);

  const weekDays = useMemo(() => {
    return Array.from({ length: 7 }, (_, i) => addDays(weekStart, i));
  }, [weekStart]);

  const postsByDay = useMemo(() => {
    const map: Record<string, AdminSocialPost[]> = {};
    (posts ?? []).forEach((post) => {
      const day = format(new Date(post.scheduled_for), "yyyy-MM-dd");
      if (!map[day]) map[day] = [];
      map[day].push(post);
    });
    return map;
  }, [posts]);

  if (isLoading) {
    return <div className="flex items-center justify-center py-12"><Loader2 className="h-6 w-6 animate-spin" /></div>;
  }

  return (
    <div className="space-y-4">
      <SocialPostGenerator />

      <div className="flex items-center justify-between">
        <h3 className="font-semibold text-sm">Content Calendar</h3>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="icon" className="h-7 w-7" onClick={() => setWeekStart(addDays(weekStart, -7))}>
            <ChevronLeft className="h-4 w-4" />
          </Button>
          <span className="text-xs font-medium">
            {format(weekStart, "MMM d")} - {format(addDays(weekStart, 6), "MMM d, yyyy")}
          </span>
          <Button variant="outline" size="icon" className="h-7 w-7" onClick={() => setWeekStart(addDays(weekStart, 7))}>
            <ChevronRight className="h-4 w-4" />
          </Button>
        </div>
      </div>

      <div className="grid grid-cols-7 gap-1">
        {weekDays.map((day) => {
          const dayKey = format(day, "yyyy-MM-dd");
          const dayPosts = postsByDay[dayKey] || [];
          const isToday = isSameDay(day, new Date());

          return (
            <div
              key={dayKey}
              className={`min-h-[120px] border rounded-lg p-1.5 ${isToday ? "border-primary/50 bg-primary/5" : ""}`}
            >
              <div className="text-[10px] font-medium text-muted-foreground mb-1">
                {format(day, "EEE")}
                <span className={`ml-1 ${isToday ? "text-primary font-bold" : ""}`}>
                  {format(day, "d")}
                </span>
              </div>
              <div className="space-y-1">
                {dayPosts.map((post) => (
                  <div
                    key={post.id}
                    className="group relative bg-muted/50 rounded p-1 cursor-pointer hover:bg-muted transition-colors"
                    onClick={() => setEditPost(post)}
                  >
                    <div className="flex items-center gap-1">
                      <Badge variant="outline" className={`text-[8px] px-1 py-0 ${PLATFORM_COLORS[post.platform] || ""}`}>
                        {PLATFORM_LABELS[post.platform]?.slice(0, 2) || post.platform.slice(0, 2)}
                      </Badge>
                      <Badge variant="outline" className={`text-[8px] px-1 py-0 ${STATUS_COLORS[post.status] || ""}`}>
                        {post.status}
                      </Badge>
                    </div>
                    <p className="text-[9px] text-muted-foreground mt-0.5 line-clamp-2">{post.content}</p>
                    <button
                      className="absolute top-0.5 right-0.5 opacity-0 group-hover:opacity-100 transition-opacity"
                      onClick={(e) => { e.stopPropagation(); setDeleteTarget(post); }}
                    >
                      <Trash2 className="h-2.5 w-2.5 text-muted-foreground" />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      {(!posts || posts.length === 0) && (
        <p className="text-sm text-muted-foreground text-center py-4">
          No social posts scheduled. Click "Generate This Week" to create content.
        </p>
      )}

      <SocialPostEditor post={editPost} open={!!editPost} onOpenChange={(open) => !open && setEditPost(null)} />

      <AlertDialog open={!!deleteTarget} onOpenChange={() => setDeleteTarget(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete post?</AlertDialogTitle>
            <AlertDialogDescription>Delete this {deleteTarget?.platform} post?</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
              onClick={() => { if (deleteTarget) deletePost.mutate(deleteTarget.id); setDeleteTarget(null); }}
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useRef, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Send, Loader2, Bookmark, RotateCcw, Bot, User } from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";
import { useSaveMarketingContent, type ChatMessage } from "@/hooks/useMarketingChat";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import ReactMarkdown from "react-markdown";

const CATEGORIES = [
  { value: "general", label: "General" },
  { value: "content", label: "Content Ideas" },
  { value: "ads", label: "Ad Campaigns" },
  { value: "social", label: "Social Calendar" },
  { value: "scaling", label: "Scaling" },
  { value: "outreach", label: "Partner Outreach" },
];

export function MarketingChatPanel() {
  const { user } = useAuth();
  const userId = user?.id;
  const [category, setCategory] = useState("general");
  const [input, setInput] = useState("");
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const saveContent = useSaveMarketingContent(userId);

  // Listen for template events from parent
  useEffect(() => {
    const handler = (e: CustomEvent<{ prompt: string; category: string }>) => {
      setCategory(e.detail.category);
      handleSendDirect(e.detail.prompt, e.detail.category);
    };
    window.addEventListener("marketing-template" as any, handler);
    return () => window.removeEventListener("marketing-template" as any, handler);
  }, [messages]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleSendDirect = async (content: string, cat: string) => {
    if (!userId || isStreaming) return;

    const userMsg: ChatMessage = { role: "user", content, category: cat };
    const newMessages = [...messages, userMsg];
    setMessages(newMessages);
    setIsStreaming(true);

    try {
      const { data: { session } } = await supabase.auth.getSession();
      const token = session?.access_token;

      const resp = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/admin-marketing-chat`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${token}`,
            apikey: import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY,
          },
          body: JSON.stringify({
            messages: newMessages.map((m) => ({ role: m.role, content: m.content })),
          }),
        }
      );

      if (!resp.ok) {
        const errorData = await resp.json().catch(() => ({}));
        throw new Error(errorData.error || `Error ${resp.status}`);
      }

      // Handle SSE streaming
      const reader = resp.body?.getReader();
      if (!reader) throw new Error("No response body");

      const decoder = new TextDecoder();
      let assistantContent = "";

      // Add placeholder assistant message
      setMessages((prev) => [...prev, { role: "assistant", content: "", category: cat }]);

      let buffer = "";
      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop() || "";

        for (const line of lines) {
          if (!line.startsWith("data: ")) continue;
          const data = line.slice(6).trim();
          if (data === "[DONE]") continue;

          try {
            const parsed = JSON.parse(data);
            const delta = parsed.choices?.[0]?.delta?.content;
            if (delta) {
              assistantContent += delta;
              setMessages((prev) => {
                const updated = [...prev];
                updated[updated.length - 1] = {
                  role: "assistant",
                  content: assistantContent,
                  category: cat,
                };
                return updated;
              });
            }
          } catch {
            // ignore parse errors on partial chunks
          }
        }
      }

      // If no streaming content was captured, show fallback
      if (!assistantContent) {
        setMessages((prev) => {
          const updated = [...prev];
          updated[updated.length - 1] = {
            role: "assistant",
            content: "I apologize, I couldn't generate a response. Please try again.",
            category: cat,
          };
          return updated;
        });
      }
    } catch (err) {
      console.error("Marketing chat error:", err);
      toast.error(err instanceof Error ? err.message : "Failed to get AI response");
      // Remove the empty assistant message if there was an error
      setMessages((prev) => prev.filter((m) => m.content !== ""));
    } finally {
      setIsStreaming(false);
    }
  };

  const handleSend = () => {
    const trimmed = input.trim();
    if (!trimmed || isStreaming) return;
    setInput("");
    handleSendDirect(trimmed, category);
  };

  const handleSaveResponse = (msg: ChatMessage) => {
    const title = msg.content.substring(0, 80).replace(/[#*\n]/g, "").trim() + "...";
    saveContent.mutate({
      category: msg.category || category,
      title,
      content: msg.content,
    });
  };

  const clearChat = () => setMessages([]);

  return (
    <div className="flex flex-col h-[calc(100vh-16rem)]">
      {/* Category tabs */}
      <div className="flex items-center justify-between mb-3">
        <Tabs value={category} onValueChange={setCategory}>
          <TabsList className="h-8">
            {CATEGORIES.map((cat) => (
              <TabsTrigger key={cat.value} value={cat.value} className="text-xs px-3 h-6">
                {cat.label}
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>
        {messages.length > 0 && (
          <Button variant="ghost" size="sm" onClick={clearChat} className="text-xs">
            <RotateCcw className="h-3.5 w-3.5 mr-1" /> New Chat
          </Button>
        )}
      </div>

      {/* Messages area */}
      <div className="flex-1 overflow-y-auto space-y-4 pr-2 min-h-0">
        {messages.length === 0 && (
          <div className="text-center py-16 text-muted-foreground">
            <Bot className="h-12 w-12 mx-auto mb-4 opacity-30" />
            <h3 className="text-lg font-medium mb-2">Marketing AI Strategist</h3>
            <p className="text-sm max-w-md mx-auto">
              Your AI CMO for CloseLoop. Ask me anything about marketing, content, ads,
              social media, partnerships, or scaling — I'll give you exact, actionable strategies.
            </p>
            <p className="text-xs mt-3 text-muted-foreground/60">
              Try a template from the Templates tab for comprehensive, ready-to-execute strategies.
            </p>
          </div>
        )}

        {messages.map((msg, i) => (
          <div
            key={i}
            className={`flex gap-3 ${msg.role === "user" ? "justify-end" : "justify-start"}`}
          >
            {msg.role === "assistant" && (
              <div className="h-7 w-7 rounded-full bg-primary/10 flex items-center justify-center shrink-0 mt-1">
                <Bot className="h-4 w-4 text-primary" />
              </div>
            )}
            <div
              className={`max-w-[85%] rounded-lg px-4 py-3 text-sm ${
                msg.role === "user"
                  ? "bg-primary text-primary-foreground"
                  : "bg-muted"
              }`}
            >
              {msg.role === "assistant" ? (
                <div className="prose prose-sm dark:prose-invert max-w-none [&>*:first-child]:mt-0 [&>*:last-child]:mb-0">
                  <ReactMarkdown>{msg.content || "..."}</ReactMarkdown>
                </div>
              ) : (
                <div className="whitespace-pre-wrap">{msg.content}</div>
              )}
              {msg.role === "assistant" && msg.content && (
                <div className="mt-2 pt-2 border-t border-border/40 flex items-center gap-2">
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-6 text-[10px] px-2"
                    onClick={() => handleSaveResponse(msg)}
                    disabled={saveContent.isPending}
                  >
                    <Bookmark className="h-3 w-3 mr-1" /> Save to Library
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-6 text-[10px] px-2"
                    onClick={() => {
                      navigator.clipboard.writeText(msg.content);
                      toast.success("Copied to clipboard");
                    }}
                  >
                    Copy
                  </Button>
                </div>
              )}
            </div>
            {msg.role === "user" && (
              <div className="h-7 w-7 rounded-full bg-foreground/10 flex items-center justify-center shrink-0 mt-1">
                <User className="h-4 w-4" />
              </div>
            )}
          </div>
        ))}

        {isStreaming && messages[messages.length - 1]?.role !== "assistant" && (
          <div className="flex gap-3">
            <div className="h-7 w-7 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
              <Bot className="h-4 w-4 text-primary" />
            </div>
            <div className="bg-muted rounded-lg px-4 py-3">
              <Loader2 className="h-4 w-4 animate-spin" />
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      {/* Input area */}
      <div className="mt-3 flex gap-2">
        <Textarea
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder={`Ask about ${CATEGORIES.find((c) => c.value === category)?.label.toLowerCase() || "marketing"}...`}
          className="min-h-[48px] max-h-[120px] resize-none"
          onKeyDown={(e) => {
            if (e.key === "Enter" && !e.shiftKey) {
              e.preventDefault();
              handleSend();
            }
          }}
        />
        <Button
          onClick={handleSend}
          disabled={!input.trim() || isStreaming}
          className="shrink-0 h-12 w-12"
        >
          {isStreaming ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
        </Button>
      </div>
    </div>
  );
}

import { useState, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Search, Globe, Phone, Star, ExternalLink, Loader2, MapPin, Bookmark, Check, AlertCircle } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { scoreAgencyLead, getTemperatureColor, getTemperatureIcon, type LeadTemperature } from "./lead-finder/leadScoring";
import { LeadDetailPanel, type AgencyLead } from "./lead-finder/LeadDetailPanel";
import { SavedLeadsTab } from "./lead-finder/SavedLeadsTab";
import { SIGNAL_LABELS } from "./lead-finder/leadConstants";
import { useIsAgencyUser } from "@/hooks/useAgencyData";
import {
  useAgencySearchLimit,
  useSavedLeads, useSaveLead, useSaveLeadsBatch,
} from "@/hooks/useAgencyLeads";

const INDUSTRY_OPTIONS = [
  { value: "all", label: "All Industries (Top 10)" },
  { value: "towing", label: "Towing" },
  { value: "plumber", label: "Plumber" },
  { value: "hvac", label: "HVAC" },
  { value: "electrician", label: "Electrician" },
  { value: "locksmith", label: "Locksmith" },
  { value: "auto repair", label: "Auto Repair" },
  { value: "dental", label: "Dental" },
  { value: "med spa", label: "Med Spa" },
  { value: "salon", label: "Salon / Barbershop" },
  { value: "pest control", label: "Pest Control" },
  { value: "landscaping", label: "Landscaping" },
  { value: "roofing", label: "Roofing" },
  { value: "mobile detailing", label: "Mobile Detailing" },
  { value: "cleaning service", label: "Cleaning Service" },
  { value: "restaurant", label: "Restaurant" },
  { value: "veterinary", label: "Veterinary" },
  { value: "real estate", label: "Real Estate" },
  { value: "insurance agency", label: "Insurance Agency" },
  { value: "law firm", label: "Law Firm" },
  { value: "fitness studio", label: "Fitness Studio" },
];

interface AgencyLeadFinderProps {
  onProvisionLead?: (lead: { name: string; industry?: string }) => void;
}

export function AgencyLeadFinder({ onProvisionLead }: AgencyLeadFinderProps = {}) {
  const { agencyId } = useIsAgencyUser();
  const [industry, setIndustry] = useState("");
  const [location, setLocation] = useState("");
  const [leads, setLeads] = useState<AgencyLead[]>([]);
  const [isSearching, setIsSearching] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  const [selectedLead, setSelectedLead] = useState<AgencyLead | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);
  const [tempFilter, setTempFilter] = useState<"all" | LeadTemperature>("all");
  const [mainTab, setMainTab] = useState("search");

  const searchLimit = useAgencySearchLimit(agencyId);
  const savedLeads = useSavedLeads(agencyId);
  const saveLead = useSaveLead(agencyId);
  const saveLeadsBatch = useSaveLeadsBatch(agencyId);

  const savedNames = useMemo(() => {
    const set = new Set<string>();
    (savedLeads.data ?? []).forEach((l) => set.add(l.name.toLowerCase().trim()));
    return set;
  }, [savedLeads.data]);

  const isLeadSaved = (name: string) => savedNames.has(name.toLowerCase().trim());

  const handleSearch = async () => {
    if (!industry || !location) {
      toast.error("Select an industry and enter a location");
      return;
    }

    const remaining = searchLimit.data?.remaining ?? 3;
    if (remaining <= 0) {
      toast.error("Daily search limit reached (3/3). Try again tomorrow.");
      return;
    }

    setIsSearching(true);
    setLeads([]);
    setTempFilter("all");

    try {
      const { data, error } = await supabase.functions.invoke("agency-lead-search", {
        body: { industry, location, count: 50 },
      });
      if (error) throw error;

      const rawLeads: AgencyLead[] = (data.leads || []).map((l: any) => ({
        ...l,
        industry: l.industry || industry,
        score: scoreAgencyLead({
          friction_signals: l.friction_signals,
          rating: l.rating,
          review_count: l.review_count,
          phone: l.phone,
          website: l.website,
          industry: l.industry || industry,
          estimated_missed_call_pct: l.estimated_missed_call_pct,
          tech_stack_signals: l.tech_stack_signals,
          years_in_business: l.years_in_business,
          owner_name: l.owner_name,
        }),
      }));

      rawLeads.sort((a, b) => (b.score?.score ?? 0) - (a.score?.score ?? 0));
      setLeads(rawLeads);
      setHasSearched(true);

      // Search is already logged server-side by the edge function — do NOT log again here

      if (rawLeads.length === 0) {
        toast.info("No leads found. Try a different location or industry.");
      } else {
        toast.success(`Found ${rawLeads.length} leads`);
      }
    } catch (err) {
      console.error("Lead search failed:", err);
      toast.error("Search failed. Please try again.");
    } finally {
      setIsSearching(false);
    }
  };

  const filteredLeads = useMemo(() => {
    if (tempFilter === "all") return leads;
    return leads.filter((l) => l.score?.temperature === tempFilter);
  }, [leads, tempFilter]);

  const tempCounts = useMemo(() => {
    const counts = { hot: 0, warm: 0, cold: 0 };
    leads.forEach((l) => {
      if (l.score?.temperature) counts[l.score.temperature]++;
    });
    return counts;
  }, [leads]);

  const openDetail = (lead: AgencyLead) => {
    setSelectedLead(lead);
    setDetailOpen(true);
  };

  const buildSavePayload = (lead: AgencyLead) => ({
    name: lead.name,
    phone: lead.phone,
    website: lead.website,
    address: lead.address,
    industry: lead.industry || null,
    rating: lead.rating,
    review_count: lead.review_count,
    employee_estimate: lead.employee_estimate || null,
    hours: lead.hours || null,
    reason: lead.reason,
    friction_signals: lead.friction_signals || [],
    confidence: lead.confidence,
    score: lead.score?.score ?? null,
    temperature: lead.score?.temperature ?? null,
    score_reasons: lead.score?.reasons ?? [],
  });

  const handleSaveAll = () => {
    const unsaved = filteredLeads.filter((l) => !isLeadSaved(l.name));
    if (unsaved.length === 0) {
      toast.info("All leads are already saved");
      return;
    }
    saveLeadsBatch.mutate(unsaved.map(buildSavePayload));
  };

  const handleSaveSingle = (lead: AgencyLead) => {
    saveLead.mutate(buildSavePayload(lead), {
      onSuccess: () => toast.success(`"${lead.name}" saved`),
    });
  };

  const remaining = searchLimit.data?.remaining ?? 3;
  const used = searchLimit.data?.used ?? 0;

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-lg font-semibold">Lead Finder</h2>
          <p className="text-sm text-muted-foreground">
            Find local businesses that are missing calls and need an AI receptionist.
          </p>
        </div>
        <Badge variant="outline" className={`text-xs ${remaining <= 0 ? "bg-destructive/10 text-destructive" : ""}`}>
          {used}/3 searches today
        </Badge>
      </div>

      <Tabs value={mainTab} onValueChange={setMainTab}>
        <TabsList className="h-9">
          <TabsTrigger value="search" className="text-xs px-4">Search</TabsTrigger>
          <TabsTrigger value="saved" className="text-xs px-4">
            Saved Leads {savedLeads.data?.length ? `(${savedLeads.data.length})` : ""}
          </TabsTrigger>
        </TabsList>

        <TabsContent value="search" className="mt-4 space-y-4">
          {/* Search Controls */}
          <div className="flex flex-col sm:flex-row gap-3">
            <div className="flex-1">
              <Label className="text-xs mb-1.5 block">Industry</Label>
              <Select value={industry} onValueChange={setIndustry}>
                <SelectTrigger><SelectValue placeholder="Select industry" /></SelectTrigger>
                <SelectContent>
                  {INDUSTRY_OPTIONS.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>{opt.label}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="flex-1">
              <Label className="text-xs mb-1.5 block">Location</Label>
              <Input
                placeholder="e.g. Austin, TX"
                value={location}
                onChange={(e) => setLocation(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleSearch()}
              />
            </div>
            <div className="flex items-end">
              <Button onClick={handleSearch} disabled={isSearching || !industry || !location || remaining <= 0}>
                {isSearching ? (
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                ) : (
                  <Search className="h-4 w-4 mr-2" />
                )}
                {isSearching ? "Searching..." : remaining <= 0 ? "Limit Reached" : "Find Leads"}
              </Button>
            </div>
          </div>

          {remaining <= 0 && (
            <div className="flex items-center gap-2 text-sm text-destructive bg-destructive/5 rounded-lg p-3">
              <AlertCircle className="h-4 w-4 shrink-0" />
              You've used all 3 searches for today. Searches reset at midnight.
            </div>
          )}

          {/* Loading */}
          {isSearching && (
            <div className="text-center py-12 text-muted-foreground text-sm">
              <Loader2 className="h-8 w-8 animate-spin mx-auto mb-3" />
              <p>Searching for {industry} businesses in {location}...</p>
              <p className="text-xs mt-1">This may take a moment as we search multiple sources.</p>
            </div>
          )}

          {/* Results */}
          {!isSearching && leads.length > 0 && (
            <div className="space-y-3">
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2">
                <Tabs value={tempFilter} onValueChange={(v) => setTempFilter(v as "all" | LeadTemperature)}>
                  <TabsList className="h-8">
                    <TabsTrigger value="all" className="text-xs px-3 h-6">All ({leads.length})</TabsTrigger>
                    <TabsTrigger value="hot" className="text-xs px-3 h-6">Hot ({tempCounts.hot})</TabsTrigger>
                    <TabsTrigger value="warm" className="text-xs px-3 h-6">Warm ({tempCounts.warm})</TabsTrigger>
                    <TabsTrigger value="cold" className="text-xs px-3 h-6">Cold ({tempCounts.cold})</TabsTrigger>
                  </TabsList>
                </Tabs>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted-foreground">{filteredLeads.length} leads</span>
                  <Button size="sm" variant="outline" onClick={handleSaveAll} disabled={saveLeadsBatch.isPending}>
                    <Bookmark className="h-3.5 w-3.5 mr-1.5" />
                    Save All
                  </Button>
                </div>
              </div>

              <div className="grid gap-2">
                {filteredLeads.map((lead) => {
                  const saved = isLeadSaved(lead.name);
                  const key = `${lead.name}-${lead.address || lead.phone || ""}`;
                  return (
                    <Card
                      key={key}
                      className="cursor-pointer hover:border-primary/40 transition-colors"
                      onClick={() => openDetail(lead)}
                    >
                      <CardContent className="p-3">
                        <div className="flex items-start gap-3">
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 flex-wrap">
                              <h3 className="font-medium text-sm truncate">{lead.name}</h3>
                              {lead.score && (
                                <Badge variant="outline" className={`text-[10px] px-1.5 py-0 ${getTemperatureColor(lead.score.temperature)}`}>
                                  {getTemperatureIcon(lead.score.temperature)} {lead.score.temperature} {lead.score.score}
                                </Badge>
                              )}
                              {saved && (
                                <Badge variant="outline" className="text-[10px] px-1.5 py-0 bg-green-500/10 text-green-700 border-green-500/20">
                                  <Check className="h-2.5 w-2.5 mr-0.5" /> Saved
                                </Badge>
                              )}
                              {lead.industry && (
                                <span className="text-[10px] text-muted-foreground capitalize">{lead.industry}</span>
                              )}
                            </div>
                            <p className="text-xs text-muted-foreground mt-1 line-clamp-1">{lead.reason}</p>
                            <div className="flex items-center gap-3 mt-1.5 text-[11px] text-muted-foreground">
                              {lead.estimated_missed_call_pct != null && lead.estimated_monthly_calls != null && (
                                <span className="flex items-center gap-0.5 text-destructive font-medium">
                                  ~{Math.round((lead.estimated_monthly_calls * (lead.estimated_missed_call_pct / 100)) / 4)}/wk missed
                                </span>
                              )}
                              {lead.rating != null && (
                                <span className="flex items-center gap-0.5">
                                  <Star className="h-3 w-3 fill-amber-400 text-amber-400" />
                                  {lead.rating}
                                  {lead.review_count != null && <span>({lead.review_count})</span>}
                                </span>
                              )}
                              {lead.phone && (
                                <span className="flex items-center gap-0.5">
                                  <Phone className="h-3 w-3" />{lead.phone}
                                </span>
                              )}
                              {lead.address && (
                                <span className="flex items-center gap-0.5 truncate">
                                  <MapPin className="h-3 w-3 shrink-0" />
                                  <span className="truncate">{lead.address}</span>
                                </span>
                              )}
                              {lead.website && (
                                <a href={lead.website} target="_blank" rel="noopener noreferrer" className="flex items-center gap-0.5 hover:text-primary" onClick={(e) => e.stopPropagation()}>
                                  <Globe className="h-3 w-3" />
                                  <span className="truncate max-w-[120px]">{lead.website.replace(/^https?:\/\//, "").replace(/\/$/, "")}</span>
                                </a>
                              )}
                            </div>
                          </div>

                          <div className="flex items-center gap-2">
                            <div className="hidden sm:flex flex-wrap gap-1 max-w-[180px] justify-end">
                              {lead.friction_signals?.slice(0, 3).map((signal) => (
                                <Badge key={signal} variant="secondary" className="text-[9px] px-1 py-0 whitespace-nowrap">
                                  {SIGNAL_LABELS[signal] || signal}
                                </Badge>
                              ))}
                            </div>
                            {!saved && (
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-7 w-7 shrink-0"
                                onClick={(e) => { e.stopPropagation(); handleSaveSingle(lead); }}
                              >
                                <Bookmark className="h-3.5 w-3.5" />
                              </Button>
                            )}
                          </div>
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}
              </div>
            </div>
          )}

          {!isSearching && hasSearched && leads.length === 0 && (
            <div className="text-center py-8 text-sm text-muted-foreground">
              No leads found. Try adjusting the industry or location.
            </div>
          )}
        </TabsContent>

        <TabsContent value="saved" className="mt-4">
          {agencyId && <SavedLeadsTab leads={savedLeads.data ?? []} agencyId={agencyId} onProvisionLead={onProvisionLead} />}
        </TabsContent>
      </Tabs>

      {/* Detail Panel — shared for search results */}
      <LeadDetailPanel
        lead={selectedLead}
        open={detailOpen}
        onOpenChange={setDetailOpen}
        isSaved={selectedLead ? isLeadSaved(selectedLead.name) : false}
        onSave={selectedLead && !isLeadSaved(selectedLead.name) ? () => handleSaveSingle(selectedLead) : undefined}
        savingInProgress={saveLead.isPending}
        onProvisionLead={onProvisionLead}
      />
    </div>
  );
}

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Loader2, Copy, Check, ExternalLink } from "lucide-react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { LADDER_STEPS, formatPrice, type PlanSku } from "@/config/pricing";

interface AgencyPaymentLinkDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tenantId: string;
  tenantName: string;
}

export function AgencyPaymentLinkDialog({
  open,
  onOpenChange,
  tenantId,
  tenantName,
}: AgencyPaymentLinkDialogProps) {
  const [selectedSku, setSelectedSku] = useState<PlanSku>("base-200");
  const [paymentLinkUrl, setPaymentLinkUrl] = useState<string | null>(null);
  const [linkLoading, setLinkLoading] = useState(false);
  const [payNowLoading, setPayNowLoading] = useState(false);
  const [copied, setCopied] = useState(false);

  const selectableSteps = LADDER_STEPS.filter((s) => !s.isEnterprise);

  const handlePayNow = async () => {
    setPayNowLoading(true);
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData?.session?.access_token;

      const { data, error } = await supabase.functions.invoke("create-checkout-session", {
        body: { plan_sku: selectedSku, tenant_id: tenantId },
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });

      if (error) throw new Error(error.message || "Failed to create checkout session");
      if (!data?.checkout_url) throw new Error("No checkout URL returned");

      window.location.href = data.checkout_url;
    } catch (err: any) {
      toast.error(err.message || "Failed to start checkout");
      setPayNowLoading(false);
    }
  };

  const handleGenerateLink = async () => {
    setLinkLoading(true);
    setPaymentLinkUrl(null);
    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData?.session?.access_token;

      const { data, error } = await supabase.functions.invoke("create-payment-link", {
        body: { plan_sku: selectedSku, tenant_id: tenantId },
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });

      if (error) throw new Error(error.message || "Failed to generate payment link");
      if (!data?.checkout_url) throw new Error("No payment link returned");

      setPaymentLinkUrl(data.checkout_url);
      toast.success("Payment link generated");
    } catch (err: any) {
      toast.error(err.message || "Failed to generate payment link");
    } finally {
      setLinkLoading(false);
    }
  };

  const handleCopy = async () => {
    if (!paymentLinkUrl) return;
    await navigator.clipboard.writeText(paymentLinkUrl);
    setCopied(true);
    toast.success("Link copied to clipboard");
    setTimeout(() => setCopied(false), 2000);
  };

  const handleClose = () => {
    onOpenChange(false);
    setTimeout(() => {
      setPaymentLinkUrl(null);
      setCopied(false);
    }, 300);
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Activate Plan</DialogTitle>
          <DialogDescription>
            Choose a plan for {tenantName} and send a payment link or pay now.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          <div>
            <Label className="text-sm font-medium mb-3 block">Select Plan</Label>
            <RadioGroup
              value={selectedSku}
              onValueChange={(v) => setSelectedSku(v as PlanSku)}
              className="space-y-2"
            >
              {selectableSteps.map((step) => (
                <div
                  key={step.sku}
                  className={`flex items-center justify-between p-3 rounded-lg border cursor-pointer ${
                    selectedSku === step.sku
                      ? "border-primary bg-primary/5"
                      : "border-border hover:border-primary/50"
                  }`}
                  onClick={() => setSelectedSku(step.sku)}
                >
                  <div className="flex items-center gap-2">
                    <RadioGroupItem value={step.sku} id={`plan-${step.sku}`} />
                    <Label htmlFor={`plan-${step.sku}`} className="cursor-pointer">
                      <div className="font-medium text-sm">{step.name}</div>
                      <div className="text-xs text-muted-foreground">
                        {step.includedMinutes?.toLocaleString()} minutes
                      </div>
                    </Label>
                  </div>
                  <span className="font-semibold text-sm">{formatPrice(step.price)}/mo</span>
                </div>
              ))}
            </RadioGroup>
          </div>

          {paymentLinkUrl && (
            <div className="space-y-2">
              <Label className="text-sm font-medium">Payment Link</Label>
              <div className="flex gap-2">
                <Input
                  value={paymentLinkUrl}
                  readOnly
                  className="text-xs"
                />
                <Button variant="outline" size="icon" onClick={handleCopy} className="shrink-0">
                  {copied ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
                </Button>
              </div>
              <p className="text-xs text-muted-foreground">
                Share this link with the client. It expires in 24 hours.
              </p>
            </div>
          )}

          <div className="flex gap-2 pt-2">
            <Button
              variant="outline"
              className="flex-1"
              onClick={handleGenerateLink}
              disabled={linkLoading}
            >
              {linkLoading ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : (
                <ExternalLink className="h-4 w-4 mr-2" />
              )}
              Generate Client Link
            </Button>
            <Button
              className="flex-1"
              onClick={handlePayNow}
              disabled={payNowLoading}
            >
              {payNowLoading ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : null}
              Pay Now (Agency)
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import type { ClientReadiness } from "@/hooks/useAgencyClientReadiness";

const STEPS = [
  { key: "provisioned", label: "Provisioned" },
  { key: "brain_setup", label: "Brain" },
  { key: "ai_ready", label: "AI Ready" },
  { key: "live", label: "Live" },
] as const;

const stepOrder: Record<string, number> = {
  provisioned: 0,
  brain_setup: 1,
  ai_ready: 2,
  plan_selected: 3,
  live: 3,
};

interface ClientOnboardingTrackerProps {
  readiness: ClientReadiness | undefined;
  tenantId: string;
  compact?: boolean;
}

export function ClientOnboardingTracker({ readiness, tenantId, compact = true }: ClientOnboardingTrackerProps) {
  const currentStep = stepOrder[readiness?.onboarding_step || "provisioned"] ?? 0;

  if (compact) {
    return (
      <div className="flex items-center gap-0.5">
        {STEPS.map((step, i) => {
          const isComplete = i <= currentStep;
          const isCurrent = i === currentStep;
          return (
            <div key={step.key} className="flex items-center">
              <div
                className={`h-2 w-2 rounded-full ${
                  isComplete
                    ? isCurrent && step.key !== "live"
                      ? "bg-amber-500"
                      : "bg-green-500"
                    : "bg-muted-foreground/30"
                }`}
                title={step.label}
              />
              {i < STEPS.length - 1 && (
                <div className={`h-px w-2 ${isComplete && i < currentStep ? "bg-green-500" : "bg-muted-foreground/20"}`} />
              )}
            </div>
          );
        })}
      </div>
    );
  }

  // Full version with labels
  return (
    <div className="flex items-center gap-1">
      {STEPS.map((step, i) => {
        const isComplete = i <= currentStep;
        const isCurrent = i === currentStep;
        return (
          <div key={step.key} className="flex items-center">
            <div className="flex flex-col items-center">
              <div
                className={`h-3 w-3 rounded-full border-2 ${
                  isComplete
                    ? isCurrent && step.key !== "live"
                      ? "border-amber-500 bg-amber-500"
                      : "border-green-500 bg-green-500"
                    : "border-muted-foreground/30 bg-transparent"
                }`}
              />
              <span className={`text-[10px] mt-0.5 ${isComplete ? "text-foreground" : "text-muted-foreground"}`}>
                {step.label}
              </span>
            </div>
            {i < STEPS.length - 1 && (
              <div className={`h-px w-4 mt-[-10px] ${isComplete && i < currentStep ? "bg-green-500" : "bg-muted-foreground/20"}`} />
            )}
          </div>
        );
      })}
    </div>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Loader2, Check, Building2, Copy, ExternalLink, Brain, Rocket, CreditCard } from "lucide-react";
import { searchIndustries, getPopularIndustries, type IndustryCatalogEntry } from "@/data/industryCatalog";
import { LADDER_STEPS, formatPrice, type PlanSku } from "@/config/pricing";
import { toast } from "sonner";
import { Link } from "react-router-dom";

type Step = "info" | "creating" | "done";

interface QuickProvisionWizardProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  agencyId: string;
  prefillLead?: { name: string; industry?: string };
}

function StepIndicator({ current, total }: { current: number; total: number }) {
  return (
    <div className="flex items-center justify-center gap-1.5 pb-2">
      {Array.from({ length: total }).map((_, i) => (
        <div
          key={i}
          className={`h-1.5 rounded-full transition-all ${
            i === current
              ? "w-6 bg-primary"
              : i < current
                ? "w-1.5 bg-primary/40"
                : "w-1.5 bg-muted"
          }`}
        />
      ))}
    </div>
  );
}

export function QuickProvisionWizard({ open, onOpenChange, agencyId, prefillLead }: QuickProvisionWizardProps) {
  const { user } = useAuth();
  const queryClient = useQueryClient();

  const [step, setStep] = useState<Step>("info");
  const [businessName, setBusinessName] = useState("");
  const [businessPhone, setBusinessPhone] = useState("");
  const [ownerEmail, setOwnerEmail] = useState("");
  const [timezone, setTimezone] = useState("America/New_York");
  const [industryQuery, setIndustryQuery] = useState("");
  const [selectedIndustry, setSelectedIndustry] = useState<IndustryCatalogEntry | null>(null);
  const [createdTenantId, setCreatedTenantId] = useState<string | null>(null);
  const [selectedPlanSku, setSelectedPlanSku] = useState<PlanSku>("base-200");
  const [paymentLinkUrl, setPaymentLinkUrl] = useState<string | null>(null);
  const [linkLoading, setLinkLoading] = useState(false);
  const [linkCopied, setLinkCopied] = useState(false);

  const popularIndustries = getPopularIndustries(8);
  const searchResults = industryQuery.length >= 2 ? searchIndustries(industryQuery) : [];
  const displayIndustries = industryQuery.length >= 2 ? searchResults : popularIndustries;

  const stepIndex = step === "info" ? 0 : step === "creating" ? 1 : 2;

  // Pre-fill from lead data
  useEffect(() => {
    if (prefillLead && open) {
      setBusinessName(prefillLead.name);
      if (prefillLead.industry) {
        setIndustryQuery(prefillLead.industry);
        const match = searchIndustries(prefillLead.industry)[0];
        if (match) setSelectedIndustry(match);
      }
    }
  }, [prefillLead, open]);

  const resetWizard = () => {
    setStep("info");
    setBusinessName("");
    setBusinessPhone("");
    setOwnerEmail("");
    setTimezone("America/New_York");
    setIndustryQuery("");
    setSelectedIndustry(null);
    setCreatedTenantId(null);
    setSelectedPlanSku("base-200");
    setPaymentLinkUrl(null);
    setLinkLoading(false);
    setLinkCopied(false);
  };

  const handleClose = () => {
    onOpenChange(false);
    setTimeout(resetWizard, 300);
  };

  const handleCreate = async () => {
    if (!businessName.trim() || !user) return;

    // Basic email validation if provided
    if (ownerEmail.trim() && !ownerEmail.includes("@")) {
      toast.error("Please enter a valid email address");
      return;
    }

    setStep("creating");

    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData?.session?.access_token;

      const body: Record<string, unknown> = {
        name: businessName.trim(),
        business_mode: selectedIndustry?.businessMode || "service",
        timezone,
        agency_id: agencyId,
        industry: selectedIndustry?.slug || "general",
        enabled_modules: selectedIndustry?.enabledModules || ["ai_voice", "instant_text_back", "booking"],
        owner_email: ownerEmail.trim() || undefined,
        phone: businessPhone.trim() || undefined,
      };

      const response = await supabase.functions.invoke("create-tenant", {
        body,
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });

      if (response.error) {
        throw new Error(response.error.message || "Failed to create tenant");
      }

      const tenantId = response.data?.tenant_id;
      setCreatedTenantId(tenantId);

      // Invalidate agency queries
      queryClient.invalidateQueries({ queryKey: ["agency-tenants"] });
      queryClient.invalidateQueries({ queryKey: ["agency-metrics"] });

      toast.success(`${businessName.trim()} has been created`);
      setStep("done");
    } catch (err: any) {
      toast.error(err.message || "Failed to create client");
      setStep("info");
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Building2 className="h-5 w-5 text-primary" />
            Add New Client
          </DialogTitle>
          <DialogDescription>
            {step === "info" && "Set up a new business for your agency."}
            {step === "creating" && "Creating the account..."}
            {step === "done" && "Client account is ready!"}
          </DialogDescription>
        </DialogHeader>

        <StepIndicator current={stepIndex} total={3} />

        {step === "info" && (
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Business Name *</Label>
              <Input
                value={businessName}
                onChange={(e) => setBusinessName(e.target.value)}
                placeholder="e.g., Joe's Plumbing"
              />
            </div>

            <div className="space-y-2">
              <Label>Business Phone</Label>
              <Input
                type="tel"
                value={businessPhone}
                onChange={(e) => setBusinessPhone(e.target.value)}
                placeholder="(555) 123-4567"
              />
            </div>

            <div className="space-y-2">
              <Label>Industry</Label>
              <Input
                value={industryQuery}
                onChange={(e) => setIndustryQuery(e.target.value)}
                placeholder="Search industries..."
              />
              <div className="flex flex-wrap gap-1.5 max-h-32 overflow-y-auto">
                {displayIndustries.slice(0, 12).map((ind) => (
                  <button
                    key={ind.slug}
                    onClick={() => {
                      setSelectedIndustry(ind);
                      setIndustryQuery(ind.name);
                    }}
                    className={`inline-flex items-center rounded-full px-2.5 py-1 text-xs transition-colors ${
                      selectedIndustry?.slug === ind.slug
                        ? "bg-primary text-primary-foreground"
                        : "bg-muted hover:bg-muted/80"
                    }`}
                  >
                    {ind.name}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-2">
              <Label>Timezone</Label>
              <Select value={timezone} onValueChange={setTimezone}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="America/New_York">Eastern</SelectItem>
                  <SelectItem value="America/Chicago">Central</SelectItem>
                  <SelectItem value="America/Denver">Mountain</SelectItem>
                  <SelectItem value="America/Los_Angeles">Pacific</SelectItem>
                  <SelectItem value="America/Anchorage">Alaska</SelectItem>
                  <SelectItem value="Pacific/Honolulu">Hawaii</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Business Owner Email (optional)</Label>
              <Input
                type="email"
                value={ownerEmail}
                onChange={(e) => setOwnerEmail(e.target.value)}
                placeholder="owner@business.com"
              />
              <p className="text-xs text-muted-foreground">
                If provided, the business owner will be invited as the account owner. Otherwise, you'll manage it directly.
              </p>
            </div>

            <div className="flex justify-end gap-2 pt-2">
              <Button variant="outline" onClick={handleClose}>Cancel</Button>
              <Button onClick={handleCreate} disabled={!businessName.trim()}>
                Create Client
              </Button>
            </div>
          </div>
        )}

        {step === "creating" && (
          <div className="flex flex-col items-center py-12 gap-4">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
            <p className="text-sm text-muted-foreground">Setting up {businessName}...</p>
          </div>
        )}

        {step === "done" && (
          <div className="space-y-4 py-2">
            <div className="flex items-center gap-3">
              <div className="h-10 w-10 rounded-full bg-green-100 dark:bg-green-900/30 flex items-center justify-center shrink-0">
                <Check className="h-5 w-5 text-green-600" />
              </div>
              <div>
                <p className="text-sm font-medium">{businessName} is ready!</p>
                {ownerEmail && (
                  <p className="text-xs text-muted-foreground">Invitation sent to {ownerEmail}</p>
                )}
              </div>
            </div>

            {/* Onboarding Checklist */}
            {createdTenantId && (
              <div className="rounded-lg border p-3 space-y-2">
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Next Steps</p>
                <div className="space-y-1.5">
                  <Link
                    to={`/app/business-brain?tenant=${createdTenantId}`}
                    className="flex items-center gap-2 text-sm hover:text-primary transition-colors"
                  >
                    <Brain className="h-3.5 w-3.5 text-muted-foreground" />
                    <span>Configure Business Brain</span>
                  </Link>
                  <Link
                    to={`/app/go-live?tenant=${createdTenantId}`}
                    className="flex items-center gap-2 text-sm hover:text-primary transition-colors"
                  >
                    <Rocket className="h-3.5 w-3.5 text-muted-foreground" />
                    <span>Check AI Readiness</span>
                  </Link>
                </div>
              </div>
            )}

            {/* Plan Selection */}
            <div className="space-y-2">
              <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Select a Plan</p>
              <RadioGroup
                value={selectedPlanSku}
                onValueChange={(v) => setSelectedPlanSku(v as PlanSku)}
                className="space-y-1.5"
              >
                {LADDER_STEPS.filter((s) => !s.isEnterprise).map((step) => (
                  <div
                    key={step.sku}
                    className={`flex items-center justify-between p-2.5 rounded-lg border cursor-pointer text-sm ${
                      selectedPlanSku === step.sku
                        ? "border-primary bg-primary/5"
                        : "border-border hover:border-primary/50"
                    }`}
                    onClick={() => setSelectedPlanSku(step.sku)}
                  >
                    <div className="flex items-center gap-2">
                      <RadioGroupItem value={step.sku} id={`wiz-${step.sku}`} />
                      <Label htmlFor={`wiz-${step.sku}`} className="cursor-pointer text-sm">
                        {step.shortName}
                      </Label>
                    </div>
                    <span className="font-semibold text-sm">{formatPrice(step.price)}/mo</span>
                  </div>
                ))}
              </RadioGroup>
            </div>

            {/* Payment Link URL (shown after generation) */}
            {paymentLinkUrl && (
              <div className="rounded-lg bg-muted/50 p-3 space-y-2">
                <p className="text-xs font-medium">Payment Link</p>
                <div className="flex gap-2">
                  <Input value={paymentLinkUrl} readOnly className="text-xs h-8" />
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-8 shrink-0"
                    onClick={async () => {
                      await navigator.clipboard.writeText(paymentLinkUrl);
                      setLinkCopied(true);
                      toast.success("Link copied");
                      setTimeout(() => setLinkCopied(false), 2000);
                    }}
                  >
                    {linkCopied ? <Check className="h-3.5 w-3.5" /> : <Copy className="h-3.5 w-3.5" />}
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground">Share with client. Expires in 24h.</p>
              </div>
            )}

            {/* Action Buttons */}
            <div className="flex gap-2 pt-1">
              <Button
                variant="outline"
                size="sm"
                className="flex-1"
                disabled={linkLoading || !createdTenantId}
                onClick={async () => {
                  if (!createdTenantId) return;
                  setLinkLoading(true);
                  try {
                    const { data: sessionData } = await supabase.auth.getSession();
                    const token = sessionData?.session?.access_token;
                    const { data, error } = await supabase.functions.invoke("create-payment-link", {
                      body: { plan_sku: selectedPlanSku, tenant_id: createdTenantId },
                      headers: token ? { Authorization: `Bearer ${token}` } : undefined,
                    });
                    if (error) throw new Error(error.message);
                    if (!data?.checkout_url) throw new Error("No link returned");
                    setPaymentLinkUrl(data.checkout_url);
                    toast.success("Payment link generated");
                  } catch (err: any) {
                    toast.error(err.message || "Failed to generate link");
                  } finally {
                    setLinkLoading(false);
                  }
                }}
              >
                {linkLoading ? <Loader2 className="h-3.5 w-3.5 animate-spin mr-1.5" /> : <ExternalLink className="h-3.5 w-3.5 mr-1.5" />}
                Send Payment Link
              </Button>
              <Button
                size="sm"
                className="flex-1"
                disabled={!createdTenantId}
                onClick={async () => {
                  if (!createdTenantId) return;
                  try {
                    const { data: sessionData } = await supabase.auth.getSession();
                    const token = sessionData?.session?.access_token;
                    const { data, error } = await supabase.functions.invoke("create-checkout-session", {
                      body: { plan_sku: selectedPlanSku, tenant_id: createdTenantId },
                      headers: token ? { Authorization: `Bearer ${token}` } : undefined,
                    });
                    if (error) throw new Error(error.message);
                    if (!data?.checkout_url) throw new Error("No checkout URL");
                    window.location.href = data.checkout_url;
                  } catch (err: any) {
                    toast.error(err.message || "Failed to start checkout");
                  }
                }}
              >
                <CreditCard className="h-3.5 w-3.5 mr-1.5" />
                Pay Now
              </Button>
            </div>

            <div className="flex justify-end">
              <Button variant="ghost" size="sm" onClick={handleClose}>Done</Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Plus, Trash2, Save, Loader2, Star } from "lucide-react";
import { useServiceAgreements, ServiceAgreementWithCustomer } from "@/hooks/useServiceAgreements";
import { useCustomers } from "@/hooks/useCustomers";
import { Badge } from "@/components/ui/badge";

interface AgreementBuilderProps {
  agreement?: ServiceAgreementWithCustomer | null;
  onSave: () => void;
  onCancel: () => void;
}

const PLAN_TEMPLATES = [
  {
    name: "Basic Maintenance",
    type: "maintenance",
    price_cents: 9900,
    billing_frequency: "monthly",
    visits_per_year: 2,
    services: ["Annual inspection", "Filter replacement", "Basic tune-up"],
    discount_percent: 10,
    priority_service: false,
  },
  {
    name: "Priority Care",
    type: "priority",
    price_cents: 14900,
    billing_frequency: "monthly",
    visits_per_year: 4,
    services: ["Bi-annual inspection", "Filter replacement", "Full tune-up", "Priority scheduling", "15% parts discount"],
    discount_percent: 15,
    priority_service: true,
  },
  {
    name: "Premium Protection",
    type: "premium",
    price_cents: 24900,
    billing_frequency: "monthly",
    visits_per_year: 4,
    services: ["Quarterly inspection", "All filters included", "Full tune-up", "Same-day priority service", "20% parts discount", "No overtime charges"],
    discount_percent: 20,
    priority_service: true,
  },
];

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);
}

export function AgreementBuilder({ agreement, onSave, onCancel }: AgreementBuilderProps) {
  const { createAgreement, updateAgreement } = useServiceAgreements();
  const { customers } = useCustomers();
  const isEditing = !!agreement;

  // Form state
  const [customerId, setCustomerId] = useState(agreement?.customer_id || "");
  const [planName, setPlanName] = useState(agreement?.plan_name || "");
  const [planType, setPlanType] = useState(agreement?.plan_type || "maintenance");
  const [priceCents, setPriceCents] = useState(agreement?.price_cents || 9900);
  const [billingFrequency, setBillingFrequency] = useState(agreement?.billing_frequency || "monthly");
  const [startDate, setStartDate] = useState(
    agreement?.start_date || new Date().toISOString().split("T")[0]
  );
  const [autoRenew, setAutoRenew] = useState(agreement?.auto_renew ?? true);
  const [servicesIncluded, setServicesIncluded] = useState<string[]>(
    agreement?.services_included || []
  );
  const [visitsPerYear, setVisitsPerYear] = useState(agreement?.visits_per_year || 2);
  const [discountPercent, setDiscountPercent] = useState(agreement?.discount_percent || 0);
  const [priorityService, setPriorityService] = useState(agreement?.priority_service || false);
  const [customerNotes, setCustomerNotes] = useState(agreement?.customer_notes || "");
  const [internalNotes, setInternalNotes] = useState(agreement?.internal_notes || "");
  const [terms, setTerms] = useState(agreement?.terms || "");
  const [newService, setNewService] = useState("");

  const [isSaving, setIsSaving] = useState(false);

  const applyTemplate = (template: typeof PLAN_TEMPLATES[0]) => {
    setPlanName(template.name);
    setPlanType(template.type);
    setPriceCents(template.price_cents);
    setBillingFrequency(template.billing_frequency);
    setVisitsPerYear(template.visits_per_year);
    setServicesIncluded(template.services);
    setDiscountPercent(template.discount_percent);
    setPriorityService(template.priority_service);
  };

  const addService = () => {
    if (newService.trim()) {
      setServicesIncluded([...servicesIncluded, newService.trim()]);
      setNewService("");
    }
  };

  const removeService = (index: number) => {
    setServicesIncluded(servicesIncluded.filter((_, i) => i !== index));
  };

  const handleSave = async () => {
    if (!customerId || !planName) return;

    setIsSaving(true);
    try {
      if (isEditing && agreement) {
        await updateAgreement.mutateAsync({
          id: agreement.id,
          customer_id: customerId,
          plan_name: planName,
          plan_type: planType,
          price_cents: priceCents,
          billing_frequency: billingFrequency,
          start_date: startDate,
          auto_renew: autoRenew,
          services_included: servicesIncluded,
          visits_per_year: visitsPerYear,
          discount_percent: discountPercent,
          priority_service: priorityService,
          customer_notes: customerNotes || undefined,
          internal_notes: internalNotes || undefined,
          terms: terms || undefined,
        });
      } else {
        await createAgreement.mutateAsync({
          customer_id: customerId,
          plan_name: planName,
          plan_type: planType,
          price_cents: priceCents,
          billing_frequency: billingFrequency,
          start_date: startDate,
          auto_renew: autoRenew,
          services_included: servicesIncluded,
          visits_per_year: visitsPerYear,
          discount_percent: discountPercent,
          priority_service: priorityService,
          customer_notes: customerNotes || undefined,
          internal_notes: internalNotes || undefined,
          terms: terms || undefined,
        });
      }
      onSave();
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Quick Templates */}
      {!isEditing && (
        <div className="space-y-2">
          <Label>Quick Start Templates</Label>
          <div className="grid grid-cols-3 gap-2">
            {PLAN_TEMPLATES.map((template) => (
              <button
                key={template.name}
                type="button"
                onClick={() => applyTemplate(template)}
                className="relative p-3 border rounded-lg text-left hover:border-primary hover:bg-primary/5 transition-colors"
              >
                <div className="flex items-center gap-2">
                  <span className="font-medium text-sm">{template.name}</span>
                  {template.priority_service && (
                    <Star className="h-3 w-3 text-yellow-500 fill-yellow-500" />
                  )}
                </div>
                <p className="text-lg font-bold mt-1">
                  {formatCurrency(template.price_cents)}
                  <span className="text-xs font-normal text-muted-foreground">/mo</span>
                </p>
                <p className="text-xs text-muted-foreground mt-1">
                  {template.visits_per_year} visits/year
                </p>
              </button>
            ))}
          </div>
        </div>
      )}

      {/* Customer Selection */}
      <div className="space-y-2">
        <Label htmlFor="customer">Customer *</Label>
        <Select value={customerId} onValueChange={setCustomerId}>
          <SelectTrigger>
            <SelectValue placeholder="Select a customer" />
          </SelectTrigger>
          <SelectContent>
            {customers.map((customer) => (
              <SelectItem key={customer.id} value={customer.id}>
                {customer.full_name || customer.phone_e164 || "Unnamed Customer"}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Plan Details */}
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="planName">Plan Name *</Label>
          <Input
            id="planName"
            value={planName}
            onChange={(e) => setPlanName(e.target.value)}
            placeholder="e.g., Annual Maintenance Plan"
          />
        </div>
        <div className="space-y-2">
          <Label htmlFor="planType">Plan Type</Label>
          <Select value={planType} onValueChange={setPlanType}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="maintenance">Maintenance</SelectItem>
              <SelectItem value="priority">Priority</SelectItem>
              <SelectItem value="premium">Premium</SelectItem>
              <SelectItem value="custom">Custom</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Pricing */}
      <div className="grid grid-cols-3 gap-4">
        <div className="space-y-2">
          <Label htmlFor="price">Price</Label>
          <div className="relative">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
            <Input
              id="price"
              type="number"
              step="0.01"
              value={(priceCents / 100).toFixed(2)}
              onChange={(e) => setPriceCents(Math.round(parseFloat(e.target.value || "0") * 100))}
              className="pl-7"
            />
          </div>
        </div>
        <div className="space-y-2">
          <Label htmlFor="frequency">Billing Frequency</Label>
          <Select value={billingFrequency} onValueChange={setBillingFrequency}>
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="monthly">Monthly</SelectItem>
              <SelectItem value="quarterly">Quarterly</SelectItem>
              <SelectItem value="annually">Annually</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label htmlFor="startDate">Start Date</Label>
          <Input
            id="startDate"
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
          />
        </div>
      </div>

      {/* Services & Benefits */}
      <div className="grid grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label htmlFor="visits">Visits Per Year</Label>
          <Input
            id="visits"
            type="number"
            min="1"
            value={visitsPerYear}
            onChange={(e) => setVisitsPerYear(parseInt(e.target.value) || 1)}
          />
        </div>
        <div className="space-y-2">
          <Label htmlFor="discount">Service Discount %</Label>
          <Input
            id="discount"
            type="number"
            min="0"
            max="100"
            value={discountPercent}
            onChange={(e) => setDiscountPercent(parseInt(e.target.value) || 0)}
          />
        </div>
      </div>

      {/* Toggles */}
      <div className="flex items-center gap-6">
        <div className="flex items-center gap-2">
          <Switch id="autoRenew" checked={autoRenew} onCheckedChange={setAutoRenew} />
          <Label htmlFor="autoRenew">Auto-renew</Label>
        </div>
        <div className="flex items-center gap-2">
          <Switch id="priority" checked={priorityService} onCheckedChange={setPriorityService} />
          <Label htmlFor="priority">Priority scheduling</Label>
        </div>
      </div>

      {/* Services Included */}
      <div className="space-y-2">
        <Label>Services Included</Label>
        <div className="flex gap-2">
          <Input
            value={newService}
            onChange={(e) => setNewService(e.target.value)}
            placeholder="Add a service..."
            onKeyDown={(e) => e.key === "Enter" && (e.preventDefault(), addService())}
          />
          <Button type="button" variant="outline" onClick={addService}>
            <Plus className="h-4 w-4" />
          </Button>
        </div>
        {servicesIncluded.length > 0 && (
          <div className="flex flex-wrap gap-2 mt-2">
            {servicesIncluded.map((service, index) => (
              <Badge key={index} variant="secondary" className="flex items-center gap-1">
                {service}
                <button
                  type="button"
                  onClick={() => removeService(index)}
                  className="ml-1 hover:text-destructive"
                >
                  <Trash2 className="h-3 w-3" />
                </button>
              </Badge>
            ))}
          </div>
        )}
      </div>

      {/* Notes */}
      <div className="space-y-2">
        <Label htmlFor="customerNotes">Customer Notes (visible to customer)</Label>
        <Textarea
          id="customerNotes"
          value={customerNotes}
          onChange={(e) => setCustomerNotes(e.target.value)}
          placeholder="Any notes for the customer..."
          rows={2}
        />
      </div>

      <div className="space-y-2">
        <Label htmlFor="internalNotes">Internal Notes (staff only)</Label>
        <Textarea
          id="internalNotes"
          value={internalNotes}
          onChange={(e) => setInternalNotes(e.target.value)}
          placeholder="Internal notes..."
          rows={2}
        />
      </div>

      {/* Actions */}
      <div className="flex justify-end gap-2 pt-4 border-t">
        <Button variant="outline" onClick={onCancel}>
          Cancel
        </Button>
        <Button onClick={handleSave} disabled={isSaving || !customerId || !planName}>
          {isSaving ? (
            <>
              <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              Saving...
            </>
          ) : (
            <>
              <Save className="h-4 w-4 mr-2" />
              {isEditing ? "Update Agreement" : "Create Agreement"}
            </>
          )}
        </Button>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { Bot, PhoneCall, Loader2 } from "lucide-react";

type AIBehaviorMode = "full_service" | "callback_only";

export default function AIBehaviorModeSelector() {
  const { tenant, assistantSettings, refreshTenant } = useAuth();
  const { toast } = useToast();

  const [behaviorMode, setBehaviorMode] = useState<AIBehaviorMode>(
    ((assistantSettings as any)?.ai_behavior_mode as AIBehaviorMode) || "full_service"
  );
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (assistantSettings) {
      setBehaviorMode(
        ((assistantSettings as any).ai_behavior_mode as AIBehaviorMode) || "full_service"
      );
    }
  }, [assistantSettings]);

  const handleChange = async (value: string) => {
    const newMode = value as AIBehaviorMode;
    setBehaviorMode(newMode);

    if (!tenant?.id) return;
    setSaving(true);

    try {
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          ai_behavior_mode: newMode,
          updated_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      await refreshTenant();

      toast({
        title: newMode === "full_service"
          ? "Full service mode enabled"
          : "Capture & callback mode enabled",
      });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Failed to save",
        description: error.message,
      });
    } finally {
      setSaving(false);
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg flex items-center gap-2">
          <Bot className="h-5 w-5" />
          What AI Does On Calls
          {saving && <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />}
        </CardTitle>
        <CardDescription>
          Control whether your AI books appointments/dispatches or just captures info for callbacks
        </CardDescription>
      </CardHeader>
      <CardContent>
        <RadioGroup value={behaviorMode} onValueChange={handleChange}>
          <div className="space-y-3">
            {/* Full Service */}
            <Label
              htmlFor="behavior-full"
              className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                behaviorMode === "full_service"
                  ? "border-primary bg-primary/5"
                  : "border-border hover:border-primary/50"
              }`}
            >
              <RadioGroupItem value="full_service" id="behavior-full" className="mt-0.5" />
              <div className="flex-1">
                <span className="font-medium">Full Service</span>
                <p className="text-sm text-muted-foreground mt-1">
                  AI books appointments, dispatches jobs, takes orders — handles everything
                </p>
              </div>
            </Label>

            {/* Capture & Callback */}
            <Label
              htmlFor="behavior-callback"
              className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                behaviorMode === "callback_only"
                  ? "border-primary bg-primary/5"
                  : "border-border hover:border-primary/50"
              }`}
            >
              <RadioGroupItem value="callback_only" id="behavior-callback" className="mt-0.5" />
              <div className="flex-1">
                <span className="font-medium">Capture & Callback</span>
                <p className="text-sm text-muted-foreground mt-1">
                  AI answers questions and captures caller info, but you handle bookings and dispatch yourself
                </p>
              </div>
            </Label>
          </div>
        </RadioGroup>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { BellRing } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

const DEFAULT_24H =
  "Hi {{customer_name}}, this is a reminder that your {{service_name}} appointment is tomorrow at {{time}}. Reply CONFIRM to confirm or call us to reschedule.";
const DEFAULT_1H =
  "Hi {{customer_name}}, your {{service_name}} appointment is in about 1 hour at {{time}}. We look forward to seeing you!";

export default function AppointmentReminderSettings() {
  const { tenant, assistantSettings } = useAuth();
  const { toast } = useToast();

  const [enabled, setEnabled] = useState(false);
  const [template24h, setTemplate24h] = useState(DEFAULT_24H);
  const [template1h, setTemplate1h] = useState(DEFAULT_1H);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (assistantSettings?.settings_json) {
      const json = assistantSettings.settings_json as Record<string, any>;
      setEnabled(json.reminders_enabled ?? false);
      setTemplate24h(json.reminder_24h_template || DEFAULT_24H);
      setTemplate1h(json.reminder_1h_template || DEFAULT_1H);
    }
  }, [assistantSettings]);

  const handleSave = async () => {
    if (!tenant?.id) return;
    setSaving(true);
    try {
      const existing = (assistantSettings?.settings_json as Record<string, any>) || {};
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          settings_json: {
            ...existing,
            reminders_enabled: enabled,
            reminder_24h_template: template24h,
            reminder_1h_template: template1h,
          },
        })
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      toast({ title: "Reminder settings saved!" });
    } catch (error: any) {
      toast({ variant: "destructive", title: "Failed to save", description: error.message });
    } finally {
      setSaving(false);
    }
  };

  // Auto-save on toggle change
  useEffect(() => {
    if (tenant?.id && assistantSettings) {
      const timeoutId = setTimeout(handleSave, 500);
      return () => clearTimeout(timeoutId);
    }
  }, [enabled]);

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg flex items-center gap-2">
          <BellRing className="h-5 w-5" />
          Appointment Reminders
        </CardTitle>
        <CardDescription>
          Automatically send SMS reminders to reduce no-shows
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <p className="font-medium text-sm">Enable Reminders</p>
            <p className="text-xs text-muted-foreground">
              Send automatic SMS reminders 24h and 1h before appointments
            </p>
          </div>
          <Switch checked={enabled} onCheckedChange={setEnabled} />
        </div>

        {enabled && (
          <div className="space-y-4 pt-2">
            <div className="space-y-2">
              <Label className="text-sm">24-Hour Reminder Template</Label>
              <Textarea
                value={template24h}
                onChange={(e) => setTemplate24h(e.target.value)}
                onBlur={handleSave}
                rows={3}
                className="text-sm"
              />
              <p className="text-xs text-muted-foreground">
                Variables: {"{{customer_name}}"}, {"{{service_name}}"}, {"{{time}}"}
              </p>
            </div>

            <div className="space-y-2">
              <Label className="text-sm">1-Hour Reminder Template</Label>
              <Textarea
                value={template1h}
                onChange={(e) => setTemplate1h(e.target.value)}
                onBlur={handleSave}
                rows={3}
                className="text-sm"
              />
              <p className="text-xs text-muted-foreground">
                Variables: {"{{customer_name}}"}, {"{{service_name}}"}, {"{{time}}"}
              </p>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Badge } from "@/components/ui/badge";
import { CalendarCheck, Clock, Bell, AlertCircle } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface BookingBehaviorSettingsProps {
  compact?: boolean;
  onSave?: () => void;
}

export default function BookingBehaviorSettings({ compact, onSave }: BookingBehaviorSettingsProps) {
  const { tenant, assistantSettings } = useAuth();
  const { toast } = useToast();
  
  const [bookingMode, setBookingMode] = useState<'auto_book' | 'pending_approval'>('auto_book');
  const [notifyEmail, setNotifyEmail] = useState(true);
  const [notifySms, setNotifySms] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (assistantSettings) {
      // Normalize backend values to UI values
      const rawMode = assistantSettings.ai_booking_mode;
      const normalizedMode: 'auto_book' | 'pending_approval' = 
        rawMode === 'pending_approval' || rawMode === 'pending' ? 'pending_approval' : 'auto_book';
      setBookingMode(normalizedMode);
      setNotifyEmail(assistantSettings.pending_booking_notify_email ?? true);
      setNotifySms(assistantSettings.pending_booking_notify_sms ?? true);
    }
  }, [assistantSettings]);

  const handleSave = async () => {
    if (!tenant?.id) return;
    
    setSaving(true);
    try {
      const { error } = await supabase
        .from('assistant_settings')
        .update({
          ai_booking_mode: bookingMode,
          pending_booking_notify_email: notifyEmail,
          pending_booking_notify_sms: notifySms,
        })
        .eq('tenant_id', tenant.id);

      if (error) throw error;

      toast({ title: "Booking settings saved!" });
      onSave?.();
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Failed to save",
        description: error.message,
      });
    } finally {
      setSaving(false);
    }
  };

  // Auto-save on change
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      if (tenant?.id && assistantSettings) {
        handleSave();
      }
    }, 500);
    return () => clearTimeout(timeoutId);
  }, [bookingMode, notifyEmail, notifySms]);

  if (compact) {
    return (
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <CalendarCheck className="h-4 w-4 text-muted-foreground" />
            <span className="text-sm font-medium">AI Booking Mode</span>
          </div>
          <Badge variant={bookingMode === 'auto_book' ? 'default' : 'secondary'}>
            {bookingMode === 'auto_book' ? 'Auto-Book' : 'Pending Approval'}
          </Badge>
        </div>
      </div>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg flex items-center gap-2">
          <CalendarCheck className="h-5 w-5" />
          Booking Behavior
        </CardTitle>
        <CardDescription>
          Control how your AI handles appointment bookings
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Booking Mode Selection */}
        <div className="space-y-4">
          <Label className="text-base font-medium">When AI schedules an appointment:</Label>
          
          <RadioGroup 
            value={bookingMode} 
            onValueChange={(value) => setBookingMode(value as 'auto_book' | 'pending_approval')}
            className="space-y-3"
          >
            <label className={`flex items-start gap-4 p-4 rounded-lg border cursor-pointer transition-all ${
              bookingMode === 'auto_book' 
                ? 'border-primary bg-primary/5' 
                : 'hover:bg-muted/50'
            }`}>
              <RadioGroupItem value="auto_book" className="mt-1" />
              <div className="flex-1">
                <div className="flex items-center gap-2">
                  <span className="font-medium">Auto-Book Appointments</span>
                  <Badge variant="default" className="text-xs">Recommended</Badge>
                </div>
                <p className="text-sm text-muted-foreground mt-1">
                  AI instantly confirms appointments based on your availability. 
                  Customers receive immediate confirmation.
                </p>
              </div>
            </label>

            <label className={`flex items-start gap-4 p-4 rounded-lg border cursor-pointer transition-all ${
              bookingMode === 'pending_approval' 
                ? 'border-primary bg-primary/5' 
                : 'hover:bg-muted/50'
            }`}>
              <RadioGroupItem value="pending_approval" className="mt-1" />
              <div className="flex-1">
                <div className="flex items-center gap-2">
                  <span className="font-medium">Require Admin Approval</span>
                  <Badge variant="secondary" className="text-xs">Manual Review</Badge>
                </div>
                <p className="text-sm text-muted-foreground mt-1">
                  AI collects appointment requests, but you must confirm each one manually 
                  before it's official.
                </p>
              </div>
            </label>
          </RadioGroup>
        </div>

        {/* Pending Approval Warning */}
        {bookingMode === 'pending_approval' && (
          <div className="flex items-start gap-3 p-4 rounded-lg bg-warning/10 border border-warning/30">
            <AlertCircle className="h-5 w-5 text-warning flex-shrink-0 mt-0.5" />
            <div className="text-sm">
              <p className="font-medium text-warning-foreground">
                Important: Manual confirmation required
              </p>
              <p className="text-muted-foreground mt-1">
                Pending appointments will appear in your Bookings page with a "Pending" status. 
                You must confirm each appointment for the customer to receive their confirmation.
              </p>
            </div>
          </div>
        )}

        {/* Notification Preferences */}
        {bookingMode === 'pending_approval' && (
          <div className="space-y-4 pt-4 border-t">
            <div className="flex items-center gap-2">
              <Bell className="h-4 w-4 text-muted-foreground" />
              <Label className="text-base font-medium">Notify me when pending bookings arrive</Label>
            </div>
            
            <div className="space-y-3 ml-6">
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium text-sm">Email Notifications</p>
                  <p className="text-xs text-muted-foreground">Get an email when AI schedules a pending booking</p>
                </div>
                <Switch 
                  checked={notifyEmail} 
                  onCheckedChange={setNotifyEmail}
                />
              </div>
              
              <div className="flex items-center justify-between">
                <div>
                  <p className="font-medium text-sm">SMS Notifications</p>
                  <p className="text-xs text-muted-foreground">Get a text when AI schedules a pending booking</p>
                </div>
                <Switch 
                  checked={notifySms} 
                  onCheckedChange={setNotifySms}
                />
              </div>
            </div>
          </div>
        )}

        {/* What AI tells customers */}
        <div className="p-4 rounded-lg bg-muted/50 space-y-2">
          <p className="text-sm font-medium">What AI tells customers:</p>
          {bookingMode === 'auto_book' ? (
            <p className="text-sm text-muted-foreground italic">
              "Great! I've booked your appointment for [date/time]. You'll receive a confirmation shortly."
            </p>
          ) : (
            <p className="text-sm text-muted-foreground italic">
              "I've submitted your appointment request for [date/time]. Someone from our team will confirm your booking shortly."
            </p>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { 
  Calendar, 
  RefreshCw, 
  CheckCircle2, 
  AlertCircle,
  Clock,
  CalendarDays,
  Plus,
  Trash2
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";

const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

interface AvailabilitySlot {
  id?: string;
  day_of_week: number;
  start_time: string;
  end_time: string;
  is_available: boolean;
}

interface CalendarSyncSettingsProps {
  onSyncComplete?: () => void;
}

export default function CalendarSyncSettings({ onSyncComplete }: CalendarSyncSettingsProps) {
  const { tenant, assistantSettings } = useAuth();
  const { toast } = useToast();
  
  const [provider, setProvider] = useState<string>('closeloop');
  const [slots, setSlots] = useState<AvailabilitySlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    loadSettings();
  }, [tenant?.id]);

  const loadSettings = async () => {
    if (!tenant?.id) return;
    setLoading(true);
    
    try {
      // Load provider from assistant settings
      if (assistantSettings) {
        setProvider(assistantSettings.calendar_provider || 'closeloop');
      }

      // Load availability slots
      const { data: slotsData, error } = await supabase
        .from('availability_slots')
        .select('*')
        .eq('tenant_id', tenant.id)
        .order('day_of_week')
        .order('start_time');

      if (error) throw error;

      if (slotsData && slotsData.length > 0) {
        setSlots(slotsData);
      } else {
        // Create default slots (Mon-Fri 9-5)
        const defaultSlots: AvailabilitySlot[] = [];
        for (let day = 1; day <= 5; day++) {
          defaultSlots.push({
            day_of_week: day,
            start_time: '09:00',
            end_time: '17:00',
            is_available: true,
          });
        }
        setSlots(defaultSlots);
      }
    } catch (error: any) {
      console.error('Error loading availability:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id) return;
    
    setSaving(true);
    try {
      // Delete existing slots
      await supabase
        .from('availability_slots')
        .delete()
        .eq('tenant_id', tenant.id);

      // Insert new slots
      const slotsToInsert = slots.map(slot => ({
        tenant_id: tenant.id,
        day_of_week: slot.day_of_week,
        start_time: slot.start_time,
        end_time: slot.end_time,
        is_available: slot.is_available,
      }));

      if (slotsToInsert.length > 0) {
        const { error } = await supabase
          .from('availability_slots')
          .insert(slotsToInsert);

        if (error) throw error;
      }

      toast({ title: "Availability saved!" });
      onSyncComplete?.();
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Failed to save",
        description: error.message,
      });
    } finally {
      setSaving(false);
    }
  };

  const toggleDay = (dayIndex: number) => {
    const existingSlot = slots.find(s => s.day_of_week === dayIndex);
    if (existingSlot) {
      setSlots(slots.map(s => 
        s.day_of_week === dayIndex 
          ? { ...s, is_available: !s.is_available }
          : s
      ));
    } else {
      setSlots([...slots, {
        day_of_week: dayIndex,
        start_time: '09:00',
        end_time: '17:00',
        is_available: true,
      }]);
    }
  };

  const updateSlotTime = (dayIndex: number, field: 'start_time' | 'end_time', value: string) => {
    setSlots(slots.map(s => 
      s.day_of_week === dayIndex 
        ? { ...s, [field]: value }
        : s
    ));
  };

  const getSlotForDay = (dayIndex: number): AvailabilitySlot | undefined => {
    return slots.find(s => s.day_of_week === dayIndex);
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6 text-center text-muted-foreground">
          Loading availability...
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg flex items-center gap-2">
          <CalendarDays className="h-5 w-5" />
          Your Availability
        </CardTitle>
        <CardDescription>
          Set when you're available for appointments. AI will only book during these times.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Weekly Schedule */}
        <div className="space-y-3">
          {dayNames.map((dayName, index) => {
            const slot = getSlotForDay(index);
            const isAvailable = slot?.is_available ?? false;

            return (
              <div 
                key={index}
                className={`flex items-center justify-between p-3 rounded-lg border transition-all ${
                  isAvailable ? 'bg-primary/5 border-primary/20' : 'bg-muted/30'
                }`}
              >
                <div className="flex items-center gap-3">
                  <Switch
                    checked={isAvailable}
                    onCheckedChange={() => toggleDay(index)}
                  />
                  <span className={`font-medium ${!isAvailable ? 'text-muted-foreground' : ''}`}>
                    {dayName}
                  </span>
                </div>

                {isAvailable && slot && (
                  <div className="flex items-center gap-2">
                    <Input
                      type="time"
                      value={slot.start_time}
                      onChange={(e) => updateSlotTime(index, 'start_time', e.target.value)}
                      className="w-28 h-8 text-sm"
                    />
                    <span className="text-muted-foreground text-sm">to</span>
                    <Input
                      type="time"
                      value={slot.end_time}
                      onChange={(e) => updateSlotTime(index, 'end_time', e.target.value)}
                      className="w-28 h-8 text-sm"
                    />
                  </div>
                )}

                {!isAvailable && (
                  <Badge variant="secondary" className="text-xs">Closed</Badge>
                )}
              </div>
            );
          })}
        </div>

        {/* Provider Info */}
        {provider === 'google' && (
          <div className="flex items-start gap-3 p-4 rounded-lg bg-muted/50">
            <CheckCircle2 className="h-5 w-5 text-success flex-shrink-0 mt-0.5" />
            <div className="text-sm">
              <p className="font-medium">Synced with Google Calendar</p>
              <p className="text-muted-foreground mt-1">
                Your busy times from Google Calendar will be automatically blocked.
              </p>
            </div>
          </div>
        )}

        {/* How AI uses this */}
        <div className="p-4 rounded-lg bg-muted/50 space-y-2 border-t pt-6">
          <p className="text-sm font-medium">AI booking behavior:</p>
          <ul className="text-sm text-muted-foreground space-y-1 list-disc list-inside">
            <li>AI only offers times during your available hours</li>
            <li>AI respects buffer time between appointments</li>
            <li>AI checks for conflicts with existing bookings</li>
            <li>AI books directly into CloseLoop's booking system</li>
          </ul>
        </div>

        {/* Save Button */}
        <div className="flex justify-end pt-4">
          <Button onClick={handleSave} disabled={saving}>
            {saving ? 'Saving...' : 'Save Availability'}
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { RefreshCw, Phone, Clock, Shield, AlertTriangle } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { format } from "date-fns";

interface CallContext {
  id: string;
  started_at: string;
  caller_phone: string | null;
  twilio_call_sid: string | null;
  context_json: Record<string, unknown> | null;
}

interface CallContextDebuggerProps {
  tenantId: string;
}

export function CallContextDebugger({ tenantId }: CallContextDebuggerProps) {
  const [lastCall, setLastCall] = useState<CallContext | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchLastCall = async () => {
    setIsLoading(true);
    setError(null);
    
    try {
      const { data, error: fetchError } = await supabase
        .from("ai_call_sessions")
        .select("id, started_at, caller_phone, twilio_call_sid, context_json")
        .eq("tenant_id", tenantId)
        .eq("call_direction", "inbound")
        .order("started_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (fetchError) throw fetchError;
      setLastCall(data as CallContext | null);
    } catch (err) {
      console.error("Error fetching call context:", err);
      setError("Failed to load call context");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchLastCall();
  }, [tenantId]);

  const context = lastCall?.context_json;
  const isHipaaRedacted = context?.hipaa_mode === true && context?.caller_phone === "[REDACTED]";

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Phone className="h-5 w-5" />
            Last Call Context
          </CardTitle>
        </CardHeader>
        <CardContent>
          <Skeleton className="h-32 w-full" />
        </CardContent>
      </Card>
    );
  }

  if (error) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Phone className="h-5 w-5" />
            Last Call Context
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-2 text-destructive">
            <AlertTriangle className="h-4 w-4" />
            <span>{error}</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!lastCall) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Phone className="h-5 w-5" />
            Last Call Context
          </CardTitle>
          <CardDescription>Debug the dynamic variables sent to ElevenLabs</CardDescription>
        </CardHeader>
        <CardContent>
          <p className="text-muted-foreground text-sm">No inbound calls recorded yet.</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <Phone className="h-5 w-5" />
              Last Call Context
            </CardTitle>
            <CardDescription>
              Debug the dynamic variables sent to ElevenLabs
            </CardDescription>
          </div>
          <Button variant="outline" size="sm" onClick={fetchLastCall}>
            <RefreshCw className="h-4 w-4 mr-2" />
            Refresh
          </Button>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Call metadata */}
        <div className="flex flex-wrap gap-2 items-center text-sm">
          <Badge variant="outline" className="flex items-center gap-1">
            <Clock className="h-3 w-3" />
            {format(new Date(lastCall.started_at), "MMM d, h:mm a")}
          </Badge>
          {lastCall.caller_phone && (
            <Badge variant="secondary">
              From: {lastCall.caller_phone}
            </Badge>
          )}
          {isHipaaRedacted && (
            <Badge variant="destructive" className="flex items-center gap-1">
              <Shield className="h-3 w-3" />
              HIPAA Redacted
            </Badge>
          )}
        </div>

        {/* Context variables */}
        {context ? (
          <div className="space-y-3">
            {/* Core variables */}
            <div className="grid grid-cols-2 gap-2 text-sm">
              <div className="space-y-1">
                <span className="text-muted-foreground">Business Name</span>
                <p className="font-medium">{String(context.business_name || "—")}</p>
              </div>
              <div className="space-y-1">
                <span className="text-muted-foreground">Business Mode</span>
                <p className="font-medium capitalize">{String(context.business_mode || "—")}</p>
              </div>
              <div className="space-y-1">
                <span className="text-muted-foreground">Hours Today</span>
                <p className="font-medium">{String(context.hours_today || "—")}</p>
              </div>
              <div className="space-y-1">
                <span className="text-muted-foreground">HIPAA Mode</span>
                <p className="font-medium">{context.hipaa_mode ? "Yes" : "No"}</p>
              </div>
            </div>

            {/* Enabled modules */}
            {Array.isArray(context.enabled_modules) && context.enabled_modules.length > 0 && (
              <div className="space-y-1">
                <span className="text-muted-foreground text-sm">Enabled Modules</span>
                <div className="flex flex-wrap gap-1">
                  {(context.enabled_modules as string[]).map((mod) => (
                    <Badge key={mod} variant="outline" className="text-xs">
                      {mod.replace(/_/g, " ")}
                    </Badge>
                  ))}
                </div>
              </div>
            )}

            {/* Summaries */}
            {context.service_summary && (
              <div className="space-y-1">
                <span className="text-muted-foreground text-sm">Service Summary</span>
                <p className="text-sm bg-muted p-2 rounded text-muted-foreground">
                  {String(context.service_summary)}
                </p>
              </div>
            )}

            {context.menu_summary && (
              <div className="space-y-1">
                <span className="text-muted-foreground text-sm">Menu Summary</span>
                <p className="text-sm bg-muted p-2 rounded text-muted-foreground">
                  {String(context.menu_summary)}
                </p>
              </div>
            )}

            {context.policies_summary && (
              <div className="space-y-1">
                <span className="text-muted-foreground text-sm">Policies Summary</span>
                <p className="text-sm bg-muted p-2 rounded text-muted-foreground">
                  {String(context.policies_summary)}
                </p>
              </div>
            )}

            {context.booking_link && (
              <div className="space-y-1">
                <span className="text-muted-foreground text-sm">Booking Link</span>
                <p className="text-sm font-mono bg-muted p-2 rounded">
                  {String(context.booking_link)}
                </p>
              </div>
            )}

            {/* Raw JSON (collapsible) */}
            <details className="text-sm">
              <summary className="cursor-pointer text-muted-foreground hover:text-foreground">
                View Raw JSON
              </summary>
              <pre className="mt-2 p-3 bg-muted rounded text-xs overflow-auto max-h-64">
                {JSON.stringify(context, null, 2)}
              </pre>
            </details>
          </div>
        ) : (
          <p className="text-muted-foreground text-sm">
            No context data stored for this call.
          </p>
        )}
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import type { BusinessFAQ } from "@/types/database";
import { Plus, Trash2, Save, Loader2 } from "lucide-react";

export default function LiveFAQList() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  
  const [faqs, setFaqs] = useState<BusinessFAQ[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [newQuestion, setNewQuestion] = useState('');
  const [newAnswer, setNewAnswer] = useState('');

  useEffect(() => {
    if (tenant?.id) {
      fetchFAQs();
    }
  }, [tenant?.id]);

  const fetchFAQs = async () => {
    if (!tenant?.id) return;

    const { data, error } = await supabase
      .from('business_faqs')
      .select('*')
      .eq('tenant_id', tenant.id)
      .order('priority_weight', { ascending: false });

    if (error) {
      console.error('Failed to fetch FAQs:', error);
    } else {
      setFaqs(data || []);
    }
    setLoading(false);
  };

  const addFAQ = async () => {
    if (!tenant?.id || !newQuestion.trim() || !newAnswer.trim()) return;

    setSaving(true);
    const { error } = await supabase
      .from('business_faqs')
      .insert({
        tenant_id: tenant.id,
        question: newQuestion,
        answer: newAnswer,
        priority_weight: faqs.length,
      });

    if (error) {
      toast({ variant: "destructive", title: "Something went wrong", description: "Try again?" });
    } else {
      toast({ title: "FAQ added", description: "Your AI can now answer this question." });
      setNewQuestion('');
      setNewAnswer('');
      fetchFAQs();
    }
    setSaving(false);
  };

  const updateFAQ = async (id: string, question: string, answer: string) => {
    const { error } = await supabase
      .from('business_faqs')
      .update({ question, answer })
      .eq('id', id);

    if (error) {
      toast({ variant: "destructive", title: "Something went wrong", description: "Try again?" });
    }
  };

  const deleteFAQ = async (id: string) => {
    const { error } = await supabase
      .from('business_faqs')
      .delete()
      .eq('id', id);

    if (error) {
      toast({ variant: "destructive", title: "Something went wrong", description: "Try again?" });
    } else {
      setFaqs(faqs.filter(f => f.id !== id));
    }
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6 text-center">
          <Loader2 className="h-6 w-6 animate-spin mx-auto" />
          <p className="text-muted-foreground mt-2">Loading FAQs...</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="text-lg">FAQs</CardTitle>
            <CardDescription>
              Answers the AI will use when customers ask common questions
            </CardDescription>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Add new FAQ */}
        <div className="p-4 border rounded-lg bg-secondary/30 space-y-3">
          <p className="font-medium text-sm">Add New FAQ</p>
          <Input
            placeholder="Question (e.g., What are your hours?)"
            value={newQuestion}
            onChange={(e) => setNewQuestion(e.target.value)}
          />
          <Textarea
            placeholder="Answer..."
            value={newAnswer}
            onChange={(e) => setNewAnswer(e.target.value)}
            rows={2}
          />
          <Button 
            size="sm" 
            onClick={addFAQ} 
            disabled={saving || !newQuestion.trim() || !newAnswer.trim()}
            className="gap-2"
          >
            <Plus className="h-4 w-4" />
            Add FAQ
          </Button>
        </div>

        {/* Existing FAQs */}
        {faqs.length === 0 ? (
          <p className="text-center text-muted-foreground py-4">
            No FAQs yet. Add the questions your customers ask most so your AI can answer them instantly.
          </p>
        ) : (
          <div className="space-y-3">
            {faqs.map((faq) => (
              <FAQItem
                key={faq.id}
                faq={faq}
                onUpdate={updateFAQ}
                onDelete={deleteFAQ}
              />
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function FAQItem({ 
  faq, 
  onUpdate, 
  onDelete 
}: { 
  faq: BusinessFAQ; 
  onUpdate: (id: string, question: string, answer: string) => void;
  onDelete: (id: string) => void;
}) {
  const [editing, setEditing] = useState(false);
  const [question, setQuestion] = useState(faq.question);
  const [answer, setAnswer] = useState(faq.answer);

  const handleSave = () => {
    onUpdate(faq.id, question, answer);
    setEditing(false);
  };

  if (editing) {
    return (
      <div className="p-4 rounded-lg border space-y-2">
        <Input
          value={question}
          onChange={(e) => setQuestion(e.target.value)}
        />
        <Textarea
          value={answer}
          onChange={(e) => setAnswer(e.target.value)}
          rows={2}
        />
        <div className="flex gap-2">
          <Button size="sm" onClick={handleSave} className="gap-1">
            <Save className="h-3 w-3" />
            Save
          </Button>
          <Button size="sm" variant="ghost" onClick={() => setEditing(false)}>
            Cancel
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 rounded-lg border">
      <div className="flex items-start justify-between">
        <div className="flex-1">
          <p 
            className="font-medium cursor-pointer hover:text-primary"
            onClick={() => setEditing(true)}
          >
            {faq.question}
          </p>
          <p className="text-sm text-muted-foreground mt-1">{faq.answer}</p>
        </div>
        <Button 
          variant="ghost" 
          size="icon" 
          className="text-destructive"
          onClick={() => onDelete(faq.id)}
        >
          <Trash2 className="h-4 w-4" />
        </Button>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Badge } from "@/components/ui/badge";
import { Phone, Calendar, AlertTriangle, Truck } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

type ServiceDefaultFlow = "schedule_first" | "urgency_check" | "dispatch_first";

interface ServiceCallFlowSettingsProps {
  compact?: boolean;
  onSave?: () => void;
}

export default function ServiceCallFlowSettings({ compact, onSave }: ServiceCallFlowSettingsProps) {
  const { tenant, assistantSettings } = useAuth();
  const { toast } = useToast();
  
  const [serviceFlow, setServiceFlow] = useState<ServiceDefaultFlow>("schedule_first");
  const [saving, setSaving] = useState(false);

  // Determine default based on industry
  const getIndustryDefault = (industry: string | undefined): ServiceDefaultFlow => {
    if (!industry) return "schedule_first";
    
    const urgencyCheckIndustries = [
      "hvac", "heating", "cooling", "plumbing", "plumber", "electrical", "electrician",
      "appliance_repair", "garage_door", "water_damage", "restoration"
    ];
    
    const dispatchFirstIndustries = [
      "locksmith", "towing", "roadside"
    ];
    
    const lowerIndustry = industry.toLowerCase();
    
    if (dispatchFirstIndustries.some(i => lowerIndustry.includes(i))) {
      return "dispatch_first";
    }
    if (urgencyCheckIndustries.some(i => lowerIndustry.includes(i))) {
      return "urgency_check";
    }
    return "schedule_first";
  };

  useEffect(() => {
    if (assistantSettings) {
      const savedFlow = (assistantSettings as any).service_default_flow;
      if (savedFlow) {
        setServiceFlow(savedFlow);
      } else {
        // Use industry default if not set
        setServiceFlow(getIndustryDefault(tenant?.industry));
      }
    }
  }, [assistantSettings, tenant?.industry]);

  const handleSave = async () => {
    if (!tenant?.id) return;
    
    setSaving(true);
    try {
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          service_default_flow: serviceFlow,
        })
        .eq("tenant_id", tenant.id);

      if (error) throw error;

      toast({ title: "Service call flow updated!" });
      onSave?.();
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Failed to save",
        description: error.message,
      });
    } finally {
      setSaving(false);
    }
  };

  // Auto-save on change
  useEffect(() => {
    const timeoutId = setTimeout(() => {
      if (tenant?.id && assistantSettings) {
        handleSave();
      }
    }, 500);
    return () => clearTimeout(timeoutId);
  }, [serviceFlow]);

  // Hide for non-service businesses OR when in callback-only mode
  const isCallbackOnly = (assistantSettings as any)?.ai_behavior_mode === "callback_only";
  if ((tenant?.business_mode !== "service" && tenant?.business_mode !== "general") || isCallbackOnly) {
    return null;
  }

  if (compact) {
    return (
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Phone className="h-4 w-4 text-muted-foreground" />
          <span className="text-sm font-medium">Service Call Flow</span>
        </div>
        <Badge variant={serviceFlow === "schedule_first" ? "default" : "secondary"}>
          {serviceFlow === "schedule_first" && "Schedule First"}
          {serviceFlow === "urgency_check" && "Ask Urgency"}
          {serviceFlow === "dispatch_first" && "Dispatch First"}
        </Badge>
      </div>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg flex items-center gap-2">
          <Phone className="h-5 w-5" />
          Service Call Behavior
        </CardTitle>
        <CardDescription>
          How should your AI handle incoming service requests?
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        <RadioGroup 
          value={serviceFlow} 
          onValueChange={(value) => setServiceFlow(value as ServiceDefaultFlow)}
          className="space-y-3"
        >
          {/* Schedule First */}
          <label className={`flex items-start gap-4 p-4 rounded-lg border cursor-pointer transition-all ${
            serviceFlow === "schedule_first" 
              ? "border-primary bg-primary/5" 
              : "hover:bg-muted/50"
          }`}>
            <RadioGroupItem value="schedule_first" className="mt-1" />
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <Calendar className="h-4 w-4" />
                <span className="font-medium">Schedule Appointments</span>
                <Badge variant="default" className="text-xs">Recommended for salons, detailing, cleaning</Badge>
              </div>
              <p className="text-sm text-muted-foreground mt-1">
                AI goes straight to scheduling. No urgency questions.
              </p>
              <p className="text-xs text-muted-foreground mt-2 italic">
                "When would you like to come in?"
              </p>
            </div>
          </label>

          {/* Urgency Check */}
          <label className={`flex items-start gap-4 p-4 rounded-lg border cursor-pointer transition-all ${
            serviceFlow === "urgency_check" 
              ? "border-primary bg-primary/5" 
              : "hover:bg-muted/50"
          }`}>
            <RadioGroupItem value="urgency_check" className="mt-1" />
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <AlertTriangle className="h-4 w-4" />
                <span className="font-medium">Ask if Urgent</span>
                <Badge variant="secondary" className="text-xs">Best for HVAC, plumbing, electrical</Badge>
              </div>
              <p className="text-sm text-muted-foreground mt-1">
                AI asks if it's urgent first, then schedules or expedites accordingly.
              </p>
              <p className="text-xs text-muted-foreground mt-2 italic">
                "Is this urgent, or can you schedule an appointment?"
              </p>
            </div>
          </label>

          {/* Dispatch First */}
          <label className={`flex items-start gap-4 p-4 rounded-lg border cursor-pointer transition-all ${
            serviceFlow === "dispatch_first" 
              ? "border-primary bg-primary/5" 
              : "hover:bg-muted/50"
          }`}>
            <RadioGroupItem value="dispatch_first" className="mt-1" />
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <Truck className="h-4 w-4" />
                <span className="font-medium">Immediate Dispatch</span>
                <Badge variant="outline" className="text-xs">For locksmiths, towing-style services</Badge>
              </div>
              <p className="text-sm text-muted-foreground mt-1">
                AI treats every call as immediate dispatch, like a tow truck service.
              </p>
              <p className="text-xs text-muted-foreground mt-2 italic">
                "What's your address? I'll send someone right away."
              </p>
            </div>
          </label>
        </RadioGroup>

        {/* Info box */}
        <div className="p-4 rounded-lg bg-muted/50 space-y-2">
          <p className="text-sm font-medium">How it works:</p>
          {serviceFlow === "schedule_first" && (
            <p className="text-sm text-muted-foreground">
              Customer: "I need my drain cleaned"<br />
              AI: "Great! When would work best for you?"
            </p>
          )}
          {serviceFlow === "urgency_check" && (
            <p className="text-sm text-muted-foreground">
              Customer: "I need my drain cleaned"<br />
              AI: "Is this urgent, or would you like to schedule an appointment?"<br />
              <span className="text-xs">(If urgent, AI checks same-day availability or offers expedited service)</span>
            </p>
          )}
          {serviceFlow === "dispatch_first" && (
            <p className="text-sm text-muted-foreground">
              Customer: "I'm locked out"<br />
              AI: "I can send someone right away. What's your address?"
            </p>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { useToast } from "@/hooks/use-toast";
import {
  Phone,
  PhoneForwarded,
  Voicemail,
  Clock,
  Radio,
  AlertTriangle,
  Loader2,
} from "lucide-react";
import type { VoiceMode } from "@/types/database";

type OffBehavior = "FORWARD_OWNER" | "VOICEMAIL" | "CALLBACK_ONLY";

export default function VoiceModeSelector() {
  const { tenant, assistantSettings, refreshTenant } = useAuth();
  const { toast } = useToast();

  const [voiceMode, setVoiceMode] = useState<VoiceMode>(
    (assistantSettings?.voice_mode as VoiceMode) || "always_on"
  );
  const [offBehavior, setOffBehavior] = useState<OffBehavior>(
    (assistantSettings?.off_behavior as OffBehavior) || "FORWARD_OWNER"
  );
  const [forwardNumber, setForwardNumber] = useState(
    assistantSettings?.owner_forward_number || ""
  );
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (assistantSettings) {
      setVoiceMode((assistantSettings.voice_mode as VoiceMode) || "always_on");
      setOffBehavior((assistantSettings.off_behavior as OffBehavior) || "FORWARD_OWNER");
      setForwardNumber(assistantSettings.owner_forward_number || "");
    }
  }, [assistantSettings]);

  const saveSettings = async (
    newMode: VoiceMode,
    newBehavior: OffBehavior,
    newNumber: string
  ) => {
    if (!tenant?.id) return;
    setSaving(true);

    try {
      const updates: Record<string, unknown> = {
        voice_mode: newMode,
        off_behavior: newBehavior,
        updated_at: new Date().toISOString(),
      };

      if (newBehavior === "FORWARD_OWNER" && newNumber.trim()) {
        const normalized = normalizePhone(newNumber);
        if (normalized) {
          updates.owner_forward_number = normalized;
        }
      }

      const { error } = await supabase
        .from("assistant_settings")
        .update(updates)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      await refreshTenant();

      toast({ title: "Call routing updated" });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Failed to save",
        description: error.message,
      });
    } finally {
      setSaving(false);
    }
  };

  const normalizePhone = (phone: string): string | null => {
    const digits = phone.replace(/\D/g, "");
    if (digits.length === 11 && digits.startsWith("1")) return `+${digits}`;
    if (digits.length === 10) return `+1${digits}`;
    if (phone.startsWith("+")) return phone;
    return null;
  };

  const handleVoiceModeChange = (value: string) => {
    const newMode = value as VoiceMode;
    setVoiceMode(newMode);
    saveSettings(newMode, offBehavior, forwardNumber);
  };

  const handleOffBehaviorChange = (value: string) => {
    const newBehavior = value as OffBehavior;
    setOffBehavior(newBehavior);
    saveSettings(voiceMode, newBehavior, forwardNumber);
  };

  const handleForwardNumberBlur = () => {
    if (forwardNumber.trim()) {
      saveSettings(voiceMode, offBehavior, forwardNumber);
    }
  };

  const showOffBehavior = voiceMode === "after_hours_only" || voiceMode === "overflow" || voiceMode === "busy_mode";

  return (
    <div className="space-y-6">
      {/* When AI Answers */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Radio className="h-5 w-5" />
            When AI Answers Calls
            {saving && <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />}
          </CardTitle>
          <CardDescription>
            Control when your AI assistant picks up incoming calls
          </CardDescription>
        </CardHeader>
        <CardContent>
          <RadioGroup value={voiceMode} onValueChange={handleVoiceModeChange}>
            <div className="space-y-3">
              {/* Always On */}
              <Label
                htmlFor="mode-always"
                className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                  voiceMode === "always_on"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:border-primary/50"
                }`}
              >
                <RadioGroupItem value="always_on" id="mode-always" className="mt-0.5" />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="font-medium">Always On</span>
                  </div>
                  <p className="text-sm text-muted-foreground mt-1">
                    AI answers every call, 24/7
                  </p>
                </div>
              </Label>

              {/* After Hours Only */}
              <Label
                htmlFor="mode-afterhours"
                className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                  voiceMode === "after_hours_only"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:border-primary/50"
                }`}
              >
                <RadioGroupItem value="after_hours_only" id="mode-afterhours" className="mt-0.5" />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <Clock className="h-4 w-4" />
                    <span className="font-medium">After Hours Only</span>
                  </div>
                  <p className="text-sm text-muted-foreground mt-1">
                    During business hours, calls go to your phone. After hours, AI answers.
                  </p>
                </div>
              </Label>

              {/* Overflow — Coming Soon */}
              <Label
                htmlFor="mode-overflow"
                className="flex items-start gap-3 p-4 rounded-lg border-2 border-border opacity-50 cursor-not-allowed"
              >
                <RadioGroupItem value="overflow" id="mode-overflow" disabled className="mt-0.5" />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="font-medium">Overflow</span>
                    <Badge variant="outline" className="text-xs">Coming Soon</Badge>
                  </div>
                  <p className="text-sm text-muted-foreground mt-1">
                    Ring your phone first. If you don't answer, AI picks up.
                  </p>
                </div>
              </Label>

              {/* Busy Mode — Coming Soon */}
              <Label
                htmlFor="mode-busy"
                className="flex items-start gap-3 p-4 rounded-lg border-2 border-border opacity-50 cursor-not-allowed"
              >
                <RadioGroupItem value="busy_mode" id="mode-busy" disabled className="mt-0.5" />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="font-medium">Busy Mode</span>
                    <Badge variant="outline" className="text-xs">Coming Soon</Badge>
                  </div>
                  <p className="text-sm text-muted-foreground mt-1">
                    AI answers only when you're already on another call.
                  </p>
                </div>
              </Label>
            </div>
          </RadioGroup>

          {voiceMode === "after_hours_only" && (
            <Alert className="mt-4">
              <AlertTriangle className="h-4 w-4" />
              <AlertDescription>
                Make sure your business hours are configured in Settings so the AI knows when to answer.
              </AlertDescription>
            </Alert>
          )}
        </CardContent>
      </Card>

      {/* Off Behavior — what happens when AI is NOT answering */}
      {showOffBehavior && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">When AI Isn't Answering</CardTitle>
            <CardDescription>
              What happens to calls during business hours (or when AI is paused)
            </CardDescription>
          </CardHeader>
          <CardContent>
            <RadioGroup value={offBehavior} onValueChange={handleOffBehaviorChange}>
              <div className="space-y-3">
                {/* Forward */}
                <Label
                  htmlFor="off-forward"
                  className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                    offBehavior === "FORWARD_OWNER"
                      ? "border-primary bg-primary/5"
                      : "border-border hover:border-primary/50"
                  }`}
                >
                  <RadioGroupItem value="FORWARD_OWNER" id="off-forward" className="mt-0.5" />
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <PhoneForwarded className="h-4 w-4" />
                      <span className="font-medium">Forward to my phone</span>
                    </div>
                    <p className="text-sm text-muted-foreground mt-1">
                      Calls ring your personal phone number
                    </p>
                  </div>
                </Label>

                {/* Voicemail */}
                <Label
                  htmlFor="off-voicemail"
                  className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                    offBehavior === "VOICEMAIL"
                      ? "border-primary bg-primary/5"
                      : "border-border hover:border-primary/50"
                  }`}
                >
                  <RadioGroupItem value="VOICEMAIL" id="off-voicemail" className="mt-0.5" />
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <Voicemail className="h-4 w-4" />
                      <span className="font-medium">Voicemail</span>
                    </div>
                    <p className="text-sm text-muted-foreground mt-1">
                      Play a message and record a voicemail
                    </p>
                  </div>
                </Label>

                {/* Callback */}
                <Label
                  htmlFor="off-callback"
                  className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                    offBehavior === "CALLBACK_ONLY"
                      ? "border-primary bg-primary/5"
                      : "border-border hover:border-primary/50"
                  }`}
                >
                  <RadioGroupItem value="CALLBACK_ONLY" id="off-callback" className="mt-0.5" />
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <Phone className="h-4 w-4" />
                      <span className="font-medium">Callback capture</span>
                    </div>
                    <p className="text-sm text-muted-foreground mt-1">
                      Acknowledge the call and promise a callback
                    </p>
                  </div>
                </Label>
              </div>
            </RadioGroup>

            {/* Forward Number Input */}
            {offBehavior === "FORWARD_OWNER" && (
              <div className="space-y-2 mt-4">
                <Label htmlFor="forward-phone">Your Phone Number</Label>
                <Input
                  id="forward-phone"
                  type="tel"
                  placeholder="+1 (555) 123-4567"
                  value={forwardNumber}
                  onChange={(e) => setForwardNumber(e.target.value)}
                  onBlur={handleForwardNumberBlur}
                  className="font-mono max-w-sm"
                />
                <p className="text-xs text-muted-foreground">
                  Enter your phone number. Calls will ring this number when AI isn't answering.
                </p>
              </div>
            )}
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Play, Square, Check, Loader2, Volume2 } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Skeleton } from "@/components/ui/skeleton";

interface VoiceOption {
  id: string;
  name: string;
  description: string | null;
}

interface VoiceSelectorProps {
  selected: string;
  onSelect: (voiceId: string) => void;
}

export default function VoiceSelector({ selected, onSelect }: VoiceSelectorProps) {
  const { toast } = useToast();
  const [voiceOptions, setVoiceOptions] = useState<VoiceOption[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [playingVoice, setPlayingVoice] = useState<string | null>(null);
  const [audioElement, setAudioElement] = useState<HTMLAudioElement | null>(null);

  // Fetch voice options from backend
  useEffect(() => {
    const fetchVoices = async () => {
      try {
        const { data, error } = await supabase.functions.invoke("get-voice-options");
        
        if (error) {
          console.error("Failed to fetch voice options:", error);
          toast({
            variant: "destructive",
            title: "Error",
            description: "Could not load voice options",
          });
          return;
        }

        if (data?.voices) {
          setVoiceOptions(data.voices);
          // Auto-select first voice if none selected
          if (!selected && data.voices.length > 0) {
            onSelect(data.voices[0].id);
          }
        }
      } catch (error) {
        console.error("Error fetching voices:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchVoices();
  }, []);

  const handlePreviewVoice = async (voice: VoiceOption) => {
    // Stop current audio if playing
    if (audioElement) {
      audioElement.pause();
      audioElement.currentTime = 0;
      setAudioElement(null);
      if (playingVoice === voice.id) {
        setPlayingVoice(null);
        return;
      }
    }

    setPlayingVoice(voice.id);
    
    try {
      const sampleText = `Hi there! I'm ${voice.name}, and I'll be your AI assistant. How can I help you today?`;
      
      // Use fetch for binary audio response (SDK doesn't handle binary well)
      const response = await fetch(
        `${import.meta.env.VITE_SUPABASE_URL}/functions/v1/elevenlabs-tts`,
        {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            apikey: import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY,
            Authorization: `Bearer ${import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY}`,
          },
          body: JSON.stringify({ 
            text: sampleText, 
            voiceId: voice.id // Send friendly ID, backend resolves to provider ID
          }),
        }
      );

      if (!response.ok) {
        throw new Error("Failed to generate voice preview");
      }

      const audioBlob = await response.blob();
      const audioUrl = URL.createObjectURL(audioBlob);
      const audio = new Audio(audioUrl);
      
      audio.onended = () => {
        setPlayingVoice(null);
        setAudioElement(null);
        URL.revokeObjectURL(audioUrl);
      };
      
      audio.onerror = () => {
        setPlayingVoice(null);
        setAudioElement(null);
        toast({
          variant: "destructive",
          title: "Playback Error",
          description: "Could not play voice preview",
        });
      };

      setAudioElement(audio);
      await audio.play();
    } catch (error: any) {
      console.error("Voice preview error:", error);
      setPlayingVoice(null);
      toast({
        variant: "destructive",
        title: "Preview Failed",
        description: "Could not load voice preview. Please try again.",
      });
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Pick a Voice</CardTitle>
          <CardDescription>Choose the voice for your AI assistant</CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          <Skeleton className="h-20 w-full" />
          <Skeleton className="h-20 w-full" />
        </CardContent>
      </Card>
    );
  }

  if (voiceOptions.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Pick a Voice</CardTitle>
          <CardDescription>Choose the voice for your AI assistant</CardDescription>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-muted-foreground">No voice options available.</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg">Pick a Voice</CardTitle>
        <CardDescription>Choose the voice for your AI assistant</CardDescription>
      </CardHeader>
      <CardContent className="space-y-3">
        {voiceOptions.map((voice) => (
          <div
            key={voice.id}
            className={`relative p-4 rounded-lg border transition-all cursor-pointer ${
              selected === voice.id
                ? "border-primary bg-primary/5 ring-1 ring-primary"
                : "hover:bg-secondary/50 hover:border-muted-foreground/30"
            }`}
            onClick={() => onSelect(voice.id)}
          >
            <div className="flex items-start justify-between gap-3">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <p className="font-medium">{voice.name}</p>
                  {selected === voice.id && (
                    <Badge variant="default" className="text-xs">
                      <Check className="h-3 w-3 mr-1" />
                      Selected
                    </Badge>
                  )}
                </div>
                <p className="text-sm text-muted-foreground mt-0.5">
                  {voice.description || "AI voice assistant"}
                </p>
              </div>
              
              <Button
                variant="outline"
                size="sm"
                className="shrink-0 gap-1.5"
                onClick={(e) => {
                  e.stopPropagation();
                  handlePreviewVoice(voice);
                }}
                disabled={playingVoice !== null && playingVoice !== voice.id}
              >
                {playingVoice === voice.id ? (
                  <>
                    <Square className="h-3.5 w-3.5" />
                    Stop
                  </>
                ) : (
                  <>
                    <Volume2 className="h-3.5 w-3.5" />
                    Preview
                  </>
                )}
              </Button>
            </div>
          </div>
        ))}
      </CardContent>
    </Card>
  );
}

/**
 * RoleGate — Wrapper component that conditionally renders children
 * based on the current user's role or permission.
 *
 * Usage:
 *   <RoleGate permission="can_manage_billing">
 *     <BillingSettings />
 *   </RoleGate>
 *
 *   <RoleGate minRole="manager" fallback={<p>Access denied</p>}>
 *     <TeamManagement />
 *   </RoleGate>
 */

import type { ReactNode } from "react";
import { useTenantRole, type Permission } from "@/hooks/useTenantRole";
import { ShieldAlert } from "lucide-react";

interface RoleGateProps {
  children: ReactNode;
  /** Required permission to view content */
  permission?: Permission;
  /** Minimum role level (viewer < staff < manager < owner) */
  minRole?: "viewer" | "staff" | "manager" | "owner";
  /** Content to show when access is denied. Defaults to nothing (hidden). */
  fallback?: ReactNode;
  /** If true, shows a styled "access denied" message instead of hiding */
  showDenied?: boolean;
}

export function RoleGate({
  children,
  permission,
  minRole,
  fallback,
  showDenied = false,
}: RoleGateProps) {
  const { hasPermission, isAtLeast } = useTenantRole();

  let allowed = true;

  if (permission) {
    allowed = hasPermission(permission);
  }

  if (minRole && allowed) {
    allowed = isAtLeast(minRole);
  }

  if (allowed) {
    return <>{children}</>;
  }

  if (fallback) {
    return <>{fallback}</>;
  }

  if (showDenied) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-muted-foreground">
        <ShieldAlert className="h-10 w-10 mb-3 opacity-40" />
        <p className="text-sm font-medium">You don't have access to this section</p>
        <p className="text-xs mt-1">Ask your account owner to adjust your permissions</p>
      </div>
    );
  }

  return null;
}

/**
 * useRoleCheck — Imperative hook for checking access in event handlers or logic
 *
 * Usage:
 *   const { canManageBilling, canEditBrain } = useRoleCheck();
 *   if (!canManageBilling) return;
 */
export function useRoleCheck() {
  const { hasPermission, isAtLeast, role } = useTenantRole();

  return {
    role,
    canManageBilling: hasPermission("can_manage_billing"),
    canDeleteTenant: hasPermission("can_delete_tenant"),
    canManageTeam: hasPermission("can_manage_team"),
    canEditBrain: hasPermission("can_edit_brain"),
    canManageSettings: hasPermission("can_manage_settings"),
    canViewReports: hasPermission("can_view_reports"),
    canManageEntities: hasPermission("can_manage_entities"),
    isAtLeastStaff: isAtLeast("staff"),
    isAtLeastManager: isAtLeast("manager"),
    isAtLeastOwner: isAtLeast("owner"),
  };
}

import { useEffect, useRef, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { RefreshCw, Clock, AlertTriangle } from "lucide-react";

/**
 * SessionExpirationHandler
 * 
 * Monitors the user's auth session and shows a beautiful toast
 * notification when the session expires, with a one-click refresh option.
 */
export function SessionExpirationHandler() {
  const hasShownExpiredToast = useRef(false);
  const toastId = useRef<string | number | null>(null);

  const handleRefreshSession = useCallback(async () => {
    // Dismiss the current toast
    if (toastId.current) {
      toast.dismiss(toastId.current);
    }

    // Show loading state
    const loadingToastId = toast.loading("Refreshing your session...", {
      description: "Please wait a moment",
    });

    try {
      const { data, error } = await supabase.auth.refreshSession();
      
      toast.dismiss(loadingToastId);

      if (error) {
        // If refresh fails, redirect to login
        toast.error("Session refresh failed", {
          description: "Please sign in again to continue.",
          duration: 5000,
        });
        
        // Give user time to see the message, then redirect
        setTimeout(() => {
          window.location.href = "/login";
        }, 2000);
        return;
      }

      if (data.session) {
        hasShownExpiredToast.current = false;
        toast.success("Session refreshed!", {
          description: "You can continue working without interruption.",
          duration: 3000,
        });
      }
    } catch (err) {
      toast.dismiss(loadingToastId);
      toast.error("Something went wrong", {
        description: "Please try signing in again.",
        duration: 5000,
      });
    }
  }, []);

  const showExpirationToast = useCallback(() => {
    if (hasShownExpiredToast.current) return;
    hasShownExpiredToast.current = true;

    toastId.current = toast.custom(
      (t) => (
        <div className="w-full max-w-md rounded-xl border border-warning/30 bg-card/95 backdrop-blur-xl shadow-2xl shadow-warning/10 p-4 animate-in slide-in-from-top-2 fade-in duration-300">
          {/* Header */}
          <div className="flex items-start gap-3">
            <div className="h-10 w-10 rounded-xl bg-warning/15 flex items-center justify-center shrink-0">
              <Clock className="h-5 w-5 text-warning" />
            </div>
            <div className="flex-1 min-w-0">
              <h3 className="font-semibold text-foreground flex items-center gap-2">
                Session Expired
                <span className="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-warning/10 text-warning text-[10px] font-medium uppercase tracking-wider">
                  <AlertTriangle className="h-3 w-3" />
                  Action Required
                </span>
              </h3>
              <p className="text-sm text-muted-foreground mt-1">
                Your session has expired. Don't worry — your work is safe.
              </p>
            </div>
          </div>

          {/* Action */}
          <div className="mt-4 flex items-center gap-2">
            <Button
              onClick={handleRefreshSession}
              size="sm"
              className="flex-1 gap-2 bg-warning hover:bg-warning/90 text-warning-foreground font-medium shadow-lg shadow-warning/20"
            >
              <RefreshCw className="h-4 w-4" />
              Refresh Session
            </Button>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => {
                toast.dismiss(t);
                window.location.href = "/login";
              }}
              className="text-muted-foreground hover:text-foreground"
            >
              Sign Out
            </Button>
          </div>

          {/* Subtle footer */}
          <p className="mt-3 text-[11px] text-muted-foreground/60 text-center">
            Sessions expire after inactivity for security purposes
          </p>
        </div>
      ),
      {
        duration: Infinity, // Don't auto-dismiss
        position: "top-center",
      }
    );
  }, [handleRefreshSession]);

  useEffect(() => {
    // Listen for auth state changes
    const { data: { subscription } } = supabase.auth.onAuthStateChange(
      (event, session) => {
        // TOKEN_REFRESHED means session was successfully refreshed
        if (event === "TOKEN_REFRESHED" && session) {
          hasShownExpiredToast.current = false;
          if (toastId.current) {
            toast.dismiss(toastId.current);
            toastId.current = null;
          }
        }

        // SIGNED_OUT could indicate session expiration
        if (event === "SIGNED_OUT") {
          // Only show toast if user was previously signed in and didn't manually sign out
          // We check this by seeing if the URL is not already on the auth page
          if (!window.location.pathname.includes("/login")) {
            showExpirationToast();
          }
        }
      }
    );

    // Also set up a periodic check for session validity
    const checkSessionValidity = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      
      if (!session && !window.location.pathname.includes("/login")) {
        showExpirationToast();
      }
    };

    // Check every 5 minutes
    const intervalId = setInterval(checkSessionValidity, 5 * 60 * 1000);

    return () => {
      subscription.unsubscribe();
      clearInterval(intervalId);
      if (toastId.current) {
        toast.dismiss(toastId.current);
      }
    };
  }, [showExpirationToast]);

  return null; // This component doesn't render anything
}

import { useState, useMemo } from "react";
import { Plus, Play, Pause, Trash2, Settings, Zap, ChevronRight, Loader2, CheckCircle, XCircle, Clock, AlertCircle } from "lucide-react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { EmptyState } from "@/components/ui/empty-state";
import { Skeleton } from "@/components/ui/skeleton";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import {
  useAutomationRules,
  useAutomationRuleMutations,
  useIntegrations,
  useTestAutomation,
  PROVIDERS,
  type AutomationRule,
} from "@/hooks/useIntegrations";
import { useTenantConfig, type BusinessMode } from "@/hooks/useTenantConfig";
import { formatDistanceToNow } from "date-fns";

interface AutomationRulesSectionProps {
  tenantId: string;
}

// Event metadata
const EVENTS: Record<string, { label: string; description: string; modes: BusinessMode[] }> = {
  "order.created": { label: "Order Created", description: "When a new order is placed", modes: ["food"] },
  "order.confirmed": { label: "Order Confirmed", description: "When an order is confirmed", modes: ["food"] },
  "order.ready": { label: "Order Ready", description: "When an order is ready for pickup", modes: ["food"] },
  "booking.created": { label: "Booking Created", description: "When a new booking is made", modes: ["service", "medical"] },
  "booking.confirmed": { label: "Booking Confirmed", description: "When a booking is confirmed", modes: ["service", "medical"] },
  "dispatch_job.created": { label: "Dispatch Job Created", description: "When a new dispatch job is created", modes: ["dispatch"] },
  "dispatch.confirmed": { label: "Dispatch Confirmed", description: "When a job is confirmed/assigned", modes: ["dispatch"] },
  "call.completed": { label: "Call Completed", description: "When an AI call ends", modes: ["service", "food", "dispatch", "medical", "general"] },
  "call.ended": { label: "Call Ended (legacy)", description: "Legacy event - use call.completed", modes: ["service", "food", "dispatch", "medical", "general"] },
  "missed_call": { label: "Missed Call", description: "When a call is missed", modes: ["service", "food", "dispatch", "medical", "general"] },
  "lead.captured": { label: "Lead Captured", description: "When a new lead is captured", modes: ["service", "food", "dispatch", "medical", "general"] },
  "sms.received": { label: "SMS Received", description: "When an SMS is received", modes: ["service", "food", "dispatch", "medical", "general"] },
};

// Action types
const ACTIONS: Record<string, { label: string; description: string; providers: string[] }> = {
  send_webhook: { label: "Send Webhook", description: "POST data to a URL", providers: ["webhook"] },
  create_event: { label: "Create Calendar Event", description: "Add to Google Calendar", providers: ["google_calendar"] },
  append_row: { label: "Append to Sheet", description: "Add row to Google Sheets", providers: ["google_sheets"] },
  print_receipt: { label: "Print Receipt", description: "Print kitchen ticket", providers: ["printer"] },
  send_sms: { label: "Send SMS", description: "Text customer", providers: ["sms"] },
  send_email: { label: "Send Email", description: "Email notification", providers: ["email"] },
};

export function AutomationRulesSection({ tenantId }: AutomationRulesSectionProps) {
  const { businessMode } = useTenantConfig();
  const { data: rules, isLoading } = useAutomationRules(tenantId);
  const { data: integrations } = useIntegrations(tenantId);
  const { createRule, toggleRule, deleteRule } = useAutomationRuleMutations(tenantId);
  const testAutomation = useTestAutomation();

  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [newRule, setNewRule] = useState({
    name: "",
    trigger_event: "",
    destination_provider: "",
    action_type: "",
    integration_id: "",
  });

  // Filter events by business mode
  const availableEvents = useMemo(() => {
    return Object.entries(EVENTS)
      .filter(([, meta]) => meta.modes.includes(businessMode))
      .map(([id, meta]) => ({ id, ...meta }));
  }, [businessMode]);

  // Get available actions based on connected integrations
  const availableActions = useMemo(() => {
    const connectedProviders = new Set(integrations?.map((i) => i.provider) || []);
    // Always include webhook, sms, print since they can work without explicit integration
    connectedProviders.add("webhook");
    connectedProviders.add("sms");
    connectedProviders.add("printer");

    return Object.entries(ACTIONS)
      .filter(([, meta]) => meta.providers.some((p) => connectedProviders.has(p)))
      .map(([id, meta]) => ({ id, ...meta }));
  }, [integrations]);

  const handleCreate = async () => {
    if (!newRule.name || !newRule.trigger_event || !newRule.action_type) return;

    try {
      await createRule.mutateAsync({
        name: newRule.name,
        trigger_event: newRule.trigger_event,
        destination_provider: newRule.destination_provider || "webhook",
        action_type: newRule.action_type,
        integration_id: newRule.integration_id || undefined,
      });
      setCreateDialogOpen(false);
      setNewRule({ name: "", trigger_event: "", destination_provider: "", action_type: "", integration_id: "" });
    } catch (e) {
      // Error handled by mutation
    }
  };

  const handleToggle = async (rule: AutomationRule) => {
    await toggleRule.mutateAsync({ id: rule.id, enabled: !rule.enabled });
  };

  const handleDelete = async (id: string) => {
    if (confirm("Are you sure you want to delete this automation?")) {
      await deleteRule.mutateAsync(id);
    }
  };

  const handleTest = async (rule: AutomationRule, dryRun: boolean) => {
    await testAutomation.mutateAsync({
      rule_id: rule.id,
      dry_run: dryRun,
    });
  };

  // Helper to render run status badge
  const renderRunStatus = (rule: AutomationRule) => {
    const latestRun = rule.latest_run;
    if (!latestRun) {
      return (
        <Badge variant="outline" className="text-xs gap-1">
          <Clock className="h-3 w-3" />
          Never run
        </Badge>
      );
    }

    const statusConfig: Record<string, { icon: React.ReactNode; variant: "default" | "secondary" | "destructive" | "outline"; label: string }> = {
      success: { icon: <CheckCircle className="h-3 w-3" />, variant: "default", label: "Success" },
      failed: { icon: <XCircle className="h-3 w-3" />, variant: "destructive", label: "Failed" },
      running: { icon: <Loader2 className="h-3 w-3 animate-spin" />, variant: "secondary", label: "Running" },
      pending: { icon: <Clock className="h-3 w-3" />, variant: "outline", label: "Pending" },
      skipped: { icon: <AlertCircle className="h-3 w-3" />, variant: "outline", label: "Skipped" },
    };

    const config = statusConfig[latestRun.status] || statusConfig.pending;
    const timeAgo = formatDistanceToNow(new Date(latestRun.started_at), { addSuffix: true });

    return (
      <Tooltip>
        <TooltipTrigger asChild>
          <Badge variant={config.variant} className="text-xs gap-1 cursor-help">
            {config.icon}
            {config.label}
          </Badge>
        </TooltipTrigger>
        <TooltipContent>
          <p>{timeAgo}</p>
          {latestRun.error_message && (
            <p className="text-destructive text-xs mt-1">{latestRun.error_message}</p>
          )}
        </TooltipContent>
      </Tooltip>
    );
  };

  if (isLoading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-8 w-48" />
        <div className="space-y-3">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-20 w-full" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-end">
        <Button onClick={() => setCreateDialogOpen(true)} size="sm">
          <Plus className="h-4 w-4 mr-2" />
          Create Rule
        </Button>
      </div>

      {rules && rules.length > 0 ? (
        <div className="space-y-3">
          {rules.map((rule) => {
            const event = EVENTS[rule.trigger_event];
            const action = ACTIONS[rule.action_type];
            const provider = PROVIDERS.find((p) => p.id === rule.destination_provider);

            return (
              <Card key={rule.id} className={!rule.enabled ? "opacity-60" : ""}>
                <CardContent className="p-4">
                  <div className="flex items-center justify-between gap-4">
                    <div className="flex items-center gap-4 min-w-0">
                      <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10 shrink-0">
                        <Zap className="h-5 w-5 text-primary" />
                      </div>
                      <div className="min-w-0">
                        <div className="flex items-center gap-2 flex-wrap">
                          <span className="font-medium">{rule.name}</span>
                          {!rule.enabled && <Badge variant="secondary">Paused</Badge>}
                          {renderRunStatus(rule)}
                        </div>
                        <div className="flex items-center gap-1 text-sm text-muted-foreground">
                          <span>{event?.label || rule.trigger_event}</span>
                          <ChevronRight className="h-3 w-3" />
                          <span className="flex items-center gap-1">
                            {provider?.icon}
                            {action?.label || rule.action_type}
                          </span>
                        </div>
                      </div>
                    </div>

                    <div className="flex items-center gap-2 shrink-0">
                      {/* Test Trigger Dropdown */}
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button
                            variant="ghost"
                            size="sm"
                            disabled={testAutomation.isPending}
                            title="Test Trigger"
                          >
                            {testAutomation.isPending ? (
                              <Loader2 className="h-4 w-4 animate-spin" />
                            ) : (
                              <Play className="h-4 w-4" />
                            )}
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuLabel>Test Automation</DropdownMenuLabel>
                          <DropdownMenuSeparator />
                          <DropdownMenuItem onClick={() => handleTest(rule, true)}>
                            <span className="font-medium">Dry Run</span>
                            <span className="text-xs text-muted-foreground ml-2">
                              (simulate)
                            </span>
                          </DropdownMenuItem>
                          <DropdownMenuItem onClick={() => handleTest(rule, false)}>
                            <span className="font-medium">Execute</span>
                            <span className="text-xs text-muted-foreground ml-2">
                              (real run)
                            </span>
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleDelete(rule.id)}
                        className="text-destructive hover:text-destructive"
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                      <Switch
                        checked={rule.enabled}
                        onCheckedChange={() => handleToggle(rule)}
                      />
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      ) : (
        <EmptyState
          icon={Zap}
          title="No automations yet"
          description="Create your first automation to start routing events to your tools"
          action={{
            label: "Create Automation",
            onClick: () => setCreateDialogOpen(true),
          }}
        />
      )}

      {/* Create Dialog */}
      <Dialog open={createDialogOpen} onOpenChange={setCreateDialogOpen}>
        <DialogContent className="max-w-lg">
          <DialogHeader>
            <DialogTitle>Create Automation</DialogTitle>
            <DialogDescription>
              Define when and how data should be sent to your connected tools
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="rule-name">Name</Label>
              <Input
                id="rule-name"
                placeholder="e.g., Send orders to kitchen printer"
                value={newRule.name}
                onChange={(e) => setNewRule({ ...newRule, name: e.target.value })}
              />
            </div>

            <div className="space-y-2">
              <Label>When this happens...</Label>
              <Select
                value={newRule.trigger_event}
                onValueChange={(value) => setNewRule({ ...newRule, trigger_event: value })}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select an event" />
                </SelectTrigger>
                <SelectContent>
                  {availableEvents.map((event) => (
                    <SelectItem key={event.id} value={event.id}>
                      <div className="flex flex-col">
                        <span>{event.label}</span>
                        <span className="text-xs text-muted-foreground">{event.description}</span>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Do this...</Label>
              <Select
                value={newRule.action_type}
                onValueChange={(value) => {
                  const action = ACTIONS[value];
                  setNewRule({
                    ...newRule,
                    action_type: value,
                    destination_provider: action?.providers[0] || "webhook",
                  });
                }}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select an action" />
                </SelectTrigger>
                <SelectContent>
                  {availableActions.map((action) => (
                    <SelectItem key={action.id} value={action.id}>
                      <div className="flex flex-col">
                        <span>{action.label}</span>
                        <span className="text-xs text-muted-foreground">{action.description}</span>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {newRule.action_type && integrations && integrations.length > 0 && (
              <div className="space-y-2">
                <Label>Using integration (optional)</Label>
                <Select
                  value={newRule.integration_id}
                  onValueChange={(value) =>
                    setNewRule({
                      ...newRule,
                      integration_id: value === "none" ? "" : value,
                    })
                  }
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select an integration" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">None (use defaults)</SelectItem>
                    {integrations
                      .filter((i) => {
                        const action = ACTIONS[newRule.action_type];
                        return action?.providers.includes(i.provider);
                      })
                      .map((integration) => (
                        <SelectItem key={integration.id} value={integration.id}>
                          {integration.display_name}
                        </SelectItem>
                      ))}
                  </SelectContent>
                </Select>
              </div>
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setCreateDialogOpen(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleCreate}
              disabled={createRule.isPending || !newRule.name || !newRule.trigger_event || !newRule.action_type}
            >
              {createRule.isPending ? "Creating..." : "Create Automation"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState } from "react";
import { formatDistanceToNow } from "date-fns";
import { CheckCircle, XCircle, Clock, RefreshCw, ChevronRight, ChevronDown, AlertCircle, Zap, Workflow } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { EmptyState } from "@/components/ui/empty-state";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { useAutomationRuns, useAutomationRunSteps, type AutomationRun } from "@/hooks/useIntegrations";
import { useTenantWorkflowRuns } from "@/hooks/useWorkflowRuns";
import type { WorkflowRun } from "@/types/workflow";

interface AutomationRunHistorySectionProps {
  tenantId: string;
}

function StatusIcon({ status }: { status: string }) {
  switch (status) {
    case "success":
      return <CheckCircle className="h-4 w-4 text-primary" />;
    case "failed":
      return <XCircle className="h-4 w-4 text-destructive" />;
    case "running":
      return <Clock className="h-4 w-4 text-accent-foreground animate-pulse" />;
    case "pending":
      return <Clock className="h-4 w-4 text-muted-foreground" />;
    default:
      return <AlertCircle className="h-4 w-4 text-muted-foreground" />;
  }
}

function StatusBadge({ status }: { status: string }) {
  const variants: Record<string, "default" | "secondary" | "destructive" | "outline"> = {
    success: "default",
    failed: "destructive",
    running: "secondary",
    pending: "outline",
    skipped: "outline",
  };

  return (
    <Badge variant={variants[status] || "secondary"} className="text-[10px] h-5 px-1.5">
      {status}
    </Badge>
  );
}

function RunDetails({ run }: { run: AutomationRun }) {
  const { data: steps, isLoading } = useAutomationRunSteps(run.id);

  if (isLoading) {
    return (
      <div className="p-4 space-y-2">
        <Skeleton className="h-4 w-full" />
        <Skeleton className="h-4 w-3/4" />
      </div>
    );
  }

  return (
    <div className="p-4 space-y-3 bg-muted/50 border-t">
      {/* Payload preview */}
      {run.payload_snapshot && (
        <div className="space-y-1">
          <p className="text-xs font-medium text-muted-foreground">Payload</p>
          <pre className="text-xs bg-background p-2 rounded border overflow-x-auto max-h-32">
            {JSON.stringify(run.payload_snapshot, null, 2)}
          </pre>
        </div>
      )}

      {/* Steps */}
      {steps && steps.length > 0 && (
        <div className="space-y-1">
          <p className="text-xs font-medium text-muted-foreground">Steps</p>
          <div className="space-y-2">
            {steps.map((step) => (
              <div
                key={step.id}
                className="flex items-center justify-between p-2 bg-background rounded border text-sm"
              >
                <div className="flex items-center gap-2">
                  <StatusIcon status={step.status} />
                  <span>{step.action_type}</span>
                  {step.destination_provider && (
                    <Badge variant="outline" className="text-[10px]">
                      {step.destination_provider}
                    </Badge>
                  )}
                </div>
                <StatusBadge status={step.status} />
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Error message */}
      {run.error_message && (
        <div className="space-y-1">
          <p className="text-xs font-medium text-destructive">Error</p>
          <p className="text-xs text-destructive bg-destructive/10 p-2 rounded">
            {run.error_message}
          </p>
        </div>
      )}
    </div>
  );
}

export function AutomationRunHistorySection({ tenantId }: AutomationRunHistorySectionProps) {
  const { data: automationRuns, isLoading: automationLoading, refetch: refetchAutomation } = useAutomationRuns(tenantId, 25);
  const { data: workflowRuns, isLoading: workflowLoading, refetch: refetchWorkflows } = useTenantWorkflowRuns(tenantId, { limit: 25 });
  const [expandedRuns, setExpandedRuns] = useState<Set<string>>(new Set());
  const [activeTab, setActiveTab] = useState<"workflows" | "legacy">("workflows");

  const isLoading = activeTab === "workflows" ? workflowLoading : automationLoading;
  
  const toggleExpanded = (runId: string) => {
    setExpandedRuns((prev) => {
      const next = new Set(prev);
      if (next.has(runId)) {
        next.delete(runId);
      } else {
        next.add(runId);
      }
      return next;
    });
  };

  const handleRefetch = () => {
    if (activeTab === "workflows") {
      refetchWorkflows();
    } else {
      refetchAutomation();
    }
  };

  // Convert workflow runs to a unified format for display
  const unifiedWorkflowRuns = (workflowRuns || []).map((run) => ({
    id: run.id,
    status: run.status,
    trigger_event: run.trigger,
    entity_type: run.entity_type,
    entity_id: run.entity_id,
    started_at: run.started_at,
    finished_at: run.finished_at,
    error_message: run.error,
    context: run.context,
    workflow_name: (run as any).workflow?.name || null,
    is_workflow: true,
  }));

  const runs = activeTab === "workflows" ? unifiedWorkflowRuns : (automationRuns || []);

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Run History</CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-14 w-full" />
          ))}
        </CardContent>
      </Card>
    );
  }

  // Stats
  const successCount = runs.filter((r) => r.status === "success").length;
  const failedCount = runs.filter((r) => r.status === "failed").length;

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between pb-2">
        <div>
          <CardTitle className="text-base">Run History</CardTitle>
          <p className="text-xs text-muted-foreground mt-1">
            {successCount} successful, {failedCount} failed
          </p>
        </div>
        <Button variant="ghost" size="sm" onClick={handleRefetch}>
          <RefreshCw className="h-4 w-4" />
        </Button>
      </CardHeader>
      <CardContent className="p-0">
        <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as "workflows" | "legacy")} className="w-full">
          <div className="px-4 pb-2">
            <TabsList className="grid w-full grid-cols-2 h-8">
              <TabsTrigger value="workflows" className="text-xs gap-1">
                <Workflow className="h-3 w-3" />
                Workflows
              </TabsTrigger>
              <TabsTrigger value="legacy" className="text-xs gap-1">
                <Zap className="h-3 w-3" />
                Legacy Rules
              </TabsTrigger>
            </TabsList>
          </div>

          <TabsContent value="workflows" className="m-0">
            {unifiedWorkflowRuns.length === 0 ? (
              <div className="p-4">
                <EmptyState
                  icon={Clock}
                  title="No workflow runs yet"
                  description="Workflow runs will appear here when events trigger your workflows"
                />
              </div>
            ) : (
              <div className="space-y-0">
                {unifiedWorkflowRuns.map((run) => {
                  const isExpanded = expandedRuns.has(run.id);

                  return (
                    <Collapsible key={run.id} open={isExpanded} onOpenChange={() => toggleExpanded(run.id)}>
                      <CollapsibleTrigger asChild>
                        <div className="flex items-center justify-between p-4 hover:bg-muted/50 transition-colors cursor-pointer border-b last:border-b-0">
                          <div className="flex items-center gap-3">
                            <StatusIcon status={run.status} />
                            <div>
                              <div className="flex items-center gap-2">
                                <span className="text-sm font-medium">
                                  {run.workflow_name || run.trigger_event}
                                </span>
                                <StatusBadge status={run.status} />
                              </div>
                              <div className="text-xs text-muted-foreground">
                                {run.trigger_event} • {run.entity_type}
                                {run.started_at && (
                                  <span> • {formatDistanceToNow(new Date(run.started_at), { addSuffix: true })}</span>
                                )}
                              </div>
                            </div>
                          </div>
                          <Button variant="ghost" size="icon" className="h-6 w-6">
                            {isExpanded ? (
                              <ChevronDown className="h-4 w-4" />
                            ) : (
                              <ChevronRight className="h-4 w-4" />
                            )}
                          </Button>
                        </div>
                      </CollapsibleTrigger>
                      <CollapsibleContent>
                        <div className="p-4 space-y-3 bg-muted/50 border-t">
                          {run.context && (
                            <div className="space-y-1">
                              <p className="text-xs font-medium text-muted-foreground">Context</p>
                              <pre className="text-xs bg-background p-2 rounded border overflow-x-auto max-h-32">
                                {JSON.stringify(run.context, null, 2)}
                              </pre>
                            </div>
                          )}
                          {run.error_message && (
                            <div className="space-y-1">
                              <p className="text-xs font-medium text-destructive">Error</p>
                              <p className="text-xs text-destructive bg-destructive/10 p-2 rounded">
                                {run.error_message}
                              </p>
                            </div>
                          )}
                        </div>
                      </CollapsibleContent>
                    </Collapsible>
                  );
                })}
              </div>
            )}
          </TabsContent>

          <TabsContent value="legacy" className="m-0">
            {!automationRuns || automationRuns.length === 0 ? (
              <div className="p-4">
                <EmptyState
                  icon={Clock}
                  title="No automation runs yet"
                  description="Legacy automation runs will appear here when events trigger your rules"
                />
              </div>
            ) : (
              <div className="space-y-0">
                {automationRuns.map((run) => {
                  const isExpanded = expandedRuns.has(run.id);

                  return (
                    <Collapsible key={run.id} open={isExpanded} onOpenChange={() => toggleExpanded(run.id)}>
                      <CollapsibleTrigger asChild>
                        <div className="flex items-center justify-between p-4 hover:bg-muted/50 transition-colors cursor-pointer border-b last:border-b-0">
                          <div className="flex items-center gap-3">
                            <StatusIcon status={run.status} />
                            <div>
                              <div className="flex items-center gap-2">
                                <span className="text-sm font-medium">
                                  {run.rule?.name || run.trigger_event}
                                </span>
                                <StatusBadge status={run.status} />
                              </div>
                              <div className="text-xs text-muted-foreground">
                                {run.trigger_event} • {run.entity_type}
                                {run.finished_at && (
                                  <span> • {formatDistanceToNow(new Date(run.started_at), { addSuffix: true })}</span>
                                )}
                              </div>
                            </div>
                          </div>
                          <Button variant="ghost" size="icon" className="h-6 w-6">
                            {isExpanded ? (
                              <ChevronDown className="h-4 w-4" />
                            ) : (
                              <ChevronRight className="h-4 w-4" />
                            )}
                          </Button>
                        </div>
                      </CollapsibleTrigger>
                      <CollapsibleContent>
                        <RunDetails run={run} />
                      </CollapsibleContent>
                    </Collapsible>
                  );
                })}
              </div>
            )}
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  );
}

