    modes: ["service", "food", "dispatch", "medical", "general"],
    requiresConfig: "webhook_url",
    color: "text-violet-500 bg-violet-500/10",
  },
];

export function OneClickPresets({ tenantId }: OneClickPresetsProps) {
  const { businessMode } = useTenantConfig();
  const { toast } = useToast();
  const { data: rules, isLoading } = useAutomationRules(tenantId);
  const { data: integrations } = useIntegrations(tenantId);
  const { createRule, toggleRule, deleteRule } = useAutomationRuleMutations(tenantId);
  const testAutomation = useTestAutomation();
  
  const [configDialog, setConfigDialog] = useState<{ preset: Preset; mode: "enable" | "test" } | null>(null);
  const [webhookUrl, setWebhookUrl] = useState("");

  // Filter presets by business mode
  const availablePresets = PRESETS.filter((p) => p.modes.includes(businessMode));

  // Map presets to existing rules
  const getPresetRule = (preset: Preset) => {
    return rules?.find(
      (r) => r.trigger_event === preset.trigger && r.action_type === preset.action
    );
  };

  const isConnected = (preset: Preset): boolean => {
    if (preset.provider === "webhook" || preset.provider === "sms" || preset.provider === "printer") {
      return true; // These don't require explicit integration
    }
    return integrations?.some((i) => i.provider === preset.provider && i.status === "connected") || false;
  };

  const handleToggle = async (preset: Preset) => {
    const existingRule = getPresetRule(preset);
    
    if (existingRule) {
      // Toggle existing rule
      await toggleRule.mutateAsync({ id: existingRule.id, enabled: !existingRule.enabled });
    } else {
      // Check if config needed
      if (preset.requiresConfig === "webhook_url") {
        setConfigDialog({ preset, mode: "enable" });
        return;
      }
      
      // Create new rule
      await createRule.mutateAsync({
        name: preset.label,
        description: preset.description,
        trigger_event: preset.trigger,
        action_type: preset.action,
        destination_provider: preset.provider,
      });
      
      toast({
        title: "Automation enabled",
        description: preset.label,
      });
    }
  };

  const handleEnableWithConfig = async () => {
    if (!configDialog) return;
    const { preset } = configDialog;
    
    await createRule.mutateAsync({
      name: preset.label,
      description: preset.description,
      trigger_event: preset.trigger,
      action_type: preset.action,
      destination_provider: preset.provider,
      field_mapping_json: preset.requiresConfig === "webhook_url" ? { url: webhookUrl } : undefined,
    });
    
    toast({
      title: "Automation enabled",
      description: preset.label,
    });
    
    setConfigDialog(null);
    setWebhookUrl("");
  };

  const handleTest = async (preset: Preset) => {
    const existingRule = getPresetRule(preset);
    
    if (!existingRule) {
      toast({
        title: "Enable first",
        description: "Please enable this automation before testing",
        variant: "destructive",
      });
      return;
    }
    
    await testAutomation.mutateAsync({
      rule_id: existingRule.id,
      dry_run: false,
    });
  };

  if (isLoading) {
    return (
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {[1, 2, 3].map((i) => (
          <Card key={i} className="animate-pulse">
            <CardContent className="p-4 h-24" />
          </Card>
        ))}
      </div>
    );
  }

  return (
    <>
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {availablePresets.map((preset) => {
          const rule = getPresetRule(preset);
          const isEnabled = rule?.enabled || false;
          const connected = isConnected(preset);
          
          return (
            <Card 
              key={preset.id} 
              className={`transition-all ${isEnabled ? "border-primary/50 bg-primary/5" : ""}`}
            >
              <CardContent className="p-4">
                <div className="flex items-start gap-3">
                  <div className={`p-2 rounded-lg shrink-0 ${preset.color}`}>
                    {preset.icon}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between gap-2">
                      <h4 className="font-medium text-sm leading-tight">
                        {preset.label}
                      </h4>
                      <Switch
                        checked={isEnabled}
                        onCheckedChange={() => handleToggle(preset)}
                        disabled={!connected && preset.requiresConfig !== "webhook_url"}
                      />
                    </div>
                    <p className="text-xs text-muted-foreground mt-1">
                      {preset.description}
                    </p>
                    
                    {/* Status row */}
                    <div className="flex items-center gap-2 mt-2">
                      {isEnabled && (
                        <Badge variant="default" className="text-[10px] h-5 gap-1">
                          <Check className="h-3 w-3" />
                          Active
                        </Badge>
                      )}
                      
                      {!connected && preset.requiresConfig !== "webhook_url" && (
                        <Badge variant="outline" className="text-[10px] h-5">
                          Connect {preset.provider.replace("_", " ")}
                        </Badge>
                      )}
                      
                      {isEnabled && (
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-5 px-1.5 text-[10px]"
                          onClick={() => handleTest(preset)}
                          disabled={testAutomation.isPending}
                        >
                          {testAutomation.isPending ? (
                            <Loader2 className="h-3 w-3 animate-spin" />
                          ) : (
                            <>
                              <Play className="h-3 w-3 mr-1" />
                              Test
                            </>
                          )}
                        </Button>
                      )}
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {/* Config Dialog for Webhook */}
      <Dialog open={!!configDialog} onOpenChange={() => setConfigDialog(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Configure Webhook</DialogTitle>
            <DialogDescription>
              Enter the URL where you want to receive data
            </DialogDescription>
          </DialogHeader>
          
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="webhook-url">Webhook URL</Label>
              <Input
                id="webhook-url"
                type="url"
                placeholder="https://your-system.com/webhook"
                value={webhookUrl}
                onChange={(e) => setWebhookUrl(e.target.value)}
              />
              <p className="text-xs text-muted-foreground">
                We'll POST event data to this URL whenever the trigger fires
              </p>
            </div>
          </div>
          
          <DialogFooter>
            <Button variant="outline" onClick={() => setConfigDialog(null)}>
              Cancel
            </Button>
            <Button
              onClick={handleEnableWithConfig}
              disabled={!webhookUrl || createRule.isPending}
            >
              {createRule.isPending ? "Enabling..." : "Enable & Save"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useBusyBlocks } from "@/hooks/useCalendarConnections";
import { useTenantSettings } from "@/hooks/useSettings";
import { CalendarConnectionStatus } from "./CalendarConnectionStatus";
import { DayAvailabilityTimeline } from "./DayAvailabilityTimeline";
import { QuickBlockDialog } from "./QuickBlockDialog";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Skeleton } from "@/components/ui/skeleton";
import { addDays, startOfDay, endOfDay, format } from "date-fns";
import { Clock, ChevronRight } from "lucide-react";

interface BusinessHours {
  [key: string]: any;
}

/** Normalize hours_json day config (supports both legacy flat and windows array formats) */
function normalizeDayHours(dayConfig: any): { open: string; close: string } | null {
  if (!dayConfig || dayConfig.closed === true) return null;
  if (dayConfig.windows?.length) {
    return { open: dayConfig.windows[0].open, close: dayConfig.windows[0].close };
  }
  if (dayConfig.open && dayConfig.close) {
    return { open: dayConfig.open, close: dayConfig.close };
  }
  return null;
}

const DAY_MAP: Record<number, string> = {
  0: "sunday",
  1: "monday",
  2: "tuesday",
  3: "wednesday",
  4: "thursday",
  5: "friday",
  6: "saturday",
};

export function AvailabilityHub() {
  const { tenant } = useAuth();
  const { tenant: tenantData, updateTenant } = useTenantSettings();
  const tenantLoading = updateTenant.isPending;
  const [blockDialogOpen, setBlockDialogOpen] = useState(false);
  const [blockDialogDate, setBlockDialogDate] = useState<Date | undefined>();
  const [selectedDayIndex, setSelectedDayIndex] = useState(0);

  // Get business hours from tenant
  const businessHours = (tenantData?.hours_json as unknown as BusinessHours) || null;

  // Get dates for today and next 2 days
  const today = new Date();
  const days = [today, addDays(today, 1), addDays(today, 2)];

  // Fetch busy blocks for next 3 days
  const { blocks, isLoading: blocksLoading, deleteBlock } = useBusyBlocks({
    start: startOfDay(today),
    end: endOfDay(addDays(today, 2)),
  });

  // Get blocks for a specific day
  const getBlocksForDay = (date: Date) => {
    return blocks.filter((block) => {
      const blockStart = new Date(block.start_at);
      return blockStart >= startOfDay(date) && blockStart <= endOfDay(date);
    });
  };

  // Get hours for a specific day
  const getHoursForDay = (date: Date) => {
    const dayName = DAY_MAP[date.getDay()];
    const raw = businessHours?.[dayName] || null;
    return normalizeDayHours(raw);
  };

  const handleOpenBlockDialog = (date?: Date) => {
    setBlockDialogDate(date);
    setBlockDialogOpen(true);
  };

  const handleRemoveBlock = async (blockId: string) => {
    await deleteBlock.mutateAsync(blockId);
  };

  const isLoading = tenantLoading || blocksLoading;

  // Summary stats
  const rawTodayHours = getHoursForDay(today);
  const todayHours = normalizeDayHours(rawTodayHours);
  const todayBlocks = getBlocksForDay(today);
  const isTodayOpen = !!todayHours;

  return (
    <div className="space-y-6">
      {/* Calendar Connection Status - Most Prominent */}
      <CalendarConnectionStatus />

      {/* Quick Status Summary */}
      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center gap-2">
            <Clock className="h-5 w-5 text-primary" />
            <CardTitle className="text-lg">Your Availability</CardTitle>
          </div>
          <CardDescription>
            What your AI knows about your schedule right now
          </CardDescription>
        </CardHeader>
        <CardContent>
          {isLoading ? (
            <div className="space-y-3">
              <Skeleton className="h-16 w-full" />
              <Skeleton className="h-24 w-full" />
            </div>
          ) : (
            <>
              {/* Today's Summary */}
              <div className="p-4 rounded-lg bg-muted/50 mb-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm text-muted-foreground">Today ({format(today, "EEEE, MMM d")})</p>
                    <p className="text-xl font-semibold">
                      {isTodayOpen && todayHours ? (
                        <span className="text-primary">
                          {formatTime(todayHours.open)} – {formatTime(todayHours.close)}
                        </span>
                      ) : (
                        <span className="text-muted-foreground">Closed</span>
                      )}
                    </p>
                  </div>
                  {isTodayOpen && (
                    <div className="text-right">
                      <p className="text-sm text-muted-foreground">
                        {todayBlocks.length > 0 
                          ? `${todayBlocks.length} time${todayBlocks.length > 1 ? "s" : ""} blocked`
                          : "No blocks"}
                      </p>
                      <Button 
                        variant="link" 
                        size="sm" 
                        className="h-auto p-0 text-primary"
                        onClick={() => handleOpenBlockDialog(today)}
                      >
                        Block time
                        <ChevronRight className="h-4 w-4 ml-1" />
                      </Button>
                    </div>
                  )}
                </div>
              </div>

              {/* Day Tabs */}
              <Tabs 
                value={selectedDayIndex.toString()} 
                onValueChange={(v) => setSelectedDayIndex(parseInt(v))}
              >
                <TabsList className="w-full grid grid-cols-3">
                  {days.map((day, i) => (
                    <TabsTrigger key={i} value={i.toString()}>
                      {i === 0 ? "Today" : i === 1 ? "Tomorrow" : format(day, "EEE")}
                    </TabsTrigger>
                  ))}
                </TabsList>
                {days.map((day, i) => (
                  <TabsContent key={i} value={i.toString()} className="mt-4">
                    <DayAvailabilityTimeline
                      date={day}
                      businessHours={getHoursForDay(day)}
                      busyBlocks={getBlocksForDay(day)}
                      onBlockTime={() => handleOpenBlockDialog(day)}
                      onRemoveBlock={handleRemoveBlock}
                    />
                  </TabsContent>
                ))}
              </Tabs>
            </>
          )}
        </CardContent>
      </Card>

      {/* Helpful Info */}
      <div className="p-4 rounded-lg bg-muted/30 border text-sm text-muted-foreground">
        <p className="font-medium text-foreground mb-1">💡 How this works</p>
        <p>
          Your AI uses this schedule to answer "Are you open?" and to only offer appointments 
          during available hours. Connect your calendar above so it can see your real-time 
          meetings and automatically block those times.
        </p>
      </div>

      {/* Quick Block Dialog */}
      <QuickBlockDialog
        open={blockDialogOpen}
        onOpenChange={setBlockDialogOpen}
        defaultDate={blockDialogDate}
      />
    </div>
  );
}

function formatTime(time: string | undefined): string {
  if (!time) return "--:--";
  const parts = time.split(":");
  if (parts.length < 2) return time;
  const [hours, minutes] = parts;
  const h = parseInt(hours, 10);
  if (isNaN(h)) return time;
  const ampm = h >= 12 ? "PM" : "AM";
  const hour12 = h % 12 || 12;
  return `${hour12}:${minutes} ${ampm}`;
}

import { useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { format, parseISO, isSameDay, addDays, isToday, isTomorrow } from "date-fns";
import { Plus, Calendar, XCircle } from "lucide-react";
import type { BusyBlock } from "@/hooks/useCalendarConnections";

interface DayAvailabilityTimelineProps {
  date: Date;
  businessHours: { open: string; close: string; closed?: boolean } | null;
  busyBlocks: BusyBlock[];
  onBlockTime?: () => void;
  onRemoveBlock?: (blockId: string) => void;
}

interface TimeSlot {
  hour: number;
  label: string;
  status: "available" | "busy" | "outside-hours";
  block?: BusyBlock;
  blockLabel?: string;
}

export function DayAvailabilityTimeline({
  date,
  businessHours,
  busyBlocks,
  onBlockTime,
  onRemoveBlock,
}: DayAvailabilityTimelineProps) {
  const dayLabel = isToday(date)
    ? "Today"
    : isTomorrow(date)
    ? "Tomorrow"
    : format(date, "EEEE");

  // Generate time slots for the day
  const timeSlots = useMemo(() => {
    const slots: TimeSlot[] = [];

    if (!businessHours || !businessHours.open || !businessHours.close) {
      // Business is closed or hours not configured - show full day as closed
      return [{ hour: 0, label: "Closed", status: "outside-hours" as const }];
    }

    const [openHour] = businessHours.open.split(":").map(Number);
    const [closeHour] = businessHours.close.split(":").map(Number);

    // Generate hourly slots
    for (let hour = openHour; hour < closeHour; hour++) {
      const slotStart = new Date(date);
      slotStart.setHours(hour, 0, 0, 0);

      const slotEnd = new Date(date);
      slotEnd.setHours(hour + 1, 0, 0, 0);

      // Check if this hour overlaps with any busy block
      const overlappingBlock = busyBlocks.find((block) => {
        const blockStart = parseISO(block.start_at);
        const blockEnd = parseISO(block.end_at);
        return blockStart < slotEnd && blockEnd > slotStart;
      });

      const formatHour = (h: number) => {
        const ampm = h >= 12 ? "PM" : "AM";
        const hour12 = h % 12 || 12;
        return `${hour12} ${ampm}`;
      };

      if (overlappingBlock) {
        const metadata = overlappingBlock.metadata_json as Record<string, unknown> | null;
        const reason = (metadata?.reason as string) || (metadata?.title as string) || "";
        
        let blockLabel = "";
        switch (overlappingBlock.block_type) {
          case "external_busy":
            blockLabel = reason || "Calendar event";
            break;
          case "confirmed_booking":
            blockLabel = reason || "Appointment";
            break;
          case "manual_busy":
            blockLabel = reason || "Blocked";
            break;
          case "hold":
            blockLabel = "On hold";
            break;
          default:
            blockLabel = reason || "Busy";
        }

        slots.push({
          hour,
          label: formatHour(hour),
          status: "busy",
          block: overlappingBlock,
          blockLabel,
        });
      } else {
        slots.push({
          hour,
          label: formatHour(hour),
          status: "available",
        });
      }
    }

    return slots;
  }, [date, businessHours, busyBlocks]);

  const isClosed = !businessHours || businessHours.closed;
  const availableCount = timeSlots.filter((s) => s.status === "available").length;
  const busyCount = timeSlots.filter((s) => s.status === "busy").length;

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Calendar className="h-4 w-4 text-muted-foreground" />
            <CardTitle className="text-base">{dayLabel}'s Availability</CardTitle>
            <span className="text-sm text-muted-foreground">
              {format(date, "MMM d")}
            </span>
          </div>
          {!isClosed && onBlockTime && (
            <Button variant="outline" size="sm" onClick={onBlockTime}>
              <Plus className="h-4 w-4 mr-1" />
              Block Time
            </Button>
          )}
        </div>
        {!isClosed && (
          <div className="flex items-center gap-4 text-sm text-muted-foreground">
            <span>{availableCount} hours available</span>
            {busyCount > 0 && <span>{busyCount} hours blocked</span>}
          </div>
        )}
      </CardHeader>
      <CardContent>
        {isClosed ? (
          <div className="flex items-center justify-center py-8 text-muted-foreground">
            <XCircle className="h-5 w-5 mr-2" />
            <span>Closed on {dayLabel}</span>
          </div>
        ) : (
          <div className="space-y-1">
            {timeSlots.map((slot) => (
              <div
                key={slot.hour}
                className={cn(
                  "flex items-center gap-3 py-2 px-3 rounded-md transition-colors",
                  slot.status === "available" && "bg-primary/5 hover:bg-primary/10",
                  slot.status === "busy" && "bg-muted"
                )}
              >
                <span className="w-16 text-sm font-medium text-muted-foreground">
                  {slot.label}
                </span>
                <div className="flex-1 flex items-center gap-2">
                  {slot.status === "available" ? (
                    <span className="text-sm text-primary">Available</span>
                  ) : (
                    <>
                      <div
                        className={cn(
                          "h-2 w-2 rounded-full",
                          slot.block?.block_type === "external_busy" && "bg-primary",
                          slot.block?.block_type === "confirmed_booking" && "bg-accent",
                          slot.block?.block_type === "manual_busy" && "bg-warning",
                          slot.block?.block_type === "hold" && "bg-muted-foreground"
                        )}
                      />
                      <span className="text-sm">{slot.blockLabel}</span>
                      {slot.block?.block_type === "manual_busy" && onRemoveBlock && (
                        <Button
                          variant="ghost"
                          size="sm"
                          className="h-6 px-2 ml-auto text-xs text-muted-foreground hover:text-destructive"
                          onClick={() => onRemoveBlock(slot.block!.id)}
                        >
                          Remove
                        </Button>
                      )}
                    </>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Legend - Always show so users understand the color coding */}
        {!isClosed && (
          <div className="flex flex-wrap gap-4 mt-4 pt-4 border-t text-xs text-muted-foreground">
            <div className="flex items-center gap-1">
              <div className="h-2 w-2 rounded-full bg-primary/30 ring-1 ring-primary/50" />
              <span>Available</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="h-2 w-2 rounded-full bg-primary" />
              <span>Calendar event</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="h-2 w-2 rounded-full bg-accent" />
              <span>Booking</span>
            </div>
            <div className="flex items-center gap-1">
              <div className="h-2 w-2 rounded-full bg-warning" />
              <span>Manual block</span>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { useBusyBlocks } from "@/hooks/useCalendarConnections";
import { format, addDays, setHours, setMinutes, parseISO } from "date-fns";
import { Loader2, Clock } from "lucide-react";

interface QuickBlockDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  defaultDate?: Date;
}

export function QuickBlockDialog({ open, onOpenChange, defaultDate }: QuickBlockDialogProps) {
  const { createBlock } = useBusyBlocks();
  const today = new Date();
  const tomorrow = addDays(today, 1);

  const [selectedDay, setSelectedDay] = useState<"today" | "tomorrow">(
    defaultDate && format(defaultDate, "yyyy-MM-dd") === format(tomorrow, "yyyy-MM-dd")
      ? "tomorrow"
      : "today"
  );
  const [startTime, setStartTime] = useState("12:00");
  const [endTime, setEndTime] = useState("13:00");
  const [reason, setReason] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    const date = selectedDay === "today" ? today : tomorrow;
    const [startHour, startMin] = startTime.split(":").map(Number);
    const [endHour, endMin] = endTime.split(":").map(Number);

    const startAt = setMinutes(setHours(date, startHour), startMin);
    const endAt = setMinutes(setHours(date, endHour), endMin);

    await createBlock.mutateAsync({
      start_at: startAt.toISOString(),
      end_at: endAt.toISOString(),
      block_type: "manual_busy",
      metadata_json: reason ? { reason } : {},
    });

    // Reset and close
    setReason("");
    setStartTime("12:00");
    setEndTime("13:00");
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[400px]">
        <DialogHeader>
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-full bg-primary/10">
              <Clock className="h-5 w-5 text-primary" />
            </div>
            <div>
              <DialogTitle>Block Time</DialogTitle>
              <DialogDescription>
                Temporarily block a time slot so your AI won't book it
              </DialogDescription>
            </div>
          </div>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4 py-4">
          {/* Day Selection */}
          <div className="space-y-2">
            <Label>When?</Label>
            <RadioGroup
              value={selectedDay}
              onValueChange={(v) => setSelectedDay(v as "today" | "tomorrow")}
              className="flex gap-4"
            >
              <label
                className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-lg border cursor-pointer transition-colors ${
                  selectedDay === "today"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:bg-muted/50"
                }`}
              >
                <RadioGroupItem value="today" className="sr-only" />
                <div className="text-center">
                  <p className="font-medium">Today</p>
                  <p className="text-sm text-muted-foreground">{format(today, "MMM d")}</p>
                </div>
              </label>
              <label
                className={`flex-1 flex items-center justify-center gap-2 p-3 rounded-lg border cursor-pointer transition-colors ${
                  selectedDay === "tomorrow"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:bg-muted/50"
                }`}
              >
                <RadioGroupItem value="tomorrow" className="sr-only" />
                <div className="text-center">
                  <p className="font-medium">Tomorrow</p>
                  <p className="text-sm text-muted-foreground">{format(tomorrow, "MMM d")}</p>
                </div>
              </label>
            </RadioGroup>
          </div>

          {/* Time Selection */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label htmlFor="startTime">Start Time</Label>
              <Input
                id="startTime"
                type="time"
                value={startTime}
                onChange={(e) => setStartTime(e.target.value)}
                required
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="endTime">End Time</Label>
              <Input
                id="endTime"
                type="time"
                value={endTime}
                onChange={(e) => setEndTime(e.target.value)}
                required
              />
            </div>
          </div>

          {/* Reason (optional) */}
          <div className="space-y-2">
            <Label htmlFor="reason">Reason (optional)</Label>
            <Input
              id="reason"
              placeholder="e.g., Lunch, Personal errand"
              value={reason}
              onChange={(e) => setReason(e.target.value)}
            />
          </div>

          <DialogFooter>
            <Button type="button" variant="ghost" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={createBlock.isPending}>
              {createBlock.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Block Time
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

