              <span className="font-medium">All set! Your AI is fully configured.</span>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * BrainNextStepsBar - Priority-ordered "What Should I Do Next?" engine
 *
 * Builds a task queue from:
 * - Capability flags that are ON but unconfigured
 * - AI readiness P0/P1 checks that are failing
 * - Categories with low completion percentages
 *
 * Renders as a persistent bar at the top of the BrainDashboard.
 */

import { useMemo, useState } from "react";
import { ArrowRight, CheckCircle2, ChevronDown, ChevronUp, Sparkles, Target } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { useAIReadinessV2 } from "@/hooks/useAIReadinessV2";
import { useBusinessCapabilities } from "@/hooks/useBusinessCapabilities";
import type { CategoryCompletionStats } from "@/hooks/useCategoryCompletion";
import type { CategoryConfig } from "@/components/brain/layout/businessBrainNavConfig";

interface NextStep {
  id: string;
  label: string;
  reason: string;
  section: string;
  priority: "critical" | "important" | "nice";
}

interface BrainNextStepsBarProps {
  completions: Record<string, CategoryCompletionStats>;
  categories: CategoryConfig[];
  onNavigate: (section: string) => void;
}

/**
 * Derive priority-ordered next steps from readiness, capabilities, and completion.
 */
function buildNextSteps(
  readiness: ReturnType<typeof useAIReadinessV2>,
  capabilities: ReturnType<typeof useBusinessCapabilities>,
  completions: Record<string, CategoryCompletionStats>,
  categories: CategoryConfig[],
): NextStep[] {
  const steps: NextStep[] = [];

  // 1. P0 readiness blockers (critical)
  for (const flag of readiness.p0Flags) {
    const rec = readiness.recommendations.find(r => r.deep_link.includes(flag) || r.label.toLowerCase().includes(flag.replace(/_/g, " ")));
    steps.push({
      id: `p0-${flag}`,
      label: rec?.label || flag.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase()),
      reason: "Required to go live",
      section: mapFlagToSection(flag),
      priority: "critical",
    });
  }

  // 2. Categories with 0% completion (important)
  const sorted = [...categories].sort((a, b) => a.order - b.order);
  for (const cat of sorted) {
    const stats = completions[cat.section];
    if (stats && stats.percentage === 0 && stats.totalFields > 0) {
      // Skip if already covered by P0
      if (steps.some(s => s.section === cat.section)) continue;
      steps.push({
        id: `empty-${cat.section}`,
        label: `Set up ${cat.title}`,
        reason: "No data configured yet",
        section: cat.section,
        priority: "important",
      });
    }
  }

  // 3. Categories with < 50% completion (important)
  for (const cat of sorted) {
    const stats = completions[cat.section];
    if (stats && stats.percentage > 0 && stats.percentage < 50 && stats.totalFields > 0) {
      if (steps.some(s => s.section === cat.section)) continue;
      steps.push({
        id: `low-${cat.section}`,
        label: `Finish ${cat.title}`,
        reason: `${stats.percentage}% complete`,
        section: cat.section,
        priority: "important",
      });
    }
  }

  // 4. Capability-driven suggestions (nice)
  if (capabilities.mode === "service" || capabilities.mode === "general") {
    if (!capabilities.hasFAQs) {
      if (!steps.some(s => s.id.includes("faq"))) {
        steps.push({
          id: "cap-faqs",
          label: "Add FAQs",
          reason: "Helps your AI answer common questions",
          section: "training",
          priority: "nice",
        });
      }
    }
  }

  // 5. P1 flags (nice)
  for (const flag of readiness.p1Flags.slice(0, 2)) {
    if (steps.some(s => s.id.includes(flag))) continue;
    steps.push({
      id: `p1-${flag}`,
      label: flag.replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase()),
      reason: "Recommended improvement",
      section: mapFlagToSection(flag),
      priority: "nice",
    });
  }

  return steps;
}

function mapFlagToSection(flag: string): string {
  if (flag.includes("service") || flag.includes("menu") || flag.includes("catalog")) return "services";
  if (flag.includes("hour") || flag.includes("name") || flag.includes("profile")) return "about";
  if (flag.includes("greeting") || flag.includes("faq") || flag.includes("script") || flag.includes("knowledge")) return "training";
  if (flag.includes("polic") || flag.includes("cancel") || flag.includes("deposit")) return "rules";
  if (flag.includes("coverage") || flag.includes("area") || flag.includes("calendar")) return "operations";
  return "about";
}

const PRIORITY_COLORS = {
  critical: "bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300",
  important: "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300",
  nice: "bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-300",
};

export function BrainNextStepsBar({ completions, categories, onNavigate }: BrainNextStepsBarProps) {
  const readiness = useAIReadinessV2();
  const capabilities = useBusinessCapabilities();
  const [showAll, setShowAll] = useState(false);

  const steps = useMemo(
    () => buildNextSteps(readiness, capabilities, completions, categories),
    [readiness, capabilities, completions, categories],
  );

  if (steps.length === 0) {
    return (
      <div className="flex items-center gap-3 p-4 rounded-xl bg-green-50 dark:bg-green-950/20 border border-green-200 dark:border-green-800/50">
        <CheckCircle2 className="h-5 w-5 text-green-600" />
        <p className="text-sm font-medium text-green-800 dark:text-green-200">
          All set! Your AI knowledge base is fully configured.
        </p>
      </div>
    );
  }

  const visibleSteps = showAll ? steps : steps.slice(0, 3);
  const hasMore = steps.length > 3;

  return (
    <div className="rounded-xl border bg-card p-4 space-y-3">
      {/* Header */}
      <div className="flex items-center gap-2">
        <Target className="h-4 w-4 text-primary" />
        <h3 className="text-sm font-semibold">What to do next</h3>
        <span className="text-xs text-muted-foreground ml-auto">
          Step 1 of {steps.length}
        </span>
      </div>

      {/* Steps */}
      <div className="space-y-1.5">
        {visibleSteps.map((step, i) => (
          <button
            key={step.id}
            type="button"
            onClick={() => onNavigate(step.section)}
            className="flex items-center gap-3 w-full p-2.5 rounded-lg hover:bg-muted/50 transition-colors text-left group"
          >
            <span className="text-xs font-bold text-muted-foreground tabular-nums shrink-0 w-5">
              {i + 1}.
            </span>
            <span className={cn(
              "text-[10px] font-bold px-1.5 py-0.5 rounded shrink-0 uppercase tracking-wider",
              PRIORITY_COLORS[step.priority],
            )}>
              {step.priority === "critical" ? "Fix" : step.priority === "important" ? "Do" : "Try"}
            </span>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium truncate">{step.label}</p>
              <p className="text-xs text-muted-foreground truncate">
                {step.reason}
                {step.priority === "critical" ? " · ~2 min" : step.priority === "important" ? " · ~3 min" : " · ~1 min"}
              </p>
            </div>
            <ArrowRight className="h-3.5 w-3.5 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity shrink-0" />
          </button>
        ))}
      </div>

      {/* Show more/less */}
      {hasMore && (
        <Button
          variant="ghost"
          size="sm"
          onClick={() => setShowAll(!showAll)}
          className="w-full text-xs"
        >
          {showAll ? "Show less" : `Show ${steps.length - 3} more`}
          {showAll ? <ChevronUp className="h-3 w-3 ml-1" /> : <ChevronDown className="h-3 w-3 ml-1" />}
        </Button>
      )}
    </div>
  );
}

import React from "react";
/**
 * BrainSectionDetail - Sidebar + Content split layout for section detail views
 *
 * Hosts:
 * - Breadcrumb navigation (Business Brain / {Title})
 * - Editorial title + inline icon + progress bar
 * - Banner content (QuoteReadinessCard, food notice, etc.)
 * - Sidebar + Content panel split (desktop) or mobile list/editor
 * - Add-on content (AddOnGroup, if any)
 * - Prev / Next category navigation
 */

import { ArrowLeft, CheckCircle2, ChevronLeft, ChevronRight } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { BRAIN_CATEGORIES, type CategoryConfig } from "@/components/brain/layout/businessBrainNavConfig";
import { BrainSectionSidebar } from "@/components/brain/layout/BrainSectionSidebar";
import { BrainMobileItemList } from "@/components/brain/layout/BrainMobileItemList";
import { BrainContentPanel } from "@/components/brain/layout/BrainContentPanel";
import type { CategoryCompletionStats } from "@/hooks/useCategoryCompletion";
import type { SectionGroup, BrainSectionItem } from "@/config/brainSectionRegistry";
import type { ItemStatusInfo } from "@/hooks/useBrainItemStatuses";

interface BrainSectionDetailProps {
  category: CategoryConfig;
  /** Mode-specific ordered categories for prev/next navigation */
  orderedCategories?: CategoryConfig[];
  /** Dynamic title resolved from industry terminology */
  resolvedTitle?: string;
  completion: CategoryCompletionStats;
  onBack: () => void;
  onNavigate: (section: string) => void;
  // Sidebar + content props
  activeItemId: string | null;
  onItemChange: (itemId: string) => void;
  groups: SectionGroup[];
  statuses: Record<string, ItemStatusInfo>;
  activeItem: BrainSectionItem | null;
  usedByAI?: string[];
  guidance?: { whyText?: string; whatText?: string; tipText?: string };
  // Slot content
  bannerContent?: React.ReactNode;
  addOnContent?: React.ReactNode;
  editorContent: React.ReactNode;
}

function getAdjacentCategories(section: string, categories?: CategoryConfig[]) {
  const source = categories ?? BRAIN_CATEGORIES;
  const sorted = [...source].sort((a, b) => a.order - b.order);
  const idx = sorted.findIndex((c) => c.section === section);
  return {
    prev: idx > 0 ? sorted[idx - 1] : null,
    next: idx < sorted.length - 1 ? sorted[idx + 1] : null,
  };
}

export const BrainSectionDetail = React.memo(function BrainSectionDetail({
  category,
  orderedCategories,
  resolvedTitle,
  completion,
  onBack,
  onNavigate,
  activeItemId,
  onItemChange,
  groups,
  statuses,
  activeItem,
  usedByAI,
  guidance,
  bannerContent,
  addOnContent,
  editorContent,
}: BrainSectionDetailProps) {
  const Icon = category.icon;
  const displayTitle = resolvedTitle || category.title;
  const { prev, next } = getAdjacentCategories(category.section, orderedCategories);
  const activeStatus = activeItemId ? statuses[activeItemId] : undefined;

  const handleMobileBack = () => {
    // Clear item selection to show list
    onItemChange("");
  };

  return (
    <div className="space-y-5">
      {/* Breadcrumb + editorial header */}
      <div className="space-y-3">
        {/* Back button + breadcrumb + progress */}
        <div className="flex items-center gap-2 text-sm">
          <button
            type="button"
            onClick={onBack}
            className="flex items-center gap-1.5 text-muted-foreground hover:text-foreground transition-colors"
          >
            <ArrowLeft className="h-4 w-4" />
            Business Brain
          </button>
          <span className="text-muted-foreground/50">/</span>
          <span className="text-foreground font-medium flex-1">{displayTitle}</span>
          <span className="text-xs font-medium tabular-nums text-muted-foreground">
            {completion.percentage}%
          </span>
        </div>

        <Progress value={completion.percentage} className="h-1" />
      </div>

      {/* Banner content */}
      {bannerContent}

      {/* Sidebar + Content split */}
      <div className="flex gap-0 min-h-[60vh]">
        {/* Desktop sidebar */}
        <BrainSectionSidebar
          groups={groups}
          activeItemId={activeItemId}
          onItemChange={onItemChange}
          statuses={statuses}
        />

        {/* Mobile: show list when no item selected, editor when item selected */}
        {!activeItemId ? (
          <BrainMobileItemList
            groups={groups}
            onItemSelect={onItemChange}
            statuses={statuses}
          />
        ) : (
          /* Content panel — always visible on desktop, conditional on mobile */
          <BrainContentPanel
            activeItem={activeItem}
            status={activeStatus}
            usedByAI={usedByAI}
            guidance={guidance}
            onMobileBack={handleMobileBack}
          >
            {editorContent}
          </BrainContentPanel>
        )}
      </div>

      {/* Add-on content */}
      {addOnContent}

      {/* Prev / Next nav */}
      <div className="flex items-center justify-between mt-8 pt-6 border-t border-border/30">
        {prev ? (
          <Button
            variant="outline"
            onClick={() => onNavigate(prev.section)}
            className="gap-2 px-4 py-2"
          >
            <ChevronLeft className="h-4 w-4" />
            {prev.title}
          </Button>
        ) : (
          <div />
        )}

        {next ? (
          <Button
            variant="outline"
            onClick={() => onNavigate(next.section)}
            className="gap-2 px-4 py-2"
          >
            {next.title}
            <ChevronRight className="h-4 w-4" />
          </Button>
        ) : (
          <div />
        )}
      </div>
    </div>
  );
});

/**
 * DispatchCoverageZonesEditor - Dispatch mode coverage zones and ETA settings
 * 
 * Manages distance-based zones, highway coverage, and ETA adjustments.
 */
import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useTenantDistanceSettings } from "@/hooks/useTenantDistanceSettings";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Slider } from "@/components/ui/slider";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Loader2,
  Plus,
  Edit2,
  Trash2,
  MapPin,
  Route,
  Clock,
  Gauge,
  Car,
  Mountain,
} from "lucide-react";
import { AIPreviewCard } from "../AIPreviewCard";

interface CoverageZone {
  id: string;
  tenant_id: string;
  zone_name: string;
  zone_type: "standard" | "highway" | "remote" | "premium";
  definition_type: "radius" | "zip" | "county" | "highway";
  min_miles: number;
  max_miles: number | null;
  zip_codes: string[];
  county_names: Array<{ name: string; state: string }>;
  highway_numbers: string[];
  base_rate_cents: number | null;
  per_mile_rate_cents: number | null;
  minimum_charge_cents: number | null;
  eta_base_minutes: number;
  eta_per_mile_minutes: number;
  is_active: boolean;
  available_24_7: boolean;
  priority_order: number;
}

const DEFAULT_ZONE: Omit<CoverageZone, "id" | "tenant_id"> = {
  zone_name: "",
  zone_type: "standard",
  definition_type: "radius",
  min_miles: 0,
  max_miles: 25,
  zip_codes: [],
  county_names: [],
  highway_numbers: [],
  base_rate_cents: null,
  per_mile_rate_cents: null,
  minimum_charge_cents: null,
  eta_base_minutes: 30,
  eta_per_mile_minutes: 2,
  is_active: true,
  available_24_7: true,
  priority_order: 0,
};

export function DispatchCoverageZonesEditor() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const { settings: distanceSettings, saveSettings: saveDistanceSettings, isLoading: distanceLoading } = useTenantDistanceSettings();
  
  const [zones, setZones] = useState<CoverageZone[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [zoneDialogOpen, setZoneDialogOpen] = useState(false);
  const [editingZone, setEditingZone] = useState<Partial<CoverageZone> | null>(null);

  useEffect(() => {
    if (!tenant?.id) return;
    fetchZones();
  }, [tenant?.id]);

  const fetchZones = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from("dispatch_coverage_zones")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("priority_order");

      if (error) throw error;
      setZones((data || []).map((z: any) => ({
        ...z,
        county_names: Array.isArray(z.county_names) ? z.county_names : [],
      })) as CoverageZone[]);
    } catch (err) {
      console.error("Failed to fetch coverage zones:", err);
      toast({ title: "Error", description: "Failed to load coverage zones", variant: "destructive" });
    } finally {
      setIsLoading(false);
    }
  };

  const handleSaveZone = async () => {
    if (!tenant?.id || !editingZone) return;
    setIsSaving(true);
    try {
      const zoneData = {
        ...editingZone,
        tenant_id: tenant.id,
      };

      if (editingZone.id) {
        const { error } = await supabase.from("dispatch_coverage_zones").update(zoneData as any).eq("id", editingZone.id);
        if (error) throw error;
      } else {
        const { error } = await supabase.from("dispatch_coverage_zones").insert(zoneData as any);
        if (error) throw error;
      }

      await fetchZones();
      setZoneDialogOpen(false);
      setEditingZone(null);
      toast({ title: "Saved", description: "Coverage zone updated" });
    } catch (err) {
      console.error("Failed to save zone:", err);
      toast({ title: "Error", description: "Failed to save zone", variant: "destructive" });
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteZone = async (id: string) => {
    if (!confirm("Delete this coverage zone?")) return;
    try {
      const { error } = await supabase.from("dispatch_coverage_zones").delete().eq("id", id);
      if (error) throw error;
      setZones(prev => prev.filter(z => z.id !== id));
      toast({ title: "Deleted", description: "Coverage zone removed" });
    } catch (err) {
      console.error("Failed to delete zone:", err);
      toast({ title: "Error", description: "Failed to delete zone", variant: "destructive" });
    }
  };

  const zoneTypeIcons: Record<string, React.ReactNode> = {
    standard: <MapPin className="h-4 w-4" />,
    highway: <Route className="h-4 w-4" />,
    remote: <Mountain className="h-4 w-4" />,
    premium: <Gauge className="h-4 w-4" />,
  };

  const zoneTypeLabels: Record<string, string> = {
    standard: "Standard",
    highway: "Highway/Interstate",
    remote: "Remote Area",
    premium: "Premium Zone",
  };

  if (isLoading || distanceLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const generateAIPreview = () => {
    const baseMinutes = distanceSettings?.eta_base_minutes || 30;
    const busyBuffer = (distanceSettings as any)?.busy_buffer_minutes || 10;
    const trafficBuffer = (distanceSettings as any)?.traffic_buffer_percent || 15;
    
    const minEta = baseMinutes;
    const maxEta = Math.round(baseMinutes * (1 + trafficBuffer / 100)) + busyBuffer;
    
    return `Based on your location, I'm showing an estimated arrival of ${minEta} to ${maxEta} minutes. This can vary depending on traffic conditions.`;
  };

  return (
    <div className="space-y-6">
      {/* Explanation */}
      <div className="rounded-lg border bg-muted/30 p-4">
        <p className="text-sm text-muted-foreground">
          <strong>Why this matters:</strong> When someone calls, your AI uses your base address to calculate drive time and give an accurate ETA. 
          The busyness slider on your dashboard adds buffer time when you're slammed. Coverage zones let you set different pricing for highways, remote areas, or premium zones.
        </p>
      </div>

      <Tabs defaultValue="eta" className="w-full">
        <TabsList className="grid grid-cols-2 h-auto">
          <TabsTrigger value="eta" className="text-xs py-2">
            <Clock className="h-3 w-3 mr-1" />
            ETA Settings
          </TabsTrigger>
          <TabsTrigger value="zones" className="text-xs py-2">
            <MapPin className="h-3 w-3 mr-1" />
            Coverage Zones
          </TabsTrigger>
        </TabsList>

        {/* ETA Settings Tab */}
        <TabsContent value="eta" className="space-y-4 mt-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Clock className="h-4 w-4 text-blue-500" />
                ETA Calculation
              </CardTitle>
              <CardDescription>
                How arrival times are calculated and presented
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="grid gap-4 sm:grid-cols-2">
                <div className="space-y-2">
                  <Label>Base response time (minutes)</Label>
                  <Input
                    type="number"
                    min="5"
                    value={distanceSettings?.eta_base_minutes || 30}
                    onChange={(e) => saveDistanceSettings({ 
                      eta_base_minutes: parseInt(e.target.value) || 30 
                    })}
                    className="w-32"
                  />
                  <p className="text-xs text-muted-foreground">
                    Time before vehicle starts driving
                  </p>
                </div>

                <div className="space-y-2">
                  <Label>Max ETA to quote (minutes)</Label>
                  <Input
                    type="number"
                    min="30"
                    value={(distanceSettings as any)?.max_eta_minutes || 120}
                    onChange={(e) => saveDistanceSettings({ 
                      max_eta_minutes: parseInt(e.target.value) || 120 
                    } as any)}
                    className="w-32"
                  />
                  <p className="text-xs text-muted-foreground">
                    Beyond this, say "extended ETA"
                  </p>
                </div>
              </div>

              <Separator />

              <div className="space-y-4">
                <Label>Busy time buffer (minutes)</Label>
                <div className="flex items-center gap-4">
                  <Slider
                    value={[(distanceSettings as any)?.busy_buffer_minutes || 10]}
                    onValueChange={([v]) => saveDistanceSettings({ busy_buffer_minutes: v } as any)}
                    min={0}
                    max={30}
                    step={5}
                    className="flex-1"
                  />
                  <Badge variant="secondary" className="w-16 justify-center">
                    +{(distanceSettings as any)?.busy_buffer_minutes || 10} min
                  </Badge>
                </div>
                <p className="text-xs text-muted-foreground">
                  Extra time added when you're busy (controlled by busyness slider)
                </p>
              </div>

              <div className="space-y-4">
                <Label>Traffic buffer (%)</Label>
                <div className="flex items-center gap-4">
                  <Slider
                    value={[(distanceSettings as any)?.traffic_buffer_percent || 15]}
                    onValueChange={([v]) => saveDistanceSettings({ traffic_buffer_percent: v } as any)}
                    min={0}
                    max={50}
                    step={5}
                    className="flex-1"
                  />
                  <Badge variant="secondary" className="w-16 justify-center">
                    +{(distanceSettings as any)?.traffic_buffer_percent || 15}%
                  </Badge>
                </div>
                <p className="text-xs text-muted-foreground">
                  Safety margin for traffic variability
                </p>
              </div>

              <Separator />

              <div className="space-y-2">
                <Label>ETA rounding</Label>
                <Select
                  value={(distanceSettings as any)?.eta_rounding_mode || "nearest_5"}
                  onValueChange={(v) => saveDistanceSettings({ eta_rounding_mode: v } as any)}
                >
                  <SelectTrigger className="w-48">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="nearest_5">Round to 5 minutes</SelectItem>
                    <SelectItem value="nearest_10">Round to 10 minutes</SelectItem>
                    <SelectItem value="nearest_15">Round to 15 minutes</SelectItem>
                    <SelectItem value="exact">Exact (no rounding)</SelectItem>
                  </SelectContent>
                </Select>
                <p className="text-xs text-muted-foreground">
                  How ETAs are spoken (e.g., "about 30 minutes" vs "27 minutes")
                </p>
              </div>

              <div className="grid gap-4 sm:grid-cols-2 pt-2">
                <div className="space-y-2">
                  <Label>Highway response (minutes faster)</Label>
                  <Input
                    type="number"
                    min="0"
                    value={(distanceSettings as any)?.highway_response_faster_minutes || 10}
                    onChange={(e) => saveDistanceSettings({ 
                      highway_response_faster_minutes: parseInt(e.target.value) || 10 
                    } as any)}
                    className="w-32"
                  />
                  <p className="text-xs text-muted-foreground">
                    Faster ETA for highway locations
                  </p>
                </div>

                <div className="space-y-2">
                  <Label>Remote area buffer (minutes)</Label>
                  <Input
                    type="number"
                    min="0"
                    value={(distanceSettings as any)?.remote_area_buffer_minutes || 15}
                    onChange={(e) => saveDistanceSettings({ 
                      remote_area_buffer_minutes: parseInt(e.target.value) || 15 
                    } as any)}
                    className="w-32"
                  />
                  <p className="text-xs text-muted-foreground">
                    Extra time for rural/remote areas
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Coverage Zones Tab */}
        <TabsContent value="zones" className="space-y-4 mt-4">
          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <div>
                  <CardTitle className="text-base flex items-center gap-2">
                    <MapPin className="h-4 w-4 text-primary" />
                    Coverage Zones
                  </CardTitle>
                  <CardDescription>
                    Define zones with different pricing and ETA rules
                  </CardDescription>
                </div>
                <Button
                  size="sm"
                  onClick={() => {
                    setEditingZone({ ...DEFAULT_ZONE, priority_order: zones.length });
                    setZoneDialogOpen(true);
                  }}
                >
                  <Plus className="h-4 w-4 mr-1" />
                  Add Zone
                </Button>
              </div>
            </CardHeader>
            <CardContent>
              {zones.length === 0 ? (
                <div className="text-center py-6 text-muted-foreground">
                  <MapPin className="h-8 w-8 mx-auto mb-2 opacity-50" />
                  <p className="text-sm">No coverage zones configured</p>
                  <p className="text-xs">Use your service area settings, or add zones for custom pricing</p>
                </div>
              ) : (
                <div className="space-y-3">
                  {zones.map((zone) => (
                    <div
                      key={zone.id}
                      className={`flex items-center justify-between p-3 rounded-lg border ${
                        zone.is_active ? "bg-card" : "bg-muted/50 opacity-60"
                      }`}
                    >
                      <div className="flex items-center gap-3">
                        <div className="p-2 rounded-md bg-muted">
                          {zoneTypeIcons[zone.zone_type]}
                        </div>
                        <div>
                          <div className="flex items-center gap-2">
                            <span className="font-medium">{zone.zone_name}</span>
                            <Badge variant="outline" className="text-xs">
                              {zoneTypeLabels[zone.zone_type]}
                            </Badge>
                          </div>
                          <p className="text-xs text-muted-foreground">
                            {zone.definition_type === "radius" && `${zone.min_miles}-${zone.max_miles || "∞"} miles`}
                            {zone.definition_type === "highway" && zone.highway_numbers.join(", ")}
                            {zone.definition_type === "zip" && `${zone.zip_codes.length} ZIP codes`}
                          </p>
                        </div>
                      </div>
                      <div className="flex items-center gap-4">
                        <div className="text-right text-sm">
                          <p className="text-muted-foreground">
                            ~{zone.eta_base_minutes}+ min ETA
                          </p>
                        </div>
                        <div className="flex gap-1">
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => {
                              setEditingZone(zone);
                              setZoneDialogOpen(true);
                            }}
                          >
                            <Edit2 className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => handleDeleteZone(zone.id)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* AI Preview */}
      <AIPreviewCard 
        title="AI will say something like:" 
        preview={generateAIPreview()} 
      />

      {/* Zone Dialog */}
      <Dialog open={zoneDialogOpen} onOpenChange={setZoneDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{editingZone?.id ? "Edit Zone" : "Add Coverage Zone"}</DialogTitle>
            <DialogDescription>Configure zone boundaries and ETA rules</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4 max-h-[60vh] overflow-y-auto">
            <div className="space-y-2">
              <Label>Zone name</Label>
              <Input
                value={editingZone?.zone_name || ""}
                onChange={(e) => setEditingZone(prev => ({ ...prev, zone_name: e.target.value }))}
                placeholder="e.g., Local, Extended, Highway I-95"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label>Zone type</Label>
                <Select
                  value={editingZone?.zone_type || "standard"}
                  onValueChange={(v) => setEditingZone(prev => ({ 
                    ...prev, 
                    zone_type: v as CoverageZone["zone_type"]
                  }))}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="standard">Standard</SelectItem>
                    <SelectItem value="highway">Highway/Interstate</SelectItem>
                    <SelectItem value="remote">Remote Area</SelectItem>
                    <SelectItem value="premium">Premium Zone</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Defined by</Label>
                <Select
                  value={editingZone?.definition_type || "radius"}
                  onValueChange={(v) => setEditingZone(prev => ({ 
                    ...prev, 
                    definition_type: v as CoverageZone["definition_type"]
                  }))}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="radius">Distance (miles)</SelectItem>
                    <SelectItem value="highway">Highway numbers</SelectItem>
                    <SelectItem value="zip">ZIP codes</SelectItem>
                    <SelectItem value="county">Counties</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            {editingZone?.definition_type === "radius" && (
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-2">
                  <Label>Min miles</Label>
                  <Input
                    type="number"
                    min="0"
                    value={editingZone?.min_miles ?? 0}
                    onChange={(e) => setEditingZone(prev => ({ 
                      ...prev, 
                      min_miles: parseFloat(e.target.value) || 0 
                    }))}
                  />
                </div>
                <div className="space-y-2">
                  <Label>Max miles</Label>
                  <Input
                    type="number"
                    min="0"
                    value={editingZone?.max_miles ?? ""}
                    onChange={(e) => setEditingZone(prev => ({ 
                      ...prev, 
                      max_miles: e.target.value ? parseFloat(e.target.value) : null 
                    }))}
                    placeholder="No limit"
                  />
                </div>
              </div>
            )}

            {editingZone?.definition_type === "highway" && (
              <div className="space-y-2">
                <Label>Highway numbers (comma-separated)</Label>
                <Input
                  value={(editingZone?.highway_numbers || []).join(", ")}
                  onChange={(e) => setEditingZone(prev => ({ 
                    ...prev, 
                    highway_numbers: e.target.value.split(",").map(s => s.trim()).filter(Boolean)
                  }))}
                  placeholder="I-95, US-1, SR-436"
                />
              </div>
            )}

            <Separator />

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label>Base ETA (minutes)</Label>
                <Input
                  type="number"
                  min="5"
                  value={editingZone?.eta_base_minutes ?? 30}
                  onChange={(e) => setEditingZone(prev => ({ 
                    ...prev, 
                    eta_base_minutes: parseInt(e.target.value) || 30 
                  }))}
                />
              </div>
              <div className="space-y-2">
                <Label>Per-mile (minutes)</Label>
                <Input
                  type="number"
                  min="0"
                  step="0.5"
                  value={editingZone?.eta_per_mile_minutes ?? 2}
                  onChange={(e) => setEditingZone(prev => ({ 
                    ...prev, 
                    eta_per_mile_minutes: parseFloat(e.target.value) || 2 
                  }))}
                />
              </div>
            </div>

            <div className="flex items-center justify-between pt-2">
              <Label>Available 24/7</Label>
              <Switch
                checked={editingZone?.available_24_7 ?? true}
                onCheckedChange={(checked) => setEditingZone(prev => ({ ...prev, available_24_7: checked }))}
              />
            </div>

            <div className="flex items-center justify-between">
              <Label>Active</Label>
              <Switch
                checked={editingZone?.is_active ?? true}
                onCheckedChange={(checked) => setEditingZone(prev => ({ ...prev, is_active: checked }))}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setZoneDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSaveZone} disabled={isSaving || !editingZone?.zone_name}>
              {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Save Zone
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Dispatch Policies Editor
 * For towing, roadside assistance, emergency services
 * Handles payment, cancellation, storage, release, and liability policies
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, Save, CreditCard, XCircle, Warehouse, Key, Shield, Siren } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { AIPreviewCard } from "../AIPreviewCard";

interface DispatchPolicies {
  id?: string;
  tenant_id: string;
  // Payment
  payment_due_at_service: boolean;
  accepted_payment_methods: string[];
  cash_only_after_hours: boolean;
  prepayment_required: boolean;
  // Cancellation
  cancel_after_dispatch_fee_cents: number;
  cancel_en_route_fee_cents: number;
  cancel_on_scene_fee_cents: number;
  // Storage
  storage_daily_rate_cents: number;
  storage_max_days: number;
  storage_grace_period_hours: number;
  storage_lien_sale_days: number;
  // Release
  release_requires_id: boolean;
  release_requires_registration: boolean;
  release_requires_title: boolean;
  release_requires_insurance: boolean;
  release_authorized_agent_allowed: boolean;
  release_police_hold_policy: string;
  // Liability
  damage_waiver_text: string;
  pre_existing_damage_policy: string;
  liability_limit_cents: number;
  insurance_requirement_text: string;
  // Keys/lockout
  lockout_attempt_limit: number;
  lockout_disclaimer: string;
  spare_key_policy: string;
  // Priority
  priority_fee_percentage: number;
  emergency_surcharge_cents: number;
}

const DEFAULT_POLICIES: Omit<DispatchPolicies, 'tenant_id'> = {
  payment_due_at_service: true,
  accepted_payment_methods: ['cash', 'card'],
  cash_only_after_hours: false,
  prepayment_required: false,
  cancel_after_dispatch_fee_cents: 5000,
  cancel_en_route_fee_cents: 7500,
  cancel_on_scene_fee_cents: 10000,
  storage_daily_rate_cents: 5000,
  storage_max_days: 30,
  storage_grace_period_hours: 24,
  storage_lien_sale_days: 45,
  release_requires_id: true,
  release_requires_registration: true,
  release_requires_title: false,
  release_requires_insurance: false,
  release_authorized_agent_allowed: true,
  release_police_hold_policy: '',
  damage_waiver_text: '',
  pre_existing_damage_policy: '',
  liability_limit_cents: 0,
  insurance_requirement_text: '',
  lockout_attempt_limit: 2,
  lockout_disclaimer: '',
  spare_key_policy: '',
  priority_fee_percentage: 0,
  emergency_surcharge_cents: 0,
};

const PAYMENT_METHODS = [
  { id: 'cash', label: 'Cash' },
  { id: 'card', label: 'Credit/Debit Card' },
  { id: 'check', label: 'Check' },
  { id: 'venmo', label: 'Venmo' },
  { id: 'zelle', label: 'Zelle' },
  { id: 'invoice', label: 'Invoice (approved accounts)' },
];

export function DispatchPoliciesEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState<DispatchPolicies | null>(null);

  useEffect(() => {
    if (tenant?.id) {
      loadPolicies();
    }
  }, [tenant?.id]);

  const loadPolicies = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('dispatch_policies')
        .select('*')
        .eq('tenant_id', tenant.id)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') throw error;
      
      setFormData(data || { ...DEFAULT_POLICIES, tenant_id: tenant.id });
    } catch (err: any) {
      toast.error("Failed to load policies");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id || !formData) return;
    setIsSaving(true);
    try {
      const { error } = await supabase
        .from('dispatch_policies')
        .upsert({
          ...formData,
          tenant_id: tenant.id,
        }, { onConflict: 'tenant_id' });

      if (error) throw error;
      toast.success("Policies saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const updateField = <K extends keyof DispatchPolicies>(field: K, value: DispatchPolicies[K]) => {
    setFormData(prev => prev ? { ...prev, [field]: value } : null);
  };

  const togglePaymentMethod = (method: string) => {
    const current = formData?.accepted_payment_methods || [];
    if (current.includes(method)) {
      updateField('accepted_payment_methods', current.filter(m => m !== method));
    } else {
      updateField('accepted_payment_methods', [...current, method]);
    }
  };

  const formatCents = (cents: number) => cents > 0 ? `$${(cents / 100).toFixed(0)}` : '$0';

  // Build AI preview
  const buildAIPreview = (): string => {
    if (!formData) return "";
    const parts: string[] = [];
    
    if (formData.payment_due_at_service) {
      parts.push("Payment is due at time of service.");
    }
    if (formData.cancel_after_dispatch_fee_cents > 0) {
      parts.push(`Cancellation after dispatch incurs a ${formatCents(formData.cancel_after_dispatch_fee_cents)} fee.`);
    }
    if (formData.storage_daily_rate_cents > 0) {
      parts.push(`Storage is ${formatCents(formData.storage_daily_rate_cents)} per day.`);
    }
    
    return parts.length > 0 ? parts.join(' ') : "No specific dispatch policies configured yet.";
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!formData) return null;

  return (
    <div className="space-y-6">
      {/* Explanation */}
      <div className="rounded-lg border bg-muted/30 p-4">
        <p className="text-sm text-muted-foreground">
          <strong>Why this matters:</strong> Your AI explains these policies to callers before issues arise. 
          Clear policies about payment, cancellation, and vehicle release prevent disputes and set expectations.
        </p>
      </div>

      {/* AI Preview */}
      <AIPreviewCard 
        title="How AI explains your dispatch policies"
        preview={buildAIPreview()}
      />

      {/* Payment Terms */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <CreditCard className="h-4 w-4" />
            Payment Terms
          </CardTitle>
          <CardDescription>
            When and how customers pay
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <Label>Payment Due at Service</Label>
              <p className="text-xs text-muted-foreground">Collect payment when job is complete</p>
            </div>
            <Switch
              checked={formData.payment_due_at_service}
              onCheckedChange={(v) => updateField('payment_due_at_service', v)}
            />
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Prepayment Required</Label>
              <p className="text-xs text-muted-foreground">Require payment before dispatching</p>
            </div>
            <Switch
              checked={formData.prepayment_required}
              onCheckedChange={(v) => updateField('prepayment_required', v)}
            />
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Cash Only After Hours</Label>
              <p className="text-xs text-muted-foreground">No cards accepted for after-hours calls</p>
            </div>
            <Switch
              checked={formData.cash_only_after_hours}
              onCheckedChange={(v) => updateField('cash_only_after_hours', v)}
            />
          </div>

          <div className="space-y-2">
            <Label>Accepted Payment Methods</Label>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
              {PAYMENT_METHODS.map((method) => (
                <label key={method.id} className="flex items-center gap-2 cursor-pointer">
                  <Checkbox
                    checked={formData.accepted_payment_methods.includes(method.id)}
                    onCheckedChange={() => togglePaymentMethod(method.id)}
                  />
                  <span className="text-sm">{method.label}</span>
                </label>
              ))}
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Cancellation Fees */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <XCircle className="h-4 w-4" />
            Cancellation Fees
          </CardTitle>
          <CardDescription>
            Charges when customer cancels after dispatch
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-3 gap-4">
            <div className="space-y-2">
              <Label>After Dispatch</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.cancel_after_dispatch_fee_cents / 100}
                  onChange={(e) => updateField('cancel_after_dispatch_fee_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                />
              </div>
              <p className="text-xs text-muted-foreground">After driver assigned</p>
            </div>

            <div className="space-y-2">
              <Label>En Route</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.cancel_en_route_fee_cents / 100}
                  onChange={(e) => updateField('cancel_en_route_fee_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                />
              </div>
              <p className="text-xs text-muted-foreground">Driver is on the way</p>
            </div>

            <div className="space-y-2">
              <Label>On Scene</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.cancel_on_scene_fee_cents / 100}
                  onChange={(e) => updateField('cancel_on_scene_fee_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                />
              </div>
              <p className="text-xs text-muted-foreground">Driver has arrived</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Storage Policies */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Warehouse className="h-4 w-4" />
            Storage Policies
          </CardTitle>
          <CardDescription>
            Impound lot and storage rules
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Daily Storage Rate</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.storage_daily_rate_cents / 100}
                  onChange={(e) => updateField('storage_daily_rate_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Grace Period</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.storage_grace_period_hours}
                  onChange={(e) => updateField('storage_grace_period_hours', parseInt(e.target.value || '0'))}
                />
                <span className="flex items-center text-sm text-muted-foreground">hours</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Max Storage Days</Label>
              <Input
                type="number"
                value={formData.storage_max_days}
                onChange={(e) => updateField('storage_max_days', parseInt(e.target.value || '0'))}
              />
            </div>

            <div className="space-y-2">
              <Label>Lien Sale After</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.storage_lien_sale_days}
                  onChange={(e) => updateField('storage_lien_sale_days', parseInt(e.target.value || '0'))}
                />
                <span className="flex items-center text-sm text-muted-foreground">days</span>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Release Requirements */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Key className="h-4 w-4" />
            Vehicle Release Requirements
          </CardTitle>
          <CardDescription>
            Documents needed to release a vehicle
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <label className="flex items-center gap-2 cursor-pointer">
              <Checkbox
                checked={formData.release_requires_id}
                onCheckedChange={(v) => updateField('release_requires_id', !!v)}
              />
              <span className="text-sm">Valid ID Required</span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer">
              <Checkbox
                checked={formData.release_requires_registration}
                onCheckedChange={(v) => updateField('release_requires_registration', !!v)}
              />
              <span className="text-sm">Registration Required</span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer">
              <Checkbox
                checked={formData.release_requires_title}
                onCheckedChange={(v) => updateField('release_requires_title', !!v)}
              />
              <span className="text-sm">Title Required</span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer">
              <Checkbox
                checked={formData.release_requires_insurance}
                onCheckedChange={(v) => updateField('release_requires_insurance', !!v)}
              />
              <span className="text-sm">Proof of Insurance</span>
            </label>
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Allow Authorized Agent</Label>
              <p className="text-xs text-muted-foreground">Someone other than owner can pick up</p>
            </div>
            <Switch
              checked={formData.release_authorized_agent_allowed}
              onCheckedChange={(v) => updateField('release_authorized_agent_allowed', v)}
            />
          </div>

          <div className="space-y-2">
            <Label>Police Hold Policy</Label>
            <Textarea
              value={formData.release_police_hold_policy}
              onChange={(e) => updateField('release_police_hold_policy', e.target.value)}
              placeholder="Vehicles on police hold cannot be released until the hold is lifted. Contact [police department] for hold status."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Liability */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Shield className="h-4 w-4" />
            Liability & Damage
          </CardTitle>
          <CardDescription>
            Waivers and damage disclaimers
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Pre-Existing Damage Policy</Label>
            <Textarea
              value={formData.pre_existing_damage_policy}
              onChange={(e) => updateField('pre_existing_damage_policy', e.target.value)}
              placeholder="We document all visible damage before towing. Photos are taken for your records."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Damage Waiver (for AI to explain)</Label>
            <Textarea
              value={formData.damage_waiver_text}
              onChange={(e) => updateField('damage_waiver_text', e.target.value)}
              placeholder="Towing inherently involves some risk. We take every precaution but cannot be held responsible for pre-existing mechanical issues."
              rows={2}
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Liability Limit</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.liability_limit_cents / 100}
                  onChange={(e) => updateField('liability_limit_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                  placeholder="0 = no limit"
                />
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <Label>Insurance Information</Label>
            <Textarea
              value={formData.insurance_requirement_text}
              onChange={(e) => updateField('insurance_requirement_text', e.target.value)}
              placeholder="We carry $1M liability coverage. Certificate available on request."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Lockout Services */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Key className="h-4 w-4" />
            Lockout Services
          </CardTitle>
          <CardDescription>
            Key and lockout service policies
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Maximum Unlock Attempts</Label>
            <Input
              type="number"
              className="w-24"
              value={formData.lockout_attempt_limit}
              onChange={(e) => updateField('lockout_attempt_limit', parseInt(e.target.value || '2'))}
            />
            <p className="text-xs text-muted-foreground">Before recommending locksmith</p>
          </div>

          <div className="space-y-2">
            <Label>Lockout Disclaimer</Label>
            <Textarea
              value={formData.lockout_disclaimer}
              onChange={(e) => updateField('lockout_disclaimer', e.target.value)}
              placeholder="We'll try our best, but some modern vehicles require a locksmith with specialized equipment."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Spare Key Policy</Label>
            <Textarea
              value={formData.spare_key_policy}
              onChange={(e) => updateField('spare_key_policy', e.target.value)}
              placeholder="We do not provide spare keys. Once unlocked, you'll need to contact your dealer for replacement keys."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Priority & Emergency */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Siren className="h-4 w-4" />
            Priority & Emergency Fees
          </CardTitle>
          <CardDescription>
            Rush and emergency surcharges
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Priority Service Premium</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.priority_fee_percentage}
                  onChange={(e) => updateField('priority_fee_percentage', parseInt(e.target.value || '0'))}
                  placeholder="0"
                />
                <span className="flex items-center text-sm text-muted-foreground">%</span>
              </div>
              <p className="text-xs text-muted-foreground">Extra for "jump the queue"</p>
            </div>

            <div className="space-y-2">
              <Label>Emergency Surcharge</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.emergency_surcharge_cents / 100}
                  onChange={(e) => updateField('emergency_surcharge_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                />
              </div>
              <p className="text-xs text-muted-foreground">For true emergencies</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end pt-2">
        <Button onClick={handleSave} disabled={isSaving}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Dispatch Policies
        </Button>
      </div>
    </div>
  );
}

