import { toast } from "sonner";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Plus,
  Search,
  ChevronDown,
  ChevronRight,
  Pencil,
  Copy,
  Trash2,
  MoreHorizontal,
  DollarSign,
  Clock,
  Loader2,
  Sparkles,
  Truck,
} from "lucide-react";
import { updateService, deleteService, createService } from "@/lib/brain/writeBrainFact";
import { DispatchServiceEditor } from "./DispatchServiceEditor";
import {
  DISPATCH_CATEGORIES,
  type DispatchServiceCategory,
  type DispatchPricingConfig,
  generatePricingSummary,
} from "@/types/dispatchPricing";

interface GroupedServices {
  category: DispatchServiceCategory;
  label: string;
  services: any[];
  order: number;
}

export function DispatchServiceCatalog() {
  const { tenant } = useAuth();
  const { services, isLoading } = useServices();
  const queryClient = useQueryClient();

  const [searchQuery, setSearchQuery] = useState("");
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set(["towing", "roadside"]));
  const [editorOpen, setEditorOpen] = useState(false);
  const [editingService, setEditingService] = useState<any | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingService, setDeletingService] = useState<any | null>(null);

  // Group services by category
  const groupedServices = useMemo(() => {
    if (!services) return [];

    const filtered = searchQuery
      ? services.filter(
          (s) =>
            s.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
            s.description?.toLowerCase().includes(searchQuery.toLowerCase())
        )
      : services;

    const groups: Record<string, GroupedServices> = {};

    for (const service of filtered) {
      const category = (service.service_category as DispatchServiceCategory) || "uncategorized";
      const categoryInfo = DISPATCH_CATEGORIES[category] || DISPATCH_CATEGORIES.uncategorized;

      if (!groups[category]) {
        groups[category] = {
          category,
          label: categoryInfo.label,
          services: [],
          order: categoryInfo.order,
        };
      }
      groups[category].services.push(service);
    }

    return Object.values(groups).sort((a, b) => a.order - b.order);
  }, [services, searchQuery]);

  const toggleCategory = (category: string) => {
    setExpandedCategories((prev) => {
      const next = new Set(prev);
      if (next.has(category)) {
        next.delete(category);
      } else {
        next.add(category);
      }
      return next;
    });
  };

  const handleToggleActive = async (service: any) => {
    if (!tenant?.id) return;
    try {
      await updateService(service.id, tenant.id, { is_active: !service.is_active });
      toast.success(service.is_active ? "Service deactivated" : "Service activated");
      queryClient.invalidateQueries({ queryKey: ["services"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to update service");
    }
  };

  const handleDuplicate = async (service: any) => {
    if (!tenant?.id) return;
    try {
      const pricingConfig = service.pricing_config_json as Record<string, unknown> | null;
      await createService(tenant.id, {
        name: `${service.name} (Copy)`,
        description: service.description,
        duration_minutes: service.duration_minutes,
        price_type: service.price_type,
        price_amount: service.price_amount,
        service_category: service.service_category,
        service_type: service.service_type,
        pricing_config_json: pricingConfig || undefined,
      });
      toast.success("Service duplicated");
      queryClient.invalidateQueries({ queryKey: ["services"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to duplicate service");
    }
  };

  const handleDelete = async () => {
    if (!tenant?.id || !deletingService) return;
    try {
      await deleteService(deletingService.id, tenant.id);
      toast.success("Service deleted");
      queryClient.invalidateQueries({ queryKey: ["services"] });
      setDeleteDialogOpen(false);
      setDeletingService(null);
    } catch (error: any) {
      toast.error(error.message || "Failed to delete service");
    }
  };

  const formatPrice = (service: any) => {
    // Safely cast the JSONB to our config type
    const rawConfig = service.pricing_config_json;
    const config: DispatchPricingConfig | null =
      rawConfig && typeof rawConfig === "object" && "pricing_model" in rawConfig
        ? (rawConfig as unknown as DispatchPricingConfig)
        : null;

    if (config?.pricing_model === "distance_tiered" && config.distance_tiers?.length) {
      const first = config.distance_tiers[0];
      const hasPerMile = config.distance_tiers.some(t => t.per_mile_price && t.per_mile_price > 0);
      return `$${first.base_price}${hasPerMile ? " + mi" : ""}`;
    }

    if (config?.pricing_model === "per_unit" && config.per_unit_price) {
      return `$${config.per_unit_price}/${config.unit_label || "unit"}`;
    }

    if (config?.pricing_model === "package" && config.packages?.length) {
      const prices = config.packages.map(p => p.price);
      return `$${Math.min(...prices)}-$${Math.max(...prices)}`;
    }

    if (service.price_type === "quote_only") return "Quote";
    if (!service.price_amount && !config?.min_price) return "Quote";

    const price = service.price_amount || config?.min_price || 0;
    const prefix = service.price_type === "starting_at" ? "From " : "";
    return `${prefix}$${price}`;
  };

  const getPricingModelBadge = (service: any): string | null => {
    const rawConfig = service.pricing_config_json;
    if (!rawConfig || typeof rawConfig !== "object" || !("pricing_model" in rawConfig)) return null;
    const model = (rawConfig as any).pricing_model;
    switch (model) {
      case "flat": return "Fixed";
      case "distance_tiered": return "Distance";
      case "per_unit": return `Per ${(rawConfig as any).unit_label || "Unit"}`;
      case "package": return "Packages";
      case "variable": return "Quote";
      default: return null;
    }
  };

  const formatDuration = (minutes: number) => {
    if (minutes < 60) return `${minutes}m`;
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return mins ? `${hours}h ${mins}m` : `${hours}h`;
  };

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="ml-3 text-sm text-muted-foreground">Loading services...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Build AI quote preview
  const activeServices = services?.filter(s => s.is_active) || [];
  const firstService = activeServices[0];
  const firstPricingConfig = firstService?.pricing_config_json as unknown as DispatchPricingConfig | null;
  const aiQuotePreview = firstService
    ? generatePricingSummary(firstPricingConfig, firstService.name)
    : "I can help you with our range of services. What do you need assistance with?";

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between gap-4">
        <div className="flex-1">
          <h3 className="text-lg font-semibold">Dispatch Services</h3>
          <p className="text-sm text-muted-foreground">
            {activeServices.length > 0
              ? `${activeServices.length} active service${activeServices.length !== 1 ? "s" : ""} across ${groupedServices.length} categor${groupedServices.length !== 1 ? "ies" : "y"}`
              : "Add your services so the AI can quote callers accurately"
            }
          </p>
        </div>
        <Button onClick={() => { setEditingService(null); setEditorOpen(true); }}>
          <Plus className="h-4 w-4 mr-2" />
          Add Service
        </Button>
      </div>

      {/* Search */}
      {services && services.length > 5 && (
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search services..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9"
          />
        </div>
      )}

      {/* Category Groups */}
      {groupedServices.length > 0 ? (
        <div className="space-y-3">
          {groupedServices.map((group) => (
            <Collapsible
              key={group.category}
              open={expandedCategories.has(group.category)}
              onOpenChange={() => toggleCategory(group.category)}
            >
              <Card>
                <CollapsibleTrigger asChild>
                  <CardHeader className="cursor-pointer hover:bg-muted/50 transition-colors py-3">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        {expandedCategories.has(group.category) ? (
                          <ChevronDown className="h-4 w-4 text-muted-foreground" />
                        ) : (
                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
                        )}
                        <CardTitle className="text-base">{group.label}</CardTitle>
                        <Badge variant="secondary" className="text-xs">
                          {group.services.length}
                        </Badge>
                      </div>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={(e) => {
                          e.stopPropagation();
                          setEditingService(null);
                          setEditorOpen(true);
                        }}
                      >
                        <Plus className="h-3 w-3 mr-1" />
                        Add
                      </Button>
                    </div>
                  </CardHeader>
                </CollapsibleTrigger>
                <CollapsibleContent>
                  <CardContent className="pt-0 pb-3">
                    <div className="divide-y">
                      {group.services.map((service) => (
                        <div
                          key={service.id}
                          role="button"
                          tabIndex={0}
                          onClick={() => {
                            setEditingService(service);
                            setEditorOpen(true);
                          }}
                          onKeyDown={(e) => {
                            if (e.key === "Enter" || e.key === " ") {
                              e.preventDefault();
                              setEditingService(service);
                              setEditorOpen(true);
                            }
                          }}
                          className={`w-full flex items-center justify-between py-3 gap-4 text-left cursor-pointer hover:bg-muted/30 transition-colors rounded-md px-2 -mx-2 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 focus:ring-offset-background ${
                            !service.is_active ? "opacity-50" : ""
                          }`}
                        >
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2">
                              <span className="font-medium truncate">{service.name}</span>
                              {getPricingModelBadge(service) && (
                                <Badge variant="secondary" className="text-xs shrink-0">
                                  {getPricingModelBadge(service)}
                                </Badge>
                              )}
                              {!service.is_active && (
                                <Badge variant="outline" className="text-xs">Inactive</Badge>
                              )}
                            </div>
                            {service.description && (
                              <p className="text-sm text-muted-foreground truncate">
                                {service.description}
                                {(service.pricing_config_json as any)?.trip_fee?.enabled && (
                                  <span className="ml-1 text-xs"> + ${(service.pricing_config_json as any).trip_fee.amount} {(service.pricing_config_json as any).trip_fee.label.toLowerCase()}</span>
                                )}
                              </p>
                            )}
                          </div>

                          <div className="flex items-center gap-4 shrink-0">
                            <div className="flex items-center gap-2 text-sm">
                              <DollarSign className="h-3.5 w-3.5 text-muted-foreground" />
                              <span className="font-medium">{formatPrice(service)}</span>
                            </div>
                            <div className="flex items-center gap-1 text-sm text-muted-foreground">
                              <Clock className="h-3.5 w-3.5" />
                              <span>{formatDuration(service.duration_minutes)}</span>
                            </div>

                            <div onClick={(e) => e.stopPropagation()}>
                              <Switch
                                checked={service.is_active}
                                onCheckedChange={() => handleToggleActive(service)}
                              />
                            </div>

                            <DropdownMenu>
                              <DropdownMenuTrigger asChild>
                                <Button
                                  variant="ghost"
                                  size="icon"
                                  className="h-8 w-8"
                                  onClick={(e) => e.stopPropagation()}
                                >
                                  <MoreHorizontal className="h-4 w-4" />
                                </Button>
                              </DropdownMenuTrigger>
                              <DropdownMenuContent align="end">
                                <DropdownMenuItem
                                  onClick={() => {
                                    setEditingService(service);
                                    setEditorOpen(true);
                                  }}
                                >
                                  <Pencil className="h-4 w-4 mr-2" />
                                  Edit
                                </DropdownMenuItem>
                                <DropdownMenuItem onClick={() => handleDuplicate(service)}>
                                  <Copy className="h-4 w-4 mr-2" />
                                  Duplicate
                                </DropdownMenuItem>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem
                                  className="text-destructive"
                                  onClick={() => {
                                    setDeletingService(service);
                                    setDeleteDialogOpen(true);
                                  }}
                                >
                                  <Trash2 className="h-4 w-4 mr-2" />
                                  Delete
                                </DropdownMenuItem>
                              </DropdownMenuContent>
                            </DropdownMenu>
                          </div>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </CollapsibleContent>
              </Card>
            </Collapsible>
          ))}
        </div>
      ) : services && services.length === 0 ? (
        <Card>
          <CardContent className="p-12 text-center">
            <div className="flex flex-col items-center gap-3">
              <div className="h-16 w-16 rounded-full bg-muted flex items-center justify-center">
                <Truck className="h-8 w-8 text-muted-foreground" />
              </div>
              <h3 className="font-semibold text-lg">No dispatch services yet</h3>
              <p className="text-sm text-muted-foreground max-w-md">
                Your AI needs to know what services you offer and how much they cost. 
                Start with common presets like <strong>Local Tow</strong>, <strong>Jump Start</strong>, 
                <strong>Lockout</strong>, <strong>Tire Change</strong>, or <strong>Fuel Delivery</strong>.
              </p>
              <p className="text-xs text-muted-foreground max-w-md">
                You can set flat rates or distance-based pricing with per-mile charges. 
                The AI will automatically calculate and quote prices based on the caller's location.
              </p>
              <Button onClick={() => setEditorOpen(true)} className="mt-2">
                <Plus className="h-4 w-4 mr-2" />
                Add Your First Service
              </Button>
            </div>
          </CardContent>
        </Card>
      ) : searchQuery ? (
        <Card>
          <CardContent className="p-8 text-center">
            <p className="text-muted-foreground">No services match "{searchQuery}"</p>
          </CardContent>
        </Card>
      ) : null}

      {/* Service Editor Dialog */}
      <DispatchServiceEditor
        open={editorOpen}
        onOpenChange={setEditorOpen}
        editingService={editingService}
        onSuccess={() => setEditingService(null)}
      />

      {/* Delete Confirmation */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Service</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete "{deletingService?.name}"? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-destructive text-destructive-foreground"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useLayoutEffect, useState, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useServices } from "@/hooks/useServices";
import { useQueryClient } from "@tanstack/react-query";
import { useTenantDistanceSettings } from "@/hooks/useTenantDistanceSettings";
import { useServiceArea } from "@/hooks/useServiceArea";
import { toast } from "sonner";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import { Slider } from "@/components/ui/slider";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Truck,
  Zap,
  Key,
  Fuel,
  CircleDot,
  Anchor,
  Plus,
  Trash2,
  DollarSign,
  Loader2,
  Info,
  Sparkles,
  Wrench,
  Thermometer,
  Bug,
  Leaf,
  Hammer,
  Waves,
  Settings,
  Heart,
  Monitor,
  Droplets,
  Package,
  Star,
} from "lucide-react";
import { createService, updateService } from "@/lib/brain/writeBrainFact";
import {
  DISPATCH_SERVICE_PRESETS,
  DISPATCH_CATEGORIES,
  VEHICLE_TYPES,
  DISTANCE_BASIS_OPTIONS,
  UNIT_LABEL_OPTIONS,
  PRESET_CATEGORY_TABS,
  type DispatchPricingConfig,
  type DistanceTier,
  type DistanceBasis,
  type DispatchServiceCategory,
  type DispatchServiceType,
  type PresetCategoryTab,
  type PackageTier,
  type AIQuoteBehavior,
  generatePricingSummary,
  calculateScenarioQuotes,
  calculateDispatchPrice,
} from "@/types/dispatchPricing";

interface DispatchServiceFormData {
  name: string;
  description: string;
  duration_minutes: number;
  service_category: DispatchServiceCategory;
  service_type: DispatchServiceType | null;
  pricing_config: DispatchPricingConfig;
  price_amount: number | null;
  price_type: "fixed" | "starting_at" | "quote_only";
  requires_dropoff: boolean;
}

const defaultFormData: DispatchServiceFormData = {
  name: "",
  description: "",
  duration_minutes: 60,
  service_category: "uncategorized",
  service_type: null,
  pricing_config: {
    pricing_model: "flat",
    min_price: 0,
  },
  price_amount: null,
  price_type: "starting_at",
  requires_dropoff: true,
};

const PRESET_ICONS: Record<string, React.ReactNode> = {
  truck: <Truck className="h-5 w-5" />,
  zap: <Zap className="h-5 w-5" />,
  key: <Key className="h-5 w-5" />,
  fuel: <Fuel className="h-5 w-5" />,
  circle: <CircleDot className="h-5 w-5" />,
  anchor: <Anchor className="h-5 w-5" />,
  wrench: <Wrench className="h-5 w-5" />,
  thermometer: <Thermometer className="h-5 w-5" />,
  sparkles: <Sparkles className="h-5 w-5" />,
  bug: <Bug className="h-5 w-5" />,
  leaf: <Leaf className="h-5 w-5" />,
  hammer: <Hammer className="h-5 w-5" />,
  waves: <Waves className="h-5 w-5" />,
  settings: <Settings className="h-5 w-5" />,
  heart: <Heart className="h-5 w-5" />,
  monitor: <Monitor className="h-5 w-5" />,
  droplets: <Droplets className="h-5 w-5" />,
  trash: <Trash2 className="h-5 w-5" />,
  container: <Package className="h-5 w-5" />,
  package: <Package className="h-5 w-5" />,
};

interface DispatchServiceEditorProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editingService?: any;
  onSuccess?: () => void;
}

export function DispatchServiceEditor({
  open,
  onOpenChange,
  editingService,
  onSuccess,
}: DispatchServiceEditorProps) {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [step, setStep] = useState(1);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState<DispatchServiceFormData>(defaultFormData);
  const [presetTab, setPresetTab] = useState<PresetCategoryTab>("towing_roadside");
  const { settings: distanceSettings } = useTenantDistanceSettings();
  const { serviceArea } = useServiceArea();

  // IMPORTANT: This editor is controlled by the parent (open prop).
  // Radix Dialog does not always fire onOpenChange when parent toggles `open`,
  // so we must hydrate/reset the form in an effect.
  useLayoutEffect(() => {
    if (!open) return;

    setIsSaving(false);

    if (editingService) {
      const pricingConfig = editingService.pricing_config_json as DispatchPricingConfig | null;
      setFormData({
        name: editingService.name || "",
        description: editingService.description || "",
        duration_minutes: editingService.duration_minutes || 60,
        service_category: (editingService.service_category as DispatchServiceCategory) || "uncategorized",
        service_type: editingService.service_type || null,
        pricing_config: pricingConfig || { pricing_model: "flat", min_price: editingService.price_amount || 0 },
        price_amount: editingService.price_amount,
        price_type: editingService.price_type || "starting_at",
        requires_dropoff: editingService.requires_dropoff !== false,
      });
      setStep(2);
    } else {
      setFormData(defaultFormData);
      setStep(1);
    }
  }, [open, editingService]);

  const handleOpenChange = (newOpen: boolean) => {
    if (!newOpen) {
      // Reset so the next open is always clean/hydrated by the effect above.
      setIsSaving(false);
      setFormData(defaultFormData);
      setStep(1);
    }
    onOpenChange(newOpen);
  };

  const applyPreset = (preset: typeof DISPATCH_SERVICE_PRESETS[0]) => {
    setFormData({
      ...formData,
      name: preset.name,
      description: preset.description,
      duration_minutes: preset.defaultDuration,
      service_category: preset.category,
      service_type: preset.type,
      pricing_config: preset.defaultPricingConfig,
      price_amount: preset.defaultPricingConfig.min_price || null,
      price_type: preset.defaultPricingConfig.pricing_model === "flat" ? "fixed" : "starting_at",
      requires_dropoff: preset.requires_dropoff,
    });
    setStep(2);
  };

  const addDistanceTier = () => {
    const tiers = formData.pricing_config.distance_tiers || [];
    const lastTier = tiers[tiers.length - 1];
    const newTier: DistanceTier = {
      min_miles: lastTier ? (lastTier.max_miles || 0) : 0,
      max_miles: lastTier ? (lastTier.max_miles || 0) + 10 : 10,
      base_price: lastTier?.base_price || 100,
      per_mile_price: 5,
    };
    setFormData({
      ...formData,
      pricing_config: {
        ...formData.pricing_config,
        distance_tiers: [...tiers, newTier],
      },
    });
  };

  const updateDistanceTier = (index: number, updates: Partial<DistanceTier>) => {
    const tiers = [...(formData.pricing_config.distance_tiers || [])];
    tiers[index] = { ...tiers[index], ...updates };
    setFormData({
      ...formData,
      pricing_config: {
        ...formData.pricing_config,
        distance_tiers: tiers,
      },
    });
  };

  const removeDistanceTier = (index: number) => {
    const tiers = formData.pricing_config.distance_tiers?.filter((_, i) => i !== index) || [];
    setFormData({
      ...formData,
      pricing_config: {
        ...formData.pricing_config,
        distance_tiers: tiers,
      },
    });
  };

  const handleSave = async () => {
    if (!tenant?.id || !formData.name.trim()) return;

    setIsSaving(true);
    try {
      // Cast pricing config to Record<string, unknown> for the API
      const pricingConfigForApi = formData.pricing_config as unknown as Record<string, unknown>;
      
      const serviceData = {
        name: formData.name.trim(),
        description: formData.description.trim() || undefined,
        duration_minutes: formData.duration_minutes,
        price_type: formData.price_type,
        price_amount: formData.price_amount || formData.pricing_config.min_price,
        service_category: formData.service_category,
        service_type: formData.service_type,
        pricing_config_json: pricingConfigForApi,
        requires_dropoff: formData.requires_dropoff,
      };

      if (editingService) {
        await updateService(editingService.id, tenant.id, serviceData);
        toast.success("Service updated successfully");
      } else {
        await createService(tenant.id, serviceData);
        toast.success("Service created successfully");
      }

      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      
      onOpenChange(false);
      onSuccess?.();
    } catch (error: any) {
      toast.error(error.message || "Failed to save service");
    } finally {
      setIsSaving(false);
    }
  };

  const aiPreview = generatePricingSummary(formData.pricing_config, formData.name || "This service");

  return (
    <Dialog open={open} onOpenChange={handleOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>
            {editingService ? "Edit Service" : step === 1 ? "Choose a Service Type" : "Configure Service"}
          </DialogTitle>
          <DialogDescription>
            {step === 1
              ? "Start with a preset or create a custom service"
              : "Set up pricing and details for your service"}
          </DialogDescription>
        </DialogHeader>

        {/* Step 1: Choose Preset */}
        {step === 1 && (
          <div className="space-y-4 py-4">
            {/* Category Tabs */}
            <div className="flex flex-wrap gap-2">
              {PRESET_CATEGORY_TABS.map((tab) => (
                <button
                  key={tab.id}
                  onClick={() => setPresetTab(tab.id)}
                  className={`px-3 py-1.5 rounded-full text-sm font-medium transition-colors ${
                    presetTab === tab.id
                      ? "bg-primary text-primary-foreground"
                      : "bg-muted text-muted-foreground hover:bg-muted/80"
                  }`}
                >
                  {tab.label}
                </button>
              ))}
            </div>

            {/* Presets Grid (filtered by tab) */}
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
              {DISPATCH_SERVICE_PRESETS.filter((p) => p.presetTab === presetTab).map((preset) => (
                <button
                  key={preset.type}
                  onClick={() => applyPreset(preset)}
                  className="flex flex-col items-center gap-2 p-4 rounded-lg border-2 border-border hover:border-primary hover:bg-primary/5 transition-colors text-center"
                >
                  <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center text-primary">
                    {PRESET_ICONS[preset.icon] || <Truck className="h-5 w-5" />}
                  </div>
                  <span className="font-medium text-sm">{preset.name}</span>
                  <Badge variant="secondary" className="text-xs">
                    {DISPATCH_CATEGORIES[preset.category]?.label.replace(" Services", "")}
                  </Badge>
                </button>
              ))}
            </div>

            <Separator />

            {/* Custom Service Option */}
            <Button
              variant="outline"
              className="w-full py-6"
              onClick={() => {
                setFormData(defaultFormData);
                setStep(2);
              }}
            >
              <Plus className="h-4 w-4 mr-2" />
              Create Custom Service
            </Button>
          </div>
        )}

        {/* Step 2: Configure Service */}
        {step === 2 && (
          <div className="space-y-6 py-4">
            {/* Basic Info */}
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2 col-span-2">
                  <Label>Service Name *</Label>
                  <Input
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="e.g., Local Tow"
                  />
                </div>
                <div className="space-y-2 col-span-2">
                  <Label>Description</Label>
                  <Textarea
                    value={formData.description}
                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                    placeholder="What's included in this service..."
                    rows={2}
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label>Category</Label>
                  <Select
                    value={formData.service_category}
                    onValueChange={(v) => setFormData({ ...formData, service_category: v as DispatchServiceCategory })}
                  >
                    <SelectTrigger>
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      {Object.entries(DISPATCH_CATEGORIES)
                        .sort((a, b) => a[1].order - b[1].order)
                        .map(([key, { label }]) => (
                          <SelectItem key={key} value={key}>
                            {label}
                          </SelectItem>
                        ))}
                    </SelectContent>
                  </Select>
                </div>
                <div className="space-y-2">
                  <Label>Duration (minutes)</Label>
                  <Input
                    type="number"
                    value={formData.duration_minutes}
                    onChange={(e) => setFormData({ ...formData, duration_minutes: parseInt(e.target.value) || 60 })}
                    min={5}
                    step={5}
                  />
                </div>
              </div>
            </div>

            <Separator />

            {/* Requires Dropoff Toggle */}
            <div className="flex items-center justify-between rounded-lg border p-4">
              <div className="space-y-0.5">
                <Label className="text-sm font-medium">This service requires a drop-off location</Label>
                <p className="text-xs text-muted-foreground">
                  Turn this on for towing services where the vehicle goes somewhere else. Leave off for on-site services like jumpstarts or lockouts.
                </p>
              </div>
              <Switch
                checked={formData.requires_dropoff}
                onCheckedChange={(checked) => setFormData({ ...formData, requires_dropoff: checked })}
              />
            </div>

            {/* Pricing Model */}
            <div className="space-y-4">
              <div className="flex items-center gap-2">
                <DollarSign className="h-4 w-4 text-primary" />
                <h4 className="font-medium">Pricing</h4>
              </div>

              <div className="space-y-2">
                <Label>How do you charge for this?</Label>
                <Select
                  value={formData.pricing_config.pricing_model}
                  onValueChange={(v) => setFormData({
                    ...formData,
                    pricing_config: { ...formData.pricing_config, pricing_model: v as any },
                    price_type: v === "flat" ? "fixed" : v === "variable" ? "quote_only" : "starting_at",
                  })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="flat">Fixed Price</SelectItem>
                    <SelectItem value="distance_tiered">Based on Distance</SelectItem>
                    <SelectItem value="per_unit">By the Hour / Room / Unit</SelectItem>
                    <SelectItem value="package">Service Packages</SelectItem>
                    <SelectItem value="variable">Custom Quote</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* Pricing model explanation */}
              <div className="flex items-start gap-2 p-3 rounded-lg bg-muted/50 text-sm">
                <Info className="h-4 w-4 text-muted-foreground shrink-0 mt-0.5" />
                <div className="text-muted-foreground">
                  {formData.pricing_config.pricing_model === "flat" && (
                    <span><strong>Fixed Price</strong> — Same price every time. Best for standardized services like lockouts ($75), jump starts ($65), or tire changes ($85). You can optionally add a per-mile surcharge beyond your service area.</span>
                  )}
                  {formData.pricing_config.pricing_model === "distance_tiered" && (
                    <span><strong>Based on Distance</strong> — A base fee plus per-mile charges. Most towing companies use this. Example: $125 for the first 10 miles, then $5/mile after that.</span>
                  )}
                  {formData.pricing_config.pricing_model === "per_unit" && (
                    <span><strong>By the Hour / Room / Unit</strong> — Charge per hour, per room, per load, or any custom unit. Example: $45/room with a 3-room minimum = $135 starting price. Works great for carpet cleaning, plumbing, IT support, etc.</span>
                  )}
                  {formData.pricing_config.pricing_model === "package" && (
                    <span><strong>Service Packages</strong> — Offer 2-4 preset packages at different price points. Example: Basic $80, Standard $150, Premium $250. The AI presents options and lets the caller choose.</span>
                  )}
                  {formData.pricing_config.pricing_model === "variable" && (
                    <span><strong>Custom Quote</strong> — The AI tells the caller you'll provide a custom quote. Best for complex jobs where pricing depends on the situation. Set a price range so the caller knows the ballpark.</span>
                  )}
                </div>
              </div>

              {/* Trip Fee Toggle (shown for ALL models) */}
              <div className="rounded-lg border p-4 space-y-3">
                <div className="flex items-center justify-between">
                  <div className="space-y-0.5">
                    <Label className="text-sm font-medium">Trip fee or service call fee</Label>
                    <p className="text-xs text-muted-foreground">
                      Charge an upfront fee for coming to the customer (diagnostic fee, trip charge, travel fee)
                    </p>
                  </div>
                  <Switch
                    checked={!!formData.pricing_config.trip_fee?.enabled}
                    onCheckedChange={(checked) => {
                      setFormData({
                        ...formData,
                        pricing_config: {
                          ...formData.pricing_config,
                          trip_fee: checked
                            ? { enabled: true, amount: 75, label: "Service Call Fee", waived_with_service: false }
                            : undefined,
                        },
                      });
                    }}
                  />
                </div>
                {formData.pricing_config.trip_fee?.enabled && (
                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1">
                      <Label className="text-xs">Amount ($)</Label>
                      <Input
                        type="number"
                        value={formData.pricing_config.trip_fee.amount}
                        onChange={(e) => setFormData({
                          ...formData,
                          pricing_config: {
                            ...formData.pricing_config,
                            trip_fee: { ...formData.pricing_config.trip_fee!, amount: parseFloat(e.target.value) || 0 },
                          },
                        })}
                        placeholder="75"
                        step="0.01"
                        min={0}
                      />
                    </div>
                    <div className="space-y-1">
                      <Label className="text-xs">Label</Label>
                      <Select
                        value={formData.pricing_config.trip_fee.label}
                        onValueChange={(v) => setFormData({
                          ...formData,
                          pricing_config: {
                            ...formData.pricing_config,
                            trip_fee: { ...formData.pricing_config.trip_fee!, label: v },
                          },
                        })}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="Service Call Fee">Service Call Fee</SelectItem>
                          <SelectItem value="Trip Charge">Trip Charge</SelectItem>
                          <SelectItem value="Diagnostic Fee">Diagnostic Fee</SelectItem>
                          <SelectItem value="Travel Fee">Travel Fee</SelectItem>
                          <SelectItem value="Delivery Fee">Delivery Fee</SelectItem>
                          <SelectItem value="Inspection Fee">Inspection Fee</SelectItem>
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="col-span-2 flex items-center gap-2">
                      <Switch
                        checked={!!formData.pricing_config.trip_fee.waived_with_service}
                        onCheckedChange={(checked) => setFormData({
                          ...formData,
                          pricing_config: {
                            ...formData.pricing_config,
                            trip_fee: { ...formData.pricing_config.trip_fee!, waived_with_service: checked },
                          },
                        })}
                      />
                      <Label className="text-xs text-muted-foreground">Waived if customer books the service</Label>
                    </div>
                  </div>
                )}
              </div>

              {/* Flat Rate Pricing */}
              {formData.pricing_config.pricing_model === "flat" && (
                <div className="space-y-4">
                  <div className="space-y-2">
                    <Label>Price ($)</Label>
                    <Input
                      type="number"
                      value={formData.pricing_config.min_price || ""}
                      onChange={(e) => setFormData({
                        ...formData,
                        pricing_config: { ...formData.pricing_config, min_price: parseFloat(e.target.value) || 0 },
                        price_amount: parseFloat(e.target.value) || null,
                      })}
                      placeholder="75.00"
                      step="0.01"
                    />
                  </div>

                  {/* Distance Surcharge */}
                  <div className="rounded-lg border p-4 space-y-3">
                    <div className="flex items-center justify-between">
                      <div className="space-y-0.5">
                        <Label className="text-sm font-medium">Add distance surcharge beyond service area</Label>
                        <p className="text-xs text-muted-foreground">
                          Charge extra per mile if the customer is outside your normal range
                        </p>
                      </div>
                      <Switch
                        checked={!!(formData.pricing_config.included_miles && formData.pricing_config.overage_per_mile)}
                        onCheckedChange={(checked) => {
                          if (checked) {
                            setFormData({
                              ...formData,
                              pricing_config: {
                                ...formData.pricing_config,
                                included_miles: 25,
                                overage_per_mile: 3,
                              },
                            });
                          } else {
                            const { included_miles, overage_per_mile, ...rest } = formData.pricing_config;
                            setFormData({
                              ...formData,
                              pricing_config: rest as DispatchPricingConfig,
                            });
                          }
                        }}
                      />
                    </div>
                    {formData.pricing_config.included_miles != null && formData.pricing_config.overage_per_mile != null && (
                      <div className="grid grid-cols-2 gap-3">
                        <div className="space-y-1">
                          <Label className="text-xs">Included miles</Label>
                          <Input
                            type="number"
                            value={formData.pricing_config.included_miles}
                            onChange={(e) => setFormData({
                              ...formData,
                              pricing_config: { ...formData.pricing_config, included_miles: parseInt(e.target.value) || 0 },
                            })}
                            placeholder="25"
                            min={0}
                          />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Per-mile rate beyond ($)</Label>
                          <Input
                            type="number"
                            value={formData.pricing_config.overage_per_mile}
                            onChange={(e) => setFormData({
                              ...formData,
                              pricing_config: { ...formData.pricing_config, overage_per_mile: parseFloat(e.target.value) || 0 },
                            })}
                            placeholder="3.00"
                            step="0.01"
                            min={0}
                          />
                        </div>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Distance Tiered Pricing */}
              {formData.pricing_config.pricing_model === "distance_tiered" && (
                <div className="space-y-4">
                  {/* Distance basis context banner */}
                  {(() => {
                    const effectiveBasis = formData.pricing_config.distance_basis && formData.pricing_config.distance_basis !== ("default" as any)
                      ? formData.pricing_config.distance_basis
                      : distanceSettings?.default_distance_basis || "tow_distance";
                    const basisLabel = DISTANCE_BASIS_OPTIONS.find(o => o.value === effectiveBasis)?.label || effectiveBasis;
                    const basisDesc = effectiveBasis === "tow_distance" ? "pickup → dropoff"
                      : effectiveBasis === "dispatch_distance" ? "your shop → pickup"
                      : effectiveBasis === "total_trip" ? "shop → pickup → dropoff"
                      : "flat rate";
                    const isOverride = formData.pricing_config.distance_basis && formData.pricing_config.distance_basis !== ("default" as any);
                    const radiusMiles = serviceArea?.radius_miles;

                    return (
                      <div className="rounded-lg border border-primary/20 bg-primary/5 p-3 space-y-1.5">
                        <p className="text-xs font-medium">
                          📏 These tiers use <strong>{basisLabel}</strong> miles ({basisDesc}).
                          {isOverride
                            ? " This service overrides your business-wide default."
                            : " This is your business-wide default — you can change it in Coverage & ETA."}
                        </p>
                        {radiusMiles && (
                          <p className="text-xs text-muted-foreground">
                            Your service area is <strong>{radiusMiles} miles</strong> from base. Tiers beyond that distance would apply to out-of-area jobs (if you accept them).
                          </p>
                        )}
                      </div>
                    );
                  })()}

                  {/* Distance Basis Selector */}
                  <div className="space-y-2">
                    <Label>Distance Measured From</Label>
                    <Select
                      value={formData.pricing_config.distance_basis || "default"}
                      onValueChange={(v) => setFormData({
                        ...formData,
                        pricing_config: { 
                          ...formData.pricing_config, 
                          distance_basis: v === "default" ? undefined : v as DistanceBasis 
                        },
                      })}
                    >
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {DISTANCE_BASIS_OPTIONS.map((option) => (
                          <SelectItem key={option.value} value={option.value}>
                            <div className="flex flex-col">
                              <span>{option.label}</span>
                              <span className="text-xs text-muted-foreground">{option.description}</span>
                            </div>
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <p className="text-xs text-muted-foreground">
                      {!formData.pricing_config.distance_basis || formData.pricing_config.distance_basis === ("default" as any)
                        ? "This service will use your business-wide default distance setting."
                        : formData.pricing_config.distance_basis === "dispatch_distance" 
                        ? "Price will be based on how far we travel to reach the customer."
                        : formData.pricing_config.distance_basis === "total_trip"
                        ? "Price will be based on the entire trip distance (to customer + tow)."
                        : "Price will be based on how far the vehicle is towed (pickup to dropoff)."}
                    </p>
                  </div>

                  <div className="flex items-center justify-between">
                    <Label>Distance Tiers</Label>
                    <Button variant="outline" size="sm" onClick={addDistanceTier}>
                      <Plus className="h-3 w-3 mr-1" />
                      Add Tier
                    </Button>
                  </div>

                  {(formData.pricing_config.distance_tiers || []).map((tier, index) => (
                    <Card key={index} className="p-4">
                      <div className="grid grid-cols-4 gap-3">
                        <div className="space-y-1">
                          <Label className="text-xs">From (mi)</Label>
                          <Input
                            type="number"
                            value={tier.min_miles}
                            onChange={(e) => updateDistanceTier(index, { min_miles: parseInt(e.target.value) || 0 })}
                            min={0}
                          />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">To (mi)</Label>
                          <Input
                            type="number"
                            value={tier.max_miles ?? ""}
                            onChange={(e) => updateDistanceTier(index, {
                              max_miles: e.target.value ? parseInt(e.target.value) : null,
                            })}
                            placeholder="∞"
                          />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Base ($)</Label>
                          <Input
                            type="number"
                            value={tier.base_price}
                            onChange={(e) => updateDistanceTier(index, { base_price: parseFloat(e.target.value) || 0 })}
                            step="0.01"
                          />
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Per Mile ($)</Label>
                          <div className="flex gap-1">
                            <Input
                              type="number"
                              value={tier.per_mile_price ?? ""}
                              onChange={(e) => updateDistanceTier(index, {
                                per_mile_price: e.target.value ? parseFloat(e.target.value) : undefined,
                              })}
                              placeholder="0"
                              step="0.01"
                            />
                            {(formData.pricing_config.distance_tiers?.length || 0) > 1 && (
                              <Button
                                variant="ghost"
                                size="icon"
                                className="shrink-0 text-destructive"
                                onClick={() => removeDistanceTier(index)}
                              >
                                <Trash2 className="h-4 w-4" />
                              </Button>
                            )}
                          </div>
                        </div>
                      </div>
                    </Card>
                  ))}

                  {(!formData.pricing_config.distance_tiers || formData.pricing_config.distance_tiers.length === 0) && (
                    <div className="text-center py-4 text-muted-foreground text-sm">
                      No distance tiers configured. Click "Add Tier" to get started.
                    </div>
                  )}

                  {/* Service area tier coverage suggestion */}
                  {(() => {
                    const tiers = formData.pricing_config.distance_tiers || [];
                    const radiusMiles = serviceArea?.radius_miles;
                    if (!radiusMiles || tiers.length === 0) return null;

                    const highestTierMax = tiers.reduce((max, t) => {
                      if (t.max_miles === null || t.max_miles === undefined) return Infinity;
                      return Math.max(max, t.max_miles);
                    }, 0);

                    if (highestTierMax !== Infinity && highestTierMax < radiusMiles) {
                      return (
                        <div className="rounded-lg border border-yellow-500/30 bg-yellow-500/5 p-3 space-y-2">
                          <p className="text-xs text-yellow-700 dark:text-yellow-400">
                            ⚠️ Your service area covers up to <strong>{radiusMiles} miles</strong>, but your highest tier only goes to <strong>{highestTierMax} miles</strong>. Jobs between {highestTierMax}–{radiusMiles} miles won't have a price — the AI will need to request a custom quote.
                          </p>
                          <Button
                            variant="outline"
                            size="sm"
                            className="text-xs h-7"
                            onClick={() => {
                              const lastTier = tiers[tiers.length - 1];
                              const newTier: DistanceTier = {
                                min_miles: highestTierMax,
                                max_miles: radiusMiles,
                                base_price: lastTier?.base_price || 100,
                                per_mile_price: lastTier?.per_mile_price || 5,
                              };
                              setFormData({
                                ...formData,
                                pricing_config: {
                                  ...formData.pricing_config,
                                  distance_tiers: [...tiers, newTier],
                                },
                              });
                            }}
                          >
                            <Plus className="h-3 w-3 mr-1" />
                            Add tier for {highestTierMax}–{radiusMiles} miles
                          </Button>
                        </div>
                      );
                    }

                    if (highestTierMax === Infinity && radiusMiles) {
                      return (
                        <div className="rounded-lg border bg-muted/30 p-3">
                          <p className="text-xs text-muted-foreground">
                            ℹ️ Your last tier is open-ended, and your service area is <strong>{radiusMiles} miles</strong>. The AI checks service area first — if someone is beyond {radiusMiles} miles, they'll be told you don't serve that area before pricing comes up.
                          </p>
                        </div>
                      );
                    }

                    return null;
                  })()}

                  {/* Inline example */}
                  <div className="flex items-start gap-2 p-3 rounded-lg bg-muted/50 text-sm">
                    <Info className="h-4 w-4 text-muted-foreground shrink-0 mt-0.5" />
                    <div className="text-muted-foreground">
                      <strong>Example:</strong> If your base is $125 for 0-10 miles, then $5/mile after that,
                      create two tiers: one for 0-10 mi ($125 base, $0/mi) and one for 10+ mi ($125 base, $5/mi).
                    </div>
                  </div>
                </div>
              )}

              {/* Per-Unit Pricing */}
              {formData.pricing_config.pricing_model === "per_unit" && (
                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label>Unit Type</Label>
                      <Select
                        value={formData.pricing_config.unit_label || "hour"}
                        onValueChange={(v) => setFormData({
                          ...formData,
                          pricing_config: { ...formData.pricing_config, unit_label: v },
                        })}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {UNIT_LABEL_OPTIONS.map((opt) => (
                            <SelectItem key={opt.value} value={opt.value}>
                              {opt.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    <div className="space-y-2">
                      <Label>Price per {formData.pricing_config.unit_label || "unit"} ($)</Label>
                      <Input
                        type="number"
                        value={formData.pricing_config.per_unit_price || ""}
                        onChange={(e) => setFormData({
                          ...formData,
                          pricing_config: { ...formData.pricing_config, per_unit_price: parseFloat(e.target.value) || 0 },
                        })}
                        placeholder="45"
                        step="0.01"
                      />
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label>Minimum {formData.pricing_config.unit_label || "unit"}s</Label>
                      <Input
                        type="number"
                        value={formData.pricing_config.min_units ?? ""}
                        onChange={(e) => setFormData({
                          ...formData,
                          pricing_config: { ...formData.pricing_config, min_units: parseFloat(e.target.value) || undefined },
                        })}
                        placeholder="1"
                        step="0.5"
                        min={0}
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>Minimum Price ($)</Label>
                      <Input
                        type="number"
                        value={formData.pricing_config.min_price || ""}
                        onChange={(e) => setFormData({
                          ...formData,
                          pricing_config: { ...formData.pricing_config, min_price: parseFloat(e.target.value) || undefined },
                          price_amount: parseFloat(e.target.value) || null,
                        })}
                        placeholder="Optional floor price"
                        step="0.01"
                      />
                    </div>
                  </div>
                  {formData.pricing_config.per_unit_price && formData.pricing_config.min_units && formData.pricing_config.min_units > 1 && (
                    <div className="text-sm text-muted-foreground">
                      Starting at <strong>${(formData.pricing_config.per_unit_price * formData.pricing_config.min_units).toFixed(0)}</strong> ({formData.pricing_config.min_units} {formData.pricing_config.unit_label || "unit"}s × ${formData.pricing_config.per_unit_price}/{formData.pricing_config.unit_label || "unit"})
                    </div>
                  )}
                </div>
              )}

              {/* Package Pricing */}
              {formData.pricing_config.pricing_model === "package" && (
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <Label>Service Packages (2-4)</Label>
                    {(formData.pricing_config.packages?.length || 0) < 4 && (
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => {
                          const packages = formData.pricing_config.packages || [];
                          setFormData({
                            ...formData,
                            pricing_config: {
                              ...formData.pricing_config,
                              packages: [...packages, { name: "", price: 0 }],
                            },
                          });
                        }}
                      >
                        <Plus className="h-3 w-3 mr-1" />
                        Add Package
                      </Button>
                    )}
                  </div>

                  {(formData.pricing_config.packages || []).map((pkg, index) => (
                    <Card key={index} className="p-4">
                      <div className="space-y-3">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            {pkg.is_popular && (
                              <Badge variant="default" className="text-xs">
                                <Star className="h-3 w-3 mr-1" /> Popular
                              </Badge>
                            )}
                          </div>
                          <div className="flex items-center gap-1">
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-7 text-xs"
                              onClick={() => {
                                const packages = [...(formData.pricing_config.packages || [])];
                                packages[index] = { ...packages[index], is_popular: !packages[index].is_popular };
                                // Only one can be popular
                                if (packages[index].is_popular) {
                                  packages.forEach((p, i) => { if (i !== index) p.is_popular = false; });
                                }
                                setFormData({
                                  ...formData,
                                  pricing_config: { ...formData.pricing_config, packages },
                                });
                              }}
                            >
                              <Star className="h-3 w-3 mr-1" />
                              {pkg.is_popular ? "Unmark" : "Mark Popular"}
                            </Button>
                            {(formData.pricing_config.packages?.length || 0) > 2 && (
                              <Button
                                variant="ghost"
                                size="icon"
                                className="h-7 w-7 text-destructive"
                                onClick={() => {
                                  const packages = formData.pricing_config.packages?.filter((_, i) => i !== index) || [];
                                  setFormData({
                                    ...formData,
                                    pricing_config: { ...formData.pricing_config, packages },
                                  });
                                }}
                              >
                                <Trash2 className="h-3 w-3" />
                              </Button>
                            )}
                          </div>
                        </div>
                        <div className="grid grid-cols-3 gap-3">
                          <div className="space-y-1 col-span-2">
                            <Label className="text-xs">Package Name</Label>
                            <Input
                              value={pkg.name}
                              onChange={(e) => {
                                const packages = [...(formData.pricing_config.packages || [])];
                                packages[index] = { ...packages[index], name: e.target.value };
                                setFormData({
                                  ...formData,
                                  pricing_config: { ...formData.pricing_config, packages },
                                });
                              }}
                              placeholder="e.g., Basic, Standard, Premium"
                            />
                          </div>
                          <div className="space-y-1">
                            <Label className="text-xs">Price ($)</Label>
                            <Input
                              type="number"
                              value={pkg.price || ""}
                              onChange={(e) => {
                                const packages = [...(formData.pricing_config.packages || [])];
                                packages[index] = { ...packages[index], price: parseFloat(e.target.value) || 0 };
                                setFormData({
                                  ...formData,
                                  pricing_config: { ...formData.pricing_config, packages },
                                });
                              }}
                              placeholder="0"
                              step="0.01"
                            />
                          </div>
                        </div>
                        <div className="space-y-1">
                          <Label className="text-xs">Description (optional)</Label>
                          <Input
                            value={pkg.description || ""}
                            onChange={(e) => {
                              const packages = [...(formData.pricing_config.packages || [])];
                              packages[index] = { ...packages[index], description: e.target.value };
                              setFormData({
                                ...formData,
                                pricing_config: { ...formData.pricing_config, packages },
                              });
                            }}
                            placeholder="What's included in this package?"
                          />
                        </div>
                      </div>
                    </Card>
                  ))}

                  {(!formData.pricing_config.packages || formData.pricing_config.packages.length === 0) && (
                    <div className="text-center py-4 text-muted-foreground text-sm">
                      No packages configured. Click "Add Package" to create your first tier.
                    </div>
                  )}
                </div>
              )}

              {/* Variable/Quote Pricing */}
              {formData.pricing_config.pricing_model === "variable" && (
                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label>Minimum Price ($)</Label>
                      <Input
                        type="number"
                        value={formData.pricing_config.min_price || ""}
                        onChange={(e) => setFormData({
                          ...formData,
                          pricing_config: { ...formData.pricing_config, min_price: parseFloat(e.target.value) || undefined },
                          price_amount: parseFloat(e.target.value) || null,
                        })}
                        placeholder="100"
                        step="0.01"
                      />
                    </div>
                    <div className="space-y-2">
                      <Label>Maximum Price ($)</Label>
                      <Input
                        type="number"
                        value={formData.pricing_config.max_price || ""}
                        onChange={(e) => setFormData({
                          ...formData,
                          pricing_config: { ...formData.pricing_config, max_price: parseFloat(e.target.value) || undefined },
                        })}
                        placeholder="500"
                        step="0.01"
                      />
                    </div>
                  </div>
                  <p className="text-sm text-muted-foreground">
                    The AI will tell callers this service requires a custom quote within this price range.
                  </p>
                </div>
              )}

              {/* AI Quote Behavior (shown for ALL models) */}
              <div className="space-y-2">
                <Label>How should the AI handle pricing on calls?</Label>
                <Select
                  value={formData.pricing_config.ai_quote_behavior || (
                    formData.pricing_config.pricing_model === "variable" ? "always_quote_required" :
                    formData.pricing_config.pricing_model === "per_unit" ? "quote_rate_only" :
                    "calculate_total"
                  )}
                  onValueChange={(v) => setFormData({
                    ...formData,
                    pricing_config: { ...formData.pricing_config, ai_quote_behavior: v as AIQuoteBehavior },
                  })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="calculate_total">Calculate and quote the total</SelectItem>
                    <SelectItem value="quote_rate_only">Just tell them the rate</SelectItem>
                    <SelectItem value="always_quote_required">Always say you'll provide a custom quote</SelectItem>
                  </SelectContent>
                </Select>
                <p className="text-xs text-muted-foreground">
                  {(formData.pricing_config.ai_quote_behavior || "calculate_total") === "calculate_total"
                    ? "The AI will do the math and tell the caller the total price."
                    : (formData.pricing_config.ai_quote_behavior || "calculate_total") === "quote_rate_only"
                    ? "The AI will state your rate but won't compute a total. Good for hourly services where the final price depends on the job."
                    : "The AI will always defer pricing to a human follow-up, regardless of your pricing setup."
                  }
                </p>
              </div>
            </div>

            <Separator />

            {/* AI Preview */}
            <div className="rounded-lg border bg-primary/5 border-primary/20 p-4">
              <div className="flex items-start gap-3">
                <Sparkles className="h-5 w-5 text-primary shrink-0 mt-0.5" />
                <div className="space-y-2 flex-1">
                  <p className="text-sm font-medium text-primary">What the AI will say</p>
                  <p className="text-sm italic">"{aiPreview}"</p>
                </div>
              </div>
            </div>

            {/* Sample Quotes */}
            {formData.pricing_config.pricing_model !== "variable" && (
              <div className="rounded-lg border p-4 space-y-3">
                <div className="flex items-center gap-2">
                  <DollarSign className="h-4 w-4 text-muted-foreground" />
                  <p className="text-sm font-medium">
                    {formData.pricing_config.pricing_model === "per_unit"
                      ? `Sample Quotes by ${formData.pricing_config.unit_label || "Unit"}s`
                      : formData.pricing_config.pricing_model === "package"
                      ? "Package Prices"
                      : "Sample Quotes by Distance"
                    }
                  </p>
                </div>
                <div className={`grid gap-2 ${
                  formData.pricing_config.pricing_model === "package"
                    ? `grid-cols-${Math.min(formData.pricing_config.packages?.length || 2, 4)}`
                    : "grid-cols-2 sm:grid-cols-4"
                }`}>
                  {calculateScenarioQuotes(formData.pricing_config, formData.name || "Service").map((q, i) => (
                    <div key={i} className="rounded-md bg-muted/50 p-2.5 text-center">
                      <p className="text-xs text-muted-foreground">
                        {formData.pricing_config.pricing_model === "per_unit"
                          ? `${q.distance} ${formData.pricing_config.unit_label || "unit"}${q.distance !== 1 ? "s" : ""}`
                          : formData.pricing_config.pricing_model === "package"
                          ? formData.pricing_config.packages?.[i]?.name || `Tier ${i + 1}`
                          : `${q.distance} miles`
                        }
                      </p>
                      <p className="text-lg font-semibold">${q.price}</p>
                    </div>
                  ))}
                </div>
                <p className="text-xs text-muted-foreground">
                  These are estimates based on your current pricing setup. The AI uses these to quote callers.
                </p>
              </div>
            )}
          </div>
        )}

        <DialogFooter>
          {step === 2 && !editingService && (
            <Button variant="outline" onClick={() => setStep(1)}>
              Back
            </Button>
          )}
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          {step === 2 && (
            <Button onClick={handleSave} disabled={isSaving || !formData.name.trim()}>
              {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingService ? "Update Service" : "Create Service"}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * DistanceBasisSettings - Configure how distance is measured for pricing
 * 
 * This sets the tenant-level default for how pricing distance is calculated.
 * Individual services can override this setting.
 */
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Loader2, ArrowRight, MapPin, Truck, Route, DollarSign, ShieldCheck } from "lucide-react";
import { useTenantDistanceSettings } from "@/hooks/useTenantDistanceSettings";

import { useState, useEffect } from "react";

type DistanceBasis = "tow_distance" | "dispatch_distance" | "total_trip" | "flat";
type DropoffCoverageMode = "none" | "same_area" | "extended";

interface DistanceBasisOption {
  value: DistanceBasis;
  label: string;
  description: string;
  icon: React.ReactNode;
  example: string;
}

const DISTANCE_BASIS_OPTIONS: DistanceBasisOption[] = [
  {
    value: "tow_distance",
    label: "Tow Distance",
    description: "Price based on how far we tow the vehicle",
    icon: (
      <div className="flex items-center gap-1 text-xs text-muted-foreground">
        <MapPin className="h-3 w-3" />
        <ArrowRight className="h-3 w-3" />
        <Truck className="h-3 w-3" />
      </div>
    ),
    example: "Pickup to dropoff location",
  },
  {
    value: "dispatch_distance",
    label: "Dispatch Distance",
    description: "Price based on how far we travel to reach you",
    icon: (
      <div className="flex items-center gap-1 text-xs text-muted-foreground">
        <Truck className="h-3 w-3" />
        <ArrowRight className="h-3 w-3" />
        <MapPin className="h-3 w-3" />
      </div>
    ),
    example: "Our shop to pickup location",
  },
  {
    value: "total_trip",
    label: "Total Trip",
    description: "Price based on our entire round trip",
    icon: (
      <div className="flex items-center gap-1 text-xs text-muted-foreground">
        <Route className="h-3 w-3" />
      </div>
    ),
    example: "Shop → pickup → dropoff",
  },
  {
    value: "flat",
    label: "Flat Rate",
    description: "Distance doesn't affect pricing",
    icon: (
      <div className="flex items-center gap-1 text-xs text-muted-foreground">
        <DollarSign className="h-3 w-3" />
      </div>
    ),
    example: "Same price regardless of distance",
  },
];

const DROPOFF_OPTIONS: { value: DropoffCoverageMode; label: string; description: string }[] = [
  {
    value: "none",
    label: "No Dropoff Check",
    description: "We'll tow anywhere the customer wants — no area restriction on the destination.",
  },
  {
    value: "same_area",
    label: "Same Service Area",
    description: "The dropoff must also be within our normal coverage radius. If it's outside, the AI will let them know.",
  },
  {
    value: "extended",
    label: "Extended Radius",
    description: "The dropoff can be further than our normal area, up to a max distance you set. Great for long-distance tows with a surcharge.",
  },
];

export function DistanceBasisSettings() {
  const { settings, isLoading, isSaving, saveSettings } = useTenantDistanceSettings();

  const [dropoffMaxMiles, setDropoffMaxMiles] = useState<number | null>(null);

  useEffect(() => {
    if (settings) {
      setDropoffMaxMiles(settings.dropoff_max_miles);
    }
  }, [settings]);

  const handleChange = async (value: string) => {
    await saveSettings({ default_distance_basis: value as DistanceBasis });
  };

  const dropoffMode = (settings?.dropoff_coverage_mode as DropoffCoverageMode) || "none";

  const handleDropoffModeChange = async (value: string) => {
    await saveSettings({ dropoff_coverage_mode: value as DropoffCoverageMode });
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const currentValue = (settings?.default_distance_basis as DistanceBasis) || "tow_distance";

  return (
    <div className="space-y-4">
      <div className="space-y-2">
        <p className="text-sm text-muted-foreground">
          Choose how your AI calculates distance for pricing. This determines what number goes into your per-mile rates.
        </p>
        <div className="rounded-lg border bg-primary/5 border-primary/20 p-3">
          <p className="text-xs">
            <strong>Example:</strong> Customer is stranded 5 miles from your shop, needs a tow to a destination 10 miles away.
          </p>
          <ul className="text-xs text-muted-foreground mt-2 space-y-1">
            <li>• <strong>Tow Distance</strong> = 10 miles (pickup → destination)</li>
            <li>• <strong>Dispatch Distance</strong> = 5 miles (your shop → pickup)</li>
            <li>• <strong>Total Trip</strong> = 15 miles (shop → pickup → destination)</li>
          </ul>
        </div>
        <div className="rounded-lg border bg-muted/30 p-3">
          <p className="text-xs text-muted-foreground">
            <strong>Most towing businesses</strong> charge based on <strong>Tow Distance</strong> — how far the vehicle needs to be hauled. 
            Some businesses charge for the full round trip to account for their drive-out time.
          </p>
        </div>
      </div>

      <RadioGroup
        value={currentValue}
        onValueChange={handleChange}
        disabled={isSaving}
        className="grid gap-3"
      >
        {DISTANCE_BASIS_OPTIONS.map((option) => {
          const isSelected = currentValue === option.value;
          return (
            <Label
              key={option.value}
              htmlFor={option.value}
              className={`
                flex items-start gap-4 p-4 rounded-lg border-2 cursor-pointer transition-all
                ${isSelected 
                  ? "border-primary bg-primary/5" 
                  : "border-border hover:border-primary/50 hover:bg-muted/50"
                }
                ${isSaving ? "opacity-50 pointer-events-none" : ""}
              `}
            >
              <RadioGroupItem value={option.value} id={option.value} className="mt-1" />
              <div className="flex-1 space-y-1">
                <div className="flex items-center gap-2">
                  <span className="font-medium">{option.label}</span>
                  {option.icon}
                  {isSelected && (
                    <Badge variant="secondary" className="ml-auto text-xs">
                      Active
                    </Badge>
                  )}
                </div>
                <p className="text-sm text-muted-foreground">{option.description}</p>
                <p className="text-xs text-muted-foreground italic">
                  Example: {option.example}
                </p>
              </div>
            </Label>
          );
        })}
      </RadioGroup>

      <div className="rounded-lg border bg-muted/30 p-3 mt-4 space-y-2">
        <p className="text-xs text-muted-foreground">
          <strong>Note:</strong> This is your default for all services. You can override this on individual services if some use a different pricing method (e.g., flat rate for local tows, per-mile for long distance).
        </p>
        <p className="text-xs text-muted-foreground">
          <strong>How this connects to pricing:</strong> This setting determines which distance your per-mile rates in each service use. For example, if you choose "Tow Distance" and a service charges $5/mile, that $5 applies to each mile the vehicle is towed (pickup → dropoff), not the distance from your shop.
        </p>
      </div>

      {/* ── Dropoff Coverage ── */}
      <div className="mt-8 space-y-4">
        <div className="space-y-1">
          <h3 className="text-base font-semibold flex items-center gap-2">
            <ShieldCheck className="h-4 w-4" />
            Dropoff Coverage Rules
          </h3>
          <p className="text-sm text-muted-foreground">
            Should your AI check whether the <strong>dropoff location</strong> is within your service area? This only applies to services that require a destination (like towing).
          </p>
        </div>

        <RadioGroup
          value={dropoffMode}
          onValueChange={handleDropoffModeChange}
          disabled={isSaving}
          className="grid gap-3"
        >
          {DROPOFF_OPTIONS.map((option) => {
            const isSelected = dropoffMode === option.value;
            return (
              <Label
                key={option.value}
                htmlFor={`dropoff-${option.value}`}
                className={`
                  flex items-start gap-4 p-4 rounded-lg border-2 cursor-pointer transition-all
                  ${isSelected
                    ? "border-primary bg-primary/5"
                    : "border-border hover:border-primary/50 hover:bg-muted/50"
                  }
                  ${isSaving ? "opacity-50 pointer-events-none" : ""}
                `}
              >
                <RadioGroupItem value={option.value} id={`dropoff-${option.value}`} className="mt-1" />
                <div className="flex-1 space-y-1">
                  <div className="flex items-center gap-2">
                    <span className="font-medium">{option.label}</span>
                    {isSelected && (
                      <Badge variant="secondary" className="ml-auto text-xs">Active</Badge>
                    )}
                  </div>
                  <p className="text-sm text-muted-foreground">{option.description}</p>
                </div>
              </Label>
            );
          })}
        </RadioGroup>

        {dropoffMode === "extended" && (
          <div className="flex items-center gap-3 pl-8">
            <Label htmlFor="dropoff-max-miles" className="text-sm whitespace-nowrap">Max dropoff distance:</Label>
            <Input
              id="dropoff-max-miles"
              type="number"
              min={1}
              max={500}
              className="w-24"
              value={dropoffMaxMiles ?? ""}
              onChange={(e) => setDropoffMaxMiles(e.target.value ? Number(e.target.value) : null)}
              onBlur={() => {
                if (dropoffMaxMiles !== settings?.dropoff_max_miles) {
                  saveSettings({ dropoff_max_miles: dropoffMaxMiles });
                }
              }}
              disabled={isSaving}
            />
            <span className="text-sm text-muted-foreground">miles</span>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * DispatchIvrSettings - Configure IVR call routing mode
 * 
 * Allows dispatch businesses to choose how inbound calls are routed:
 * - Towing only (default)
 * - Impound only
 * - IVR routing (Press 1 for towing, Press 2 for impound status)
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Loader2, Phone, Truck, Warehouse, PhoneCall, Sparkles } from "lucide-react";

type IvrMode = "towing_only" | "impound_only" | "ivr_routing";

interface IvrOption {
  value: IvrMode;
  label: string;
  description: string;
  icon: typeof Truck;
  preview: string;
}

const IVR_OPTIONS: IvrOption[] = [
  {
    value: "towing_only",
    label: "Towing & Roadside Only",
    description: "All calls go directly to the towing/dispatch AI. Best if you don't handle impound inquiries over the phone.",
    icon: Truck,
    preview: "Hi, thanks for calling! Do you need a tow or roadside assistance today?",
  },
  {
    value: "impound_only",
    label: "Impound Inquiries Only",
    description: "All calls go directly to the impound AI. Best for a dedicated impound line or if you only do impound recovery.",
    icon: Warehouse,
    preview: "Hi, thanks for calling the impound lot! I can help you check on a vehicle or get release information. What's the plate number?",
  },
  {
    value: "ivr_routing",
    label: "IVR Menu (Press 1 or 2)",
    description: "Callers choose: Press 1 for towing/roadside, Press 2 for impound. Each agent can transfer to the other if needed.",
    icon: PhoneCall,
    preview: "Thanks for calling! Press 1 for towing and roadside assistance, or press 2 to check on an impounded vehicle.",
  },
];

export function DispatchIvrSettings() {
  const { tenant } = useAuth();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [mode, setMode] = useState<IvrMode>("towing_only");

  useEffect(() => {
    if (tenant?.id) {
      loadSettings();
    }
  }, [tenant?.id]);

  const loadSettings = async () => {
    if (!tenant?.id) return;
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("assistant_settings")
        .select("dispatch_ivr_mode")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error) throw error;
      setMode((data?.dispatch_ivr_mode as IvrMode) || "towing_only");
    } catch (error) {
      console.error("Failed to load IVR settings:", error);
    } finally {
      setLoading(false);
    }
  };

  const saveSettings = async () => {
    if (!tenant?.id) return;
    setSaving(true);
    try {
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          dispatch_ivr_mode: mode,
          updated_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      toast.success("Call routing saved");
    } catch (error: any) {
      console.error("Failed to save:", error);
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const selectedOption = IVR_OPTIONS.find(o => o.value === mode)!;

  return (
    <div className="space-y-6">
      {/* Intro Text */}
      <p className="text-sm text-muted-foreground">
        Choose how inbound calls are routed when someone calls your CloseLoop number. This controls whether they reach your towing dispatcher, impound assistant, or an IVR menu.
      </p>

      {/* AI Preview */}
      <div className="rounded-lg border bg-primary/5 border-primary/20 p-4">
        <div className="flex items-start gap-3">
          <Sparkles className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div>
            <p className="text-sm font-medium text-primary mb-1">What callers hear first</p>
            <p className="text-sm italic">"{selectedOption.preview}"</p>
          </div>
        </div>
      </div>

      {/* Mode Selection */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <div className="flex items-center gap-2 mb-4">
            <Phone className="h-4 w-4 text-muted-foreground" />
            <h4 className="font-medium">Call Routing Mode</h4>
          </div>

          <RadioGroup value={mode} onValueChange={(v) => setMode(v as IvrMode)}>
            <div className="space-y-3">
              {IVR_OPTIONS.map((option) => (
                <label
                  key={option.value}
                  className={`flex items-start gap-4 p-4 rounded-lg border cursor-pointer transition-colors ${
                    mode === option.value
                      ? "border-primary bg-primary/5"
                      : "hover:bg-muted/50"
                  }`}
                >
                  <RadioGroupItem value={option.value} className="mt-1" />
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <option.icon className="h-4 w-4 text-muted-foreground" />
                      <span className="font-medium">{option.label}</span>
                    </div>
                    <p className="text-sm text-muted-foreground mt-1">
                      {option.description}
                    </p>
                  </div>
                </label>
              ))}
            </div>
          </RadioGroup>
        </CardContent>
      </Card>

      {/* Agent Transfer Note */}
      {mode === "ivr_routing" && (
        <div className="rounded-lg border bg-muted/50 p-4">
          <p className="text-sm text-muted-foreground">
            <strong>Smart Transfers:</strong> If someone calls the towing line asking about an impounded vehicle, the AI will offer to transfer them to impound. Same goes the other way — the impound agent can transfer to dispatch if someone needs a tow.
          </p>
        </div>
      )}

      {/* Impound-only tip */}
      {mode === "impound_only" && (
        <div className="rounded-lg border bg-amber-500/10 border-amber-500/20 p-4">
          <p className="text-sm text-amber-600 dark:text-amber-400">
            <strong>Tip:</strong> With this mode, callers can't request tows from this number. Make sure you have a separate line for dispatch, or switch to IVR routing.
          </p>
        </div>
      )}

      {/* Save */}
      <div className="flex justify-end">
        <Button onClick={saveSettings} disabled={saving}>
          {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          Save Call Routing
        </Button>
      </div>
    </div>
  );
}

/**
 * ImpoundFeesEditor - Configure impound fee structure
 * 
 * Allows dispatch businesses to set up their fee schedule:
 * - Base tow fee
 * - Daily storage fee
 * - Admin and gate fees
 * - Accepted payment methods
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent } from "@/components/ui/card";
import { Loader2, DollarSign, CreditCard, Sparkles } from "lucide-react";

interface ImpoundSettings {
  tenant_id: string;
  base_tow_fee_cents: number;
  daily_storage_cents: number;
  gate_fee_cents: number;
  admin_fee_cents: number;
  accepted_payment: string[];
  default_release_requirements: string[];
}

const PAYMENT_METHODS = [
  { id: "cash", label: "Cash" },
  { id: "credit_card", label: "Credit Card" },
  { id: "debit_card", label: "Debit Card" },
  { id: "check", label: "Check" },
  { id: "money_order", label: "Money Order" },
];

const DEFAULT_SETTINGS: Omit<ImpoundSettings, "tenant_id"> = {
  base_tow_fee_cents: 15000,
  daily_storage_cents: 3500,
  gate_fee_cents: 5000,
  admin_fee_cents: 2500,
  accepted_payment: ["cash", "credit_card", "debit_card"],
  default_release_requirements: ["valid_id", "registration", "payment"],
};

export function ImpoundFeesEditor() {
  const { tenant } = useAuth();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [settings, setSettings] = useState<ImpoundSettings | null>(null);

  useEffect(() => {
    if (tenant?.id) {
      loadSettings();
    }
  }, [tenant?.id]);

  const loadSettings = async () => {
    if (!tenant?.id) return;
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("impound_settings")
        .select("*")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setSettings({
          tenant_id: data.tenant_id,
          base_tow_fee_cents: data.base_tow_fee_cents,
          daily_storage_cents: data.daily_storage_cents,
          gate_fee_cents: data.gate_fee_cents || 0,
          admin_fee_cents: data.admin_fee_cents || 0,
          accepted_payment: data.accepted_payment || DEFAULT_SETTINGS.accepted_payment,
          default_release_requirements: data.default_release_requirements || DEFAULT_SETTINGS.default_release_requirements,
        });
      } else {
        // Initialize with defaults
        setSettings({
          tenant_id: tenant.id,
          ...DEFAULT_SETTINGS,
        });
      }
    } catch (error) {
      console.error("Failed to load impound settings:", error);
      toast.error("Failed to load fee settings");
    } finally {
      setLoading(false);
    }
  };

  const saveSettings = async () => {
    if (!tenant?.id || !settings) return;
    setSaving(true);
    try {
      const { error } = await supabase
        .from("impound_settings")
        .upsert({
          tenant_id: tenant.id,
          base_tow_fee_cents: settings.base_tow_fee_cents,
          daily_storage_cents: settings.daily_storage_cents,
          gate_fee_cents: settings.gate_fee_cents,
          admin_fee_cents: settings.admin_fee_cents,
          accepted_payment: settings.accepted_payment,
          default_release_requirements: settings.default_release_requirements,
          updated_at: new Date().toISOString(),
        }, { onConflict: "tenant_id" });

      if (error) throw error;
      toast.success("Fee settings saved");
    } catch (error: any) {
      console.error("Failed to save settings:", error);
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const updateCents = (field: keyof ImpoundSettings, dollars: string) => {
    if (!settings) return;
    const cents = Math.round(parseFloat(dollars || "0") * 100);
    setSettings({ ...settings, [field]: cents });
  };

  const togglePaymentMethod = (methodId: string) => {
    if (!settings) return;
    const current = settings.accepted_payment;
    const updated = current.includes(methodId)
      ? current.filter((m) => m !== methodId)
      : [...current, methodId];
    setSettings({ ...settings, accepted_payment: updated });
  };

  const formatDollars = (cents: number) => (cents / 100).toFixed(2);

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!settings) return null;

  // Calculate example total
  const exampleDays = 3;
  const exampleTotal =
    settings.base_tow_fee_cents +
    exampleDays * settings.daily_storage_cents +
    settings.admin_fee_cents +
    settings.gate_fee_cents;

  return (
    <div className="space-y-6">
      {/* AI Preview */}
      <div className="rounded-lg border bg-primary/5 border-primary/20 p-4">
        <div className="flex items-start gap-3">
          <Sparkles className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div>
            <p className="text-sm font-medium text-primary mb-1">What the AI tells customers (example with {exampleDays} days storage)</p>
            <p className="text-sm italic">
              "The total to release your vehicle is ${formatDollars(exampleTotal)}. 
              That's ${formatDollars(settings.base_tow_fee_cents)} for the tow, 
              ${formatDollars(exampleDays * settings.daily_storage_cents)} for {exampleDays} days of storage, 
              plus ${formatDollars(settings.admin_fee_cents + settings.gate_fee_cents)} in fees. 
              We accept {settings.accepted_payment.map(m => 
                PAYMENT_METHODS.find(p => p.id === m)?.label.toLowerCase()
              ).filter(Boolean).join(", ")}."
            </p>
          </div>
        </div>
      </div>

      {/* Fee Structure */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <div className="flex items-center gap-2 mb-2">
            <DollarSign className="h-4 w-4 text-muted-foreground" />
            <h4 className="font-medium">Fee Structure</h4>
          </div>
          <p className="text-sm text-muted-foreground mb-4">
            The AI calculates total release costs automatically based on days stored. Set your standard fees below.
          </p>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Base Tow Fee</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  step="0.01"
                  min="0"
                  value={formatDollars(settings.base_tow_fee_cents)}
                  onChange={(e) => updateCents("base_tow_fee_cents", e.target.value)}
                  className="pl-7"
                />
              </div>
              <p className="text-xs text-muted-foreground">Charged once when vehicle is impounded</p>
            </div>

            <div className="space-y-2">
              <Label>Daily Storage Fee</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  step="0.01"
                  min="0"
                  value={formatDollars(settings.daily_storage_cents)}
                  onChange={(e) => updateCents("daily_storage_cents", e.target.value)}
                  className="pl-7"
                />
              </div>
              <p className="text-xs text-muted-foreground">Per day the vehicle stays in your lot</p>
            </div>

            <div className="space-y-2">
              <Label>Admin/Processing Fee</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  step="0.01"
                  min="0"
                  value={formatDollars(settings.admin_fee_cents)}
                  onChange={(e) => updateCents("admin_fee_cents", e.target.value)}
                  className="pl-7"
                />
              </div>
              <p className="text-xs text-muted-foreground">One-time paperwork/processing fee</p>
            </div>

            <div className="space-y-2">
              <Label>Gate Fee (After-Hours)</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  step="0.01"
                  min="0"
                  value={formatDollars(settings.gate_fee_cents)}
                  onChange={(e) => updateCents("gate_fee_cents", e.target.value)}
                  className="pl-7"
                />
              </div>
              <p className="text-xs text-muted-foreground">Extra fee for pickups outside normal hours</p>
            </div>
          </div>
          
          <div className="rounded-lg border bg-muted/30 p-3 mt-4">
            <p className="text-xs text-muted-foreground">
              <strong>Example calculation:</strong> $150 tow + ($35/day × 3 days) + $25 admin + $50 gate = <strong>${formatDollars(settings.base_tow_fee_cents + 3*settings.daily_storage_cents + settings.admin_fee_cents + settings.gate_fee_cents)}</strong>
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Payment Methods */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <div className="flex items-center gap-2 mb-2">
            <CreditCard className="h-4 w-4 text-muted-foreground" />
            <h4 className="font-medium">Accepted Payment Methods</h4>
          </div>
          <p className="text-sm text-muted-foreground mb-4">
            The AI will tell callers which payment types you accept for vehicle release.
          </p>

          <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
            {PAYMENT_METHODS.map((method) => (
              <label
                key={method.id}
                className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                  settings.accepted_payment.includes(method.id) 
                    ? "border-primary bg-primary/5" 
                    : "hover:bg-muted/50"
                }`}
              >
                <Checkbox
                  checked={settings.accepted_payment.includes(method.id)}
                  onCheckedChange={() => togglePaymentMethod(method.id)}
                />
                <span className="text-sm">{method.label}</span>
              </label>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Save */}
      <div className="flex justify-end">
        <Button onClick={saveSettings} disabled={saving}>
          {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          Save Fee Settings
        </Button>
      </div>
    </div>
  );
}

/**
 * ImpoundLotEditor - Configure impound lot details
 * 
 * Allows dispatch businesses to set up their impound lot information:
 * - Lot name, address, phone
 * - Operating hours
 * - Directions for customers
 */

import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent } from "@/components/ui/card";
import { Loader2, MapPin, Phone, Building, Navigation, ExternalLink, Car, Clock } from "lucide-react";

interface HoursEntry {
  open: string | null;
  close: string | null;
}

interface ImpoundLot {
  id?: string;
  tenant_id: string;
  name: string;
  address: string;
  city: string;
  state: string;
  zip: string;
  phone: string | null;
  directions: string | null;
  hours_json: Record<string, HoursEntry>;
  is_default: boolean;
  is_active: boolean;
}

const DAYS = [
  { key: "monday", label: "Monday" },
  { key: "tuesday", label: "Tuesday" },
  { key: "wednesday", label: "Wednesday" },
  { key: "thursday", label: "Thursday" },
  { key: "friday", label: "Friday" },
  { key: "saturday", label: "Saturday" },
  { key: "sunday", label: "Sunday" },
];

const DEFAULT_HOURS: Record<string, HoursEntry> = {
  monday: { open: "08:00", close: "17:00" },
  tuesday: { open: "08:00", close: "17:00" },
  wednesday: { open: "08:00", close: "17:00" },
  thursday: { open: "08:00", close: "17:00" },
  friday: { open: "08:00", close: "17:00" },
  saturday: { open: "09:00", close: "12:00" },
  sunday: { open: null, close: null },
};

export function ImpoundLotEditor() {
  const { tenant } = useAuth();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [lot, setLot] = useState<ImpoundLot | null>(null);

  useEffect(() => {
    if (tenant?.id) {
      loadLot();
    }
  }, [tenant?.id]);

  const loadLot = async () => {
    if (!tenant?.id) return;
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("impound_lots")
        .select("*")
        .eq("tenant_id", tenant.id)
        .eq("is_default", true)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setLot({
          id: data.id,
          tenant_id: data.tenant_id,
          name: data.name,
          address: data.address,
          city: data.city,
          state: data.state,
          zip: data.zip,
          phone: data.phone,
          directions: data.directions as string | null,
          hours_json: (data.hours_json as unknown as Record<string, HoursEntry>) || DEFAULT_HOURS,
          is_default: data.is_default,
          is_active: data.is_active,
        });
      } else {
        // Initialize with defaults
        setLot({
          tenant_id: tenant.id,
          name: "Main Impound Lot",
          address: "",
          city: "",
          state: "",
          zip: "",
          phone: null,
          directions: null,
          hours_json: DEFAULT_HOURS,
          is_default: true,
          is_active: true,
        });
      }
    } catch (error) {
      console.error("Failed to load impound lot:", error);
      toast.error("Failed to load lot details");
    } finally {
      setLoading(false);
    }
  };

  const saveLot = async () => {
    if (!tenant?.id || !lot) return;
    setSaving(true);
    try {
      if (lot.id) {
        const updateData = {
          name: lot.name,
          address: lot.address,
          city: lot.city,
          state: lot.state,
          zip: lot.zip,
          phone: lot.phone,
          directions: lot.directions,
          hours_json: JSON.parse(JSON.stringify(lot.hours_json)),
          is_active: lot.is_active,
          updated_at: new Date().toISOString(),
        };
        const { error } = await supabase
          .from("impound_lots")
          .update(updateData)
          .eq("id", lot.id);
        if (error) throw error;
      } else {
        const insertData = {
          tenant_id: tenant.id,
          name: lot.name,
          address: lot.address,
          city: lot.city,
          state: lot.state,
          zip: lot.zip,
          phone: lot.phone,
          directions: lot.directions,
          hours_json: JSON.parse(JSON.stringify(lot.hours_json)),
          is_default: true,
          is_active: true,
        };
        const { data, error } = await supabase
          .from("impound_lots")
          .insert([insertData])
          .select()
          .single();
        if (error) throw error;
        setLot({ ...lot, id: data.id });
      }
      toast.success("Lot details saved");
    } catch (error: any) {
      console.error("Failed to save lot:", error);
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const updateField = <K extends keyof ImpoundLot>(field: K, value: ImpoundLot[K]) => {
    if (!lot) return;
    setLot({ ...lot, [field]: value });
  };

  const updateHours = (day: string, field: "open" | "close", value: string | null) => {
    if (!lot) return;
    setLot({
      ...lot,
      hours_json: {
        ...lot.hours_json,
        [day]: { ...lot.hours_json[day], [field]: value },
      },
    });
  };

  const toggleDayClosed = (day: string, isClosed: boolean) => {
    if (!lot) return;
    if (isClosed) {
      updateHours(day, "open", null);
      updateHours(day, "close", null);
    } else {
      setLot({
        ...lot,
        hours_json: {
          ...lot.hours_json,
          [day]: { open: "08:00", close: "17:00" },
        },
      });
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!lot) return null;

  return (
    <div className="space-y-6">
      {/* Quick Link to Inventory */}
      <Card className="border-primary/20 bg-primary/5">
        <CardContent className="py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Car className="h-5 w-5 text-primary" />
              <div>
                <p className="font-medium">Manage Impound Inventory</p>
                <p className="text-sm text-muted-foreground">
                  Add vehicles, process releases, and track storage fees
                </p>
              </div>
            </div>
            <Button variant="outline" asChild>
              <Link to="/app/impound-lot">
                Open Impound Lot
                <ExternalLink className="h-4 w-4 ml-2" />
              </Link>
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Location Details */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <div className="flex items-center gap-2 mb-2">
            <Building className="h-4 w-4 text-muted-foreground" />
            <h4 className="font-medium">Location Details</h4>
          </div>
          <p className="text-sm text-muted-foreground mb-4">
            The AI tells callers this address when they ask where to pick up their vehicle.
          </p>

          <div className="space-y-3">
            <div className="space-y-2">
              <Label>Lot Name</Label>
              <Input
                value={lot.name}
                onChange={(e) => updateField("name", e.target.value)}
                placeholder="Main Impound Lot"
              />
              <p className="text-xs text-muted-foreground">
                Example: "Downtown Impound", "ABC Towing Storage Lot"
              </p>
            </div>

            <div className="space-y-2">
              <Label>Street Address</Label>
              <Input
                value={lot.address}
                onChange={(e) => updateField("address", e.target.value)}
                placeholder="456 Storage Lane"
              />
            </div>

            <div className="grid grid-cols-3 gap-3">
              <div className="space-y-2">
                <Label>City</Label>
                <Input
                  value={lot.city}
                  onChange={(e) => updateField("city", e.target.value)}
                  placeholder="Austin"
                />
              </div>
              <div className="space-y-2">
                <Label>State</Label>
                <Input
                  value={lot.state}
                  onChange={(e) => updateField("state", e.target.value)}
                  placeholder="TX"
                  maxLength={2}
                />
              </div>
              <div className="space-y-2">
                <Label>ZIP</Label>
                <Input
                  value={lot.zip}
                  onChange={(e) => updateField("zip", e.target.value)}
                  placeholder="78701"
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label className="flex items-center gap-2">
                <Phone className="h-3.5 w-3.5" />
                Lot Phone Number
              </Label>
              <Input
                value={lot.phone || ""}
                onChange={(e) => updateField("phone", e.target.value || null)}
                placeholder="(512) 555-1234"
              />
              <p className="text-xs text-muted-foreground">
                If different from your main business number. AI will give this for impound-specific calls.
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Directions */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <div className="flex items-center gap-2 mb-2">
            <Navigation className="h-4 w-4 text-muted-foreground" />
            <h4 className="font-medium">Driving Directions</h4>
          </div>
          <p className="text-sm text-muted-foreground">
            The AI reads this word-for-word when callers ask "How do I get there?" Write it like you're giving directions over the phone.
          </p>
          <Textarea
            value={lot.directions || ""}
            onChange={(e) => updateField("directions", e.target.value || null)}
            placeholder="We're located off Highway 183, behind the Shell gas station on the corner of 5th and Main. Look for the large blue sign that says 'ABC Towing'. The entrance is on the right side of the building."
            rows={4}
          />
          <div className="rounded-lg border bg-muted/30 p-3">
            <p className="text-xs text-muted-foreground">
              <strong>Tip:</strong> Include landmarks, cross streets, and what to look for. Avoid abbreviations like "Hwy" — write "Highway" so it sounds natural when spoken.
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Hours */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <div className="flex items-center gap-2 mb-2">
            <Clock className="h-4 w-4 text-muted-foreground" />
            <h4 className="font-medium">Vehicle Release Hours</h4>
          </div>
          <p className="text-sm text-muted-foreground mb-4">
            When can customers pick up their vehicles? The AI will tell callers these hours and whether you're currently open.
          </p>

          <div className="space-y-3">
            {DAYS.map(({ key, label }) => {
              const hours = lot.hours_json[key];
              const isClosed = !hours?.open && !hours?.close;
              
              return (
                <div key={key} className="flex items-center gap-4">
                  <div className="w-24 text-sm font-medium">{label}</div>
                  <Switch
                    checked={!isClosed}
                    onCheckedChange={(checked) => toggleDayClosed(key, !checked)}
                  />
                  {isClosed ? (
                    <span className="text-sm text-muted-foreground">Closed — no pickups</span>
                  ) : (
                    <div className="flex items-center gap-2">
                      <Input
                        type="time"
                        value={hours?.open || "08:00"}
                        onChange={(e) => updateHours(key, "open", e.target.value)}
                        className="w-28"
                      />
                      <span className="text-muted-foreground">to</span>
                      <Input
                        type="time"
                        value={hours?.close || "17:00"}
                        onChange={(e) => updateHours(key, "close", e.target.value)}
                        className="w-28"
                      />
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          
          <div className="rounded-lg border bg-amber-500/10 border-amber-500/20 p-3 mt-4">
            <p className="text-xs text-amber-600 dark:text-amber-400">
              <strong>After-hours pickups:</strong> If you offer gate fees for after-hours releases, configure that in the Fee Structure section below.
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Save */}
      <div className="flex justify-end">
        <Button onClick={saveLot} disabled={saving}>
          {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          Save Lot Details
        </Button>
      </div>
    </div>
  );
}

/**
 * ImpoundReleaseEditor - Configure release requirements
 * 
 * Allows dispatch businesses to set up what's needed to release a vehicle:
 * - Required documents (ID, registration, title, etc.)
 * - Special requirements (lien release, police release)
 * - Custom requirements
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent } from "@/components/ui/card";
import { Loader2, FileCheck, Plus, X, Sparkles } from "lucide-react";

interface ReleaseRequirement {
  id: string;
  label: string;
  description: string;
  isBuiltIn: boolean;
}

const BUILT_IN_REQUIREMENTS: ReleaseRequirement[] = [
  { id: "valid_id", label: "Valid ID", description: "Government-issued photo ID", isBuiltIn: true },
  { id: "registration", label: "Vehicle Registration", description: "Current registration or title", isBuiltIn: true },
  { id: "insurance", label: "Proof of Insurance", description: "Valid insurance card", isBuiltIn: true },
  { id: "payment", label: "Payment in Full", description: "All fees must be paid", isBuiltIn: true },
  { id: "lien_release", label: "Lien Release", description: "If vehicle has a lienholder", isBuiltIn: true },
  { id: "police_release", label: "Police Release", description: "For police-ordered tows", isBuiltIn: true },
];

export function ImpoundReleaseEditor() {
  const { tenant } = useAuth();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [selectedRequirements, setSelectedRequirements] = useState<string[]>([]);
  const [customRequirements, setCustomRequirements] = useState<ReleaseRequirement[]>([]);
  const [newCustom, setNewCustom] = useState({ label: "", description: "" });

  useEffect(() => {
    if (tenant?.id) {
      loadSettings();
    }
  }, [tenant?.id]);

  const loadSettings = async () => {
    if (!tenant?.id) return;
    setLoading(true);
    try {
      const { data, error } = await supabase
        .from("impound_settings")
        .select("default_release_requirements")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error) throw error;

      const requirements = data?.default_release_requirements || ["valid_id", "registration", "payment"];
      
      // Separate built-in from custom
      const builtInIds = BUILT_IN_REQUIREMENTS.map(r => r.id);
      const selected = requirements.filter((r: string) => builtInIds.includes(r));
      const custom = requirements
        .filter((r: string) => !builtInIds.includes(r))
        .map((r: string) => ({
          id: r,
          label: r.replace(/_/g, " ").replace(/\b\w/g, (l: string) => l.toUpperCase()),
          description: "",
          isBuiltIn: false,
        }));

      setSelectedRequirements(selected);
      setCustomRequirements(custom);
    } catch (error) {
      console.error("Failed to load release requirements:", error);
      toast.error("Failed to load requirements");
    } finally {
      setLoading(false);
    }
  };

  const saveSettings = async () => {
    if (!tenant?.id) return;
    setSaving(true);
    try {
      const allRequirements = [
        ...selectedRequirements,
        ...customRequirements.map(r => r.id),
      ];

      const { error } = await supabase
        .from("impound_settings")
        .upsert({
          tenant_id: tenant.id,
          default_release_requirements: allRequirements,
          updated_at: new Date().toISOString(),
        }, { onConflict: "tenant_id" });

      if (error) throw error;
      toast.success("Release requirements saved");
    } catch (error: any) {
      console.error("Failed to save:", error);
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const toggleRequirement = (id: string) => {
    setSelectedRequirements(prev =>
      prev.includes(id) ? prev.filter(r => r !== id) : [...prev, id]
    );
  };

  const addCustomRequirement = () => {
    if (!newCustom.label.trim()) return;
    const id = newCustom.label.toLowerCase().replace(/\s+/g, "_");
    setCustomRequirements(prev => [
      ...prev,
      { id, label: newCustom.label.trim(), description: newCustom.description.trim(), isBuiltIn: false },
    ]);
    setNewCustom({ label: "", description: "" });
  };

  const removeCustomRequirement = (id: string) => {
    setCustomRequirements(prev => prev.filter(r => r.id !== id));
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  // Build preview list
  const allActiveRequirements = [
    ...BUILT_IN_REQUIREMENTS.filter(r => selectedRequirements.includes(r.id)),
    ...customRequirements,
  ];

  return (
    <div className="space-y-6">
      {/* AI Preview */}
      <div className="rounded-lg border bg-primary/5 border-primary/20 p-4">
        <div className="flex items-start gap-3">
          <Sparkles className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div>
            <p className="text-sm font-medium text-primary mb-1">What the AI tells customers</p>
            <p className="text-sm italic">
              "To pick up your vehicle, you'll need to bring: 
              {allActiveRequirements.length > 0 
                ? ` ${allActiveRequirements.map(r => r.label.toLowerCase()).join(", ")}.`
                : " a valid ID and payment."
              } Make sure to have all documents ready when you arrive."
            </p>
          </div>
        </div>
      </div>

      {/* Standard Requirements */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <div className="flex items-center gap-2 mb-2">
            <FileCheck className="h-4 w-4 text-muted-foreground" />
            <h4 className="font-medium">Standard Requirements</h4>
          </div>
          <p className="text-sm text-muted-foreground mb-4">
            Select the documents and conditions required to release a vehicle. The AI will tell callers exactly what to bring.
          </p>

          <div className="space-y-3">
            {BUILT_IN_REQUIREMENTS.map((req) => (
              <label
                key={req.id}
                className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                  selectedRequirements.includes(req.id)
                    ? "border-primary bg-primary/5"
                    : "hover:bg-muted/50"
                }`}
              >
                <Checkbox
                  checked={selectedRequirements.includes(req.id)}
                  onCheckedChange={() => toggleRequirement(req.id)}
                  className="mt-0.5"
                />
                <div>
                  <span className="text-sm font-medium">{req.label}</span>
                  <p className="text-xs text-muted-foreground">{req.description}</p>
                </div>
              </label>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Custom Requirements */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <h4 className="font-medium">Custom Requirements</h4>
          <p className="text-sm text-muted-foreground">
            Add specific requirements for your business that aren't listed above. For example: "Manager approval for police holds" or "Lienholder authorization letter".
          </p>

          {customRequirements.length > 0 && (
            <div className="space-y-2">
              {customRequirements.map((req) => (
                <div
                  key={req.id}
                  className="flex items-center justify-between p-3 rounded-lg border bg-muted/30"
                >
                  <div>
                    <span className="text-sm font-medium">{req.label}</span>
                    {req.description && (
                      <p className="text-xs text-muted-foreground">{req.description}</p>
                    )}
                  </div>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => removeCustomRequirement(req.id)}
                  >
                    <X className="h-4 w-4" />
                  </Button>
                </div>
              ))}
            </div>
          )}

          <div className="space-y-3 p-4 rounded-lg border bg-muted/30">
            <div className="space-y-2">
              <Label>Requirement Name</Label>
              <Input
                placeholder="e.g., Manager Signature"
                value={newCustom.label}
                onChange={(e) => setNewCustom(prev => ({ ...prev, label: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label>Description (optional)</Label>
              <Input
                placeholder="e.g., Required for vehicles held over 30 days"
                value={newCustom.description}
                onChange={(e) => setNewCustom(prev => ({ ...prev, description: e.target.value }))}
              />
            </div>
            <Button
              variant="outline"
              onClick={addCustomRequirement}
              disabled={!newCustom.label.trim()}
              className="w-full"
            >
              <Plus className="h-4 w-4 mr-2" />
              Add Custom Requirement
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Save */}
      <div className="flex justify-end">
        <Button onClick={saveSettings} disabled={saving}>
          {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          Save Requirements
        </Button>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Loader2, Save, ShieldAlert, Plus, X } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";

const examplePromises = [
  "Never promise same-day service without checking availability",
  "Never guarantee exact arrival times (only windows)",
  "Never commit to prices without knowing job details",
  "Never promise we can service areas outside our coverage",
];

export function AINeverPromiseEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  const [promises, setPromises] = useState<string[]>([]);
  const [newPromise, setNewPromise] = useState("");
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    if (tenant) {
      const aiNeverPromise = tenant.ai_never_promise;
      if (Array.isArray(aiNeverPromise)) {
        setPromises(aiNeverPromise);
      }
      setIsLoading(false);
    }
  }, [tenant]);

  const handleAddPromise = () => {
    const trimmed = newPromise.trim();
    if (trimmed && !promises.includes(trimmed)) {
      setPromises([...promises, trimmed]);
      setNewPromise("");
    }
  };

  const handleRemovePromise = (index: number) => {
    setPromises(promises.filter((_, i) => i !== index));
  };

  const handleSave = async () => {
    if (!tenant?.id) return;

    setIsSaving(true);
    try {
      const { error } = await supabase
        .from("tenants")
        .update({ ai_never_promise: promises } as any)
        .eq("id", tenant.id);

      if (error) throw error;

      toast.success("AI restrictions updated successfully");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (error: unknown) {
      const errorMessage = error instanceof Error ? error.message : "Failed to save";
      toast.error(errorMessage);
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6 text-center">
          <Loader2 className="h-6 w-6 animate-spin mx-auto" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <ShieldAlert className="h-5 w-5" />
          Things the AI Should Never Promise
        </CardTitle>
        <CardDescription>
          Define guardrails to prevent your AI from making commitments you can't keep.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Current Promises List */}
        {promises.length > 0 ? (
          <div className="space-y-2">
            {promises.map((promise, index) => (
              <div
                key={index}
                className="flex items-center gap-2 p-3 rounded-lg border bg-card"
              >
                <ShieldAlert className="h-4 w-4 text-destructive shrink-0" />
                <span className="text-sm flex-1">{promise}</span>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => handleRemovePromise(index)}
                  className="h-8 w-8 p-0"
                >
                  <X className="h-4 w-4" />
                </Button>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-6 text-muted-foreground">
            <ShieldAlert className="h-8 w-8 mx-auto mb-2 opacity-50" />
            <p className="text-sm">No restrictions configured yet</p>
            <p className="text-xs">Add rules below to protect your business</p>
          </div>
        )}

        {/* Add New Promise */}
        <div className="flex gap-2">
          <Input
            placeholder="e.g., Never promise same-day service without checking"
            value={newPromise}
            onChange={(e) => setNewPromise(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleAddPromise()}
          />
          <Button variant="outline" onClick={handleAddPromise} disabled={!newPromise.trim()}>
            <Plus className="h-4 w-4 mr-1" />
            Add
          </Button>
        </div>

        {/* Example Suggestions */}
        {promises.length < 3 && (
          <div className="pt-4 border-t">
            <p className="text-xs text-muted-foreground mb-2">Common examples (click to add):</p>
            <div className="flex flex-wrap gap-2">
              {examplePromises
                .filter((ex) => !promises.includes(ex))
                .slice(0, 3)
                .map((example) => (
                  <Badge
                    key={example}
                    variant="outline"
                    className="cursor-pointer hover:bg-muted"
                    onClick={() => setPromises([...promises, example])}
                  >
                    + {example.substring(0, 40)}...
                  </Badge>
                ))}
            </div>
          </div>
        )}

        {/* Save Button */}
        <div className="flex justify-end pt-4">
          <Button onClick={handleSave} disabled={isSaving}>
            {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
            <Save className="h-4 w-4 mr-2" />
            Save Restrictions
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
