    { name: "Couples Packages", description: "Side-by-side treatments", category: "Special Events" },
    { name: "Aromatherapy", description: "Essential oil treatments", category: "Add-on Services" },
  ],
  
  // Cleaning
  cleaning: [
    { name: "Deep Cleaning", description: "Intensive one-time cleaning", category: "Specialty" },
    { name: "Move-In/Move-Out", description: "Cleaning for moves", category: "Specialty" },
    { name: "Carpet Cleaning", description: "Professional carpet shampooing", category: "Specialty" },
    { name: "Window Cleaning", description: "Interior and exterior windows", category: "Add-on Services" },
    { name: "Organizing Services", description: "Home organization", category: "Add-on Services" },
    { name: "Pressure Washing", description: "Exterior surface cleaning", category: "Exterior" },
  ],
  
  // Landscaping
  landscaping: [
    { name: "Irrigation Systems", description: "Sprinkler installation and repair", category: "Installation" },
    { name: "Tree Services", description: "Trimming, removal, and planting", category: "Specialty" },
    { name: "Hardscaping", description: "Patios, walkways, and retaining walls", category: "Construction" },
    { name: "Outdoor Lighting", description: "Landscape lighting design", category: "Add-on Services" },
    { name: "Snow Removal", description: "Winter snow and ice services", category: "Seasonal" },
    { name: "Pest Control", description: "Lawn pest treatment", category: "Maintenance" },
  ],
  
  // Auto Repair/Mechanic
  auto_repair: [
    { name: "Detailing", description: "Interior/exterior detailing", category: "Detailing" },
    { name: "Body Work", description: "Collision and dent repair", category: "Body Work" },
    { name: "Window Tinting", description: "Automotive tinting", category: "Add-on Services" },
    { name: "Fleet Services", description: "Commercial fleet maintenance", category: "Commercial" },
    { name: "Performance Upgrades", description: "Performance parts and tuning", category: "Specialty" },
    { name: "Vehicle Inspections", description: "State inspections and pre-purchase", category: "Inspection" },
  ],
  
  // Medical/Healthcare
  medical: [
    { name: "Lab Services", description: "On-site lab work and testing", category: "Diagnostics" },
    { name: "Telemedicine", description: "Virtual consultations", category: "Virtual Care" },
    { name: "Wellness Programs", description: "Preventive care and wellness", category: "Wellness" },
    { name: "Physical Therapy", description: "Rehabilitation services", category: "Therapy" },
  ],
  medspa: [
    { name: "IV Therapy", description: "Vitamin and hydration infusions", category: "Wellness" },
    { name: "Weight Management", description: "Medical weight loss programs", category: "Wellness" },
    { name: "Skincare Products", description: "Professional-grade skincare", category: "Retail" },
    { name: "Membership Plans", description: "Monthly treatment packages", category: "Plans" },
  ],
  
  // Photography
  photography: [
    { name: "Videography", description: "Professional video services", category: "Video" },
    { name: "Photo Editing", description: "Advanced retouching and editing", category: "Post-Production" },
    { name: "Prints & Albums", description: "Professional printing services", category: "Products" },
    { name: "Drone Photography", description: "Aerial photography", category: "Specialty" },
  ],
  
  // Fitness
  fitness: [
    { name: "Nutrition Coaching", description: "Meal planning and nutrition advice", category: "Wellness" },
    { name: "Online Training", description: "Virtual workout programs", category: "Virtual" },
    { name: "Group Classes", description: "Small group training sessions", category: "Classes" },
    { name: "Recovery Services", description: "Stretching, massage, recovery", category: "Wellness" },
  ],
  
  // Pet Services
  pet_grooming: [
    { name: "Pet Boarding", description: "Overnight pet care", category: "Boarding" },
    { name: "Pet Sitting", description: "In-home pet sitting", category: "Care" },
    { name: "Pet Photography", description: "Professional pet photos", category: "Specialty" },
    { name: "Pet Products", description: "Premium pet supplies", category: "Retail" },
  ],
  
  // Locksmith
  locksmith: [
    { name: "Safe Services", description: "Safe opening and installation", category: "Specialty" },
    { name: "Security Systems", description: "Security system installation", category: "Installation" },
    { name: "Access Control", description: "Commercial access systems", category: "Commercial" },
    { name: "Key Duplication", description: "Key copying services", category: "Services" },
  ],
};

// Map business_mode to default suggestions when no specific industry match
const MODE_DEFAULT_SUGGESTIONS: Record<string, AdditionalServiceSuggestion[]> = {
  dispatch: [
    { name: "Vehicle Storage", description: "Short and long-term storage", category: "Storage" },
    { name: "Minor Repairs", description: "Basic repair services", category: "Auto Repair" },
    { name: "Fleet Services", description: "Commercial fleet support", category: "Commercial" },
  ],
  service: [
    { name: "Maintenance Plans", description: "Recurring service agreements", category: "Plans" },
    { name: "Emergency Services", description: "After-hours emergency calls", category: "Emergency" },
    { name: "Consulting", description: "Expert consultation and advice", category: "Consulting" },
  ],
  food: [
    { name: "Catering", description: "Event catering services", category: "Catering" },
    { name: "Meal Prep", description: "Weekly meal preparation", category: "Specialty" },
    { name: "Private Events", description: "Private dining and events", category: "Events" },
  ],
  medical: [
    { name: "Telemedicine", description: "Virtual consultations", category: "Virtual Care" },
    { name: "Wellness Programs", description: "Preventive care programs", category: "Wellness" },
  ],
  general: [
    { name: "Consulting", description: "Expert consultation", category: "Consulting" },
    { name: "Custom Services", description: "Tailored solutions", category: "Specialty" },
  ],
};

// Categories that are relevant by mode
const MODE_CATEGORIES: Record<string, string[]> = {
  dispatch: ["Auto Repair", "Body Work", "Detailing", "Storage", "Maintenance", "Impound", "Glass", "Commercial"],
  service: ["Maintenance", "Specialty", "Add-on Services", "Plans", "Installation", "Emergency", "Consulting"],
  food: ["Catering", "Events", "Specialty", "Delivery"],
  medical: ["Wellness", "Diagnostics", "Therapy", "Virtual Care", "Specialty"],
  general: ["Consulting", "Specialty", "Add-on Services", "Other"],
};

export function AdditionalServicesEditor() {
  const { tenant } = useAuth();
  const { services, isLoading } = useServices();
  const { businessMode } = useTenantConfig();
  const queryClient = useQueryClient();

  const [expandedServiceId, setExpandedServiceId] = useState<string | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingService, setDeletingService] = useState<any | null>(null);
  const [editingFormData, setEditingFormData] = useState<Record<string, ServiceFormData>>({});
  const [savingServiceId, setSavingServiceId] = useState<string | null>(null);
  const [isCreatingNew, setIsCreatingNew] = useState(false);
  const [newServiceData, setNewServiceData] = useState<ServiceFormData>(defaultFormData);
  const [showSuggestions, setShowSuggestions] = useState(false);

  // Filter to only secondary services - must be before useMemo that depends on it
  const secondaryServices = services?.filter(s => s.service_type === "secondary") || [];

  // Get industry from tenant
  const tenantIndustry = tenant?.industry?.toLowerCase() || "";
  
  // Get industry-aware suggestions
  const industrySuggestions = useMemo(() => {
    // Try exact industry match first
    const exactMatch = INDUSTRY_ADDON_SUGGESTIONS[tenantIndustry];
    if (exactMatch) return exactMatch;
    
    // Try partial matches (e.g., "auto_detailing" -> "detailing")
    for (const [key, suggestions] of Object.entries(INDUSTRY_ADDON_SUGGESTIONS)) {
      if (tenantIndustry.includes(key) || key.includes(tenantIndustry)) {
        return suggestions;
      }
    }
    
    // Fall back to mode defaults
    return MODE_DEFAULT_SUGGESTIONS[businessMode] || MODE_DEFAULT_SUGGESTIONS.general;
  }, [tenantIndustry, businessMode]);
  
  // Get relevant categories for the current industry/mode
  const categoryOptions = useMemo(() => {
    const baseCategories = MODE_CATEGORIES[businessMode] || MODE_CATEGORIES.general;
    // Add any unique categories from industry suggestions
    const suggestionCategories = industrySuggestions.map(s => s.category);
    const allCategories = [...new Set([...baseCategories, ...suggestionCategories])];
    // Always add "Other" at the end
    if (!allCategories.includes("Other")) {
      allCategories.push("Other");
    }
    return allCategories;
  }, [businessMode, industrySuggestions]);
  
  // Filter out suggestions that are already added
  const availableSuggestions = useMemo(() => {
    const existingNames = secondaryServices.map(s => s.name.toLowerCase());
    return industrySuggestions.filter(
      suggestion => !existingNames.includes(suggestion.name.toLowerCase())
    );
  }, [industrySuggestions, secondaryServices]);

  const formatPrice = (service: any) => {
    if (service.price_type === "quote_only") return "Quote/Callback";
    if (!service.price_amount) return "Not Set";
    const prefix = service.price_type === "starting_at" ? "From " : "";
    return `${prefix}$${service.price_amount}`;
  };

  const toggleService = (serviceId: string, service: any) => {
    if (expandedServiceId === serviceId) {
      setExpandedServiceId(null);
    } else {
      setExpandedServiceId(serviceId);
      if (!editingFormData[serviceId]) {
        setEditingFormData(prev => ({
          ...prev,
          [serviceId]: {
            name: service.name,
            description: service.description || "",
            service_category: service.service_category || "",
            price_type: service.price_type,
            price_amount: service.price_amount ? Number(service.price_amount) : null,
            duration_minutes: service.duration_minutes || 60,
          }
        }));
      }
    }
    setIsCreatingNew(false);
  };

  const updateFormField = (serviceId: string, field: keyof ServiceFormData, value: any) => {
    setEditingFormData(prev => ({
      ...prev,
      [serviceId]: {
        ...prev[serviceId],
        [field]: value,
      }
    }));
  };

  const handleSave = async (serviceId: string) => {
    if (!tenant?.id) return;
    const formData = editingFormData[serviceId];
    if (!formData || !formData.name.trim()) return;

    setSavingServiceId(serviceId);
    try {
      await updateService(serviceId, tenant.id, {
        name: formData.name.trim(),
        description: formData.description.trim() || undefined,
        service_category: formData.service_category.trim() || undefined,
        price_type: formData.price_type,
        price_amount: formData.price_amount,
        duration_minutes: formData.duration_minutes,
        service_type: "secondary",
      });
      toast.success("Service updated");
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      setExpandedServiceId(null);
    } catch (error: any) {
      toast.error(error.message || "Failed to save service");
    } finally {
      setSavingServiceId(null);
    }
  };

  const handleCreateNew = async () => {
    if (!tenant?.id || !newServiceData.name.trim()) return;

    setSavingServiceId("new");
    try {
      await createService(tenant.id, {
        name: newServiceData.name.trim(),
        description: newServiceData.description.trim() || undefined,
        service_category: newServiceData.service_category.trim() || undefined,
        price_type: newServiceData.price_type,
        price_amount: newServiceData.price_amount,
        duration_minutes: newServiceData.duration_minutes,
        service_type: "secondary",
        is_active: true,
      });
      toast.success("Additional service added");
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      setIsCreatingNew(false);
      setNewServiceData(defaultFormData);
    } catch (error: any) {
      toast.error(error.message || "Failed to create service");
    } finally {
      setSavingServiceId(null);
    }
  };

  const handleDelete = async () => {
    if (!tenant?.id || !deletingService) return;

    try {
      await deleteService(deletingService.id, tenant.id);
      toast.success("Service removed");
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      setDeleteDialogOpen(false);
      setDeletingService(null);
    } catch (error: any) {
      toast.error(error.message || "Failed to delete service");
    }
  };

  const handleToggleActive = async (service: any, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!tenant?.id) return;

    try {
      await updateService(service.id, tenant.id, {
        is_active: !service.is_active,
      });
      toast.success(service.is_active ? "Service hidden from AI" : "Service visible to AI");
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to update service");
    }
  };

  const startCreatingNew = () => {
    setIsCreatingNew(true);
    setExpandedServiceId(null);
    setNewServiceData(defaultFormData);
  };

  // Get an industry-aware example for the explanation - must be before any early returns
  const industryExample = useMemo(() => {
    const examples: Record<string, string> = {
      towing: "a tow company might also offer body work, auto repair, or detailing",
      roadside: "a roadside service might also offer tire sales or battery replacement",
      detailing: "a detailing business might also offer ceramic coating or window tinting",
      hvac: "an HVAC company might also offer duct cleaning or maintenance plans",
      plumbing: "a plumber might also offer water heater services or drain cleaning",
      electrical: "an electrician might also offer EV charger installation or smart home wiring",
      salon: "a salon might also offer makeup services, skincare, or nail services",
      cleaning: "a cleaning service might also offer deep cleaning, carpet cleaning, or pressure washing",
      landscaping: "a landscaping company might also offer irrigation systems or tree services",
      auto_repair: "an auto shop might also offer detailing, body work, or inspections",
    };
    
    // Try to find a matching example
    for (const [key, example] of Object.entries(examples)) {
      if (tenantIndustry.includes(key) || key.includes(tenantIndustry)) {
        return example;
      }
    }
    
    // Default by mode
    const modeExamples: Record<string, string> = {
      dispatch: "a service company might also offer repairs, storage, or maintenance",
      service: "a service business might also offer maintenance plans or specialty services",
      food: "a restaurant might also offer catering or meal prep services",
      medical: "a medical practice might also offer telemedicine or wellness programs",
      general: "a business might also offer consulting or add-on services",
    };
    return modeExamples[businessMode] || modeExamples.general;
  }, [tenantIndustry, businessMode]);

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="ml-3 text-sm text-muted-foreground">Loading services...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Build AI preview based on configured services
  const aiPreview = secondaryServices.length > 0
    ? secondaryServices.some(s => s.price_amount)
      ? `We also offer ${secondaryServices.map(s => s.name.toLowerCase()).join(", ")}. Would you like pricing information?`
      : `We also offer ${secondaryServices.map(s => s.name.toLowerCase()).join(", ")}. Would you like me to have someone call you with details?`
    : null;

  // Inline form component
  const ServiceForm = ({ 
    formData, 
    onChange, 
    onSave, 
    onCancel, 
    isSaving,
    isNew = false 
  }: { 
    formData: ServiceFormData;
    onChange: (field: keyof ServiceFormData, value: any) => void;
    onSave: () => void;
    onCancel: () => void;
    isSaving: boolean;
    isNew?: boolean;
  }) => (
    <div className="p-4 space-y-4 border-t bg-muted/20">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label className="text-xs">Service Name *</Label>
          <Input
            value={formData.name}
            onChange={(e) => onChange("name", e.target.value)}
            placeholder="Body Work, Auto Repair, etc."
          />
        </div>
        <div className="space-y-2">
          <Label className="text-xs">Category</Label>
          <Select
            value={formData.service_category || ""}
            onValueChange={(v) => onChange("service_category", v)}
          >
            <SelectTrigger>
              <SelectValue placeholder="Select category..." />
            </SelectTrigger>
            <SelectContent>
              {categoryOptions.map(cat => (
                <SelectItem key={cat} value={cat}>{cat}</SelectItem>
              ))}
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground">Groups related services together</p>
        </div>
      </div>

      <div className="space-y-2">
        <Label className="text-xs">Description (optional)</Label>
        <Textarea
          value={formData.description}
          onChange={(e) => onChange("description", e.target.value)}
          placeholder="What's included, who it's for, any details the AI should know..."
          rows={2}
        />
        <p className="text-xs text-muted-foreground">
          The more detail you add, the better the AI can explain this service
        </p>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label className="text-xs">How should AI handle pricing?</Label>
          <Select
            value={formData.price_type}
            onValueChange={(v) => onChange("price_type", v)}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="fixed">Quote exact price</SelectItem>
              <SelectItem value="starting_at">Quote "starting at" price</SelectItem>
              <SelectItem value="quote_only">Offer callback for quote</SelectItem>
            </SelectContent>
          </Select>
          <div className="text-xs text-muted-foreground flex items-start gap-1.5 mt-1">
            {formData.price_type === "fixed" && (
              <><DollarSign className="h-3 w-3 mt-0.5 text-primary" /><span>AI says: "That's $X"</span></>
            )}
            {formData.price_type === "starting_at" && (
              <><DollarSign className="h-3 w-3 mt-0.5 text-primary/70" /><span>AI says: "Starting at $X"</span></>
            )}
            {formData.price_type === "quote_only" && (
              <><PhoneCall className="h-3 w-3 mt-0.5 text-muted-foreground" /><span>AI says: "I'll have someone call you"</span></>
            )}
          </div>
        </div>
        <div className="space-y-2">
          <Label className="text-xs">Price ($)</Label>
          <Input
            type="number"
            step="0.01"
            value={formData.price_amount ?? ""}
            onChange={(e) => onChange("price_amount", e.target.value ? parseFloat(e.target.value) : null)}
            placeholder="150.00"
            disabled={formData.price_type === "quote_only"}
          />
        </div>
      </div>

      <div className="flex items-center justify-end gap-2 pt-2">
        <Button variant="outline" size="sm" onClick={onCancel} disabled={isSaving}>
          <X className="h-4 w-4 mr-1" />
          Cancel
        </Button>
        <Button size="sm" onClick={onSave} disabled={isSaving || !formData.name.trim()}>
          {isSaving ? (
            <Loader2 className="h-4 w-4 mr-1 animate-spin" />
          ) : (
            <Check className="h-4 w-4 mr-1" />
          )}
          {isNew ? "Add Service" : "Save Changes"}
        </Button>
      </div>
    </div>
  );
  return (
    <div className="space-y-6">
      {/* Explanation Card */}
      <div className="rounded-lg border bg-muted/30 p-4">
        <div className="flex items-start gap-3">
          <Info className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div className="space-y-2">
            <p className="text-sm font-medium">What are Additional Services?</p>
            <p className="text-sm text-muted-foreground">
              These are services your business offers <strong>in addition</strong> to your core business. 
              For example, {industryExample}. 
              The AI will mention these when relevant and either quote prices or offer callbacks based on your configuration.
            </p>
            <div className="flex items-center gap-2 pt-1">
              <Lightbulb className="h-4 w-4 text-warning shrink-0" />
              <p className="text-xs text-muted-foreground">
                <strong>Tip:</strong> Add as much or as little detail as you want — the AI adapts!
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* AI Preview */}
      {aiPreview && (
        <div className="rounded-lg border bg-primary/5 border-primary/20 p-4">
          <div className="flex items-start gap-3">
            <Wrench className="h-5 w-5 text-primary shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-medium text-primary mb-1">What the AI tells customers</p>
              <p className="text-sm italic">"{aiPreview}"</p>
            </div>
          </div>
        </div>
      )}

      {/* Industry-Aware Suggestions */}
      {availableSuggestions.length > 0 && (
        <Collapsible open={showSuggestions} onOpenChange={setShowSuggestions}>
          <div className="rounded-lg border bg-accent/30 border-accent/50 overflow-hidden">
            <CollapsibleTrigger asChild>
              <button className="w-full px-4 py-3 flex items-center justify-between hover:bg-accent/50 transition-colors text-left">
                <div className="flex items-center gap-3">
                  <Sparkles className="h-5 w-5 text-accent-foreground shrink-0" />
                  <div>
                    <p className="text-sm font-medium">
                      Suggested services for your business
                    </p>
                    <p className="text-xs text-muted-foreground">
                      {availableSuggestions.length} suggestion{availableSuggestions.length !== 1 ? 's' : ''} based on your industry
                    </p>
                  </div>
                </div>
                {showSuggestions ? (
                  <ChevronDown className="h-4 w-4 text-muted-foreground" />
                ) : (
                  <ChevronRight className="h-4 w-4 text-muted-foreground" />
                )}
              </button>
            </CollapsibleTrigger>
            <CollapsibleContent>
              <div className="px-4 pb-4 pt-1 space-y-2">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                  {availableSuggestions.map((suggestion) => (
                    <button
                      key={suggestion.name}
                      onClick={() => {
                        setNewServiceData({
                          ...defaultFormData,
                          name: suggestion.name,
                          description: suggestion.description,
                          service_category: suggestion.category,
                        });
                        setIsCreatingNew(true);
                        setShowSuggestions(false);
                      }}
                      className="flex items-start gap-3 p-3 rounded-md border bg-background hover:bg-muted/50 transition-colors text-left group"
                    >
                      <Plus className="h-4 w-4 text-muted-foreground group-hover:text-primary mt-0.5 shrink-0" />
                      <div className="min-w-0">
                        <p className="text-sm font-medium truncate">{suggestion.name}</p>
                        <p className="text-xs text-muted-foreground line-clamp-2">{suggestion.description}</p>
                        <Badge variant="secondary" className="mt-1 text-xs">{suggestion.category}</Badge>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            </CollapsibleContent>
          </div>
        </Collapsible>
      )}

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h3 className="text-lg font-semibold">Additional Services</h3>
          <p className="text-sm text-muted-foreground">
            {secondaryServices.length 
              ? `${secondaryServices.length} additional service${secondaryServices.length !== 1 ? 's' : ''} configured`
              : "Add services beyond your core business"
            }
          </p>
        </div>
        <Button onClick={startCreatingNew} disabled={isCreatingNew}>
          <Plus className="h-4 w-4 mr-2" />
          Add Service
        </Button>
      </div>

      {/* New Service Form */}
      {isCreatingNew && (
        <Card>
          <div className="px-4 py-3 flex items-center gap-3 bg-primary/5 border-b">
            <Plus className="h-4 w-4 text-primary" />
            <span className="font-medium text-sm">New Additional Service</span>
          </div>
          <ServiceForm
            formData={newServiceData}
            onChange={(field, value) => setNewServiceData(prev => ({ ...prev, [field]: value }))}
            onSave={handleCreateNew}
            onCancel={() => {
              setIsCreatingNew(false);
              setNewServiceData(defaultFormData);
            }}
            isSaving={savingServiceId === "new"}
            isNew
          />
        </Card>
      )}

      {/* Services List */}
      {secondaryServices.length > 0 ? (
        <div className="space-y-2">
          {secondaryServices.map((service) => {
            const isExpanded = expandedServiceId === service.id;
            const formData = editingFormData[service.id];

            return (
              <Collapsible
                key={service.id}
                open={isExpanded}
                onOpenChange={() => toggleService(service.id, service)}
              >
                <Card className="overflow-hidden">
                  <CollapsibleTrigger asChild>
                    <button className="w-full px-4 py-3 flex items-center justify-between hover:bg-muted/50 transition-colors text-left">
                      <div className="flex items-center gap-3 flex-1 min-w-0">
                        {isExpanded ? (
                          <ChevronDown className="h-4 w-4 text-muted-foreground shrink-0" />
                        ) : (
                          <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
                        )}
                        <div className="min-w-0">
                          <div className="flex items-center gap-2">
                            <span className="font-medium text-sm truncate">{service.name}</span>
                            {service.service_category && (
                              <Badge variant="secondary" className="text-xs shrink-0">
                                {service.service_category}
                              </Badge>
                            )}
                            {!service.is_active && (
                              <Badge variant="outline" className="text-xs shrink-0">Hidden</Badge>
                            )}
                          </div>
                          {service.description && (
                            <p className="text-xs text-muted-foreground truncate mt-0.5">
                              {service.description}
                            </p>
                          )}
                        </div>
                      </div>
                      <div className="flex items-center gap-4 shrink-0">
                        <span className="text-sm font-medium">{formatPrice(service)}</span>
                        <Button
                          size="icon"
                          variant="ghost"
                          className="h-7 w-7 text-destructive hover:text-destructive shrink-0"
                          onClick={(e) => {
                            e.stopPropagation();
                            setDeletingService(service);
                            setDeleteDialogOpen(true);
                          }}
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                        </Button>
                      </div>
                    </button>
                  </CollapsibleTrigger>
                  <CollapsibleContent>
                    {formData && (
                      <ServiceForm
                        formData={formData}
                        onChange={(field, value) => updateFormField(service.id, field, value)}
                        onSave={() => handleSave(service.id)}
                        onCancel={() => setExpandedServiceId(null)}
                        isSaving={savingServiceId === service.id}
                      />
                    )}
                    <div className="px-4 py-2 border-t bg-muted/10 flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <Switch
                          checked={service.is_active}
                          onCheckedChange={() => handleToggleActive(service, { stopPropagation: () => {} } as any)}
                        />
                        <Label className="text-xs text-muted-foreground">
                          {service.is_active ? "Visible to AI" : "Hidden from AI"}
                        </Label>
                      </div>
                    </div>
                  </CollapsibleContent>
                </Card>
              </Collapsible>
            );
          })}
        </div>
      ) : !isCreatingNew && (
        <Card>
          <CardContent className="p-8 text-center">
            <div className="flex flex-col items-center gap-4 max-w-md mx-auto">
              <div className="h-16 w-16 rounded-full bg-muted flex items-center justify-center">
                <Wrench className="h-8 w-8 text-muted-foreground" />
              </div>
              <div>
                <h3 className="font-semibold text-lg mb-1">No additional services yet</h3>
                <p className="text-sm text-muted-foreground">
                  If your business offers services beyond your core focus (like body work for a tow company), 
                  add them here so the AI can inform customers.
                </p>
              </div>
              <Button onClick={startCreatingNew}>
                <Plus className="h-4 w-4 mr-2" />
                Add Your First Service
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Delete Confirmation */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove Service</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to remove "{deletingService?.name}"? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Remove
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import type { BusinessFAQ } from "@/types/database";
import { HelpCircle, Loader2 } from "lucide-react";
import { createFAQ, updateFAQ, deleteFAQ } from "@/lib/brain/writeBrainFact";
import { invalidateBrainQueries } from "@/lib/brain/invalidateBrainQueries";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { SuggestedFAQButtons } from "./SuggestedFAQButtons";
import { KnowledgeSection } from "../shared/KnowledgeSection";
import { KnowledgeItem } from "../shared/KnowledgeItem";
import { InlineUploadButton } from "../uploads/InlineUploadButton";

export function BusinessFAQEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  // Fetch tenant policies to filter overlapping FAQ suggestions
  const [tenantPolicies, setTenantPolicies] = useState<{ cancellation?: string; deposit?: string; refund?: string }>({});

  const [faqs, setFaqs] = useState<BusinessFAQ[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingFaq, setEditingFaq] = useState<BusinessFAQ | null>(null);
  const [formQuestion, setFormQuestion] = useState('');
  const [formAnswer, setFormAnswer] = useState('');

  useEffect(() => {
    if (tenant?.id) {
      fetchFAQs();
      // Fetch policies for dedup
      supabase
        .from('tenants')
        .select('cancellation_policy, deposit_policy, refund_policy')
        .eq('id', tenant.id)
        .single()
        .then(({ data }) => {
          if (data) {
            setTenantPolicies({
              cancellation: data.cancellation_policy || undefined,
              deposit: data.deposit_policy || undefined,
              refund: data.refund_policy || undefined,
            });
          }
        });
    }
  }, [tenant?.id]);

  const fetchFAQs = async () => {
    if (!tenant?.id) return;
    const { data, error } = await supabase
      .from('business_faqs')
      .select('*')
      .eq('tenant_id', tenant.id)
      .order('priority_weight', { ascending: false });
    if (!error) setFaqs(data || []);
    setLoading(false);
  };

  const openAddDialog = () => {
    setEditingFaq(null);
    setFormQuestion('');
    setFormAnswer('');
    setIsDialogOpen(true);
  };

  const openEditDialog = (faq: BusinessFAQ) => {
    setEditingFaq(faq);
    setFormQuestion(faq.question);
    setFormAnswer(faq.answer);
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!tenant?.id || !formQuestion.trim() || !formAnswer.trim()) return;

    setSaving(true);
    try {
      if (editingFaq) {
        await updateFAQ(editingFaq.id, tenant.id, {
          question: formQuestion,
          answer: formAnswer,
        });
        toast.success("FAQ saved — Your AI will now use this.");
      } else {
        await createFAQ(tenant.id, {
          question: formQuestion,
          answer: formAnswer,
          priority_weight: faqs.length,
        });
        toast.success("FAQ added — Your AI can now answer this question.");
      }
      setIsDialogOpen(false);
      fetchFAQs();
      invalidateBrainQueries(queryClient, tenant?.id);
    } catch (error: any) {
      toast.error(error.message || "Failed to save FAQ");
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteFAQ = async (id: string) => {
    if (!tenant?.id) return;
    try {
      await deleteFAQ(id, tenant.id);
      setFaqs(faqs.filter(f => f.id !== id));
      toast.success("FAQ removed");
      invalidateBrainQueries(queryClient, tenant?.id);
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    }
  };

  const handleSuggestionClick = (question: string, answer: string) => {
    setEditingFaq(null);
    setFormQuestion(question);
    setFormAnswer(answer);
    setIsDialogOpen(true);
  };

  return (
    <>
      {/* Policy dedup notice */}
      {(tenantPolicies.cancellation || tenantPolicies.deposit || tenantPolicies.refund) && (
        <div className="mb-4 p-3 rounded-lg border border-border bg-muted/30 text-sm text-muted-foreground">
          💡 Your cancellation, deposit, and refund policies are managed in the <strong>How You Operate → Policies</strong> tab. Your AI already uses those — no need to duplicate them here as FAQs.
        </div>
      )}


      <KnowledgeSection
        title="FAQs"
        description="Common questions and answers. Your AI will use these to respond to customer inquiries."
        items={faqs}
        isLoading={loading}
        onAdd={openAddDialog}
        addButtonLabel="Add FAQ"
        emptyState={{
          icon: HelpCircle,
          title: "No FAQs yet",
          description: "Add the questions your customers ask most so your AI can answer them instantly.",
        }}
        headerActions={
          <SuggestedFAQButtons
            onAdd={handleSuggestionClick}
            existingQuestions={faqs.map(f => f.question)}
            tenantPolicies={tenantPolicies}
            tenantName={tenant?.name ?? undefined}
            tenantAddress={tenant?.address ?? undefined}
            tenantHours={tenant?.hours_json as Record<string, any> ?? undefined}
            tenantServiceArea={tenant?.service_area_json as { radius_miles?: number } ?? undefined}
          />
        }
        renderItem={(faq) => (
          <KnowledgeItem
            onEdit={() => openEditDialog(faq)}
            onDelete={() => handleDeleteFAQ(faq.id)}
          >
            <p className="font-medium text-sm">{faq.question}</p>
            <p className="text-sm text-muted-foreground mt-1 line-clamp-2">{faq.answer}</p>
          </KnowledgeItem>
        )}
      />

      {/* Add/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editingFaq ? "Edit FAQ" : "Add FAQ"}</DialogTitle>
            <DialogDescription>
              {editingFaq
                ? "Update this question and answer."
                : "Add a common question and how your AI should respond."}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="question">Question</Label>
              <Input
                id="question"
                placeholder="What do customers ask? (e.g., What are your hours?)"
                value={formQuestion}
                onChange={(e) => setFormQuestion(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="answer">Answer</Label>
              <Textarea
                id="answer"
                placeholder="What should AI say? (Write it how you'd say it on the phone)"
                value={formAnswer}
                onChange={(e) => setFormAnswer(e.target.value)}
                rows={4}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)} disabled={saving}>
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              disabled={saving || !formQuestion.trim() || !formAnswer.trim()}
            >
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingFaq ? "Save Changes" : "Add FAQ"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { MessageSquare, Loader2, Plus, Lightbulb } from "lucide-react";
import { createObjectionResponse, updateObjectionResponse, deleteObjectionResponse } from "@/lib/brain/writeBrainFact";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { KnowledgeSection } from "../shared/KnowledgeSection";
import { KnowledgeItem } from "../shared/KnowledgeItem";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { getObjectionExamples } from "@/lib/industryExamples";

interface ObjectionResponse {
  id: string;
  tenant_id: string;
  objection: string;
  response: string;
  priority_weight?: number;
  created_at?: string;
}

export function BusinessObjectionEditor() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const queryClient = useQueryClient();
  
  const examples = getObjectionExamples(businessMode);

  const [objections, setObjections] = useState<ObjectionResponse[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<ObjectionResponse | null>(null);
  const [formObjection, setFormObjection] = useState('');
  const [formResponse, setFormResponse] = useState('');

  useEffect(() => {
    if (tenant?.id) {
      fetchObjections();
    }
  }, [tenant?.id]);

  const fetchObjections = async () => {
    if (!tenant?.id) return;

    const { data, error } = await supabase
      .from('objection_responses')
      .select('*')
      .eq('tenant_id', tenant.id)
      .order('priority_weight', { ascending: false });

    if (error) {
      console.error('Failed to fetch objections:', error);
    } else {
      setObjections(data || []);
    }
    setLoading(false);
  };

  const openAddDialog = () => {
    setEditingItem(null);
    setFormObjection('');
    setFormResponse('');
    setIsDialogOpen(true);
  };

  const openEditDialog = (item: ObjectionResponse) => {
    setEditingItem(item);
    setFormObjection(item.objection);
    setFormResponse(item.response);
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!tenant?.id || !formObjection.trim() || !formResponse.trim()) return;

    setSaving(true);
    try {
      if (editingItem) {
        await updateObjectionResponse(editingItem.id, tenant.id, {
          objection: formObjection,
          response: formResponse,
        });
        toast.success("Response updated");
      } else {
        await createObjectionResponse(tenant.id, {
          objection: formObjection,
          response: formResponse,
          priority_weight: objections.length,
        });
        toast.success("Response added");
      }
      setIsDialogOpen(false);
      fetchObjections();
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const handleDeleteObjection = async (id: string) => {
    if (!tenant?.id) return;

    try {
      await deleteObjectionResponse(id, tenant.id);
      setObjections(objections.filter(o => o.id !== id));
      toast.success("Response deleted");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    }
  };

  // Suggested objection buttons for quick add
  const SuggestedObjectionButtons = () => {
    const availableSuggestions = examples.commonObjections.filter(
      suggestion => !objections.some(o => o.objection.toLowerCase().includes(suggestion.objection.toLowerCase().slice(0, 15)))
    );
    
    if (availableSuggestions.length === 0) return null;
    
    return (
      <div className="space-y-2">
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          <Lightbulb className="h-3 w-3 shrink-0" />
          <span className="truncate">Quick add:</span>
        </div>
        <div className="flex gap-2 overflow-x-auto pb-1 -mb-1 scrollbar-thin">
          {availableSuggestions.slice(0, 3).map((suggestion) => (
            <button
              key={suggestion.objection}
              type="button"
              className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-medium rounded-full border border-border bg-background hover:bg-muted/50 transition-colors whitespace-nowrap shrink-0"
              onClick={() => {
                setEditingItem(null);
                setFormObjection(suggestion.objection);
                setFormResponse(suggestion.response);
                setIsDialogOpen(true);
              }}
            >
              <Plus className="h-3 w-3" />
              {suggestion.objection}
            </button>
          ))}
        </div>
      </div>
    );
  };

  return (
    <>
      <KnowledgeSection
        title="Objection Handling"
        description="When customers have doubts or push back, here's how your AI responds."
        items={objections}
        isLoading={loading}
        onAdd={openAddDialog}
        addButtonLabel="Add Response"
        emptyState={{
          icon: MessageSquare,
          title: "No objection responses",
          description: "Add responses to common customer objections to help your AI close more leads.",
        }}
        headerActions={<SuggestedObjectionButtons />}
        renderItem={(item) => (
          <KnowledgeItem
            onEdit={() => openEditDialog(item)}
            onDelete={() => handleDeleteObjection(item.id)}
          >
            <p className="font-medium text-sm">{item.objection}</p>
            <p className="text-sm text-muted-foreground mt-1 line-clamp-2">{item.response}</p>
          </KnowledgeItem>
        )}
      />

      {/* Add/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>{editingItem ? "Edit Response" : "Add Objection Response"}</DialogTitle>
            <DialogDescription>
              {editingItem
                ? "Update how your AI handles this objection."
                : "Add a common objection and how your AI should respond."}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="objection">When customer says...</Label>
              <Input
                id="objection"
                placeholder={examples.objectionPlaceholder}
                value={formObjection}
                onChange={(e) => setFormObjection(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="response">AI should respond...</Label>
              <Textarea
                id="response"
                placeholder={examples.responsePlaceholder}
                value={formResponse}
                onChange={(e) => setFormResponse(e.target.value)}
                rows={4}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)} disabled={saving}>
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              disabled={saving || !formObjection.trim() || !formResponse.trim()}
            >
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingItem ? "Save Changes" : "Add Response"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Loader2, Save, Info } from "lucide-react";
import { updateBusinessPolicies } from "@/lib/brain/writeBrainFact";
import { supabase } from "@/integrations/supabase/client";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { PolicyTemplateButtons } from "../templates/PolicyTemplateButtons";


import type { BusinessMode } from "@/hooks/useTenantConfig";

// Mode-specific tips for policies
const POLICY_TIPS: Record<BusinessMode, string> = {
  service: "Write policies as if speaking aloud — your AI reads them naturally to callers when explaining booking terms.",
  dispatch: "Key policies for dispatch: payment timing, cancellation fees after driver dispatch, and storage rates if you have an impound lot.",
  food: "Clear delivery minimums and fees prevent confusion. The AI will explain these when customers ask about delivery.",
  medical: "Keep policies HIPAA-compliant. The AI won't discuss specific medical information but will explain appointment and billing policies.",
  general: "Simple, clear policies help your AI answer questions confidently. Write them like you'd explain to a customer.",
  sales: "Define your sales policies clearly — returns, warranties, financing terms. The AI will explain these when asked.",
};

const PAYMENT_METHODS = [
  { id: "cash", label: "Cash" },
  { id: "credit_card", label: "Credit Card" },
  { id: "debit_card", label: "Debit Card" },
  { id: "check", label: "Check" },
  { id: "venmo", label: "Venmo" },
  { id: "paypal", label: "PayPal" },
  { id: "zelle", label: "Zelle" },
];

const PAYMENT_TIMING_OPTIONS = [
  { id: "", label: "Not specified" },
  { id: "at_booking", label: "Payment at time of booking" },
  { id: "deposit_then_balance", label: "Deposit at booking, balance at service" },
  { id: "at_service", label: "Payment due at time of service" },
  { id: "after_completion", label: "Payment due after service completion" },
  { id: "net_30", label: "Net 30 (invoice after service)" },
];

export function BusinessPoliciesEditor() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const queryClient = useQueryClient();

  const [formData, setFormData] = useState({
    cancellation_policy: "",
    deposit_policy: "",
    refund_policy: "",
    payment_methods: [] as string[],
    payment_timing: "",
  });
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    if (tenant) {
      const ctxFields = (tenant as any).context_fields_json as Record<string, any> | null;
      setFormData({
        cancellation_policy: tenant.cancellation_policy || "",
        deposit_policy: tenant.deposit_policy || "",
        refund_policy: tenant.refund_policy || "",
        payment_methods: Array.isArray(tenant.payment_methods) ? tenant.payment_methods : [],
        payment_timing: ctxFields?.payment_timing || "",
      });
      setIsLoading(false);
    }
  }, [tenant]);

  const handleSave = async () => {
    if (!tenant?.id) return;
    setIsSaving(true);
    try {
      await updateBusinessPolicies(tenant.id, {
        cancellation_policy: formData.cancellation_policy.trim() || undefined,
        deposit_policy: formData.deposit_policy.trim() || undefined,
        refund_policy: formData.refund_policy.trim() || undefined,
        payment_methods: formData.payment_methods.length > 0 ? formData.payment_methods : undefined,
      });

      // Save payment timing to context_fields_json
      const timingLabel = PAYMENT_TIMING_OPTIONS.find(o => o.id === formData.payment_timing)?.label || "";
      const existingCtx = ((tenant as any).context_fields_json as Record<string, any>) || {};
      await supabase
        .from("tenants")
        .update({
          context_fields_json: { ...existingCtx, payment_timing: timingLabel },
        })
        .eq("id", tenant.id);

      toast.success("Policies saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const togglePaymentMethod = (methodId: string) => {
    setFormData((prev) => ({
      ...prev,
      payment_methods: prev.payment_methods.includes(methodId)
        ? prev.payment_methods.filter((m) => m !== methodId)
        : [...prev.payment_methods, methodId],
    }));
  };

  // Build preview
  const buildPreview = () => {
    const parts: string[] = [];
    if (formData.cancellation_policy) {
      parts.push(formData.cancellation_policy.split('.')[0] + '.');
    }
    if (formData.payment_methods.length > 0) {
      const methods = formData.payment_methods.map(m => 
        PAYMENT_METHODS.find(pm => pm.id === m)?.label || m
      );
      parts.push(`We accept ${methods.slice(0, 3).join(', ')}${methods.length > 3 ? ' and more' : ''}.`);
    }
    return parts.length > 0 ? parts.join(' ') : "No policies configured yet.";
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Compact mode tip */}
      <p className="text-xs text-muted-foreground">{POLICY_TIPS[businessMode]}</p>

      {/* Cancellation */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label>Cancellation Policy</Label>
          <PolicyTemplateButtons 
            type="cancellation" 
            onSelect={(text) => setFormData({ ...formData, cancellation_policy: text })}
          />
        </div>
        <Textarea
          value={formData.cancellation_policy}
          onChange={(e) => setFormData({ ...formData, cancellation_policy: e.target.value })}
          placeholder="Free cancellation up to 24 hours before..."
          rows={2}
        />
      </div>

      {/* Deposit */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label>Deposit Policy</Label>
          <PolicyTemplateButtons 
            type="deposit" 
            onSelect={(text) => setFormData({ ...formData, deposit_policy: text })}
          />
        </div>
        <Textarea
          value={formData.deposit_policy}
          onChange={(e) => setFormData({ ...formData, deposit_policy: e.target.value })}
          placeholder="$100 deposit to secure booking..."
          rows={2}
        />
      </div>

      {/* Refund */}
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <Label>Refund Policy</Label>
          <PolicyTemplateButtons 
            type="refund" 
            onSelect={(text) => setFormData({ ...formData, refund_policy: text })}
          />
        </div>
        <Textarea
          value={formData.refund_policy}
          onChange={(e) => setFormData({ ...formData, refund_policy: e.target.value })}
          placeholder="Full refund if cancelled 48+ hours in advance..."
          rows={2}
        />
      </div>

      {/* Payment Methods */}
      <div className="space-y-3">
        <Label>Accepted Payments</Label>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
          {PAYMENT_METHODS.map((method) => (
            <label key={method.id} className="flex items-center gap-2 cursor-pointer">
              <Checkbox
                checked={formData.payment_methods.includes(method.id)}
                onCheckedChange={() => togglePaymentMethod(method.id)}
              />
              <span className="text-sm">{method.label}</span>
            </label>
          ))}
        </div>
      </div>

      {/* Payment Timing */}
      <div className="space-y-2">
        <Label>When Is Payment Due?</Label>
        <p className="text-xs text-muted-foreground">
          AI will mention this when customers ask about payment timing
        </p>
        <Select
          value={formData.payment_timing}
          onValueChange={(v) => setFormData({ ...formData, payment_timing: v })}
        >
          <SelectTrigger>
            <SelectValue placeholder="Select payment timing..." />
          </SelectTrigger>
          <SelectContent>
            {PAYMENT_TIMING_OPTIONS.map((opt) => (
              <SelectItem key={opt.id} value={opt.id || "none"}>
                {opt.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Save */}
      <div className="flex justify-end pt-2">
        <Button onClick={handleSave} disabled={isSaving}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save
        </Button>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useQueryClient, useQuery, useMutation } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Lightbulb, FileText, Loader2 } from "lucide-react";
import { SuggestedKnowledgeButtons } from "./SuggestedKnowledgeButtons";
import { KnowledgeSection } from "../shared/KnowledgeSection";
import { KnowledgeItem } from "../shared/KnowledgeItem";
import {
  createCustomKnowledge,
  updateCustomKnowledge,
  deleteCustomKnowledge,
} from "@/lib/brain/writeBrainFact";

interface KnowledgeEntry {
  id: string;
  type: "policy" | "upsell";
  title: string;
  content: string;
  priority_weight: number;
  created_at: string;
}

type CategoryType = "policy" | "upsell";

const categoryLabels: Record<CategoryType, { label: string; icon: typeof FileText }> = {
  policy: { label: "Facts AI should know", icon: FileText },
  upsell: { label: "Things AI should mention", icon: Lightbulb },
};

export function CustomKnowledgeEditor() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Form state
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<KnowledgeEntry | null>(null);
  const [category, setCategory] = useState<CategoryType>("policy");
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  // Fetch existing knowledge entries
  const { data: entries = [], isLoading } = useQuery({
    queryKey: ["custom-knowledge", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("ai_knowledge_base")
        .select("*")
        .eq("tenant_id", tenant.id)
        .in("type", ["policy", "upsell"])
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data as KnowledgeEntry[];
    },
    enabled: !!tenant?.id,
  });

  // Create mutation
  const createMutation = useMutation({
    mutationFn: async (entry: { type: CategoryType; title: string; content: string }) => {
      if (!tenant?.id) throw new Error("No tenant");
      return createCustomKnowledge(tenant.id, entry);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["custom-knowledge", tenant?.id] });
      toast({ title: "Knowledge added!", description: "Your AI now knows this information." });
      resetForm();
    },
    onError: (error: any) => {
      toast({ variant: "destructive", title: "Failed to add", description: error.message });
    },
  });

  // Update mutation
  const updateMutation = useMutation({
    mutationFn: async ({ id, updates }: { id: string; updates: { title?: string; content?: string; type?: CategoryType } }) => {
      if (!tenant?.id) throw new Error("No tenant");
      return updateCustomKnowledge(id, tenant.id, updates);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["custom-knowledge", tenant?.id] });
      toast({ title: "Updated!", description: "Knowledge updated successfully." });
      resetForm();
    },
    onError: (error: any) => {
      toast({ variant: "destructive", title: "Failed to update", description: error.message });
    },
  });

  // Delete mutation
  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      if (!tenant?.id) throw new Error("No tenant");
      return deleteCustomKnowledge(id, tenant.id);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["custom-knowledge", tenant?.id] });
      toast({ title: "Deleted", description: "Knowledge removed." });
    },
    onError: (error: any) => {
      toast({ variant: "destructive", title: "Failed to delete", description: error.message });
    },
  });

  const resetForm = () => {
    setIsDialogOpen(false);
    setEditingEntry(null);
    setCategory("policy");
    setTitle("");
    setContent("");
  };

  const handleSave = () => {
    if (!title.trim() || !content.trim()) {
      toast({ variant: "destructive", title: "Missing fields", description: "Please fill in both title and details." });
      return;
    }

    if (editingEntry) {
      updateMutation.mutate({
        id: editingEntry.id,
        updates: { title: title.trim(), content: content.trim(), type: category },
      });
    } else {
      createMutation.mutate({
        type: category,
        title: title.trim(),
        content: content.trim(),
      });
    }
  };

  const openAddDialog = () => {
    setEditingEntry(null);
    setCategory("policy");
    setTitle("");
    setContent("");
    setIsDialogOpen(true);
  };

  const openEditDialog = (entry: KnowledgeEntry) => {
    setEditingEntry(entry);
    setCategory(entry.type as CategoryType);
    setTitle(entry.title);
    setContent(entry.content);
    setIsDialogOpen(true);
  };

  const handleQuickAdd = (template: { title: string; category: CategoryType; placeholder: string }) => {
    setEditingEntry(null);
    setCategory(template.category);
    setTitle(template.title);
    setContent(template.placeholder);
    setIsDialogOpen(true);
  };

  const isSaving = createMutation.isPending || updateMutation.isPending;
  const existingTitles = entries.map((e) => e.title);

  return (
    <>
      <KnowledgeSection
        title="Custom Knowledge"
        description="Add any information you want your AI to know — from warranties to company history."
        items={entries}
        isLoading={isLoading}
        onAdd={openAddDialog}
        addButtonLabel="Add Knowledge"
        emptyState={{
          icon: Lightbulb,
          title: "No custom knowledge yet",
          description: "Add facts, policies, or promotions that your AI should know about.",
        }}
        headerActions={
          <SuggestedKnowledgeButtons
            onSelect={handleQuickAdd}
            existingTitles={existingTitles}
          />
        }
        renderItem={(entry) => {
          const CategoryIcon = categoryLabels[entry.type as CategoryType]?.icon || FileText;
          return (
            <KnowledgeItem
              onEdit={() => openEditDialog(entry)}
              onDelete={() => deleteMutation.mutate(entry.id)}
            >
              <div className="flex items-center gap-2 mb-1">
                <CategoryIcon className="h-4 w-4 text-muted-foreground shrink-0" />
                <span className="font-medium text-sm truncate">{entry.title}</span>
                <Badge variant="outline" className="text-xs shrink-0">
                  {categoryLabels[entry.type as CategoryType]?.label || entry.type}
                </Badge>
              </div>
              <p className="text-sm text-muted-foreground line-clamp-2">{entry.content}</p>
            </KnowledgeItem>
          );
        }}
      />

      {/* Add/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>{editingEntry ? "Edit Knowledge" : "Add Custom Knowledge"}</DialogTitle>
            <DialogDescription>
              {editingEntry
                ? "Update this knowledge entry."
                : "Add information your AI should know about."}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Type</Label>
                <Select value={category} onValueChange={(v) => setCategory(v as CategoryType)}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="policy">
                      <span className="flex items-center gap-2">
                        <FileText className="h-4 w-4" />
                        Facts AI should know
                      </span>
                    </SelectItem>
                    <SelectItem value="upsell">
                      <span className="flex items-center gap-2">
                        <Lightbulb className="h-4 w-4" />
                        Things AI should mention
                      </span>
                    </SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Topic</Label>
                <Input
                  placeholder="e.g., Warranty Policy"
                  value={title}
                  onChange={(e) => setTitle(e.target.value)}
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Details</Label>
              <Textarea
                placeholder="Write it how you'd explain it to a new employee..."
                value={content}
                onChange={(e) => setContent(e.target.value)}
                rows={4}
              />
              <p className="text-xs text-muted-foreground">
                Write naturally — your AI will use this when relevant.
              </p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={resetForm} disabled={isSaving}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={isSaving || !title.trim() || !content.trim()}>
              {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingEntry ? "Save Changes" : "Add Knowledge"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

/**
 * Custom Policies Editor
 * 
 * Allows businesses to add freeform custom policies beyond the predefined options.
 * Uses the ai_knowledge_base table with type="policy".
