export function CustomPoliciesEditor() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const queryClient = useQueryClient();

  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingPolicy, setEditingPolicy] = useState<CustomPolicy | null>(null);
  const [title, setTitle] = useState("");
  const [content, setContent] = useState("");

  // Fetch custom policies
  const { data: policies = [], isLoading } = useQuery({
    queryKey: ["custom-policies", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("ai_knowledge_base")
        .select("*")
        .eq("tenant_id", tenant.id)
        .eq("type", "policy")
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data as CustomPolicy[];
    },
    enabled: !!tenant?.id,
  });

  // Create mutation
  const createMutation = useMutation({
    mutationFn: async (policy: { title: string; content: string }) => {
      if (!tenant?.id) throw new Error("No tenant");
      const { data, error } = await supabase
        .from("ai_knowledge_base")
        .insert({
          tenant_id: tenant.id,
          type: "policy",
          title: policy.title,
          content: policy.content,
          priority_weight: 50,
        })
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["custom-policies", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["custom-knowledge", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      toast.success("Policy added! Your AI now knows this.");
      resetForm();
    },
    onError: (error: any) => {
      toast.error(error.message || "Failed to add policy");
    },
  });

  // Update mutation
  const updateMutation = useMutation({
    mutationFn: async ({ id, updates }: { id: string; updates: { title: string; content: string } }) => {
      if (!tenant?.id) throw new Error("No tenant");
      const { data, error } = await supabase
        .from("ai_knowledge_base")
        .update(updates)
        .eq("id", id)
        .eq("tenant_id", tenant.id)
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["custom-policies", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["custom-knowledge", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      toast.success("Policy updated!");
      resetForm();
    },
    onError: (error: any) => {
      toast.error(error.message || "Failed to update policy");
    },
  });

  // Delete mutation
  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      if (!tenant?.id) throw new Error("No tenant");
      const { error } = await supabase
        .from("ai_knowledge_base")
        .delete()
        .eq("id", id)
        .eq("tenant_id", tenant.id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["custom-policies", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["custom-knowledge", tenant?.id] });
      toast.success("Policy removed");
    },
    onError: (error: any) => {
      toast.error(error.message || "Failed to delete policy");
    },
  });

  const resetForm = () => {
    setIsDialogOpen(false);
    setEditingPolicy(null);
    setTitle("");
    setContent("");
  };

  const handleSave = () => {
    if (!title.trim() || !content.trim()) {
      toast.error("Please fill in both title and policy details");
      return;
    }

    if (editingPolicy) {
      updateMutation.mutate({
        id: editingPolicy.id,
        updates: { title: title.trim(), content: content.trim() },
      });
    } else {
      createMutation.mutate({
        title: title.trim(),
        content: content.trim(),
      });
    }
  };

  const openAddDialog = () => {
    setEditingPolicy(null);
    setTitle("");
    setContent("");
    setIsDialogOpen(true);
  };

  const openEditDialog = (policy: CustomPolicy) => {
    setEditingPolicy(policy);
    setTitle(policy.title);
    setContent(policy.content);
    setIsDialogOpen(true);
  };

  const handleSuggestionClick = (suggestion: { title: string; placeholder: string }) => {
    setEditingPolicy(null);
    setTitle(suggestion.title);
    setContent(suggestion.placeholder);
    setIsDialogOpen(true);
  };

  const isSaving = createMutation.isPending || updateMutation.isPending;
  const suggestions = POLICY_SUGGESTIONS[businessMode] || POLICY_SUGGESTIONS.general;
  const existingTitles = policies.map((p) => p.title.toLowerCase());
  const availableSuggestions = suggestions.filter(
    (s) => !existingTitles.includes(s.title.toLowerCase())
  );

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Quick Add Suggestions */}
      {availableSuggestions.length > 0 && (
        <div className="space-y-2">
          <Label className="text-xs text-muted-foreground">Suggested policies for your business:</Label>
          <div className="flex flex-wrap gap-2">
            {availableSuggestions.slice(0, 4).map((suggestion) => (
              <Button
                key={suggestion.title}
                variant="outline"
                size="sm"
                className="text-xs"
                onClick={() => handleSuggestionClick(suggestion)}
              >
                <Plus className="h-3 w-3 mr-1" />
                {suggestion.title}
              </Button>
            ))}
          </div>
        </div>
      )}

      {/* Existing Policies */}
      {policies.length > 0 ? (
        <div className="space-y-2">
          {policies.map((policy) => (
            <Card key={policy.id} className="group">
              <CardContent className="p-3">
                <div className="flex items-start justify-between gap-2">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <FileText className="h-4 w-4 text-muted-foreground shrink-0" />
                      <span className="font-medium text-sm truncate">{policy.title}</span>
                    </div>
                    <p className="text-sm text-muted-foreground line-clamp-2">{policy.content}</p>
                  </div>
                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-8 w-8 p-0"
                      onClick={() => openEditDialog(policy)}
                    >
                      <Pencil className="h-3.5 w-3.5" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="h-8 w-8 p-0 text-destructive hover:text-destructive"
                      onClick={() => deleteMutation.mutate(policy.id)}
                      disabled={deleteMutation.isPending}
                    >
                      <Trash2 className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : (
        <div className="text-center py-6 border border-dashed rounded-lg">
          <FileText className="h-8 w-8 mx-auto mb-2 text-muted-foreground/50" />
          <p className="text-sm text-muted-foreground">No custom policies yet</p>
          <p className="text-xs text-muted-foreground mt-1">
            Add policies for scenarios not covered by the standard options
          </p>
        </div>
      )}

      {/* Add Button */}
      <Button variant="outline" onClick={openAddDialog} className="w-full">
        <Plus className="h-4 w-4 mr-2" />
        Add Custom Policy
      </Button>

      {/* Add/Edit Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>{editingPolicy ? "Edit Policy" : "Add Custom Policy"}</DialogTitle>
            <DialogDescription>
              {editingPolicy
                ? "Update this policy. Changes will be available to your AI immediately."
                : "Add a policy for a specific scenario. Your AI will use this when relevant."}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Policy Name</Label>
              <Input
                placeholder="e.g., Weather Policy, Late Arrival, Gift Cards..."
                value={title}
                onChange={(e) => setTitle(e.target.value)}
              />
            </div>
            <div className="space-y-2">
              <Label>Policy Details</Label>
              <Textarea
                placeholder="Explain this policy as you would to a customer calling..."
                value={content}
                onChange={(e) => setContent(e.target.value)}
                rows={4}
              />
              <p className="text-xs text-muted-foreground">
                Write naturally — your AI will paraphrase this when explaining to callers.
              </p>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={resetForm} disabled={isSaving}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={isSaving || !title.trim() || !content.trim()}>
              {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingPolicy ? "Save Changes" : "Add Policy"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Slider } from "@/components/ui/slider";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Loader2,
  Clock,
  MapPin,
  Truck,
  ChevronDown,
  Navigation,
  Sparkles,
  AlertCircle,
  Check,
} from "lucide-react";
import { useTenantDistanceSettings } from "@/hooks/useTenantDistanceSettings";

const ROUNDING_OPTIONS = [
  { value: 5, label: "5 minutes" },
  { value: 10, label: "10 minutes" },
  { value: 15, label: "15 minutes" },
];

// Example scenarios for preview
const EXAMPLE_SCENARIOS = [
  { distance: 5, travelTime: 8, location: "Downtown (5 miles)" },
  { distance: 12, travelTime: 18, location: "Suburbs (12 miles)" },
  { distance: 25, travelTime: 35, location: "Edge of service area (25 miles)" },
];

export function DispatchEtaSection() {
  const {
    settings,
    isLoading,
    isSaving,
    isGeocoding,
    toggleEnabled,
    setBaseLocationFromAddress,
    setEtaParams,
  } = useTenantDistanceSettings();

  const [addressInput, setAddressInput] = useState("");
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const [selectedScenario, setSelectedScenario] = useState(0);

  // Response time in minutes (default 30)
  const responseTime = settings?.eta_base_minutes ?? 30;

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Truck className="h-5 w-5" />
            Response Time & ETA
          </CardTitle>
        </CardHeader>
        <CardContent className="flex items-center justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  if (!settings) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Truck className="h-5 w-5" />
            Response Time & ETA
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-muted-foreground">Unable to load ETA settings.</p>
        </CardContent>
      </Card>
    );
  }

  const hasBaseLocation = settings.base_lat !== null && settings.base_lng !== null;
  const isEnabled = settings.distance_provider_enabled;

  const handleSetLocation = async () => {
    if (!addressInput.trim()) return;
    const success = await setBaseLocationFromAddress(addressInput);
    if (success) {
      setAddressInput("");
    }
  };

  // Calculate example ETAs
  const scenario = EXAMPLE_SCENARIOS[selectedScenario];
  const rawEta = responseTime + scenario.travelTime;
  const roundTo = settings.eta_rounding_minutes || 5;
  const roundedEta = Math.ceil(rawEta / roundTo) * roundTo;
  const displayEta = settings.eta_max_minutes && roundedEta > settings.eta_max_minutes
    ? settings.eta_max_minutes
    : Math.max(roundedEta, settings.eta_min_minutes || 0);

  // Generate spoken ETA
  const spokenEta = displayEta >= 60
    ? `about ${Math.floor(displayEta / 60)} hour${Math.floor(displayEta / 60) > 1 ? "s" : ""}${displayEta % 60 > 0 ? ` and ${displayEta % 60} minutes` : ""}`
    : `approximately ${displayEta} to ${displayEta + 5} minutes`;

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <Truck className="h-5 w-5" />
              Response Time & ETA
              {isEnabled && hasBaseLocation && (
                <Badge variant="secondary" className="ml-2">Active</Badge>
              )}
            </CardTitle>
            <CardDescription className="mt-1">
              Configure how the AI calculates and communicates arrival times.
              <span className="block text-xs mt-1 text-muted-foreground/70 italic">
                ETAs are always spoken as ranges—never exact guarantees.
              </span>
            </CardDescription>
          </div>
          <div className="flex items-center gap-2">
            <Label htmlFor="eta-enabled" className="text-sm text-muted-foreground">
              {isEnabled ? "Enabled" : "Disabled"}
            </Label>
            <Switch
              id="eta-enabled"
              checked={isEnabled}
              onCheckedChange={toggleEnabled}
              disabled={isSaving}
            />
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-6">
        {/* Response Time Slider - Main Control */}
        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <Clock className="h-4 w-4 text-primary" />
            <h4 className="font-medium">Average Response Time</h4>
          </div>
          
          <div className="space-y-4">
            <p className="text-sm text-muted-foreground">
              How long does it typically take to dispatch a driver after receiving a call?
            </p>
            
            <div className="space-y-3">
              <div className="flex items-center justify-between">
                <span className="text-sm text-muted-foreground">5 min</span>
                <span className="text-2xl font-bold text-primary">{responseTime} min</span>
                <span className="text-sm text-muted-foreground">120 min</span>
              </div>
              <Slider
                value={[responseTime]}
                onValueChange={([value]) => setEtaParams({ eta_base_minutes: value })}
                min={5}
                max={120}
                step={5}
                disabled={!isEnabled || isSaving}
                className="py-2"
              />
            </div>

            <p className="text-sm text-muted-foreground">
              The AI will add travel time to this number when giving customers an ETA.
            </p>
          </div>
        </div>

        <Separator />

        {/* Base Location */}
        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <MapPin className="h-4 w-4 text-primary" />
            <h4 className="font-medium">Your Business Location</h4>
          </div>

          {hasBaseLocation ? (
            <div className="flex items-center gap-3 p-3 rounded-lg bg-muted/50 border">
              <Check className="h-4 w-4 text-primary" />
              <div className="flex-1">
                <p className="text-sm font-medium">{settings.base_place_name || "Location set"}</p>
                <p className="text-xs text-muted-foreground">
                  Used to calculate travel time to customers
                </p>
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={() => setAddressInput(settings.base_place_name || "")}
              >
                Change
              </Button>
            </div>
          ) : (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-destructive/10 border border-destructive/20">
              <AlertCircle className="h-4 w-4 text-destructive" />
              <p className="text-sm text-muted-foreground">
                Set your business address to enable distance-based ETA calculations.
              </p>
            </div>
          )}

          <div className="flex gap-2">
            <Input
              placeholder="Enter your business address..."
              value={addressInput}
              onChange={(e) => setAddressInput(e.target.value)}
              disabled={isSaving || isGeocoding}
              onKeyDown={(e) => e.key === "Enter" && handleSetLocation()}
            />
            <Button
              onClick={handleSetLocation}
              disabled={!addressInput.trim() || isSaving || isGeocoding}
            >
              {isGeocoding ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Setting...
                </>
              ) : (
                "Set"
              )}
            </Button>
          </div>
        </div>

        <Separator />

        {/* Live ETA Preview */}
        <div className="space-y-4">
          <div className="flex items-center gap-2">
            <Sparkles className="h-4 w-4 text-primary" />
            <h4 className="font-medium">ETA Example</h4>
          </div>

          <div className="grid grid-cols-3 gap-2">
            {EXAMPLE_SCENARIOS.map((s, i) => (
              <Button
                key={i}
                variant={selectedScenario === i ? "default" : "outline"}
                size="sm"
                onClick={() => setSelectedScenario(i)}
                className="text-xs"
              >
                {s.distance} mi
              </Button>
            ))}
          </div>

          <div className="rounded-lg border bg-primary/5 border-primary/20 p-4 space-y-3">
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">Customer location:</span>
              <span className="font-medium">{scenario.location}</span>
            </div>
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">Your response time:</span>
              <span>{responseTime} min</span>
            </div>
            <div className="flex items-center justify-between text-sm">
              <span className="text-muted-foreground">Travel time:</span>
              <span>{scenario.travelTime} min</span>
            </div>
            <Separator />
            <div className="flex items-center justify-between">
              <span className="text-sm font-medium">Quoted ETA:</span>
              <Badge variant="secondary" className="text-base px-3 py-1">
                ~{displayEta} min
              </Badge>
            </div>
            
            <div className="pt-2 border-t">
              <p className="text-sm italic text-muted-foreground">
                "{`We can have a driver to you in ${spokenEta}.`}"
              </p>
            </div>
          </div>
        </div>

        {/* Advanced Options */}
        <Collapsible open={advancedOpen} onOpenChange={setAdvancedOpen}>
          <CollapsibleTrigger asChild>
            <Button variant="ghost" className="w-full justify-between">
              <span>Advanced Options</span>
              <ChevronDown className={`h-4 w-4 transition-transform ${advancedOpen ? "rotate-180" : ""}`} />
            </Button>
          </CollapsibleTrigger>
          <CollapsibleContent className="pt-4 space-y-4">
            <div className="grid gap-4 sm:grid-cols-3">
              <div className="space-y-2">
                <Label>Round to nearest</Label>
                <Select
                  value={String(settings.eta_rounding_minutes || 5)}
                  onValueChange={(v) => setEtaParams({ eta_rounding_minutes: parseInt(v) })}
                  disabled={!isEnabled || isSaving}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {ROUNDING_OPTIONS.map((opt) => (
                      <SelectItem key={opt.value} value={String(opt.value)}>
                        {opt.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Minimum ETA (min)</Label>
                <Input
                  type="number"
                  min={0}
                  max={120}
                  value={settings.eta_min_minutes ?? ""}
                  onChange={(e) => setEtaParams({
                    eta_min_minutes: e.target.value ? parseInt(e.target.value) : null
                  })}
                  placeholder="No minimum"
                  disabled={!isEnabled || isSaving}
                />
              </div>

              <div className="space-y-2">
                <Label>Maximum ETA (min)</Label>
                <Input
                  type="number"
                  min={0}
                  max={480}
                  value={settings.eta_max_minutes ?? ""}
                  onChange={(e) => setEtaParams({
                    eta_max_minutes: e.target.value ? parseInt(e.target.value) : null
                  })}
                  placeholder="No maximum"
                  disabled={!isEnabled || isSaving}
                />
                <p className="text-xs text-muted-foreground">
                  Say "over an hour" above this
                </p>
              </div>
            </div>
          </CollapsibleContent>
        </Collapsible>
      </CardContent>
    </Card>
  );
}

/**
 * GuidedSetupOverlay
 *
 * A modal overlay that appears on first visit to Business Brain (or via ?guided=true).
 * Shows the 3-4 most important setup sections for the user's business mode.
 */

import { useEffect, useState, useMemo } from "react";
import { useSearchParams } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Check, ChevronRight, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useAuth } from "@/contexts/AuthContext";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { useBusinessAwareness } from "@/hooks/useBusinessAwareness";
import { getIndustryOnboardingConfig } from "@/config/industryOnboardingConfig";
import { getOrderedSteps, getStepTitle, type HubStep } from "../hub/hubStepsConfig";
import type { BusinessMode } from "@/hooks/useTenantConfig";

const STORAGE_KEY = "brain_guided_seen";
const SNOOZE_KEY = "brain_guided_snoozed_at";
const SNOOZE_DURATION_MS = 24 * 60 * 60 * 1000; // 24 hours

interface GuidedSetupOverlayProps {
  onNavigateToSection: (sectionId: string) => void;
  getStepCompletion: (stepId: string) => boolean;
}

/** Get priority steps for a mode — the 3-4 most important ones */
function getPrioritySteps(mode: BusinessMode, capabilities?: Record<string, boolean>): string[] {
  const isCallbackOnly = capabilities?.aiBooksDirect === false;

  // Common priorities
  const steps: string[] = ["identity"];

  switch (mode) {
    case "dispatch":
      steps.push("coverage", "ai-setup", "knowledge");
      break;
    case "food":
      steps.push("offerings", "ai-setup", "knowledge");
      break;
    case "medical":
      steps.push("calendar", "policies", "knowledge");
      break;
    case "service":
    case "general":
    default:
      if (isCallbackOnly) {
        steps.push("ai-setup", "knowledge", "hours");
      } else {
        steps.push("calendar", "offerings", "ai-setup");
      }
      break;
  }

  return steps;
}

export function GuidedSetupOverlay({
  onNavigateToSection,
  getStepCompletion,
}: GuidedSetupOverlayProps) {
  const [searchParams, setSearchParams] = useSearchParams();
  const { businessMode } = useTenantConfig();
  const { tenant } = useAuth();
  const { slug, category, mode } = useIndustryContext();
  const { complexityTier } = useBusinessAwareness();
  const [open, setOpen] = useState(false);

  // Read capabilities from tenant
  const capabilities = useMemo(() => {
    const raw = (tenant as any)?.capabilities_json;
    if (raw && typeof raw === "object") return raw as Record<string, boolean>;
    return {};
  }, [tenant]);

  useEffect(() => {
    const isGuided = searchParams.get("guided") === "true";
    const hasSeen = localStorage.getItem(STORAGE_KEY) === "true";
    const snoozedAt = localStorage.getItem(SNOOZE_KEY);
    const isSnoozed = snoozedAt && Date.now() - parseInt(snoozedAt, 10) < SNOOZE_DURATION_MS;

    if (isGuided || (!hasSeen && !isSnoozed)) {
      setOpen(true);
      // Clean up the query param
      if (isGuided) {
        const newParams = new URLSearchParams(searchParams);
        newParams.delete("guided");
        setSearchParams(newParams, { replace: true });
      }
    }
  }, [searchParams, setSearchParams]);

  const onboardingConfig = useMemo(
    () => getIndustryOnboardingConfig(mode, category ?? undefined, slug ?? undefined),
    [mode, category, slug]
  );

  const allSteps = getOrderedSteps(businessMode);
  const priorityIds = getPrioritySteps(businessMode, capabilities);
  // Simple businesses: show fewer priority steps to avoid overwhelming
  const maxSteps = complexityTier === "simple" ? 3 : priorityIds.length;
  const prioritySteps = priorityIds
    .slice(0, maxSteps)
    .map((id) => allSteps.find((s) => s.id === id))
    .filter(Boolean) as HubStep[];

  const handleDismiss = () => {
    localStorage.setItem(STORAGE_KEY, "true");
    setOpen(false);
  };

  const handleSnooze = () => {
    localStorage.setItem(SNOOZE_KEY, Date.now().toString());
    setOpen(false);
  };

  const handleNavigate = (step: HubStep) => {
    handleDismiss();
    onNavigateToSection(step.sectionId);
  };

  const completedCount = prioritySteps.filter((s) => getStepCompletion(s.id)).length;

  return (
    <AnimatePresence>
      {open && (
        <Dialog open={open} onOpenChange={(v) => !v && handleDismiss()}>
          <DialogContent className="sm:max-w-md">
            <DialogHeader>
              <div className="flex items-center gap-2 mb-1">
                <Sparkles className="h-5 w-5 text-primary" />
                <DialogTitle>Let's finish setting up {onboardingConfig.setupTitle}</DialogTitle>
              </div>
              <DialogDescription>
                Here are the most important things to configure for your business.
                {completedCount > 0 && ` ${completedCount} of ${prioritySteps.length} done!`}
              </DialogDescription>
            </DialogHeader>

            <div className="space-y-2 py-2">
              {prioritySteps.map((step, i) => {
                const isComplete = getStepCompletion(step.id);
                const title = getStepTitle(step.id, businessMode);
                const Icon = step.icon;

                return (
                  <motion.button
                    key={step.id}
                    initial={{ opacity: 0, x: -10 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: i * 0.05 }}
                    onClick={() => handleNavigate(step)}
                    className={cn(
                      "w-full flex items-center gap-3 p-3 rounded-lg border text-left transition-colors",
                      isComplete
                        ? "border-emerald-500/30 bg-emerald-500/5"
                        : "border-border hover:border-primary/50 hover:bg-primary/5"
                    )}
                  >
                    <div
                      className={cn(
                        "h-8 w-8 rounded-full flex items-center justify-center shrink-0",
                        isComplete ? "bg-emerald-500/20" : "bg-muted"
                      )}
                    >
                      {isComplete ? (
                        <Check className="h-4 w-4 text-emerald-600" />
                      ) : (
                        <Icon className="h-4 w-4 text-muted-foreground" />
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium">{title}</p>
                      <p className="text-xs text-muted-foreground truncate">
                        {step.purpose}
                      </p>
                    </div>
                    <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
                  </motion.button>
                );
              })}
            </div>

            <div className="flex gap-2 pt-2">
              <Button variant="outline" size="sm" className="flex-1" onClick={handleSnooze}>
                Show me later
              </Button>
              <Button size="sm" className="flex-1" onClick={handleDismiss}>
                I'll explore on my own
              </Button>
            </div>
          </DialogContent>
        </Dialog>
      )}
    </AnimatePresence>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { 
  Plus, 
  Pencil, 
  Trash2, 
