interface MenuItemFormData {
  name: string;
  description: string;
  category: string;
  price_cents: number;
  prep_time_minutes: number;
  is_available: boolean;
  dietary_tags: string[];
}

const defaultFormData: MenuItemFormData = {
  name: "",
  description: "",
  category: "",
  price_cents: 0,
  prep_time_minutes: 15,
  is_available: true,
  dietary_tags: [],
};

/**
 * MenuCatalogEditor - Inline menu management for food mode
 * 
 * Features:
 * - Collapsible category sections for large menus
 * - Inline upload button to quickly import menus
 * - Clear explanations of what each section does
 */
export function MenuCatalogEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<any | null>(null);
  const [deletingItem, setDeletingItem] = useState<any | null>(null);
  const [formData, setFormData] = useState<MenuItemFormData>(defaultFormData);
  const [expandedCategories, setExpandedCategories] = useState<Set<string>>(new Set());

  // Fetch menu items
  const { data: menuItems, isLoading } = useQuery({
    queryKey: ["menu-items", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("menu_items")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("category", { ascending: true })
        .order("name", { ascending: true });

      if (error) throw error;
      return data || [];
    },
    enabled: !!tenant?.id,
  });

  // Create mutation
  const createMutation = useMutation({
    mutationFn: async (item: MenuItemFormData) => {
      const { error } = await supabase
        .from("menu_items")
        .insert({
          tenant_id: tenant?.id,
          ...item,
        });
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["menu-items"] });
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      toast.success("Menu item added");
      setDialogOpen(false);
      setFormData(defaultFormData);
    },
    onError: (error: Error) => {
      toast.error(error.message || "Failed to add menu item");
    },
  });

  // Update mutation
  const updateMutation = useMutation({
    mutationFn: async ({ id, updates }: { id: string; updates: Partial<MenuItemFormData> }) => {
      const { error } = await supabase
        .from("menu_items")
        .update(updates)
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["menu-items"] });
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      toast.success("Menu item updated");
      setDialogOpen(false);
      setEditingItem(null);
      setFormData(defaultFormData);
    },
    onError: (error: Error) => {
      toast.error(error.message || "Failed to update menu item");
    },
  });

  // Delete mutation
  const deleteMutation = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase
        .from("menu_items")
        .delete()
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["menu-items"] });
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      toast.success("Menu item deleted");
      setDeleteDialogOpen(false);
      setDeletingItem(null);
    },
    onError: (error: Error) => {
      toast.error(error.message || "Failed to delete menu item");
    },
  });

  const openCreateDialog = () => {
    setEditingItem(null);
    setFormData(defaultFormData);
    setDialogOpen(true);
  };

  const openEditDialog = (item: any) => {
    setEditingItem(item);
    setFormData({
      name: item.name,
      description: item.description || "",
      category: item.category || "",
      price_cents: item.price_cents || 0,
      prep_time_minutes: item.prep_time_minutes || 15,
      is_available: item.is_available ?? true,
      dietary_tags: item.dietary_tags || [],
    });
    setDialogOpen(true);
  };

  const handleSave = () => {
    if (!tenant?.id || !formData.name.trim()) return;

    if (editingItem) {
      updateMutation.mutate({ id: editingItem.id, updates: formData });
    } else {
      createMutation.mutate(formData);
    }
  };

  const handleToggleAvailable = (item: any) => {
    updateMutation.mutate({
      id: item.id,
      updates: { is_available: !item.is_available },
    });
  };

  const toggleCategory = (category: string) => {
    setExpandedCategories(prev => {
      const next = new Set(prev);
      if (next.has(category)) {
        next.delete(category);
      } else {
        next.add(category);
      }
      return next;
    });
  };

  const expandAllCategories = () => {
    setExpandedCategories(new Set(categories));
  };

  const collapseAllCategories = () => {
    setExpandedCategories(new Set());
  };

  const isSaving = createMutation.isPending || updateMutation.isPending;

  // Group items by category
  const categories = [...new Set(menuItems?.map(item => item.category || "Uncategorized") || [])];
  const itemsByCategory = categories.reduce((acc, category) => {
    acc[category] = menuItems?.filter(item => (item.category || "Uncategorized") === category) || [];
    return acc;
  }, {} as Record<string, any[]>);

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="ml-3 text-sm text-muted-foreground">Loading menu...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  // AI preview for first item
  const firstItem = menuItems?.[0];
  const aiPreview = firstItem
    ? `Our ${firstItem.name} is $${((firstItem.price_cents || 0) / 100).toFixed(2)}${firstItem.prep_time_minutes ? ` and takes about ${firstItem.prep_time_minutes} minutes to prepare` : ""}.`
    : "I can tell you about our menu items and pricing.";

  const totalItems = menuItems?.length || 0;
  const availableItems = menuItems?.filter(i => i.is_available).length || 0;

  return (
    <div className="space-y-6">
      {/* Upload action */}
      <InlineUploadButton 
        contentType="menu" 
        variant="prominent"
        onUploadComplete={() => queryClient.invalidateQueries({ queryKey: ["menu-items"] })}
      />

      {/* Header with stats and actions */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h3 className="text-lg font-semibold">Menu Items</h3>
          <p className="text-sm text-muted-foreground">
            {totalItems === 0 
              ? "Add your menu items so the AI can answer questions and take orders"
              : `${totalItems} items across ${categories.length} ${categories.length === 1 ? 'category' : 'categories'} • ${availableItems} available`
            }
          </p>
        </div>
        <Button onClick={openCreateDialog}>
          <Plus className="h-4 w-4 mr-2" />
          Add Item
        </Button>
      </div>

      {/* Menu Items by Category */}
      {menuItems && menuItems.length > 0 ? (
        <div className="space-y-2">
          {/* Expand/Collapse All */}
          {categories.length > 1 && (
            <div className="flex items-center justify-end gap-2 mb-2">
              <Button variant="ghost" size="sm" onClick={expandAllCategories}>
                Expand All
              </Button>
              <Button variant="ghost" size="sm" onClick={collapseAllCategories}>
                Collapse All
              </Button>
            </div>
          )}

          {categories.map((category) => {
            const items = itemsByCategory[category];
            const isExpanded = expandedCategories.has(category);
            const categoryAvailable = items.filter(i => i.is_available).length;

            return (
              <Collapsible 
                key={category} 
                open={isExpanded}
                onOpenChange={() => toggleCategory(category)}
              >
                <Card>
                  <CollapsibleTrigger asChild>
                    <button className="w-full px-4 py-3 flex items-center justify-between hover:bg-muted/50 transition-colors rounded-t-lg">
                      <div className="flex items-center gap-3">
                        {isExpanded ? (
                          <ChevronDown className="h-4 w-4 text-muted-foreground" />
                        ) : (
                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
                        )}
                        <h4 className="font-medium">{category}</h4>
                        <Badge variant="secondary" className="text-xs">
                          {items.length} {items.length === 1 ? 'item' : 'items'}
                        </Badge>
                        {categoryAvailable < items.length && (
                          <Badge variant="outline" className="text-xs text-muted-foreground">
                            {items.length - categoryAvailable} unavailable
                          </Badge>
                        )}
                      </div>
                      <div className="text-sm text-muted-foreground">
                        ${((items.reduce((sum, i) => sum + (i.price_cents || 0), 0) / items.length / 100) || 0).toFixed(2)} avg
                      </div>
                    </button>
                  </CollapsibleTrigger>
                  <CollapsibleContent>
                    <div className="border-t">
                      <div className="divide-y">
                        {items.map((item) => (
                          <div 
                            key={item.id} 
                            className="px-4 py-3 flex items-center justify-between gap-4 hover:bg-muted/30"
                          >
                            <div className="flex-1 min-w-0">
                              <div className="flex items-center gap-2">
                                <span className="font-medium text-sm truncate">{item.name}</span>
                                {!item.is_available && (
                                  <Badge variant="outline" className="text-xs shrink-0">Unavailable</Badge>
                                )}
                              </div>
                              {item.description && (
                                <p className="text-xs text-muted-foreground truncate mt-0.5">
                                  {item.description}
                                </p>
                              )}
                            </div>
                            <div className="flex items-center gap-4 shrink-0">
                              <div className="flex items-center gap-3 text-sm">
                                <span className="font-medium">
                                  ${((item.price_cents || 0) / 100).toFixed(2)}
                                </span>
                                {item.prep_time_minutes && (
                                  <span className="flex items-center gap-1 text-muted-foreground text-xs">
                                    <Clock className="h-3 w-3" />
                                    {item.prep_time_minutes}m
                                  </span>
                                )}
                              </div>
                              <div className="flex items-center gap-1">
                                <Button
                                  size="icon"
                                  variant="ghost"
                                  className="h-7 w-7"
                                  onClick={() => openEditDialog(item)}
                                >
                                  <Pencil className="h-3.5 w-3.5" />
                                </Button>
                                <Button
                                  size="icon"
                                  variant="ghost"
                                  className="h-7 w-7 text-destructive hover:text-destructive"
                                  onClick={() => {
                                    setDeletingItem(item);
                                    setDeleteDialogOpen(true);
                                  }}
                                >
                                  <Trash2 className="h-3.5 w-3.5" />
                                </Button>
                              </div>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  </CollapsibleContent>
                </Card>
              </Collapsible>
            );
          })}
        </div>
      ) : (
        <Card>
          <CardContent className="p-8 text-center">
            <div className="flex flex-col items-center gap-4 max-w-md mx-auto">
              <div className="h-16 w-16 rounded-full bg-muted flex items-center justify-center">
                <Utensils className="h-8 w-8 text-muted-foreground" />
              </div>
              <div>
                <h3 className="font-semibold text-lg mb-1">No menu items yet</h3>
                <p className="text-sm text-muted-foreground">
                  Use the upload button above to import your menu, or add items manually.
                </p>
              </div>
              <Button onClick={openCreateDialog}>
                <Plus className="h-4 w-4 mr-2" />
                Add Item Manually
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Create/Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{editingItem ? "Edit Menu Item" : "Add Menu Item"}</DialogTitle>
            <DialogDescription>Configure your menu item details and pricing</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Item Name *</Label>
              <Input
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="Classic Cheeseburger"
              />
            </div>
            <div className="space-y-2">
              <Label>Category</Label>
              <Input
                value={formData.category}
                onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                placeholder="Burgers, Appetizers, Drinks..."
              />
              <p className="text-xs text-muted-foreground">
                Group similar items together (e.g., "Burgers", "Sides", "Drinks")
              </p>
            </div>
            <div className="space-y-2">
              <Label>Description</Label>
              <Textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="Brief description for customers"
                rows={2}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Price ($)</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={(formData.price_cents / 100).toFixed(2)}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      price_cents: Math.round(parseFloat(e.target.value) * 100) || 0,
                    })
                  }
                />
              </div>
              <div className="space-y-2">
                <Label>Prep Time (min)</Label>
                <Input
                  type="number"
                  value={formData.prep_time_minutes}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      prep_time_minutes: parseInt(e.target.value) || 15,
                    })
                  }
                />
              </div>
            </div>
            <div className="flex items-center justify-between">
              <div>
                <Label>Available</Label>
                <p className="text-xs text-muted-foreground">Turn off to hide from AI</p>
              </div>
              <Switch
                checked={formData.is_available}
                onCheckedChange={(checked) =>
                  setFormData({ ...formData, is_available: checked })
                }
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={isSaving || !formData.name.trim()}>
              {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingItem ? "Update" : "Add Item"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Menu Item</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete "{deletingItem?.name}"? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => deletingItem && deleteMutation.mutate(deletingItem.id)}
              className="bg-destructive text-destructive-foreground"
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

/**
 * Price Modifiers Editor
 * 
 * Allows businesses to define price adjustments based on:
 * - Vehicle/property size (detailing, cleaning, HVAC)
 * - Urgency (same-day, emergency)
 * - Time of day (after-hours, weekends)
 * - Custom factors
 * 
 * Industry-aware: Shows relevant modifier types based on business mode
 */

import { useState, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Plus,
  Trash2,
  Loader2,
  Info,
  Lightbulb,
  ChevronDown,
  ChevronRight,
  Check,
  X,
  Car,
  Clock,
  Zap,
  Settings2,
  DollarSign,
  Percent,
} from "lucide-react";
import { toast } from "sonner";

// Modifier type configuration
const MODIFIER_TYPES = {
  vehicle_size: {
    label: "Vehicle Size",
    icon: Car,
    description: "Price adjustments based on vehicle type (sedan, SUV, truck, etc.)",
    modes: ["service", "dispatch"],
    industries: ["detailing", "auto", "towing", "car_wash"],
    suggestions: [
      { name: "Sedan", adjustment: 0 },
      { name: "SUV/Crossover", adjustment: 25 },
      { name: "Truck", adjustment: 35 },
      { name: "Van/Minivan", adjustment: 30 },
      { name: "Large Truck/RV", adjustment: 75 },
    ],
  },
  property_size: {
    label: "Property Size",
    icon: Settings2,
    description: "Price adjustments based on property size or rooms",
    modes: ["service"],
    industries: ["cleaning", "hvac", "plumbing", "electrical", "landscaping"],
    suggestions: [
      { name: "Small (under 1,500 sqft)", adjustment: 0 },
      { name: "Medium (1,500-2,500 sqft)", adjustment: 50 },
      { name: "Large (2,500-4,000 sqft)", adjustment: 100 },
      { name: "Extra Large (4,000+ sqft)", adjustment: 175 },
    ],
  },
  urgency: {
    label: "Urgency",
    icon: Zap,
    description: "Surcharges for same-day or emergency service",
    modes: ["service", "dispatch", "medical", "sales"],
    industries: [],
    suggestions: [
      { name: "Same Day Service", adjustment: 50 },
      { name: "Emergency (2-4 hours)", adjustment: 100 },
      { name: "After Hours Emergency", adjustment: 150 },
    ],
  },
  time_of_day: {
    label: "Time of Day",
    icon: Clock,
    description: "Rate adjustments for after-hours or weekend work",
    modes: ["service", "dispatch", "sales"],
    industries: [],
    suggestions: [
      { name: "After Hours (6pm-8am)", adjustment: 50 },
      { name: "Weekend", adjustment: 35 },
      { name: "Holiday", adjustment: 75 },
    ],
  },
  equipment: {
    label: "Special Equipment",
    icon: Settings2,
    description: "Fees for specialized equipment or tools",
    modes: ["dispatch", "service"],
    industries: ["towing", "hvac", "plumbing", "electrical"],
    suggestions: [
      { name: "Flatbed Required", adjustment: 50 },
      { name: "Specialty Tools", adjustment: 25 },
      { name: "Heavy Equipment", adjustment: 100 },
    ],
  },
  complexity: {
    label: "Complexity",
    icon: Settings2,
    description: "Price adjustments for job difficulty",
    modes: ["service"],
    industries: [],
    suggestions: [
      { name: "Standard", adjustment: 0 },
      { name: "Complex", adjustment: 50 },
      { name: "Very Complex", adjustment: 100 },
    ],
  },
  custom: {
    label: "Custom Modifier",
    icon: Settings2,
    description: "Define your own price adjustment",
    modes: ["service", "dispatch", "food", "medical", "general", "sales"],
    industries: [],
    suggestions: [],
  },
};

type ModifierType = keyof typeof MODIFIER_TYPES;
type AdjustmentType = "fixed" | "percentage" | "multiplier";

interface PriceModifier {
  id: string;
  name: string;
  description: string | null;
  modifier_type: ModifierType;
  adjustment_type: AdjustmentType;
  adjustment_value: number;
  is_active: boolean;
  show_to_customer: boolean;
}

interface ModifierFormData {
  name: string;
  description: string;
  modifier_type: ModifierType;
  adjustment_type: AdjustmentType;
  adjustment_value: number;
  show_to_customer: boolean;
}

const defaultFormData: ModifierFormData = {
  name: "",
  description: "",
  modifier_type: "custom",
  adjustment_type: "fixed",
  adjustment_value: 0,
  show_to_customer: true,
};

export function PriceModifiersEditor() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const { config: industryConfig } = useIndustryContext();
  const queryClient = useQueryClient();

  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [isCreatingNew, setIsCreatingNew] = useState(false);
  const [newFormData, setNewFormData] = useState<ModifierFormData>(defaultFormData);
  const [editingFormData, setEditingFormData] = useState<Record<string, ModifierFormData>>({});
  const [savingId, setSavingId] = useState<string | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingModifier, setDeletingModifier] = useState<PriceModifier | null>(null);
  const [selectedType, setSelectedType] = useState<ModifierType | null>(null);

  // Fetch modifiers
  const { data: modifiers, isLoading } = useQuery({
    queryKey: ["price-modifiers", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("price_modifiers")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("modifier_type")
        .order("display_order");
      if (error) throw error;
      return data as PriceModifier[];
    },
    enabled: !!tenant?.id,
  });

  // Get industry from tenant
  const tenantIndustry = tenant?.industry?.toLowerCase() || "";

  // Filter modifier types relevant to this business
  const relevantTypes = useMemo(() => {
    return Object.entries(MODIFIER_TYPES)
      .filter(([_, config]) => {
        // Check if mode matches
        if (!config.modes.includes(businessMode)) return false;
        // If no industry restrictions, show it
        if (config.industries.length === 0) return true;
        // Check if industry matches
        return config.industries.some(ind => 
          tenantIndustry.includes(ind) || ind.includes(tenantIndustry)
        );
      })
      .map(([key, config]) => ({ key: key as ModifierType, ...config }));
  }, [businessMode, tenantIndustry]);

  // Group modifiers by type
  const modifiersByType = useMemo(() => {
    const groups: Record<string, PriceModifier[]> = {};
    modifiers?.forEach(mod => {
      if (!groups[mod.modifier_type]) {
        groups[mod.modifier_type] = [];
      }
      groups[mod.modifier_type].push(mod);
    });
    return groups;
  }, [modifiers]);

  const formatAdjustment = (mod: PriceModifier | ModifierFormData) => {
    const value = mod.adjustment_value;
    switch (mod.adjustment_type) {
      case "fixed":
        return value >= 0 ? `+$${value}` : `-$${Math.abs(value)}`;
      case "percentage":
        return value >= 0 ? `+${value}%` : `${value}%`;
      case "multiplier":
        return `${value}x`;
    }
  };

  const handleSave = async (modifierId: string) => {
    if (!tenant?.id) return;
    const formData = editingFormData[modifierId];
    if (!formData?.name.trim()) return;

    setSavingId(modifierId);
    try {
      const { error } = await supabase
        .from("price_modifiers")
        .update({
          name: formData.name.trim(),
          description: formData.description.trim() || null,
          modifier_type: formData.modifier_type,
          adjustment_type: formData.adjustment_type,
          adjustment_value: formData.adjustment_value,
          show_to_customer: formData.show_to_customer,
        })
        .eq("id", modifierId)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      toast.success("Modifier updated");
      queryClient.invalidateQueries({ queryKey: ["price-modifiers"] });
      setExpandedId(null);
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setSavingId(null);
    }
  };

  const handleCreate = async () => {
    if (!tenant?.id || !newFormData.name.trim()) return;

    setSavingId("new");
    try {
      const { error } = await supabase
        .from("price_modifiers")
        .insert({
          tenant_id: tenant.id,
          name: newFormData.name.trim(),
          description: newFormData.description.trim() || null,
          modifier_type: newFormData.modifier_type,
          adjustment_type: newFormData.adjustment_type,
          adjustment_value: newFormData.adjustment_value,
          show_to_customer: newFormData.show_to_customer,
        });

      if (error) throw error;
      toast.success("Modifier added");
      queryClient.invalidateQueries({ queryKey: ["price-modifiers"] });
      setIsCreatingNew(false);
      setSelectedType(null);
      setNewFormData(defaultFormData);
    } catch (error: any) {
      toast.error(error.message || "Failed to create");
    } finally {
      setSavingId(null);
    }
  };

  const handleDelete = async () => {
    if (!tenant?.id || !deletingModifier) return;

    try {
      const { error } = await supabase
        .from("price_modifiers")
        .delete()
        .eq("id", deletingModifier.id)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      toast.success("Modifier removed");
      queryClient.invalidateQueries({ queryKey: ["price-modifiers"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    } finally {
      setDeleteDialogOpen(false);
      setDeletingModifier(null);
    }
  };

  const handleToggleActive = async (mod: PriceModifier) => {
    if (!tenant?.id) return;

    try {
      const { error } = await supabase
        .from("price_modifiers")
        .update({ is_active: !mod.is_active })
        .eq("id", mod.id)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      toast.success(mod.is_active ? "Modifier disabled" : "Modifier enabled");
      queryClient.invalidateQueries({ queryKey: ["price-modifiers"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to update");
    }
  };

  const handleQuickAdd = (type: ModifierType, suggestion: { name: string; adjustment: number }) => {
    setNewFormData({
      name: suggestion.name,
      description: "",
      modifier_type: type,
      adjustment_type: "fixed",
      adjustment_value: suggestion.adjustment,
      show_to_customer: true,
    });
    setSelectedType(type);
    setIsCreatingNew(true);
  };

  const toggleExpanded = (id: string, mod: PriceModifier) => {
    if (expandedId === id) {
      setExpandedId(null);
    } else {
      setExpandedId(id);
      if (!editingFormData[id]) {
        setEditingFormData(prev => ({
          ...prev,
          [id]: {
            name: mod.name,
            description: mod.description || "",
            modifier_type: mod.modifier_type,
            adjustment_type: mod.adjustment_type,
            adjustment_value: mod.adjustment_value,
            show_to_customer: mod.show_to_customer,
          },
        }));
      }
    }
    setIsCreatingNew(false);
  };

  // Build AI preview
  const aiPreview = useMemo(() => {
    const activeModifiers = modifiers?.filter(m => m.is_active && m.show_to_customer) || [];
    if (activeModifiers.length === 0) return null;

    const vehicleSize = activeModifiers.find(m => m.modifier_type === "vehicle_size");
    const urgency = activeModifiers.find(m => m.modifier_type === "urgency");

    if (vehicleSize && urgency) {
      return `For an SUV with same-day service, that would be ${formatAdjustment(vehicleSize)} for the vehicle size and ${formatAdjustment(urgency)} for same-day.`;
    } else if (vehicleSize) {
      return `For an SUV, that would be ${formatAdjustment(vehicleSize)} extra.`;
    } else if (urgency) {
      return `For same-day service, there's a ${formatAdjustment(urgency)} surcharge.`;
    }
    return null;
  }, [modifiers]);

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="ml-3 text-sm text-muted-foreground">Loading modifiers...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Form component for creating/editing
  const ModifierForm = ({
    formData,
    onChange,
    onSave,
    onCancel,
    isSaving,
    isNew = false,
  }: {
    formData: ModifierFormData;
    onChange: (field: keyof ModifierFormData, value: any) => void;
    onSave: () => void;
    onCancel: () => void;
    isSaving: boolean;
    isNew?: boolean;
  }) => (
    <div className="p-4 space-y-4 border-t bg-muted/20">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label className="text-xs">Name *</Label>
          <Input
            value={formData.name}
            onChange={(e) => onChange("name", e.target.value)}
            placeholder="e.g., SUV, Same Day, After Hours"
          />
        </div>
        <div className="space-y-2">
          <Label className="text-xs">Modifier Type</Label>
          <Select
            value={formData.modifier_type}
            onValueChange={(v) => onChange("modifier_type", v)}
            disabled={!isNew}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {relevantTypes.map(type => (
                <SelectItem key={type.key} value={type.key}>{type.label}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="space-y-2">
          <Label className="text-xs">Adjustment Type</Label>
          <Select
            value={formData.adjustment_type}
            onValueChange={(v) => onChange("adjustment_type", v)}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="fixed">Fixed Amount ($)</SelectItem>
              <SelectItem value="percentage">Percentage (%)</SelectItem>
              <SelectItem value="multiplier">Multiplier (x)</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div className="space-y-2">
          <Label className="text-xs">
            {formData.adjustment_type === "fixed" && "Amount ($)"}
            {formData.adjustment_type === "percentage" && "Percentage (%)"}
            {formData.adjustment_type === "multiplier" && "Multiplier"}
          </Label>
          <div className="relative">
            {formData.adjustment_type === "fixed" && (
              <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            )}
            {formData.adjustment_type === "percentage" && (
              <Percent className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            )}
            <Input
              type="number"
              step={formData.adjustment_type === "multiplier" ? "0.1" : "1"}
              value={formData.adjustment_value}
              onChange={(e) => onChange("adjustment_value", parseFloat(e.target.value) || 0)}
              className={formData.adjustment_type === "fixed" ? "pl-8" : ""}
              placeholder={formData.adjustment_type === "multiplier" ? "1.5" : "50"}
            />
          </div>
        </div>
        <div className="space-y-2">
          <Label className="text-xs">Preview</Label>
          <div className="h-10 flex items-center px-3 rounded-md border bg-muted/50">
            <span className="text-sm font-medium">{formatAdjustment(formData)}</span>
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between pt-2">
        <div className="flex items-center gap-2">
          <Switch
            checked={formData.show_to_customer}
            onCheckedChange={(v) => onChange("show_to_customer", v)}
          />
          <Label className="text-xs text-muted-foreground">AI mentions this to customers</Label>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={onCancel} disabled={isSaving}>
            <X className="h-4 w-4 mr-1" />
            Cancel
          </Button>
          <Button size="sm" onClick={onSave} disabled={isSaving || !formData.name.trim()}>
            {isSaving ? (
              <Loader2 className="h-4 w-4 mr-1 animate-spin" />
            ) : (
              <Check className="h-4 w-4 mr-1" />
            )}
            {isNew ? "Add Modifier" : "Save"}
          </Button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">

      {/* Quick Add by Type */}
      {!isCreatingNew && relevantTypes.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-medium">Add Price Modifiers</h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
            {relevantTypes.map(type => {
              const existingCount = modifiersByType[type.key]?.length || 0;
              const Icon = type.icon;
              
              return (
                <Card key={type.key} className="overflow-hidden">
                  <div className="p-4">
                    <div className="flex items-start gap-3">
                      <div className="p-2 rounded-md bg-primary/10">
                        <Icon className="h-4 w-4 text-primary" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <h4 className="text-sm font-medium">{type.label}</h4>
                          {existingCount > 0 && (
                            <Badge variant="secondary" className="text-xs">
                              {existingCount} added
                            </Badge>
                          )}
                        </div>
                        <p className="text-xs text-muted-foreground mt-0.5">{type.description}</p>
                        
                        {type.suggestions.length > 0 && (
                          <div className="flex flex-wrap gap-1 mt-2">
                            {type.suggestions.slice(0, 3).map(suggestion => (
                              <Button
                                key={suggestion.name}
                                variant="outline"
                                size="sm"
                                className="h-7 text-xs"
                                onClick={() => handleQuickAdd(type.key, suggestion)}
                              >
                                <Plus className="h-3 w-3 mr-1" />
                                {suggestion.name}
                              </Button>
                            ))}
                          </div>
                        )}
                        
                        {type.key === "custom" && (
                          <Button
                            variant="outline"
                            size="sm"
                            className="mt-2 h-7 text-xs"
                            onClick={() => {
                              setNewFormData({ ...defaultFormData, modifier_type: "custom" });
                              setSelectedType("custom");
                              setIsCreatingNew(true);
                            }}
                          >
                            <Plus className="h-3 w-3 mr-1" />
                            Add Custom Modifier
                          </Button>
                        )}
                      </div>
                    </div>
                  </div>
                </Card>
              );
            })}
          </div>
        </div>
      )}

      {/* New Modifier Form */}
      {isCreatingNew && (
        <Card>
          <div className="px-4 py-3 flex items-center gap-3 bg-primary/5 border-b">
            <Plus className="h-4 w-4 text-primary" />
            <span className="font-medium text-sm">
              New {selectedType ? MODIFIER_TYPES[selectedType].label : "Modifier"}
            </span>
          </div>
          <ModifierForm
            formData={newFormData}
            onChange={(field, value) => setNewFormData(prev => ({ ...prev, [field]: value }))}
            onSave={handleCreate}
            onCancel={() => {
              setIsCreatingNew(false);
              setSelectedType(null);
              setNewFormData(defaultFormData);
            }}
            isSaving={savingId === "new"}
            isNew
          />
        </Card>
      )}

      {/* Existing Modifiers */}
      {modifiers && modifiers.length > 0 && (
        <div className="space-y-3">
          <h3 className="text-sm font-medium">Your Modifiers</h3>
          <div className="space-y-2">
            {modifiers.map(mod => {
              const typeConfig = MODIFIER_TYPES[mod.modifier_type] || MODIFIER_TYPES.custom;
              const Icon = typeConfig.icon;
              const isExpanded = expandedId === mod.id;

              return (
                <Collapsible
                  key={mod.id}
                  open={isExpanded}
                  onOpenChange={() => toggleExpanded(mod.id, mod)}
                >
                  <Card className="overflow-hidden">
                    <CollapsibleTrigger asChild>
                      <button className="w-full px-4 py-3 flex items-center justify-between hover:bg-muted/50 transition-colors text-left">
                        <div className="flex items-center gap-3 flex-1 min-w-0">
                          {isExpanded ? (
                            <ChevronDown className="h-4 w-4 text-muted-foreground shrink-0" />
                          ) : (
                            <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
                          )}
                          <Icon className="h-4 w-4 text-muted-foreground shrink-0" />
                          <div className="min-w-0">
                            <div className="flex items-center gap-2">
                              <span className="font-medium text-sm truncate">{mod.name}</span>
                              <Badge variant="secondary" className="text-xs shrink-0">
                                {typeConfig.label}
                              </Badge>
                              {!mod.is_active && (
                                <Badge variant="outline" className="text-xs shrink-0">Disabled</Badge>
                              )}
                            </div>
                          </div>
                        </div>
                        <div className="flex items-center gap-3 shrink-0">
                          <Badge
                            variant={mod.adjustment_value >= 0 ? "default" : "secondary"}
                            className="font-mono"
                          >
                            {formatAdjustment(mod)}
                          </Badge>
                          <Switch
                            checked={mod.is_active}
                            onCheckedChange={() => handleToggleActive(mod)}
                            onClick={(e) => e.stopPropagation()}
                          />
                        </div>
                      </button>
                    </CollapsibleTrigger>
                    <CollapsibleContent>
                      {editingFormData[mod.id] && (
                        <ModifierForm
                          formData={editingFormData[mod.id]}
                          onChange={(field, value) =>
                            setEditingFormData(prev => ({
                              ...prev,
                              [mod.id]: { ...prev[mod.id], [field]: value },
                            }))
                          }
                          onSave={() => handleSave(mod.id)}
                          onCancel={() => setExpandedId(null)}
                          isSaving={savingId === mod.id}
                        />
                      )}
                      <div className="px-4 pb-3 flex justify-end">
                        <Button
                          variant="ghost"
                          size="sm"
                          className="text-destructive hover:text-destructive"
                          onClick={() => {
                            setDeletingModifier(mod);
                            setDeleteDialogOpen(true);
                          }}
                        >
                          <Trash2 className="h-4 w-4 mr-1" />
                          Delete
                        </Button>
                      </div>
                    </CollapsibleContent>
                  </Card>
                </Collapsible>
              );
            })}
          </div>
        </div>
      )}

      {/* Empty State */}
      {(!modifiers || modifiers.length === 0) && !isCreatingNew && (
        <div className="text-center py-8 text-muted-foreground">
          <Settings2 className="h-12 w-12 mx-auto mb-3 opacity-50" />
          <p className="text-sm">No price modifiers configured yet</p>
          <p className="text-xs mt-1">Use the cards above to add modifiers for your business</p>
        </div>
      )}

      {/* Delete Confirmation */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Modifier?</AlertDialogTitle>
            <AlertDialogDescription>
              This will remove "{deletingModifier?.name}" from your pricing. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useServices } from "@/hooks/useServices";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Plus, Trash2, Clock, DollarSign, Loader2, Info, Lightbulb, ChevronDown, ChevronRight, Check, X, ClipboardPaste, FileSpreadsheet } from "lucide-react";
import { InlineUploadButton } from "../uploads/InlineUploadButton";
import { PasteFromPOSDialog } from "../templates/PasteFromPOSDialog";
import { ServiceCSVImportDialog } from "../templates/ServiceCSVImportDialog";
import { FlatbedPricingDialog } from "./FlatbedPricingDialog";
import { createService, updateService, deleteService } from "@/lib/brain/writeBrainFact";
import { invalidateBrainQueries } from "@/lib/brain/invalidateBrainQueries";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { getServiceExamples, getSlugServiceExamples, COMPLEXITY_HINTS, PRICE_FACTOR_HINTS } from "@/lib/industryExamples";
import { useIndustryContext } from "@/hooks/useIndustryContext";


type PriceType = "fixed" | "starting_at" | "quote_only";

type BookingType = "direct_book" | "estimate_first" | "consultation";

type PaymentTiming = "at_booking" | "at_service" | "deposit_then_balance" | "quote_first";

interface ServiceFormData {
  name: string;
  description: string;
  duration_minutes: number;
  price_type: PriceType;
  price_amount: number | null;
  deposit_amount: number | null;
  deposit_required: boolean;
  complexity: "simple" | "complex";
  price_factors: string;
  booking_type: BookingType;
  prerequisite_note: string;
  duration_min_minutes: number | null;
  duration_max_minutes: number | null;
  required_intake_fields: string[];
  payment_timing: PaymentTiming;
}

const COMMON_INTAKE_FIELDS = [
  "address",
  "property_type",
  "urgency",
  "budget_range",
  "scope_of_work",
  "access_instructions",
  "preferred_date",
  "vehicle_info",
  "photos",
  "warranty_status",
];

const defaultFormData: ServiceFormData = {
  name: "",
  description: "",
  duration_minutes: 60,
  price_type: "fixed",
  price_amount: null,
  deposit_amount: null,
  deposit_required: false,
  complexity: "simple",
  price_factors: "",
  booking_type: "direct_book",
  prerequisite_note: "",
  duration_min_minutes: null,
  duration_max_minutes: null,
  required_intake_fields: [],
  payment_timing: "at_service",
};

// Extracted outside ServiceCatalogEditor to prevent focus loss on re-render
function ServiceForm({ 
  formData, 
  onChange, 
  onSave, 
  onCancel, 
  isSaving,
  isNew = false,
  serviceExamples,
  businessMode,
}: { 
  formData: ServiceFormData;
  onChange: (field: keyof ServiceFormData, value: any) => void;
  onSave: () => void;
  onCancel: () => void;
  isSaving: boolean;
  isNew?: boolean;
  serviceExamples: ReturnType<typeof getServiceExamples>;
  businessMode: string;
}) {
  return (
    <div className="p-4 space-y-4 border-t bg-muted/20">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label className="text-xs capitalize">{serviceExamples.serviceName} Name *</Label>
          <Input
            value={formData.name}
            onChange={(e) => onChange("name", e.target.value)}
            placeholder={serviceExamples.serviceNamePlaceholder}
          />
        </div>
        <div className="space-y-2">
          <Label className="text-xs">How long does this take? (minutes)</Label>
          <Input
            type="number"
            value={formData.duration_minutes}
            onChange={(e) => onChange("duration_minutes", parseInt(e.target.value) || 60)}
            placeholder="60"
          />
          <p className="text-xs text-muted-foreground">{serviceExamples.durationHint}</p>
        </div>
      </div>

      <div className="space-y-2">
        <Label className="text-xs">Description</Label>
        <Textarea
          value={formData.description}
          onChange={(e) => onChange("description", e.target.value)}
          placeholder={serviceExamples.descriptionPlaceholder}
          rows={2}
        />
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label className="text-xs">How should AI quote this?</Label>
          <Select
            value={formData.price_type}
            onValueChange={(v) => onChange("price_type", v)}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="fixed">Quote exact price</SelectItem>
              <SelectItem value="starting_at">Quote "starting at" price</SelectItem>
              <SelectItem value="quote_only">Don't quote - offer callback</SelectItem>
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground">
            {formData.price_type === "fixed" && "AI says: \"That's $X\""}
            {formData.price_type === "starting_at" && "AI says: \"Starting at $X, depending on...\""}
            {formData.price_type === "quote_only" && "AI says: \"I'd need to have someone call you with a quote\""}
          </p>
        </div>
        <div className="space-y-2">
          <Label className="text-xs">Price ($)</Label>
          <Input
            type="number"
            step="0.01"
            value={formData.price_amount ?? ""}
            onChange={(e) => onChange("price_amount", e.target.value ? parseFloat(e.target.value) : null)}
            placeholder="150.00"
            disabled={formData.price_type === "quote_only"}
          />
        </div>
      </div>

      {/* Price Factors — shown when price varies */}
      {(formData.price_type === "starting_at" || formData.price_type === "quote_only") && (
        <div className="space-y-2">
          <Label className="text-xs">What makes the price vary? <span className="text-muted-foreground">(AI will explain this to callers)</span></Label>
          <Textarea
            value={formData.price_factors}
            onChange={(e) => onChange("price_factors", e.target.value)}
            placeholder={PRICE_FACTOR_HINTS[businessMode] || PRICE_FACTOR_HINTS.general}
            rows={2}
          />
        </div>
      )}

      {/* Complexity Toggle — hidden for food mode */}
      {businessMode !== "food" && (
        <div className="space-y-2">
          <Label className="text-xs">How should the AI handle this?</Label>
          <div className="flex gap-2">
            <Button
              type="button"
              variant={formData.complexity === "simple" ? "default" : "outline"}
              size="sm"
              onClick={() => onChange("complexity", "simple")}
              className="flex-1"
            >
              Quick confirmation
            </Button>
            <Button
              type="button"
              variant={formData.complexity === "complex" ? "default" : "outline"}
              size="sm"
              onClick={() => onChange("complexity", "complex")}
              className="flex-1"
            >
              Ask detailed questions
            </Button>
          </div>
          <p className="text-xs text-muted-foreground">
            {formData.complexity === "simple"
              ? `Quick: ${(COMPLEXITY_HINTS[businessMode] || COMPLEXITY_HINTS.general).simple}`
              : `Detailed: ${(COMPLEXITY_HINTS[businessMode] || COMPLEXITY_HINTS.general).complex}`
            }
          </p>
        </div>
      )}

      {/* Booking Type — hidden for food mode */}
      {businessMode !== "food" && (
        <div className="space-y-2">
          <Label className="text-xs">What happens when someone calls for this?</Label>
          <Select
            value={formData.booking_type}
            onValueChange={(v) => onChange("booking_type", v)}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="direct_book">Book it directly</SelectItem>
              <SelectItem value="estimate_first">Schedule an estimate visit first</SelectItem>
              <SelectItem value="consultation">Take their info for a callback</SelectItem>
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground">
            {formData.booking_type === "direct_book" && "AI will check availability and book the appointment on the call."}
            {formData.booking_type === "estimate_first" && "AI will book an estimate visit instead of the full job. Good for jobs that need an on-site quote."}
            {formData.booking_type === "consultation" && "AI will collect details and schedule a callback. Good for custom or complex projects."}
          </p>
        </div>
      )}

      {/* Prerequisite note — shown when not direct_book */}
      {businessMode !== "food" && formData.booking_type !== "direct_book" && (
        <div className="space-y-2">
          <Label className="text-xs">Any prerequisites the AI should mention?</Label>
          <Input
            value={formData.prerequisite_note}
            onChange={(e) => onChange("prerequisite_note", e.target.value)}
            placeholder="e.g., Requires on-site estimate first, Permit needed (adds 2 weeks)"
          />
        </div>
      )}

      {/* Required Intake Fields */}
      {businessMode !== "food" && (
        <div className="space-y-2">
          <Label className="text-xs">Required info to collect before booking</Label>
          <p className="text-[11px] text-muted-foreground">AI will ask for these before scheduling this service</p>
          <div className="flex flex-wrap gap-1.5">
            {COMMON_INTAKE_FIELDS.map((field) => {
              const selected = formData.required_intake_fields.includes(field);
              return (
                <Badge
                  key={field}
                  variant={selected ? "default" : "outline"}
                  className="cursor-pointer text-xs"
                  onClick={() => {
                    const next = selected
                      ? formData.required_intake_fields.filter((f) => f !== field)
                      : [...formData.required_intake_fields, field];
                    onChange("required_intake_fields", next);
                  }}
                >
                  {field.replace(/_/g, " ")}
                </Badge>
              );
            })}
          </div>
        </div>
      )}

      {/* Duration Range — collapsible enhancement */}
      {(formData.duration_min_minutes !== null || formData.duration_max_minutes !== null) ? (
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label className="text-xs">Min duration (minutes)</Label>
            <Input
              type="number"
              value={formData.duration_min_minutes ?? ""}
              onChange={(e) => onChange("duration_min_minutes", e.target.value ? parseInt(e.target.value) : null)}
              placeholder="30"
            />
          </div>
          <div className="space-y-2">
            <Label className="text-xs">Max duration (minutes)</Label>
            <Input
              type="number"
              value={formData.duration_max_minutes ?? ""}
              onChange={(e) => onChange("duration_max_minutes", e.target.value ? parseInt(e.target.value) : null)}
              placeholder="180"
            />
          </div>
          <p className="col-span-2 text-xs text-muted-foreground">
            AI will say "typically {formData.duration_minutes} minutes, but can range from {formData.duration_min_minutes || '?'} to {formData.duration_max_minutes || '?'} minutes"
          </p>
        </div>
      ) : (
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="text-xs text-muted-foreground"
          onClick={() => {
            onChange("duration_min_minutes", Math.max(15, Math.round(formData.duration_minutes * 0.5)));
            onChange("duration_max_minutes", Math.round(formData.duration_minutes * 2));
          }}
        >
          <Clock className="h-3 w-3 mr-1" />
          + Add duration range (for variable-length jobs)
        </Button>
      )}

      <div className="flex items-center gap-4 pt-2">
        <div className="flex items-center space-x-2">
          <Switch
            checked={formData.deposit_required}
            onCheckedChange={(checked) => onChange("deposit_required", checked)}
          />
          <Label className="text-sm">Collect deposit to confirm?</Label>
        </div>
        {formData.deposit_required && (
          <div className="flex items-center gap-2">
            <Label className="text-xs">Deposit ($):</Label>
            <Input
              type="number"
              step="0.01"
              value={formData.deposit_amount ?? ""}
              onChange={(e) => onChange("deposit_amount", e.target.value ? parseFloat(e.target.value) : null)}
              placeholder="50.00"
              className="w-24 h-8"
            />
          </div>
        )}
      </div>

      {/* Payment Timing — hidden for food mode */}
      {businessMode !== "food" && (
        <div className="space-y-2">
          <Label className="text-xs">When is payment collected?</Label>
          <Select
            value={formData.payment_timing}
            onValueChange={(v) => onChange("payment_timing", v)}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="at_service">At time of service</SelectItem>
              <SelectItem value="at_booking">At booking (prepay)</SelectItem>
              <SelectItem value="deposit_then_balance">Deposit now, balance at service</SelectItem>
              <SelectItem value="quote_first">After quote approval</SelectItem>
            </SelectContent>
          </Select>
          <p className="text-xs text-muted-foreground">
            {formData.payment_timing === "at_service" && "AI says: \"Payment is collected when we complete the service.\""}
            {formData.payment_timing === "at_booking" && "AI says: \"Payment is required to confirm your booking.\""}
            {formData.payment_timing === "deposit_then_balance" && "AI says: \"A deposit holds your spot, and the balance is due at service.\""}
            {formData.payment_timing === "quote_first" && "AI says: \"We'll provide a quote first, and payment is due after you approve it.\""}
          </p>
        </div>
      )}

      <div className="flex items-center justify-end gap-2 pt-2">
        <Button variant="outline" size="sm" onClick={onCancel} disabled={isSaving}>
          <X className="h-4 w-4 mr-1" />
          Cancel
        </Button>
        <Button size="sm" onClick={onSave} disabled={isSaving || !formData.name.trim()}>
          {isSaving ? (
            <Loader2 className="h-4 w-4 mr-1 animate-spin" />
          ) : (
            <Check className="h-4 w-4 mr-1" />
          )}
          {isNew ? "Add Service" : "Save Changes"}
        </Button>
      </div>
    </div>
  );
}

export function ServiceCatalogEditor() {
  const { tenant } = useAuth();
  const { services, isLoading } = useServices();
  const { businessMode } = useTenantConfig();
  const { terms, config, slug } = useIndustryContext();
  const queryClient = useQueryClient();

  const serviceExamples = slug
    ? getSlugServiceExamples(businessMode, slug)
    : getServiceExamples(businessMode);

  const [expandedServiceId, setExpandedServiceId] = useState<string | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingService, setDeletingService] = useState<any | null>(null);
  const [editingFormData, setEditingFormData] = useState<Record<string, ServiceFormData>>({});
  const [savingServiceId, setSavingServiceId] = useState<string | null>(null);
  const [isCreatingNew, setIsCreatingNew] = useState(false);
  const [newServiceData, setNewServiceData] = useState<ServiceFormData>(defaultFormData);
  const [pasteDialogOpen, setPasteDialogOpen] = useState(false);
  const [csvDialogOpen, setCsvDialogOpen] = useState(false);
  const [flatbedDialogOpen, setFlatbedDialogOpen] = useState(false);

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hours === 0) return `${mins}min`;
    if (mins === 0) return `${hours}h`;
    return `${hours}h ${mins}min`;
  };

  const formatPrice = (service: any) => {
    if (service.price_type === "quote_only") return "Quote Required";
    if (!service.price_amount) return "Not Set";
    const prefix = service.price_type === "starting_at" ? "From " : "";
    return `${prefix}$${service.price_amount}`;
  };

  const toggleService = (serviceId: string, service: any) => {
    if (expandedServiceId === serviceId) {
      setExpandedServiceId(null);
    } else {
      setExpandedServiceId(serviceId);
      // Initialize form data for this service if not already done
      if (!editingFormData[serviceId]) {
        setEditingFormData(prev => ({
          ...prev,
          [serviceId]: {
            name: service.name,
            description: service.description || "",
            duration_minutes: service.duration_minutes,
            price_type: service.price_type,
            price_amount: service.price_amount ? Number(service.price_amount) : null,
            deposit_amount: service.deposit_amount ? Number(service.deposit_amount) : null,
            deposit_required: service.deposit_required || false,
            complexity: service.complexity || "simple",
            price_factors: service.price_factors || "",
            booking_type: service.booking_type || "direct_book",
            prerequisite_note: service.prerequisite_note || "",
            duration_min_minutes: service.duration_min_minutes ?? null,
            duration_max_minutes: service.duration_max_minutes ?? null,
            required_intake_fields: Array.isArray((service as any).required_intake_fields) ? (service as any).required_intake_fields : [],
            payment_timing: (service as any).payment_timing || "at_service",
          }
        }));
      }
    }
    // Close new service form if open
    setIsCreatingNew(false);
  };

  const updateFormField = (serviceId: string, field: keyof ServiceFormData, value: any) => {
    setEditingFormData(prev => ({
      ...prev,
      [serviceId]: {
        ...prev[serviceId],
        [field]: value,
      }
    }));
  };

  const handleSave = async (serviceId: string) => {
    if (!tenant?.id) return;
    const formData = editingFormData[serviceId];
    if (!formData || !formData.name.trim()) return;

    setSavingServiceId(serviceId);
    try {
      await updateService(serviceId, tenant.id, {
        name: formData.name.trim(),
        description: formData.description.trim() || undefined,
        duration_minutes: formData.duration_minutes,
        price_type: formData.price_type,
        price_amount: formData.price_amount,
        deposit_amount: formData.deposit_amount,
        deposit_required: formData.deposit_required,
        complexity: formData.complexity,
        price_factors: formData.price_factors.trim() || undefined,
        booking_type: formData.booking_type,
        prerequisite_note: formData.prerequisite_note.trim() || undefined,
        duration_min_minutes: formData.duration_min_minutes,
        duration_max_minutes: formData.duration_max_minutes,
        required_intake_fields: formData.required_intake_fields.length > 0 ? formData.required_intake_fields : undefined,
        payment_timing: formData.payment_timing,
      } as any);
      toast.success("Service updated");
      queryClient.invalidateQueries({ queryKey: ["services"] });
      invalidateBrainQueries(queryClient, tenant?.id);
      setExpandedServiceId(null);
    } catch (error: any) {
      toast.error(error.message || "Failed to save service");
    } finally {
      setSavingServiceId(null);
    }
  };

  const handleCreateNew = async () => {
    if (!tenant?.id || !newServiceData.name.trim()) return;

    // Detect if this is a towing service (check if name contains "tow")
    const isTowingService = /tow/i.test(newServiceData.name.trim());

    // For dispatch mode towing services, show flatbed pricing dialog
    if (isTowingService && businessMode === "dispatch") {
      setFlatbedDialogOpen(true);
      return;
    }

    // Otherwise, create service normally
    await executeCreateService(false);
  };

  const executeCreateService = async (createSeparate: boolean, flatbedPrice?: number, wheelLiftPrice?: number) => {
    if (!tenant?.id || !newServiceData.name.trim()) return;

    setSavingServiceId("new");
    try {
      if (createSeparate && flatbedPrice !== undefined && wheelLiftPrice !== undefined) {
        // Create two services: Wheel Lift and Flatbed
        const baseName = newServiceData.name.trim().replace(/\s*-\s*(wheel\s*lift|flatbed|hook|truck)$/i, "");

        await createService(tenant.id, {
          name: `${baseName} - Wheel Lift`,
          description: newServiceData.description.trim() || "Standard towing method for rear-wheel drive vehicles",
          duration_minutes: newServiceData.duration_minutes,
          price_type: newServiceData.price_type,
          price_amount: wheelLiftPrice,
          deposit_amount: newServiceData.deposit_amount,
          deposit_required: newServiceData.deposit_required,
          complexity: newServiceData.complexity,
          price_factors: newServiceData.price_factors.trim() || undefined,
          booking_type: newServiceData.booking_type,
          prerequisite_note: newServiceData.prerequisite_note.trim() || undefined,
          duration_min_minutes: newServiceData.duration_min_minutes,
          duration_max_minutes: newServiceData.duration_max_minutes,
          required_intake_fields: newServiceData.required_intake_fields.length > 0 ? newServiceData.required_intake_fields : undefined,
          payment_timing: newServiceData.payment_timing,
        } as any);

        await createService(tenant.id, {
          name: `${baseName} - Flatbed`,
          description: newServiceData.description.trim() || "Recommended for AWD, luxury, exotic, and modified vehicles",
          duration_minutes: newServiceData.duration_minutes + 15, // Flatbed takes slightly longer
          price_type: newServiceData.price_type,
          price_amount: flatbedPrice,
          deposit_amount: newServiceData.deposit_amount,
          deposit_required: newServiceData.deposit_required,
          complexity: newServiceData.complexity,
          price_factors: newServiceData.price_factors.trim() || undefined,
          booking_type: newServiceData.booking_type,
          prerequisite_note: newServiceData.prerequisite_note.trim() || undefined,
          duration_min_minutes: newServiceData.duration_min_minutes ? newServiceData.duration_min_minutes + 15 : null,
          duration_max_minutes: newServiceData.duration_max_minutes ? newServiceData.duration_max_minutes + 15 : null,
          required_intake_fields: newServiceData.required_intake_fields.length > 0 ? newServiceData.required_intake_fields : undefined,
          payment_timing: newServiceData.payment_timing,
        } as any);

        toast.success("Created 2 services: Wheel Lift and Flatbed");
      } else {
        // Create single service
        await createService(tenant.id, {
          name: newServiceData.name.trim(),
          description: newServiceData.description.trim() || undefined,
          duration_minutes: newServiceData.duration_minutes,
          price_type: newServiceData.price_type,
          price_amount: newServiceData.price_amount,
          deposit_amount: newServiceData.deposit_amount,
          deposit_required: newServiceData.deposit_required,
          complexity: newServiceData.complexity,
          price_factors: newServiceData.price_factors.trim() || undefined,
          booking_type: newServiceData.booking_type,
          prerequisite_note: newServiceData.prerequisite_note.trim() || undefined,
          duration_min_minutes: newServiceData.duration_min_minutes,
          duration_max_minutes: newServiceData.duration_max_minutes,
          required_intake_fields: newServiceData.required_intake_fields.length > 0 ? newServiceData.required_intake_fields : undefined,
          payment_timing: newServiceData.payment_timing,
        } as any);
        toast.success("Service created");
      }

      queryClient.invalidateQueries({ queryKey: ["services"] });
      invalidateBrainQueries(queryClient, tenant?.id);
      setIsCreatingNew(false);
      setNewServiceData(defaultFormData);
    } catch (error: any) {
      toast.error(error.message || "Failed to create service");
    } finally {
      setSavingServiceId(null);
    }
  };

  const handleDelete = async () => {
    if (!tenant?.id || !deletingService) return;

    try {
      await deleteService(deletingService.id, tenant.id);
      toast.success("Service deleted");
      queryClient.invalidateQueries({ queryKey: ["services"] });
      invalidateBrainQueries(queryClient, tenant?.id);
      setDeleteDialogOpen(false);
      setDeletingService(null);
    } catch (error: any) {
      toast.error(error.message || "Failed to delete service");
    }
  };

  const handleToggleActive = async (service: any, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!tenant?.id) return;

    try {
      await updateService(service.id, tenant.id, {
        is_active: !service.is_active,
      });
      toast.success(service.is_active ? "Service deactivated" : "Service activated");
      queryClient.invalidateQueries({ queryKey: ["services"] });
      invalidateBrainQueries(queryClient, tenant?.id);
    } catch (error: any) {
      toast.error(error.message || "Failed to update service");
    }
  };

  const startCreatingNew = () => {
    setIsCreatingNew(true);
    setExpandedServiceId(null);
    setNewServiceData(defaultFormData);
  };

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="ml-3 text-sm text-muted-foreground">Loading services...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Build AI quote preview from first service
  const firstService = services?.[0];
  const aiQuotePreview = firstService
    ? `Our ${firstService.name.toLowerCase()} ${
        firstService.price_type === "starting_at" 
          ? `starts at $${firstService.price_amount}` 
          : firstService.price_type === "quote_only"
          ? "requires a custom quote"
          : `is $${firstService.price_amount}`
      }${firstService.duration_minutes ? ` and takes about ${formatDuration(firstService.duration_minutes)}` : ""}.`
    : "I can tell you about our services and pricing.";

  // ServiceForm is now extracted as a top-level component above

  return (
    <div className="space-y-6">
      {/* Compact upload action */}
      <InlineUploadButton
        contentType="services"
        variant="prominent"
        onUploadComplete={() => queryClient.invalidateQueries({ queryKey: ["services"] })}
      />

      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h3 className="text-lg font-semibold capitalize">{terms.services} Catalog</h3>
          <p className="text-sm text-muted-foreground">
            {services?.length 
              ? `${services.length} ${serviceExamples.serviceName}${services.length !== 1 ? 's' : ''} • Click to expand and edit`
              : `Add your ${terms.services} so the AI can quote prices and book ${terms.bookings}`
            }
          </p>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Button variant="outline" size="sm" onClick={() => setPasteDialogOpen(true)}>
            <ClipboardPaste className="h-3.5 w-3.5 mr-1.5" />
            Paste from POS
          </Button>
          <Button variant="outline" size="sm" onClick={() => setCsvDialogOpen(true)}>
            <FileSpreadsheet className="h-3.5 w-3.5 mr-1.5" />
            CSV Import
          </Button>
          <Button onClick={startCreatingNew} disabled={isCreatingNew}>
            <Plus className="h-4 w-4 mr-2" />
            {terms.addService}
          </Button>
        </div>
      </div>

      {/* New Service Form */}
      {isCreatingNew && (
        <Card>
          <div className="px-4 py-3 flex items-center gap-3 bg-primary/5 border-b">
            <Plus className="h-4 w-4 text-primary" />
            <span className="font-medium text-sm capitalize">New {serviceExamples.serviceName}</span>
          </div>
          <ServiceForm
            formData={newServiceData}
            onChange={(field, value) => setNewServiceData(prev => ({ ...prev, [field]: value }))}
            onSave={handleCreateNew}
            onCancel={() => {
              setIsCreatingNew(false);
              setNewServiceData(defaultFormData);
            }}
            isSaving={savingServiceId === "new"}
            isNew
            serviceExamples={serviceExamples}
            businessMode={businessMode}
          />
        </Card>
      )}

      {/* Services List */}
      {services && services.length > 0 ? (
        <div className="space-y-2">
          {services.map((service) => {
            const isExpanded = expandedServiceId === service.id;
            const formData = editingFormData[service.id];

            return (
              <Collapsible
                key={service.id}
                open={isExpanded}
                onOpenChange={() => toggleService(service.id, service)}
              >
                <Card className="overflow-hidden">
                  <CollapsibleTrigger asChild>
                    <button className="w-full px-4 py-3 flex items-center justify-between hover:bg-muted/50 transition-colors text-left">
                      <div className="flex items-center gap-3 flex-1 min-w-0">
                        {isExpanded ? (
                          <ChevronDown className="h-4 w-4 text-muted-foreground shrink-0" />
                        ) : (
                          <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
                        )}
                        <div className="min-w-0">
                          <div className="flex items-center gap-2">
                            <span className="font-medium text-sm truncate">{service.name}</span>
                            {!service.is_active && (
                              <Badge variant="outline" className="text-xs shrink-0">Inactive</Badge>
                            )}
                          </div>
                          {service.description && (
                            <p className="text-xs text-muted-foreground truncate mt-0.5">
                              {service.description}
                            </p>
                          )}
                        </div>
                      </div>
                      <div className="flex items-center gap-4 shrink-0">
                        <div className="flex items-center gap-3 text-sm">
                          <span className="font-medium">{formatPrice(service)}</span>
                          <span className="flex items-center gap-1 text-muted-foreground text-xs">
                            <Clock className="h-3 w-3" />
                            {formatDuration(service.duration_minutes)}
                          </span>
                        </div>
                        <Button
                          size="icon"
                          variant="ghost"
                          className="h-7 w-7 text-destructive hover:text-destructive shrink-0"
                          onClick={(e) => {
                            e.stopPropagation();
                            setDeletingService(service);
                            setDeleteDialogOpen(true);
                          }}
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                        </Button>
                      </div>
                    </button>
                  </CollapsibleTrigger>
                  <CollapsibleContent>
                    {formData && (
                      <ServiceForm
                        formData={formData}
                        onChange={(field, value) => updateFormField(service.id, field, value)}
                        onSave={() => handleSave(service.id)}
                        onCancel={() => setExpandedServiceId(null)}
                        isSaving={savingServiceId === service.id}
                        serviceExamples={serviceExamples}
                        businessMode={businessMode}
                      />
                    )}
                    <div className="px-4 py-2 border-t bg-muted/10 flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <Switch
                          checked={service.is_active}
                          onCheckedChange={() => handleToggleActive(service, { stopPropagation: () => {} } as any)}
                        />
                        <Label className="text-xs text-muted-foreground">
                          {service.is_active ? "Active" : "Inactive"}
                        </Label>
                      </div>
                    </div>
                  </CollapsibleContent>
                </Card>
              </Collapsible>
            );
          })}
        </div>
      ) : !isCreatingNew && (
        <Card>
          <CardContent className="p-8 text-center">
            <div className="flex flex-col items-center gap-4 max-w-md mx-auto">
              <div className="h-16 w-16 rounded-full bg-muted flex items-center justify-center">
                <DollarSign className="h-8 w-8 text-muted-foreground" />
              </div>
              <div>
                <h3 className="font-semibold text-lg mb-1">No {terms.services} yet</h3>
                <p className="text-sm text-muted-foreground">
                  Use the upload button above to import your {terms.services} list, or add them manually.
                </p>
              </div>
              <Button onClick={startCreatingNew}>
                <Plus className="h-4 w-4 mr-2" />
                Add Manually
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Delete Confirmation */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Service</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete "{deletingService?.name}"? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground hover:bg-destructive/90">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* POS Paste Dialog */}
      <PasteFromPOSDialog open={pasteDialogOpen} onOpenChange={setPasteDialogOpen} />

      {/* CSV Import Dialog */}
      <ServiceCSVImportDialog open={csvDialogOpen} onOpenChange={setCsvDialogOpen} />

      {/* Flatbed Pricing Dialog */}
      <FlatbedPricingDialog
        open={flatbedDialogOpen}
        onOpenChange={setFlatbedDialogOpen}
        serviceName={newServiceData.name.trim()}
        basePrice={newServiceData.price_amount}
        onConfirm={executeCreateService}
      />
    </div>
  );
}

/**
 * Service Packages Editor
 * 
 * Allows businesses to create:
 * - Bundles: Combine services for a discounted price
 * - Memberships: Recurring subscriptions with included services
 * - Treatment Series: Medical packages (e.g., 6-session laser treatment)
 * 
 * Industry-aware: Shows relevant package types based on business mode
 */

import { useState, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useServices } from "@/hooks/useServices";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Plus,
  Trash2,
  Loader2,
  Info,
  Lightbulb,
  ChevronDown,
  ChevronRight,
  Check,
  X,
  Package,
  Star,
  Calendar,
  CreditCard,
  DollarSign,
} from "lucide-react";
import { toast } from "sonner";

type PackageType = "bundle" | "membership" | "treatment_series";
type BillingInterval = "weekly" | "monthly" | "quarterly" | "yearly";

interface ServicePackage {
  id: string;
  name: string;
  description: string | null;
  package_type: PackageType;
  regular_price_cents: number | null;
  package_price_cents: number;
  billing_interval: BillingInterval | null;
  included_services_per_period: Record<string, number> | null;
  member_discount_percent: number;
  total_sessions: number | null;
  session_validity_days: number | null;
  included_items: Array<{ service_id: string; quantity: number }>;
  is_active: boolean;
  is_featured: boolean;
}

interface PackageFormData {
  name: string;
  description: string;
  package_type: PackageType;
  regular_price_cents: number;
  package_price_cents: number;
  billing_interval: BillingInterval;
  member_discount_percent: number;
  total_sessions: number;
  session_validity_days: number;
  included_items: Array<{ service_id: string; quantity: number }>;
  is_featured: boolean;
}

const defaultFormData: PackageFormData = {
  name: "",
  description: "",
  package_type: "bundle",
  regular_price_cents: 0,
  package_price_cents: 0,
  billing_interval: "monthly",
  member_discount_percent: 10,
  total_sessions: 6,
  session_validity_days: 180,
  included_items: [],
  is_featured: false,
};

const PACKAGE_TYPES = {
  bundle: {
    label: "Service Bundle",
    description: "Combine multiple services at a discounted price",
    icon: Package,
    modes: ["service", "dispatch", "medical", "general"],
    example: "Full Detail Package = Interior + Exterior + Ceramic Coating",
  },
  membership: {
    label: "Membership Plan",
    description: "Recurring subscription with included services each period",
    icon: CreditCard,
    modes: ["service", "medical"],
    example: "Gold Member = 2 washes/month + 10% off all services",
  },
  treatment_series: {
    label: "Treatment Series",
    description: "Package of treatments to be used over time",
    icon: Calendar,
    modes: ["medical", "service"],
    example: "6-Session Laser Package at 15% off",
  },
};

export function ServicePackagesEditor() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const { services } = useServices();
  const queryClient = useQueryClient();

  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [isCreatingNew, setIsCreatingNew] = useState(false);
  const [selectedType, setSelectedType] = useState<PackageType | null>(null);
  const [newFormData, setNewFormData] = useState<PackageFormData>(defaultFormData);
  const [editingFormData, setEditingFormData] = useState<Record<string, PackageFormData>>({});
  const [savingId, setSavingId] = useState<string | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingPackage, setDeletingPackage] = useState<ServicePackage | null>(null);

  // Fetch packages
  const { data: packages, isLoading } = useQuery({
    queryKey: ["service-packages", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("service_packages")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("display_order")
        .order("created_at");
      if (error) throw error;
      return (data || []) as unknown as ServicePackage[];
    },
    enabled: !!tenant?.id,
  });

  // Filter to primary services only
  const primaryServices = useMemo(() => {
    return services?.filter(s => s.service_type !== "secondary" && s.is_active) || [];
  }, [services]);

  // Filter relevant package types for this mode
  const relevantTypes = useMemo(() => {
    return Object.entries(PACKAGE_TYPES)
      .filter(([_, config]) => config.modes.includes(businessMode))
      .map(([key, config]) => ({ key: key as PackageType, ...config }));
  }, [businessMode]);

  const formatPrice = (cents: number) => {
    return `$${(cents / 100).toFixed(2)}`;
  };

  const calculateSavings = (regular: number, package_: number) => {
    if (!regular || regular <= package_) return null;
    const savings = regular - package_;
    const percent = Math.round((savings / regular) * 100);
    return { amount: savings, percent };
  };

  const getServiceName = (serviceId: string) => {
    const service = primaryServices.find(s => s.id === serviceId);
    return service?.name || "Unknown Service";
  };

  const handleSave = async (packageId: string) => {
    if (!tenant?.id) return;
    const formData = editingFormData[packageId];
    if (!formData?.name.trim()) return;

    setSavingId(packageId);
    try {
      const { error } = await supabase
        .from("service_packages")
        .update({
          name: formData.name.trim(),
          description: formData.description.trim() || null,
          package_type: formData.package_type,
          regular_price_cents: formData.regular_price_cents || null,
          package_price_cents: formData.package_price_cents,
          billing_interval: formData.package_type === "membership" ? formData.billing_interval : null,
          member_discount_percent: formData.member_discount_percent,
          total_sessions: formData.package_type === "treatment_series" ? formData.total_sessions : null,
          session_validity_days: formData.package_type === "treatment_series" ? formData.session_validity_days : null,
          included_items: formData.included_items,
          is_featured: formData.is_featured,
        })
        .eq("id", packageId)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      toast.success("Package updated");
      queryClient.invalidateQueries({ queryKey: ["service-packages"] });
      setExpandedId(null);
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setSavingId(null);
    }
  };

  const handleCreate = async () => {
    if (!tenant?.id || !newFormData.name.trim()) return;

    setSavingId("new");
    try {
      const { error } = await supabase
        .from("service_packages")
        .insert({
          tenant_id: tenant.id,
          name: newFormData.name.trim(),
          description: newFormData.description.trim() || null,
          package_type: newFormData.package_type,
          regular_price_cents: newFormData.regular_price_cents || null,
          package_price_cents: newFormData.package_price_cents,
          billing_interval: newFormData.package_type === "membership" ? newFormData.billing_interval : null,
          member_discount_percent: newFormData.member_discount_percent,
          total_sessions: newFormData.package_type === "treatment_series" ? newFormData.total_sessions : null,
          session_validity_days: newFormData.package_type === "treatment_series" ? newFormData.session_validity_days : null,
          included_items: newFormData.included_items,
          is_featured: newFormData.is_featured,
        });

      if (error) throw error;
      toast.success("Package created");
      queryClient.invalidateQueries({ queryKey: ["service-packages"] });
      setIsCreatingNew(false);
      setSelectedType(null);
      setNewFormData(defaultFormData);
    } catch (error: any) {
      toast.error(error.message || "Failed to create");
    } finally {
      setSavingId(null);
    }
  };

  const handleDelete = async () => {
    if (!tenant?.id || !deletingPackage) return;

    try {
      const { error } = await supabase
        .from("service_packages")
        .delete()
        .eq("id", deletingPackage.id)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      toast.success("Package removed");
      queryClient.invalidateQueries({ queryKey: ["service-packages"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    } finally {
      setDeleteDialogOpen(false);
      setDeletingPackage(null);
    }
  };

  const handleToggleActive = async (pkg: ServicePackage) => {
    if (!tenant?.id) return;

    try {
      const { error } = await supabase
        .from("service_packages")
        .update({ is_active: !pkg.is_active })
        .eq("id", pkg.id)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      toast.success(pkg.is_active ? "Package hidden" : "Package visible");
      queryClient.invalidateQueries({ queryKey: ["service-packages"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to update");
    }
  };

  const addServiceToForm = (formData: PackageFormData, setFormData: (data: PackageFormData) => void) => {
    if (primaryServices.length === 0) return;
    const existingIds = formData.included_items.map(i => i.service_id);
    const availableService = primaryServices.find(s => !existingIds.includes(s.id));
    if (availableService) {
      setFormData({
        ...formData,
        included_items: [...formData.included_items, { service_id: availableService.id, quantity: 1 }],
      });
    }
  };

  const removeServiceFromForm = (
    formData: PackageFormData,
    setFormData: (data: PackageFormData) => void,
    index: number
  ) => {
    setFormData({
      ...formData,
      included_items: formData.included_items.filter((_, i) => i !== index),
    });
  };

  const toggleExpanded = (id: string, pkg: ServicePackage) => {
    if (expandedId === id) {
      setExpandedId(null);
    } else {
      setExpandedId(id);
      if (!editingFormData[id]) {
        setEditingFormData(prev => ({
          ...prev,
          [id]: {
            name: pkg.name,
            description: pkg.description || "",
            package_type: pkg.package_type,
            regular_price_cents: pkg.regular_price_cents || 0,
            package_price_cents: pkg.package_price_cents,
            billing_interval: pkg.billing_interval || "monthly",
            member_discount_percent: pkg.member_discount_percent,
            total_sessions: pkg.total_sessions || 6,
            session_validity_days: pkg.session_validity_days || 180,
            included_items: pkg.included_items || [],
            is_featured: pkg.is_featured,
          },
        }));
      }
    }
    setIsCreatingNew(false);
  };

  // AI Preview
  const aiPreview = useMemo(() => {
    const activePackages = packages?.filter(p => p.is_active) || [];
    if (activePackages.length === 0) return null;
    
    const featured = activePackages.find(p => p.is_featured) || activePackages[0];
    const savings = calculateSavings(featured.regular_price_cents || 0, featured.package_price_cents);
    
    if (savings) {
      return `Our ${featured.name} is ${formatPrice(featured.package_price_cents)} — that's ${savings.percent}% off if you purchased separately!`;
    }
    return `We have a ${featured.name} available for ${formatPrice(featured.package_price_cents)}.`;
  }, [packages]);

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="ml-3 text-sm text-muted-foreground">Loading packages...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Form Component
  const PackageForm = ({
    formData,
    onChange,
    onSave,
    onCancel,
    isSaving,
    isNew = false,
  }: {
    formData: PackageFormData;
    onChange: (data: PackageFormData) => void;
    onSave: () => void;
    onCancel: () => void;
    isSaving: boolean;
    isNew?: boolean;
  }) => {
    const typeConfig = PACKAGE_TYPES[formData.package_type];
    const savings = calculateSavings(formData.regular_price_cents, formData.package_price_cents);

    return (
      <div className="p-4 space-y-4 border-t bg-muted/20">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label className="text-xs">Package Name *</Label>
            <Input
              value={formData.name}
              onChange={(e) => onChange({ ...formData, name: e.target.value })}
              placeholder="e.g., Full Detail Package, Gold Membership"
            />
          </div>
          <div className="space-y-2">
            <Label className="text-xs">Package Type</Label>
            <Select
              value={formData.package_type}
              onValueChange={(v) => onChange({ ...formData, package_type: v as PackageType })}
              disabled={!isNew}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {relevantTypes.map(type => (
                  <SelectItem key={type.key} value={type.key}>{type.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="space-y-2">
          <Label className="text-xs">Description (optional)</Label>
          <Textarea
            value={formData.description}
            onChange={(e) => onChange({ ...formData, description: e.target.value })}
            placeholder="What's included and why it's a great value..."
            rows={2}
          />
        </div>

        {/* Included Services */}
        <div className="space-y-2">
          <div className="flex items-center justify-between">
            <Label className="text-xs">Included Services</Label>
            <Button
              variant="outline"
              size="sm"
              onClick={() => addServiceToForm(formData, onChange)}
              disabled={primaryServices.length === 0}
            >
              <Plus className="h-3 w-3 mr-1" />
              Add Service
            </Button>
          </div>
          {formData.included_items.length === 0 ? (
            <p className="text-xs text-muted-foreground py-2">
              No services added yet. Add services to include in this package.
            </p>
          ) : (
            <div className="space-y-2">
              {formData.included_items.map((item, index) => (
                <div key={index} className="flex items-center gap-2">
                  <Select
                    value={item.service_id}
                    onValueChange={(v) => {
                      const newItems = [...formData.included_items];
                      newItems[index] = { ...item, service_id: v };
                      onChange({ ...formData, included_items: newItems });
                    }}
                  >
                    <SelectTrigger className="flex-1">
                      <SelectValue placeholder="Select service..." />
                    </SelectTrigger>
                    <SelectContent>
                      {primaryServices.map(service => (
                        <SelectItem key={service.id} value={service.id}>
                          {service.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <span className="text-xs text-muted-foreground">×</span>
                  <Input
                    type="number"
                    min={1}
                    value={item.quantity}
                    onChange={(e) => {
                      const newItems = [...formData.included_items];
                      newItems[index] = { ...item, quantity: parseInt(e.target.value) || 1 };
                      onChange({ ...formData, included_items: newItems });
                    }}
                    className="w-16"
                  />
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => removeServiceFromForm(formData, onChange, index)}
                  >
                    <Trash2 className="h-4 w-4 text-muted-foreground" />
                  </Button>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Pricing */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div className="space-y-2">
            <Label className="text-xs">Regular Price (if purchased separately)</Label>
            <div className="relative">
              <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                type="number"
                step="0.01"
                value={(formData.regular_price_cents / 100).toFixed(2)}
                onChange={(e) => onChange({ ...formData, regular_price_cents: Math.round(parseFloat(e.target.value) * 100) || 0 })}
                className="pl-8"
                placeholder="250.00"
              />
            </div>
          </div>
          <div className="space-y-2">
            <Label className="text-xs">Package Price *</Label>
            <div className="relative">
              <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                type="number"
                step="0.01"
                value={(formData.package_price_cents / 100).toFixed(2)}
                onChange={(e) => onChange({ ...formData, package_price_cents: Math.round(parseFloat(e.target.value) * 100) || 0 })}
                className="pl-8"
                placeholder="199.00"
              />
            </div>
          </div>
          <div className="space-y-2">
            <Label className="text-xs">Savings</Label>
            <div className="h-10 flex items-center px-3 rounded-md border bg-muted/50">
              {savings ? (
                <span className="text-sm font-medium text-primary">
                  Save {savings.percent}% ({formatPrice(savings.amount)})
                </span>
              ) : (
                <span className="text-sm text-muted-foreground">Set both prices</span>
              )}
            </div>
          </div>
        </div>

        {/* Membership-specific fields */}
        {formData.package_type === "membership" && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2 border-t">
            <div className="space-y-2">
              <Label className="text-xs">Billing Interval</Label>
              <Select
                value={formData.billing_interval}
                onValueChange={(v) => onChange({ ...formData, billing_interval: v as BillingInterval })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="weekly">Weekly</SelectItem>
                  <SelectItem value="monthly">Monthly</SelectItem>
                  <SelectItem value="quarterly">Quarterly</SelectItem>
                  <SelectItem value="yearly">Yearly</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label className="text-xs">Member Discount on Other Services (%)</Label>
              <Input
                type="number"
                min={0}
                max={100}
                value={formData.member_discount_percent}
                onChange={(e) => onChange({ ...formData, member_discount_percent: parseInt(e.target.value) || 0 })}
                placeholder="10"
              />
            </div>
          </div>
        )}

        {/* Treatment Series-specific fields */}
        {formData.package_type === "treatment_series" && (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 pt-2 border-t">
            <div className="space-y-2">
              <Label className="text-xs">Total Sessions</Label>
              <Input
                type="number"
                min={1}
                value={formData.total_sessions}
                onChange={(e) => onChange({ ...formData, total_sessions: parseInt(e.target.value) || 1 })}
                placeholder="6"
              />
            </div>
            <div className="space-y-2">
              <Label className="text-xs">Days to Use All Sessions</Label>
              <Input
                type="number"
                min={1}
                value={formData.session_validity_days}
                onChange={(e) => onChange({ ...formData, session_validity_days: parseInt(e.target.value) || 180 })}
                placeholder="180"
              />
            </div>
          </div>
        )}

        <div className="flex items-center justify-between pt-2">
          <div className="flex items-center gap-2">
            <input
              type="checkbox"
              id="featured"
              checked={formData.is_featured}
              onChange={(e) => onChange({ ...formData, is_featured: e.target.checked })}
              className="rounded border-input"
            />
            <Label htmlFor="featured" className="text-xs text-muted-foreground cursor-pointer">
              Feature this package (AI mentions it first)
            </Label>
          </div>
          <div className="flex items-center gap-2">
            <Button variant="outline" size="sm" onClick={onCancel} disabled={isSaving}>
              <X className="h-4 w-4 mr-1" />
              Cancel
            </Button>
            <Button size="sm" onClick={onSave} disabled={isSaving || !formData.name.trim()}>
              {isSaving ? (
                <Loader2 className="h-4 w-4 mr-1 animate-spin" />
              ) : (
                <Check className="h-4 w-4 mr-1" />
              )}
              {isNew ? "Create Package" : "Save"}
            </Button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Explanation */}
      <div className="rounded-lg border bg-muted/30 p-4">
        <div className="flex items-start gap-3">
          <Info className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div className="space-y-2">
            <p className="text-sm font-medium">What are Service Packages?</p>
            <p className="text-sm text-muted-foreground">
              Packages let you bundle services together at a discounted price. 
              When customers ask about deals or packages, the AI can offer these options and explain the savings.
            </p>
            <div className="flex items-center gap-2 pt-1">
              <Lightbulb className="h-4 w-4 text-warning shrink-0" />
              <p className="text-xs text-muted-foreground">
                <strong>Tip:</strong> Mark one package as "featured" so the AI suggests it first!
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* AI Preview */}
      {aiPreview && (
        <div className="rounded-lg border bg-primary/5 border-primary/20 p-4">
          <div className="flex items-start gap-3">
            <Package className="h-5 w-5 text-primary shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-medium text-primary mb-1">How the AI promotes packages</p>
              <p className="text-sm italic">"{aiPreview}"</p>
            </div>
          </div>
        </div>
      )}

      {/* Create New Section */}
      {!isCreatingNew && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-medium">Create a Package</h3>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
            {relevantTypes.map(type => {
              const Icon = type.icon;
              return (
                <button
                  key={type.key}
                  onClick={() => {
                    setNewFormData({ ...defaultFormData, package_type: type.key });
                    setSelectedType(type.key);
                    setIsCreatingNew(true);
                  }}
                  className="flex flex-col items-start gap-2 p-4 rounded-lg border bg-card hover:bg-accent/50 transition-colors text-left"
                >
                  <div className="p-2 rounded-md bg-primary/10">
                    <Icon className="h-5 w-5 text-primary" />
                  </div>
                  <div>
                    <h4 className="text-sm font-medium">{type.label}</h4>
                    <p className="text-xs text-muted-foreground mt-0.5">{type.description}</p>
                  </div>
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* New Package Form */}
      {isCreatingNew && selectedType && (
        <Card>
          <div className="px-4 py-3 flex items-center gap-3 bg-primary/5 border-b">
            <Plus className="h-4 w-4 text-primary" />
            <span className="font-medium text-sm">
              New {PACKAGE_TYPES[selectedType].label}
            </span>
          </div>
          <PackageForm
            formData={newFormData}
            onChange={setNewFormData}
            onSave={handleCreate}
            onCancel={() => {
              setIsCreatingNew(false);
              setSelectedType(null);
              setNewFormData(defaultFormData);
            }}
            isSaving={savingId === "new"}
            isNew
          />
        </Card>
      )}

      {/* Existing Packages */}
      {packages && packages.length > 0 && (
        <div className="space-y-3">
          <h3 className="text-sm font-medium">Your Packages</h3>
          <div className="space-y-2">
            {packages.map(pkg => {
              const typeConfig = PACKAGE_TYPES[pkg.package_type];
              const Icon = typeConfig.icon;
              const isExpanded = expandedId === pkg.id;
              const savings = calculateSavings(pkg.regular_price_cents || 0, pkg.package_price_cents);

              return (
                <Collapsible
                  key={pkg.id}
                  open={isExpanded}
                  onOpenChange={() => toggleExpanded(pkg.id, pkg)}
                >
                  <Card className="overflow-hidden">
                    <CollapsibleTrigger asChild>
                      <button className="w-full px-4 py-3 flex items-center justify-between hover:bg-muted/50 transition-colors text-left">
                        <div className="flex items-center gap-3 flex-1 min-w-0">
                          {isExpanded ? (
                            <ChevronDown className="h-4 w-4 text-muted-foreground shrink-0" />
                          ) : (
                            <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
                          )}
                          <Icon className="h-4 w-4 text-muted-foreground shrink-0" />
                          <div className="min-w-0">
                            <div className="flex items-center gap-2">
                              <span className="font-medium text-sm truncate">{pkg.name}</span>
                              {pkg.is_featured && (
                                <Star className="h-3 w-3 text-warning fill-warning" />
                              )}
                              <Badge variant="secondary" className="text-xs shrink-0">
                                {typeConfig.label}
                              </Badge>
                              {!pkg.is_active && (
                                <Badge variant="outline" className="text-xs shrink-0">Hidden</Badge>
                              )}
                            </div>
                          </div>
                        </div>
                        <div className="flex items-center gap-3 shrink-0">
                          <div className="text-right">
                            <p className="text-sm font-medium">{formatPrice(pkg.package_price_cents)}</p>
                            {savings && (
                              <p className="text-xs text-primary">Save {savings.percent}%</p>
                            )}
                          </div>
                        </div>
                      </button>
                    </CollapsibleTrigger>
                    <CollapsibleContent>
                      {editingFormData[pkg.id] && (
                        <PackageForm
                          formData={editingFormData[pkg.id]}
                          onChange={(data) => setEditingFormData(prev => ({ ...prev, [pkg.id]: data }))}
                          onSave={() => handleSave(pkg.id)}
                          onCancel={() => setExpandedId(null)}
                          isSaving={savingId === pkg.id}
                        />
                      )}
                      <div className="px-4 pb-3 flex justify-between">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleToggleActive(pkg)}
                        >
                          {pkg.is_active ? "Hide from AI" : "Show to AI"}
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          className="text-destructive hover:text-destructive"
                          onClick={() => {
                            setDeletingPackage(pkg);
                            setDeleteDialogOpen(true);
                          }}
                        >
                          <Trash2 className="h-4 w-4 mr-1" />
                          Delete
                        </Button>
                      </div>
                    </CollapsibleContent>
                  </Card>
                </Collapsible>
              );
            })}
          </div>
        </div>
      )}

      {/* Empty State */}
      {(!packages || packages.length === 0) && !isCreatingNew && (
        <div className="text-center py-8 text-muted-foreground">
          <Package className="h-12 w-12 mx-auto mb-3 opacity-50" />
          <p className="text-sm">No packages created yet</p>
          <p className="text-xs mt-1">Create a package to offer bundled discounts</p>
        </div>
      )}

      {/* Delete Confirmation */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Package?</AlertDialogTitle>
            <AlertDialogDescription>
              This will remove "{deletingPackage?.name}" from your offerings. This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete} className="bg-destructive text-destructive-foreground">
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

