  const handleAdd = () => {
    if (!newName.trim()) return;
    createStaffMember.mutate(
      {
        full_name: newName.trim(),
        role: newRole,
        is_active: true,
        email: null,
        phone: null,
        hours_json: null,
        service_ids: null,
        calendar_connection_id: null,
        color: COLORS[staff.length % COLORS.length],
        sort_order: staff.length,
      },
      {
        onSuccess: () => {
          setNewName("");
          setNewRole("staff");
          setShowAddForm(false);
