            <div>
              <div className="flex items-center justify-between mb-2">
                <Label>Services</Label>
                <button
                  type="button"
                  className="text-xs text-primary hover:underline"
                  onClick={() => onUpdate({ service_ids: allServices ? services.map((s) => s.id) : null })}
