export function SuggestedFAQButtons({
  onAdd, existingQuestions = [], tenantPolicies,
  tenantName, tenantAddress, tenantHours, tenantServiceArea,
}: SuggestedFAQButtonsProps) {
  const { businessMode } = useTenantConfig();

  // Get FAQs for current business mode
  const suggestedFaqs = MODE_FAQS[businessMode] || MODE_FAQS.general;

  // Filter out already-added FAQs and policy-covered FAQs
  const policyOverlapPatterns = [
    ...(tenantPolicies?.cancellation ? ["cancellation"] : []),
    ...(tenantPolicies?.deposit ? ["deposit"] : []),
    ...(tenantPolicies?.refund ? ["refund", "return"] : []),
  ];

  const availableFAQs = suggestedFaqs
    .filter(faq => {
      // Skip if already added
      if (existingQuestions.some(q => q.toLowerCase().includes(faq.question.toLowerCase().slice(0, 20)))) return false;
      // Skip if covered by a policy
      if (policyOverlapPatterns.some(pattern => faq.question.toLowerCase().includes(pattern))) return false;
      return true;
    })
    .map(faq => personalizeFAQ(faq, tenantAddress, tenantHours, tenantServiceArea));

  if (availableFAQs.length === 0) {
    return null;
  }

  return (
    <div className="space-y-2">
      <div className="flex items-center gap-2 text-xs text-muted-foreground">
        <Lightbulb className="h-3 w-3 shrink-0" />
        <span className="truncate">Quick add:</span>
      </div>
      <div className="flex gap-2 overflow-x-auto pb-1 -mb-1 scrollbar-thin">
        {availableFAQs.slice(0, 4).map((faq) => (
          <button
            key={faq.question}
            type="button"
            className="inline-flex items-center gap-1 px-2.5 py-1 text-xs font-medium rounded-full border border-border bg-background hover:bg-muted/50 transition-colors whitespace-nowrap shrink-0"
            onClick={() => onAdd(faq.question, faq.answer)}
            title={faq.needsEditing ? "Needs your details — edit after adding" : undefined}
          >
            <Plus className="h-3 w-3" />
            {faq.question}
            {faq.needsEditing && (
              <AlertCircle className="h-3 w-3 text-amber-500 shrink-0" />
            )}
          </button>
        ))}
      </div>
    </div>
  );
}

/**
 * Business Brain - Preview Panel
 * 
 * Shows "What the AI sees" - a read-only summary of current values
 * without calling any new APIs.
 */

import { useMemo } from "react";
import { Volume2, CheckCircle2, AlertCircle, Info, Building2, Clock, Package, MapPin, Shield, Sparkles, BookOpen } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { useBrainSummaries } from "@/hooks/useBrainSummaries";
import { useBusinessCapabilities } from "@/hooks/useBusinessCapabilities";
import { cn } from "@/lib/utils";

interface BrainPreviewPanelProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  activeSection?: string;
}

interface PreviewSection {
  id: string;
  label: string;
  icon: React.ComponentType<{ className?: string }>;
  items: Array<{
    label: string;
    value: string | null;
    status: "complete" | "missing" | "partial";
  }>;
}

export function BrainPreviewPanel({ open, onOpenChange, activeSection }: BrainPreviewPanelProps) {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const caps = useCapabilities();
  const summaries = useBrainSummaries();
  const capabilities = useBusinessCapabilities();

  // Parse hours for display
  const hoursDisplay = useMemo(() => {
    const hoursJson = tenant?.hours_json as Record<string, { closed?: boolean; windows?: { open: string; close: string }[] }> | null;
    if (!hoursJson || typeof hoursJson !== "object") return null;
    const openDays = Object.entries(hoursJson).filter(([, day]) => day && !day.closed && Array.isArray(day.windows) && day.windows.length > 0);
    if (openDays.length === 0) return null;
    if (openDays.length === 7) return "7 days configured";
    if (openDays.length >= 5) return `${openDays.length} days configured`;
    return `${openDays.length} day${openDays.length === 1 ? "" : "s"} configured`;
  }, [tenant?.hours_json]);

  // Build preview data from tenant
  const sections = useMemo<PreviewSection[]>(() => {
    if (!tenant) return [];

    return [
      {
        id: "profile",
        label: "Profile & Identity",
        icon: Building2,
        items: [
          {
            label: "Business Name",
            value: tenant.name || null,
            status: tenant.name ? "complete" : "missing",
          },
          {
            label: "Timezone",
            value: tenant.timezone || null,
            status: tenant.timezone ? "complete" : "missing",
          },
          {
            label: "Address",
            value: tenant.address || null,
            status: tenant.address ? "complete" : "missing",
          },
          {
            label: "Tagline",
            value: tenant.tagline || null,
            status: tenant.tagline ? "complete" : "partial",
          },
        ],
      },
      {
        id: "hours",
        label: "Operating Hours",
        icon: Clock,
        items: [
          {
            label: "Hours Configured",
            value: hoursDisplay || null,
            status: hoursDisplay ? "complete" : "missing",
          },
        ],
      },
      {
        id: "services",
        label: caps.isFoodBusiness ? "Menu" : "Services",
        icon: Package,
        items: [
          {
            label: caps.isFoodBusiness ? "Menu Items" : "Services",
            value: summaries.catalog !== "No services added yet" ? summaries.catalog : null,
            status: capabilities.hasServices ? "complete" : "missing",
          },
        ],
      },
      {
        id: "service-area",
        label: "Service Area",
        icon: MapPin,
        items: [
          {
            label: "Coverage Mode",
            value: (() => {
              const sa = (tenant as Record<string, unknown>).service_area_json as Record<string, unknown> | null;
              if (!sa || Object.keys(sa).length === 0) return null;
              const radius = (sa as { radius_miles?: number }).radius_miles;
              return radius ? `${radius} mile radius` : "Configured";
            })(),
            status: (() => {
              const sa = (tenant as Record<string, unknown>).service_area_json as Record<string, unknown> | null;
              return sa && Object.keys(sa).length > 0 ? "complete" : "missing";
            })(),
          },
          {
            label: "Base Address",
            value: tenant.address || null,
            status: tenant.address ? "complete" : "missing",
          },
        ],
      },
      {
        id: "policies",
        label: "Policies & Rules",
        icon: Shield,
        items: [
          {
            label: "Policies",
            value: summaries.policies !== "No policies set yet" ? summaries.policies : null,
            status: summaries.policies !== "No policies set yet" ? "complete" : "missing",
          },
          {
            label: "Guardrails",
            value: summaries.guardrails !== "No limits set yet" ? summaries.guardrails : null,
            status: summaries.guardrails !== "No limits set yet" ? "complete" : "missing",
          },
        ],
      },
      {
        id: "ai-behavior",
        label: "AI Behavior",
        icon: Sparkles,
        items: [
          {
            label: "Greeting",
            value: summaries.scripts !== "Using the default — customize to match your style" ? summaries.scripts : null,
            status: summaries.scripts !== "Using the default — customize to match your style" ? "complete" : "missing",
          },
          {
            label: "Guidelines",
            value: summaries.guidelines !== "No special instructions yet" ? summaries.guidelines : null,
            status: summaries.guidelines !== "No special instructions yet" ? "complete" : "missing",
          },
        ],
      },
      {
        id: "knowledge",
        label: "Knowledge & Training",
        icon: BookOpen,
        items: [
          {
            label: "FAQs",
            value: summaries.faqs !== "No questions added yet — your AI says 'I'm not sure' to unknowns" ? summaries.faqs : null,
            status: capabilities.hasFAQs ? "complete" : "missing",
          },
          {
            label: "Objections",
            value: summaries.objections !== "No responses set — your AI uses generic replies to pushback" ? summaries.objections : null,
            status: capabilities.hasKnowledge ? "complete" : "missing",
          },
        ],
      },
    ];
  }, [tenant, businessMode, hoursDisplay, summaries, capabilities, caps.isFoodBusiness]);

  // Summary stats
  const stats = useMemo(() => {
    let complete = 0;
    let missing = 0;
    let partial = 0;
    
    sections.forEach(section => {
      section.items.forEach(item => {
        if (item.status === "complete") complete++;
        else if (item.status === "missing") missing++;
        else partial++;
      });
    });

    return { complete, missing, partial, total: complete + missing + partial };
  }, [sections]);

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full sm:max-w-md">
        <SheetHeader className="pb-4">
          <div className="flex items-center gap-2">
            <Volume2 className="h-5 w-5 text-primary" />
            <SheetTitle>What Your AI Sees</SheetTitle>
          </div>
          <SheetDescription>
            This is a summary of the information your AI uses to answer calls.
          </SheetDescription>
        </SheetHeader>

        {/* Stats bar */}
        <div className="flex items-center gap-4 mb-4 p-3 rounded-lg bg-muted/50">
          <div className="flex items-center gap-1.5">
            <CheckCircle2 className="h-4 w-4 text-emerald-500" />
            <span className="text-sm">{stats.complete} complete</span>
          </div>
          <div className="flex items-center gap-1.5">
            <AlertCircle className="h-4 w-4 text-amber-500" />
            <span className="text-sm">{stats.missing} missing</span>
          </div>
        </div>

        <ScrollArea className="h-[calc(100vh-220px)]">
          <div className="space-y-4 pr-4">
            {sections.map((section) => {
              const Icon = section.icon;
              const isActive = activeSection === section.id;
              
              return (
                <div
                  key={section.id}
                  className={cn(
                    "rounded-lg border p-3",
                    isActive && "ring-2 ring-primary border-primary"
                  )}
                >
                  <div className="flex items-center gap-2 mb-2">
                    <Icon className="h-4 w-4 text-muted-foreground" />
                    <span className="text-sm font-medium">{section.label}</span>
                    {isActive && (
                      <Badge variant="secondary" className="text-xs ml-auto">
                        Current
                      </Badge>
                    )}
                  </div>
                  <div className="space-y-1.5">
                    {section.items.map((item, idx) => (
                      <div key={idx} className="flex items-start justify-between gap-2">
                        <span className="text-xs text-muted-foreground">{item.label}</span>
                        <div className="flex items-center gap-1.5">
                          {item.status === "complete" ? (
                            <CheckCircle2 className="h-3 w-3 text-emerald-500 shrink-0" />
                          ) : item.status === "missing" ? (
                            <AlertCircle className="h-3 w-3 text-amber-500 shrink-0" />
                          ) : (
                            <Info className="h-3 w-3 text-muted-foreground shrink-0" />
                          )}
                          <span className={cn(
                            "text-xs text-right",
                            item.status === "missing" ? "text-amber-600 dark:text-amber-400 italic" : "text-foreground"
                          )}>
                            {item.value || "Not set"}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </div>
        </ScrollArea>

        <Separator className="my-4" />

        <div className="rounded-lg bg-muted/30 p-3">
          <div className="flex items-start gap-2">
            <Info className="h-4 w-4 text-muted-foreground shrink-0 mt-0.5" />
            <p className="text-xs text-muted-foreground">
              This preview shows a snapshot of your current configuration. 
              Complete all sections for the best AI performance.
            </p>
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

/**
 * Business Brain - Standardized Tab Header
 * 
 * Provides consistent structure for each tab:
 * A) What this controls (1 sentence)
 * B) How the AI uses it (1-2 bullets)
 * C) Common mistakes (mode-aware)
 */

import { ReactNode } from "react";
import { Info, AlertCircle, Lightbulb, Eye } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import type { BusinessMode } from "@/hooks/useTenantConfig";

export interface TabGuidance {
  /** What this tab controls */
  whatItControls: string;
  /** How the AI uses this information */
  howAIUsesIt: string[];
  /** Common mistakes to avoid (can be mode-specific) */
  commonMistakes: string[];
  /** Tips for success */
  tips?: string[];
}

interface BrainTabHeaderProps {
  title: string;
  icon?: ReactNode;
  guidance: TabGuidance;
  businessMode?: BusinessMode;
  onPreviewSection?: () => void;
  className?: string;
}

export function BrainTabHeader({
  title,
  icon,
  guidance,
  businessMode,
  onPreviewSection,
  className,
}: BrainTabHeaderProps) {
  return (
    <div className={cn("mb-6", className)}>
      {/* Title with tooltip */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          {icon}
          <h2 className="text-xl font-semibold">{title}</h2>
          <TooltipProvider>
            <Tooltip>
              <TooltipTrigger asChild>
                <button className="text-muted-foreground hover:text-foreground transition-colors">
                  <Info className="h-4 w-4" />
                </button>
              </TooltipTrigger>
              <TooltipContent side="right" className="max-w-xs">
                <p className="font-medium mb-1">{guidance.whatItControls}</p>
                <ul className="text-xs space-y-1 text-muted-foreground">
                  {guidance.howAIUsesIt.map((item, i) => (
                    <li key={i}>• {item}</li>
                  ))}
                </ul>
              </TooltipContent>
            </Tooltip>
          </TooltipProvider>
        </div>
        {onPreviewSection && (
          <Button
            variant="ghost"
            size="sm"
            onClick={onPreviewSection}
            className="gap-2 text-muted-foreground hover:text-foreground"
          >
            <Eye className="h-4 w-4" />
            <span className="hidden sm:inline">Preview</span>
          </Button>
        )}
      </div>

      {/* What this controls */}
      <p className="text-sm text-muted-foreground mb-4">
        {guidance.whatItControls}
      </p>

      {/* Guidance cards row */}
      <div className="grid gap-3 sm:grid-cols-2">
        {/* How AI uses it */}
        <div className="rounded-lg border bg-primary/5 border-primary/20 p-3">
          <div className="flex items-center gap-2 mb-2">
            <Lightbulb className="h-4 w-4 text-primary" />
            <span className="text-xs font-medium text-primary">How your AI uses this</span>
          </div>
          <ul className="text-xs text-muted-foreground space-y-1">
            {guidance.howAIUsesIt.map((item, i) => (
              <li key={i}>• {item}</li>
            ))}
          </ul>
        </div>

        {/* Common mistakes */}
        {guidance.commonMistakes.length > 0 && (
          <div className="rounded-lg border bg-amber-500/5 border-amber-500/20 p-3">
            <div className="flex items-center gap-2 mb-2">
              <AlertCircle className="h-4 w-4 text-amber-500" />
              <span className="text-xs font-medium text-amber-600 dark:text-amber-400">Avoid these mistakes</span>
            </div>
            <ul className="text-xs text-muted-foreground space-y-1">
              {guidance.commonMistakes.map((item, i) => (
                <li key={i}>• {item}</li>
              ))}
            </ul>
          </div>
        )}
      </div>
    </div>
  );
}

