  const [formData, setFormData] = useState<SpecialFormData>(defaultFormData);
  const [editingFormData, setEditingFormData] = useState<Record<string, SpecialFormData>>({});
  const [savingId, setSavingId] = useState<string | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingSpecial, setDeletingSpecial] = useState<MenuSpecial | null>(null);

  // Fetch specials
  const { data: specials, isLoading } = useQuery({
    queryKey: ["menu-specials", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("menu_specials")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return (data || []) as unknown as MenuSpecial[];
    },
    enabled: !!tenant?.id,
  });

  const handleCreate = async () => {
    if (!tenant?.id || !formData.name.trim()) return;
    
    setSavingId("new");
    try {
      const { error } = await supabase
        .from("menu_specials")
        .insert({
          tenant_id: tenant.id,
          name: formData.name.trim(),
          description: formData.description.trim() || null,
          items: formData.items.filter(i => i.name.trim()),
          schedule_type: formData.schedule_type,
          active_days: formData.schedule_type === "weekly" ? formData.active_days : null,
          start_time: formData.schedule_type === "daily" ? formData.start_time : null,
          end_time: formData.schedule_type === "daily" ? formData.end_time : null,
          start_date: formData.schedule_type === "date_range" ? formData.start_date : null,
          end_date: formData.schedule_type === "date_range" ? formData.end_date : null,
          is_active: true,
        });

      if (error) throw error;
      
      toast.success("Special created");
      queryClient.invalidateQueries({ queryKey: ["menu-specials"] });
      setIsCreating(false);
      setFormData(defaultFormData);
    } catch (error: any) {
      toast.error(error.message || "Failed to create");
    } finally {
      setSavingId(null);
    }
  };

  const handleUpdate = async (specialId: string) => {
    if (!tenant?.id) return;
    const data = editingFormData[specialId];
    if (!data?.name.trim()) return;
    
    setSavingId(specialId);
    try {
      const { error } = await supabase
        .from("menu_specials")
        .update({
          name: data.name.trim(),
          description: data.description.trim() || null,
          items: data.items.filter(i => i.name.trim()),
          schedule_type: data.schedule_type,
          active_days: data.schedule_type === "weekly" ? data.active_days : null,
          start_time: data.schedule_type === "daily" ? data.start_time : null,
          end_time: data.schedule_type === "daily" ? data.end_time : null,
          start_date: data.schedule_type === "date_range" ? data.start_date : null,
          end_date: data.schedule_type === "date_range" ? data.end_date : null,
        })
        .eq("id", specialId)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      
      toast.success("Special updated");
      queryClient.invalidateQueries({ queryKey: ["menu-specials"] });
      setExpandedId(null);
    } catch (error: any) {
      toast.error(error.message || "Failed to update");
    } finally {
      setSavingId(null);
    }
  };

  const handleDelete = async () => {
    if (!tenant?.id || !deletingSpecial) return;
    
    try {
      const { error } = await supabase
        .from("menu_specials")
        .delete()
        .eq("id", deletingSpecial.id)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      
      toast.success("Special removed");
      queryClient.invalidateQueries({ queryKey: ["menu-specials"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    } finally {
      setDeleteDialogOpen(false);
      setDeletingSpecial(null);
    }
  };

  const handleToggleActive = async (special: MenuSpecial) => {
    if (!tenant?.id) return;
    
    try {
      const { error } = await supabase
        .from("menu_specials")
        .update({ is_active: !special.is_active })
        .eq("id", special.id)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      
      toast.success(special.is_active ? "Special hidden" : "Special active");
      queryClient.invalidateQueries({ queryKey: ["menu-specials"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to update");
    }
  };

  const toggleExpanded = (id: string, special: MenuSpecial) => {
    if (expandedId === id) {
      setExpandedId(null);
    } else {
      setExpandedId(id);
      if (!editingFormData[id]) {
        setEditingFormData(prev => ({
          ...prev,
          [id]: {
            name: special.name,
            description: special.description || "",
            items: (special.items as any) || [{ name: "", price_cents: 0 }],
            schedule_type: special.schedule_type,
            active_days: special.active_days || [],
            start_time: special.start_time || "16:00",
            end_time: special.end_time || "18:00",
            start_date: special.start_date || "",
            end_date: special.end_date || "",
          },
        }));
      }
    }
    setIsCreating(false);
  };

  const getScheduleLabel = (special: MenuSpecial) => {
    switch (special.schedule_type) {
      case "always":
        return "Always";
      case "weekly":
        return special.active_days?.map(d => DAYS_OF_WEEK[d]?.label).join(", ") || "Weekly";
      case "daily":
        return `${special.start_time} - ${special.end_time}`;
      case "date_range":
        return `${special.start_date} to ${special.end_date}`;
      default:
        return "";
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="ml-3 text-sm text-muted-foreground">Loading specials...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  // AI Preview
  const activeSpecials = specials?.filter(s => s.is_active) || [];
  const aiPreview = activeSpecials.length > 0
    ? `Today we have our ${activeSpecials[0].name}! ${activeSpecials[0].description || ""}`
    : "I can tell you about any specials we're running.";

  // Form component
  const SpecialForm = ({
    data,
    onChange,
    onSave,
    onCancel,
    isSaving,
  }: {
    data: SpecialFormData;
    onChange: (data: SpecialFormData) => void;
    onSave: () => void;
    onCancel: () => void;
    isSaving: boolean;
  }) => (
    <div className="p-4 space-y-4 border-t bg-muted/20">
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label className="text-xs">Special Name *</Label>
          <Input
            value={data.name}
            onChange={(e) => onChange({ ...data, name: e.target.value })}
            placeholder="e.g., Taco Tuesday, Happy Hour"
          />
        </div>
        <div className="space-y-2">
          <Label className="text-xs">Schedule Type</Label>
          <Select
            value={data.schedule_type}
            onValueChange={(v) => onChange({ ...data, schedule_type: v as any })}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {SCHEDULE_TYPES.map(type => (
                <SelectItem key={type.value} value={type.value}>
                  {type.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      <div className="space-y-2">
        <Label className="text-xs">Description</Label>
        <Textarea
          value={data.description}
          onChange={(e) => onChange({ ...data, description: e.target.value })}
          placeholder="What makes this special great?"
          rows={2}
        />
      </div>

      {/* Schedule-specific fields */}
      {data.schedule_type === "weekly" && (
        <div className="space-y-2">
          <Label className="text-xs">Active Days</Label>
          <div className="flex flex-wrap gap-2">
            {DAYS_OF_WEEK.map(day => (
              <Button
                key={day.value}
                type="button"
                variant={data.active_days.includes(day.value) ? "default" : "outline"}
                size="sm"
                onClick={() => {
                  const newDays = data.active_days.includes(day.value)
                    ? data.active_days.filter(d => d !== day.value)
                    : [...data.active_days, day.value];
                  onChange({ ...data, active_days: newDays.sort() });
                }}
              >
                {day.label}
              </Button>
            ))}
          </div>
        </div>
      )}

      {data.schedule_type === "daily" && (
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label className="text-xs">Start Time</Label>
            <Input
              type="time"
              value={data.start_time}
              onChange={(e) => onChange({ ...data, start_time: e.target.value })}
            />
          </div>
          <div className="space-y-2">
            <Label className="text-xs">End Time</Label>
            <Input
              type="time"
              value={data.end_time}
              onChange={(e) => onChange({ ...data, end_time: e.target.value })}
            />
          </div>
        </div>
      )}

      {data.schedule_type === "date_range" && (
        <div className="grid grid-cols-2 gap-4">
          <div className="space-y-2">
            <Label className="text-xs">Start Date</Label>
            <Input
              type="date"
              value={data.start_date}
              onChange={(e) => onChange({ ...data, start_date: e.target.value })}
            />
          </div>
          <div className="space-y-2">
            <Label className="text-xs">End Date</Label>
            <Input
              type="date"
              value={data.end_date}
              onChange={(e) => onChange({ ...data, end_date: e.target.value })}
            />
          </div>
        </div>
      )}

      {/* Items in special */}
      <div className="space-y-2">
        <Label className="text-xs">Items in This Special</Label>
        {data.items.map((item, i) => (
          <div key={i} className="flex items-center gap-2">
            <Input
              value={item.name}
              onChange={(e) => {
                const newItems = [...data.items];
                newItems[i] = { ...item, name: e.target.value };
                onChange({ ...data, items: newItems });
              }}
              placeholder="Item name"
              className="flex-1"
            />
            <div className="flex items-center gap-1">
              <span className="text-sm text-muted-foreground">$</span>
              <Input
                type="number"
                step="0.01"
                value={(item.price_cents / 100).toFixed(2)}
                onChange={(e) => {
                  const newItems = [...data.items];
                  newItems[i] = { ...item, price_cents: Math.round(parseFloat(e.target.value) * 100) || 0 };
                  onChange({ ...data, items: newItems });
                }}
                className="w-24"
              />
            </div>
            {data.items.length > 1 && (
              <Button
                variant="ghost"
                size="sm"
                onClick={() => {
                  onChange({ ...data, items: data.items.filter((_, idx) => idx !== i) });
                }}
              >
                <X className="h-4 w-4" />
              </Button>
            )}
          </div>
        ))}
        <Button
          variant="outline"
          size="sm"
          onClick={() => onChange({ ...data, items: [...data.items, { name: "", price_cents: 0 }] })}
        >
          <Plus className="h-3 w-3 mr-1" />
          Add Item
        </Button>
      </div>

      <div className="flex justify-end gap-2 pt-2">
        <Button variant="outline" size="sm" onClick={onCancel} disabled={isSaving}>
          Cancel
        </Button>
        <Button size="sm" onClick={onSave} disabled={isSaving || !data.name.trim()}>
          {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : "Save"}
        </Button>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">

      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h4 className="font-medium">Daily Specials & Deals</h4>
          <p className="text-sm text-muted-foreground">
            {specials?.length || 0} specials • {activeSpecials.length} active
          </p>
        </div>
        <Button onClick={() => { setIsCreating(true); setExpandedId(null); }}>
          <Plus className="h-4 w-4 mr-2" />
          Add Special
        </Button>
      </div>

      {/* Create new form */}
      {isCreating && (
        <Card>
          <div className="px-4 py-3 border-b">
            <h4 className="font-medium text-sm">New Special</h4>
          </div>
          <SpecialForm
            data={formData}
            onChange={setFormData}
            onSave={handleCreate}
            onCancel={() => { setIsCreating(false); setFormData(defaultFormData); }}
            isSaving={savingId === "new"}
          />
        </Card>
      )}

      {/* Existing specials */}
      {specials && specials.length > 0 && (
        <div className="space-y-2">
          {specials.map(special => {
            const isExpanded = expandedId === special.id;
            const data = editingFormData[special.id];

            return (
              <Card key={special.id}>
                <Collapsible
                  open={isExpanded}
                  onOpenChange={() => toggleExpanded(special.id, special)}
                >
                  <div className="px-4 py-3 flex items-center justify-between">
                    <CollapsibleTrigger asChild>
                      <button className="flex items-center gap-3 flex-1 text-left">
                        {isExpanded ? (
                          <ChevronDown className="h-4 w-4 text-muted-foreground" />
                        ) : (
                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
                        )}
                        <div>
                          <div className="flex items-center gap-2">
                            <span className="font-medium text-sm">{special.name}</span>
                            {!special.is_active && (
                              <Badge variant="outline" className="text-xs">Hidden</Badge>
                            )}
                          </div>
                          <p className="text-xs text-muted-foreground">
                            {getScheduleLabel(special)}
                          </p>
                        </div>
                      </button>
                    </CollapsibleTrigger>
                    <div className="flex items-center gap-2">
                      <Switch
                        checked={special.is_active}
                        onCheckedChange={() => handleToggleActive(special)}
                      />
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => {
                          setDeletingSpecial(special);
                          setDeleteDialogOpen(true);
                        }}
                      >
                        <Trash2 className="h-4 w-4 text-muted-foreground" />
                      </Button>
                    </div>
                  </div>
                  <CollapsibleContent>
                    {data && (
                      <SpecialForm
                        data={data}
                        onChange={(newData) => setEditingFormData(prev => ({
                          ...prev,
                          [special.id]: newData,
                        }))}
                        onSave={() => handleUpdate(special.id)}
                        onCancel={() => setExpandedId(null)}
                        isSaving={savingId === special.id}
                      />
                    )}
                  </CollapsibleContent>
                </Collapsible>
              </Card>
            );
          })}
        </div>
      )}

      {/* Empty state */}
      {!isCreating && (!specials || specials.length === 0) && (
        <Card>
          <CardContent className="p-8 text-center">
            <Star className="h-8 w-8 mx-auto mb-2 text-muted-foreground" />
            <h4 className="font-medium mb-1">No specials yet</h4>
            <p className="text-sm text-muted-foreground mb-4">
              Create specials like "Taco Tuesday" or "Happy Hour" to attract customers
            </p>
            <Button onClick={() => setIsCreating(true)}>
              <Plus className="h-4 w-4 mr-2" />
              Create Your First Special
            </Button>
          </CardContent>
        </Card>
      )}

      {/* Delete confirmation */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this special?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently remove "{deletingSpecial?.name}".
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDelete}>Remove</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

/**
 * DeliveryZonesEditor - Food mode delivery zones with tiered fees
 * 
 * Manages delivery zones, fees per zone, and peak hour adjustments.
 */
import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Loader2,
  Plus,
  Edit2,
  Trash2,
  MapPin,
  DollarSign,
  Clock,
  Flame,
} from "lucide-react";
import { AIPreviewCard } from "../AIPreviewCard";

interface DeliveryZone {
  id: string;
  tenant_id: string;
  zone_name: string;
  zone_type: "radius" | "zip" | "neighborhood";
  min_miles: number;
  max_miles: number | null;
  zip_codes: string[];
  neighborhood_names: string[];
  delivery_fee_cents: number;
  minimum_order_cents: number;
  estimated_delivery_min_minutes: number;
  estimated_delivery_max_minutes: number;
  peak_fee_cents: number;
  peak_time_adjustment_minutes: number;
  is_active: boolean;
  priority_order: number;
}

interface PeakHour {
  id: string;
  tenant_id: string;
  name: string;
  day_of_week: number;
  start_time: string;
  end_time: string;
  prep_buffer_minutes: number;
  delivery_buffer_minutes: number;
  fee_adjustment_cents: number;
  is_active: boolean;
}

const DAY_NAMES = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

const DEFAULT_ZONE: Omit<DeliveryZone, "id" | "tenant_id"> = {
  zone_name: "",
  zone_type: "radius",
  min_miles: 0,
  max_miles: 5,
  zip_codes: [],
  neighborhood_names: [],
  delivery_fee_cents: 0,
  minimum_order_cents: 0,
  estimated_delivery_min_minutes: 30,
  estimated_delivery_max_minutes: 45,
  peak_fee_cents: 0,
  peak_time_adjustment_minutes: 10,
  is_active: true,
  priority_order: 0,
};

export function DeliveryZonesEditor() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const [zones, setZones] = useState<DeliveryZone[]>([]);
  const [peakHours, setPeakHours] = useState<PeakHour[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  
  const [zoneDialogOpen, setZoneDialogOpen] = useState(false);
  const [editingZone, setEditingZone] = useState<Partial<DeliveryZone> | null>(null);
  const [peakDialogOpen, setPeakDialogOpen] = useState(false);
  const [editingPeak, setEditingPeak] = useState<Partial<PeakHour> | null>(null);

  useEffect(() => {
    if (!tenant?.id) return;
    fetchData();
  }, [tenant?.id]);

  const fetchData = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const [zonesRes, peakRes] = await Promise.all([
        supabase.from("delivery_zones").select("*").eq("tenant_id", tenant.id).order("priority_order"),
        supabase.from("peak_hours").select("*").eq("tenant_id", tenant.id).order("day_of_week"),
      ]);

      if (zonesRes.error) throw zonesRes.error;
      if (peakRes.error) throw peakRes.error;

      setZones((zonesRes.data || []) as DeliveryZone[]);
      setPeakHours((peakRes.data || []) as PeakHour[]);
    } catch (err) {
      console.error("Failed to fetch delivery settings:", err);
      toast({
        title: "Error",
        description: "Failed to load delivery zones",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleSaveZone = async () => {
    if (!tenant?.id || !editingZone) return;
    setIsSaving(true);
    try {
      const zoneData = {
        ...editingZone,
        tenant_id: tenant.id,
      };

      if (editingZone.id) {
        const { error } = await supabase
          .from("delivery_zones")
          .update(zoneData as any)
          .eq("id", editingZone.id);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from("delivery_zones")
          .insert(zoneData as any);
        if (error) throw error;
      }

      await fetchData();
      setZoneDialogOpen(false);
      setEditingZone(null);
      toast({ title: "Saved", description: "Delivery zone updated" });
    } catch (err) {
      console.error("Failed to save zone:", err);
      toast({ title: "Error", description: "Failed to save zone", variant: "destructive" });
    } finally {
      setIsSaving(false);
    }
  };

  const handleDeleteZone = async (id: string) => {
    if (!confirm("Delete this delivery zone?")) return;
    try {
      const { error } = await supabase.from("delivery_zones").delete().eq("id", id);
      if (error) throw error;
      setZones(prev => prev.filter(z => z.id !== id));
      toast({ title: "Deleted", description: "Delivery zone removed" });
    } catch (err) {
      console.error("Failed to delete zone:", err);
      toast({ title: "Error", description: "Failed to delete zone", variant: "destructive" });
    }
  };

  const handleSavePeak = async () => {
    if (!tenant?.id || !editingPeak) return;
    setIsSaving(true);
    try {
      const peakData = {
        ...editingPeak,
        tenant_id: tenant.id,
      };

      if (editingPeak.id) {
        const { error } = await supabase
          .from("peak_hours")
          .update(peakData as any)
          .eq("id", editingPeak.id);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from("peak_hours")
          .insert(peakData as any);
        if (error) throw error;
      }

      await fetchData();
      setPeakDialogOpen(false);
      setEditingPeak(null);
      toast({ title: "Saved", description: "Peak hours updated" });
    } catch (err) {
      console.error("Failed to save peak hours:", err);
      toast({ title: "Error", description: "Failed to save peak hours", variant: "destructive" });
    } finally {
      setIsSaving(false);
    }
  };

  const formatCurrency = (cents: number) => {
    return new Intl.NumberFormat("en-US", {
      style: "currency",
      currency: "USD",
    }).format(cents / 100);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const generateAIPreview = () => {
    if (zones.length === 0) {
      return "Let me check if we deliver to your area.";
    }
    
    const activeZones = zones.filter(z => z.is_active);
    if (activeZones.length === 0) {
      return "I'm sorry, we're not currently offering delivery.";
    }

    const firstZone = activeZones[0];
    const fee = firstZone.delivery_fee_cents > 0 
      ? `There's a ${formatCurrency(firstZone.delivery_fee_cents)} delivery fee` 
      : "Delivery is free";
    const time = `${firstZone.estimated_delivery_min_minutes} to ${firstZone.estimated_delivery_max_minutes} minutes`;
    
    return `${fee} for your area. Estimated delivery time is ${time}.`;
  };

  return (
    <div className="space-y-6">
      {/* Delivery Zones */}
      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-base flex items-center gap-2">
                <MapPin className="h-4 w-4 text-primary" />
                Delivery Zones
              </CardTitle>
              <CardDescription>
                Set different fees and times by distance or area
              </CardDescription>
            </div>
            <Button
              size="sm"
              onClick={() => {
                setEditingZone({ ...DEFAULT_ZONE, priority_order: zones.length });
                setZoneDialogOpen(true);
              }}
            >
              <Plus className="h-4 w-4 mr-1" />
              Add Zone
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {zones.length === 0 ? (
            <div className="text-center py-6 text-muted-foreground">
              <MapPin className="h-8 w-8 mx-auto mb-2 opacity-50" />
              <p className="text-sm">No delivery zones configured</p>
              <p className="text-xs">Add zones to set up tiered delivery fees</p>
            </div>
          ) : (
            <div className="space-y-3">
              {zones.map((zone) => (
                <div
                  key={zone.id}
                  className={`flex items-center justify-between p-3 rounded-lg border ${
                    zone.is_active ? "bg-card" : "bg-muted/50 opacity-60"
                  }`}
                >
                  <div className="flex items-center gap-3">
                    <div>
                      <div className="flex items-center gap-2">
                        <span className="font-medium">{zone.zone_name}</span>
                        {!zone.is_active && <Badge variant="secondary">Inactive</Badge>}
                      </div>
                      <p className="text-xs text-muted-foreground">
                        {zone.zone_type === "radius" && `${zone.min_miles}-${zone.max_miles || "∞"} miles`}
                        {zone.zone_type === "zip" && `${zone.zip_codes.length} ZIP codes`}
                        {zone.zone_type === "neighborhood" && `${zone.neighborhood_names.length} neighborhoods`}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-4">
                    <div className="text-right">
                      <p className="text-sm font-medium">
                        {zone.delivery_fee_cents > 0 ? formatCurrency(zone.delivery_fee_cents) : "Free"}
                      </p>
                      <p className="text-xs text-muted-foreground">
                        {zone.estimated_delivery_min_minutes}-{zone.estimated_delivery_max_minutes} min
                      </p>
                    </div>
                    <div className="flex gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => {
                          setEditingZone(zone);
                          setZoneDialogOpen(true);
                        }}
                      >
                        <Edit2 className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => handleDeleteZone(zone.id)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Peak Hours */}
      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-base flex items-center gap-2">
                <Flame className="h-4 w-4 text-orange-500" />
                Peak Hours
              </CardTitle>
              <CardDescription>
                Adjust timing and fees during busy periods
              </CardDescription>
            </div>
            <Button
              size="sm"
              variant="outline"
              onClick={() => {
                setEditingPeak({
                  name: "",
                  day_of_week: 0,
                  start_time: "12:00",
                  end_time: "14:00",
                  prep_buffer_minutes: 10,
                  delivery_buffer_minutes: 10,
                  fee_adjustment_cents: 0,
                  is_active: true,
                });
                setPeakDialogOpen(true);
              }}
            >
              <Plus className="h-4 w-4 mr-1" />
              Add Peak Period
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {peakHours.length === 0 ? (
            <div className="text-center py-6 text-muted-foreground">
              <Clock className="h-8 w-8 mx-auto mb-2 opacity-50" />
              <p className="text-sm">No peak hours configured</p>
              <p className="text-xs">Add peak periods for lunch/dinner rushes</p>
            </div>
          ) : (
            <div className="grid gap-2 sm:grid-cols-2">
              {peakHours.map((peak) => (
                <div
                  key={peak.id}
                  className={`p-3 rounded-lg border ${
                    peak.is_active ? "bg-card" : "bg-muted/50 opacity-60"
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <div>
                      <span className="font-medium text-sm">{peak.name}</span>
                      <p className="text-xs text-muted-foreground">
                        {DAY_NAMES[peak.day_of_week]} {peak.start_time}-{peak.end_time}
                      </p>
                    </div>
                    <div className="flex gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7"
                        onClick={() => {
                          setEditingPeak(peak);
                          setPeakDialogOpen(true);
                        }}
                      >
                        <Edit2 className="h-3 w-3" />
                      </Button>
                    </div>
                  </div>
                  {peak.fee_adjustment_cents > 0 && (
                    <Badge variant="secondary" className="mt-2 text-xs">
                      +{formatCurrency(peak.fee_adjustment_cents)} surge
                    </Badge>
                  )}
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* AI Preview */}
      <AIPreviewCard 
        title="AI will say something like:" 
        preview={generateAIPreview()} 
      />

      {/* Zone Dialog */}
      <Dialog open={zoneDialogOpen} onOpenChange={setZoneDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{editingZone?.id ? "Edit Zone" : "Add Delivery Zone"}</DialogTitle>
            <DialogDescription>Configure delivery area and pricing</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Zone name</Label>
              <Input
                value={editingZone?.zone_name || ""}
                onChange={(e) => setEditingZone(prev => ({ ...prev, zone_name: e.target.value }))}
                placeholder="e.g., Nearby, Extended, Far"
              />
            </div>

            <div className="space-y-2">
              <Label>Zone type</Label>
              <Select
                value={editingZone?.zone_type || "radius"}
                onValueChange={(v) => setEditingZone(prev => ({ ...prev, zone_type: v as "radius" | "zip" | "neighborhood" }))}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="radius">Distance-based (miles)</SelectItem>
                  <SelectItem value="zip">ZIP codes</SelectItem>
                  <SelectItem value="neighborhood">Neighborhoods</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {editingZone?.zone_type === "radius" && (
              <div className="grid grid-cols-2 gap-3">
                <div className="space-y-2">
                  <Label>Min miles</Label>
                  <Input
                    type="number"
                    min="0"
                    value={editingZone?.min_miles ?? 0}
                    onChange={(e) => setEditingZone(prev => ({ ...prev, min_miles: parseFloat(e.target.value) || 0 }))}
                  />
                </div>
                <div className="space-y-2">
                  <Label>Max miles</Label>
                  <Input
                    type="number"
                    min="0"
                    value={editingZone?.max_miles ?? ""}
                    onChange={(e) => setEditingZone(prev => ({ 
                      ...prev, 
                      max_miles: e.target.value ? parseFloat(e.target.value) : null 
                    }))}
                    placeholder="No limit"
                  />
                </div>
              </div>
            )}

            <Separator />

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label>Delivery fee ($)</Label>
                <Input
                  type="number"
                  min="0"
                  step="0.01"
                  value={(editingZone?.delivery_fee_cents || 0) / 100}
                  onChange={(e) => setEditingZone(prev => ({ 
                    ...prev, 
                    delivery_fee_cents: Math.round(parseFloat(e.target.value || "0") * 100) 
                  }))}
                />
              </div>
              <div className="space-y-2">
                <Label>Minimum order ($)</Label>
                <Input
                  type="number"
                  min="0"
                  step="0.01"
                  value={(editingZone?.minimum_order_cents || 0) / 100}
                  onChange={(e) => setEditingZone(prev => ({ 
                    ...prev, 
                    minimum_order_cents: Math.round(parseFloat(e.target.value || "0") * 100) 
                  }))}
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label>Min delivery time</Label>
                <Input
                  type="number"
                  min="5"
                  value={editingZone?.estimated_delivery_min_minutes ?? 30}
                  onChange={(e) => setEditingZone(prev => ({ 
                    ...prev, 
                    estimated_delivery_min_minutes: parseInt(e.target.value) || 30 
                  }))}
                />
              </div>
              <div className="space-y-2">
                <Label>Max delivery time</Label>
                <Input
                  type="number"
                  min="5"
                  value={editingZone?.estimated_delivery_max_minutes ?? 45}
                  onChange={(e) => setEditingZone(prev => ({ 
                    ...prev, 
                    estimated_delivery_max_minutes: parseInt(e.target.value) || 45 
                  }))}
                />
              </div>
            </div>

            <div className="flex items-center justify-between pt-2">
              <Label>Active</Label>
              <Switch
                checked={editingZone?.is_active ?? true}
                onCheckedChange={(checked) => setEditingZone(prev => ({ ...prev, is_active: checked }))}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setZoneDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSaveZone} disabled={isSaving || !editingZone?.zone_name}>
              {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Save Zone
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Peak Hours Dialog */}
      <Dialog open={peakDialogOpen} onOpenChange={setPeakDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{editingPeak?.id ? "Edit Peak Period" : "Add Peak Period"}</DialogTitle>
            <DialogDescription>Configure busy hour adjustments</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Name</Label>
              <Input
                value={editingPeak?.name || ""}
                onChange={(e) => setEditingPeak(prev => ({ ...prev, name: e.target.value }))}
                placeholder="e.g., Lunch Rush, Dinner Peak"
              />
            </div>

            <div className="space-y-2">
              <Label>Day of week</Label>
              <Select
                value={String(editingPeak?.day_of_week ?? 0)}
                onValueChange={(v) => setEditingPeak(prev => ({ ...prev, day_of_week: parseInt(v) }))}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {DAY_NAMES.map((day, idx) => (
                    <SelectItem key={idx} value={String(idx)}>{day}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label>Start time</Label>
                <Input
                  type="time"
                  value={editingPeak?.start_time || "12:00"}
                  onChange={(e) => setEditingPeak(prev => ({ ...prev, start_time: e.target.value }))}
                />
              </div>
              <div className="space-y-2">
                <Label>End time</Label>
                <Input
                  type="time"
                  value={editingPeak?.end_time || "14:00"}
                  onChange={(e) => setEditingPeak(prev => ({ ...prev, end_time: e.target.value }))}
                />
              </div>
            </div>

            <Separator />

            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-2">
                <Label>Extra prep time (min)</Label>
                <Input
                  type="number"
                  min="0"
                  value={editingPeak?.prep_buffer_minutes ?? 10}
                  onChange={(e) => setEditingPeak(prev => ({ 
                    ...prev, 
                    prep_buffer_minutes: parseInt(e.target.value) || 0 
                  }))}
                />
              </div>
              <div className="space-y-2">
                <Label>Extra delivery time (min)</Label>
                <Input
                  type="number"
                  min="0"
                  value={editingPeak?.delivery_buffer_minutes ?? 10}
                  onChange={(e) => setEditingPeak(prev => ({ 
                    ...prev, 
                    delivery_buffer_minutes: parseInt(e.target.value) || 0 
                  }))}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Surge fee ($)</Label>
              <Input
                type="number"
                min="0"
                step="0.01"
                value={(editingPeak?.fee_adjustment_cents || 0) / 100}
                onChange={(e) => setEditingPeak(prev => ({ 
                  ...prev, 
                  fee_adjustment_cents: Math.round(parseFloat(e.target.value || "0") * 100) 
                }))}
              />
              <p className="text-xs text-muted-foreground">
                Additional fee during this peak period
              </p>
            </div>

            <div className="flex items-center justify-between pt-2">
              <Label>Active</Label>
              <Switch
                checked={editingPeak?.is_active ?? true}
                onCheckedChange={(checked) => setEditingPeak(prev => ({ ...prev, is_active: checked }))}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setPeakDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSavePeak} disabled={isSaving || !editingPeak?.name}>
              {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Save Peak Hours
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

/**
 * Food Policies Editor
 * For restaurants, cafes, catering, food trucks
 * Handles orders, refunds, delivery, allergies, reservations, and catering policies
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, Save, ShoppingCart, Undo2, Truck, AlertTriangle, Users, UtensilsCrossed, Wine } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { AIPreviewCard } from "../AIPreviewCard";

interface FoodPolicies {
  id?: string;
  tenant_id: string;
  // Order modifications
  order_modification_cutoff_minutes: number;
  order_cancellation_allowed: boolean;
  order_cancellation_cutoff_minutes: number;
  order_cancellation_fee_cents: number;
  // Refunds
  wrong_order_refund_policy: string;
  missing_item_policy: string;
  quality_issue_policy: string;
  // Delivery
  delivery_driver_tip_policy: string;
  contactless_delivery_default: boolean;
  delivery_instructions_required: boolean;
  delivery_photo_proof: boolean;
  // Allergies
  allergy_disclaimer: string;
  cross_contamination_warning: string;
  dietary_accommodation_policy: string;
  nutrition_info_available: boolean;
  // Reservations
  reservation_hold_minutes: number;
  reservation_no_show_fee_cents: number;
  reservation_cancellation_hours: number;
  large_party_minimum: number;
  large_party_deposit_cents: number;
  large_party_deposit_policy: string;
  // Catering
  catering_minimum_guests: number;
  catering_deposit_percentage: number;
  catering_cancellation_days: number;
  catering_cancellation_fee_policy: string;
  catering_final_count_hours: number;
  // Venue
  outside_food_allowed: boolean;
  corkage_fee_cents: number;
  cake_cutting_fee_cents: number;
  private_event_minimum_cents: number;
}

const DEFAULT_POLICIES: Omit<FoodPolicies, 'tenant_id'> = {
  order_modification_cutoff_minutes: 5,
  order_cancellation_allowed: true,
  order_cancellation_cutoff_minutes: 10,
  order_cancellation_fee_cents: 0,
  wrong_order_refund_policy: 'full_refund',
  missing_item_policy: 'refund_or_credit',
  quality_issue_policy: '',
  delivery_driver_tip_policy: '',
  contactless_delivery_default: true,
  delivery_instructions_required: false,
  delivery_photo_proof: false,
  allergy_disclaimer: '',
  cross_contamination_warning: '',
  dietary_accommodation_policy: '',
  nutrition_info_available: false,
  reservation_hold_minutes: 15,
  reservation_no_show_fee_cents: 0,
  reservation_cancellation_hours: 4,
  large_party_minimum: 6,
  large_party_deposit_cents: 0,
  large_party_deposit_policy: '',
  catering_minimum_guests: 10,
  catering_deposit_percentage: 50,
  catering_cancellation_days: 7,
  catering_cancellation_fee_policy: '',
  catering_final_count_hours: 48,
  outside_food_allowed: false,
  corkage_fee_cents: 0,
  cake_cutting_fee_cents: 0,
  private_event_minimum_cents: 0,
};

export function FoodPoliciesEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState<FoodPolicies | null>(null);

  useEffect(() => {
    if (tenant?.id) {
      loadPolicies();
    }
  }, [tenant?.id]);

  const loadPolicies = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('food_policies')
        .select('*')
        .eq('tenant_id', tenant.id)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') throw error;
      
      setFormData(data || { ...DEFAULT_POLICIES, tenant_id: tenant.id });
    } catch (err: any) {
      toast.error("Failed to load policies");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id || !formData) return;
    setIsSaving(true);
    try {
      const { error } = await supabase
        .from('food_policies')
        .upsert({
          ...formData,
          tenant_id: tenant.id,
        }, { onConflict: 'tenant_id' });

      if (error) throw error;
      toast.success("Policies saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const updateField = <K extends keyof FoodPolicies>(field: K, value: FoodPolicies[K]) => {
    setFormData(prev => prev ? { ...prev, [field]: value } : null);
  };

  const formatCents = (cents: number) => cents > 0 ? `$${(cents / 100).toFixed(0)}` : 'No fee';

  // Build AI preview
  const buildAIPreview = (): string => {
    if (!formData) return "";
    const parts: string[] = [];
    
    if (formData.order_cancellation_allowed) {
      parts.push(`You can cancel within ${formData.order_cancellation_cutoff_minutes} minutes.`);
    }
    if (formData.reservation_hold_minutes > 0) {
      parts.push(`We hold reservations for ${formData.reservation_hold_minutes} minutes.`);
    }
    if (formData.allergy_disclaimer) {
      parts.push("Please inform us of any allergies.");
    }
    
    return parts.length > 0 ? parts.join(' ') : "No specific food policies configured yet.";
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!formData) return null;

  return (
    <div className="space-y-6">
      {/* AI Preview */}
      <AIPreviewCard 
        title="How AI explains your food policies"
        preview={buildAIPreview()}
      />

      {/* Order Policies */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <ShoppingCart className="h-4 w-4" />
            Order Modifications
          </CardTitle>
          <CardDescription>
            How customers can change or cancel orders
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Modification Cutoff</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.order_modification_cutoff_minutes}
                  onChange={(e) => updateField('order_modification_cutoff_minutes', parseInt(e.target.value || '0'))}
                />
                <span className="flex items-center text-sm text-muted-foreground">min</span>
              </div>
              <p className="text-xs text-muted-foreground">After order, can modify within</p>
            </div>

            <div className="space-y-2">
              <Label>Cancellation Cutoff</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.order_cancellation_cutoff_minutes}
                  onChange={(e) => updateField('order_cancellation_cutoff_minutes', parseInt(e.target.value || '0'))}
                />
                <span className="flex items-center text-sm text-muted-foreground">min</span>
              </div>
              <p className="text-xs text-muted-foreground">After order, can cancel within</p>
            </div>
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Allow Order Cancellation</Label>
              <p className="text-xs text-muted-foreground">Customers can cancel orders</p>
            </div>
            <Switch
              checked={formData.order_cancellation_allowed}
              onCheckedChange={(v) => updateField('order_cancellation_allowed', v)}
            />
          </div>

          {formData.order_cancellation_allowed && (
            <div className="space-y-2">
              <Label>Cancellation Fee</Label>
              <div className="relative w-40">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.order_cancellation_fee_cents / 100}
                  onChange={(e) => updateField('order_cancellation_fee_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                />
              </div>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Refund Policies */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Undo2 className="h-4 w-4" />
            Refunds & Issues
          </CardTitle>
          <CardDescription>
            How to handle order problems
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Wrong Order Policy</Label>
              <Select 
                value={formData.wrong_order_refund_policy} 
                onValueChange={(v) => updateField('wrong_order_refund_policy', v)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="full_refund">Full Refund</SelectItem>
                  <SelectItem value="remake">Remake Order</SelectItem>
