/**
 * Food Service Types Editor
 * 
 * Quick toggle for what order types the restaurant offers.
 * This MUST be configured first before Coverage settings make sense.
 */

import { useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Loader2, Truck, ShoppingBag, Utensils, Users, Info } from "lucide-react";
import { toast } from "sonner";

interface FoodOrderSettings {
  tenant_id: string;
  accepts_pickup: boolean;
  accepts_delivery: boolean;
  accepts_dine_in: boolean;
  accepts_catering: boolean;
}

const SERVICE_TYPES = [
  {
    key: "accepts_dine_in" as const,
    label: "Dine-In",
    description: "Customers eat at your location",
    icon: Utensils,
  },
  {
    key: "accepts_pickup" as const,
    label: "Pickup / Takeout",
    description: "Customers order ahead and pick up",
    icon: ShoppingBag,
  },
  {
    key: "accepts_delivery" as const,
    label: "Delivery",
    description: "You deliver to customers",
    icon: Truck,
    showsCoverage: true,
  },
  {
    key: "accepts_catering" as const,
    label: "Catering & Private Events",
    description: "Large orders for events and parties",
    icon: Users,
    showsCoverage: true,
  },
];

export function FoodServiceTypesEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  const { data: settings, isLoading } = useQuery({
    queryKey: ["food-order-settings", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data, error } = await supabase
        .from("food_order_settings")
        .select("accepts_pickup, accepts_delivery, accepts_dine_in, accepts_catering, tenant_id")
        .eq("tenant_id", tenant.id)
        .maybeSingle();
      if (error && error.code !== "PGRST116") throw error;
      return data as FoodOrderSettings | null;
    },
    enabled: !!tenant?.id,
  });

  const effectiveSettings = useMemo(() => ({
    accepts_dine_in: settings?.accepts_dine_in ?? true,
    accepts_pickup: settings?.accepts_pickup ?? true,
    accepts_delivery: settings?.accepts_delivery ?? false,
    accepts_catering: settings?.accepts_catering ?? false,
  }), [settings]);

  const handleToggle = async (key: keyof typeof effectiveSettings, value: boolean) => {
    if (!tenant?.id) return;

    try {
      const payload = {
        tenant_id: tenant.id,
        ...effectiveSettings,
        [key]: value,
      };

      const { error } = await supabase
        .from("food_order_settings")
        .upsert(payload, { onConflict: "tenant_id" });

      if (error) throw error;

      toast.success(`${value ? "Enabled" : "Disabled"} ${SERVICE_TYPES.find(s => s.key === key)?.label}`);
      queryClient.invalidateQueries({ queryKey: ["food-order-settings"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to update");
    }
  };

  const needsCoverage = effectiveSettings.accepts_delivery || effectiveSettings.accepts_catering;

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-6">
        <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="rounded-lg border bg-muted/30 p-4">
        <div className="flex items-start gap-3">
          <Info className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div className="space-y-1">
            <p className="text-sm font-medium">How does your business serve customers?</p>
            <p className="text-sm text-muted-foreground">
              Toggle on the service types you offer. Enabling <strong>Delivery</strong> or <strong>Catering</strong> will 
              unlock coverage area settings so your AI knows where you can serve.
            </p>
          </div>
        </div>
      </div>

      <Card>
        <CardContent className="p-4 space-y-3">
          {SERVICE_TYPES.map(({ key, label, description, icon: Icon, showsCoverage }) => (
            <div 
              key={key} 
              className="flex items-center justify-between p-3 rounded-lg border hover:bg-muted/50 transition-colors"
            >
              <div className="flex items-center gap-3">
                <Icon className="h-5 w-5 text-muted-foreground" />
                <div>
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-medium">{label}</p>
                    {showsCoverage && effectiveSettings[key] && (
                      <Badge variant="secondary" className="text-xs">
                        Coverage Settings Available
                      </Badge>
                    )}
                  </div>
                  <p className="text-xs text-muted-foreground">{description}</p>
                </div>
              </div>
              <Switch
                checked={effectiveSettings[key]}
                onCheckedChange={(v) => handleToggle(key, v)}
              />
            </div>
          ))}
        </CardContent>
      </Card>

      {needsCoverage && (
        <div className="rounded-lg border border-primary/20 bg-primary/5 p-4">
          <p className="text-sm text-primary">
            <strong>Next step:</strong> Go to the <strong>Coverage & ETA</strong> tab to configure where you deliver or cater.
          </p>
        </div>
      )}
    </div>
  );
}

/**
 * Food Settings Editor
 * 
 * Comprehensive settings for food businesses:
 * - Delivery settings (fees, radius, minimums)
 * - Pickup settings (wait times, instructions)
 * - Order limits and restrictions
 * - Kitchen hours (if different from business hours)
 * - Peak time handling
 * - Tip suggestions
 */

import { useState, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import {
  Loader2,
  Info,
  Lightbulb,
  Truck,
  ShoppingBag,
  Clock,
  DollarSign,
  Users,
  MapPin,
  Utensils,
  Plus,
  X,
} from "lucide-react";
import { toast } from "sonner";

interface FoodOrderSettings {
  tenant_id: string;
  accepts_pickup: boolean;
  accepts_delivery: boolean;
  accepts_dine_in: boolean;
  delivery_radius_miles: number | null;
  delivery_minimum_cents: number | null;
  delivery_fee_cents: number | null;
  delivery_fee_type: "flat" | "distance" | "order_value" | null;
  delivery_fee_config: Record<string, any> | null;
  estimated_prep_minutes: number | null;
  peak_time_buffer_minutes: number | null;
  tip_suggestions: number[] | null;
  allows_special_instructions: boolean;
  max_order_items: number | null;
  accepts_catering: boolean;
  catering_min_guests: number | null;
  catering_lead_days: number | null;
  menu_notes: string | null;
  order_confirmation_mode: string | null;
}

const defaultSettings: Partial<FoodOrderSettings> = {
  accepts_pickup: true,
  accepts_delivery: false,
  accepts_dine_in: true,
  delivery_radius_miles: 5,
  delivery_minimum_cents: 1500,
  delivery_fee_cents: 500,
  delivery_fee_type: "flat",
  estimated_prep_minutes: 20,
  peak_time_buffer_minutes: 10,
  tip_suggestions: [15, 18, 20, 25],
  allows_special_instructions: true,
  max_order_items: null,
  accepts_catering: false,
  catering_min_guests: 10,
  catering_lead_days: 3,
};

export function FoodSettingsEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  
  const [activeTab, setActiveTab] = useState("ordering");
  const [isSaving, setIsSaving] = useState(false);
  const [localSettings, setLocalSettings] = useState<Partial<FoodOrderSettings>>({});
  const [taxRatePercent, setTaxRatePercent] = useState<number>(0);
  const [taxRateChanged, setTaxRateChanged] = useState(false);

  // Fetch settings
  const { data: settings, isLoading } = useQuery({
    queryKey: ["food-order-settings", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data, error } = await supabase
        .from("food_order_settings")
        .select("*")
        .eq("tenant_id", tenant.id)
        .single();
      if (error && error.code !== "PGRST116") throw error;
      return data as FoodOrderSettings | null;
    },
    enabled: !!tenant?.id,
  });

  // Load tax rate from tenant context_fields_json
  useQuery({
    queryKey: ["tenant-tax-rate", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data } = await supabase
        .from("tenants")
        .select("context_fields_json")
        .eq("id", tenant.id)
        .single();
      const ctx = (data as any)?.context_fields_json;
      if (ctx?.tax_rate_percent != null) {
        setTaxRatePercent(ctx.tax_rate_percent);
      }
      return ctx;
    },
    enabled: !!tenant?.id,
  });

  // Merge fetched with local edits
  const effectiveSettings = useMemo(() => ({
    ...defaultSettings,
    ...settings,
    ...localSettings,
  }), [settings, localSettings]);

  const updateSetting = <K extends keyof FoodOrderSettings>(key: K, value: FoodOrderSettings[K]) => {
    setLocalSettings(prev => ({ ...prev, [key]: value }));
  };

  const handleSave = async () => {
    if (!tenant?.id) return;
    
    setIsSaving(true);
    try {
      const payload = {
        tenant_id: tenant.id,
        ...effectiveSettings,
      };

      const { error } = await supabase
        .from("food_order_settings")
        .upsert(payload, { onConflict: "tenant_id" });

      if (error) throw error;

      // Save tax rate to tenant context_fields_json
      if (taxRateChanged) {
        const { data: currentTenant } = await supabase
          .from("tenants")
          .select("context_fields_json")
          .eq("id", tenant.id)
          .single();
        const existingCtx = (currentTenant as any)?.context_fields_json || {};
        await supabase
          .from("tenants")
          .update({ context_fields_json: { ...existingCtx, tax_rate_percent: taxRatePercent } })
          .eq("id", tenant.id);
        setTaxRateChanged(false);
      }

      toast.success("Settings saved");
      queryClient.invalidateQueries({ queryKey: ["food-order-settings"] });
      queryClient.invalidateQueries({ queryKey: ["tenant-tax-rate"] });
      setLocalSettings({});
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const hasChanges = Object.keys(localSettings).length > 0 || taxRateChanged;

  // AI Preview
  const aiPreview = useMemo(() => {
    const parts: string[] = [];
    
    if (effectiveSettings.accepts_pickup && effectiveSettings.accepts_delivery) {
      parts.push("We offer both pickup and delivery");
    } else if (effectiveSettings.accepts_pickup) {
      parts.push("We're pickup only");
    } else if (effectiveSettings.accepts_delivery) {
      parts.push("We offer delivery");
    }
    
    if (effectiveSettings.accepts_delivery && effectiveSettings.delivery_minimum_cents) {
      parts.push(`with a $${(effectiveSettings.delivery_minimum_cents / 100).toFixed(0)} minimum`);
    }
    
    if (effectiveSettings.estimated_prep_minutes) {
      parts.push(`Orders take about ${effectiveSettings.estimated_prep_minutes} minutes to prepare`);
    }
    
    return parts.length > 0 
      ? parts.join(". ") + "."
      : "I can help you place an order for pickup or delivery.";
  }, [effectiveSettings]);

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="ml-3 text-sm text-muted-foreground">Loading settings...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Explanation */}
      <div className="rounded-lg border bg-muted/30 p-4">
        <div className="flex items-start gap-3">
          <Info className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div className="space-y-2">
            <p className="text-sm font-medium">What is this?</p>
            <p className="text-sm text-muted-foreground">
              Configure how customers can order from you. Set up <strong>delivery fees</strong>,
              <strong>pickup options</strong>, <strong>prep times</strong>, and <strong>catering requirements</strong>.
              Your AI uses these to tell customers exactly how ordering works.
            </p>
          </div>
        </div>
      </div>

      {/* AI Preview */}
      <div className="rounded-lg border bg-primary/5 border-primary/20 p-4">
        <div className="flex items-start gap-3">
          <Utensils className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div>
            <p className="text-sm font-medium text-primary mb-1">What the AI tells customers</p>
            <p className="text-sm italic">"{aiPreview}"</p>
          </div>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid grid-cols-4 h-auto">
          <TabsTrigger value="ordering" className="text-xs py-2">
            <ShoppingBag className="h-3.5 w-3.5 mr-1" />
            Ordering
          </TabsTrigger>
          <TabsTrigger value="delivery" className="text-xs py-2">
            <Truck className="h-3.5 w-3.5 mr-1" />
            Delivery
          </TabsTrigger>
          <TabsTrigger value="timing" className="text-xs py-2">
            <Clock className="h-3.5 w-3.5 mr-1" />
            Timing
          </TabsTrigger>
          <TabsTrigger value="catering" className="text-xs py-2">
            <Users className="h-3.5 w-3.5 mr-1" />
            Catering
          </TabsTrigger>
        </TabsList>

        {/* Ordering Options */}
        <TabsContent value="ordering" className="mt-4 space-y-4">
          <Card>
            <CardContent className="p-4 space-y-4">
              <h4 className="font-medium">Order Types</h4>
              
              <div className="space-y-3">
                <div className="flex items-center justify-between p-3 rounded-lg border">
                  <div className="flex items-center gap-3">
                    <ShoppingBag className="h-5 w-5 text-muted-foreground" />
                    <div>
                      <p className="text-sm font-medium">Pickup Orders</p>
                      <p className="text-xs text-muted-foreground">Customers order ahead and pick up</p>
                    </div>
                  </div>
                  <Switch
                    checked={effectiveSettings.accepts_pickup}
                    onCheckedChange={(v) => updateSetting("accepts_pickup", v)}
                  />
                </div>

                <div className="flex items-center justify-between p-3 rounded-lg border">
                  <div className="flex items-center gap-3">
                    <Truck className="h-5 w-5 text-muted-foreground" />
                    <div>
                      <p className="text-sm font-medium">Delivery Orders</p>
                      <p className="text-xs text-muted-foreground">You deliver to customers</p>
                    </div>
                  </div>
                  <Switch
                    checked={effectiveSettings.accepts_delivery}
                    onCheckedChange={(v) => updateSetting("accepts_delivery", v)}
                  />
                </div>

                <div className="flex items-center justify-between p-3 rounded-lg border">
                  <div className="flex items-center gap-3">
                    <Utensils className="h-5 w-5 text-muted-foreground" />
                    <div>
                      <p className="text-sm font-medium">Dine-In</p>
                      <p className="text-xs text-muted-foreground">Customers eat at your location</p>
                    </div>
                  </div>
                  <Switch
                    checked={effectiveSettings.accepts_dine_in}
                    onCheckedChange={(v) => updateSetting("accepts_dine_in", v)}
                  />
                </div>
              </div>

              <div className="pt-4 border-t space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <Label className="text-sm">Allow Special Instructions</Label>
                    <p className="text-xs text-muted-foreground">Let customers add notes to items</p>
                  </div>
                  <Switch
                    checked={effectiveSettings.allows_special_instructions}
                    onCheckedChange={(v) => updateSetting("allows_special_instructions", v)}
                  />
                </div>

                <div className="space-y-2">
                  <Label className="text-sm">Max Items Per Order</Label>
                  <Input
                    type="number"
                    min="1"
                    placeholder="No limit"
                    value={effectiveSettings.max_order_items || ""}
                    onChange={(e) => updateSetting("max_order_items", e.target.value ? parseInt(e.target.value) : null)}
                    className="w-32"
                  />
                  <p className="text-xs text-muted-foreground">Leave empty for no limit</p>
                </div>

                <div className="space-y-2">
                  <Label className="text-sm flex items-center gap-2">
                    <DollarSign className="h-4 w-4" />
                    Sales Tax Rate
                  </Label>
                  <div className="flex items-center gap-2">
                    <Input
                      type="number"
                      min="0"
                      max="20"
                      step="0.125"
                      value={taxRatePercent}
                      onChange={(e) => {
                        setTaxRatePercent(parseFloat(e.target.value) || 0);
                        setTaxRateChanged(true);
                      }}
                      className="w-24"
                    />
                    <span className="text-sm text-muted-foreground">%</span>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Applied to all food orders. The AI will include tax when quoting order totals.
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Delivery Settings */}
        <TabsContent value="delivery" className="mt-4 space-y-4">
          <Card>
            <CardContent className="p-4 space-y-4">
              <h4 className="font-medium">Delivery Configuration</h4>

              {!effectiveSettings.accepts_delivery ? (
                <div className="text-center py-8 text-muted-foreground">
                  <Truck className="h-8 w-8 mx-auto mb-2 opacity-50" />
                  <p className="text-sm">Enable delivery in the Ordering tab to configure these settings</p>
                </div>
              ) : (
                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label className="text-sm">Delivery Radius</Label>
                      <div className="flex items-center gap-2">
                        <Input
                          type="number"
                          min="1"
                          max="50"
                          value={effectiveSettings.delivery_radius_miles || ""}
                          onChange={(e) => updateSetting("delivery_radius_miles", parseInt(e.target.value) || null)}
                          className="w-20"
                        />
                        <span className="text-sm text-muted-foreground">miles</span>
                      </div>
                    </div>

                    <div className="space-y-2">
                      <Label className="text-sm">Minimum Order</Label>
                      <div className="flex items-center gap-2">
                        <span className="text-sm text-muted-foreground">$</span>
                        <Input
                          type="number"
                          min="0"
                          step="5"
                          value={(effectiveSettings.delivery_minimum_cents || 0) / 100}
                          onChange={(e) => updateSetting("delivery_minimum_cents", Math.round(parseFloat(e.target.value) * 100) || null)}
                          className="w-24"
                        />
                      </div>
                    </div>
                  </div>

                  <div className="space-y-2">
                    <Label className="text-sm">Delivery Fee Type</Label>
                    <Select
                      value={effectiveSettings.delivery_fee_type || "flat"}
                      onValueChange={(v) => updateSetting("delivery_fee_type", v as any)}
                    >
                      <SelectTrigger className="w-48">
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="flat">Flat Fee</SelectItem>
                        <SelectItem value="distance">Based on Distance</SelectItem>
                        <SelectItem value="order_value">Based on Order Value</SelectItem>
                      </SelectContent>
                    </Select>
                  </div>

                  {effectiveSettings.delivery_fee_type === "flat" && (
                    <div className="space-y-2">
                      <Label className="text-sm">Delivery Fee</Label>
                      <div className="flex items-center gap-2">
                        <span className="text-sm text-muted-foreground">$</span>
                        <Input
                          type="number"
                          min="0"
                          step="0.50"
                          value={(effectiveSettings.delivery_fee_cents || 0) / 100}
                          onChange={(e) => updateSetting("delivery_fee_cents", Math.round(parseFloat(e.target.value) * 100) || null)}
                          className="w-24"
                        />
                      </div>
                    </div>
                  )}

                  <div className="flex items-start gap-2 p-3 rounded-lg bg-warning/10 border border-warning/20">
                    <Lightbulb className="h-4 w-4 text-warning shrink-0 mt-0.5" />
                    <p className="text-xs text-muted-foreground">
                      Customers within your delivery radius can order delivery.
                      The AI will explain your minimum order and delivery fees.
                    </p>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Timing Settings */}
        <TabsContent value="timing" className="mt-4 space-y-4">
          <Card>
            <CardContent className="p-4 space-y-4">
              <h4 className="font-medium">Preparation & Wait Times</h4>

              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label className="text-sm">Estimated Prep Time</Label>
                  <div className="flex items-center gap-2">
                    <Input
                      type="number"
                      min="5"
                      max="120"
                      step="5"
                      value={effectiveSettings.estimated_prep_minutes || ""}
                      onChange={(e) => updateSetting("estimated_prep_minutes", parseInt(e.target.value) || null)}
                      className="w-20"
                    />
                    <span className="text-sm text-muted-foreground">minutes</span>
                  </div>
                  <p className="text-xs text-muted-foreground">Average time to prepare an order</p>
                </div>

                <div className="space-y-2">
                  <Label className="text-sm">Peak Time Buffer</Label>
                  <div className="flex items-center gap-2">
                    <span className="text-sm text-muted-foreground">+</span>
                    <Input
                      type="number"
                      min="0"
                      max="60"
                      step="5"
                      value={effectiveSettings.peak_time_buffer_minutes || ""}
                      onChange={(e) => updateSetting("peak_time_buffer_minutes", parseInt(e.target.value) || null)}
                      className="w-20"
                    />
                    <span className="text-sm text-muted-foreground">minutes</span>
                  </div>
                  <p className="text-xs text-muted-foreground">Extra time during busy periods</p>
                </div>
              </div>

              <div className="pt-4 border-t space-y-2">
                <Label className="text-sm">Tip Suggestions</Label>
                <div className="flex flex-wrap gap-2">
                  {(effectiveSettings.tip_suggestions || []).map((tip, i) => (
                    <Badge key={i} variant="secondary" className="gap-1 pr-1">
                      {tip}%
                      <button
                        onClick={() => {
                          const newTips = [...(effectiveSettings.tip_suggestions || [])];
                          newTips.splice(i, 1);
                          updateSetting("tip_suggestions", newTips);
                        }}
                        className="ml-1 hover:text-destructive"
                      >
                        <X className="h-3 w-3" />
                      </button>
                    </Badge>
                  ))}
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => {
                      const newTip = prompt("Enter tip percentage (e.g., 20):");
                      if (newTip && !isNaN(parseInt(newTip))) {
                        updateSetting("tip_suggestions", [
                          ...(effectiveSettings.tip_suggestions || []),
                          parseInt(newTip)
                        ].sort((a, b) => a - b));
                      }
                    }}
                  >
                    <Plus className="h-3 w-3 mr-1" />
                    Add
                  </Button>
                </div>
                <p className="text-xs text-muted-foreground">
                  Suggested tip percentages shown to customers
                </p>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Catering Settings */}
        <TabsContent value="catering" className="mt-4 space-y-4">
          <Card>
            <CardContent className="p-4 space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="font-medium">Catering Services</h4>
                  <p className="text-sm text-muted-foreground">Accept large orders for events and groups</p>
                </div>
                <Switch
                  checked={effectiveSettings.accepts_catering}
                  onCheckedChange={(v) => updateSetting("accepts_catering", v)}
                />
              </div>

              {effectiveSettings.accepts_catering && (
                <div className="space-y-4 pt-4 border-t">
                  <div className="grid grid-cols-2 gap-4">
                    <div className="space-y-2">
                      <Label className="text-sm">Minimum Guests</Label>
                      <Input
                        type="number"
                        min="1"
                        value={effectiveSettings.catering_min_guests || ""}
                        onChange={(e) => updateSetting("catering_min_guests", parseInt(e.target.value) || null)}
                        className="w-24"
                      />
                      <p className="text-xs text-muted-foreground">Smallest group you'll cater</p>
                    </div>

                    <div className="space-y-2">
                      <Label className="text-sm">Advance Notice Required</Label>
                      <div className="flex items-center gap-2">
                        <Input
                          type="number"
                          min="1"
                          max="30"
                          value={effectiveSettings.catering_lead_days || ""}
                          onChange={(e) => updateSetting("catering_lead_days", parseInt(e.target.value) || null)}
                          className="w-20"
                        />
                        <span className="text-sm text-muted-foreground">days</span>
                      </div>
                      <p className="text-xs text-muted-foreground">How far ahead to book</p>
                    </div>
                  </div>

                  <div className="flex items-start gap-2 p-3 rounded-lg bg-warning/10 border border-warning/20">
                    <Lightbulb className="h-4 w-4 text-warning shrink-0 mt-0.5" />
                    <p className="text-xs text-muted-foreground">
                      The AI will collect catering inquiries with guest count, event date,
                      and menu preferences, then pass them to you for a custom quote.
                    </p>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Save button */}
      {hasChanges && (
        <div className="flex justify-end sticky bottom-4">
          <Button onClick={handleSave} disabled={isSaving}>
            {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
            Save Changes
          </Button>
        </div>
      )}
    </div>
  );
}

/**
 * Menu Sizes Editor
 * 
 * Manage size variants for menu items:
 * - Small, Medium, Large
 * - Personal, Family, Party size
 * - Custom sizes per item
 */

import { useState, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  Plus,
  Trash2,
  Loader2,
  Info,
  Lightbulb,
  ChevronDown,
  ChevronRight,
  Scale,
} from "lucide-react";
import { toast } from "sonner";

interface MenuItemSize {
  id: string;
  menu_item_id: string;
  tenant_id: string;
  name: string;
  price_cents: number;
  is_default: boolean;
  display_order: number;
  is_active: boolean;
}

interface MenuItem {
  id: string;
  name: string;
  category: string | null;
  price_cents: number | null;
}

const COMMON_SIZE_TEMPLATES = [
  { name: "Small", priceMultiplier: 0.8 },
  { name: "Medium", priceMultiplier: 1.0 },
  { name: "Large", priceMultiplier: 1.3 },
];

const ALT_SIZE_TEMPLATES = [
  { name: "Personal", priceMultiplier: 1.0 },
  { name: "Sharing", priceMultiplier: 1.8 },
  { name: "Family", priceMultiplier: 2.5 },
];

export function MenuSizesEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  const [expandedItemId, setExpandedItemId] = useState<string | null>(null);
  const [savingId, setSavingId] = useState<string | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deletingSize, setDeletingSize] = useState<MenuItemSize | null>(null);

  // Fetch menu items
  const { data: menuItems, isLoading: loadingItems } = useQuery({
    queryKey: ["menu-items", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("menu_items")
        .select("id, name, category, price_cents")
        .eq("tenant_id", tenant.id)
        .order("category")
        .order("name");
      if (error) throw error;
      return data as MenuItem[];
    },
    enabled: !!tenant?.id,
  });

  // Fetch sizes
  const { data: allSizes, isLoading: loadingSizes } = useQuery({
    queryKey: ["menu-item-sizes", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("menu_item_sizes")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("display_order");
      if (error) throw error;
      return data as MenuItemSize[];
    },
    enabled: !!tenant?.id,
  });

  // Group sizes by menu item
  const sizesByItem = useMemo(() => {
    const grouped: Record<string, MenuItemSize[]> = {};
    allSizes?.forEach(size => {
      if (!grouped[size.menu_item_id]) grouped[size.menu_item_id] = [];
      grouped[size.menu_item_id].push(size);
    });
    return grouped;
  }, [allSizes]);

  // Items with sizes
  const itemsWithSizes = useMemo(() => {
    return menuItems?.filter(item => sizesByItem[item.id]?.length > 0) || [];
  }, [menuItems, sizesByItem]);

  // Items without sizes
  const itemsWithoutSizes = useMemo(() => {
    return menuItems?.filter(item => !sizesByItem[item.id]?.length) || [];
  }, [menuItems, sizesByItem]);

  const handleAddSizes = async (itemId: string, template: typeof COMMON_SIZE_TEMPLATES) => {
    if (!tenant?.id) return;
    
    const item = menuItems?.find(i => i.id === itemId);
    if (!item) return;
    
    const basePrice = item.price_cents || 1000;
    
    setSavingId(itemId);
    try {
      const sizes = template.map((t, i) => ({
        tenant_id: tenant.id,
        menu_item_id: itemId,
        name: t.name,
        price_cents: Math.round(basePrice * t.priceMultiplier),
        is_default: t.priceMultiplier === 1.0,
        display_order: i,
        is_active: true,
      }));

      const { error } = await supabase
        .from("menu_item_sizes")
        .insert(sizes);

      if (error) throw error;
      
      toast.success("Sizes added");
      queryClient.invalidateQueries({ queryKey: ["menu-item-sizes"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to add sizes");
    } finally {
      setSavingId(null);
    }
  };

  const handleUpdateSize = async (sizeId: string, updates: Partial<MenuItemSize>) => {
    if (!tenant?.id) return;
    
    setSavingId(sizeId);
    try {
      const { error } = await supabase
        .from("menu_item_sizes")
        .update(updates)
        .eq("id", sizeId)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      
      toast.success("Size updated");
      queryClient.invalidateQueries({ queryKey: ["menu-item-sizes"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to update");
    } finally {
      setSavingId(null);
    }
  };

  const handleDeleteSize = async () => {
    if (!tenant?.id || !deletingSize) return;
    
    try {
      const { error } = await supabase
        .from("menu_item_sizes")
        .delete()
        .eq("id", deletingSize.id)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      
      toast.success("Size removed");
      queryClient.invalidateQueries({ queryKey: ["menu-item-sizes"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    } finally {
      setDeleteDialogOpen(false);
      setDeletingSize(null);
    }
  };

  const handleRemoveAllSizes = async (itemId: string) => {
    if (!tenant?.id) return;
    
    setSavingId(itemId);
    try {
      const { error } = await supabase
        .from("menu_item_sizes")
        .delete()
        .eq("menu_item_id", itemId)
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      
      toast.success("Sizes removed");
      queryClient.invalidateQueries({ queryKey: ["menu-item-sizes"] });
    } catch (error: any) {
      toast.error(error.message || "Failed to remove sizes");
    } finally {
      setSavingId(null);
    }
  };

  const isLoading = loadingItems || loadingSizes;

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="ml-3 text-sm text-muted-foreground">Loading sizes...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  // AI Preview
  const aiPreview = itemsWithSizes.length > 0
    ? `We have ${itemsWithSizes[0].name} in ${sizesByItem[itemsWithSizes[0].id]?.map(s => s.name).join(", ")}. Which size would you like?`
    : "I can tell you about our menu items and sizes.";

  return (
    <div className="space-y-6">
      {/* Explanation */}
      <div className="rounded-lg border bg-muted/30 p-4">
        <div className="flex items-start gap-3">
          <Info className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div className="space-y-2">
            <p className="text-sm font-medium">What is this?</p>
            <p className="text-sm text-muted-foreground">
              Add size options to menu items. When a customer orders, 
              the AI will ask which size they want and quote the correct price.
            </p>
          </div>
        </div>
      </div>

      {/* AI Preview */}
      {itemsWithSizes.length > 0 && (
        <div className="rounded-lg border bg-primary/5 border-primary/20 p-4">
          <div className="flex items-start gap-3">
            <Scale className="h-5 w-5 text-primary shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-medium text-primary mb-1">What the AI asks</p>
              <p className="text-sm italic">"{aiPreview}"</p>
            </div>
          </div>
        </div>
      )}

      {/* Items with sizes */}
      {itemsWithSizes.length > 0 && (
        <div className="space-y-2">
          <h4 className="font-medium">Items with Sizes ({itemsWithSizes.length})</h4>
          
          {itemsWithSizes.map(item => {
            const sizes = sizesByItem[item.id] || [];
            const isExpanded = expandedItemId === item.id;

            return (
              <Collapsible
                key={item.id}
                open={isExpanded}
                onOpenChange={() => setExpandedItemId(isExpanded ? null : item.id)}
              >
                <Card>
                  <CollapsibleTrigger asChild>
                    <button className="w-full px-4 py-3 flex items-center justify-between hover:bg-muted/50">
                      <div className="flex items-center gap-3">
                        {isExpanded ? (
                          <ChevronDown className="h-4 w-4 text-muted-foreground" />
                        ) : (
                          <ChevronRight className="h-4 w-4 text-muted-foreground" />
                        )}
                        <span className="font-medium text-sm">{item.name}</span>
                        <div className="flex gap-1">
                          {sizes.map(s => (
                            <Badge key={s.id} variant="secondary" className="text-xs">
                              {s.name}: ${(s.price_cents / 100).toFixed(2)}
                            </Badge>
                          ))}
                        </div>
                      </div>
                    </button>
                  </CollapsibleTrigger>
                  <CollapsibleContent>
                    <div className="px-4 pb-4 space-y-3 border-t pt-3">
                      {sizes.map(size => (
                        <div key={size.id} className="flex items-center gap-3">
                          <Input
                            value={size.name}
                            onChange={(e) => handleUpdateSize(size.id, { name: e.target.value })}
                            className="w-32"
                            placeholder="Size name"
                          />
                          <div className="flex items-center gap-1">
                            <span className="text-sm text-muted-foreground">$</span>
                            <Input
                              type="number"
                              step="0.01"
                              value={(size.price_cents / 100).toFixed(2)}
                              onChange={(e) => handleUpdateSize(size.id, { 
                                price_cents: Math.round(parseFloat(e.target.value) * 100) 
                              })}
                              className="w-24"
                            />
                          </div>
                          <div className="flex items-center gap-2">
                            <Label className="text-xs text-muted-foreground">Default</Label>
                            <Switch
                              checked={size.is_default}
                              onCheckedChange={(v) => handleUpdateSize(size.id, { is_default: v })}
                            />
                          </div>
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() => {
                              setDeletingSize(size);
                              setDeleteDialogOpen(true);
                            }}
                          >
                            <Trash2 className="h-4 w-4 text-muted-foreground" />
                          </Button>
                        </div>
                      ))}
                      <div className="pt-2 flex justify-end">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => handleRemoveAllSizes(item.id)}
                          disabled={savingId === item.id}
                        >
                          Remove All Sizes
                        </Button>
                      </div>
                    </div>
                  </CollapsibleContent>
                </Card>
              </Collapsible>
            );
          })}
        </div>
      )}

      {/* Items without sizes */}
      {itemsWithoutSizes.length > 0 && (
        <div className="space-y-2">
          <h4 className="font-medium">Add Sizes to Items</h4>
          <p className="text-sm text-muted-foreground mb-3">
            Select items that should have size options
          </p>

          <div className="grid gap-2">
            {itemsWithoutSizes.slice(0, 10).map(item => (
              <Card key={item.id}>
                <CardContent className="p-3 flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium">{item.name}</p>
                    <p className="text-xs text-muted-foreground">
                      {item.category} • ${((item.price_cents || 0) / 100).toFixed(2)}
                    </p>
                  </div>
                  <div className="flex gap-2">
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleAddSizes(item.id, COMMON_SIZE_TEMPLATES)}
                      disabled={savingId === item.id}
                    >
                      {savingId === item.id ? (
                        <Loader2 className="h-3 w-3 animate-spin" />
                      ) : (
                        "S / M / L"
                      )}
                    </Button>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={() => handleAddSizes(item.id, ALT_SIZE_TEMPLATES)}
                      disabled={savingId === item.id}
                    >
                      Personal / Family
                    </Button>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>

          {itemsWithoutSizes.length > 10 && (
            <p className="text-xs text-muted-foreground text-center pt-2">
              + {itemsWithoutSizes.length - 10} more items
            </p>
          )}
        </div>
      )}

      {/* Empty state */}
      {menuItems?.length === 0 && (
        <Card>
          <CardContent className="p-8 text-center">
            <Scale className="h-8 w-8 mx-auto mb-2 text-muted-foreground" />
            <p className="text-sm text-muted-foreground">
              Add menu items first, then you can add size options to them.
            </p>
          </CardContent>
        </Card>
      )}

      {/* Delete confirmation */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Remove this size?</AlertDialogTitle>
            <AlertDialogDescription>
              This will remove the "{deletingSize?.name}" size option.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleDeleteSize}>Remove</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

/**
 * General Policies Editor
 * For general businesses or as fallback for all modes
 * Handles contact, privacy, terms, and accessibility policies
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, Save, Phone, Lock, FileText, Cloud, Accessibility, Globe } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { AIPreviewCard } from "../AIPreviewCard";
import { Badge } from "@/components/ui/badge";

interface GeneralPolicies {
  id?: string;
  tenant_id: string;
  // Contact
  response_time_hours: number;
  preferred_contact_method: string;
  callback_availability: string;
  // Privacy
  privacy_policy_url: string;
  data_retention_policy: string;
  marketing_opt_in_default: boolean;
  // Terms
  terms_of_service_url: string;
  dispute_resolution_policy: string;
  // Seasonal
  holiday_policy: string;
  weather_cancellation_policy: string;
  force_majeure_text: string;
  // Accessibility
  ada_accommodations_text: string;
  language_support: string[];
}

const DEFAULT_POLICIES: Omit<GeneralPolicies, 'tenant_id'> = {
  response_time_hours: 24,
  preferred_contact_method: 'phone',
  callback_availability: '',
  privacy_policy_url: '',
  data_retention_policy: '',
  marketing_opt_in_default: false,
  terms_of_service_url: '',
  dispute_resolution_policy: '',
  holiday_policy: '',
  weather_cancellation_policy: '',
  force_majeure_text: '',
  ada_accommodations_text: '',
  language_support: ['english'],
};

const LANGUAGE_OPTIONS = [
  { id: 'english', label: 'English' },
  { id: 'spanish', label: 'Spanish' },
  { id: 'french', label: 'French' },
  { id: 'mandarin', label: 'Mandarin' },
  { id: 'vietnamese', label: 'Vietnamese' },
  { id: 'korean', label: 'Korean' },
  { id: 'tagalog', label: 'Tagalog' },
  { id: 'german', label: 'German' },
  { id: 'arabic', label: 'Arabic' },
  { id: 'portuguese', label: 'Portuguese' },
];

export function GeneralPoliciesEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState<GeneralPolicies | null>(null);

  useEffect(() => {
    if (tenant?.id) {
      loadPolicies();
    }
  }, [tenant?.id]);

  const loadPolicies = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('general_policies')
        .select('*')
        .eq('tenant_id', tenant.id)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') throw error;
      
      setFormData(data || { ...DEFAULT_POLICIES, tenant_id: tenant.id });
    } catch (err: any) {
      toast.error("Failed to load policies");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id || !formData) return;
    setIsSaving(true);
    try {
      const { error } = await supabase
        .from('general_policies')
        .upsert({
          ...formData,
          tenant_id: tenant.id,
        }, { onConflict: 'tenant_id' });

      if (error) throw error;
      toast.success("Policies saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const updateField = <K extends keyof GeneralPolicies>(field: K, value: GeneralPolicies[K]) => {
    setFormData(prev => prev ? { ...prev, [field]: value } : null);
  };

  const toggleLanguage = (lang: string) => {
    const current = formData?.language_support || [];
    if (current.includes(lang)) {
      updateField('language_support', current.filter(l => l !== lang));
    } else {
      updateField('language_support', [...current, lang]);
    }
  };

  // Build AI preview
  const buildAIPreview = (): string => {
    if (!formData) return "";
    const parts: string[] = [];
    
    if (formData.response_time_hours > 0) {
      parts.push(`We typically respond within ${formData.response_time_hours} hours.`);
    }
    if (formData.language_support.length > 1) {
      parts.push(`We can help in ${formData.language_support.join(', ')}.`);
    }
    
    return parts.length > 0 ? parts.join(' ') : "No specific general policies configured yet.";
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!formData) return null;

  return (
    <div className="space-y-6">
      {/* AI Preview */}
      <AIPreviewCard 
        title="How AI explains your general policies"
        preview={buildAIPreview()}
      />

      {/* Contact Policies */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Phone className="h-4 w-4" />
            Contact & Response
          </CardTitle>
          <CardDescription>
            How and when you respond to inquiries
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Typical Response Time</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.response_time_hours}
                  onChange={(e) => updateField('response_time_hours', parseInt(e.target.value || '0'))}
                />
                <span className="flex items-center text-sm text-muted-foreground">hours</span>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Preferred Contact Method</Label>
              <select
                className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm"
                value={formData.preferred_contact_method}
                onChange={(e) => updateField('preferred_contact_method', e.target.value)}
              >
                <option value="phone">Phone</option>
                <option value="email">Email</option>
                <option value="text">Text/SMS</option>
                <option value="any">Any Method</option>
              </select>
            </div>
          </div>

          <div className="space-y-2">
            <Label>Callback Availability</Label>
            <Textarea
              value={formData.callback_availability}
              onChange={(e) => updateField('callback_availability', e.target.value)}
              placeholder="We return calls Monday-Friday, 9am-5pm. Messages left after hours will be returned the next business day."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Privacy & Data */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Lock className="h-4 w-4" />
            Privacy & Data
          </CardTitle>
          <CardDescription>
            Data handling and privacy policies
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Privacy Policy URL</Label>
            <Input
              type="url"
              value={formData.privacy_policy_url}
              onChange={(e) => updateField('privacy_policy_url', e.target.value)}
              placeholder="https://yoursite.com/privacy"
            />
          </div>

          <div className="space-y-2">
            <Label>Data Retention Policy (for AI to explain)</Label>
            <Textarea
              value={formData.data_retention_policy}
              onChange={(e) => updateField('data_retention_policy', e.target.value)}
              placeholder="We keep your information secure and never sell it to third parties. Call recordings are stored for 90 days for quality purposes."
              rows={2}
            />
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Marketing Opt-In Default</Label>
              <p className="text-xs text-muted-foreground">New contacts opted in by default</p>
            </div>
            <Switch
              checked={formData.marketing_opt_in_default}
              onCheckedChange={(v) => updateField('marketing_opt_in_default', v)}
            />
          </div>
        </CardContent>
      </Card>

      {/* Terms & Disputes */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <FileText className="h-4 w-4" />
            Terms & Disputes
          </CardTitle>
          <CardDescription>
            Terms of service and dispute resolution
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Terms of Service URL</Label>
            <Input
              type="url"
              value={formData.terms_of_service_url}
              onChange={(e) => updateField('terms_of_service_url', e.target.value)}
              placeholder="https://yoursite.com/terms"
            />
          </div>

          <div className="space-y-2">
            <Label>Dispute Resolution Policy</Label>
            <Textarea
              value={formData.dispute_resolution_policy}
              onChange={(e) => updateField('dispute_resolution_policy', e.target.value)}
              placeholder="If you're not satisfied, please contact us first. We want to make things right before any formal dispute process."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Seasonal & Weather */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Cloud className="h-4 w-4" />
            Seasonal & Weather
          </CardTitle>
          <CardDescription>
            Holiday hours and weather-related policies
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Holiday Policy</Label>
            <Textarea
              value={formData.holiday_policy}
              onChange={(e) => updateField('holiday_policy', e.target.value)}
              placeholder="We're closed on major holidays. Check our website or call for holiday hours."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Weather Cancellation Policy</Label>
            <Textarea
              value={formData.weather_cancellation_policy}
              onChange={(e) => updateField('weather_cancellation_policy', e.target.value)}
              placeholder="In severe weather, we may reschedule for safety. We'll contact you as soon as possible if this happens."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Force Majeure / Circumstances Beyond Control</Label>
            <Textarea
              value={formData.force_majeure_text}
              onChange={(e) => updateField('force_majeure_text', e.target.value)}
              placeholder="We're not responsible for delays caused by natural disasters, pandemics, or other circumstances beyond our control."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Accessibility */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Accessibility className="h-4 w-4" />
            Accessibility & Languages
          </CardTitle>
          <CardDescription>
            ADA accommodations and language support
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>ADA Accommodations</Label>
            <Textarea
              value={formData.ada_accommodations_text}
              onChange={(e) => updateField('ada_accommodations_text', e.target.value)}
              placeholder="We're committed to accessibility. Let us know if you need any accommodations and we'll do our best to help."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label className="flex items-center gap-2">
              <Globe className="h-4 w-4" />
              Languages Supported
            </Label>
            <div className="flex flex-wrap gap-2">
              {LANGUAGE_OPTIONS.map((lang) => (
                <Badge
                  key={lang.id}
                  variant={formData.language_support.includes(lang.id) ? "default" : "outline"}
                  className="cursor-pointer"
                  onClick={() => toggleLanguage(lang.id)}
                >
                  {lang.label}
                </Badge>
              ))}
            </div>
            <p className="text-xs text-muted-foreground">Click to toggle. AI will mention available languages when relevant.</p>
          </div>
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end pt-2">
        <Button onClick={handleSave} disabled={isSaving}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save General Policies
        </Button>
      </div>
    </div>
  );
}

/**
 * ResponseTimeEditor - General mode response time and callback settings
 * 
 * Manages callback targets, urgency tiers, and priority zones.
 */
import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Loader2,
  Save,
  Phone,
  Mail,
  Zap,
  Clock,
  MapPin,
  X,
  Plus,
} from "lucide-react";
import { AIPreviewCard } from "../AIPreviewCard";

interface ResponseTimeSettings {
  tenant_id: string;
  callback_target_minutes: number;
  callback_max_minutes: number;
  email_target_hours: number;
  email_max_hours: number;
  urgent_callback_minutes: number;
  urgent_surcharge_cents: number;
  after_hours_callback_mode: "next_day" | "within_hours" | "emergency_only";
  after_hours_target_minutes: number | null;
  priority_zip_codes: string[];
  priority_response_minutes: number;
}

const DEFAULT_SETTINGS: Omit<ResponseTimeSettings, "tenant_id"> = {
  callback_target_minutes: 60,
  callback_max_minutes: 240,
  email_target_hours: 24,
  email_max_hours: 48,
  urgent_callback_minutes: 15,
  urgent_surcharge_cents: 0,
  after_hours_callback_mode: "next_day",
  after_hours_target_minutes: null,
  priority_zip_codes: [],
  priority_response_minutes: 30,
};

export function ResponseTimeEditor() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const [settings, setSettings] = useState<ResponseTimeSettings | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);
  const [newZip, setNewZip] = useState("");

  useEffect(() => {
    if (!tenant?.id) return;
    fetchSettings();
  }, [tenant?.id]);

  const fetchSettings = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from("response_time_settings")
        .select("*")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setSettings({
          ...data,
          priority_zip_codes: (data.priority_zip_codes as string[]) || [],
        } as ResponseTimeSettings);
      } else {
        setSettings({ ...DEFAULT_SETTINGS, tenant_id: tenant.id });
      }
    } catch (err) {
      console.error("Failed to fetch response time settings:", err);
      toast({ title: "Error", description: "Failed to load response settings", variant: "destructive" });
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id || !settings) return;
    setIsSaving(true);
    try {
      const { error } = await supabase
        .from("response_time_settings")
        .upsert({ ...settings, tenant_id: tenant.id }, { onConflict: "tenant_id" });

      if (error) throw error;
      toast({ title: "Saved", description: "Response settings updated" });
      setHasChanges(false);
    } catch (err) {
      console.error("Failed to save response time settings:", err);
      toast({ title: "Error", description: "Failed to save response settings", variant: "destructive" });
    } finally {
      setIsSaving(false);
    }
  };

  const updateSettings = (updates: Partial<ResponseTimeSettings>) => {
    setSettings(prev => prev ? { ...prev, ...updates } : null);
    setHasChanges(true);
  };

  const addPriorityZip = () => {
    if (!newZip || !settings) return;
    const trimmed = newZip.trim();
    if (/^\d{5}$/.test(trimmed) && !settings.priority_zip_codes.includes(trimmed)) {
      updateSettings({ priority_zip_codes: [...settings.priority_zip_codes, trimmed] });
    }
    setNewZip("");
  };

  const removePriorityZip = (zip: string) => {
    if (!settings) return;
    updateSettings({ priority_zip_codes: settings.priority_zip_codes.filter(z => z !== zip) });
  };

  const formatTime = (minutes: number) => {
    if (minutes < 60) return `${minutes} minutes`;
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (mins === 0) return hours === 1 ? "1 hour" : `${hours} hours`;
    return `${hours}h ${mins}m`;
  };

  if (isLoading || !settings) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const generateAIPreview = () => {
    const target = settings.callback_target_minutes;
    const max = settings.callback_max_minutes;
    
    let response = `We typically respond within ${formatTime(target)}`;
    if (settings.urgent_callback_minutes < target) {
      response += `. For urgent matters, we can often call back within ${formatTime(settings.urgent_callback_minutes)}`;
    }
    return response + ".";
  };

  return (
    <div className="space-y-6">
      {/* Callback Response Times */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Phone className="h-4 w-4 text-blue-500" />
            Callback Response Times
          </CardTitle>
          <CardDescription>
            How quickly you aim to return calls
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label>Target response time</Label>
              <Select
                value={String(settings.callback_target_minutes)}
                onValueChange={(v) => updateSettings({ callback_target_minutes: parseInt(v) })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="15">15 minutes</SelectItem>
                  <SelectItem value="30">30 minutes</SelectItem>
                  <SelectItem value="60">1 hour</SelectItem>
                  <SelectItem value="120">2 hours</SelectItem>
                  <SelectItem value="240">4 hours</SelectItem>
                  <SelectItem value="480">Same day</SelectItem>
                </SelectContent>
              </Select>
              <p className="text-xs text-muted-foreground">
                Goal for most callbacks
              </p>
            </div>

            <div className="space-y-2">
              <Label>Maximum response time</Label>
              <Select
                value={String(settings.callback_max_minutes)}
                onValueChange={(v) => updateSettings({ callback_max_minutes: parseInt(v) })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="60">1 hour</SelectItem>
                  <SelectItem value="120">2 hours</SelectItem>
                  <SelectItem value="240">4 hours</SelectItem>
                  <SelectItem value="480">Same day</SelectItem>
                  <SelectItem value="1440">24 hours</SelectItem>
                </SelectContent>
              </Select>
              <p className="text-xs text-muted-foreground">
                Worst-case scenario
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Urgent Requests */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Zap className="h-4 w-4 text-amber-500" />
            Urgent Requests
          </CardTitle>
          <CardDescription>
            Faster response for time-sensitive matters
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label>Urgent callback target</Label>
              <Select
                value={String(settings.urgent_callback_minutes)}
                onValueChange={(v) => updateSettings({ urgent_callback_minutes: parseInt(v) })}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="5">5 minutes</SelectItem>
                  <SelectItem value="10">10 minutes</SelectItem>
                  <SelectItem value="15">15 minutes</SelectItem>
                  <SelectItem value="30">30 minutes</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Urgent fee ($)</Label>
              <Input
                type="number"
                min="0"
                step="0.01"
                value={settings.urgent_surcharge_cents / 100}
                onChange={(e) => updateSettings({ 
                  urgent_surcharge_cents: Math.round(parseFloat(e.target.value || "0") * 100) 
                })}
              />
              <p className="text-xs text-muted-foreground">
                Extra charge for priority callbacks (0 = free)
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* After-Hours Behavior */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Clock className="h-4 w-4 text-purple-500" />
            After-Hours Behavior
          </CardTitle>
          <CardDescription>
            How callbacks work outside business hours
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>After-hours callback mode</Label>
            <Select
              value={settings.after_hours_callback_mode}
              onValueChange={(v) => updateSettings({ 
                after_hours_callback_mode: v as ResponseTimeSettings["after_hours_callback_mode"]
              })}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="next_day">Next business day</SelectItem>
                <SelectItem value="within_hours">Within specified time</SelectItem>
                <SelectItem value="emergency_only">Emergency only</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {settings.after_hours_callback_mode === "within_hours" && (
            <div className="space-y-2">
              <Label>After-hours target (minutes)</Label>
              <Input
                type="number"
                min="15"
                value={settings.after_hours_target_minutes ?? ""}
                onChange={(e) => updateSettings({ 
                  after_hours_target_minutes: e.target.value ? parseInt(e.target.value) : null 
                })}
                placeholder="e.g., 120"
                className="w-32"
              />
            </div>
          )}
        </CardContent>
      </Card>

      {/* Priority Zones */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <MapPin className="h-4 w-4 text-green-500" />
            Priority Zones
          </CardTitle>
          <CardDescription>
            Faster response for specific areas
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Priority ZIP codes</Label>
            <p className="text-xs text-muted-foreground">
              Callers from these ZIPs get faster callbacks
            </p>
            <div className="flex flex-wrap gap-2 mb-2">
              {settings.priority_zip_codes.map((zip) => (
                <Badge key={zip} variant="secondary" className="gap-1 pr-1">
                  {zip}
                  <button
                    type="button"
                    onClick={() => removePriorityZip(zip)}
                    className="ml-1 hover:bg-white/20 rounded-full p-0.5"
                  >
                    <X className="h-3 w-3" />
                  </button>
                </Badge>
              ))}
            </div>
            <div className="flex gap-2">
              <Input
                value={newZip}
                onChange={(e) => setNewZip(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && (e.preventDefault(), addPriorityZip())}
                placeholder="Enter ZIP code"
                maxLength={5}
                className="w-32"
              />
              <Button type="button" variant="outline" size="icon" onClick={addPriorityZip}>
                <Plus className="h-4 w-4" />
              </Button>
            </div>
          </div>

          {settings.priority_zip_codes.length > 0 && (
            <div className="space-y-2">
              <Label>Priority response time</Label>
              <Select
                value={String(settings.priority_response_minutes)}
                onValueChange={(v) => updateSettings({ priority_response_minutes: parseInt(v) })}
              >
                <SelectTrigger className="w-48">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="15">15 minutes</SelectItem>
                  <SelectItem value="30">30 minutes</SelectItem>
                  <SelectItem value="45">45 minutes</SelectItem>
                  <SelectItem value="60">1 hour</SelectItem>
                </SelectContent>
              </Select>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Email Response (optional) */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Mail className="h-4 w-4 text-slate-500" />
            Email Response
          </CardTitle>
          <CardDescription>
            Response time for email inquiries
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid gap-4 sm:grid-cols-2">
            <div className="space-y-2">
              <Label>Target (hours)</Label>
              <Input
                type="number"
                min="1"
                value={settings.email_target_hours}
                onChange={(e) => updateSettings({ 
                  email_target_hours: parseInt(e.target.value) || 24 
                })}
                className="w-24"
              />
            </div>
            <div className="space-y-2">
              <Label>Maximum (hours)</Label>
              <Input
                type="number"
                min="1"
                value={settings.email_max_hours}
                onChange={(e) => updateSettings({ 
                  email_max_hours: parseInt(e.target.value) || 48 
                })}
                className="w-24"
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* AI Preview */}
      <AIPreviewCard 
        title="AI will say something like:" 
        preview={generateAIPreview()} 
      />

      {/* Save Button */}
      <div className="flex justify-end">
        <Button onClick={handleSave} disabled={isSaving || !hasChanges}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Settings
        </Button>
      </div>
    </div>
  );
}

/**
 * Required Questions Guidance Component
 * Provides UX guidance and recommended defaults by business mode
 */

import { useState } from "react";
import { MessageSquare, Copy, Check, ChevronDown, ChevronUp, Lightbulb, AlertTriangle, Eye } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import type { BusinessMode } from "@/hooks/useTenantConfig";

interface RequiredQuestionsGuidanceProps {
  businessMode: BusinessMode;
  requiredCount?: number;
}

interface RecommendedDefault {
  question: string;
}

const RECOMMENDED_DEFAULTS: Record<BusinessMode, RecommendedDefault[]> = {
  dispatch: [
    { question: "Exact pickup address (street + city + ZIP, or highway + mile marker)" },
    { question: "Service needed: tow, jump start, lockout, tire change, or fuel delivery" },
    { question: "Vehicle year, make, model (e.g., '2019 Honda Civic')" },
    { question: "Vehicle color (so driver can identify you)" },
    { question: "Is the vehicle drivable? (yes/no — determines equipment needed)" },
    { question: "Where should we take it? (home, shop, or our lot)" },
    { question: "Are you with the vehicle right now?" },
    { question: "Your name and callback number" },
  ],
  food: [
    { question: "Pickup or delivery" },
    { question: "Delivery address (if delivery)" },
    { question: "Order items + quantities" },
    { question: "Requested time (ASAP or scheduled)" },
    { question: "Name + callback number" },
  ],
  service: [
    { question: "Service requested" },
    { question: "Address/ZIP (if mobile)" },
    { question: "Preferred day/time" },
    { question: "Name + callback number" },
    { question: "Any special notes (pets, access, etc.)" },
  ],
  medical: [
    { question: "Reason for appointment" },
    { question: "Patient name + date of birth" },
    { question: "Preferred day/time" },
    { question: "Callback number" },
    { question: "Insurance provider (if applicable)" },
  ],
  general: [
    { question: "What you need help with" },
    { question: "Name + callback number" },
    { question: "Best time to reach you" },
  ],
  sales: [
    { question: "What product or service are you interested in" },
    { question: "Your budget range" },
    { question: "Name + callback number" },
    { question: "Preferred time for a viewing or consultation" },
  ],
};

const MODE_LABELS: Record<BusinessMode, string> = {
  dispatch: "Dispatch / Towing",
  food: "Restaurant / Food",
  service: "Service Business",
  medical: "Medical Practice",
  general: "General Business",
  sales: "Sales Business",
};

export function RequiredQuestionsGuidance({
  businessMode,
  requiredCount = 0,
}: RequiredQuestionsGuidanceProps) {
  const [defaultsOpen, setDefaultsOpen] = useState(false);
  const [copied, setCopied] = useState<number | null>(null);

  const defaults = RECOMMENDED_DEFAULTS[businessMode] || RECOMMENDED_DEFAULTS.general;

  const handleCopy = (question: string, index: number) => {
    navigator.clipboard.writeText(question);
    setCopied(index);
    setTimeout(() => setCopied(null), 2000);
  };

  return (
    <Card className="border-border/50 bg-card/50 mb-6">
      <CardContent className="p-4 space-y-4">
        {/* Header */}
        <div className="flex items-start gap-3">
          <MessageSquare className="h-4 w-4 text-primary mt-0.5" />
          <div className="flex-1">
            <h4 className="font-medium text-sm">What your AI must ask every time</h4>
            <p className="text-xs text-muted-foreground mt-0.5">
              These are mandatory intake questions the AI must collect before confirming a booking/order/dispatch.
            </p>
          </div>
        </div>

        {/* How AI uses it */}
        <div className="rounded-lg bg-primary/5 border border-primary/20 p-3">
          <div className="flex items-center gap-2 mb-2">
            <Lightbulb className="h-3.5 w-3.5 text-primary" />
            <span className="text-xs font-medium text-primary">How your AI uses this</span>
          </div>
          <ul className="text-xs text-muted-foreground space-y-1">
            <li>• If any required answer is missing, the AI will keep asking until it has it (or it will take a callback request).</li>
            <li>• These questions prevent incomplete tickets.</li>
            <li>• Write questions exactly how you want them asked.</li>
            {businessMode === "dispatch" && (
              <li>• Towing dispatches need exact location, vehicle info, and service type to dispatch the right equipment.</li>
            )}
            {businessMode === "medical" && (
              <li>• Medical practices should collect patient name, DOB, and insurance upfront for verification.</li>
            )}
            {businessMode === "food" && (
              <li>• Food orders need at minimum: items, pickup/delivery preference, and contact info.</li>
            )}
            {businessMode === "service" && (
              <li>• Service appointments need the job type, preferred time, and property address (if mobile).</li>
            )}
          </ul>
        </div>

        {/* Recommended defaults */}
        <Collapsible open={defaultsOpen} onOpenChange={setDefaultsOpen}>
          <CollapsibleTrigger asChild>
            <Button variant="ghost" size="sm" className="w-full justify-between h-8 px-2">
              <span className="flex items-center gap-2 text-xs">
                <Eye className="h-3.5 w-3.5" />
                Recommended defaults for {MODE_LABELS[businessMode]}
              </span>
              {defaultsOpen ? (
                <ChevronUp className="h-3.5 w-3.5" />
              ) : (
                <ChevronDown className="h-3.5 w-3.5" />
              )}
            </Button>
          </CollapsibleTrigger>
          <CollapsibleContent className="pt-2">
            <div className="space-y-2 rounded-lg border bg-muted/30 p-3">
              {defaults.map((item, i) => (
                <div key={i} className="flex items-center justify-between gap-2">
                  <p className="text-xs flex-1">{item.question}</p>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-6 px-2 shrink-0"
                    onClick={() => handleCopy(item.question, i)}
                  >
                    {copied === i ? (
                      <Check className="h-3 w-3 text-primary" />
                    ) : (
                      <Copy className="h-3 w-3" />
                    )}
                  </Button>
                </div>
              ))}
              <p className="text-[10px] text-muted-foreground/70 pt-2 border-t">
                Click copy to use a question — add it below to make it required.
              </p>
            </div>
          </CollapsibleContent>
        </Collapsible>

        {/* Avoid list */}
        <div className="rounded-lg bg-amber-500/5 border border-amber-500/20 p-3">
          <div className="flex items-center gap-2 mb-2">
            <AlertTriangle className="h-3.5 w-3.5 text-amber-500" />
            <span className="text-xs font-medium text-amber-600 dark:text-amber-400">Avoid these</span>
          </div>
          <ul className="text-xs text-muted-foreground space-y-1">
            <li>• Asking for too many things at once (one answer per question)</li>
            <li>• Vague questions like "Tell me about yourself"</li>
            <li>• Questions the AI can't verify (e.g., "Are you 18+")</li>
          </ul>
        </div>

        {/* Preview snippet */}
        <div className="rounded-lg border bg-muted/30 p-3">
          <div className="flex items-center gap-2 mb-2">
            <Eye className="h-3.5 w-3.5 text-muted-foreground" />
            <span className="text-xs font-medium text-muted-foreground">Preview: What the AI will say</span>
          </div>
          <p className="text-xs italic">
            {requiredCount > 0
              ? `"The AI will not confirm until it has answers to ${requiredCount} required question${requiredCount === 1 ? "" : "s"}."`
              : '"The AI will use best-practice intake questions and ask for missing details naturally."'}
          </p>
        </div>
      </CardContent>
    </Card>
  );
}

/**
 * GuidedSetupFlow - Step-by-step guided setup inside Business Brain
 *
 * Replaces the overwhelming 95+ editor Brain dashboard with a linear,
 * one-section-at-a-time wizard for new users. Driven by P0/P1 flags
 * from useAIReadinessV2. Each step renders an EXISTING editor component
 * via BrainEditorRenderer, wrapped in guided context.
 *
 * "Switch to full Brain" link always available for power users.
 */

import { useState, useMemo, useCallback, useEffect } from "react";
import { useNavigate, useSearchParams } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import {
  ArrowLeft, ArrowRight, Check, CheckCircle2, SkipForward,
  LayoutGrid, PartyPopper, Rocket,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { useFoodMode } from "@/hooks/useFoodMode";
import { useAIReadinessV2 } from "@/hooks/useAIReadinessV2";
import { BrainEditorRenderer } from "@/components/brain/layout/BrainEditorRenderer";
import {
  getGuidedSetupSteps,
  computeStepProgress,
  type GuidedSetupStep,
} from "@/config/guidedSetupSteps";

interface GuidedSetupFlowProps {
  onSwitchToFullBrain: () => void;
}

export function GuidedSetupFlow({ onSwitchToFullBrain }: GuidedSetupFlowProps) {
  const navigate = useNavigate();
  const [searchParams, setSearchParams] = useSearchParams();
  const { businessMode } = useTenantConfig();
  const caps = useCapabilities();
  const { isFoodMode } = useFoodMode();
  const isDispatchMode = caps.isDispatchBusiness;
  const { score, p0Flags, p1Flags, canGoLive, refetch } = useAIReadinessV2();

  // Get all steps for this mode
  const allSteps = useMemo(
    () => getGuidedSetupSteps(businessMode),
    [businessMode],
  );

  // Compute which steps are complete based on active flags
  const allFlags = useMemo(() => [...p0Flags, ...p1Flags], [p0Flags, p1Flags]);
  const flagSet = useMemo(() => new Set(allFlags), [allFlags]);

  const stepsWithStatus = useMemo(() => {
    return allSteps.map((step) => {
      const isComplete = step.resolvesFlagKeys.length === 0
        ? false // Optional steps with no flags default to "not complete" (skippable)
        : step.resolvesFlagKeys.every((fk) => !flagSet.has(fk));
      return { ...step, isComplete };
    });
  }, [allSteps, flagSet]);

  const progress = useMemo(
    () => computeStepProgress(businessMode, allFlags),
    [businessMode, allFlags],
  );

  // Current step index
  const stepParam = searchParams.get("step");
  const [currentStepIndex, setCurrentStepIndex] = useState<number>(() => {
    if (stepParam) {
      const idx = stepsWithStatus.findIndex((s) => s.id === stepParam);
      if (idx >= 0) return idx;
    }
    // Default to first incomplete step
    const firstIncomplete = stepsWithStatus.findIndex((s) => !s.isComplete);
    return firstIncomplete >= 0 ? firstIncomplete : 0;
  });

  // Update URL when step changes
  useEffect(() => {
    const step = stepsWithStatus[currentStepIndex];
    if (step) {
      setSearchParams({ mode: "setup", step: step.id }, { replace: true });
    }
  }, [currentStepIndex, stepsWithStatus, setSearchParams]);

  const currentStep = stepsWithStatus[currentStepIndex];
  const isLastStep = currentStepIndex === stepsWithStatus.length - 1;
  const isFirstStep = currentStepIndex === 0;

  // Navigation
  const goNext = useCallback(() => {
    // Refetch readiness after moving forward (user likely saved something)
    refetch();
    if (isLastStep) return;
    setCurrentStepIndex((i) => Math.min(i + 1, stepsWithStatus.length - 1));
  }, [isLastStep, stepsWithStatus.length, refetch]);

  const goPrev = useCallback(() => {
    if (isFirstStep) return;
    setCurrentStepIndex((i) => Math.max(i - 1, 0));
  }, [isFirstStep]);

  const goToStep = useCallback((index: number) => {
    setCurrentStepIndex(index);
  }, []);

  // Check if setup is complete (all required steps done)
  const allRequiredDone = canGoLive || progress.completedSteps === progress.totalSteps;

  if (!currentStep) return null;

  // ─── Celebration view ────────────────────────────────────────────────────
  if (allRequiredDone) {
    return (
      <div className="max-w-2xl mx-auto py-12 px-4">
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.4 }}
          className="text-center space-y-6"
        >
          <div className="inline-flex items-center justify-center h-20 w-20 rounded-full bg-emerald-100 dark:bg-emerald-900/30 mx-auto">
            <PartyPopper className="h-10 w-10 text-emerald-600" />
          </div>

          <div className="space-y-2">
            <h1 className="text-3xl font-bold">You're ready to go live!</h1>
            <p className="text-muted-foreground text-lg">
              Your AI has everything it needs to start answering calls. You can always come back to fine-tune things later.
            </p>
          </div>

          <div className="flex items-center justify-center gap-2 text-sm">
            <CheckCircle2 className="h-4 w-4 text-emerald-600" />
            <span className="text-muted-foreground">
              AI Readiness: <strong className="text-foreground">{score}%</strong>
            </span>
          </div>

          <div className="flex flex-col sm:flex-row items-center justify-center gap-3 pt-4">
            <Button
              size="lg"
              className="gap-2"
              onClick={() => navigate("/app/dashboard")}
            >
              <Rocket className="h-5 w-5" />
              Go to Dashboard
            </Button>
            <Button
              variant="outline"
              size="lg"
              className="gap-2"
              onClick={onSwitchToFullBrain}
            >
              <LayoutGrid className="h-5 w-5" />
              Fine-tune in Full Brain
            </Button>
          </div>
        </motion.div>
      </div>
    );
  }

  // ─── Guided flow view ────────────────────────────────────────────────────

  const progressPercent = progress.totalSteps > 0
    ? Math.round((progress.completedSteps / progress.totalSteps) * 100)
    : 0;

  return (
    <div className="max-w-4xl mx-auto py-6 px-4 space-y-6">
      {/* ── Header with progress ── */}
      <div className="space-y-4">
        <div className="flex items-center justify-between">
          <div className="space-y-1">
            <h1 className="text-2xl font-bold">Set Up Your AI</h1>
            <p className="text-sm text-muted-foreground">
              Step {currentStepIndex + 1} of {stepsWithStatus.length}
              {" "}— {progress.completedSteps} of {progress.totalSteps} items complete
            </p>
          </div>
          <Button
            variant="ghost"
            size="sm"
            className="gap-1.5 text-muted-foreground"
            onClick={onSwitchToFullBrain}
          >
            <LayoutGrid className="h-4 w-4" />
            Full Brain
          </Button>
        </div>

        <Progress value={progressPercent} className="h-2" />
      </div>

      {/* ── Step pills ── */}
      <div className="flex gap-1.5 overflow-x-auto pb-2 scrollbar-none">
        {stepsWithStatus.map((step, index) => {
          const Icon = step.icon;
          const isCurrent = index === currentStepIndex;

          return (
            <button
              key={step.id}
              onClick={() => goToStep(index)}
              className={cn(
                "flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap transition-colors shrink-0",
                step.isComplete
                  ? "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400"
                  : isCurrent
                    ? "bg-primary text-primary-foreground"
                    : "bg-muted text-muted-foreground hover:bg-muted/80",
              )}
            >
              {step.isComplete ? (
                <Check className="h-3 w-3" />
              ) : (
                <Icon className="h-3 w-3" />
              )}
              <span className="hidden sm:inline">{step.title.split(" ").slice(0, 3).join(" ")}</span>
              <span className="sm:hidden">{index + 1}</span>
            </button>
          );
        })}
      </div>

      {/* ── Current step content ── */}
      <AnimatePresence mode="wait">
        <motion.div
          key={currentStep.id}
          initial={{ opacity: 0, x: 20 }}
          animate={{ opacity: 1, x: 0 }}
          exit={{ opacity: 0, x: -20 }}
          transition={{ duration: 0.2 }}
        >
          {/* Context card */}
          <Card className="mb-6 border-primary/20 bg-primary/5">
            <CardContent className="p-4">
              <div className="flex items-start gap-3">
                <div className={cn(
                  "flex h-10 w-10 items-center justify-center rounded-lg shrink-0",
                  currentStep.isComplete
                    ? "bg-emerald-100 dark:bg-emerald-900/30"
                    : "bg-primary/10",
                )}>
                  {currentStep.isComplete ? (
                    <CheckCircle2 className="h-5 w-5 text-emerald-600" />
                  ) : (
                    <currentStep.icon className="h-5 w-5 text-primary" />
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <h2 className="text-lg font-semibold">{currentStep.title}</h2>
                    {currentStep.isComplete && (
                      <Badge variant="default" className="bg-emerald-600 text-xs">
                        Complete
                      </Badge>
                    )}
                    {currentStep.skippable && !currentStep.isComplete && (
                      <Badge variant="outline" className="text-xs">
                        Optional
                      </Badge>
                    )}
                  </div>
                  <p className="text-sm text-muted-foreground mt-1">{currentStep.why}</p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Editor component (reused from Brain) */}
          <div className="min-h-[400px]">
            <BrainEditorRenderer
              itemId={currentStep.editorItemId}
              businessMode={businessMode}
              caps={caps}
              isFoodMode={isFoodMode}
              isDispatchMode={isDispatchMode}
            />
          </div>
        </motion.div>
      </AnimatePresence>

      {/* ── Navigation buttons ── */}
      <div className="flex items-center justify-between pt-4 border-t">
        <Button
          variant="outline"
          onClick={goPrev}
          disabled={isFirstStep}
          className="gap-2"
        >
          <ArrowLeft className="h-4 w-4" />
          Previous
        </Button>

        <div className="flex items-center gap-2">
          {currentStep.skippable && !currentStep.isComplete && (
            <Button
              variant="ghost"
              onClick={goNext}
              className="gap-1 text-muted-foreground"
            >
              <SkipForward className="h-4 w-4" />
              Skip for now
            </Button>
          )}

          <Button
            onClick={goNext}
            disabled={isLastStep && !currentStep.isComplete}
            className="gap-2"
          >
            {isLastStep ? (
              <>
                Finish Setup
                <Check className="h-4 w-4" />
              </>
            ) : (
              <>
                Next
                <ArrowRight className="h-4 w-4" />
              </>
            )}
          </Button>
        </div>
      </div>
    </div>
  );
}

/**
 * BusinessBrainHub - Compact landing for Business Brain setup
 *
 * Scannable layout: header with inline progress, then step list.
 */

import { useCallback, useMemo, useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { useFoodMode } from "@/hooks/useFoodMode";
import { useBusinessAwareness } from "@/hooks/useBusinessAwareness";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Brain, PhoneIncoming, ChevronDown, ChevronRight } from "lucide-react";
import { cn } from "@/lib/utils";

import { StepCard } from "./StepCard";
import { getOrderedSteps, getStepTitle, getStepPurpose, isStepEmphasized } from "./hubStepsConfig";
import { GuidedSetupOverlay } from "../editors/GuidedSetupOverlay";

interface BusinessBrainHubProps {
  onNavigateToSection: (sectionId: string) => void;
}

export function BusinessBrainHub({ onNavigateToSection }: BusinessBrainHubProps) {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const caps = useCapabilities();
  const { isFoodMode } = useFoodMode();
  const { complexityTier } = useBusinessAwareness();
  const isSimple = complexityTier === "simple";
  const [advancedOpen, setAdvancedOpen] = useState(false);

  // Check identity
  const { data: tenantData } = useQuery({
    queryKey: ["tenant-profile", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data } = await supabase
        .from("tenants")
        .select("name, tagline, timezone, address")
        .eq("id", tenant.id)
        .single();
      return data;
    },
    enabled: !!tenant?.id,
  });

  // Check hours
  const { data: hoursData } = useQuery({
    queryKey: ["availability-slots", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data } = await supabase
        .from("availability_slots")
        .select("id")
        .eq("tenant_id", tenant.id)
        .limit(1);
      return data || [];
    },
    enabled: !!tenant?.id,
  });

  // Check services
  const { data: servicesData } = useQuery({
    queryKey: ["services", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data } = await supabase
        .from("services")
        .select("id, price_amount, price_type")
        .eq("tenant_id", tenant.id);
      return data || [];
    },
    enabled: !!tenant?.id,
  });

  // Check FAQs
  const { data: faqsData } = useQuery({
    queryKey: ["faqs-count", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data } = await supabase
        .from("business_faqs")
        .select("id")
        .eq("tenant_id", tenant.id);
      return data || [];
    },
    enabled: !!tenant?.id,
  });

  // Check AI scripts
  const { data: assistantData } = useQuery({
    queryKey: ["ai-assistant", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data } = await supabase
        .from("ai_assistants")
        .select("greeting_script, fallback_script")
        .eq("tenant_id", tenant.id)
        .single();
      return data;
    },
    enabled: !!tenant?.id,
  });

  // Check calendar
  const { data: calendarData } = useQuery({
    queryKey: ["calendar-connections", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data } = await supabase
        .from("calendar_connections")
        .select("id, status")
        .eq("tenant_id", tenant.id);
      return data || [];
    },
    enabled: !!tenant?.id,
  });

  // Read capabilities from tenant for step filtering
  const capabilities = useMemo(() => {
    const raw = (tenant as any)?.capabilities_json;
    if (raw && typeof raw === "object") return raw as Record<string, boolean>;
    return {};
  }, [tenant]);

  const isCallbackOnly = capabilities?.callbackOnly === true;

  const getStepCompletion = useCallback((stepId: string): boolean => {
    switch (stepId) {
      case "identity":
        return !!(tenantData?.name && tenantData?.timezone);
      case "hours":
        return (hoursData?.length || 0) > 0;
      case "offerings": {
        if (isCallbackOnly) {
          // For callback-only, just having services listed is enough (no price requirement)
          return (servicesData?.length || 0) >= 1;
        }
        const minServices = isFoodMode ? 3 : 1;
        const servicesConfigured = servicesData?.filter(s =>
          (s.price_amount && s.price_amount > 0) || !!s.price_type
        ) || [];
        return servicesConfigured.length >= minServices;
      }
      case "coverage": {
        // Walk-in businesses without mobile service don't need coverage
        const needsCoverage = capabilities?.mobileService === true ||
          caps.isDispatchBusiness || caps.isFoodBusiness;
        if (!needsCoverage) return true;
        return !!(tenantData?.address);
      }
      case "calendar":
        if (caps.isDispatchBusiness || caps.isFoodBusiness) return true;
        return calendarData?.some(c => c.status === "active") ?? false;
      case "policies":
        return true;
      case "ai-setup":
        return !!(assistantData?.greeting_script || assistantData?.fallback_script);
      case "knowledge":
        return (faqsData?.length || 0) >= 3;
      default:
        return false;
    }
  }, [tenantData, hoursData, servicesData, faqsData, assistantData, calendarData, isFoodMode, isCallbackOnly, caps.isDispatchBusiness, caps.isFoodBusiness]);

  const orderedSteps = getOrderedSteps(businessMode, capabilities);
  const completedCount = orderedSteps.filter(step => getStepCompletion(step.id)).length;
  const totalSteps = orderedSteps.length;
  const percentage = Math.round((completedCount / totalSteps) * 100);
  const isAllComplete = completedCount >= totalSteps;

  // For simple tier, split steps into main and advanced (knowledge + ai-setup)
  const advancedStepIds = new Set(["knowledge", "ai-setup"]);
  const mainSteps = isSimple ? orderedSteps.filter(s => !advancedStepIds.has(s.id)) : orderedSteps;
  const advancedSteps = isSimple ? orderedSteps.filter(s => advancedStepIds.has(s.id)) : [];
  const hasIncompleteAdvanced = advancedSteps.some(s => !getStepCompletion(s.id));
  // Auto-expand if any advanced step is incomplete
  const showAdvanced = advancedOpen || hasIncompleteAdvanced;

  const renderStep = (step: typeof orderedSteps[0], index: number) => {
    const isComplete = getStepCompletion(step.id);
    const emphasized = isStepEmphasized(step, businessMode);
    const title = getStepTitle(step.id, businessMode);
    const purpose = getStepPurpose(step.id, isCallbackOnly);

    return (
      <StepCard
        key={step.id}
        stepNumber={index + 1}
        sectionId={step.sectionId}
        title={title}
        purpose={purpose}
        icon={step.icon}
        usedByAI={step.usedByAI}
        isComplete={isComplete}
        isEmphasized={emphasized}
        mode={businessMode}
        onEdit={onNavigateToSection}
      />
    );
  };

  return (
    <div className="pb-12">
      {/* Guided setup overlay */}
      <GuidedSetupOverlay
        onNavigateToSection={onNavigateToSection}
        getStepCompletion={getStepCompletion}
      />

      {/* Callback-only banner */}
      {isCallbackOnly && (
        <div className="mb-4 rounded-lg border border-primary/20 bg-primary/5 p-4">
          <div className="flex items-start gap-3">
            <PhoneIncoming className="h-5 w-5 text-primary mt-0.5 shrink-0" />
            <div>
              <p className="text-sm font-medium">Capture & Callback Mode</p>
              <p className="text-xs text-muted-foreground mt-1">
                Your AI will answer calls, qualify callers by asking about their needs, collect their info, and let them know you'll call back. No scheduling or booking needed.
              </p>
            </div>
          </div>
        </div>
      )}

      <div className="flex items-center justify-between gap-4 mb-6">
        <div className="flex items-center gap-3">
          <Brain className="h-6 w-6 text-primary" />
          <div>
            <h1 className="text-lg font-semibold">Business Brain</h1>
            <p className="text-sm text-muted-foreground">
              {isCallbackOnly
                ? "Teach your AI what you do so it can qualify callers"
                : "Teach your AI about your business"}
            </p>
          </div>
        </div>

        {/* Progress indicator */}
        <div className="flex items-center gap-3">
          <span className="text-sm font-medium whitespace-nowrap">{percentage}% Complete</span>
          <div className="w-24 h-1.5 rounded-full bg-muted overflow-hidden">
            <div
              className={cn(
                "h-full rounded-full transition-all duration-500",
                isAllComplete ? "bg-emerald-500" : "bg-primary"
              )}
              style={{ width: `${percentage}%` }}
            />
          </div>
        </div>
      </div>

      {/* Steps list */}
      <div className="space-y-0.5">
        {mainSteps.map((step, index) => renderStep(step, index))}
      </div>

      {/* Advanced steps (collapsed for simple tier) */}
      {advancedSteps.length > 0 && (
        <div className="mt-4">
          <button
            onClick={() => setAdvancedOpen(!showAdvanced)}
            className="flex items-center gap-2 w-full px-3 py-2 text-xs font-semibold text-muted-foreground/60 uppercase tracking-wider hover:text-foreground transition-colors"
          >
            {showAdvanced ? (
              <ChevronDown className="h-3 w-3" />
            ) : (
              <ChevronRight className="h-3 w-3" />
            )}
            Advanced
          </button>
          {showAdvanced && (
            <div className="space-y-0.5">
              {advancedSteps.map((step, index) => renderStep(step, mainSteps.length + index))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

/**
 * Roadside Knowledge Editor (Dispatch Mode)
 * 
 * Allows towing/roadside companies to configure situation-specific
 * safety scripts, service times, and escalation triggers.
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { AlertTriangle, Loader2, Clock, Shield, Zap } from "lucide-react";
import { toast } from "sonner";
import { KnowledgeSection } from "@/components/brain/shared/KnowledgeSection";
import { KnowledgeItem } from "@/components/brain/shared/KnowledgeItem";
import { AIPreviewCard } from "@/components/brain/AIPreviewCard";

interface RoadsideKnowledge {
  id: string;
  tenant_id: string;
  situation_type: string;
  safety_instructions: string | null;
  estimated_service_time_minutes: number | null;
  tools_required: string[] | null;
  can_be_self_service: boolean;
  self_service_tips: string | null;
  escalation_triggers: string[] | null;
  common_questions: string[] | null;
  ai_script: string | null;
  priority_level: string | null;
  created_at: string;
}

const SITUATION_TYPES = ["Flat Tire", "Dead Battery", "Lockout", "Out of Fuel", "Overheating", "Stuck/Off-Road", "Accident", "Breakdown", "Transmission Issue"];
const PRIORITY_LEVELS = [
  { value: "standard", label: "Standard", color: "bg-blue-100 text-blue-700" },
  { value: "urgent", label: "Urgent", color: "bg-yellow-100 text-yellow-700" },
  { value: "emergency", label: "Emergency", color: "bg-red-100 text-red-700" },
];

export function RoadsideKnowledgeEditor() {
  const { tenant } = useAuth();
  const [items, setItems] = useState<RoadsideKnowledge[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<RoadsideKnowledge | null>(null);
  
  // Form state
  const [formSituation, setFormSituation] = useState("");
  const [formSafety, setFormSafety] = useState("");
  const [formServiceTime, setFormServiceTime] = useState<number | null>(null);
  const [formTools, setFormTools] = useState("");
  const [formCanSelfService, setFormCanSelfService] = useState(false);
  const [formSelfServiceTips, setFormSelfServiceTips] = useState("");
  const [formEscalation, setFormEscalation] = useState("");
  const [formQuestions, setFormQuestions] = useState("");
  const [formAIScript, setFormAIScript] = useState("");
  const [formPriority, setFormPriority] = useState("standard");

  useEffect(() => {
    if (tenant?.id) fetchItems();
  }, [tenant?.id]);

  const fetchItems = async () => {
    if (!tenant?.id) return;
    const { data, error } = await supabase
      .from("roadside_knowledge")
      .select("*")
      .eq("tenant_id", tenant.id)
      .order("situation_type");
    if (!error) setItems((data as RoadsideKnowledge[]) || []);
    setLoading(false);
  };

  const resetForm = () => {
    setEditingItem(null);
    setFormSituation("");
    setFormSafety("");
    setFormServiceTime(null);
    setFormTools("");
    setFormCanSelfService(false);
    setFormSelfServiceTips("");
    setFormEscalation("");
    setFormQuestions("");
    setFormAIScript("");
    setFormPriority("standard");
  };

  const openAddDialog = () => {
    resetForm();
    setIsDialogOpen(true);
  };

  const openEditDialog = (item: RoadsideKnowledge) => {
    setEditingItem(item);
    setFormSituation(item.situation_type);
    setFormSafety(item.safety_instructions || "");
    setFormServiceTime(item.estimated_service_time_minutes);
    setFormTools(item.tools_required?.join(", ") || "");
    setFormCanSelfService(item.can_be_self_service);
    setFormSelfServiceTips(item.self_service_tips || "");
    setFormEscalation(item.escalation_triggers?.join(", ") || "");
    setFormQuestions(item.common_questions?.join(", ") || "");
    setFormAIScript(item.ai_script || "");
    setFormPriority(item.priority_level || "standard");
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!tenant?.id || !formSituation.trim()) return;
    setSaving(true);
    try {
      const payload = {
        tenant_id: tenant.id,
        situation_type: formSituation.trim(),
        safety_instructions: formSafety.trim() || null,
        estimated_service_time_minutes: formServiceTime,
        tools_required: formTools.split(",").map(s => s.trim()).filter(Boolean),
        can_be_self_service: formCanSelfService,
        self_service_tips: formCanSelfService ? formSelfServiceTips.trim() : null,
        escalation_triggers: formEscalation.split(",").map(s => s.trim()).filter(Boolean),
        common_questions: formQuestions.split(",").map(s => s.trim()).filter(Boolean),
        ai_script: formAIScript.trim() || null,
        priority_level: formPriority,
      };

      if (editingItem) {
        const { error } = await supabase
          .from("roadside_knowledge")
          .update(payload)
          .eq("id", editingItem.id);
        if (error) throw error;
        toast.success("Roadside knowledge updated");
      } else {
        const { error } = await supabase
          .from("roadside_knowledge")
          .insert(payload);
        if (error) throw error;
        toast.success("Roadside knowledge added");
      }
      setIsDialogOpen(false);
      resetForm();
      fetchItems();
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!tenant?.id) return;
    try {
      const { error } = await supabase
        .from("roadside_knowledge")
        .delete()
        .eq("id", id);
      if (error) throw error;
      setItems(items.filter(i => i.id !== id));
      toast.success("Roadside knowledge deleted");
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    }
  };

  const getPriorityConfig = (level: string | null) => {
    return PRIORITY_LEVELS.find(p => p.value === level) || PRIORITY_LEVELS[0];
  };

  const getAIPreview = () => {
    if (!formSituation) return "";
    let preview = "";
    if (formSafety) {
      preview += `First, ${formSafety} `;
    }
    if (formServiceTime) {
      preview += `Our technician can typically resolve ${formSituation.toLowerCase()} in about ${formServiceTime} minutes. `;
    }
    return preview || `I'll dispatch help for your ${formSituation.toLowerCase()} right away.`;
  };

  return (
    <>
      <KnowledgeSection
        title="Roadside Situations"
        description="Configure how your AI handles different roadside emergencies with safety scripts and escalation triggers."
        items={items}
        isLoading={loading}
        onAdd={openAddDialog}
        addButtonLabel="Add Situation"
        emptyState={{
          icon: AlertTriangle,
          title: "No roadside knowledge yet",
          description: "Add safety scripts and procedures for different roadside situations.",
        }}
        headerActions={
          <div className="flex flex-wrap gap-2">
            {SITUATION_TYPES.filter(s => !items.some(i => i.situation_type === s)).slice(0, 4).map(sit => (
              <Badge
                key={sit}
                variant="outline"
                className="cursor-pointer hover:bg-muted"
                onClick={() => {
                  resetForm();
                  setFormSituation(sit);
                  setIsDialogOpen(true);
                }}
              >
                + {sit}
              </Badge>
            ))}
          </div>
        }
        renderItem={(item) => {
          const priority = getPriorityConfig(item.priority_level);
          return (
            <KnowledgeItem
              onEdit={() => openEditDialog(item)}
              onDelete={() => handleDelete(item.id)}
            >
              <div className="flex items-center gap-2 mb-1">
                {item.priority_level === "emergency" ? (
                  <Zap className="h-4 w-4 text-red-500" />
                ) : (
                  <AlertTriangle className="h-4 w-4 text-muted-foreground" />
                )}
                <span className="font-medium text-sm">{item.situation_type}</span>
                <Badge className={`text-xs ${priority.color}`}>
                  {priority.label}
                </Badge>
              </div>
              <div className="flex flex-wrap gap-3 text-sm text-muted-foreground mt-2">
                {item.estimated_service_time_minutes && (
                  <span className="flex items-center gap-1">
                    <Clock className="h-3 w-3" />
                    ~{item.estimated_service_time_minutes} min
                  </span>
                )}
                {item.safety_instructions && (
                  <span className="flex items-center gap-1">
                    <Shield className="h-3 w-3" />
                    Safety script set
                  </span>
                )}
              </div>
            </KnowledgeItem>
          );
        }}
      />

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingItem ? "Edit Situation" : "Add Roadside Situation"}</DialogTitle>
            <DialogDescription>
              Configure how your AI handles this type of roadside emergency.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Situation Type *</Label>
                <Input
                  placeholder="e.g., Flat Tire, Dead Battery"
                  value={formSituation}
                  onChange={(e) => setFormSituation(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>Priority Level</Label>
                <select
                  className="w-full h-10 rounded-md border border-input bg-background px-3 py-2 text-sm"
                  value={formPriority}
                  onChange={(e) => setFormPriority(e.target.value)}
                >
                  {PRIORITY_LEVELS.map(p => (
                    <option key={p.value} value={p.value}>{p.label}</option>
                  ))}
                </select>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Safety Instructions (AI speaks this first)</Label>
              <Textarea
                placeholder="e.g., First, are you in a safe location away from traffic? If you're on a highway, please turn on your hazards and stay in your vehicle..."
                value={formSafety}
                onChange={(e) => setFormSafety(e.target.value)}
                rows={3}
              />
              <p className="text-xs text-muted-foreground">
                What should the AI tell callers to keep them safe while waiting?
              </p>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Estimated Service Time (minutes)</Label>
                <Input
                  type="number"
                  placeholder="e.g., 20"
                  value={formServiceTime || ""}
                  onChange={(e) => setFormServiceTime(e.target.value ? parseInt(e.target.value) : null)}
                />
              </div>
              <div className="space-y-2">
                <Label>Tools Required (comma-separated)</Label>
                <Input
                  placeholder="e.g., Jack, spare tire, lug wrench"
                  value={formTools}
                  onChange={(e) => setFormTools(e.target.value)}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Escalation Triggers (comma-separated)</Label>
              <Input
                placeholder="e.g., Vehicle on fire, Injury, Highway shoulder"
                value={formEscalation}
                onChange={(e) => setFormEscalation(e.target.value)}
              />
              <p className="text-xs text-muted-foreground">
                Situations where AI should recommend 911 or immediate escalation
              </p>
            </div>

            <div className="flex items-center gap-2">
              <Switch checked={formCanSelfService} onCheckedChange={setFormCanSelfService} />
              <Label className="text-sm">Can be self-serviced (offer tips)</Label>
            </div>

            {formCanSelfService && (
              <div className="space-y-2">
                <Label>Self-Service Tips</Label>
                <Textarea
                  placeholder="e.g., If you have a spare tire and feel comfortable, the jack is typically located..."
                  value={formSelfServiceTips}
                  onChange={(e) => setFormSelfServiceTips(e.target.value)}
                  rows={2}
                />
              </div>
            )}

            <div className="space-y-2">
              <Label>Common Questions (comma-separated)</Label>
              <Input
                placeholder="e.g., How long will it take, Do you have my size tire"
                value={formQuestions}
                onChange={(e) => setFormQuestions(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>AI Script (optional - exactly what to say)</Label>
              <Textarea
                placeholder="Full script for how AI should handle this situation..."
                value={formAIScript}
                onChange={(e) => setFormAIScript(e.target.value)}
                rows={3}
              />
            </div>

            {formSituation && (
              <AIPreviewCard 
                title="AI Preview" 
                preview={getAIPreview()} 
                className="mt-4"
                compact 
              />
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)} disabled={saving}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={saving || !formSituation.trim()}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingItem ? "Save Changes" : "Add Situation"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

/**
 * Vehicle Knowledge Editor (Dispatch Mode)
 * 
 * Allows towing companies to configure vehicle-specific requirements,
 * equipment needs, and pricing considerations.
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Truck, Loader2, AlertTriangle, Wrench, Scale } from "lucide-react";
import { toast } from "sonner";
import { KnowledgeSection } from "@/components/brain/shared/KnowledgeSection";
import { KnowledgeItem } from "@/components/brain/shared/KnowledgeItem";
import { AIPreviewCard } from "@/components/brain/AIPreviewCard";

interface VehicleKnowledge {
  id: string;
  tenant_id: string;
  vehicle_category: string;
  equipment_required: string[] | null;
  weight_class: string | null;
  max_weight_lbs: number | null;
  special_instructions: string | null;
  common_issues: string[] | null;
  estimated_hookup_minutes: number | null;
  requires_special_permit: boolean;
  additional_fees_apply: boolean;
  fee_notes: string | null;
  created_at: string;
}

const VEHICLE_CATEGORIES = ["Sedan", "SUV", "Pickup", "Motorcycle", "Semi/Tractor", "RV/Motorhome", "Box Truck", "Classic/Antique", "Electric Vehicle", "AWD/4WD"];
const EQUIPMENT_OPTIONS = ["Flatbed", "Wheel-lift", "Dollies", "Chains", "Straps", "Winch", "Go-Jacks", "Battery Pack", "Fuel Can"];
const WEIGHT_CLASSES = ["Light (<5,000 lbs)", "Medium (5,000-10,000 lbs)", "Heavy (10,000-26,000 lbs)", "Super Heavy (26,000+ lbs)"];

export function VehicleKnowledgeEditor() {
  const { tenant } = useAuth();
  const [items, setItems] = useState<VehicleKnowledge[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<VehicleKnowledge | null>(null);
  
  // Form state
  const [formCategory, setFormCategory] = useState("");
  const [formEquipment, setFormEquipment] = useState<string[]>([]);
  const [formWeightClass, setFormWeightClass] = useState("");
  const [formMaxWeight, setFormMaxWeight] = useState<number | null>(null);
  const [formInstructions, setFormInstructions] = useState("");
  const [formIssues, setFormIssues] = useState("");
  const [formHookupTime, setFormHookupTime] = useState<number | null>(null);
  const [formPermitRequired, setFormPermitRequired] = useState(false);
  const [formExtraFees, setFormExtraFees] = useState(false);
  const [formFeeNotes, setFormFeeNotes] = useState("");

  useEffect(() => {
    if (tenant?.id) fetchItems();
  }, [tenant?.id]);

  const fetchItems = async () => {
    if (!tenant?.id) return;
    const { data, error } = await supabase
      .from("vehicle_knowledge")
      .select("*")
      .eq("tenant_id", tenant.id)
      .order("vehicle_category");
    if (!error) setItems((data as VehicleKnowledge[]) || []);
    setLoading(false);
  };

  const resetForm = () => {
    setEditingItem(null);
    setFormCategory("");
    setFormEquipment([]);
    setFormWeightClass("");
    setFormMaxWeight(null);
    setFormInstructions("");
    setFormIssues("");
    setFormHookupTime(null);
    setFormPermitRequired(false);
    setFormExtraFees(false);
    setFormFeeNotes("");
  };

  const openAddDialog = () => {
    resetForm();
    setIsDialogOpen(true);
  };

  const openEditDialog = (item: VehicleKnowledge) => {
    setEditingItem(item);
    setFormCategory(item.vehicle_category);
    setFormEquipment(item.equipment_required || []);
    setFormWeightClass(item.weight_class || "");
    setFormMaxWeight(item.max_weight_lbs);
    setFormInstructions(item.special_instructions || "");
    setFormIssues(item.common_issues?.join(", ") || "");
    setFormHookupTime(item.estimated_hookup_minutes);
    setFormPermitRequired(item.requires_special_permit);
    setFormExtraFees(item.additional_fees_apply);
    setFormFeeNotes(item.fee_notes || "");
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!tenant?.id || !formCategory.trim()) return;
    setSaving(true);
    try {
      const payload = {
        tenant_id: tenant.id,
        vehicle_category: formCategory.trim(),
        equipment_required: formEquipment,
        weight_class: formWeightClass || null,
        max_weight_lbs: formMaxWeight,
        special_instructions: formInstructions.trim() || null,
        common_issues: formIssues.split(",").map(s => s.trim()).filter(Boolean),
        estimated_hookup_minutes: formHookupTime,
        requires_special_permit: formPermitRequired,
        additional_fees_apply: formExtraFees,
        fee_notes: formExtraFees ? formFeeNotes.trim() : null,
      };

      if (editingItem) {
        const { error } = await supabase
          .from("vehicle_knowledge")
          .update(payload)
          .eq("id", editingItem.id);
        if (error) throw error;
        toast.success("Vehicle knowledge updated");
      } else {
        const { error } = await supabase
          .from("vehicle_knowledge")
          .insert(payload);
        if (error) throw error;
        toast.success("Vehicle knowledge added");
      }
      setIsDialogOpen(false);
      resetForm();
      fetchItems();
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!tenant?.id) return;
    try {
      const { error } = await supabase
        .from("vehicle_knowledge")
        .delete()
        .eq("id", id);
      if (error) throw error;
      setItems(items.filter(i => i.id !== id));
      toast.success("Vehicle knowledge deleted");
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    }
  };

  const toggleEquipment = (eq: string) => {
    if (formEquipment.includes(eq)) {
      setFormEquipment(formEquipment.filter(e => e !== eq));
    } else {
      setFormEquipment([...formEquipment, eq]);
    }
  };

  const getAIPreview = () => {
    if (!formCategory) return "";
    let preview = `For ${formCategory.toLowerCase()} towing, `;
    if (formEquipment.length > 0) {
      preview += `we'll use ${formEquipment.join(" and ").toLowerCase()}. `;
    }
    if (formHookupTime) {
      preview += `Hookup takes about ${formHookupTime} minutes. `;
    }
    if (formExtraFees && formFeeNotes) {
      preview += formFeeNotes;
    }
    return preview;
  };

  return (
    <>
      <KnowledgeSection
        title="Vehicle Towing Requirements"
        description="Configure equipment and procedures for different vehicle types so your AI quotes accurately."
        items={items}
        isLoading={loading}
        onAdd={openAddDialog}
        addButtonLabel="Add Vehicle Type"
        emptyState={{
          icon: Truck,
          title: "No vehicle knowledge yet",
          description: "Add towing requirements for different vehicle categories.",
        }}
        headerActions={
          <div className="flex flex-wrap gap-2">
            {VEHICLE_CATEGORIES.filter(c => !items.some(i => i.vehicle_category === c)).slice(0, 4).map(cat => (
              <Badge
                key={cat}
                variant="outline"
                className="cursor-pointer hover:bg-muted"
                onClick={() => {
                  resetForm();
                  setFormCategory(cat);
                  setIsDialogOpen(true);
                }}
              >
                + {cat}
              </Badge>
            ))}
          </div>
        }
        renderItem={(item) => (
          <KnowledgeItem
            onEdit={() => openEditDialog(item)}
            onDelete={() => handleDelete(item.id)}
          >
            <div className="flex items-center gap-2 mb-1">
              <Truck className="h-4 w-4 text-muted-foreground" />
              <span className="font-medium text-sm">{item.vehicle_category}</span>
              {item.requires_special_permit && (
                <Badge variant="outline" className="text-xs text-orange-600 border-orange-300">
                  <AlertTriangle className="h-3 w-3 mr-1" />
                  Permit
                </Badge>
              )}
              {item.additional_fees_apply && (
                <Badge variant="secondary" className="text-xs">Extra fees</Badge>
              )}
            </div>
            <div className="flex flex-wrap gap-2 mt-2">
              {item.equipment_required?.map(eq => (
                <Badge key={eq} variant="outline" className="text-xs">
                  <Wrench className="h-3 w-3 mr-1" />
                  {eq}
                </Badge>
              ))}
              {item.weight_class && (
                <Badge variant="secondary" className="text-xs">
                  <Scale className="h-3 w-3 mr-1" />
                  {item.weight_class}
                </Badge>
              )}
            </div>
          </KnowledgeItem>
        )}
      />

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingItem ? "Edit Vehicle Type" : "Add Vehicle Type"}</DialogTitle>
            <DialogDescription>
              Configure towing requirements for this vehicle category.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Vehicle Category *</Label>
              <Input
                placeholder="e.g., Motorcycle, Semi, RV"
                value={formCategory}
                onChange={(e) => setFormCategory(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>Equipment Required</Label>
              <div className="flex flex-wrap gap-2">
                {EQUIPMENT_OPTIONS.map(eq => (
                  <Badge
                    key={eq}
                    variant={formEquipment.includes(eq) ? "default" : "outline"}
                    className="cursor-pointer"
                    onClick={() => toggleEquipment(eq)}
                  >
                    <Wrench className="h-3 w-3 mr-1" />
                    {eq}
                  </Badge>
                ))}
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Weight Class</Label>
                <select
                  className="w-full h-10 rounded-md border border-input bg-background px-3 py-2 text-sm"
                  value={formWeightClass}
                  onChange={(e) => setFormWeightClass(e.target.value)}
                >
                  <option value="">Select weight class</option>
                  {WEIGHT_CLASSES.map(wc => (
                    <option key={wc} value={wc}>{wc}</option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label>Max Weight (lbs)</Label>
                <Input
                  type="number"
                  placeholder="e.g., 10000"
                  value={formMaxWeight || ""}
                  onChange={(e) => setFormMaxWeight(e.target.value ? parseInt(e.target.value) : null)}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Estimated Hookup Time (minutes)</Label>
              <Input
                type="number"
                placeholder="e.g., 15"
                value={formHookupTime || ""}
                onChange={(e) => setFormHookupTime(e.target.value ? parseInt(e.target.value) : null)}
              />
            </div>

            <div className="space-y-2">
              <Label>Special Instructions</Label>
              <Textarea
                placeholder="e.g., Always use flatbed for AWD vehicles to prevent transmission damage..."
                value={formInstructions}
                onChange={(e) => setFormInstructions(e.target.value)}
                rows={3}
              />
            </div>

            <div className="space-y-2">
              <Label>Common Issues (comma-separated)</Label>
              <Input
                placeholder="e.g., Locked steering, parking brake stuck, transmission in gear"
                value={formIssues}
                onChange={(e) => setFormIssues(e.target.value)}
              />
            </div>

            <div className="flex items-center gap-6">
              <div className="flex items-center gap-2">
                <Switch checked={formPermitRequired} onCheckedChange={setFormPermitRequired} />
                <Label className="text-sm">Requires Special Permit</Label>
              </div>
              <div className="flex items-center gap-2">
                <Switch checked={formExtraFees} onCheckedChange={setFormExtraFees} />
                <Label className="text-sm">Additional Fees Apply</Label>
              </div>
            </div>

            {formExtraFees && (
              <div className="space-y-2">
                <Label>Fee Notes (what AI should say)</Label>
                <Textarea
                  placeholder="e.g., There's an additional $50 charge for motorcycles due to specialized equipment..."
                  value={formFeeNotes}
                  onChange={(e) => setFormFeeNotes(e.target.value)}
                  rows={2}
                />
              </div>
            )}

            {formCategory && (
              <AIPreviewCard 
                title="AI Preview" 
                preview={getAIPreview()} 
                className="mt-4"
                compact 
              />
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)} disabled={saving}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={saving || !formCategory.trim()}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingItem ? "Save Changes" : "Add Vehicle Type"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

/**
 * Catering Knowledge Editor (Food Mode)
