  const handleDelete = async (id: string) => {
    if (!tenant?.id) return;
    try {
      const { error } = await supabase
        .from("catering_knowledge")
        .delete()
        .eq("id", id);
      if (error) throw error;
      setItems(items.filter(i => i.id !== id));
      toast.success("Catering info deleted");
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    }
  };

  const getAIPreview = () => {
    if (!formEventType) return "";
    let preview = `For ${formEventType.toLowerCase()} events, `;
    if (formMinGuests && formMaxGuests) {
      preview += `we accommodate ${formMinGuests} to ${formMaxGuests} guests. `;
    } else if (formMinGuests) {
      preview += `we require a minimum of ${formMinGuests} guests. `;
    }
    if (formLeadTime) {
      preview += `We recommend booking at least ${formLeadTime} days in advance. `;
    }
    if (formDeposit) {
      preview += `A ${formDeposit}% deposit is required to secure your date.`;
    }
    return preview;
  };

  return (
    <>
      <KnowledgeSection
        title="Catering by Event Type"
        description="Configure catering requirements for different event types so your AI can provide accurate quotes."
        items={items}
        isLoading={loading}
        onAdd={openAddDialog}
        addButtonLabel="Add Event Type"
        emptyState={{
          icon: PartyPopper,
          title: "No catering info yet",
          description: "Add catering details for weddings, corporate events, parties, and more.",
        }}
        headerActions={
          <div className="flex flex-wrap gap-2">
            {COMMON_EVENT_TYPES.filter(t => !items.some(i => i.event_type === t)).slice(0, 4).map(type => (
              <Badge
                key={type}
                variant="outline"
                className="cursor-pointer hover:bg-muted"
                onClick={() => {
                  resetForm();
                  setFormEventType(type);
                  setIsDialogOpen(true);
                }}
              >
                + {type}
              </Badge>
            ))}
          </div>
        }
        renderItem={(item) => (
          <KnowledgeItem
            onEdit={() => openEditDialog(item)}
            onDelete={() => handleDelete(item.id)}
          >
            <div className="flex items-center gap-2 mb-1">
              <PartyPopper className="h-4 w-4 text-muted-foreground" />
              <span className="font-medium text-sm">{item.event_type}</span>
            </div>
            <div className="flex flex-wrap gap-3 text-sm text-muted-foreground">
              {(item.min_guests || item.max_guests) && (
                <span className="flex items-center gap-1">
                  <Users className="h-3 w-3" />
                  {item.min_guests && item.max_guests 
                    ? `${item.min_guests}-${item.max_guests} guests`
                    : item.min_guests 
                      ? `Min ${item.min_guests}` 
                      : `Up to ${item.max_guests}`}
                </span>
              )}
              {item.lead_time_days && (
                <span className="flex items-center gap-1">
                  <Clock className="h-3 w-3" />
                  {item.lead_time_days}+ days notice
                </span>
              )}
              {item.deposit_percentage && (
                <span className="flex items-center gap-1">
                  <DollarSign className="h-3 w-3" />
                  {item.deposit_percentage}% deposit
                </span>
              )}
            </div>
          </KnowledgeItem>
        )}
      />

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingItem ? "Edit Event Type" : "Add Catering Event Type"}</DialogTitle>
            <DialogDescription>
              Configure catering details for this type of event.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Event Type *</Label>
              <Input
                placeholder="e.g., Wedding, Corporate Lunch"
                value={formEventType}
                onChange={(e) => setFormEventType(e.target.value)}
              />
            </div>

            <div className="grid gap-4 sm:grid-cols-3">
              <div className="space-y-2">
                <Label>Minimum Guests</Label>
                <Input
                  type="number"
                  placeholder="e.g., 20"
                  value={formMinGuests || ""}
                  onChange={(e) => setFormMinGuests(e.target.value ? parseInt(e.target.value) : null)}
                />
              </div>
              <div className="space-y-2">
                <Label>Maximum Guests</Label>
                <Input
                  type="number"
                  placeholder="e.g., 200"
                  value={formMaxGuests || ""}
                  onChange={(e) => setFormMaxGuests(e.target.value ? parseInt(e.target.value) : null)}
                />
              </div>
              <div className="space-y-2">
                <Label>Lead Time (days)</Label>
                <Input
                  type="number"
                  placeholder="e.g., 14"
                  value={formLeadTime || ""}
                  onChange={(e) => setFormLeadTime(e.target.value ? parseInt(e.target.value) : null)}
                />
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Deposit Required (%)</Label>
                <Input
                  type="number"
                  placeholder="e.g., 25"
                  value={formDeposit || ""}
                  onChange={(e) => setFormDeposit(e.target.value ? parseInt(e.target.value) : null)}
                />
              </div>
              <div className="flex items-center gap-2 pt-6">
                <Switch checked={formStaffingIncluded} onCheckedChange={setFormStaffingIncluded} />
                <Label>Staffing included in package</Label>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Menu Restrictions</Label>
              <Textarea
                placeholder="e.g., Buffet only for 50+ guests, limited menu for rush orders..."
                value={formMenuRestrictions}
                onChange={(e) => setFormMenuRestrictions(e.target.value)}
                rows={2}
              />
            </div>

            <div className="space-y-2">
              <Label>Setup Requirements</Label>
              <Textarea
                placeholder="e.g., Need access 2 hours before, kitchen facility required..."
                value={formSetupReq}
                onChange={(e) => setFormSetupReq(e.target.value)}
                rows={2}
              />
            </div>

            <div className="space-y-2">
              <Label>Equipment We Provide (comma-separated)</Label>
              <Input
                placeholder="e.g., Chafing dishes, serving utensils, linens"
                value={formEquipment}
                onChange={(e) => setFormEquipment(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>Venue Requirements</Label>
              <Input
                placeholder="e.g., Covered area if outdoors, electrical access"
                value={formVenueReq}
                onChange={(e) => setFormVenueReq(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>Cancellation Policy</Label>
              <Textarea
                placeholder="e.g., Full refund if cancelled 30+ days out, 50% within 14 days..."
                value={formCancellation}
                onChange={(e) => setFormCancellation(e.target.value)}
                rows={2}
              />
            </div>

            <div className="space-y-2">
              <Label>AI Script (optional - exactly what to say)</Label>
              <Textarea
                placeholder="For [event type] events, we offer comprehensive catering packages..."
                value={formAIScript}
                onChange={(e) => setFormAIScript(e.target.value)}
                rows={3}
              />
            </div>

            {formEventType && (
              <AIPreviewCard 
                title="AI Preview" 
                preview={getAIPreview()} 
                className="mt-4"
                compact 
              />
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)} disabled={saving}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={saving || !formEventType.trim()}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingItem ? "Save Changes" : "Add Event Type"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

/**
 * Menu Knowledge Editor (Food Mode)
 * 
 * Allows food businesses to add detailed descriptions, ingredients, allergens,
 * and pairing suggestions for menu items.
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Slider } from "@/components/ui/slider";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { UtensilsCrossed, Loader2, Flame, Leaf, Star } from "lucide-react";
import { toast } from "sonner";
import { KnowledgeSection } from "@/components/brain/shared/KnowledgeSection";
import { KnowledgeItem } from "@/components/brain/shared/KnowledgeItem";
import { AIPreviewCard } from "@/components/brain/AIPreviewCard";

interface MenuKnowledge {
  id: string;
  tenant_id: string;
  item_name: string;
  detailed_description: string | null;
  ingredients: string[] | null;
  allergens: string[] | null;
  dietary_tags: string[] | null;
  prep_notes: string | null;
  pairing_suggestions: string | null;
  chef_notes: string | null;
  calorie_count: number | null;
  spice_level: number | null;
  is_signature: boolean;
  is_seasonal: boolean;
  seasonal_availability: string | null;
  created_at: string;
}

const COMMON_ALLERGENS = ["Dairy", "Eggs", "Fish", "Shellfish", "Tree Nuts", "Peanuts", "Wheat", "Soy", "Sesame"];
const DIETARY_TAGS = ["Vegetarian", "Vegan", "Gluten-Free", "Keto", "Halal", "Kosher", "Dairy-Free", "Nut-Free"];

export function MenuKnowledgeEditor() {
  const { tenant } = useAuth();
  const [items, setItems] = useState<MenuKnowledge[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<MenuKnowledge | null>(null);
  
  // Form state
  const [formName, setFormName] = useState("");
  const [formDescription, setFormDescription] = useState("");
  const [formIngredients, setFormIngredients] = useState("");
  const [formAllergens, setFormAllergens] = useState<string[]>([]);
  const [formDietaryTags, setFormDietaryTags] = useState<string[]>([]);
  const [formPrepNotes, setFormPrepNotes] = useState("");
  const [formPairings, setFormPairings] = useState("");
  const [formChefNotes, setFormChefNotes] = useState("");
  const [formCalories, setFormCalories] = useState<number | null>(null);
  const [formSpiceLevel, setFormSpiceLevel] = useState(0);
  const [formIsSignature, setFormIsSignature] = useState(false);
  const [formIsSeasonal, setFormIsSeasonal] = useState(false);
  const [formSeasonalAvail, setFormSeasonalAvail] = useState("");

  useEffect(() => {
    if (tenant?.id) fetchItems();
  }, [tenant?.id]);

  const fetchItems = async () => {
    if (!tenant?.id) return;
    const { data, error } = await supabase
      .from("menu_knowledge")
      .select("*")
      .eq("tenant_id", tenant.id)
      .order("is_signature", { ascending: false });
    if (!error) setItems((data as MenuKnowledge[]) || []);
    setLoading(false);
  };

  const resetForm = () => {
    setEditingItem(null);
    setFormName("");
    setFormDescription("");
    setFormIngredients("");
    setFormAllergens([]);
    setFormDietaryTags([]);
    setFormPrepNotes("");
    setFormPairings("");
    setFormChefNotes("");
    setFormCalories(null);
    setFormSpiceLevel(0);
    setFormIsSignature(false);
    setFormIsSeasonal(false);
    setFormSeasonalAvail("");
  };

  const openAddDialog = () => {
    resetForm();
    setIsDialogOpen(true);
  };

  const openEditDialog = (item: MenuKnowledge) => {
    setEditingItem(item);
    setFormName(item.item_name);
    setFormDescription(item.detailed_description || "");
    setFormIngredients(item.ingredients?.join(", ") || "");
    setFormAllergens(item.allergens || []);
    setFormDietaryTags(item.dietary_tags || []);
    setFormPrepNotes(item.prep_notes || "");
    setFormPairings(item.pairing_suggestions || "");
    setFormChefNotes(item.chef_notes || "");
    setFormCalories(item.calorie_count);
    setFormSpiceLevel(item.spice_level || 0);
    setFormIsSignature(item.is_signature);
    setFormIsSeasonal(item.is_seasonal);
    setFormSeasonalAvail(item.seasonal_availability || "");
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!tenant?.id || !formName.trim()) return;
    setSaving(true);
    try {
      const payload = {
        tenant_id: tenant.id,
        item_name: formName.trim(),
        detailed_description: formDescription.trim() || null,
        ingredients: formIngredients.split(",").map(s => s.trim()).filter(Boolean),
        allergens: formAllergens,
        dietary_tags: formDietaryTags,
        prep_notes: formPrepNotes.trim() || null,
        pairing_suggestions: formPairings.trim() || null,
        chef_notes: formChefNotes.trim() || null,
        calorie_count: formCalories,
        spice_level: formSpiceLevel,
        is_signature: formIsSignature,
        is_seasonal: formIsSeasonal,
        seasonal_availability: formIsSeasonal ? formSeasonalAvail.trim() : null,
      };

      if (editingItem) {
        const { error } = await supabase
          .from("menu_knowledge")
          .update(payload)
          .eq("id", editingItem.id);
        if (error) throw error;
        toast.success("Menu item knowledge updated");
      } else {
        const { error } = await supabase
          .from("menu_knowledge")
          .insert(payload);
        if (error) throw error;
        toast.success("Menu item knowledge added");
      }
      setIsDialogOpen(false);
      resetForm();
      fetchItems();
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!tenant?.id) return;
    try {
      const { error } = await supabase
        .from("menu_knowledge")
        .delete()
        .eq("id", id);
      if (error) throw error;
      setItems(items.filter(i => i.id !== id));
      toast.success("Menu item knowledge deleted");
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    }
  };

  const toggleTag = (tag: string, current: string[], setter: (tags: string[]) => void) => {
    if (current.includes(tag)) {
      setter(current.filter(t => t !== tag));
    } else {
      setter([...current, tag]);
    }
  };

  const getAIPreview = () => {
    if (!formName) return "";
    let preview = `Our ${formName}`;
    if (formIsSignature) preview = `Our signature ${formName}`;
    if (formDescription) preview += ` - ${formDescription}`;
    if (formDietaryTags.length > 0) preview += ` It's ${formDietaryTags.join(" and ").toLowerCase()}.`;
    if (formAllergens.length > 0) preview += ` Please note it contains ${formAllergens.join(", ").toLowerCase()}.`;
    if (formPairings) preview += ` I'd recommend pairing it with ${formPairings}.`;
    return preview;
  };

  return (
    <>
      <KnowledgeSection
        title="Menu Item Knowledge"
        description="Detailed information about dishes so your AI can describe them appetizingly and answer ingredient questions."
        items={items}
        isLoading={loading}
        onAdd={openAddDialog}
        addButtonLabel="Add Item"
        emptyState={{
          icon: UtensilsCrossed,
          title: "No menu knowledge yet",
          description: "Add detailed descriptions, ingredients, and allergen info for your dishes.",
        }}
        renderItem={(item) => (
          <KnowledgeItem
            onEdit={() => openEditDialog(item)}
            onDelete={() => handleDelete(item.id)}
          >
            <div className="flex items-center gap-2 mb-1">
              {item.is_signature && <Star className="h-4 w-4 text-yellow-500 fill-yellow-500" />}
              <span className="font-medium text-sm">{item.item_name}</span>
              {item.spice_level && item.spice_level > 0 && (
                <div className="flex items-center gap-0.5">
                  {Array.from({ length: item.spice_level }).map((_, i) => (
                    <Flame key={i} className="h-3 w-3 text-red-500" />
                  ))}
                </div>
              )}
            </div>
            {item.detailed_description && (
              <p className="text-sm text-muted-foreground line-clamp-1">{item.detailed_description}</p>
            )}
            <div className="flex flex-wrap gap-1 mt-2">
              {item.dietary_tags?.map(tag => (
                <Badge key={tag} variant="secondary" className="text-xs">
                  <Leaf className="h-3 w-3 mr-1" />
                  {tag}
                </Badge>
              ))}
              {item.allergens?.slice(0, 3).map(a => (
                <Badge key={a} variant="outline" className="text-xs text-orange-600 border-orange-300">
                  {a}
                </Badge>
              ))}
            </div>
          </KnowledgeItem>
        )}
      />

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingItem ? "Edit Menu Item" : "Add Menu Item Knowledge"}</DialogTitle>
            <DialogDescription>
              Add details your AI will use to describe and answer questions about this dish.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Item Name *</Label>
                <Input
                  placeholder="e.g., Truffle Risotto"
                  value={formName}
                  onChange={(e) => setFormName(e.target.value)}
                />
              </div>
              <div className="flex items-center gap-6">
                <div className="flex items-center gap-2">
                  <Switch checked={formIsSignature} onCheckedChange={setFormIsSignature} />
                  <Label className="text-sm">Signature Dish</Label>
                </div>
                <div className="flex items-center gap-2">
                  <Switch checked={formIsSeasonal} onCheckedChange={setFormIsSeasonal} />
                  <Label className="text-sm">Seasonal</Label>
                </div>
              </div>
            </div>

            {formIsSeasonal && (
              <div className="space-y-2">
                <Label>Seasonal Availability</Label>
                <Input
                  placeholder="e.g., Summer only, Available Oct-Dec"
                  value={formSeasonalAvail}
                  onChange={(e) => setFormSeasonalAvail(e.target.value)}
                />
              </div>
            )}

            <div className="space-y-2">
              <Label>Description</Label>
              <Textarea
                placeholder="Describe the dish appetizingly - how it looks, tastes, and what makes it special..."
                value={formDescription}
                onChange={(e) => setFormDescription(e.target.value)}
                rows={3}
              />
            </div>

            <div className="space-y-2">
              <Label>Ingredients (comma-separated)</Label>
              <Input
                placeholder="e.g., Arborio rice, truffle oil, parmesan, shallots"
                value={formIngredients}
                onChange={(e) => setFormIngredients(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>Allergens</Label>
              <div className="flex flex-wrap gap-2">
                {COMMON_ALLERGENS.map(allergen => (
                  <Badge
                    key={allergen}
                    variant={formAllergens.includes(allergen) ? "default" : "outline"}
                    className="cursor-pointer"
                    onClick={() => toggleTag(allergen, formAllergens, setFormAllergens)}
                  >
                    {allergen}
                  </Badge>
                ))}
              </div>
            </div>

            <div className="space-y-2">
              <Label>Dietary Tags</Label>
              <div className="flex flex-wrap gap-2">
                {DIETARY_TAGS.map(tag => (
                  <Badge
                    key={tag}
                    variant={formDietaryTags.includes(tag) ? "default" : "outline"}
                    className="cursor-pointer"
                    onClick={() => toggleTag(tag, formDietaryTags, setFormDietaryTags)}
                  >
                    <Leaf className="h-3 w-3 mr-1" />
                    {tag}
                  </Badge>
                ))}
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Spice Level (0-5)</Label>
                <div className="flex items-center gap-4">
                  <Slider
                    value={[formSpiceLevel]}
                    onValueChange={([v]) => setFormSpiceLevel(v)}
                    max={5}
                    step={1}
                    className="flex-1"
                  />
                  <div className="flex items-center gap-0.5 w-20">
                    {formSpiceLevel > 0 ? (
                      Array.from({ length: formSpiceLevel }).map((_, i) => (
                        <Flame key={i} className="h-4 w-4 text-red-500" />
                      ))
                    ) : (
                      <span className="text-sm text-muted-foreground">Not spicy</span>
                    )}
                  </div>
                </div>
              </div>
              <div className="space-y-2">
                <Label>Calories (optional)</Label>
                <Input
                  type="number"
                  placeholder="e.g., 450"
                  value={formCalories || ""}
                  onChange={(e) => setFormCalories(e.target.value ? parseInt(e.target.value) : null)}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Pairing Suggestions</Label>
              <Input
                placeholder="e.g., Pairs well with a crisp Pinot Grigio or our house salad"
                value={formPairings}
                onChange={(e) => setFormPairings(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>Preparation Notes (internal)</Label>
              <Textarea
                placeholder="How is it prepared? Any special instructions for the kitchen..."
                value={formPrepNotes}
                onChange={(e) => setFormPrepNotes(e.target.value)}
                rows={2}
              />
            </div>

            <div className="space-y-2">
              <Label>Chef's Notes (what AI can mention)</Label>
              <Textarea
                placeholder="Special touches, story behind the dish, chef's recommendations..."
                value={formChefNotes}
                onChange={(e) => setFormChefNotes(e.target.value)}
                rows={2}
              />
            </div>

            {formName && (
              <AIPreviewCard 
                title="AI Preview" 
                preview={getAIPreview()} 
                className="mt-4"
                compact 
              />
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)} disabled={saving}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={saving || !formName.trim()}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingItem ? "Save Changes" : "Add Item"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

/**
 * Insurance Knowledge Editor (Medical Mode)
 * 
 * Allows medical practices to configure carrier-specific scripts
 * and verification processes.
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Shield, Loader2, Check, X } from "lucide-react";
import { toast } from "sonner";
import { KnowledgeSection } from "@/components/brain/shared/KnowledgeSection";
import { KnowledgeItem } from "@/components/brain/shared/KnowledgeItem";
import { AIPreviewCard } from "@/components/brain/AIPreviewCard";

interface InsuranceKnowledge {
  id: string;
  tenant_id: string;
  carrier_name: string;
  plan_types: string[] | null;
  is_accepted: boolean;
  verification_process: string | null;
  common_coverage_notes: string | null;
  copay_typical_range: string | null;
  pre_authorization_required: string[] | null;
  billing_notes: string | null;
  patient_script: string | null;
  created_at: string;
}

const COMMON_CARRIERS = ["Blue Cross Blue Shield", "Aetna", "Cigna", "UnitedHealthcare", "Humana", "Medicare", "Medicaid", "Kaiser Permanente", "Anthem"];
const PLAN_TYPES = ["HMO", "PPO", "EPO", "POS", "Medicare Advantage", "Medicare Part B", "Medicaid", "High Deductible", "Self-funded"];

export function InsuranceKnowledgeEditor() {
  const { tenant } = useAuth();
  const [items, setItems] = useState<InsuranceKnowledge[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<InsuranceKnowledge | null>(null);
  
  // Form state
  const [formCarrier, setFormCarrier] = useState("");
  const [formPlanTypes, setFormPlanTypes] = useState<string[]>([]);
  const [formIsAccepted, setFormIsAccepted] = useState(true);
  const [formVerification, setFormVerification] = useState("");
  const [formCoverage, setFormCoverage] = useState("");
  const [formCopay, setFormCopay] = useState("");
  const [formPreAuth, setFormPreAuth] = useState("");
  const [formBilling, setFormBilling] = useState("");
  const [formScript, setFormScript] = useState("");

  useEffect(() => {
    if (tenant?.id) fetchItems();
  }, [tenant?.id]);

  const fetchItems = async () => {
    if (!tenant?.id) return;
    const { data, error } = await supabase
      .from("insurance_knowledge")
      .select("*")
      .eq("tenant_id", tenant.id)
      .order("carrier_name");
    if (!error) setItems((data as InsuranceKnowledge[]) || []);
    setLoading(false);
  };

  const resetForm = () => {
    setEditingItem(null);
    setFormCarrier("");
    setFormPlanTypes([]);
    setFormIsAccepted(true);
    setFormVerification("");
    setFormCoverage("");
    setFormCopay("");
    setFormPreAuth("");
    setFormBilling("");
    setFormScript("");
  };

  const openAddDialog = () => {
    resetForm();
    setIsDialogOpen(true);
  };

  const openEditDialog = (item: InsuranceKnowledge) => {
    setEditingItem(item);
    setFormCarrier(item.carrier_name);
    setFormPlanTypes(item.plan_types || []);
    setFormIsAccepted(item.is_accepted);
    setFormVerification(item.verification_process || "");
    setFormCoverage(item.common_coverage_notes || "");
    setFormCopay(item.copay_typical_range || "");
    setFormPreAuth(item.pre_authorization_required?.join(", ") || "");
    setFormBilling(item.billing_notes || "");
    setFormScript(item.patient_script || "");
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!tenant?.id || !formCarrier.trim()) return;
    setSaving(true);
    try {
      const payload = {
        tenant_id: tenant.id,
        carrier_name: formCarrier.trim(),
        plan_types: formPlanTypes,
        is_accepted: formIsAccepted,
        verification_process: formVerification.trim() || null,
        common_coverage_notes: formCoverage.trim() || null,
        copay_typical_range: formCopay.trim() || null,
        pre_authorization_required: formPreAuth.split(",").map(s => s.trim()).filter(Boolean),
        billing_notes: formBilling.trim() || null,
        patient_script: formScript.trim() || null,
      };

      if (editingItem) {
        const { error } = await supabase
          .from("insurance_knowledge")
          .update(payload)
          .eq("id", editingItem.id);
        if (error) throw error;
        toast.success("Insurance info updated");
      } else {
        const { error } = await supabase
          .from("insurance_knowledge")
          .insert(payload);
        if (error) throw error;
        toast.success("Insurance info added");
      }
      setIsDialogOpen(false);
      resetForm();
      fetchItems();
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!tenant?.id) return;
    try {
      const { error } = await supabase
        .from("insurance_knowledge")
        .delete()
        .eq("id", id);
      if (error) throw error;
      setItems(items.filter(i => i.id !== id));
      toast.success("Insurance info deleted");
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    }
  };

  const togglePlanType = (type: string) => {
    if (formPlanTypes.includes(type)) {
      setFormPlanTypes(formPlanTypes.filter(t => t !== type));
    } else {
      setFormPlanTypes([...formPlanTypes, type]);
    }
  };

  const getAIPreview = () => {
    if (!formCarrier) return "";
    if (!formIsAccepted) {
      return `Unfortunately, we don't currently accept ${formCarrier}. Would you like information about our self-pay rates?`;
    }
    let preview = `Yes, we accept ${formCarrier}`;
    if (formPlanTypes.length > 0) {
      preview += ` including ${formPlanTypes.join(", ")} plans`;
    }
    preview += ".";
    if (formCopay) {
      preview += ` Typical copays range from ${formCopay}.`;
    }
    return preview;
  };

  return (
    <>
      <KnowledgeSection
        title="Insurance Carrier Info"
        description="Configure what your AI says about each insurance carrier you work with."
        items={items}
        isLoading={loading}
        onAdd={openAddDialog}
        addButtonLabel="Add Carrier"
        emptyState={{
          icon: Shield,
          title: "No insurance info configured",
          description: "Add carriers you accept and scripts for handling insurance questions.",
        }}
        headerActions={
          <div className="flex flex-wrap gap-2">
            {COMMON_CARRIERS.filter(c => !items.some(i => i.carrier_name === c)).slice(0, 4).map(carrier => (
              <Badge
                key={carrier}
                variant="outline"
                className="cursor-pointer hover:bg-muted"
                onClick={() => {
                  resetForm();
                  setFormCarrier(carrier);
                  setIsDialogOpen(true);
                }}
              >
                + {carrier}
              </Badge>
            ))}
          </div>
        }
        renderItem={(item) => (
          <KnowledgeItem
            onEdit={() => openEditDialog(item)}
            onDelete={() => handleDelete(item.id)}
          >
            <div className="flex items-center gap-2 mb-1">
              <Shield className="h-4 w-4 text-muted-foreground" />
              <span className="font-medium text-sm">{item.carrier_name}</span>
              {item.is_accepted ? (
                <Badge variant="secondary" className="text-xs bg-green-100 text-green-700">
                  <Check className="h-3 w-3 mr-1" />
                  Accepted
                </Badge>
              ) : (
                <Badge variant="secondary" className="text-xs bg-red-100 text-red-700">
                  <X className="h-3 w-3 mr-1" />
                  Not Accepted
                </Badge>
              )}
            </div>
            {item.plan_types && item.plan_types.length > 0 && (
              <div className="flex flex-wrap gap-1 mt-2">
                {item.plan_types.map(type => (
                  <Badge key={type} variant="outline" className="text-xs">{type}</Badge>
                ))}
              </div>
            )}
          </KnowledgeItem>
        )}
      />

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingItem ? "Edit Insurance Carrier" : "Add Insurance Carrier"}</DialogTitle>
            <DialogDescription>
              Configure what your AI should say about this insurance carrier.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Carrier Name *</Label>
                <Input
                  placeholder="e.g., Blue Cross Blue Shield"
                  value={formCarrier}
                  onChange={(e) => setFormCarrier(e.target.value)}
                />
              </div>
              <div className="flex items-center gap-2 pt-6">
                <Switch checked={formIsAccepted} onCheckedChange={setFormIsAccepted} />
                <Label className="text-sm">We accept this carrier</Label>
              </div>
            </div>

            {formIsAccepted && (
              <>
                <div className="space-y-2">
                  <Label>Plan Types Accepted</Label>
                  <div className="flex flex-wrap gap-2">
                    {PLAN_TYPES.map(type => (
                      <Badge
                        key={type}
                        variant={formPlanTypes.includes(type) ? "default" : "outline"}
                        className="cursor-pointer"
                        onClick={() => togglePlanType(type)}
                      >
                        {type}
                      </Badge>
                    ))}
                  </div>
                </div>

                <div className="space-y-2">
                  <Label>Typical Copay Range</Label>
                  <Input
                    placeholder="e.g., $25-$50"
                    value={formCopay}
                    onChange={(e) => setFormCopay(e.target.value)}
                  />
                </div>

                <div className="space-y-2">
                  <Label>Verification Process</Label>
                  <Textarea
                    placeholder="e.g., We verify benefits before your appointment. Please have your member ID ready..."
                    value={formVerification}
                    onChange={(e) => setFormVerification(e.target.value)}
                    rows={2}
                  />
                </div>

                <div className="space-y-2">
                  <Label>Coverage Notes</Label>
                  <Textarea
                    placeholder="e.g., Most plans cover preventive visits at 100%. Specialty visits may require referral..."
                    value={formCoverage}
                    onChange={(e) => setFormCoverage(e.target.value)}
                    rows={2}
                  />
                </div>

                <div className="space-y-2">
                  <Label>Services Requiring Pre-Authorization (comma-separated)</Label>
                  <Input
                    placeholder="e.g., MRI, CT Scan, Surgery"
                    value={formPreAuth}
                    onChange={(e) => setFormPreAuth(e.target.value)}
                  />
                </div>

                <div className="space-y-2">
                  <Label>Billing Notes (internal)</Label>
                  <Input
                    placeholder="e.g., Uses Naviguard for out-of-network appeals"
                    value={formBilling}
                    onChange={(e) => setFormBilling(e.target.value)}
                  />
                </div>
              </>
            )}

            <div className="space-y-2">
              <Label>Patient Script (what AI says)</Label>
              <Textarea
                placeholder={formIsAccepted 
                  ? "e.g., Yes, we're in-network with [Carrier]. Copays typically range from..."
                  : "e.g., We don't currently accept [Carrier], but we offer competitive self-pay rates..."}
                value={formScript}
                onChange={(e) => setFormScript(e.target.value)}
                rows={3}
              />
            </div>

            {formCarrier && (
              <AIPreviewCard 
                title="AI Preview" 
                preview={formScript || getAIPreview()} 
                className="mt-4"
                compact 
              />
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)} disabled={saving}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={saving || !formCarrier.trim()}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingItem ? "Save Changes" : "Add Carrier"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

/**
 * Symptom Triage Editor (Medical Mode)
 * 
 * Allows medical practices to configure symptom-specific handling,
 * escalation triggers, and pre-visit instructions.
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Stethoscope, Loader2, AlertTriangle, Clock, Video } from "lucide-react";
import { toast } from "sonner";
import { KnowledgeSection } from "@/components/brain/shared/KnowledgeSection";
import { KnowledgeItem } from "@/components/brain/shared/KnowledgeItem";
import { AIPreviewCard } from "@/components/brain/AIPreviewCard";

interface SymptomTriage {
  id: string;
  tenant_id: string;
  symptom_category: string;
  symptom_name: string;
  severity_indicators: string[] | null;
  escalation_action: string | null;
  pre_visit_instructions: string | null;
  questions_to_ask: string[] | null;
  can_be_telehealth: boolean;
  typical_duration_minutes: number | null;
  specialty_referral: string | null;
  hipaa_safe_response: string | null;
  created_at: string;
}

const SYMPTOM_CATEGORIES = ["Pain", "Respiratory", "Digestive", "Skin", "Mental Health", "Cardiac", "Neurological", "Pediatric", "Women's Health", "General"];
const ESCALATION_ACTIONS = ["Recommend ER", "Schedule same-day", "Schedule urgent (48hr)", "Routine appointment", "Telehealth only", "Call 911"];

export function SymptomTriageEditor() {
  const { tenant } = useAuth();
  const [items, setItems] = useState<SymptomTriage[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<SymptomTriage | null>(null);
  
  // Form state
  const [formCategory, setFormCategory] = useState("");
  const [formSymptom, setFormSymptom] = useState("");
  const [formSeverity, setFormSeverity] = useState("");
  const [formEscalation, setFormEscalation] = useState("");
  const [formPreVisit, setFormPreVisit] = useState("");
  const [formQuestions, setFormQuestions] = useState("");
  const [formCanTelehealth, setFormCanTelehealth] = useState(true);
  const [formDuration, setFormDuration] = useState<number | null>(null);
  const [formReferral, setFormReferral] = useState("");
  const [formHIPAASafe, setFormHIPAASafe] = useState("");

  useEffect(() => {
    if (tenant?.id) fetchItems();
  }, [tenant?.id]);

  const fetchItems = async () => {
    if (!tenant?.id) return;
    const { data, error } = await supabase
      .from("symptom_triage")
      .select("*")
      .eq("tenant_id", tenant.id)
      .order("symptom_category");
    if (!error) setItems((data as SymptomTriage[]) || []);
    setLoading(false);
  };

  const resetForm = () => {
    setEditingItem(null);
    setFormCategory("");
    setFormSymptom("");
    setFormSeverity("");
    setFormEscalation("");
    setFormPreVisit("");
    setFormQuestions("");
    setFormCanTelehealth(true);
    setFormDuration(null);
    setFormReferral("");
    setFormHIPAASafe("");
  };

  const openAddDialog = () => {
    resetForm();
    setIsDialogOpen(true);
  };

  const openEditDialog = (item: SymptomTriage) => {
    setEditingItem(item);
    setFormCategory(item.symptom_category);
    setFormSymptom(item.symptom_name);
    setFormSeverity(item.severity_indicators?.join(", ") || "");
    setFormEscalation(item.escalation_action || "");
    setFormPreVisit(item.pre_visit_instructions || "");
    setFormQuestions(item.questions_to_ask?.join(", ") || "");
    setFormCanTelehealth(item.can_be_telehealth);
    setFormDuration(item.typical_duration_minutes);
    setFormReferral(item.specialty_referral || "");
    setFormHIPAASafe(item.hipaa_safe_response || "");
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!tenant?.id || !formSymptom.trim() || !formCategory.trim()) return;
    setSaving(true);
    try {
      const payload = {
        tenant_id: tenant.id,
        symptom_category: formCategory.trim(),
        symptom_name: formSymptom.trim(),
        severity_indicators: formSeverity.split(",").map(s => s.trim()).filter(Boolean),
        escalation_action: formEscalation || null,
        pre_visit_instructions: formPreVisit.trim() || null,
        questions_to_ask: formQuestions.split(",").map(s => s.trim()).filter(Boolean),
        can_be_telehealth: formCanTelehealth,
        typical_duration_minutes: formDuration,
        specialty_referral: formReferral.trim() || null,
        hipaa_safe_response: formHIPAASafe.trim() || null,
      };

      if (editingItem) {
        const { error } = await supabase
          .from("symptom_triage")
          .update(payload)
          .eq("id", editingItem.id);
        if (error) throw error;
        toast.success("Symptom triage updated");
      } else {
        const { error } = await supabase
          .from("symptom_triage")
          .insert(payload);
        if (error) throw error;
        toast.success("Symptom triage added");
      }
      setIsDialogOpen(false);
      resetForm();
      fetchItems();
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!tenant?.id) return;
    try {
      const { error } = await supabase
        .from("symptom_triage")
        .delete()
        .eq("id", id);
      if (error) throw error;
      setItems(items.filter(i => i.id !== id));
      toast.success("Symptom triage deleted");
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    }
  };

  const getAIPreview = () => {
    if (!formHIPAASafe) return formSymptom ? `I can help schedule an appointment for ${formSymptom.toLowerCase()}.` : "";
    return formHIPAASafe;
  };

  return (
    <>
      <KnowledgeSection
        title="Symptom Triage Scripts"
        description="Configure HIPAA-safe responses and escalation rules for different symptoms."
        items={items}
        isLoading={loading}
        onAdd={openAddDialog}
        addButtonLabel="Add Symptom"
        emptyState={{
          icon: Stethoscope,
          title: "No symptom triage configured",
          description: "Add symptom-specific handling rules and HIPAA-safe scripts.",
        }}
        headerActions={
          <div className="flex flex-wrap gap-2">
            {SYMPTOM_CATEGORIES.filter(c => !items.some(i => i.symptom_category === c)).slice(0, 4).map(cat => (
              <Badge
                key={cat}
                variant="outline"
                className="cursor-pointer hover:bg-muted"
                onClick={() => {
                  resetForm();
                  setFormCategory(cat);
                  setIsDialogOpen(true);
                }}
              >
                + {cat}
              </Badge>
            ))}
          </div>
        }
        renderItem={(item) => (
          <KnowledgeItem
            onEdit={() => openEditDialog(item)}
            onDelete={() => handleDelete(item.id)}
          >
            <div className="flex items-center gap-2 mb-1">
              <Stethoscope className="h-4 w-4 text-muted-foreground" />
              <span className="font-medium text-sm">{item.symptom_name}</span>
              <Badge variant="secondary" className="text-xs">{item.symptom_category}</Badge>
              {item.can_be_telehealth && (
                <Badge variant="outline" className="text-xs">
                  <Video className="h-3 w-3 mr-1" />
                  Telehealth
                </Badge>
              )}
            </div>
            <div className="flex flex-wrap gap-2 mt-2 text-sm text-muted-foreground">
              {item.escalation_action && (
                <span className="flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3" />
                  {item.escalation_action}
                </span>
              )}
              {item.typical_duration_minutes && (
                <span className="flex items-center gap-1">
                  <Clock className="h-3 w-3" />
                  {item.typical_duration_minutes} min appointment
                </span>
              )}
            </div>
          </KnowledgeItem>
        )}
      />

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingItem ? "Edit Symptom Triage" : "Add Symptom Triage"}</DialogTitle>
            <DialogDescription>
              Configure how your AI handles calls about this symptom in a HIPAA-compliant way.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Category *</Label>
                <select
                  className="w-full h-10 rounded-md border border-input bg-background px-3 py-2 text-sm"
                  value={formCategory}
                  onChange={(e) => setFormCategory(e.target.value)}
                >
                  <option value="">Select category</option>
                  {SYMPTOM_CATEGORIES.map(cat => (
                    <option key={cat} value={cat}>{cat}</option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label>Symptom Name *</Label>
                <Input
                  placeholder="e.g., Chest Pain, Headache, Rash"
                  value={formSymptom}
                  onChange={(e) => setFormSymptom(e.target.value)}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Severity Indicators (red flags, comma-separated)</Label>
              <Input
                placeholder="e.g., Radiating to arm, Difficulty breathing, Fever over 103"
                value={formSeverity}
                onChange={(e) => setFormSeverity(e.target.value)}
              />
              <p className="text-xs text-muted-foreground">
                These trigger the escalation action below
              </p>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Escalation Action</Label>
                <select
                  className="w-full h-10 rounded-md border border-input bg-background px-3 py-2 text-sm"
                  value={formEscalation}
                  onChange={(e) => setFormEscalation(e.target.value)}
                >
                  <option value="">Select action</option>
                  {ESCALATION_ACTIONS.map(action => (
                    <option key={action} value={action}>{action}</option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label>Typical Appointment Duration (min)</Label>
                <Input
                  type="number"
                  placeholder="e.g., 30"
                  value={formDuration || ""}
                  onChange={(e) => setFormDuration(e.target.value ? parseInt(e.target.value) : null)}
                />
              </div>
            </div>

            <div className="flex items-center gap-2">
              <Switch checked={formCanTelehealth} onCheckedChange={setFormCanTelehealth} />
              <Label className="text-sm">Can be handled via telehealth</Label>
            </div>

            <div className="space-y-2">
              <Label>Questions AI Should Ask (comma-separated)</Label>
              <Input
                placeholder="e.g., When did it start, On a scale of 1-10, Any medications taken"
                value={formQuestions}
                onChange={(e) => setFormQuestions(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>Pre-Visit Instructions</Label>
              <Textarea
                placeholder="e.g., Please don't eat or drink 8 hours before your appointment..."
                value={formPreVisit}
                onChange={(e) => setFormPreVisit(e.target.value)}
                rows={2}
              />
            </div>

            <div className="space-y-2">
              <Label>Specialty Referral (if needed)</Label>
              <Input
                placeholder="e.g., Cardiology, Dermatology"
                value={formReferral}
                onChange={(e) => setFormReferral(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>HIPAA-Safe Response (what AI can say)</Label>
              <Textarea
                placeholder="e.g., I can help schedule an appointment. The doctor will evaluate your symptoms and discuss treatment options during your visit..."
                value={formHIPAASafe}
                onChange={(e) => setFormHIPAASafe(e.target.value)}
                rows={3}
              />
              <p className="text-xs text-muted-foreground">
                This is the exact script the AI will use - make sure it doesn't provide medical advice
              </p>
            </div>

            {formSymptom && (
              <AIPreviewCard 
                title="AI Preview" 
                preview={getAIPreview()} 
                className="mt-4"
                compact 
              />
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)} disabled={saving}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={saving || !formSymptom.trim() || !formCategory.trim()}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingItem ? "Save Changes" : "Add Symptom"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

/**
 * Product Knowledge Editor (Service Mode)
 * 
 * Allows service businesses to document products/materials they use
 * so the AI can educate customers and upsell appropriately.
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Package, Loader2, Star, AlertTriangle } from "lucide-react";
import { toast } from "sonner";
import { KnowledgeSection } from "@/components/brain/shared/KnowledgeSection";
import { KnowledgeItem } from "@/components/brain/shared/KnowledgeItem";
import { AIPreviewCard } from "@/components/brain/AIPreviewCard";

interface ProductKnowledge {
  id: string;
  tenant_id: string;
  product_name: string;
  brand: string | null;
  category: string | null;
  description: string | null;
  benefits: string[] | null;
  usage_instructions: string | null;
  warnings: string | null;
  price_range: string | null;
  is_premium: boolean;
  upsell_script: string | null;
  related_services: string[] | null;
  created_at: string;
}

export function ProductKnowledgeEditor() {
  const { tenant } = useAuth();
  const [items, setItems] = useState<ProductKnowledge[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<ProductKnowledge | null>(null);
  
  // Form state
  const [formName, setFormName] = useState("");
  const [formBrand, setFormBrand] = useState("");
  const [formCategory, setFormCategory] = useState("");
  const [formDescription, setFormDescription] = useState("");
  const [formBenefits, setFormBenefits] = useState("");
  const [formUsage, setFormUsage] = useState("");
  const [formWarnings, setFormWarnings] = useState("");
  const [formPrice, setFormPrice] = useState("");
  const [formIsPremium, setFormIsPremium] = useState(false);
  const [formUpsell, setFormUpsell] = useState("");
  const [formServices, setFormServices] = useState("");

  useEffect(() => {
    if (tenant?.id) fetchItems();
  }, [tenant?.id]);

  const fetchItems = async () => {
    if (!tenant?.id) return;
    const { data, error } = await supabase
      .from("product_knowledge")
      .select("*")
      .eq("tenant_id", tenant.id)
      .order("product_name");
    if (!error) setItems((data as ProductKnowledge[]) || []);
    setLoading(false);
  };

  const resetForm = () => {
    setEditingItem(null);
    setFormName("");
    setFormBrand("");
    setFormCategory("");
    setFormDescription("");
    setFormBenefits("");
    setFormUsage("");
    setFormWarnings("");
    setFormPrice("");
    setFormIsPremium(false);
    setFormUpsell("");
    setFormServices("");
  };

  const openAddDialog = () => {
    resetForm();
    setIsDialogOpen(true);
  };

  const openEditDialog = (item: ProductKnowledge) => {
    setEditingItem(item);
    setFormName(item.product_name);
    setFormBrand(item.brand || "");
    setFormCategory(item.category || "");
    setFormDescription(item.description || "");
    setFormBenefits(item.benefits?.join(", ") || "");
    setFormUsage(item.usage_instructions || "");
    setFormWarnings(item.warnings || "");
    setFormPrice(item.price_range || "");
    setFormIsPremium(item.is_premium);
    setFormUpsell(item.upsell_script || "");
    setFormServices(item.related_services?.join(", ") || "");
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!tenant?.id || !formName.trim()) return;
    setSaving(true);
    try {
      const payload = {
        tenant_id: tenant.id,
        product_name: formName.trim(),
        brand: formBrand.trim() || null,
        category: formCategory.trim() || null,
        description: formDescription.trim() || null,
        benefits: formBenefits.split(",").map(s => s.trim()).filter(Boolean),
        usage_instructions: formUsage.trim() || null,
        warnings: formWarnings.trim() || null,
        price_range: formPrice.trim() || null,
        is_premium: formIsPremium,
        upsell_script: formUpsell.trim() || null,
        related_services: formServices.split(",").map(s => s.trim()).filter(Boolean),
      };

      if (editingItem) {
        const { error } = await supabase
          .from("product_knowledge")
          .update(payload)
          .eq("id", editingItem.id);
        if (error) throw error;
        toast.success("Product knowledge updated");
      } else {
        const { error } = await supabase
          .from("product_knowledge")
          .insert(payload);
        if (error) throw error;
        toast.success("Product knowledge added");
      }
      setIsDialogOpen(false);
      resetForm();
      fetchItems();
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!tenant?.id) return;
    try {
      const { error } = await supabase
        .from("product_knowledge")
        .delete()
        .eq("id", id);
      if (error) throw error;
      setItems(items.filter(i => i.id !== id));
      toast.success("Product knowledge deleted");
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    }
  };

  const getAIPreview = () => {
    if (!formName) return "";
    let preview = `We use ${formName}`;
    if (formBrand) preview = `We use ${formBrand} ${formName}`;
    if (formIsPremium) preview += ", which is a premium product";
    if (formBenefits) {
      const benefits = formBenefits.split(",").map(s => s.trim()).filter(Boolean);
      if (benefits.length > 0) {
        preview += `. It ${benefits.slice(0, 2).join(" and ").toLowerCase()}`;
      }
    }
    preview += ".";
    return preview;
  };

  return (
    <>
      <KnowledgeSection
        title="Product & Material Knowledge"
        description="Teach your AI about the products and materials you use so it can educate customers."
        items={items}
        isLoading={loading}
        onAdd={openAddDialog}
        addButtonLabel="Add Product"
        emptyState={{
          icon: Package,
          title: "No product knowledge yet",
          description: "Add products and materials you use so your AI can explain their benefits.",
        }}
        renderItem={(item) => (
          <KnowledgeItem
            onEdit={() => openEditDialog(item)}
            onDelete={() => handleDelete(item.id)}
          >
            <div className="flex items-center gap-2 mb-1">
              <Package className="h-4 w-4 text-muted-foreground" />
              <span className="font-medium text-sm">
                {item.brand ? `${item.brand} ` : ""}{item.product_name}
              </span>
              {item.is_premium && (
                <Badge variant="secondary" className="text-xs bg-yellow-100 text-yellow-700">
                  <Star className="h-3 w-3 mr-1 fill-yellow-500" />
                  Premium
                </Badge>
              )}
              {item.category && (
                <Badge variant="outline" className="text-xs">{item.category}</Badge>
              )}
            </div>
            {item.description && (
              <p className="text-sm text-muted-foreground line-clamp-1">{item.description}</p>
            )}
          </KnowledgeItem>
        )}
      />

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingItem ? "Edit Product" : "Add Product Knowledge"}</DialogTitle>
            <DialogDescription>
              Document a product or material so your AI can explain its benefits to customers.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Product Name *</Label>
                <Input
                  placeholder="e.g., Ceramic Coating, Color Gloss"
                  value={formName}
                  onChange={(e) => setFormName(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>Brand</Label>
                <Input
                  placeholder="e.g., Redken, 3M, Sherwin-Williams"
                  value={formBrand}
                  onChange={(e) => setFormBrand(e.target.value)}
                />
              </div>
            </div>

            <div className="grid gap-4 sm:grid-cols-2">
              <div className="space-y-2">
                <Label>Category</Label>
                <Input
                  placeholder="e.g., Paint, Hair Color, Sealant"
                  value={formCategory}
                  onChange={(e) => setFormCategory(e.target.value)}
                />
              </div>
              <div className="flex items-center gap-2 pt-6">
                <Switch checked={formIsPremium} onCheckedChange={setFormIsPremium} />
                <Label className="text-sm">Premium/Upgrade Option</Label>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Description</Label>
              <Textarea
                placeholder="What is this product and why do you use it?"
                value={formDescription}
                onChange={(e) => setFormDescription(e.target.value)}
                rows={2}
              />
            </div>

            <div className="space-y-2">
              <Label>Benefits (comma-separated)</Label>
              <Input
                placeholder="e.g., Lasts longer, Less maintenance, Better protection"
                value={formBenefits}
                onChange={(e) => setFormBenefits(e.target.value)}
              />
            </div>

            {formIsPremium && (
              <div className="space-y-2">
                <Label>Price Range (upgrade cost)</Label>
                <Input
                  placeholder="e.g., $50-$100 additional"
                  value={formPrice}
                  onChange={(e) => setFormPrice(e.target.value)}
                />
              </div>
            )}

            <div className="space-y-2">
              <Label>Related Services (comma-separated)</Label>
              <Input
                placeholder="e.g., Full Detail, Paint Correction, Color Treatment"
                value={formServices}
                onChange={(e) => setFormServices(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>Usage Instructions (aftercare)</Label>
              <Textarea
                placeholder="e.g., Wait 24 hours before washing, avoid direct sunlight..."
                value={formUsage}
                onChange={(e) => setFormUsage(e.target.value)}
                rows={2}
              />
            </div>

            <div className="space-y-2">
              <Label>Warnings/Precautions</Label>
              <Input
                placeholder="e.g., Not suitable for sensitive skin, avoid if pregnant"
                value={formWarnings}
                onChange={(e) => setFormWarnings(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>Upsell Script (how AI should mention this)</Label>
              <Textarea
                placeholder="e.g., For an additional $50, we can apply our ceramic coating which protects your paint for up to 2 years..."
                value={formUpsell}
                onChange={(e) => setFormUpsell(e.target.value)}
                rows={2}
              />
            </div>

            {formName && (
              <AIPreviewCard 
                title="AI Preview" 
                preview={formUpsell || getAIPreview()} 
                className="mt-4"
                compact 
              />
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)} disabled={saving}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={saving || !formName.trim()}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingItem ? "Save Changes" : "Add Product"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

/**
 * Aftercare Instructions Editor (Service + Medical Mode)
 * 
 * Allows businesses to configure post-service instructions
 * that the AI can provide to customers.
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Heart, Loader2, Clock, AlertTriangle } from "lucide-react";
import { toast } from "sonner";
import { KnowledgeSection } from "@/components/brain/shared/KnowledgeSection";
import { KnowledgeItem } from "@/components/brain/shared/KnowledgeItem";
import { AIPreviewCard } from "@/components/brain/AIPreviewCard";

interface AftercareInstruction {
  id: string;
  tenant_id: string;
  service_id: string | null;
  service_name: string;
  immediate_care: string[] | null;
  ongoing_care: string[] | null;
  things_to_avoid: string[] | null;
  warning_signs: string[] | null;
  follow_up_recommended: boolean;
  follow_up_timeframe: string | null;
  ai_verbatim_script: string | null;
  created_at: string;
}

export function AftercareInstructionsEditor() {
  const { tenant } = useAuth();
  const [items, setItems] = useState<AftercareInstruction[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingItem, setEditingItem] = useState<AftercareInstruction | null>(null);
  
  // Form state
  const [formServiceName, setFormServiceName] = useState("");
  const [formImmediateCare, setFormImmediateCare] = useState("");
  const [formOngoingCare, setFormOngoingCare] = useState("");
  const [formAvoid, setFormAvoid] = useState("");
  const [formWarnings, setFormWarnings] = useState("");
  const [formFollowUp, setFormFollowUp] = useState(false);
  const [formFollowUpTime, setFormFollowUpTime] = useState("");
  const [formAIScript, setFormAIScript] = useState("");

  useEffect(() => {
    if (tenant?.id) fetchItems();
  }, [tenant?.id]);

  const fetchItems = async () => {
    if (!tenant?.id) return;
    const { data, error } = await supabase
      .from("aftercare_instructions")
      .select("*")
      .eq("tenant_id", tenant.id)
      .order("service_name");
    if (!error) setItems((data as AftercareInstruction[]) || []);
    setLoading(false);
  };

  const resetForm = () => {
    setEditingItem(null);
    setFormServiceName("");
    setFormImmediateCare("");
    setFormOngoingCare("");
    setFormAvoid("");
    setFormWarnings("");
    setFormFollowUp(false);
    setFormFollowUpTime("");
    setFormAIScript("");
  };

  const openAddDialog = () => {
    resetForm();
    setIsDialogOpen(true);
  };

  const openEditDialog = (item: AftercareInstruction) => {
    setEditingItem(item);
    setFormServiceName(item.service_name);
    setFormImmediateCare(item.immediate_care?.join("\n") || "");
    setFormOngoingCare(item.ongoing_care?.join("\n") || "");
    setFormAvoid(item.things_to_avoid?.join("\n") || "");
    setFormWarnings(item.warning_signs?.join("\n") || "");
    setFormFollowUp(item.follow_up_recommended);
    setFormFollowUpTime(item.follow_up_timeframe || "");
    setFormAIScript(item.ai_verbatim_script || "");
    setIsDialogOpen(true);
  };

  const handleSave = async () => {
    if (!tenant?.id || !formServiceName.trim()) return;
    setSaving(true);
    try {
      const parseLines = (text: string) => text.split("\n").map(s => s.trim()).filter(Boolean);
      
      const payload = {
        tenant_id: tenant.id,
        service_name: formServiceName.trim(),
        immediate_care: parseLines(formImmediateCare),
        ongoing_care: parseLines(formOngoingCare),
        things_to_avoid: parseLines(formAvoid),
        warning_signs: parseLines(formWarnings),
        follow_up_recommended: formFollowUp,
        follow_up_timeframe: formFollowUp ? formFollowUpTime.trim() : null,
        ai_verbatim_script: formAIScript.trim() || null,
      };

      if (editingItem) {
        const { error } = await supabase
          .from("aftercare_instructions")
          .update(payload)
          .eq("id", editingItem.id);
        if (error) throw error;
        toast.success("Aftercare instructions updated");
      } else {
        const { error } = await supabase
          .from("aftercare_instructions")
          .insert(payload);
        if (error) throw error;
        toast.success("Aftercare instructions added");
      }
      setIsDialogOpen(false);
      resetForm();
      fetchItems();
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (!tenant?.id) return;
    try {
      const { error } = await supabase
        .from("aftercare_instructions")
        .delete()
        .eq("id", id);
      if (error) throw error;
      setItems(items.filter(i => i.id !== id));
      toast.success("Aftercare instructions deleted");
    } catch (error: any) {
      toast.error(error.message || "Failed to delete");
    }
  };

  const getAIPreview = () => {
    if (!formServiceName) return "";
    let preview = `After your ${formServiceName.toLowerCase()}, `;
    const immediate = formImmediateCare.split("\n").filter(Boolean);
    if (immediate.length > 0) {
      preview += immediate[0].toLowerCase();
    }
    if (formFollowUp && formFollowUpTime) {
      preview += ` We recommend scheduling a follow-up in ${formFollowUpTime}.`;
    }
    return preview;
  };

  return (
    <>
      <KnowledgeSection
        title="Aftercare Instructions"
        description="Post-service care instructions your AI can share with customers."
        items={items}
        isLoading={loading}
        onAdd={openAddDialog}
        addButtonLabel="Add Instructions"
        emptyState={{
          icon: Heart,
          title: "No aftercare instructions yet",
          description: "Add post-service care instructions for each of your services.",
        }}
        renderItem={(item) => (
          <KnowledgeItem
            onEdit={() => openEditDialog(item)}
            onDelete={() => handleDelete(item.id)}
          >
            <div className="flex items-center gap-2 mb-1">
              <Heart className="h-4 w-4 text-muted-foreground" />
              <span className="font-medium text-sm">{item.service_name}</span>
              {item.follow_up_recommended && item.follow_up_timeframe && (
                <Badge variant="secondary" className="text-xs">
                  <Clock className="h-3 w-3 mr-1" />
                  Follow-up: {item.follow_up_timeframe}
                </Badge>
              )}
            </div>
            <div className="flex flex-wrap gap-2 text-sm text-muted-foreground mt-1">
              {item.immediate_care && item.immediate_care.length > 0 && (
                <span>{item.immediate_care.length} immediate care steps</span>
              )}
              {item.warning_signs && item.warning_signs.length > 0 && (
                <span className="flex items-center gap-1 text-orange-600">
                  <AlertTriangle className="h-3 w-3" />
                  {item.warning_signs.length} warning signs
                </span>
              )}
            </div>
          </KnowledgeItem>
        )}
      />

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingItem ? "Edit Aftercare" : "Add Aftercare Instructions"}</DialogTitle>
            <DialogDescription>
              Configure post-service instructions that your AI will share with customers.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Service Name *</Label>
              <Input
                placeholder="e.g., Hair Coloring, Dental Cleaning, Full Detail"
                value={formServiceName}
                onChange={(e) => setFormServiceName(e.target.value)}
              />
            </div>

            <div className="space-y-2">
              <Label>Immediate Care (first 24-48 hours, one per line)</Label>
              <Textarea
                placeholder="Wait 24 hours before washing&#10;Avoid direct sunlight&#10;Keep the area dry"
                value={formImmediateCare}
                onChange={(e) => setFormImmediateCare(e.target.value)}
                rows={3}
              />
            </div>

            <div className="space-y-2">
              <Label>Ongoing Care (one per line)</Label>
              <Textarea
                placeholder="Use gentle, color-safe shampoo&#10;Apply provided ointment twice daily&#10;Avoid harsh chemicals"
                value={formOngoingCare}
                onChange={(e) => setFormOngoingCare(e.target.value)}
                rows={3}
              />
            </div>

            <div className="space-y-2">
              <Label>Things to Avoid (one per line)</Label>
              <Textarea
                placeholder="Swimming pools&#10;Hot tubs&#10;Excessive sun exposure"
                value={formAvoid}
                onChange={(e) => setFormAvoid(e.target.value)}
                rows={3}
              />
            </div>

            <div className="space-y-2">
              <Label>Warning Signs - When to Call Back (one per line)</Label>
              <Textarea
                placeholder="Excessive swelling&#10;Signs of infection&#10;Unusual pain after 48 hours"
                value={formWarnings}
                onChange={(e) => setFormWarnings(e.target.value)}
                rows={3}
              />
            </div>

            <div className="flex items-center gap-2">
              <Switch checked={formFollowUp} onCheckedChange={setFormFollowUp} />
              <Label className="text-sm">Follow-up appointment recommended</Label>
            </div>

            {formFollowUp && (
              <div className="space-y-2">
                <Label>Follow-up Timeframe</Label>
                <Input
                  placeholder="e.g., 2 weeks, 1 month, 6 months"
                  value={formFollowUpTime}
                  onChange={(e) => setFormFollowUpTime(e.target.value)}
                />
              </div>
            )}

            <div className="space-y-2">
              <Label>AI Verbatim Script (optional - exactly what to say)</Label>
              <Textarea
                placeholder="After your appointment today, you'll want to..."
                value={formAIScript}
                onChange={(e) => setFormAIScript(e.target.value)}
                rows={3}
              />
            </div>

            {formServiceName && (
              <AIPreviewCard 
                title="AI Preview" 
                preview={formAIScript || getAIPreview()} 
                className="mt-4"
                compact 
              />
            )}
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)} disabled={saving}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={saving || !formServiceName.trim()}>
              {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingItem ? "Save Changes" : "Add Instructions"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

