/**
 * SectionSummaryCard - Status-focused section card for Business Brain
 *
 * Redesigned: Borderless rounded-2xl, clean expand/collapse, inline icons,
 * no icon boxes, no mode accent borders. Elevated shadow when expanded.
 */

import { useState, useEffect, ReactNode, useCallback } from "react";
import { ChevronDown, ChevronRight, Check, AlertCircle, Circle, Sparkles, Lightbulb, LucideIcon, Zap } from "lucide-react";
import { cn } from "@/lib/utils";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import type { BusinessMode } from "@/hooks/useTenantConfig";
import type { FieldPriority } from "@/config/essentialFields";

export type SectionStatus = "complete" | "incomplete" | "warning" | "error" | "optional";

interface SectionSummaryCardProps {
  id: string;
  title: string;
  icon: LucideIcon;
  status: SectionStatus;
  statusText: string;
  isEssential?: boolean;
  /** AI impact priority from essentialFields registry */
  aiPriority?: FieldPriority;
  /** Tooltip explaining AI impact if not configured */
  aiImpactText?: string;
  mode?: BusinessMode;
  onEdit?: () => void;
  children: ReactNode;
  className?: string;
  defaultExpanded?: boolean;
  /** Controlled expansion state - when provided, overrides internal state */
  expanded?: boolean;
  /** Callback when expansion state changes */
  onExpandedChange?: (expanded: boolean) => void;
  /** Guidance text shown at the top of expanded content when section is incomplete */
  guidanceText?: string;
  /** Helpful tip shown below guidance text */
  guidanceTip?: string;
  /** Always-visible "why" explanation below title (from brainGuidance.why) */
  whyText?: string;
  /** "What this does" text shown in expanded header (from brainGuidance.what) */
  whatText?: string;
  /** Mode-specific tip shown in expanded callout (from brainGuidance.tips[mode]) */
  tipText?: string;
  /** How AI uses this data — shown as bullets in expanded header */
  usedByAI?: string[];
  /** Step number injected by EssentialGroup */
  stepNumber?: number;
}

const STATUS_CONFIG: Record<SectionStatus, { icon: typeof Check; color: string; label: string }> = {
  complete: { icon: Check, color: "text-green-600 bg-green-100 dark:bg-green-900/30", label: "Done" },
  incomplete: { icon: Circle, color: "text-muted-foreground bg-muted", label: "Set up" },
  optional: { icon: Circle, color: "text-muted-foreground/50 bg-muted/50", label: "Optional" },
  warning: { icon: AlertCircle, color: "text-amber-600 bg-amber-100 dark:bg-amber-900/30", label: "Needs attention" },
  error: { icon: AlertCircle, color: "text-red-600 bg-red-100 dark:bg-red-900/30", label: "Required" },
};

export function SectionSummaryCard({
  id,
  title,
  icon: Icon,
  status,
  statusText,
  isEssential = false,
  aiPriority,
  aiImpactText,
  mode = "general",
  onEdit,
  children,
  className,
  defaultExpanded = false,
  expanded: controlledExpanded,
  onExpandedChange,
  guidanceText,
  guidanceTip,
  whyText,
  whatText,
  tipText,
  usedByAI,
  stepNumber,
}: SectionSummaryCardProps) {
  const [internalExpanded, setInternalExpanded] = useState(defaultExpanded);

  // Use controlled state if provided, otherwise use internal state
  const isExpanded = controlledExpanded !== undefined ? controlledExpanded : internalExpanded;

  const statusConfig = STATUS_CONFIG[status];
  const StatusIcon = statusConfig.icon;

  // Derive AI priority from isEssential if not explicitly provided
  const effectivePriority: FieldPriority | undefined = aiPriority ?? (isEssential ? "required" : undefined);

  const isComplete = status === "complete";

  const toggleExpanded = useCallback(() => {
    const newValue = !isExpanded;
    if (onExpandedChange) {
      onExpandedChange(newValue);
    } else {
      setInternalExpanded(newValue);
    }
  }, [isExpanded, onExpandedChange]);

  // Sync with URL hash for deep linking
  useEffect(() => {
    const hash = window.location.hash.replace("#", "");
    if (hash === id && !isExpanded) {
      if (onExpandedChange) {
        onExpandedChange(true);
      } else {
        setInternalExpanded(true);
      }
      setTimeout(() => {
        const element = document.getElementById(id);
        if (element) {
          element.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      }, 100);
    }
  }, [id, isExpanded, onExpandedChange]);

  // Determine effective guidance: new props take priority over legacy concatenated props
  const effectiveWhatText = whatText || (guidanceText && !whyText ? guidanceText : undefined);
  const effectiveTipText = tipText || guidanceTip;

  return (
    <div
      id={id}
      className={cn(
        "rounded-2xl bg-card transition-all duration-200 shadow-sm",
        isExpanded && "shadow-md",
        className
      )}
    >
      {/* Header - always visible */}
      <div className="flex items-center gap-3 p-4">
        {/* Step number badge (from EssentialGroup) */}
        {stepNumber !== undefined && (
          <div className={cn(
            "flex items-center justify-center h-6 w-6 rounded-full text-xs font-semibold shrink-0",
            isComplete
              ? "bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300"
              : "bg-primary/10 text-primary"
          )}>
            {isComplete ? (
              <Check className="h-3.5 w-3.5" />
            ) : (
              stepNumber
            )}
          </div>
        )}

        <button
          type="button"
          onClick={toggleExpanded}
          className="flex-1 flex items-center gap-3 text-left hover:bg-muted/30 -m-2 p-2 rounded-lg transition-colors"
        >
          <Icon className="h-4 w-4 text-muted-foreground shrink-0" />

          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 flex-wrap">
              <h3 className="font-medium text-sm">{title}</h3>

              {/* Sparkle icon tooltip — replaces jargon "Required for AI" badge */}
              {effectivePriority === "required" && status === "incomplete" && (
                <TooltipProvider delayDuration={200}>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="cursor-help">
                        <Sparkles className="h-3.5 w-3.5 text-amber-500" />
                      </span>
                    </TooltipTrigger>
                    <TooltipContent side="top" className="max-w-xs">
                      <p className="text-xs">
                        {aiImpactText || "Your AI needs this to work properly"}
                      </p>
                    </TooltipContent>
                  </Tooltip>
                </TooltipProvider>
              )}
            </div>
            <p className="text-xs text-muted-foreground truncate mt-0.5">
              {statusText}
            </p>
            {/* Why text — always visible below status, not just when expanded */}
            {whyText && (
              <p className="text-xs text-muted-foreground/80 mt-1 line-clamp-2">
                {whyText}
              </p>
            )}
          </div>
        </button>

        {/* Status Badge */}
        <div className={cn(
          "flex items-center justify-center h-6 w-6 rounded-full shrink-0",
          statusConfig.color
        )}>
          <StatusIcon className="h-3.5 w-3.5" />
        </div>

        {/* Expand indicator via chevron on the clickable header area */}
        <span className="shrink-0 text-muted-foreground">
          {isExpanded ? (
            <ChevronDown className="h-4 w-4" />
          ) : (
            <ChevronRight className="h-4 w-4" />
          )}
        </span>
      </div>

      {/* Content - shown when expanded */}
      {isExpanded && (
        <div className="px-4 pb-4 pt-0">
          <div className="mt-4 space-y-4">
            {children}
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * Business Brain Setup Progress Bar
 * 
 * Visual progress indicator showing:
 * - 6 key setup milestones
 * - Completion computed from loaded values (no API calls)
 * - Click to scroll to relevant section
 */

import { useMemo } from "react";
import { 
  Building2, 
  Clock, 
  Package, 
  MapPin, 
  Shield, 
  Sparkles,
  CheckCircle2,
  Circle,
} from "lucide-react";
import { Progress } from "@/components/ui/progress";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { cn } from "@/lib/utils";

interface SetupMilestone {
  id: string;
  label: string;
  icon: typeof Building2;
  section: string;
  isComplete: boolean;
}

interface SetupProgressBarProps {
  onNavigateToSection: (section: string) => void;
  className?: string;
}

export function SetupProgressBar({ onNavigateToSection, className }: SetupProgressBarProps) {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const caps = useCapabilities();

  const milestones = useMemo<SetupMilestone[]>(() => {
    if (!tenant) return [];

    return [
      {
        id: "identity",
        label: "Identity",
        icon: Building2,
        section: "profile",
        isComplete: Boolean(tenant.name && tenant.timezone),
      },
      {
        id: "hours",
        label: "Hours",
        icon: Clock,
        section: "hours",
        // Check hours_json on tenant
        isComplete: Boolean(tenant.hours_json),
      },
      {
        id: "offerings",
        label: caps.isFoodBusiness ? "Menu" : "Services",
        icon: Package,
        section: "services",
        // Basic check - would ideally count services
        isComplete: false, // Requires separate query
      },
      {
        id: "coverage",
        label: "Coverage",
        icon: MapPin,
        section: "service-area",
        isComplete: Boolean(
          (tenant as Record<string, unknown>).service_area_config_json
        ),
      },
      {
        id: "policies",
        label: "Policies",
        icon: Shield,
        section: "policies",
        isComplete: Boolean(tenant.cancellation_policy),
      },
      {
        id: "ai",
        label: "AI Scripts",
        icon: Sparkles,
        section: "ai-behavior",
        // Basic check for greeting setup
        isComplete: false, // Requires assistant_settings query
      },
    ];
  }, [tenant, businessMode, caps]);

  const completedCount = milestones.filter(m => m.isComplete).length;
  const progressPercent = milestones.length > 0 
    ? Math.round((completedCount / milestones.length) * 100) 
    : 0;

  if (!tenant) return null;

  return (
    <div className={cn("rounded-lg border bg-card/50 p-4", className)}>
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-medium">Setup Progress</h3>
        <span className="text-sm text-muted-foreground">
          {completedCount}/{milestones.length} complete
        </span>
      </div>

      <Progress value={progressPercent} className="h-2 mb-4" />

      <div className="flex flex-wrap gap-2">
        <TooltipProvider>
          {milestones.map((milestone) => {
            const Icon = milestone.icon;
            return (
              <Tooltip key={milestone.id}>
                <TooltipTrigger asChild>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => onNavigateToSection(milestone.section)}
                    className={cn(
                      "gap-1.5 h-8 px-2",
                      milestone.isComplete 
                        ? "text-emerald-600 dark:text-emerald-400" 
                        : "text-muted-foreground"
                    )}
                  >
                    {milestone.isComplete ? (
                      <CheckCircle2 className="h-3.5 w-3.5" />
                    ) : (
                      <Circle className="h-3.5 w-3.5" />
                    )}
                    <span className="text-xs">{milestone.label}</span>
                  </Button>
                </TooltipTrigger>
                <TooltipContent side="bottom">
                  <p>{milestone.isComplete ? "Complete" : "Needs setup"}</p>
                </TooltipContent>
              </Tooltip>
            );
          })}
        </TooltipProvider>
      </div>
    </div>
  );
}

