/**
 * MedicalCoverageEditor - Medical mode coverage and scheduling settings
 * 
 * Manages in-home visits, telehealth regions, and appointment buffers.
 */
import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Loader2,
  Save,
  Home,
  Video,
  Clock,
  Calendar,
  MapPin,
  Stethoscope,
  X,
  Plus,
} from "lucide-react";
import { AIPreviewCard } from "../AIPreviewCard";

interface MedicalCoverageSettings {
  tenant_id: string;
  offers_home_visits: boolean;
  home_visit_radius_miles: number | null;
  home_visit_fee_cents: number;
  home_visit_duration_minutes: number;
  offers_telehealth: boolean;
  telehealth_states: string[];
  telehealth_platforms: string[];
  standard_buffer_minutes: number;
  new_patient_extra_minutes: number;
  procedure_buffer_minutes: number;
  reserves_urgent_slots: boolean;
  urgent_slots_per_day: number;
  accepts_medicare: boolean;
  accepts_medicaid: boolean;
  in_network_insurers: string[];
  out_of_network_policy: string | null;
}

const DEFAULT_SETTINGS: Omit<MedicalCoverageSettings, "tenant_id"> = {
  offers_home_visits: false,
  home_visit_radius_miles: null,
  home_visit_fee_cents: 0,
  home_visit_duration_minutes: 60,
  offers_telehealth: true,
  telehealth_states: [],
  telehealth_platforms: [],
  standard_buffer_minutes: 10,
  new_patient_extra_minutes: 15,
  procedure_buffer_minutes: 30,
  reserves_urgent_slots: true,
  urgent_slots_per_day: 2,
  accepts_medicare: true,
  accepts_medicaid: false,
  in_network_insurers: [],
  out_of_network_policy: null,
};

const US_STATES = [
  "AL", "AK", "AZ", "AR", "CA", "CO", "CT", "DE", "FL", "GA",
  "HI", "ID", "IL", "IN", "IA", "KS", "KY", "LA", "ME", "MD",
  "MA", "MI", "MN", "MS", "MO", "MT", "NE", "NV", "NH", "NJ",
  "NM", "NY", "NC", "ND", "OH", "OK", "OR", "PA", "RI", "SC",
  "SD", "TN", "TX", "UT", "VT", "VA", "WA", "WV", "WI", "WY", "DC"
];

const COMMON_PLATFORMS = ["Zoom", "Doxy.me", "SimplePractice", "Teladoc", "Amwell", "Phone Call"];

export function MedicalCoverageEditor() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const [settings, setSettings] = useState<MedicalCoverageSettings | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);
  const [newState, setNewState] = useState("");
  const [newPlatform, setNewPlatform] = useState("");

  useEffect(() => {
    if (!tenant?.id) return;
    fetchSettings();
  }, [tenant?.id]);

  const fetchSettings = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from("medical_coverage_settings")
        .select("*")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setSettings({
          ...data,
          telehealth_states: (data.telehealth_states as string[]) || [],
          telehealth_platforms: (data.telehealth_platforms as string[]) || [],
          in_network_insurers: (data.in_network_insurers as string[]) || [],
        } as MedicalCoverageSettings);
      } else {
        setSettings({ ...DEFAULT_SETTINGS, tenant_id: tenant.id });
      }
    } catch (err) {
      console.error("Failed to fetch medical coverage settings:", err);
      toast({ title: "Error", description: "Failed to load coverage settings", variant: "destructive" });
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id || !settings) return;
    setIsSaving(true);
    try {
      const { error } = await supabase
        .from("medical_coverage_settings")
        .upsert({ ...settings, tenant_id: tenant.id }, { onConflict: "tenant_id" });

      if (error) throw error;
      toast({ title: "Saved", description: "Coverage settings updated" });
      setHasChanges(false);
    } catch (err) {
      console.error("Failed to save medical coverage settings:", err);
      toast({ title: "Error", description: "Failed to save coverage settings", variant: "destructive" });
    } finally {
      setIsSaving(false);
    }
  };

  const updateSettings = (updates: Partial<MedicalCoverageSettings>) => {
    setSettings(prev => prev ? { ...prev, ...updates } : null);
    setHasChanges(true);
  };

  const addState = (state: string) => {
    if (!state || !settings) return;
    const normalized = state.toUpperCase().trim();
    if (US_STATES.includes(normalized) && !settings.telehealth_states.includes(normalized)) {
      updateSettings({ telehealth_states: [...settings.telehealth_states, normalized] });
    }
    setNewState("");
  };

  const removeState = (state: string) => {
    if (!settings) return;
    updateSettings({ telehealth_states: settings.telehealth_states.filter(s => s !== state) });
  };

  const addPlatform = (platform: string) => {
    if (!platform || !settings) return;
    const trimmed = platform.trim();
    if (!settings.telehealth_platforms.includes(trimmed)) {
      updateSettings({ telehealth_platforms: [...settings.telehealth_platforms, trimmed] });
    }
    setNewPlatform("");
  };

  const removePlatform = (platform: string) => {
    if (!settings) return;
    updateSettings({ telehealth_platforms: settings.telehealth_platforms.filter(p => p !== platform) });
  };

  const formatCurrency = (cents: number) => {
    return new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(cents / 100);
  };

  if (isLoading || !settings) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const generateAIPreview = () => {
    const parts: string[] = [];
    
    if (settings.offers_telehealth && settings.telehealth_states.length > 0) {
      parts.push(`We offer telehealth appointments for patients in ${settings.telehealth_states.slice(0, 3).join(", ")}${settings.telehealth_states.length > 3 ? " and other states" : ""}`);
    }
    
    if (settings.offers_home_visits) {
      const fee = settings.home_visit_fee_cents > 0 
        ? `There's a ${formatCurrency(settings.home_visit_fee_cents)} home visit fee` 
        : "Home visits are available";
      parts.push(fee);
    }
    
    if (settings.reserves_urgent_slots) {
      parts.push(`We do reserve a few same-day slots for urgent needs`);
    }
    
    return parts.length > 0 
      ? parts.join(". ") + "."
      : "Let me check what appointment options are available for you.";
  };

  return (
    <div className="space-y-6">
      <Tabs defaultValue="telehealth" className="w-full">
        <TabsList className="grid grid-cols-3 h-auto">
          <TabsTrigger value="telehealth" className="text-xs py-2">
            <Video className="h-3 w-3 mr-1" />
            Telehealth
          </TabsTrigger>
          <TabsTrigger value="home-visits" className="text-xs py-2">
            <Home className="h-3 w-3 mr-1" />
            Home Visits
          </TabsTrigger>
          <TabsTrigger value="scheduling" className="text-xs py-2">
            <Calendar className="h-3 w-3 mr-1" />
            Scheduling
          </TabsTrigger>
        </TabsList>

        {/* Telehealth Tab */}
        <TabsContent value="telehealth" className="space-y-4 mt-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Video className="h-4 w-4 text-blue-500" />
                Telehealth Services
              </CardTitle>
              <CardDescription>
                Virtual appointment availability and platforms
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-center justify-between p-3 rounded-lg border">
                <div className="space-y-0.5">
                  <Label>Offer telehealth appointments</Label>
                  <p className="text-xs text-muted-foreground">
                    Allow virtual visits for appropriate cases
                  </p>
                </div>
                <Switch
                  checked={settings.offers_telehealth}
                  onCheckedChange={(checked) => updateSettings({ offers_telehealth: checked })}
                />
              </div>

              {settings.offers_telehealth && (
                <>
                  <div className="space-y-2">
                    <Label>Licensed states for telehealth</Label>
                    <p className="text-xs text-muted-foreground">
                      States where you're licensed to provide virtual care
                    </p>
                    <div className="flex flex-wrap gap-2 mb-2">
                      {settings.telehealth_states.map((state) => (
                        <Badge key={state} variant="secondary" className="gap-1 pr-1">
                          {state}
                          <button
                            type="button"
                            onClick={() => removeState(state)}
                            className="ml-1 hover:bg-white/20 rounded-full p-0.5"
                          >
                            <X className="h-3 w-3" />
                          </button>
                        </Badge>
                      ))}
                    </div>
                    <div className="flex gap-2">
                      <Input
                        value={newState}
                        onChange={(e) => setNewState(e.target.value.toUpperCase())}
                        onKeyDown={(e) => e.key === "Enter" && (e.preventDefault(), addState(newState))}
                        placeholder="Enter state code (e.g., CA)"
                        maxLength={2}
                        className="w-32"
                      />
                      <Button type="button" variant="outline" size="icon" onClick={() => addState(newState)}>
                        <Plus className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>

                  <Separator />

                  <div className="space-y-2">
                    <Label>Telehealth platforms</Label>
                    <div className="flex flex-wrap gap-2 mb-2">
                      {settings.telehealth_platforms.map((platform) => (
                        <Badge key={platform} variant="outline" className="gap-1 pr-1">
                          {platform}
                          <button
                            type="button"
                            onClick={() => removePlatform(platform)}
                            className="ml-1 hover:bg-muted rounded-full p-0.5"
                          >
                            <X className="h-3 w-3" />
                          </button>
                        </Badge>
                      ))}
                    </div>
                    <div className="flex flex-wrap gap-2">
                      {COMMON_PLATFORMS.filter(p => !settings.telehealth_platforms.includes(p)).map((platform) => (
                        <Button
                          key={platform}
                          type="button"
                          variant="ghost"
                          size="sm"
                          className="h-7 text-xs"
                          onClick={() => addPlatform(platform)}
                        >
                          <Plus className="h-3 w-3 mr-1" />
                          {platform}
                        </Button>
                      ))}
                    </div>
                  </div>
                </>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Home Visits Tab */}
        <TabsContent value="home-visits" className="space-y-4 mt-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Home className="h-4 w-4 text-green-500" />
                In-Home Visits
              </CardTitle>
              <CardDescription>
                Home visit availability and pricing
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-center justify-between p-3 rounded-lg border">
                <div className="space-y-0.5">
                  <Label>Offer home visits</Label>
                  <p className="text-xs text-muted-foreground">
                    Provide in-home care for eligible patients
                  </p>
                </div>
                <Switch
                  checked={settings.offers_home_visits}
                  onCheckedChange={(checked) => updateSettings({ offers_home_visits: checked })}
                />
              </div>

              {settings.offers_home_visits && (
                <>
                  <div className="grid gap-4 sm:grid-cols-2">
                    <div className="space-y-2">
                      <Label>Home visit radius (miles)</Label>
                      <Input
                        type="number"
                        min="1"
                        value={settings.home_visit_radius_miles ?? ""}
                        onChange={(e) => updateSettings({ 
                          home_visit_radius_miles: e.target.value ? parseFloat(e.target.value) : null 
                        })}
                        placeholder="e.g., 15"
                      />
                    </div>

                    <div className="space-y-2">
                      <Label>Home visit fee ($)</Label>
                      <Input
                        type="number"
                        min="0"
                        step="0.01"
                        value={settings.home_visit_fee_cents / 100}
                        onChange={(e) => updateSettings({ 
                          home_visit_fee_cents: Math.round(parseFloat(e.target.value || "0") * 100) 
                        })}
                      />
                    </div>
                  </div>

                  <div className="space-y-2">
                    <Label>Default home visit duration (minutes)</Label>
                    <Input
                      type="number"
                      min="15"
                      step="15"
                      value={settings.home_visit_duration_minutes}
                      onChange={(e) => updateSettings({ 
                        home_visit_duration_minutes: parseInt(e.target.value) || 60 
                      })}
                      className="w-32"
                    />
                  </div>
                </>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Scheduling Tab */}
        <TabsContent value="scheduling" className="space-y-4 mt-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Clock className="h-4 w-4 text-purple-500" />
                Appointment Buffers
              </CardTitle>
              <CardDescription>
                Time between appointments for different scenarios
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid gap-4 sm:grid-cols-3">
                <div className="space-y-2">
                  <Label>Standard buffer</Label>
                  <Input
                    type="number"
                    min="0"
                    step="5"
                    value={settings.standard_buffer_minutes}
                    onChange={(e) => updateSettings({ 
                      standard_buffer_minutes: parseInt(e.target.value) || 10 
                    })}
                    className="w-24"
                  />
                  <p className="text-xs text-muted-foreground">Between appointments</p>
                </div>

                <div className="space-y-2">
                  <Label>New patient extra</Label>
                  <Input
                    type="number"
                    min="0"
                    step="5"
                    value={settings.new_patient_extra_minutes}
                    onChange={(e) => updateSettings({ 
                      new_patient_extra_minutes: parseInt(e.target.value) || 15 
                    })}
                    className="w-24"
                  />
                  <p className="text-xs text-muted-foreground">Added for new patients</p>
                </div>

                <div className="space-y-2">
                  <Label>Procedure buffer</Label>
                  <Input
                    type="number"
                    min="0"
                    step="5"
                    value={settings.procedure_buffer_minutes}
                    onChange={(e) => updateSettings({ 
                      procedure_buffer_minutes: parseInt(e.target.value) || 30 
                    })}
                    className="w-24"
                  />
                  <p className="text-xs text-muted-foreground">After procedures</p>
                </div>
              </div>

              <Separator />

              <div className="flex items-center justify-between p-3 rounded-lg border">
                <div className="space-y-0.5">
                  <Label>Reserve same-day urgent slots</Label>
                  <p className="text-xs text-muted-foreground">
                    Keep slots open for urgent cases
                  </p>
                </div>
                <Switch
                  checked={settings.reserves_urgent_slots}
                  onCheckedChange={(checked) => updateSettings({ reserves_urgent_slots: checked })}
                />
              </div>

              {settings.reserves_urgent_slots && (
                <div className="space-y-2">
                  <Label>Urgent slots per day</Label>
                  <Input
                    type="number"
                    min="1"
                    max="10"
                    value={settings.urgent_slots_per_day}
                    onChange={(e) => updateSettings({ 
                      urgent_slots_per_day: parseInt(e.target.value) || 2 
                    })}
                    className="w-24"
                  />
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* AI Preview */}
      <AIPreviewCard 
        title="AI will say something like:" 
        preview={generateAIPreview()} 
      />

      {/* Save Button */}
      <div className="flex justify-end">
        <Button onClick={handleSave} disabled={isSaving || !hasChanges}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Settings
        </Button>
      </div>
    </div>
  );
}

/**
 * Medical Policies Editor
 * For clinics, practices, telehealth
 * Handles appointments, insurance, consent, prescriptions, and patient rights
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, Save, Calendar, CreditCard, FileText, Pill, FolderOpen, Clock, Heart } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { AIPreviewCard } from "../AIPreviewCard";

interface MedicalPolicies {
  id?: string;
  tenant_id: string;
  // Appointments
  appointment_no_show_fee_cents: number;
  appointment_late_arrival_minutes: number;
  appointment_late_reschedule: boolean;
  cancellation_notice_hours: number;
  cancellation_fee_cents: number;
  new_patient_arrival_minutes: number;
  // Insurance & billing
  insurance_verification_required: boolean;
  insurance_verification_days_before: number;
  out_of_network_disclosure: string;
  balance_due_policy: string;
  payment_plan_available: boolean;
  payment_plan_minimum_cents: number;
  collections_notice: string;
  // Forms & consent
  hipaa_consent_required: boolean;
  treatment_consent_required: boolean;
  financial_agreement_required: boolean;
  minor_consent_policy: string;
  telehealth_consent_required: boolean;
  // Prescriptions
  prescription_refill_notice_days: number;
  prescription_refill_appointment_required: boolean;
  controlled_substance_policy: string;
  // Records
  records_request_fee_cents: number;
  records_request_processing_days: number;
  records_release_form_required: boolean;
  // After hours
  after_hours_contact_policy: string;
  emergency_protocol: string;
  hospital_affiliation: string;
  // Patient rights
  patient_rights_summary: string;
  complaint_procedure: string;
}

const DEFAULT_POLICIES: Omit<MedicalPolicies, 'tenant_id'> = {
  appointment_no_show_fee_cents: 5000,
  appointment_late_arrival_minutes: 15,
  appointment_late_reschedule: true,
  cancellation_notice_hours: 24,
  cancellation_fee_cents: 2500,
  new_patient_arrival_minutes: 15,
  insurance_verification_required: true,
  insurance_verification_days_before: 2,
  out_of_network_disclosure: '',
  balance_due_policy: '',
  payment_plan_available: true,
  payment_plan_minimum_cents: 5000,
  collections_notice: '',
  hipaa_consent_required: true,
  treatment_consent_required: true,
  financial_agreement_required: true,
  minor_consent_policy: '',
  telehealth_consent_required: true,
  prescription_refill_notice_days: 5,
  prescription_refill_appointment_required: false,
  controlled_substance_policy: '',
  records_request_fee_cents: 2500,
  records_request_processing_days: 14,
  records_release_form_required: true,
  after_hours_contact_policy: '',
  emergency_protocol: '',
  hospital_affiliation: '',
  patient_rights_summary: '',
  complaint_procedure: '',
};

export function MedicalPoliciesEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState<MedicalPolicies | null>(null);

  useEffect(() => {
    if (tenant?.id) {
      loadPolicies();
    }
  }, [tenant?.id]);

  const loadPolicies = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('medical_policies')
        .select('*')
        .eq('tenant_id', tenant.id)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') throw error;
      
      setFormData(data || { ...DEFAULT_POLICIES, tenant_id: tenant.id });
    } catch (err: any) {
      toast.error("Failed to load policies");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id || !formData) return;
    setIsSaving(true);
    try {
      const { error } = await supabase
        .from('medical_policies')
        .upsert({
          ...formData,
          tenant_id: tenant.id,
        }, { onConflict: 'tenant_id' });

      if (error) throw error;
      toast.success("Policies saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const updateField = <K extends keyof MedicalPolicies>(field: K, value: MedicalPolicies[K]) => {
    setFormData(prev => prev ? { ...prev, [field]: value } : null);
  };

  const formatCents = (cents: number) => cents > 0 ? `$${(cents / 100).toFixed(0)}` : 'No fee';

  // Build AI preview
  const buildAIPreview = (): string => {
    if (!formData) return "";
    const parts: string[] = [];
    
    if (formData.cancellation_notice_hours > 0) {
      parts.push(`Please give us ${formData.cancellation_notice_hours} hours notice to reschedule.`);
    }
    if (formData.new_patient_arrival_minutes > 0) {
      parts.push(`New patients should arrive ${formData.new_patient_arrival_minutes} minutes early.`);
    }
    if (formData.insurance_verification_required) {
      parts.push("We verify insurance before your visit.");
    }
    
    return parts.length > 0 ? parts.join(' ') : "No specific medical policies configured yet.";
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!formData) return null;

  return (
    <div className="space-y-6">
      {/* AI Preview */}
      <AIPreviewCard 
        title="How AI explains your practice policies"
        preview={buildAIPreview()}
      />

      {/* Appointment Policies */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Calendar className="h-4 w-4" />
            Appointment Policies
          </CardTitle>
          <CardDescription>
            Scheduling, cancellations, and no-shows
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>No-Show Fee</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.appointment_no_show_fee_cents / 100}
                  onChange={(e) => updateField('appointment_no_show_fee_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Cancellation Fee</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.cancellation_fee_cents / 100}
                  onChange={(e) => updateField('cancellation_fee_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                />
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Cancellation Notice Required</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.cancellation_notice_hours}
                  onChange={(e) => updateField('cancellation_notice_hours', parseInt(e.target.value || '0'))}
                />
                <span className="flex items-center text-sm text-muted-foreground">hours</span>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Late Arrival Grace Period</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.appointment_late_arrival_minutes}
                  onChange={(e) => updateField('appointment_late_arrival_minutes', parseInt(e.target.value || '0'))}
                />
                <span className="flex items-center text-sm text-muted-foreground">min</span>
              </div>
            </div>
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Reschedule Late Arrivals</Label>
              <p className="text-xs text-muted-foreground">Require rescheduling if patient arrives late</p>
            </div>
            <Switch
              checked={formData.appointment_late_reschedule}
              onCheckedChange={(v) => updateField('appointment_late_reschedule', v)}
            />
          </div>

          <div className="space-y-2">
            <Label>New Patient Early Arrival</Label>
            <div className="flex gap-2 items-center">
              <Input
                type="number"
                className="w-24"
                value={formData.new_patient_arrival_minutes}
                onChange={(e) => updateField('new_patient_arrival_minutes', parseInt(e.target.value || '0'))}
              />
              <span className="text-sm text-muted-foreground">minutes before appointment</span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Insurance & Billing */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <CreditCard className="h-4 w-4" />
            Insurance & Billing
          </CardTitle>
          <CardDescription>
            Payment, insurance, and billing policies
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <Label>Insurance Verification Required</Label>
              <p className="text-xs text-muted-foreground">Verify coverage before appointments</p>
            </div>
            <Switch
              checked={formData.insurance_verification_required}
              onCheckedChange={(v) => updateField('insurance_verification_required', v)}
            />
          </div>

          {formData.insurance_verification_required && (
            <div className="space-y-2">
              <Label>Verify Coverage</Label>
              <div className="flex gap-2 items-center">
                <Input
                  type="number"
                  className="w-24"
                  value={formData.insurance_verification_days_before}
                  onChange={(e) => updateField('insurance_verification_days_before', parseInt(e.target.value || '0'))}
                />
                <span className="text-sm text-muted-foreground">days before appointment</span>
              </div>
            </div>
          )}

          <div className="space-y-2">
            <Label>Out-of-Network Disclosure</Label>
            <Textarea
              value={formData.out_of_network_disclosure}
              onChange={(e) => updateField('out_of_network_disclosure', e.target.value)}
              placeholder="We are out-of-network with some insurance plans. You may have out-of-pocket costs that can be submitted to your insurance for reimbursement."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Balance Due Policy</Label>
            <Textarea
              value={formData.balance_due_policy}
              onChange={(e) => updateField('balance_due_policy', e.target.value)}
              placeholder="Copays and deductibles are due at time of service. Outstanding balances are due within 30 days."
              rows={2}
            />
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Payment Plans Available</Label>
              <p className="text-xs text-muted-foreground">Offer payment plans for large balances</p>
            </div>
            <Switch
              checked={formData.payment_plan_available}
              onCheckedChange={(v) => updateField('payment_plan_available', v)}
            />
          </div>

          {formData.payment_plan_available && (
            <div className="space-y-2">
              <Label>Minimum Balance for Payment Plan</Label>
              <div className="relative w-40">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.payment_plan_minimum_cents / 100}
                  onChange={(e) => updateField('payment_plan_minimum_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                />
              </div>
            </div>
          )}

          <div className="space-y-2">
            <Label>Collections Notice</Label>
            <Textarea
              value={formData.collections_notice}
              onChange={(e) => updateField('collections_notice', e.target.value)}
              placeholder="Accounts past due 90 days may be referred to collections."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Forms & Consent */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <FileText className="h-4 w-4" />
            Forms & Consent
          </CardTitle>
          <CardDescription>
            Required forms and consent documents
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <label className="flex items-center gap-2 cursor-pointer">
              <Switch
                checked={formData.hipaa_consent_required}
                onCheckedChange={(v) => updateField('hipaa_consent_required', v)}
              />
              <span className="text-sm">HIPAA Consent Required</span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer">
              <Switch
                checked={formData.treatment_consent_required}
                onCheckedChange={(v) => updateField('treatment_consent_required', v)}
              />
              <span className="text-sm">Treatment Consent Required</span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer">
              <Switch
                checked={formData.financial_agreement_required}
                onCheckedChange={(v) => updateField('financial_agreement_required', v)}
              />
              <span className="text-sm">Financial Agreement Required</span>
            </label>

            <label className="flex items-center gap-2 cursor-pointer">
              <Switch
                checked={formData.telehealth_consent_required}
                onCheckedChange={(v) => updateField('telehealth_consent_required', v)}
              />
              <span className="text-sm">Telehealth Consent Required</span>
            </label>
          </div>

          <div className="space-y-2">
            <Label>Minor Consent Policy</Label>
            <Textarea
              value={formData.minor_consent_policy}
              onChange={(e) => updateField('minor_consent_policy', e.target.value)}
              placeholder="Patients under 18 must have a parent or legal guardian present for treatment, except in emergency situations."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Prescriptions */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Pill className="h-4 w-4" />
            Prescriptions
          </CardTitle>
          <CardDescription>
            Medication refill and controlled substance policies
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Refill Notice Required</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.prescription_refill_notice_days}
                  onChange={(e) => updateField('prescription_refill_notice_days', parseInt(e.target.value || '0'))}
                />
                <span className="flex items-center text-sm text-muted-foreground">days</span>
              </div>
            </div>
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Appointment Required for Refills</Label>
              <p className="text-xs text-muted-foreground">Some medications require an office visit</p>
            </div>
            <Switch
              checked={formData.prescription_refill_appointment_required}
              onCheckedChange={(v) => updateField('prescription_refill_appointment_required', v)}
            />
          </div>

          <div className="space-y-2">
            <Label>Controlled Substance Policy</Label>
            <Textarea
              value={formData.controlled_substance_policy}
              onChange={(e) => updateField('controlled_substance_policy', e.target.value)}
              placeholder="Controlled substances require in-person appointments. Early refills are not permitted. Lost prescriptions cannot be replaced."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Medical Records */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <FolderOpen className="h-4 w-4" />
            Medical Records
          </CardTitle>
          <CardDescription>
            Records requests and release policies
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Records Request Fee</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.records_request_fee_cents / 100}
                  onChange={(e) => updateField('records_request_fee_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Processing Time</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.records_request_processing_days}
                  onChange={(e) => updateField('records_request_processing_days', parseInt(e.target.value || '0'))}
                />
                <span className="flex items-center text-sm text-muted-foreground">days</span>
              </div>
            </div>
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Release Form Required</Label>
              <p className="text-xs text-muted-foreground">Written authorization needed for records release</p>
            </div>
            <Switch
              checked={formData.records_release_form_required}
              onCheckedChange={(v) => updateField('records_release_form_required', v)}
            />
          </div>
        </CardContent>
      </Card>

      {/* After Hours & Emergency */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Clock className="h-4 w-4" />
            After Hours & Emergency
          </CardTitle>
          <CardDescription>
            Emergency protocols and after-hours contact
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>After-Hours Contact Policy</Label>
            <Textarea
              value={formData.after_hours_contact_policy}
              onChange={(e) => updateField('after_hours_contact_policy', e.target.value)}
              placeholder="For urgent matters after hours, call our main number and follow the prompts for the on-call provider. For emergencies, call 911."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Emergency Protocol</Label>
            <Textarea
              value={formData.emergency_protocol}
              onChange={(e) => updateField('emergency_protocol', e.target.value)}
              placeholder="For life-threatening emergencies, call 911 immediately. Do not wait to contact our office."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Hospital Affiliation</Label>
            <Textarea
              value={formData.hospital_affiliation}
              onChange={(e) => updateField('hospital_affiliation', e.target.value)}
              placeholder="We have privileges at City General Hospital and can arrange admissions if needed."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Patient Rights */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Heart className="h-4 w-4" />
            Patient Rights
          </CardTitle>
          <CardDescription>
            Rights and complaint procedures
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Patient Rights Summary</Label>
            <Textarea
              value={formData.patient_rights_summary}
              onChange={(e) => updateField('patient_rights_summary', e.target.value)}
              placeholder="You have the right to be treated with respect, understand your diagnosis and treatment options, and access your medical records."
              rows={3}
            />
          </div>

          <div className="space-y-2">
            <Label>Complaint Procedure</Label>
            <Textarea
              value={formData.complaint_procedure}
              onChange={(e) => updateField('complaint_procedure', e.target.value)}
              placeholder="If you have concerns about your care, please speak with our office manager. You may also file a complaint with the State Medical Board."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end pt-2">
        <Button onClick={handleSave} disabled={isSaving}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Medical Policies
        </Button>
      </div>
    </div>
  );
}

/**
 * Medical Pricing Editor
 * 
 * Comprehensive pricing for medical practices:
 * - Insurance accepted
 * - Self-pay/cash rates
 * - Consultation fees (new vs returning)
 * - Series/package discounts
 * - Telehealth pricing
 */

import { useState, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Textarea } from "@/components/ui/textarea";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import {
  Loader2,
  Info,
  Lightbulb,
  CreditCard,
  ShieldCheck,
  Users,
  Stethoscope,
  Plus,
  X,
  FileText,
} from "lucide-react";
import { toast } from "sonner";

interface MedicalPracticeSettings {
  tenant_id: string;
  accepts_insurance: boolean;
  accepted_insurance_carriers: string[];
  insurance_notes: string | null;
  new_patient_fee_cents: number | null;
  follow_up_fee_cents: number | null;
  consultation_fee_cents: number | null;
  waive_consultation_with_treatment: boolean;
  series_discount_percent: number | null;
  requires_consent_form: boolean;
  requires_medical_history: boolean;
}

const COMMON_INSURANCE_CARRIERS = [
  "Aetna",
  "Anthem Blue Cross",
  "Blue Cross Blue Shield",
  "Cigna",
  "Humana",
  "Kaiser Permanente",
  "Medicare",
  "Medicaid",
  "UnitedHealthcare",
  "Tricare",
];

const defaultSettings: Partial<MedicalPracticeSettings> = {
  accepts_insurance: true,
  accepted_insurance_carriers: [],
  new_patient_fee_cents: 15000,
  follow_up_fee_cents: 7500,
  consultation_fee_cents: 5000,
  waive_consultation_with_treatment: true,
  series_discount_percent: 15,
  requires_consent_form: true,
  requires_medical_history: true,
};

export function MedicalPricingEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  const [activeTab, setActiveTab] = useState("insurance");
  const [isSaving, setIsSaving] = useState(false);
  const [localSettings, setLocalSettings] = useState<Partial<MedicalPracticeSettings>>({});
  const [newCarrier, setNewCarrier] = useState("");

  // Fetch settings
  const { data: settings, isLoading } = useQuery({
    queryKey: ["medical-practice-settings", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data, error } = await supabase
        .from("medical_practice_settings")
        .select("*")
        .eq("tenant_id", tenant.id)
        .single();
      if (error && error.code !== "PGRST116") throw error;
      return data as MedicalPracticeSettings | null;
    },
    enabled: !!tenant?.id,
  });

  // Merge fetched with local edits
  const effectiveSettings = useMemo(() => ({
    ...defaultSettings,
    ...settings,
    ...localSettings,
  }), [settings, localSettings]);

  const updateSetting = <K extends keyof MedicalPracticeSettings>(key: K, value: MedicalPracticeSettings[K]) => {
    setLocalSettings(prev => ({ ...prev, [key]: value }));
  };

  const addCarrier = (carrier: string) => {
    if (!carrier.trim()) return;
    const current = effectiveSettings.accepted_insurance_carriers || [];
    if (!current.includes(carrier.trim())) {
      updateSetting("accepted_insurance_carriers", [...current, carrier.trim()]);
    }
    setNewCarrier("");
  };

  const removeCarrier = (carrier: string) => {
    const current = effectiveSettings.accepted_insurance_carriers || [];
    updateSetting("accepted_insurance_carriers", current.filter(c => c !== carrier));
  };

  const handleSave = async () => {
    if (!tenant?.id) return;

    setIsSaving(true);
    try {
      const payload = {
        tenant_id: tenant.id,
        ...effectiveSettings,
      };

      const { error } = await supabase
        .from("medical_practice_settings")
        .upsert(payload, { onConflict: "tenant_id" });

      if (error) throw error;

      toast.success("Settings saved");
      queryClient.invalidateQueries({ queryKey: ["medical-practice-settings"] });
      setLocalSettings({});
    } catch (error: any) {
      toast.error(error.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const hasChanges = Object.keys(localSettings).length > 0;

  // AI Preview
  const aiPreview = useMemo(() => {
    const parts: string[] = [];

    if (effectiveSettings.accepts_insurance) {
      const carriers = effectiveSettings.accepted_insurance_carriers || [];
      if (carriers.length > 0) {
        parts.push(`We accept ${carriers.slice(0, 3).join(", ")}${carriers.length > 3 ? ` and ${carriers.length - 3} more` : ""}`);
      } else {
        parts.push("We accept most major insurance");
      }
    } else {
      parts.push("We're a self-pay practice");
    }

    if (effectiveSettings.new_patient_fee_cents) {
      parts.push(`A new patient visit is $${(effectiveSettings.new_patient_fee_cents / 100).toFixed(0)}`);
    }

    if (effectiveSettings.waive_consultation_with_treatment) {
      parts.push("and we waive the consultation fee if you proceed with treatment");
    }

    return parts.join(". ") + ".";
  }, [effectiveSettings]);

  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <Loader2 className="h-6 w-6 animate-spin text-primary" />
            <span className="ml-3 text-sm text-muted-foreground">Loading settings...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Explanation */}
      <div className="rounded-lg border bg-muted/30 p-4">
        <div className="flex items-start gap-3">
          <Info className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div className="space-y-2">
            <p className="text-sm font-medium">What is this?</p>
            <p className="text-sm text-muted-foreground">
              Configure your practice's pricing and insurance information. 
              Your AI will use this to answer cost questions and explain payment options to patients.
            </p>
          </div>
        </div>
      </div>

      {/* AI Preview */}
      <div className="rounded-lg border bg-primary/5 border-primary/20 p-4">
        <div className="flex items-start gap-3">
          <Stethoscope className="h-5 w-5 text-primary shrink-0 mt-0.5" />
          <div>
            <p className="text-sm font-medium text-primary mb-1">What the AI tells patients</p>
            <p className="text-sm italic">"{aiPreview}"</p>
          </div>
        </div>
      </div>

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="grid grid-cols-3 h-auto">
          <TabsTrigger value="insurance" className="text-xs py-2">
            <ShieldCheck className="h-3.5 w-3.5 mr-1" />
            Insurance
          </TabsTrigger>
          <TabsTrigger value="pricing" className="text-xs py-2">
            <CreditCard className="h-3.5 w-3.5 mr-1" />
            Pricing
          </TabsTrigger>
          <TabsTrigger value="requirements" className="text-xs py-2">
            <FileText className="h-3.5 w-3.5 mr-1" />
            Requirements
          </TabsTrigger>
        </TabsList>

        {/* Insurance Settings */}
        <TabsContent value="insurance" className="mt-4 space-y-4">
          <Card>
            <CardContent className="p-4 space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="font-medium">Accept Insurance</h4>
                  <p className="text-sm text-muted-foreground">Do you bill insurance carriers?</p>
                </div>
                <Switch
                  checked={effectiveSettings.accepts_insurance}
                  onCheckedChange={(v) => updateSetting("accepts_insurance", v)}
                />
              </div>

              {effectiveSettings.accepts_insurance && (
                <div className="space-y-4 pt-4 border-t">
                  <div className="space-y-2">
                    <Label className="text-sm">Accepted Carriers</Label>
                    <div className="flex flex-wrap gap-2">
                      {(effectiveSettings.accepted_insurance_carriers || []).map(carrier => (
                        <Badge key={carrier} variant="secondary" className="gap-1 pr-1">
                          {carrier}
                          <button
                            onClick={() => removeCarrier(carrier)}
                            className="ml-1 hover:text-destructive"
                          >
                            <X className="h-3 w-3" />
                          </button>
                        </Badge>
                      ))}
                    </div>
                  </div>

                  <div className="space-y-2">
                    <Label className="text-xs">Quick Add Common Carriers</Label>
                    <div className="flex flex-wrap gap-1">
                      {COMMON_INSURANCE_CARRIERS
                        .filter(c => !(effectiveSettings.accepted_insurance_carriers || []).includes(c))
                        .map(carrier => (
                          <Button
                            key={carrier}
                            variant="outline"
                            size="sm"
                            className="text-xs h-7"
                            onClick={() => addCarrier(carrier)}
                          >
                            <Plus className="h-3 w-3 mr-1" />
                            {carrier}
                          </Button>
                        ))}
                    </div>
                  </div>

                  <div className="flex gap-2">
                    <Input
                      value={newCarrier}
                      onChange={(e) => setNewCarrier(e.target.value)}
                      placeholder="Add custom carrier..."
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault();
                          addCarrier(newCarrier);
                        }
                      }}
                    />
                    <Button onClick={() => addCarrier(newCarrier)} disabled={!newCarrier.trim()}>
                      Add
                    </Button>
                  </div>

                  <div className="space-y-2">
                    <Label className="text-sm">Insurance Notes</Label>
                    <Textarea
                      value={effectiveSettings.insurance_notes || ""}
                      onChange={(e) => updateSetting("insurance_notes", e.target.value || null)}
                      placeholder="Any special notes about insurance (e.g., 'We verify benefits before your visit')"
                      rows={2}
                    />
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Pricing Settings */}
        <TabsContent value="pricing" className="mt-4 space-y-4">
          <Card>
            <CardContent className="p-4 space-y-4">
              <h4 className="font-medium">Self-Pay / Cash Rates</h4>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                <div className="space-y-2">
                  <Label className="text-sm">New Patient Visit</Label>
                  <div className="flex items-center gap-2">
                    <span className="text-sm text-muted-foreground">$</span>
                    <Input
                      type="number"
                      min="0"
                      step="25"
                      value={(effectiveSettings.new_patient_fee_cents || 0) / 100}
                      onChange={(e) => updateSetting("new_patient_fee_cents", Math.round(parseFloat(e.target.value) * 100) || null)}
                      className="w-28"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label className="text-sm">Follow-Up Visit</Label>
                  <div className="flex items-center gap-2">
                    <span className="text-sm text-muted-foreground">$</span>
                    <Input
                      type="number"
                      min="0"
                      step="25"
                      value={(effectiveSettings.follow_up_fee_cents || 0) / 100}
                      onChange={(e) => updateSetting("follow_up_fee_cents", Math.round(parseFloat(e.target.value) * 100) || null)}
                      className="w-28"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label className="text-sm">Consultation Fee</Label>
                  <div className="flex items-center gap-2">
                    <span className="text-sm text-muted-foreground">$</span>
                    <Input
                      type="number"
                      min="0"
                      step="25"
                      value={(effectiveSettings.consultation_fee_cents || 0) / 100}
                      onChange={(e) => updateSetting("consultation_fee_cents", Math.round(parseFloat(e.target.value) * 100) || null)}
                      className="w-28"
                    />
                  </div>
                </div>
              </div>

              <div className="flex items-center justify-between pt-4 border-t">
                <div>
                  <Label className="text-sm">Waive Consultation with Treatment</Label>
                  <p className="text-xs text-muted-foreground">
                    Apply consultation fee toward treatment if patient proceeds
                  </p>
                </div>
                <Switch
                  checked={effectiveSettings.waive_consultation_with_treatment}
                  onCheckedChange={(v) => updateSetting("waive_consultation_with_treatment", v)}
                />
              </div>

              <div className="pt-4 border-t space-y-2">
                <Label className="text-sm">Series/Package Discount</Label>
                <div className="flex items-center gap-2">
                  <Input
                    type="number"
                    min="0"
                    max="50"
                    value={effectiveSettings.series_discount_percent || 0}
                    onChange={(e) => updateSetting("series_discount_percent", parseInt(e.target.value) || null)}
                    className="w-20"
                  />
                  <span className="text-sm text-muted-foreground">% off for treatment packages</span>
                </div>
                <p className="text-xs text-muted-foreground">
                  Discount applied when patients purchase a series of treatments
                </p>
              </div>

              <div className="flex items-start gap-2 p-3 rounded-lg bg-warning/10 border border-warning/20">
                <Lightbulb className="h-4 w-4 text-warning shrink-0 mt-0.5" />
                <p className="text-xs text-muted-foreground">
                  These are self-pay rates. Insurance rates are typically negotiated separately. 
                  The AI will mention these to uninsured patients or when asked about costs.
                </p>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Requirements Settings */}
        <TabsContent value="requirements" className="mt-4 space-y-4">
          <Card>
            <CardContent className="p-4 space-y-4">
              <h4 className="font-medium">Patient Requirements</h4>

              <div className="space-y-3">
                <div className="flex items-center justify-between p-3 rounded-lg border">
                  <div>
                    <p className="text-sm font-medium">Consent Form Required</p>
                    <p className="text-xs text-muted-foreground">
                      Patients must sign consent before treatment
                    </p>
                  </div>
                  <Switch
                    checked={effectiveSettings.requires_consent_form}
                    onCheckedChange={(v) => updateSetting("requires_consent_form", v)}
                  />
                </div>

                <div className="flex items-center justify-between p-3 rounded-lg border">
                  <div>
                    <p className="text-sm font-medium">Medical History Required</p>
                    <p className="text-xs text-muted-foreground">
                      New patients must complete health history
                    </p>
                  </div>
                  <Switch
                    checked={effectiveSettings.requires_medical_history}
                    onCheckedChange={(v) => updateSetting("requires_medical_history", v)}
                  />
                </div>
              </div>

              <div className="flex items-start gap-2 p-3 rounded-lg bg-info/10 border border-info/20">
                <Info className="h-4 w-4 text-info shrink-0 mt-0.5" />
                <p className="text-xs text-muted-foreground">
                  The AI will inform new patients about these requirements when they book 
                  and remind them to arrive early to complete paperwork.
                </p>
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* Save button */}
      {hasChanges && (
        <div className="flex justify-end sticky bottom-4">
          <Button onClick={handleSave} disabled={isSaving}>
            {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
            Save Changes
          </Button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import { Loader2, Save } from "lucide-react";
import { updateBusinessProfile } from "@/lib/brain/writeBrainFact";
import { invalidateBrainQueries } from "@/lib/brain/invalidateBrainQueries";
import { supabase } from "@/integrations/supabase/client";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { PreviewSentence } from "../layout/BusinessBrainSectionCard";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { getProfileExamples } from "@/lib/industryExamples";

const TIMEZONES = [
  { value: "America/New_York", label: "Eastern Time (ET)" },
  { value: "America/Chicago", label: "Central Time (CT)" },
  { value: "America/Denver", label: "Mountain Time (MT)" },
  { value: "America/Los_Angeles", label: "Pacific Time (PT)" },
  { value: "America/Anchorage", label: "Alaska Time (AKT)" },
  { value: "Pacific/Honolulu", label: "Hawaii Time (HT)" },
];

function parseAddressComponents(address: string): {
  line1: string;
  city: string;
  state: string;
  zip: string;
} {
  if (!address) return { line1: "", city: "", state: "", zip: "" };
  const parts = address.split(",").map((p) => p.trim());
  if (parts.length >= 3) {
    const stateZipPart = parts[parts.length - 1];
    const stateZipMatch = stateZipPart.match(/^([A-Z]{2})\s+(\d{5}(?:-\d{4})?)$/i);
    if (stateZipMatch) {
      return {
        line1: parts.slice(0, -2).join(", "),
        city: parts[parts.length - 2],
        state: stateZipMatch[1].toUpperCase(),
        zip: stateZipMatch[2],
      };
    }
    return { line1: parts[0], city: parts[1], state: parts.slice(2).join(", "), zip: "" };
  }
  if (parts.length === 2) return { line1: parts[0], city: parts[1], state: "", zip: "" };
  return { line1: address, city: "", state: "", zip: "" };
}

function combineAddress(components: { line1: string; city: string; state: string; zip: string }): string {
  const { line1, city, state, zip } = components;
  const parts: string[] = [];
  if (line1) parts.push(line1);
  if (city) parts.push(city);
  if (state && zip) parts.push(`${state} ${zip}`);
  else if (state) parts.push(state);
  else if (zip) parts.push(zip);
  return parts.join(", ");
}

export function BusinessProfileEditor() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const queryClient = useQueryClient();
  
  const examples = getProfileExamples(businessMode);

  const [formData, setFormData] = useState({
    name: "",
    tagline: "",
    phone_public: "",
    timezone: "",
    website_url: "",
    years_in_business: "",
    address_line1: "",
    address_city: "",
    address_state: "",
    address_zip: "",
  });
  const [isSaving, setIsSaving] = useState(false);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    if (tenant) {
      const addressComponents = parseAddressComponents(tenant.address || "");
      setFormData({
        name: tenant.name || "",
        tagline: tenant.tagline || "",
        phone_public: tenant.phone_public || "",
        timezone: tenant.timezone || "America/New_York",
        website_url: tenant.website_url || "",
        years_in_business: tenant.years_in_business?.toString() || "",
        address_line1: addressComponents.line1,
        address_city: addressComponents.city,
        address_state: addressComponents.state,
        address_zip: addressComponents.zip,
      });
      setIsLoading(false);
    }
  }, [tenant]);

  const handleSave = async () => {
    if (!tenant?.id || !formData.name.trim()) {
      toast.error("Business name is required");
      return;
    }

    setIsSaving(true);
    try {
      const combinedAddress = combineAddress({
        line1: formData.address_line1.trim(),
        city: formData.address_city.trim(),
        state: formData.address_state.trim().toUpperCase(),
        zip: formData.address_zip.trim(),
      });

      await updateBusinessProfile(tenant.id, {
        name: formData.name.trim(),
        tagline: formData.tagline.trim() || undefined,
        phone_public: formData.phone_public.trim() || undefined,
        address: combinedAddress || undefined,
        timezone: formData.timezone,
      });

      const { error } = await supabase
        .from("tenants")
        .update({
          website_url: formData.website_url.trim() || null,
          years_in_business: formData.years_in_business ? parseInt(formData.years_in_business) : null,
        } as any)
        .eq("id", tenant.id);

      if (error) throw error;

      toast.success("Profile saved");
      invalidateBrainQueries(queryClient, tenant?.id);
    } catch (error: unknown) {
      toast.error(error instanceof Error ? error.message : "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  // Build greeting preview
  const greetingPreview = (() => {
    const parts = [`Thanks for calling ${formData.name || "us"}!`];
    if (formData.years_in_business) {
      parts.push(`We've been serving the ${formData.address_city || "area"} for ${formData.years_in_business} years.`);
    }
    parts.push("How can I help?");
    return parts.join(" ");
  })();

  return (
    <div className="space-y-6">
      {/* AI Preview */}
      <PreviewSentence sentence={greetingPreview} />

      {/* Core Info */}
      <div className="space-y-4">
        <div className="grid gap-4 sm:grid-cols-2">
          <div className="space-y-2">
            <Label htmlFor="name">Business Name *</Label>
            <Input
              id="name"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder={examples.businessNamePlaceholder}
            />
            <p className="text-xs text-muted-foreground">AI introduces your business by this name on every call</p>
          </div>

          <div className="space-y-2">
            <Label htmlFor="tagline">Your One-Liner</Label>
            <Input
              id="tagline"
              value={formData.tagline}
              onChange={(e) => setFormData({ ...formData, tagline: e.target.value })}
              placeholder={examples.taglinePlaceholder}
            />
            <p className="text-xs text-muted-foreground">{examples.taglineHint}</p>
          </div>
        </div>

        <div className="grid gap-4 sm:grid-cols-2">
          <div className="space-y-2">
            <Label htmlFor="phone">Phone</Label>
            <Input
              id="phone"
              type="tel"
              value={formData.phone_public}
              onChange={(e) => setFormData({ ...formData, phone_public: e.target.value })}
              placeholder="(555) 123-4567"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="timezone">Timezone</Label>
            <Select
              value={formData.timezone}
              onValueChange={(value) => setFormData({ ...formData, timezone: value })}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {TIMEZONES.map((tz) => (
                  <SelectItem key={tz.value} value={tz.value}>
                    {tz.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>

        <div className="grid gap-4 sm:grid-cols-2">
          <div className="space-y-2">
            <Label htmlFor="website">Website (optional)</Label>
            <Input
              id="website"
              type="url"
              value={formData.website_url}
