  enabled: true,
  maxFollowUps: 3,
  hotLeadSteps: DEFAULT_HOT_STEPS,
  warmLeadSteps: DEFAULT_WARM_STEPS,
  coldLeadSteps: [],
  respectQuietHours: true,
  quietHoursStart: "21:00",
  quietHoursEnd: "09:00",
  stopOnBooking: true,
  stopOnOptOut: true,
};

export function FollowUpSequenceEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [config, setConfig] = useState<FollowUpConfig>(DEFAULT_CONFIG);
  const [activeTab, setActiveTab] = useState<"hot" | "warm" | "cold">("hot");

  useEffect(() => {
    if (tenant?.id) loadConfig();
  }, [tenant?.id]);

  const loadConfig = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await (supabase as any)
        .from("general_workflow_config")
        .select("sales_followup_config")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error && error.code !== "PGRST116") throw error;
      if (data?.sales_followup_config) {
        setConfig({ ...DEFAULT_CONFIG, ...data.sales_followup_config });
      }
    } catch (err) {
      console.error("Failed to load follow-up config:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id) return;
    setIsSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("general_workflow_config")
        .upsert(
          { tenant_id: tenant.id, sales_followup_config: config },
          { onConflict: "tenant_id" }
        );
      if (error) throw error;
      toast.success("Follow-up sequences saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const getSteps = (): FollowUpStep[] => {
    if (activeTab === "hot") return config.hotLeadSteps;
    if (activeTab === "warm") return config.warmLeadSteps;
    return config.coldLeadSteps;
  };

  const setSteps = (steps: FollowUpStep[]) => {
    setConfig((prev) => ({
      ...prev,
      [`${activeTab}LeadSteps`]: steps,
    }));
  };

  const addStep = () => {
    setSteps([
      ...getSteps(),
      { delayHours: 24, channel: "sms", template: "", onlyIfNoResponse: true },
    ]);
  };

  const removeStep = (idx: number) => {
    setSteps(getSteps().filter((_, i) => i !== idx));
  };

  const updateStep = (idx: number, field: keyof FollowUpStep, value: any) => {
    setSteps(getSteps().map((s, i) => (i === idx ? { ...s, [field]: value } : s)));
  };

  const formatDelay = (hours: number): string => {
    if (hours < 1) return `${Math.round(hours * 60)} min`;
    if (hours < 24) return `${hours}h`;
    const days = Math.floor(hours / 24);
    return `${days}d`;
  };

  const buildPreview = (): string => {
    if (!config.enabled) return "Follow-up sequences are turned off.";
    const hotCount = config.hotLeadSteps.length;
    const warmCount = config.warmLeadSteps.length;
    return `Hot leads get ${hotCount} follow-up${hotCount !== 1 ? "s" : ""}, warm leads get ${warmCount}. ${config.respectQuietHours ? `Quiet hours: ${config.quietHoursStart}–${config.quietHoursEnd}.` : ""} ${config.stopOnBooking ? "Stops automatically when they book." : ""}`;
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const steps = getSteps();

  return (
    <div className="space-y-6">
      <AIPreviewCard title="How AI follows up with leads" preview={buildPreview()} />

      {/* Master Toggle */}
      <Card>
        <CardContent className="p-5">
          <div className="flex items-center justify-between">
            <div>
              <p className="font-medium text-sm">Enable follow-up sequences</p>
              <p className="text-xs text-muted-foreground">AI will automatically follow up with leads via text</p>
            </div>
            <Switch
              checked={config.enabled}
              onCheckedChange={(v) => setConfig((p) => ({ ...p, enabled: v }))}
            />
          </div>
        </CardContent>
      </Card>

      {config.enabled && (
        <>
          {/* Lead Temperature Tabs */}
          <div className="flex gap-2">
            {(["hot", "warm", "cold"] as const).map((tab) => (
              <Button
                key={tab}
                variant={activeTab === tab ? "default" : "outline"}
                size="sm"
                onClick={() => setActiveTab(tab)}
                className="capitalize"
              >
                {tab} Leads
                <span className="ml-1.5 text-xs opacity-70">
                  ({tab === "hot" ? config.hotLeadSteps.length : tab === "warm" ? config.warmLeadSteps.length : config.coldLeadSteps.length})
                </span>
              </Button>
            ))}
          </div>

          {/* Sequence Steps */}
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <MessageSquare className="h-4 w-4" />
                {activeTab.charAt(0).toUpperCase() + activeTab.slice(1)} Lead Sequence
              </CardTitle>
              <CardDescription>
                Messages sent to {activeTab} leads after their initial call
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {steps.length === 0 && (
                <p className="text-sm text-muted-foreground text-center py-4">
                  No follow-ups configured for {activeTab} leads.
                </p>
              )}
              {steps.map((step, idx) => (
                <div key={idx} className="space-y-2">
                  {idx > 0 && (
                    <div className="flex justify-center">
                      <ArrowDown className="h-4 w-4 text-muted-foreground" />
                    </div>
                  )}
                  <div className="border rounded-lg p-3 space-y-3">
                    <div className="flex items-center justify-between">
                      <p className="text-xs font-medium text-muted-foreground">Step {idx + 1}</p>
                      <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => removeStep(idx)}>
                        <Trash2 className="h-3.5 w-3.5" />
                      </Button>
                    </div>
                    <div className="grid grid-cols-3 gap-2">
                      <div className="space-y-1">
                        <Label className="text-xs">Wait</Label>
                        <Select
                          value={String(step.delayHours)}
                          onValueChange={(v) => updateStep(idx, "delayHours", Number(v))}
                        >
                          <SelectTrigger className="h-8 text-xs">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="0.5">30 min</SelectItem>
                            <SelectItem value="1">1 hour</SelectItem>
                            <SelectItem value="4">4 hours</SelectItem>
                            <SelectItem value="24">1 day</SelectItem>
                            <SelectItem value="48">2 days</SelectItem>
                            <SelectItem value="72">3 days</SelectItem>
                            <SelectItem value="168">1 week</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="space-y-1">
                        <Label className="text-xs">Channel</Label>
                        <Select
                          value={step.channel}
                          onValueChange={(v) => updateStep(idx, "channel", v)}
                        >
                          <SelectTrigger className="h-8 text-xs">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            <SelectItem value="sms">SMS</SelectItem>
                            <SelectItem value="call">AI Call</SelectItem>
                          </SelectContent>
                        </Select>
                      </div>
                      <div className="flex items-end">
                        <div className="flex items-center gap-1.5">
                          <Switch
                            checked={step.onlyIfNoResponse}
                            onCheckedChange={(v) => updateStep(idx, "onlyIfNoResponse", v)}
                            className="scale-75"
                          />
                          <span className="text-xs text-muted-foreground">Only if no reply</span>
                        </div>
                      </div>
                    </div>
                    <Textarea
                      value={step.template}
                      onChange={(e) => updateStep(idx, "template", e.target.value)}
                      placeholder="Hi {{name}}, following up about {{interest}}..."
                      rows={2}
                      className="text-sm"
                    />
                  </div>
                </div>
              ))}
              <Button variant="outline" size="sm" onClick={addStep} className="gap-1 w-full">
                <Plus className="h-3.5 w-3.5" />
                Add Step
              </Button>
            </CardContent>
          </Card>

          {/* Settings */}
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Clock className="h-4 w-4" />
                Settings
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-center justify-between">
                <div>
                  <Label>Respect quiet hours</Label>
                  <p className="text-xs text-muted-foreground">Don't send messages late at night</p>
                </div>
                <Switch
                  checked={config.respectQuietHours}
                  onCheckedChange={(v) => setConfig((p) => ({ ...p, respectQuietHours: v }))}
                />
              </div>
              {config.respectQuietHours && (
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <Label className="text-xs">Quiet start</Label>
                    <Input
                      type="time"
                      value={config.quietHoursStart}
                      onChange={(e) => setConfig((p) => ({ ...p, quietHoursStart: e.target.value }))}
                    />
                  </div>
                  <div className="space-y-1">
                    <Label className="text-xs">Quiet end</Label>
                    <Input
                      type="time"
                      value={config.quietHoursEnd}
                      onChange={(e) => setConfig((p) => ({ ...p, quietHoursEnd: e.target.value }))}
                    />
                  </div>
                </div>
              )}
              <div className="flex items-center justify-between">
                <div>
                  <Label>Stop on booking</Label>
                  <p className="text-xs text-muted-foreground">Stop sequence when lead books an appointment</p>
                </div>
                <Switch
                  checked={config.stopOnBooking}
                  onCheckedChange={(v) => setConfig((p) => ({ ...p, stopOnBooking: v }))}
                />
              </div>
              <div className="flex items-center justify-between">
                <div>
                  <Label>Stop on opt-out</Label>
                  <p className="text-xs text-muted-foreground">Stop if they reply STOP or unsubscribe</p>
                </div>
                <Switch
                  checked={config.stopOnOptOut}
                  onCheckedChange={(v) => setConfig((p) => ({ ...p, stopOnOptOut: v }))}
                />
              </div>
            </CardContent>
          </Card>
        </>
      )}

      <div className="flex justify-end pt-2">
        <Button onClick={handleSave} disabled={isSaving}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Sequences
        </Button>
      </div>
    </div>
  );
}

/**
 * Lead Pipeline Editor
 * Configure lead stages and how the AI categorizes prospects.
 * Sales mode only.
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, Save, GitBranch, Flame, Thermometer, Snowflake, Plus, Trash2 } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { AIPreviewCard } from "../AIPreviewCard";

interface LeadStage {
  name: string;
  color: string;
  autoAdvance: boolean;
}

interface PipelineConfig {
  stages: LeadStage[];
  autoScoreLeads: boolean;
  scoringMethod: string;
  hotLeadSignals: string[];
  coldLeadSignals: string[];
  assignmentMethod: string;
}

const DEFAULT_STAGES: LeadStage[] = [
  { name: "New", color: "blue", autoAdvance: false },
  { name: "Contacted", color: "yellow", autoAdvance: true },
  { name: "Qualified", color: "orange", autoAdvance: false },
  { name: "Proposal", color: "purple", autoAdvance: false },
  { name: "Won", color: "green", autoAdvance: false },
  { name: "Lost", color: "gray", autoAdvance: false },
];

const DEFAULT_CONFIG: PipelineConfig = {
  stages: DEFAULT_STAGES,
  autoScoreLeads: true,
  scoringMethod: "conversation_signals",
  hotLeadSignals: ["ready to buy", "wants to schedule", "has financing"],
  coldLeadSignals: ["just browsing", "not sure yet", "checking prices"],
  assignmentMethod: "round_robin",
};

const STAGE_COLORS = ["blue", "yellow", "orange", "purple", "green", "gray", "red", "pink"];

export function LeadPipelineEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [config, setConfig] = useState<PipelineConfig>(DEFAULT_CONFIG);

  useEffect(() => {
    if (tenant?.id) loadConfig();
  }, [tenant?.id]);

  const loadConfig = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await (supabase as any)
        .from("general_workflow_config")
        .select("sales_pipeline_config")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error && error.code !== "PGRST116") throw error;
      if (data?.sales_pipeline_config) {
        setConfig({ ...DEFAULT_CONFIG, ...data.sales_pipeline_config });
      }
    } catch (err) {
      console.error("Failed to load pipeline config:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id) return;
    setIsSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("general_workflow_config")
        .upsert(
          { tenant_id: tenant.id, sales_pipeline_config: config },
          { onConflict: "tenant_id" }
        );
      if (error) throw error;
      toast.success("Lead pipeline saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const addStage = () => {
    setConfig((prev) => ({
      ...prev,
      stages: [...prev.stages, { name: "", color: "blue", autoAdvance: false }],
    }));
  };

  const removeStage = (idx: number) => {
    setConfig((prev) => ({
      ...prev,
      stages: prev.stages.filter((_, i) => i !== idx),
    }));
  };

  const updateStage = (idx: number, field: keyof LeadStage, value: string | boolean) => {
    setConfig((prev) => ({
      ...prev,
      stages: prev.stages.map((s, i) => (i === idx ? { ...s, [field]: value } : s)),
    }));
  };

  const buildPreview = (): string => {
    const parts: string[] = [];
    const activeStages = config.stages.filter((s) => s.name.trim());
    parts.push(`I'll track leads through ${activeStages.length} stages: ${activeStages.map((s) => s.name).join(" → ")}.`);
    if (config.autoScoreLeads) {
      parts.push("I'll automatically score leads as hot, warm, or cold based on conversation signals.");
    }
    if (config.assignmentMethod === "round_robin") {
      parts.push("New leads are distributed evenly across your sales team.");
    } else if (config.assignmentMethod === "best_match") {
      parts.push("I'll assign leads to the salesperson best suited to their needs.");
    }
    return parts.join(" ");
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <AIPreviewCard title="How AI manages your pipeline" preview={buildPreview()} />

      {/* Pipeline Stages */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <GitBranch className="h-4 w-4" />
            Pipeline Stages
          </CardTitle>
          <CardDescription>Define the stages a lead moves through</CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          {config.stages.map((stage, idx) => (
            <div key={idx} className="flex items-center gap-2">
              <div
                className="w-3 h-3 rounded-full shrink-0"
                style={{ backgroundColor: stage.color }}
              />
              <Input
                value={stage.name}
                onChange={(e) => updateStage(idx, "name", e.target.value)}
                placeholder="Stage name"
                className="flex-1"
              />
              <Select
                value={stage.color}
                onValueChange={(v) => updateStage(idx, "color", v)}
              >
                <SelectTrigger className="w-24">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {STAGE_COLORS.map((c) => (
                    <SelectItem key={c} value={c}>
                      {c}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
              <Button
                variant="ghost"
                size="icon"
                onClick={() => removeStage(idx)}
                disabled={config.stages.length <= 2}
              >
                <Trash2 className="h-4 w-4 text-muted-foreground" />
              </Button>
            </div>
          ))}
          <Button variant="outline" size="sm" onClick={addStage} className="gap-1">
            <Plus className="h-3.5 w-3.5" />
            Add Stage
          </Button>
        </CardContent>
      </Card>

      {/* Lead Scoring */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Flame className="h-4 w-4" />
            Lead Scoring
          </CardTitle>
          <CardDescription>How the AI rates lead quality</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <Label>Auto-score leads</Label>
              <p className="text-xs text-muted-foreground">AI rates leads as hot/warm/cold after each call</p>
            </div>
            <Switch
              checked={config.autoScoreLeads}
              onCheckedChange={(v) => setConfig((p) => ({ ...p, autoScoreLeads: v }))}
            />
          </div>

          {config.autoScoreLeads && (
            <>
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <Flame className="h-3.5 w-3.5 text-red-500" />
                  <Label>Hot lead signals</Label>
                </div>
                <p className="text-xs text-muted-foreground">
                  Phrases or behaviors that indicate a hot lead
                </p>
                <Input
                  value={config.hotLeadSignals.join(", ")}
                  onChange={(e) =>
                    setConfig((p) => ({
                      ...p,
                      hotLeadSignals: e.target.value.split(",").map((s) => s.trim()).filter(Boolean),
                    }))
                  }
                  placeholder="ready to buy, wants to schedule, has financing"
                />
              </div>
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <Snowflake className="h-3.5 w-3.5 text-blue-500" />
                  <Label>Cold lead signals</Label>
                </div>
                <p className="text-xs text-muted-foreground">
                  Phrases or behaviors that indicate a cold lead
                </p>
                <Input
                  value={config.coldLeadSignals.join(", ")}
                  onChange={(e) =>
                    setConfig((p) => ({
                      ...p,
                      coldLeadSignals: e.target.value.split(",").map((s) => s.trim()).filter(Boolean),
                    }))
                  }
                  placeholder="just browsing, not sure yet, checking prices"
                />
              </div>
            </>
          )}
        </CardContent>
      </Card>

      {/* Lead Assignment */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Thermometer className="h-4 w-4" />
            Lead Assignment
          </CardTitle>
          <CardDescription>How new leads are assigned to your team</CardDescription>
        </CardHeader>
        <CardContent className="space-y-2">
          <Label>Assignment method</Label>
          <Select
            value={config.assignmentMethod}
            onValueChange={(v) => setConfig((p) => ({ ...p, assignmentMethod: v }))}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="round_robin">Round robin - Distribute evenly</SelectItem>
              <SelectItem value="best_match">Best match - Based on expertise</SelectItem>
              <SelectItem value="first_available">First available - Whoever's free</SelectItem>
              <SelectItem value="manual">Manual - Owner assigns all leads</SelectItem>
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      <div className="flex justify-end pt-2">
        <Button onClick={handleSave} disabled={isSaving}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Pipeline
        </Button>
      </div>
    </div>
  );
}

/**
 * Sales Policies Editor
 * For car dealerships, real estate, solar, insurance, equipment, luxury retail, etc.
 * Handles pricing strategy, qualification behavior, appointment settings, and lead capture.
 * Reads/writes to general_workflow_config table (sales_* columns).
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Slider } from "@/components/ui/slider";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, Save, DollarSign, UserCheck, CalendarCheck, Target } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { AIPreviewCard } from "../AIPreviewCard";

interface SalesWorkflowConfig {
  tenant_id: string;
  sales_pricing_strategy: string;
  sales_ask_trade_in: boolean;
  sales_ask_financing: boolean;
  sales_ask_timeline: boolean;
  sales_ask_budget: string;
  sales_max_vehicles_to_mention: number;
  sales_appointment_label: string;
  sales_push_intensity: string;
  sales_follow_up_script: string;
  sales_lead_capture_minimum: string;
  sales_inventory_presentation: string;
}

const DEFAULTS: Omit<SalesWorkflowConfig, "tenant_id"> = {
  sales_pricing_strategy: "deflect_to_visit",
  sales_ask_trade_in: true,
  sales_ask_financing: true,
  sales_ask_timeline: true,
  sales_ask_budget: "careful",
  sales_max_vehicles_to_mention: 3,
  sales_appointment_label: "test drive",
  sales_push_intensity: "medium",
  sales_follow_up_script: "",
  sales_lead_capture_minimum: "name_phone_interest",
  sales_inventory_presentation: "conversational",
};

export function SalesPoliciesEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState<SalesWorkflowConfig | null>(null);

  useEffect(() => {
    if (tenant?.id) {
      loadConfig();
    }
  }, [tenant?.id]);

  const loadConfig = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await (supabase as any)
        .from("general_workflow_config")
        .select("*")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error && error.code !== "PGRST116") throw error;

      setFormData({
        tenant_id: tenant.id,
        sales_pricing_strategy: data?.sales_pricing_strategy || DEFAULTS.sales_pricing_strategy,
        sales_ask_trade_in: data?.sales_ask_trade_in !== false,
        sales_ask_financing: data?.sales_ask_financing !== false,
        sales_ask_timeline: data?.sales_ask_timeline !== false,
        sales_ask_budget: data?.sales_ask_budget || DEFAULTS.sales_ask_budget,
        sales_max_vehicles_to_mention: data?.sales_max_vehicles_to_mention || DEFAULTS.sales_max_vehicles_to_mention,
        sales_appointment_label: data?.sales_appointment_label || DEFAULTS.sales_appointment_label,
        sales_push_intensity: data?.sales_push_intensity || DEFAULTS.sales_push_intensity,
        sales_follow_up_script: data?.sales_follow_up_script || DEFAULTS.sales_follow_up_script,
        sales_lead_capture_minimum: data?.sales_lead_capture_minimum || DEFAULTS.sales_lead_capture_minimum,
        sales_inventory_presentation: data?.sales_inventory_presentation || DEFAULTS.sales_inventory_presentation,
      });
    } catch (err: any) {
      toast.error("Failed to load sales config");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id || !formData) return;
    setIsSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("general_workflow_config")
        .upsert(
          {
            tenant_id: tenant.id,
            sales_pricing_strategy: formData.sales_pricing_strategy,
            sales_ask_trade_in: formData.sales_ask_trade_in,
            sales_ask_financing: formData.sales_ask_financing,
            sales_ask_timeline: formData.sales_ask_timeline,
            sales_ask_budget: formData.sales_ask_budget,
            sales_max_vehicles_to_mention: formData.sales_max_vehicles_to_mention,
            sales_appointment_label: formData.sales_appointment_label,
            sales_push_intensity: formData.sales_push_intensity,
            sales_follow_up_script: formData.sales_follow_up_script,
            sales_lead_capture_minimum: formData.sales_lead_capture_minimum,
            sales_inventory_presentation: formData.sales_inventory_presentation,
          },
          { onConflict: "tenant_id" }
        );

      if (error) throw error;
      toast.success("Sales settings saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const updateField = <K extends keyof SalesWorkflowConfig>(field: K, value: SalesWorkflowConfig[K]) => {
    setFormData((prev) => (prev ? { ...prev, [field]: value } : null));
  };

  const buildAIPreview = (): string => {
    if (!formData) return "";
    const parts: string[] = [];

    const pricingMap: Record<string, string> = {
      deflect_to_visit: "I'll encourage you to visit us for the best pricing.",
      give_range: "I can share a general price range to help you plan.",
      give_exact: "I'll share our current pricing with you.",
    };
    parts.push(pricingMap[formData.sales_pricing_strategy] || pricingMap.deflect_to_visit);

    if (formData.sales_ask_trade_in) parts.push("I'll ask about trade-ins.");
    if (formData.sales_ask_financing) parts.push("I'll discuss financing options.");

    const pushMap: Record<string, string> = {
      soft: `I'll gently suggest scheduling a ${formData.sales_appointment_label}.`,
      medium: `I'll recommend booking a ${formData.sales_appointment_label} when the time is right.`,
      assertive: `I'll actively work to get you scheduled for a ${formData.sales_appointment_label}.`,
    };
    parts.push(pushMap[formData.sales_push_intensity] || pushMap.medium);

    return parts.join(" ");
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!formData) return null;

  return (
    <div className="space-y-6">
      {/* AI Preview */}
      <AIPreviewCard title="How AI handles sales calls" preview={buildAIPreview()} />

      {/* Pricing Strategy */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <DollarSign className="h-4 w-4" />
            Pricing Strategy
          </CardTitle>
          <CardDescription>How your AI handles pricing questions</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>When asked about price</Label>
            <Select
              value={formData.sales_pricing_strategy}
              onValueChange={(v) => updateField("sales_pricing_strategy", v)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="deflect_to_visit">Deflect to visit - "Come see us for the best deal"</SelectItem>
                <SelectItem value="give_range">Give a range - Share approximate pricing</SelectItem>
                <SelectItem value="give_exact">Give exact price - Share listed prices from inventory</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label>Inventory presentation style</Label>
            <Select
              value={formData.sales_inventory_presentation}
              onValueChange={(v) => updateField("sales_inventory_presentation", v)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="conversational">Conversational - Weave into natural dialogue</SelectItem>
                <SelectItem value="list_format">List format - Present as organized options</SelectItem>
                <SelectItem value="highlight_best_match">Best match - Lead with top recommendation</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label>Max items to mention per response: {formData.sales_max_vehicles_to_mention}</Label>
            <Slider
              value={[formData.sales_max_vehicles_to_mention]}
              onValueChange={([v]) => updateField("sales_max_vehicles_to_mention", v)}
              min={1}
              max={5}
              step={1}
            />
            <p className="text-xs text-muted-foreground">
              How many inventory items the AI describes in a single response
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Qualification Questions */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <UserCheck className="h-4 w-4" />
            Qualification Questions
          </CardTitle>
          <CardDescription>What your AI asks to qualify leads</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <Label>Ask about trade-ins</Label>
              <p className="text-xs text-muted-foreground">Ask if caller has something to trade in</p>
            </div>
            <Switch
              checked={formData.sales_ask_trade_in}
              onCheckedChange={(v) => updateField("sales_ask_trade_in", v)}
            />
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Ask about financing</Label>
              <p className="text-xs text-muted-foreground">Ask if caller needs financing</p>
            </div>
            <Switch
              checked={formData.sales_ask_financing}
              onCheckedChange={(v) => updateField("sales_ask_financing", v)}
            />
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Ask about timeline</Label>
              <p className="text-xs text-muted-foreground">Ask when they're looking to buy</p>
            </div>
            <Switch
              checked={formData.sales_ask_timeline}
              onCheckedChange={(v) => updateField("sales_ask_timeline", v)}
            />
          </div>

          <div className="space-y-2">
            <Label>Ask about budget</Label>
            <Select
              value={formData.sales_ask_budget}
              onValueChange={(v) => updateField("sales_ask_budget", v)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="always">Always - Ask every caller</SelectItem>
                <SelectItem value="careful">Careful - Only when naturally relevant</SelectItem>
                <SelectItem value="never">Never - Don't ask about budget</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label>Minimum info to capture</Label>
            <Select
              value={formData.sales_lead_capture_minimum}
              onValueChange={(v) => updateField("sales_lead_capture_minimum", v)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="name_phone">Name + phone only</SelectItem>
                <SelectItem value="name_phone_interest">Name + phone + what they're looking for</SelectItem>
                <SelectItem value="name_phone_interest_timeline">Name + phone + interest + timeline</SelectItem>
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              AI will try to collect at least this much before ending the call
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Appointment Settings */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <CalendarCheck className="h-4 w-4" />
            Appointment Settings
          </CardTitle>
          <CardDescription>How your AI pushes for appointments</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>What to call the appointment</Label>
            <Select
              value={formData.sales_appointment_label}
              onValueChange={(v) => updateField("sales_appointment_label", v)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="test drive">Test Drive</SelectItem>
                <SelectItem value="showing">Showing</SelectItem>
                <SelectItem value="demo">Demo</SelectItem>
                <SelectItem value="consultation">Consultation</SelectItem>
                <SelectItem value="site visit">Site Visit</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label>Push intensity</Label>
            <Select
              value={formData.sales_push_intensity}
              onValueChange={(v) => updateField("sales_push_intensity", v)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="soft">Soft - Mention once, don't push</SelectItem>
                <SelectItem value="medium">Medium - Suggest at natural points in conversation</SelectItem>
                <SelectItem value="assertive">Assertive - Actively guide toward booking</SelectItem>
              </SelectContent>
            </Select>
          </div>
        </CardContent>
      </Card>

      {/* Follow-up Script */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Target className="h-4 w-4" />
            Follow-Up
          </CardTitle>
          <CardDescription>Custom script for callback situations</CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Follow-up script</Label>
            <Textarea
              value={formData.sales_follow_up_script}
              onChange={(e) => updateField("sales_follow_up_script", e.target.value)}
              placeholder="Hi, this is the AI assistant from {{business_name}}. You called earlier about {{interest}}. I wanted to follow up and see if you'd like to schedule a {{appointment_label}}."
              rows={3}
            />
            <p className="text-xs text-muted-foreground">
              Used when the AI follows up on a previous inquiry. Leave blank for default.
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end pt-2">
        <Button onClick={handleSave} disabled={isSaving}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Sales Settings
        </Button>
      </div>
    </div>
  );
}

/**
 * Sales Scripts / Objection Playbook Editor
 * Teach the AI how to handle price objections, competitor comparisons, and hesitation.
 * Sales mode only.
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, Save, Shield, Plus, Trash2, MessageCircle, Swords, Lightbulb } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { AIPreviewCard } from "../AIPreviewCard";

interface SalesScript {
  id: string;
  category: string;
  trigger: string;
  response: string;
}

interface ScriptsConfig {
  scripts: SalesScript[];
  closingStyle: string;
  valueProps: string[];
}

const DEFAULT_SCRIPTS: SalesScript[] = [
  {
    id: "price-too-high",
    category: "price_objection",
    trigger: "That's too expensive / too much money",
    response: "I understand budget is important. Many of our customers felt the same way initially but found the value far exceeded the cost. Would it help if I walked you through what's included?",
  },
  {
    id: "thinking-about-it",
    category: "hesitation",
    trigger: "I need to think about it / not ready yet",
    response: "Absolutely, take your time! This is a big decision. Can I send you some information to review? And would it be okay if I followed up in a day or two?",
  },
  {
    id: "competitor-comparison",
    category: "competitor",
    trigger: "What about [competitor]? / I'm looking at other options",
    response: "Great question! We respect our competitors. What sets us apart is {{value_prop}}. Would you like to come in and see the difference firsthand?",
  },
];

const DEFAULT_CONFIG: ScriptsConfig = {
  scripts: DEFAULT_SCRIPTS,
  closingStyle: "assumptive",
  valueProps: [],
};

const CATEGORIES = [
  { value: "price_objection", label: "Price Objection", icon: "$" },
  { value: "hesitation", label: "Hesitation", icon: "..." },
  { value: "competitor", label: "Competitor Comparison", icon: "vs" },
  { value: "timing", label: "Timing / Not Now", icon: "clock" },
  { value: "trust", label: "Trust / Credibility", icon: "shield" },
  { value: "custom", label: "Custom", icon: "+" },
];

let nextId = 1;
function generateId() {
  return `script-${Date.now()}-${nextId++}`;
}

export function SalesScriptsEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [config, setConfig] = useState<ScriptsConfig>(DEFAULT_CONFIG);
  const [newValueProp, setNewValueProp] = useState("");

  useEffect(() => {
    if (tenant?.id) loadConfig();
  }, [tenant?.id]);

  const loadConfig = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await (supabase as any)
        .from("general_workflow_config")
        .select("sales_scripts_config")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error && error.code !== "PGRST116") throw error;
      if (data?.sales_scripts_config) {
        setConfig({ ...DEFAULT_CONFIG, ...data.sales_scripts_config });
      }
    } catch (err) {
      console.error("Failed to load scripts config:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id) return;
    setIsSaving(true);
    try {
      const { error } = await (supabase as any)
        .from("general_workflow_config")
        .upsert(
          { tenant_id: tenant.id, sales_scripts_config: config },
          { onConflict: "tenant_id" }
        );
      if (error) throw error;
      toast.success("Sales scripts saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const addScript = () => {
    setConfig((prev) => ({
      ...prev,
      scripts: [
        ...prev.scripts,
        { id: generateId(), category: "custom", trigger: "", response: "" },
      ],
    }));
  };

  const removeScript = (id: string) => {
    setConfig((prev) => ({
      ...prev,
      scripts: prev.scripts.filter((s) => s.id !== id),
    }));
  };

  const updateScript = (id: string, field: keyof SalesScript, value: string) => {
    setConfig((prev) => ({
      ...prev,
      scripts: prev.scripts.map((s) => (s.id === id ? { ...s, [field]: value } : s)),
    }));
  };

  const addValueProp = () => {
    if (!newValueProp.trim()) return;
    setConfig((prev) => ({
      ...prev,
      valueProps: [...prev.valueProps, newValueProp.trim()],
    }));
    setNewValueProp("");
  };

  const removeValueProp = (idx: number) => {
    setConfig((prev) => ({
      ...prev,
      valueProps: prev.valueProps.filter((_, i) => i !== idx),
    }));
  };

  const getCategoryLabel = (cat: string) =>
    CATEGORIES.find((c) => c.value === cat)?.label || cat;

  const buildPreview = (): string => {
    const parts: string[] = [];
    const scriptCount = config.scripts.filter((s) => s.trigger.trim() && s.response.trim()).length;
    parts.push(`I have ${scriptCount} trained response${scriptCount !== 1 ? "s" : ""} for common objections.`);
    if (config.valueProps.length > 0) {
      parts.push(`I'll emphasize: ${config.valueProps.slice(0, 3).join(", ")}.`);
    }
    const closingMap: Record<string, string> = {
      assumptive: "I'll guide conversations toward booking with confidence.",
      consultative: "I'll listen first and recommend based on their needs.",
      soft: "I'll suggest next steps gently without pressure.",
    };
    parts.push(closingMap[config.closingStyle] || closingMap.assumptive);
    return parts.join(" ");
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <AIPreviewCard title="How AI handles objections" preview={buildPreview()} />

      {/* Value Propositions */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Lightbulb className="h-4 w-4" />
            Value Propositions
          </CardTitle>
          <CardDescription>
            Key selling points the AI weaves into conversations
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-3">
          {config.valueProps.map((prop, idx) => (
            <div key={idx} className="flex items-center gap-2">
              <span className="text-sm flex-1">{prop}</span>
              <Button variant="ghost" size="icon" className="h-6 w-6" onClick={() => removeValueProp(idx)}>
                <Trash2 className="h-3.5 w-3.5" />
              </Button>
            </div>
          ))}
          <div className="flex gap-2">
            <Input
              value={newValueProp}
              onChange={(e) => setNewValueProp(e.target.value)}
              placeholder="e.g. Lifetime warranty included"
              onKeyDown={(e) => e.key === "Enter" && addValueProp()}
            />
            <Button variant="outline" size="sm" onClick={addValueProp}>
              <Plus className="h-3.5 w-3.5" />
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Closing Style */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Swords className="h-4 w-4" />
            Closing Style
          </CardTitle>
          <CardDescription>How the AI approaches closing</CardDescription>
        </CardHeader>
        <CardContent className="space-y-2">
          <Label>Approach</Label>
          <Select
            value={config.closingStyle}
            onValueChange={(v) => setConfig((p) => ({ ...p, closingStyle: v }))}
          >
            <SelectTrigger>
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="assumptive">Assumptive - "Let's get you scheduled for..."</SelectItem>
              <SelectItem value="consultative">Consultative - "Based on what you've shared, I'd recommend..."</SelectItem>
              <SelectItem value="soft">Soft - "Would you like to take the next step?"</SelectItem>
            </SelectContent>
          </Select>
        </CardContent>
      </Card>

      {/* Objection Scripts */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Shield className="h-4 w-4" />
            Objection Playbook
          </CardTitle>
          <CardDescription>
            Teach the AI exactly how to respond to common pushback
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {config.scripts.map((script) => (
            <div key={script.id} className="border rounded-lg p-3 space-y-2">
              <div className="flex items-center justify-between">
                <Select
                  value={script.category}
                  onValueChange={(v) => updateScript(script.id, "category", v)}
                >
                  <SelectTrigger className="w-48 h-7 text-xs">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {CATEGORIES.map((cat) => (
                      <SelectItem key={cat.value} value={cat.value}>
                        {cat.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-6 w-6"
                  onClick={() => removeScript(script.id)}
                >
                  <Trash2 className="h-3.5 w-3.5" />
                </Button>
              </div>
              <div className="space-y-1">
                <Label className="text-xs">When the caller says...</Label>
                <Input
                  value={script.trigger}
                  onChange={(e) => updateScript(script.id, "trigger", e.target.value)}
                  placeholder="That's too expensive / I need to think about it"
                  className="text-sm"
                />
              </div>
              <div className="space-y-1">
                <Label className="text-xs">AI responds with...</Label>
                <Textarea
                  value={script.response}
                  onChange={(e) => updateScript(script.id, "response", e.target.value)}
                  placeholder="I understand. Many customers felt the same way..."
                  rows={2}
                  className="text-sm"
                />
              </div>
            </div>
          ))}
          <Button variant="outline" size="sm" onClick={addScript} className="gap-1 w-full">
            <Plus className="h-3.5 w-3.5" />
            Add Script
          </Button>
        </CardContent>
      </Card>

      <div className="flex justify-end pt-2">
        <Button onClick={handleSave} disabled={isSaving}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Scripts
        </Button>
      </div>
    </div>
  );
}

/**
 * ServiceCoverageEditor - Service mode coverage and timing settings
 * 
 * Manages same-day service, travel buffers, and on-site duration settings.
 */
import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Loader2,
  Save,
  Clock,
  MapPin,
  Zap,
  Car,
  CalendarClock,
  Info,
} from "lucide-react";
import { AIPreviewCard } from "../AIPreviewCard";

interface ServiceCoverageSettings {
  tenant_id: string;
  same_day_radius_miles: number | null;
  same_day_enabled: boolean;
  same_day_cutoff_time: string | null;
  travel_buffer_minutes: number;
  buffer_mode: "fixed" | "distance_based" | "none";
  default_onsite_minutes: number;
  onsite_by_service_type: Record<string, number>;
  accepts_same_day_urgent: boolean;
  urgent_upcharge_percent: number;
  preferred_zip_priority: string[];
  avoid_traffic_hours: boolean;
}

const DEFAULT_SETTINGS: Omit<ServiceCoverageSettings, "tenant_id"> = {
  same_day_radius_miles: null,
  same_day_enabled: true,
  same_day_cutoff_time: "14:00",
  travel_buffer_minutes: 15,
  buffer_mode: "fixed",
  default_onsite_minutes: 60,
  onsite_by_service_type: {},
  accepts_same_day_urgent: true,
  urgent_upcharge_percent: 0,
  preferred_zip_priority: [],
  avoid_traffic_hours: false,
};

export function ServiceCoverageEditor() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const [settings, setSettings] = useState<ServiceCoverageSettings | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);

  useEffect(() => {
    if (!tenant?.id) return;
    fetchSettings();
  }, [tenant?.id]);

  const fetchSettings = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from("service_coverage_settings")
        .select("*")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setSettings({
          ...data,
          onsite_by_service_type: (data.onsite_by_service_type as Record<string, number>) || {},
          preferred_zip_priority: (data.preferred_zip_priority as string[]) || [],
        } as ServiceCoverageSettings);
      } else {
        setSettings({
          ...DEFAULT_SETTINGS,
          tenant_id: tenant.id,
        });
      }
    } catch (err) {
      console.error("Failed to fetch service coverage settings:", err);
      toast({
        title: "Error",
        description: "Failed to load coverage settings",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id || !settings) return;
    setIsSaving(true);
    try {
      const { error } = await supabase
        .from("service_coverage_settings")
        .upsert({
          ...settings,
          tenant_id: tenant.id,
        }, { onConflict: "tenant_id" });

      if (error) throw error;

      toast({
        title: "Saved",
        description: "Coverage settings updated",
      });
      setHasChanges(false);
    } catch (err) {
      console.error("Failed to save service coverage settings:", err);
      toast({
        title: "Error",
        description: "Failed to save coverage settings",
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  const updateSettings = (updates: Partial<ServiceCoverageSettings>) => {
    setSettings(prev => prev ? { ...prev, ...updates } : null);
    setHasChanges(true);
  };

  if (isLoading || !settings) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const formatCutoffTime = (time: string | null) => {
    if (!time) return "2:00 PM";
    const [hours] = time.split(":");
    const hour = parseInt(hours);
    const ampm = hour >= 12 ? "PM" : "AM";
    const displayHour = hour > 12 ? hour - 12 : hour || 12;
    return `${displayHour}:00 ${ampm}`;
  };

  const generateAIPreview = () => {
    const parts: string[] = [];
    
    if (settings.same_day_enabled) {
      parts.push(`I can often get someone out same-day`);
      if (settings.same_day_cutoff_time) {
        parts.push(`if you call before ${formatCutoffTime(settings.same_day_cutoff_time)}`);
      }
    }
    
    if (settings.accepts_same_day_urgent && settings.urgent_upcharge_percent > 0) {
      parts.push(`For emergencies, we do have a ${settings.urgent_upcharge_percent}% urgent service fee`);
    }
    
    if (settings.travel_buffer_minutes > 0) {
      parts.push(`I'll schedule about ${settings.travel_buffer_minutes} minutes between appointments for travel`);
    }
    
    return parts.length > 0 
      ? parts.join(". ") + "."
      : "Let me check our availability for your area.";
  };

  return (
    <div className="space-y-6">
      <Tabs defaultValue="same-day" className="w-full">
        <TabsList className="grid grid-cols-3 h-auto">
          <TabsTrigger value="same-day" className="text-xs py-2">
            <Zap className="h-3 w-3 mr-1" />
            Same-Day
          </TabsTrigger>
          <TabsTrigger value="scheduling" className="text-xs py-2">
            <CalendarClock className="h-3 w-3 mr-1" />
            Scheduling
          </TabsTrigger>
          <TabsTrigger value="travel" className="text-xs py-2">
            <Car className="h-3 w-3 mr-1" />
            Travel
          </TabsTrigger>
        </TabsList>

        {/* Same-Day Service Tab */}
        <TabsContent value="same-day" className="space-y-4 mt-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Zap className="h-4 w-4 text-amber-500" />
                Same-Day Service
              </CardTitle>
              <CardDescription>
                Configure when you can offer same-day appointments
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex items-center justify-between p-3 rounded-lg border">
                <div className="space-y-0.5">
                  <Label>Same-day service available</Label>
                  <p className="text-xs text-muted-foreground">
                    AI will offer same-day appointments when available
                  </p>
                </div>
                <Switch
                  checked={settings.same_day_enabled}
                  onCheckedChange={(checked) => updateSettings({ same_day_enabled: checked })}
                />
              </div>

              {settings.same_day_enabled && (
                <>
                  <div className="grid gap-4 sm:grid-cols-2">
                    <div className="space-y-2">
                      <Label>Same-day cutoff time</Label>
                      <Select
                        value={settings.same_day_cutoff_time || "14:00"}
                        onValueChange={(value) => updateSettings({ same_day_cutoff_time: value })}
                      >
                        <SelectTrigger>
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="10:00">10:00 AM</SelectItem>
                          <SelectItem value="11:00">11:00 AM</SelectItem>
                          <SelectItem value="12:00">12:00 PM</SelectItem>
                          <SelectItem value="13:00">1:00 PM</SelectItem>
                          <SelectItem value="14:00">2:00 PM</SelectItem>
                          <SelectItem value="15:00">3:00 PM</SelectItem>
                          <SelectItem value="16:00">4:00 PM</SelectItem>
                          <SelectItem value="17:00">5:00 PM</SelectItem>
                        </SelectContent>
                      </Select>
                      <p className="text-xs text-muted-foreground">
                        No same-day offers after this time
                      </p>
                    </div>

                    <div className="space-y-2">
                      <Label>Same-day radius (miles)</Label>
                      <Input
                        type="number"
                        value={settings.same_day_radius_miles ?? ""}
                        onChange={(e) => updateSettings({ 
                          same_day_radius_miles: e.target.value ? parseFloat(e.target.value) : null 
                        })}
                        placeholder="Leave blank for full area"
                      />
                      <p className="text-xs text-muted-foreground">
                        Limit same-day to closer customers
                      </p>
                    </div>
                  </div>

                  <Separator />

                  <div className="flex items-center justify-between p-3 rounded-lg border">
                    <div className="space-y-0.5">
                      <Label>Accept urgent/emergency same-day</Label>
                      <p className="text-xs text-muted-foreground">
                        Allow rush jobs with upcharge
                      </p>
                    </div>
                    <Switch
                      checked={settings.accepts_same_day_urgent}
                      onCheckedChange={(checked) => updateSettings({ accepts_same_day_urgent: checked })}
                    />
                  </div>

                  {settings.accepts_same_day_urgent && (
                    <div className="space-y-2">
                      <Label>Urgent service upcharge (%)</Label>
                      <Input
                        type="number"
                        min="0"
                        max="100"
                        value={settings.urgent_upcharge_percent}
                        onChange={(e) => updateSettings({ 
                          urgent_upcharge_percent: parseFloat(e.target.value) || 0 
                        })}
                        className="w-32"
                      />
                      <p className="text-xs text-muted-foreground">
                        Extra charge for rush/emergency same-day
                      </p>
                    </div>
                  )}
                </>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Scheduling Tab */}
        <TabsContent value="scheduling" className="space-y-4 mt-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Clock className="h-4 w-4 text-blue-500" />
                Appointment Duration
              </CardTitle>
              <CardDescription>
                How long typical service appointments take
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label>Default on-site duration (minutes)</Label>
                <Input
                  type="number"
                  min="15"
                  step="15"
                  value={settings.default_onsite_minutes}
                  onChange={(e) => updateSettings({ 
                    default_onsite_minutes: parseInt(e.target.value) || 60 
                  })}
                  className="w-32"
                />
                <p className="text-xs text-muted-foreground">
                  Used for scheduling when service type isn't specified
                </p>
              </div>

              <div className="rounded-lg border bg-muted/30 p-3">
                <div className="flex items-start gap-2">
                  <Info className="h-4 w-4 text-muted-foreground mt-0.5" />
                  <p className="text-xs text-muted-foreground">
                    You can set specific durations for each service type in your Services catalog.
                    This default is used when the AI doesn't know the exact service yet.
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* Travel Tab */}
        <TabsContent value="travel" className="space-y-4 mt-4">
          <Card>
            <CardHeader className="pb-3">
              <CardTitle className="text-base flex items-center gap-2">
                <Car className="h-4 w-4 text-green-500" />
                Travel Buffer
              </CardTitle>
              <CardDescription>
                Time between appointments for travel
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label>Buffer mode</Label>
                <Select
                  value={settings.buffer_mode}
                  onValueChange={(value) => updateSettings({ buffer_mode: value as "fixed" | "distance_based" | "none" })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="fixed">Fixed buffer between appointments</SelectItem>
                    <SelectItem value="distance_based">Calculate based on distance</SelectItem>
                    <SelectItem value="none">No buffer (back-to-back)</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {settings.buffer_mode === "fixed" && (
                <div className="space-y-2">
                  <Label>Travel buffer (minutes)</Label>
                  <Input
                    type="number"
                    min="0"
                    step="5"
                    value={settings.travel_buffer_minutes}
                    onChange={(e) => updateSettings({ 
                      travel_buffer_minutes: parseInt(e.target.value) || 0 
                    })}
                    className="w-32"
                  />
                  <p className="text-xs text-muted-foreground">
                    Time added between appointments for travel
                  </p>
                </div>
              )}

              {settings.buffer_mode === "distance_based" && (
                <div className="rounded-lg border bg-muted/30 p-3">
                  <p className="text-xs text-muted-foreground">
                    Travel time will be automatically calculated using distance between appointments.
                    Requires Mapbox distance provider to be enabled.
                  </p>
                </div>
              )}

              <Separator />

              <div className="flex items-center justify-between p-3 rounded-lg border">
                <div className="space-y-0.5">
                  <Label>Avoid scheduling during traffic hours</Label>
                  <p className="text-xs text-muted-foreground">
                    Add extra buffer during peak traffic times (7-9am, 4-6pm)
                  </p>
                </div>
                <Switch
                  checked={settings.avoid_traffic_hours}
                  onCheckedChange={(checked) => updateSettings({ avoid_traffic_hours: checked })}
                />
              </div>
            </CardContent>
          </Card>
        </TabsContent>
      </Tabs>

      {/* AI Preview */}
      <AIPreviewCard 
        title="AI will say something like:" 
        preview={generateAIPreview()} 
      />

      {/* Save Button */}
      <div className="flex justify-end">
        <Button onClick={handleSave} disabled={isSaving || !hasChanges}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Settings
        </Button>
      </div>
    </div>
  );
}

/**
 * Service Policies Editor
 * For salons, HVAC, plumbers, cleaners, contractors, etc.
 * Handles scheduling, guarantees, property, and liability policies
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, Save, Clock, Shield, Home, AlertTriangle, Car } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { AIPreviewCard } from "../AIPreviewCard";

interface ServicePolicies {
  id?: string;
  tenant_id: string;
  // Scheduling
  no_show_fee_cents: number;
  no_show_fee_type: string;
  late_arrival_grace_minutes: number;
  late_arrival_fee_cents: number;
  rescheduling_notice_hours: number;
  rescheduling_fee_cents: number;
  max_reschedules_allowed: number;
  // Guarantees
  satisfaction_guarantee_enabled: boolean;
  satisfaction_guarantee_text: string;
  warranty_days: number | null;
  warranty_text: string;
  // Property
  pet_policy: string;
  parking_requirements: string;
  access_requirements: string;
  age_restriction_years: number | null;
  // Liability
  liability_waiver_required: boolean;
  liability_waiver_text: string;
  damage_policy: string;
  insurance_info: string;
  // Travel
  travel_fee_policy: string;
  minimum_service_charge_cents: number;
}

const DEFAULT_POLICIES: Omit<ServicePolicies, 'tenant_id'> = {
  no_show_fee_cents: 0,
  no_show_fee_type: 'fixed',
  late_arrival_grace_minutes: 15,
  late_arrival_fee_cents: 0,
  rescheduling_notice_hours: 24,
  rescheduling_fee_cents: 0,
  max_reschedules_allowed: 2,
  satisfaction_guarantee_enabled: false,
  satisfaction_guarantee_text: '',
  warranty_days: null,
  warranty_text: '',
  pet_policy: '',
  parking_requirements: '',
  access_requirements: '',
  age_restriction_years: null,
  liability_waiver_required: false,
  liability_waiver_text: '',
  damage_policy: '',
  insurance_info: '',
  travel_fee_policy: '',
  minimum_service_charge_cents: 0,
};

export function ServicePoliciesEditor() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState<ServicePolicies | null>(null);

  useEffect(() => {
    if (tenant?.id) {
      loadPolicies();
    }
  }, [tenant?.id]);

  const loadPolicies = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('service_policies')
        .select('*')
        .eq('tenant_id', tenant.id)
        .maybeSingle();

      if (error && error.code !== 'PGRST116') throw error;
      
      setFormData(data || { ...DEFAULT_POLICIES, tenant_id: tenant.id });
    } catch (err: any) {
      toast.error("Failed to load policies");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id || !formData) return;
    setIsSaving(true);
    try {
      const { error } = await supabase
        .from('service_policies')
        .upsert({
          ...formData,
          tenant_id: tenant.id,
        }, { onConflict: 'tenant_id' });

      if (error) throw error;
      toast.success("Policies saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const updateField = <K extends keyof ServicePolicies>(field: K, value: ServicePolicies[K]) => {
    setFormData(prev => prev ? { ...prev, [field]: value } : null);
  };

  const formatCents = (cents: number) => cents > 0 ? `$${(cents / 100).toFixed(0)}` : 'No fee';

  // Build AI preview
  const buildAIPreview = (): string => {
    if (!formData) return "";
    const parts: string[] = [];
    
    if (formData.no_show_fee_cents > 0) {
      parts.push(`No-shows are charged ${formatCents(formData.no_show_fee_cents)}.`);
    }
    if (formData.late_arrival_grace_minutes > 0) {
      parts.push(`We have a ${formData.late_arrival_grace_minutes}-minute grace period for late arrivals.`);
    }
    if (formData.satisfaction_guarantee_enabled) {
      parts.push("We offer a satisfaction guarantee.");
    }
    if (formData.pet_policy) {
      parts.push(formData.pet_policy);
    }
    
    return parts.length > 0 ? parts.join(' ') : "No specific service policies configured yet.";
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!formData) return null;

  return (
    <div className="space-y-6">
      {/* AI Preview */}
      <AIPreviewCard 
        title="How AI explains your service policies"
        preview={buildAIPreview()}
      />

      {/* Scheduling Policies */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Clock className="h-4 w-4" />
            Scheduling Policies
          </CardTitle>
          <CardDescription>
            No-shows, late arrivals, and rescheduling rules
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* No-show fee */}
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>No-Show Fee</Label>
              <div className="flex gap-2">
                <div className="relative flex-1">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                  <Input
                    type="number"
                    className="pl-7"
                    value={formData.no_show_fee_cents / 100}
                    onChange={(e) => updateField('no_show_fee_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                    placeholder="0"
                  />
                </div>
                <Select 
                  value={formData.no_show_fee_type} 
                  onValueChange={(v) => updateField('no_show_fee_type', v)}
                >
                  <SelectTrigger className="w-32">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="fixed">Fixed</SelectItem>
                    <SelectItem value="percentage">% of service</SelectItem>
                    <SelectItem value="full_service">Full price</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Late Arrival Grace Period</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.late_arrival_grace_minutes}
                  onChange={(e) => updateField('late_arrival_grace_minutes', parseInt(e.target.value || '0'))}
                  placeholder="15"
                />
                <span className="flex items-center text-sm text-muted-foreground">min</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Late Arrival Fee</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.late_arrival_fee_cents / 100}
                  onChange={(e) => updateField('late_arrival_fee_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                  placeholder="0"
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Rescheduling Notice Required</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.rescheduling_notice_hours}
                  onChange={(e) => updateField('rescheduling_notice_hours', parseInt(e.target.value || '0'))}
                  placeholder="24"
                />
                <span className="flex items-center text-sm text-muted-foreground">hours</span>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Rescheduling Fee (late notice)</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
                <Input
                  type="number"
                  className="pl-7"
                  value={formData.rescheduling_fee_cents / 100}
                  onChange={(e) => updateField('rescheduling_fee_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                  placeholder="0"
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label>Max Reschedules Allowed</Label>
              <Input
                type="number"
                value={formData.max_reschedules_allowed}
                onChange={(e) => updateField('max_reschedules_allowed', parseInt(e.target.value || '0'))}
                placeholder="2"
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Service Guarantees */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Shield className="h-4 w-4" />
            Guarantees & Warranties
          </CardTitle>
          <CardDescription>
            Your service quality promises
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <Label>Satisfaction Guarantee</Label>
              <p className="text-xs text-muted-foreground">Offer to make it right if customer isn't satisfied</p>
            </div>
            <Switch
              checked={formData.satisfaction_guarantee_enabled}
              onCheckedChange={(v) => updateField('satisfaction_guarantee_enabled', v)}
            />
          </div>

          {formData.satisfaction_guarantee_enabled && (
            <div className="space-y-2">
              <Label>Guarantee Details</Label>
              <Textarea
                value={formData.satisfaction_guarantee_text}
                onChange={(e) => updateField('satisfaction_guarantee_text', e.target.value)}
                placeholder="If you're not 100% satisfied, we'll come back and make it right at no extra charge."
                rows={2}
              />
            </div>
          )}

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Warranty Period</Label>
              <div className="flex gap-2">
                <Input
                  type="number"
                  value={formData.warranty_days || ''}
                  onChange={(e) => updateField('warranty_days', e.target.value ? parseInt(e.target.value) : null)}
                  placeholder="30"
                />
                <span className="flex items-center text-sm text-muted-foreground">days</span>
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <Label>Warranty Terms</Label>
            <Textarea
              value={formData.warranty_text}
              onChange={(e) => updateField('warranty_text', e.target.value)}
              placeholder="All workmanship is warranted for 30 days. Parts warranties vary by manufacturer."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Property/Premises */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Home className="h-4 w-4" />
            Property & Access
          </CardTitle>
          <CardDescription>
            Requirements for service at customer locations
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Pet Policy</Label>
            <Select 
              value={formData.pet_policy || 'none'} 
              onValueChange={(v) => updateField('pet_policy', v === 'none' ? '' : v)}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select pet policy..." />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="none">No specific policy</SelectItem>
                <SelectItem value="We love pets! No need to secure them.">Pets welcome</SelectItem>
                <SelectItem value="Please secure pets in another room during service.">Please secure pets</SelectItem>
                <SelectItem value="For safety, pets must be secured or removed during service.">Pets must be secured</SelectItem>
                <SelectItem value="No pets on premises during service.">No pets during service</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label>Parking Requirements</Label>
            <Textarea
              value={formData.parking_requirements}
              onChange={(e) => updateField('parking_requirements', e.target.value)}
              placeholder="Please ensure our service vehicle has clear access to the driveway or provide visitor parking info."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Access Requirements</Label>
            <Textarea
              value={formData.access_requirements}
              onChange={(e) => updateField('access_requirements', e.target.value)}
              placeholder="Gate codes, lockbox info, or key arrangements should be provided 24 hours before your appointment."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Age Restriction (if applicable)</Label>
            <div className="flex gap-2 items-center">
              <Input
                type="number"
                className="w-24"
                value={formData.age_restriction_years || ''}
                onChange={(e) => updateField('age_restriction_years', e.target.value ? parseInt(e.target.value) : null)}
                placeholder="18"
              />
              <span className="text-sm text-muted-foreground">years or older required</span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Liability */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <AlertTriangle className="h-4 w-4" />
            Liability & Insurance
          </CardTitle>
          <CardDescription>
            Waivers, damage policies, and coverage info
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <Label>Require Liability Waiver</Label>
              <p className="text-xs text-muted-foreground">Customers must sign before service begins</p>
            </div>
            <Switch
              checked={formData.liability_waiver_required}
              onCheckedChange={(v) => updateField('liability_waiver_required', v)}
            />
          </div>

          {formData.liability_waiver_required && (
            <div className="space-y-2">
              <Label>Waiver Summary (for AI to explain)</Label>
              <Textarea
                value={formData.liability_waiver_text}
                onChange={(e) => updateField('liability_waiver_text', e.target.value)}
                placeholder="You'll need to sign a standard liability waiver before we begin. It covers normal risks associated with the service."
                rows={2}
              />
            </div>
          )}

          <div className="space-y-2">
            <Label>Damage Policy</Label>
            <Textarea
              value={formData.damage_policy}
              onChange={(e) => updateField('damage_policy', e.target.value)}
              placeholder="Pre-existing damage should be documented before service. Any damage caused by our team will be repaired or compensated."
              rows={2}
            />
          </div>

          <div className="space-y-2">
            <Label>Insurance Information</Label>
            <Textarea
              value={formData.insurance_info}
              onChange={(e) => updateField('insurance_info', e.target.value)}
              placeholder="We are fully licensed and insured. Proof of insurance available upon request."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Travel & Minimums */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Car className="h-4 w-4" />
            Travel & Minimums
          </CardTitle>
          <CardDescription>
            Service call minimums and travel charges
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-2">
            <Label>Minimum Service Charge</Label>
            <div className="relative w-40">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">$</span>
              <Input
                type="number"
                className="pl-7"
                value={formData.minimum_service_charge_cents / 100}
                onChange={(e) => updateField('minimum_service_charge_cents', Math.round(parseFloat(e.target.value || '0') * 100))}
                placeholder="0"
              />
            </div>
            <p className="text-xs text-muted-foreground">Minimum charge for any service call</p>
          </div>

          <div className="space-y-2">
            <Label>Travel Fee Policy</Label>
            <Textarea
              value={formData.travel_fee_policy}
              onChange={(e) => updateField('travel_fee_policy', e.target.value)}
              placeholder="Travel within 10 miles is free. Beyond that, a $1/mile travel fee applies."
              rows={2}
            />
          </div>
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end pt-2">
        <Button onClick={handleSave} disabled={isSaving}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Service Policies
        </Button>
      </div>
    </div>
  );
}

/**
 * Intake Requirements Editor
 * Manages required questions the AI must ask callers
 * Supports mode-aware visibility and custom field types
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Loader2, Save, Plus, Trash2, GripVertical, MessageSquare } from "lucide-react";
import { toast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";
import { AIPreviewCard } from "../AIPreviewCard";
import type { BusinessMode } from "@/hooks/useTenantConfig";

interface IntakeRequirement {
  id?: string;
  tenant_id: string;
  field_key: string;
  field_label: string;
  field_type: string;
  options_json: any;
  is_required: boolean;
  ask_order: number;
  visible_modes: string[];
  visible_intents: string[] | null;
  ai_prompt_hint: string;
  validation_hint: string;
  is_active: boolean;
}

const FIELD_TYPES = [
  { value: 'text', label: 'Text' },
  { value: 'phone', label: 'Phone Number' },
  { value: 'email', label: 'Email Address' },
  { value: 'address', label: 'Full Address' },
  { value: 'number', label: 'Number' },
  { value: 'select', label: 'Single Choice' },
  { value: 'multiselect', label: 'Multiple Choice' },
  { value: 'date', label: 'Date' },
  { value: 'time', label: 'Time' },
  { value: 'datetime', label: 'Date & Time' },
];

const ALL_MODES: BusinessMode[] = ['service', 'dispatch', 'food', 'medical', 'general', 'sales'];

const SUGGESTED_FIELDS: Partial<IntakeRequirement>[] = [
  // Universal fields
  { field_key: 'customer_name', field_label: "What's your name?", field_type: 'text', is_required: true, ai_prompt_hint: 'Ask for their full name' },
  { field_key: 'customer_phone', field_label: "What's the best number to reach you?", field_type: 'phone', is_required: true, ai_prompt_hint: 'Get their callback number' },
  { field_key: 'customer_email', field_label: "What's your email address?", field_type: 'email', is_required: false, ai_prompt_hint: 'Optional - for confirmation emails' },
  
  // Dispatch-specific fields (P0 required for dispatch mode)
  { field_key: 'pickup_address', field_label: "What's the exact address or cross streets where you are?", field_type: 'address', is_required: true, visible_modes: ['dispatch'], ai_prompt_hint: 'Get exact pickup location - street address, highway mile marker, or cross streets' },
  { field_key: 'dropoff_address', field_label: "Where should we take the vehicle?", field_type: 'address', is_required: false, visible_modes: ['dispatch'], ai_prompt_hint: 'Destination - home, shop, or our lot' },
  { field_key: 'vehicle_year', field_label: "What year is the vehicle?", field_type: 'text', is_required: true, visible_modes: ['dispatch'], ai_prompt_hint: 'Get vehicle year (e.g., 2019)' },
  { field_key: 'vehicle_make', field_label: "What's the make of the vehicle?", field_type: 'text', is_required: true, visible_modes: ['dispatch'], ai_prompt_hint: 'Get vehicle manufacturer (e.g., Honda, Ford, Toyota)' },
  { field_key: 'vehicle_model', field_label: "What's the model?", field_type: 'text', is_required: true, visible_modes: ['dispatch'], ai_prompt_hint: 'Get vehicle model (e.g., Civic, F-150, Camry)' },
  { field_key: 'vehicle_color', field_label: "What color is it?", field_type: 'text', is_required: false, visible_modes: ['dispatch'], ai_prompt_hint: 'Get vehicle color so driver can identify it' },
  { field_key: 'is_drivable', field_label: "Is the vehicle drivable or does it need to be towed?", field_type: 'select', is_required: true, visible_modes: ['dispatch'], ai_prompt_hint: 'Determines if we need flatbed or can do roadside' },
  { field_key: 'service_needed', field_label: "What service do you need? (tow, jump, lockout, tire, fuel)", field_type: 'text', is_required: true, visible_modes: ['dispatch'], ai_prompt_hint: 'Type of roadside service or tow' },
  { field_key: 'urgency', field_label: "Do you need someone right now or can this be scheduled?", field_type: 'select', is_required: false, visible_modes: ['dispatch'], ai_prompt_hint: 'Emergency vs. scheduled pickup' },
  
  // Service-specific fields
  { field_key: 'service_address', field_label: "What's the service address?", field_type: 'address', is_required: true, visible_modes: ['service'], ai_prompt_hint: 'Get the location for service' },
  { field_key: 'preferred_date', field_label: "When would you like to come in?", field_type: 'date', is_required: false, visible_modes: ['service', 'medical'], ai_prompt_hint: 'Preferred appointment date' },
  { field_key: 'preferred_time', field_label: "What time works best?", field_type: 'text', is_required: false, visible_modes: ['service', 'medical'], ai_prompt_hint: 'Morning, afternoon, or specific time' },
  
  // Food-specific fields
  { field_key: 'party_size', field_label: "How many in your party?", field_type: 'number', is_required: true, visible_modes: ['food'], ai_prompt_hint: 'Number of guests' },
  { field_key: 'delivery_address', field_label: "What's your delivery address?", field_type: 'address', is_required: false, visible_modes: ['food'], ai_prompt_hint: 'Only if delivery, not pickup' },
  
  // Medical-specific fields
  { field_key: 'reason_for_visit', field_label: "What brings you in today?", field_type: 'text', is_required: true, visible_modes: ['medical'], ai_prompt_hint: 'Brief reason for appointment' },
  { field_key: 'insurance_provider', field_label: "Who is your insurance provider?", field_type: 'text', is_required: true, visible_modes: ['medical'], ai_prompt_hint: 'Insurance company name' },
];

interface IntakeRequirementsEditorProps {
  businessMode: BusinessMode;
}

export function IntakeRequirementsEditor({ businessMode }: IntakeRequirementsEditorProps) {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [requirements, setRequirements] = useState<IntakeRequirement[]>([]);

  useEffect(() => {
    if (tenant?.id) {
      loadRequirements();
    }
  }, [tenant?.id]);

  const loadRequirements = async () => {
    if (!tenant?.id) return;
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from('intake_requirements')
        .select('*')
        .eq('tenant_id', tenant.id)
        .order('ask_order', { ascending: true });

      if (error) throw error;
      
      setRequirements(data || []);
    } catch (err: any) {
      toast.error("Failed to load requirements");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleSave = async () => {
    if (!tenant?.id) return;
    setIsSaving(true);
    try {
      // Delete removed requirements
      const existingIds = requirements.filter(r => r.id).map(r => r.id);
      
      // Upsert all requirements
      for (const req of requirements) {
        const { error } = await supabase
          .from('intake_requirements')
          .upsert({
            ...req,
            tenant_id: tenant.id,
          }, { onConflict: 'tenant_id,field_key' });

        if (error) throw error;
      }
      
      toast.success("Requirements saved");
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      loadRequirements(); // Reload to get IDs
    } catch (err: any) {
      toast.error(err.message || "Failed to save");
    } finally {
      setIsSaving(false);
    }
  };

  const addRequirement = () => {
    const newReq: IntakeRequirement = {
      tenant_id: tenant?.id || '',
      field_key: `custom_${Date.now()}`,
      field_label: '',
      field_type: 'text',
      options_json: null,
      is_required: false,
      ask_order: requirements.length * 10 + 10,
      visible_modes: ALL_MODES,
      visible_intents: null,
      ai_prompt_hint: '',
      validation_hint: '',
      is_active: true,
    };
    setRequirements([...requirements, newReq]);
  };

  const addSuggested = (suggested: Partial<IntakeRequirement>) => {
    // Check if already exists
    if (requirements.some(r => r.field_key === suggested.field_key)) {
      toast.info("This field already exists");
      return;
    }
    
    const newReq: IntakeRequirement = {
      tenant_id: tenant?.id || '',
      field_key: suggested.field_key || `custom_${Date.now()}`,
      field_label: suggested.field_label || '',
      field_type: suggested.field_type || 'text',
      options_json: null,
      is_required: suggested.is_required || false,
      ask_order: requirements.length * 10 + 10,
      visible_modes: suggested.visible_modes || ALL_MODES,
      visible_intents: null,
      ai_prompt_hint: suggested.ai_prompt_hint || '',
      validation_hint: '',
      is_active: true,
    };
    setRequirements([...requirements, newReq]);
  };

  const updateRequirement = (index: number, updates: Partial<IntakeRequirement>) => {
    const updated = [...requirements];
    updated[index] = { ...updated[index], ...updates };
    setRequirements(updated);
  };

  const removeRequirement = async (index: number) => {
    const req = requirements[index];
    if (req.id) {
      // Delete from database
      const { error } = await supabase
        .from('intake_requirements')
        .delete()
        .eq('id', req.id);
      
      if (error) {
        toast.error("Failed to delete");
        return;
      }
    }
    setRequirements(requirements.filter((_, i) => i !== index));
  };

  // Filter suggestions by current business mode
  const relevantSuggestions = SUGGESTED_FIELDS.filter(s => 
    !s.visible_modes || s.visible_modes.includes(businessMode)
  );

  // Build AI preview
  const buildAIPreview = (): string => {
    const activeReqs = requirements.filter(r => r.is_active);
    if (activeReqs.length === 0) return "No intake questions configured. AI will collect basic info like name and phone.";
    
    const required = activeReqs.filter(r => r.is_required);
    const optional = activeReqs.filter(r => !r.is_required);
    
    let preview = `I'll need to collect ${required.length} required piece${required.length !== 1 ? 's' : ''} of information`;
    if (optional.length > 0) {
      preview += ` and may ask ${optional.length} optional question${optional.length !== 1 ? 's' : ''}`;
    }
    preview += '.';
    
    return preview;
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* AI Preview */}
      <AIPreviewCard 
        title="How AI collects information"
        preview={buildAIPreview()}
      />

      {/* Suggested Fields */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base">Quick Add Common Fields</CardTitle>
          <CardDescription>
            Click to add pre-configured intake questions
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-2">
            {relevantSuggestions.map((suggestion) => (
              <Button
                key={suggestion.field_key}
                variant="outline"
                size="sm"
                onClick={() => addSuggested(suggestion)}
                disabled={requirements.some(r => r.field_key === suggestion.field_key)}
              >
                <Plus className="h-3 w-3 mr-1" />
                {suggestion.field_label?.replace(/\?$/, '')}
              </Button>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Current Requirements */}
      <Card>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <MessageSquare className="h-4 w-4" />
            Required Questions
          </CardTitle>
          <CardDescription>
            Information the AI will collect from every caller
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {requirements.length === 0 ? (
            <div className="text-center py-6 text-muted-foreground">
              No intake questions configured. Add some above or create custom ones.
            </div>
          ) : (
            <div className="space-y-3">
              {requirements.map((req, index) => (
                <div 
                  key={req.field_key} 
                  className="flex items-start gap-3 p-3 rounded-lg border bg-card"
                >
                  <div className="pt-2 cursor-move text-muted-foreground">
                    <GripVertical className="h-4 w-4" />
                  </div>
                  
                  <div className="flex-1 space-y-3">
                    <div className="grid grid-cols-2 gap-3">
                      <div className="space-y-1">
                        <Label className="text-xs">Question</Label>
                        <Input
                          value={req.field_label}
                          onChange={(e) => updateRequirement(index, { field_label: e.target.value })}
                          placeholder="What's your...?"
                        />
                      </div>
                      
                      <div className="space-y-1">
                        <Label className="text-xs">Field Type</Label>
                        <Select 
                          value={req.field_type} 
                          onValueChange={(v) => updateRequirement(index, { field_type: v })}
                        >
                          <SelectTrigger>
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {FIELD_TYPES.map((type) => (
                              <SelectItem key={type.value} value={type.value}>
                                {type.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                    </div>
                    
                    <div className="flex items-center gap-4">
                      <label className="flex items-center gap-2 cursor-pointer">
                        <Switch
                          checked={req.is_required}
                          onCheckedChange={(v) => updateRequirement(index, { is_required: v })}
                        />
                        <span className="text-sm">Required</span>
                      </label>
                      
                      <label className="flex items-center gap-2 cursor-pointer">
                        <Switch
                          checked={req.is_active}
                          onCheckedChange={(v) => updateRequirement(index, { is_active: v })}
                        />
                        <span className="text-sm">Active</span>
                      </label>
                    </div>
                  </div>
                  
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => removeRequirement(index)}
                    className="text-destructive hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              ))}
            </div>
          )}
          
          <Button variant="outline" onClick={addRequirement} className="w-full">
            <Plus className="h-4 w-4 mr-2" />
            Add Custom Question
          </Button>
        </CardContent>
      </Card>

      {/* Save Button */}
      <div className="flex justify-end pt-2">
        <Button onClick={handleSave} disabled={isSaving}>
          {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
          <Save className="h-4 w-4 mr-2" />
          Save Requirements
        </Button>
      </div>
    </div>
  );
}

/**
 * Apply Industry Template Modal
 *
 * Shows a preview of what will be added/changed when applying an industry template.
 * Supports two modes: Merge (non-destructive) and Replace (overwrite).
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Alert, AlertDescription } from "@/components/ui/alert";
import {
  Loader2,
  Package,
  HelpCircle,
  MessageSquare,
  FileText,
  MapPin,
  AlertTriangle,
  CheckCircle2,
  Plus,
  AlertCircle,
  Sparkles,
} from "lucide-react";
import {
  getTemplate,
  previewTemplateApplication,
  applyTemplate,
  fetchCurrentBrainState,
  type IndustryTemplate,
  type TemplatePreviewResult,
  type ApplyMode,
} from "@/lib/industryTemplates";
import { useToast } from "@/hooks/use-toast";
import { useQueryClient } from "@tanstack/react-query";

interface ApplyTemplateModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  industryKey: string;
  onApplied?: () => void;
}

export function ApplyTemplateModal({
  open,
  onOpenChange,
  industryKey,
  onApplied,
}: ApplyTemplateModalProps) {
  const { tenant, refreshTenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [isLoading, setIsLoading] = useState(true);
  const [isApplying, setIsApplying] = useState(false);
  const [template, setTemplate] = useState<IndustryTemplate | null>(null);
  const [preview, setPreview] = useState<TemplatePreviewResult | null>(null);
  const [selectedMode, setSelectedMode] = useState<ApplyMode>("merge");

  // Load template and generate preview
  useEffect(() => {
    if (!open || !tenant?.id || !industryKey) return;

    async function loadPreview() {
      setIsLoading(true);
      try {
        const tmpl = getTemplate(industryKey);
        if (!tmpl) {
          throw new Error("Template not found");
        }
        setTemplate(tmpl);

        const currentState = await fetchCurrentBrainState(tenant!.id);
        const previewResult = previewTemplateApplication(currentState, tmpl, selectedMode);
        setPreview(previewResult);
      } catch (error) {
        console.error("Failed to load template preview:", error);
        toast({
          title: "Error",
          description: "Failed to load template preview.",
          variant: "destructive",
        });
      } finally {
        setIsLoading(false);
      }
    }

    loadPreview();
  }, [open, tenant?.id, industryKey, selectedMode, toast]);

  // Handle mode change
  const handleModeChange = async (mode: ApplyMode) => {
    setSelectedMode(mode);
    if (template && tenant?.id) {
      setIsLoading(true);
      try {
        const currentState = await fetchCurrentBrainState(tenant.id);
        const previewResult = previewTemplateApplication(currentState, template, mode);
        setPreview(previewResult);
      } catch (error) {
        console.error("Failed to update preview:", error);
      } finally {
        setIsLoading(false);
      }
    }
  };

  // Handle apply
  const handleApply = async () => {
    if (!template || !preview || !tenant?.id) return;

    setIsApplying(true);
    try {
      const result = await applyTemplate(tenant.id, template, selectedMode, preview);

      if (result.success) {
        toast({
          title: "Template Applied",
          description: `Added ${result.servicesAdded} services, ${result.faqsAdded} FAQs, and ${result.objectionsAdded} objection responses.${result.conflictsCreated > 0 ? ` ${result.conflictsCreated} items sent to Review Queue.` : ""}`,
        });

        // Invalidate queries to refresh data
        queryClient.invalidateQueries({ queryKey: ["services"] });
        queryClient.invalidateQueries({ queryKey: ["business-faqs"] });
        queryClient.invalidateQueries({ queryKey: ["objection-responses"] });
        queryClient.invalidateQueries({ queryKey: ["service-area"] });
        queryClient.invalidateQueries({ queryKey: ["brain-review-count"] });
        refreshTenant?.();

        onOpenChange(false);
        onApplied?.();
      } else {
        toast({
          title: "Partial Success",
          description: `Template applied with some errors: ${result.errors.join(", ")}`,
          variant: "destructive",
        });
      }
    } catch (error) {
      console.error("Failed to apply template:", error);
      toast({
        title: "Error",
        description: "Failed to apply template. Please try again.",
        variant: "destructive",
      });
    } finally {
      setIsApplying(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[85vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-primary" />
            Apply Industry Template
            {template && (
              <Badge variant="secondary" className="ml-2">
                {template.icon} {template.name}
              </Badge>
            )}
          </DialogTitle>
          <DialogDescription>
            Pre-populate your Business Brain with industry-specific defaults. Everything
            remains fully editable.
          </DialogDescription>
        </DialogHeader>

        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          </div>
        ) : template && preview ? (
          <div className="flex-1 overflow-hidden flex flex-col gap-4">
            {/* Mode Selection */}
            <div className="flex gap-2">
              <Button
                variant={selectedMode === "merge" ? "default" : "outline"}
                size="sm"
                onClick={() => handleModeChange("merge")}
                className="flex-1"
              >
                <Plus className="h-4 w-4 mr-1" />
                Merge (Recommended)
              </Button>
              <Button
                variant={selectedMode === "replace" ? "destructive" : "outline"}
                size="sm"
                onClick={() => handleModeChange("replace")}
                className="flex-1"
              >
                <AlertTriangle className="h-4 w-4 mr-1" />
                Replace All
              </Button>
            </div>

            {selectedMode === "replace" && (
              <Alert variant="destructive">
                <AlertTriangle className="h-4 w-4" />
                <AlertDescription>
                  Replace mode will delete all existing services, FAQs, objection responses,
                  and policies before applying the template.
                </AlertDescription>
              </Alert>
            )}

            {/* Preview Summary */}
            <div className="grid grid-cols-2 gap-3 text-sm">
              <div className="flex items-center gap-2 p-3 bg-emerald-500/10 rounded-md">
                <CheckCircle2 className="h-4 w-4 text-emerald-600" />
                <span className="font-medium">{preview.totals.itemsToAdd}</span>
                <span className="text-muted-foreground">items to add</span>
              </div>
              {selectedMode === "merge" && preview.totals.conflictCount > 0 && (
                <div className="flex items-center gap-2 p-3 bg-amber-500/10 rounded-md">
                  <AlertCircle className="h-4 w-4 text-amber-600" />
                  <span className="font-medium">{preview.totals.conflictCount}</span>
                  <span className="text-muted-foreground">conflicts → Review Queue</span>
                </div>
              )}
            </div>

            {/* Preview Tabs */}
            <Tabs defaultValue="services" className="flex-1 overflow-hidden flex flex-col">
              <TabsList className="grid grid-cols-5 w-full">
                <TabsTrigger value="services" className="gap-1 text-xs">
                  <Package className="h-3 w-3" />
                  Services
                  <Badge variant="secondary" className="h-4 px-1 text-[10px]">
                    {preview.services.toAdd.length}
                  </Badge>
                </TabsTrigger>
                <TabsTrigger value="faqs" className="gap-1 text-xs">
                  <HelpCircle className="h-3 w-3" />
                  FAQs
                  <Badge variant="secondary" className="h-4 px-1 text-[10px]">
                    {preview.faqs.toAdd.length}
                  </Badge>
                </TabsTrigger>
                <TabsTrigger value="objections" className="gap-1 text-xs">
                  <MessageSquare className="h-3 w-3" />
                  Objections
                  <Badge variant="secondary" className="h-4 px-1 text-[10px]">
                    {preview.objections.toAdd.length}
                  </Badge>
                </TabsTrigger>
                <TabsTrigger value="policies" className="gap-1 text-xs">
                  <FileText className="h-3 w-3" />
                  Policies
                  <Badge variant="secondary" className="h-4 px-1 text-[10px]">
                    {preview.policies.toAdd.length}
                  </Badge>
                </TabsTrigger>
                <TabsTrigger value="area" className="gap-1 text-xs">
                  <MapPin className="h-3 w-3" />
                  Area
                </TabsTrigger>
              </TabsList>

              <ScrollArea className="flex-1 mt-3">
                <TabsContent value="services" className="mt-0">
                  <PreviewList
                    items={preview.services.toAdd.map((s) => ({
                      title: s.name,
                      subtitle: s.description || `${s.duration_minutes} min`,
                      badge:
                        s.base_price_model === "fixed"
                          ? `$${((s.fixed_price_cents || 0) / 100).toFixed(0)}`
                          : s.base_price_model === "starting_at"
                            ? `From $${((s.starting_price_cents || 0) / 100).toFixed(0)}`
                            : "Quote",
                    }))}
                    conflicts={preview.services.conflicts.map((c) => ({
                      title: c.templateItem.name,
                      conflict: `Already exists as "${c.existingName}"`,
                    }))}
                    emptyMessage="No services to add"
                  />
                </TabsContent>

                <TabsContent value="faqs" className="mt-0">
                  <PreviewList
                    items={preview.faqs.toAdd.map((f) => ({
                      title: f.question,
                      subtitle: f.answer.substring(0, 80) + (f.answer.length > 80 ? "..." : ""),
                    }))}
                    conflicts={preview.faqs.conflicts.map((c) => ({
                      title: c.templateItem.question,
                      conflict: `Similar to "${c.existingQuestion}"`,
                    }))}
                    emptyMessage="No FAQs to add"
                  />
                </TabsContent>

                <TabsContent value="objections" className="mt-0">
                  <PreviewList
                    items={preview.objections.toAdd.map((o) => ({
                      title: `"${o.objection}"`,
                      subtitle:
                        o.response.substring(0, 80) + (o.response.length > 80 ? "..." : ""),
                    }))}
                    conflicts={preview.objections.conflicts.map((c) => ({
                      title: `"${c.templateItem.objection}"`,
                      conflict: `Similar to "${c.existingObjection}"`,
                    }))}
                    emptyMessage="No objection responses to add"
                  />
                </TabsContent>

                <TabsContent value="policies" className="mt-0">
                  <PreviewList
                    items={preview.policies.toAdd.map((p) => ({
                      title: p.type.charAt(0).toUpperCase() + p.type.slice(1) + " Policy",
                      subtitle: p.text.substring(0, 100) + (p.text.length > 100 ? "..." : ""),
                    }))}
                    conflicts={preview.policies.conflicts.map((c) => ({
                      title:
                        c.templateItem.type.charAt(0).toUpperCase() +
                        c.templateItem.type.slice(1) +
                        " Policy",
                      conflict: "Already configured",
                    }))}
                    emptyMessage="No policies to add"
                  />
                </TabsContent>

                <TabsContent value="area" className="mt-0">
                  <div className="space-y-3">
                    {preview.service_area.willConfigure ? (
                      <div className="p-3 bg-muted rounded-md">
                        <p className="text-sm font-medium mb-2">Service Area Defaults</p>
                        <div className="text-xs text-muted-foreground space-y-1">
                          <p>
                            <span className="font-medium">Mode:</span>{" "}
                            {preview.service_area.defaults.mode}
                          </p>
                          {preview.service_area.defaults.radius_miles && (
                            <p>
                              <span className="font-medium">Radius:</span>{" "}
                              {preview.service_area.defaults.radius_miles} miles
                            </p>
                          )}
                          {preview.service_area.defaults.restrictions.no_cross_state_lines && (
                            <p>
                              <span className="font-medium">Restriction:</span> No crossing
                              state lines
                            </p>
                          )}
                          <p className="italic mt-2">{preview.service_area.defaults.notes}</p>
                        </div>
                      </div>
                    ) : (
                      <div className="p-3 bg-muted/50 rounded-md text-center text-sm text-muted-foreground">
                        Service area already configured - will not be changed in merge mode
                      </div>
                    )}
                  </div>
                </TabsContent>
              </ScrollArea>
            </Tabs>
          </div>
        ) : (
          <div className="py-8 text-center text-muted-foreground">
            Template not found for "{industryKey}"
          </div>
        )}

        <DialogFooter className="gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={isApplying}>
            Cancel
          </Button>
          <Button onClick={handleApply} disabled={isLoading || isApplying || !preview}>
            {isApplying ? (
              <>
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                Applying...
              </>
            ) : (
              <>
                <Sparkles className="h-4 w-4 mr-2" />
                Apply Template
              </>
            )}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// ============================================================================
// PREVIEW LIST COMPONENT
// ============================================================================

interface PreviewListProps {
  items: Array<{
    title: string;
    subtitle?: string;
    badge?: string;
  }>;
  conflicts?: Array<{
    title: string;
    conflict: string;
  }>;
  emptyMessage: string;
}

function PreviewList({ items, conflicts = [], emptyMessage }: PreviewListProps) {
  if (items.length === 0 && conflicts.length === 0) {
    return (
      <div className="p-4 text-center text-sm text-muted-foreground">{emptyMessage}</div>
    );
  }

  return (
    <div className="space-y-2">
      {/* Items to add */}
      {items.map((item, idx) => (
        <div
          key={idx}
          className="flex items-start gap-2 p-2 bg-emerald-500/5 rounded-md border border-emerald-500/20"
        >
          <Plus className="h-4 w-4 text-emerald-600 shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2">
              <p className="text-sm font-medium truncate">{item.title}</p>
              {item.badge && (
                <Badge variant="secondary" className="text-[10px] shrink-0">
                  {item.badge}
                </Badge>
              )}
            </div>
            {item.subtitle && (
              <p className="text-xs text-muted-foreground truncate">{item.subtitle}</p>
            )}
          </div>
        </div>
      ))}

      {/* Conflicts */}
      {conflicts.map((conflict, idx) => (
        <div
          key={`conflict-${idx}`}
          className="flex items-start gap-2 p-2 bg-amber-500/5 rounded-md border border-amber-500/20"
        >
          <AlertCircle className="h-4 w-4 text-amber-600 shrink-0 mt-0.5" />
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium truncate">{conflict.title}</p>
            <p className="text-xs text-amber-600">{conflict.conflict}</p>
          </div>
        </div>
      ))}
    </div>
  );
}

/**
 * Industry Template Card
 *
 * Allows users to select an industry and apply pre-configured templates
 * to quickly set up their Business Brain.
 */

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Sparkles, Building2 } from "lucide-react";
import { ApplyTemplateModal } from "./ApplyTemplateModal";
import { getTemplateOptionsForMode, getTemplate } from "@/lib/industryTemplates";

// Format business mode for display
const businessModeLabels: Record<string, string> = {
  service: "Service & Booking",
  food: "Food & Restaurant",
  medical: "Medical",
  dispatch: "Dispatch & Towing",
  general: "General",
};

export function IndustryTemplateCard() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const [showTemplateModal, setShowTemplateModal] = useState(false);
  const [selectedIndustry, setSelectedIndustry] = useState<string>("");

  // Get formatted business mode label
  const businessModeLabel = businessModeLabels[businessMode] || businessMode;

  // Get templates filtered by the user's business mode
  const templateOptions = getTemplateOptionsForMode(businessMode);

  // Check if template exists for selected industry
  const selectedTemplate = selectedIndustry ? getTemplate(selectedIndustry) : null;

  const handleApplyTemplate = () => {
    if (selectedIndustry) {
      setShowTemplateModal(true);
    }
  };

  return (
    <>
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Building2 className="h-5 w-5" />
            Quick Start Templates
          </CardTitle>
          <CardDescription>
            Apply pre-built services, FAQs, and policies to get started quickly
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Current Business Type Display */}
          <div className="flex items-center gap-2 p-3 bg-muted rounded-md">
            <span className="text-sm text-muted-foreground">Your business type:</span>
            <Badge variant="secondary">
              {businessModeLabel}
            </Badge>
          </div>

          {/* Template Selector */}
          <div className="space-y-2">
            <Label>Apply a business template</Label>
            <Select value={selectedIndustry} onValueChange={setSelectedIndustry}>
              <SelectTrigger>
                <SelectValue placeholder="Choose a template..." />
              </SelectTrigger>
              <SelectContent>
                {templateOptions.map((option) => (
                  <SelectItem key={option.value} value={option.value}>
                    <span className="flex items-center gap-2">
                      <span>{option.icon}</span>
                      <span>{option.label}</span>
                    </span>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {templateOptions.length === 0 && (
              <p className="text-xs text-muted-foreground">No templates available for your business type.</p>
            )}
          </div>

          {/* Template Preview Info */}
          {selectedTemplate && (
            <div className="p-3 bg-primary/5 border border-primary/20 rounded-md space-y-2">
              <div className="flex items-center gap-2">
                <Sparkles className="h-4 w-4 text-primary" />
                <span className="text-sm font-medium">
                  {selectedTemplate.icon} {selectedTemplate.name} Template
                </span>
              </div>
              <p className="text-xs text-muted-foreground">
                This template includes:
              </p>
              <div className="grid grid-cols-2 gap-2 text-xs text-muted-foreground">
                <div>
                  <span className="font-medium">{selectedTemplate.defaults.services.length}</span>{" "}
                  services
                </div>
                <div>
                  <span className="font-medium">{selectedTemplate.defaults.faqs.length}</span>{" "}
                  FAQs
                </div>
                <div>
                  <span className="font-medium">
                    {selectedTemplate.defaults.objections.length}
                  </span>{" "}
                  objection handlers
                </div>
                <div>
                  <span className="font-medium">
                    {selectedTemplate.defaults.policies.length}
                  </span>{" "}
                  policies
                </div>
              </div>
            </div>
          )}

          {/* Apply Button */}
          <Button
            onClick={handleApplyTemplate}
            disabled={!selectedIndustry || !selectedTemplate}
            className="w-full"
          >
            <Sparkles className="h-4 w-4 mr-2" />
            Apply Template
          </Button>

          <p className="text-xs text-muted-foreground text-center">
            Templates provide starting defaults. Everything remains fully editable.
          </p>
        </CardContent>
      </Card>

      {/* Apply Template Modal */}
      <ApplyTemplateModal
        open={showTemplateModal}
        onOpenChange={setShowTemplateModal}
        industryKey={selectedIndustry}
        onApplied={() => {
          // Could refresh page or show success state
        }}
      />
    </>
  );
}

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { useAuth } from "@/contexts/AuthContext";
import { createService } from "@/lib/brain/writeBrainFact";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import {
  Loader2,
  ClipboardPaste,
  Wand2,
  CheckCircle2,
  AlertCircle,
  X,
  Check,
} from "lucide-react";

interface PasteFromPOSDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

interface ParsedService {
  name: string;
  description: string;
  duration_minutes: number;
  price_amount: number | null;
  price_type: "fixed" | "starting_at" | "quote_only";
  selected: boolean;
}

export function PasteFromPOSDialog({ open, onOpenChange }: PasteFromPOSDialogProps) {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  const [pastedText, setPastedText] = useState("");
  const [parsedServices, setParsedServices] = useState<ParsedService[]>([]);
  const [isParsing, setIsParsing] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const [result, setResult] = useState<{ success: number; failed: number } | null>(null);
  const [parseError, setParseError] = useState<string | null>(null);

  const handleParse = async () => {
    if (!pastedText.trim() || !tenant?.id) return;

    setIsParsing(true);
    setParseError(null);
    setParsedServices([]);

    try {
      const { data, error } = await supabase.functions.invoke("parse-services-text", {
        body: { text: pastedText.trim(), tenantId: tenant.id },
      });

      if (error) throw error;

      if (!data?.services || data.services.length === 0) {
        setParseError("No services could be extracted from the text. Try a different format.");
        return;
      }

      setParsedServices(
        data.services.map((s: any) => ({
          name: s.name || "",
          description: s.description || "",
          duration_minutes: s.duration_minutes || 60,
          price_amount: s.price_amount ?? null,
          price_type: s.price_type || "fixed",
          selected: true,
        }))
      );
    } catch (err: any) {
      console.error("Parse error:", err);
      setParseError(err.message || "Failed to parse text. Please try again.");
    } finally {
      setIsParsing(false);
    }
  };

  const toggleService = (index: number) => {
    setParsedServices((prev) =>
      prev.map((s, i) => (i === index ? { ...s, selected: !s.selected } : s))
    );
  };

  const handleImport = async () => {
    if (!tenant?.id) return;
    const selected = parsedServices.filter((s) => s.selected);
    if (selected.length === 0) return;

    setIsImporting(true);
    let success = 0;
    let failed = 0;

    for (const svc of selected) {
      try {
        await createService(tenant.id, {
          name: svc.name,
          description: svc.description || undefined,
          duration_minutes: svc.duration_minutes,
          price_type: svc.price_type,
          price_amount: svc.price_amount ?? undefined,
        });
        success++;
      } catch {
        failed++;
      }
    }

    setIsImporting(false);
    setResult({ success, failed });
    queryClient.invalidateQueries({ queryKey: ["services"] });
    queryClient.invalidateQueries({ queryKey: ["business-context"] });
    toast.success(`${success} service${success !== 1 ? "s" : ""} imported!`);
  };

  const handleClose = () => {
    setPastedText("");
    setParsedServices([]);
    setResult(null);
    setParseError(null);
    onOpenChange(false);
  };

  const selectedCount = parsedServices.filter((s) => s.selected).length;

  const formatPrice = (svc: ParsedService) => {
    if (svc.price_type === "quote_only") return "Quote";
    if (svc.price_amount == null) return "—";
    const prefix = svc.price_type === "starting_at" ? "From " : "";
    return `${prefix}$${svc.price_amount}`;
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <ClipboardPaste className="h-5 w-5" />
            Paste from POS (Square, Clover, etc.)
          </DialogTitle>
          <DialogDescription>
            Copy your service list from your POS system and paste it below. AI will parse it into individual services.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Step 1: Paste */}
          {parsedServices.length === 0 && !result && (
            <>
              <Textarea
                placeholder={`Paste your service list here...\n\nExample:\nFull Detail - Starting at $250 (3-4 hours)\nInterior Detail - $150 (2 hours)\nExterior Wash & Wax - $75 (1 hour)\nPaint Correction - Quote required`}
                value={pastedText}
                onChange={(e) => setPastedText(e.target.value)}
                className="min-h-[200px] resize-none font-mono text-sm"
                disabled={isParsing}
              />

              {parseError && (
                <div className="bg-destructive/10 text-destructive p-3 rounded-md flex items-center gap-2 text-sm">
                  <AlertCircle className="h-4 w-4 shrink-0" />
                  {parseError}
                </div>
              )}

              <Button
                onClick={handleParse}
                disabled={isParsing || !pastedText.trim()}
                className="w-full"
              >
                {isParsing ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Parsing with AI...
                  </>
                ) : (
                  <>
                    <Wand2 className="h-4 w-4 mr-2" />
                    Parse Services
                  </>
                )}
              </Button>
            </>
          )}

          {/* Step 2: Preview */}
          {parsedServices.length > 0 && !result && (
            <>
              <p className="text-sm text-muted-foreground">
                Found {parsedServices.length} services. Deselect any you don't want to import.
              </p>
              <div className="border rounded-md overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b bg-muted/50">
                      <th className="text-left p-2 font-medium w-8"></th>
                      <th className="text-left p-2 font-medium">Service</th>
                      <th className="text-left p-2 font-medium">Price</th>
                      <th className="text-left p-2 font-medium">Duration</th>
                    </tr>
                  </thead>
                  <tbody>
                    {parsedServices.map((svc, i) => (
                      <tr
                        key={i}
                        className={`border-b last:border-0 cursor-pointer hover:bg-muted/30 transition-colors ${
                          !svc.selected ? "opacity-40" : ""
                        }`}
                        onClick={() => toggleService(i)}
                      >
                        <td className="p-2 text-center">
                          {svc.selected ? (
                            <Check className="h-4 w-4 text-primary" />
                          ) : (
                            <X className="h-4 w-4 text-muted-foreground" />
                          )}
                        </td>
                        <td className="p-2">
                          <div className="font-medium">{svc.name}</div>
                          {svc.description && (
                            <div className="text-xs text-muted-foreground truncate max-w-[300px]">
                              {svc.description}
                            </div>
                          )}
                        </td>
                        <td className="p-2">
                          <Badge variant="secondary" className="text-xs">
                            {formatPrice(svc)}
                          </Badge>
                        </td>
                        <td className="p-2 text-muted-foreground">
                          {svc.duration_minutes}min
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <Button
                variant="outline"
                size="sm"
                onClick={() => {
                  setParsedServices([]);
                  setParseError(null);
                }}
              >
                ← Back to paste
              </Button>
            </>
          )}

          {/* Step 3: Result */}
          {result && (
            <div className="bg-primary/10 text-primary p-4 rounded-md flex items-center gap-3">
              <CheckCircle2 className="h-5 w-5" />
              <span className="text-sm font-medium">
                {result.success} service{result.success !== 1 ? "s" : ""} imported
                {result.failed > 0 && `, ${result.failed} failed`}
              </span>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={handleClose}>
            {result ? "Done" : "Cancel"}
          </Button>
          {parsedServices.length > 0 && !result && (
            <Button onClick={handleImport} disabled={isImporting || selectedCount === 0}>
              {isImporting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Import {selectedCount} Service{selectedCount !== 1 ? "s" : ""}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useRef } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useKnowledgeUploads } from "@/hooks/useKnowledgeUploads";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Loader2, Upload, Wand2, FileText, ClipboardPaste } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

const acceptedFormats = ".pdf,.png,.jpg,.jpeg,.docx,.xlsx";
const MAX_TEXT_LENGTH = 50000; // 50k characters max for pasted text

interface InlineUploadButtonProps {
  /** The type of content this upload is for - used to hint expected document type */
  contentType: "menu" | "services" | "faqs" | "policies" | "hours" | "general";
  /** Optional callback when upload completes successfully */
  onUploadComplete?: () => void;
  /** Size variant: compact (small button), default (dashed border), prominent (highlighted card) */
  variant?: "default" | "compact" | "prominent";
  /** Custom class name */
  className?: string;
}

/**
 * InlineUploadButton - Upload files or paste text to auto-fill data
 */
export function InlineUploadButton({
  contentType,
  onUploadComplete,
  variant = "default",
  className
}: InlineUploadButtonProps) {
  const { tenant } = useAuth();
  const { createUpload } = useKnowledgeUploads();
  const [isProcessing, setIsProcessing] = useState(false);
  const [dialogOpen, setDialogOpen] = useState(false);
  const [pastedText, setPastedText] = useState("");
  const [activeTab, setActiveTab] = useState<"upload" | "paste">("upload");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const contentTypeLabels: Record<string, string> = {
    menu: "menu",
    services: "service list",
    faqs: "FAQ document",
    policies: "policies",
    hours: "hours",
    general: "document"
  };

  const sourceTypeMap: Record<string, string> = {
    menu: "menu_pdf",
    services: "services_doc",
    faqs: "faq_doc",
    policies: "general",
    hours: "general",
    general: "general"
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      await handleFileUpload(files[0]);
    }
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleFileUpload = async (file: File) => {
    if (!tenant?.id) {
      toast.error("No tenant found. Please refresh and try again.");
      return;
    }

    const validExtensions = [".pdf", ".png", ".jpg", ".jpeg", ".docx", ".xlsx"];
    const fileExtension = "." + file.name.split(".").pop()?.toLowerCase();
    if (!validExtensions.includes(fileExtension)) {
      toast.error("Please upload a PDF, image, or document file.");
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      toast.error("Please upload a file smaller than 10MB");
      return;
    }

    setIsProcessing(true);

    try {
      const source = await createUpload({
        fileName: file.name,
        sourceType: sourceTypeMap[contentType] as any
      });

      const filePath = `${tenant.id}/${source.id}/${file.name}`;
      const { error: uploadError } = await supabase.storage
        .from("knowledge-documents")
        .upload(filePath, file);

      if (uploadError) {
        throw new Error(`Upload failed: ${uploadError.message}`);
      }

      const { data: urlData } = supabase.storage
        .from("knowledge-documents")
        .getPublicUrl(filePath);

      await supabase
        .from("knowledge_sources")
        .update({ file_url: urlData.publicUrl, status: "processing" })
        .eq("id", source.id);

      await supabase.functions.invoke("process-knowledge-upload", {
        body: {
          sourceId: source.id,
          tenantId: tenant.id,
          fileUrl: urlData.publicUrl,
          sourceType: "auto",
          autoDetect: true
        }
      });

      toast.success("Document uploaded! Check the Review Queue to approve extracted items.", {
        action: {
          label: "Review",
          onClick: () => window.location.href = "/app/business-brain?section=knowledge"
        }
      });

      setDialogOpen(false);
      onUploadComplete?.();
    } catch (error) {
      console.error("Upload error:", error);
      toast.error(error instanceof Error ? error.message : "Upload failed");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleTextSubmit = async () => {
    if (!tenant?.id) {
      toast.error("No tenant found. Please refresh and try again.");
      return;
    }

    const trimmedText = pastedText.trim();
    if (!trimmedText) {
      toast.error("Please paste some text first.");
      return;
    }

    if (trimmedText.length > MAX_TEXT_LENGTH) {
      toast.error(`Text is too long. Maximum ${MAX_TEXT_LENGTH.toLocaleString()} characters allowed.`);
      return;
    }

    setIsProcessing(true);

    try {
      // Create a knowledge source record for pasted text
      const source = await createUpload({
        fileName: `Pasted ${contentTypeLabels[contentType]} (${new Date().toLocaleDateString()})`,
        sourceType: sourceTypeMap[contentType] as any
      });

      // Update status to processing
      await supabase
        .from("knowledge_sources")
        .update({ status: "processing" })
        .eq("id", source.id);

      // Call the edge function with the raw text instead of a file URL
      await supabase.functions.invoke("process-knowledge-upload", {
        body: {
          sourceId: source.id,
          tenantId: tenant.id,
          rawText: trimmedText,
          sourceType: sourceTypeMap[contentType],
          autoDetect: true
        }
      });

      toast.success("Text processed! Check the Review Queue to approve extracted items.", {
        action: {
          label: "Review",
          onClick: () => window.location.href = "/app/business-brain?section=knowledge"
        }
      });

      setPastedText("");
      setDialogOpen(false);
      onUploadComplete?.();
    } catch (error) {
      console.error("Text processing error:", error);
      toast.error(error instanceof Error ? error.message : "Processing failed");
    } finally {
      setIsProcessing(false);
    }
  };

  const openDialog = () => {
    setDialogOpen(true);
    setActiveTab("upload");
    setPastedText("");
  };

  const fileInput = (
    <input
      ref={fileInputRef}
      type="file"
      accept={acceptedFormats}
      onChange={handleFileSelect}
      className="hidden"
    />
  );

  const uploadDialog = (
    <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
      <DialogContent className="sm:max-w-lg">
        <DialogHeader>
          <DialogTitle>Import your {contentTypeLabels[contentType]}</DialogTitle>
          <DialogDescription>
            Upload a file or paste text — AI will extract and organize the information for you.
          </DialogDescription>
        </DialogHeader>

        <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as "upload" | "paste")} className="mt-2">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="upload" className="gap-2">
              <FileText className="h-4 w-4" />
              Upload File
            </TabsTrigger>
            <TabsTrigger value="paste" className="gap-2">
              <ClipboardPaste className="h-4 w-4" />
              Paste Text
            </TabsTrigger>
          </TabsList>

          <TabsContent value="upload" className="mt-4">
            <div
              onClick={() => !isProcessing && fileInputRef.current?.click()}
              className={cn(
                "border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-colors",
                "hover:border-primary/50 hover:bg-primary/5",
                isProcessing && "opacity-50 pointer-events-none"
              )}
            >
              {fileInput}
              {isProcessing ? (
                <div className="flex flex-col items-center gap-3">
                  <Loader2 className="h-10 w-10 text-primary animate-spin" />
                  <p className="text-sm text-muted-foreground">Processing your file...</p>
                </div>
              ) : (
                <div className="flex flex-col items-center gap-3">
                  <Upload className="h-10 w-10 text-muted-foreground" />
                  <div>
                    <p className="font-medium">Click to upload</p>
                    <p className="text-sm text-muted-foreground mt-1">
                      PDF, image, Word, or Excel file
                    </p>
                  </div>
                </div>
              )}
            </div>
          </TabsContent>

          <TabsContent value="paste" className="mt-4 space-y-4">
            <div>
              <Textarea
                placeholder={`Paste your ${contentTypeLabels[contentType]} here...\n\nFor example, copy your menu from your website, a list of services with prices, or FAQ content.`}
                value={pastedText}
                onChange={(e) => setPastedText(e.target.value)}
                className="min-h-[200px] resize-none"
                disabled={isProcessing}
              />
              <p className="text-xs text-muted-foreground mt-2">
                {pastedText.length.toLocaleString()} / {MAX_TEXT_LENGTH.toLocaleString()} characters
              </p>
            </div>
            <Button
              onClick={handleTextSubmit}
              disabled={isProcessing || !pastedText.trim()}
              className="w-full"
            >
              {isProcessing ? (
                <>
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  Processing...
                </>
              ) : (
                <>
                  <Wand2 className="h-4 w-4 mr-2" />
                  Extract & Import
                </>
              )}
            </Button>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );

  if (variant === "compact") {
    return (
      <>
        {uploadDialog}
        <Button
          variant="outline"
          size="sm"
          onClick={openDialog}
          disabled={isProcessing}
          className={cn("gap-2", className)}
        >
          {isProcessing ? (
            <Loader2 className="h-3.5 w-3.5 animate-spin" />
          ) : (
            <Upload className="h-3.5 w-3.5" />
          )}
          Import
        </Button>
      </>
    );
  }

  if (variant === "prominent") {
    return (
      <>
        {uploadDialog}
        <button
          onClick={openDialog}
          disabled={isProcessing}
          className={cn(
            "w-full flex items-center gap-4 p-4 rounded-xl border-2 border-dashed",
            "border-primary/30 bg-primary/5 hover:bg-primary/10 hover:border-primary/50",
            "text-left transition-all duration-200 group",
            isProcessing && "opacity-50 pointer-events-none",
            className
          )}
        >
          <div className="flex-shrink-0 h-12 w-12 rounded-lg bg-primary/10 flex items-center justify-center group-hover:bg-primary/20 transition-colors">
            {isProcessing ? (
              <Loader2 className="h-6 w-6 text-primary animate-spin" />
            ) : (
              <Wand2 className="h-6 w-6 text-primary" />
            )}
          </div>
          <div className="flex-1 min-w-0">
            <p className="font-medium text-foreground">
              {isProcessing ? "Processing your content..." : `Import your ${contentTypeLabels[contentType]}`}
            </p>
            <p className="text-sm text-muted-foreground mt-0.5">
              {isProcessing 
                ? "AI is extracting items — check Review Queue when done"
                : "Upload a file or paste text — AI will extract and organize it"
              }
            </p>
          </div>
          {!isProcessing && (
            <Upload className="h-5 w-5 text-muted-foreground group-hover:text-primary transition-colors flex-shrink-0" />
          )}
        </button>
      </>
    );
  }

  // Default variant
  return (
    <>
      {uploadDialog}
      <button
        onClick={openDialog}
        disabled={isProcessing}
        className={cn(
          "group flex items-center gap-2 px-3 py-2 rounded-lg border border-dashed",
          "border-muted-foreground/25 hover:border-primary/50 hover:bg-primary/5",
          "text-sm text-muted-foreground hover:text-primary transition-colors",
          isProcessing && "opacity-50 pointer-events-none",
          className
        )}
      >
        {isProcessing ? (
          <Loader2 className="h-4 w-4 animate-spin" />
        ) : (
          <Wand2 className="h-4 w-4" />
        )}
        <span>
          {isProcessing 
            ? "Processing..." 
            : `Import ${contentTypeLabels[contentType]} to auto-fill`
          }
        </span>
      </button>
    </>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Globe, Loader2, Check, X, AlertCircle, Sparkles } from "lucide-react";
import { createService, createFAQ } from "@/lib/brain/writeBrainFact";
import { invalidateBrainQueries } from "@/lib/brain/invalidateBrainQueries";
import { toast } from "sonner";

interface ExtractedData {
  business_name: string | null;
  phone: string | null;
  address: string | null;
  hours: Record<string, { open: string; close: string; is_open: boolean }> | null;
  services: Array<{
    name: string;
    description: string;
    price_amount: number | null;
    duration_minutes: number | null;
  }>;
  faqs: Array<{ question: string; answer: string }>;
  description: string | null;
}

type WizardStep = "input" | "loading" | "preview" | "applying" | "done";

interface WebsiteImportWizardProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function WebsiteImportWizard({ open, onOpenChange }: WebsiteImportWizardProps) {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  const [url, setUrl] = useState("");
  const [step, setStep] = useState<WizardStep>("input");
  const [extractedData, setExtractedData] = useState<ExtractedData | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [selectedServices, setSelectedServices] = useState<Set<number>>(new Set());
  const [selectedFaqs, setSelectedFaqs] = useState<Set<number>>(new Set());
  const [applyProgress, setApplyProgress] = useState({ current: 0, total: 0 });

  const resetWizard = () => {
    setUrl("");
    setStep("input");
    setExtractedData(null);
    setError(null);
    setSelectedServices(new Set());
    setSelectedFaqs(new Set());
    setApplyProgress({ current: 0, total: 0 });
  };

  const handleClose = () => {
    onOpenChange(false);
    // Reset after animation
    setTimeout(resetWizard, 300);
  };

  const handleFetch = async () => {
    if (!tenant?.id || !url.trim()) return;

    const trimmedUrl = url.trim();
    // Basic URL validation
    if (!/^https?:\/\/.+\..+/.test(trimmedUrl) && !/^[a-zA-Z0-9].*\..+/.test(trimmedUrl)) {
      setError("Please enter a valid website URL");
      return;
    }

    const fullUrl = trimmedUrl.startsWith("http") ? trimmedUrl : `https://${trimmedUrl}`;

    setStep("loading");
    setError(null);

    try {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData?.session?.access_token;

      const response = await supabase.functions.invoke("import-business-website", {
        body: { url: fullUrl, tenant_id: tenant.id },
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });

      if (response.error) {
        throw new Error(response.error.message || "Failed to import website");
      }

      const data = response.data as ExtractedData;
      setExtractedData(data);

      // Pre-select all items
      if (data.services) {
        setSelectedServices(new Set(data.services.map((_, i) => i)));
      }
      if (data.faqs) {
        setSelectedFaqs(new Set(data.faqs.map((_, i) => i)));
      }

      setStep("preview");
    } catch (err: any) {
      setError(err.message || "Failed to extract data from website");
      setStep("input");
    }
  };

  const handleApply = async () => {
    if (!tenant?.id || !extractedData) return;

    setStep("applying");
    const servicesToCreate = extractedData.services.filter((_, i) => selectedServices.has(i));
    const faqsToCreate = extractedData.faqs.filter((_, i) => selectedFaqs.has(i));
    const total = servicesToCreate.length + faqsToCreate.length;
    setApplyProgress({ current: 0, total });

    let created = 0;
    let errors = 0;

    // Create services
    for (const svc of servicesToCreate) {
      try {
        await createService(tenant.id, {
          name: svc.name,
          description: svc.description || undefined,
          price_amount: svc.price_amount ?? undefined,
          price_type: svc.price_amount ? "fixed" : "quote_only",
          duration_minutes: svc.duration_minutes ?? 60,
        });
        created++;
      } catch {
        errors++;
      }
      setApplyProgress({ current: created + errors, total });
    }

    // Create FAQs
    for (const faq of faqsToCreate) {
      try {
        await createFAQ(tenant.id, {
          question: faq.question,
          answer: faq.answer,
        });
        created++;
      } catch {
        errors++;
      }
      setApplyProgress({ current: created + errors, total });
    }

    // Update tenant fields if extracted
    if (extractedData.business_name || extractedData.address || extractedData.hours) {
      try {
        const updates: Record<string, unknown> = {};
        if (extractedData.hours) updates.hours_json = extractedData.hours;
        if (extractedData.address) updates.address = extractedData.address;

        if (Object.keys(updates).length > 0) {
          await supabase
            .from("tenants")
            .update(updates)
            .eq("id", tenant.id);
        }
      } catch {
        // Non-critical
      }
    }

    // Invalidate queries
    queryClient.invalidateQueries({ queryKey: ["services"] });
    queryClient.invalidateQueries({ queryKey: ["business-faqs"] });
    invalidateBrainQueries(queryClient, tenant.id);

    if (errors > 0) {
      toast.success(`Imported ${created} items (${errors} skipped)`);
    } else {
      toast.success(`Successfully imported ${created} items from website`);
    }

    setStep("done");
  };

  const toggleService = (index: number) => {
    setSelectedServices(prev => {
      const next = new Set(prev);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      return next;
    });
  };

  const toggleFaq = (index: number) => {
    setSelectedFaqs(prev => {
      const next = new Set(prev);
      if (next.has(index)) next.delete(index);
      else next.add(index);
      return next;
    });
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-lg max-h-[85vh] flex flex-col">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Globe className="h-5 w-5 text-primary" />
            Import from Website
          </DialogTitle>
          <DialogDescription>
            {step === "input" && "Enter your business website URL and we'll extract your services, FAQs, and more."}
            {step === "loading" && "Scanning your website..."}
            {step === "preview" && "Review what we found. Uncheck anything you don't want to import."}
            {step === "applying" && "Importing your data..."}
            {step === "done" && "Import complete!"}
          </DialogDescription>
        </DialogHeader>

        {/* Step: URL Input */}
        {step === "input" && (
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Website URL</Label>
              <Input
                value={url}
                onChange={(e) => setUrl(e.target.value)}
                placeholder="https://www.yourbusiness.com"
                onKeyDown={(e) => e.key === "Enter" && handleFetch()}
              />
            </div>
            {error && (
              <div className="flex items-center gap-2 text-sm text-destructive">
                <AlertCircle className="h-4 w-4" />
                {error}
              </div>
            )}
            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={handleClose}>Cancel</Button>
              <Button onClick={handleFetch} disabled={!url.trim()}>
                <Sparkles className="h-4 w-4 mr-2" />
                Scan Website
              </Button>
            </div>
          </div>
        )}

        {/* Step: Loading */}
        {step === "loading" && (
          <div className="flex flex-col items-center justify-center py-12 gap-4">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
            <p className="text-sm text-muted-foreground">Extracting business data from your website...</p>
            <p className="text-xs text-muted-foreground">This usually takes 10-20 seconds</p>
          </div>
        )}

        {/* Step: Preview */}
        {step === "preview" && extractedData && (
          <ScrollArea className="flex-1 min-h-0 max-h-[55vh]">
            <div className="space-y-4 pr-4">
              {/* Business Info */}
              {(extractedData.business_name || extractedData.address) && (
                <div className="rounded-lg border p-3 space-y-1">
                  <p className="text-sm font-medium">Business Info</p>
                  {extractedData.business_name && (
                    <p className="text-sm text-muted-foreground">Name: {extractedData.business_name}</p>
                  )}
                  {extractedData.address && (
                    <p className="text-sm text-muted-foreground">Address: {extractedData.address}</p>
                  )}
                  {extractedData.phone && (
                    <p className="text-sm text-muted-foreground">Phone: {extractedData.phone}</p>
                  )}
                </div>
              )}

              {/* Services */}
              {extractedData.services.length > 0 && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <p className="text-sm font-medium">Services ({selectedServices.size}/{extractedData.services.length})</p>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="text-xs h-6"
                      onClick={() => {
                        if (selectedServices.size === extractedData.services.length) {
                          setSelectedServices(new Set());
                        } else {
                          setSelectedServices(new Set(extractedData.services.map((_, i) => i)));
                        }
                      }}
                    >
                      {selectedServices.size === extractedData.services.length ? "Deselect All" : "Select All"}
                    </Button>
                  </div>
                  {extractedData.services.map((svc, i) => (
                    <label
                      key={i}
                      className="flex items-start gap-3 rounded-lg border p-3 cursor-pointer hover:bg-muted/50"
                    >
                      <Checkbox
                        checked={selectedServices.has(i)}
                        onCheckedChange={() => toggleService(i)}
                        className="mt-0.5"
                      />
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-sm font-medium">{svc.name}</span>
                          {svc.price_amount && (
                            <Badge variant="secondary" className="text-xs">${svc.price_amount}</Badge>
                          )}
                          {svc.duration_minutes && (
                            <Badge variant="outline" className="text-xs">{svc.duration_minutes}min</Badge>
                          )}
                        </div>
                        {svc.description && (
                          <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{svc.description}</p>
                        )}
                      </div>
                    </label>
                  ))}
                </div>
              )}

              {/* FAQs */}
              {extractedData.faqs.length > 0 && (
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <p className="text-sm font-medium">FAQs ({selectedFaqs.size}/{extractedData.faqs.length})</p>
                    <Button
                      variant="ghost"
                      size="sm"
                      className="text-xs h-6"
                      onClick={() => {
                        if (selectedFaqs.size === extractedData.faqs.length) {
                          setSelectedFaqs(new Set());
                        } else {
                          setSelectedFaqs(new Set(extractedData.faqs.map((_, i) => i)));
                        }
                      }}
                    >
                      {selectedFaqs.size === extractedData.faqs.length ? "Deselect All" : "Select All"}
                    </Button>
                  </div>
                  {extractedData.faqs.map((faq, i) => (
                    <label
                      key={i}
                      className="flex items-start gap-3 rounded-lg border p-3 cursor-pointer hover:bg-muted/50"
                    >
                      <Checkbox
                        checked={selectedFaqs.has(i)}
                        onCheckedChange={() => toggleFaq(i)}
                        className="mt-0.5"
                      />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium">{faq.question}</p>
                        <p className="text-xs text-muted-foreground mt-0.5 line-clamp-2">{faq.answer}</p>
                      </div>
                    </label>
                  ))}
                </div>
              )}

              {extractedData.services.length === 0 && extractedData.faqs.length === 0 && (
                <div className="text-center py-8">
                  <AlertCircle className="h-8 w-8 mx-auto text-muted-foreground mb-2" />
                  <p className="text-sm text-muted-foreground">No services or FAQs found on this website.</p>
                  <p className="text-xs text-muted-foreground mt-1">Try a different URL or add your data manually.</p>
                </div>
              )}
            </div>
          </ScrollArea>
        )}

        {/* Preview Actions */}
        {step === "preview" && extractedData && (
          <div className="flex justify-end gap-2 pt-2 border-t">
            <Button variant="outline" onClick={() => { setStep("input"); setError(null); }}>
              <X className="h-4 w-4 mr-1" />
              Back
            </Button>
            <Button
              onClick={handleApply}
              disabled={selectedServices.size + selectedFaqs.size === 0}
            >
              <Check className="h-4 w-4 mr-1" />
              Import {selectedServices.size + selectedFaqs.size} Items
            </Button>
          </div>
        )}

        {/* Step: Applying */}
        {step === "applying" && (
          <div className="flex flex-col items-center justify-center py-12 gap-4">
            <Loader2 className="h-8 w-8 animate-spin text-primary" />
            <p className="text-sm text-muted-foreground">
              Importing... {applyProgress.current}/{applyProgress.total}
            </p>
          </div>
        )}

        {/* Step: Done */}
        {step === "done" && (
          <div className="flex flex-col items-center justify-center py-12 gap-4">
            <div className="h-12 w-12 rounded-full bg-green-100 dark:bg-green-900/30 flex items-center justify-center">
              <Check className="h-6 w-6 text-green-600" />
            </div>
            <p className="text-sm font-medium">Import complete!</p>
            <p className="text-xs text-muted-foreground">Your Business Brain has been updated with the imported data.</p>
            <Button onClick={handleClose}>Done</Button>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { useDispatchWorkflowConfig } from "@/hooks/useWorkflowConfig";
import type { DispatchWorkflowConfig } from "@/hooks/useWorkflowConfig";
import { AlertCircle, CheckCircle2, Loader2, Info, X } from "lucide-react";
import { Alert, AlertDescription } from "@/components/ui/alert";

const VEHICLE_FIELD_OPTIONS = ["year", "make", "model", "color", "vin"];
const PAYMENT_METHOD_OPTIONS = ["cash", "card", "check", "venmo", "zelle", "invoice"];

export default function DispatchWorkflowConfig() {
  const { config, isLoading, update, isUpdating } = useDispatchWorkflowConfig();
  const [localConfig, setLocalConfig] = useState<Partial<DispatchWorkflowConfig>>({});
  const [hasChanges, setHasChanges] = useState(false);

  // Initialize local config when data loads
  useEffect(() => {
    if (config) {
      setLocalConfig(config);
      setHasChanges(false);
    }
  }, [config]);

  const handleUpdate = (field: keyof DispatchWorkflowConfig, value: any) => {
    setLocalConfig((prev) => ({ ...prev, [field]: value }));
    setHasChanges(true);
  };

  const handleSave = () => {
    update(localConfig);
    setHasChanges(false);
  };

  const handleReset = () => {
    if (config) {
      setLocalConfig(config);
      setHasChanges(false);
    }
  };

  const toggleArrayItem = (field: keyof DispatchWorkflowConfig, item: string) => {
    const currentArray = (localConfig[field] as string[]) || [];
    const newArray = currentArray.includes(item)
      ? currentArray.filter((i) => i !== item)
      : [...currentArray, item];
    handleUpdate(field, newArray);
  };

  const addLuxuryBrand = (brand: string) => {
    const currentBrands = localConfig.luxury_brands || [];
    if (brand && !currentBrands.includes(brand)) {
      handleUpdate("luxury_brands", [...currentBrands, brand]);
    }
  };

  const removeLuxuryBrand = (brand: string) => {
    const currentBrands = localConfig.luxury_brands || [];
    handleUpdate("luxury_brands", currentBrands.filter((b) => b !== brand));
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Save Bar */}
      {hasChanges && (
        <Alert>
          <AlertCircle className="h-4 w-4" />
          <AlertDescription className="flex items-center justify-between">
            <span>You have unsaved changes</span>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={handleReset}>
                Reset
              </Button>
              <Button size="sm" onClick={handleSave} disabled={isUpdating}>
                {isUpdating ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Saving...
                  </>
                ) : (
                  <>
                    <CheckCircle2 className="mr-2 h-4 w-4" />
                    Save Changes
                  </>
                )}
              </Button>
            </div>
          </AlertDescription>
        </Alert>
      )}

      {/* Vehicle Collection Settings */}
      <Card>
        <CardHeader>
          <CardTitle>Vehicle Information Collection</CardTitle>
          <CardDescription>
            Configure when and how to collect vehicle details from customers
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Vehicle Timing */}
          <div className="space-y-2">
            <Label>When to collect vehicle info</Label>
            <Select
              value={localConfig.vehicle_info_timing || "before_pricing"}
              onValueChange={(value) => handleUpdate("vehicle_info_timing", value)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="before_pricing">
                  Before Pricing (affects quote calculation)
                </SelectItem>
                <SelectItem value="after_pricing">
                  After Pricing (just for driver notes)
                </SelectItem>
                <SelectItem value="optional">
                  Optional (only if service requires it)
                </SelectItem>
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              {localConfig.vehicle_info_timing === "before_pricing" && (
                <>
                  <Info className="inline h-3 w-3 mr-1" />
                  Agent will ask for vehicle type BEFORE calling pricing tools. Use this if vehicle
                  type affects your pricing (e.g., luxury vehicles, flatbed requirements).
                </>
              )}
              {localConfig.vehicle_info_timing === "after_pricing" && (
                <>
                  <Info className="inline h-3 w-3 mr-1" />
                  Agent will ask for vehicle details AFTER quoting price. Use this if you charge
                  flat rates regardless of vehicle type.
                </>
              )}
              {localConfig.vehicle_info_timing === "optional" && (
                <>
                  <Info className="inline h-3 w-3 mr-1" />
                  Agent will only collect vehicle info if the service type requires it (e.g.,
                  towing but not lockouts).
                </>
              )}
            </p>
          </div>

          {/* Vehicle Affects Pricing */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>Vehicle type affects pricing</Label>
              <p className="text-sm text-muted-foreground">
                Enable if pricing varies by vehicle (luxury, oversized, etc.)
              </p>
            </div>
            <Switch
              checked={localConfig.vehicle_affects_pricing ?? true}
              onCheckedChange={(checked) => handleUpdate("vehicle_affects_pricing", checked)}
            />
          </div>

          {/* Required Fields */}
          <div className="space-y-2">
            <Label>Required vehicle fields</Label>
            <div className="flex flex-wrap gap-2">
              {VEHICLE_FIELD_OPTIONS.map((field) => (
                <Badge
                  key={field}
                  variant={
                    (localConfig.required_vehicle_fields || []).includes(field)
                      ? "default"
                      : "outline"
                  }
                  className="cursor-pointer"
                  onClick={() => toggleArrayItem("required_vehicle_fields", field)}
                >
                  {field}
                </Badge>
              ))}
            </div>
            <p className="text-xs text-muted-foreground">
              Click to toggle which vehicle details the agent must collect
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Luxury Vehicle Protocols */}
      <Card>
        <CardHeader>
          <CardTitle>Luxury Vehicle Protocols</CardTitle>
          <CardDescription>
            Special handling for high-end vehicles that may require flatbed towing
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Enable Luxury Flatbed */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>Recommend flatbed for luxury vehicles</Label>
              <p className="text-sm text-muted-foreground">
                Agent will suggest flatbed towing for luxury brands
              </p>
            </div>
            <Switch
              checked={localConfig.luxury_flatbed_recommendation ?? false}
              onCheckedChange={(checked) =>
                handleUpdate("luxury_flatbed_recommendation", checked)
              }
            />
          </div>

          {/* Luxury Brands */}
          {localConfig.luxury_flatbed_recommendation && (
            <div className="space-y-2">
              <Label>Luxury brands that trigger flatbed recommendation</Label>
              <div className="flex flex-wrap gap-2 mb-2">
                {(localConfig.luxury_brands || []).map((brand) => (
                  <Badge key={brand} variant="secondary" className="gap-1">
                    {brand}
                    <X
                      className="h-3 w-3 cursor-pointer"
                      onClick={() => removeLuxuryBrand(brand)}
                    />
                  </Badge>
                ))}
              </div>
              <div className="flex gap-2">
                <Input
                  placeholder="Add brand (e.g., BMW, Mercedes)"
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      addLuxuryBrand(e.currentTarget.value);
                      e.currentTarget.value = "";
                    }
                  }}
                />
                <Button
                  variant="outline"
                  size="sm"
                  onClick={(e) => {
                    const input = e.currentTarget.previousSibling as HTMLInputElement;
                    if (input?.value) {
                      addLuxuryBrand(input.value);
                      input.value = "";
                    }
                  }}
                >
                  Add
                </Button>
              </div>
              <p className="text-xs text-muted-foreground">
                Press Enter or click Add to include a brand
              </p>
            </div>
          )}

          {/* AWD Detection */}
          {localConfig.luxury_flatbed_recommendation && (
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label>Ask about all-wheel drive (AWD/4WD)</Label>
                <p className="text-sm text-muted-foreground">
                  Agent will ask if luxury vehicles have AWD before recommending flatbed
                </p>
              </div>
              <Switch
                checked={localConfig.awd_detection_enabled ?? false}
                onCheckedChange={(checked) => handleUpdate("awd_detection_enabled", checked)}
              />
            </div>
          )}

          {/* Motorcycle Handling */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>Special motorcycle handling</Label>
              <p className="text-sm text-muted-foreground">
                Enable special protocols for motorcycle towing
              </p>
            </div>
            <Switch
              checked={localConfig.motorcycle_special_handling ?? false}
              onCheckedChange={(checked) => handleUpdate("motorcycle_special_handling", checked)}
            />
          </div>
        </CardContent>
      </Card>

      {/* Payment Collection */}
      <Card>
        <CardHeader>
          <CardTitle>Payment Collection</CardTitle>
          <CardDescription>Configure when and how to discuss payment with customers</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Ask Payment Method */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>Ask about payment method</Label>
              <p className="text-sm text-muted-foreground">
                Enable to have agent discuss payment during booking
              </p>
            </div>
            <Switch
              checked={localConfig.ask_payment_method ?? true}
              onCheckedChange={(checked) => handleUpdate("ask_payment_method", checked)}
            />
          </div>

          {localConfig.ask_payment_method && (
            <>
              {/* Payment Timing */}
              <div className="space-y-2">
                <Label>When to collect payment</Label>
                <Select
                  value={localConfig.payment_timing || "on_arrival"}
                  onValueChange={(value) => handleUpdate("payment_timing", value)}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="upfront">Upfront (before dispatch)</SelectItem>
                    <SelectItem value="on_arrival">On Arrival (driver collects)</SelectItem>
                    <SelectItem value="invoiced">Invoiced (bill later)</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              {/* Accepted Methods */}
              <div className="space-y-2">
                <Label>Accepted payment methods</Label>
                <div className="flex flex-wrap gap-2">
                  {PAYMENT_METHOD_OPTIONS.map((method) => (
                    <Badge
                      key={method}
                      variant={
                        (localConfig.accepted_methods || []).includes(method)
                          ? "default"
                          : "outline"
                      }
                      className="cursor-pointer capitalize"
                      onClick={() => toggleArrayItem("accepted_methods", method)}
                    >
                      {method}
                    </Badge>
                  ))}
                </div>
              </div>

              {/* Payment Message */}
              <div className="space-y-2">
                <Label>Payment due message</Label>
                <Textarea
                  value={localConfig.payment_due_message || ""}
                  onChange={(e) => handleUpdate("payment_due_message", e.target.value)}
                  placeholder="Driver will collect {{price}} when they arrive"
                  rows={2}
                />
                <p className="text-xs text-muted-foreground">
                  Use {"{"}
                  {"{"}price{"}"}{"}"}to insert the quoted amount
                </p>
              </div>
            </>
          )}
        </CardContent>
      </Card>

      {/* Address Confirmation */}
      <Card>
        <CardHeader>
          <CardTitle>Address Confirmation</CardTitle>
          <CardDescription>
            Configure how the agent confirms locations with customers
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Confirm Geocoded */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>Confirm geocoded address</Label>
              <p className="text-sm text-muted-foreground">
                Agent will read back the standardized address for confirmation
              </p>
            </div>
            <Switch
              checked={localConfig.confirm_geocoded_address ?? true}
              onCheckedChange={(checked) => handleUpdate("confirm_geocoded_address", checked)}
            />
          </div>

          {/* Require ZIP */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>Require ZIP code</Label>
              <p className="text-sm text-muted-foreground">
                Agent must collect ZIP code for all addresses
              </p>
            </div>
            <Switch
              checked={localConfig.require_zip_code ?? false}
              onCheckedChange={(checked) => handleUpdate("require_zip_code", checked)}
            />
          </div>

          {/* Confirmation Script */}
          <div className="space-y-2">
            <Label>Address confirmation script</Label>
            <Textarea
              value={localConfig.address_confirmation_script || ""}
              onChange={(e) => handleUpdate("address_confirmation_script", e.target.value)}
              placeholder="Got it, {{geocoded_address}} - is that correct?"
              rows={2}
            />
            <p className="text-xs text-muted-foreground">
              Use {"{"}
              {"{"}geocoded_address{"}"}{"}"}to insert the formatted address
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Driver Expectations */}
      <Card>
        <CardHeader>
          <CardTitle>Driver Communication</CardTitle>
          <CardDescription>
            Set customer expectations for driver contact and arrival
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Driver Callback Script */}
          <div className="space-y-2">
            <Label>Driver callback script</Label>
            <Textarea
              value={localConfig.driver_callback_script || ""}
              onChange={(e) => handleUpdate("driver_callback_script", e.target.value)}
              placeholder="Our driver will call you when they're about 10 minutes away"
              rows={2}
            />
            <p className="text-xs text-muted-foreground">
              Tell customers when to expect a call from the driver
            </p>
          </div>

          {/* Include Direct Contact */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>Provide driver direct contact info</Label>
              <p className="text-sm text-muted-foreground">
                Give customers a direct number to reach the driver
              </p>
            </div>
            <Switch
              checked={localConfig.include_direct_contact_info ?? false}
              onCheckedChange={(checked) => handleUpdate("include_direct_contact_info", checked)}
            />
          </div>

          {/* Escalation Number */}
          {localConfig.include_direct_contact_info && (
            <div className="space-y-2">
              <Label>Escalation/Direct contact number</Label>
              <Input
                type="tel"
                value={localConfig.escalation_number || ""}
                onChange={(e) => handleUpdate("escalation_number", e.target.value)}
                placeholder="(555) 123-4567"
              />
              <p className="text-xs text-muted-foreground">
                Number agent will provide for direct driver contact
              </p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { useFoodWorkflowConfig } from "@/hooks/useWorkflowConfig";
import type { FoodWorkflowConfig } from "@/hooks/useWorkflowConfig";
import { AlertCircle, CheckCircle2, Loader2, Info } from "lucide-react";
import { Alert, AlertDescription } from "@/components/ui/alert";

export default function FoodWorkflowConfig() {
  const { config, isLoading, update, isUpdating } = useFoodWorkflowConfig();
  const [localConfig, setLocalConfig] = useState<Partial<FoodWorkflowConfig>>({});
  const [hasChanges, setHasChanges] = useState(false);

  useEffect(() => {
    if (config) {
      setLocalConfig(config);
      setHasChanges(false);
    }
  }, [config]);

  const handleUpdate = (field: keyof FoodWorkflowConfig, value: any) => {
    setLocalConfig((prev) => ({ ...prev, [field]: value }));
    setHasChanges(true);
  };

  const handleSave = () => {
    update(localConfig);
    setHasChanges(false);
  };

  const handleReset = () => {
    if (config) {
      setLocalConfig(config);
      setHasChanges(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Save Bar */}
      {hasChanges && (
        <Alert>
          <AlertCircle className="h-4 w-4" />
          <AlertDescription className="flex items-center justify-between">
            <span>You have unsaved changes</span>
            <div className="flex gap-2">
              <Button variant="outline" size="sm" onClick={handleReset}>
                Reset
              </Button>
              <Button size="sm" onClick={handleSave} disabled={isUpdating}>
                {isUpdating ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    Saving...
                  </>
                ) : (
                  <>
                    <CheckCircle2 className="mr-2 h-4 w-4" />
                    Save Changes
                  </>
                )}
              </Button>
            </div>
          </AlertDescription>
        </Alert>
      )}

      {/* Order Type Settings */}
      <Card>
        <CardHeader>
          <CardTitle>Order Type Handling</CardTitle>
          <CardDescription>
            Configure how the agent determines if orders are pickup or delivery
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Ask Pickup vs Delivery */}
          <div className="space-y-2">
            <Label>When to ask about order type</Label>
            <Select
              value={localConfig.ask_pickup_vs_delivery || "if_both_enabled"}
              onValueChange={(value) => handleUpdate("ask_pickup_vs_delivery", value)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="always">Always Ask</SelectItem>
                <SelectItem value="if_both_enabled">
                  Only if Both Pickup & Delivery Enabled
                </SelectItem>
                <SelectItem value="never">Never Ask (Use Default)</SelectItem>
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              {localConfig.ask_pickup_vs_delivery === "always" && (
                <>
                  <Info className="inline h-3 w-3 mr-1" />
                  Agent will always ask "Pickup or delivery?" even if only one is available
                </>
              )}
              {localConfig.ask_pickup_vs_delivery === "if_both_enabled" && (
                <>
                  <Info className="inline h-3 w-3 mr-1" />
                  Agent only asks if both options are enabled in Order Settings
                </>
              )}
              {localConfig.ask_pickup_vs_delivery === "never" && (
                <>
                  <Info className="inline h-3 w-3 mr-1" />
                  Agent assumes default type without asking
                </>
              )}
            </p>
          </div>

          {/* Default Order Type */}
          <div className="space-y-2">
            <Label>Default order type (when not asking)</Label>
            <Select
              value={localConfig.default_order_type || "ask"}
              onValueChange={(value) => handleUpdate("default_order_type", value)}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="pickup">Pickup</SelectItem>
                <SelectItem value="delivery">Delivery</SelectItem>
                <SelectItem value="ask">Always Ask Customer</SelectItem>
              </SelectContent>
            </Select>
            <p className="text-xs text-muted-foreground">
              What to assume if customer doesn't specify
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Order Timing */}
      <Card>
        <CardHeader>
          <CardTitle>Order Timing</CardTitle>
          <CardDescription>Configure when orders can be placed and prepared</CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* ASAP vs Scheduled */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <Label>Ask if order is ASAP or scheduled</Label>
              <p className="text-sm text-muted-foreground">
                Agent will ask "For now or for a specific time?"
              </p>
            </div>
            <Switch
              checked={localConfig.ask_asap_vs_scheduled ?? true}
              onCheckedChange={(checked) => handleUpdate("ask_asap_vs_scheduled", checked)}
            />
          </div>

          {/* Min Advance Minutes */}
          <div className="space-y-2">
