import { useState } from "react";
import { startOfWeek, addDays, isSameDay } from "date-fns";
import { CalendarHeader } from "./CalendarHeader";
import { TimeGrid } from "./TimeGrid";
import { DayColumn } from "./DayColumn";
import { StaffDayView } from "./StaffDayView";
import { useScheduleData, type ScheduleEvent } from "@/hooks/useScheduleData";
import { Loader2, Calendar, Users } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";

interface ScheduleCalendarProps {
  onEventClick?: (event: ScheduleEvent) => void;
  onSlotClick?: (date: Date, hour: number) => void;
}

export function ScheduleCalendar({ onEventClick, onSlotClick }: ScheduleCalendarProps) {
  const [currentDate, setCurrentDate] = useState(new Date());
  const [view, setView] = useState<"week" | "day">("week");
  const [teamView, setTeamView] = useState(false);

  const weekStart = startOfWeek(currentDate, { weekStartsOn: 0 });
  const { events, isLoading } = useScheduleData(weekStart);

  const startHour = 7;
  const endHour = 20;

  const getDaysToShow = () => {
    if (view === "day") return [currentDate];
    return Array.from({ length: 7 }, (_, i) => addDays(weekStart, i));
  };

  const days = getDaysToShow();
  const hasEventsThisWeek = events.length > 0;
  const hasStaffAssignments = events.some((e) => e.staffMemberId);

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="flex flex-col h-full">
      <div className="flex items-center justify-between gap-2 pb-4">
        <div className="flex-1">
          <CalendarHeader
            currentDate={currentDate}
            view={view}
            onDateChange={setCurrentDate}
            onViewChange={(v) => {
              setView(v);
              if (v === "week") setTeamView(false);
            }}
          />
        </div>
        {/* Team view toggle — only in day view */}
        {view === "day" && (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant={teamView ? "secondary" : "outline"}
                size="sm"
                className="gap-1.5 shrink-0"
                onClick={() => setTeamView(!teamView)}
              >
                <Users className="h-3.5 w-3.5" />
                Team
              </Button>
            </TooltipTrigger>
            <TooltipContent>
              {teamView ? "Switch to timeline view" : "View by team member"}
            </TooltipContent>
          </Tooltip>
        )}
      </div>

      {/* Legend */}
      <div className="flex flex-wrap items-center gap-4 pb-4 text-xs text-muted-foreground">
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-3 rounded bg-primary/20 border border-primary/50" />
          <span>Confirmed</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-3 rounded bg-warning/20 border border-warning/50" />
          <span>Pending</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-3 rounded bg-muted border border-muted-foreground/30" />
          <span>Busy (External)</span>
        </div>
        <div className="flex items-center gap-1.5">
          <div className="w-3 h-3 rounded bg-accent/20 border border-accent/50 border-dashed" />
          <span>Hold</span>
        </div>
        {hasStaffAssignments && (
          <div className="flex items-center gap-1.5">
            <Users className="h-3 w-3" />
            <span>Staff assigned</span>
          </div>
        )}
        <div className="ml-auto text-muted-foreground/70">
          <kbd className="px-1.5 py-0.5 text-[10px] font-mono bg-muted rounded">←</kbd>
          {" "}
          <kbd className="px-1.5 py-0.5 text-[10px] font-mono bg-muted rounded">→</kbd>
          {" "}to navigate
        </div>
      </div>

      <div className="flex-1 overflow-auto border rounded-lg bg-background">
        {view === "day" && teamView ? (
          <StaffDayView
            date={currentDate}
            events={events}
            startHour={startHour}
            endHour={endHour}
            onEventClick={onEventClick}
            onSlotClick={onSlotClick}
          />
        ) : (
          <div className="flex min-w-[600px]">
            <div className="w-16 flex-shrink-0">
              <TimeGrid startHour={startHour} endHour={endHour} />
            </div>
            {days.map((day) => (
              <DayColumn
                key={day.toISOString()}
                date={day}
                events={events}
                startHour={startHour}
                endHour={endHour}
                onEventClick={onEventClick}
                onSlotClick={onSlotClick}
              />
            ))}
          </div>
        )}
      </div>

      {!hasEventsThisWeek && (
        <div className="flex items-center justify-center py-6 text-sm text-muted-foreground border-t mt-4">
          <Calendar className="h-4 w-4 mr-2 opacity-50" />
          <span>No schedule items this week. Click any time slot to create a booking!</span>
        </div>
      )}
    </div>
  );
}

import { format, getHours, getMinutes } from "date-fns";
import { cn } from "@/lib/utils";
import { CalendarEvent } from "./CalendarEvent";
import type { ScheduleEvent } from "@/hooks/useScheduleData";
import { User } from "lucide-react";

interface StaffDayViewProps {
  date: Date;
  events: ScheduleEvent[];
  startHour?: number;
  endHour?: number;
  onEventClick?: (event: ScheduleEvent) => void;
  onSlotClick?: (date: Date, hour: number) => void;
}

const HOUR_HEIGHT = 64;

const STAFF_COLORS = [
  "border-l-blue-500",
  "border-l-emerald-500",
  "border-l-amber-500",
  "border-l-purple-500",
  "border-l-rose-500",
  "border-l-cyan-500",
  "border-l-orange-500",
  "border-l-pink-500",
  "border-l-teal-500",
];

const STAFF_BG = [
  "bg-blue-500/8",
  "bg-emerald-500/8",
  "bg-amber-500/8",
  "bg-purple-500/8",
  "bg-rose-500/8",
  "bg-cyan-500/8",
  "bg-orange-500/8",
  "bg-pink-500/8",
  "bg-teal-500/8",
];

export function StaffDayView({
  date,
  events,
  startHour = 7,
  endHour = 20,
  onEventClick,
  onSlotClick,
}: StaffDayViewProps) {
  const totalHours = endHour - startHour;
  const columnHeight = totalHours * HOUR_HEIGHT;

  // Group events by staff member
  const staffGroups = new Map<string, { name: string; events: ScheduleEvent[] }>();
  const unassigned: ScheduleEvent[] = [];

  for (const event of events) {
    const eventDate = event.start;
    if (
      eventDate.getFullYear() !== date.getFullYear() ||
      eventDate.getMonth() !== date.getMonth() ||
      eventDate.getDate() !== date.getDate()
    ) continue;

    if (event.staffMemberId && event.staffName) {
      const key = event.staffMemberId;
      if (!staffGroups.has(key)) {
        staffGroups.set(key, { name: event.staffName, events: [] });
      }
      staffGroups.get(key)!.events.push(event);
    } else {
      unassigned.push(event);
    }
  }

  const staffEntries = Array.from(staffGroups.entries());
  const columns = [
    ...staffEntries.map(([id, group], i) => ({
      id,
      label: group.name,
      events: group.events,
      colorIdx: i % STAFF_COLORS.length,
    })),
    ...(unassigned.length > 0 || staffEntries.length === 0
      ? [{ id: "unassigned", label: "Unassigned", events: unassigned, colorIdx: -1 }]
      : []),
  ];

  const getEventPosition = (event: ScheduleEvent) => {
    const eventStartHour = getHours(event.start) + getMinutes(event.start) / 60;
    const eventEndHour = getHours(event.end) + getMinutes(event.end) / 60;
    const visibleStart = Math.max(eventStartHour, startHour);
    const visibleEnd = Math.min(eventEndHour, endHour);
    const top = (visibleStart - startHour) * HOUR_HEIGHT;
    const height = Math.max((visibleEnd - visibleStart) * HOUR_HEIGHT, 20);
    return { top, height };
  };

  const handleSlotClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!onSlotClick) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const y = e.clientY - rect.top;
    const hour = Math.floor(y / HOUR_HEIGHT) + startHour;
    onSlotClick(date, hour);
  };

  if (columns.length === 0) {
    return (
      <div className="flex-1 flex items-center justify-center py-12 text-sm text-muted-foreground">
        No team members or events for this day.
      </div>
    );
  }

  return (
    <div className="flex min-w-[600px]">
      {/* Time column */}
      <div className="w-16 flex-shrink-0">
        <div className="h-12 border-b border-border" />
        {Array.from({ length: totalHours + 1 }).map((_, i) => {
          const h = startHour + i;
          return (
            <div key={h} className="h-16 border-b border-border pr-2 text-right">
              <span className="text-xs text-muted-foreground -mt-2 block">
                {h === 0 ? "12 AM" : h < 12 ? `${h} AM` : h === 12 ? "12 PM" : `${h - 12} PM`}
              </span>
            </div>
          );
        })}
      </div>

      {/* Staff columns */}
      {columns.map((col) => (
        <div key={col.id} className="flex-1 min-w-[140px]">
          {/* Column header */}
          <div className={cn(
            "h-12 border-b border-l border-border flex items-center justify-center gap-1.5 px-2",
            col.colorIdx >= 0 ? STAFF_BG[col.colorIdx] : "bg-muted/30"
          )}>
            <User className="h-3.5 w-3.5 text-muted-foreground" />
            <span className="text-xs font-semibold truncate">{col.label}</span>
            <span className="text-[10px] text-muted-foreground">({col.events.length})</span>
          </div>

          {/* Events container */}
          <div
            className="relative border-l border-border cursor-pointer"
            style={{ height: columnHeight }}
            onClick={handleSlotClick}
          >
            {/* Hour lines */}
            {Array.from({ length: totalHours }).map((_, i) => (
              <div
                key={i}
                className="absolute left-0 right-0 border-b border-border/50"
                style={{ top: `${i * HOUR_HEIGHT}px`, height: HOUR_HEIGHT }}
              />
            ))}

            {/* Events */}
            {col.events.map((event) => {
              const { top, height } = getEventPosition(event);
              return (
                <CalendarEvent
                  key={event.id}
                  event={event}
                  style={{ top, height }}
                  onClick={onEventClick}
                />
              );
            })}
          </div>
        </div>
      ))}
    </div>
  );
}

 import { Badge } from "@/components/ui/badge";
 import { Phone, Loader2 } from "lucide-react";
 import { formatDistanceToNow } from "date-fns";
 import { cn } from "@/lib/utils";
 import { computeCallPriority, type PriorityInput } from "@/lib/priorityScoring";
 import { PriorityBadge } from "./PriorityBadge";
 import type { PriorityConfig } from "@/config/industryBrainConfig";
 import type { InboxConfig } from "@/config/industryBrainConfig";

 interface CallSession {
   id: string;
   started_at: string;
   ended_at: string | null;
   caller_phone: string | null;
   call_direction: "inbound" | "outbound";
   outcome: string | null;
   summary: string | null;
   context_json: Record<string, unknown> | null;
   extracted_payload: Record<string, unknown> | null;
   customer_id: string | null;
   customer?: {
     id: string;
     full_name: string;
     phone_e164: string;
   } | null;
 }

 interface InboxCallCardProps {
   call: CallSession;
   onClick: () => void;
   customerName: string;
   priorityConfig: PriorityConfig;
   inboxConfig: InboxConfig;
 }

 function formatPhone(phone: string | null): string {
   if (!phone) return "Unknown";
   if (phone.includes("(") || (phone.startsWith("+") && phone.length > 12)) return phone;
   const cleaned = phone.replace(/\D/g, "");
   if (cleaned.length === 10) {
     return `(${cleaned.slice(0, 3)}) ${cleaned.slice(3, 6)}-${cleaned.slice(6)}`;
   }
   if (cleaned.length === 11 && cleaned.startsWith("1")) {
     return `(${cleaned.slice(1, 4)}) ${cleaned.slice(4, 7)}-${cleaned.slice(7)}`;
   }
   return phone;
 }

 function formatDuration(startedAt: string, endedAt: string | null): string {
   if (!endedAt) return "";
   const start = new Date(startedAt).getTime();
   const end = new Date(endedAt).getTime();
   const seconds = Math.floor((end - start) / 1000);
   const mins = Math.floor(seconds / 60);
   const secs = seconds % 60;
   if (mins === 0) return `${secs}s`;
   return `${mins}m ${secs}s`;
 }

 function getOutcomeStyles(outcome: string | null): { bg: string; iconBg: string; border: string; label: string } {
   switch (outcome) {
     case "booked":
       return { bg: "bg-success/10", iconBg: "bg-success/10 text-success", border: "border-success text-success", label: "Booked" };
     case "order":
       return { bg: "bg-success/10", iconBg: "bg-success/10 text-success", border: "border-success text-success", label: "Order" };
     case "dispatch":
       return { bg: "bg-success/10", iconBg: "bg-success/10 text-success", border: "border-success text-success", label: "Dispatch" };
     case "followup":
       return { bg: "bg-warning/10", iconBg: "bg-warning/10 text-warning", border: "border-warning text-warning", label: "Follow-up" };
     case "lead_captured":
       return { bg: "bg-warning/10", iconBg: "bg-warning/10 text-warning", border: "border-warning text-warning", label: "Lead" };
     case "message":
       return { bg: "bg-warning/10", iconBg: "bg-warning/10 text-warning", border: "border-warning text-warning", label: "Message" };
     case "lost":
       return { bg: "bg-destructive/10", iconBg: "bg-destructive/10 text-destructive", border: "border-destructive text-destructive", label: "Lost" };
     case "escalated":
       return { bg: "bg-info/10", iconBg: "bg-info/10 text-info", border: "border-info text-info", label: "Escalated" };
     default:
       return { bg: "bg-muted", iconBg: "bg-muted text-muted-foreground", border: "border-muted-foreground text-muted-foreground", label: outcome || "Pending" };
   }
 }

 /**
  * Build industry-aware preview text from extracted_payload.
  */
 function buildPreviewText(payload: Record<string, unknown> | null, previewFields: string[]): string | null {
   if (!payload) return null;

   const parts: string[] = [];
   for (const path of previewFields) {
     const pathParts = path.split(".");
     let current: unknown = payload;
     for (const p of pathParts) {
       if (current === null || current === undefined || typeof current !== "object") { current = undefined; break; }
       current = (current as Record<string, unknown>)[p];
     }
     if (current && typeof current === "string") {
       parts.push(current);
     } else if (Array.isArray(current) && current.length > 0) {
       // Summarize array items
       const items = current.slice(0, 3).map((item) => {
         if (typeof item === "object" && item !== null) {
           return (item as Record<string, unknown>).name || (item as Record<string, unknown>).item || JSON.stringify(item);
         }
         return String(item);
       });
       parts.push(items.join(", ") + (current.length > 3 ? ` +${current.length - 3} more` : ""));
     }
   }

   return parts.length > 0 ? parts.join(" - ") : null;
 }

 const PRIORITY_BORDER_COLORS: Record<string, string> = {
