             <p className="text-sm text-muted-foreground">
               {duration}
             </p>
           )}
         </div>
       </div>
     </div>
   );
 }

/**
 * LeadKanbanCard — Compact card for leads in the Kanban pipeline.
 * Shows customer name, phone, service requested, priority, and time.
 */

import { Phone, Clock, ChevronRight } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { PriorityBadge } from "./PriorityBadge";
import { computeCallPriority } from "@/lib/priorityScoring";
import type { PriorityConfig } from "@/config/industryBrainConfig";

interface CallSession {
  id: string;
  started_at: string;
  ended_at: string | null;
  caller_phone: string | null;
  call_direction: "inbound" | "outbound";
  outcome: string | null;
  summary: string | null;
  context_json: Record<string, unknown> | null;
  extracted_payload: Record<string, unknown> | null;
  customer_id: string | null;
  followup_status?: string | null;
  customer?: {
    id: string;
    full_name: string;
    phone_e164: string;
  } | null;
}

interface LeadKanbanCardProps {
  call: CallSession;
  customerName: string;
  onClick: () => void;
  priorityConfig: PriorityConfig;
}

function formatPhone(phone: string | null): string {
  if (!phone) return "Unknown";
  const cleaned = phone.replace(/\D/g, "");
  if (cleaned.length === 10) {
    return `(${cleaned.slice(0, 3)}) ${cleaned.slice(3, 6)}-${cleaned.slice(6)}`;
  }
  if (cleaned.length === 11 && cleaned.startsWith("1")) {
    return `(${cleaned.slice(1, 4)}) ${cleaned.slice(4, 7)}-${cleaned.slice(7)}`;
  }
  return phone;
}

function extractServiceRequested(payload: Record<string, unknown> | null): string | null {
  if (!payload) return null;
  const booking = payload.booking as Record<string, unknown> | undefined;
  if (booking?.service_requested && typeof booking.service_requested === "string") {
    return booking.service_requested;
  }
  const serviceRequested = payload.service_requested;
  if (typeof serviceRequested === "string") return serviceRequested;
  return null;
}

function extractVehicleInfo(payload: Record<string, unknown> | null): string | null {
  if (!payload) return null;
  const dispatch = payload.dispatch as Record<string, unknown> | undefined;
  if (dispatch?.vehicle_type && typeof dispatch.vehicle_type === "string") {
    return dispatch.vehicle_type;
  }
  const vehicle = payload.vehicle;
  if (typeof vehicle === "string") return vehicle;
  return null;
}

const PRIORITY_ACCENT: Record<string, string> = {
  high: "border-l-destructive",
  medium: "border-l-warning",
  low: "border-l-border",
};

export function LeadKanbanCard({ call, customerName, onClick, priorityConfig }: LeadKanbanCardProps) {
  const callbackRequested = !!(
    call.extracted_payload &&
    typeof call.extracted_payload === "object" &&
    (call.extracted_payload as Record<string, unknown>).callback &&
    typeof (call.extracted_payload as Record<string, unknown>).callback === "object" &&
    ((call.extracted_payload as Record<string, unknown>).callback as Record<string, unknown>)?.requested
  );

  const priority = computeCallPriority(
    { outcome: call.outcome, started_at: call.started_at, callbackRequested },
    priorityConfig,
  );

  const serviceRequested = extractServiceRequested(call.extracted_payload);
  const vehicleInfo = extractVehicleInfo(call.extracted_payload);

  return (
    <button
      type="button"
      onClick={onClick}
      className={cn(
        "w-full text-left rounded-lg border border-border/40 bg-card p-3 hover:bg-muted/40 transition-all cursor-pointer group border-l-2",
        PRIORITY_ACCENT[priority.level] || "border-l-border",
      )}
    >
      <div className="flex items-start justify-between gap-2">
        <div className="min-w-0 flex-1">
          <p className="font-medium text-sm truncate">{customerName}</p>
          <p className="text-xs text-muted-foreground font-mono mt-0.5">
            {formatPhone(call.caller_phone)}
          </p>
        </div>
        <ChevronRight className="h-4 w-4 text-muted-foreground/40 group-hover:text-muted-foreground shrink-0 mt-0.5 transition-colors" />
      </div>

      {/* Service / Vehicle info */}
      {(serviceRequested || vehicleInfo) && (
        <div className="mt-2 flex flex-wrap gap-1">
          {serviceRequested && (
            <Badge variant="secondary" className="text-[10px] px-1.5 py-0 font-normal">
              {serviceRequested}
            </Badge>
          )}
          {vehicleInfo && (
            <Badge variant="outline" className="text-[10px] px-1.5 py-0 font-normal">
              {vehicleInfo}
            </Badge>
          )}
        </div>
      )}

      {/* Summary */}
      {call.summary && (
        <p className="text-xs text-muted-foreground mt-2 line-clamp-2">{call.summary}</p>
      )}

      {/* Footer: priority + time */}
      <div className="flex items-center justify-between mt-2 gap-2">
        <PriorityBadge level={priority.level} label={priority.label} className="text-[10px]" />
        <span className="text-[10px] text-muted-foreground flex items-center gap-1">
          <Clock className="h-3 w-3" />
          {formatDistanceToNow(new Date(call.started_at), { addSuffix: true })}
        </span>
      </div>
    </button>
  );
}

/**
 * LeadsKanbanView — Pipeline board for lead management.
 *
 * Columns: New → Contacted → Quoted → Won → Lost
 * Each column shows leads filtered by followup_status (or outcome for Won/Lost).
 * Leads can be moved between stages via dropdown on the detail panel.
 */

import { useMemo } from "react";
import { cn } from "@/lib/utils";
import { ScrollArea } from "@/components/ui/scroll-area";
import { LeadKanbanCard } from "./LeadKanbanCard";
import type { PriorityConfig } from "@/config/industryBrainConfig";
import { computeCallPriority } from "@/lib/priorityScoring";
import { computeLeadTemperatureFromSession, TEMPERATURE_COLORS, type LeadTemperature } from "@/lib/leadTemperature";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { supabase } from "@/integrations/supabase/client";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

interface CallSession {
  id: string;
  started_at: string;
  ended_at: string | null;
  caller_phone: string | null;
  call_direction: "inbound" | "outbound";
  outcome: string | null;
  summary: string | null;
  context_json: Record<string, unknown> | null;
  extracted_payload: Record<string, unknown> | null;
  customer_id: string | null;
  followup_status?: string | null;
  customer?: {
    id: string;
    full_name: string;
    phone_e164: string;
  } | null;
}

export type PipelineStage = "new" | "contacted" | "quoted" | "won" | "lost";

interface StageConfig {
  id: PipelineStage;
  label: string;
  color: string;
  dotColor: string;
  bgColor: string;
}

const STAGES: StageConfig[] = [
  { id: "new", label: "New", color: "text-blue-400", dotColor: "bg-blue-400", bgColor: "bg-blue-500/5" },
  { id: "contacted", label: "Contacted", color: "text-amber-400", dotColor: "bg-amber-400", bgColor: "bg-amber-500/5" },
  { id: "quoted", label: "Quoted", color: "text-purple-400", dotColor: "bg-purple-400", bgColor: "bg-purple-500/5" },
  { id: "won", label: "Won", color: "text-emerald-400", dotColor: "bg-emerald-400", bgColor: "bg-emerald-500/5" },
  { id: "lost", label: "Lost", color: "text-red-400", dotColor: "bg-red-400", bgColor: "bg-red-500/5" },
];

function getLeadStage(call: CallSession): PipelineStage {
  // Terminal outcomes override followup_status
  if (call.outcome === "booked") return "won";
  if (call.outcome === "lost") return "lost";

  // Use followup_status for pipeline stage
  const status = call.followup_status;
  if (status === "contacted") return "contacted";
  if (status === "quoted") return "quoted";
  if (status === "won") return "won";
  if (status === "lost") return "lost";

  // Default: new lead
  return "new";
}

interface LeadsKanbanViewProps {
  leads: CallSession[];
  getCustomerName: (call: CallSession) => string;
  onSelectCall: (call: CallSession) => void;
  priorityConfig: PriorityConfig;
  tenantId: string;
}

export function LeadsKanbanView({
  leads,
  getCustomerName,
  onSelectCall,
  priorityConfig,
  tenantId,
}: LeadsKanbanViewProps) {
  const queryClient = useQueryClient();

  const stageLeads = useMemo(() => {
    const grouped: Record<PipelineStage, CallSession[]> = {
      new: [],
      contacted: [],
      quoted: [],
      won: [],
      lost: [],
    };

    for (const lead of leads) {
      const stage = getLeadStage(lead);
      grouped[stage].push(lead);
    }

    // Sort each stage by temperature score desc, then recency desc
    for (const stage of Object.keys(grouped) as PipelineStage[]) {
      grouped[stage].sort((a, b) => {
        const tempA = computeLeadTemperatureFromSession(a);
        const tempB = computeLeadTemperatureFromSession(b);
        if (tempB.score !== tempA.score) return tempB.score - tempA.score;
        return new Date(b.started_at).getTime() - new Date(a.started_at).getTime();
      });
    }

    return grouped;
  }, [leads, priorityConfig]);

  const handleStageChange = async (callId: string, newStage: PipelineStage) => {
    // Map stage to followup_status and optionally outcome
    let followup_status: string | null = newStage;
    let outcome: string | undefined;

    if (newStage === "won") {
      outcome = "booked";
      followup_status = "won";
    } else if (newStage === "lost") {
      outcome = "lost";
      followup_status = "lost";
    } else if (newStage === "new") {
      followup_status = null;
    }

    const updateData: Record<string, unknown> = { followup_status };
    if (outcome) updateData.outcome = outcome;

    const { error } = await supabase
      .from("ai_call_sessions")
      .update(updateData)
      .eq("id", callId);

    if (error) {
      toast.error("Failed to update lead stage");
      return;
    }

    queryClient.invalidateQueries({ queryKey: ["inbox_calls", tenantId] });
    toast.success(`Lead moved to ${STAGES.find(s => s.id === newStage)?.label}`);
  };

  return (
    <div className="flex gap-3 overflow-x-auto pb-4 -mx-2 px-2">
      {STAGES.map((stage) => {
        const items = stageLeads[stage.id];
        return (
          <div
            key={stage.id}
            className={cn(
              "flex-shrink-0 w-[260px] rounded-xl border border-border/30 flex flex-col max-h-[calc(100vh-16rem)]",
              stage.bgColor,
            )}
          >
            {/* Column header */}
            <div className="px-3 py-2.5 border-b border-border/20 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className={cn("w-2 h-2 rounded-full", stage.dotColor)} />
                <span className={cn("text-sm font-semibold", stage.color)}>
                  {stage.label}
                </span>
              </div>
              <span className="text-xs text-muted-foreground font-mono bg-muted/50 px-1.5 py-0.5 rounded">
                {items.length}
              </span>
            </div>

            {/* Cards */}
            <ScrollArea className="flex-1 p-2">
              <div className="space-y-2">
                {items.length === 0 ? (
                  <p className="text-xs text-muted-foreground/50 text-center py-6">
                    No leads
                  </p>
                ) : (
                  items.map((call) => {
                    const temp = computeLeadTemperatureFromSession(call);
                    const tempColors = TEMPERATURE_COLORS[temp.temperature];
                    return (
                    <div key={call.id} className="space-y-1">
                      <div className="relative">
                        <LeadKanbanCard
                          call={call}
                          customerName={getCustomerName(call)}
                          onClick={() => onSelectCall(call)}
                          priorityConfig={priorityConfig}
                        />
                        <span className={cn(
                          "absolute top-1.5 right-1.5 flex items-center gap-1 px-1.5 py-0.5 rounded-full text-[10px] font-medium",
                          tempColors.bg, tempColors.text,
                        )}>
                          <span className={cn("w-1.5 h-1.5 rounded-full", tempColors.dot)} />
                          {temp.temperature}
                        </span>
                      </div>
                      {/* Stage change dropdown */}
                      <Select
                        value={getLeadStage(call)}
                        onValueChange={(val) => handleStageChange(call.id, val as PipelineStage)}
                      >
                        <SelectTrigger className="h-6 text-[10px] border-0 bg-transparent hover:bg-muted/40 px-2 w-full">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {STAGES.map((s) => (
                            <SelectItem key={s.id} value={s.id} className="text-xs">
                              <span className="flex items-center gap-2">
                                <span className={cn("w-1.5 h-1.5 rounded-full", s.dotColor)} />
                                Move to {s.label}
                              </span>
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                    );
                  })
                )}
              </div>
            </ScrollArea>
          </div>
        );
      })}
    </div>
  );
}

import { useState, useCallback } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Upload, AlertCircle, CheckCircle2 } from "lucide-react";
import { useDropzone } from "react-dropzone";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useQueryClient } from "@tanstack/react-query";
import { toast } from "sonner";

interface CustomerCSVImportDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

interface ParsedRow {
  name: string;
  phone: string;
  email: string;
  vehicleYear: string;
  vehicleMake: string;
  vehicleModel: string;
  vin: string;
  licensePlate: string;
  valid: boolean;
  error?: string;
}

function normalizePhoneE164(raw: string): string {
  const digits = raw.replace(/\D/g, "");
  if (digits.length === 10) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith("1")) return `+${digits}`;
  if (digits.startsWith("+")) return raw.replace(/[^\d+]/g, "");
  return `+${digits}`;
}

function parseCSV(text: string): ParsedRow[] {
  const lines = text.split(/\r?\n/).filter((l) => l.trim());
  if (lines.length < 2) return [];

  const headers = lines[0].split(",").map((h) => h.trim().toLowerCase());
  const nameIdx = headers.findIndex((h) => h.includes("name"));
  const phoneIdx = headers.findIndex((h) => h.includes("phone"));
  const emailIdx = headers.findIndex((h) => h.includes("email"));
  const yearIdx = headers.findIndex((h) => h.includes("year"));
  const makeIdx = headers.findIndex((h) => h.includes("make"));
  const modelIdx = headers.findIndex((h) => h.includes("model"));
  const vinIdx = headers.findIndex((h) => h === "vin");
  const plateIdx = headers.findIndex((h) => h.includes("plate") || h.includes("license"));

  return lines.slice(1).map((line) => {
    const cols = line.split(",").map((c) => c.trim());
    const name = nameIdx >= 0 ? cols[nameIdx] || "" : "";
    const phone = phoneIdx >= 0 ? cols[phoneIdx] || "" : "";
    const email = emailIdx >= 0 ? cols[emailIdx] || "" : "";
    const vehicleYear = yearIdx >= 0 ? cols[yearIdx] || "" : "";
    const vehicleMake = makeIdx >= 0 ? cols[makeIdx] || "" : "";
    const vehicleModel = modelIdx >= 0 ? cols[modelIdx] || "" : "";
    const vin = vinIdx >= 0 ? cols[vinIdx] || "" : "";
    const licensePlate = plateIdx >= 0 ? cols[plateIdx] || "" : "";

    const valid = !!name && !!phone;
    return {
      name, phone, email, vehicleYear, vehicleMake, vehicleModel, vin, licensePlate,
      valid,
      error: !name ? "Missing name" : !phone ? "Missing phone" : undefined,
    };
  });
}

export function CustomerCSVImportDialog({ open, onOpenChange }: CustomerCSVImportDialogProps) {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const [rows, setRows] = useState<ParsedRow[]>([]);
  const [importing, setImporting] = useState(false);
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<{ imported: number; skipped: number } | null>(null);

  const onDrop = useCallback((files: File[]) => {
    const file = files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      setRows(parseCSV(text));
      setResult(null);
    };
    reader.readAsText(file);
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: { "text/csv": [".csv"] },
    maxFiles: 1,
  });

  const handleImport = async () => {
    if (!tenant?.id) return;
    setImporting(true);
    setProgress(0);
    let imported = 0;
    let skipped = 0;
    const validRows = rows.filter((r) => r.valid);

    for (let i = 0; i < validRows.length; i++) {
      const row = validRows[i];
      try {
        const phoneE164 = normalizePhoneE164(row.phone);

        // Upsert customer
        const { data: existing } = await (supabase as any)
          .from("customers")
          .select("id")
          .eq("tenant_id", tenant.id)
          .eq("phone_e164", phoneE164)
          .maybeSingle();

        let customerId: string;
        if (existing) {
          customerId = existing.id;
        } else {
          const { data: newCust, error } = await (supabase as any)
            .from("customers")
            .insert({
              tenant_id: tenant.id,
              full_name: row.name,
              phone_e164: phoneE164,
              phone_raw: row.phone,
              email: row.email || null,
              source: "csv_import",
            })
            .select("id")
            .single();
          if (error) throw error;
          customerId = newCust.id;
        }

        // Add vehicle if make or model provided
        if (row.vehicleMake || row.vehicleModel) {
          await (supabase as any)
            .from("customer_vehicles")
            .insert({
              tenant_id: tenant.id,
              customer_id: customerId,
              year: row.vehicleYear ? parseInt(row.vehicleYear) : null,
              make: row.vehicleMake || null,
              model: row.vehicleModel || null,
              vin: row.vin || null,
              license_plate: row.licensePlate || null,
            });
        }

        imported++;
      } catch {
        skipped++;
      }
      setProgress(Math.round(((i + 1) / validRows.length) * 100));
    }

    setResult({ imported, skipped });
    setImporting(false);
    queryClient.invalidateQueries({ queryKey: ["customers"] });
    toast.success(`Imported ${imported} customers`);
  };

  const handleClose = () => {
    setRows([]);
    setResult(null);
    setProgress(0);
    onOpenChange(false);
  };

  const validCount = rows.filter((r) => r.valid).length;
  const hasVehicleData = rows.some((r) => r.vehicleMake || r.vehicleModel);

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-2xl max-h-[80vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>Import Customers from CSV</DialogTitle>
          <DialogDescription>
            Upload a CSV with columns: Name, Phone, Email, Vehicle Year, Vehicle Make, Vehicle Model, VIN, License Plate
          </DialogDescription>
        </DialogHeader>

        {rows.length === 0 ? (
          <div
            {...getRootProps()}
            className={`border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-colors ${
              isDragActive ? "border-primary bg-primary/5" : "border-border hover:border-primary/50"
            }`}
          >
            <input {...getInputProps()} />
            <Upload className="h-8 w-8 mx-auto text-muted-foreground mb-2" />
            <p className="text-sm text-muted-foreground">
              {isDragActive ? "Drop your CSV here" : "Drag & drop a CSV file, or click to browse"}
            </p>
          </div>
        ) : result ? (
          <div className="text-center py-6 space-y-3">
            <CheckCircle2 className="h-10 w-10 text-emerald-500 mx-auto" />
            <p className="text-sm">
              <strong>{result.imported}</strong> customers imported
              {result.skipped > 0 && <>, <strong>{result.skipped}</strong> skipped</>}
            </p>
            <Button onClick={handleClose}>Done</Button>
          </div>
        ) : (
          <div className="space-y-4">
            <div className="flex items-center gap-2">
              <Badge variant="secondary">{validCount} valid</Badge>
              {rows.length - validCount > 0 && (
                <Badge variant="destructive">{rows.length - validCount} invalid</Badge>
              )}
              {hasVehicleData && <Badge variant="outline">Includes vehicles</Badge>}
            </div>

            <div className="max-h-60 overflow-y-auto border rounded-lg">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Name</TableHead>
                    <TableHead>Phone</TableHead>
                    <TableHead>Email</TableHead>
                    {hasVehicleData && <TableHead>Vehicle</TableHead>}
                    <TableHead className="w-8" />
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {rows.slice(0, 50).map((row, i) => (
                    <TableRow key={i} className={!row.valid ? "opacity-50" : ""}>
                      <TableCell className="text-sm">{row.name || "—"}</TableCell>
                      <TableCell className="text-sm">{row.phone || "—"}</TableCell>
                      <TableCell className="text-sm">{row.email || "—"}</TableCell>
                      {hasVehicleData && (
                        <TableCell className="text-sm">
                          {[row.vehicleYear, row.vehicleMake, row.vehicleModel].filter(Boolean).join(" ") || "—"}
                        </TableCell>
                      )}
                      <TableCell>
                        {!row.valid && <AlertCircle className="h-3.5 w-3.5 text-destructive" />}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
            {rows.length > 50 && (
              <p className="text-xs text-muted-foreground text-center">
                Showing first 50 of {rows.length} rows
              </p>
            )}

            {importing && <Progress value={progress} className="h-2" />}

            <div className="flex justify-end gap-2">
              <Button variant="outline" onClick={handleClose} disabled={importing}>
                Cancel
              </Button>
              <Button onClick={handleImport} disabled={importing || validCount === 0}>
                {importing ? `Importing... ${progress}%` : `Import ${validCount} Customers`}
              </Button>
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { format } from "date-fns";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Skeleton } from "@/components/ui/skeleton";
import { Phone, Mail, Calendar, Clock, FileText, User, Link2, Car, ClipboardCheck, MapPin } from "lucide-react";
import { type Customer, useCustomers } from "@/hooks/useCustomers";
import { useCustomerActivity } from "@/hooks/useCustomerActivity";
import { SharePortalLinkDialog } from "@/components/customers/SharePortalLinkDialog";
import { VehiclesTab } from "@/components/customers/VehiclesTab";
import { CustomerJobsTab } from "@/components/customers/CustomerJobsTab";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { useCapabilities } from "@/hooks/useCapabilities";
import { toast } from "sonner";

interface CustomerDetailSheetProps {
  customer: Customer | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onBookAppointment?: (customer: Customer) => void;
}

const outcomeColors: Record<string, string> = {
  booked: "bg-emerald-500/10 text-emerald-700",
  followup: "bg-amber-500/10 text-amber-700",
  lost: "bg-red-500/10 text-red-700",
  escalated: "bg-purple-500/10 text-purple-700",
};

const bookingStatusColors: Record<string, string> = {
  confirmed: "bg-emerald-500/10 text-emerald-700",
  completed: "bg-blue-500/10 text-blue-700",
  canceled: "bg-red-500/10 text-red-700",
  pending_deposit: "bg-amber-500/10 text-amber-700",
  no_show: "bg-red-500/10 text-red-700",
};

/* ─── Industry-aware helpers ─── */

function getCustomerLabel(mode: string): string {
  switch (mode) {
    case "medical": return "Patient";
    case "food": return "Guest";
    case "sales": return "Prospect";
    default: return "Customer";
  }
}

function getSinceLabel(mode: string): string {
  return `${getCustomerLabel(mode)} since`;
}

function getAddressLabel(mode: string, category: string | null): string {
  if (mode === "food") return "Delivery Address";
  if (mode === "medical") return "Patient Address";
  if (mode === "dispatch") return "Pickup Location";
  if (category === "home_services") return "Service Address";
  return "Address";
}

function getBookingsTabLabel(mode: string): string {
  switch (mode) {
    case "service":
    case "medical":
    case "sales": return "Appointments";
    case "food": return "Reservations";
    case "dispatch": return "Dispatches";
    default: return "Bookings";
  }
}

function getHistoryTabLabel(mode: string, category: string | null): string {
  if (mode === "medical" || category === "beauty_wellness") return "Visit History";
  if (mode === "food") return "Order History";
  return "Service History";
}

function getBookActionLabel(mode: string): string {
  switch (mode) {
    case "medical": return "Schedule Visit";
    case "food": return "Place Order";
    case "sales": return "Schedule Meeting";
    case "dispatch": return "Create Job";
    default: return "Book Appointment";
  }
}

function showVehiclesTab(mode: string, category: string | null): boolean {
  return category === "auto_services" || mode === "dispatch" || mode === "sales";
}

export function CustomerDetailSheet({
  customer,
  open,
  onOpenChange,
  onBookAppointment,
}: CustomerDetailSheetProps) {
  const { updateCustomer } = useCustomers();
  const { callHistory, bookings, isLoading } = useCustomerActivity(
    customer?.id ?? null,
    customer?.phone_e164 ?? null,
  );
  const { mode, category } = useIndustryContext();
  const caps = useCapabilities();

  const [notes, setNotes] = useState(customer?.notes || "");
  const [notesDirty, setNotesDirty] = useState(false);
  const [portalDialogOpen, setPortalDialogOpen] = useState(false);

  const handleNotesChange = (value: string) => {
    setNotes(value);
    setNotesDirty(true);
  };

  const handleSaveNotes = async () => {
    if (!customer) return;
    try {
      await updateCustomer.mutateAsync({ id: customer.id, notes });
      setNotesDirty(false);
      toast.success("Notes saved");
    } catch {
      toast.error("Failed to save notes");
    }
  };

  if (!customer) return null;

  const hasVehicles = showVehiclesTab(mode, category);
  const hasJobs = caps.hasJobTracking;
  const customerLabel = getCustomerLabel(mode);
  const defaultTab = hasVehicles ? "vehicles" : "history";

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="sm:max-w-lg overflow-y-auto">
        <SheetHeader>
          <SheetTitle className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
              <User className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-base">{customer.full_name}</p>
              <p className="text-sm font-normal text-muted-foreground">
                {customer.phone_e164}
              </p>
            </div>
          </SheetTitle>
        </SheetHeader>

        {/* Contact info */}
        <div className="mt-4 space-y-2">
          {customer.email && (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Mail className="h-4 w-4" />
              {customer.email}
            </div>
          )}
          {customer.service_address && (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <MapPin className="h-4 w-4" />
              <span className="text-xs font-medium text-muted-foreground/70 mr-1">
                {getAddressLabel(mode, category)}:
              </span>
              {customer.service_address}
            </div>
          )}
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <Calendar className="h-4 w-4" />
            {getSinceLabel(mode)} {format(new Date(customer.created_at), "MMM d, yyyy")}
          </div>
          {customer.source && (
            <Badge variant="outline" className="text-xs">
              {customer.source}
            </Badge>
          )}
          {customer.tags && customer.tags.length > 0 && (
            <div className="flex flex-wrap gap-1">
              {customer.tags.map((tag) => (
                <Badge key={tag} variant="secondary" className="text-xs">
                  {tag}
                </Badge>
              ))}
            </div>
          )}
        </div>

        {/* Actions */}
        <div className="flex gap-2 mt-4">
          <Button
            variant="outline"
            size="sm"
            onClick={() => window.open(`tel:${customer.phone_e164}`, "_self")}
          >
            <Phone className="h-4 w-4 mr-1" />
            Call
          </Button>
          {onBookAppointment && (
            <Button
              variant="outline"
              size="sm"
              onClick={() => onBookAppointment(customer)}
            >
              <Calendar className="h-4 w-4 mr-1" />
              {getBookActionLabel(mode)}
            </Button>
          )}
          <Button
            variant="outline"
            size="sm"
            onClick={() => setPortalDialogOpen(true)}
          >
            <Link2 className="h-4 w-4 mr-1" />
            Share Portal
          </Button>
        </div>

        {/* Tabs — industry-aware */}
        <Tabs defaultValue={defaultTab} className="mt-6">
          <TabsList className="w-full flex-wrap h-auto gap-1">
            {hasVehicles && (
              <TabsTrigger value="vehicles" className="flex-1 min-w-0">
                <Car className="h-3.5 w-3.5 mr-1" />
                <span className="hidden sm:inline">Vehicles</span>
              </TabsTrigger>
            )}
            {hasJobs && (
              <TabsTrigger value="jobs" className="flex-1 min-w-0">
                <ClipboardCheck className="h-3.5 w-3.5 mr-1" />
                <span className="hidden sm:inline">Jobs</span>
              </TabsTrigger>
            )}
            <TabsTrigger value="history" className="flex-1 min-w-0">
              <Phone className="h-3.5 w-3.5 mr-1" />
              <span className="hidden sm:inline">Calls</span>
            </TabsTrigger>
            <TabsTrigger value="bookings" className="flex-1 min-w-0">
              <Calendar className="h-3.5 w-3.5 mr-1" />
              <span className="hidden sm:inline">{getBookingsTabLabel(mode)}</span>
            </TabsTrigger>
            <TabsTrigger value="notes" className="flex-1 min-w-0">
              <FileText className="h-3.5 w-3.5 mr-1" />
              <span className="hidden sm:inline">Notes</span>
            </TabsTrigger>
          </TabsList>

          {/* Vehicles Tab */}
          {hasVehicles && (
            <TabsContent value="vehicles" className="mt-4">
              <VehiclesTab customerId={customer.id} />
            </TabsContent>
          )}

          {/* Jobs Tab */}
          {hasJobs && (
            <TabsContent value="jobs" className="mt-4">
              <CustomerJobsTab customerId={customer.id} />
            </TabsContent>
          )}

          {/* Calls Tab */}
          <TabsContent value="history" className="mt-4">
            {isLoading ? (
              <div className="space-y-3">
                <Skeleton className="h-16 w-full" />
                <Skeleton className="h-16 w-full" />
              </div>
            ) : callHistory.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-8">
                No call history yet
              </p>
            ) : (
              <div className="space-y-3">
                {callHistory.map((call) => (
                  <div key={call.id} className="border rounded-lg p-3">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-sm font-medium">
                        {format(new Date(call.started_at), "MMM d, h:mm a")}
                      </span>
                      {call.outcome && (
                        <Badge className={outcomeColors[call.outcome] || "bg-muted"}>
                          {call.outcome}
                        </Badge>
                      )}
                    </div>
                    {call.summary && (
                      <p className="text-sm text-muted-foreground line-clamp-2">
                        {call.summary}
                      </p>
                    )}
                    {call.ended_at && call.started_at && (
                      <p className="text-xs text-muted-foreground mt-1 flex items-center gap-1">
                        <Clock className="h-3 w-3" />
                        {Math.round(
                          (new Date(call.ended_at).getTime() - new Date(call.started_at).getTime()) / 60000
                        )}{" "}
                        min
                      </p>
                    )}
                  </div>
                ))}
              </div>
            )}
          </TabsContent>

          {/* Bookings/Appointments/Reservations Tab */}
          <TabsContent value="bookings" className="mt-4">
            {isLoading ? (
              <div className="space-y-3">
                <Skeleton className="h-16 w-full" />
                <Skeleton className="h-16 w-full" />
              </div>
            ) : bookings.length === 0 ? (
              <p className="text-sm text-muted-foreground text-center py-8">
                No {getBookingsTabLabel(mode).toLowerCase()} yet
              </p>
            ) : (
              <div className="space-y-3">
                {bookings.map((booking) => (
                  <div key={booking.id} className="border rounded-lg p-3">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-sm font-medium">
                        {format(new Date(booking.start_at), "MMM d, h:mm a")}
                      </span>
                      <Badge className={bookingStatusColors[booking.status] || "bg-muted"}>
                        {booking.status}
                      </Badge>
                    </div>
                    {booking.service?.name && (
                      <p className="text-sm text-muted-foreground">
                        {booking.service.name}
                      </p>
                    )}
                    {booking.notes && (
                      <p className="text-xs text-muted-foreground mt-1">
                        {booking.notes}
                      </p>
                    )}
                  </div>
                ))}
              </div>
            )}
          </TabsContent>

          {/* Notes Tab */}
          <TabsContent value="notes" className="mt-4">
            <Textarea
              value={notes}
              onChange={(e) => handleNotesChange(e.target.value)}
              placeholder={`Add notes about this ${customerLabel.toLowerCase()}...`}
              rows={6}
            />
            {notesDirty && (
              <Button
                size="sm"
                className="mt-2"
                onClick={handleSaveNotes}
                disabled={updateCustomer.isPending}
              >
                {updateCustomer.isPending ? "Saving..." : "Save Notes"}
              </Button>
            )}
          </TabsContent>
        </Tabs>
      </SheetContent>

      {/* Portal link sharing dialog */}
      <SharePortalLinkDialog
        open={portalDialogOpen}
        onOpenChange={setPortalDialogOpen}
        customerId={customer.id}
        customerName={customer.full_name}
      />
    </Sheet>
  );
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { formatDistanceToNow } from "date-fns";

interface CustomerJobsTabProps {
  customerId: string;
}

const statusColors: Record<string, string> = {
  intake: "bg-blue-500/10 text-blue-700",
  in_progress: "bg-amber-500/10 text-amber-700",
  on_hold: "bg-orange-500/10 text-orange-700",
  completed: "bg-emerald-500/10 text-emerald-700",
  picked_up: "bg-primary/10 text-primary",
  cancelled: "bg-red-500/10 text-red-700",
};

export function CustomerJobsTab({ customerId }: CustomerJobsTabProps) {
  const { tenant } = useAuth();

  const { data: jobs = [], isLoading } = useQuery({
    queryKey: ["customer-jobs", tenant?.id, customerId],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await (supabase as any)
        .from("active_jobs")
        .select("id, job_number, title, status, priority, created_at, actual_completion, job_service_items(id, title, status)")
        .eq("tenant_id", tenant.id)
        .eq("customer_id", customerId)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return data ?? [];
    },
    enabled: !!tenant?.id && !!customerId,
  });

  if (isLoading) {
    return (
      <div className="space-y-3">
        <Skeleton className="h-16 w-full" />
        <Skeleton className="h-16 w-full" />
      </div>
    );
  }

  if (jobs.length === 0) {
    return <p className="text-sm text-muted-foreground text-center py-8">No jobs yet</p>;
  }

  return (
    <div className="space-y-3">
      {jobs.map((job: any) => {
        const items = job.job_service_items || [];
        const completedItems = items.filter((i: any) => i.status === "completed").length;
        return (
          <div key={job.id} className="border rounded-lg p-3">
            <div className="flex items-center justify-between mb-1">
              <div className="flex items-center gap-2">
                <span className="text-xs font-mono text-muted-foreground">{job.job_number}</span>
                <span className="text-sm font-medium">{job.title}</span>
              </div>
              <Badge className={statusColors[job.status] || "bg-muted"}>
                {job.status?.replace("_", " ")}
              </Badge>
            </div>
            {items.length > 0 && (
              <p className="text-xs text-muted-foreground">
                {completedItems}/{items.length} steps completed
              </p>
            )}
            <p className="text-xs text-muted-foreground mt-1">
              {formatDistanceToNow(new Date(job.created_at), { addSuffix: true })}
            </p>
          </div>
        );
      })}
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import type { CustomerMergeQueue as MergeQueueType } from "@/types/database";
import { GitMerge, User, Check, X, ArrowRight } from "lucide-react";

interface MergeQueueItemWithCustomer extends MergeQueueType {
  existing_customer?: {
    full_name: string;
    email: string | null;
    phone_e164: string;
  };
}

export default function CustomerMergeQueue() {
  const { tenant, user } = useAuth();
  const { toast } = useToast();
  
  const [items, setItems] = useState<MergeQueueItemWithCustomer[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (tenant?.id) {
      fetchQueue();
    }
  }, [tenant?.id]);

  const fetchQueue = async () => {
    if (!tenant?.id) return;

    const { data, error } = await supabase
      .from('customer_merge_queue')
      .select(`
        *,
        existing_customer:customers!customer_merge_queue_existing_customer_id_fkey (
          full_name,
          email,
          phone_e164
        )
      `)
      .eq('tenant_id', tenant.id)
      .eq('resolved', false)
      .order('created_at', { ascending: false });

    if (error) {
      console.error('Failed to fetch merge queue:', error);
    } else {
      setItems((data || []) as MergeQueueItemWithCustomer[]);
    }
    setLoading(false);
  };

  const handleMerge = async (item: MergeQueueItemWithCustomer) => {
    const { error: updateError } = await supabase
      .from('customers')
      .update({
        full_name: item.incoming_name || item.existing_customer?.full_name,
        email: item.incoming_email || item.existing_customer?.email,
        updated_at: new Date().toISOString(),
      })
      .eq('id', item.existing_customer_id);

    if (updateError) {
      toast({ variant: "destructive", title: "Failed to merge customer" });
      return;
    }

    await supabase
      .from('customer_merge_queue')
      .update({
        resolved: true,
        resolution: 'merged',
        resolved_at: new Date().toISOString(),
        resolved_by: user?.id,
      })
      .eq('id', item.id);

    toast({ title: "Customer merged successfully" });
    fetchQueue();
  };

  const handleKeepExisting = async (item: MergeQueueItemWithCustomer) => {
    await supabase
      .from('customer_merge_queue')
      .update({
        resolved: true,
        resolution: 'kept_existing',
        resolved_at: new Date().toISOString(),
        resolved_by: user?.id,
      })
      .eq('id', item.id);

    toast({ title: "Kept existing customer data" });
    fetchQueue();
  };

  const handleCreateNew = async (item: MergeQueueItemWithCustomer) => {
    const { error: createError } = await supabase
      .from('customers')
      .insert({
        tenant_id: tenant!.id,
        phone_e164: item.incoming_phone_e164 + '_new',
        phone_raw: item.incoming_phone_e164,
        full_name: item.incoming_name || 'Unknown',
        email: item.incoming_email,
        source: item.source,
        notes: `Created from conflict resolution. Original customer ID: ${item.existing_customer_id}`,
      });

    if (createError) {
      toast({ variant: "destructive", title: "Failed to create new customer" });
      return;
    }

    await supabase
      .from('customer_merge_queue')
      .update({
        resolved: true,
        resolution: 'created_new',
        resolved_at: new Date().toISOString(),
        resolved_by: user?.id,
      })
      .eq('id', item.id);

    toast({ title: "Created as new customer" });
    fetchQueue();
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6 text-center text-muted-foreground">
          Loading merge queue...
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="flex items-center gap-2">
              <GitMerge className="h-5 w-5" />
              Customer Conflicts
            </CardTitle>
            <CardDescription>
              Resolve conflicting customer information from different sources
            </CardDescription>
          </div>
          <Badge variant="outline" className="text-lg">
            {items.length}
          </Badge>
        </div>
      </CardHeader>
      <CardContent>
        {items.length === 0 ? (
          <div className="text-center py-8">
            <Check className="h-12 w-12 text-green-500 mx-auto mb-3" />
            <p className="font-medium">No conflicts to resolve!</p>
            <p className="text-sm text-muted-foreground">
              All customer data is clean and unified.
            </p>
          </div>
        ) : (
          <div className="space-y-4">
            {items.map((item) => (
              <div key={item.id} className="border rounded-lg p-4 space-y-4">
                <div className="flex items-center gap-2">
                  <Badge variant="outline">
                    {item.conflict_type === 'name_mismatch' && 'Name Conflict'}
                    {item.conflict_type === 'email_mismatch' && 'Email Conflict'}
                    {item.conflict_type === 'both_mismatch' && 'Multiple Conflicts'}
                  </Badge>
                  <span className="text-xs text-muted-foreground">
                    from {item.source}
                  </span>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  <div className="p-3 rounded-lg bg-muted">
                    <p className="text-xs font-medium text-muted-foreground mb-2">EXISTING</p>
                    <div className="flex items-center gap-2 mb-1">
                      <User className="h-4 w-4" />
                      <span className="font-medium">{item.existing_customer?.full_name}</span>
                    </div>
                    <p className="text-sm text-muted-foreground">
                      {item.existing_customer?.email || 'No email'}
                    </p>
                    <p className="text-sm text-muted-foreground">
                      {item.existing_customer?.phone_e164}
                    </p>
                  </div>

                  <div className="flex items-center justify-center">
                    <ArrowRight className="h-6 w-6 text-muted-foreground" />
                  </div>

                  <div className="p-3 rounded-lg bg-primary/10">
                    <p className="text-xs font-medium text-primary mb-2">INCOMING</p>
                    <div className="flex items-center gap-2 mb-1">
                      <User className="h-4 w-4" />
                      <span className="font-medium">{item.incoming_name || 'Not provided'}</span>
                    </div>
                    <p className="text-sm text-muted-foreground">
                      {item.incoming_email || 'No email'}
                    </p>
                    <p className="text-sm text-muted-foreground">
                      {item.incoming_phone_e164}
                    </p>
                  </div>
                </div>

                <div className="flex gap-2 pt-2">
                  <Button 
                    size="sm" 
                    onClick={() => handleMerge(item)}
                    className="gap-1"
                  >
                    <GitMerge className="h-3 w-3" />
                    Merge
                  </Button>
                  <Button 
                    size="sm" 
                    variant="outline" 
                    onClick={() => handleKeepExisting(item)}
                  >
                    Keep Existing
                  </Button>
                  <Button 
                    size="sm" 
                    variant="ghost" 
                    onClick={() => handleCreateNew(item)}
                  >
                    Create New
                  </Button>
                </div>
              </div>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useCustomerVehicles, type VehicleInput } from "@/hooks/useCustomerVehicles";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { Car, Plus, Trash2, X } from "lucide-react";

interface VehiclesTabProps {
  customerId: string;
}

export function VehiclesTab({ customerId }: VehiclesTabProps) {
  const { vehicles, isLoading, addVehicle, deleteVehicle } = useCustomerVehicles(customerId);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ year: "", make: "", model: "", color: "", vin: "", license_plate: "" });

  const handleSubmit = () => {
    if (!form.make && !form.model) return;
    addVehicle.mutate(
      {
        customer_id: customerId,
        year: form.year ? parseInt(form.year) : null,
        make: form.make,
        model: form.model,
        color: form.color,
        vin: form.vin,
        license_plate: form.license_plate,
      },
      {
        onSuccess: () => {
          setForm({ year: "", make: "", model: "", color: "", vin: "", license_plate: "" });
          setShowForm(false);
        },
      }
    );
  };

  if (isLoading) {
    return (
      <div className="space-y-3">
        <Skeleton className="h-20 w-full" />
        <Skeleton className="h-20 w-full" />
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {vehicles.length === 0 && !showForm && (
        <p className="text-sm text-muted-foreground text-center py-8">No vehicles on file</p>
      )}

      {vehicles.map((v) => (
        <div key={v.id} className="border rounded-lg p-3 flex items-start justify-between gap-2">
          <div className="flex items-start gap-3">
            <div className="h-9 w-9 rounded-lg bg-muted flex items-center justify-center shrink-0 mt-0.5">
              <Car className="h-4 w-4 text-muted-foreground" />
            </div>
            <div>
              <p className="text-sm font-medium">
                {[v.year, v.make, v.model].filter(Boolean).join(" ") || "Unknown Vehicle"}
              </p>
              <div className="flex flex-wrap gap-1.5 mt-1">
                {v.color && <Badge variant="outline" className="text-xs">{v.color}</Badge>}
                {v.license_plate && <Badge variant="outline" className="text-xs">Plate: {v.license_plate}</Badge>}
                {v.vin && <Badge variant="outline" className="text-xs font-mono">VIN: {v.vin}</Badge>}
              </div>
            </div>
          </div>
          <Button
            variant="ghost"
            size="icon"
            className="h-7 w-7 shrink-0 text-muted-foreground hover:text-destructive"
            onClick={() => deleteVehicle.mutate(v.id)}
          >
            <Trash2 className="h-3.5 w-3.5" />
          </Button>
        </div>
      ))}

      {showForm ? (
        <div className="border rounded-lg p-3 space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-sm font-medium">Add Vehicle</p>
            <Button variant="ghost" size="icon" className="h-7 w-7" onClick={() => setShowForm(false)}>
              <X className="h-3.5 w-3.5" />
            </Button>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <div>
              <Label className="text-xs">Year</Label>
              <Input placeholder="2022" value={form.year} onChange={(e) => setForm({ ...form, year: e.target.value })} />
            </div>
            <div>
              <Label className="text-xs">Make</Label>
              <Input placeholder="Honda" value={form.make} onChange={(e) => setForm({ ...form, make: e.target.value })} />
            </div>
            <div>
              <Label className="text-xs">Model</Label>
              <Input placeholder="Civic" value={form.model} onChange={(e) => setForm({ ...form, model: e.target.value })} />
            </div>
          </div>
          <div className="grid grid-cols-3 gap-2">
            <div>
              <Label className="text-xs">Color</Label>
              <Input placeholder="Blue" value={form.color} onChange={(e) => setForm({ ...form, color: e.target.value })} />
            </div>
            <div>
              <Label className="text-xs">VIN</Label>
              <Input placeholder="Optional" value={form.vin} onChange={(e) => setForm({ ...form, vin: e.target.value })} />
            </div>
            <div>
              <Label className="text-xs">Plate</Label>
              <Input placeholder="Optional" value={form.license_plate} onChange={(e) => setForm({ ...form, license_plate: e.target.value })} />
            </div>
          </div>
          <Button size="sm" onClick={handleSubmit} disabled={addVehicle.isPending || (!form.make && !form.model)}>
            {addVehicle.isPending ? "Adding..." : "Add Vehicle"}
          </Button>
        </div>
      ) : (
        <Button variant="outline" size="sm" className="w-full" onClick={() => setShowForm(true)}>
          <Plus className="h-3.5 w-3.5 mr-1.5" />
          Add Vehicle
        </Button>
      )}
    </div>
  );
}

import { Link } from "react-router-dom";
import { useAIReadinessV2, formatReadinessFlag, type ReadinessRecommendation } from "@/hooks/useAIReadinessV2";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { 
  Brain, 
  AlertTriangle, 
  CheckCircle2, 
  ChevronRight,
  Sparkles,
  XCircle,
  Info,
  Loader2
} from "lucide-react";

interface AIReadinessPanelProps {
  /** Compact mode for dashboard banner */
  compact?: boolean;
  /** Show even when ready */
  alwaysShow?: boolean;
}

/**
 * AI Readiness Panel - Shows readiness score, P0/P1 issues, and fix links
 * Used on /app/go-live (full) and /app/dashboard (compact banner)
 */
export function AIReadinessPanel({ compact = false, alwaysShow = false }: AIReadinessPanelProps) {
  const { 
    score, 
    p0Flags, 
    p1Flags, 
    recommendations, 
    canGoLive, 
    isReady, 
    loading,
    businessMode 
  } = useAIReadinessV2();
  
  // Don't show if ready and not forced
  if (!alwaysShow && isReady && p0Flags.length === 0) {
    return null;
  }
  
  if (loading) {
    return compact ? null : (
      <Card>
        <CardContent className="p-6 flex items-center justify-center">
          <Loader2 className="h-5 w-5 animate-spin text-muted-foreground" />
          <span className="ml-2 text-muted-foreground">Calculating readiness...</span>
        </CardContent>
      </Card>
    );
  }
  
  const getScoreColor = () => {
    if (score >= 85) return "text-emerald-500";
    if (score >= 70) return "text-amber-500";
    if (score >= 50) return "text-orange-500";
    return "text-rose-500";
  };
  
  const getScoreBg = () => {
    if (score >= 85) return "bg-emerald-500/10 border-emerald-500/30";
    if (score >= 70) return "bg-amber-500/10 border-amber-500/30";
    if (score >= 50) return "bg-orange-500/10 border-orange-500/30";
    return "bg-rose-500/10 border-rose-500/30";
  };
  
  const getProgressColor = () => {
    if (score >= 85) return "[&>div]:bg-emerald-500";
    if (score >= 70) return "[&>div]:bg-amber-500";
    if (score >= 50) return "[&>div]:bg-orange-500";
    return "[&>div]:bg-rose-500";
  };

  // Compact banner for dashboard
  if (compact) {
    return (
      <Card className={`border ${getScoreBg()}`}>
        <CardContent className="p-4">
          <div className="flex flex-col lg:flex-row lg:items-center gap-4">
            {/* Score Badge */}
            <div className="flex items-center gap-3">
              <div className="flex items-center justify-center h-12 w-12 rounded-xl bg-primary/10">
                <Brain className="h-6 w-6 text-primary" />
              </div>
              <div>
                <div className="flex items-center gap-2">
                  <span className="text-sm font-medium">AI Readiness</span>
                  <Badge variant="outline" className={getScoreColor()}>
                    {score}%
                  </Badge>
                </div>
                <div className="flex items-center gap-2 mt-1">
                  <Progress value={score} className={`w-24 h-1.5 ${getProgressColor()}`} />
                  <span className="text-xs text-muted-foreground">
                    {score >= 85 ? "Ready to go live" : "Need 85% to go live"}
                  </span>
                </div>
              </div>
            </div>
            
            {/* P0 Issues Preview */}
            {p0Flags.length > 0 && (
              <div className="flex-1 flex flex-wrap gap-2">
                {p0Flags.slice(0, 3).map(flag => (
                  <div 
                    key={flag}
                    className="flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium bg-rose-500/10 text-rose-600 dark:text-rose-400"
                  >
                    <XCircle className="h-3 w-3" />
                    <span>{formatReadinessFlag(flag)}</span>
                  </div>
                ))}
                {p0Flags.length > 3 && (
                  <Badge variant="secondary" className="text-xs">
                    +{p0Flags.length - 3} more
                  </Badge>
                )}
              </div>
            )}
            
            {/* Action Button - Route to Fix Center if issues exist, else Go Live */}
            <Button size="sm" className="gap-1 shrink-0" asChild>
              <Link to={canGoLive ? "/app/go-live" : "/app/readiness"}>
                <Sparkles className="h-3.5 w-3.5" />
                {canGoLive ? "Go Live" : "Fix Issues"}
                <ChevronRight className="h-3.5 w-3.5" />
              </Link>
            </Button>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Full panel for go-live page
  return (
    <Card className={`border ${getScoreBg()}`}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="flex items-center justify-center h-12 w-12 rounded-xl bg-primary/10">
              <Brain className="h-6 w-6 text-primary" />
            </div>
            <div>
              <CardTitle className="text-lg">AI Readiness Score</CardTitle>
              <CardDescription>
                {businessMode.charAt(0).toUpperCase() + businessMode.slice(1)} mode requirements
              </CardDescription>
            </div>
          </div>
          <div className="text-right">
            <div className={`text-4xl font-bold ${getScoreColor()}`}>{score}%</div>
            <div className="text-sm text-muted-foreground">
              {canGoLive ? "Ready to go live!" : "Need 85% + no blockers"}
            </div>
          </div>
        </div>
        <Progress value={score} className={`mt-4 h-3 ${getProgressColor()}`} />
      </CardHeader>
      
      <CardContent className="space-y-6">
        {/* P0 Issues - Required to Go Live */}
        {p0Flags.length > 0 && (
          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <XCircle className="h-4 w-4 text-rose-500" />
              <h4 className="font-medium text-rose-600 dark:text-rose-400">
                Required to Go Live ({p0Flags.length})
              </h4>
            </div>
            <div className="space-y-2">
              {p0Flags.map(flag => {
                const rec = recommendations.find(r => 
                  r.label.toLowerCase().includes(flag.replace(/_/g, " ").split("_")[0])
                );
                return (
                  <div 
                    key={flag}
                    className="flex items-center justify-between p-3 rounded-lg bg-rose-500/5 border border-rose-500/20"
                  >
                    <div className="flex items-center gap-2">
                      <AlertTriangle className="h-4 w-4 text-rose-500" />
                      <span className="text-sm font-medium">{formatReadinessFlag(flag)}</span>
                    </div>
                    {rec && (
                      <Button size="sm" variant="outline" className="text-xs h-7" asChild>
                        <Link to={rec.deep_link}>
                          Fix Now
                          <ChevronRight className="h-3 w-3 ml-1" />
                        </Link>
                      </Button>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
        
        {p0Flags.length > 0 && p1Flags.length > 0 && <Separator />}
        
        {/* P1 Issues - Optional Improvements */}
        {p1Flags.length > 0 && (
          <div className="space-y-3">
            <div className="flex items-center gap-2">
              <Info className="h-4 w-4 text-amber-500" />
              <h4 className="font-medium text-amber-600 dark:text-amber-400">
                Optional Improvements ({p1Flags.length})
              </h4>
            </div>
            <div className="space-y-2">
              {p1Flags.map(flag => {
                const rec = recommendations.find(r => 
                  r.label.toLowerCase().includes(flag.replace(/_/g, " ").split("_")[0])
                );
                return (
                  <div 
                    key={flag}
                    className="flex items-center justify-between p-3 rounded-lg bg-amber-500/5 border border-amber-500/20"
                  >
                    <div className="flex items-center gap-2">
                      <AlertTriangle className="h-4 w-4 text-amber-500" />
                      <span className="text-sm">{formatReadinessFlag(flag)}</span>
                    </div>
                    {rec && (
                      <Button size="sm" variant="ghost" className="text-xs h-7" asChild>
                        <Link to={rec.deep_link}>
                          Improve
                          <ChevronRight className="h-3 w-3 ml-1" />
                        </Link>
                      </Button>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        )}
        
        {/* All Good State */}
        {p0Flags.length === 0 && p1Flags.length === 0 && (
          <div className="flex items-center gap-3 p-4 rounded-lg bg-emerald-500/10 border border-emerald-500/30">
            <CheckCircle2 className="h-6 w-6 text-emerald-500" />
            <div>
              <p className="font-medium text-emerald-600 dark:text-emerald-400">
                All requirements met!
              </p>
              <p className="text-sm text-muted-foreground">
                Your AI assistant is ready to go live.
              </p>
            </div>
          </div>
        )}
        
        {/* Recommendations List */}
        {recommendations.length > 0 && p0Flags.length === 0 && p1Flags.length === 0 && (
          <div className="space-y-2">
            <h4 className="text-sm font-medium text-muted-foreground">Quick Links</h4>
            <div className="flex flex-wrap gap-2">
              {recommendations.slice(0, 4).map((rec, i) => (
                <Button key={i} size="sm" variant="outline" asChild>
                  <Link to={rec.deep_link}>
                    {rec.label}
                    <ChevronRight className="h-3 w-3 ml-1" />
                  </Link>
                </Button>
              ))}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Slider } from "@/components/ui/slider";
import { Label } from "@/components/ui/label";
import { useNavigate } from "react-router-dom";
import { hasVoiceFeature, hasSmsFeature } from "@/config/pricing";
import { 
  Phone, 
  MessageSquare,
  CheckCircle2, 
  AlertCircle,
  Play,
  Settings2,
  Zap,
  Copy,
  Clock
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useState } from "react";

export function AgentControlCard() {
  const { tenant, assistantSettings, refreshTenant, subscription } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  
  const [smsDelay, setSmsDelay] = useState(assistantSettings?.sms_first_delay_seconds || 5);
  const [updatingDelay, setUpdatingDelay] = useState(false);

  // Use centralized helpers for feature detection
  const planCode = subscription?.plan_code;
  const hasVoice = hasVoiceFeature(planCode);
  const hasSms = hasSmsFeature(planCode);
  const showTabs = hasVoice && hasSms;

  // Voice agent state
  const voiceEnabled = assistantSettings?.voice_ai_enabled && assistantSettings?.go_live_enabled;
  const phoneConnected = assistantSettings?.phone_connected || false;
  const calendarConnected = !!assistantSettings?.booking_url;
  const closeloopNumber = assistantSettings?.closeloop_number;
  const voiceMode = assistantSettings?.voice_mode || "always_on";
  const aiBehaviorMode = (assistantSettings as any)?.ai_behavior_mode || "full_service";

  // SMS agent state
  const smsEnabled = assistantSettings?.instant_text_enabled || false;

  const handleToggleVoice = async (enabled: boolean) => {
    if (!tenant) return;

    try {
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          go_live_enabled: enabled,
          voice_ai_enabled: enabled,
          updated_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant.id);

      if (error) throw error;

      await refreshTenant();
      toast({
        title: enabled ? "Voice Agent Activated ✅" : "Voice Agent Paused",
        description: enabled 
          ? "Now answering calls 24/7" 
          : "Paused - won't answer calls",
      });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Update Failed",
        description: error.message,
      });
    }
  };

  const handleToggleSms = async (enabled: boolean) => {
    if (!tenant) return;

    try {
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          instant_text_enabled: enabled,
          updated_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant.id);

      if (error) throw error;

      await refreshTenant();
      toast({
        title: enabled ? "SMS Agent Activated ✅" : "SMS Agent Paused",
        description: enabled 
          ? "Auto-replying to missed calls" 
          : "Paused - won't send auto-texts",
      });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Update Failed",
        description: error.message,
      });
    }
  };

  const handleDelayChange = async (value: number[]) => {
    setSmsDelay(value[0]);
  };

  const handleDelayCommit = async (value: number[]) => {
    if (!tenant) return;
    setUpdatingDelay(true);

    try {
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          sms_first_delay_seconds: value[0],
          updated_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant.id);

      if (error) throw error;

      await refreshTenant();
      toast({
        title: "Delay Updated",
        description: `SMS will send ${value[0]} seconds after missed call`,
      });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Update Failed",
        description: error.message,
      });
    } finally {
      setUpdatingDelay(false);
    }
  };

  const copyPhoneNumber = () => {
    if (closeloopNumber) {
      navigator.clipboard.writeText(closeloopNumber);
      toast({
        title: "Copied!",
        description: "Phone number copied to clipboard",
      });
    }
  };

  const VoiceAgentContent = () => (
    <div className="space-y-4">
      {/* Voice Status Row */}
      <div className="flex items-start justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className={`relative flex items-center justify-center h-12 w-12 rounded-xl transition-colors ${
            voiceEnabled 
              ? "bg-primary text-primary-foreground" 
              : "bg-muted text-muted-foreground"
          }`}>
            <Phone className="h-6 w-6" />
            {voiceEnabled && (
              <span className="absolute -top-1 -right-1 flex h-3 w-3">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-primary opacity-75"></span>
                <span className="relative inline-flex rounded-full h-3 w-3 bg-primary border-2 border-background"></span>
              </span>
            )}
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h3 className="font-medium">Voice Agent</h3>
              <Badge variant={voiceEnabled ? "default" : "secondary"} className="text-xs">
                {voiceEnabled ? "Live" : "Paused"}
              </Badge>
              {voiceEnabled && aiBehaviorMode === "callback_only" && (
                <Badge variant="outline" className="text-xs">
                  Capture Only
                </Badge>
              )}
            </div>
            <p className="text-sm text-muted-foreground">
              {!voiceEnabled
                ? "Toggle to start answering"
                : voiceMode === "after_hours_only"
                  ? "Answering after hours"
                  : "Answering calls 24/7"}
            </p>
          </div>
        </div>
        <Switch
          checked={voiceEnabled}
          onCheckedChange={handleToggleVoice}
        />
      </div>

      {/* Connection Status */}
      <div className="flex items-center gap-4 p-3 rounded-lg bg-muted/50">
        <div className="flex items-center gap-2 flex-1">
          {phoneConnected ? (
            <CheckCircle2 className="h-4 w-4 text-primary shrink-0" />
          ) : (
            <AlertCircle className="h-4 w-4 text-muted-foreground shrink-0" />
          )}
          <div className="flex items-center gap-2 min-w-0">
            <span className={`text-sm ${phoneConnected ? "text-foreground font-medium" : "text-muted-foreground"}`}>
              Phone
            </span>
            {phoneConnected && closeloopNumber && (
              <>
                <span className="text-xs text-muted-foreground truncate">
                  {closeloopNumber}
                </span>
                <Button 
                  variant="ghost" 
                  size="icon" 
                  className="h-6 w-6 shrink-0"
                  onClick={copyPhoneNumber}
                >
                  <Copy className="h-3 w-3" />
                </Button>
              </>
            )}
          </div>
        </div>
        
        <div className="w-px h-4 bg-border" />
        
        <div className="flex items-center gap-2">
          {calendarConnected ? (
            <CheckCircle2 className="h-4 w-4 text-primary" />
          ) : (
            <AlertCircle className="h-4 w-4 text-muted-foreground" />
          )}
          <span className={`text-sm ${calendarConnected ? "text-foreground font-medium" : "text-muted-foreground"}`}>
            Calendar
          </span>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-2 gap-3">
        <Button 
          variant="outline" 
          className="h-10 gap-2"
          onClick={() => navigate("/app/simulator")}
        >
          <Play className="h-4 w-4" />
          Test AI
        </Button>
        
        <Button 
          variant="outline" 
          className="h-10 gap-2"
          onClick={() => navigate("/app/ai-assistant")}
        >
          <Settings2 className="h-4 w-4" />
          Configure
        </Button>
      </div>
    </div>
  );

  const SmsAgentContent = () => (
    <div className="space-y-4">
      {/* SMS Status Row */}
      <div className="flex items-start justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className={`relative flex items-center justify-center h-12 w-12 rounded-xl transition-colors ${
            smsEnabled 
              ? "bg-primary text-primary-foreground" 
              : "bg-muted text-muted-foreground"
          }`}>
            <MessageSquare className="h-6 w-6" />
            {smsEnabled && (
              <span className="absolute -top-1 -right-1 flex h-3 w-3">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-primary opacity-75"></span>
                <span className="relative inline-flex rounded-full h-3 w-3 bg-primary border-2 border-background"></span>
              </span>
            )}
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h3 className="font-medium">SMS Agent</h3>
              <Badge variant={smsEnabled ? "default" : "secondary"} className="text-xs">
                {smsEnabled ? "Active" : "Paused"}
              </Badge>
            </div>
            <p className="text-sm text-muted-foreground">
              {smsEnabled ? "Auto-texting missed callers" : "Toggle to enable auto-texts"}
            </p>
          </div>
        </div>
        <Switch
          checked={smsEnabled}
          onCheckedChange={handleToggleSms}
        />
      </div>

      {/* Delay Setting */}
      <div className="p-4 rounded-lg bg-muted/50 space-y-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Clock className="h-4 w-4 text-muted-foreground" />
            <Label className="text-sm font-medium">Response Delay</Label>
          </div>
          <span className="text-sm font-medium tabular-nums">{smsDelay}s</span>
        </div>
        <Slider
          value={[smsDelay]}
          onValueChange={handleDelayChange}
          onValueCommit={handleDelayCommit}
          min={0}
          max={60}
          step={5}
          className="w-full"
          disabled={updatingDelay}
        />
        <p className="text-xs text-muted-foreground">
          Wait {smsDelay} seconds after a missed call before sending an AI-generated text
        </p>
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-2 gap-3">
        <Button 
          variant="outline" 
          className="h-10 gap-2"
          onClick={() => navigate("/app/simulator")}
        >
          <Play className="h-4 w-4" />
          Test SMS
        </Button>
        
        <Button 
          variant="outline" 
          className="h-10 gap-2"
          onClick={() => navigate("/app/ai-assistant")}
        >
          <Settings2 className="h-4 w-4" />
          Configure
        </Button>
      </div>
    </div>
  );

  // If no subscription yet, show a minimal card
  if (!planCode) {
    return (
      <Card className="border-border">
        <CardContent className="p-6">
          <div className="flex items-center gap-4">
            <div className="flex items-center justify-center h-14 w-14 rounded-2xl bg-muted text-muted-foreground">
              <Zap className="h-7 w-7" />
            </div>
            <div>
              <h2 className="font-semibold text-lg">AI Agents</h2>
              <p className="text-sm text-muted-foreground">
                Complete setup to activate your AI agents
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  // Determine active state for card styling
  const isAnyActive = voiceEnabled || smsEnabled;

  return (
    <Card className={`overflow-hidden transition-all ${
      isAnyActive 
        ? "border-primary/40 bg-gradient-to-br from-primary/5 via-transparent to-primary/10 shadow-lg shadow-primary/5" 
        : "border-border"
    }`}>
      <CardContent className="p-6">
        {showTabs ? (
          <Tabs defaultValue="voice" className="w-full">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-3">
                <div className={`flex items-center justify-center h-10 w-10 rounded-xl transition-colors ${
                  isAnyActive 
                    ? "bg-primary text-primary-foreground" 
                    : "bg-muted text-muted-foreground"
                }`}>
                  <Zap className="h-5 w-5" />
                </div>
                <h2 className="font-semibold text-lg">AI Agents</h2>
              </div>
              <TabsList className="h-9">
                <TabsTrigger value="voice" className="gap-1.5 text-xs px-3">
                  <Phone className="h-3.5 w-3.5" />
                  Voice
                </TabsTrigger>
                <TabsTrigger value="sms" className="gap-1.5 text-xs px-3">
                  <MessageSquare className="h-3.5 w-3.5" />
                  SMS
                </TabsTrigger>
              </TabsList>
            </div>

            <TabsContent value="voice" className="mt-0">
              <VoiceAgentContent />
            </TabsContent>
            <TabsContent value="sms" className="mt-0">
              <SmsAgentContent />
            </TabsContent>
          </Tabs>
        ) : hasVoice ? (
          <>
            <div className="flex items-center gap-3 mb-4">
              <div className={`flex items-center justify-center h-10 w-10 rounded-xl transition-colors ${
                voiceEnabled 
                  ? "bg-primary text-primary-foreground" 
                  : "bg-muted text-muted-foreground"
              }`}>
                <Phone className="h-5 w-5" />
              </div>
              <h2 className="font-semibold text-lg">Voice Agent</h2>
            </div>
            <VoiceAgentContent />
          </>
        ) : hasSms ? (
          <>
            <div className="flex items-center gap-3 mb-4">
              <div className={`flex items-center justify-center h-10 w-10 rounded-xl transition-colors ${
                smsEnabled 
                  ? "bg-primary text-primary-foreground" 
                  : "bg-muted text-muted-foreground"
              }`}>
                <MessageSquare className="h-5 w-5" />
              </div>
              <h2 className="font-semibold text-lg">SMS Agent</h2>
            </div>
            <SmsAgentContent />
          </>
        ) : null}
      </CardContent>
    </Card>
  );
}

import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { useNavigate, Link } from "react-router-dom";
import { hasVoiceFeature, hasSmsFeature } from "@/config/pricing";
import { useQuery } from "@tanstack/react-query";
import { useAIReadinessV2 } from "@/hooks/useAIReadinessV2";
import {
  Phone,
  Copy,
  Check,
  AlertCircle,
  Shield,
  Activity,
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { useState } from "react";
import { AgentOffBehaviorModal } from "./AgentOffBehaviorModal";

export function AgentControlPanel() {
  const { tenant, assistantSettings, refreshTenant, subscription, isSuperAdmin } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const { score: readinessScore, canGoLive } = useAIReadinessV2();

  const planCode = subscription?.plan_code;
  const hasVoice = hasVoiceFeature(planCode);
  const hasSms = hasSmsFeature(planCode);

  const { data: phoneNumberData } = useQuery({
    queryKey: ["tenant-phone-number", tenant?.id, isSuperAdmin],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data: tenantPhone } = await supabase
        .from("phone_numbers")
        .select("phone_e164")
        .eq("tenant_id", tenant.id)
        .limit(1)
        .maybeSingle();
      if (tenantPhone?.phone_e164) return tenantPhone.phone_e164;
      if (isSuperAdmin) {
        const { data: adminLine } = await supabase
          .from("phone_numbers")
          .select("phone_e164")
          .eq("is_admin_test_line", true)
          .limit(1)
          .maybeSingle();
        if (adminLine?.phone_e164) return adminLine.phone_e164;
      }
      return null;
    },
    enabled: !!tenant?.id,
  });

  const voiceEnabled = assistantSettings?.voice_ai_enabled && assistantSettings?.go_live_enabled;
  const smsEnabled = assistantSettings?.instant_text_enabled || false;
  const closeloopNumber =
    (assistantSettings as any)?.forwarding_phone_e164 ||
    assistantSettings?.closeloop_number ||
    phoneNumberData;
  const hasPhoneConnected = !!closeloopNumber;
  const isActive = (voiceEnabled || smsEnabled) && hasPhoneConnected;
  const canToggleOn = isSuperAdmin || canGoLive;
  const readinessPercent = readinessScore || 0;

  const [offBehaviorModalOpen, setOffBehaviorModalOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const [toggling, setToggling] = useState(false);

  const handleToggle = async (enabled: boolean) => {
    if (!tenant) return;
    if (enabled && !isSuperAdmin && !canGoLive) {
      toast({
        variant: "destructive",
        title: "Cannot Go Live Yet",
        description: `AI Readiness must be at least 85%. Currently at ${readinessPercent}%.`,
      });
      return;
    }
    if (!enabled && hasVoice) {
      const offBehavior = assistantSettings?.off_behavior || "FORWARD_OWNER";
      const forwardNumber = assistantSettings?.owner_forward_number;
      if (offBehavior === "FORWARD_OWNER" && !forwardNumber) {
        setOffBehaviorModalOpen(true);
        return;
      }
    }
    setToggling(true);
    try {
      const updates: Record<string, any> = { updated_at: new Date().toISOString() };
      if (hasVoice) {
        updates.go_live_enabled = enabled;
        updates.voice_ai_enabled = enabled;
      }
      if (hasSms) {
        updates.instant_text_enabled = enabled;
      }
      const { error } = await supabase
        .from("assistant_settings")
        .update(updates)
        .eq("tenant_id", tenant.id);
      if (error) throw error;
      await refreshTenant();
      toast({
        title: enabled ? "AI Agent is now live" : "AI Agent paused",
        description: enabled
          ? "Your AI is now handling incoming calls and messages."
          : "Your AI has stopped answering. Calls will follow your fallback rules.",
      });
    } catch (error: any) {
      toast({ variant: "destructive", title: "Update Failed", description: error.message });
    } finally {
      setToggling(false);
    }
  };

  const copyPhoneNumber = () => {
    if (closeloopNumber) {
      navigator.clipboard.writeText(closeloopNumber);
      setCopied(true);
      toast({ title: "Copied!", description: "Phone number copied to clipboard" });
      setTimeout(() => setCopied(false), 2000);
    }
  };

  const businessName = tenant?.name || "Your Business";

  // No subscription
  if (!planCode && !isSuperAdmin) {
    return (
      <div className="rounded-xl bg-card/60 backdrop-blur-sm border border-border/30 p-6">
        <div className="flex items-center gap-4">
          <div className="flex-1 min-w-0">
            <h3 className="text-lg font-semibold mb-1">Get your AI receptionist</h3>
            <p className="text-sm text-muted-foreground">
              Complete setup to start answering calls with AI.
            </p>
          </div>
          <Button asChild className="shadow-[0_0_20px_-6px_hsl(230_70%_62%/0.3)]">
            <Link to="/app/go-live">Get Started</Link>
          </Button>
        </div>
      </div>
    );
  }

  return (
    <>
      <div className={cn(
        "rounded-xl border bg-card/60 backdrop-blur-sm shadow-sm w-fit",
        isActive ? "border-success/20 shimmer-active" : "border-border/30"
      )}>
        <div className="px-5 py-4">
          {/* Status Row */}
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-3 min-w-0">
              {/* Power Toggle */}
              <button
                onClick={() => handleToggle(!isActive)}
                disabled={toggling || (!hasPhoneConnected && !isActive)}
                className={cn(
                  "relative shrink-0 h-6 w-11 rounded-full transition-colors duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                  isActive ? "bg-success" : "bg-muted-foreground/20",
                  (toggling || (!hasPhoneConnected && !isActive)) && "opacity-40 cursor-not-allowed"
                )}
              >
                <span className={cn(
                  "absolute top-0.5 left-0.5 h-5 w-5 rounded-full bg-white shadow-sm transition-transform duration-200",
                  isActive && "translate-x-5"
                )} />
              </button>

              <h2 className="text-sm font-semibold truncate text-foreground">{businessName}</h2>

              <div className={cn(
                "flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-medium shrink-0",
                isActive
                  ? "bg-success/10 text-success shadow-[0_0_12px_-2px_hsl(152_60%_44%/0.4)]"
                  : "bg-muted text-muted-foreground"
              )}>
                <span className={cn(
                  "w-1.5 h-1.5 rounded-full",
                  isActive ? "bg-success animate-pulse" : "bg-muted-foreground/40"
                )} />
                {isActive ? "Live" : "Paused"}
              </div>

              {isSuperAdmin && (
                <Badge variant="outline" className="gap-1 text-[10px] border-primary/20 shrink-0">
                  <Shield className="h-3 w-3" />
                  Admin
                </Badge>
              )}
            </div>

            <div className="flex items-center gap-3 shrink-0">
              {/* Phone Number */}
              {hasPhoneConnected ? (
                <button
                  onClick={copyPhoneNumber}
                  className="flex items-center gap-1.5 text-xs text-muted-foreground hover:text-foreground transition-colors group"
                >
                  <Phone className="h-3.5 w-3.5" />
                  <span className="font-mono text-[11px]">{formatPhone(closeloopNumber)}</span>
                  {copied ? (
                    <Check className="h-3 w-3 text-success" />
                  ) : (
                    <Copy className="h-3 w-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                  )}
                </button>
              ) : (
                <Button variant="outline" size="sm" className="h-7 gap-1.5 text-xs" asChild>
                  <Link to="/app/go-live">
                    <Phone className="h-3.5 w-3.5" />
                    Connect Phone
                  </Link>
                </Button>
              )}

              {/* Readiness */}
              <div className="hidden sm:flex items-center gap-2">
                <div className="w-px h-4 bg-border/40" />
                <Activity className="h-3.5 w-3.5 text-muted-foreground" />
                <div className={cn(
                  "relative w-14 h-1 bg-muted rounded-full overflow-hidden",
                  readinessPercent >= 85 && "glow-primary-sm"
                )}>
                  <div
                    className={cn(
                      "h-full rounded-full transition-all duration-500",
                      readinessPercent >= 85 ? "bg-success" : "bg-warning"
                    )}
                    style={{ width: `${Math.min(readinessPercent, 100)}%` }}
                  />
                </div>
                <span className={cn(
                  "text-[11px] font-medium tabular-nums",
                  readinessPercent >= 85 ? "text-success" : "text-warning"
                )}>
                  {readinessPercent}%
                </span>
                {!canGoLive && (
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-6 px-2 text-[11px] text-warning hover:text-warning gap-1"
                    onClick={() => navigate("/app/business-brain")}
                  >
                    <AlertCircle className="h-3 w-3" />
                    Complete Setup
                  </Button>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      <AgentOffBehaviorModal
        open={offBehaviorModalOpen}
        onOpenChange={setOffBehaviorModalOpen}
        tenantId={tenant?.id || ""}
        currentBehavior={assistantSettings?.off_behavior}
        currentForwardNumber={assistantSettings?.owner_forward_number}
        onConfigured={async () => {
          await refreshTenant();
          handleToggle(false);
        }}
      />
    </>
  );
}

function formatPhone(phone: string): string {
  const cleaned = phone.replace(/\D/g, "");
  if (cleaned.length === 11 && cleaned.startsWith("1")) {
    return `(${cleaned.slice(1, 4)}) ${cleaned.slice(4, 7)}-${cleaned.slice(7)}`;
  }
  return phone;
}

import { useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { useToast } from "@/hooks/use-toast";
import { Phone, Voicemail, PhoneForwarded, Loader2, AlertCircle } from "lucide-react";
import { Alert, AlertDescription } from "@/components/ui/alert";

interface AgentOffBehaviorModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  tenantId: string;
  currentBehavior?: "FORWARD_OWNER" | "VOICEMAIL" | "CALLBACK_ONLY";
  currentForwardNumber?: string;
  onConfigured: () => void;
}

export function AgentOffBehaviorModal({
  open,
  onOpenChange,
  tenantId,
  currentBehavior = "FORWARD_OWNER",
  currentForwardNumber = "",
  onConfigured,
}: AgentOffBehaviorModalProps) {
  const { toast } = useToast();
  const [behavior, setBehavior] = useState<"FORWARD_OWNER" | "VOICEMAIL" | "CALLBACK_ONLY">(currentBehavior);
  const [forwardNumber, setForwardNumber] = useState(currentForwardNumber);
  const [saving, setSaving] = useState(false);

  const handleSave = async () => {
    // Validation
    if (behavior === "FORWARD_OWNER" && !forwardNumber.trim()) {
      toast({
        variant: "destructive",
        title: "Phone Number Required",
        description: "Please enter your phone number to enable forwarding.",
      });
      return;
    }

    setSaving(true);
    try {
      const updates: any = {
        off_behavior: behavior,
        updated_at: new Date().toISOString(),
      };

      if (behavior === "FORWARD_OWNER") {
        // Normalize phone to E.164 format
        const normalizedNumber = normalizePhoneNumber(forwardNumber);
        if (!normalizedNumber) {
          throw new Error("Invalid phone number format. Use E.164 format like +1234567890");
        }
        updates.owner_forward_number = normalizedNumber;
        updates.owner_forward_verified = true; // Stub for now - can add verification flow later
      }

      const { error } = await supabase
        .from("assistant_settings")
        .update(updates)
        .eq("tenant_id", tenantId);

      if (error) throw error;

      toast({
        title: "OFF Behavior Configured",
        description: getSuccessMessage(behavior),
      });

      onConfigured();
      onOpenChange(false);
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Configuration Failed",
        description: error.message,
      });
    } finally {
      setSaving(false);
    }
  };

  const normalizePhoneNumber = (phone: string): string | null => {
    const digits = phone.replace(/\D/g, "");
    if (digits.length === 11 && digits.startsWith("1")) {
      return `+${digits}`;
    } else if (digits.length === 10) {
      return `+1${digits}`;
    } else if (phone.startsWith("+")) {
      return phone;
    }
    return null;
  };

  const getSuccessMessage = (behavior: string): string => {
    switch (behavior) {
      case "FORWARD_OWNER":
        return "Calls will be forwarded to your phone when AI is OFF";
      case "VOICEMAIL":
        return "Calls will go to voicemail when AI is OFF";
      case "CALLBACK_ONLY":
        return "Calls will be captured for callback when AI is OFF";
      default:
        return "Configuration saved";
    }
  };

  const getBehaviorSubtext = (behavior: string): string => {
    switch (behavior) {
      case "FORWARD_OWNER":
        return "Forward to your phone";
      case "VOICEMAIL":
        return "Voicemail";
      case "CALLBACK_ONLY":
        return "Callback only";
      default:
        return "";
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Configure Agent OFF Behavior</DialogTitle>
          <DialogDescription>
            Choose what happens when you turn your AI agent OFF
          </DialogDescription>
        </DialogHeader>

        <Alert>
          <AlertCircle className="h-4 w-4" />
          <AlertDescription>
            Your CloseLoop phone still receives calls when AI is OFF. Configure how to handle them.
          </AlertDescription>
        </Alert>

        <div className="space-y-4 py-4">
          <RadioGroup value={behavior} onValueChange={(value: any) => setBehavior(value)}>
            <div className="space-y-3">
              {/* Forward to Owner */}
              <Label
                htmlFor="forward"
                className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                  behavior === "FORWARD_OWNER"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:border-primary/50"
                }`}
              >
                <RadioGroupItem value="FORWARD_OWNER" id="forward" className="mt-0.5" />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <PhoneForwarded className="h-4 w-4" />
                    <span className="font-medium">Forward to my phone</span>
                  </div>
                  <p className="text-sm text-muted-foreground mt-1">
                    Calls ring your phone when AI is OFF
                  </p>
                </div>
              </Label>

              {/* Voicemail */}
              <Label
                htmlFor="voicemail"
                className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                  behavior === "VOICEMAIL"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:border-primary/50"
                }`}
              >
                <RadioGroupItem value="VOICEMAIL" id="voicemail" className="mt-0.5" />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <Voicemail className="h-4 w-4" />
                    <span className="font-medium">Voicemail</span>
                  </div>
                  <p className="text-sm text-muted-foreground mt-1">
                    Play message and record voicemail
                  </p>
                </div>
              </Label>

              {/* Callback Only */}
              <Label
                htmlFor="callback"
                className={`flex items-start gap-3 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                  behavior === "CALLBACK_ONLY"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:border-primary/50"
                }`}
              >
                <RadioGroupItem value="CALLBACK_ONLY" id="callback" className="mt-0.5" />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <Phone className="h-4 w-4" />
                    <span className="font-medium">Callback only</span>
                  </div>
                  <p className="text-sm text-muted-foreground mt-1">
                    Capture caller info, promise callback
                  </p>
                </div>
              </Label>
            </div>
          </RadioGroup>

          {/* Forward Number Input */}
          {behavior === "FORWARD_OWNER" && (
            <div className="space-y-2 pt-2">
              <Label htmlFor="phone">Your Phone Number</Label>
              <Input
                id="phone"
                type="tel"
                placeholder="+1 (555) 123-4567"
                value={forwardNumber}
                onChange={(e) => setForwardNumber(e.target.value)}
                className="font-mono"
              />
              <p className="text-xs text-muted-foreground">
                Enter in E.164 format (e.g., +12345678900) or 10-digit US number
              </p>
            </div>
          )}
        </div>

        <DialogFooter className="flex-col sm:flex-row gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)} disabled={saving}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={saving}>
            {saving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
            Save & Turn OFF
          </Button>
        </DialogFooter>

        <div className="text-xs text-muted-foreground text-center">
          When AI is OFF: <span className="font-medium">{getBehaviorSubtext(behavior)}</span>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { useNavigate } from "react-router-dom";
import { 
  Power, 
  Phone, 
  Calendar, 
  CheckCircle2, 
  AlertCircle, 
  Play,
  Settings 
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";

export function AgentStatusBanner() {
  const { tenant, assistantSettings, refreshTenant } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();

  const isLive = assistantSettings?.go_live_enabled || false;
  const phoneConnected = assistantSettings?.phone_connected || false;
  const calendarConnected = !!assistantSettings?.booking_url;

  const handleToggleLive = async (enabled: boolean) => {
    if (!tenant) return;

    try {
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          go_live_enabled: enabled,
          updated_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant.id);

      if (error) throw error;

      await refreshTenant();
      toast({
        title: enabled ? "AI Activated ✅" : "AI Paused",
        description: enabled 
          ? "Your AI is now answering calls" 
          : "Your AI is paused and won't answer calls",
      });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Update Failed",
        description: error.message,
      });
    }
