        <div className="flex flex-col md:flex-row md:items-center gap-4">
          {/* Status Indicator */}
          <div className="flex items-center gap-4 flex-1">
            <div className={`flex items-center justify-center h-12 w-12 rounded-full ${
              isLive ? "bg-primary text-primary-foreground" : "bg-muted"
            }`}>
              <Power className="h-6 w-6" />
            </div>
            
            <div>
              <div className="flex items-center gap-2">
                <h2 className="font-semibold text-lg">AI Agent</h2>
                <Badge variant={isLive ? "default" : "secondary"} className="gap-1">
                  {isLive ? (
                    <>
                      <div className="h-2 w-2 rounded-full bg-current animate-pulse" />
                      Live
                    </>
                  ) : (
                    "Paused"
                  )}
                </Badge>
              </div>
              <p className="text-sm text-muted-foreground">
                {isLive 
                  ? "Answering calls and booking appointments 24/7" 
                  : "Your AI is paused. Toggle to start answering calls."
                }
              </p>
            </div>
          </div>

          {/* Connection Health */}
          <div className="flex items-center gap-3 flex-wrap">
            <div className="flex items-center gap-1.5 text-sm">
              {phoneConnected ? (
                <CheckCircle2 className="h-4 w-4 text-primary" />
              ) : (
                <AlertCircle className="h-4 w-4 text-muted-foreground" />
              )}
              <span className={phoneConnected ? "text-foreground" : "text-muted-foreground"}>
                Phone
              </span>
            </div>
            
            <div className="flex items-center gap-1.5 text-sm">
              {calendarConnected ? (
                <CheckCircle2 className="h-4 w-4 text-primary" />
              ) : (
                <AlertCircle className="h-4 w-4 text-muted-foreground" />
              )}
              <span className={calendarConnected ? "text-foreground" : "text-muted-foreground"}>
                Calendar
              </span>
            </div>
          </div>

          {/* Controls */}
          <div className="flex items-center gap-3">
            <Button 
              variant="outline" 
              size="sm"
              onClick={() => navigate("/app/simulator")}
              className="gap-2"
            >
              <Play className="h-4 w-4" />
              Test
            </Button>
            
            <Button 
              variant="ghost" 
              size="sm"
              onClick={() => navigate("/app/ai-assistant")}
              className="gap-2"
            >
              <Settings className="h-4 w-4" />
            </Button>

            <Switch
              checked={isLive}
              onCheckedChange={handleToggleLive}
            />
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { useMemo } from "react";
import { Link } from "react-router-dom";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Zap, AlertCircle, CheckCircle2, ArrowRight } from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";
import { useWorkflows } from "@/hooks/useWorkflows";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { getAutomationTogglesForMode } from "@/lib/createDefaultWorkflows";

export function AutomationStatusCard() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const tenantId = tenant?.id ?? null;

  const { data: workflows, isLoading } = useWorkflows(tenantId);

  const stats = useMemo(() => {
    if (!workflows) return { active: 0, total: 0, hasCriticalOff: false };

    const activeCount = workflows.filter(w => w.status === "active").length;
    const toggles = getAutomationTogglesForMode(businessMode);
    
    // Check if any critical notifications are off
    const criticalTriggers = ["booking.confirmed", "order.confirmed", "dispatch.created", "missed_call"];
    const activeTriggers = new Set(
      workflows.filter(w => w.status === "active").map(w => w.trigger)
    );
    
    const hasCriticalOff = toggles.some(
      t => criticalTriggers.includes(t.trigger) && !activeTriggers.has(t.trigger)
    );

    return {
      active: activeCount,
      total: toggles.length,
      hasCriticalOff,
    };
  }, [workflows, businessMode]);

  if (isLoading) {
    return (
      <Card>
        <CardHeader className="pb-2">
          <Skeleton className="h-5 w-32" />
        </CardHeader>
        <CardContent>
          <Skeleton className="h-8 w-24" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Link to="/app/automations">
      <Card className="hover:shadow-md transition-shadow cursor-pointer hover:border-primary/50">
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
          <CardTitle className="text-sm font-medium">Automations</CardTitle>
          <div className="flex items-center gap-2">
            {stats.hasCriticalOff ? (
              <AlertCircle className="h-4 w-4 text-accent-foreground" />
            ) : stats.active > 0 ? (
              <CheckCircle2 className="h-4 w-4 text-primary" />
            ) : (
              <Zap className="h-4 w-4 text-muted-foreground" />
            )}
          </div>
        </CardHeader>
        <CardContent className="space-y-2">
          <div className="flex items-baseline gap-1">
            <span className="text-2xl font-bold">{stats.active}</span>
            <span className="text-sm text-muted-foreground">active</span>
          </div>
          
          {stats.hasCriticalOff ? (
            <div className="flex items-center gap-1 text-xs text-accent-foreground">
              <AlertCircle className="h-3 w-3" />
              Customer notifications may be off
            </div>
          ) : stats.active === 0 ? (
            <p className="text-xs text-muted-foreground">
              Enable auto-texts and notifications
            </p>
          ) : (
            <p className="text-xs text-muted-foreground">
              Auto-sending confirmations & alerts
            </p>
          )}

          <div className="flex items-center text-xs text-primary pt-1">
            Configure
            <ArrowRight className="h-3 w-3 ml-1" />
          </div>
        </CardContent>
      </Card>
    </Link>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent } from "@/components/ui/card";
import { Slider } from "@/components/ui/slider";
import { Badge } from "@/components/ui/badge";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Gauge, Loader2 } from "lucide-react";
import { cn } from "@/lib/utils";

interface BusynessRulesConfig {
  base_prep_minutes: number;
  busy_buffer_minutes: number;
  manual_busyness_pct: number;
}

/**
 * Compact busyness slider for the dashboard.
 * Allows quick adjustment of current workload level.
 */
export function BusynessSliderWidget() {
  const { tenant } = useAuth();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [busynessPct, setBusynessPct] = useState(0);
  const [config, setConfig] = useState<BusynessRulesConfig | null>(null);

  // Load current busyness settings
  useEffect(() => {
    if (!tenant?.id) return;

    const loadData = async () => {
      setLoading(true);
      try {
        const { data, error } = await supabase
          .from("tenants")
          .select("busyness_rules_jsonb" as any)
          .eq("id", tenant.id)
          .single();

        if (error) throw error;

        const dataAny = data as any;
        if (dataAny?.busyness_rules_jsonb) {
          const rules = dataAny.busyness_rules_jsonb as BusynessRulesConfig;
          setConfig(rules);
          setBusynessPct(rules.manual_busyness_pct ?? 0);
        } else {
          // Default values if not configured
          setConfig({
            base_prep_minutes: 30,
            busy_buffer_minutes: 15,
            manual_busyness_pct: 0
          });
          setBusynessPct(0);
        }
      } catch (error) {
        console.error("Failed to load busyness settings:", error);
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [tenant?.id]);

  // Save busyness value with debounce
  const saveBusyness = async (value: number) => {
    if (!tenant?.id || !config) return;

    setSaving(true);
    try {
      const updatedConfig = { ...config, manual_busyness_pct: value };
      
      const { error } = await supabase
        .from("tenants")
        .update({ busyness_rules_jsonb: updatedConfig } as any)
        .eq("id", tenant.id);

      if (error) throw error;
      
      setConfig(updatedConfig);
      toast.success(`Busyness set to ${value}%`);
    } catch (error) {
      console.error("Failed to save busyness:", error);
      toast.error("Failed to update busyness");
    } finally {
      setSaving(false);
    }
  };

  const handleSliderChange = (values: number[]) => {
    setBusynessPct(values[0]);
  };

  const handleSliderCommit = (values: number[]) => {
    saveBusyness(values[0]);
  };

  // Get status label and color
  const getStatus = () => {
    if (busynessPct === 0) return { label: "Wide Open", color: "text-success border-success/30" };
    if (busynessPct < 50) return { label: "Light", color: "text-blue-500 border-blue-500/30" };
    if (busynessPct < 80) return { label: "Busy", color: "text-amber-500 border-amber-500/30" };
    return { label: "Slammed", color: "text-destructive border-destructive/30" };
  };

  const status = getStatus();

  // Calculate current ETA adjustment
  const getETAImpact = () => {
    if (!config) return null;
    const buffer = Math.round((busynessPct / 100) * (config.busy_buffer_minutes ?? 15));
    return buffer > 0 ? `+${buffer} min` : null;
  };

  if (loading) {
    return (
      <Card className="border-2 border-border">
        <CardContent className="p-4 flex items-center justify-center">
          <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-2 border-border">
      <CardContent className="p-4">
        <div className="flex items-center gap-4">
          {/* Icon */}
          <div className={cn(
            "w-10 h-10 rounded-lg flex items-center justify-center shrink-0",
            busynessPct >= 80 ? "bg-destructive/10" : 
            busynessPct >= 50 ? "bg-amber-500/10" : 
            busynessPct > 0 ? "bg-blue-500/10" : "bg-success/10"
          )}>
            <Gauge className={cn(
              "h-5 w-5",
              busynessPct >= 80 ? "text-destructive" : 
              busynessPct >= 50 ? "text-amber-500" : 
              busynessPct > 0 ? "text-blue-500" : "text-success"
            )} />
          </div>

          {/* Slider Section */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2">
                <span className="text-sm font-medium">Current Busyness</span>
                {saving && <Loader2 className="h-3 w-3 animate-spin text-muted-foreground" />}
              </div>
              <div className="flex items-center gap-2">
                {getETAImpact() && (
                  <span className="text-xs text-muted-foreground">
                    ETA {getETAImpact()}
                  </span>
                )}
                <Badge variant="outline" className={cn("text-xs", status.color)}>
                  {status.label}
                </Badge>
                <span className="text-lg font-bold tabular-nums w-12 text-right">
                  {busynessPct}%
                </span>
              </div>
            </div>
            
            <Slider
              value={[busynessPct]}
              onValueChange={handleSliderChange}
              onValueCommit={handleSliderCommit}
              min={0}
              max={100}
              step={5}
              className="w-full"
            />
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Badge } from "@/components/ui/badge";
import { 
  Calendar, 
  Check, 
  Loader2, 
  AlertCircle,
  CalendarDays,
  RefreshCw
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface CalendarConnectionStepProps {
  onComplete: () => void;
  isComplete: boolean;
  onSkip?: () => void;
}

type CalendarOption = 'closeloop' | 'google' | 'outlook' | 'apple';

const calendarOptions = [
  { 
    id: 'closeloop' as CalendarOption, 
    name: "CloseLoop Calendar", 
    icon: CalendarDays,
    description: "Manage your availability directly in CloseLoop",
    available: true,
    recommended: true,
  },
  { 
    id: 'google' as CalendarOption, 
    name: "Google Calendar", 
    icon: "🔵",
    description: "Sync with your Google Calendar",
    available: false, // Coming soon
    oauthRequired: true,
  },
  { 
    id: 'outlook' as CalendarOption, 
    name: "Microsoft Outlook", 
    icon: "🔷",
    description: "Sync with Outlook/Microsoft 365",
    available: false,
  },
  { 
    id: 'apple' as CalendarOption, 
    name: "Apple Calendar", 
    icon: "🍎",
    description: "Sync with Apple Calendar",
    available: false,
  },
];

export function CalendarConnectionStep({ onComplete, isComplete, onSkip }: CalendarConnectionStepProps) {
  const { tenant, assistantSettings, refreshTenant } = useAuth();
  const { toast } = useToast();
  
  const [selectedOption, setSelectedOption] = useState<CalendarOption>('closeloop');
  const [bookingMode, setBookingMode] = useState<'auto_book' | 'pending_approval'>(() => {
    const rawMode = assistantSettings?.ai_booking_mode;
    return rawMode === 'pending_approval' || rawMode === 'pending' ? 'pending_approval' : 'auto_book';
  });
  const [saving, setSaving] = useState(false);

  const saveSettings = async (updates: Record<string, unknown>) => {
    if (!tenant) throw new Error("No tenant");

    // Check if settings exist first
    const { data: existing } = await supabase
      .from("assistant_settings")
      .select("tenant_id")
      .eq("tenant_id", tenant.id)
      .maybeSingle();

    if (existing) {
      // UPDATE existing row
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          ...updates,
          updated_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant.id);
      if (error) throw error;
    } else {
      // INSERT new row
      const { error } = await supabase
        .from("assistant_settings")
        .insert({
          tenant_id: tenant.id,
          ...updates,
          updated_at: new Date().toISOString(),
        });
      if (error) throw error;
    }
  };

  const handleSaveCloseLoop = async () => {
    if (!tenant) return;

    setSaving(true);
    try {
      await saveSettings({
        calendar_provider: 'closeloop',
        ai_booking_mode: bookingMode,
        setup_step_calendar: true,
      });

      // Also update tenant to enable calendar sync
      await supabase
        .from("tenants")
        .update({ 
          calendar_sync_enabled: true,
          calendar_sync_provider: 'closeloop',
        })
        .eq("id", tenant.id);

      // Auto-seed availability_slots from tenant hours_json if none exist
      const { data: existingSlots } = await supabase
        .from("availability_slots")
        .select("id")
        .eq("tenant_id", tenant.id)
        .limit(1);

      if (!existingSlots || existingSlots.length === 0) {
        // Fetch tenant hours
        const { data: tenantData } = await supabase
          .from("tenants")
          .select("hours_json")
          .eq("id", tenant.id)
          .single();

        const hoursJson = tenantData?.hours_json as Record<string, { closed?: boolean; windows?: { open: string; close: string }[] }> | null;
        if (hoursJson) {
          const dayMap: Record<string, number> = { sunday: 0, monday: 1, tuesday: 2, wednesday: 3, thursday: 4, friday: 5, saturday: 6 };
          const slotsToInsert: { tenant_id: string; day_of_week: number; start_time: string; end_time: string; is_available: boolean }[] = [];

          for (const [dayName, config] of Object.entries(hoursJson)) {
            const dow = dayMap[dayName.toLowerCase()];
            if (dow === undefined) continue;
            if (config.closed || !config.windows?.length) {
              slotsToInsert.push({ tenant_id: tenant.id, day_of_week: dow, start_time: '00:00:00', end_time: '00:00:00', is_available: false });
            } else {
              for (const w of config.windows) {
                slotsToInsert.push({ tenant_id: tenant.id, day_of_week: dow, start_time: `${w.open}:00`, end_time: `${w.close}:00`, is_available: true });
              }
            }
          }

          if (slotsToInsert.length > 0) {
            await supabase.from("availability_slots").insert(slotsToInsert);
          }
        }
      }

      await refreshTenant();
      toast({
        title: "Calendar Set Up! ✅",
        description: "Your AI can now book appointments based on your business hours.",
      });
      onComplete();
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Save Failed",
        description: error.message,
      });
    } finally {
      setSaving(false);
    }
  };

  const handleSkip = async () => {
    if (!tenant) return;

    setSaving(true);
    try {
      await saveSettings({
        setup_step_calendar: true,
      });

      await refreshTenant();
      toast({
        title: "Calendar Step Skipped",
        description: "You can set up your calendar later in Settings.",
      });
      onSkip?.();
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Skip Failed",
        description: error.message,
      });
    } finally {
      setSaving(false);
    }
  };

  const handleContinue = () => {
    if (selectedOption === 'closeloop') {
      handleSaveCloseLoop();
    } else {
      // All other options are "coming soon" - allow skip
      toast({
        title: "Coming Soon",
        description: "This calendar integration will be available soon. You can skip for now or use CloseLoop Calendar.",
      });
    }
  };

  const selectedOptionData = calendarOptions.find(o => o.id === selectedOption);

  if (isComplete) {
    const provider = assistantSettings?.calendar_provider || 'closeloop';
    return (
      <Card className="border-primary/20 bg-primary/5">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-primary">
            <Check className="h-5 w-5" />
            Calendar Connected
          </CardTitle>
          <CardDescription className="flex items-center gap-2">
            <CalendarDays className="h-4 w-4" />
            {provider === 'closeloop' ? 'Using CloseLoop Calendar' : `Connected to ${provider}`}
          </CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Calendar className="h-5 w-5 text-primary" />
          Set Up Your Calendar
        </CardTitle>
        <CardDescription>
          Your AI will book appointments directly into your calendar when customers call or text
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Calendar Source Selection */}
        <div className="space-y-3">
          <Label className="font-medium">Choose your calendar</Label>
          <RadioGroup 
            value={selectedOption} 
            onValueChange={(v) => setSelectedOption(v as CalendarOption)}
            className="space-y-3"
          >
            {calendarOptions.map((option) => {
              const IconComponent = typeof option.icon === 'string' ? null : option.icon;
              return (
                <label
                  key={option.id}
                  className={`flex items-start gap-4 p-4 rounded-lg border-2 cursor-pointer transition-all ${
                    selectedOption === option.id 
                      ? 'border-primary bg-primary/5' 
                      : 'hover:border-primary/50 hover:bg-muted/50'
                  }`}
                >
                  <RadioGroupItem 
                    value={option.id} 
                    className="mt-1" 
                  />
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      {IconComponent ? (
                        <IconComponent className="h-5 w-5 text-primary" />
                      ) : (
                        <span className="text-xl">{option.icon as string}</span>
                      )}
                      <span className="font-medium">{option.name}</span>
                      {option.recommended && (
                        <Badge variant="default" className="text-[10px]">Recommended</Badge>
                      )}
                      {!option.available && (
                        <Badge variant="secondary" className="text-[10px]">Coming Soon</Badge>
                      )}
                    </div>
                    <p className="text-sm text-muted-foreground mt-1">{option.description}</p>
                  </div>
                </label>
              );
            })}
          </RadioGroup>
        </div>

        {/* Booking Mode Selection - only show for CloseLoop */}
        {selectedOption === 'closeloop' && (
          <div className="space-y-3 pt-4 border-t">
            <Label className="font-medium">When AI books an appointment:</Label>
            <RadioGroup 
              value={bookingMode} 
              onValueChange={(value) => setBookingMode(value as 'auto_book' | 'pending_approval')}
              className="space-y-2"
            >
              <label className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all ${
                bookingMode === 'auto_book' 
                  ? 'border-primary bg-primary/5' 
                  : 'hover:bg-muted/50'
              }`}>
                <RadioGroupItem value="auto_book" className="mt-1" />
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="font-medium text-sm">Confirm Immediately</span>
                    <Badge variant="default" className="text-[10px]">Recommended</Badge>
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    AI confirms appointments instantly - customer gets immediate confirmation
                  </p>
                </div>
              </label>

              <label className={`flex items-start gap-3 p-3 rounded-lg border cursor-pointer transition-all ${
                bookingMode === 'pending_approval' 
                  ? 'border-primary bg-primary/5' 
                  : 'hover:bg-muted/50'
              }`}>
                <RadioGroupItem value="pending_approval" className="mt-1" />
                <div className="flex-1">
                  <span className="font-medium text-sm">Require My Approval</span>
                  <p className="text-xs text-muted-foreground mt-0.5">
                    AI schedules as pending - you must confirm each booking manually
                  </p>
                </div>
              </label>
            </RadioGroup>

            {bookingMode === 'pending_approval' && (
              <div className="flex items-start gap-2 p-3 rounded-lg bg-warning/10 border border-warning/30">
                <AlertCircle className="h-4 w-4 text-warning flex-shrink-0 mt-0.5" />
                <p className="text-xs text-muted-foreground">
                  Pending bookings appear in your Bookings page. You must confirm before the customer receives confirmation.
                </p>
              </div>
            )}
          </div>
        )}

        {/* What AI Does - only show for CloseLoop */}
        {selectedOption === 'closeloop' && (
          <div className="rounded-lg bg-muted/50 p-4 text-sm">
            <p className="font-medium mb-2">How AI books appointments:</p>
            <ul className="space-y-1 text-muted-foreground">
              <li className="flex items-start gap-2">
                <Check className="h-4 w-4 text-primary shrink-0 mt-0.5" />
                <span>Checks your calendar for available time slots</span>
              </li>
              <li className="flex items-start gap-2">
                <Check className="h-4 w-4 text-primary shrink-0 mt-0.5" />
                <span>Offers available times to customers on calls or via text</span>
              </li>
              <li className="flex items-start gap-2">
                <Check className="h-4 w-4 text-primary shrink-0 mt-0.5" />
                <span>Books the appointment directly into your calendar</span>
              </li>
              <li className="flex items-start gap-2">
                <Check className="h-4 w-4 text-primary shrink-0 mt-0.5" />
                <span>Sends confirmation to the customer</span>
              </li>
            </ul>
          </div>
        )}

        {/* Actions */}
        <div className="flex flex-col sm:flex-row gap-3">
          <Button 
            onClick={handleContinue} 
            disabled={saving || (selectedOption !== 'closeloop' && !selectedOptionData?.available)}
            className="flex-1 gap-2"
          >
            {saving ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : selectedOption === 'google' ? (
              <RefreshCw className="h-4 w-4" />
            ) : (
              <Check className="h-4 w-4" />
            )}
            {saving ? "Setting up..." : 
             selectedOption === 'closeloop' ? "Use CloseLoop Calendar" :
             "Connect Calendar"}
          </Button>
          
          <Button 
            variant="ghost" 
            onClick={handleSkip}
            disabled={saving}
            className="text-muted-foreground"
          >
            Skip for now
          </Button>
        </div>

        {/* Help text */}
        {selectedOption === 'closeloop' && (
          <p className="text-xs text-center text-muted-foreground">
            After setup, configure your available hours in Settings → Business Hours
          </p>
        )}
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import { Phone, Plus, ArrowRight, Check, Copy, Loader2 } from "lucide-react";
import type { AssistantSettings } from "@/types/database";

interface ConnectPhoneDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  currentSettings: AssistantSettings | null;
  onSuccess: () => void;
}

export function ConnectPhoneDialog({ 
  open, 
  onOpenChange, 
  currentSettings,
  onSuccess 
}: ConnectPhoneDialogProps) {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const [loading, setLoading] = useState(false);
  const [existingNumber, setExistingNumber] = useState("");
  const [copied, setCopied] = useState(false);

  // Get real provisioned number from currentSettings
  const closeloopForwardingNumber = currentSettings?.forwarding_phone_e164 
    || currentSettings?.closeloop_number 
    || "(Pending provisioning)";

  const handleConnectExisting = async () => {
    if (!tenant || !existingNumber.trim()) return;
    
    setLoading(true);
    try {
      // Upsert assistant settings with the business phone
      const { error } = await supabase
        .from("assistant_settings")
        .upsert({
          tenant_id: tenant.id,
          business_phone_number: existingNumber.trim(),
          phone_connected: true,
          updated_at: new Date().toISOString(),
        }, {
          onConflict: "tenant_id",
        });

      if (error) throw error;

      toast({
        title: "Phone connected!",
        description: "Set up call forwarding to complete the connection.",
      });

      onSuccess();
      onOpenChange(false);
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Failed to connect",
        description: error.message,
      });
    } finally {
      setLoading(false);
    }
  };

  const handleGetNewNumber = async () => {
    if (!tenant) return;
    
    setLoading(true);
    try {
      // Call the Twilio provisioning edge function
      const { data, error } = await supabase.functions.invoke("provision-twilio-number", {
        body: { 
          tenant_id: tenant.id,
          number_type: "local"
        },
      });

      if (error) throw error;
      if (!data?.success) {
        throw new Error(data?.error || "Failed to provision number");
      }

      toast({
        title: "New number assigned!",
        description: `Your CloseLoop number is ${data.friendly_name || data.phone_number}`,
      });

      onSuccess();
      onOpenChange(false);
    } catch (error: any) {
      console.error("Provisioning error:", error);
      toast({
        variant: "destructive",
        title: "Failed to provision number",
        description: error.message || "Failed to provision phone number",
      });
    } finally {
      setLoading(false);
    }
  };

  const copyForwardingNumber = () => {
    navigator.clipboard.writeText(closeloopForwardingNumber.replace(/\D/g, ""));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Phone className="h-5 w-5" />
            Connect Phone Number
          </DialogTitle>
          <DialogDescription>
            Set up your business phone to receive AI-powered calls and texts.
          </DialogDescription>
        </DialogHeader>

        <Tabs defaultValue="existing" className="mt-4">
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="existing">Use Existing</TabsTrigger>
            <TabsTrigger value="new">Get New Number</TabsTrigger>
          </TabsList>

          <TabsContent value="existing" className="space-y-4 mt-4">
            <div className="space-y-2">
              <Label htmlFor="phone">Your Business Phone Number</Label>
              <Input
                id="phone"
                type="tel"
                placeholder="+1 (555) 000-0000"
                value={existingNumber}
                onChange={(e) => setExistingNumber(e.target.value)}
              />
            </div>

            <div className="rounded-lg border bg-muted/50 p-4 space-y-3">
              <p className="text-sm font-medium">Set up call forwarding:</p>
              <ol className="text-sm text-muted-foreground space-y-2">
                <li className="flex items-start gap-2">
                  <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground text-xs">1</span>
                  <span>Go to your phone carrier settings</span>
                </li>
                <li className="flex items-start gap-2">
                  <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground text-xs">2</span>
                  <span>Enable call forwarding when busy/unanswered</span>
                </li>
                <li className="flex items-start gap-2">
                  <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground text-xs">3</span>
                  <div className="flex-1">
                    <span>Forward to this number:</span>
                    <div className="flex items-center gap-2 mt-1">
                      <code className="bg-background px-2 py-1 rounded text-xs">
                        {closeloopForwardingNumber}
                      </code>
                      <Button
                        size="icon"
                        variant="ghost"
                        className="h-6 w-6"
                        onClick={copyForwardingNumber}
                      >
                        {copied ? (
                          <Check className="h-3 w-3 text-green-500" />
                        ) : (
                          <Copy className="h-3 w-3" />
                        )}
                      </Button>
                    </div>
                  </div>
                </li>
              </ol>
            </div>

            <Button 
              className="w-full" 
              onClick={handleConnectExisting}
              disabled={loading || !existingNumber.trim()}
            >
              {loading ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <ArrowRight className="mr-2 h-4 w-4" />
              )}
              Connect Number
            </Button>
          </TabsContent>

          <TabsContent value="new" className="space-y-4 mt-4">
            <div className="rounded-lg border bg-muted/50 p-4 text-center">
              <Plus className="h-10 w-10 mx-auto text-muted-foreground mb-3" />
              <p className="font-medium">Get a CloseLoop Number</p>
              <p className="text-sm text-muted-foreground mt-1">
                We'll provision a new local number for your business. 
                Customers call this number and your AI answers.
              </p>
            </div>

            <Button 
              className="w-full" 
              onClick={handleGetNewNumber}
              disabled={loading}
            >
              {loading ? (
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <Plus className="mr-2 h-4 w-4" />
              )}
              {loading ? "Provisioning..." : "Get New Number"}
            </Button>
          </TabsContent>
        </Tabs>
      </DialogContent>
    </Dialog>
  );
}

import { useTenantConfig, type BusinessMode } from "@/hooks/useTenantConfig";
