  const smsEnabled = assistantSettings?.instant_text_enabled || false;
  const isAnyActive = voiceEnabled || smsEnabled;
  const closeloopNumber = assistantSettings?.closeloop_number;

  // Busyness level state
  const [busynessLevel, setBusynessLevel] = useState(0);
  const [busynessSaving, setBusynessSaving] = useState(false);

  // OFF behavior modal state
  const [offBehaviorModalOpen, setOffBehaviorModalOpen] = useState(false);

  // Load busyness level from tenant on mount
  useEffect(() => {
    if (tenant?.busyness_rules_jsonb) {
      const rules = tenant.busyness_rules_jsonb as { manual_busyness_pct?: number };
      setBusynessLevel(rules.manual_busyness_pct ?? 0);
    }
  }, [tenant]);

  // Fetch real stats
  const { data: stats } = useQuery({
    queryKey: ["dashboard-hero-stats", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return { callsToday: 0, bookingsThisWeek: 0, revenueRecovered: 0 };

      const today = new Date();
      const todayStart = startOfDay(today).toISOString();
      const todayEnd = endOfDay(today).toISOString();
      const weekStart = startOfWeek(today, { weekStartsOn: 1 }).toISOString();
      const weekEnd = endOfWeek(today, { weekStartsOn: 1 }).toISOString();

      const [callsResult, bookingsResult] = await Promise.all([
        supabase
          .from("ai_call_sessions")
          .select("*", { count: "exact", head: true })
          .eq("tenant_id", tenant.id)
          .gte("started_at", todayStart)
          .lte("started_at", todayEnd),
        supabase
          .from("bookings")
          .select("deposit_paid, service_id, services(price_cents)")
          .eq("tenant_id", tenant.id)
          .gte("created_at", weekStart)
          .lte("created_at", weekEnd)
      ]);

      const bookings = bookingsResult.data || [];
      const bookingsThisWeek = bookings.length;
      
      // Calculate revenue from confirmed bookings with deposits
      const revenueRecovered = bookings
        .filter(b => b.deposit_paid)
        .reduce((sum, b) => {
          const price = (b.services as { price_cents?: number } | null)?.price_cents || 0;
          return sum + (price / 100);
        }, 0);

      return {
        callsToday: callsResult.count || 0,
        bookingsThisWeek,
        revenueRecovered: Math.round(revenueRecovered)
      };
    },
    enabled: !!tenant?.id,
    refetchInterval: 30000,
  });

  const readinessScore = calculateReadinessFromContext(context);

  const handleToggle = async (enabled: boolean) => {
    if (!tenant) return;

    // If turning OFF, check if off_behavior is configured
    if (!enabled && hasVoice) {
      const offBehavior = assistantSettings?.off_behavior || "FORWARD_OWNER";
      const forwardNumber = assistantSettings?.owner_forward_number;

      // If FORWARD_OWNER but no number configured, show modal
      if (offBehavior === "FORWARD_OWNER" && !forwardNumber) {
        setOffBehaviorModalOpen(true);
        return;
      }
    }

    try {
      const updates: Record<string, any> = {
        updated_at: new Date().toISOString(),
      };

      // Update voice settings if user has voice capability
      if (hasVoice) {
        updates.go_live_enabled = enabled;
        updates.voice_ai_enabled = enabled;
      }

      // Update SMS settings if user has SMS capability
      if (hasSms) {
        updates.instant_text_enabled = enabled;
      }

      const { error } = await supabase
        .from("assistant_settings")
        .update(updates)
        .eq("tenant_id", tenant.id);

      if (error) throw error;

      await refreshTenant();

      // Get configured off behavior for better messaging
      const offBehavior = assistantSettings?.off_behavior || "FORWARD_OWNER";
      const offBehaviorLabel = getOffBehaviorLabel(offBehavior);

      toast({
        title: enabled ? "AI Agent Activated ✅" : "AI Agent Paused",
        description: enabled
          ? "Now handling calls & messages 24/7"
          : `Paused - ${offBehaviorLabel}`,
      });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Update Failed",
        description: error.message,
      });
    }
  };

  const getOffBehaviorLabel = (behavior: string): string => {
    switch (behavior) {
      case "FORWARD_OWNER":
        return "calls will forward to you";
      case "VOICEMAIL":
        return "calls go to voicemail";
      case "CALLBACK_ONLY":
        return "capturing callback requests";
      default:
        return "won't handle calls";
    }
  };

  const copyPhoneNumber = () => {
    if (closeloopNumber) {
      navigator.clipboard.writeText(closeloopNumber);
      toast({
        title: "Copied!",
        description: "Phone number copied to clipboard",
      });
    }
  };

  // Debounced save for busyness level
  const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  const saveBusynessLevel = useCallback(
    async (level: number) => {
      if (!tenant?.id) return;
      setBusynessSaving(true);

      try {
        const currentRules = (tenant.busyness_rules_jsonb as Record<string, unknown>) || {};
        const updatedRules = {
          ...currentRules,
          manual_busyness_pct: level,
        };

        const { error } = await supabase
          .from("tenants")
          .update({ busyness_rules_jsonb: updatedRules })
          .eq("id", tenant.id);

        if (error) throw error;

        await refreshTenant();
        toast({
          title: "Saved",
          description: `Busyness level set to ${level}%`,
        });
      } catch (error: any) {
        toast({
          variant: "destructive",
          title: "Save Failed",
          description: error.message,
        });
      } finally {
        setBusynessSaving(false);
      }
    },
    [tenant?.id, refreshTenant, toast]
  );

  const handleBusynessChange = (values: number[]) => {
    const level = values[0];
    setBusynessLevel(level);

    // Debounce the save
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current);
    }
    saveTimeoutRef.current = setTimeout(() => {
      saveBusynessLevel(level);
    }, 500);
  };

  const getBusynessHelperText = (level: number): string => {
    if (level <= 25) return "Relaxed: answer fast, be flexible";
    if (level <= 70) return "Normal: balanced";
    return "Packed: stricter, prioritize callback";
  };

  if (!planCode) {
    return (
      <Card>
        <CardContent className="p-5">
          <div className="flex items-center gap-4">
            <div className="flex items-center justify-center h-12 w-12 rounded-xl bg-muted text-muted-foreground">
              <Zap className="h-6 w-6" />
            </div>
            <div>
              <h2 className="font-semibold">AI Agent</h2>
              <p className="text-sm text-muted-foreground">
                Complete setup to activate your AI agent
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  const metrics = [
    {
      label: "Calls Today",
      value: stats?.callsToday || 0,
      icon: Phone,
    },
    {
      label: "Bookings",
      value: stats?.bookingsThisWeek || 0,
      icon: Calendar,
      sublabel: "this week",
    },
    {
      label: "Revenue",
      value: `$${(stats?.revenueRecovered || 0).toLocaleString()}`,
      icon: TrendingUp,
      sublabel: "recovered",
    },
    {
      label: "AI Ready",
      value: `${readinessScore}%`,
      icon: Brain,
    },
  ];

  return (
    <Card className={cn(
      "overflow-hidden transition-all duration-200 animate-fade-in",
      isAnyActive && "border-primary/30"
    )}>
      <CardContent className="p-0">
        {/* Top Section: Agent Status */}
        <div className="p-5">
          <div className="flex items-start justify-between gap-4">
            <div className="flex items-center gap-4">
              <div className={cn(
                "relative flex items-center justify-center h-12 w-12 rounded-xl transition-colors duration-200",
                isAnyActive 
                  ? "bg-primary text-primary-foreground" 
                  : "bg-muted text-muted-foreground"
              )}>
                {hasVoice ? <Phone className="h-5 w-5" /> : <MessageSquare className="h-5 w-5" />}
                {isAnyActive && (
                  <span className="absolute -top-1 -right-1 flex h-3 w-3">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-success opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-3 w-3 bg-success border-2 border-card"></span>
                  </span>
                )}
              </div>
              <div className="min-w-0">
                <div className="flex items-center gap-2.5 flex-wrap">
                  <h2 className="font-semibold text-base">AI Agent</h2>
                  <Badge 
                    variant={isAnyActive ? "success" : "muted"} 
                    size="sm"
                  >
                    {isAnyActive ? "Live" : "Paused"}
                  </Badge>
                  {hasVoice && hasSms && (
                    <Badge variant="outline" size="sm" className="hidden sm:inline-flex">Voice + SMS</Badge>
                  )}
                </div>
                <p className="text-sm text-muted-foreground mt-0.5 truncate max-w-[280px]">
                  {isAnyActive 
                    ? hasVoice && hasSms
                      ? `Handling calls & texts for ${tenant?.name || "your business"}`
                      : hasVoice
                        ? `Answering calls for ${tenant?.name || "your business"}`
                        : `Text-backs for ${tenant?.name || "your business"}`
                    : hasVoice 
                      ? "Toggle to start answering calls"
                      : "Enable instant text responses"
                  }
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3">
              {closeloopNumber && (
                <Button 
                  variant="ghost" 
                  size="icon" 
                  className="h-9 w-9 text-muted-foreground hover:text-foreground"
                  onClick={copyPhoneNumber}
                >
                  <Copy className="h-4 w-4" />
                </Button>
              )}
              <Switch
                checked={isAnyActive}
                onCheckedChange={handleToggle}
              />
            </div>
          </div>

          {/* Quick Actions */}
          <div className="flex flex-wrap gap-2 mt-5">
            <Button
              variant="outline"
              size="sm"
              className="h-9 gap-2"
              onClick={() => navigate("/app/simulator")}
            >
              <Play className="h-4 w-4" />
              Test
            </Button>
            <Button
              variant="outline"
              size="sm"
              className="h-9 gap-2"
              onClick={() => navigate("/app/business-brain")}
            >
              <Brain className="h-4 w-4" />
              Knowledge
            </Button>
            <Button
              variant="outline"
              size="sm"
              className="h-9 gap-2"
              onClick={() => navigate("/app/inbox?tab=calls")}
            >
              <Phone className="h-4 w-4" />
              Calls
            </Button>
          </div>
        </div>

        {/* Middle Section: Busyness Slider (dispatch/food only) */}
        {showBusynessSlider && (
        <TooltipProvider>
          <div className="border-t border-border/50 bg-muted/30 px-5 py-4">
            <div className="flex items-center gap-2 mb-3">
              <Gauge className="h-4 w-4 text-muted-foreground" />
              <Label className="text-sm font-medium flex items-center gap-1.5">
                Busyness
                <Tooltip>
                  <TooltipTrigger asChild>
                    <HelpCircle className="h-3.5 w-3.5 text-muted-foreground/60 cursor-help" />
                  </TooltipTrigger>
                  <TooltipContent side="top" className="max-w-xs text-xs">
                    <p>Higher values make AI prioritize urgent requests and offer callbacks.</p>
                  </TooltipContent>
                </Tooltip>
              </Label>
              <span className="text-sm font-medium tabular-nums ml-auto text-muted-foreground">
                {busynessLevel}%
              </span>
              {busynessSaving && (
                <Badge variant="muted" size="sm">Saving...</Badge>
              )}
            </div>
            <Slider
              value={[busynessLevel]}
              onValueChange={handleBusynessChange}
              min={0}
              max={100}
              step={5}
              className="w-full"
              disabled={busynessSaving}
            />
            <p className="text-xs text-muted-foreground mt-2">
              {getBusynessHelperText(busynessLevel)}
            </p>
          </div>
        </TooltipProvider>
        )}

        {/* Bottom Section: Metrics Strip */}
        <div className="border-t border-border/50 bg-muted/20 px-5 py-4">
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            {metrics.map((metric) => (
              <div key={metric.label} className="flex items-center gap-3">
                <div className="flex items-center justify-center h-9 w-9 rounded-lg bg-primary/8">
                  <metric.icon className="h-4 w-4 text-primary" />
                </div>
                <div className="min-w-0">
                  <p className="text-base font-semibold leading-none tabular-nums">{metric.value}</p>
                  <p className="text-xs text-muted-foreground mt-0.5 truncate">{metric.label}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </CardContent>

      {/* OFF Behavior Configuration Modal */}
      <AgentOffBehaviorModal
        open={offBehaviorModalOpen}
        onOpenChange={setOffBehaviorModalOpen}
        tenantId={tenant?.id || ""}
        currentBehavior={assistantSettings?.off_behavior}
        currentForwardNumber={assistantSettings?.owner_forward_number}
        onConfigured={async () => {
          await refreshTenant();
          // After configuration, proceed with toggle OFF
          handleToggle(false);
        }}
      />
    </Card>
  );
}

import { useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Copy, Check, ExternalLink, Zap } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

const SUPABASE_PROJECT_REF = import.meta.env.VITE_SUPABASE_PROJECT_ID || "zsqfzluyylzmmjtfxwgr";
const ELEVENLABS_INIT_URL = `https://${SUPABASE_PROJECT_REF}.supabase.co/functions/v1/elevenlabs-init`;

export function ElevenLabsInitWebhookCard() {
  const { toast } = useToast();
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(ELEVENLABS_INIT_URL);
      setCopied(true);
      toast({
        title: "Copied!",
        description: "Webhook URL copied to clipboard",
      });
      setTimeout(() => setCopied(false), 2000);
    } catch (error) {
      toast({
        variant: "destructive",
        title: "Copy failed",
        description: "Please copy the URL manually",
      });
    }
  };

  return (
    <Card className="border-accent/20 bg-accent/5">
      <CardHeader className="pb-3">
        <div className="flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-accent/10">
            <Zap className="h-4 w-4 text-accent-foreground" />
          </div>
          <div>
            <CardTitle className="text-base flex items-center gap-2">
              ElevenLabs Initiation Webhook
              <Badge variant="outline" className="text-xs">Optional</Badge>
            </CardTitle>
            <CardDescription className="text-xs">
              Inject business context when calls start
            </CardDescription>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="space-y-2">
          <div className="flex gap-2">
            <Input
              readOnly
              value={ELEVENLABS_INIT_URL}
              className="font-mono text-xs bg-background"
            />
            <Button
              variant="outline"
              size="icon"
              onClick={handleCopy}
              className="shrink-0"
            >
              {copied ? (
                <Check className="h-4 w-4 text-primary" />
              ) : (
                <Copy className="h-4 w-4" />
              )}
            </Button>
          </div>
          <p className="text-xs text-muted-foreground">
            Paste this URL in ElevenLabs → Settings → Conversation Initiation Client Data Webhook
          </p>
        </div>

        <div className="rounded-lg border bg-muted/50 p-3 space-y-2">
          <p className="text-xs font-medium">This webhook provides:</p>
          <ul className="text-xs text-muted-foreground space-y-1">
            <li>• Business name, hours, and services pricing</li>
            <li>• Menu items (for food businesses)</li>
            <li>• FAQs and booking links</li>
            <li>• HIPAA-compliant data filtering</li>
          </ul>
        </div>

        <Button
          variant="outline"
          size="sm"
          className="w-full gap-2"
          asChild
        >
          <a
            href="https://elevenlabs.io/docs/conversational-ai/customization/personalization/dynamic-variables"
            target="_blank"
            rel="noopener noreferrer"
          >
            <ExternalLink className="h-3 w-3" />
            ElevenLabs Documentation
          </a>
        </Button>
      </CardContent>
    </Card>
  );
}

import { useAuth } from "@/contexts/AuthContext";
import { useAIReadinessV2, formatReadinessFlag } from "@/hooks/useAIReadinessV2";
import { SectionCard } from "@/components/layout/SectionCard";
import { Progress } from "@/components/ui/progress";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  CheckCircle2,
  XCircle,
  AlertTriangle,
  ArrowRight,
  Rocket,
  Sparkles,
  ChevronRight,
} from "lucide-react";
import { Link } from "react-router-dom";

/**
 * Go Live Checklist - Uses V2 readiness system with RPC-based scoring
 * Shows P0 blockers with deep links to fix them
 */
export function GoLiveChecklist() {
  const { assistantSettings } = useAuth();
  const {
    score,
    p0Flags,
    p1Flags,
    recommendations,
    canGoLive,
    isReady,
    loading
  } = useAIReadinessV2();

  const goLiveEnabled = assistantSettings?.go_live_enabled || false;

  // Already live - show success state
  if (goLiveEnabled) {
    return (
      <SectionCard
        variant="elevated"
        className="border-emerald-500/30 bg-gradient-to-br from-emerald-500/10 to-transparent"
      >
        <div className="flex items-center gap-4 p-4">
          <div className="h-12 w-12 rounded-xl bg-emerald-500/20 flex items-center justify-center shrink-0">
            <Rocket className="h-6 w-6 text-emerald-500" />
          </div>
          <div className="flex-1 min-w-0">
            <h3 className="font-semibold flex items-center gap-2">
              You're Live!
              <Badge variant="default" className="bg-emerald-500 hover:bg-emerald-600">
                Active
              </Badge>
            </h3>
            <p className="text-sm text-muted-foreground">
              AI answering calls 24/7 • {score}% readiness
            </p>
          </div>
          <Button variant="outline" size="sm" className="gap-1.5" asChild>
            <Link to="/app/calls">
              View Calls
              <ChevronRight className="h-4 w-4" />
            </Link>
          </Button>
        </div>
      </SectionCard>
    );
  }

  if (loading) {
    return (
      <SectionCard>
        <div className="flex items-center justify-center py-8">
          <div className="animate-spin rounded-full h-6 w-6 border-2 border-primary border-t-transparent" />
          <span className="ml-3 text-sm text-muted-foreground">Checking readiness...</span>
        </div>
      </SectionCard>
    );
  }

  const getScoreColor = () => {
    if (score >= 85) return "text-emerald-500";
    if (score >= 70) return "text-amber-500";
    if (score >= 50) return "text-orange-500";
    return "text-rose-500";
  };

  const getProgressColor = () => {
    if (score >= 85) return "[&>div]:bg-emerald-500";
    if (score >= 70) return "[&>div]:bg-amber-500";
    if (score >= 50) return "[&>div]:bg-orange-500";
    return "[&>div]:bg-rose-500";
  };

  return (
    <SectionCard
      variant="elevated"
      className={score >= 85 && p0Flags.length === 0 ? "border-emerald-500/30" : ""}
    >
      {/* Header */}
      <div className="flex items-center justify-between mb-4 p-5 pb-0">
        <div className="flex items-center gap-3">
          <div className="h-10 w-10 rounded-xl bg-primary/10 flex items-center justify-center">
            <Sparkles className="h-5 w-5 text-primary" />
          </div>
          <div>
            <h3 className="font-semibold flex items-center gap-2">
              Go Live Checklist
              {canGoLive && (
                <Badge variant="outline" className="text-emerald-500 border-emerald-500/30">
                  Ready
                </Badge>
              )}
            </h3>
            <p className="text-sm text-muted-foreground">
              {canGoLive
                ? "All requirements met"
                : `${p0Flags.length} issue${p0Flags.length !== 1 ? 's' : ''} to fix`}
            </p>
          </div>
        </div>
        <div className="text-right">
          <div className={`text-3xl font-bold ${getScoreColor()}`}>{score}%</div>
          <div className="text-xs text-muted-foreground">readiness</div>
        </div>
      </div>

      {/* Progress Bar */}
      <div className="px-5 pb-4">
        <Progress value={score} className={`h-2 ${getProgressColor()}`} />
      </div>

      <Separator />

      {/* Checklist Items */}
      <div className="p-5 space-y-3">
        {/* P0 Issues - Must Fix */}
        {p0Flags.length > 0 && (
          <div className="space-y-2">
            <div className="flex items-center gap-2 mb-2">
              <XCircle className="h-4 w-4 text-rose-500" />
              <span className="text-sm font-medium text-rose-600 dark:text-rose-400">
                Must Fix ({p0Flags.length})
              </span>
            </div>
            {p0Flags.map((flag) => {
              const rec = recommendations.find(r =>
                r.label.toLowerCase().includes(flag.replace(/_/g, " ").split("_")[0]) ||
                flag.includes(r.label.toLowerCase().replace(/\s+/g, "_"))
              );
              return (
                <Link
                  key={flag}
                  to={rec?.deep_link || "/app/settings"}
                  className="flex items-center justify-between p-3 rounded-lg bg-rose-500/5 border border-rose-500/20 hover:bg-rose-500/10 transition-colors group"
                >
                  <div className="flex items-center gap-2.5 flex-1 min-w-0">
                    <AlertTriangle className="h-4 w-4 text-rose-500 shrink-0" />
                    <span className="text-sm font-medium truncate">
                      {formatReadinessFlag(flag)}
                    </span>
                  </div>
                  <ChevronRight className="h-4 w-4 text-muted-foreground group-hover:text-foreground shrink-0" />
                </Link>
              );
            })}
          </div>
        )}

        {/* P1 Issues - Recommended (show max 3) */}
        {p0Flags.length === 0 && p1Flags.length > 0 && (
          <div className="space-y-2">
            <div className="flex items-center gap-2 mb-2">
              <CheckCircle2 className="h-4 w-4 text-amber-500" />
              <span className="text-sm font-medium text-amber-600 dark:text-amber-400">
                Recommended ({p1Flags.length})
              </span>
            </div>
            {p1Flags.slice(0, 3).map((flag) => {
              const rec = recommendations.find(r =>
                r.label.toLowerCase().includes(flag.replace(/_/g, " ").split("_")[0]) ||
                flag.includes(r.label.toLowerCase().replace(/\s+/g, "_"))
              );
              return (
                <Link
                  key={flag}
                  to={rec?.deep_link || "/app/settings"}
                  className="flex items-center justify-between p-3 rounded-lg bg-amber-500/5 border border-amber-500/20 hover:bg-amber-500/10 transition-colors group"
                >
                  <div className="flex items-center gap-2.5 flex-1 min-w-0">
                    <AlertTriangle className="h-4 w-4 text-amber-500 shrink-0" />
                    <span className="text-sm truncate">{formatReadinessFlag(flag)}</span>
                  </div>
                  <ChevronRight className="h-4 w-4 text-muted-foreground group-hover:text-foreground shrink-0" />
                </Link>
              );
            })}
          </div>
        )}

        {/* All Good State */}
        {p0Flags.length === 0 && p1Flags.length === 0 && (
          <div className="flex items-center gap-3 p-4 rounded-lg bg-emerald-500/10 border border-emerald-500/30">
            <CheckCircle2 className="h-6 w-6 text-emerald-500" />
            <div className="flex-1">
              <p className="font-medium text-emerald-600 dark:text-emerald-400">
                All requirements met!
              </p>
              <p className="text-sm text-muted-foreground">
                You're ready to go live with your AI assistant.
              </p>
            </div>
          </div>
        )}

        {/* Action Button */}
        <div className="pt-2">
          <Button
            className={`w-full gap-2 ${!canGoLive && 'opacity-50 cursor-not-allowed'}`}
            variant={canGoLive ? "default" : "secondary"}
            disabled={!canGoLive}
            asChild={canGoLive}
          >
            {canGoLive ? (
              <Link to="/app/go-live">
                <Rocket className="h-4 w-4" />
                Go Live Now
                <ArrowRight className="h-4 w-4 ml-auto" />
              </Link>
            ) : (
              <>
                <Sparkles className="h-4 w-4" />
                Complete {p0Flags.length} Step{p0Flags.length !== 1 ? 's' : ''} to Go Live
              </>
            )}
          </Button>
          {!canGoLive && (
            <p className="text-xs text-center text-muted-foreground mt-2">
              Score must be 85%+ with no blocking issues
            </p>
          )}
        </div>
      </div>
    </SectionCard>
  );
}

import { useState, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Link } from "react-router-dom";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Power, Check, Loader2, Sparkles, Phone, Calendar, MessageSquare, Shield, AlertTriangle, Brain } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { hasVoiceFeature, hasSmsFeature } from "@/config/pricing";
import { useAIReadinessV2 } from "@/hooks/useAIReadinessV2";

interface GoLiveStepProps {
  onComplete: () => void;
  isComplete: boolean;
  canActivate: boolean; // Basic prerequisite (phone + test)
}

export function GoLiveStep({ onComplete, isComplete, canActivate }: GoLiveStepProps) {
  const { tenant, assistantSettings, subscription, refreshTenant } = useAuth();
  const { toast } = useToast();
  const { score, canGoLive, p0Flags, loading: readinessLoading } = useAIReadinessV2();

  const [showConfirm, setShowConfirm] = useState(false);
  const [activating, setActivating] = useState(false);
  const isLive = assistantSettings?.go_live_enabled || false;

  // Plan-based feature filtering using centralized helpers
  const planCode = subscription?.plan_code || null;
  const hasVoice = hasVoiceFeature(planCode);
  const hasSms = hasSmsFeature(planCode);

  // CRITICAL: Go live requires 85%+ readiness score AND no P0 blockers
  const meetsReadinessRequirements = canGoLive; // This checks score >= 85 AND p0Flags.length === 0
  const fullyCanActivate = canActivate && meetsReadinessRequirements;

  // Filter features based on plan capabilities
  const features = useMemo(() => {
    const allFeatures = [];
    if (hasVoice) {
      allFeatures.push({ icon: Phone, text: "Answer calls you miss or can't take" });
    }
    if (hasSms) {
      allFeatures.push({ icon: MessageSquare, text: "Send instant texts to missed callers" });
    }
    allFeatures.push(
      { icon: Calendar, text: "Direct customers to book appointments" },
      { icon: Shield, text: "Work 24/7, even when you're closed" }
    );
    return allFeatures;
  }, [hasVoice, hasSms]);

  const handleGoLive = async () => {
    if (!tenant) return;

    setActivating(true);
    try {
      const { error } = await supabase
        .from("assistant_settings")
        .upsert({
          tenant_id: tenant.id,
          go_live_enabled: true,
          setup_completed_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        } as any, {
          onConflict: "tenant_id",
        });

      if (error) throw error;

      await refreshTenant();
      setShowConfirm(false);
      
      toast({
        title: "AI is now live",
        description: "Your AI is handling incoming calls.",
      });
      onComplete();
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Activation Failed",
        description: error.message,
      });
    } finally {
      setActivating(false);
    }
  };

  const handleToggleLive = async (enabled: boolean) => {
    if (!tenant) return;

    try {
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          go_live_enabled: enabled,
          updated_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant.id);

      if (error) throw error;

      await refreshTenant();
      toast({
        title: enabled ? "AI is now live" : "AI paused",
        description: enabled 
          ? "Your AI is handling incoming calls." 
          : "Your AI won't answer calls until you turn it back on.",
      });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Update Failed",
        description: error.message,
      });
    }
  };

  if (isComplete || isLive) {
    return (
      <Card className="border-primary/20 bg-gradient-to-br from-primary/5 to-primary/10">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-primary">
            <Sparkles className="h-5 w-5" />
            Your AI is Live! 🎉
          </CardTitle>
          <CardDescription>
            Your AI assistant is actively answering calls and helping customers
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between p-4 rounded-lg bg-background/80">
            <div className="flex items-center gap-3">
              <div className="h-3 w-3 rounded-full bg-success animate-pulse" />
              <span className="font-medium">AI Agent Status</span>
            </div>
            <div className="flex items-center gap-3">
              <Badge variant={isLive ? "default" : "secondary"}>
                {isLive ? "Active" : "Paused"}
              </Badge>
              <Switch
                checked={isLive}
                onCheckedChange={handleToggleLive}
              />
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <Card className={!fullyCanActivate ? "opacity-90" : ""}>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Power className="h-5 w-5 text-primary" />
            Go Live
          </CardTitle>
          <CardDescription>
            {fullyCanActivate 
              ? "You're ready! Activate your AI to start answering calls."
              : "Complete your setup to activate your AI."
            }
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Readiness Score - Always show */}
          <div className="space-y-3 p-4 rounded-lg border bg-muted/30">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <Brain className="h-4 w-4 text-primary" />
                <span className="text-sm font-medium">AI Readiness</span>
              </div>
              <Badge variant={meetsReadinessRequirements ? "default" : "secondary"}>
                {readinessLoading ? "..." : `${score}%`}
              </Badge>
            </div>
            <Progress value={score} className="h-2" />
            <p className="text-xs text-muted-foreground">
              {meetsReadinessRequirements 
                ? "Your AI is ready to go live!"
                : "Need 85% or higher to go live. Complete your Business Brain setup."
              }
            </p>
            
            {/* P0 Blockers */}
            {p0Flags.length > 0 && (
              <div className="mt-3 space-y-2">
                <p className="text-xs font-medium text-destructive flex items-center gap-1">
                  <AlertTriangle className="h-3 w-3" />
                  {p0Flags.length} blocking issue{p0Flags.length > 1 ? "s" : ""} to fix:
                </p>
                <ul className="text-xs text-muted-foreground space-y-1">
                  {p0Flags.slice(0, 3).map((flag, i) => (
                    <li key={i} className="flex items-center gap-1">
                      • {flag}
                    </li>
                  ))}
                  {p0Flags.length > 3 && (
                    <li className="text-muted-foreground">
                      +{p0Flags.length - 3} more...
                    </li>
                  )}
                </ul>
                <Button variant="outline" size="sm" asChild className="mt-2">
                  <Link to="/app/business-brain">
                    <Brain className="h-3 w-3 mr-1" />
                    Open Business Brain
                  </Link>
                </Button>
              </div>
            )}
          </div>

          {/* What happens when you go live */}
          <div className="space-y-3">
            <p className="text-sm font-medium">When you go live, your AI will:</p>
            <div className="grid gap-3">
              {features.map((feature, index) => (
                <div key={index} className="flex items-center gap-3 p-3 rounded-lg bg-muted/50">
                  <feature.icon className="h-5 w-5 text-primary" />
                  <span className="text-sm">{feature.text}</span>
                </div>
              ))}
            </div>
          </div>

          {/* Go Live Button */}
          <Button 
            onClick={() => setShowConfirm(true)}
            disabled={!fullyCanActivate || readinessLoading}
            size="lg"
            className="w-full gap-2 h-14 text-lg"
          >
            <Power className="h-5 w-5" />
            {readinessLoading ? "Checking readiness..." : "Go Live Now"}
          </Button>

          {!fullyCanActivate && !readinessLoading && (
            <p className="text-xs text-center text-muted-foreground">
              {!canActivate 
                ? "Complete the phone and testing steps above first"
                : "Complete your Business Brain setup to reach 85% readiness"
              }
            </p>
          )}
        </CardContent>
      </Card>

      {/* Confirmation Dialog */}
      <AlertDialog open={showConfirm} onOpenChange={setShowConfirm}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2">
              <Sparkles className="h-5 w-5 text-primary" />
              Ready to Go Live?
            </AlertDialogTitle>
            <AlertDialogDescription>
              Your AI assistant will start answering calls and booking appointments immediately. 
              You can pause it anytime from your dashboard.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Not Yet</AlertDialogCancel>
            <AlertDialogAction onClick={handleGoLive} disabled={activating} className="gap-2">
              {activating ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <Check className="h-4 w-4" />
              )}
              {activating ? "Activating..." : "Yes, Go Live!"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

import { useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { useBusinessContext, calculateReadinessFromContext } from "@/hooks/useBusinessContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { 
  CheckCircle2, 
  AlertCircle, 
  XCircle,
  Building2,
  Clock,
  Briefcase,
  FileText,
  HelpCircle,
  UtensilsCrossed,
  ChevronRight
} from "lucide-react";

interface StatusItem {
  id: string;
  label: string;
  complete: boolean;
  icon: React.ElementType;
  count?: number;
  target?: number;
}

export function KnowledgeStatusBar() {
  const navigate = useNavigate();
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const caps = useCapabilities();
  const { context, loading } = useBusinessContext(tenant?.id || null);

  const score = calculateReadinessFromContext(context);

  const statusItems = useMemo<StatusItem[]>(() => {
    const items: StatusItem[] = [
      {
        id: 'identity',
        label: 'Identity',
        complete: !!(context?.business.name && context?.business.phone),
        icon: Building2,
      },
      {
        id: 'hours',
        label: 'Hours',
        complete: !!(context?.hours && Object.keys(context.hours).length > 0),
        icon: Clock,
      },
    ];

    // Mode-specific: Menu vs Services
    if (caps.isFoodBusiness) {
      items.push({
        id: 'menu',
        label: 'Menu',
        complete: (context?.services?.length || 0) >= 5,
        icon: UtensilsCrossed,
        count: context?.services?.length || 0,
      });
    } else {
      items.push({
        id: 'services',
        label: 'Services',
        complete: (context?.services?.length || 0) >= 3,
        icon: Briefcase,
        count: context?.services?.length || 0,
      });
    }

    items.push(
      {
        id: 'faqs',
        label: 'FAQs',
        complete: (context?.faqs?.length || 0) >= 3,
        icon: HelpCircle,
        count: context?.faqs?.length || 0,
        target: 3,
      },
      {
        id: 'policies',
        label: 'Policies',
        complete: !!(context?.policies.cancellation || context?.policies.deposit),
        icon: FileText,
      }
    );

    return items;
  }, [context, businessMode]);

  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-emerald-400';
    if (score >= 50) return 'text-amber-400';
    return 'text-rose-400';
  };

  const getScoreBg = (score: number) => {
    if (score >= 80) return 'bg-emerald-500/15';
    if (score >= 50) return 'bg-amber-500/15';
    return 'bg-rose-500/15';
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-4">
          <div className="h-6 bg-muted animate-pulse rounded" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-border/50">
      <CardContent className="p-4">
        <div className="flex flex-col gap-4">
          {/* Top: Score + Progress */}
          <div className="flex items-center gap-4">
            <div className={`flex items-center gap-2 px-3 py-1.5 rounded-lg ${getScoreBg(score)}`}>
              <span className={`text-lg font-bold ${getScoreColor(score)}`}>{score}%</span>
              <span className="text-sm text-muted-foreground">Ready</span>
            </div>
            <div className="flex-1">
              <Progress value={score} className="h-2" />
            </div>
            <Button 
              variant="ghost" 
              size="sm" 
              className="gap-1 text-xs"
              onClick={() => navigate("/app/business-brain")}
            >
              Review
              <ChevronRight className="h-3 w-3" />
            </Button>
          </div>

          {/* Bottom: Status Pills */}
          <div className="flex flex-wrap gap-2">
            {statusItems.map((item) => (
              <div
                key={item.id}
                className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium transition-colors ${
                  item.complete
                    ? 'bg-emerald-500/15 text-emerald-400'
                    : 'bg-muted text-muted-foreground'
                }`}
              >
                {item.complete ? (
                  <CheckCircle2 className="h-3 w-3" />
                ) : (
                  <AlertCircle className="h-3 w-3" />
                )}
                <span>{item.label}</span>
                {item.count !== undefined && (
                  <span className="opacity-70">
                    ({item.count}{item.target ? `/${item.target}` : ''})
                  </span>
                )}
              </div>
            ))}
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { Link } from "react-router-dom";
import { RefreshCw, Clock, TrendingUp, TrendingDown, ArrowRight, DollarSign, Target } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useLeadRecoveryDashboard } from "@/hooks/useLeadRecoveryDashboard";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { useState } from "react";
import { cn } from "@/lib/utils";

// Lead Recovery is most valuable for service/booking and medical businesses
// Dispatch is urgent (if they didn't book now, they called someone else)
// Food can benefit from reservation/catering follow-ups
const RECOVERY_RELEVANT_MODES = ["service", "medical", "food", "general"];

export function LeadRecoveryWidget() {
  const [period, setPeriod] = useState<"month" | "week">("month");
  const { data, isLoading } = useLeadRecoveryDashboard(period);
  const { businessMode } = useTenantConfig();
  const caps = useCapabilities();

  // Don't show for dispatch - their leads are urgent and time-sensitive
  if (caps.isDispatchBusiness) {
    return null;
  }

  if (isLoading) {
    return <LeadRecoveryWidgetSkeleton />;
  }
  // Empty state - recovery not enabled or no campaigns
  if (!data || (!data.isEnabled && data.currentMonth.campaignsStarted === 0)) {
    return (
      <Card className="border-border/50">
        <CardHeader className="pb-2">
          <CardTitle className="text-lg font-semibold">Lead Recovery</CardTitle>
        </CardHeader>
        <CardContent className="text-center py-8">
          <div className="rounded-full bg-muted p-4 mx-auto w-fit mb-4">
            <RefreshCw className="w-8 h-8 text-muted-foreground" />
          </div>
          <h3 className="font-medium text-foreground">Recover More Leads</h3>
          <p className="text-sm text-muted-foreground mt-1 max-w-sm mx-auto">
            Automatically follow up with leads who don't book on their first call.
          </p>
          <Button className="mt-4" asChild>
            <Link to="/app/settings/recovery">
              Enable Lead Recovery
              <ArrowRight className="w-4 h-4 ml-2" />
            </Link>
          </Button>
        </CardContent>
      </Card>
    );
  }

  const leadsChange = data.currentMonth.leadsRecovered - data.previousMonth.leadsRecovered;
  const revenueChange = data.currentMonth.recoveredRevenueCents - data.previousMonth.recoveredRevenueCents;

  return (
    <Card className="border-border/50">
      <CardHeader className="flex flex-row items-center justify-between pb-2">
        <CardTitle className="text-lg font-semibold">Lead Recovery</CardTitle>
        <Select value={period} onValueChange={(v) => setPeriod(v as "month" | "week")}>
          <SelectTrigger className="w-32 h-8 text-sm">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="month">This Month</SelectItem>
            <SelectItem value="week">This Week</SelectItem>
          </SelectContent>
        </Select>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* Top metrics row */}
        <div className="grid grid-cols-3 gap-3">
          <MetricCard
            icon={<RefreshCw className="w-4 h-4" />}
            label="Leads Recovered"
            value={data.currentMonth.leadsRecovered.toString()}
            change={leadsChange}
            changeLabel="vs last"
            colorClass="text-emerald-600 dark:text-emerald-400"
            bgClass="bg-emerald-50 dark:bg-emerald-950/30"
          />
          <MetricCard
            icon={<DollarSign className="w-4 h-4" />}
            label="Revenue Saved"
            value={formatCurrency(data.currentMonth.recoveredRevenueCents)}
            change={revenueChange}
            changeLabel=""
            formatChange={(v) => formatCurrency(Math.abs(v))}
            colorClass="text-emerald-600 dark:text-emerald-400"
            bgClass="bg-emerald-50 dark:bg-emerald-950/30"
          />
          <MetricCard
            icon={<Target className="w-4 h-4" />}
            label="Recovery Rate"
            value={`${data.currentMonth.recoveryRate.toFixed(0)}%`}
            colorClass="text-blue-600 dark:text-blue-400"
            bgClass="bg-blue-50 dark:bg-blue-950/30"
          />
        </div>

        {/* Status bar */}
        <div className="flex items-center gap-3 p-3 bg-muted/50 rounded-lg text-sm">
          <div className="flex items-center gap-2">
            <RefreshCw className="w-4 h-4 text-primary" />
            <span className="text-muted-foreground">
              <span className="font-medium text-foreground">{data.activeCampaigns}</span> in active recovery
            </span>
          </div>
          <span className="text-muted-foreground/50">·</span>
          <div className="flex items-center gap-2">
            <Clock className={cn(
              "w-4 h-4",
              data.awaitingResponse > 0 ? "text-amber-500" : "text-muted-foreground"
            )} />
            <span className="text-muted-foreground">
              <span className={cn(
                "font-medium",
                data.awaitingResponse > 0 ? "text-amber-600 dark:text-amber-400" : "text-foreground"
              )}>
                {data.awaitingResponse}
              </span> awaiting response
            </span>
            {data.awaitingResponse > 0 && (
              <Badge 
                variant="outline" 
                className="bg-amber-50 text-amber-700 border-amber-200 dark:bg-amber-950/50 dark:text-amber-400 dark:border-amber-800 animate-pulse text-xs"
              >
                Needs attention
              </Badge>
            )}
          </div>
        </div>

        {/* Footer links */}
        <div className="flex items-center justify-between pt-2 border-t border-border/50">
          <Button variant="ghost" size="sm" className="text-muted-foreground hover:text-foreground" asChild>
            <Link to="/app/leads/recovery">View Recovery Queue</Link>
          </Button>
          <Button variant="ghost" size="sm" className="text-muted-foreground hover:text-foreground" asChild>
            <Link to="/app/settings/recovery">
              Configure
              <ArrowRight className="w-3 h-3 ml-1" />
            </Link>
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

interface MetricCardProps {
  icon: React.ReactNode;
  label: string;
  value: string;
  change?: number;
  changeLabel?: string;
  formatChange?: (value: number) => string;
  colorClass?: string;
  bgClass?: string;
}

function MetricCard({
  icon,
  label,
  value,
  change,
  changeLabel,
  formatChange,
  colorClass = "text-foreground",
  bgClass = "bg-muted",
}: MetricCardProps) {
  const hasChange = change !== undefined && change !== 0;
  const isPositive = (change || 0) >= 0;

  return (
    <div className={cn("p-3 rounded-lg", bgClass)}>
      <div className={cn("flex items-center gap-1.5 mb-1", colorClass)}>
        {icon}
        <span className="text-xs font-medium uppercase tracking-wider opacity-80">
          {label}
        </span>
      </div>
      <div className={cn("text-2xl font-bold", colorClass)}>{value}</div>
      {hasChange && (
        <div className="flex items-center gap-1 mt-1">
          {isPositive ? (
            <TrendingUp className="w-3 h-3 text-emerald-500" />
          ) : (
            <TrendingDown className="w-3 h-3 text-red-500" />
          )}
          <span className={cn(
            "text-xs font-medium",
            isPositive ? "text-emerald-600 dark:text-emerald-400" : "text-red-600 dark:text-red-400"
          )}>
            {isPositive ? "+" : "-"}
            {formatChange ? formatChange(change) : Math.abs(change)}
          </span>
          {changeLabel && (
            <span className="text-xs text-muted-foreground">{changeLabel}</span>
          )}
        </div>
      )}
    </div>
  );
}

function LeadRecoveryWidgetSkeleton() {
  return (
    <Card className="border-border/50">
      <CardHeader className="flex flex-row items-center justify-between pb-2">
        <Skeleton className="h-6 w-32" />
        <Skeleton className="h-8 w-28" />
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid grid-cols-3 gap-3">
          {[1, 2, 3].map((i) => (
            <div key={i} className="p-3 rounded-lg bg-muted/50">
              <Skeleton className="h-4 w-20 mb-2" />
              <Skeleton className="h-8 w-16" />
            </div>
          ))}
        </div>
        <Skeleton className="h-12 w-full rounded-lg" />
        <div className="flex justify-between pt-2 border-t border-border/50">
          <Skeleton className="h-8 w-32" />
          <Skeleton className="h-8 w-24" />
        </div>
      </CardContent>
    </Card>
  );
}

function formatCurrency(cents: number): string {
  const dollars = cents / 100;
  if (dollars >= 10000) {
    return `$${(dollars / 1000).toFixed(1)}k`;
  }
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(dollars);
}

import { useEffect, useMemo } from "react";
import { useNavigate, Link } from "react-router-dom";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { formatDistanceToNow } from "date-fns";
import {
  Phone,
  Calendar,
  UtensilsCrossed,
  Truck,
  MessageSquare,
  ArrowRight,
  FlaskConical,
  Inbox,
} from "lucide-react";

interface ActivityItem {
  id: string;
  type: "call" | "booking" | "order" | "dispatch" | "sms";
  title: string;
  subtitle: string;
  time: string;
  timestamp: Date;
  status?: "success" | "warning" | "info";
}

export function LiveActivityFeed() {
  const navigate = useNavigate();
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const { terms } = useIndustryContext();

  // Realtime subscription
  useEffect(() => {
    if (!tenant?.id) return;
    const invalidate = () => queryClient.invalidateQueries({ queryKey: ["live-activity-feed", tenant.id] });
    const channel = supabase
      .channel('activity-feed-realtime')
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'ai_call_sessions', filter: `tenant_id=eq.${tenant.id}` }, invalidate)
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'bookings', filter: `tenant_id=eq.${tenant.id}` }, invalidate)
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'food_orders', filter: `tenant_id=eq.${tenant.id}` }, invalidate)
      .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'dispatch_jobs', filter: `tenant_id=eq.${tenant.id}` }, invalidate)
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [tenant?.id, queryClient]);

  const { data: activities, isLoading } = useQuery({
    queryKey: ["live-activity-feed", tenant?.id],
    queryFn: async (): Promise<ActivityItem[]> => {
      if (!tenant?.id) return [];
      const results: ActivityItem[] = [];

      const { data: calls } = await supabase
        .from("ai_call_sessions")
        .select("id, caller_phone, outcome, started_at, summary")
        .eq("tenant_id", tenant.id)
        .order("started_at", { ascending: false })
        .limit(5);

      calls?.forEach((call) => {
        const phone = call.caller_phone || "Unknown";
        const displayPhone = phone.length > 8 ? `${phone.slice(0, 3)}...${phone.slice(-4)}` : phone;
        results.push({
          id: `call-${call.id}`,
          type: "call",
          title: `Call ${call.outcome === 'booked' ? 'converted' : 'answered'}`,
          subtitle: call.summary?.slice(0, 50) || `From: ${displayPhone}`,
          time: formatDistanceToNow(new Date(call.started_at), { addSuffix: true }),
          timestamp: new Date(call.started_at),
          status: call.outcome === 'booked' ? 'success' : 'info',
        });
      });

      const { data: bookings } = await supabase
        .from("bookings")
        .select("id, status, created_at, leads(full_name)")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false })
        .limit(4);

      bookings?.forEach((booking) => {
        const leadName = (booking.leads as any)?.full_name || terms.customer;
        const statusLabel = booking.status === 'confirmed' ? terms.bookingConfirmed : terms.bookingCreated;
        results.push({
          id: `booking-${booking.id}`,
          type: "booking",
          title: statusLabel,
          subtitle: leadName,
          time: formatDistanceToNow(new Date(booking.created_at), { addSuffix: true }),
          timestamp: new Date(booking.created_at),
          status: booking.status === 'confirmed' ? 'success' : 'info',
        });
      });

      const { data: orders } = await supabase
        .from("food_orders")
        .select("id, order_number, status, order_type, customer_name, created_at")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false })
        .limit(4);

      orders?.forEach((order) => {
        results.push({
          id: `order-${order.id}`,
          type: "order",
          title: `Order #${order.order_number}`,
          subtitle: `${order.customer_name || "Customer"} · ${order.order_type?.replace("_", " ")}`,
          time: formatDistanceToNow(new Date(order.created_at), { addSuffix: true }),
          timestamp: new Date(order.created_at),
          status: order.status === 'completed' ? 'success' : 'info',
        });
      });

      const { data: jobs } = await supabase
        .from("dispatch_jobs")
        .select("id, status, customer_name, job_type, created_at")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false })
        .limit(3);

      jobs?.forEach((job) => {
        results.push({
          id: `dispatch-${job.id}`,
          type: "dispatch",
          title: `${job.job_type || 'Job'} ${job.status}`,
          subtitle: job.customer_name || "Customer",
          time: formatDistanceToNow(new Date(job.created_at), { addSuffix: true }),
          timestamp: new Date(job.created_at),
          status: job.status === 'completed' ? 'success' : 'info',
        });
      });

      return results.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime()).slice(0, 10);
    },
    enabled: !!tenant?.id,
    refetchInterval: 30000,
  });

  const iconMap: Record<string, React.ElementType> = useMemo(() => ({
    call: Phone,
    booking: Calendar,
    order: UtensilsCrossed,
    dispatch: Truck,
    sms: MessageSquare,
  }), []);

  const colorMap: Record<string, string> = useMemo(() => ({
    call: "bg-success/10 text-success",
    booking: "bg-info/10 text-info",
    order: "bg-warning/10 text-warning",
    dispatch: "bg-primary/10 text-primary",
    sms: "bg-accent/10 text-accent-foreground",
  }), []);

  const getNavPath = (type: string) => {
    switch (type) {
      case "call": return "/app/inbox?tab=calls";
      case "booking": return "/app/bookings";
      case "order": return "/app/orders";
      case "dispatch": return "/app/dispatch";
      default: return "/app/inbox";
    }
  };

  const hasActivity = activities && activities.length > 0;

  if (isLoading) {
    return (
      <Card>
        <CardHeader className="pb-3">
          <Skeleton className="h-4 w-32" />
        </CardHeader>
        <CardContent className="space-y-4">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="flex items-center gap-3">
              <Skeleton className="h-8 w-8 rounded-lg" />
              <div className="flex-1">
                <Skeleton className="h-4 w-32 mb-1.5" />
                <Skeleton className="h-3 w-48" />
              </div>
            </div>
          ))}
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="border-border/30 bg-card/60 backdrop-blur-sm">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <h3 className="text-sm font-semibold text-foreground">Recent Activity</h3>
          <Button
            variant="ghost"
            size="sm"
            className="gap-1 text-xs h-7 text-muted-foreground hover:text-foreground"
            onClick={() => navigate("/app/inbox")}
          >
            View All
            <ArrowRight className="h-3 w-3" />
          </Button>
        </div>
      </CardHeader>

      <CardContent className="pt-0">
        {hasActivity ? (
          <div className="space-y-1">
            {activities.slice(0, 8).map((item) => {
              const Icon = iconMap[item.type] || Phone;
              const colorClass = colorMap[item.type] || "bg-muted text-muted-foreground";
              return (
                <div
                  key={item.id}
                  className={cn(
                    "flex items-start gap-3 p-2.5 -mx-2.5 rounded-lg cursor-pointer hover:bg-card/90 hover:shadow-sm transition-all",
                    item.type === "call" && "border-l-2 border-success",
                    item.type === "booking" && "border-l-2 border-primary",
                    item.type === "order" && "border-l-2 border-warning",
                    item.type === "dispatch" && "border-l-2 border-primary",
                    item.type === "sms" && "border-l-2 border-muted-foreground/30",
                  )}
                  onClick={() => navigate(getNavPath(item.type))}
                >
                  <div className={cn(
                    "h-8 w-8 rounded-lg flex items-center justify-center shrink-0 mt-0.5",
                    colorClass
                  )}>
                    <Icon className="h-3.5 w-3.5" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium leading-tight truncate">{item.title}</p>
                    <p className="text-[13px] text-muted-foreground truncate">{item.subtitle}</p>
                  </div>
                  <p className="text-[11px] text-muted-foreground/60 shrink-0 mt-0.5">{item.time}</p>
                </div>
              );
            })}
          </div>
        ) : (
          <div className="flex flex-col items-center justify-center py-10 text-center">
            <div className="rounded-2xl bg-muted/60 p-4 mb-4 glow-primary-subtle">
              <Inbox className="w-7 h-7 text-muted-foreground/60" />
            </div>
            <p className="text-sm font-medium mb-1">No activity yet</p>
            <p className="text-xs text-muted-foreground max-w-[220px] mb-4">
              When your AI handles calls, activity will appear here.
            </p>
            <Button size="sm" variant="outline" asChild>
              <Link to="/app/simulator" className="gap-1.5">
                <FlaskConical className="h-3.5 w-3.5" />
                Test Your AI
              </Link>
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import {
  Phone, Calendar, Users, UtensilsCrossed, Truck, Stethoscope,
} from "lucide-react";
import { startOfDay, startOfWeek, endOfDay } from "date-fns";
import { AnimatedNumber } from "@/components/ui/animated-number";

interface Metric {
  label: string;
  value: number | string;
  icon: React.ElementType;
  href: string;
}

export function MetricsGrid() {
  const navigate = useNavigate();
  const { tenant, assistantSettings } = useAuth();
  const { businessMode } = useTenantConfig();
  const caps = useCapabilities();
  const { terms } = useIndustryContext();
  const isCallbackOnly = businessMode === "service" &&
    (assistantSettings as Record<string, unknown> | null)?.ai_booking_mode === "callback_only";

  const todayStart = startOfDay(new Date()).toISOString();
  const todayEnd = endOfDay(new Date()).toISOString();
  const weekStart = startOfWeek(new Date()).toISOString();

  const { data: callsToday = 0 } = useQuery({
    queryKey: ["metrics-calls", tenant?.id, todayStart],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("ai_call_sessions")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .gte("started_at", todayStart)
        .lte("started_at", todayEnd);
      return count || 0;
    },
    enabled: !!tenant?.id,
  });

  const { data: bookingsWeek = 0 } = useQuery({
    queryKey: ["metrics-bookings", tenant?.id, weekStart],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("bookings")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .gte("created_at", weekStart);
      return count || 0;
    },
    enabled: !!tenant?.id,
  });

  const { data: totalCustomers = 0 } = useQuery({
    queryKey: ["metrics-customers", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("customers")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id);
      return count || 0;
    },
    enabled: !!tenant?.id,
  });

  const { data: ordersToday = 0 } = useQuery({
    queryKey: ["metrics-orders", tenant?.id, todayStart],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("food_orders")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .gte("created_at", todayStart);
      return count || 0;
    },
    enabled: !!tenant?.id && caps.hasFoodOrders,
  });

  const { data: jobsPending = 0 } = useQuery({
    queryKey: ["metrics-dispatch", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("dispatch_jobs")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .in("status", ["pending", "assigned"]);
      return count || 0;
    },
    enabled: !!tenant?.id && caps.hasDispatchQueue,
  });

  const { data: intakesToday = 0 } = useQuery({
    queryKey: ["metrics-intakes", tenant?.id, todayStart],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("medical_intakes")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .gte("created_at", todayStart);
      return count || 0;
    },
    enabled: !!tenant?.id && caps.hasMedicalIntake,
  });

  const { data: newLeadsCount = 0 } = useQuery({
    queryKey: ["metrics-new-leads", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("leads")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .eq("status", "new");
      return count || 0;
    },
    enabled: !!tenant?.id && isCallbackOnly,
  });

  const getMetrics = (): Metric[] => {
    const base: Metric[] = [
      { label: "Calls Today", value: callsToday, icon: Phone, href: "/app/inbox?tab=calls" },
    ];

    switch (businessMode) {
      case "food":
        return [
          { label: "Orders Today", value: ordersToday, icon: UtensilsCrossed, href: "/app/orders" },
          ...base,
          { label: "Customers", value: totalCustomers, icon: Users, href: "/app/customers" },
        ];
      case "dispatch":
        return [
          { label: "Active Jobs", value: jobsPending, icon: Truck, href: "/app/dispatch" },
          ...base,
          { label: "Customers", value: totalCustomers, icon: Users, href: "/app/customers" },
        ];
      case "medical":
        return [
          { label: "Intakes Today", value: intakesToday, icon: Stethoscope, href: "/app/medical-intake" },
          { label: terms.bookingsMetricLabel, value: bookingsWeek, icon: Calendar, href: "/app/bookings" },
          ...base,
        ];
      default:
        if (isCallbackOnly) {
          return [
            ...base,
            { label: "New Leads", value: newLeadsCount, icon: Users, href: "/app/inbox?tab=leads" },
            { label: "Customers", value: totalCustomers, icon: Users, href: "/app/customers" },
          ];
        }
        return [
          ...base,
          { label: terms.bookingsMetricLabel, value: bookingsWeek, icon: Calendar, href: "/app/bookings" },
          { label: "Customers", value: totalCustomers, icon: Users, href: "/app/customers" },
        ];
    }
  };

  const metrics = getMetrics();

  return (
    <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
      {metrics.slice(0, 3).map((metric) => {
        const Icon = metric.icon;
        return (
          <button
            key={metric.label}
            className="text-left p-5 rounded-xl bg-card/60 backdrop-blur-sm border border-border/30 card-interactive cursor-pointer group"
            onClick={() => navigate(metric.href)}
          >
            <div className="flex items-center gap-2 mb-3">
              <div className="flex h-8 w-8 items-center justify-center rounded-lg bg-primary/10 border border-primary/10 group-hover:bg-primary/15 group-hover:shadow-[0_0_16px_-4px_hsl(230_70%_62%/0.2)] transition-all">
                <Icon className="h-4 w-4 text-primary" />
              </div>
              <p className="text-[13px] font-medium text-muted-foreground/80">
                {metric.label}
              </p>
            </div>
            <p className="text-[36px] font-bold tracking-tight tabular-nums text-foreground leading-none">
              {typeof metric.value === "number" ? (
                <AnimatedNumber value={metric.value} />
              ) : (
                metric.value
              )}
            </p>
          </button>
        );
      })}
    </div>
  );
}

import { useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { useKnowledgeSuggestions } from "@/hooks/useKnowledgeSuggestions";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { 
  AlertCircle, 
  ChefHat, 
  Brain, 
  Calendar,
  ArrowRight,
} from "lucide-react";

interface AttentionItem {
  count: number;
  label: string;
  icon: React.ElementType;
  href: string;
  priority: number;
}

export function NeedsAttentionBanner() {
  const navigate = useNavigate();
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const caps = useCapabilities();
  const { terms } = useIndustryContext();
  const { pendingCount: knowledgeGaps } = useKnowledgeSuggestions();

  // Fetch pending orders (food mode)
  const { data: pendingOrders = 0 } = useQuery({
    queryKey: ["attention-pending-orders", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("food_orders")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .eq("status", "pending");
      return count || 0;
    },
    enabled: !!tenant?.id && caps.hasFoodOrders,
  });

  // Fetch pending bookings (pending or pending_deposit status)
  const { data: pendingBookings = 0 } = useQuery({
    queryKey: ["attention-pending-bookings", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("bookings")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .in("status", ["pending", "pending_deposit"]);
      return count || 0;
    },
    enabled: !!tenant?.id,
  });

  // Build attention items
  const items: AttentionItem[] = [];

  if (pendingOrders > 0) {
    items.push({
      count: pendingOrders,
      label: pendingOrders === 1 ? "new order" : "new orders",
      icon: ChefHat,
      href: "/app/orders",
      priority: 1,
    });
  }

  if (pendingBookings > 0) {
    items.push({
      count: pendingBookings,
      label: pendingBookings === 1 ? terms.pendingBooking : terms.pendingBookings,
      icon: Calendar,
      href: "/app/bookings",
      priority: 2,
    });
  }

  if (knowledgeGaps > 0) {
    items.push({
      count: knowledgeGaps,
      label: knowledgeGaps === 1 ? "knowledge gap" : "knowledge gaps",
      icon: Brain,
      href: "/app/business-brain",
      priority: 3,
    });
  }

  // Sort by priority
  items.sort((a, b) => a.priority - b.priority);

  // Nothing needs attention
  if (items.length === 0) return null;

  // Get highest priority item for main action
  const primaryItem = items[0];

  return (
    <div className="flex flex-col sm:flex-row sm:items-center gap-3 p-4 rounded-xl bg-warning/[0.06] backdrop-blur-sm border border-warning/20 animate-fade-in card-interactive">
      <div className="flex items-center gap-3 flex-1 min-w-0">
        <div className="h-10 w-10 rounded-xl bg-warning/15 border border-warning/20 flex items-center justify-center shrink-0 shadow-[0_0_16px_-4px_hsl(38_90%_50%/0.25)]">
          <AlertCircle className="h-4 w-4 text-warning" />
        </div>
        <div className="min-w-0">
          <p className="text-sm font-semibold tracking-tight text-warning">Needs Your Attention</p>
          <p className="text-xs text-warning/70 truncate">
            {items.map((item, i) => (
              <span key={item.href}>
                {item.count} {item.label}
                {i < items.length - 1 && " · "}
              </span>
            ))}
          </p>
        </div>
      </div>
      <Button 
        size="sm"
        className="bg-warning hover:bg-warning/90 text-warning-foreground shrink-0 h-9 text-xs font-semibold shadow-sm"
        onClick={() => navigate(primaryItem.href)}
      >
        Review
        <ArrowRight className="h-3 w-3 ml-1" />
      </Button>
    </div>
  );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  CheckCircle2,
  Calendar,
  ShoppingBag,
  Truck,
  UserPlus,
  ArrowRight,
  Link2,
  Sparkles,
} from "lucide-react";
import { useNavigate } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useCapabilities } from "@/hooks/useCapabilities";
import { formatDistanceToNow } from "date-fns";

interface RecentOutcome {
  id: string;
  type: "booking" | "order" | "dispatch" | "lead";
  title: string;
  subtitle: string;
  time: string;
  synced: boolean;
}

export function NextStepsPanel() {
  const navigate = useNavigate();
  const { tenant } = useAuth();
  const caps = useCapabilities();
  const businessMode = tenant?.business_mode || "service";

  const { data: recentOutcomes, isLoading } = useQuery({
    queryKey: ["recent-outcomes", tenant?.id],
    queryFn: async (): Promise<RecentOutcome[]> => {
      if (!tenant?.id) return [];

      const outcomes: RecentOutcome[] = [];

      // Fetch recent bookings
      if (caps.hasBooking) {
        const { data: bookings } = await supabase
          .from("bookings")
          .select("id, status, start_at, created_at, leads(full_name)")
          .eq("tenant_id", tenant.id)
          .order("created_at", { ascending: false })
          .limit(3);

        bookings?.forEach((b) => {
          outcomes.push({
            id: b.id,
            type: "booking",
            title: (b.leads as any)?.full_name || "New Booking",
            subtitle: `Scheduled for ${new Date(b.start_at).toLocaleDateString()}`,
            time: formatDistanceToNow(new Date(b.created_at), { addSuffix: true }),
            synced: false, // Would check routing_rules status
          });
        });
      }

      // Fetch recent orders (food mode)
      if (caps.hasFoodOrders) {
        // Orders table may not exist in all schemas, wrap in try-catch
        try {
          const { data: orders } = await supabase
            .from("dispatch_jobs")
            .select("id, status, customer_name, price_cents, created_at")
            .eq("tenant_id", tenant.id)
            .order("created_at", { ascending: false })
            .limit(3);

          orders?.forEach((o: any) => {
            outcomes.push({
              id: o.id,
              type: "order",
              title: o.customer_name || "New Order",
              subtitle: `$${((o.price_cents || 0) / 100).toFixed(2)} - ${o.status}`,
              time: formatDistanceToNow(new Date(o.created_at), { addSuffix: true }),
              synced: false,
            });
          });
        } catch {
          // Orders table doesn't exist yet
        }
      }

      // Fetch recent dispatch jobs
      if (caps.hasDispatchQueue) {
        const { data: jobs } = await supabase
          .from("dispatch_jobs")
          .select("id, status, customer_name, job_type, created_at")
          .eq("tenant_id", tenant.id)
          .order("created_at", { ascending: false })
          .limit(3);

        jobs?.forEach((j) => {
          outcomes.push({
            id: j.id,
            type: "dispatch",
            title: j.customer_name || "New Job",
            subtitle: j.job_type || j.status,
            time: formatDistanceToNow(new Date(j.created_at), { addSuffix: true }),
            synced: false,
          });
        });
      }

      // Sort by most recent
      return outcomes.slice(0, 4);
    },
    enabled: !!tenant?.id,
    refetchInterval: 30000,
  });

  const { data: hasIntegrations } = useQuery({
    queryKey: ["has-integrations", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return false;
      const { count } = await supabase
        .from("integrations")
        .select("id", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .eq("status", "connected");
      return (count || 0) > 0;
    },
    enabled: !!tenant?.id,
  });

  const getIcon = (type: string) => {
    switch (type) {
      case "booking":
        return <Calendar className="h-4 w-4 text-blue-500" />;
      case "order":
        return <ShoppingBag className="h-4 w-4 text-orange-500" />;
      case "dispatch":
        return <Truck className="h-4 w-4 text-emerald-500" />;
      case "lead":
        return <UserPlus className="h-4 w-4 text-purple-500" />;
      default:
        return <CheckCircle2 className="h-4 w-4 text-muted-foreground" />;
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-base font-medium">What's Happening</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {[1, 2, 3].map((i) => (
              <Skeleton key={i} className="h-14 w-full" />
            ))}
          </div>
        </CardContent>
      </Card>
    );
  }

  const hasOutcomes = recentOutcomes && recentOutcomes.length > 0;

  return (
    <Card>
      <CardHeader className="pb-2">
        <CardTitle className="text-base font-medium flex items-center gap-2">
          <Sparkles className="h-4 w-4 text-primary" />
          What's Happening
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        {hasOutcomes ? (
          <>
            <div className="space-y-2">
              {recentOutcomes.map((outcome) => (
                <div
                  key={outcome.id}
                  className="flex items-center justify-between py-2 px-2 -mx-2 rounded-lg hover:bg-muted/50 transition-colors"
                >
                  <div className="flex items-center gap-3">
                    <div className="p-1.5 rounded-lg bg-muted">
                      {getIcon(outcome.type)}
                    </div>
                    <div>
                      <p className="text-sm font-medium">{outcome.title}</p>
                      <p className="text-xs text-muted-foreground">{outcome.subtitle}</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-muted-foreground">{outcome.time}</p>
                    {outcome.synced && (
                      <Badge variant="secondary" className="text-xs">
                        <CheckCircle2 className="h-2.5 w-2.5 mr-1" />
                        Synced
                      </Badge>
                    )}
                  </div>
                </div>
              ))}
            </div>

            {/* Integration prompt - only if no integrations connected */}
            {!hasIntegrations && (
              <div className="pt-2 border-t">
                <Button
                  variant="ghost"
                  size="sm"
                  className="w-full justify-between text-muted-foreground hover:text-foreground"
                  onClick={() => navigate("/app/integrations")}
                >
                  <span className="flex items-center gap-2">
                    <Link2 className="h-4 w-4" />
                    Sync to Google Calendar, Sheets & more
                  </span>
                  <ArrowRight className="h-4 w-4" />
                </Button>
              </div>
            )}
          </>
        ) : (
          <div className="text-center py-4">
            <p className="text-sm text-muted-foreground mb-3">
              No recent activity yet. When AI handles calls, outcomes will appear here.
            </p>
            <Button
              variant="outline"
              size="sm"
              onClick={() => navigate("/app/simulator")}
            >
              Test your AI
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useState, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Badge } from "@/components/ui/badge";
import { Phone, Check, Loader2, Smartphone, ArrowRight, CheckCircle2, Clock, PhoneCall } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { CarrierInstructions } from "./CarrierInstructions";
import { ElevenLabsInitWebhookCard } from "./ElevenLabsInitWebhookCard";

interface PhoneConnectionStepProps {
  onComplete: () => void;
  isComplete: boolean;
}

// Format E.164 number to friendly display
function formatPhoneNumber(phone: string): string {
  const cleaned = phone.replace(/\D/g, "");
  if (cleaned.length === 11 && cleaned.startsWith("1")) {
    const areaCode = cleaned.substring(1, 4);
    const prefix = cleaned.substring(4, 7);
    const line = cleaned.substring(7, 11);
    return `(${areaCode}) ${prefix}-${line}`;
  }
  return phone;
}

export function PhoneConnectionStep({ onComplete, isComplete }: PhoneConnectionStepProps) {
  const { tenant, assistantSettings, refreshTenant } = useAuth();
  const { toast } = useToast();
  
  const [phoneMethod, setPhoneMethod] = useState<"closeloop_number" | "forwarded">("forwarded");
  const [businessPhone, setBusinessPhone] = useState(assistantSettings?.business_phone_number || "");
  const [connecting, setConnecting] = useState(false);
  const [provisioning, setProvisioning] = useState(false);
  
  // Get the real Twilio number if provisioned
  const closeloopNumber = useMemo(() => {
    // Priority: forwarding_phone_e164 > closeloop_number > placeholder
    const phoneNumber = assistantSettings?.forwarding_phone_e164 || assistantSettings?.closeloop_number;
    if (phoneNumber) {
      return phoneNumber;
    }
    return null;
  }, [assistantSettings]);

  // Get connection status
  const connectStatus = assistantSettings?.connect_status || "not_connected";

  const saveSettings = async (updates: Record<string, unknown>) => {
    if (!tenant) throw new Error("No tenant");

    // Check if settings exist first
    const { data: existing } = await supabase
      .from("assistant_settings")
      .select("tenant_id")
      .eq("tenant_id", tenant.id)
      .maybeSingle();

    if (existing) {
      // UPDATE existing row
      const { error } = await supabase
        .from("assistant_settings")
        .update({
          ...updates,
          updated_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant.id);
      if (error) throw error;
    } else {
      // INSERT new row
      const { error } = await supabase
        .from("assistant_settings")
        .insert({
          tenant_id: tenant.id,
          ...updates,
          updated_at: new Date().toISOString(),
        });
      if (error) throw error;
    }
  };

  const handleConnectExisting = async () => {
    if (!tenant || !businessPhone.trim()) {
      toast({
        variant: "destructive",
        title: "Enter phone number",
        description: "Please enter your business phone number",
      });
      return;
    }

    setConnecting(true);
    try {
      await saveSettings({
        business_phone_number: businessPhone.trim(),
        phone_connected: true,
        phone_method: "forwarded",
        closeloop_number: closeloopNumber,
        setup_step_phone: true,
      });

      // Also sync to tenants.phone_public
      await supabase
        .from("tenants")
        .update({ phone_public: businessPhone.trim() })
        .eq("id", tenant.id);

      await refreshTenant();
      toast({
        title: "Phone Connected! ✅",
        description: "Now set up call forwarding using the instructions below.",
      });
      onComplete();
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Connection Failed",
        description: error.message,
      });
    } finally {
      setConnecting(false);
    }
  };

  const handleProvisionNew = async () => {
    if (!tenant) return;

    setProvisioning(true);
    try {
      // Call the Twilio provisioning edge function
      const { data, error } = await supabase.functions.invoke("provision-twilio-number", {
        body: { 
          tenant_id: tenant.id,
          number_type: "local"
        },
      });

      if (error) throw error;
      if (!data?.success) {
        throw new Error(data?.error || "Failed to provision number");
      }

      await refreshTenant();
      toast({
        title: "New Number Provisioned! 🎉",
        description: `Your new CloseLoop number is ${data.friendly_name || data.phone_number}`,
      });
      onComplete();
    } catch (error: any) {
      console.error("Provisioning error:", error);
      toast({
        variant: "destructive",
        title: "Provisioning Failed",
        description: error.message || "Failed to provision phone number",
      });
    } finally {
      setProvisioning(false);
    }
  };

  if (isComplete && closeloopNumber) {
    const isVerified = connectStatus === "forwarding_verified";
    const displayNumber = formatPhoneNumber(closeloopNumber);
    
    return (
      <Card className="border-primary/20 bg-primary/5">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-primary">
            <Check className="h-5 w-5" />
            Phone Connected
          </CardTitle>
          <CardDescription className="space-y-2">
            <div className="flex items-center gap-2">
              <span className="font-medium text-foreground text-lg">{displayNumber}</span>
              {isVerified ? (
                <Badge variant="default" className="gap-1">
                  <CheckCircle2 className="h-3 w-3" />
                  Verified
                </Badge>
              ) : (
                <Badge variant="secondary" className="gap-1">
                  <Clock className="h-3 w-3" />
                  Awaiting First Call
                </Badge>
              )}
            </div>
            <p className="text-sm">
              {assistantSettings?.phone_method === "closeloop_number" 
                ? "This is your dedicated CloseLoop number. Share it with customers!"
                : "Forward your business calls to this number."
              }
            </p>
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {assistantSettings?.phone_method === "forwarded" && (
            <CarrierInstructions forwardingNumber={closeloopNumber} />
          )}
          
          {/* Connection status indicator */}
          <div className="rounded-lg border p-4 bg-background">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className={`h-3 w-3 rounded-full ${isVerified ? "bg-green-500" : "bg-yellow-500 animate-pulse"}`} />
                <div>
                  <p className="font-medium">
                    {isVerified ? "AI Voice Agent Active" : "Waiting for first call..."}
                  </p>
                  <p className="text-xs text-muted-foreground">
                    {isVerified 
                      ? "Your AI is answering calls on this number" 
                      : "Make a test call to verify the connection"
                    }
                  </p>
                </div>
              </div>
              {!isVerified && (
                <Button variant="outline" size="sm" className="gap-2" asChild>
                  <a href={`tel:${closeloopNumber}`}>
                    <PhoneCall className="h-4 w-4" />
                    Test Call
                  </a>
                </Button>
              )}
            </div>
          </div>
          
          {/* ElevenLabs Init Webhook Card */}
          <ElevenLabsInitWebhookCard />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Phone className="h-5 w-5 text-primary" />
          Connect Your Business Phone
        </CardTitle>
        <CardDescription>
          Choose how you want your AI to receive calls
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <RadioGroup 
          value={phoneMethod} 
          onValueChange={(v) => setPhoneMethod(v as "closeloop_number" | "forwarded")}
          className="space-y-4"
        >
          {/* Option 1: Get new AI number */}
          <div 
            onClick={() => setPhoneMethod("closeloop_number")}
            className={`flex items-start space-x-4 p-4 rounded-lg border-2 transition-colors cursor-pointer ${
              phoneMethod === "closeloop_number" 
                ? "border-primary bg-primary/5" 
                : "border-muted hover:border-primary/50"
            }`}
          >
            <RadioGroupItem value="closeloop_number" id="new-number" className="mt-1" />
            <div className="flex-1">
              <Label htmlFor="new-number" className="font-medium cursor-pointer flex items-center gap-2">
                Get a New AI Number
                <Badge variant="secondary" className="text-xs">Recommended</Badge>
              </Label>
              <p className="text-sm text-muted-foreground mt-1">
                We'll assign you a dedicated phone number. Give this to customers or add it to your website.
              </p>
            </div>
          </div>

          {/* Option 2: Keep existing number */}
          <div 
            onClick={() => setPhoneMethod("forwarded")}
            className={`flex items-start space-x-4 p-4 rounded-lg border-2 transition-colors cursor-pointer ${
              phoneMethod === "forwarded" 
                ? "border-primary bg-primary/5" 
                : "border-muted hover:border-primary/50"
            }`}
          >
            <RadioGroupItem value="forwarded" id="existing-number" className="mt-1" />
            <div className="flex-1">
              <Label htmlFor="existing-number" className="font-medium cursor-pointer flex items-center gap-2">
                <Smartphone className="h-4 w-4" />
                Keep My Current Number
              </Label>
              <p className="text-sm text-muted-foreground mt-1">
                We'll give you an AI number behind the scenes. Forward your calls there when you can't answer.
              </p>
            </div>
          </div>
        </RadioGroup>
        
        {/* Clarifying note */}
        <p className="text-xs text-muted-foreground bg-muted/50 p-3 rounded-lg">
          Both options give you an AI-powered number. The difference is whether customers call it directly or you forward calls to it.
        </p>

        {/* Conditional content based on selection */}
        {phoneMethod === "closeloop_number" ? (
          <div className="space-y-4 pt-4 border-t">
            <div className="text-center py-6">
              <div className="inline-flex items-center justify-center h-16 w-16 rounded-full bg-primary/10 mb-4">
                <Phone className="h-8 w-8 text-primary" />
              </div>
              <p className="text-sm text-muted-foreground mb-4">
                Click below to get your dedicated AI phone number instantly
              </p>
              <Button 
                onClick={handleProvisionNew} 
                disabled={provisioning}
                size="lg"
                className="gap-2"
              >
                {provisioning ? (
                  <Loader2 className="h-5 w-5 animate-spin" />
                ) : (
                  <Phone className="h-5 w-5" />
                )}
                {provisioning ? "Provisioning..." : "Get My Number"}
              </Button>
            </div>
          </div>
        ) : (
          <div className="space-y-4 pt-4 border-t">
            <div className="space-y-2">
              <Label htmlFor="business-phone">Your Business Phone Number</Label>
              <Input
                id="business-phone"
                type="tel"
                placeholder="+1 (555) 123-4567"
                value={businessPhone}
                onChange={(e) => setBusinessPhone(e.target.value)}
              />
              <p className="text-xs text-muted-foreground">
                This is the number you currently use for your business
              </p>
            </div>

            <Button 
              onClick={handleConnectExisting} 
              disabled={connecting || !businessPhone.trim()}
              className="w-full gap-2"
            >
              {connecting ? (
                <Loader2 className="h-4 w-4 animate-spin" />
              ) : (
                <ArrowRight className="h-4 w-4" />
              )}
              {connecting ? "Connecting..." : "Connect & Show Forwarding Steps"}
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useNavigate } from "react-router-dom";
import { cn } from "@/lib/utils";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { 
  Calendar, 
  FlaskConical, 
  Plus, 
  Bot,
  UtensilsCrossed,
  Truck,
  Clock,
  Zap,
} from "lucide-react";

interface QuickAction {
  label: string;
  icon: React.ElementType;
  href: string;
  variant?: "default" | "outline" | "secondary";
}

export function QuickActionsCard() {
  const navigate = useNavigate();
  const { businessMode, enabledModules } = useTenantConfig();
  const caps = useCapabilities();
  const { terms } = useIndustryContext();

  const getActions = (): QuickAction[] => {
    const actions: QuickAction[] = [];

    // Capability-based primary actions
    if (caps.hasFoodOrders) {
      actions.push({ label: terms.viewBookings, icon: UtensilsCrossed, href: "/app/orders" });
    }
    if (caps.hasReservations) {
      actions.push({ label: "Reservations", icon: Clock, href: "/app/reservations" });
    }
    if (caps.hasDispatchQueue && !caps.hasFoodOrders) {
      actions.push({ label: terms.viewBookings, icon: Truck, href: "/app/dispatch" });
    }
    if (caps.hasBooking && !caps.hasFoodOrders && !caps.hasDispatchQueue) {
      actions.push({ label: terms.viewBookings, icon: Calendar, href: "/app/bookings" });
    }

    // Common actions
    actions.push({ label: "Test AI", icon: FlaskConical, href: "/app/simulator", variant: "outline" });
    actions.push({ label: "Add Knowledge", icon: Bot, href: "/app/business-brain", variant: "outline" });

    return actions.slice(0, 4);
  };

  const actions = getActions();

  return (
    <Card className="animate-fade-in">
      <CardHeader className="pb-3 pt-4 px-4">
        <CardTitle className="text-sm font-medium flex items-center gap-2">
          <div className="h-6 w-6 rounded-md bg-primary/10 flex items-center justify-center">
            <Zap className="h-3.5 w-3.5 text-primary" />
          </div>
          Quick Actions
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-1.5 px-4 pb-4">
        {actions.map((action, index) => {
          const Icon = action.icon;
          return (
            <Button
              key={action.label}
              variant={action.variant || "secondary"}
              className={cn(
                "w-full justify-start gap-2.5 h-9 text-sm font-normal hover:translate-x-0.5 transition-all",
                action.variant === "outline" && "text-muted-foreground hover:text-foreground"
              )}
              onClick={() => navigate(action.href)}
            >
              <Icon className="h-4 w-4 opacity-70" />
              {action.label}
            </Button>
          );
        })}
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQueryClient } from "@tanstack/react-query";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { FileText, Loader2 } from "lucide-react";

interface QuickAddPolicyDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const POLICY_TYPES = [
  { value: "cancellation", label: "Cancellation Policy" },
  { value: "refund", label: "Refund Policy" },
  { value: "deposit", label: "Deposit Policy" },
  { value: "late", label: "Late Arrival Policy" },
  { value: "reschedule", label: "Rescheduling Policy" },
  { value: "other", label: "Other Policy" },
];

export function QuickAddPolicyDialog({ open, onOpenChange }: QuickAddPolicyDialogProps) {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [policyType, setPolicyType] = useState("cancellation");
  const [content, setContent] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!tenant?.id || !content.trim()) return;

    setIsSubmitting(true);

    try {
      const policyLabel = POLICY_TYPES.find(p => p.value === policyType)?.label || "Policy";
      
      // Map policy type to the correct tenant column
      // Core policies go directly to tenants table for AI context builder
      const policyColumnMap: Record<string, string> = {
        cancellation: "cancellation_policy",
        refund: "refund_policy",
        deposit: "deposit_policy",
      };
      
      const tenantColumn = policyColumnMap[policyType];
      
      if (tenantColumn) {
        // Update the tenant's policy column directly (this is what AI reads)
        const { error } = await supabase
          .from("tenants")
          .update({ [tenantColumn]: content.trim() })
          .eq("id", tenant.id);

        if (error) throw error;
      } else {
        // For other policy types, store in ai_knowledge_base as supplementary knowledge
        const { error } = await supabase.from("ai_knowledge_base").insert({
          tenant_id: tenant.id,
          type: "policy",
          title: policyLabel,
          content: content.trim(),
          priority_weight: 10,
        });

        if (error) throw error;
      }

      toast({
        title: "Policy added!",
        description: `Your AI now knows your ${policyLabel.toLowerCase()}.`,
      });

      // Reset and close
      setPolicyType("cancellation");
      setContent("");
      onOpenChange(false);

      // Invalidate queries
      queryClient.invalidateQueries({ queryKey: ["business-context"] });
      queryClient.invalidateQueries({ queryKey: ["knowledge-base"] });
      queryClient.invalidateQueries({ queryKey: ["tenant"] });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Failed to add policy",
        description: error.message,
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileText className="h-5 w-5 text-primary" />
            Add Policy
          </DialogTitle>
          <DialogDescription>
            Add a business policy. Your AI will reference this when customers ask about your policies.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="space-y-2">
            <Label htmlFor="policy-type">Policy Type</Label>
            <Select value={policyType} onValueChange={setPolicyType}>
              <SelectTrigger id="policy-type">
                <SelectValue placeholder="Select policy type" />
              </SelectTrigger>
              <SelectContent>
                {POLICY_TYPES.map((type) => (
                  <SelectItem key={type.value} value={type.value}>
                    {type.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="content">Policy Details</Label>
            <Textarea
              id="content"
              placeholder={
                policyType === "cancellation"
                  ? 'e.g., "Cancellations must be made at least 24 hours in advance. Late cancellations may be subject to a 50% fee."'
                  : "Enter your policy details..."
              }
              value={content}
              onChange={(e) => setContent(e.target.value)}
              rows={5}
              required
            />
          </div>

          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={isSubmitting || !content.trim()}>
              {isSubmitting && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Add Policy
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

