function InfoTooltip({ text }: { text: string }) {
  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <HelpCircle className="h-3 w-3 text-muted-foreground/50 cursor-help" />
      </TooltipTrigger>
      <TooltipContent side="top" className="max-w-[200px] text-xs">
        {text}
      </TooltipContent>
    </Tooltip>
  );
}

function TrendIndicator({ percent }: { percent: number }) {
  const { value, direction } = formatTrend(percent);
  if (direction === "flat") return null;

  const Icon = direction === "up" ? TrendingUp : TrendingDown;
  return (
    <span
      className={cn(
        "inline-flex items-center gap-0.5 text-xs font-medium",
        direction === "up" ? "text-emerald-500" : "text-red-400"
      )}
    >
      <Icon className="h-3 w-3" />
      {value}
    </span>
  );
}

function MetricCell({
  label,
  value,
  trend,
  subtext,
  icon: Icon,
  accent,
  tooltip,
}: {
  label: string;
  value: string | number;
  trend?: number;
  subtext?: string;
  icon: React.ElementType;
  accent: string;
  tooltip?: string;
}) {
  return (
    <div className="space-y-1">
      <p className="text-micro text-muted-foreground flex items-center gap-1">
        {label}
        {tooltip && <InfoTooltip text={tooltip} />}
      </p>
      <p className="text-xl font-bold tracking-tight">{value}</p>
      <div className="flex items-center gap-2">
        {trend !== undefined && trend !== 0 && <TrendIndicator percent={trend} />}
        {subtext && (
          <span className="text-xs text-muted-foreground">{subtext}</span>
        )}
      </div>
    </div>
  );
}

