export function ROIPerformanceWidget() {
  const navigate = useNavigate();
  const { data, isLoading, error } = useROIDashboard();

  if (isLoading) return <WidgetSkeleton />;

  if (error || !data) return null;

  if (!data.hasData) {
    return (
      <WidgetEmpty
        steps={data.emptyStateSteps}
        encouragement={data.emptyStateEncouragement}
      />
    );
  }

  const roiDisplay = formatROI(data.roiMultiplier);
  const roiExplanation = getROIExplanation(data.roiMultiplier);
  const roiBadge = getROIBadge(data.roiMultiplier, data.celebratoryTone);
  const entityChange = data.previousMonth
    ? formatCountChange(
        data.entitiesCreated - data.previousMonth.entitiesCreated,
        data.entityName
      )
    : undefined;

  const storyHeadline = buildStoryHeadline(data.storyTemplate, {
    verb: data.actionVerbPast,
    count: data.entitiesCreated,
    entity: data.entityName.toLowerCase(),
    value: formatRevenue(data.aiRevenueCents),
  });

  const winMessage = getWinMessage(
    {
      entitiesCreated: data.entitiesCreated,
      aiRevenueCents: data.aiRevenueCents,
      trends: { calls: data.trends.calls },
    },
    data.celebratoryTone
  );

  return (
    <TooltipProvider>
      <Card className="overflow-hidden">
        <CardContent className="p-0">
          {/* Hero ROI area */}
          <div className="bg-gradient-to-r from-primary/8 to-transparent p-5 md:p-6">
            <div className="flex items-start justify-between gap-3 mb-3">
              <div className="space-y-1 min-w-0 flex-1">
                <h3 className="text-sm font-semibold text-foreground truncate">
                  {storyHeadline}
                </h3>
                {winMessage && (
                  <p className="text-xs text-muted-foreground line-clamp-2">
                    {winMessage}
                  </p>
                )}
              </div>
              <Badge variant="muted" size="sm" className="flex-shrink-0">
                This Month
              </Badge>
            </div>

            <div className="flex items-end gap-4">
              <div>
                <p className="text-micro text-muted-foreground mb-1">ROI</p>
                <p className="text-display text-primary">{roiDisplay}</p>
              </div>
              <div className="pb-2">
                {roiBadge && (
                  <Badge variant={roiBadge.variant} size="sm">
                    {roiBadge.label}
                  </Badge>
                )}
                <p className="text-[11px] text-muted-foreground leading-snug mt-1 max-w-[200px]">
                  {roiExplanation}
                </p>
                <Button
                  variant="ghost"
                  size="sm"
                  className="mt-1 h-7 text-xs gap-1 px-0 justify-start text-primary hover:text-primary/80 w-fit"
                  onClick={() => navigate("/app/reports/roi")}
                >
                  View Full Report
                  <ArrowRight className="h-3 w-3" />
                </Button>
              </div>
            </div>
          </div>

          {/* Compact metric strip */}
          <div className="flex divide-x divide-border/30 px-5 md:px-6 py-4">
            <div className="flex-1 pr-5">
              <MetricCell
                label="AI Revenue"
                value={formatRevenue(data.aiRevenueCents)}
                trend={data.trends.revenue}
                icon={DollarSign}
                accent="text-emerald-500"
                tooltip="Revenue from bookings created by your AI agent"
              />
            </div>
            <div className="flex-1 px-5">
              <MetricCell
                label={`${data.entityName} ${data.actionVerbPast}`}
                value={data.entitiesCreated}
                trend={data.trends.entities}
                subtext={entityChange}
                icon={Target}
                accent="text-blue-500"
              />
            </div>
            <div className="flex-1 px-5">
              <MetricCell
                label={data.callsLabel}
                value={data.totalCalls}
                trend={data.trends.calls}
                icon={Phone}
                accent="text-violet-500"
              />
            </div>
            <div className="flex-1 pl-5">
              <MetricCell
                label="Conversion"
                value={`${Math.round(data.conversionRate)}%`}
                trend={data.trends.conversion}
                icon={TrendingUp}
                accent="text-amber-500"
                tooltip="Percentage of calls that resulted in a booking"
              />
            </div>
          </div>
        </CardContent>
      </Card>
    </TooltipProvider>
  );
}

import { useState } from "react";
import { Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Button } from "@/components/ui/button";
import { useAuth } from "@/contexts/AuthContext";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { useCapabilities } from "@/hooks/useCapabilities";
import { useBusinessCapabilities } from "@/hooks/useBusinessCapabilities";
import { useKnowledgeGaps } from "@/hooks/useKnowledgeGaps";
import { useConversionMetrics } from "@/hooks/useIntelligence";
import { useCalendarConnections } from "@/hooks/useCalendarConnections";
import { useServices } from "@/hooks/useServices";
import { buildSetupSteps } from "@/lib/setupStepBuilder";
import { cn } from "@/lib/utils";
import { QuickAddFAQDialog } from "./QuickAddFAQDialog";
import { QuickAddPolicyDialog } from "./QuickAddPolicyDialog";
import {
  CheckCircle2,
  Circle,
  Package,
  Clock,
  HelpCircle,
  Phone,
  FlaskConical,
  Rocket,
  ChevronRight,
  UtensilsCrossed,
  Warehouse,
  Users,
  Car,
  FileText,
  Calendar as CalendarIcon,
  AlertTriangle,
  DollarSign,
  MapPin,
  Shield,
  Plus,
} from "lucide-react";

/**
 * SetupProgressChecklist - Business-aware setup progress with dynamic steps
 */
export function SetupProgressChecklist() {
  const [faqDialogOpen, setFaqDialogOpen] = useState(false);
  const [policyDialogOpen, setPolicyDialogOpen] = useState(false);
  const { tenant, assistantSettings } = useAuth();
  const { terms } = useIndustryContext();
  const caps = useCapabilities();
  const bizCaps = useBusinessCapabilities();
  const { totalUnresolvedCount: gapCount } = useKnowledgeGaps();
  const { metrics } = useConversionMetrics(30);
  const { hasConnectedCalendar } = useCalendarConnections();
  const { services: allServices } = useServices();

  // Fetch counts for completion checks
  const { data: counts } = useQuery({
    queryKey: ["setup-checklist-counts", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return { faqs: 0, menuItems: 0, impoundConfigured: false };

      const [faqsResult, menuResult, impoundSettingsResult, impoundLotsResult] = await Promise.all([
        supabase
          .from("business_faqs")
          .select("*", { count: "exact", head: true })
          .eq("tenant_id", tenant.id),
        supabase
          .from("menu_items")
          .select("*", { count: "exact", head: true })
          .eq("tenant_id", tenant.id),
        supabase
          .from("impound_settings")
          .select("impound_handling_enabled, base_tow_fee_cents")
          .eq("tenant_id", tenant.id)
          .maybeSingle(),
        supabase
          .from("impound_lots")
          .select("address")
          .eq("tenant_id", tenant.id)
          .eq("is_active", true)
          .limit(1)
          .maybeSingle(),
      ]);

      const impoundConfigured = !!(
        (impoundSettingsResult.data?.base_tow_fee_cents && impoundSettingsResult.data.base_tow_fee_cents > 0) ||
        impoundLotsResult.data?.address
      );

      return {
        faqs: faqsResult.count || 0,
        menuItems: menuResult.count || 0,
        impoundConfigured,
      };
    },
    enabled: !!tenant?.id,
  });

  // Derive service data
  const activeServices = (allServices || []).filter((s) => s.is_active !== false);
  const servicesWithoutPrices = activeServices
    .filter((s) => !s.price_amount && s.price_type !== "quote_only")
    .map((s) => s.name);

  const hoursConfigured = !!tenant?.hours_json &&
    Object.keys((tenant?.hours_json as Record<string, unknown>) || {}).length > 0;

  // Build steps using the builder
  const steps = buildSetupSteps(
    {
      serviceCount: activeServices.length,
      servicesWithoutPrices,
      faqCount: counts?.faqs || 0,
      gapCount,
      hoursConfigured,
      hasCalendar: hasConnectedCalendar,
      hasBooking: caps.hasBooking,
      phoneConnected: assistantSettings?.phone_connected || false,
      tested: assistantSettings?.setup_step_tested || false,
      goLive: assistantSettings?.go_live_enabled || false,
      hangupRate: metrics.hangupRate,
      recentCallCount: metrics.totalCalls,
      caps,
      terms,
      menuItemCount: counts?.menuItems || 0,
      impoundConfigured: counts?.impoundConfigured || false,
      showStaffSection: bizCaps.showStaffSection,
      showCurbsideSection: bizCaps.showCurbsideSection,
      showNewPatientFormsSection: bizCaps.showNewPatientFormsSection,
      // Capability-driven flags
      chargesTripFee: bizCaps.service.chargesTripFee,
      hasTripFeeModifier: false, // TODO: check price_modifiers table
      hasMinimumCharge: bizCaps.service.hasMinimumCharge,
      hasMinimumChargeModifier: false,
      requiresDeposits: bizCaps.service.requiresDeposits,
      hasDepositConfigured: !!assistantSettings?.deposit_amount,
      offersMobileService: bizCaps.service.offersMobileService,
      hasServiceArea: !!(tenant as any)?.service_area_json && Object.keys(((tenant as any)?.service_area_json as Record<string, unknown>) || {}).length > 0,
    },
    {
      Package,
      UtensilsCrossed,
      Clock,
      HelpCircle,
      Warehouse,
      Users,
      Car,
      FileText,
      Phone,
      FlaskConical,
      Rocket,
      CalendarIcon,
      AlertTriangle,
      DollarSign,
      MapPin,
      Shield,
    },
  );

  const visibleSteps = steps.filter(s => !s.skip);
  const completedCount = visibleSteps.filter((s) => s.completed).length;
  const progressPercent = Math.round((completedCount / visibleSteps.length) * 100);

  // Don't show if already live
  if (assistantSettings?.go_live_enabled) {
    return null;
  }

  return (
    <Card className="h-full">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg font-medium">Setup Progress</CardTitle>
          <span className="text-sm font-medium text-muted-foreground tabular-nums">
            {completedCount}/{visibleSteps.length}
          </span>
        </div>
        <Progress value={progressPercent} className="h-2 mt-3" />
      </CardHeader>

      <CardContent className="pt-0">
        <div className="space-y-1">
          {visibleSteps.map((step) => (
            <div key={step.id} className="flex items-center gap-3 p-3 -mx-3 rounded-lg transition-colors group">
              <Link
                to={step.href}
                className={cn(
                  "flex items-center gap-3 flex-1 min-w-0",
                  step.completed ? "opacity-60" : "hover:bg-muted/50 -m-1 p-1 rounded-lg"
                )}
              >
                {step.completed ? (
                  <CheckCircle2 className="h-5 w-5 text-success shrink-0" />
                ) : (
                  <Circle className="h-5 w-5 text-muted-foreground shrink-0" />
                )}
                <div className="flex-1 min-w-0">
                  <p
                    className={cn(
                      "text-sm font-medium",
                      step.completed && "line-through text-muted-foreground"
                    )}
                  >
                    {step.label}
                  </p>
                  {!step.completed && (
                    <p className="text-[13px] text-muted-foreground truncate">
                      {step.description}
                    </p>
                  )}
                </div>
                {!step.completed && (
                  <ChevronRight className="h-4 w-4 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity shrink-0" />
                )}
              </Link>

              {/* Inline quick-add for FAQ and policy steps */}
              {!step.completed && step.id === "faqs" && (
                <Button
                  variant="ghost"
                  size="sm"
                  className="shrink-0 h-7 text-xs gap-1"
                  onClick={(e) => { e.stopPropagation(); setFaqDialogOpen(true); }}
                >
                  <Plus className="h-3 w-3" />
                  Add
                </Button>
              )}
            </div>
          ))}
        </div>
      </CardContent>

      {/* Quick-add dialogs */}
      <QuickAddFAQDialog open={faqDialogOpen} onOpenChange={setFaqDialogOpen} />
      <QuickAddPolicyDialog open={policyDialogOpen} onOpenChange={setPolicyDialogOpen} />
    </Card>
  );
}

import { useState, useEffect, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Phone, Brain, Power, Check, ChevronDown, ChevronRight, CheckCircle2, Zap, Globe, Search } from "lucide-react";
import { PhoneConnectionStep } from "./PhoneConnectionStep";
import { ConfigureAIStep } from "./ConfigureAIStep";
import { GoLiveStep } from "./GoLiveStep";
import { WelcomeBanner } from "./WelcomeBanner";
import { ReadinessRing } from "./ReadinessRing";
import { TestCallCard } from "./TestCallCard";
import { SmartChecklist } from "./SmartChecklist";
import { useAIReadinessV2 } from "@/hooks/useAIReadinessV2";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { searchIndustries, getPopularIndustries, type IndustryCatalogEntry } from "@/data/industryCatalog";
import { WebsiteImportWizard } from "@/components/brain/uploads/WebsiteImportWizard";

interface SetupWizardProps {
  onSetupComplete: () => void;
}

type SetupStep = {
  id: string;
  title: string;
  subtitle: string;
  icon: React.ComponentType<{ className?: string }>;
  isComplete: boolean;
};

export function SetupWizard({ onSetupComplete }: SetupWizardProps) {
  const { tenant, assistantSettings } = useAuth();
  const { score, p0Flags, canGoLive: aiReady, stepProgress } = useAIReadinessV2();
  const { businessMode } = useTenantConfig();
  const [quickStartQuery, setQuickStartQuery] = useState("");
  const [websiteImportOpen, setWebsiteImportOpen] = useState(false);
  const [quickStartDismissed, setQuickStartDismissed] = useState(false);

  // Determine completion status from assistant_settings
  const phoneComplete = assistantSettings?.setup_step_phone || assistantSettings?.phone_connected || false;
  const aiKnowledgeComplete = score >= 85 && p0Flags.length === 0;
  const goLiveComplete = assistantSettings?.go_live_enabled || false;

  // Business info is auto-complete from onboarding
  const businessInfoComplete = !!(tenant?.name && tenant?.timezone);

  const steps: SetupStep[] = useMemo(() => [
    {
      id: "business-info",
      title: "Business Info",
      subtitle: businessInfoComplete ? `${tenant?.name}` : "Complete your profile",
      icon: CheckCircle2,
      isComplete: businessInfoComplete,
    },
    {
      id: "phone",
      title: "Connect Phone",
      subtitle: phoneComplete ? "Phone connected" : "Get an AI phone number",
      icon: Phone,
      isComplete: phoneComplete,
    },
    {
      id: "ai-knowledge",
      title: "Configure AI",
      subtitle: aiKnowledgeComplete
        ? "AI knowledge ready"
        : `${stepProgress.completedSteps} of ${stepProgress.totalSteps} items complete`,
      icon: Brain,
      isComplete: aiKnowledgeComplete,
    },
    {
      id: "golive",
      title: "Go Live",
      subtitle: goLiveComplete ? "Your AI is live!" : "Activate your AI",
      icon: Power,
      isComplete: goLiveComplete,
    },
  ], [businessInfoComplete, phoneComplete, aiKnowledgeComplete, goLiveComplete, tenant, stepProgress]);

  // Find first incomplete step (skip business-info since it's auto-done)
  const firstIncompleteIndex = useMemo(() => {
    const idx = steps.findIndex(s => !s.isComplete);
    return idx === -1 ? steps.length - 1 : idx;
  }, [steps]);

  // Track which step is expanded
  const [expandedStep, setExpandedStep] = useState<number>(firstIncompleteIndex);
  const [userSelected, setUserSelected] = useState(false);

  // Auto-advance when a step completes
  useEffect(() => {
    if (!userSelected) {
      setExpandedStep(firstIncompleteIndex);
    }
  }, [firstIncompleteIndex, userSelected]);

  const completedCount = steps.filter(s => s.isComplete).length;
  const progress = (completedCount / steps.length) * 100;

  const handleStepComplete = (stepIndex: number) => {
    setUserSelected(false);
    if (stepIndex < steps.length - 1) {
      setExpandedStep(stepIndex + 1);
    } else {
      onSetupComplete();
    }
  };

  const toggleStep = (index: number) => {
    setUserSelected(true);
    setExpandedStep(expandedStep === index ? -1 : index);
  };

  // For Go Live, need phone connected + AI knowledge ready
  const canActivateGoLive = phoneComplete && aiKnowledgeComplete;

  return (
    <div className="max-w-2xl mx-auto space-y-6 p-4 md:p-6">
      {/* Welcome Banner — replaces generic header */}
      <WelcomeBanner />

      {/* Quick Start — shown when AI knowledge is low */}
      {score < 50 && !quickStartDismissed && (
        <div className="rounded-xl border-2 border-primary/20 bg-primary/5 p-5 space-y-4">
          <div className="flex items-center gap-3">
            <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
              <Zap className="h-5 w-5 text-primary" />
            </div>
            <div>
              <h3 className="font-semibold text-sm">Quick Start</h3>
              <p className="text-xs text-muted-foreground">Import your business data in seconds</p>
            </div>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {/* Website Import */}
            <button
              onClick={() => setWebsiteImportOpen(true)}
              className="flex items-center gap-3 rounded-lg border bg-card p-3 text-left hover:border-primary/40 transition-colors"
            >
              <Globe className="h-5 w-5 text-primary shrink-0" />
              <div>
                <p className="text-sm font-medium">Import from Website</p>
                <p className="text-xs text-muted-foreground">Scan your site for services & FAQs</p>
              </div>
            </button>

            {/* Industry Template */}
            <a
              href="/app/business-brain?section=about"
              className="flex items-center gap-3 rounded-lg border bg-card p-3 text-left hover:border-primary/40 transition-colors"
            >
              <Search className="h-5 w-5 text-primary shrink-0" />
              <div>
                <p className="text-sm font-medium">Pick Your Industry</p>
                <p className="text-xs text-muted-foreground">Auto-fill from 100+ templates</p>
              </div>
            </a>
          </div>

          <button
            onClick={() => setQuickStartDismissed(true)}
            className="text-xs text-muted-foreground hover:text-foreground transition-colors"
          >
            Skip — I'll set up manually
          </button>
        </div>
      )}

      <WebsiteImportWizard open={websiteImportOpen} onOpenChange={setWebsiteImportOpen} />

      {/* Readiness Ring + Progress */}
      <div className="flex items-center gap-6 justify-center">
        <ReadinessRing score={score} size={100} strokeWidth={7} />
        <div className="space-y-2 text-left">
          <p className="text-sm font-medium">
            {completedCount === steps.length
              ? "You're all set!"
              : `${completedCount} of ${steps.length} steps complete`
            }
          </p>
          <Progress value={progress} className="h-2 w-40" />
          {score < 85 && (
            <p className="text-xs text-muted-foreground">
              Need 85% readiness to go live
            </p>
          )}
        </div>
      </div>

      {/* Test Call CTA — show after phone is connected */}
      {phoneComplete && <TestCallCard variant="full" />}

      {/* Accordion Steps */}
      <div className="space-y-3">
        {steps.map((step, index) => {
          const Icon = step.icon;
          const isExpanded = expandedStep === index;

          return (
            <div
              key={step.id}
              className={`rounded-lg border transition-all ${
                step.isComplete
                  ? "border-emerald-500/20 bg-emerald-500/5"
                  : isExpanded
                    ? "border-primary/30 bg-card shadow-sm"
                    : "border-border bg-card"
              }`}
            >
              {/* Step header - always visible */}
              <button
                onClick={() => toggleStep(index)}
                className="w-full flex items-center gap-3 p-4 text-left"
              >
                <div className={`flex h-8 w-8 items-center justify-center rounded-full shrink-0 ${
                  step.isComplete
                    ? "bg-emerald-100 dark:bg-emerald-900/30"
                    : isExpanded
                      ? "bg-primary/10"
                      : "bg-muted"
                }`}>
                  {step.isComplete ? (
                    <Check className="h-4 w-4 text-emerald-600" />
                  ) : (
                    <Icon className="h-4 w-4 text-muted-foreground" />
                  )}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <p className="text-sm font-medium">{step.title}</p>
                    {step.isComplete && (
                      <Badge variant="outline" className="text-[10px] border-emerald-500/30 text-emerald-600">
                        Done
                      </Badge>
                    )}
                  </div>
                  <p className="text-xs text-muted-foreground truncate">{step.subtitle}</p>
                </div>
                {!step.isComplete && (
                  isExpanded
                    ? <ChevronDown className="h-4 w-4 text-muted-foreground shrink-0" />
                    : <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
                )}
              </button>

              {/* Step content - expanded only */}
              {isExpanded && !step.isComplete && (
                <div className="px-4 pb-4">
                  {step.id === "business-info" && (
                    <p className="text-sm text-muted-foreground">
                      Business info was set up during onboarding. You can edit it in{" "}
                      <a href="/app/business-brain?section=about" className="text-primary underline">Business Brain</a>.
                    </p>
                  )}
                  {step.id === "phone" && (
                    <PhoneConnectionStep
                      onComplete={() => handleStepComplete(index)}
                      isComplete={phoneComplete}
                    />
                  )}
                  {step.id === "ai-knowledge" && (
                    <ConfigureAIStep
                      onComplete={() => handleStepComplete(index)}
                      isComplete={aiKnowledgeComplete}
                    />
                  )}
                  {step.id === "golive" && (
                    <GoLiveStep
                      onComplete={() => handleStepComplete(index)}
                      isComplete={goLiveComplete}
                      canActivate={canActivateGoLive}
                    />
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Smart Checklist — contextual next steps */}
      <SmartChecklist />

      {/* Business Name footer */}
      <div className="text-center pt-4 border-t">
        <p className="text-sm text-muted-foreground">
          Setting up AI for <span className="font-medium text-foreground">{tenant?.name || "your business"}</span>
        </p>
      </div>
    </div>
  );
}

import { useMemo } from "react";
import { Link } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { useServices } from "@/hooks/useServices";
import { useCalendarConnections } from "@/hooks/useCalendarConnections";
import { useAIReadinessV2 } from "@/hooks/useAIReadinessV2";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { cn } from "@/lib/utils";
import {
  ChevronRight,
  Clock,
  Calendar,
  HelpCircle,
  FileText,
  Users,
  MapPin,
  Package,
  UtensilsCrossed,
} from "lucide-react";

interface ChecklistTask {
  id: string;
  label: string;
  description: string;
  href: string;
  isComplete: boolean;
  timeEstimate: string;
  icon: React.ElementType;
  impact: "high" | "medium" | "low";
}

/**
 * SmartChecklist - Contextual task list that shows what's left to configure.
 * Tasks are mode-aware and sorted by impact.
 */
export function SmartChecklist() {
  const { tenant, assistantSettings } = useAuth();
  const { businessMode } = useTenantConfig();
  const { services } = useServices();
  const { hasConnectedCalendar } = useCalendarConnections();
  const { p0Flags } = useAIReadinessV2();

  const activeServices = (services || []).filter((s) => s.is_active !== false);
  const hoursConfigured =
    !!tenant?.hours_json &&
    Object.keys((tenant?.hours_json as Record<string, unknown>) || {}).length > 0;

  // Fetch FAQ count
  const { data: faqCount = 0 } = useQuery({
    queryKey: ["smart-checklist-faqs", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("business_faqs")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id);
      return count || 0;
    },
    enabled: !!tenant?.id,
  });

  // Fetch menu item count (food mode)
  const { data: menuItemCount = 0 } = useQuery({
    queryKey: ["smart-checklist-menu", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("menu_items")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id);
      return count || 0;
    },
    enabled: !!tenant?.id && businessMode === "food",
  });

  // Fetch team size from onboarding
  const teamSize = useMemo(() => {
    const caps = (tenant as any)?.capabilities_json;
    if (!caps) return 1;
    const profile = caps._business_profile;
    if (!profile?.team_size) return 1;
    const sizeMap: Record<string, number> = { solo: 1, "2-5": 3, "6-15": 10, "16+": 20 };
    return sizeMap[profile.team_size] || 1;
  }, [tenant]);

  const tasks = useMemo<ChecklistTask[]>(() => {
    const all: ChecklistTask[] = [];

    // Calendar connection — high impact for booking modes, medium for others
    const isBookingMode = businessMode === "service" || businessMode === "medical";
    if (!hasConnectedCalendar && isBookingMode) {
      all.push({
        id: "calendar",
        label: "Connect your Google Calendar",
        description: "So your AI books real slots and avoids double-booking",
        href: "/app/business-brain?section=about&item=calendar-sync",
        isComplete: false,
        timeEstimate: "~2 min",
        icon: Calendar,
        impact: "high",
      });
    }

    // FAQs — high impact for all modes
    if (faqCount < 5) {
      all.push({
        id: "faqs",
        label: faqCount === 0 ? "Add your top FAQs" : `Add more FAQs (${faqCount}/5)`,
        description: "Your AI answers these when customers ask common questions",
        href: "/app/business-brain?section=training&item=faqs",
        isComplete: false,
        timeEstimate: "~3 min",
        icon: HelpCircle,
        impact: "high",
      });
    }

    // Services/Menu — mode-specific, high impact
    if (businessMode === "food") {
      // Food mode: check menu items, not services
      if (menuItemCount === 0) {
        all.push({
          id: "menu",
          label: "Add your menu items",
          description: "So your AI can describe your menu and take orders",
          href: "/app/business-brain?section=services&item=catalog",
          isComplete: false,
          timeEstimate: "~5 min",
          icon: UtensilsCrossed,
          impact: "high",
        });
      }
    } else if (businessMode !== "dispatch") {
      // Service, medical, general, sales: check services
      if (activeServices.length === 0) {
        all.push({
          id: "services",
          label: "Add your services",
          description: "So your AI can describe what you offer and quote prices",
          href: "/app/business-brain?section=services&item=catalog",
          isComplete: false,
          timeEstimate: "~3 min",
          icon: Package,
          impact: "high",
        });
      }
    }
    // Dispatch: services are handled differently via dispatch-specific setup; omit from checklist

    // Hours — high impact for all modes
    if (!hoursConfigured) {
      all.push({
        id: "hours",
        label: "Set your business hours",
        description: "So your AI can tell callers when you're open",
        href: "/app/business-brain?section=about&item=business-hours",
        isComplete: false,
        timeEstimate: "~1 min",
        icon: Clock,
        impact: "high",
      });
    }

    // Policies — medium impact (all modes)
    const hasCancellationPolicy = p0Flags.every((f) => f !== "missing_policies");
    if (!hasCancellationPolicy) {
      all.push({
        id: "policies",
        label: "Set your cancellation policy",
        description: "So your AI can explain your policy to customers",
        href: "/app/business-brain?section=operations&item=policies",
        isComplete: false,
        timeEstimate: "~1 min",
        icon: FileText,
        impact: "medium",
      });
    }

    // Service area — medium impact (dispatch/service modes only)
    if (
      (businessMode === "dispatch" || businessMode === "service") &&
      p0Flags.includes("missing_service_area")
    ) {
      all.push({
        id: "service-area",
        label: "Define your service area",
        description: "So your AI can confirm if a location is serviceable",
        href: "/app/business-brain?section=operations&item=coverage",
        isComplete: false,
        timeEstimate: "~2 min",
        icon: MapPin,
        impact: businessMode === "dispatch" ? "high" : "medium",
      });
    }

    // Calendar — medium impact for non-booking modes
    if (!hasConnectedCalendar && !isBookingMode && businessMode !== "dispatch") {
      all.push({
        id: "calendar",
        label: "Connect your calendar",
        description: "Sync your schedule so your AI knows when you're available",
        href: "/app/business-brain?section=about&item=calendar-sync",
        isComplete: false,
        timeEstimate: "~2 min",
        icon: Calendar,
        impact: "medium",
      });
    }

    // Team members — medium impact (if team > 1)
    if (teamSize > 1) {
      all.push({
        id: "team",
        label: "Add your team members",
        description: "So your AI knows who's available and can assign work",
        href: "/app/business-brain?section=about&item=team",
        isComplete: false,
        timeEstimate: "~2 min",
        icon: Users,
        impact: "medium",
      });
    }

    // Sort: high > medium > low
    const impactOrder = { high: 0, medium: 1, low: 2 };
    all.sort((a, b) => impactOrder[a.impact] - impactOrder[b.impact]);

    return all;
  }, [
    hasConnectedCalendar,
    faqCount,
    menuItemCount,
    activeServices.length,
    hoursConfigured,
    p0Flags,
    businessMode,
    teamSize,
  ]);

  if (tasks.length === 0) return null;

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-semibold text-muted-foreground uppercase tracking-wider">
          Recommended Next Steps
        </h3>
        <span className="text-xs text-muted-foreground">
          {tasks.length} {tasks.length === 1 ? "task" : "tasks"} remaining
        </span>
      </div>
      <div className="space-y-1.5">
        {tasks.map((task) => {
          const Icon = task.icon;
          return (
            <Link
              key={task.id}
              to={task.href}
              className={cn(
                "flex items-center gap-3 p-3 rounded-lg border border-border/30 bg-card/60 backdrop-blur-sm transition-all group",
                "hover:border-primary/20 hover:bg-card/80"
              )}
            >
              <div className="h-8 w-8 rounded-lg bg-muted/60 border border-border/20 flex items-center justify-center shrink-0">
                <Icon className="h-4 w-4 text-muted-foreground" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium">{task.label}</p>
                <p className="text-xs text-muted-foreground truncate">{task.description}</p>
              </div>
              <div className="flex items-center gap-2 shrink-0">
                <span className="text-[10px] text-muted-foreground bg-muted/60 border border-border/20 px-1.5 py-0.5 rounded">
                  {task.timeEstimate}
                </span>
                <ChevronRight className="h-4 w-4 text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity" />
              </div>
            </Link>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { useBusinessContext } from "@/hooks/useBusinessContext";
import { useKnowledgeUploads } from "@/hooks/useKnowledgeUploads";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import {
  Brain,
  Upload,
  FileText,
  HelpCircle,
  Clock,
  Briefcase,
  UtensilsCrossed,
  CheckCircle2,
  AlertTriangle,
  Plus,
  Loader2,
} from "lucide-react";
import { QuickAddFAQDialog } from "./QuickAddFAQDialog";
import { QuickAddServiceDialog } from "./QuickAddServiceDialog";
import { QuickAddPolicyDialog } from "./QuickAddPolicyDialog";

export function TeachAISection() {
  const navigate = useNavigate();
  const { tenant } = useAuth();
  const { toast } = useToast();
  const { businessMode } = useTenantConfig();
  const caps = useCapabilities();
  const { context } = useBusinessContext(tenant?.id || null);
  const { createUpload, processingCount } = useKnowledgeUploads();

  const [isDragging, setIsDragging] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [faqDialogOpen, setFaqDialogOpen] = useState(false);
  const [serviceDialogOpen, setServiceDialogOpen] = useState(false);
  const [policyDialogOpen, setPolicyDialogOpen] = useState(false);

  // Handle file upload
  const handleFileUpload = useCallback(async (files: FileList) => {
    if (!tenant?.id || files.length === 0) return;

    setIsUploading(true);
    
    try {
      for (const file of Array.from(files)) {
        // Validate file type
        const allowedTypes = [
          'application/pdf',
          'image/jpeg',
          'image/png',
          'image/webp',
          'application/msword',
          'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
          'application/vnd.ms-excel',
          'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        ];

        if (!allowedTypes.includes(file.type)) {
          toast({
            variant: "destructive",
            title: "Unsupported file type",
            description: `${file.name} is not supported. Use PDF, images, Word, or Excel.`,
          });
          continue;
        }

        // Upload to Supabase storage
        const fileName = `${tenant.id}/${Date.now()}-${file.name}`;
        const { data: uploadData, error: uploadError } = await supabase.storage
          .from("knowledge-uploads")
          .upload(fileName, file);

        if (uploadError) {
          throw new Error(`Failed to upload ${file.name}: ${uploadError.message}`);
        }

        // Get public URL
        const { data: { publicUrl } } = supabase.storage
          .from("knowledge-uploads")
          .getPublicUrl(fileName);

        // Create knowledge source record
        await createUpload({
          fileName: file.name,
          fileUrl: publicUrl,
          sourceType: "general",
        });

        // Trigger processing
        await supabase.functions.invoke("process-knowledge-upload", {
          body: { tenant_id: tenant.id, file_url: publicUrl, file_name: file.name },
        });
      }

      toast({
        title: "Files uploaded!",
        description: "AI is now extracting knowledge from your documents.",
      });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Upload failed",
        description: error.message,
      });
    } finally {
      setIsUploading(false);
    }
  }, [tenant?.id, createUpload, toast]);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    handleFileUpload(e.dataTransfer.files);
  }, [handleFileUpload]);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  // Knowledge summary
  const servicesCount = context?.services?.length || 0;
  const faqsCount = context?.faqs?.length || 0;
  const hasHours = context?.hours && Object.keys(context.hours).length > 0;
  const hasPolicies = !!(context?.policies.cancellation || context?.policies.deposit);

  // Mode-aware labels
  const serviceLabel = businessMode === 'food' ? 'Menu items' : 'Services';
  const missingServiceLabel = businessMode === 'food' ? 'Menu items' : 'Services';
  const minServicesNeeded = businessMode === 'food' ? 5 : 3;

  // Missing items - industry aware
  const missingItems: string[] = [];
  if (!context?.business.name) missingItems.push("Business name");
  if (!hasHours) missingItems.push("Business hours");
  if (faqsCount < 3) missingItems.push("FAQs");
  if (!hasPolicies) missingItems.push("Policies");
  if (caps.isFoodBusiness && servicesCount < 5) missingItems.push("Menu items");
  if (!caps.isFoodBusiness && servicesCount < 3) missingItems.push("Services");

  const quickAddButtons = [
    {
      icon: caps.isFoodBusiness ? UtensilsCrossed : Briefcase,
      label: caps.isFoodBusiness ? 'Menu Item' : 'Service',
      onClick: () => setServiceDialogOpen(true),
    },
    {
      icon: HelpCircle,
      label: 'FAQ',
      onClick: () => setFaqDialogOpen(true),
    },
    {
      icon: Clock,
      label: 'Hours',
      onClick: () => navigate('/app/settings'),
    },
    {
      icon: FileText,
      label: 'Policy',
      onClick: () => setPolicyDialogOpen(true),
    },
  ];

  return (
    <>
      <Card className="border-primary/20 bg-gradient-to-br from-card to-primary/5">
        <CardHeader className="pb-3">
          <CardTitle className="flex items-center gap-2 text-base font-medium">
            <Brain className="h-5 w-5 text-primary" />
            Teach Your AI
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Upload Zone - Redirects to Business Brain */}
          <div
            onClick={() => navigate('/app/business-brain')}
            className="relative border-2 border-dashed border-primary/50 rounded-xl p-6 text-center transition-colors hover:border-primary hover:bg-primary/5 cursor-pointer"
          >
            <Brain className="h-8 w-8 mx-auto text-primary mb-2" />
            <p className="text-sm font-medium mb-1">Upload Knowledge in Business Brain</p>
            <p className="text-xs text-muted-foreground mb-3">
              Click here to upload menus, policies, and other documents
            </p>
            <Button size="sm" variant="outline" className="pointer-events-none">
              Go to Business Brain
            </Button>
          </div>

          {/* Processing indicator */}
          {processingCount > 0 && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-amber-500/10 border border-amber-500/20">
              <Loader2 className="h-4 w-4 text-amber-400 animate-spin" />
              <span className="text-sm text-amber-400">
                Processing {processingCount} file{processingCount > 1 ? 's' : ''}...
              </span>
            </div>
          )}

          {/* Quick Add Section */}
          <div>
            <p className="text-xs text-muted-foreground text-center mb-3">— OR QUICK ADD —</p>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
              {quickAddButtons.map((btn) => (
                <Button
                  key={btn.label}
                  variant="outline"
                  size="sm"
                  className="gap-2 h-auto py-2.5"
                  onClick={btn.onClick}
                >
                  <Plus className="h-3.5 w-3.5" />
                  {btn.label}
                </Button>
              ))}
            </div>
          </div>

          {/* Knowledge Summary */}
          <div className="pt-3 border-t border-border/50">
            <p className="text-xs font-medium text-muted-foreground mb-2">What AI knows:</p>
            <div className="flex flex-wrap gap-2">
              <Badge variant="outline" className={servicesCount > 0 ? 'text-emerald-400 border-emerald-500/30' : ''}>
                {servicesCount > 0 && <CheckCircle2 className="h-3 w-3 mr-1" />}
                {servicesCount} {caps.isFoodBusiness ? 'Menu items' : 'Services'}
              </Badge>
              <Badge variant="outline" className={faqsCount > 0 ? 'text-emerald-400 border-emerald-500/30' : ''}>
                {faqsCount > 0 && <CheckCircle2 className="h-3 w-3 mr-1" />}
                {faqsCount} FAQs
              </Badge>
              <Badge variant="outline" className={hasHours ? 'text-emerald-400 border-emerald-500/30' : ''}>
                {hasHours && <CheckCircle2 className="h-3 w-3 mr-1" />}
                Hours
              </Badge>
              <Badge variant="outline" className={hasPolicies ? 'text-emerald-400 border-emerald-500/30' : ''}>
                {hasPolicies && <CheckCircle2 className="h-3 w-3 mr-1" />}
                Policies
              </Badge>
            </div>

            {/* Missing items alert */}
            {missingItems.length > 0 && (
              <div className="mt-3 flex items-start gap-2 p-2.5 rounded-lg bg-amber-500/10 border border-amber-500/20">
                <AlertTriangle className="h-4 w-4 text-amber-400 mt-0.5 shrink-0" />
                <div className="flex-1">
                  <p className="text-xs text-amber-400">
                    Missing: {missingItems.slice(0, 2).join(', ')}
                    {missingItems.length > 2 && ` +${missingItems.length - 2} more`}
                  </p>
                </div>
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-6 text-xs text-amber-400 hover:text-amber-300 px-2"
                  onClick={() => navigate('/app/business-brain')}
                >
                  Fix
                </Button>
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Quick Add Dialogs */}
      <QuickAddFAQDialog open={faqDialogOpen} onOpenChange={setFaqDialogOpen} />
      <QuickAddServiceDialog open={serviceDialogOpen} onOpenChange={setServiceDialogOpen} />
      <QuickAddPolicyDialog open={policyDialogOpen} onOpenChange={setPolicyDialogOpen} />
    </>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Mic, Check, Loader2, PhoneCall, Volume2, MessageSquare } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { hasVoiceFeature, hasSmsFeature } from "@/config/pricing";
import VoiceAgentTest from "@/components/ai/VoiceAgentTest";
import SMSSimulator from "@/components/simulator/SMSSimulator";

interface TestAIStepProps {
  onComplete: () => void;
  isComplete: boolean;
}

export function TestAIStep({ onComplete, isComplete }: TestAIStepProps) {
  const { tenant, refreshTenant, subscription } = useAuth();
  const { toast } = useToast();
  
  // Use centralized helpers for feature detection
  const planCode = subscription?.plan_code;
  const hasVoice = hasVoiceFeature(planCode);
  const hasSms = hasSmsFeature(planCode);
  
  const [testPhoneNumber, setTestPhoneNumber] = useState("");
  const [callingPhone, setCallingPhone] = useState(false);
  const [hasTested, setHasTested] = useState(false);
  
  // Default to appropriate tab based on plan
  const defaultTab = hasVoice ? "browser" : "sms";

  const handleTestCallToPhone = async () => {
    if (!testPhoneNumber.trim()) {
      toast({
        variant: "destructive",
        title: "Enter phone number",
        description: "Please enter the phone number to call",
      });
      return;
    }

    setCallingPhone(true);
    try {
      const { data, error } = await supabase.functions.invoke("test-call-phone", {
        body: { 
          tenantId: tenant?.id, 
          phoneNumber: testPhoneNumber.trim(),
        },
      });

      if (error) throw error;

      toast({
        title: "📞 Test Call Initiated",
        description: "Your phone should ring in a few seconds. Answer to talk to your AI!",
      });
      setHasTested(true);
    } catch (error: any) {
      // Demo mode fallback
      toast({
        title: "📞 Demo Mode",
        description: "Real phone calls require Twilio. Use the browser test below!",
      });
      setHasTested(true);
    } finally {
      setCallingPhone(false);
    }
  };

  const handleMarkComplete = async () => {
    if (!tenant) return;

    try {
      // Check if settings exist
      const { data: existing } = await supabase
        .from("assistant_settings")
        .select("tenant_id")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (existing) {
        const { error } = await supabase
          .from("assistant_settings")
          .update({
            setup_step_tested: true,
            updated_at: new Date().toISOString(),
          })
          .eq("tenant_id", tenant.id);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from("assistant_settings")
          .insert({
            tenant_id: tenant.id,
            setup_step_tested: true,
          });
        if (error) throw error;
      }

      await refreshTenant();
      toast({
        title: "AI Tested! ✅",
        description: "You're ready to go live.",
      });
      onComplete();
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Error",
        description: error.message,
      });
    }
  };

  if (isComplete) {
    return (
      <Card className="border-primary/20 bg-primary/5">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-primary">
            <Check className="h-5 w-5" />
            AI Tested
          </CardTitle>
          <CardDescription>
            You've tested your AI voice agent and it's working great!
          </CardDescription>
        </CardHeader>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          {hasVoice ? <Mic className="h-5 w-5 text-primary" /> : <MessageSquare className="h-5 w-5 text-primary" />}
          {hasVoice ? "Test Your AI Voice Agent" : "Test Your AI Text Responses"}
        </CardTitle>
        <CardDescription>
          {hasVoice 
            ? "Experience your AI as customers will. Make a test call to hear it in action."
            : "See how your AI responds to text messages from customers."
          }
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Test Methods */}
        <Tabs defaultValue={defaultTab} className="w-full">
          <TabsList className={`grid w-full ${hasVoice && hasSms ? "grid-cols-3" : "grid-cols-2"}`}>
            {hasVoice && (
              <>
                <TabsTrigger value="browser" className="gap-2">
                  <Volume2 className="h-4 w-4" />
                  Browser Test
                </TabsTrigger>
                <TabsTrigger value="phone" className="gap-2">
                  <PhoneCall className="h-4 w-4" />
                  Call My Phone
                </TabsTrigger>
              </>
            )}
            {hasSms && (
              <TabsTrigger value="sms" className="gap-2">
                <MessageSquare className="h-4 w-4" />
                SMS Test
              </TabsTrigger>
            )}
          </TabsList>

          {hasVoice && (
            <>
              <TabsContent value="browser" className="mt-4">
                <div className="space-y-4">
                  <p className="text-sm text-muted-foreground">
                    Speak directly to your AI through your browser's microphone. This is the quickest way to test.
                  </p>
                  
                  <VoiceAgentTest />
                </div>
              </TabsContent>

              <TabsContent value="phone" className="mt-4">
                <div className="space-y-4">
                  <p className="text-sm text-muted-foreground">
                    Have your AI call you to experience exactly what your customers will hear.
                  </p>
                  
                  <div className="space-y-2">
                    <Label htmlFor="test-phone">Your Phone Number</Label>
                    <Input
                      id="test-phone"
                      type="tel"
                      placeholder="+1 (555) 123-4567"
                      value={testPhoneNumber}
                      onChange={(e) => setTestPhoneNumber(e.target.value)}
                    />
                  </div>

                  <Button
                    onClick={handleTestCallToPhone}
                    disabled={callingPhone || !testPhoneNumber.trim()}
                    className="w-full gap-2"
                    variant="outline"
                  >
                    {callingPhone ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <PhoneCall className="h-4 w-4" />
                    )}
                    {callingPhone ? "Calling..." : "Call My Phone"}
                  </Button>

                  <p className="text-xs text-center text-muted-foreground">
                    Demo mode: Real calls require Twilio integration
                  </p>
                </div>
              </TabsContent>
            </>
          )}

          {hasSms && (
            <TabsContent value="sms" className="mt-4">
              <div className="space-y-4">
                <p className="text-sm text-muted-foreground">
                  Simulate an incoming text message to see how your AI responds to customers.
                </p>
                
                <SMSSimulator />
              </div>
            </TabsContent>
          )}
        </Tabs>

        {/* Complete Step */}
        <div className="pt-4 border-t">
          <Button 
            onClick={handleMarkComplete}
            className="w-full gap-2"
          >
            <Check className="h-4 w-4" />
            I've Tested My AI - Continue
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { PhoneCall, Sparkles, MessageSquare, X } from "lucide-react";
import { useIndustryContext } from "@/hooks/useIndustryContext";

// Format E.164 number to friendly display
function formatPhoneNumber(phone: string): string {
  const cleaned = phone.replace(/\D/g, "");
  if (cleaned.length === 11 && cleaned.startsWith("1")) {
    return `(${cleaned.substring(1, 4)}) ${cleaned.substring(4, 7)}-${cleaned.substring(7, 11)}`;
  }
  return phone;
}

interface TestCallCardProps {
  /** Compact inline version (for sidebar) vs. full card */
  variant?: "full" | "compact";
}

/**
 * TestCallCard - Prominent CTA to make a test call to the AI agent.
 * Shows phone number, sample prompts, and a direct call link.
 */
export function TestCallCard({ variant = "full" }: TestCallCardProps) {
  const { assistantSettings } = useAuth();
  const { terms, mode } = useIndustryContext();
  const [showModal, setShowModal] = useState(false);

  const aiNumber = assistantSettings?.forwarding_phone_e164 || assistantSettings?.closeloop_number;
  if (!aiNumber) return null;

  const displayNumber = formatPhoneNumber(aiNumber);

  // Mode-aware sample prompts
  const samplePrompts = (() => {
    switch (mode) {
      case "dispatch":
        return [
          `"I need a tow truck"`,
          `"How much does a tow cost?"`,
          `"What's your service area?"`,
          `"How long until you can get here?"`,
        ];
      case "food":
        return [
          `"I'd like to place an order for pickup"`,
          `"What are your hours?"`,
          `"Do you deliver to my area?"`,
          `"Can I make a reservation for tonight?"`,
        ];
      case "medical":
        return [
          `"I need to schedule an appointment"`,
          `"What are your office hours?"`,
          `"Do you accept my insurance?"`,
          `"I need to reschedule my visit"`,
        ];
      case "general":
        return [
          `"I'd like some information about your business"`,
          `"What are your hours?"`,
          `"Can someone call me back?"`,
          `"What services do you offer?"`,
        ];
      default: // service
        return [
          `"I need to schedule ${(terms.bookingLabel as string)?.toLowerCase() || "an appointment"}"`,
          `"What are your hours?"`,
          `"How much does a ${(terms.serviceLabel as string)?.toLowerCase() || "service"} cost?"`,
          `"Do you have any availability today?"`,
        ];
    }
  })();

  if (variant === "compact") {
    return (
      <div className="flex items-center gap-3 p-3 rounded-lg border bg-primary/5 border-primary/20">
        <div className="h-8 w-8 rounded-full bg-primary/10 flex items-center justify-center shrink-0">
          <PhoneCall className="h-4 w-4 text-primary" />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-medium">Test Your AI</p>
          <p className="text-xs text-muted-foreground truncate">{displayNumber}</p>
        </div>
        <Button variant="outline" size="sm" className="gap-1.5 shrink-0" onClick={() => setShowModal(true)}>
          <PhoneCall className="h-3.5 w-3.5" />
          Call
        </Button>
      </div>
    );
  }

  return (
    <>
      <Card className="border-primary/20 bg-gradient-to-br from-primary/5 to-primary/10 overflow-hidden">
        <CardContent className="p-6">
          <div className="flex items-start justify-between gap-4">
            <div className="space-y-3">
              <div className="flex items-center gap-2">
                <Sparkles className="h-5 w-5 text-primary" />
                <h3 className="text-lg font-semibold">Hear Your AI in Action</h3>
              </div>
              <p className="text-sm text-muted-foreground">
                Call your AI number to hear how it answers. Try one of the sample prompts below.
              </p>
              <div className="flex items-center gap-3">
                <span className="text-xl font-bold tracking-tight">{displayNumber}</span>
                <Badge variant="secondary" className="gap-1">
                  <div className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
                  Live
                </Badge>
              </div>
              <div className="flex flex-wrap gap-2 pt-1">
                <Button className="gap-2" onClick={() => setShowModal(true)}>
                  <PhoneCall className="h-4 w-4" />
                  Make a Test Call
                </Button>
                <Button variant="outline" className="gap-2" asChild>
                  <a href={`tel:${aiNumber}`}>
                    <PhoneCall className="h-4 w-4" />
                    Call Now
                  </a>
                </Button>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Test Call Modal */}
      <Dialog open={showModal} onOpenChange={setShowModal}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <PhoneCall className="h-5 w-5 text-primary" />
              Test Your AI Agent
            </DialogTitle>
            <DialogDescription>
              Call the number below from your phone to hear your AI in action.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-6 py-4">
            {/* Phone number */}
            <div className="text-center p-6 rounded-xl bg-muted/50 border">
              <p className="text-3xl font-bold tracking-tight">{displayNumber}</p>
              <p className="text-sm text-muted-foreground mt-2">Your AI phone number</p>
              <Button className="mt-4 gap-2" size="lg" asChild>
                <a href={`tel:${aiNumber}`}>
                  <PhoneCall className="h-5 w-5" />
                  Call from This Device
                </a>
              </Button>
            </div>

            {/* Sample prompts */}
            <div className="space-y-3">
              <p className="text-sm font-medium flex items-center gap-2">
                <MessageSquare className="h-4 w-4 text-muted-foreground" />
                Try saying:
              </p>
              <div className="grid gap-2">
                {samplePrompts.map((prompt, i) => (
                  <div
                    key={i}
                    className="text-sm text-muted-foreground p-3 rounded-lg bg-muted/30 border border-dashed"
                  >
                    {prompt}
                  </div>
                ))}
              </div>
            </div>

            <p className="text-xs text-center text-muted-foreground">
              After your call, check the Inbox to see the transcript and how your AI handled it.
            </p>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { 
  Clock,
  AlertCircle,
  CheckCircle2,
  ArrowRight,
  ShieldCheck
} from "lucide-react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Link } from "react-router-dom";
import { startOfDay, endOfDay } from "date-fns";

interface TodayStats {
  pendingItems: number;
  urgentItems: number;
  completedItems: number;
}

export function TodayQueueCard() {
  const { businessMode, hipaaMode } = useTenantConfig();
  const caps = useCapabilities();
  const { tenant } = useAuth();

  const { data: stats, isLoading } = useQuery({
    queryKey: ["today-queue-stats", tenant?.id, businessMode],
    queryFn: async (): Promise<TodayStats> => {
      if (!tenant?.id) return { pendingItems: 0, urgentItems: 0, completedItems: 0 };

      const today = new Date();
      const todayStart = startOfDay(today).toISOString();
      const todayEnd = endOfDay(today).toISOString();

      let pendingItems = 0;
      let urgentItems = 0;
      let completedItems = 0;

      if (caps.hasBooking) {
        const { data: bookings } = await supabase
          .from("bookings")
          .select("status, start_at")
          .eq("tenant_id", tenant.id)
          .gte("start_at", todayStart)
          .lte("start_at", todayEnd);

        pendingItems = bookings?.filter(b => b.status === "pending_deposit").length || 0;
        completedItems = bookings?.filter(b => b.status === "confirmed").length || 0;
      }

      if (caps.hasDispatchQueue) {
        const { data: jobs } = await supabase
          .from("dispatch_jobs")
          .select("status, priority")
          .eq("tenant_id", tenant.id)
          .in("status", ["pending", "assigned", "en_route", "on_site"]);

        pendingItems = jobs?.filter(j => j.status === "pending").length || 0;
        urgentItems = jobs?.filter(j => j.priority === "urgent" || j.priority === "high").length || 0;
        completedItems = jobs?.filter(j => j.status === "completed").length || 0;
      }

      if (caps.hasFoodOrders) {
        const { data: orders } = await supabase
          .from("food_orders")
          .select("status, created_at")
          .eq("tenant_id", tenant.id)
          .gte("created_at", todayStart)
          .lte("created_at", todayEnd);

        pendingItems = orders?.filter(o => o.status === "pending" || o.status === "confirmed").length || 0;
        completedItems = orders?.filter(o => o.status === "ready" || o.status === "completed").length || 0;
      }

      if (caps.hasMedicalIntake) {
        const { data: intakes } = await supabase
          .from("medical_intakes")
          .select("status, urgency_level")
          .eq("tenant_id", tenant.id)
          .eq("status", "pending");

        pendingItems = intakes?.length || 0;
        urgentItems = intakes?.filter(i => i.urgency_level === "urgent").length || 0;
      }

      return { pendingItems, urgentItems, completedItems };
    },
    enabled: !!tenant?.id,
    refetchInterval: 30000,
  });

  const getQueueTitle = () => {
    switch (businessMode) {
      case "dispatch": return "Dispatch Queue";
      case "food": return "Kitchen Queue";
      case "medical": return "Intake Queue";
      case "sales": return "Appointments";
      default: return "Today's Queue";
    }
  };

  const getMainLink = () => {
    switch (businessMode) {
      case "dispatch": return "/app/dispatch";
      case "food": return "/app/orders";
      case "medical": return "/app/medical-intake";
      default: return "/app/bookings";
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader className="pb-3">
          <Skeleton className="h-5 w-32" />
        </CardHeader>
        <CardContent>
          <Skeleton className="h-16 w-full" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-base font-medium">{getQueueTitle()}</CardTitle>
          {hipaaMode && (
            <Badge variant="outline" className="gap-1 text-xs">
              <ShieldCheck className="h-3 w-3" />
              HIPAA
            </Badge>
          )}
        </div>
      </CardHeader>
      <CardContent>
        <Link to={getMainLink()}>
          <div className="flex items-center justify-between p-3 rounded-lg bg-muted/50 hover:bg-muted transition-colors cursor-pointer group">
            <div className="flex items-center gap-6">
              {/* Pending */}
              <div className="flex items-center gap-2">
                <div className={`flex items-center justify-center h-8 w-8 rounded-lg ${
                  stats?.pendingItems ? "bg-amber-500/15" : "bg-muted"
                }`}>
                  <Clock className={`h-4 w-4 ${stats?.pendingItems ? "text-amber-400" : "text-muted-foreground"}`} />
                </div>
                <div>
                  <p className="text-lg font-bold leading-none">{stats?.pendingItems || 0}</p>
                  <p className="text-xs text-muted-foreground">Pending</p>
                </div>
              </div>

              {/* Urgent (only show if mode supports it) */}
              {(caps.hasDispatchQueue || caps.hasMedicalIntake) && (
                <div className="flex items-center gap-2">
                  <div className={`flex items-center justify-center h-8 w-8 rounded-lg ${
                    stats?.urgentItems ? "bg-rose-500/15" : "bg-muted"
                  }`}>
                    <AlertCircle className={`h-4 w-4 ${stats?.urgentItems ? "text-rose-400" : "text-muted-foreground"}`} />
                  </div>
                  <div>
                    <p className="text-lg font-bold leading-none">{stats?.urgentItems || 0}</p>
                    <p className="text-xs text-muted-foreground">Urgent</p>
                  </div>
                </div>
              )}

              {/* Completed */}
              <div className="flex items-center gap-2">
                <div className={`flex items-center justify-center h-8 w-8 rounded-lg ${
                  stats?.completedItems ? "bg-emerald-500/15" : "bg-muted"
                }`}>
                  <CheckCircle2 className={`h-4 w-4 ${stats?.completedItems ? "text-emerald-400" : "text-muted-foreground"}`} />
                </div>
                <div>
                  <p className="text-lg font-bold leading-none">{stats?.completedItems || 0}</p>
                  <p className="text-xs text-muted-foreground">Done</p>
                </div>
              </div>
            </div>

            <ArrowRight className="h-5 w-5 text-muted-foreground group-hover:text-foreground transition-colors" />
          </div>
        </Link>
      </CardContent>
    </Card>
  );
}

import { useNavigate } from "react-router-dom";
import { cn } from "@/lib/utils";
import { Card, CardContent } from "@/components/ui/card";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { 
  Phone, 
  Calendar, 
  DollarSign, 
  Bot,
  UtensilsCrossed,
  Truck,
  Users,
  Stethoscope,
  TrendingUp,
  HelpCircle,
} from "lucide-react";
import { startOfDay, startOfWeek, endOfDay } from "date-fns";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

interface MetricCard {
  label: string;
  value: number | string;
  icon: React.ElementType;
  href: string;
  color: string;
  bgColor: string;
  tooltip?: string;
}

export function TodaySnapshot() {
  const navigate = useNavigate();
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const caps = useCapabilities();
  const { terms } = useIndustryContext();

  const todayStart = startOfDay(new Date()).toISOString();
  const todayEnd = endOfDay(new Date()).toISOString();
  const weekStart = startOfWeek(new Date()).toISOString();

  // Fetch today's calls
  const { data: callsToday = 0 } = useQuery({
    queryKey: ["snapshot-calls", tenant?.id, todayStart],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("ai_call_sessions")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .gte("started_at", todayStart)
        .lte("started_at", todayEnd);
      return count || 0;
    },
    enabled: !!tenant?.id,
  });

  // Fetch bookings this week
  const { data: bookingsWeek = 0 } = useQuery({
    queryKey: ["snapshot-bookings", tenant?.id, weekStart],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("bookings")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .gte("created_at", weekStart);
      return count || 0;
    },
    enabled: !!tenant?.id,
  });

  // Fetch orders today (for food mode)
  const { data: ordersToday = 0 } = useQuery({
    queryKey: ["snapshot-orders", tenant?.id, todayStart],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("food_orders")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .gte("created_at", todayStart)
        .lte("created_at", todayEnd);
      return count || 0;
    },
    enabled: !!tenant?.id && caps.hasFoodOrders,
  });

  // Fetch pending orders (for food mode)
  const { data: pendingPrep = 0 } = useQuery({
    queryKey: ["snapshot-pending-orders", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("food_orders")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .in("status", ["pending", "confirmed", "preparing"]);
      return count || 0;
    },
    enabled: !!tenant?.id && caps.hasFoodOrders,
  });

  // Fetch dispatch jobs (for dispatch mode)
  const { data: jobsPending = 0 } = useQuery({
    queryKey: ["snapshot-dispatch-pending", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("dispatch_jobs")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .in("status", ["pending", "assigned"]);
      return count || 0;
    },
    enabled: !!tenant?.id && caps.hasDispatchQueue,
  });

  // Fetch intakes today (for medical mode)
  const { data: intakesToday = 0 } = useQuery({
    queryKey: ["snapshot-medical-intakes", tenant?.id, todayStart],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await supabase
        .from("medical_intakes")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .gte("created_at", todayStart)
        .lte("created_at", todayEnd);
      return count || 0;
    },
    enabled: !!tenant?.id && caps.hasMedicalIntake,
  });

  // Fetch AI readiness score
  const { data: aiScore = 0 } = useQuery({
    queryKey: ["snapshot-ai-score", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      // Simple score based on knowledge count
      const { count: faqs } = await supabase
        .from("business_faqs")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id);
      const { count: services } = await supabase
        .from("services")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id);
      const { count: knowledge } = await supabase
        .from("ai_knowledge_base")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id);
      
      const totalItems = (faqs || 0) + (services || 0) + (knowledge || 0);
      // Simple scoring: 10 items = 100%
      return Math.min(100, Math.round((totalItems / 10) * 100));
    },
    enabled: !!tenant?.id,
  });

  // Build metrics based on business mode
  const getMetrics = (): MetricCard[] => {
    switch (businessMode) {
      case "food":
        return [
          { label: "Orders Today", value: ordersToday, icon: UtensilsCrossed, href: "/app/orders", color: "text-orange-400", bgColor: "bg-orange-500/15" },
          { label: "Pending Prep", value: pendingPrep, icon: Truck, href: "/app/orders", color: "text-amber-400", bgColor: "bg-amber-500/15" },
          { label: "Calls Today", value: callsToday, icon: Phone, href: "/app/inbox?tab=calls", color: "text-emerald-400", bgColor: "bg-emerald-500/15" },
          { label: "Knowledge Score", value: `${aiScore}%`, icon: Bot, href: "/app/business-brain", color: "text-primary", bgColor: "bg-primary/15", tooltip: "How much your AI knows about your business. Add FAQs, services, and policies to improve." },
        ];
      case "dispatch":
        return [
          { label: "Jobs Pending", value: jobsPending, icon: Truck, href: "/app/dispatch", color: "text-sky-400", bgColor: "bg-sky-500/15" },
          { label: "Calls Today", value: callsToday, icon: Phone, href: "/app/inbox?tab=calls", color: "text-emerald-400", bgColor: "bg-emerald-500/15" },
          { label: "Leads", value: bookingsWeek, icon: Users, href: "/app/inbox?tab=leads", color: "text-purple-400", bgColor: "bg-purple-500/15" },
          { label: "Knowledge Score", value: `${aiScore}%`, icon: Bot, href: "/app/business-brain", color: "text-primary", bgColor: "bg-primary/15", tooltip: "How much your AI knows about your business. Add FAQs, services, and policies to improve." },
        ];
      case "medical":
        return [
          { label: "Intakes Today", value: intakesToday, icon: Stethoscope, href: "/app/medical-intake", color: "text-rose-400", bgColor: "bg-rose-500/15" },
          { label: terms.bookingsMetricLabel, value: bookingsWeek, icon: Calendar, href: "/app/bookings", color: "text-blue-400", bgColor: "bg-blue-500/15" },
          { label: "Calls Today", value: callsToday, icon: Phone, href: "/app/inbox?tab=calls", color: "text-emerald-400", bgColor: "bg-emerald-500/15" },
          { label: "Knowledge Score", value: `${aiScore}%`, icon: Bot, href: "/app/business-brain", color: "text-primary", bgColor: "bg-primary/15", tooltip: "How much your AI knows about your business. Add FAQs, services, and policies to improve." },
        ];
      case "service":
      case "general":
      default:
        return [
          { label: "Calls Today", value: callsToday, icon: Phone, href: "/app/inbox?tab=calls", color: "text-emerald-400", bgColor: "bg-emerald-500/15" },
          { label: terms.bookingsMetricLabel, value: bookingsWeek, icon: Calendar, href: "/app/bookings", color: "text-blue-400", bgColor: "bg-blue-500/15" },
          { label: "This Week", value: bookingsWeek > 0 ? `+${bookingsWeek}` : "0", icon: TrendingUp, href: "/app/inbox?tab=leads", color: "text-purple-400", bgColor: "bg-purple-500/15" },
          { label: "Knowledge Score", value: `${aiScore}%`, icon: Bot, href: "/app/business-brain", color: "text-primary", bgColor: "bg-primary/15", tooltip: "How much your AI knows about your business. Add FAQs, services, and policies to improve." },
        ];
    }
  };

  const metrics = getMetrics();

  return (
    <TooltipProvider>
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 md:gap-4">
        {metrics.map((metric, index) => {
          const Icon = metric.icon;
          const cardContent = (
            <Card 
              key={metric.label}
              variant="interactive"
              className={cn(
                "group animate-fade-in",
                `stagger-${index + 1}`
              )}
              onClick={() => navigate(metric.href)}
            >
              <CardContent className="py-4 px-4">
                <div className="flex items-center gap-3">
                  <div className={cn(
                    "h-10 w-10 rounded-xl flex items-center justify-center shrink-0 transition-all duration-300",
                    metric.bgColor,
                    "group-hover:scale-110"
                  )}>
                    <Icon className={cn("h-5 w-5", metric.color)} />
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="text-2xl font-bold truncate tabular-nums">{metric.value}</p>
                    <p className="text-xs text-muted-foreground truncate flex items-center gap-1">
                      {metric.label}
                      {metric.tooltip && <HelpCircle className="h-3 w-3 opacity-40" />}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>
          );

          if (metric.tooltip) {
            return (
              <Tooltip key={metric.label}>
                <TooltipTrigger asChild>
                  {cardContent}
                </TooltipTrigger>
                <TooltipContent side="bottom" className="max-w-xs">
                  <p className="text-xs">{metric.tooltip}</p>
                </TooltipContent>
              </Tooltip>
            );
          }

          return cardContent;
        })}
      </div>
    </TooltipProvider>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useAIReadinessV2 } from "@/hooks/useAIReadinessV2";
import { useKnowledgeConflicts } from "@/hooks/useKnowledgeConflicts";
import { useKnowledgeUploads } from "@/hooks/useKnowledgeUploads";
import { useUsage } from "@/hooks/useUsage";
import { useSubscription } from "@/hooks/useSubscription";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import {
  AlertTriangle,
  ChevronDown,
  ChevronUp,
  AlertCircle,
  FileWarning,
  Upload,
  CreditCard,
  ExternalLink,
} from "lucide-react";
import { Link } from "react-router-dom";
import { cn } from "@/lib/utils";

interface Alert {
  id: string;
  type: "critical" | "warning" | "info";
  icon: typeof AlertTriangle;
  title: string;
  description: string;
  actionLabel?: string;
  actionLink?: string;
  count?: number;
}

/**
 * UnifiedAlertBanner consolidates multiple dashboard alerts into a single expandable panel.
 * Priority order: Usage (billing) > Knowledge Conflicts > Readiness > Uploads
 */
export function UnifiedAlertBanner() {
  const [isExpanded, setIsExpanded] = useState(false);
  const { tenant } = useAuth();

  // Gather alerts from various sources (V2 readiness — V1 was deprecated)
  const { score: readinessScore, p0Flags } = useAIReadinessV2();
  const { conflicts } = useKnowledgeConflicts();
  const { uploads, processingCount } = useKnowledgeUploads();
  
  // Pending uploads are those still processing or uploading
  const pendingUploads = uploads.filter(u => u.status === "processing" || u.status === "uploading");

  // Usage tracking
  const { planSku, hasVoice, hasSms } = useSubscription(tenant?.id || null);
  const { usage } = useUsage(tenant?.id || null, planSku);

  const alerts: Alert[] = [];

  // 1. Usage alert (highest priority - billing impact)
  const usagePercent = Math.max(usage?.voicePercentUsed || 0, usage?.smsPercentUsed || 0);
  const isNearLimit = usagePercent >= 80;

  if (isNearLimit) {
    alerts.push({
      id: "usage",
      type: usagePercent >= 95 ? "critical" : "warning",
      icon: CreditCard,
      title: usagePercent >= 95 ? "Usage limit almost reached" : "Approaching usage limit",
      description: `You've used ${usagePercent}% of your monthly allowance. ${usagePercent >= 95 ? "Calls may be limited soon." : "Consider upgrading your plan."}`,
      actionLabel: "Manage Plan",
      actionLink: "/app/go-live",
    });
  }

  // 2. Knowledge conflicts (data integrity)
  if (conflicts && conflicts.length > 0) {
    alerts.push({
      id: "conflicts",
      type: "warning",
      icon: FileWarning,
      title: "Knowledge conflicts detected",
      description: `${conflicts.length} piece${conflicts.length > 1 ? "s" : ""} of conflicting information need your review.`,
      actionLabel: "Resolve Conflicts",
      actionLink: "/app/business-brain#conflicts",
      count: conflicts.length,
    });
  }

  // 3. AI Readiness — handled inline in AgentControlPanel, skip here

  // 4. Pending uploads (lowest priority)
  if (pendingUploads && pendingUploads.length > 0) {
    alerts.push({
      id: "uploads",
      type: "info",
      icon: Upload,
      title: "Knowledge uploads pending review",
      description: `${pendingUploads.length} upload${pendingUploads.length > 1 ? "s" : ""} ready for your approval.`,
      actionLabel: "Review Uploads",
      actionLink: "/app/business-brain#uploads",
      count: pendingUploads.length,
    });
  }

  // Don't render if no alerts
  if (alerts.length === 0) {
    return null;
  }

  const primaryAlert = alerts[0];
  const secondaryAlerts = alerts.slice(1);
  const hasCritical = alerts.some((a) => a.type === "critical");

  const PrimaryIcon = primaryAlert.icon;

  return (
    <Card
      className={cn(
        "border-l-4",
        "backdrop-blur-sm border-border/30",
        hasCritical
          ? "border-l-destructive bg-destructive/5"
          : primaryAlert.type === "warning"
            ? "border-l-amber-500 bg-amber-50/50 dark:bg-amber-950/20"
            : "border-l-blue-500 bg-blue-50/50 dark:bg-blue-950/20"
      )}
    >
      <Collapsible open={isExpanded} onOpenChange={setIsExpanded}>
        <CardContent className="p-4">
          {/* Primary Alert */}
          <div className="flex items-start gap-3">
            <div
              className={cn(
                "flex h-9 w-9 items-center justify-center rounded-full shrink-0",
                hasCritical
                  ? "bg-destructive/10 text-destructive"
                  : primaryAlert.type === "warning"
                    ? "bg-amber-500/10 text-amber-600"
                    : "bg-blue-500/10 text-blue-600"
              )}
            >
              <PrimaryIcon className="h-5 w-5" />
            </div>

            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <p className="font-medium text-sm">{primaryAlert.title}</p>
                {alerts.length > 1 && (
                  <Badge variant="secondary" className="text-xs">
                    +{alerts.length - 1} more
                  </Badge>
                )}
              </div>
              <p className="text-xs text-muted-foreground mt-0.5">{primaryAlert.description}</p>
            </div>

            <div className="flex items-center gap-2 shrink-0">
              {primaryAlert.actionLink && (
                <Button asChild size="sm" variant={hasCritical ? "destructive" : "outline"}>
                  <Link to={primaryAlert.actionLink}>
                    {primaryAlert.actionLabel}
                    <ExternalLink className="ml-1.5 h-3 w-3" />
                  </Link>
                </Button>
              )}

              {secondaryAlerts.length > 0 && (
                <CollapsibleTrigger asChild>
                  <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                    {isExpanded ? (
                      <ChevronUp className="h-4 w-4" />
                    ) : (
                      <ChevronDown className="h-4 w-4" />
                    )}
                  </Button>
                </CollapsibleTrigger>
              )}
            </div>
          </div>

          {/* Secondary Alerts (collapsible) */}
          <CollapsibleContent>
            {secondaryAlerts.length > 0 && (
              <div className="mt-4 pt-4 border-t border-border/20 space-y-3">
                {secondaryAlerts.map((alert) => {
                  const AlertIcon = alert.icon;
                  return (
                    <div key={alert.id} className="flex items-center gap-3">
                      <AlertIcon
                        className={cn(
                          "h-4 w-4 shrink-0",
                          alert.type === "critical"
                            ? "text-destructive"
                            : alert.type === "warning"
                              ? "text-amber-600"
                              : "text-blue-600"
                        )}
                      />
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium">{alert.title}</p>
                        <p className="text-xs text-muted-foreground truncate">{alert.description}</p>
                      </div>
                      {alert.actionLink && (
                        <Button asChild size="sm" variant="ghost" className="shrink-0">
                          <Link to={alert.actionLink}>{alert.actionLabel}</Link>
                        </Button>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </CollapsibleContent>
        </CardContent>
      </Collapsible>
    </Card>
  );
}

import { useNavigate } from "react-router-dom";
import { useLeads } from "@/hooks/useLeads";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Users, ArrowRight, Phone, UserCheck, UserX } from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { cn } from "@/lib/utils";
import { ROIPerformanceWidget } from "../ROIPerformanceWidget";
import { LeadRecoveryWidget } from "../LeadRecoveryWidget";

const statusStyles: Record<string, { bg: string; text: string }> = {
  new: { bg: "bg-blue-500/10", text: "text-blue-700 dark:text-blue-400" },
  contacted: { bg: "bg-amber-500/10", text: "text-amber-700 dark:text-amber-400" },
  qualified: { bg: "bg-purple-500/10", text: "text-purple-700 dark:text-purple-400" },
  booked: { bg: "bg-emerald-500/10", text: "text-emerald-700 dark:text-emerald-400" },
  won: { bg: "bg-success/10", text: "text-success" },
  lost: { bg: "bg-muted", text: "text-muted-foreground" },
};

export function CallbackDashboardLayout() {
  const navigate = useNavigate();
  const { leads, stats } = useLeads();

  // Hot leads = new + has phone
  const hotLeads = leads
    .filter((l) => l.status === "new" && l.phone)
    .slice(0, 5);

  const followUpCount = leads.filter(
    (l) => l.status === "contacted" || l.status === "qualified"
  ).length;

  return (
    <div className="space-y-6">
      {/* Lead Funnel Summary */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <FunnelCard label="Hot Leads" value={hotLeads.length} icon={Users} color="text-blue-600" />
        <FunnelCard label="Follow-up" value={followUpCount} icon={Phone} color="text-amber-600" />
        <FunnelCard label="Won" value={stats.won} icon={UserCheck} color="text-emerald-600" />
        <FunnelCard label="Total" value={stats.total} icon={Users} color="text-muted-foreground" />
      </div>

      {/* Hot Leads List + Quick Action */}
      <div className="grid gap-6 lg:grid-cols-[1fr_auto]">
        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-3">
            <CardTitle className="text-base font-semibold">Hot Leads</CardTitle>
            <Button
              variant="ghost"
              size="sm"
              className="text-xs"
              onClick={() => navigate("/app/inbox?tab=leads")}
            >
              View All
              <ArrowRight className="h-3 w-3 ml-1" />
            </Button>
          </CardHeader>
          <CardContent className="pt-0">
            {hotLeads.length === 0 ? (
              <p className="text-sm text-muted-foreground py-6 text-center">
                No hot leads right now. New calls will appear here.
              </p>
            ) : (
              <div className="space-y-2">
                {hotLeads.map((lead) => {
                  const styles = statusStyles[lead.status] || statusStyles.new;
                  return (
                    <div
                      key={lead.id}
                      className="flex items-center gap-3 p-3 rounded-lg border hover:bg-muted/50 cursor-pointer transition-colors"
                      onClick={() => navigate("/app/inbox?tab=leads")}
                    >
                      <div className={cn("w-8 h-8 rounded-full flex items-center justify-center shrink-0", styles.bg, styles.text)}>
                        <Users className="w-4 h-4" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium truncate">{lead.full_name}</p>
                        <p className="text-xs text-muted-foreground">{lead.phone}</p>
                      </div>
                      <span className="text-xs text-muted-foreground shrink-0">
                        {formatDistanceToNow(new Date(lead.created_at), { addSuffix: true })}
                      </span>
                    </div>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Quick Action */}
        <Card className="flex flex-col items-center justify-center p-6 min-w-[200px]">
          <Users className="h-8 w-8 text-primary mb-3" />
          <p className="text-sm font-medium mb-1">View All Leads</p>
          <p className="text-xs text-muted-foreground text-center mb-4">
            Manage and convert your leads
          </p>
          <Button size="sm" onClick={() => navigate("/app/inbox?tab=leads")}>
            Go to Leads
          </Button>
        </Card>
      </div>

      <ROIPerformanceWidget />
      <LeadRecoveryWidget />
    </div>
  );
}

function FunnelCard({
  label,
  value,
  icon: Icon,
  color,
}: {
  label: string;
  value: number;
  icon: React.ElementType;
  color: string;
}) {
  return (
    <Card>
      <CardContent className="p-4">
        <div className="flex items-center gap-2 mb-2">
          <Icon className={cn("h-4 w-4", color)} />
          <span className="text-xs font-medium text-muted-foreground">{label}</span>
        </div>
        <p className="text-2xl font-bold tracking-tight tabular-nums">{value}</p>
      </CardContent>
    </Card>
  );
}

import { Car, Users, TrendingUp, CalendarCheck, Warehouse } from "lucide-react";
import { QuickActionButton } from "../widgets/QuickActionButton";
import { ROIPerformanceWidget } from "../ROIPerformanceWidget";
import { LeadRecoveryWidget } from "../LeadRecoveryWidget";
import { useTestDrives } from "@/hooks/useTestDrives";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { format, parseISO } from "date-fns";
import { useSalesInventory } from "@/hooks/useSalesInventory";

export function SalesDashboardLayout() {
  const { tenant } = useAuth();
  const { stats: driveStats, testDrives } = useTestDrives();
  const { stats: inventoryStats } = useSalesInventory();

  // Get hot leads count
  const { data: hotLeadsCount = 0 } = useQuery({
    queryKey: ["hot-leads-count", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count } = await (supabase as any)
        .from("leads")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .eq("lead_score", "hot");
      return count ?? 0;
    },
    enabled: !!tenant?.id,
  });

  // Today's test drives
  const todayDrives = testDrives.filter((d) => {
    if (!d.scheduled_at) return false;
    const date = new Date(d.scheduled_at);
    const now = new Date();
    return (
      date.getFullYear() === now.getFullYear() &&
      date.getMonth() === now.getMonth() &&
      date.getDate() === now.getDate()
    );
  });

  return (
    <div className="space-y-6">
      {/* Stats Row */}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <Card>
          <CardContent className="p-4 flex items-center gap-3">
            <div className="p-2 rounded-full bg-primary/10">
              <Car className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold">{driveStats.today}</p>
              <p className="text-xs text-muted-foreground">Test Drives Today</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 flex items-center gap-3">
            <div className="p-2 rounded-full bg-primary/10">
              <CalendarCheck className="h-5 w-5 text-primary" />
            </div>
            <div>
              <p className="text-2xl font-bold">{driveStats.thisWeek}</p>
              <p className="text-xs text-muted-foreground">This Week</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 flex items-center gap-3">
            <div className="p-2 rounded-full bg-accent">
              <TrendingUp className="h-5 w-5 text-accent-foreground" />
            </div>
            <div>
              <p className="text-2xl font-bold">{hotLeadsCount}</p>
              <p className="text-xs text-muted-foreground">Hot Leads</p>
            </div>
          </CardContent>
        </Card>
         <Card>
          <CardContent className="p-4 flex items-center gap-3">
            <div className="p-2 rounded-full bg-secondary">
              <Warehouse className="h-5 w-5 text-secondary-foreground" />
            </div>
            <div>
              <p className="text-2xl font-bold">{inventoryStats.available}</p>
              <p className="text-xs text-muted-foreground">Vehicles Available</p>
            </div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4 flex items-center gap-3">
            <div className="p-2 rounded-full bg-secondary">
              <Users className="h-5 w-5 text-secondary-foreground" />
            </div>
            <div>
              <p className="text-2xl font-bold">{driveStats.pending}</p>
              <p className="text-xs text-muted-foreground">Pending Appointments</p>
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Today's Schedule + Quick Actions */}
      <div className="grid gap-6 lg:grid-cols-[1fr_auto]">
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-2 mb-3">
              <Car className="h-4 w-4 text-primary" />
              <p className="text-sm font-medium">Today's Test Drives</p>
              <Badge variant="secondary" className="text-xs ml-auto">
                {todayDrives.length} scheduled
              </Badge>
            </div>
            {todayDrives.length === 0 ? (
              <p className="text-sm text-muted-foreground">No test drives scheduled for today</p>
            ) : (
              <div className="flex gap-2 overflow-x-auto pb-1">
                {todayDrives.map((d) => (
                  <div
                    key={d.id}
                    className="flex-shrink-0 rounded-lg border p-2.5 min-w-[140px] bg-primary/5 border-primary/20"
                  >
                    <p className="text-xs font-semibold tabular-nums">
                      {d.scheduled_at ? format(parseISO(d.scheduled_at), "h:mm a") : "TBD"}
                    </p>
                    <p className="text-xs font-medium truncate mt-1">
                      {d.customer?.full_name || "Walk-in"}
                    </p>
                    <p className="text-[11px] text-muted-foreground truncate">
                      {[d.vehicle_year, d.vehicle_make, d.vehicle_model].filter(Boolean).join(" ") || "Vehicle TBD"}
                    </p>
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        <div className="space-y-2">
          <QuickActionButton
            label="View Inventory"
            description="Browse & sync vehicle inventory"
            href="/app/sales-inventory"
            icon={Warehouse}
          />
          <QuickActionButton
            label="View Test Drives"
            description="Manage all test drive appointments"
            href="/app/test-drives"
            icon={Car}
          />
          <QuickActionButton
            label="View Pipeline"
            description="Sales pipeline overview"
            href="/app/sales-pipeline"
            icon={TrendingUp}
          />
        </div>
      </div>

      <ROIPerformanceWidget />
      <LeadRecoveryWidget />
    </div>
  );
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { AlertTriangle, Database, Zap, XCircle } from "lucide-react";
import { cn } from "@/lib/utils";

export type PreviewSource = "variables" | "snapshot" | "missing";

interface PreviewCardProps {
  title: string;
  value: string | null | undefined;
  source: PreviewSource;
  icon?: React.ReactNode;
  className?: string;
}

const sourceConfig: Record<PreviewSource, { label: string; icon: React.ReactNode; variant: "default" | "secondary" | "destructive" }> = {
  variables: {
    label: "Variables",
    icon: <Zap className="h-3 w-3" />,
    variant: "default",
  },
  snapshot: {
    label: "Snapshot",
    icon: <Database className="h-3 w-3" />,
    variant: "secondary",
  },
  missing: {
    label: "Missing",
    icon: <XCircle className="h-3 w-3" />,
    variant: "destructive",
  },
};

export function PreviewCard({ title, value, source, icon, className }: PreviewCardProps) {
  const config = sourceConfig[source];
  const isEmpty = !value || value.trim() === "";
  const effectiveSource = isEmpty ? "missing" : source;
  const effectiveConfig = sourceConfig[effectiveSource];

  return (
    <Card className={cn(
      "transition-all",
      effectiveSource === "missing" && "border-destructive/30 bg-destructive/5",
      className
    )}>
      <CardHeader className="pb-2 pt-4 px-4">
        <CardTitle className="text-sm font-medium flex items-center justify-between">
          <div className="flex items-center gap-2">
            {icon}
            {title}
          </div>
          <Badge 
            variant={effectiveConfig.variant} 
            className="text-xs gap-1 font-normal"
          >
            {effectiveConfig.icon}
            {effectiveConfig.label}
          </Badge>
        </CardTitle>
      </CardHeader>
      <CardContent className="px-4 pb-4">
        {isEmpty ? (
          <div className="flex items-center gap-2 text-destructive text-sm">
            <AlertTriangle className="h-4 w-4" />
            <span>Missing — AI may ask extra questions</span>
          </div>
        ) : (
          <p className="text-sm text-muted-foreground line-clamp-4 whitespace-pre-wrap">
            {value}
          </p>
        )}
      </CardContent>
    </Card>
  );
}

import { Phone, MoreHorizontal, ChevronRight, MapPin, Navigation, Truck, Clock, ChevronDown } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  DropdownMenuLabel,
} from "@/components/ui/dropdown-menu";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { cn } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";

interface DispatchJob {
  id: string;
  job_number?: string;
  status: string;
  priority: string;
  customer_name: string | null;
  customer_phone: string | null;
  pickup_address: string | null;
  dropoff_address?: string | null;
  job_type?: string | null;
  description?: string | null;
  notes?: string | null;
  price_cents?: number | null;
  estimated_duration_minutes?: number | null;
  assigned_crew: string | null;
  assigned_vehicle: string | null;
  created_at: string;
  customers?: { full_name: string; phone_e164: string } | null;
}

interface DispatchCommandTableProps {
  jobs: DispatchJob[];
  onAssign: (job: DispatchJob) => void;
  onUpdateStatus: (job: DispatchJob, newStatus: string) => void;
  onCall: (job: DispatchJob) => void;
  onViewDetails: (job: DispatchJob) => void;
}

const priorityConfig: Record<string, { label: string; className: string; rowClass: string }> = {
  urgent: { 
    label: "Urgent", 
    className: "bg-destructive text-destructive-foreground",
    rowClass: "bg-destructive/5 hover:bg-destructive/10"
  },
  high: { 
    label: "High", 
    className: "bg-warning/15 text-warning border-warning/30",
    rowClass: ""
  },
  normal: { 
    label: "Normal", 
    className: "bg-muted text-muted-foreground",
    rowClass: ""
  },
  low: { 
    label: "Low", 
    className: "bg-muted/50 text-muted-foreground",
    rowClass: ""
  },
};

const statusConfig: Record<string, { label: string; className: string }> = {
  pending: { label: "Pending", className: "border-warning text-warning bg-warning/10" },
  assigned: { label: "Assigned", className: "border-info text-info bg-info/10" },
  en_route: { label: "En Route", className: "border-primary text-primary bg-primary/10" },
  on_site: { label: "On Site", className: "border-success text-success bg-success/10" },
  completed: { label: "Completed", className: "border-muted-foreground text-muted-foreground" },
  cancelled: { label: "Cancelled", className: "border-destructive/30 text-destructive" },
};

export function DispatchCommandTable({
  jobs,
  onAssign,
  onUpdateStatus,
  onCall,
  onViewDetails,
}: DispatchCommandTableProps) {
  const getNextStatus = (currentStatus: string): string | null => {
    const flow: Record<string, string> = {
      pending: "assigned",
      assigned: "en_route",
      en_route: "on_site",
      on_site: "completed",
    };
    return flow[currentStatus] || null;
  };

  const getNextStatusLabel = (currentStatus: string): string | null => {
    const labels: Record<string, string> = {
      pending: "Assign",
      assigned: "Start Route",
      en_route: "Arrived",
      on_site: "Complete",
    };
    return labels[currentStatus] || null;
  };

  const truncateAddress = (address: string | null, maxLength = 28) => {
    if (!address) return "—";
    if (address.length <= maxLength) return address;
    return address.slice(0, maxLength) + "…";
  };

  return (
    <div className="rounded-lg border bg-card overflow-x-auto">
      <Table className="w-full">
        <TableHeader>
          <TableRow className="hover:bg-transparent bg-muted/30">
            <TableHead className="w-[80px] whitespace-nowrap">Job #</TableHead>
            <TableHead className="w-[110px] whitespace-nowrap">Customer</TableHead>
            <TableHead className="whitespace-nowrap">Pickup</TableHead>
            <TableHead className="hidden 2xl:table-cell whitespace-nowrap">Drop-off</TableHead>
            <TableHead className="w-[60px] whitespace-nowrap">Type</TableHead>
            <TableHead className="w-[60px] hidden xl:table-cell text-right whitespace-nowrap">Price</TableHead>
            <TableHead className="w-[70px] whitespace-nowrap">Priority</TableHead>
            <TableHead className="w-[85px] whitespace-nowrap">Status</TableHead>
            <TableHead className="w-[65px] hidden xl:table-cell whitespace-nowrap">Time</TableHead>
            <TableHead className="w-[40px] whitespace-nowrap"></TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {jobs.map((job) => {
            const priority = priorityConfig[job.priority] || priorityConfig.normal;
            const status = statusConfig[job.status] || statusConfig.pending;
            const nextStatus = getNextStatus(job.status);
            const nextLabel = getNextStatusLabel(job.status);

            return (
              <TableRow
                key={job.id}
                className={cn(
                  "cursor-pointer transition-colors hover:bg-muted/20",
                  priority.rowClass
                )}
                onClick={() => onViewDetails(job)}
              >
                {/* Job Number */}
                <TableCell className="font-mono text-xs font-medium">
                  {job.job_number || job.id.slice(0, 8)}
                </TableCell>

                {/* Customer */}
                <TableCell>
                  <div className="flex flex-col gap-0.5">
                    <span className="font-medium text-sm truncate block">
                      {job.customer_name || job.customers?.full_name || "Unknown"}
                    </span>
                    {job.customer_phone && (
                      <Button
                        variant="link"
                        size="sm"
                        className="h-auto p-0 text-xs text-muted-foreground justify-start"
                        onClick={(e) => {
                          e.stopPropagation();
                          onCall(job);
                        }}
                      >
                        <Phone className="h-3 w-3 mr-1" />
                        {job.customer_phone.replace(/(\+1)(\d{3})(\d{3})(\d{4})/, "$2-$3-$4")}
                      </Button>
                    )}
                  </div>
                </TableCell>

                {/* Pickup Address */}
                <TableCell>
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <div className="flex items-center gap-1.5">
                        <MapPin className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                        <span className="text-sm truncate block">
                          {truncateAddress(job.pickup_address)}
                        </span>
                      </div>
                    </TooltipTrigger>
                    {job.pickup_address && (
                      <TooltipContent side="bottom" className="max-w-xs">
                        {job.pickup_address}
                      </TooltipContent>
                    )}
                  </Tooltip>
                </TableCell>

                {/* Dropoff Address */}
                <TableCell className="hidden 2xl:table-cell">
                  {job.dropoff_address ? (
                    <Tooltip>
                      <TooltipTrigger asChild>
                        <div className="flex items-center gap-1.5">
                          <Navigation className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                          <span className="text-sm truncate block">
                            {truncateAddress(job.dropoff_address, 24)}
                          </span>
                        </div>
                      </TooltipTrigger>
                      <TooltipContent side="bottom" className="max-w-xs">
                        {job.dropoff_address}
                      </TooltipContent>
                    </Tooltip>
                  ) : (
                    <span className="text-muted-foreground">—</span>
                  )}
                </TableCell>

                {/* Service Type */}
                <TableCell>
                  <span className="text-sm">{job.job_type || "Service"}</span>
                </TableCell>

                {/* Price */}
                <TableCell className="hidden xl:table-cell text-right">
                  {job.price_cents !== null && job.price_cents !== undefined ? (
                    <span className="text-sm font-medium tabular-nums">
                      ${(job.price_cents / 100).toFixed(0)}
                    </span>
                  ) : (
                    <span className="text-muted-foreground text-sm">—</span>
                  )}
                </TableCell>

                {/* Priority */}
                <TableCell>
                  <Badge variant="outline" className={cn("text-xs", priority.className)}>
                    {priority.label}
                  </Badge>
                </TableCell>

                {/* Status - Clickable Dropdown */}
                <TableCell onClick={(e) => e.stopPropagation()}>
                  <DropdownMenu>
                    <DropdownMenuTrigger asChild>
                      <Button
                        variant="ghost"
                        size="sm"
                        className={cn(
                          "h-7 px-2 text-xs gap-1 font-normal",
                          status.className,
                          "border hover:opacity-80"
                        )}
                      >
                        {status.label}
                        <ChevronDown className="h-3 w-3 opacity-60" />
                      </Button>
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start" className="w-36">
                      <DropdownMenuLabel className="text-xs">Change Status</DropdownMenuLabel>
                      <DropdownMenuSeparator />
                      {Object.entries(statusConfig).map(([key, config]) => (
                        <DropdownMenuItem
                          key={key}
                          onClick={() => {
                            if (key === "assigned" && job.status === "pending") {
                              onAssign(job);
                            } else {
                              onUpdateStatus(job, key);
                            }
                          }}
                          className={cn(
                            "text-xs",
                            job.status === key && "bg-muted font-medium"
                          )}
                        >
                          <Badge
                            variant="outline"
                            className={cn("h-4 w-4 p-0 mr-2 shrink-0", config.className)}
                          />
                          {config.label}
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                </TableCell>

                {/* Time */}
                <TableCell className="hidden xl:table-cell">
                  <div className="flex items-center gap-1 text-xs text-muted-foreground">
                    <Clock className="h-3 w-3" />
                    {formatDistanceToNow(new Date(job.created_at), { addSuffix: false })}
                  </div>
                </TableCell>

                {/* Actions */}
                <TableCell>
                  <div onClick={(e) => e.stopPropagation()}>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon" className="h-7 w-7">
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        <DropdownMenuItem onClick={() => onViewDetails(job)}>
                          View Details
                        </DropdownMenuItem>
                        {nextStatus && nextLabel && (
                          <DropdownMenuItem
                            onClick={() => {
                              if (job.status === "pending") {
                                onAssign(job);
                              } else {
                                onUpdateStatus(job, nextStatus);
                              }
                            }}
                          >
                            <ChevronRight className="h-4 w-4 mr-2" />
                            {nextLabel}
                          </DropdownMenuItem>
                        )}
                        <DropdownMenuItem onClick={() => onCall(job)}>
                          <Phone className="h-4 w-4 mr-2" />
                          Call Customer
                        </DropdownMenuItem>
                        {job.status !== "cancelled" && job.status !== "completed" && (
                          <>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem
                              className="text-destructive"
                              onClick={() => onUpdateStatus(job, "cancelled")}
                            >
                              Cancel Job
                            </DropdownMenuItem>
                          </>
                        )}
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </div>
                </TableCell>
              </TableRow>
            );
          })}
        </TableBody>
      </Table>
    </div>
  );
}

import { MapPin, ArrowRight, Phone, AlertTriangle } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export const priorityColors: Record<string, string> = {
  urgent: "bg-destructive text-destructive-foreground",
  high: "bg-warning/10 text-warning border-warning/30",
  normal: "bg-muted text-muted-foreground border-border",
  low: "bg-muted/50 text-muted-foreground border-border",
};

export const statusColors: Record<string, string> = {
  pending: "border-warning text-warning",
  assigned: "border-info text-info",
  en_route: "border-primary text-primary",
  on_site: "border-success text-success",
  completed: "text-muted-foreground border-border",
  cancelled: "text-destructive border-destructive/30",
};

export const statusLabels: Record<string, string> = {
  pending: "Pending",
  assigned: "Assigned",
  en_route: "En Route",
  on_site: "On Site",
  completed: "Completed",
  cancelled: "Cancelled",
};

interface DispatchJobCardProps<T> {
  job: T & {
    id: string;
    job_number?: string;
    status: string;
    priority: string;
    customer_name: string | null;
    customer_phone: string | null;
    pickup_address: string | null;
    dropoff_address?: string | null;
    job_type?: string | null;
    notes?: string | null;
    price_cents?: number | null;
    total_distance_miles?: number | null;
    assigned_crew: string | null;
    assigned_vehicle: string | null;
    created_at: string;
  };
  onAssign?: (job: T) => void;
  onUpdateStatus?: (job: T, newStatus: string) => void;
  onCall?: (job: T) => void;
}

export function DispatchJobCard<T>({ job, onAssign, onUpdateStatus, onCall }: DispatchJobCardProps<T>) {
  return (
    <div
      className={cn(
        "rounded-lg border p-4 transition-all duration-200 hover:shadow-md hover:-translate-y-0.5 hover:border-border/60",
        job.priority === "urgent" && "border-destructive/40"
      )}
    >
      {/* Top: priority + job ID */}
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          {job.priority === "urgent" ? (
            <Badge className="bg-destructive text-destructive-foreground text-[11px] h-5 gap-1">
              <AlertTriangle className="h-3 w-3" />
              URGENT
            </Badge>
          ) : job.priority === "high" ? (
            <span className="h-2 w-2 rounded-full bg-warning shrink-0" />
          ) : null}
        </div>
        {job.job_number && (
          <span className="text-xs text-muted-foreground font-mono">#{job.job_number}</span>
        )}
      </div>

      {/* Service type */}
      {job.job_type && (
        <p className={cn("text-sm font-medium mb-2", job.priority === "low" && "text-muted-foreground")}>
          {job.job_type}
        </p>
      )}

      {/* Pickup / Dropoff */}
      <div className="space-y-1.5 mb-3 text-sm">
        <div className="flex items-start gap-2">
          <MapPin className="h-3.5 w-3.5 mt-0.5 shrink-0 text-muted-foreground" />
          <span className="line-clamp-1">{job.pickup_address || "No pickup address"}</span>
        </div>
        {job.dropoff_address && (
          <div className="flex items-start gap-2">
            <ArrowRight className="h-3.5 w-3.5 mt-0.5 shrink-0 text-muted-foreground" />
            <span className="line-clamp-1">{job.dropoff_address}</span>
          </div>
        )}
      </div>

      <div className="border-t border-border/30 pt-3 space-y-2">
        {/* Customer + phone */}
        <div className="flex items-center gap-2 text-sm">
          <span className="font-medium">{job.customer_name || "Unknown"}</span>
          {job.customer_phone && (
            <>
              <span className="text-muted-foreground">·</span>
              <span className="text-muted-foreground">{job.customer_phone}</span>
            </>
          )}
        </div>

        {/* Distance + price */}
        <div className="flex items-center gap-2 text-xs text-muted-foreground">
          {job.total_distance_miles != null && (
            <span>{job.total_distance_miles.toFixed(1)} mi</span>
          )}
          {job.total_distance_miles != null && job.price_cents != null && <span>·</span>}
          {job.price_cents != null && (
            <span>${(job.price_cents / 100).toFixed(0)}</span>
          )}
        </div>
      </div>

      {/* Actions */}
      <div className="flex gap-2 pt-3 mt-3 border-t border-border/30">
        <Button size="sm" variant="outline" className="gap-1.5" onClick={() => onCall?.(job)}>
          <Phone className="h-3.5 w-3.5" />
          Call
        </Button>
        {job.status === "pending" && (
          <Button size="sm" className="flex-1" onClick={() => onAssign?.(job)}>
            Assign Driver
          </Button>
        )}
        {job.status === "assigned" && (
          <Button size="sm" className="flex-1" onClick={() => onUpdateStatus?.(job as T, "en_route")}>
            Start Route
          </Button>
        )}
        {job.status === "en_route" && (
          <Button size="sm" className="flex-1" onClick={() => onUpdateStatus?.(job as T, "on_site")}>
            Arrived
          </Button>
        )}
        {job.status === "on_site" && (
          <Button size="sm" className="flex-1" onClick={() => onUpdateStatus?.(job as T, "completed")}>
            Complete
          </Button>
        )}
      </div>
    </div>
  );
}

import { formatDistanceToNow, format } from "date-fns";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import {
  Phone,
  MapPin,
  Navigation,
  Truck,
  User,
  Clock,
  DollarSign,
  FileText,
  ExternalLink,
  Copy,
  ChevronRight,
  Route,
  Calculator,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useToast } from "@/hooks/use-toast";

interface PriceBreakdown {
  base_price?: number;
  per_mile_rate?: number;
  distance_charge?: number;
  vehicle_modifier?: number;
  urgency_modifier?: number;
  total?: number;
  description?: string;
  [key: string]: unknown;
}

interface DispatchJob {
  id: string;
  job_number?: string;
  status: string;
  priority: string;
  customer_name: string | null;
  customer_phone: string | null;
  pickup_address: string | null;
  pickup_lat?: number | null;
  pickup_lng?: number | null;
  dropoff_address?: string | null;
  dropoff_lat?: number | null;
  dropoff_lng?: number | null;
  job_type?: string | null;
  description?: string | null;
  notes?: string | null;
  price_cents?: number | null;
  estimated_duration_minutes?: number | null;
  assigned_crew: string | null;
  assigned_vehicle: string | null;
  created_at: string;
  dispatched_at?: string | null;
  arrived_at?: string | null;
  completed_at?: string | null;
  customers?: { full_name: string; phone_e164: string } | null;
  // Distance & Pricing fields
  dispatch_distance_miles?: number | null;
  tow_distance_miles?: number | null;
  total_distance_miles?: number | null;
  service_tier?: string | null;
  pricing_note?: string | null;
  price_breakdown?: PriceBreakdown | null;
}

interface DispatchJobDetailsSheetProps {
  job: DispatchJob | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onAssign: (job: DispatchJob) => void;
  onUpdateStatus: (job: DispatchJob, status: string) => void;
  onCall: (job: DispatchJob) => void;
}

const statusConfig: Record<string, { label: string; className: string }> = {
  pending: { label: "Pending", className: "border-warning text-warning bg-warning/10" },
  assigned: { label: "Assigned", className: "border-info text-info bg-info/10" },
  en_route: { label: "En Route", className: "border-primary text-primary bg-primary/10" },
  on_site: { label: "On Site", className: "border-success text-success bg-success/10" },
  completed: { label: "Completed", className: "border-muted-foreground text-muted-foreground bg-muted" },
  cancelled: { label: "Cancelled", className: "border-destructive/30 text-destructive bg-destructive/10" },
};

const priorityConfig: Record<string, { label: string; className: string }> = {
  urgent: { label: "Urgent", className: "bg-destructive text-destructive-foreground" },
  high: { label: "High", className: "bg-warning/15 text-warning border-warning/30" },
  normal: { label: "Normal", className: "bg-muted text-muted-foreground" },
  low: { label: "Low", className: "bg-muted/50 text-muted-foreground" },
};

export function DispatchJobDetailsSheet({
  job,
  open,
  onOpenChange,
  onAssign,
  onUpdateStatus,
  onCall,
}: DispatchJobDetailsSheetProps) {
  const { toast } = useToast();

  if (!job) return null;

  const status = statusConfig[job.status] || statusConfig.pending;
  const priority = priorityConfig[job.priority] || priorityConfig.normal;
  
  const getNextStatus = (currentStatus: string): string | null => {
    const flow: Record<string, string> = {
      pending: "assigned",
      assigned: "en_route",
      en_route: "on_site",
      on_site: "completed",
    };
    return flow[currentStatus] || null;
  };

  const getNextStatusLabel = (currentStatus: string): string | null => {
    const labels: Record<string, string> = {
      pending: "Assign & Dispatch",
      assigned: "Mark En Route",
      en_route: "Mark Arrived",
      on_site: "Complete Job",
    };
    return labels[currentStatus] || null;
  };

  const nextStatus = getNextStatus(job.status);
  const nextLabel = getNextStatusLabel(job.status);

  const copyToClipboard = (text: string, label: string) => {
    navigator.clipboard.writeText(text);
    toast({ title: `${label} copied` });
  };

  const openInMaps = (address: string) => {
    const encoded = encodeURIComponent(address);
    window.open(`https://www.google.com/maps/search/?api=1&query=${encoded}`, "_blank");
  };

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full sm:max-w-lg overflow-y-auto">
        <SheetHeader className="pb-4">
          <div className="flex items-center justify-between">
            <SheetTitle className="text-lg">
              Job #{job.job_number || job.id.slice(0, 8)}
            </SheetTitle>
            <div className="flex items-center gap-2">
              <Badge variant="outline" className={cn("text-xs", priority.className)}>
                {priority.label}
              </Badge>
              <Badge variant="outline" className={cn("text-xs", status.className)}>
                {status.label}
              </Badge>
            </div>
          </div>
        </SheetHeader>

        <div className="space-y-6">
          {/* Quick Actions */}
          {nextStatus && nextLabel && (
            <div className="flex gap-2">
              <Button
                className="flex-1"
                onClick={() => {
                  if (job.status === "pending") {
                    onAssign(job);
                  } else {
                    onUpdateStatus(job, nextStatus);
                  }
                }}
              >
                <ChevronRight className="h-4 w-4 mr-2" />
                {nextLabel}
              </Button>
              {job.customer_phone && (
                <Button variant="outline" size="icon" onClick={() => onCall(job)}>
                  <Phone className="h-4 w-4" />
                </Button>
              )}
            </div>
          )}

          <Separator />

          {/* Customer Info */}
          <div className="space-y-3">
            <h4 className="text-sm font-semibold uppercase tracking-wide text-muted-foreground">
              Customer
            </h4>
            <div className="space-y-2">
              <div className="flex items-center gap-3">
                <User className="h-4 w-4 text-muted-foreground" />
                <span className="font-medium">
                  {job.customer_name || job.customers?.full_name || "Unknown"}
                </span>
              </div>
              {job.customer_phone && (
                <div className="flex items-center gap-3">
                  <Phone className="h-4 w-4 text-muted-foreground" />
                  <Button
                    variant="link"
                    className="h-auto p-0 text-primary"
                    onClick={() => onCall(job)}
                  >
                    {job.customer_phone}
                  </Button>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-6 w-6"
                    onClick={() => copyToClipboard(job.customer_phone!, "Phone")}
                  >
                    <Copy className="h-3 w-3" />
                  </Button>
                </div>
              )}
            </div>
          </div>

          <Separator />

          {/* Locations */}
          <div className="space-y-3">
            <h4 className="text-sm font-semibold uppercase tracking-wide text-muted-foreground">
              Locations
            </h4>
            <div className="space-y-4">
              {/* Pickup */}
              <div className="space-y-2">
                <div className="flex items-center gap-2 text-xs font-medium text-muted-foreground">
                  <MapPin className="h-3 w-3" />
                  PICKUP
                </div>
                {job.pickup_address ? (
                  <div className="flex items-start gap-2">
                    <p className="flex-1 text-sm">{job.pickup_address}</p>
                    <div className="flex gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7"
                        onClick={() => copyToClipboard(job.pickup_address!, "Address")}
                      >
                        <Copy className="h-3 w-3" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7"
                        onClick={() => openInMaps(job.pickup_address!)}
                      >
                        <ExternalLink className="h-3 w-3" />
                      </Button>
                    </div>
                  </div>
                ) : (
                  <p className="text-sm text-muted-foreground">Not provided</p>
                )}
              </div>

              {/* Dropoff */}
              {job.dropoff_address && (
                <div className="space-y-2">
                  <div className="flex items-center gap-2 text-xs font-medium text-muted-foreground">
                    <Navigation className="h-3 w-3" />
                    DROP-OFF
                  </div>
                  <div className="flex items-start gap-2">
                    <p className="flex-1 text-sm">{job.dropoff_address}</p>
                    <div className="flex gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7"
                        onClick={() => copyToClipboard(job.dropoff_address!, "Address")}
                      >
                        <Copy className="h-3 w-3" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7"
                        onClick={() => openInMaps(job.dropoff_address!)}
                      >
                        <ExternalLink className="h-3 w-3" />
                      </Button>
                    </div>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Distance & Pricing Section */}
          <Separator />
          <div className="space-y-3">
            <h4 className="text-sm font-semibold uppercase tracking-wide text-muted-foreground flex items-center gap-2">
              <Route className="h-4 w-4" />
              Distance & Pricing
            </h4>
            
            {/* Show guidance when no distance data is available */}
            {!job.dispatch_distance_miles && !job.tow_distance_miles && !job.price_breakdown && !job.pricing_note ? (
              <div className="p-3 rounded-lg bg-muted/50 border border-dashed border-muted-foreground/30">
                <p className="text-sm text-muted-foreground">
                  Distance and pricing data will appear here when jobs are created through AI calls with a base address configured in Business Brain → Coverage & ETA.
                </p>
              </div>
            ) : (
              <>
                {/* Distance Breakdown */}
                {(job.dispatch_distance_miles || job.tow_distance_miles) && (
                  <div className="p-3 rounded-lg bg-muted/50 space-y-2">
                    <p className="text-xs font-medium text-muted-foreground uppercase tracking-wide">Distance Breakdown</p>
                    <div className="grid grid-cols-2 gap-3">
                      {job.dispatch_distance_miles != null && (
                        <div className="space-y-0.5">
                          <p className="text-xs text-muted-foreground">Drive to Pickup</p>
                          <p className="text-sm font-semibold">{job.dispatch_distance_miles.toFixed(1)} mi</p>
                        </div>
                      )}
                      {job.tow_distance_miles != null && (
                        <div className="space-y-0.5">
                          <p className="text-xs text-muted-foreground">Pickup → Drop-off</p>
                          <p className="text-sm font-semibold">{job.tow_distance_miles.toFixed(1)} mi</p>
                        </div>
                      )}
                    </div>
                    {job.total_distance_miles != null && (
                      <div className="pt-2 border-t border-border/50 flex justify-between items-center">
                        <p className="text-xs text-muted-foreground">Total Trip</p>
                        <p className="text-sm font-bold">{job.total_distance_miles.toFixed(1)} mi</p>
                      </div>
                    )}
                  </div>
                )}

                {/* Service Tier Badge */}
                {job.service_tier && (
                  <div className="flex items-center gap-2">
                    <span className="text-xs text-muted-foreground">Service Tier:</span>
                    <Badge variant="outline" className="text-xs">
                      {job.service_tier}
                    </Badge>
                  </div>
                )}

                {/* Price Breakdown */}
                {job.price_breakdown && Object.keys(job.price_breakdown).length > 0 && (
                  <div className="p-3 rounded-lg border border-success/30 bg-success/5 space-y-2">
                    <div className="flex items-center gap-2">
                      <Calculator className="h-4 w-4 text-success" />
                      <p className="text-xs font-medium text-success uppercase tracking-wide">Price Breakdown</p>
                    </div>
                    <div className="space-y-1.5">
                      {job.price_breakdown.base_price != null && (
                        <div className="flex justify-between text-sm">
                          <span className="text-muted-foreground">Base Price</span>
                          <span className="font-medium">${job.price_breakdown.base_price.toFixed(2)}</span>
                        </div>
                      )}
                      {job.price_breakdown.distance_charge != null && job.price_breakdown.distance_charge > 0 && (
                        <div className="flex justify-between text-sm">
                          <span className="text-muted-foreground">
                            Distance Charge
                            {job.price_breakdown.per_mile_rate && (
                              <span className="text-xs ml-1">(${job.price_breakdown.per_mile_rate}/mi)</span>
                            )}
                          </span>
                          <span className="font-medium">${job.price_breakdown.distance_charge.toFixed(2)}</span>
                        </div>
                      )}
                      {job.price_breakdown.vehicle_modifier != null && job.price_breakdown.vehicle_modifier !== 0 && (
                        <div className="flex justify-between text-sm">
                          <span className="text-muted-foreground">Vehicle Adjustment</span>
                          <span className="font-medium">
                            {job.price_breakdown.vehicle_modifier > 0 ? '+' : ''}${job.price_breakdown.vehicle_modifier.toFixed(2)}
                          </span>
                        </div>
                      )}
                      {job.price_breakdown.urgency_modifier != null && job.price_breakdown.urgency_modifier !== 0 && (
                        <div className="flex justify-between text-sm">
                          <span className="text-muted-foreground">Urgency Fee</span>
                          <span className="font-medium">
                            +${job.price_breakdown.urgency_modifier.toFixed(2)}
                          </span>
                        </div>
                      )}
                      {job.price_breakdown.total != null && (
                        <div className="flex justify-between text-sm pt-2 border-t border-success/20">
                          <span className="font-semibold text-foreground">Total Quote</span>
                          <span className="font-bold text-success text-base">${job.price_breakdown.total.toFixed(2)}</span>
                        </div>
                      )}
                    </div>
                  </div>
                )}

                {/* Pricing Note from AI */}
                {job.pricing_note && (
                  <div className="p-3 rounded-lg bg-primary/5 border border-primary/20">
                    <p className="text-xs font-medium text-primary mb-1">AI Quote Given to Customer</p>
                    <p className="text-sm text-foreground">{job.pricing_note}</p>
                  </div>
                )}
              </>
            )}
          </div>

          <Separator />

          {/* Job Details */}
          <div className="space-y-3">
            <h4 className="text-sm font-semibold uppercase tracking-wide text-muted-foreground">
              Job Details
            </h4>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <p className="text-xs text-muted-foreground">Service Type</p>
                <p className="text-sm font-medium">{job.job_type || "General"}</p>
              </div>
              {job.price_cents !== null && job.price_cents !== undefined && (
                <div className="space-y-1">
                  <p className="text-xs text-muted-foreground">Final Price</p>
                  <div className="flex items-center gap-1">
                    <DollarSign className="h-4 w-4 text-success" />
                    <p className="text-sm font-semibold">${(job.price_cents / 100).toFixed(2)}</p>
                  </div>
                </div>
              )}
              {job.estimated_duration_minutes && (
                <div className="space-y-1">
                  <p className="text-xs text-muted-foreground">Est. Duration</p>
                  <div className="flex items-center gap-1">
                    <Clock className="h-4 w-4 text-muted-foreground" />
                    <p className="text-sm font-medium">{job.estimated_duration_minutes} min</p>
                  </div>
                </div>
              )}
            </div>
            {(job.description || job.notes) && (
              <div className="space-y-1 pt-2">
                <p className="text-xs text-muted-foreground">Notes</p>
                <div className="flex items-start gap-2 p-3 rounded-lg bg-muted/50">
                  <FileText className="h-4 w-4 mt-0.5 text-muted-foreground shrink-0" />
                  <p className="text-sm">{job.description || job.notes}</p>
                </div>
              </div>
            )}
          </div>

          {/* Assignment */}
          {(job.assigned_crew || job.assigned_vehicle) && (
            <>
              <Separator />
              <div className="space-y-3">
                <h4 className="text-sm font-semibold uppercase tracking-wide text-muted-foreground">
                  Assignment
                </h4>
                <div className="grid grid-cols-2 gap-4">
                  {job.assigned_crew && (
                    <div className="space-y-1">
                      <p className="text-xs text-muted-foreground">Crew</p>
                      <div className="flex items-center gap-2">
                        <User className="h-4 w-4 text-muted-foreground" />
                        <p className="text-sm font-medium">{job.assigned_crew}</p>
                      </div>
                    </div>
                  )}
                  {job.assigned_vehicle && (
                    <div className="space-y-1">
                      <p className="text-xs text-muted-foreground">Vehicle</p>
                      <div className="flex items-center gap-2">
                        <Truck className="h-4 w-4 text-muted-foreground" />
                        <p className="text-sm font-medium">{job.assigned_vehicle}</p>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </>
          )}

          <Separator />

          {/* Timeline */}
          <div className="space-y-3">
            <h4 className="text-sm font-semibold uppercase tracking-wide text-muted-foreground">
              Timeline
            </h4>
            <div className="space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="text-muted-foreground">Created</span>
                <span>{format(new Date(job.created_at), "MMM d, h:mm a")}</span>
              </div>
              {job.dispatched_at && (
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Dispatched</span>
                  <span>{format(new Date(job.dispatched_at), "MMM d, h:mm a")}</span>
                </div>
              )}
              {job.arrived_at && (
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Arrived</span>
                  <span>{format(new Date(job.arrived_at), "MMM d, h:mm a")}</span>
                </div>
              )}
              {job.completed_at && (
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Completed</span>
                  <span>{format(new Date(job.completed_at), "MMM d, h:mm a")}</span>
                </div>
              )}
            </div>
          </div>

          {/* Cancel Button */}
          {job.status !== "cancelled" && job.status !== "completed" && (
            <>
              <Separator />
              <Button
                variant="outline"
                className="w-full text-destructive hover:text-destructive"
                onClick={() => onUpdateStatus(job, "cancelled")}
              >
                Cancel Job
              </Button>
            </>
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

import { useState, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { useToast } from "@/hooks/use-toast";
import { Camera, ImagePlus, X, Loader2, CheckCircle2 } from "lucide-react";
import { cn } from "@/lib/utils";

interface PhotoUploaderProps {
  tenantId: string;
  entityType: "impound" | "dispatch";
  entityId?: string;
  onPhotosChange?: (urls: string[]) => void;
  maxPhotos?: number;
  className?: string;
}

export function PhotoUploader({
  tenantId,
  entityType,
  entityId,
  onPhotosChange,
  maxPhotos = 5,
  className,
}: PhotoUploaderProps) {
  const [photos, setPhotos] = useState<string[]>([]);
  const [uploading, setUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);
  const { toast } = useToast();

  const uploadPhoto = async (file: File) => {
    if (photos.length >= maxPhotos) {
      toast({
        variant: "destructive",
        title: "Maximum photos reached",
        description: `You can only upload up to ${maxPhotos} photos.`,
      });
      return;
    }

    setUploading(true);
    try {
      const timestamp = Date.now();
      const ext = file.name.split(".").pop() || "jpg";
      const filePath = `${tenantId}/${entityType}/${entityId || "new"}/${timestamp}.${ext}`;

      const { error: uploadError } = await supabase.storage
        .from("dispatch-photos")
        .upload(filePath, file, {
          cacheControl: "3600",
          upsert: false,
        });

      if (uploadError) throw uploadError;

      const { data: urlData } = supabase.storage
        .from("dispatch-photos")
        .getPublicUrl(filePath);

      const newPhotos = [...photos, urlData.publicUrl];
      setPhotos(newPhotos);
      onPhotosChange?.(newPhotos);

      toast({
        title: "Photo uploaded",
        description: "Photo added successfully.",
      });
    } catch (error) {
      console.error("Upload error:", error);
      toast({
        variant: "destructive",
        title: "Upload failed",
        description: error instanceof Error ? error.message : "Failed to upload photo",
      });
    } finally {
      setUploading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      uploadPhoto(files[0]);
    }
    // Reset input value so the same file can be uploaded again
    e.target.value = "";
  };

  const removePhoto = (index: number) => {
    const newPhotos = photos.filter((_, i) => i !== index);
    setPhotos(newPhotos);
    onPhotosChange?.(newPhotos);
  };

  return (
    <div className={cn("space-y-4", className)}>
      {/* Photo Grid */}
      {photos.length > 0 && (
        <div className="grid grid-cols-3 gap-2">
          {photos.map((url, index) => (
            <div key={index} className="relative aspect-square rounded-lg overflow-hidden bg-muted">
              <img 
                src={url} 
                alt={`Photo ${index + 1}`} 
                className="w-full h-full object-cover"
              />
              <button
                onClick={() => removePhoto(index)}
                className="absolute top-1 right-1 h-6 w-6 bg-black/60 rounded-full flex items-center justify-center text-white hover:bg-black/80 transition-colors"
              >
                <X className="h-4 w-4" />
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Upload Buttons */}
      {photos.length < maxPhotos && (
        <div className="grid grid-cols-2 gap-3">
          {/* Camera Button */}
          <input
            ref={cameraInputRef}
            type="file"
            accept="image/*"
            capture="environment"
            onChange={handleFileChange}
            className="hidden"
          />
          <Button
            type="button"
            variant="outline"
            className="h-20 flex-col gap-2"
            onClick={() => cameraInputRef.current?.click()}
            disabled={uploading}
          >
            {uploading ? (
              <Loader2 className="h-6 w-6 animate-spin" />
            ) : (
              <Camera className="h-6 w-6" />
            )}
            <span className="text-xs font-medium">Take Photo</span>
          </Button>

          {/* Gallery Button */}
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            onChange={handleFileChange}
            className="hidden"
          />
          <Button
            type="button"
            variant="outline"
            className="h-20 flex-col gap-2"
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading}
          >
            {uploading ? (
              <Loader2 className="h-6 w-6 animate-spin" />
            ) : (
              <ImagePlus className="h-6 w-6" />
            )}
            <span className="text-xs font-medium">From Gallery</span>
          </Button>
        </div>
      )}

      {/* Photo Count */}
      <div className="flex items-center justify-between text-xs text-muted-foreground">
        <span className="flex items-center gap-1">
          {photos.length > 0 && <CheckCircle2 className="h-3.5 w-3.5 text-green-500" />}
          {photos.length} of {maxPhotos} photos
        </span>
        {photos.length === 0 && (
          <span className="text-muted-foreground/70">Optional but recommended</span>
        )}
      </div>
    </div>
  );
}

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Plus, Trash2, Save, Send, CreditCard, Loader2, Layers } from "lucide-react";
import { useEstimates, EstimateLineItem, PricingOption, EstimateWithCustomer } from "@/hooks/useEstimates";
import { useCustomers } from "@/hooks/useCustomers";
import { useFinancing, formatFinancingAmount } from "@/hooks/useFinancing";
import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";

interface EstimateBuilderProps {
  estimate?: EstimateWithCustomer | null;
  onSave: () => void;
  onCancel: () => void;
}

function generateId(): string {
  return Math.random().toString(36).substring(2, 15);
}

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);
}

const DEFAULT_PRICING_OPTIONS: PricingOption[] = [
  { id: generateId(), name: "Basic", description: "Essential services", line_items: [], total_cents: 0 },
  { id: generateId(), name: "Standard", description: "Recommended option", line_items: [], total_cents: 0 },
  { id: generateId(), name: "Premium", description: "Full service package", line_items: [], total_cents: 0 },
];

function LineItemsEditor({
  lineItems,
  onChange,
}: {
  lineItems: EstimateLineItem[];
  onChange: (items: EstimateLineItem[]) => void;
}) {
  const updateLineItem = (id: string, field: keyof EstimateLineItem, value: string | number) => {
    onChange(
      lineItems.map((item) => {
        if (item.id !== id) return item;
        const updated = { ...item, [field]: value };
        if (field === "quantity" || field === "unit_price_cents") {
          updated.total_cents = updated.quantity * updated.unit_price_cents;
        }
        return updated;
      })
    );
  };

  const addLineItem = () => {
    onChange([
      ...lineItems,
      { id: generateId(), name: "", description: "", quantity: 1, unit_price_cents: 0, total_cents: 0 },
    ]);
  };

  const removeLineItem = (id: string) => {
    if (lineItems.length > 1) {
      onChange(lineItems.filter((item) => item.id !== id));
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <Label>Line Items</Label>
        <Button variant="outline" size="sm" onClick={addLineItem}>
          <Plus className="h-4 w-4 mr-1" />
          Add Item
        </Button>
      </div>

      <Card>
        <CardContent className="p-0">
          <div className="grid grid-cols-12 gap-2 px-4 py-2 bg-muted/50 text-sm font-medium border-b">
            <div className="col-span-5">Description</div>
            <div className="col-span-2 text-center">Qty</div>
            <div className="col-span-2 text-right">Unit Price</div>
            <div className="col-span-2 text-right">Total</div>
            <div className="col-span-1"></div>
          </div>

          <div className="divide-y">
            {lineItems.map((item) => (
              <div key={item.id} className="grid grid-cols-12 gap-2 px-4 py-3 items-center">
                <div className="col-span-5">
                  <Input
                    placeholder="Item name"
                    value={item.name}
                    onChange={(e) => updateLineItem(item.id, "name", e.target.value)}
                    className="mb-1"
                  />
                  <Input
                    placeholder="Description (optional)"
                    value={item.description || ""}
                    onChange={(e) => updateLineItem(item.id, "description", e.target.value)}
                    className="text-sm"
                  />
                </div>
                <div className="col-span-2">
                  <Input
                    type="number"
                    min="1"
                    value={item.quantity}
                    onChange={(e) => updateLineItem(item.id, "quantity", parseInt(e.target.value) || 1)}
                    className="text-center"
                  />
                </div>
                <div className="col-span-2">
                  <Input
                    type="number"
                    min="0"
                    step="0.01"
                    placeholder="0.00"
                    value={(item.unit_price_cents / 100).toFixed(2)}
                    onChange={(e) =>
                      updateLineItem(item.id, "unit_price_cents", Math.round(parseFloat(e.target.value || "0") * 100))
                    }
                    className="text-right"
                  />
                </div>
                <div className="col-span-2 text-right font-medium">{formatCurrency(item.total_cents)}</div>
                <div className="col-span-1 flex justify-center">
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => removeLineItem(item.id)}
                    disabled={lineItems.length === 1}
                    className="text-muted-foreground hover:text-destructive"
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

export function EstimateBuilder({ estimate, onSave, onCancel }: EstimateBuilderProps) {
  const { createEstimate, updateEstimate, sendEstimate } = useEstimates();
  const { customers = [] } = useCustomers();
  const { isConnected: financingAvailable, createApplication } = useFinancing();

  // Form state
  const [title, setTitle] = useState(estimate?.title || "");
  const [customerId, setCustomerId] = useState(estimate?.customer_id || "");
  const [usePricingOptions, setUsePricingOptions] = useState(!!estimate?.pricing_options?.length);
  const [lineItems, setLineItems] = useState<EstimateLineItem[]>(
    estimate?.line_items || [
      { id: generateId(), name: "", description: "", quantity: 1, unit_price_cents: 0, total_cents: 0 },
    ]
  );
  const [pricingOptions, setPricingOptions] = useState<PricingOption[]>(
    estimate?.pricing_options || DEFAULT_PRICING_OPTIONS.map(opt => ({
      ...opt,
      id: generateId(),
      line_items: [{ id: generateId(), name: "", description: "", quantity: 1, unit_price_cents: 0, total_cents: 0 }],
    }))
  );
  const [activeOptionTab, setActiveOptionTab] = useState(pricingOptions[1]?.id || pricingOptions[0]?.id);
  const [taxRate, setTaxRate] = useState(estimate?.tax_rate_percent || 0);
  const [discountCents, setDiscountCents] = useState(estimate?.discount_cents || 0);
  const [validDays, setValidDays] = useState(30);
  const [customerNotes, setCustomerNotes] = useState(estimate?.customer_notes || "");
  const [internalNotes, setInternalNotes] = useState(estimate?.internal_notes || "");

  // Calculate totals based on mode
  const calculateTotal = (items: EstimateLineItem[]) => {
    const subtotal = items.reduce((sum, item) => sum + item.total_cents, 0);
    const taxAmount = Math.round(((subtotal - discountCents) * taxRate) / 100);
    return subtotal - discountCents + taxAmount;
  };

  const subtotal = usePricingOptions
    ? pricingOptions.find(o => o.id === activeOptionTab)?.line_items.reduce((sum, item) => sum + item.total_cents, 0) || 0
    : lineItems.reduce((sum, item) => sum + item.total_cents, 0);
  const taxAmount = Math.round(((subtotal - discountCents) * taxRate) / 100);
  const total = subtotal - discountCents + taxAmount;

  // Update pricing option line items
  const updatePricingOptionLineItems = (optionId: string, items: EstimateLineItem[]) => {
    setPricingOptions((options) =>
      options.map((opt) =>
        opt.id === optionId
          ? { ...opt, line_items: items, total_cents: items.reduce((sum, item) => sum + item.total_cents, 0) }
          : opt
      )
    );
  };

  // Update pricing option metadata
  const updatePricingOption = (optionId: string, field: "name" | "description", value: string) => {
    setPricingOptions((options) =>
      options.map((opt) => (opt.id === optionId ? { ...opt, [field]: value } : opt))
    );
  };

  // Calculate valid until date
  const getValidUntil = () => {
    const date = new Date();
    date.setDate(date.getDate() + validDays);
    return date.toISOString().split("T")[0];
  };

  // Save estimate
  const handleSave = async (sendAfterSave = false) => {
    const validItems = usePricingOptions
      ? pricingOptions[1]?.line_items.filter((item) => item.name.trim()) || []
      : lineItems.filter((item) => item.name.trim());

    if (validItems.length === 0 && !usePricingOptions) {
      return; // TODO: Show error
    }

    // Prepare pricing options with calculated totals
    const preparedOptions = usePricingOptions
      ? pricingOptions.map((opt) => ({
          ...opt,
          total_cents: calculateTotal(opt.line_items),
        }))
      : undefined;

    const estimateData = {
      customer_id: customerId || undefined,
      title: title || undefined,
      line_items: usePricingOptions ? pricingOptions[1]?.line_items || [] : lineItems.filter(item => item.name.trim()),
      pricing_options: preparedOptions,
      tax_rate_percent: taxRate,
      discount_cents: discountCents,
      valid_until: getValidUntil(),
      customer_notes: customerNotes || undefined,
      internal_notes: internalNotes || undefined,
    };

    if (estimate) {
      await updateEstimate.mutateAsync({
        id: estimate.id,
        ...estimateData,
      });
    } else {
      const newEstimate = await createEstimate.mutateAsync(estimateData);

      if (sendAfterSave && customerId) {
        await sendEstimate.mutateAsync({
          estimateId: newEstimate.id,
        });
      }
    }

    onSave();
  };

  return (
    <div className="space-y-6">
      {/* Basic Info */}
      <div className="grid gap-4 md:grid-cols-2">
        <div className="space-y-2">
          <Label htmlFor="title">Estimate Title (Optional)</Label>
          <Input
            id="title"
            placeholder="e.g., HVAC System Replacement"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
          />
        </div>
        <div className="space-y-2">
          <Label htmlFor="customer">Customer</Label>
          <Select value={customerId} onValueChange={setCustomerId}>
            <SelectTrigger>
              <SelectValue placeholder="Select a customer" />
            </SelectTrigger>
            <SelectContent>
              {customers.map((customer) => (
                <SelectItem key={customer.id} value={customer.id}>
                  {customer.full_name || customer.phone_e164 || "Unknown"}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Pricing Mode Toggle */}
      <Card className="bg-muted/30">
        <CardContent className="p-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Layers className="h-5 w-5 text-muted-foreground" />
              <div>
                <p className="font-medium">Good-Better-Best Pricing</p>
                <p className="text-sm text-muted-foreground">
                  Offer multiple pricing tiers to increase close rates
                </p>
              </div>
            </div>
            <Switch checked={usePricingOptions} onCheckedChange={setUsePricingOptions} />
          </div>
        </CardContent>
      </Card>

      {/* Line Items / Pricing Options */}
      {usePricingOptions ? (
        <div className="space-y-4">
          <Tabs value={activeOptionTab} onValueChange={setActiveOptionTab}>
            <TabsList className="grid w-full grid-cols-3">
              {pricingOptions.map((option, index) => (
                <TabsTrigger key={option.id} value={option.id} className="relative">
                  {option.name}
                  {index === 1 && (
                    <Badge variant="secondary" className="ml-2 text-xs">
                      Popular
                    </Badge>
                  )}
                </TabsTrigger>
              ))}
            </TabsList>

            {pricingOptions.map((option) => (
              <TabsContent key={option.id} value={option.id} className="space-y-4">
                <div className="grid gap-4 md:grid-cols-2">
                  <div className="space-y-2">
                    <Label>Option Name</Label>
                    <Input
                      value={option.name}
                      onChange={(e) => updatePricingOption(option.id, "name", e.target.value)}
                      placeholder="e.g., Basic, Standard, Premium"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>Description</Label>
                    <Input
                      value={option.description || ""}
                      onChange={(e) => updatePricingOption(option.id, "description", e.target.value)}
                      placeholder="Brief description of this option"
                    />
                  </div>
                </div>

                <LineItemsEditor
                  lineItems={option.line_items}
                  onChange={(items) => updatePricingOptionLineItems(option.id, items)}
                />

                <div className="flex justify-end">
                  <div className="text-right">
                    <p className="text-sm text-muted-foreground">Option Total</p>
                    <p className="text-2xl font-bold">{formatCurrency(calculateTotal(option.line_items))}</p>
                  </div>
                </div>
              </TabsContent>
            ))}
          </Tabs>
        </div>
      ) : (
        <LineItemsEditor lineItems={lineItems} onChange={setLineItems} />
      )}

      {/* Totals (for single pricing mode) */}
      {!usePricingOptions && (
        <div className="flex justify-end">
          <div className="w-72 space-y-2">
            <div className="flex justify-between text-sm">
              <span>Subtotal</span>
              <span>{formatCurrency(subtotal)}</span>
            </div>

            <div className="flex items-center justify-between text-sm">
              <div className="flex items-center gap-2">
                <span>Discount</span>
                <Input
                  type="number"
                  min="0"
                  step="0.01"
                  value={(discountCents / 100).toFixed(2)}
                  onChange={(e) => setDiscountCents(Math.round(parseFloat(e.target.value || "0") * 100))}
                  className="w-24 h-8 text-right"
                />
              </div>
              <span className="text-destructive">-{formatCurrency(discountCents)}</span>
            </div>

            <div className="flex items-center justify-between text-sm">
              <div className="flex items-center gap-2">
                <span>Tax</span>
                <Input
                  type="number"
                  min="0"
                  max="100"
                  step="0.1"
                  value={taxRate}
                  onChange={(e) => setTaxRate(parseFloat(e.target.value) || 0)}
                  className="w-16 h-8 text-right"
                />
                <span>%</span>
              </div>
              <span>{formatCurrency(taxAmount)}</span>
            </div>

            <div className="border-t pt-2 flex justify-between font-bold text-lg">
              <span>Total</span>
              <span>{formatCurrency(total)}</span>
            </div>
          </div>
        </div>
      )}

      {/* Notes */}
      <div className="grid gap-4 md:grid-cols-2">
        <div className="space-y-2">
          <Label htmlFor="customerNotes">Notes for Customer</Label>
          <Textarea
            id="customerNotes"
            placeholder="These notes will be visible on the estimate..."
            value={customerNotes}
            onChange={(e) => setCustomerNotes(e.target.value)}
            rows={3}
          />
        </div>
        <div className="space-y-2">
          <Label htmlFor="internalNotes">Internal Notes</Label>
          <Textarea
            id="internalNotes"
            placeholder="Private notes (not shown to customer)..."
            value={internalNotes}
            onChange={(e) => setInternalNotes(e.target.value)}
            rows={3}
          />
        </div>
      </div>

      {/* Valid For */}
      <div className="flex items-center gap-4">
        <Label>Valid for</Label>
        <Select value={validDays.toString()} onValueChange={(v) => setValidDays(parseInt(v))}>
          <SelectTrigger className="w-32">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="7">7 days</SelectItem>
            <SelectItem value="14">14 days</SelectItem>
            <SelectItem value="30">30 days</SelectItem>
            <SelectItem value="60">60 days</SelectItem>
            <SelectItem value="90">90 days</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Financing Option */}
      {financingAvailable && total >= 50000 && (
        <Card className="bg-gradient-to-r from-emerald-50 to-teal-50 dark:from-emerald-900/20 dark:to-teal-900/20 border-emerald-200 dark:border-emerald-800">
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <div className="p-2 rounded-lg bg-emerald-500/10">
                  <CreditCard className="h-5 w-5 text-emerald-600" />
                </div>
                <div>
                  <p className="font-medium text-sm">Offer Financing</p>
                  <p className="text-xs text-muted-foreground">
                    {formatFinancingAmount(total)} with Wisetack
                  </p>
                </div>
              </div>
              <Badge
                variant="secondary"
                className="bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400"
              >
                Increase close rate by 30%
              </Badge>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Actions */}
      <div className="flex items-center justify-between pt-4 border-t">
        <div>
          {financingAvailable && total >= 50000 && customerId && (
            <Button
              variant="outline"
              onClick={async () => {
                const customer = customers.find((c) => c.id === customerId);
                if (!customer?.email) return;

                await createApplication.mutateAsync({
                  customer_id: customerId,
                  estimate_id: estimate?.id,
                  amount_cents: total,
                  customer_email: customer.email,
                  customer_phone: customer.phone_e164 || undefined,
                  customer_name: customer.full_name || undefined,
                  description: title || "Service Estimate",
                });
              }}
              disabled={createApplication.isPending}
              className="text-emerald-600 border-emerald-300 hover:bg-emerald-50"
            >
              {createApplication.isPending ? (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              ) : (
                <CreditCard className="h-4 w-4 mr-2" />
              )}
              Offer Financing
            </Button>
          )}
        </div>
        <div className="flex items-center gap-3">
          <Button variant="outline" onClick={onCancel}>
            Cancel
          </Button>
          <Button
            variant="outline"
            onClick={() => handleSave(false)}
            disabled={createEstimate.isPending || updateEstimate.isPending}
          >
            <Save className="h-4 w-4 mr-2" />
            Save as Draft
          </Button>
          <Button
            onClick={() => handleSave(true)}
            disabled={createEstimate.isPending || updateEstimate.isPending || !customerId}
          >
            <Send className="h-4 w-4 mr-2" />
            Save & Send
          </Button>
        </div>
      </div>
    </div>
  );
}

/**
 * ImpoundBulkImportDialog - CSV import for existing impound inventory
 * 
 * Supports common spreadsheet formats with column mapping
 */

import { useState, useCallback } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import { useDropzone } from "react-dropzone";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { 
  Upload, 
  FileSpreadsheet, 
  Loader2, 
  CheckCircle2, 
  AlertTriangle,
  Download 
} from "lucide-react";

interface ImpoundBulkImportDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  defaultLotId?: string;
  onSuccess: () => void;
}

type ParsedRow = {
  license_plate?: string;
  license_plate_state?: string;
  vin?: string;
  vehicle_year?: string;
  vehicle_make?: string;
  vehicle_model?: string;
  vehicle_color?: string;
  towed_from_address?: string;
  tow_reason?: string;
  towed_at?: string;
  notes?: string;
};

const COLUMN_ALIASES: Record<string, string[]> = {
  license_plate: ["plate", "license", "tag", "plate number", "license plate"],
  license_plate_state: ["state", "plate state", "st"],
  vin: ["vin", "vin number", "vehicle id"],
  vehicle_year: ["year", "yr", "model year"],
  vehicle_make: ["make", "manufacturer", "brand"],
  vehicle_model: ["model", "vehicle model"],
  vehicle_color: ["color", "colour", "vehicle color"],
  towed_from_address: ["address", "location", "towed from", "pickup address", "from"],
  tow_reason: ["reason", "tow reason", "cause"],
  towed_at: ["date", "tow date", "towed date", "towed at", "impound date"],
  notes: ["notes", "comments", "remarks"],
};

function parseCSV(text: string): { headers: string[]; rows: Record<string, string>[] } {
  const lines = text.trim().split(/\r?\n/);
  if (lines.length < 2) return { headers: [], rows: [] };

  const headers = lines[0].split(",").map((h) => h.trim().toLowerCase().replace(/"/g, ""));
  const rows: Record<string, string>[] = [];

  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(",").map((v) => v.trim().replace(/"/g, ""));
    const row: Record<string, string> = {};
    headers.forEach((h, idx) => {
      row[h] = values[idx] || "";
    });
    rows.push(row);
  }

  return { headers, rows };
}

function mapColumns(row: Record<string, string>): ParsedRow {
  const result: ParsedRow = {};
  
  for (const [field, aliases] of Object.entries(COLUMN_ALIASES)) {
    for (const alias of aliases) {
      if (row[alias] !== undefined && row[alias] !== "") {
        (result as any)[field] = row[alias];
        break;
      }
    }
  }
  
  return result;
}

function parseDate(dateStr?: string): string {
  if (!dateStr) return new Date().toISOString();
  
  try {
    const parsed = new Date(dateStr);
    if (!isNaN(parsed.getTime())) {
      return parsed.toISOString();
    }
  } catch {}
  
  return new Date().toISOString();
}

export function ImpoundBulkImportDialog({
  open,
  onOpenChange,
  defaultLotId,
  onSuccess,
}: ImpoundBulkImportDialogProps) {
  const { tenant } = useAuth();
  const [parsedData, setParsedData] = useState<ParsedRow[]>([]);
  const [fileName, setFileName] = useState<string>("");
  const [importStats, setImportStats] = useState<{ success: number; errors: number } | null>(null);

  const onDrop = useCallback((acceptedFiles: File[]) => {
    const file = acceptedFiles[0];
    if (!file) return;

    setFileName(file.name);
    setImportStats(null);

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      const { rows } = parseCSV(text);
      const mapped = rows.map(mapColumns).filter((r) => r.license_plate || r.vin);
      setParsedData(mapped);
    };
    reader.readAsText(file);
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      "text/csv": [".csv"],
      "application/vnd.ms-excel": [".csv"],
    },
    maxFiles: 1,
  });

  const importMutation = useMutation({
    mutationFn: async () => {
      if (!tenant?.id) throw new Error("No tenant");
      if (parsedData.length === 0) throw new Error("No data to import");

      let success = 0;
      let errors = 0;

      for (const row of parsedData) {
        try {
          const { error } = await supabase.from("impound_vehicles").insert({
            tenant_id: tenant.id,
            lot_id: defaultLotId || null,
            license_plate: row.license_plate?.toUpperCase().replace(/\s/g, "") || null,
            license_plate_state: row.license_plate_state?.toUpperCase() || null,
            vin: row.vin?.toUpperCase() || null,
            vehicle_year: row.vehicle_year || null,
            vehicle_make: row.vehicle_make || null,
            vehicle_model: row.vehicle_model || null,
            vehicle_color: row.vehicle_color || null,
            towed_from_address: row.towed_from_address || null,
            tow_reason: row.tow_reason || null,
            notes: row.notes || null,
            towed_at: parseDate(row.towed_at),
            status: "in_lot",
          });

          if (error) {
            console.error("Import row error:", error);
            errors++;
          } else {
            success++;
          }
        } catch (err) {
          errors++;
        }
      }

      setImportStats({ success, errors });
      return { success, errors };
    },
    onSuccess: ({ success, errors }) => {
      if (errors === 0) {
        toast.success(`Imported ${success} vehicles successfully`);
        onSuccess();
        onOpenChange(false);
      } else {
        toast.warning(`Imported ${success} vehicles, ${errors} failed`);
        onSuccess();
      }
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  const downloadTemplate = () => {
    const template = `license_plate,state,vin,year,make,model,color,towed_from_address,tow_reason,towed_at,notes
ABC1234,CA,1HGBH41JXMN109186,2020,Honda,Civic,Blue,123 Main St,police_request,2024-01-15,Sample note
XYZ5678,TX,,2019,Toyota,Camry,White,456 Oak Ave,abandoned,2024-01-16,`;
    
    const blob = new Blob([template], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = "impound_import_template.csv";
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleClose = () => {
    setParsedData([]);
    setFileName("");
    setImportStats(null);
    onOpenChange(false);
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <FileSpreadsheet className="h-5 w-5" />
            Import Impound Inventory
          </DialogTitle>
          <DialogDescription>
            Upload a CSV file to bulk import your existing impound lot inventory
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4">
          {/* Template Download */}
          <div className="flex justify-end">
            <Button variant="ghost" size="sm" onClick={downloadTemplate}>
              <Download className="h-4 w-4 mr-2" />
              Download Template
            </Button>
          </div>

          {/* Dropzone */}
          {parsedData.length === 0 ? (
            <div
              {...getRootProps()}
              className={`border-2 border-dashed rounded-lg p-8 text-center cursor-pointer transition-colors ${
                isDragActive ? "border-primary bg-primary/5" : "border-muted-foreground/25 hover:border-primary/50"
              }`}
            >
              <input {...getInputProps()} />
              <Upload className="h-10 w-10 mx-auto text-muted-foreground mb-3" />
              <p className="text-sm text-muted-foreground">
                {isDragActive
                  ? "Drop the CSV file here..."
                  : "Drag & drop a CSV file here, or click to select"}
              </p>
              <p className="text-xs text-muted-foreground mt-2">
                Supports: license plate, VIN, year, make, model, color, address, tow reason
              </p>
            </div>
          ) : (
            <>
              {/* Preview */}
              <Alert>
                <FileSpreadsheet className="h-4 w-4" />
                <AlertDescription>
                  <strong>{fileName}</strong> - {parsedData.length} vehicles ready to import
                </AlertDescription>
              </Alert>

              <ScrollArea className="h-48 rounded border p-2">
                <div className="space-y-2 text-sm">
                  {parsedData.slice(0, 10).map((row, i) => (
                    <div key={i} className="flex items-center gap-2 p-2 bg-muted/50 rounded">
                      <span className="font-mono font-medium">
                        {row.license_plate || row.vin?.slice(-6) || "—"}
                      </span>
                      <span className="text-muted-foreground">
                        {[row.vehicle_year, row.vehicle_make, row.vehicle_model]
                          .filter(Boolean)
                          .join(" ") || "Unknown vehicle"}
                      </span>
                    </div>
                  ))}
                  {parsedData.length > 10 && (
                    <p className="text-center text-muted-foreground">
                      ...and {parsedData.length - 10} more
                    </p>
                  )}
                </div>
              </ScrollArea>

              {/* Import Stats */}
              {importStats && (
                <div className="flex gap-4">
                  <div className="flex items-center gap-2 text-success">
                    <CheckCircle2 className="h-4 w-4" />
                    <span>{importStats.success} imported</span>
                  </div>
                  {importStats.errors > 0 && (
                    <div className="flex items-center gap-2 text-destructive">
                      <AlertTriangle className="h-4 w-4" />
                      <span>{importStats.errors} failed</span>
                    </div>
                  )}
                </div>
              )}
            </>
          )}

          {/* Actions */}
          <div className="flex justify-end gap-2">
            <Button variant="outline" onClick={handleClose}>
              Cancel
            </Button>
            {parsedData.length > 0 && (
              <>
                <Button
                  variant="outline"
                  onClick={() => {
                    setParsedData([]);
                    setFileName("");
                    setImportStats(null);
                  }}
                >
                  Clear
                </Button>
                <Button
                  onClick={() => importMutation.mutate()}
                  disabled={importMutation.isPending}
                >
                  {importMutation.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                  Import {parsedData.length} Vehicles
                </Button>
              </>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

/**
 * ImpoundQuickAddDialog - Tablet-friendly quick add form for drivers
 * 
 * Features:
 * - Enter plate number or VIN
 * - Scan VIN via camera with OCR
 * - Auto-decode VIN to get year/make/model
 */

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Loader2, Car, MapPin, FileText, Search } from "lucide-react";
import { VinScanner } from "./VinScanner";
import { useVinDecoder } from "@/hooks/useVinDecoder";

const US_STATES = [
  "AL", "AK", "AZ", "AR", "CA", "CO", "CT", "DE", "FL", "GA",
  "HI", "ID", "IL", "IN", "IA", "KS", "KY", "LA", "ME", "MD",
  "MA", "MI", "MN", "MS", "MO", "MT", "NE", "NV", "NH", "NJ",
  "NM", "NY", "NC", "ND", "OH", "OK", "OR", "PA", "RI", "SC",
  "SD", "TN", "TX", "UT", "VT", "VA", "WA", "WV", "WI", "WY"
];

const TOW_REASONS = [
  { value: "police_request", label: "Police Request" },
  { value: "private_property", label: "Private Property" },
  { value: "abandoned", label: "Abandoned Vehicle" },
  { value: "accident", label: "Accident Recovery" },
  { value: "repossession", label: "Repossession" },
  { value: "owner_request", label: "Owner Request" },
  { value: "other", label: "Other" },
];

interface ImpoundQuickAddDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  defaultLotId?: string;
  onSuccess: () => void;
}

export function ImpoundQuickAddDialog({
  open,
  onOpenChange,
  defaultLotId,
  onSuccess,
}: ImpoundQuickAddDialogProps) {
  const { tenant } = useAuth();
  const { decodeVin, isDecoding } = useVinDecoder();
  
  const [formData, setFormData] = useState({
    license_plate: "",
    license_plate_state: "",
    vin: "",
    vehicle_year: "",
    vehicle_make: "",
    vehicle_model: "",
    vehicle_color: "",
    towed_from_address: "",
    tow_reason: "",
    notes: "",
  });

  // Auto-decode VIN when it reaches 17 characters
  useEffect(() => {
    const vin = formData.vin.replace(/\s/g, "");
    if (vin.length === 17) {
      handleVinDecode(vin);
    }
  }, [formData.vin]);

  const handleVinDecode = async (vin: string) => {
    const info = await decodeVin(vin);
    if (info) {
      setFormData(prev => ({
        ...prev,
        vehicle_year: info.year || prev.vehicle_year,
        vehicle_make: info.make || prev.vehicle_make,
        vehicle_model: info.model || prev.vehicle_model,
      }));
    }
  };

  const handleVinFromScanner = (vin: string) => {
    setFormData(prev => ({ ...prev, vin }));
    // The useEffect will trigger decode automatically
  };

  const handleManualDecode = () => {
    const vin = formData.vin.replace(/\s/g, "");
    if (vin.length === 17) {
      handleVinDecode(vin);
    } else {
      toast.error("Enter a valid 17-character VIN first");
    }
  };

  const createMutation = useMutation({
    mutationFn: async () => {
      if (!tenant?.id) throw new Error("No tenant");
      if (!formData.license_plate && !formData.vin) {
        throw new Error("Please enter a license plate or VIN");
      }

      const { error } = await supabase.from("impound_vehicles").insert({
        tenant_id: tenant.id,
        lot_id: defaultLotId || null,
        license_plate: formData.license_plate.toUpperCase().replace(/\s/g, "") || null,
        license_plate_state: formData.license_plate_state || null,
        vin: formData.vin.toUpperCase() || null,
        vehicle_year: formData.vehicle_year || null,
        vehicle_make: formData.vehicle_make || null,
        vehicle_model: formData.vehicle_model || null,
        vehicle_color: formData.vehicle_color || null,
        towed_from_address: formData.towed_from_address || null,
        tow_reason: formData.tow_reason || null,
        notes: formData.notes || null,
        towed_at: new Date().toISOString(),
        status: "in_lot",
      });

      if (error) throw error;
    },
    onSuccess: () => {
      toast.success("Vehicle added to impound lot");
      setFormData({
        license_plate: "",
        license_plate_state: "",
        vin: "",
        vehicle_year: "",
        vehicle_make: "",
        vehicle_model: "",
        vehicle_color: "",
        towed_from_address: "",
        tow_reason: "",
        notes: "",
      });
      onSuccess();
      onOpenChange(false);
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    createMutation.mutate();
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Car className="h-5 w-5" />
            Add Vehicle to Impound
          </DialogTitle>
          <DialogDescription>
            Enter vehicle details to log it in the impound lot
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* License Plate - Large and prominent for tablet use */}
          <div className="space-y-2">
            <Label htmlFor="plate">License Plate *</Label>
            <div className="flex gap-2">
              <Input
                id="plate"
                placeholder="ABC1234"
                value={formData.license_plate}
                onChange={(e) => setFormData({ ...formData, license_plate: e.target.value })}
                className="font-mono text-lg uppercase flex-1"
                autoFocus
              />
              <Select
                value={formData.license_plate_state}
                onValueChange={(v) => setFormData({ ...formData, license_plate_state: v })}
              >
                <SelectTrigger className="w-24">
                  <SelectValue placeholder="State" />
                </SelectTrigger>
                <SelectContent>
                  {US_STATES.map((state) => (
                    <SelectItem key={state} value={state}>{state}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* VIN with scanner and decode */}
          <div className="space-y-2">
            <Label htmlFor="vin">VIN (auto-decodes vehicle info)</Label>
            <div className="flex gap-2">
              <Input
                id="vin"
                placeholder="17-character VIN"
                value={formData.vin}
                onChange={(e) => setFormData({ ...formData, vin: e.target.value.toUpperCase() })}
                className="font-mono uppercase flex-1"
                maxLength={17}
              />
              <Button
                type="button"
                variant="outline"
                size="icon"
                onClick={handleManualDecode}
                disabled={isDecoding || formData.vin.length !== 17}
                title="Decode VIN"
              >
                {isDecoding ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}
              </Button>
            </div>
            <VinScanner onVinDetected={handleVinFromScanner} disabled={isDecoding} />
          </div>

          {/* Vehicle Details Row */}
          <div className="grid grid-cols-4 gap-2">
            <div className="space-y-2">
              <Label htmlFor="year">Year</Label>
              <Input
                id="year"
                placeholder="2020"
                value={formData.vehicle_year}
                onChange={(e) => setFormData({ ...formData, vehicle_year: e.target.value })}
                maxLength={4}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="make">Make</Label>
              <Input
                id="make"
                placeholder="Honda"
                value={formData.vehicle_make}
                onChange={(e) => setFormData({ ...formData, vehicle_make: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="model">Model</Label>
              <Input
                id="model"
                placeholder="Civic"
                value={formData.vehicle_model}
                onChange={(e) => setFormData({ ...formData, vehicle_model: e.target.value })}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="color">Color</Label>
              <Input
                id="color"
                placeholder="Blue"
                value={formData.vehicle_color}
                onChange={(e) => setFormData({ ...formData, vehicle_color: e.target.value })}
              />
            </div>
          </div>

          {/* Towed From */}
          <div className="space-y-2">
            <Label htmlFor="address" className="flex items-center gap-1">
              <MapPin className="h-3 w-3" />
              Towed From
            </Label>
            <Input
              id="address"
              placeholder="123 Main St, City, State"
              value={formData.towed_from_address}
              onChange={(e) => setFormData({ ...formData, towed_from_address: e.target.value })}
            />
          </div>

          {/* Tow Reason */}
          <div className="space-y-2">
            <Label>Tow Reason</Label>
            <Select
              value={formData.tow_reason}
              onValueChange={(v) => setFormData({ ...formData, tow_reason: v })}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select reason" />
              </SelectTrigger>
              <SelectContent>
                {TOW_REASONS.map((reason) => (
                  <SelectItem key={reason.value} value={reason.value}>
                    {reason.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Notes */}
          <div className="space-y-2">
            <Label htmlFor="notes" className="flex items-center gap-1">
              <FileText className="h-3 w-3" />
              Notes
            </Label>
            <Textarea
              id="notes"
              placeholder="Any additional notes about this vehicle..."
              value={formData.notes}
              onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
              rows={2}
            />
          </div>

          {/* Submit */}
          <div className="flex justify-end gap-2 pt-2">
            <Button type="button" variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={createMutation.isPending} size="lg">
              {createMutation.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Add to Lot
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}

/**
 * ImpoundVehicleDetailDialog - Full vehicle details and release processing
 */

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useMutation } from "@tanstack/react-query";
import { toast } from "sonner";
import { format } from "date-fns";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  Car,
  MapPin,
  Calendar,
  DollarSign,
  Loader2,
  CheckCircle2,
  User,
  CreditCard,
} from "lucide-react";

type ImpoundVehicle = {
  id: string;
  tenant_id: string;
  lot_id: string | null;
  license_plate: string | null;
  license_plate_state: string | null;
  vin: string | null;
  vehicle_year: string | null;
  vehicle_make: string | null;
  vehicle_model: string | null;
  vehicle_color: string | null;
  towed_from_address: string | null;
  towed_at: string;
  tow_reason: string | null;
  status: string | null;
  base_tow_fee_cents: number | null;
  storage_fee_daily_cents: number | null;
  days_stored: number | null;
  total_fees_cents: number | null;
  admin_fee_cents: number | null;
  gate_fee_cents: number | null;
  released_at: string | null;
  released_to_name: string | null;
  released_to_phone: string | null;
  release_notes: string | null;
  payment_method: string | null;
  notes: string | null;
  impound_lots?: { name: string } | null;
};

interface ImpoundVehicleDetailDialogProps {
  vehicle: ImpoundVehicle;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onUpdate: () => void;
}

const PAYMENT_METHODS = [
  { value: "cash", label: "Cash" },
  { value: "card", label: "Credit/Debit Card" },
  { value: "check", label: "Check" },
  { value: "money_order", label: "Money Order" },
];

const statusConfig: Record<string, { label: string; variant: "default" | "secondary" | "outline" }> = {
  in_lot: { label: "In Lot", variant: "default" },
  pending_release: { label: "Pending Release", variant: "secondary" },
  released: { label: "Released", variant: "outline" },
};

export function ImpoundVehicleDetailDialog({
  vehicle,
  open,
  onOpenChange,
  onUpdate,
}: ImpoundVehicleDetailDialogProps) {
  const { tenant } = useAuth();
  
  const [releaseData, setReleaseData] = useState({
    released_to_name: "",
    released_to_phone: "",
    payment_method: "",
    release_notes: "",
  });

  const status = statusConfig[vehicle.status || "in_lot"] || statusConfig.in_lot;

  const vehicleDescription = [
    vehicle.vehicle_year,
    vehicle.vehicle_color,
    vehicle.vehicle_make,
    vehicle.vehicle_model,
  ]
    .filter(Boolean)
    .join(" ") || "Unknown Vehicle";

  const daysStored = vehicle.days_stored || 
    Math.floor((Date.now() - new Date(vehicle.towed_at).getTime()) / (1000 * 60 * 60 * 24));

  // Calculate fees
  const baseTow = vehicle.base_tow_fee_cents || 0;
  const dailyStorage = vehicle.storage_fee_daily_cents || 0;
  const storageFees = dailyStorage * daysStored;
  const adminFee = vehicle.admin_fee_cents || 0;
  const gateFee = vehicle.gate_fee_cents || 0;
  const totalFees = baseTow + storageFees + adminFee + gateFee;

  const updateStatusMutation = useMutation({
    mutationFn: async (newStatus: string) => {
      const updates: Record<string, unknown> = {
        status: newStatus,
        updated_at: new Date().toISOString(),
      };

      if (newStatus === "released") {
        updates.released_at = new Date().toISOString();
        updates.released_to_name = releaseData.released_to_name || null;
        updates.released_to_phone = releaseData.released_to_phone || null;
        updates.payment_method = releaseData.payment_method || null;
        updates.release_notes = releaseData.release_notes || null;
        updates.total_fees_cents = totalFees;
        updates.days_stored = daysStored;
      }

      const { error } = await supabase
        .from("impound_vehicles")
        .update(updates)
        .eq("id", vehicle.id);

      if (error) throw error;
    },
    onSuccess: () => {
      toast.success("Vehicle updated");
      onUpdate();
      onOpenChange(false);
    },
    onError: (error: Error) => {
      toast.error(error.message);
    },
  });

  const formatCents = (cents: number) => `$${(cents / 100).toFixed(2)}`;

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <div className="flex items-center justify-between">
            <DialogTitle className="flex items-center gap-2">
              <Car className="h-5 w-5" />
              <span className="font-mono">
                {vehicle.license_plate || vehicle.vin?.slice(-6) || "Unknown"}
              </span>
            </DialogTitle>
            <Badge variant={status.variant}>{status.label}</Badge>
          </div>
        </DialogHeader>

        <div className="space-y-4">
          {/* Vehicle Info */}
          <div className="space-y-2">
            <p className="font-medium">{vehicleDescription}</p>
            {vehicle.vin && (
              <p className="text-sm text-muted-foreground font-mono">VIN: {vehicle.vin}</p>
            )}
          </div>

          {/* Tow Details */}
          <div className="space-y-2 text-sm">
            {vehicle.towed_from_address && (
              <div className="flex items-start gap-2">
                <MapPin className="h-4 w-4 text-muted-foreground shrink-0 mt-0.5" />
                <span>{vehicle.towed_from_address}</span>
              </div>
            )}
            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              <span>
                Towed: {format(new Date(vehicle.towed_at), "MMM d, yyyy 'at' h:mm a")}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              <span>{daysStored} day{daysStored !== 1 ? "s" : ""} in storage</span>
            </div>
          </div>

          <Separator />

          {/* Fee Breakdown */}
          <div className="space-y-2">
            <h4 className="font-medium flex items-center gap-2">
              <DollarSign className="h-4 w-4" />
              Fee Breakdown
            </h4>
            <div className="space-y-1 text-sm">
              {baseTow > 0 && (
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Tow Fee</span>
                  <span>{formatCents(baseTow)}</span>
                </div>
              )}
              <div className="flex justify-between">
                <span className="text-muted-foreground">
                  Storage ({daysStored} days × {formatCents(dailyStorage)}/day)
                </span>
                <span>{formatCents(storageFees)}</span>
              </div>
              {adminFee > 0 && (
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Admin Fee</span>
                  <span>{formatCents(adminFee)}</span>
                </div>
              )}
              {gateFee > 0 && (
                <div className="flex justify-between">
                  <span className="text-muted-foreground">Gate Fee</span>
                  <span>{formatCents(gateFee)}</span>
                </div>
              )}
              <Separator className="my-2" />
              <div className="flex justify-between font-medium">
                <span>Total Due</span>
                <span className="text-success">{formatCents(totalFees)}</span>
              </div>
            </div>
          </div>

          {/* Release Form (if in_lot or pending_release) */}
          {vehicle.status !== "released" && (
            <>
              <Separator />
              
              <div className="space-y-3">
                <h4 className="font-medium flex items-center gap-2">
                  <CheckCircle2 className="h-4 w-4" />
                  Release Vehicle
                </h4>
                
                <div className="grid grid-cols-2 gap-3">
                  <div className="space-y-1">
                    <Label htmlFor="releaseName" className="text-xs">
                      <User className="h-3 w-3 inline mr-1" />
                      Released To
                    </Label>
                    <Input
                      id="releaseName"
                      placeholder="Name"
                      value={releaseData.released_to_name}
                      onChange={(e) => 
                        setReleaseData({ ...releaseData, released_to_name: e.target.value })
                      }
                    />
                  </div>
                  <div className="space-y-1">
                    <Label htmlFor="releasePhone" className="text-xs">Phone</Label>
                    <Input
                      id="releasePhone"
                      placeholder="Phone"
                      value={releaseData.released_to_phone}
                      onChange={(e) => 
                        setReleaseData({ ...releaseData, released_to_phone: e.target.value })
                      }
                    />
                  </div>
                </div>

                <div className="space-y-1">
                  <Label className="text-xs">
                    <CreditCard className="h-3 w-3 inline mr-1" />
                    Payment Method
                  </Label>
                  <Select
                    value={releaseData.payment_method}
                    onValueChange={(v) => 
                      setReleaseData({ ...releaseData, payment_method: v })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Select payment method" />
                    </SelectTrigger>
                    <SelectContent>
                      {PAYMENT_METHODS.map((method) => (
                        <SelectItem key={method.value} value={method.value}>
                          {method.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-1">
                  <Label htmlFor="releaseNotes" className="text-xs">Notes</Label>
                  <Textarea
                    id="releaseNotes"
                    placeholder="Release notes..."
                    value={releaseData.release_notes}
                    onChange={(e) => 
                      setReleaseData({ ...releaseData, release_notes: e.target.value })
                    }
                    rows={2}
                  />
                </div>
              </div>
            </>
          )}

          {/* Released Info */}
          {vehicle.status === "released" && vehicle.released_at && (
            <>
              <Separator />
              <div className="space-y-2 text-sm">
                <h4 className="font-medium text-muted-foreground">Release Information</h4>
                <p>Released: {format(new Date(vehicle.released_at), "MMM d, yyyy 'at' h:mm a")}</p>
                {vehicle.released_to_name && <p>To: {vehicle.released_to_name}</p>}
                {vehicle.payment_method && <p>Payment: {vehicle.payment_method}</p>}
              </div>
            </>
          )}

          {/* Actions */}
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Close
            </Button>
            
            {vehicle.status === "in_lot" && (
              <Button
                variant="secondary"
                onClick={() => updateStatusMutation.mutate("pending_release")}
                disabled={updateStatusMutation.isPending}
              >
                {updateStatusMutation.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                Mark Pending Release
              </Button>
            )}
            
            {(vehicle.status === "in_lot" || vehicle.status === "pending_release") && (
              <Button
                onClick={() => updateStatusMutation.mutate("released")}
                disabled={updateStatusMutation.isPending}
              >
                {updateStatusMutation.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                <CheckCircle2 className="h-4 w-4 mr-2" />
                Release Vehicle
              </Button>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from "react";
import { 
  CheckCircle, XCircle, Clock, ChevronDown, ChevronUp, 
  Calendar, FileSpreadsheet, Webhook, Printer, RefreshCw, 
  ExternalLink, Loader2, MessageSquare
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { formatDistanceToNow, format } from "date-fns";
import type { AutomationRun, AutomationRunStep } from "@/hooks/useIntegrations";

interface AutomationActivityFeedProps {
  runs: AutomationRun[];
  isLoading?: boolean;
  onRetry?: (runId: string) => void;
  onViewDetails?: (runId: string) => void;
}

const PROVIDER_ICONS: Record<string, React.ReactNode> = {
  google_calendar: <Calendar className="h-4 w-4" />,
  google_sheets: <FileSpreadsheet className="h-4 w-4" />,
  webhook: <Webhook className="h-4 w-4" />,
  printer: <Printer className="h-4 w-4" />,
  sms: <MessageSquare className="h-4 w-4" />,
};

const STATUS_CONFIG = {
  success: {
    icon: <CheckCircle className="h-4 w-4 text-green-500" />,
    badge: "Success",
    badgeClass: "bg-green-500/10 text-green-600 border-green-500/20",
  },
  failed: {
    icon: <XCircle className="h-4 w-4 text-red-500" />,
    badge: "Failed",
    badgeClass: "bg-red-500/10 text-red-600 border-red-500/20",
  },
  running: {
    icon: <Loader2 className="h-4 w-4 text-blue-500 animate-spin" />,
    badge: "Running",
    badgeClass: "bg-blue-500/10 text-blue-600 border-blue-500/20",
  },
  pending: {
    icon: <Clock className="h-4 w-4 text-amber-500" />,
    badge: "Pending",
    badgeClass: "bg-amber-500/10 text-amber-600 border-amber-500/20",
  },
  skipped: {
    icon: <Clock className="h-4 w-4 text-muted-foreground" />,
    badge: "Skipped",
    badgeClass: "bg-muted text-muted-foreground",
  },
};

interface ActivityItemProps {
  run: AutomationRun;
  onRetry?: (runId: string) => void;
}

function ActivityItem({ run, onRetry }: ActivityItemProps) {
  const [expanded, setExpanded] = useState(false);
  const statusConfig = STATUS_CONFIG[run.status] || STATUS_CONFIG.pending;
  const providerIcon = PROVIDER_ICONS[run.rule?.destination_provider || ""] || <Webhook className="h-4 w-4" />;

  const triggerLabel = run.trigger_event
    .replace(".", " ")
    .replace(/_/g, " ")
    .replace(/\b\w/g, c => c.toUpperCase());

  const ruleName = run.rule?.name || triggerLabel;
  const timeAgo = formatDistanceToNow(new Date(run.started_at), { addSuffix: true });

  return (
    <Collapsible open={expanded} onOpenChange={setExpanded}>
      <div className={`p-4 transition-colors ${expanded ? "bg-muted/50" : "hover:bg-muted/30"}`}>
        <div className="flex items-start gap-3">
          {/* Status Icon */}
          <div className="pt-0.5 shrink-0">
            {statusConfig.icon}
          </div>

          {/* Content */}
          <div className="flex-1 min-w-0">
            <div className="flex items-start justify-between gap-2">
              <div className="min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="font-medium text-sm">{ruleName}</span>
                  <div className="flex items-center gap-1 text-muted-foreground">
                    {providerIcon}
                  </div>
                </div>
                <p className="text-xs text-muted-foreground mt-0.5">
                  {timeAgo}
                </p>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                <Badge variant="outline" className={`text-[10px] h-5 ${statusConfig.badgeClass}`}>
                  {statusConfig.badge}
                </Badge>
                <CollapsibleTrigger asChild>
                  <Button variant="ghost" size="sm" className="h-6 w-6 p-0">
                    {expanded ? (
                      <ChevronUp className="h-4 w-4" />
                    ) : (
                      <ChevronDown className="h-4 w-4" />
                    )}
                  </Button>
                </CollapsibleTrigger>
              </div>
            </div>

            {/* Error message preview */}
            {run.status === "failed" && run.error_message && !expanded && (
              <p className="text-xs text-red-600 mt-1 truncate">
                {run.error_message}
              </p>
            )}
          </div>
        </div>

        {/* Expanded Details */}
        <CollapsibleContent>
          <div className="mt-3 ml-7 space-y-3">
            <Separator />
            
            {/* Details Grid */}
            <div className="grid grid-cols-2 gap-3 text-xs">
              <div>
                <span className="text-muted-foreground">Trigger:</span>
                <p className="font-medium">{run.trigger_event}</p>
              </div>
              <div>
                <span className="text-muted-foreground">Entity:</span>
                <p className="font-medium">{run.entity_type} / {run.entity_id.slice(0, 8)}...</p>
              </div>
              <div>
                <span className="text-muted-foreground">Started:</span>
                <p className="font-medium">{format(new Date(run.started_at), "MMM d, h:mm a")}</p>
              </div>
              {run.finished_at && (
                <div>
                  <span className="text-muted-foreground">Finished:</span>
                  <p className="font-medium">{format(new Date(run.finished_at), "MMM d, h:mm a")}</p>
                </div>
              )}
            </div>

            {/* Error Message */}
            {run.error_message && (
              <div className="p-2 bg-red-50 dark:bg-red-950/20 rounded border border-red-200 dark:border-red-900/50">
                <p className="text-xs font-medium text-red-700 dark:text-red-400 mb-1">Error:</p>
                <p className="text-xs font-mono text-red-600 dark:text-red-300">
                  {run.error_message}
                </p>
              </div>
            )}

            {/* Payload Preview */}
            {run.payload_snapshot && Object.keys(run.payload_snapshot).length > 0 && (
              <div className="p-2 bg-muted rounded">
                <p className="text-xs font-medium text-muted-foreground mb-1">Payload:</p>
                <pre className="text-xs font-mono overflow-auto max-h-24">
                  {JSON.stringify(run.payload_snapshot, null, 2)}
                </pre>
              </div>
            )}

            {/* Actions */}
            {run.status === "failed" && onRetry && (
              <div className="flex items-center gap-2 pt-1">
                <Button size="sm" variant="outline" className="h-7 text-xs gap-1" onClick={() => onRetry(run.id)}>
                  <RefreshCw className="h-3 w-3" />
                  Retry
                </Button>
              </div>
            )}
          </div>
        </CollapsibleContent>
      </div>
    </Collapsible>
  );
}

export function AutomationActivityFeed({ runs, isLoading, onRetry }: AutomationActivityFeedProps) {
  if (isLoading) {
    return (
      <Card>
        <CardContent className="p-8 flex items-center justify-center">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  if (!runs || runs.length === 0) {
    return (
      <Card>
        <CardContent className="p-8 text-center">
          <Clock className="h-10 w-10 text-muted-foreground mx-auto mb-3" />
          <h3 className="font-medium mb-1">No Activity Yet</h3>
          <p className="text-sm text-muted-foreground">
            Automation activity will appear here when your integrations start running
          </p>
        </CardContent>
      </Card>
    );
  }

  // Group runs by date
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);

  const groupedRuns = runs.reduce<Record<string, AutomationRun[]>>((acc, run) => {
    const runDate = new Date(run.started_at);
    let key: string;
    
    if (runDate.toDateString() === today.toDateString()) {
      key = "Today";
    } else if (runDate.toDateString() === yesterday.toDateString()) {
      key = "Yesterday";
    } else {
      key = format(runDate, "MMMM d, yyyy");
    }
    
    if (!acc[key]) acc[key] = [];
    acc[key].push(run);
    return acc;
  }, {});

  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-base flex items-center gap-2">
          Recent Activity
          {runs.length > 0 && (
            <Badge variant="secondary" className="text-xs">
              {runs.length} runs
            </Badge>
          )}
        </CardTitle>
      </CardHeader>
      <CardContent className="p-0">
        <ScrollArea className="h-[500px]">
          {Object.entries(groupedRuns).map(([dateLabel, dateRuns]) => (
            <div key={dateLabel}>
              <div className="sticky top-0 bg-background px-4 py-2 border-b z-10">
                <span className="text-xs font-medium text-muted-foreground">{dateLabel}</span>
              </div>
              <div className="divide-y">
                {dateRuns.map((run) => (
                  <ActivityItem key={run.id} run={run} onRetry={onRetry} />
                ))}
              </div>
            </div>
          ))}
        </ScrollArea>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { CheckCircle, AlertCircle, Zap, Clock, Plus, ExternalLink, RefreshCw, Loader2 } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { formatDistanceToNow } from "date-fns";
