import { ExternalLink, FileText, Printer, Eye, RefreshCw, Settings } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useToast } from "@/hooks/use-toast";

interface QuickAction {
  id: string;
  label: string;
  icon: React.ReactNode;
  description?: string;
  onClick: () => void;
  disabled?: boolean;
}

interface QuickActionsMenuProps {
  providerId: string;
  integrationConfig?: Record<string, unknown>;
  onTest?: () => void;
  onReconnect?: () => void;
  onSettings?: () => void;
}

export function QuickActionsMenu({ 
  providerId, 
  integrationConfig,
  onTest,
  onReconnect,
  onSettings,
}: QuickActionsMenuProps) {
  const { toast } = useToast();

  const getQuickActions = (): QuickAction[] => {
    switch (providerId) {
      case "google_calendar":
        return [
          {
            id: "view-calendar",
            label: "Open Google Calendar",
            icon: <ExternalLink className="h-4 w-4" />,
            description: "View your calendar in a new tab",
            onClick: () => {
              window.open("https://calendar.google.com", "_blank");
            },
          },
          {
            id: "view-last-event",
            label: "View latest synced event",
            icon: <Eye className="h-4 w-4" />,
            description: "Jump to the most recently created event",
            onClick: () => {
              // In a real implementation, this would open the specific event
              toast({
                title: "Opening calendar",
                description: "Navigating to your most recent synced event",
              });
              window.open("https://calendar.google.com", "_blank");
            },
          },
        ];

      case "google_sheets":
        const sheetId = integrationConfig?.sheet_id as string;
        return [
          {
            id: "view-sheet",
            label: "Open Spreadsheet",
            icon: <ExternalLink className="h-4 w-4" />,
            description: "View your connected spreadsheet",
            onClick: () => {
              const url = sheetId 
                ? `https://docs.google.com/spreadsheets/d/${sheetId}`
                : "https://sheets.google.com";
              window.open(url, "_blank");
            },
          },
          {
            id: "view-last-row",
            label: "View last entry",
            icon: <FileText className="h-4 w-4" />,
            description: "See the most recently added row",
            onClick: () => {
              const url = sheetId 
                ? `https://docs.google.com/spreadsheets/d/${sheetId}`
                : "https://sheets.google.com";
              window.open(url, "_blank");
            },
          },
        ];

      case "webhook":
        return [
          {
            id: "view-last-delivery",
            label: "View last delivery",
            icon: <Eye className="h-4 w-4" />,
            description: "See the payload and response of the last webhook call",
            onClick: () => {
              toast({
                title: "View in History",
                description: "Check the History tab for detailed webhook logs",
              });
            },
          },
          {
            id: "test-webhook",
            label: "Send test payload",
            icon: <RefreshCw className="h-4 w-4" />,
            description: "Send a sample payload to test your webhook",
            onClick: () => onTest?.(),
            disabled: !onTest,
          },
        ];

      case "printer":
        return [
          {
            id: "test-print",
            label: "Print test ticket",
            icon: <Printer className="h-4 w-4" />,
            description: "Send a test print job to verify connection",
            onClick: () => {
              toast({
                title: "Test print sent",
                description: "A test ticket has been sent to your printer",
              });
              onTest?.();
            },
          },
          {
            id: "printnode-dashboard",
            label: "Open PrintNode dashboard",
            icon: <ExternalLink className="h-4 w-4" />,
            description: "Manage your cloud printer settings",
            onClick: () => {
              window.open("https://app.printnode.com", "_blank");
            },
          },
        ];

      default:
        return [];
    }
  };

  const quickActions = getQuickActions();

  // Always include common actions
  const commonActions: QuickAction[] = [
    ...(onTest ? [{
      id: "test-connection",
      label: "Test connection",
      icon: <RefreshCw className="h-4 w-4" />,
      onClick: onTest,
    }] : []),
    ...(onSettings ? [{
      id: "settings",
      label: "Settings",
      icon: <Settings className="h-4 w-4" />,
      onClick: onSettings,
    }] : []),
    ...(onReconnect ? [{
      id: "reconnect",
      label: "Reconnect",
      icon: <RefreshCw className="h-4 w-4" />,
      onClick: onReconnect,
    }] : []),
  ];

  const allActions = [...quickActions, ...commonActions];

  if (allActions.length === 0) return null;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="ghost" size="sm" className="h-7 px-2 text-xs">
          Actions
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-56">
        <DropdownMenuLabel>Quick Actions</DropdownMenuLabel>
        <DropdownMenuSeparator />
        {quickActions.map((action) => (
          <DropdownMenuItem 
            key={action.id} 
            onClick={action.onClick}
            disabled={action.disabled}
            className="flex items-start gap-2 py-2"
          >
            {action.icon}
            <div className="flex-1 min-w-0">
              <p className="font-medium text-sm">{action.label}</p>
              {action.description && (
                <p className="text-xs text-muted-foreground truncate">{action.description}</p>
              )}
            </div>
          </DropdownMenuItem>
        ))}
        {commonActions.length > 0 && quickActions.length > 0 && (
          <DropdownMenuSeparator />
        )}
        {commonActions.map((action) => (
          <DropdownMenuItem 
            key={action.id} 
            onClick={action.onClick}
            disabled={action.disabled}
          >
            {action.icon}
            <span className="ml-2">{action.label}</span>
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQueryClient } from "@tanstack/react-query";
import { useToast } from "@/hooks/use-toast";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent } from "@/components/ui/card";
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { Badge } from "@/components/ui/badge";
import {
  Globe,
  Plus,
  Trash2,
  RefreshCw,
  ChevronDown,
  Loader2,
  CheckCircle2,
  AlertCircle,
} from "lucide-react";
import { formatDistanceToNow } from "date-fns";

interface InventorySyncPanelProps {
  lastSyncedAt: string | null;
}

export function InventorySyncPanel({ lastSyncedAt }: InventorySyncPanelProps) {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const [open, setOpen] = useState(false);
  const [urls, setUrls] = useState<string[]>([""]);
  const [isSaving, setIsSaving] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncResult, setSyncResult] = useState<{ success: boolean; message: string } | null>(null);
  const [loaded, setLoaded] = useState(false);

  // Load existing dealer_urls from tenant context_fields_json
  useEffect(() => {
    if (!tenant?.id || loaded) return;
    const contextFields = (tenant as any).context_fields_json as Record<string, any> | null;
    const existing = contextFields?.dealer_urls as string[] | undefined;
    if (existing && existing.length > 0) {
      setUrls(existing);
    }
    setLoaded(true);
  }, [tenant?.id, loaded]);

  const handleAddUrl = () => setUrls((prev) => [...prev, ""]);

  const handleRemoveUrl = (index: number) => {
    setUrls((prev) => prev.filter((_, i) => i !== index));
  };

  const handleUrlChange = (index: number, value: string) => {
    setUrls((prev) => prev.map((u, i) => (i === index ? value : u)));
  };

  const cleanUrls = urls.map((u) => u.trim()).filter(Boolean);

  const handleSaveUrls = async () => {
    if (!tenant?.id) return;
    setIsSaving(true);
    try {
      const contextFields = ((tenant as any).context_fields_json as Record<string, any>) || {};
      const updated = { ...contextFields, dealer_urls: cleanUrls };

      const { error } = await (supabase as any)
        .from("tenants")
        .update({ context_fields_json: updated })
        .eq("id", tenant.id);

      if (error) throw error;
      toast({ title: "URLs saved", description: `${cleanUrls.length} dealer URL(s) saved.` });
    } catch (e: any) {
      toast({ title: "Error saving URLs", description: e.message, variant: "destructive" });
    } finally {
      setIsSaving(false);
    }
  };

  const handleSync = async () => {
    if (!tenant?.id || cleanUrls.length === 0) {
      toast({ title: "No URLs", description: "Add at least one dealer URL first.", variant: "destructive" });
      return;
    }
    setIsSyncing(true);
    setSyncResult(null);
    try {
      // Save URLs first
      await handleSaveUrls();

      const { data, error } = await supabase.functions.invoke("scrape-carsforsale", {
        body: { tenant_id: tenant.id, dealer_urls: cleanUrls, full_sync: true },
      });

      if (error) throw error;

      const count = data?.items_synced ?? data?.count ?? 0;
      setSyncResult({ success: true, message: `Synced ${count} vehicle(s) from ${cleanUrls.length} source(s).` });
      queryClient.invalidateQueries({ queryKey: ["sales-inventory", tenant.id] });
      toast({ title: "Sync complete", description: `${count} vehicles imported.` });
    } catch (e: any) {
      setSyncResult({ success: false, message: e.message || "Sync failed" });
      toast({ title: "Sync failed", description: e.message, variant: "destructive" });
    } finally {
      setIsSyncing(false);
    }
  };

  return (
    <Collapsible open={open} onOpenChange={setOpen}>
      <Card>
        <CollapsibleTrigger asChild>
          <CardContent className="p-4 flex items-center justify-between cursor-pointer hover:bg-muted/30 transition-colors">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-full bg-primary/10">
                <Globe className="h-4 w-4 text-primary" />
              </div>
              <div>
                <p className="text-sm font-medium">Import from Web</p>
                <p className="text-xs text-muted-foreground">
                  {lastSyncedAt
                    ? `Last synced ${formatDistanceToNow(new Date(lastSyncedAt), { addSuffix: true })}`
                    : "No sync yet — add your dealer page URLs"}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              {cleanUrls.length > 0 && (
                <Badge variant="secondary" className="text-xs">
                  {cleanUrls.length} URL{cleanUrls.length !== 1 ? "s" : ""}
                </Badge>
              )}
              <ChevronDown className={`h-4 w-4 text-muted-foreground transition-transform ${open ? "rotate-180" : ""}`} />
            </div>
          </CardContent>
        </CollapsibleTrigger>

        <CollapsibleContent>
          <CardContent className="px-4 pb-4 pt-0 space-y-3 border-t">
            <p className="text-xs text-muted-foreground pt-3">
              Add your dealer listing page URLs (e.g. carsforsale.com, autotrader). We'll scrape vehicle details automatically every 6 hours.
            </p>

            <div className="space-y-2">
              {urls.map((url, i) => (
                <div key={i} className="flex items-center gap-2">
                  <Input
                    placeholder="https://www.carsforsale.com/your-dealer"
                    value={url}
                    onChange={(e) => handleUrlChange(i, e.target.value)}
                    className="flex-1"
                  />
                  {urls.length > 1 && (
                    <Button variant="ghost" size="icon" onClick={() => handleRemoveUrl(i)} className="shrink-0">
                      <Trash2 className="h-4 w-4 text-muted-foreground" />
                    </Button>
                  )}
                </div>
              ))}
            </div>

            <div className="flex items-center gap-2 flex-wrap">
              <Button variant="outline" size="sm" onClick={handleAddUrl}>
                <Plus className="h-3.5 w-3.5 mr-1" />
                Add URL
              </Button>
              <Button variant="outline" size="sm" onClick={handleSaveUrls} disabled={isSaving || cleanUrls.length === 0}>
                {isSaving ? <Loader2 className="h-3.5 w-3.5 mr-1 animate-spin" /> : null}
                Save
              </Button>
              <Button size="sm" onClick={handleSync} disabled={isSyncing || cleanUrls.length === 0}>
                {isSyncing ? (
                  <Loader2 className="h-3.5 w-3.5 mr-1 animate-spin" />
                ) : (
                  <RefreshCw className="h-3.5 w-3.5 mr-1" />
                )}
                Sync Now
              </Button>
            </div>

            {syncResult && (
              <div className={`flex items-center gap-2 text-xs rounded-md p-2 ${syncResult.success ? "bg-green-50 text-green-700 dark:bg-green-900/20 dark:text-green-400" : "bg-destructive/10 text-destructive"}`}>
                {syncResult.success ? <CheckCircle2 className="h-3.5 w-3.5" /> : <AlertCircle className="h-3.5 w-3.5" />}
                {syncResult.message}
              </div>
            )}
          </CardContent>
        </CollapsibleContent>
      </Card>
    </Collapsible>
  );
}

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import { ExternalLink, Fuel, Gauge, Calendar, MapPin, Palette, Car } from "lucide-react";
import { cn } from "@/lib/utils";
import { proxyImageUrl } from "@/lib/proxyImage";

interface VehicleItem {
  id: string;
  year: string | null;
  make: string | null;
  model: string | null;
  trim: string | null;
  body_style: string | null;
  color_exterior: string | null;
  color_interior: string | null;
  msrp_cents: number | null;
  asking_price_cents: number | null;
  internet_price_cents: number | null;
  condition: string | null;
  mileage: number | null;
  status: string;
  features: string[] | null;
  description: string | null;
  photo_urls: string[] | null;
  listing_url: string | null;
  stock_number: string | null;
  vin: string | null;
  special_notes: string | null;
  lot_location: string | null;
  days_on_lot: number;
  financing_available: boolean | null;
  trade_in_eligible: boolean | null;
  last_synced_at: string | null;
}

function formatPrice(cents: number | null): string {
  if (!cents) return "--";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(cents / 100);
}

const statusColors: Record<string, string> = {
  available: "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400",
  pending: "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400",
  sold: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
  hold: "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400",
};

interface Props {
  vehicle: VehicleItem | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function VehicleDetailDialog({ vehicle, open, onOpenChange }: Props) {
  if (!vehicle) return null;

  const title = [vehicle.year, vehicle.make, vehicle.model].filter(Boolean).join(" ") || "Vehicle";
  const descParts = vehicle.description?.split(" • ").filter(Boolean) || [];

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[85vh] p-0">
        {/* Photo */}
        {vehicle.photo_urls && vehicle.photo_urls.length > 0 && (
          <div className="relative w-full h-48 overflow-hidden rounded-t-lg bg-muted">
            <img
              src={proxyImageUrl(vehicle.photo_urls[0])}
              alt={title}
              className="w-full h-full object-cover"
            />
            {vehicle.photo_urls.length > 1 && (
              <Badge variant="secondary" className="absolute bottom-2 right-2 text-[10px]">
                +{vehicle.photo_urls.length - 1} photos
              </Badge>
            )}
          </div>
        )}

        <ScrollArea className="max-h-[60vh]">
          <div className="p-6 space-y-5">
            <DialogHeader className="space-y-1">
              <div className="flex items-start justify-between gap-2">
                <DialogTitle className="text-xl">{title}</DialogTitle>
                <Badge className={cn("text-xs shrink-0", statusColors[vehicle.status] || statusColors.available)}>
                  {vehicle.status}
                </Badge>
              </div>
              {vehicle.trim && (
                <p className="text-sm text-muted-foreground">{vehicle.trim}</p>
              )}
            </DialogHeader>

            {/* Pricing */}
            <div className="flex items-baseline gap-3">
              {vehicle.asking_price_cents && (
                <span className="text-2xl font-bold">
                  {formatPrice(vehicle.asking_price_cents)}
                </span>
              )}
              {vehicle.msrp_cents && vehicle.msrp_cents !== vehicle.asking_price_cents && (
                <span className="text-sm text-muted-foreground line-through">
                  {formatPrice(vehicle.msrp_cents)}
                </span>
              )}
              {vehicle.internet_price_cents && vehicle.internet_price_cents !== vehicle.asking_price_cents && (
                <span className="text-sm text-primary">
                  Internet: {formatPrice(vehicle.internet_price_cents)}
                </span>
              )}
            </div>

            <Separator />

            {/* Key specs grid */}
            <div className="grid grid-cols-2 gap-3 text-sm">
              {vehicle.mileage != null && (
                <div className="flex items-center gap-2">
                  <Gauge className="h-4 w-4 text-muted-foreground shrink-0" />
                  <span>{vehicle.mileage.toLocaleString()} miles</span>
                </div>
              )}
              {vehicle.color_exterior && (
                <div className="flex items-center gap-2">
                  <Palette className="h-4 w-4 text-muted-foreground shrink-0" />
                  <span>Ext: {vehicle.color_exterior}</span>
                </div>
              )}
              {vehicle.color_interior && (
                <div className="flex items-center gap-2">
                  <Car className="h-4 w-4 text-muted-foreground shrink-0" />
                  <span>Int: {vehicle.color_interior}</span>
                </div>
              )}
              {vehicle.body_style && (
                <div className="flex items-center gap-2">
                  <Car className="h-4 w-4 text-muted-foreground shrink-0" />
                  <span>{vehicle.body_style}</span>
                </div>
              )}
              {vehicle.condition && (
                <div className="flex items-center gap-2">
                  <Badge variant="outline" className="text-[10px]">{vehicle.condition}</Badge>
                </div>
              )}
              {vehicle.days_on_lot > 0 && (
                <div className="flex items-center gap-2">
                  <Calendar className="h-4 w-4 text-muted-foreground shrink-0" />
                  <span>{vehicle.days_on_lot} days on lot</span>
                </div>
              )}
              {vehicle.lot_location && (
                <div className="flex items-center gap-2">
                  <MapPin className="h-4 w-4 text-muted-foreground shrink-0" />
                  <span>{vehicle.lot_location}</span>
                </div>
              )}
            </div>

            {/* Engine / Drivetrain from description */}
            {descParts.length > 0 && (
              <>
                <Separator />
                <div>
                  <h4 className="text-sm font-medium mb-2">Specifications</h4>
                  <div className="flex flex-wrap gap-2">
                    {descParts.map((part, i) => (
                      <Badge key={i} variant="secondary" className="text-xs">
                        {part}
                      </Badge>
                    ))}
                  </div>
                </div>
              </>
            )}

            {/* Features */}
            {vehicle.features && vehicle.features.length > 0 && (
              <>
                <Separator />
                <div>
                  <h4 className="text-sm font-medium mb-2">Features</h4>
                  <div className="flex flex-wrap gap-1.5">
                    {vehicle.features.map((f, i) => (
                      <Badge key={i} variant="outline" className="text-[10px]">
                        {f}
                      </Badge>
                    ))}
                  </div>
                </div>
              </>
            )}

            {/* Seller Notes */}
            {vehicle.special_notes && (
              <>
                <Separator />
                <div>
                  <h4 className="text-sm font-medium mb-2">Seller Notes</h4>
                  <p className="text-sm text-muted-foreground leading-relaxed">
                    {vehicle.special_notes}
                  </p>
                </div>
              </>
            )}

            {/* IDs & Meta */}
            <Separator />
            <div className="grid grid-cols-2 gap-2 text-xs text-muted-foreground">
              {vehicle.stock_number && <span>Stock #: {vehicle.stock_number}</span>}
              {vehicle.vin && <span>VIN: {vehicle.vin}</span>}
              {vehicle.financing_available && <Badge variant="outline" className="text-[10px] w-fit">Financing Available</Badge>}
              {vehicle.trade_in_eligible && <Badge variant="outline" className="text-[10px] w-fit">Trade-In Eligible</Badge>}
              {vehicle.last_synced_at && (
                <span className="col-span-2">
                  Last synced: {new Date(vehicle.last_synced_at).toLocaleDateString()}
                </span>
              )}
            </div>

            {/* View listing link */}
            {vehicle.listing_url && (
              <a
                href={vehicle.listing_url}
                target="_blank"
                rel="noopener noreferrer"
                className="inline-flex items-center gap-1.5 text-sm text-primary hover:underline"
              >
                <ExternalLink className="h-3.5 w-3.5" />
                View original listing
              </a>
            )}
          </div>
        </ScrollArea>
      </DialogContent>
    </Dialog>
  );
}

import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Separator } from "@/components/ui/separator";
import { ServiceChecklist } from "./ServiceChecklist";
import { JobTimeline } from "./JobTimeline";
import { JobNotificationToggles } from "./JobNotificationToggles";
import { useJobServiceItems } from "@/hooks/useJobServiceItems";
import { useActiveJobs, type ActiveJob, type JobStatus, type JobPriority } from "@/hooks/useActiveJobs";
import { useJobLabels } from "@/hooks/useJobLabels";
import { useFleetDrivers } from "@/hooks/useFleetDrivers";
import { Progress } from "@/components/ui/progress";
import { Phone, User, Clock, AlertTriangle, Zap, UserCheck } from "lucide-react";

interface JobDetailSheetProps {
  job: ActiveJob | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const STATUS_OPTIONS: { value: JobStatus; label: string }[] = [
  { value: "intake", label: "Intake" },
  { value: "in_progress", label: "In Progress" },
  { value: "on_hold", label: "On Hold" },
  { value: "completed", label: "Completed" },
  { value: "picked_up", label: "Picked Up" },
  { value: "cancelled", label: "Cancelled" },
];

const PRIORITY_OPTIONS: { value: JobPriority; label: string; icon?: typeof AlertTriangle }[] = [
  { value: "normal", label: "Normal" },
  { value: "rush", label: "Rush", icon: Zap },
  { value: "urgent", label: "Urgent", icon: AlertTriangle },
];

export function JobDetailSheet({ job, open, onOpenChange }: JobDetailSheetProps) {
  const labels = useJobLabels();
  const { updateJob, updateJobStatus } = useActiveJobs();
  const { activeDrivers } = useFleetDrivers();
  const {
    items,
    completedCount,
    totalCount,
    progressPercent,
    toggleItemStatus,
    addItem,
    removeItem,
  } = useJobServiceItems(job?.id ?? null);

  if (!job) return null;

  const handleStatusChange = (status: JobStatus) => {
    updateJobStatus.mutate({ id: job.id, status });
  };

  const handlePriorityChange = (priority: JobPriority) => {
    updateJob.mutate({ id: job.id, priority });
  };

  const handleToggleNotification = (field: "notify_on_step_complete" | "notify_on_all_complete", value: boolean) => {
    updateJob.mutate({ id: job.id, [field]: value });
  };

  const handleToggleItem = (itemId: string, currentStatus: string) => {
    toggleItemStatus.mutate({ itemId, currentStatus });
  };

  const handleAddItem = (title: string) => {
    addItem.mutate({ title });
  };

  const handleRemoveItem = (itemId: string) => {
    removeItem.mutate(itemId);
  };

  const meta = (job.metadata_json || {}) as Record<string, unknown>;

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="sm:max-w-lg overflow-y-auto">
        <SheetHeader className="pb-4">
          <div className="flex items-center gap-2 text-xs text-muted-foreground font-mono">
            {job.job_number}
          </div>
          <SheetTitle className="text-lg">{job.title}</SheetTitle>
        </SheetHeader>

        {/* Status + Priority selectors */}
        <div className="flex items-center gap-3 pb-4">
          <Select value={job.status} onValueChange={(v) => handleStatusChange(v as JobStatus)}>
            <SelectTrigger className="h-8 w-36 text-sm">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {STATUS_OPTIONS.map((opt) => (
                <SelectItem key={opt.value} value={opt.value}>
                  {opt.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          <Select value={job.priority} onValueChange={(v) => handlePriorityChange(v as JobPriority)}>
            <SelectTrigger className="h-8 w-28 text-sm">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {PRIORITY_OPTIONS.map((opt) => (
                <SelectItem key={opt.value} value={opt.value}>
                  {opt.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Assigned To */}
        {activeDrivers.length > 0 && (
          <div className="flex items-center gap-2 pb-4">
            <UserCheck className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
            <Select
              value={(meta.assigned_to as string) || "unassigned"}
              onValueChange={(v) =>
                updateJob.mutate({
                  id: job.id,
                  metadata_json: { ...meta, assigned_to: v === "unassigned" ? null : v },
                })
              }
            >
              <SelectTrigger className="h-8 text-sm flex-1">
                <SelectValue placeholder="Unassigned" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="unassigned">Unassigned</SelectItem>
                {activeDrivers.map((d) => (
                  <SelectItem key={d.id} value={d.id}>
                    {d.full_name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        )}

        {/* Customer info */}
        {(job.customer_name || job.customer_phone) && (
          <div className="flex flex-col gap-1 pb-4 text-sm">
            {job.customer_name && (
              <div className="flex items-center gap-2 text-muted-foreground">
                <User className="h-3.5 w-3.5" />
                {job.customer_name}
              </div>
            )}
            {job.customer_phone && (
              <div className="flex items-center gap-2 text-muted-foreground">
                <Phone className="h-3.5 w-3.5" />
                {job.customer_phone}
              </div>
            )}
            {job.estimated_completion && (
              <div className="flex items-center gap-2 text-muted-foreground">
                <Clock className="h-3.5 w-3.5" />
                Est.{" "}
                {new Date(job.estimated_completion).toLocaleString(undefined, {
                  month: "short",
                  day: "numeric",
                  hour: "numeric",
                  minute: "2-digit",
                })}
              </div>
            )}
          </div>
        )}

        {/* Metadata */}
        {Object.keys(meta).length > 0 && (
          <div className="flex flex-wrap gap-2 pb-4">
            {labels.metadataFields
              .filter((f) => meta[f.key])
              .map((f) => (
                <Badge key={f.key} variant="secondary" className="text-xs">
                  {f.label}: {String(meta[f.key])}
                </Badge>
              ))}
          </div>
        )}

        {/* Progress bar */}
        {totalCount > 0 && (
          <div className="space-y-1 pb-4">
            <div className="flex items-center justify-between text-xs text-muted-foreground">
              <span>
                {completedCount}/{totalCount} {labels.serviceSteps.toLowerCase()} complete
              </span>
              <span>{progressPercent}%</span>
            </div>
            <Progress value={progressPercent} className="h-2" />
          </div>
        )}

        <Separator className="mb-4" />

        {/* Tabbed content */}
        <Tabs defaultValue="checklist">
          <TabsList className="w-full">
            <TabsTrigger value="checklist" className="flex-1 text-xs">
              {labels.serviceSteps}
            </TabsTrigger>
            <TabsTrigger value="timeline" className="flex-1 text-xs">
              Timeline
            </TabsTrigger>
            <TabsTrigger value="settings" className="flex-1 text-xs">
              Settings
            </TabsTrigger>
          </TabsList>

          <TabsContent value="checklist" className="mt-4">
            <ServiceChecklist
              items={items}
              labels={labels}
              onToggle={handleToggleItem}
              onAdd={handleAddItem}
              onRemove={handleRemoveItem}
            />
          </TabsContent>

          <TabsContent value="timeline" className="mt-4">
            <JobTimeline jobId={job.id} />
          </TabsContent>

          <TabsContent value="settings" className="mt-4 space-y-4">
            <JobNotificationToggles
              notifyOnStepComplete={job.notify_on_step_complete}
              notifyOnAllComplete={job.notify_on_all_complete}
              onToggleStep={(v) => handleToggleNotification("notify_on_step_complete", v)}
              onToggleAll={(v) => handleToggleNotification("notify_on_all_complete", v)}
            />

            {job.notes && (
              <div className="space-y-1.5">
                <p className="text-sm font-medium text-muted-foreground">Notes</p>
                <p className="text-sm whitespace-pre-wrap">{job.notes}</p>
              </div>
            )}
          </TabsContent>
        </Tabs>
      </SheetContent>
    </Sheet>
  );
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Loader2 } from "lucide-react";

interface StatusUpdate {
  id: string;
  previous_status: string | null;
  new_status: string;
  message: string | null;
  triggered_notification: boolean;
  created_at: string;
}

interface JobTimelineProps {
  jobId: string;
}

const STATUS_LABELS: Record<string, string> = {
  intake: "Intake",
  in_progress: "In Progress",
  on_hold: "On Hold",
  completed: "Completed",
  picked_up: "Picked Up",
  cancelled: "Cancelled",
};

export function JobTimeline({ jobId }: JobTimelineProps) {
  const { data: updates, isLoading } = useQuery({
    queryKey: ["job-status-updates", jobId],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("job_status_updates")
        .select("*")
        .eq("job_id", jobId)
        .order("created_at", { ascending: false });

      if (error) throw error;
      return (data ?? []) as StatusUpdate[];
    },
    enabled: !!jobId,
  });

  if (isLoading) {
    return (
      <div className="flex items-center justify-center py-6">
        <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!updates?.length) {
    return (
      <p className="text-sm text-muted-foreground py-4 text-center">
        No status changes yet.
      </p>
    );
  }

  return (
    <div className="space-y-3">
      {updates.map((update) => (
        <div key={update.id} className="flex gap-3">
          <div className="flex flex-col items-center">
            <div className="h-2 w-2 rounded-full bg-primary mt-1.5" />
            <div className="w-px flex-1 bg-border" />
          </div>
          <div className="pb-4 min-w-0">
            <p className="text-sm">
              {update.previous_status
                ? `${STATUS_LABELS[update.previous_status] || update.previous_status} \u2192 ${STATUS_LABELS[update.new_status] || update.new_status}`
                : `Set to ${STATUS_LABELS[update.new_status] || update.new_status}`}
            </p>
            {update.message && (
              <p className="text-xs text-muted-foreground mt-0.5">{update.message}</p>
            )}
            <p className="text-[10px] text-muted-foreground mt-1">
              {new Date(update.created_at).toLocaleString(undefined, {
                month: "short",
                day: "numeric",
                hour: "numeric",
                minute: "2-digit",
              })}
              {update.triggered_notification && " \u00b7 Notification sent"}
            </p>
          </div>
        </div>
      ))}
    </div>
  );
}

