        description: 'When you are open',
        icon: Clock,
        iconBg: 'bg-purple-500/15',
        iconColor: 'text-purple-400',
        href: '/app/settings',
        points: 10,
        complete: !!(context?.hours && Object.keys(context.hours).length > 0),
      },
    ];

    // Industry-specific: Menu for food, Services for others
    if (caps.isFoodBusiness) {
      items.push({
        id: 'menu',
        label: 'Menu Items',
        description: 'Your menu with prices',
        icon: UtensilsCrossed,
        iconBg: 'bg-orange-500/15',
        iconColor: 'text-orange-400',
        href: '/app/business-brain',
        points: 20,
        complete: (context?.services?.length || 0) >= 5, // menu_items mapped to services
      });
    } else {
      items.push({
        id: 'services',
        label: 'Services & Pricing',
        description: 'What you offer and pricing',
        icon: Briefcase,
        iconBg: 'bg-emerald-500/15',
        iconColor: 'text-emerald-400',
        href: '/app/services',
        points: 20,
        complete: (context?.services?.length || 0) >= 3,
      });
    }

    items.push(
      {
        id: 'policies',
        label: 'Policies',
        description: 'Cancellation, deposits, payments',
        icon: FileText,
        iconBg: 'bg-rose-500/15',
        iconColor: 'text-rose-400',
        href: '/app/settings',
        points: 15,
        complete: !!(context?.policies.cancellation || context?.policies.deposit),
      },
      {
        id: 'faqs',
        label: 'FAQs',
        description: 'Common questions answered',
        icon: HelpCircle,
        iconBg: 'bg-cyan-500/15',
        iconColor: 'text-cyan-400',
        href: '/app/ai-assistant',
        points: 20,
        complete: (context?.faqs?.length || 0) >= 3,
      },
      {
        id: 'objections',
        label: 'Objection Handling',
        description: 'How to respond to pushback',
        icon: MessageSquare,
        iconBg: 'bg-amber-500/15',
        iconColor: 'text-amber-400',
        href: '/app/ai-assistant',
        points: 15,
        complete: (context?.objection_responses?.length || 0) >= 2,
      }
    );

    return items;
  }, [context, businessMode]);

  const getScoreColor = (score: number) => {
    if (score >= 80) return 'text-emerald-400';
    if (score >= 50) return 'text-amber-400';
    return 'text-rose-400';
  };

  const getScoreLabel = (score: number) => {
    if (score >= 80) return 'Ready';
    if (score >= 50) return 'Almost There';
    return 'Needs Work';
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6 text-center text-muted-foreground">
          Calculating AI readiness...
        </CardContent>
      </Card>
    );
  }

  if (compact) {
    return (
      <div className="flex items-center gap-3 p-3 rounded-lg border bg-card">
        <div className="flex items-center justify-center h-10 w-10 rounded-full bg-primary/10">
          <Brain className="h-5 w-5 text-primary" />
        </div>
        <div className="flex-1">
          <div className="flex items-center gap-2">
            <span className="font-medium">AI Readiness</span>
            <Badge variant="outline" className={getScoreColor(score)}>
              {score}%
            </Badge>
          </div>
          <div className="h-1.5 mt-1 bg-muted rounded-full overflow-hidden">
            <div 
              className="h-full bg-gradient-to-r from-primary to-primary/80 transition-all duration-300"
              style={{ width: `${score}%` }}
            />
          </div>
        </div>
        {score < 80 && (
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={() => navigate('/app/business-brain')}
          >
            Improve
          </Button>
        )}
      </div>
    );
  }

  return (
    <Card className="border-primary/20 bg-gradient-to-br from-card to-primary/5">
      <CardHeader>
        <div className="flex items-center justify-between">
          {/* Left: Title + description */}
          <div className="flex items-center gap-3">
            <div className="h-12 w-12 rounded-xl bg-primary/15 flex items-center justify-center">
              <Brain className="h-6 w-6 text-primary" />
            </div>
            <div>
              <CardTitle>AI Readiness Score</CardTitle>
              <CardDescription>
                How prepared your AI is to handle conversations
              </CardDescription>
            </div>
          </div>
          
          {/* Right: Large score with ring */}
          <div className="relative hidden sm:block">
            <svg className="h-20 w-20 -rotate-90">
              <circle
                className="text-muted"
                strokeWidth="6"
                stroke="currentColor"
                fill="transparent"
                r="34"
                cx="40"
                cy="40"
              />
              <circle
                className="text-primary transition-all duration-500"
                strokeWidth="6"
                strokeDasharray={34 * 2 * Math.PI}
                strokeDashoffset={34 * 2 * Math.PI * (1 - score / 100)}
                strokeLinecap="round"
                stroke="currentColor"
                fill="transparent"
                r="34"
                cx="40"
                cy="40"
              />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span className={`text-2xl font-bold ${getScoreColor(score)}`}>{score}%</span>
            </div>
          </div>
          
          {/* Mobile: Just show score badge */}
          <div className="sm:hidden">
            <Badge variant="outline" className={`text-lg px-3 py-1 ${getScoreColor(score)}`}>
              {score}%
            </Badge>
          </div>
        </div>
      </CardHeader>
      
      <CardContent className="space-y-4">
        {/* Status message */}
        {score >= 80 ? (
          <div className="flex items-center gap-2 text-emerald-400 bg-emerald-500/10 border border-emerald-500/20 p-3 rounded-lg">
            <CheckCircle2 className="h-5 w-5 flex-shrink-0" />
            <span className="text-sm font-medium">Your AI is ready to handle customer conversations!</span>
          </div>
        ) : (
          <div className="flex items-center gap-2 text-amber-400 bg-amber-500/10 border border-amber-500/20 p-3 rounded-lg">
            <AlertCircle className="h-5 w-5 flex-shrink-0" />
            <span className="text-sm font-medium">Complete these items to improve your AI's knowledge</span>
          </div>
        )}
        
        {/* Actionable Checklist */}
        <div className="grid gap-2">
          {scoreItems.map(item => (
            <Link to={item.href} key={item.id}>
              <div className={`flex items-center justify-between p-3 rounded-lg border transition-colors hover:bg-muted/50 ${
                item.complete 
                  ? 'bg-emerald-500/5 border-emerald-500/20' 
                  : 'bg-muted/30 border-border'
              }`}>
                <div className="flex items-center gap-3">
                  <div className={`h-8 w-8 rounded-lg flex items-center justify-center ${
                    item.complete ? item.iconBg : 'bg-muted'
                  }`}>
                    <item.icon className={`h-4 w-4 ${
                      item.complete ? item.iconColor : 'text-muted-foreground'
                    }`} />
                  </div>
                  <div>
                    <p className="font-medium text-sm">{item.label}</p>
                    <p className="text-xs text-muted-foreground">{item.description}</p>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Badge variant="outline" className={`text-xs ${item.complete ? 'text-emerald-400 border-emerald-500/30' : ''}`}>
                    +{item.points} pts
                  </Badge>
                  {item.complete ? (
                    <CheckCircle2 className="h-4 w-4 text-emerald-400" />
                  ) : (
                    <ChevronRight className="h-4 w-4 text-muted-foreground" />
                  )}
                </div>
              </div>
            </Link>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import type { KnowledgeGap } from "@/types/database";
import { 
  AlertTriangle, CheckCircle2, Clock, HelpCircle, 
  DollarSign, MapPin, MessageSquare, X, Plus,
  BookOpen, FileText, ShieldAlert
} from "lucide-react";

const gapTypeIcons: Record<string, React.ElementType> = {
  missing_policy: AlertTriangle,
  missing_pricing: DollarSign,
  missing_service_area: MapPin,
  unanswered_question: HelpCircle,
  missing_hours: Clock,
  missing_faq: MessageSquare,
  other: HelpCircle,
};

const gapTypeLabels: Record<string, string> = {
  missing_policy: 'Missing Policy',
  missing_pricing: 'Missing Pricing',
  missing_service_area: 'Service Area',
  unanswered_question: 'Unanswered Question',
  missing_hours: 'Missing Hours',
  missing_faq: 'Missing FAQ',
  other: 'Other',
};

const priorityColors: Record<number, string> = {
  1: 'bg-blue-500/15 text-blue-400 border border-blue-500/30',
  2: 'bg-amber-500/15 text-amber-400 border border-amber-500/30',
  3: 'bg-rose-500/15 text-rose-400 border border-rose-500/30',
};

type AddAsType = 'faq' | 'policy' | 'objection';

export default function KnowledgeGapQueue() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  
  const [gaps, setGaps] = useState<KnowledgeGap[]>([]);
  const [loading, setLoading] = useState(true);
  const [resolvingId, setResolvingId] = useState<string | null>(null);
  const [resolutionNotes, setResolutionNotes] = useState('');
  
  // Add as dialog state
  const [addDialogOpen, setAddDialogOpen] = useState(false);
  const [addAsType, setAddAsType] = useState<AddAsType>('faq');
  const [selectedGap, setSelectedGap] = useState<KnowledgeGap | null>(null);
  const [newQuestion, setNewQuestion] = useState('');
  const [newAnswer, setNewAnswer] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (tenant?.id) {
      fetchGaps();
    }
  }, [tenant?.id]);

  const fetchGaps = async () => {
    if (!tenant?.id) return;

    const { data, error } = await supabase
      .from('knowledge_gaps')
      .select('*')
      .eq('tenant_id', tenant.id)
      .eq('resolved', false)
      .order('priority', { ascending: false })
      .order('occurrence_count', { ascending: false });

    if (error) {
      console.error('Failed to fetch knowledge gaps:', error);
    } else {
      setGaps(data || []);
    }
    setLoading(false);
  };

  const resolveGap = async (gapId: string) => {
    const { error } = await supabase
      .from('knowledge_gaps')
      .update({
        resolved: true,
        resolved_at: new Date().toISOString(),
        resolution_notes: resolutionNotes || 'Resolved',
      })
      .eq('id', gapId);

    if (error) {
      toast({ variant: "destructive", title: "Failed to resolve gap" });
    } else {
      toast({ title: "Knowledge gap resolved!" });
      setResolvingId(null);
      setResolutionNotes('');
      fetchGaps();
    }
  };

  const dismissGap = async (gapId: string) => {
    const { error } = await supabase
      .from('knowledge_gaps')
      .update({
        resolved: true,
        resolved_at: new Date().toISOString(),
        resolution_notes: 'Dismissed - not applicable',
      })
      .eq('id', gapId);

    if (error) {
      toast({ variant: "destructive", title: "Failed to dismiss gap" });
    } else {
      fetchGaps();
    }
  };

  const openAddDialog = (gap: KnowledgeGap, type: AddAsType) => {
    setSelectedGap(gap);
    setAddAsType(type);
    setNewQuestion(gap.customer_question || gap.description);
    setNewAnswer('');
    setAddDialogOpen(true);
  };

  const handleAddKnowledge = async () => {
    if (!tenant?.id || !selectedGap) return;
    
    setSaving(true);
    try {
      if (addAsType === 'faq') {
        const { error } = await supabase.from('business_faqs').insert({
          tenant_id: tenant.id,
          question: newQuestion,
          answer: newAnswer,
          priority_weight: 1,
        });
        if (error) throw error;
      } else if (addAsType === 'objection') {
        const { error } = await supabase.from('objection_responses').insert({
          tenant_id: tenant.id,
          objection: newQuestion,
          response: newAnswer,
          priority_weight: 1,
        });
        if (error) throw error;
      } else if (addAsType === 'policy') {
        const { error } = await supabase.from('ai_knowledge_base').insert({
          tenant_id: tenant.id,
          type: 'policy',
          title: newQuestion,
          content: newAnswer,
          priority_weight: 1,
        });
        if (error) throw error;
      }

      // Mark gap as resolved
      await supabase.from('knowledge_gaps').update({
        resolved: true,
        resolved_at: new Date().toISOString(),
        resolution_notes: `Added as ${addAsType}`,
      }).eq('id', selectedGap.id);

      toast({ 
        title: "Knowledge added!",
        description: `Added as ${addAsType} and gap resolved.`,
      });
      
      setAddDialogOpen(false);
      setSelectedGap(null);
      setNewQuestion('');
      setNewAnswer('');
      fetchGaps();
    } catch (error: any) {
      toast({ 
        variant: "destructive", 
        title: "Failed to add knowledge",
        description: error.message,
      });
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6 text-center text-muted-foreground">
          Loading knowledge gaps...
        </CardContent>
      </Card>
    );
  }

  return (
    <>
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="flex items-center gap-2">
                <AlertTriangle className="h-5 w-5 text-yellow-500" />
                Knowledge Gaps
              </CardTitle>
              <CardDescription>
                Questions the AI couldn't answer confidently. Fix these to improve performance.
              </CardDescription>
            </div>
            <Badge variant="outline" className="text-lg">
              {gaps.length}
            </Badge>
          </div>
        </CardHeader>
        <CardContent>
          {gaps.length === 0 ? (
            <div className="text-center py-8">
              <CheckCircle2 className="h-12 w-12 text-green-500 mx-auto mb-3" />
              <p className="font-medium">No knowledge gaps!</p>
              <p className="text-sm text-muted-foreground">
                Your AI has all the information it needs.
              </p>
            </div>
          ) : (
            <div className="space-y-3">
              {gaps.map((gap) => {
                const Icon = gapTypeIcons[gap.gap_type] || HelpCircle;
                const isResolving = resolvingId === gap.id;

                return (
                  <div
                    key={gap.id}
                    className="border rounded-lg p-4 space-y-3"
                  >
                    <div className="flex items-start justify-between gap-3">
                      <div className="flex items-start gap-3">
                        <div className="h-8 w-8 rounded-full bg-muted flex items-center justify-center">
                          <Icon className="h-4 w-4" />
                        </div>
                        <div>
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className="font-medium">
                              {gapTypeLabels[gap.gap_type]}
                            </span>
                            <Badge className={priorityColors[gap.priority || 1]}>
                              {gap.priority === 3 ? 'High' : gap.priority === 2 ? 'Medium' : 'Low'}
                            </Badge>
                            {gap.occurrence_count > 1 && (
                              <Badge variant="outline">
                                {gap.occurrence_count}x asked
                              </Badge>
                            )}
                          </div>
                          <p className="text-sm text-muted-foreground mt-1">
                            {gap.description}
                          </p>
                          {gap.customer_question && (
                            <p className="text-sm mt-2 p-2 bg-muted rounded">
                              Customer asked: "{gap.customer_question}"
                            </p>
                          )}
                        </div>
                      </div>
                      
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => dismissGap(gap.id)}
                        title="Dismiss"
                      >
                        <X className="h-4 w-4" />
                      </Button>
                    </div>

                    {isResolving ? (
                      <div className="space-y-2 pl-11">
                        <Textarea
                          placeholder="What did you fix? (optional)"
                          value={resolutionNotes}
                          onChange={(e) => setResolutionNotes(e.target.value)}
                          rows={2}
                        />
                        <div className="flex gap-2">
                          <Button size="sm" onClick={() => resolveGap(gap.id)}>
                            Mark Resolved
                          </Button>
                          <Button 
                            size="sm" 
                            variant="outline" 
                            onClick={() => setResolvingId(null)}
                          >
                            Cancel
                          </Button>
                        </div>
                      </div>
                    ) : (
                      <div className="pl-11 flex flex-wrap gap-2">
                        <Button
                          size="sm"
                          variant="default"
                          className="gap-1"
                          onClick={() => openAddDialog(gap, 'faq')}
                        >
                          <BookOpen className="h-3 w-3" />
                          Add as FAQ
                        </Button>
                        <Button
                          size="sm"
                          variant="secondary"
                          className="gap-1"
                          onClick={() => openAddDialog(gap, 'policy')}
                        >
                          <FileText className="h-3 w-3" />
                          Add Policy
                        </Button>
                        <Button
                          size="sm"
                          variant="secondary"
                          className="gap-1"
                          onClick={() => openAddDialog(gap, 'objection')}
                        >
                          <ShieldAlert className="h-3 w-3" />
                          Add Objection
                        </Button>
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => setResolvingId(gap.id)}
                        >
                          I Fixed This
                        </Button>
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Add Knowledge Dialog */}
      <Dialog open={addDialogOpen} onOpenChange={setAddDialogOpen}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <Plus className="h-5 w-5" />
              Add as {addAsType === 'faq' ? 'FAQ' : addAsType === 'policy' ? 'Policy' : 'Objection Response'}
            </DialogTitle>
            <DialogDescription>
              Add this to your AI knowledge base to handle similar questions in the future.
            </DialogDescription>
          </DialogHeader>
          
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Type</Label>
              <Select value={addAsType} onValueChange={(v) => setAddAsType(v as AddAsType)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="faq">FAQ (Question & Answer)</SelectItem>
                  <SelectItem value="policy">Policy</SelectItem>
                  <SelectItem value="objection">Objection Response</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>
                {addAsType === 'faq' ? 'Question' : addAsType === 'objection' ? 'Customer Objection' : 'Policy Title'}
              </Label>
              <Input
                value={newQuestion}
                onChange={(e) => setNewQuestion(e.target.value)}
                placeholder={addAsType === 'faq' ? 'What is your cancellation policy?' : 
                            addAsType === 'objection' ? 'That seems expensive...' :
                            'Emergency Service Policy'}
              />
            </div>

            <div className="space-y-2">
              <Label>
                {addAsType === 'faq' ? 'Answer' : addAsType === 'objection' ? 'AI Response' : 'Policy Details'}
              </Label>
              <Textarea
                value={newAnswer}
                onChange={(e) => setNewAnswer(e.target.value)}
                rows={4}
                placeholder={addAsType === 'faq' ? 'Enter the answer your AI should give...' :
                            addAsType === 'objection' ? 'Enter how AI should respond to this objection...' :
                            'Describe the policy in detail...'}
              />
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setAddDialogOpen(false)}>
              Cancel
            </Button>
            <Button 
              onClick={handleAddKnowledge} 
              disabled={!newQuestion || !newAnswer || saving}
            >
              {saving ? 'Adding...' : 'Add to Knowledge Base'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState, useRef, useCallback } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useKnowledgeUploads } from "@/hooks/useKnowledgeUploads";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "@/hooks/use-toast";
import { 
  Upload, 
  FileText, 
  Image, 
  FileSpreadsheet,
  CheckCircle2,
  XCircle,
  Loader2,
  Sparkles,
  File,
  Wand2
} from "lucide-react";
import { Link } from "react-router-dom";
import { cn } from "@/lib/utils";

const acceptedFormats = ".pdf,.png,.jpg,.jpeg,.docx,.xlsx";
const formatLabels = ["PDF", "PNG", "JPG", "DOCX", "XLSX"];

interface UploadResult {
  detected_type: string;
  confidence: number;
  new_items: number;
  conflicts: number;
  matched: number;
}

export function KnowledgeUploadHub() {
  const { tenant } = useAuth();
  const { uploads, processingCount, createUpload } = useKnowledgeUploads();
  const [isDragging, setIsDragging] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isUploading, setIsUploading] = useState(false);
  const [lastResult, setLastResult] = useState<UploadResult | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const files = Array.from(e.dataTransfer.files);
    if (files.length > 0) {
      handleFileUpload(files[0]);
    }
  }, []);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (files && files.length > 0) {
      handleFileUpload(files[0]);
    }
    // Reset input so same file can be selected again
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleFileUpload = async (file: File) => {
    if (!tenant?.id) {
      toast({
        title: "Error",
        description: "No tenant found. Please refresh and try again.",
        variant: "destructive"
      });
      return;
    }

    // Validate file type
    const validExtensions = [".pdf", ".png", ".jpg", ".jpeg", ".docx", ".xlsx"];
    const fileExtension = "." + file.name.split(".").pop()?.toLowerCase();
    if (!validExtensions.includes(fileExtension)) {
      toast({
        title: "Unsupported file type",
        description: `Please upload one of: ${formatLabels.join(", ")}`,
        variant: "destructive"
      });
      return;
    }

    // Validate file size (max 10MB)
    if (file.size > 10 * 1024 * 1024) {
      toast({
        title: "File too large",
        description: "Please upload a file smaller than 10MB",
        variant: "destructive"
      });
      return;
    }

    setIsUploading(true);
    setUploadProgress(10);
    setLastResult(null);

    try {
      // 1. Create knowledge_sources record with "auto" type (AI will detect)
      const source = await createUpload({
        fileName: file.name,
        sourceType: "general" // Will be auto-detected
      });
      setUploadProgress(20);

      // 2. Upload file to storage
      const filePath = `${tenant.id}/${source.id}/${file.name}`;
      const { error: uploadError } = await supabase.storage
        .from("knowledge-documents")
        .upload(filePath, file);

      if (uploadError) {
        throw new Error(`Upload failed: ${uploadError.message}`);
      }
      setUploadProgress(50);

      // 3. Get public URL
      const { data: urlData } = supabase.storage
        .from("knowledge-documents")
        .getPublicUrl(filePath);

      // 4. Update record with file URL
      await supabase
        .from("knowledge_sources")
        .update({ file_url: urlData.publicUrl, status: "processing" })
        .eq("id", source.id);
      setUploadProgress(60);

      // 5. Trigger processing edge function with auto-detect enabled
      const { data: fnData, error: fnError } = await supabase.functions.invoke("process-knowledge-upload", {
        body: {
          sourceId: source.id,
          tenantId: tenant.id,
          fileUrl: urlData.publicUrl,
          sourceType: "auto", // Auto-detect mode
          autoDetect: true
        }
      });

      if (fnError) {
        console.error("Processing error:", fnError);
        toast({
          title: "Processing started",
          description: "Your document is being analyzed. Check the Review Queue for results."
        });
      } else if (fnData?.success) {
        setLastResult({
          detected_type: fnData.detected_type,
          confidence: fnData.confidence,
          new_items: fnData.new_items,
          conflicts: fnData.conflicts,
          matched: fnData.matched
        });
        
        const totalItems = fnData.new_items + fnData.conflicts;
        if (totalItems > 0) {
          toast({
            title: `${getTypeLabel(fnData.detected_type)} detected!`,
            description: `Found ${fnData.new_items} new items and ${fnData.conflicts} updates to review.`
          });
        } else if (fnData.matched > 0) {
          toast({
            title: "All items matched",
            description: `${fnData.matched} items already exist in your knowledge base.`
          });
        } else {
          toast({
            title: "Document processed",
            description: "No extractable items found in this document."
          });
        }
      }

      setUploadProgress(100);

    } catch (error) {
      console.error("Upload error:", error);
      toast({
        title: "Upload failed",
        description: error instanceof Error ? error.message : "Unknown error occurred",
        variant: "destructive"
      });
    } finally {
      setIsUploading(false);
      setTimeout(() => setUploadProgress(0), 1000);
    }
  };

  const recentUploads = uploads.slice(0, 3);

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Wand2 className="h-5 w-5 text-primary" />
          Smart Upload
        </CardTitle>
        <CardDescription>
          Drop any document or photo — menus, price lists, hours signs, FAQs — and we'll automatically extract the information.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Drop Zone */}
        <div
          className={cn(
            "border-2 border-dashed rounded-lg p-8 text-center transition-all cursor-pointer",
            isDragging 
              ? "border-primary bg-primary/5 scale-[1.02]" 
              : "border-muted-foreground/25 hover:border-primary/50 hover:bg-muted/30",
            isUploading && "pointer-events-none opacity-50"
          )}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
          onClick={() => fileInputRef.current?.click()}
        >
          <input
            ref={fileInputRef}
            type="file"
            accept={acceptedFormats}
            onChange={handleFileSelect}
            className="hidden"
          />
          
          {isUploading ? (
            <div className="space-y-4">
              <div className="h-14 w-14 mx-auto rounded-full bg-primary/10 flex items-center justify-center">
                <Sparkles className="h-7 w-7 text-primary animate-pulse" />
              </div>
              <div>
                <p className="text-sm font-medium">Analyzing your document...</p>
                <p className="text-xs text-muted-foreground mt-1">AI is detecting the document type and extracting data</p>
              </div>
              <Progress value={uploadProgress} className="max-w-xs mx-auto" />
            </div>
          ) : (
            <>
              <div className="h-14 w-14 mx-auto rounded-full bg-muted flex items-center justify-center mb-3">
                <Upload className="h-7 w-7 text-muted-foreground" />
              </div>
              <p className="text-sm font-medium mb-1">
                Drop your menu, price list, or business photo here
              </p>
              <p className="text-xs text-muted-foreground mb-3">
                We'll automatically figure out what it is and extract the information
              </p>
              <div className="flex items-center justify-center gap-2">
                {formatLabels.map((format) => (
                  <Badge key={format} variant="secondary" className="text-xs">
                    {format}
                  </Badge>
                ))}
              </div>
              <p className="text-xs text-muted-foreground mt-3">
                Max file size: 10MB
              </p>
            </>
          )}
        </div>

        {/* Last Upload Result */}
        {lastResult && (
          <Card className="bg-muted/30 border-primary/20">
            <CardContent className="p-4">
              <div className="flex items-start gap-3">
                <div className="h-10 w-10 rounded-lg bg-primary/15 flex items-center justify-center shrink-0">
                  <Sparkles className="h-5 w-5 text-primary" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-2">
                    <Badge variant="outline" className="bg-primary/10">
                      {getTypeLabel(lastResult.detected_type)}
                    </Badge>
                    <span className="text-xs text-muted-foreground">
                      {Math.round(lastResult.confidence * 100)}% confidence
                    </span>
                  </div>
                  <div className="grid grid-cols-3 gap-4 text-center">
                    <div>
                      <p className="text-lg font-semibold text-primary">{lastResult.new_items}</p>
                      <p className="text-xs text-muted-foreground">New items</p>
                    </div>
                    <div>
                      <p className="text-lg font-semibold text-amber-500">{lastResult.conflicts}</p>
                      <p className="text-xs text-muted-foreground">Updates</p>
                    </div>
                    <div>
                      <p className="text-lg font-semibold text-emerald-500">{lastResult.matched}</p>
                      <p className="text-xs text-muted-foreground">Matched</p>
                    </div>
                  </div>
                  {(lastResult.new_items > 0 || lastResult.conflicts > 0) && (
                    <Button variant="link" size="sm" className="p-0 h-auto mt-2" asChild>
                      <Link to="/app/business-brain?tab=review">
                        Review extracted items →
                      </Link>
                    </Button>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Recent Uploads */}
        {recentUploads.length > 0 && !lastResult && (
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <p className="text-sm font-medium">Recent Uploads</p>
              {processingCount > 0 && (
                <Badge variant="secondary">
                  <Loader2 className="h-3 w-3 mr-1 animate-spin" />
                  {processingCount} processing
                </Badge>
              )}
            </div>
            <div className="space-y-2">
              {recentUploads.map((upload) => (
                <div 
                  key={upload.id} 
                  className="flex items-center justify-between p-2 rounded-lg bg-muted/50"
                >
                  <div className="flex items-center gap-2 min-w-0">
                    <FileIcon fileName={upload.file_name} />
                    <span className="text-sm truncate">{upload.file_name}</span>
                  </div>
                  <UploadStatusBadge status={upload.status} />
                </div>
              ))}
            </div>
            <Button variant="link" size="sm" className="p-0 h-auto" asChild>
              <Link to="/app/business-brain?tab=assets">
                View all uploads →
              </Link>
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

function getTypeLabel(type: string): string {
  const labels: Record<string, string> = {
    menu_pdf: "Menu",
    menu: "Menu",
    services_doc: "Services",
    services: "Services",
    pricing: "Price List",
    hours: "Operating Hours",
    policies: "Policies",
    faq_doc: "FAQs",
    faq: "FAQs",
    general: "Document"
  };
  return labels[type] || "Document";
}

function FileIcon({ fileName }: { fileName: string }) {
  const ext = fileName.split(".").pop()?.toLowerCase();
  
  if (ext === "pdf") return <FileText className="h-4 w-4 text-destructive" />;
  if (["png", "jpg", "jpeg"].includes(ext || "")) return <Image className="h-4 w-4 text-primary" />;
  if (["xlsx", "docx"].includes(ext || "")) return <FileSpreadsheet className="h-4 w-4 text-accent-foreground" />;
  return <File className="h-4 w-4 text-muted-foreground" />;
}

function UploadStatusBadge({ status }: { status: string }) {
  switch (status) {
    case "uploading":
    case "processing":
      return (
        <Badge variant="secondary" className="gap-1">
          <Loader2 className="h-3 w-3 animate-spin" />
          Processing
        </Badge>
      );
    case "ready":
      return (
        <Badge variant="default" className="gap-1">
          <CheckCircle2 className="h-3 w-3" />
          Ready
        </Badge>
      );
    case "failed":
      return (
        <Badge variant="destructive" className="gap-1">
          <XCircle className="h-3 w-3" />
          Failed
        </Badge>
      );
    default:
      return null;
  }
}

import { useState } from "react";
import { usePricingRules, PricingRule } from "@/hooks/usePricingRules";
import { useServices } from "@/hooks/useServices";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { EmptyState } from "@/components/ui/empty-state";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Plus, Pencil, Trash2, DollarSign, Percent, Tag, Loader2, Globe, Briefcase } from "lucide-react";

interface RuleFormData {
  name: string;
  description: string;
  type: "surcharge" | "discount" | "fee";
  amount: number;
  amount_type: "percent" | "fixed";
  scope: "all" | "specific";
  service_id: string | null;
  is_active: boolean;
}

const defaultFormData: RuleFormData = {
  name: "",
  description: "",
  type: "fee",
  amount: 0,
  amount_type: "fixed",
  scope: "all",
  service_id: null,
  is_active: true,
};

export function PricingRulesEditor() {
  const { rules, isLoading, isSaving, addRule, updateRule, deleteRule, toggleRuleActive } = usePricingRules();
  const { services } = useServices();

  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [editingRule, setEditingRule] = useState<PricingRule | null>(null);
  const [deletingRule, setDeletingRule] = useState<PricingRule | null>(null);
  const [formData, setFormData] = useState<RuleFormData>(defaultFormData);

  const openCreateDialog = () => {
    setEditingRule(null);
    setFormData(defaultFormData);
    setDialogOpen(true);
  };

  const openEditDialog = (rule: PricingRule) => {
    setEditingRule(rule);
    setFormData({
      name: rule.name,
      description: rule.description,
      type: rule.type,
      amount: rule.amount,
      amount_type: rule.amount_type,
      scope: rule.service_id ? "specific" : "all",
      service_id: rule.service_id,
      is_active: rule.is_active,
    });
    setDialogOpen(true);
  };

  const handleSave = async () => {
    if (!formData.name.trim()) return;

    const ruleData = {
      name: formData.name,
      description: formData.description,
      type: formData.type,
      amount: formData.amount,
      amount_type: formData.amount_type,
      service_id: formData.scope === "all" ? null : formData.service_id,
      is_active: formData.is_active,
    };

    if (editingRule) {
      await updateRule(editingRule.id, ruleData);
    } else {
      await addRule(ruleData);
    }
    setDialogOpen(false);
  };

  const handleDelete = async () => {
    if (!deletingRule) return;
    await deleteRule(deletingRule.id);
    setDeleteDialogOpen(false);
    setDeletingRule(null);
  };

  const getServiceName = (serviceId: string | null): string => {
    if (!serviceId) return "All services";
    const service = services.find((s) => s.id === serviceId);
    return service?.name || "Unknown service";
  };

  const formatAmount = (rule: PricingRule): string => {
    if (rule.amount_type === "percent") {
      return `${rule.amount}%`;
    }
    return `$${rule.amount.toFixed(2)}`;
  };

  const getTypeLabel = (type: PricingRule["type"]): string => {
    switch (type) {
      case "surcharge":
        return "Surcharge";
      case "discount":
        return "Discount";
      case "fee":
        return "Fee";
    }
  };

  const getTypeBadgeVariant = (type: PricingRule["type"]): "default" | "secondary" | "destructive" | "outline" => {
    switch (type) {
      case "surcharge":
        return "default";
      case "discount":
        return "secondary";
      case "fee":
        return "outline";
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-32">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-medium">Pricing Rules</h3>
          <p className="text-sm text-muted-foreground">
            Add surcharges, discounts, or fees that apply globally or to specific services.
          </p>
        </div>
        <Button onClick={openCreateDialog} className="gap-2">
          <Plus className="h-4 w-4" />
          Add Price Rule
        </Button>
      </div>

      {rules.length > 0 ? (
        <div className="space-y-3">
          {rules.map((rule) => (
            <Card key={rule.id} className={!rule.is_active ? "opacity-60" : ""}>
              <CardContent className="p-4">
                <div className="flex items-start justify-between gap-4">
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span className="font-medium">{rule.name}</span>
                      <Badge variant={getTypeBadgeVariant(rule.type)}>
                        {getTypeLabel(rule.type)}
                      </Badge>
                      <Badge variant="outline" className="gap-1">
                        {rule.amount_type === "percent" ? (
                          <Percent className="h-3 w-3" />
                        ) : (
                          <DollarSign className="h-3 w-3" />
                        )}
                        {formatAmount(rule)}
                      </Badge>
                      {/* Scope Badge */}
                      <Badge
                        variant="secondary"
                        className={`gap-1 ${rule.service_id ? "bg-blue-500/15 text-blue-600" : "bg-emerald-500/15 text-emerald-600"}`}
                      >
                        {rule.service_id ? (
                          <>
                            <Briefcase className="h-3 w-3" />
                            Service: {getServiceName(rule.service_id)}
                          </>
                        ) : (
                          <>
                            <Globe className="h-3 w-3" />
                            All services
                          </>
                        )}
                      </Badge>
                    </div>
                    {rule.description && (
                      <p className="text-sm text-muted-foreground mt-1">{rule.description}</p>
                    )}
                  </div>
                  <div className="flex items-center gap-2">
                    <Switch
                      checked={rule.is_active}
                      onCheckedChange={(checked) => toggleRuleActive(rule.id, checked)}
                    />
                    <Button variant="ghost" size="icon" onClick={() => openEditDialog(rule)}>
                      <Pencil className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="text-destructive hover:text-destructive"
                      onClick={() => {
                        setDeletingRule(rule);
                        setDeleteDialogOpen(true);
                      }}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : (
        <Card>
          <CardContent className="p-0">
            <EmptyState
              icon={Tag}
              title="No pricing rules yet"
              description="Add surcharges, discounts, or fees to customize your pricing."
              action={{
                label: "Add Price Rule",
                onClick: openCreateDialog,
              }}
            />
          </CardContent>
        </Card>
      )}

      {/* Create/Edit Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle>{editingRule ? "Edit Price Rule" : "Add Price Rule"}</DialogTitle>
            <DialogDescription>
              Configure a pricing rule to apply surcharges, discounts, or fees.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Rule Name *</Label>
              <Input
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="e.g., Weekend Surcharge"
              />
            </div>

            <div className="space-y-2">
              <Label>Description</Label>
              <Input
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                placeholder="e.g., Applied to weekend appointments"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Type</Label>
                <Select
                  value={formData.type}
                  onValueChange={(v) => setFormData({ ...formData, type: v as RuleFormData["type"] })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="fee">Fee</SelectItem>
                    <SelectItem value="surcharge">Surcharge</SelectItem>
                    <SelectItem value="discount">Discount</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label>Amount Type</Label>
                <Select
                  value={formData.amount_type}
                  onValueChange={(v) => setFormData({ ...formData, amount_type: v as RuleFormData["amount_type"] })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="fixed">Fixed ($)</SelectItem>
                    <SelectItem value="percent">Percent (%)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label>Amount</Label>
              <Input
                type="number"
                value={formData.amount || ""}
                onChange={(e) => setFormData({ ...formData, amount: parseFloat(e.target.value) || 0 })}
                placeholder={formData.amount_type === "percent" ? "10" : "25.00"}
                step={formData.amount_type === "percent" ? "1" : "0.01"}
              />
            </div>

            <div className="space-y-3">
              <Label>Applies To</Label>
              <RadioGroup
                value={formData.scope}
                onValueChange={(v) => {
                  const scope = v as "all" | "specific";
                  setFormData({
                    ...formData,
                    scope,
                    service_id: scope === "all" ? null : formData.service_id,
                  });
                }}
                className="space-y-2"
              >
                <div className="flex items-center space-x-2">
                  <RadioGroupItem value="all" id="scope-all" />
                  <Label htmlFor="scope-all" className="font-normal cursor-pointer">
                    All services (global rule)
                  </Label>
                </div>
                <div className="flex items-center space-x-2">
                  <RadioGroupItem value="specific" id="scope-specific" />
                  <Label htmlFor="scope-specific" className="font-normal cursor-pointer">
                    Specific service
                  </Label>
                </div>
              </RadioGroup>

              {formData.scope === "specific" && (
                <Select
                  value={formData.service_id || ""}
                  onValueChange={(v) => setFormData({ ...formData, service_id: v || null })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select a service..." />
                  </SelectTrigger>
                  <SelectContent>
                    {services.map((service) => (
                      <SelectItem key={service.id} value={service.id}>
                        {service.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>

            <div className="flex items-center justify-between">
              <Label htmlFor="is-active">Active</Label>
              <Switch
                id="is-active"
                checked={formData.is_active}
                onCheckedChange={(checked) => setFormData({ ...formData, is_active: checked })}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDialogOpen(false)}>
              Cancel
            </Button>
            <Button
              onClick={handleSave}
              disabled={!formData.name.trim() || isSaving || (formData.scope === "specific" && !formData.service_id)}
            >
              {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              {editingRule ? "Save Changes" : "Add Rule"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation */}
      <AlertDialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Pricing Rule?</AlertDialogTitle>
            <AlertDialogDescription>
              Are you sure you want to delete "{deletingRule?.name}"? This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleDelete}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isSaving ? <Loader2 className="h-4 w-4 animate-spin" /> : "Delete"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

import { useState, useRef, useEffect } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import { 
  MessageCircle, Bot, Sparkles, 
  ArrowRight, X, Minimize2, Maximize2, HelpCircle, Volume2
} from "lucide-react";
import { getTierInfo, getDefaultStepForTier } from "@/config/pricing";
import { Link } from "react-router-dom";

interface Message {
  role: 'assistant' | 'user';
  content: string;
  options?: string[];
  quickActions?: string[];
  recommendation?: RecommendedSetup;
}

interface RecommendedSetup {
  businessType: string;
  businessMode: string;
  tier: string;
  planName: string;
  sku: string;
  price: number;
  keyFeatures: string[];
  whyItFits: string[];
}

const discoveryQuestions = [
  {
    id: 'business_type',
    question: "What type of business do you have?",
    options: ['Service business', 'Towing / dispatch', 'Restaurant', 'Medical / Dental', 'Other'],
  },
  {
    id: 'call_volume',
    question: "About how many calls per day?",
    options: ['0–5', '6–20', '21–60', '60+'],
  },
  {
    id: 'channel',
    question: "How should we handle calls?",
    options: ['Voice (AI answers live)', 'SMS (text-back)', 'Both'],
  },
];

function generateRecommendation(answers: Record<string, string>): RecommendedSetup {
  const businessType = answers['business_type'] || '';
  const callVolume = answers['call_volume'] || '';
  const channel = answers['channel'] || '';
  
  let businessMode = 'service';
  let businessTypeDisplay = 'Service Business';
  
  if (businessType.includes('Restaurant')) {
    businessMode = 'food';
    businessTypeDisplay = 'Restaurant / Food';
  } else if (businessType.includes('Medical') || businessType.includes('Dental')) {
    businessMode = 'medical';
    businessTypeDisplay = 'Medical / Healthcare';
  } else if (businessType.includes('Towing') || businessType.includes('dispatch')) {
    businessMode = 'dispatch';
    businessTypeDisplay = 'Towing / Dispatch';
  } else if (businessType.includes('Other')) {
    businessMode = 'general';
    businessTypeDisplay = 'General Business';
  }

  // All channels now map to voice tier (SMS coming soon)
  const tier: 'voice' = 'voice';

  const defaultStep = getDefaultStepForTier(tier);
  let sku = defaultStep?.sku || 'voice-200';
  let price = defaultStep?.price || 249;

  if (callVolume.includes('21–60') || callVolume.includes('60+')) {
    sku = 'voice-600'; price = 299;
  }

  const keyFeatures: string[] = [];
  keyFeatures.push('AI answers calls 24/7');
  keyFeatures.push('Captures customer data automatically');
  keyFeatures.push('Handles objections naturally');

  const whyItFits: string[] = [];
  if (businessMode === 'food') whyItFits.push('Handles orders, reservations, catering');
  else if (businessMode === 'medical') whyItFits.push('Includes intake forms & scheduling');
  else if (businessMode === 'dispatch') whyItFits.push('Prioritizes urgency & location');
  else whyItFits.push('Optimized for booking appointments');

  const tierInfo = getTierInfo(tier);

  return {
    businessType: businessTypeDisplay,
    businessMode,
    tier,
    planName: tierInfo?.displayName || 'Voice + SMS',
    sku,
    price,
    keyFeatures,
    whyItFits,
  };
}

export function SalesAIAgent() {
  const [isOpen, setIsOpen] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);
  const [messages, setMessages] = useState<Message[]>([]);
  const [currentQuestion, setCurrentQuestion] = useState(0);
  const [answers, setAnswers] = useState<Record<string, string>>({});
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (isOpen && messages.length === 0) {
      setMessages([{
        role: 'assistant',
        content: "Hey! I can help you find the right setup in 60 seconds. What would you like to do?",
        quickActions: ["Help me choose a plan", "Will it work for my business?", "Hear a demo call"],
      }]);
    }
  }, [isOpen]);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const askQuestion = (index: number) => {
    if (index < discoveryQuestions.length) {
      const q = discoveryQuestions[index];
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: q.question,
        options: q.options,
      }]);
      setCurrentQuestion(index);
    }
  };

  const showRecommendation = (finalAnswers: Record<string, string>) => {
    const rec = generateRecommendation(finalAnswers);
    setMessages(prev => [...prev, {
      role: 'assistant',
      content: "Based on what you told me, here's my recommendation:",
      recommendation: rec,
    }]);
  };

  const handleQuickAction = (action: string) => {
    setMessages(prev => [...prev, { role: 'user', content: action }]);
    
    if (action.includes("demo")) {
      setTimeout(() => {
        setMessages(prev => [...prev, {
          role: 'assistant',
          content: "Great choice! Scroll down to the 'Hear How It Works' section to play real demo calls for different industries.",
        }]);
        setTimeout(() => setIsOpen(false), 2000);
        document.getElementById('demo')?.scrollIntoView({ behavior: 'smooth' });
      }, 300);
      return;
    }
    
    if (action.includes("work for my business") || action.includes("choose")) {
      setTimeout(() => askQuestion(0), 300);
    }
  };

  const handleOptionClick = (option: string) => {
    setMessages(prev => [...prev, { role: 'user', content: option }]);
    
    const questionId = discoveryQuestions[currentQuestion]?.id;
    if (questionId) {
      const newAnswers = { ...answers, [questionId]: option };
      setAnswers(newAnswers);

      if (currentQuestion >= discoveryQuestions.length - 1) {
        setTimeout(() => showRecommendation(newAnswers), 300);
      } else {
        setTimeout(() => askQuestion(currentQuestion + 1), 300);
      }
    }
  };

  const resetChat = () => {
    setMessages([]);
    setCurrentQuestion(0);
    setAnswers({});
    setIsOpen(false);
  };

  if (!isOpen) {
    return (
      <Button
        onClick={() => setIsOpen(true)}
        className="fixed bottom-24 md:bottom-6 right-4 md:right-6 z-50 h-14 w-14 rounded-full shadow-xl hover:scale-110 transition-all duration-200 bg-primary hover:bg-primary/90"
        size="icon"
      >
        <MessageCircle className="h-6 w-6" />
      </Button>
    );
  }

  return (
    <Card className={`fixed bottom-24 md:bottom-6 right-4 md:right-6 z-50 shadow-2xl border transition-all duration-300 ${
      isMinimized ? 'w-72 h-14' : 'w-[360px] md:w-[400px] h-[520px]'
    }`}>
      {/* Header */}
      <CardHeader className="p-4 border-b flex flex-row items-center justify-between bg-gradient-to-r from-card to-muted/30 rounded-t-lg">
        <div className="flex items-center gap-3">
          <div className="h-11 w-11 rounded-full bg-gradient-to-br from-primary to-primary/80 flex items-center justify-center shadow-md">
            <Bot className="h-5 w-5 text-primary-foreground" />
          </div>
          <div>
            <CardTitle className="text-sm font-semibold">CloseLoop Assistant</CardTitle>
            {!isMinimized && (
              <p className="text-xs text-muted-foreground">Find your perfect setup</p>
            )}
          </div>
        </div>
        <div className="flex items-center gap-1">
          <Button 
            variant="ghost" 
            size="icon" 
            className="h-8 w-8 hover:bg-muted"
            onClick={() => setIsMinimized(!isMinimized)}
          >
            {isMinimized ? <Maximize2 className="h-4 w-4" /> : <Minimize2 className="h-4 w-4" />}
          </Button>
          <Button 
            variant="ghost" 
            size="icon" 
            className="h-8 w-8 hover:bg-muted"
            onClick={resetChat}
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
      </CardHeader>

      {!isMinimized && (
        <>
          {/* Messages */}
          <ScrollArea className="h-[400px] p-4" ref={scrollRef}>
            <div className="space-y-4">
              {messages.map((msg, i) => (
                <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className="max-w-[90%]">
                    <div className={`rounded-2xl px-4 py-3 text-sm ${
                      msg.role === 'user' 
                        ? 'bg-primary text-primary-foreground' 
                        : 'bg-muted'
                    }`}>
                      <p>{msg.content}</p>
                    </div>
                    
                    {/* Quick Actions */}
                    {msg.quickActions && (
                      <div className="flex flex-col gap-2 mt-3">
                        {msg.quickActions.map((action, j) => (
                          <Button
                            key={j}
                            variant="outline"
                            size="sm"
                            onClick={() => handleQuickAction(action)}
                            className="justify-start text-left h-auto py-2.5 px-4 text-sm hover:bg-primary/5 hover:border-primary/30 transition-colors"
                          >
                            {action.includes("demo") && <Volume2 className="h-4 w-4 mr-2 shrink-0 text-primary" />}
                            {action.includes("work") && <HelpCircle className="h-4 w-4 mr-2 shrink-0 text-primary" />}
                            {action.includes("choose") && <Sparkles className="h-4 w-4 mr-2 shrink-0 text-primary" />}
                            {action}
                          </Button>
                        ))}
                      </div>
                    )}
                    
                    {/* Options */}
                    {msg.options && (
                      <div className="flex flex-wrap gap-2 mt-3">
                        {msg.options.map((opt, j) => (
                          <Button
                            key={j}
                            variant="outline"
                            size="sm"
                            onClick={() => handleOptionClick(opt)}
                            className="text-sm h-9 hover:bg-primary/5 hover:border-primary/30 transition-colors"
                          >
                            {opt}
                          </Button>
                        ))}
                      </div>
                    )}

                    {/* Recommendation Card */}
                    {msg.recommendation && (
                      <Card className="mt-4 border-primary/30 shadow-md">
                        <CardContent className="p-5 space-y-4">
                          <div className="flex items-center justify-between">
                            <Badge className="gap-1 bg-primary text-primary-foreground px-3 py-1">
                              <Sparkles className="h-3 w-3" />
                              Recommended
                            </Badge>
                            <span className="font-bold text-2xl">
                              ${msg.recommendation.price}<span className="text-sm font-normal text-muted-foreground">/mo</span>
                            </span>
                          </div>

                          <div className="space-y-1.5 text-sm">
                            <p><span className="text-muted-foreground">Type:</span> <span className="font-medium">{msg.recommendation.businessType}</span></p>
                            <p><span className="text-muted-foreground">Plan:</span> <span className="font-medium">{msg.recommendation.planName}</span></p>
                          </div>

                          <div>
                            <p className="text-xs font-semibold text-muted-foreground mb-2 uppercase tracking-wide">What you get:</p>
                            <ul className="text-sm space-y-1.5">
                              {msg.recommendation.keyFeatures.map((f, k) => (
                                <li key={k} className="flex items-center gap-2">
                                  <span className="text-primary font-bold">✓</span> {f}
                                </li>
                              ))}
                            </ul>
                          </div>

                          <Link 
                            to={`/signup?tier=${msg.recommendation.tier}&sku=${msg.recommendation.sku}&mode=${msg.recommendation.businessMode}`}
                            className="block"
                          >
                            <Button className="w-full gap-2 h-11 font-semibold">
                              Start with this setup
                              <ArrowRight className="h-4 w-4" />
                            </Button>
                          </Link>
                          
                          <p className="text-xs text-center text-muted-foreground">
                            Setup in ~10 min • Cancel anytime
                          </p>
                        </CardContent>
                      </Card>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </ScrollArea>

          {/* Footer */}
          <div className="p-3 border-t bg-muted/20">
            <p className="text-xs text-center text-muted-foreground">
              Powered by CloseLoop
            </p>
          </div>
        </>
      )}
    </Card>
  );
}

import { Card, CardContent } from "@/components/ui/card";
