  const sidebarSubtitle = useMemo(() => {
    const tagline = (assistantSettings as Record<string, unknown> | null)?.business_tagline as string | undefined;
    if (tagline) return tagline;
    if (catalog?.name) return `AI for ${catalog.name}`;
    return "AI Receptionist";
  }, [assistantSettings, catalog]);

  // Mobile nav - simplified (unchanged from before)
  const mobileNavItems = useMemo(() => {
    const items: NavItem[] = [
      { href: "/app/dashboard", label: "Home", icon: LayoutDashboard },
      { href: "/app/inbox", label: (terms.inboxPageTitle as string) || "Leads", icon: caps.isDispatchBusiness ? Phone : Users },
    ];
    if (caps.isFoodBusiness && caps.hasFoodOrders) {
      items.push({ href: "/app/orders", label: "Orders", icon: UtensilsCrossed });
    } else if (caps.isDispatchBusiness && caps.hasDispatchQueue) {
      items.push({ href: "/app/dispatch", label: "Jobs", icon: Truck });
    } else if (caps.isSalesBusiness && caps.hasSalesLeads) {
      items.push({ href: "/app/sales-pipeline", label: "Pipeline", icon: DollarSign });
    } else if (caps.hasBooking) {
      items.push({ href: "/app/bookings", label: terms.bookingsPageTitle || "Bookings", icon: Calendar });
    }
    items.push({ href: "/app/business-brain", label: "Setup", icon: Bot });
    items.push({ href: "/app/settings", label: "Settings", icon: Settings });
    return items.slice(0, 5);
  }, [enabledModules, caps, terms]);

  useEffect(() => {
    if (!loading && !user) navigate("/login");
  }, [user, loading, navigate]);

  useEffect(() => {
    if (!loading && user && !tenant && !isSuperAdmin && !isAgency && !isAgencyLoading) {
      if (location.pathname !== "/app/onboarding") navigate("/app/onboarding");
    }
  }, [loading, user, tenant, isSuperAdmin, isAgency, isAgencyLoading, location.pathname, navigate]);

  // Clear selectedPlan bypass once a real subscription is confirmed
  useEffect(() => {
    if (!loading && hasActiveSubscription) {
      sessionStorage.removeItem("selectedPlan");
    }
  }, [loading, hasActiveSubscription]);

  useEffect(() => {
    if (isSuperAdmin) return;
    // Agency users accessing agency dashboard should never be redirected
    if (isAgency && location.pathname.startsWith("/app/agency")) return;
    // Don't redirect from /app/agency while agency status is still loading
    if (isAgencyLoading && location.pathname.startsWith("/app/agency")) return;
    const justCompletedOnboarding = sessionStorage.getItem("selectedPlan") !== null;
    if (justCompletedOnboarding) return;
    if (!loading && tenant && !hasActiveSubscription) {
      const isAllowedRoute = alwaysAccessibleRoutes.some(route => location.pathname.startsWith(route));
      if (!isAllowedRoute && location.pathname !== "/app/go-live") {
        navigate("/app/go-live");
      }
    }
  }, [loading, tenant, hasActiveSubscription, isSuperAdmin, isAgency, isAgencyLoading, location.pathname, navigate]);

  const handleSignOut = async () => {
    await signOut();
    navigate("/");
  };

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-background">
        <div className="animate-spin rounded-full h-8 w-8 border-2 border-primary border-t-transparent" />
      </div>
    );
  }

  if (!user) return null;

  const isRouteAccessible = effectiveHasSubscription || alwaysAccessibleRoutes.some(route => location.pathname.startsWith(route)) || (isAgency && location.pathname.startsWith("/app/agency"));

  return (
    <>
      {/* Super Admin Bar — full width, above everything */}
      {isSuperAdmin && (
        <header className="hidden md:flex fixed top-0 left-0 right-0 z-50 h-10 bg-background/95 backdrop-blur-lg border-b border-border/20 items-center justify-between px-4">
          <Link
            to="/admin/overview"
            className="flex items-center gap-1.5 text-xs font-semibold text-primary hover:text-primary/80 transition-colors"
          >
            <Lock className="h-3 w-3" />
            Admin Dashboard
          </Link>
          <div className="flex items-center gap-3">
            <div className="flex items-center gap-2 text-warning mr-2">
              <FlaskConical className="h-3.5 w-3.5" />
              <span className="text-[11px] font-semibold uppercase tracking-wider">Admin Testing</span>
            </div>
            <AdminModeSelector />
            <AdminTenantSwitcher />
          </div>
        </header>
      )}

      <div className={cn("flex min-h-screen", isSuperAdmin && "md:pt-10")}>
        {/* App Sidebar */}
        <AppSidebar
          enabledModules={enabledModules}
          caps={caps}
          terms={terms}
          conflictsCount={conflictsCount}
          effectiveHasSubscription={effectiveHasSubscription}
          displayTenant={displayTenant}
          subtitle={sidebarSubtitle}
          open={sidebarOpen}
          setOpen={setSidebarOpen}
          showAgency={showAgency}
          isAgencyOnly={isAgency && !tenant}
        />

        {/* Content area */}
        <div className="flex-1 min-w-0">
          {/* Slim top bar — desktop only */}
          <SlimTopBar
            userEmail={user.email || ""}
            tenantName={displayTenant?.name}
            onSignOut={handleSignOut}
            isSuperAdmin={isSuperAdmin}
          />

          {/* Trial banner — shown when subscription is trialing */}
          <TrialBanner />

          <MobileHeader
            displayTenant={displayTenant}
            userEmail={user.email || ""}
            onSignOut={handleSignOut}
            onToggleSidebar={() => setSidebarOpen(!sidebarOpen)}
          />

          {/* Page content */}
          <div className={cn(
            "flex-1",
            "pt-14 md:pt-0", // Mobile header offset (mobile only — desktop slim bar is in flow)
            "pb-16 md:pb-0" // Mobile bottom nav
          )}>
            {isRouteAccessible ? (
              <AnimatePresence mode="wait" initial={false}>
                <motion.div
                  key={location.pathname}
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0, transition: { duration: 0.2, ease: "easeOut" } }}
                  exit={{ opacity: 0, y: -4, transition: { duration: 0.15 } }}
                >
                  <Outlet />
                </motion.div>
              </AnimatePresence>
            ) : (
              <div className="p-6 flex items-center justify-center min-h-[60vh]">
                <Card className="max-w-md text-center">
                  <CardHeader className="pb-4">
                    <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-muted mb-4">
                      <Lock className="h-7 w-7 text-muted-foreground" />
                    </div>
                    <CardTitle>Subscription Required</CardTitle>
                    <CardDescription className="mt-2">
                      Choose a plan to unlock all features.
                    </CardDescription>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <Button onClick={() => navigate("/app/go-live")} className="w-full" size="lg">
                      <CreditCard className="mr-2 h-4 w-4" />
                      Choose a Plan
                    </Button>
                  </CardContent>
                </Card>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Mobile Bottom Nav — unchanged */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 z-30 h-16 bg-background/95 backdrop-blur-lg border-t border-border/20 safe-area-pb">
        <div className="grid grid-cols-5 h-full">
          {mobileNavItems.map((item) => {
            const Icon = item.icon;
            const isActive = location.pathname === item.href;
            return (
              <Link
                key={item.href}
                to={item.href}
                className={cn(
                  "flex flex-col items-center justify-center gap-0.5",
                  isActive ? "text-primary" : "text-muted-foreground"
                )}
              >
                <Icon className="h-5 w-5" />
                <span className="text-[10px] font-medium">{item.label}</span>
              </Link>
            );
          })}
        </div>
      </nav>
    </>
  );
}

/** Mobile header */
function MobileHeader({
  displayTenant,
  userEmail,
  onSignOut,
  onToggleSidebar,
}: {
  displayTenant: { name?: string } | null;
  userEmail: string;
  onSignOut: () => void;
  onToggleSidebar: () => void;
}) {
  const navigate = useNavigate();

  return (
    <header className="md:hidden fixed top-0 left-0 right-0 z-40 h-14 bg-background/95 backdrop-blur-lg border-b border-border/20 flex items-center justify-between px-4">
      <div className="flex items-center gap-3">
        <Button
          variant="ghost"
          size="icon"
          onClick={onToggleSidebar}
          className="h-9 w-9"
        >
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round">
            <line x1="3" y1="5" x2="17" y2="5" />
            <line x1="3" y1="10" x2="17" y2="10" />
            <line x1="3" y1="15" x2="17" y2="15" />
          </svg>
        </Button>
        <div className="flex items-center gap-2">
          <div className="h-7 w-7 rounded-lg gradient-brand flex items-center justify-center">
            <AudioWaveform className="h-3.5 w-3.5 text-white" />
          </div>
          <span className="font-semibold text-sm">{displayTenant?.name || BRAND.name}</span>
        </div>
      </div>
      <div className="flex items-center gap-1">
        <NotificationBell />
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="icon" className="h-9 w-9 rounded-full">
              <Avatar className="h-7 w-7">
                <AvatarFallback className="bg-primary/20 text-primary text-xs">
                  {userEmail?.[0]?.toUpperCase()}
                </AvatarFallback>
              </Avatar>
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-56">
            <div className="px-3 py-2.5">
              <p className="text-sm font-medium truncate">{userEmail}</p>
            </div>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={onSignOut} className="text-destructive">
              <LogOut className="mr-2 h-4 w-4" />
              Sign out
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </header>
  );
}

export function AppLayout() {
  return (
    <AdminModeProvider>
      <DispatchJobListener />
      <CommandPalette />
      <AppLayoutContent />
    </AdminModeProvider>
  );
}

import { useLocation } from "react-router-dom";
import {
  LayoutDashboard,
  MessageSquare,
  Calendar,
  Settings,
  Bot,
  Route,
  FlaskConical,
  Lock,
  Truck,
  UtensilsCrossed,
  Clock,
  Cake,
  Stethoscope,
  HelpCircle,
  FileText,
  BarChart3,
  Warehouse,
  Users,
  UserCircle,
  AudioWaveform,
  DollarSign,
  Car,
  Sparkles,
  ClipboardCheck,
  Phone,
  Building2,
  Package,
  ChefHat,
  Heart,
  FileCheck,
  UserSearch,
  Map,
  Presentation,
} from "lucide-react";
import { motion } from "framer-motion";
import { Link } from "react-router-dom";
import {
  AnimatedSidebar,
  SidebarBody,
  SidebarLink,
  useAnimatedSidebar,
} from "@/components/ui/animated-sidebar";
import { BRAND } from "@/config/brand";
import { cn } from "@/lib/utils";

interface NavItem {
  href: string;
  label: string;
  icon: React.ReactNode;
  badge?: number;
}

const alwaysAccessibleRoutes = ["/app/settings", "/app/go-live", "/app/agency"];

interface AppSidebarProps {
  enabledModules: string[];
  caps: {
    hasDispatchQueue: boolean;
    hasImpoundLot: boolean;
    hasFleetManagement: boolean;
    hasBooking: boolean;
    hasFoodOrders: boolean;
    hasReservations: boolean;
    hasCatering: boolean;
    hasMedicalIntake: boolean;
    hasSalesLeads: boolean;
    hasTestDrives: boolean;
    hasSalesInventory: boolean;
    hasEstimates: boolean;
    hasPhoneQuotes: boolean;
    hasJobTracking: boolean;
    hasLeadFollowUp: boolean;
    isFoodBusiness: boolean;
    isDispatchBusiness: boolean;
    isServiceBusiness: boolean;
    [key: string]: unknown;
  };
  terms: { bookingsPageTitle?: string; [key: string]: unknown };
  conflictsCount: number;
  effectiveHasSubscription: boolean;
  displayTenant: { name?: string } | null;
  subtitle?: string;
  open: boolean;
  setOpen: React.Dispatch<React.SetStateAction<boolean>>;
  showAgency?: boolean;
  isAgencyOnly?: boolean;
}

export function AppSidebar({
  enabledModules,
  caps,
  terms,
  conflictsCount,
  effectiveHasSubscription,
  displayTenant,
  subtitle,
  open,
  setOpen,
  showAgency,
  isAgencyOnly,
}: AppSidebarProps) {
  const location = useLocation();

  const iconClass = "h-4 w-4 shrink-0";

  // Build workspace items (capability-gated)
  const workspaceItems: NavItem[] = [];
  if (caps.hasBooking) {
    workspaceItems.push({ href: "/app/bookings", label: terms.bookingsPageTitle || "Bookings", icon: <Calendar className={iconClass} /> });
  }
  if (caps.hasDispatchQueue) {
    workspaceItems.push({ href: "/app/dispatch", label: "Dispatch", icon: <Truck className={iconClass} /> });
  }
  if (caps.hasImpoundLot) {
    workspaceItems.push({ href: "/app/impound-lot", label: "Impound Lot", icon: <Warehouse className={iconClass} /> });
  }
  if (caps.hasFleetManagement) {
    workspaceItems.push({ href: "/app/fleet", label: caps.isDispatchBusiness ? "Fleet" : "Team", icon: <Users className={iconClass} /> });
  }
  if (caps.hasFoodOrders) {
    workspaceItems.push({ href: "/app/orders", label: "Orders", icon: <UtensilsCrossed className={iconClass} /> });
  }
  if (caps.hasReservations) {
    workspaceItems.push({ href: "/app/reservations", label: "Reservations", icon: <Clock className={iconClass} /> });
  }
  if (caps.hasCatering) {
    workspaceItems.push({ href: "/app/catering", label: "Catering", icon: <Cake className={iconClass} /> });
  }
  if (caps.hasMedicalIntake) {
    workspaceItems.push({ href: "/app/medical-intake", label: "Patients", icon: <Stethoscope className={iconClass} /> });
  }
  if (caps.hasSalesLeads) {
    workspaceItems.push({ href: "/app/sales-pipeline", label: "Sales Pipeline", icon: <DollarSign className={iconClass} /> });
  }
  if (caps.hasTestDrives) {
    workspaceItems.push({ href: "/app/test-drives", label: "Test Drives", icon: <Car className={iconClass} /> });
  }
  if (caps.hasSalesInventory) {
    workspaceItems.push({ href: "/app/sales-inventory", label: "Inventory", icon: <Warehouse className={iconClass} /> });
  }
  if (caps.hasEstimates || caps.hasPhoneQuotes) {
    workspaceItems.push({ href: "/app/estimates", label: "Estimates", icon: <FileText className={iconClass} /> });
  }
  if (caps.hasJobTracking) {
    workspaceItems.push({ href: "/app/jobs", label: "Active Jobs", icon: <ClipboardCheck className={iconClass} /> });
  }
  if (caps.hasJobTracking) {
    workspaceItems.push({ href: "/app/time-tracking", label: "Time Tracking", icon: <Clock className={iconClass} /> });
  }
  if (caps.hasJobTracking) {
    workspaceItems.push({ href: "/app/inventory", label: "Parts Inventory", icon: <Package className={iconClass} /> });
  }
  if (caps.hasFoodOrders) {
    workspaceItems.push({ href: "/app/kitchen", label: "Kitchen Display", icon: <ChefHat className={iconClass} /> });
  }
  if (caps.hasFoodOrders || caps.hasReservations) {
    workspaceItems.push({ href: "/app/loyalty", label: "Loyalty", icon: <Heart className={iconClass} /> });
  }
  if (caps.hasBooking || caps.hasJobTracking) {
    workspaceItems.push({ href: "/app/agreements", label: "Agreements", icon: <FileCheck className={iconClass} /> });
  }
  if (caps.hasDispatchQueue) {
    workspaceItems.push({ href: "/app/dispatch-map", label: "Dispatch Map", icon: <Map className={iconClass} /> });
  }

  const coreItems: NavItem[] = [
    { href: "/app/dashboard", label: "Dashboard", icon: <LayoutDashboard className={iconClass} /> },
    { href: "/app/inbox", label: (terms.inboxPageTitle as string) || "Leads", icon: caps.isDispatchBusiness ? <Phone className={iconClass} /> : <Users className={iconClass} /> },
    { href: "/app/customers", label: (terms.customers ? String(terms.customers).charAt(0).toUpperCase() + String(terms.customers).slice(1) : "Customers"), icon: <UserCircle className={iconClass} /> },
    ...(caps.hasLeadFollowUp ? [{ href: "/app/leads/recovery", label: "Lead Recovery", icon: <UserSearch className={iconClass} /> }] : []),
  ];

  const aiCenterItems: NavItem[] = [
    { href: "/app/business-brain", label: "Business Brain", icon: <Bot className={iconClass} />, badge: conflictsCount || undefined },
    { href: "/app/simulator", label: "Test Your AI", icon: <FlaskConical className={iconClass} /> },
    { href: "/app/partner", label: "AI Insights", icon: <Sparkles className={iconClass} /> },
  ];

  const manageItems: NavItem[] = [
    { href: "/app/integrations", label: "Integrations", icon: <Route className={iconClass} /> },
    { href: "/app/reports/roi", label: "Reports", icon: <BarChart3 className={iconClass} /> },
    ...(showAgency ? [{ href: "/app/agency", label: "Agency", icon: <Building2 className={iconClass} /> }] : []),
    { href: "/app/settings", label: "Settings", icon: <Settings className={iconClass} /> },
  ];

  const bottomItems: NavItem[] = [
    { href: "/app/help", label: "Help", icon: <HelpCircle className={iconClass} /> },
  ];

  const renderLink = (item: NavItem) => {
    const isActive = location.pathname === item.href;
    const isLocked = !effectiveHasSubscription && !alwaysAccessibleRoutes.some(route => item.href.startsWith(route));
    return (
      <SidebarLink
        key={item.href}
        link={{ label: item.label, href: item.href, icon: item.icon, badge: item.badge }}
        isActive={isActive}
        isLocked={isLocked}
      />
    );
  };

  // Agency-only users get a full agency-optimized sidebar
  if (isAgencyOnly) {
    const agencyCoreItems: NavItem[] = [
      { href: "/app/agency", label: "Dashboard", icon: <LayoutDashboard className={iconClass} /> },
      { href: "/app/agency/clients", label: "Clients", icon: <Building2 className={iconClass} /> },
    ];

    const agencyGrowthItems: NavItem[] = [
      { href: "/app/agency/leads", label: "Lead Finder", icon: <UserSearch className={iconClass} /> },
      { href: "/app/agency/leads/saved", label: "Saved Leads", icon: <Users className={iconClass} /> },
    ];

    const agencyBusinessItems: NavItem[] = [
      { href: "/app/agency/demos", label: "Demos", icon: <Presentation className={iconClass} /> },
      { href: "/app/agency/commissions", label: "Commissions", icon: <DollarSign className={iconClass} /> },
      { href: "/app/agency/reports", label: "Reports", icon: <BarChart3 className={iconClass} /> },
    ];

    const agencyManageItems: NavItem[] = [
      { href: "/app/settings", label: "Settings", icon: <Settings className={iconClass} /> },
    ];

    return (
      <AnimatedSidebar open={open} setOpen={setOpen}>
        <SidebarBody className="justify-between gap-6">
          <div className="flex flex-col flex-1 overflow-y-auto overflow-x-hidden">
            {/* CORE */}
            {open && <p className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground/40 px-3 pt-1 pb-1">Agency</p>}
            <div className="flex flex-col gap-0.5">
              {agencyCoreItems.map(renderLink)}
            </div>

            {/* GROWTH */}
            {open && <p className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground/40 px-3 pt-4 pb-1">Growth</p>}
            <div className={cn("flex flex-col gap-0.5", !open && "mt-4")}>
              {agencyGrowthItems.map(renderLink)}
            </div>

            {/* BUSINESS */}
            {open && <p className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground/40 px-3 pt-4 pb-1">Business</p>}
            <div className={cn("flex flex-col gap-0.5", !open && "mt-4")}>
              {agencyBusinessItems.map(renderLink)}
            </div>

            {/* MANAGE */}
            {open && <p className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground/40 px-3 pt-4 pb-1">Manage</p>}
            <div className={cn("flex flex-col gap-0.5", !open && "mt-4")}>
              {agencyManageItems.map(renderLink)}
            </div>
          </div>

          {/* Bottom */}
          <div className="flex flex-col gap-0.5">
            {bottomItems.map(renderLink)}
          </div>
        </SidebarBody>
      </AnimatedSidebar>
    );
  }

  return (
    <AnimatedSidebar open={open} setOpen={setOpen}>
      <SidebarBody className="justify-between gap-6">
        <div className="flex flex-col flex-1 overflow-y-auto overflow-x-hidden">
          {/* MAIN */}
          {open && <p className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground/40 px-3 pt-1 pb-1">Main</p>}
          <div className="flex flex-col gap-0.5">
            {coreItems.map(renderLink)}
          </div>

          {/* Workspace items */}
          {workspaceItems.length > 0 && (
            <div className="flex flex-col gap-0.5 mt-3">
              {workspaceItems.map(renderLink)}
            </div>
          )}

          {/* AI CENTER */}
          {open && <p className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground/40 px-3 pt-4 pb-1">AI Center</p>}
          <div className={cn("flex flex-col gap-0.5", !open && "mt-4")}>
            {aiCenterItems.map(renderLink)}
          </div>

          {/* MANAGE */}
          {open && <p className="text-[10px] font-medium uppercase tracking-widest text-muted-foreground/40 px-3 pt-4 pb-1">Manage</p>}
          <div className={cn("flex flex-col gap-0.5", !open && "mt-4")}>
            {manageItems.map(renderLink)}
          </div>
        </div>

        {/* Bottom */}
        <div className="flex flex-col gap-0.5">
          {bottomItems.map(renderLink)}
        </div>
      </SidebarBody>
    </AnimatedSidebar>
  );
}

import { useState } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useLeads } from "@/hooks/useLeads";
import { toast } from "sonner";

interface CreateLeadDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

export function CreateLeadDialog({ open, onOpenChange }: CreateLeadDialogProps) {
  const { createLead } = useLeads();
  const [fullName, setFullName] = useState("");
  const [phone, setPhone] = useState("");
  const [email, setEmail] = useState("");
  const [source, setSource] = useState("manual");
  const [notes, setNotes] = useState("");

  const resetForm = () => {
    setFullName("");
    setPhone("");
    setEmail("");
    setSource("manual");
    setNotes("");
  };

  const handleSubmit = async () => {
    if (!fullName.trim()) {
      toast.error("Please enter a name");
      return;
    }

    try {
      await createLead.mutateAsync({
        full_name: fullName.trim(),
        phone: phone.trim() || null,
        email: email.trim() || null,
        source: source as any,
        status: "new",
        vehicle_or_context: notes.trim() || null,
      } as any);
      toast.success("Lead created");
      resetForm();
      onOpenChange(false);
    } catch {
      toast.error("Failed to create lead");
    }
  };

  return (
    <Dialog open={open} onOpenChange={(v) => { if (!v) resetForm(); onOpenChange(v); }}>
      <DialogContent className="sm:max-w-md">
        <DialogHeader>
          <DialogTitle>Add Lead</DialogTitle>
          <DialogDescription>
            Manually add a new lead to your pipeline
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          <div className="space-y-2">
            <Label htmlFor="lead-name">Full Name *</Label>
            <Input
              id="lead-name"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              placeholder="John Doe"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="lead-phone">Phone</Label>
            <Input
              id="lead-phone"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              placeholder="+1 (555) 123-4567"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="lead-email">Email</Label>
            <Input
              id="lead-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="john@example.com"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="lead-source">Source</Label>
            <Select value={source} onValueChange={setSource}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="manual">Manual</SelectItem>
                <SelectItem value="referral">Referral</SelectItem>
                <SelectItem value="website_form">Website</SelectItem>
                <SelectItem value="walk_in">Walk-in</SelectItem>
              </SelectContent>
            </Select>
          </div>

          <div className="space-y-2">
            <Label htmlFor="lead-notes">Notes</Label>
            <Textarea
              id="lead-notes"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              placeholder="Any additional notes..."
              rows={2}
            />
          </div>
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => { resetForm(); onOpenChange(false); }}>
            Cancel
          </Button>
          <Button onClick={handleSubmit} disabled={createLead.isPending || !fullName.trim()}>
            {createLead.isPending ? "Creating..." : "Add Lead"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

