                  "h-12 w-12 rounded-full flex items-center justify-center text-lg font-bold shrink-0",
                  temp ? `${temp.bgCls}` : "bg-primary/10 text-primary"
                )}>
                  {lead.full_name.charAt(0).toUpperCase()}
