                      </div>
                      <div className="text-right shrink-0">
                        <p className="text-xs text-muted-foreground">
                          {format(new Date(call.started_at), "MMM d")}
                        </p>
                        <p className="text-xs text-muted-foreground">
                          {format(new Date(call.started_at), "h:mm a")}
                        </p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </>
          )}

          {/* Bottom Actions */}
          <Separator />
          <div className="flex gap-2">
            {lead.phone && (
              <Button
                variant="outline"
                size="sm"
