              recipientName={lead.full_name}
              customerId={lead.customer_id ?? undefined}
            />
          )}
        </div>
      </SheetContent>
    </Sheet>
  );
}

/**
 * DispatchJobListener - Global realtime listener for new dispatch jobs
 * 
 * This component subscribes to dispatch_jobs INSERT events and shows
 * toast notifications regardless of which page the user is viewing.
 * Should be mounted in AppLayout for dispatch-enabled tenants.
 */

import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { supabase } from "@/integrations/supabase/client";
import { toast as sonnerToast } from "sonner";
import { useQueryClient } from "@tanstack/react-query";

interface DispatchJobPayload {
  id: string;
  job_number?: string;
  customer_name: string | null;
  pickup_address: string | null;
  priority: string;
  status: string;
}

export function DispatchJobListener() {
  const { tenant } = useAuth();
  const { enabledModules } = useTenantConfig();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const isDispatchEnabled = enabledModules.includes("dispatch_queue");

  useEffect(() => {
    // Only subscribe if dispatch module is enabled
    if (!tenant?.id || !isDispatchEnabled) return;

    const channel = supabase
      .channel("global-dispatch-alerts")
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "dispatch_jobs",
          filter: `tenant_id=eq.${tenant.id}`,
        },
        (payload) => {
          const newJob = payload.new as DispatchJobPayload;
          
          // Play notification sound
          try {
            const audio = new Audio("/notification.mp3");
            audio.volume = 0.5;
            audio.play().catch(() => {});
          } catch {}

          // Show global toast with View action
          sonnerToast.info("🚨 New Dispatch Job!", {
            description: `${newJob.customer_name || "Customer"} - ${newJob.pickup_address?.slice(0, 50) || "Unknown location"}`,
            duration: 15000,
            action: {
              label: "View",
              onClick: () => {
                navigate(`/app/dispatch?highlight=${newJob.id}`);
              },
            },
          });

          // Invalidate dispatch queries so the list updates when they navigate
          queryClient.invalidateQueries({ queryKey: ["dispatch-jobs"] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [tenant?.id, isDispatchEnabled, navigate, queryClient]);

  // This component doesn't render anything - it's just a listener
  return null;
}

import { useEffect, useCallback, useRef } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useNavigate } from "react-router-dom";
import { Button } from "@/components/ui/button";

type SoundType = "order" | "call" | "lead" | "urgent" | "notification";

interface SoundConfig {
  frequency: number;
  duration: number;
  type: OscillatorType;
  repeat?: number;
  delay?: number;
}

const SOUND_CONFIGS: Record<SoundType, SoundConfig> = {
  order: { frequency: 800, duration: 0.15, type: "sine", repeat: 3, delay: 0.1 }, // Kitchen bell
  call: { frequency: 600, duration: 0.2, type: "sine", repeat: 2, delay: 0.15 },
  lead: { frequency: 440, duration: 0.1, type: "sine" },
  urgent: { frequency: 900, duration: 0.1, type: "square", repeat: 4, delay: 0.08 },
  notification: { frequency: 520, duration: 0.1, type: "sine" },
};

export function useSoundManager() {
  const audioContextRef = useRef<AudioContext | null>(null);
  const soundEnabledRef = useRef(true);

  // Initialize audio context on first user interaction
  const initAudio = useCallback(() => {
    if (!audioContextRef.current) {
      // WebKit prefix for older Safari versions
      const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      audioContextRef.current = new AudioContextClass();
    }
    return audioContextRef.current;
  }, []);

  const playSound = useCallback(async (type: SoundType) => {
    if (!soundEnabledRef.current) return;
    
    try {
      const ctx = initAudio();
      const config = SOUND_CONFIGS[type];
      const repeat = config.repeat || 1;
      const delay = config.delay || 0;

      for (let i = 0; i < repeat; i++) {
        const startTime = ctx.currentTime + (i * (config.duration + delay));
        
        const oscillator = ctx.createOscillator();
        const gainNode = ctx.createGain();
        
        oscillator.connect(gainNode);
        gainNode.connect(ctx.destination);
        
        oscillator.frequency.value = config.frequency;
        oscillator.type = config.type;
        
        // Fade in/out for smoother sound
        gainNode.gain.setValueAtTime(0, startTime);
        gainNode.gain.linearRampToValueAtTime(0.3, startTime + 0.02);
        gainNode.gain.linearRampToValueAtTime(0, startTime + config.duration);
        
        oscillator.start(startTime);
        oscillator.stop(startTime + config.duration);
      }
    } catch {
      // Audio playback not available - silently fail
    }
  }, [initAudio]);

  const setSoundEnabled = useCallback((enabled: boolean) => {
    soundEnabledRef.current = enabled;
  }, []);

  return { playSound, setSoundEnabled, initAudio };
}

export function SoundManager() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const { playSound, setSoundEnabled, initAudio } = useSoundManager();
  const processedEventsRef = useRef<Set<string>>(new Set());

  // Load sound preference
  useEffect(() => {
    const stored = localStorage.getItem("notificationSoundsEnabled");
    setSoundEnabled(stored !== "false");
  }, [setSoundEnabled]);

  // Initialize audio on first user interaction
  useEffect(() => {
    const handleInteraction = () => {
      initAudio();
      document.removeEventListener('click', handleInteraction);
      document.removeEventListener('keydown', handleInteraction);
    };
    
    document.addEventListener('click', handleInteraction, { once: true });
    document.addEventListener('keydown', handleInteraction, { once: true });
    
    return () => {
      document.removeEventListener('click', handleInteraction);
      document.removeEventListener('keydown', handleInteraction);
    };
  }, [initAudio]);

  // Subscribe to realtime events
  useEffect(() => {
    if (!tenant?.id) return;

    const channel = supabase
      .channel('sound-manager')
      // New food orders
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'food_orders', filter: `tenant_id=eq.${tenant.id}` },
        (payload) => {
          const eventId = `order-${payload.new.id}`;
          if (processedEventsRef.current.has(eventId)) return;
          processedEventsRef.current.add(eventId);
          
          playSound("order");
          const order = payload.new as { order_number?: string; order_type?: string };
          toast({
            title: "🍽️ New Order!",
            description: `Order #${order.order_number} - ${order.order_type?.toUpperCase() || "Pickup"}`,
            action: (
              <Button 
                size="sm" 
                variant="secondary"
                onClick={() => navigate("/app/orders")}
              >
                View
              </Button>
            ),
          });
        }
      )
      // New calls
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'ai_call_sessions', filter: `tenant_id=eq.${tenant.id}` },
        (payload) => {
          const eventId = `call-${payload.new.id}`;
          if (processedEventsRef.current.has(eventId)) return;
          processedEventsRef.current.add(eventId);
          
          playSound("call");
        }
      )
      // New bookings
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'bookings', filter: `tenant_id=eq.${tenant.id}` },
        (payload) => {
          const eventId = `booking-${payload.new.id}`;
          if (processedEventsRef.current.has(eventId)) return;
          processedEventsRef.current.add(eventId);
          
          playSound("lead");
          toast({
            title: "📅 New Booking!",
            description: "A new appointment was just scheduled.",
            action: (
              <Button 
                size="sm" 
                variant="secondary"
                onClick={() => navigate("/app/bookings")}
              >
                View
              </Button>
            ),
          });
        }
      )
      // Urgent dispatch jobs
      .on(
        'postgres_changes',
        { event: 'INSERT', schema: 'public', table: 'dispatch_jobs', filter: `tenant_id=eq.${tenant.id}` },
        (payload) => {
          const job = payload.new as { id: string; priority?: string; job_type?: string; customer_name?: string };
          const eventId = `dispatch-${job.id}`;
          if (processedEventsRef.current.has(eventId)) return;
          processedEventsRef.current.add(eventId);

          if (job.priority === "urgent") {
            playSound("urgent");
          } else {
            playSound("notification");
          }
          toast({
            title: "🚚 New Job!",
            description: `${job.job_type || "Job"} - ${job.customer_name || "Customer"}`,
            action: (
              <Button 
                size="sm" 
                variant="secondary"
                onClick={() => navigate("/app/dispatch")}
              >
                View
              </Button>
            ),
          });
        }
      )
      .subscribe();

    // Cleanup old events periodically
    const cleanup = setInterval(() => {
      if (processedEventsRef.current.size > 100) {
        processedEventsRef.current.clear();
      }
    }, 60000);

    return () => {
      supabase.removeChannel(channel);
      clearInterval(cleanup);
    };
  }, [tenant?.id, playSound, toast, navigate]);

  return null; // This is a non-visual component
}

