    streetAddress: "",
    city: "",
    state: "",
    zipCode: "",
    contactFirstName: "",
    contactLastName: "",
    contactEmail: "",
    websiteUrl: "",
  };
}

const ENTITY_TYPES = [
  { value: "sole_proprietorship", label: "Sole Proprietorship" },
  { value: "llc", label: "LLC" },
  { value: "corporation", label: "Corporation" },
  { value: "partnership", label: "Partnership" },
  { value: "non_profit", label: "Non-Profit" },
] as const;

const US_STATES = [
  "AL","AK","AZ","AR","CA","CO","CT","DE","FL","GA","HI","ID","IL","IN","IA",
  "KS","KY","LA","ME","MD","MA","MI","MN","MS","MO","MT","NE","NV","NH","NJ",
  "NM","NY","NC","ND","OH","OK","OR","PA","RI","SC","SD","TN","TX","UT","VT",
  "VA","WA","WV","WI","WY","DC",
] as const;

interface Props {
  value: A2PBusinessData;
  onChange: (data: A2PBusinessData) => void;
  businessName?: string;
  userEmail?: string;
  userDisplayName?: string;
}

export function A2PBusinessFields({ value, onChange, businessName, userEmail, userDisplayName }: Props) {
  const update = <K extends keyof A2PBusinessData>(key: K, val: A2PBusinessData[K]) => {
    onChange({ ...value, [key]: val });
  };

  // Pre-fill on first render if empty
  if (!value.legalBusinessName && businessName) {
    // Don't call onChange during render — handled by parent
  }

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold tracking-tight">
          Business identity for SMS
        </h2>
        <p className="mt-2 text-muted-foreground">
          We need these details to activate text messaging on your business number. This information is used for carrier compliance and is never shared publicly.
        </p>
      </div>

      {/* Legal Business Name */}
      <div className="space-y-2">
        <Label htmlFor="legal-name">Legal Business Name</Label>
        <Input
          id="legal-name"
          placeholder={businessName || "e.g. Acme Services LLC"}
          value={value.legalBusinessName}
          onChange={(e) => update("legalBusinessName", e.target.value)}
        />
        <p className="text-xs text-muted-foreground">
          As registered with your state — may differ from your display name
        </p>
      </div>

      {/* Entity Type + EIN side by side */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        <div className="space-y-2">
          <Label>Business Entity Type</Label>
          <Select value={value.entityType} onValueChange={(v) => update("entityType", v)}>
            <SelectTrigger>
              <SelectValue placeholder="Select entity type" />
            </SelectTrigger>
            <SelectContent>
              {ENTITY_TYPES.map((et) => (
                <SelectItem key={et.value} value={et.value}>
                  {et.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        <div className="space-y-2">
          <Label htmlFor="ein">EIN / Tax ID</Label>
          <Input
            id="ein"
            placeholder="XX-XXXXXXX"
            value={value.ein}
            onChange={(e) => {
              // Auto-format EIN: XX-XXXXXXX
              let raw = e.target.value.replace(/\D/g, "").slice(0, 9);
              if (raw.length > 2) raw = raw.slice(0, 2) + "-" + raw.slice(2);
              update("ein", raw);
            }}
            maxLength={10}
          />
          <p className="text-xs text-muted-foreground">
            {value.entityType === "sole_proprietorship"
              ? "Optional for sole proprietors — skip if you don't have one"
              : "9-digit federal tax ID number"}
          </p>
        </div>
      </div>

      {/* Structured Address */}
      <div className="space-y-3">
        <Label>Business Address</Label>
        <Input
          placeholder="Street address"
          value={value.streetAddress}
          onChange={(e) => update("streetAddress", e.target.value)}
        />
        <div className="grid grid-cols-6 gap-2">
          <div className="col-span-3">
            <Input
              placeholder="City"
              value={value.city}
              onChange={(e) => update("city", e.target.value)}
            />
          </div>
          <div className="col-span-1">
            <Select value={value.state} onValueChange={(v) => update("state", v)}>
              <SelectTrigger>
                <SelectValue placeholder="ST" />
              </SelectTrigger>
              <SelectContent>
                {US_STATES.map((st) => (
                  <SelectItem key={st} value={st}>{st}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="col-span-2">
            <Input
              placeholder="ZIP Code"
              value={value.zipCode}
              onChange={(e) => update("zipCode", e.target.value.replace(/\D/g, "").slice(0, 5))}
              maxLength={5}
            />
          </div>
        </div>
      </div>

      {/* Contact Info */}
      <div className="space-y-3">
        <Label>Contact Person</Label>
        <div className="grid grid-cols-2 gap-2">
          <Input
            placeholder="First name"
            value={value.contactFirstName}
            onChange={(e) => update("contactFirstName", e.target.value)}
          />
          <Input
            placeholder="Last name"
            value={value.contactLastName}
            onChange={(e) => update("contactLastName", e.target.value)}
          />
        </div>
        <Input
          placeholder="Contact email"
          type="email"
          value={value.contactEmail}
          onChange={(e) => update("contactEmail", e.target.value)}
        />
      </div>

      {/* Website */}
      <div className="space-y-2">
        <Label htmlFor="website-url">Website URL</Label>
        <Input
          id="website-url"
          placeholder="https://www.yourbusiness.com"
          value={value.websiteUrl}
          onChange={(e) => update("websiteUrl", e.target.value)}
        />
        <p className="text-xs text-muted-foreground">
          Required by carriers to verify your business
        </p>
      </div>
    </div>
  );
}

/**
 * AIPreviewPanel — Shows a live preview of how the AI will greet callers
 * during onboarding Phase 5 (Your AI Assistant).
 */
import { useMemo } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Phone, Bot, User } from "lucide-react";
import { cn } from "@/lib/utils";
import type { AITone } from "@/components/onboarding/CommunicationPreferences";
import type { BusinessMode } from "@/components/onboarding/BusinessModeSelector";

interface AIPreviewPanelProps {
  businessName: string;
  businessMode: BusinessMode;
  aiTone: AITone;
  customGreeting: string;
}

const TONE_GREETINGS: Record<AITone, (name: string) => string> = {
  professional: (name) =>
    `Thank you for calling ${name}. How may I assist you today?`,
  friendly: (name) =>
    `Hi there! Thanks for calling ${name}. How can I help you today?`,
  casual: (name) =>
    `Hey! You've reached ${name}. What can I do for you?`,
};

const TONE_RESPONSES: Record<AITone, string> = {
  professional:
    "I'd be happy to help you with that. Let me check our availability for you right away.",
  friendly:
    "Great, I can definitely help with that! Let me look at what we have available.",
  casual:
    "Sure thing! Let me pull that up for you real quick.",
};

function getCallerMessage(mode: BusinessMode): string {
  switch (mode) {
    case "food":
      return "Hi, I'd like to place an order for pickup.";
    case "dispatch":
      return "I need a tow truck. My car broke down on Highway 101.";
    case "medical":
      return "I'd like to schedule an appointment with the doctor.";
    case "sales":
      return "I'm interested in what you have available. Can you tell me more?";
    default:
      return "I'd like to schedule an appointment, please.";
  }
}

export function AIPreviewPanel({
  businessName,
  businessMode,
  aiTone,
  customGreeting,
}: AIPreviewPanelProps) {
  const displayName = businessName || "Your Business";

  const greeting = useMemo(() => {
    if (customGreeting.trim()) return customGreeting;
    return TONE_GREETINGS[aiTone](displayName);
  }, [customGreeting, aiTone, displayName]);

  const callerMessage = useMemo(() => getCallerMessage(businessMode), [businessMode]);
  const aiResponse = useMemo(() => TONE_RESPONSES[aiTone], [aiTone]);

  return (
    <Card className="border-primary/20 bg-gradient-to-br from-primary/5 to-transparent">
      <CardContent className="p-5 space-y-4">
        <div className="flex items-center gap-2">
          <div className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/10">
            <Phone className="h-4 w-4 text-primary" />
          </div>
          <div>
            <p className="text-sm font-medium">Live Preview</p>
            <p className="text-xs text-muted-foreground">
              Here's how your AI will handle a call
            </p>
          </div>
        </div>

        {/* Simulated conversation */}
        <div className="space-y-3">
          {/* AI Greeting */}
          <div className="flex items-start gap-2">
            <div className="flex h-6 w-6 items-center justify-center rounded-full bg-primary/10 shrink-0 mt-0.5">
              <Bot className="h-3.5 w-3.5 text-primary" />
            </div>
            <div className="bg-primary/10 rounded-lg rounded-tl-none px-3 py-2 max-w-[85%]">
              <p className="text-sm">{greeting}</p>
            </div>
          </div>

          {/* Caller */}
          <div className="flex items-start gap-2 justify-end">
            <div className="bg-muted rounded-lg rounded-tr-none px-3 py-2 max-w-[85%]">
              <p className="text-sm text-muted-foreground">{callerMessage}</p>
            </div>
            <div className="flex h-6 w-6 items-center justify-center rounded-full bg-muted shrink-0 mt-0.5">
              <User className="h-3.5 w-3.5 text-muted-foreground" />
            </div>
          </div>

          {/* AI Response */}
          <div className="flex items-start gap-2">
            <div className="flex h-6 w-6 items-center justify-center rounded-full bg-primary/10 shrink-0 mt-0.5">
              <Bot className="h-3.5 w-3.5 text-primary" />
            </div>
            <div className="bg-primary/10 rounded-lg rounded-tl-none px-3 py-2 max-w-[85%]">
              <p className="text-sm">{aiResponse}</p>
            </div>
          </div>
        </div>

        <p className="text-xs text-muted-foreground text-center pt-1">
          This is a preview. The actual AI adapts to each caller's needs.
        </p>
      </CardContent>
    </Card>
  );
}

