import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import BusinessHoursEditor, { BusinessHours } from "@/components/onboarding/BusinessHoursEditor";
import { AlertCircle } from "lucide-react";

export interface BusinessBasicsData {
  businessName: string;
  tagline: string;
  phoneNumber: string;
  address: string;
  timezone: string;
  hoursJson: BusinessHours;
}

interface BusinessBasicsFormProps {
  data: BusinessBasicsData;
  onChange: (data: BusinessBasicsData) => void;
}

// Common US timezones (can be extended)
const TIMEZONES = [
  { value: "America/New_York", label: "Eastern Time (ET)" },
  { value: "America/Chicago", label: "Central Time (CT)" },
  { value: "America/Denver", label: "Mountain Time (MT)" },
  { value: "America/Phoenix", label: "Mountain Time - Arizona (no DST)" },
  { value: "America/Los_Angeles", label: "Pacific Time (PT)" },
  { value: "America/Anchorage", label: "Alaska Time (AKT)" },
  { value: "Pacific/Honolulu", label: "Hawaii Time (HT)" },
  { value: "America/Puerto_Rico", label: "Atlantic Time - Puerto Rico" },
];

/**
 * Business Basics Form - Step D of Onboarding
 *
 * Collects essential business information:
 * - Business name (required)
 * - Tagline (optional)
 * - Phone number (required)
 * - Address (optional)
 * - Timezone (required)
 * - Business hours (required)
 *
 * UI only - no database writes. Validation logic included.
 */
export default function BusinessBasicsForm({ data, onChange }: BusinessBasicsFormProps) {
  const updateField = <K extends keyof BusinessBasicsData>(
    field: K,
    value: BusinessBasicsData[K]
  ) => {
    onChange({ ...data, [field]: value });
  };

  // Validation helpers (for parent to use)
  const hasBusinessName = data.businessName.trim().length > 0;
  const hasPhoneNumber = data.phoneNumber.trim().length > 0;
  const hasTimezone = data.timezone.length > 0;

  return (
    <div className="space-y-6">
      {/* Business Name */}
      <div className="space-y-2">
        <Label htmlFor="businessName">
          Business Name <span className="text-rose-400">*</span>
        </Label>
        <Input
          id="businessName"
          placeholder="e.g. Smith's Plumbing Service"
          value={data.businessName}
          onChange={(e) => updateField("businessName", e.target.value)}
          className={!hasBusinessName && data.businessName.length > 0 ? "border-rose-400" : ""}
        />
        {!hasBusinessName && data.businessName.length > 0 && (
          <div className="flex items-center gap-1 text-xs text-rose-400">
            <AlertCircle className="h-3 w-3" />
            <span>Business name is required</span>
          </div>
        )}
      </div>

      {/* Tagline */}
      <div className="space-y-2">
        <Label htmlFor="tagline">
          Tagline <span className="text-muted-foreground text-xs">(optional)</span>
        </Label>
        <Input
          id="tagline"
          placeholder="e.g. Your trusted local plumber since 1995"
          value={data.tagline}
          onChange={(e) => updateField("tagline", e.target.value)}
        />
        <p className="text-xs text-muted-foreground">
          A short slogan or value proposition
        </p>
      </div>

      {/* Phone Number */}
      <div className="space-y-2">
        <Label htmlFor="phoneNumber">
          Phone Number <span className="text-rose-400">*</span>
        </Label>
        <Input
          id="phoneNumber"
          type="tel"
          placeholder="e.g. (555) 123-4567"
          value={data.phoneNumber}
          onChange={(e) => updateField("phoneNumber", e.target.value)}
          className={!hasPhoneNumber && data.phoneNumber.length > 0 ? "border-rose-400" : ""}
        />
        {!hasPhoneNumber && data.phoneNumber.length > 0 && (
          <div className="flex items-center gap-1 text-xs text-rose-400">
            <AlertCircle className="h-3 w-3" />
            <span>Phone number is required</span>
          </div>
        )}
        <p className="text-xs text-muted-foreground">
          This will be your public business number
        </p>
      </div>

      {/* Address */}
      <div className="space-y-2">
        <Label htmlFor="address">
          Business Address <span className="text-muted-foreground text-xs">(optional)</span>
        </Label>
        <Textarea
          id="address"
          placeholder="e.g. 123 Main St, Springfield, IL 62701"
          value={data.address}
          onChange={(e) => updateField("address", e.target.value)}
          rows={2}
        />
        <p className="text-xs text-muted-foreground">
          Your physical business location (if applicable)
        </p>
      </div>

      {/* Timezone */}
      <div className="space-y-2">
        <Label htmlFor="timezone">
          Timezone <span className="text-rose-400">*</span>
        </Label>
        <Select
          value={data.timezone}
          onValueChange={(value) => updateField("timezone", value)}
        >
          <SelectTrigger
            id="timezone"
            className={!hasTimezone ? "border-rose-400" : ""}
          >
            <SelectValue placeholder="Select your timezone" />
          </SelectTrigger>
          <SelectContent>
            {TIMEZONES.map((tz) => (
              <SelectItem key={tz.value} value={tz.value}>
                {tz.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {!hasTimezone && (
          <div className="flex items-center gap-1 text-xs text-rose-400">
            <AlertCircle className="h-3 w-3" />
            <span>Timezone is required</span>
          </div>
        )}
        <p className="text-xs text-muted-foreground">
          Used for scheduling and business hours
        </p>
      </div>

      {/* Business Hours */}
      <div className="space-y-2">
        <Label>
          Business Hours <span className="text-rose-400">*</span>
        </Label>
        <div className="rounded-lg border p-4">
          <BusinessHoursEditor
            hours={data.hoursJson}
            onChange={(hours) => updateField("hoursJson", hours)}
          />
        </div>
        <p className="text-xs text-muted-foreground">
          When your business is available to take calls and appointments
        </p>
      </div>
    </div>
  );
}

/**
 * Validation function for parent components
 */
export function validateBusinessBasics(data: BusinessBasicsData): boolean {
  return (
    data.businessName.trim().length > 0 &&
    data.phoneNumber.trim().length > 0 &&
    data.timezone.length > 0
  );
}

import { useAIReadinessV2 } from "@/hooks/useAIReadinessV2";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Link } from "react-router-dom";
import { Brain, CheckCircle2, AlertCircle, XCircle, ChevronRight } from "lucide-react";

interface BusinessBrainHealthProps {
  /** Show compact version with minimal details */
  compact?: boolean;
  /** Show action buttons like "Go Live" */
  showActions?: boolean;
}

/**
 * Business Brain Health Panel
 *
 * Displays AI readiness score (0-100) with actionable recommendations.
 * Uses the existing useAIReadinessV2 hook to fetch readiness data.
 *
 * Supports two modes:
 * - Full: Complete panel with score, progress bar, recommendations list
 * - Compact: Minimal inline display for headers/dashboards
 */
export function BusinessBrainHealth({ compact = false, showActions = false }: BusinessBrainHealthProps) {
  const {
    score,
    p0Flags,
    p1Flags,
    recommendations,
    canGoLive,
    isReady,
    loading
  } = useAIReadinessV2();

  if (loading) {
    if (compact) {
      return (
        <div className="flex items-center gap-3 p-3 rounded-lg border bg-card">
          <Skeleton className="h-5 w-5 rounded" />
          <div className="flex-1 space-y-2">
            <Skeleton className="h-4 w-32" />
            <Skeleton className="h-1.5 w-full" />
          </div>
        </div>
      );
    }

    return (
      <Card>
        <CardHeader>
          <Skeleton className="h-6 w-48" />
        </CardHeader>
        <CardContent className="space-y-4">
          <Skeleton className="h-2 w-full" />
          <Skeleton className="h-20 w-full" />
        </CardContent>
      </Card>
    );
  }

  // Compact mode - minimal inline display
  if (compact) {
    return (
      <div className="flex items-center gap-3 p-3 rounded-lg border bg-card">
        <Brain className="h-5 w-5 text-primary shrink-0" />
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2 mb-1">
            <span className="font-medium text-sm">AI Readiness</span>
            <Badge variant="outline" className="text-xs">
              {score}%
            </Badge>
          </div>
          <Progress value={score} className="h-1.5" />
        </div>
        {recommendations.length > 0 && (
          <Badge variant="secondary" className="shrink-0">
            {recommendations.length} left
          </Badge>
        )}
      </div>
    );
  }

  // Full mode - complete panel
  const statusMessage = canGoLive
    ? "Your AI is ready to go live!"
    : isReady
    ? "Almost there! Complete a few more items to go live."
    : `${recommendations.length} ${recommendations.length === 1 ? 'item' : 'items'} to complete`;

  const statusVariant = canGoLive ? "default" : isReady ? "secondary" : "outline";
  const statusIcon = canGoLive ? CheckCircle2 : AlertCircle;
  const StatusIcon = statusIcon;

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Brain className="h-6 w-6 text-primary" />
            <CardTitle>Business Brain Health</CardTitle>
          </div>
          <div className="text-center">
            <div className="text-3xl font-bold">{score}%</div>
            <Badge variant={statusVariant} className="mt-1">
              {canGoLive ? "Ready" : isReady ? "Almost Ready" : "In Progress"}
            </Badge>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <Progress value={score} className="h-2" />

        {/* Status message */}
        <div
          className={`flex items-center gap-2 p-3 rounded-lg ${
            canGoLive
              ? "text-emerald-400 bg-emerald-500/10"
              : "text-amber-400 bg-amber-500/10"
          }`}
        >
          <StatusIcon className="h-5 w-5 shrink-0" />
          <span className="text-sm font-medium">
            {statusMessage}
          </span>
        </div>

        {/* Recommendations list */}
        {recommendations.length > 0 && (
          <div className="space-y-2">
            <h4 className="text-sm font-medium text-muted-foreground">
              Action Items
            </h4>
            {recommendations.map((rec, i) => {
              // Determine if this is P0 (critical) or P1 (recommended)
              const isP0 = p0Flags.some(flag => rec.label.toLowerCase().includes(flag.replace(/_/g, ' ')));

              // Deep-link safety: normalize path and check validity
              const hasValidLink = rec.deep_link && typeof rec.deep_link === 'string' && rec.deep_link.trim().length > 0;
              const normalizedLink = hasValidLink
                ? rec.deep_link.startsWith('/') ? rec.deep_link : `/${rec.deep_link}`
                : '';

              const content = (
                <div className="flex items-center justify-between p-3 rounded-lg border hover:bg-muted/50 transition-colors">
                  <div className="flex items-center gap-3">
                    <XCircle
                      className={`h-4 w-4 shrink-0 ${
                        isP0 ? 'text-rose-400' : 'text-amber-400'
                      }`}
                    />
                    <div>
                      <span className="text-sm">{rec.label}</span>
                      {isP0 && (
                        <Badge variant="destructive" className="ml-2 text-xs">
                          Required
                        </Badge>
                      )}
                    </div>
                  </div>
                  {hasValidLink && (
                    <ChevronRight className="h-4 w-4 text-muted-foreground shrink-0" />
                  )}
                </div>
              );

              // If no valid link, render as plain div
              if (!hasValidLink) {
                return <div key={i}>{content}</div>;
              }

              // Otherwise render as Link with normalized path
              return (
                <Link key={i} to={normalizedLink}>
                  {content}
                </Link>
              );
            })}
          </div>
        )}

        {/* Completed items indicator */}
        {score > 0 && recommendations.length === 0 && (
          <div className="flex items-center gap-2 text-emerald-400 bg-emerald-500/10 p-3 rounded-lg">
            <CheckCircle2 className="h-5 w-5" />
            <span className="text-sm font-medium">
              All setup items completed!
            </span>
          </div>
        )}

        {/* Action button */}
        {showActions && canGoLive && (
          <Button className="w-full" asChild>
            <Link to="/app/go-live">Review & Go Live</Link>
          </Button>
        )}
      </CardContent>
    </Card>
  );
}

