                    <Label className="flex items-center gap-1">
                      <DollarSign className="h-3 w-3" />
                      Admin Fee ($)
                    </Label>
                    <Input
                      type="number"
                      placeholder="75"
                      value={data.impoundAdminFee || ""}
                      onChange={(e) => update("impoundAdminFee", parseFloat(e.target.value) || 0)}
                      min={0}
