              >
                {type}
                <button
                  type="button"
                  onClick={() => removeItem("jobTypes", i)}
                  className="ml-1 text-muted-foreground hover:text-foreground"
                >
                  <X className="h-3 w-3" />
                </button>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Crews */}
      <Card>
        <CardContent className="pt-6 space-y-4">
