import { useState, useMemo, useEffect, useCallback } from "react";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Search, Check, Star, ChevronDown } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  industryCatalog,
  searchIndustries,
  getPopularIndustries,
  categoryLabels,
  type IndustryCategory,
  type IndustryCatalogEntry,
  INDUSTRY_COUNT,
} from "@/data/industryCatalog";

interface IndustrySelectorProps {
  value: string;
  onChange: (slug: string, industry: IndustryCatalogEntry) => void;
}

const RECENT_INDUSTRIES_KEY = "closeloop_recent_industries";
const MAX_RECENT = 5;

// Category filter chips with icons for better UX
const categoryFilters: { key: IndustryCategory | "all"; label: string; icon: string }[] = [
  { key: "all", label: "All", icon: "🏢" },
  { key: "home_services", label: "Home", icon: "🏠" },
  { key: "auto_services", label: "Auto", icon: "🚗" },
  { key: "beauty_wellness", label: "Beauty", icon: "💇" },
  { key: "health_medical", label: "Medical", icon: "🏥" },
  { key: "food_hospitality", label: "Food", icon: "🍽️" },
  { key: "dispatch_logistics", label: "Dispatch", icon: "🚛" },
  { key: "professional_services", label: "Pro", icon: "💼" },
  { key: "pet_services", label: "Pets", icon: "🐕" },
  { key: "fitness_recreation", label: "Fitness", icon: "💪" },
  { key: "events_entertainment", label: "Events", icon: "📸" },
  { key: "property_real_estate", label: "Property", icon: "🏘️" },
  { key: "sales_dealerships", label: "Sales", icon: "💰" },
];

export default function IndustrySelector({ value, onChange }: IndustrySelectorProps) {
  const [searchQuery, setSearchQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState<IndustryCategory | "all">("all");
  const [recentIndustries, setRecentIndustries] = useState<string[]>([]);
  const [isExpanded, setIsExpanded] = useState(!value || value === "other" || value === "");

  // Load recent industries from localStorage
  useEffect(() => {
    try {
      const stored = localStorage.getItem(RECENT_INDUSTRIES_KEY);
      if (stored) {
        setRecentIndustries(JSON.parse(stored));
      }
    } catch {
      // Ignore localStorage errors
    }
  }, []);

  // Save to recent industries
  const saveToRecent = useCallback((slug: string) => {
    setRecentIndustries(prev => {
      const updated = [slug, ...prev.filter(s => s !== slug)].slice(0, MAX_RECENT);
      try {
        localStorage.setItem(RECENT_INDUSTRIES_KEY, JSON.stringify(updated));
      } catch {
        // Ignore localStorage errors
      }
      return updated;
    });
  }, []);

  // Get popular industries
  const popularIndustries = useMemo(() => getPopularIndustries(12), []);

  // Get recent industries as full objects
  const recentIndustryObjects = useMemo(() => {
    return recentIndustries
      .map(slug => industryCatalog.find(i => i.slug === slug))
      .filter((i): i is IndustryCatalogEntry => i !== undefined);
  }, [recentIndustries]);

  // Filter industries based on search and category
  const filteredIndustries = useMemo(() => {
    let results = searchQuery ? searchIndustries(searchQuery) : industryCatalog;
    
    if (activeCategory !== "all") {
      results = results.filter(i => i.category === activeCategory);
    }
    
    // Sort alphabetically, but keep "Other" at the end
    return results.sort((a, b) => {
      if (a.slug === "other") return 1;
      if (b.slug === "other") return -1;
      return a.name.localeCompare(b.name);
    });
  }, [searchQuery, activeCategory]);

  // Determine what to show
  const showRecent = !searchQuery && activeCategory === "all" && recentIndustryObjects.length > 0;
  const showPopular = !searchQuery && activeCategory === "all";

  const handleSelect = (industry: IndustryCatalogEntry) => {
    saveToRecent(industry.slug);
    setIsExpanded(false);
    onChange(industry.slug, industry);
  };

  // Mode badge helper
  const getModeLabel = (mode: string) => {
    switch (mode) {
      case 'food': return { label: 'Food', color: 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400' };
      case 'dispatch': return { label: 'Dispatch', color: 'bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400' };
      case 'medical': return { label: 'Medical', color: 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400' };
      case 'service': return { label: 'Booking', color: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400' };
      case 'sales': return { label: 'Sales', color: 'bg-amber-100 text-amber-700 dark:bg-amber-900/30 dark:text-amber-400' };
      default: return { label: 'General', color: 'bg-gray-100 text-gray-700 dark:bg-gray-900/30 dark:text-gray-400' };
    }
  };

  const renderIndustryItem = (industry: IndustryCatalogEntry, showBadge?: string) => {
    const isSelected = value === industry.slug;
    const modeInfo = getModeLabel(industry.businessMode);
    
    return (
      <button
        key={industry.slug}
        type="button"
        onClick={() => handleSelect(industry)}
        className={cn(
          "flex items-center gap-3 w-full px-3 py-2.5 rounded-lg text-left transition-all",
          "hover:bg-muted/80 focus:outline-none focus:ring-2 focus:ring-primary/20",
          isSelected && "bg-primary/10 ring-2 ring-primary"
        )}
      >
        <span className="text-xl flex-shrink-0">{industry.icon}</span>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <span className={cn("font-medium truncate", isSelected && "text-primary")}>
              {industry.name}
            </span>
            {showBadge && (
              <Badge variant="outline" className="text-[10px] px-1.5 py-0 h-4">
                {showBadge}
              </Badge>
            )}
          </div>
          <div className="flex items-center gap-2 mt-0.5">
            <span className={cn("text-[10px] px-1.5 py-0.5 rounded-full font-medium", modeInfo.color)}>
              {modeInfo.label}
            </span>
            <span className="text-xs text-muted-foreground truncate">
              {industry.services.length} services
            </span>
          </div>
        </div>
        {isSelected && (
          <Check className="h-4 w-4 text-primary flex-shrink-0" />
        )}
      </button>
    );
  };

  return (
    <div className="space-y-4">
      <div className="space-y-2">
        <Label>Industry *</Label>
        <p className="text-xs text-muted-foreground">
          Choose from {INDUSTRY_COUNT} industries to get tailored templates
        </p>
      </div>

      {/* Show search and filters only when expanded or no selection */}
      {(isExpanded || !value || value === "other") && (
        <>
          {/* Search Input */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search industries..."
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value);
                setIsExpanded(true);
              }}
              className="pl-9"
            />
          </div>

          {/* Category Filters - horizontal scroll on mobile */}
          <div className="overflow-x-auto pb-1 -mx-1 px-1">
            <div className="flex gap-1.5 min-w-max">
              {categoryFilters.map((cat) => (
                <button
                  key={cat.key}
                  type="button"
                  onClick={() => {
                    setActiveCategory(cat.key);
                    setIsExpanded(true);
                  }}
                  className={cn(
                    "flex items-center gap-1 px-2.5 py-1.5 rounded-full text-xs font-medium transition-colors whitespace-nowrap",
                    activeCategory === cat.key
                      ? "bg-primary text-primary-foreground"
                      : "bg-muted text-muted-foreground hover:bg-muted/80"
                  )}
                >
                  <span>{cat.icon}</span>
                  <span>{cat.label}</span>
                </button>
              ))}
            </div>
          </div>

          {/* Industry List */}
          <ScrollArea className="h-[300px] rounded-lg border">
        <div className="p-2 space-y-4">
          {/* Recent Industries */}
          {showRecent && (
            <div className="space-y-1">
              <div className="flex items-center gap-1.5 px-2 py-1">
                <Star className="h-3 w-3 text-muted-foreground" />
                <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                  Recently Used
                </span>
              </div>
              {recentIndustryObjects.map(industry => renderIndustryItem(industry, "Recent"))}
            </div>
          )}

          {/* Popular Industries */}
          {showPopular && (
            <div className="space-y-1">
              <div className="flex items-center gap-1.5 px-2 py-1">
                <span className="text-xs font-medium text-muted-foreground uppercase tracking-wide">
                  Popular
                </span>
              </div>
              {popularIndustries
                .filter(i => !recentIndustries.includes(i.slug))
                .map(industry => renderIndustryItem(industry))}
            </div>
          )}

          {/* Divider if we showed popular */}
          {showPopular && filteredIndustries.length > popularIndustries.length && (
            <div className="flex items-center gap-2 px-2 py-1">
              <div className="flex-1 border-t" />
              <span className="text-xs text-muted-foreground">All Industries</span>
              <div className="flex-1 border-t" />
            </div>
          )}

          {/* All/Filtered Industries */}
          {(searchQuery || activeCategory !== "all") && (
            <div className="space-y-1">
              {filteredIndustries.length === 0 ? (
                <div className="text-center py-8 text-muted-foreground">
                  <p>No industries found for "{searchQuery}"</p>
                  <p className="text-xs mt-1">Try a different search term</p>
                </div>
              ) : (
                filteredIndustries.map(industry => renderIndustryItem(industry))
              )}
            </div>
          )}

          {/* Full list when not searching (excluding already shown) */}
          {!searchQuery && activeCategory === "all" && (
            <div className="space-y-1">
              {filteredIndustries
                .filter(i => 
                  !popularIndustries.some(p => p.slug === i.slug) && 
                  !recentIndustries.includes(i.slug)
                )
                .map(industry => renderIndustryItem(industry))}
            </div>
          )}
        </div>
      </ScrollArea>
        </>
      )}

      {/* Selected Industry Display */}
      {value && value !== "other" && (
        <div 
          className="flex items-center gap-2 p-3 bg-primary/5 border border-primary/20 rounded-lg cursor-pointer hover:bg-primary/10 transition-colors"
          onClick={() => setIsExpanded(!isExpanded)}
        >
          <span className="text-xl">
            {industryCatalog.find(i => i.slug === value)?.icon || "🏢"}
          </span>
          <div className="flex-1">
            <div className="flex items-center gap-2">
              <p className="font-medium text-sm">
                {industryCatalog.find(i => i.slug === value)?.name || value}
              </p>
              {(() => {
                const industry = industryCatalog.find(i => i.slug === value);
                if (industry) {
                  const modeInfo = getModeLabel(industry.businessMode);
                  return (
                    <span className={cn("text-[10px] px-1.5 py-0.5 rounded-full font-medium", modeInfo.color)}>
                      {modeInfo.label}
                    </span>
                  );
                }
                return null;
              })()}
            </div>
            <p className="text-xs text-muted-foreground">
              {industryCatalog.find(i => i.slug === value)?.services.length || 0} default services • Click to change
            </p>
          </div>
          <ChevronDown className={cn("h-4 w-4 text-muted-foreground transition-transform", isExpanded && "rotate-180")} />
        </div>
      )}
    </div>
  );
}

import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Checkbox } from "@/components/ui/checkbox";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Shield, Phone, FileText, Clock, AlertTriangle, CheckCircle2 } from "lucide-react";

export interface MedicalSetupData {
  requireVerbalConsent: boolean;
  storeTranscripts: boolean;
  storeRecordings: boolean;
  retentionDays: number;
  urgentEscalationNumber: string;
  intakeTypes: string[];
  schedulingNotes: string;
  // HIPAA acknowledgment
  hipaaAcknowledged?: boolean;
}

interface MedicalSetupEditorProps {
  data: MedicalSetupData;
  onChange: (data: MedicalSetupData) => void;
}

const intakeTypeOptions = [
  { id: "new_patient", label: "New Patient Intake" },
  { id: "follow_up", label: "Follow-up Appointment" },
  { id: "prescription_refill", label: "Prescription Refill Request" },
  { id: "appointment_request", label: "General Appointment Request" },
];

export function MedicalSetupEditor({ data, onChange }: MedicalSetupEditorProps) {
  const update = (field: keyof MedicalSetupData, value: any) => {
    onChange({ ...data, [field]: value });
  };

  const toggleIntakeType = (typeId: string) => {
    const current = data.intakeTypes || [];
    if (current.includes(typeId)) {
      update("intakeTypes", current.filter(t => t !== typeId));
    } else {
      update("intakeTypes", [...current, typeId]);
    }
  };

  return (
    <div className="space-y-6">
      {/* HIPAA Acknowledgment Card */}
      <Card className={data.hipaaAcknowledged ? "border-success/50 bg-success/5" : "border-amber-500/50 bg-amber-500/5"}>
        <CardHeader className="pb-3">
          <CardTitle className="text-base flex items-center gap-2">
            <Shield className={data.hipaaAcknowledged ? "h-5 w-5 text-success" : "h-5 w-5 text-amber-600"} />
            HIPAA Compliance Mode
          </CardTitle>
          <CardDescription>
            Your AI will operate under strict HIPAA guidelines to protect patient privacy.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="space-y-3 text-sm">
            <div className="flex items-start gap-2">
              <CheckCircle2 className="h-4 w-4 text-success mt-0.5 shrink-0" />
              <span>Call recordings are <strong>disabled by default</strong></span>
            </div>
            <div className="flex items-start gap-2">
              <CheckCircle2 className="h-4 w-4 text-success mt-0.5 shrink-0" />
              <span>Full transcripts are <strong>not stored</strong> — only structured intake data</span>
            </div>
            <div className="flex items-start gap-2">
              <CheckCircle2 className="h-4 w-4 text-success mt-0.5 shrink-0" />
              <span>AI will <strong>never provide medical advice</strong> or diagnoses</span>
            </div>
            <div className="flex items-start gap-2">
              <CheckCircle2 className="h-4 w-4 text-success mt-0.5 shrink-0" />
              <span>Urgent symptoms are <strong>immediately escalated</strong> to staff</span>
            </div>
          </div>

          <div className="flex items-start space-x-3 pt-2 border-t">
            <Checkbox
              id="hipaa-ack"
              checked={data.hipaaAcknowledged || false}
              onCheckedChange={(checked) => update("hipaaAcknowledged", checked === true)}
            />
            <div className="grid gap-1.5 leading-none">
              <label
                htmlFor="hipaa-ack"
                className="text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70 cursor-pointer"
              >
                I understand and acknowledge HIPAA mode
              </label>
              <p className="text-xs text-muted-foreground">
                I confirm that I understand the privacy protections enabled for patient data.
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Privacy Controls */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <h4 className="font-medium flex items-center gap-2">
            <Shield className="h-4 w-4" />
            Privacy & Data Controls
          </h4>

          <div className="flex items-center justify-between">
            <div>
              <Label>Require Verbal Consent</Label>
              <p className="text-sm text-muted-foreground">
                AI will ask for verbal consent before proceeding with intake
              </p>
            </div>
            <Switch
              checked={data.requireVerbalConsent}
              onCheckedChange={(v) => update("requireVerbalConsent", v)}
            />
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Store Full Transcripts</Label>
              <p className="text-sm text-muted-foreground text-amber-600">
                ⚠️ Enabling increases PHI exposure
              </p>
            </div>
            <Switch
              checked={data.storeTranscripts}
              onCheckedChange={(v) => update("storeTranscripts", v)}
            />
          </div>

          <div className="flex items-center justify-between">
            <div>
              <Label>Store Call Recordings</Label>
              <p className="text-sm text-muted-foreground text-amber-600">
                ⚠️ Enabling increases PHI exposure
              </p>
            </div>
            <Switch
              checked={data.storeRecordings}
              onCheckedChange={(v) => update("storeRecordings", v)}
            />
          </div>

          <div className="space-y-2">
            <Label>Data Retention (days)</Label>
            <Input
              type="number"
              value={data.retentionDays}
              onChange={(e) => update("retentionDays", parseInt(e.target.value) || 30)}
              min={7}
              max={365}
            />
            <p className="text-xs text-muted-foreground">
              Call data older than this will be automatically purged
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Escalation */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <h4 className="font-medium flex items-center gap-2">
            <AlertTriangle className="h-4 w-4" />
            Urgent Escalation
          </h4>

          <div className="space-y-2">
            <Label>Emergency Escalation Number</Label>
            <Input
              type="tel"
              placeholder="+1 (555) 123-4567"
              value={data.urgentEscalationNumber}
              onChange={(e) => update("urgentEscalationNumber", e.target.value)}
            />
            <p className="text-xs text-muted-foreground">
              AI will transfer urgent medical situations to this number
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Intake Types */}
      <Card>
        <CardContent className="pt-6 space-y-4">
          <h4 className="font-medium flex items-center gap-2">
            <FileText className="h-4 w-4" />
            Intake Types
          </h4>
          <p className="text-sm text-muted-foreground">
            Select which types of intake requests the AI should handle
          </p>

          <div className="space-y-3">
            {intakeTypeOptions.map((option) => (
              <div key={option.id} className="flex items-center justify-between">
                <Label>{option.label}</Label>
                <Switch
                  checked={(data.intakeTypes || []).includes(option.id)}
                  onCheckedChange={() => toggleIntakeType(option.id)}
                />
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Scheduling Notes */}
      <div className="space-y-2">
        <Label className="flex items-center gap-2">
          <Clock className="h-4 w-4" />
          Scheduling Notes for AI
        </Label>
        <Textarea
          placeholder="E.g., 'New patient appointments are 45 minutes, follow-ups are 15 minutes. We don't schedule same-day appointments.'"
          value={data.schedulingNotes}
          onChange={(e) => update("schedulingNotes", e.target.value)}
          rows={3}
        />
      </div>

      {/* AI Guardrails Notice */}
      <Alert>
        <AlertTriangle className="h-4 w-4" />
        <AlertTitle>AI Medical Guardrails</AlertTitle>
        <AlertDescription>
          The AI will never provide medical diagnoses, treatment recommendations, or medication advice. 
          All urgent situations will be escalated to staff or emergency services.
        </AlertDescription>
      </Alert>
    </div>
  );
}

/**
 * ModeAwareQuestions — Compact scenario toggle cards for onboarding Phase 1.
 *
 * Renders 3-5 mode-specific questions filtered by `onboardingVisible: true`.
 * Shows pre-answered questions already toggled on based on industry.
 * Inline follow-up fields when toggled on with followUp config.
 */
import React, { useState, useMemo } from "react";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent } from "@/components/ui/card";
import { ChevronDown, ChevronUp, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";
import {
  getQuestionsForMode,
  groupLabels,
  type ScenarioQuestion,
  type QuestionGroup,
  type FollowUpField,
} from "@/lib/scenarioQuestions";
import { getIndustryBySlug } from "@/data/industryCatalog";
import type { BusinessMode } from "@/components/onboarding/BusinessModeSelector";

interface ModeAwareQuestionsProps {
  businessMode: BusinessMode;
  industrySlug: string;
  scenarioAnswers: Record<string, boolean>;
  onScenarioAnswersChange: (answers: Record<string, boolean>) => void;
  scenarioDetails: Record<string, string>;
  onScenarioDetailsChange: (details: Record<string, string>) => void;
}

export const ModeAwareQuestions = React.memo(function ModeAwareQuestions({
  businessMode,
  industrySlug,
  scenarioAnswers,
  onScenarioAnswersChange,
  scenarioDetails,
  onScenarioDetailsChange,
}: ModeAwareQuestionsProps) {
  const [expanded, setExpanded] = useState(true);

  const industryEntry = getIndustryBySlug(industrySlug);
  const industryContext = industryEntry
    ? { slug: industrySlug, category: industryEntry.category }
    : undefined;

  // Get only onboarding-visible questions for this mode/industry
  const questions = useMemo(() => {
    const all = getQuestionsForMode(businessMode, industryContext);
    return all.filter((q) => q.onboardingVisible);
  }, [businessMode, industryContext?.slug, industryContext?.category]);

  // Group questions
  const grouped = useMemo(() => {
    const groups: Record<string, ScenarioQuestion[]> = {};
    for (const q of questions) {
      const group = q.group || "core";
      if (!groups[group]) groups[group] = [];
      groups[group].push(q);
    }
    return groups;
  }, [questions]);

  if (questions.length === 0) return null;

  const handleToggle = (capabilityKey: string, value: boolean) => {
    onScenarioAnswersChange({ ...scenarioAnswers, [capabilityKey]: value });
  };

  const handleDetailChange = (key: string, value: string) => {
    onScenarioDetailsChange({ ...scenarioDetails, [key]: value });
  };

  return (
    <div className="pt-4 border-t space-y-3">
      <button
        type="button"
        className="flex items-center justify-between w-full"
        onClick={() => setExpanded(!expanded)}
      >
        <div className="flex items-center gap-2">
          <p className="text-sm font-medium">Quick questions about your business</p>
          <Badge variant="secondary" className="text-xs">
            {questions.length}
          </Badge>
        </div>
        {expanded ? (
          <ChevronUp className="h-4 w-4 text-muted-foreground" />
        ) : (
          <ChevronDown className="h-4 w-4 text-muted-foreground" />
        )}
      </button>

      {expanded && (
        <div className="space-y-4">
          {Object.entries(grouped).map(([group, groupQuestions]) => (
            <div key={group} className="space-y-2">
              {Object.keys(grouped).length > 1 && (
                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                  {groupLabels[group as QuestionGroup] || group}
                </p>
              )}
              {groupQuestions.map((q) => {
                const isOn = scenarioAnswers[q.capabilityKey] ?? q.defaultValue;
                const hasFollowUp = isOn && q.followUp;

                // Check conditional visibility — respect parent defaultValue
                if (q.showWhen) {
                  const parentQuestion = questions.find((pq) => pq.capabilityKey === q.showWhen!.capabilityKey);
                  const parentVal = scenarioAnswers[q.showWhen.capabilityKey] ?? parentQuestion?.defaultValue;
                  if (parentVal !== q.showWhen.value) return null;
                }

                return (
                  <Card
                    key={q.id}
                    className={cn(
                      "transition-all",
                      isOn ? "border-primary/30 bg-primary/5" : ""
                    )}
                  >
                    <CardContent className="p-3 space-y-2">
                      <div className="flex items-center justify-between gap-3">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2">
                            <p className="text-sm font-medium">{q.label}</p>
                            {q.requiredForAI && (
                              <Sparkles className="h-3 w-3 text-primary shrink-0" />
                            )}
                          </div>
                          {q.description && (
                            <p className="text-xs text-muted-foreground mt-0.5">{q.description}</p>
                          )}
                        </div>
                        <Switch
                          checked={isOn}
                          onCheckedChange={(checked) => handleToggle(q.capabilityKey, checked)}
                        />
                      </div>

                      {/* Inline follow-up fields */}
                      {hasFollowUp && q.followUp && "fields" in q.followUp && (
                        <div className="pl-1 pt-1 space-y-2">
                          {(q.followUp as { fields: FollowUpField[] }).fields.map((field) => (
                            <div key={field.key} className="flex items-center gap-2">
                              <Label className="text-xs whitespace-nowrap min-w-[100px]">
                                {field.label}
                              </Label>
                              {field.type === "select" && field.options ? (
                                <select
                                  className="h-8 rounded-md border border-input bg-background px-2 text-xs w-full"
                                  value={scenarioDetails[field.key] || field.defaultValue || ""}
                                  onChange={(e) => handleDetailChange(field.key, e.target.value)}
                                >
                                  {field.options.map((opt) => (
                                    <option key={opt.value} value={opt.value}>{opt.label}</option>
                                  ))}
                                </select>
                              ) : (
                                <Input
                                  className="h-8 text-xs"
                                  type={field.type === "currency" || field.type === "number" || field.type === "miles" ? "number" : "text"}
                                  placeholder={field.placeholder}
                                  value={scenarioDetails[field.key] || ""}
                                  onChange={(e) => handleDetailChange(field.key, e.target.value)}
                                />
                              )}
                              {field.suffix && (
                                <span className="text-xs text-muted-foreground whitespace-nowrap">{field.suffix}</span>
                              )}
                            </div>
                          ))}
                        </div>
                      )}

                      {/* Radio follow-up */}
                      {hasFollowUp && q.followUp && "type" in q.followUp && q.followUp.type === "radio" && (
                        <div className="pl-1 pt-1 space-y-1.5">
                          <p className="text-xs font-medium">{q.followUp.label}</p>
                          {q.followUp.options.map((opt) => (
                            <label
                              key={opt.value}
                              className={cn(
                                "flex items-start gap-2 p-2 rounded-md cursor-pointer text-xs border transition-all",
                                scenarioDetails[(q.followUp as any)!.answerKey || ""] === opt.value ||
                                  (!scenarioDetails[(q.followUp as any)!.answerKey || ""] && (q.followUp as any)!.defaultValue === opt.value)
                                  ? "border-primary bg-primary/5"
                                  : "border-transparent hover:bg-muted/50"
                              )}
                            >
                              <input
                                type="radio"
                                name={(q.followUp as any)!.id}
                                value={opt.value}
                                checked={
                                  scenarioDetails[(q.followUp as any)!.answerKey || ""] === opt.value ||
                                  (!scenarioDetails[(q.followUp as any)!.answerKey || ""] && (q.followUp as any)!.defaultValue === opt.value)
                                }
                                onChange={() =>
                                  handleDetailChange((q.followUp as any)!.answerKey || (q.followUp as any)!.id, opt.value)
                                }
                                className="mt-0.5"
                              />
                              <div>
                                <p className="font-medium">{opt.label}</p>
                                {opt.description && (
                                  <p className="text-muted-foreground">{opt.description}</p>
                                )}
                              </div>
                            </label>
                          ))}
                        </div>
                      )}
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          ))}
        </div>
      )}
    </div>
  );
});

import { Card, CardContent } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import {
  Phone,
  MessageSquare,
  Calendar,
  Truck,
  UtensilsCrossed,
  BookOpen,
  Clock,
  Cake,
  Stethoscope,
  Shield,
  Warehouse,
  Users,
} from "lucide-react";
import { cn } from "@/lib/utils";

interface ModuleDefinition {
  id: string;
  label: string;
  description: string;
  icon: React.ElementType;
  isCore?: boolean;
  requiresMode?: string[];
}

const allModules: ModuleDefinition[] = [
  {
    id: "ai_voice",
    label: "AI Voice Agent",
    description: "AI answers phone calls 24/7",
    icon: Phone,
    isCore: true,
  },
  {
    id: "instant_text_back",
    label: "Instant Text Back",
    description: "Auto-reply to missed calls via SMS",
    icon: MessageSquare,
    isCore: true,
  },
  {
    id: "booking",
    label: "Appointment Booking",
    description: "AI books appointments directly into your calendar",
    icon: Calendar,
    requiresMode: ["service", "medical", "general"],
