import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";

export interface BusinessPolicies {
  cancellationPolicy: string;
  depositPolicy: string;
  refundPolicy: string;
  paymentMethods: string[];
  aiNeverPromise: string[];
}

interface PoliciesEditorProps {
  data: BusinessPolicies;
  onChange: (data: BusinessPolicies) => void;
}

const paymentMethodOptions = [
  { value: 'cash', label: 'Cash' },
  { value: 'card', label: 'Credit/Debit Card' },
  { value: 'check', label: 'Check' },
  { value: 'venmo', label: 'Venmo' },
  { value: 'zelle', label: 'Zelle' },
  { value: 'paypal', label: 'PayPal' },
  { value: 'applepay', label: 'Apple Pay' },
  { value: 'financing', label: 'Financing Available' },
];

export default function PoliciesEditor({ data, onChange }: PoliciesEditorProps) {
  const update = (field: keyof BusinessPolicies, value: any) => {
    onChange({ ...data, [field]: value });
  };

  const togglePaymentMethod = (method: string) => {
    const current = data.paymentMethods || [];
    if (current.includes(method)) {
      update('paymentMethods', current.filter(m => m !== method));
    } else {
      update('paymentMethods', [...current, method]);
    }
  };

  return (
    <div className="space-y-6">
      {/* Cancellation Policy */}
      <div className="space-y-2">
        <Label>Cancellation Policy</Label>
        <Textarea
          value={data.cancellationPolicy}
          onChange={(e) => update('cancellationPolicy', e.target.value)}
          placeholder="e.g., Free cancellation up to 24 hours before appointment. Less than 24 hours notice may incur a $50 fee."
          rows={3}
        />
        <p className="text-xs text-muted-foreground">The AI will explain this when asked</p>
      </div>
      
      {/* Deposit Policy */}
      <div className="space-y-2">
        <Label>Deposit Policy</Label>
        <Textarea
          value={data.depositPolicy}
          onChange={(e) => update('depositPolicy', e.target.value)}
          placeholder="e.g., We require a 25% deposit to secure your appointment. Deposit is applied to your final bill."
          rows={3}
        />
      </div>
      
      {/* Refund Policy */}
      <div className="space-y-2">
        <Label>Refund Policy</Label>
        <Textarea
          value={data.refundPolicy}
          onChange={(e) => update('refundPolicy', e.target.value)}
          placeholder="e.g., 100% satisfaction guaranteed. If you're not happy, we'll make it right or refund your money."
          rows={3}
        />
      </div>
      
      {/* Payment Methods */}
      <div className="space-y-3">
        <Label>Payment Methods Accepted</Label>
        <div className="grid grid-cols-2 gap-2">
          {paymentMethodOptions.map((method) => (
            <label
              key={method.value}
              className="flex items-center gap-2 p-2 rounded-md border cursor-pointer hover:bg-muted/50 transition-colors"
            >
              <Checkbox
                checked={(data.paymentMethods || []).includes(method.value)}
                onCheckedChange={() => togglePaymentMethod(method.value)}
              />
              <span className="text-sm">{method.label}</span>
            </label>
          ))}
        </div>
      </div>
      
      {/* AI Guardrails */}
      <div className="space-y-2">
        <Label>Things AI should NEVER promise</Label>
        <Textarea
          value={(data.aiNeverPromise || []).join('\n')}
          onChange={(e) => update('aiNeverPromise', e.target.value.split('\n').filter(Boolean))}
          placeholder="Enter each item on a new line, e.g.:
Same-day appointments
Price matching
Free services
Work outside our service area"
          rows={4}
        />
        <p className="text-xs text-muted-foreground">One per line. AI will never agree to these.</p>
      </div>
    </div>
  );
}

import { useMemo, useState, useCallback, useRef, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Card, CardContent } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Shield, Bot, ChevronDown, DollarSign } from "lucide-react";
import { ScrollArea } from "@/components/ui/scroll-area";
import { cn } from "@/lib/utils";
import {
  getQuestionsForMode,
  isPreAnswered,
  groupLabels,
  type ScenarioQuestion,
  type QuestionGroup,
  type FollowUpField,
  type ScenarioFollowUp,
} from "@/lib/scenarioQuestions";
import { getIndustryBySlug } from "@/data/industryCatalog";
import type { BusinessMode } from "@/components/onboarding/BusinessModeSelector";

interface ScenarioDiscoveryProps {
  businessMode: BusinessMode;
  answers: Record<string, boolean>;
  onChange: (answers: Record<string, boolean>) => void;
  /** Follow-up detail values (non-boolean) keyed by FollowUpField.key */
  details?: Record<string, string>;
  onDetailsChange?: (details: Record<string, string>) => void;
  industrySlug?: string;
  industryCategory?: string;
}

export function ScenarioDiscovery({
  businessMode,
  answers,
  onChange,
  details = {},
  onDetailsChange,
  industrySlug,
  industryCategory,
}: ScenarioDiscoveryProps) {
  const industryContext = industrySlug && industryCategory
    ? { slug: industrySlug, category: industryCategory }
    : undefined;

  const industryEntry = industrySlug ? getIndustryBySlug(industrySlug) : null;
  const industryLabel = industryEntry?.name?.toLowerCase();

  const questions = getQuestionsForMode(businessMode, industryContext);

  // Filter to onboarding-visible questions only, plus showWhen condition
  const visibleQuestions = useMemo(() => {
    return questions.filter((q) => {
      // Only show questions marked for onboarding (or blocking questions like HIPAA)
      if (!q.onboardingVisible && !q.blocking) return false;
      // Apply conditional visibility
      if (q.showWhen) {
        return answers[q.showWhen.capabilityKey] === q.showWhen.value;
      }
      return true;
    });
  }, [questions, answers]);

  // Group questions
  const grouped = useMemo(() => {
    const groups: { group: QuestionGroup; questions: ScenarioQuestion[] }[] = [];
    const byGroup = new Map<QuestionGroup, ScenarioQuestion[]>();

    for (const q of visibleQuestions) {
      const g = q.group || "core";
      if (!byGroup.has(g)) byGroup.set(g, []);
      byGroup.get(g)!.push(q);
    }

    // Preserve order: core → ai_behavior → advanced
    const order: QuestionGroup[] = ["core", "ai_behavior", "advanced"];
    for (const g of order) {
      const qs = byGroup.get(g);
      if (qs && qs.length > 0) {
        groups.push({ group: g, questions: qs });
      }
    }

    return groups;
  }, [visibleQuestions]);

  const toggle = (capabilityKey: string, blocking?: boolean) => {
    if (blocking) return; // Blocking questions cannot be toggled off
    onChange({
      ...answers,
      [capabilityKey]: !answers[capabilityKey],
    });
  };

  const updateDetail = (key: string, value: string) => {
    onDetailsChange?.({ ...details, [key]: value });
  };

  const handleFollowUpChange = (key: string, value: string) => {
    onChange({
      ...answers,
      [key]: value as any,
    });
  };

  let globalIndex = 0;

  const [hasScrolled, setHasScrolled] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Track scroll to hide the "more below" indicator
  useEffect(() => {
    const viewport = scrollRef.current?.querySelector("[data-radix-scroll-area-viewport]");
    if (!viewport) return;
    const handleScroll = () => {
      if ((viewport as HTMLElement).scrollTop > 40) setHasScrolled(true);
    };
    viewport.addEventListener("scroll", handleScroll);
    return () => viewport.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold tracking-tight">
          How does your {industryLabel || "business"} operate?
        </h2>
        <p className="mt-2 text-muted-foreground">
          Tell us about your operations so we can configure the right capabilities.
        </p>
      </div>

      <div className="relative">
        <ScrollArea className="h-[380px]" ref={scrollRef}>
          <div className="space-y-5 pr-4">
            {grouped.map(({ group, questions: groupQuestions }) => (
              <div key={group} className="space-y-3">
                {grouped.length > 1 && (
                  <p className="text-xs font-medium uppercase tracking-wider text-muted-foreground px-1">
                    {groupLabels[group]}
                  </p>
                )}
                {groupQuestions.map((q) => {
                  const index = globalIndex++;
                  return (
                    <QuestionCard
                      key={q.id}
                      question={q}
                      checked={answers[q.capabilityKey] ?? q.defaultValue}
                      onToggle={() => toggle(q.capabilityKey, q.blocking)}
                      index={index}
                      isPreSet={isPreAnswered(q, industryContext)}
                      details={details}
                      onDetailChange={updateDetail}
                      answers={answers as Record<string, boolean | string>}
                      onAnswerChange={handleFollowUpChange}
                    />
                  );
                })}
              </div>
            ))}
          </div>
        </ScrollArea>

        {/* Scroll indicator */}
        {!hasScrolled && visibleQuestions.length > 4 && (
          <div className="absolute bottom-0 left-0 right-0 pointer-events-none">
            <div className="h-16 bg-gradient-to-t from-background to-transparent" />
            <div className="absolute bottom-2 left-1/2 -translate-x-1/2 pointer-events-auto">
              <span className="inline-flex items-center gap-1 text-xs text-muted-foreground bg-muted/80 backdrop-blur-sm px-3 py-1.5 rounded-full shadow-sm">
                <ChevronDown className="h-3 w-3 animate-bounce" />
                Scroll for more
              </span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function FollowUpFields({
  fields,
  details,
  onDetailChange,
}: {
  fields: FollowUpField[];
  details: Record<string, string>;
  onDetailChange: (key: string, value: string) => void;
}) {
  return (
    <motion.div
      initial={{ opacity: 0, height: 0 }}
      animate={{ opacity: 1, height: "auto" }}
      exit={{ opacity: 0, height: 0 }}
      transition={{ duration: 0.2 }}
      className="overflow-hidden"
    >
      <div className="mt-3 pt-3 border-t border-border/50 flex flex-wrap gap-3">
        {fields.map((field) => (
          <div key={field.key} className="flex-1 min-w-[140px] max-w-[200px]">
            <label className="text-xs font-medium text-muted-foreground mb-1 block">
              {field.label}
            </label>
            {field.type === "select" ? (
              <Select
                value={details[field.key] || field.defaultValue || ""}
                onValueChange={(v) => onDetailChange(field.key, v)}
              >
                <SelectTrigger className="h-8 text-xs">
                  <SelectValue placeholder="Select..." />
                </SelectTrigger>
                <SelectContent>
                  {field.options?.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      {opt.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            ) : (
              <div className="relative">
                {(field.type === "currency") && (
                  <DollarSign className="absolute left-2 top-1/2 -translate-y-1/2 h-3 w-3 text-muted-foreground" />
                )}
                <Input
                  type={field.type === "number" || field.type === "currency" || field.type === "miles" ? "number" : "text"}
                  value={details[field.key] || ""}
                  onChange={(e) => onDetailChange(field.key, e.target.value)}
                  placeholder={field.placeholder}
                  className={cn("h-8 text-xs", field.type === "currency" && "pl-6")}
                />
                {field.type === "miles" && (
                  <span className="absolute right-2 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">mi</span>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
    </motion.div>
  );
}

function QuestionCard({
  question,
  checked,
  onToggle,
  index,
  isPreSet,
  details = {},
  onDetailChange,
  answers,
  onAnswerChange,
}: {
  question: ScenarioQuestion;
  checked: boolean;
  onToggle: () => void;
  index: number;
  isPreSet?: boolean;
  details?: Record<string, string>;
  onDetailChange?: (key: string, value: string) => void;
  answers: Record<string, boolean | string>;
  onAnswerChange: (key: string, value: string) => void;
}) {
  const isBlocking = question.blocking;
  const showFollowUp = checked && question.followUp;
  // Determine which type of follow-up this is
  const isFieldsFollowUp = showFollowUp && "fields" in question.followUp!;
  const isRadioFollowUp = showFollowUp && "answerKey" in question.followUp!;

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.05 }}
    >
      <Card
        className={cn(
          "transition-all",
          isBlocking && "border-amber-500/50 bg-amber-500/5",
          !isBlocking && checked && "border-primary/50 bg-primary/5"
        )}
      >
        <CardContent className="p-4">
          <div className="flex items-center gap-4">
            {isBlocking && (
              <div className="flex h-10 w-10 items-center justify-center rounded-lg shrink-0 bg-amber-500/20">
                <Shield className="h-5 w-5 text-amber-600" />
              </div>
            )}

            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <h4 className="font-medium">{question.question}</h4>
                {isPreSet && checked && (
                  <Badge variant="outline" className="text-[10px] gap-1 shrink-0 border-primary/40 text-primary">
                    Pre-set for your industry
                  </Badge>
                )}
                {question.requiredForAI && (
                  <Badge variant="secondary" className="text-[10px] gap-1 shrink-0">
                    <Bot className="h-3 w-3" />
                    AI uses this
                  </Badge>
                )}
              </div>
              {question.description && (
                <p className="text-sm text-muted-foreground mt-0.5">
                  {question.description}
                </p>
              )}
            </div>

            <Switch
              checked={checked}
              onCheckedChange={onToggle}
              disabled={isBlocking}
            />
          </div>

          {/* Inline follow-up fields (input-based) */}
          <AnimatePresence>
            {isFieldsFollowUp && onDetailChange && (
              <FollowUpFields
                fields={(question.followUp as { fields: FollowUpField[] }).fields}
                details={details}
                onDetailChange={onDetailChange}
              />
            )}
          </AnimatePresence>

          {/* Inline follow-up question (radio/select-based) */}
          <AnimatePresence>
            {isRadioFollowUp && question.followUp && "answerKey" in question.followUp && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: "auto" }}
                exit={{ opacity: 0, height: 0 }}
                transition={{ duration: 0.2 }}
                className="overflow-hidden"
              >
                <FollowUpSection
                  followUp={question.followUp as ScenarioFollowUp}
                  value={(answers[(question.followUp as ScenarioFollowUp).answerKey] as string) || (question.followUp as ScenarioFollowUp).defaultValue}
                  onChange={(val) => onAnswerChange((question.followUp as ScenarioFollowUp).answerKey, val)}
                />
              </motion.div>
            )}
          </AnimatePresence>
        </CardContent>
      </Card>
    </motion.div>
  );
}

function FollowUpSection({
  followUp,
  value,
  onChange,
}: {
  followUp: ScenarioFollowUp;
  value: string;
  onChange: (val: string) => void;
}) {
  return (
    <div className="mt-3 pt-3 border-t border-border/50">
      <p className="text-sm font-medium mb-2">{followUp.label}</p>
      <RadioGroup value={value} onValueChange={onChange} className="space-y-1.5">
        {followUp.options.map((opt) => (
          <label
            key={opt.value}
            className={cn(
              "flex items-start gap-3 p-2.5 rounded-md cursor-pointer transition-all text-sm",
              value === opt.value
                ? "bg-primary/10 border border-primary/30"
                : "hover:bg-muted/50 border border-transparent"
            )}
          >
            <RadioGroupItem value={opt.value} className="mt-0.5" />
            <div className="flex-1 min-w-0">
              <span className="font-medium">{opt.label}</span>
              <p className="text-xs text-muted-foreground mt-0.5">{opt.description}</p>
            </div>
          </label>
        ))}
      </RadioGroup>
    </div>
  );
}

import { useState } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { cn } from "@/lib/utils";
import { Info, HelpCircle } from "lucide-react";
import BusinessHoursEditor, { type BusinessHours } from "@/components/onboarding/BusinessHoursEditor";
import {
  DEFAULT_BUSINESS_HOURS,
  RESTAURANT_HOURS,
  HOURS_24_7,
} from "@/lib/hoursUtils";
import type { BusinessMode } from "@/components/onboarding/BusinessModeSelector";

export interface SchedulingPrefs {
  defaultDurationMinutes: number;
  bufferMinutes: number;
  sameDayBooking: boolean;
  is24x7: boolean;
}

/** Industry-specific scheduling defaults keyed by industry slug */
const industrySchedulingDefaults: Record<string, Partial<SchedulingPrefs>> = {
  // Detailing / auto care — long jobs, need buffer for cleanup
  "auto-detailing": { defaultDurationMinutes: 120, bufferMinutes: 30, sameDayBooking: true },
  "car-wash": { defaultDurationMinutes: 30, bufferMinutes: 10, sameDayBooking: true },
  // Auto repair — multi-hour jobs, drop-off model
  auto_repair: { defaultDurationMinutes: 120, bufferMinutes: 30, sameDayBooking: true },
  // Salons & beauty — 30-60 min appointments, tight buffer
  "hair-salon": { defaultDurationMinutes: 45, bufferMinutes: 10, sameDayBooking: true },
  "nail-salon": { defaultDurationMinutes: 45, bufferMinutes: 10, sameDayBooking: true },
  "barber-shop": { defaultDurationMinutes: 30, bufferMinutes: 5, sameDayBooking: true },
  "med-spa": { defaultDurationMinutes: 60, bufferMinutes: 15, sameDayBooking: false },
  // Healthcare — strict scheduling
  dental: { defaultDurationMinutes: 30, bufferMinutes: 15, sameDayBooking: false },
  chiropractic: { defaultDurationMinutes: 30, bufferMinutes: 10, sameDayBooking: true },
  veterinary: { defaultDurationMinutes: 30, bufferMinutes: 15, sameDayBooking: true },
  // Home services — longer blocks, travel time
  plumbing: { defaultDurationMinutes: 90, bufferMinutes: 30, sameDayBooking: true },
  hvac: { defaultDurationMinutes: 90, bufferMinutes: 30, sameDayBooking: true },
  electrical: { defaultDurationMinutes: 90, bufferMinutes: 30, sameDayBooking: true },
  "pest-control": { defaultDurationMinutes: 60, bufferMinutes: 20, sameDayBooking: true },
  "house-cleaning": { defaultDurationMinutes: 120, bufferMinutes: 30, sameDayBooking: false },
  landscaping: { defaultDurationMinutes: 120, bufferMinutes: 30, sameDayBooking: false },
  // Tattoo / body art — long sessions
  "tattoo-studio": { defaultDurationMinutes: 120, bufferMinutes: 30, sameDayBooking: false },
  // Photography — 1-2 hour sessions
  photography: { defaultDurationMinutes: 90, bufferMinutes: 30, sameDayBooking: false },
  // Massage / wellness
  "massage-therapy": { defaultDurationMinutes: 60, bufferMinutes: 15, sameDayBooking: true },
  // Fitness / personal training
  "personal-training": { defaultDurationMinutes: 60, bufferMinutes: 10, sameDayBooking: true },
  // Tutoring
  tutoring: { defaultDurationMinutes: 60, bufferMinutes: 10, sameDayBooking: true },
  // Towing / dispatch — no scheduling
  towing: { defaultDurationMinutes: 60, bufferMinutes: 0, sameDayBooking: true, is24x7: false },
};

export function getDefaultSchedulingPrefs(
  mode: BusinessMode,
  scenarioAnswers?: Record<string, boolean>,
  industrySlug?: string
): SchedulingPrefs {
  const hasLongJobs = scenarioAnswers?.hasLongDurationJobs ?? false;
  const isCallbackOnly = scenarioAnswers?.aiBooksDirect === false;

  // Start with mode defaults
  let base: SchedulingPrefs;
  switch (mode) {
    case "dispatch":
      base = { defaultDurationMinutes: 60, bufferMinutes: 0, sameDayBooking: true, is24x7: false };
      break;
    case "food":
      base = { defaultDurationMinutes: 30, bufferMinutes: 0, sameDayBooking: true, is24x7: false };
      break;
    case "medical":
      base = { defaultDurationMinutes: 30, bufferMinutes: 15, sameDayBooking: false, is24x7: false };
      break;
    default:
      if (isCallbackOnly) {
        base = { defaultDurationMinutes: 60, bufferMinutes: 15, sameDayBooking: true, is24x7: false };
      } else if (hasLongJobs) {
        base = { defaultDurationMinutes: 120, bufferMinutes: 30, sameDayBooking: true, is24x7: false };
      } else {
        base = { defaultDurationMinutes: 60, bufferMinutes: 15, sameDayBooking: true, is24x7: false };
      }
  }

  // Override with industry-specific defaults if available
  if (industrySlug && industrySchedulingDefaults[industrySlug]) {
    return { ...base, ...industrySchedulingDefaults[industrySlug] };
  }

  return base;
}

export function getDefaultHoursForMode(mode: BusinessMode): BusinessHours {
  switch (mode) {
    case "food":
      return RESTAURANT_HOURS;
    case "dispatch":
      return DEFAULT_BUSINESS_HOURS;
    default:
      return DEFAULT_BUSINESS_HOURS;
  }
}

interface SchedulingSetupProps {
  businessMode: BusinessMode;
  hours: BusinessHours;
  onHoursChange: (hours: BusinessHours) => void;
  prefs: SchedulingPrefs;
  onPrefsChange: (prefs: SchedulingPrefs) => void;
  scenarioAnswers?: Record<string, boolean>;
}

function formatDuration(mins: number): string {
  if (mins === 0) return "Varies";
  if (mins < 60) return `${mins} min`;
  if (mins % 60 === 0) return `${mins / 60} hr${mins > 60 ? "s" : ""}`;
  const h = Math.floor(mins / 60);
  const m = mins % 60;
  return `${h}h ${m}m`;
}

function formatBuffer(mins: number): string {
  if (mins === 0) return "None";
  if (mins < 60) return `${mins} min`;
  if (mins % 60 === 0) return `${mins / 60} hr${mins > 60 ? "s" : ""}`;
  return `${mins} min`;
}

function getDurationOptions(hasLongJobs: boolean): number[] {
  if (hasLongJobs) {
    return [60, 90, 120, 180, 240, 480, 0]; // 0 = "Varies"
  }
  return [15, 30, 45, 60, 90, 120, 0]; // 0 = "Varies"
}

function getBufferOptions(hasLongJobs: boolean): number[] {
  if (hasLongJobs) {
    return [0, 15, 30, 45, 60, 120];
  }
  return [0, 5, 10, 15, 30, 45, 60];
}

function WhyTooltip({ text }: { text: string }) {
  const [open, setOpen] = useState(false);
  return (
    <span className="relative inline-flex">
      <button
        type="button"
        onClick={() => setOpen(!open)}
        className="text-muted-foreground hover:text-foreground transition-colors"
        aria-label="Why this matters"
      >
        <HelpCircle className="h-3.5 w-3.5" />
      </button>
      {open && (
        <span className="absolute left-0 top-6 z-50 w-64 rounded-md border bg-popover p-3 text-xs text-popover-foreground shadow-md animate-fade-in">
          {text}
        </span>
      )}
    </span>
  );
}

export function SchedulingSetup({
  businessMode,
  hours,
  onHoursChange,
  prefs,
  onPrefsChange,
  scenarioAnswers,
}: SchedulingSetupProps) {
  const isCallbackOnly = scenarioAnswers?.aiBooksDirect === false;
  const hasLongJobs = scenarioAnswers?.hasLongDurationJobs ?? false;

  const update = <K extends keyof SchedulingPrefs>(key: K, val: SchedulingPrefs[K]) => {
    onPrefsChange({ ...prefs, [key]: val });
  };

  const handle24x7Toggle = (enabled: boolean) => {
    update("is24x7", enabled);
    if (enabled) {
      onHoursChange(HOURS_24_7);
    } else {
      onHoursChange(getDefaultHoursForMode(businessMode));
    }
  };

  const showAppointmentPrefs = !isCallbackOnly && (businessMode === "service" || businessMode === "medical" || businessMode === "general");
  const showDispatchPrefs = businessMode === "dispatch";
  const showFoodPrefs = businessMode === "food";

  const durationOptions = getDurationOptions(hasLongJobs);
  const bufferOptions = getBufferOptions(hasLongJobs);

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold tracking-tight">
          Scheduling & Hours
        </h2>
        <p className="mt-2 text-muted-foreground">
          {isCallbackOnly
            ? "Set your business hours so the AI knows when you're open. Since you chose callback-only, you don't need appointment slots."
            : "Set your business hours and scheduling preferences. You can fine-tune these later in the Business Brain."
          }
        </p>
      </div>

      {/* Callback-only info banner */}
      {isCallbackOnly && (
        <Card className="border-blue-500/30 bg-blue-500/5">
          <CardContent className="p-4">
            <div className="flex items-start gap-3">
              <Info className="h-5 w-5 text-blue-500 shrink-0 mt-0.5" />
              <div>
                <p className="font-medium text-sm">Callback-Only Mode</p>
                <p className="text-xs text-muted-foreground mt-1">
                  Your AI will collect customer information and create callback requests. 
                  You'll schedule appointments manually by calling them back. Just set your 
                  business hours below so the AI knows when you're available.
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* 24/7 Toggle for dispatch */}
      {showDispatchPrefs && (
        <Card className={cn(prefs.is24x7 && "border-primary bg-primary/5")}>
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="font-medium text-sm">24/7 Operations</p>
                <p className="text-xs text-muted-foreground">Available around the clock</p>
              </div>
              <Switch
                checked={prefs.is24x7}
                onCheckedChange={handle24x7Toggle}
              />
            </div>
          </CardContent>
        </Card>
      )}

      {/* Business Hours Editor */}
      {!prefs.is24x7 && (
        <div className="space-y-2">
          <Label>Business Hours</Label>
          <div className="border rounded-lg p-4 max-h-[320px] overflow-y-auto">
            <BusinessHoursEditor hours={hours} onChange={onHoursChange} />
          </div>
        </div>
      )}

      {/* Appointment-based prefs — hidden for callback-only */}
      {showAppointmentPrefs && (
        <div className="space-y-4">
          <p className="text-sm font-medium">Scheduling Preferences</p>

          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1">
              <div className="flex items-center gap-1.5">
                <Label className="text-xs">Default Appointment Duration</Label>
                <WhyTooltip text="This sets how long the AI blocks on your calendar per booking. Pick your most common appointment length — you can always override per service later." />
              </div>
              <div className="flex flex-wrap gap-2">
                {durationOptions.map((d) => (
                  <button
                    key={d}
                    type="button"
                    onClick={() => update("defaultDurationMinutes", d)}
                    className={cn(
                      "px-3 py-1.5 rounded-md text-xs font-medium border transition-colors",
                      prefs.defaultDurationMinutes === d
                        ? "border-primary bg-primary/10 text-primary"
                        : "border-border hover:bg-muted/50"
                    )}
                  >
                    {formatDuration(d)}
                  </button>
                ))}
              </div>
            </div>

            <div className="space-y-1">
              <div className="flex items-center gap-1.5">
                <Label className="text-xs">Buffer Between Appointments</Label>
                <WhyTooltip text="Buffer time prevents back-to-back bookings. Use it for cleanup, travel, or prep. For example, a 30-minute buffer after a 3-hour detail gives you time to inspect the car and prep for the next one." />
              </div>
              <div className="flex flex-wrap gap-2">
                {bufferOptions.map((b) => (
                  <button
                    key={b}
                    type="button"
                    onClick={() => update("bufferMinutes", b)}
                    className={cn(
                      "px-3 py-1.5 rounded-md text-xs font-medium border transition-colors",
                      prefs.bufferMinutes === b
                        ? "border-primary bg-primary/10 text-primary"
                        : "border-border hover:bg-muted/50"
                    )}
                  >
                    {formatBuffer(b)}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <Card className={cn(prefs.sameDayBooking && "border-primary bg-primary/5")}>
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div>
                  <div className="flex items-center gap-1.5">
                    <p className="font-medium text-sm">Same-day booking</p>
                    <WhyTooltip text="When enabled, callers can book an appointment for later today if you have open slots. Turn this off if you need lead time to prepare (e.g., ordering supplies, scheduling staff)." />
                  </div>
                  <p className="text-xs text-muted-foreground">Allow customers to book appointments for today</p>
                </div>
                <Switch
                  checked={prefs.sameDayBooking}
                  onCheckedChange={(v) => update("sameDayBooking", v)}
                />
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Food-specific prefs */}
      {showFoodPrefs && (
        <Card className={cn(prefs.sameDayBooking && "border-primary bg-primary/5")}>
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div>
                <p className="font-medium text-sm">Same-day orders</p>
                <p className="text-xs text-muted-foreground">Accept orders for same-day pickup and delivery</p>
              </div>
              <Switch
                checked={prefs.sameDayBooking}
                onCheckedChange={(v) => update("sameDayBooking", v)}
              />
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

/**
 * ServiceAreaStep - Onboarding step for configuring coverage area
 *
 * Only shown for modes that need coverage: dispatch, service (mobile), food (delivery).
 * Lets user set radius and customize out-of-area message.
 */

import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { Textarea } from "@/components/ui/textarea";
import { MapPin } from "lucide-react";
import { getIndustryTerminology } from "@/data/industryTerminology";
import type { BusinessMode } from "@/components/onboarding/BusinessModeSelector";

export interface ServiceAreaConfig {
  radiusMiles: number;
  zipCodes: string;
  outOfAreaMessage: string;
}

export function getDefaultServiceArea(mode: BusinessMode): ServiceAreaConfig {
  const radius = mode === "dispatch" ? 30 : mode === "food" ? 10 : 25;
  const msg =
    mode === "dispatch"
      ? "I'm sorry, that location is outside our coverage zone. Let me take your number and we'll see if we can help."
      : mode === "food"
      ? "Unfortunately, we don't deliver to that area yet. You're welcome to place a pickup order though!"
      : "That's a bit outside our service area. Let me take your info and we'll see what we can do.";

  return {
    radiusMiles: radius,
    zipCodes: "",
    outOfAreaMessage: msg,
  };
}

interface ServiceAreaStepProps {
  businessMode: BusinessMode;
  value: ServiceAreaConfig;
  onChange: (value: ServiceAreaConfig) => void;
}

export function ServiceAreaStep({
  businessMode,
  value,
  onChange,
}: ServiceAreaStepProps) {
  const terms = getIndustryTerminology(businessMode);

  const update = (partial: Partial<ServiceAreaConfig>) => {
    onChange({ ...value, ...partial });
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold tracking-tight">
          Where You Serve
        </h2>
        <p className="mt-2 text-muted-foreground">
          Your AI will check if callers are in your {terms.locationLabel} before
          booking.
        </p>
      </div>

      {/* Radius slider */}
      <div className="space-y-3">
        <Label>Coverage Radius</Label>
        <div className="flex items-center gap-4">
          <Slider
            value={[value.radiusMiles]}
            onValueChange={([v]) => update({ radiusMiles: v })}
            min={1}
            max={50}
            step={1}
            className="flex-1"
          />
          <span className="text-sm font-medium tabular-nums w-20 text-right">
            {value.radiusMiles} miles
          </span>
        </div>
      </div>

      {/* ZIP codes (optional) */}
      <div className="space-y-2">
        <Label htmlFor="zip-codes">ZIP Codes (optional)</Label>
        <Input
          id="zip-codes"
          value={value.zipCodes}
          onChange={(e) => update({ zipCodes: e.target.value })}
          placeholder="e.g. 90210, 90211, 90212"
        />
        <p className="text-xs text-muted-foreground">
          Comma-separated. Leave blank to use radius only.
        </p>
      </div>

      {/* Out-of-area message */}
      <div className="space-y-2">
        <Label htmlFor="out-of-area">Out-of-Area Response</Label>
        <Textarea
          id="out-of-area"
          value={value.outOfAreaMessage}
          onChange={(e) => update({ outOfAreaMessage: e.target.value })}
          rows={3}
          placeholder="What your AI says when a caller is outside your area"
        />
        <div className="flex items-start gap-2 text-xs text-muted-foreground">
          <MapPin className="h-3 w-3 mt-0.5 shrink-0" />
          <span>Your AI will say this to callers outside your coverage area.</span>
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Plus, Trash2, ChevronDown, ChevronRight } from "lucide-react";
import { durationOptions, priceTypeOptions } from "@/data/industryTemplates";
import type { ModeFieldContract } from "@/lib/businessModeContract";

export interface AdvancedService {
  name: string;
  duration: number;
  price: number;
  priceType: 'fixed' | 'starting_at' | 'quote_only';
  description: string;
  preparationInstructions: string;
  upsellSuggestions: string[];
  depositRequired: boolean;
}

interface ServiceEditorAdvancedProps {
  services: AdvancedService[];
  onChange: (services: AdvancedService[]) => void;
  modeContract?: ModeFieldContract;
}

export default function ServiceEditorAdvanced({ services, onChange, modeContract }: ServiceEditorAdvancedProps) {
  const [expandedIndex, setExpandedIndex] = useState<number | null>(0);

  // Filter price type options based on mode contract
  const allowedPriceTypes = modeContract
    ? priceTypeOptions.filter(opt => modeContract.allowedPriceTypes.includes(opt.value as any))
    : priceTypeOptions;

  const updateService = (index: number, field: keyof AdvancedService, value: any) => {
    const updated = [...services];
    updated[index] = { ...updated[index], [field]: value };
    onChange(updated);
  };

  const removeService = (index: number) => {
    if (services.length <= 1) return;
    const updated = services.filter((_, i) => i !== index);
    onChange(updated);
    if (expandedIndex === index) {
      setExpandedIndex(null);
    } else if (expandedIndex !== null && expandedIndex > index) {
      setExpandedIndex(expandedIndex - 1);
    }
  };

  const addService = () => {
    const newService: AdvancedService = {
      name: '',
      duration: 60,
      price: 0,
      priceType: 'fixed',
      description: '',
      preparationInstructions: '',
      upsellSuggestions: [],
      depositRequired: false,
    };
    onChange([...services, newService]);
    setExpandedIndex(services.length);
  };

  const formatPrice = (price: number, priceType: string) => {
    if (priceType === 'quote_only') return 'Quote';
    const prefix = priceType === 'starting_at' ? 'From ' : '';
    return `${prefix}$${price}`;
  };

  const formatDuration = (minutes: number) => {
    if (minutes < 60) return `${minutes}min`;
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`;
  };

  return (
    <div className="space-y-3">
      {services.map((service, index) => (
        <Collapsible
          key={index}
          open={expandedIndex === index}
          onOpenChange={(open) => setExpandedIndex(open ? index : null)}
        >
          <div className="rounded-lg border bg-card overflow-hidden">
            <CollapsibleTrigger asChild>
              <div className="flex items-center justify-between p-3 cursor-pointer hover:bg-muted/50 transition-colors">
                <div className="flex items-center gap-3">
                  {expandedIndex === index ? (
                    <ChevronDown className="h-4 w-4 text-muted-foreground" />
                  ) : (
                    <ChevronRight className="h-4 w-4 text-muted-foreground" />
                  )}
                  <div>
                    <p className="font-medium text-sm">
                      {service.name || 'New Service'}
                    </p>
                    <p className="text-xs text-muted-foreground">
                      {modeContract?.showDuration !== false && `${formatDuration(service.duration)} • `}
                      {formatPrice(service.price, service.priceType)}
                    </p>
                  </div>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={(e) => {
                    e.stopPropagation();
                    removeService(index);
                  }}
                  disabled={services.length <= 1}
                  className="shrink-0 text-muted-foreground hover:text-destructive h-8 w-8"
                >
                  <Trash2 className="h-4 w-4" />
                </Button>
              </div>
            </CollapsibleTrigger>
            
            <CollapsibleContent>
              <div className="p-3 pt-0 space-y-4 border-t">
                {/* Basic info */}
                <div className="grid grid-cols-1 gap-3">
                  <div className="space-y-1.5">
                    <Label className="text-xs">Service Name *</Label>
                    <Input
                      value={service.name}
                      onChange={(e) => updateService(index, 'name', e.target.value)}
                      placeholder="e.g., Full Detail"
                    />
                  </div>
                  
                  <div className={modeContract?.showDuration !== false ? "grid grid-cols-3 gap-2" : "grid grid-cols-2 gap-2"}>
                    {modeContract?.showDuration !== false && (
                      <div className="space-y-1.5">
                        <Label className="text-xs">Duration</Label>
                        <Select
                          value={service.duration.toString()}
                          onValueChange={(value) => updateService(index, 'duration', parseInt(value))}
                        >
                          <SelectTrigger className="h-9">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {durationOptions.map((opt) => (
                              <SelectItem key={opt.value} value={opt.value.toString()}>
                                {opt.label}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>
                    )}

                    <div className="space-y-1.5">
                      <Label className="text-xs">{modeContract?.labels?.priceLabel || "Price"}</Label>
                      <div className="relative">
                        <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">$</span>
                        <Input
                          type="number"
                          min={0}
                          value={service.price}
                          onChange={(e) => updateService(index, 'price', parseFloat(e.target.value) || 0)}
                          className="pl-6 h-9"
                          disabled={service.priceType === 'quote_only'}
                        />
                      </div>
                    </div>

                    <div className="space-y-1.5">
                      <Label className="text-xs">Price Type</Label>
                      <Select
                        value={service.priceType}
                        onValueChange={(value) => updateService(index, 'priceType', value)}
                      >
                        <SelectTrigger className="h-9">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          {allowedPriceTypes.map((opt) => (
                            <SelectItem key={opt.value} value={opt.value}>
                              {opt.label}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>
                  </div>
                </div>
                
                {/* Description */}
                <div className="space-y-1.5">
                  <Label className="text-xs">{modeContract?.labels?.offeringDescription || "What's included?"}</Label>
                  <Textarea
                    value={service.description}
                    onChange={(e) => updateService(index, 'description', e.target.value)}
                    placeholder="Describe what the customer gets with this service..."
                    rows={2}
                    className="text-sm"
                  />
                </div>

                {/* Preparation instructions */}
                {modeContract?.showPreparationInstructions !== false && (
                  <div className="space-y-1.5">
                    <Label className="text-xs">Preparation Instructions</Label>
                    <Textarea
                      value={service.preparationInstructions}
                      onChange={(e) => updateService(index, 'preparationInstructions', e.target.value)}
                      placeholder="What should the customer do before the appointment?"
                      rows={2}
                      className="text-sm"
                    />
                  </div>
                )}

                {/* Upsells */}
                {modeContract?.showUpsellSuggestions !== false && (
                  <div className="space-y-1.5">
                    <Label className="text-xs">Upsell Suggestions</Label>
                    <Input
                      value={service.upsellSuggestions.join(', ')}
                      onChange={(e) => updateService(index, 'upsellSuggestions', e.target.value.split(',').map(s => s.trim()).filter(Boolean))}
                      placeholder="e.g., Ceramic coating, Paint protection (comma-separated)"
                      className="text-sm"
                    />
                    <p className="text-xs text-muted-foreground">AI will suggest these add-ons to customers</p>
                  </div>
                )}

                {/* Deposit */}
                {modeContract?.showDepositRequired !== false && (
                  <div className="flex items-center justify-between py-2">
                    <div>
                      <Label className="text-sm">Require deposit?</Label>
                      <p className="text-xs text-muted-foreground">Collect payment before confirming</p>
                    </div>
                    <Switch
                      checked={service.depositRequired}
                      onCheckedChange={(checked) => updateService(index, 'depositRequired', checked)}
                    />
                  </div>
                )}
              </div>
            </CollapsibleContent>
          </div>
        </Collapsible>
      ))}
      
      <Button
        variant="outline"
        onClick={addService}
        className="w-full"
      >
        <Plus className="mr-2 h-4 w-4" />
        Add {modeContract?.labels?.offeringName || "Service"}
      </Button>
    </div>
  );
}

/**
 * ServicePreviewStep - Onboarding step for previewing/editing template services
 *
 * Shows pre-populated services from industry template and lets user
 * edit, add, remove, or toggle services before they're saved to DB.
 */

import React, { useState, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Plus, X, AlertCircle, DollarSign } from "lucide-react";
import { getIndustryTerminology } from "@/data/industryTerminology";
import { cn } from "@/lib/utils";
import { getPricingModel } from "@/config/pricingModels";
import type { BusinessMode } from "@/components/onboarding/BusinessModeSelector";

export interface EditableService {
  name: string;
  duration: number;
  price: number;
  priceType: "fixed" | "starting_at" | "quote_only";
  description?: string;
  enabled: boolean;
}

interface ServicePreviewStepProps {
  businessMode: BusinessMode;
  industrySlug: string;
  services: EditableService[];
  onChange: (services: EditableService[]) => void;
}

export const ServicePreviewStep = React.memo(function ServicePreviewStep({
  businessMode,
  industrySlug,
  services,
  onChange,
}: ServicePreviewStepProps) {
  const terms = getIndustryTerminology(businessMode);
  const pricingModel = useMemo(() => getPricingModel(businessMode, industrySlug), [businessMode, industrySlug]);
  const [editingIdx, setEditingIdx] = useState<number | null>(null);

  const toggleService = (idx: number) => {
    const updated = [...services];
    updated[idx] = { ...updated[idx], enabled: !updated[idx].enabled };
    onChange(updated);
  };

  const updateService = (idx: number, field: keyof EditableService, value: string | number) => {
    const updated = [...services];
    updated[idx] = { ...updated[idx], [field]: value };
    onChange(updated);
  };

  const removeService = (idx: number) => {
    const updated = services.filter((_, i) => i !== idx);
    onChange(updated);
  };

  const addService = () => {
    onChange([
      ...services,
      {
        name: "",
        duration: 60,
        price: 0,
        priceType: "fixed",
        enabled: true,
      },
    ]);
    setEditingIdx(services.length);
  };

  const enabledCount = services.filter((s) => s.enabled).length;
  const enabledNoPriceCount = services.filter((s) => s.enabled && s.price === 0 && s.priceType !== "quote_only").length;

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold tracking-tight">
          {terms.catalogCardTitle}
        </h2>
        <p className="mt-2 text-muted-foreground">
          We've pre-loaded {terms.serviceItemLabel}s based on your industry.
          Toggle off any you don't offer, or add your own.
        </p>
      </div>

      {/* Pricing model context */}
      {pricingModel.typicalRange && (
        <div className="flex items-start gap-2 p-3 rounded-lg border bg-muted/30 text-sm">
          <DollarSign className="h-4 w-4 text-primary shrink-0 mt-0.5" />
          <div>
            <p className="font-medium text-foreground">{pricingModel.label}</p>
            <p className="text-muted-foreground">
              {pricingModel.description}.{" "}
              <span className="text-foreground font-medium">Typical range: {pricingModel.typicalRange}</span>
            </p>
          </div>
        </div>
      )}

      {/* Pricing helper tip */}
      {enabledNoPriceCount > 0 && (
        <div className="flex items-start gap-2 p-3 rounded-lg border border-amber-500/30 bg-amber-500/5 text-sm">
          <AlertCircle className="h-4 w-4 text-amber-600 shrink-0 mt-0.5" />
          <p className="text-muted-foreground">
            <strong className="text-foreground">{enabledNoPriceCount} {enabledNoPriceCount === 1 ? "service has" : "services have"} no price.</strong>{" "}
            Tap a service to add a price, or mark it as "Quote only" if pricing varies.
            Your AI uses prices to give callers accurate quotes.
          </p>
        </div>
      )}

      <div className="space-y-3">
        {services.map((service, idx) => (
          <div
            key={idx}
            className={cn(
              "rounded-lg border p-4 bg-card transition-colors",
              service.enabled && "border-primary/30 bg-primary/5"
            )}
          >
            <div className="flex items-start gap-3">
              <Switch
                checked={service.enabled}
                onCheckedChange={() => toggleService(idx)}
                className="mt-0.5"
              />

              <div className="flex-1 min-w-0">
                {editingIdx === idx ? (
                  <div className="space-y-2">
                    <Input
                      value={service.name}
                      onChange={(e) => updateService(idx, "name", e.target.value)}
                      placeholder={terms.itemNamePlaceholder}
                      autoFocus
                      onBlur={() => setEditingIdx(null)}
                      onKeyDown={(e) => e.key === "Enter" && setEditingIdx(null)}
                    />
                    <div className="flex gap-2">
                      <Input
                        type="number"
                        value={service.price}
                        onChange={(e) => updateService(idx, "price", parseFloat(e.target.value) || 0)}
                        className="w-28"
                        placeholder="Price"
                      />
                      <Input
                        type="number"
                        value={service.duration}
                        onChange={(e) => updateService(idx, "duration", parseInt(e.target.value) || 0)}
                        className="w-28"
                        placeholder="Duration (min)"
                      />
                    </div>
                  </div>
                ) : (
                  <div>
                    <p className={cn(
                      "text-sm font-medium",
                      !service.enabled && "text-muted-foreground line-through"
                    )}>
                      {service.name || `New ${terms.serviceItemLabel}`}
                    </p>
                    <p className="text-xs text-muted-foreground mt-1">
                      {service.price > 0
                        ? `$${service.price}`
                        : service.priceType === "quote_only"
                        ? "Quote only"
                        : "No price set"}
                      {" · "}
                      {service.duration >= 60
                        ? `${Math.floor(service.duration / 60)} hour${service.duration >= 120 ? "s" : ""}${service.duration % 60 ? ` ${service.duration % 60} min` : ""}`
                        : `${service.duration} min`}
                    </p>
                  </div>
                )}
              </div>

              {editingIdx !== idx && (
                <div className="flex items-center gap-1 shrink-0">
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-xs text-muted-foreground hover:text-foreground h-7 px-2"
                    onClick={() => setEditingIdx(idx)}
                  >
                    Edit
                  </Button>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="text-xs text-muted-foreground hover:text-destructive h-7 px-2"
                    onClick={() => removeService(idx)}
                  >
                    Remove
                  </Button>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      <Button
        variant="outline"
        onClick={addService}
        className="w-full gap-2"
      >
        <Plus className="h-4 w-4" />
        {terms.addItemButton}
      </Button>

      <p className="text-xs text-muted-foreground text-center">
        {enabledCount} {terms.serviceItemLabel}{enabledCount !== 1 ? "s" : ""} will be added to your account
      </p>
    </div>
  );
});

/**
 * TeamSetupStep — Onboarding step for capturing team/staff information.
 *
 * Solo operators can skip. Others add team members with name, role, and
 * optionally which services they can perform. This data seeds the
 * staff_members table (Phase 3) and informs multi-resource availability.
 */

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Card, CardContent } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Plus, X, User, Users, UserPlus } from "lucide-react";
import { cn } from "@/lib/utils";
import type { EditableService } from "./ServicePreviewStep";

export interface TeamMember {
  name: string;
  role: "owner" | "manager" | "staff";
  phone: string;
  email: string;
  canPerformAllServices: boolean;
  serviceNames: string[]; // service names they can perform (if not all)
}

interface TeamSetupStepProps {
  isSolo: boolean;
  onSoloChange: (solo: boolean) => void;
  members: TeamMember[];
  onChange: (members: TeamMember[]) => void;
  services: EditableService[];
}

const roleLabels: Record<TeamMember["role"], string> = {
  owner: "Owner",
  manager: "Manager",
  staff: "Staff",
};

export function TeamSetupStep({
  isSolo,
  onSoloChange,
  members,
  onChange,
  services,
}: TeamSetupStepProps) {
  const [expandedIdx, setExpandedIdx] = useState<number | null>(null);

  const enabledServices = services.filter((s) => s.enabled && s.name.trim());

  const addMember = () => {
    onChange([
      ...members,
      {
        name: "",
        role: "staff",
        phone: "",
        email: "",
        canPerformAllServices: true,
        serviceNames: [],
      },
    ]);
    setExpandedIdx(members.length);
  };

  const removeMember = (idx: number) => {
    onChange(members.filter((_, i) => i !== idx));
    if (expandedIdx === idx) setExpandedIdx(null);
  };

  const updateMember = (idx: number, updates: Partial<TeamMember>) => {
    const updated = [...members];
    updated[idx] = { ...updated[idx], ...updates };
    onChange(updated);
  };

  const toggleServiceForMember = (idx: number, serviceName: string) => {
    const member = members[idx];
    const current = member.serviceNames;
    const updated = current.includes(serviceName)
      ? current.filter((s) => s !== serviceName)
      : [...current, serviceName];
    updateMember(idx, { serviceNames: updated });
  };

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold tracking-tight">
          Who's on your team?
        </h2>
        <p className="mt-2 text-muted-foreground">
          Tell us about your team so we can set up scheduling for each person.
          You can always add or edit team members later.
        </p>
      </div>

      {/* Solo toggle */}
      <Card className={cn(isSolo && "border-primary bg-primary/5")}>
        <CardContent className="p-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <User className="h-5 w-5 text-muted-foreground" />
              <div>
                <p className="font-medium text-sm">I'm the only one</p>
                <p className="text-xs text-muted-foreground">
                  Solo operator — no team members to add
                </p>
              </div>
            </div>
            <Switch checked={isSolo} onCheckedChange={onSoloChange} />
          </div>
        </CardContent>
      </Card>

      {/* Team members list */}
      {!isSolo && (
        <>
          {members.length > 0 && (
            <div className="space-y-3">
              {members.map((member, idx) => (
                <Card key={idx} className="transition-all">
                  <CardContent className="p-4">
                    <div className="flex items-center gap-3">
                      <div className="flex h-8 w-8 items-center justify-center rounded-full bg-primary/10 shrink-0">
                        <Users className="h-4 w-4 text-primary" />
                      </div>

                      <div className="flex-1 min-w-0">
                        {expandedIdx === idx ? (
                          <div className="space-y-3">
                            <Input
                              value={member.name}
                              onChange={(e) =>
                                updateMember(idx, { name: e.target.value })
                              }
                              placeholder="Team member name"
                              autoFocus
                            />
                            <div className="flex gap-2">
                              <Input
                                value={member.phone}
                                onChange={(e) =>
                                  updateMember(idx, { phone: e.target.value })
                                }
                                placeholder="Phone (optional)"
                                className="flex-1"
                              />
                              <Input
                                value={member.email}
                                onChange={(e) =>
                                  updateMember(idx, { email: e.target.value })
                                }
                                placeholder="Email (optional)"
                                className="flex-1"
                              />
                            </div>
                            {/* Role selection */}
                            <div className="flex gap-2">
                              {(
                                ["owner", "manager", "staff"] as const
                              ).map((r) => (
                                <button
                                  key={r}
                                  type="button"
                                  onClick={() => updateMember(idx, { role: r })}
                                  className={cn(
                                    "px-3 py-1 rounded-md text-xs font-medium border transition-colors",
                                    member.role === r
                                      ? "border-primary bg-primary/10 text-primary"
                                      : "border-border hover:bg-muted/50"
                                  )}
                                >
                                  {roleLabels[r]}
                                </button>
                              ))}
                            </div>
                            {/* Service assignment */}
                            {enabledServices.length > 0 && (
                              <div className="space-y-2">
                                <div className="flex items-center justify-between">
                                  <p className="text-xs font-medium text-muted-foreground">
                                    Which services can they perform?
                                  </p>
                                  <button
                                    type="button"
                                    onClick={() =>
                                      updateMember(idx, {
                                        canPerformAllServices:
                                          !member.canPerformAllServices,
                                      })
                                    }
                                    className={cn(
                                      "text-xs px-2 py-0.5 rounded border transition-colors",
                                      member.canPerformAllServices
                                        ? "border-primary bg-primary/10 text-primary"
                                        : "border-border text-muted-foreground"
                                    )}
                                  >
                                    All services
                                  </button>
                                </div>
                                {!member.canPerformAllServices && (
                                  <div className="flex flex-wrap gap-1.5">
                                    {enabledServices.map((s) => (
                                      <button
                                        key={s.name}
                                        type="button"
                                        onClick={() =>
                                          toggleServiceForMember(idx, s.name)
                                        }
                                        className={cn(
                                          "text-xs px-2 py-1 rounded-full border transition-colors",
                                          member.serviceNames.includes(s.name)
                                            ? "border-primary bg-primary/10 text-primary"
                                            : "border-border text-muted-foreground hover:bg-muted/50"
                                        )}
                                      >
                                        {s.name}
                                      </button>
                                    ))}
                                  </div>
                                )}
                              </div>
                            )}
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => setExpandedIdx(null)}
                              className="text-xs"
                            >
                              Done
                            </Button>
                          </div>
                        ) : (
                          <button
                            type="button"
                            className="text-left w-full"
                            onClick={() => setExpandedIdx(idx)}
                          >
                            <p className="text-sm font-medium">
                              {member.name || "New team member"}
                            </p>
                            <div className="flex items-center gap-2 mt-0.5">
                              <Badge variant="outline" className="text-[10px]">
                                {roleLabels[member.role]}
                              </Badge>
                              {member.canPerformAllServices ? (
                                <span className="text-xs text-muted-foreground">
                                  All services
                                </span>
                              ) : (
                                <span className="text-xs text-muted-foreground">
                                  {member.serviceNames.length} service
                                  {member.serviceNames.length !== 1 ? "s" : ""}
                                </span>
                              )}
                            </div>
                          </button>
                        )}
                      </div>

                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 shrink-0 text-muted-foreground hover:text-destructive"
                        onClick={() => removeMember(idx)}
                      >
                        <X className="h-4 w-4" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          )}

          <Button
            variant="outline"
            onClick={addMember}
            className="w-full gap-2"
          >
            <UserPlus className="h-4 w-4" />
            Add team member
          </Button>

          <p className="text-xs text-muted-foreground text-center">
            {members.length === 0
              ? "Add your team members so we can schedule them individually"
              : `${members.length} team member${members.length !== 1 ? "s" : ""} added`}
          </p>
        </>
      )}
    </div>
  );
}

import React, { useMemo } from "react";
/**
 * Phase 5: GO LIVE — Review setup + launch
 */
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Check, Pencil, Sparkles, TestTube2, Rocket, AlertTriangle, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { getIndustryBySlug } from "@/data/industryCatalog";
import { estimateOnboardingReadiness, type ReadinessFlag } from "@/lib/estimateOnboardingReadiness";
import type { BusinessMode } from "@/components/onboarding/BusinessModeSelector";
import type { EditableService } from "@/components/onboarding/ServicePreviewStep";
import type { EditableFAQ } from "@/components/onboarding/FAQPreviewStep";
import type { EditablePolicies } from "@/components/onboarding/PolicyPreviewStep";
import type { BusinessHours } from "@/components/onboarding/BusinessHoursEditor";
import type { AITone, AIBookingMode } from "@/components/onboarding/CommunicationPreferences";
import type { AfterHoursBehavior } from "./OnboardingAI";
import type { WorkStyle } from "./OnboardingIdentity";

const modeLabels: Record<BusinessMode, string> = {
  service: "Service Business",
  dispatch: "Dispatch / On-Demand",
  food: "Food & Hospitality",
  medical: "Medical / Healthcare",
  general: "General Business",
  sales: "Sales Business",
};

const toneLabels: Record<AITone, string> = {
  professional: "Professional",
  friendly: "Friendly",
  casual: "Casual",
};

const bookingLabels: Record<AIBookingMode, string> = {
  auto_book: "Auto-booking enabled",
  pending_approval: "Book + require approval",
  suggest_callback: "Suggest + callback",
  callback_only: "Callback only",
};

const afterHoursLabels: Record<AfterHoursBehavior, string> = {
  ai_24_7: "24/7 AI answering",
  voicemail: "Voicemail",
  text_back: "Text back with hours",
};

interface OnboardingReviewProps {
  businessName: string;
  businessAddress: string;
  businessMode: BusinessMode;
  industrySlug: string;
  services: EditableService[];
  templateFAQs: EditableFAQ[];
  templatePolicies: EditablePolicies;
  businessHours: BusinessHours;
  aiTone: AITone;
  bookingMode: AIBookingMode;
  afterHours: AfterHoursBehavior;
  is24x7: boolean;
  workStyle: WorkStyle;
  serviceAreaRadius?: number;
  scenarioAnswers: Record<string, boolean>;
  customGreeting: string;
  onEditPhase: (phase: number) => void;
  onTestAI: () => void;
  onGoLive: () => void;
  loading: boolean;
}

export const OnboardingReview = React.memo(function OnboardingReview({
  businessName,
  businessAddress,
  businessMode,
  industrySlug,
  services,
  templateFAQs,
  templatePolicies,
  businessHours,
  aiTone,
  bookingMode,
  afterHours,
  is24x7,
  workStyle,
  serviceAreaRadius,
  scenarioAnswers,
  customGreeting,
  onEditPhase,
  onTestAI,
  onGoLive,
  loading,
}: OnboardingReviewProps) {
  const industryEntry = getIndustryBySlug(industrySlug);
  const enabledServices = services.filter((s) => s.enabled);

  // Calculate real readiness score
  const readinessResult = useMemo(
    () =>
      estimateOnboardingReadiness({
        businessName,
        businessAddress,
        businessMode,
        services,
        templateFAQs,
        templatePolicies,
        businessHours,
        is24x7,
        scenarioAnswers,
        customGreeting,
        workStyle,
        serviceAreaRadius,
      }),
    [businessName, businessAddress, businessMode, services, templateFAQs, templatePolicies, businessHours, is24x7, scenarioAnswers, customGreeting, workStyle, serviceAreaRadius]
  );

  const { score: readiness, p0Flags, p1Flags } = readinessResult;

  // Summary items for the checklist
  const checks = [
    { label: `${enabledServices.length} services configured`, done: enabledServices.length > 0 },
    { label: is24x7 ? "24/7 answering" : "Business hours set", done: true },
    { label: `${toneLabels[aiTone]} AI tone`, done: true },
    { label: bookingLabels[bookingMode], done: true },
    { label: afterHoursLabels[afterHours], done: true },
  ];

  if ((workStyle === "go_to_customer" || workStyle === "both") && serviceAreaRadius) {
    checks.push({ label: `${serviceAreaRadius} mile service area`, done: true });
  }

  // Score color
  const scoreColor = readiness >= 85 ? "text-emerald-600" : readiness >= 60 ? "text-amber-600" : "text-red-600";
  const progressColor = readiness >= 85 ? "[&>div]:bg-emerald-500" : readiness >= 60 ? "[&>div]:bg-amber-500" : "[&>div]:bg-red-500";

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold tracking-tight">
          {readiness >= 85 ? "You're ready to go live!" : "Almost there — a few items to finish"}
        </h2>
        <p className="mt-2 text-muted-foreground">
          Review your setup, then launch your AI receptionist.
        </p>
      </div>

      {/* Business Summary Card */}
      <Card>
        <CardContent className="p-5 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              {industryEntry && <span className="text-2xl">{industryEntry.icon}</span>}
              <div>
                <p className="text-lg font-semibold">{businessName}</p>
                <div className="flex items-center gap-2 mt-0.5">
                  <Badge variant="secondary">{modeLabels[businessMode]}</Badge>
                  {industryEntry && (
                    <Badge variant="outline" className="text-xs">{industryEntry.name}</Badge>
                  )}
                </div>
              </div>
            </div>
            <button
              type="button"
              onClick={() => onEditPhase(1)}
              className="text-muted-foreground hover:text-primary transition-colors"
              aria-label="Edit identity"
            >
              <Pencil className="h-4 w-4" />
            </button>
          </div>
        </CardContent>
      </Card>

      {/* Setup Checklist */}
      <Card>
        <CardContent className="p-5 space-y-4">
          <div className="flex items-center justify-between">
            <p className="text-sm font-medium">Setup Summary</p>
            <button
              type="button"
              onClick={() => onEditPhase(3)}
              className="text-muted-foreground hover:text-primary transition-colors text-xs"
            >
              Edit
            </button>
          </div>
          <div className="space-y-2">
            {checks.map((check, idx) => (
              <div key={idx} className="flex items-center gap-2.5">
                <div className={cn(
                  "flex h-5 w-5 items-center justify-center rounded-full shrink-0",
                  check.done ? "bg-primary/10" : "bg-muted"
                )}>
                  <Check className={cn(
                    "h-3 w-3",
                    check.done ? "text-primary" : "text-muted-foreground"
                  )} />
                </div>
                <span className="text-sm">{check.label}</span>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* P0 Flags — Fix before going live */}
      {p0Flags.length > 0 && (
        <Card className="border-red-200 dark:border-red-800">
          <CardContent className="p-5 space-y-3">
            <div className="flex items-center gap-2">
              <AlertTriangle className="h-4 w-4 text-red-500" />
              <p className="text-sm font-medium text-red-600 dark:text-red-400">Fix before going live</p>
            </div>
            <div className="space-y-2">
              {p0Flags.map((flag) => (
                <div key={flag.id} className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <X className="h-3.5 w-3.5 text-red-500" />
                    <span className="text-sm">{flag.label}</span>
                  </div>
                  <button
                    type="button"
                    onClick={() => onEditPhase(flag.phase)}
                    className="text-xs text-primary hover:underline"
                  >
                    Fix
                  </button>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* P1 Flags — Recommended */}
      {p1Flags.length > 0 && (
        <Card className="border-amber-200 dark:border-amber-800">
          <CardContent className="p-5 space-y-3">
            <div className="flex items-center gap-2">
              <Sparkles className="h-4 w-4 text-amber-500" />
              <p className="text-sm font-medium text-amber-600 dark:text-amber-400">Recommended</p>
            </div>
            <div className="space-y-2">
              {p1Flags.map((flag) => (
                <div key={flag.id} className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <AlertTriangle className="h-3.5 w-3.5 text-amber-500" />
                    <span className="text-sm">{flag.label}</span>
                  </div>
                  <button
                    type="button"
                    onClick={() => onEditPhase(flag.phase)}
                    className="text-xs text-primary hover:underline"
                  >
                    Edit
                  </button>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Readiness Score */}
      <Card>
        <CardContent className="p-5 space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Sparkles className="h-4 w-4 text-primary" />
              <p className="text-sm font-medium">AI Readiness</p>
            </div>
            <span className={cn("text-sm font-semibold", scoreColor)}>{readiness}%</span>
          </div>
          <Progress value={readiness} className={cn("h-2", progressColor)} />
          <p className="text-xs text-muted-foreground">
            This matches the readiness score on your dashboard. You can continue to improve after going live.
          </p>
        </CardContent>
      </Card>

      {/* Action Buttons */}
      <div className="flex flex-col gap-3 pt-2">
        <Button
          size="lg"
          onClick={onGoLive}
          disabled={loading || p0Flags.length > 0}
          className="w-full gap-2"
        >
          {loading ? (
            <>
              <span className="h-4 w-4 animate-spin rounded-full border-2 border-current border-t-transparent" />
              Setting up...
            </>
          ) : (
            <>
              <Rocket className="h-4 w-4" />
              Go Live Now
            </>
          )}
        </Button>
        <Button
          variant="outline"
          size="lg"
          onClick={onTestAI}
          disabled={loading}
          className="w-full gap-2"
        >
          <TestTube2 className="h-4 w-4" />
          Test Your AI First
        </Button>
      </div>

      <p className="text-xs text-muted-foreground text-center">
        Everything can be fine-tuned later in your{" "}
        <span className="font-medium text-foreground">Business Brain</span>.
      </p>
    </div>
  );
});

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { cn } from "@/lib/utils";
import { 
  Truck,
  ShoppingBag,
  UtensilsCrossed,
  Eye,
} from "lucide-react";
import { formatDistanceToNow } from "date-fns";

interface OrderItem {
  name: string;
  qty: number;
  price_cents?: number | null;
  matched?: boolean;
  modifiers?: string[];
}

export const orderStatusColors: Record<string, string> = {
  pending: "bg-warning/10 text-warning border-warning/30",
  confirmed: "bg-info/10 text-info border-info/30",
  preparing: "bg-primary/10 text-primary border-primary/30",
  ready: "bg-success/10 text-success border-success/30",
  out_for_delivery: "bg-info/10 text-info border-info/30",
  completed: "bg-muted text-muted-foreground border-border",
  cancelled: "bg-destructive/10 text-destructive border-destructive/30",
  needs_followup: "bg-warning/10 text-warning border-warning/30",
};

export const orderStatusLabels: Record<string, string> = {
  pending: "Pending",
  confirmed: "Confirmed",
  preparing: "Preparing",
  ready: "Ready",
  out_for_delivery: "Out for Delivery",
  completed: "Completed",
  cancelled: "Cancelled",
  needs_followup: "Needs Follow-up",
};

interface OrderCardProps {
  order: {
    id: string;
    order_number: string;
    order_type: string;
    status: string;
    customer_name: string | null;
    customer_phone: string | null;
    delivery_address: string | null;
    items_json: unknown;
    special_instructions: string | null;
    total_cents: number | null;
    created_at: string;
    requested_time: string | null;
  };
  onView?: () => void;
  onStatusChange?: (status: string) => void;
  isUpdating?: boolean;
}

const getNextStatus = (status: string): { next: string; label: string } | null => {
  switch (status) {
    case "pending": return { next: "confirmed", label: "Confirm" };
    case "confirmed": return { next: "preparing", label: "Start Preparing" };
    case "preparing": return { next: "ready", label: "Mark Ready" };
    case "ready": return { next: "completed", label: "Complete" };
    default: return null;
  }
};

export function OrderCard({ order, onView, onStatusChange, isUpdating }: OrderCardProps) {
  const items = Array.isArray(order.items_json) ? (order.items_json as OrderItem[]) : [];
  const nextAction = getNextStatus(order.status);
  
  const getOrderTypeIcon = () => {
    switch (order.order_type) {
      case "delivery": return <Truck className="w-3 h-3 mr-1" />;
      case "dine_in": return <UtensilsCrossed className="w-3 h-3 mr-1" />;
      default: return <ShoppingBag className="w-3 h-3 mr-1" />;
    }
  };

  const formatOrderType = (type: string) => {
    if (type === "pickup") return "Pickup";
    if (type === "delivery") return "Delivery";
    if (type === "dine_in") return "Dine In";
    return type.replace("_", " ");
  };

  const getItemsPreview = () => {
    if (items.length === 0) return "No items";
    return items.map(i => i.name).join(", ");
  };

  const formatRelativeTime = (date: string) => {
    return formatDistanceToNow(new Date(date), { addSuffix: true });
  };

  return (
    <Card className="hover:border-primary/50 transition-colors">
      <CardContent className="p-4">
        {/* Header */}
        <div className="flex items-center justify-between mb-3">
          <div className="flex items-center gap-2">
            <span className="font-mono text-lg font-bold">#{order.order_number}</span>
            <Badge variant="outline" className="gap-0.5">
              {getOrderTypeIcon()}
              {formatOrderType(order.order_type)}
            </Badge>
          </div>
          <Badge className={cn("border", orderStatusColors[order.status])}>
            {orderStatusLabels[order.status] || order.status}
          </Badge>
        </div>

        {/* Customer */}
        <div className="mb-3">
          <p className="font-medium">{order.customer_name || "Unknown Customer"}</p>
          <p className="text-sm text-muted-foreground">{order.customer_phone || "No phone"}</p>
        </div>

        {/* Items preview */}
        <div className="mb-3 p-3 bg-muted/50 rounded-lg">
          <p className="text-sm font-medium mb-1">
            {items.length} item{items.length !== 1 ? "s" : ""}
          </p>
          <p className="text-sm text-muted-foreground line-clamp-2">
            {getItemsPreview()}
          </p>
        </div>

        {/* Total & time */}
        <div className="flex items-center justify-between mb-3">
          <p className="text-lg font-semibold">
            ${((order.total_cents || 0) / 100).toFixed(2)}
          </p>
          <p className="text-sm text-muted-foreground">
            {formatRelativeTime(order.created_at)}
          </p>
        </div>

        {/* Status actions */}
        <div className="flex gap-2 pt-3 border-t">
          {nextAction && onStatusChange && (
            <Button
              size="sm"
              className="flex-1"
              disabled={isUpdating}
              onClick={() => onStatusChange(nextAction.next)}
            >
              {nextAction.label}
            </Button>
          )}
          {!nextAction && (
            <Button size="sm" variant="outline" className="flex-1" disabled>
              {order.status === "completed" ? "Done" : order.status === "cancelled" ? "Cancelled" : "No Action"}
            </Button>
          )}
          <Button size="sm" variant="outline" onClick={onView}>
            <Eye className="w-4 h-4" />
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Card, CardContent } from "@/components/ui/card";
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Phone,
  MapPin,
  Clock,
  Printer,
  RefreshCw,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  Loader2,
  Truck,
  ShoppingBag,
  Copy,
  ExternalLink,
} from "lucide-react";
import { format } from "date-fns";
import { useToast } from "@/hooks/use-toast";
import { useNavigate } from "react-router-dom";

interface OrderItem {
  name: string;
  qty: number;
  base_price?: number;
  price_cents?: number | null;
  menu_item_id?: string | null;
  matched?: boolean;
  modifiers?: string[];
  item_notes?: string;
}

interface HandoffAttempt {
  id: string;
  method: string;
  status: string;
  error_message: string | null;
  created_at: string;
}

interface Order {
  id: string;
  order_number: string;
  order_type: string;
  status: string;
  customer_name: string | null;
  customer_phone: string | null;
  delivery_address: string | null;
  address_json: unknown;
  items_json: unknown;
  special_instructions: string | null;
  requested_time: string | null;
  totals_estimate: unknown;
  handoff_state: unknown;
  subtotal_cents: number | null;
  tax_cents: number | null;
  total_cents: number | null;
  created_at: string;
}

interface OrderDetailsDrawerProps {
  order: Order | null;
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

const statusConfig: Record<string, { label: string; color: string }> = {
   pending: { label: "Pending", color: "bg-warning/10 text-warning border-warning/30" },
   confirmed: { label: "Confirmed", color: "bg-info/10 text-info border-info/30" },
   preparing: { label: "Preparing", color: "bg-primary/10 text-primary border-primary/30" },
   ready: { label: "Ready", color: "bg-success/10 text-success border-success/30" },
   out_for_delivery: { label: "Out for Delivery", color: "bg-info/10 text-info border-info/30" },
   completed: { label: "Completed", color: "bg-muted text-muted-foreground border-border" },
   cancelled: { label: "Cancelled", color: "bg-destructive/10 text-destructive border-destructive/30" },
   needs_followup: { label: "Needs Follow-up", color: "bg-warning/10 text-warning border-warning/30" },
};

export function OrderDetailsDrawer({ order, open, onOpenChange }: OrderDetailsDrawerProps) {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const navigate = useNavigate();
  const queryClient = useQueryClient();

  const items = Array.isArray(order?.items_json) ? (order.items_json as OrderItem[]) : [];
  const address = order?.address_json as { street?: string; city?: string; zip?: string } | null;
  const config = statusConfig[order?.status || "pending"];

  const { data: handoffAttempts } = useQuery({
    queryKey: ["handoff-attempts", order?.id],
    queryFn: async () => {
      if (!order?.id) return [];
      const { data, error } = await supabase
        .from("handoff_attempts")
        .select("*")
        .eq("order_id", order.id)
        .order("created_at", { ascending: false });

      if (error) throw error;
      return data as HandoffAttempt[];
    },
    enabled: !!order?.id && open,
  });

  const updateStatusMutation = useMutation({
    mutationFn: async (newStatus: string) => {
      if (!order?.id) throw new Error("No order");
      const { error } = await supabase
        .from("food_orders")
        .update({ status: newStatus as any })
        .eq("id", order.id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["food-orders"] });
      toast({ title: "Order status updated" });
    },
    onError: (error: Error) => {
      toast({ variant: "destructive", title: "Error", description: error.message });
    },
  });

  const retryHandoffMutation = useMutation({
    mutationFn: async (method: string) => {
      if (!order?.id || !tenant?.id) throw new Error("No order or tenant");
      
      const response = await supabase.functions.invoke("order-handoff", {
        body: {
          order_id: order.id,
          tenant_id: tenant.id,
          methods: [method],
        },
      });

      if (response.error) throw response.error;
      return response.data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["handoff-attempts", order?.id] });
      toast({ title: "Handoff retry initiated" });
    },
    onError: (error: Error) => {
      toast({ variant: "destructive", title: "Retry failed", description: error.message });
    },
  });

  const handlePrint = () => {
    if (order?.id) {
      navigate(`/app/orders/${order.id}/ticket`);
    }
  };

  const handleCopyPhone = () => {
    if (order?.customer_phone) {
      navigator.clipboard.writeText(order.customer_phone);
      toast({ title: "Phone number copied" });
    }
  };

  const formatCurrency = (cents: number | null | undefined) => {
    if (cents == null) return "$0.00";
    return `$${(cents / 100).toFixed(2)}`;
  };

  const formatOrderType = (type: string) => {
    if (type === "pickup") return "Pickup";
    if (type === "delivery") return "Delivery";
    if (type === "dine_in") return "Dine-in";
    return type.charAt(0).toUpperCase() + type.slice(1);
  };

  if (!order) return null;

  const isDelivery = order.order_type === "delivery";

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full sm:max-w-lg overflow-y-auto p-0">
        {/* Header */}
        <div className="sticky top-0 bg-background border-b p-4 z-10">
          <SheetHeader>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <SheetTitle className="font-mono text-xl">{order.order_number}</SheetTitle>
                <Badge className={config.color}>{config.label}</Badge>
              </div>
            </div>
            <div className="flex items-center gap-3 mt-2 text-sm text-muted-foreground">
              <Badge variant="outline" className="gap-1">
                {isDelivery ? <Truck className="h-3 w-3" /> : <ShoppingBag className="h-3 w-3" />}
                {formatOrderType(order.order_type)}
              </Badge>
              <span className="flex items-center gap-1">
                <Clock className="h-3 w-3" />
                {order.requested_time 
                  ? format(new Date(order.requested_time), "h:mm a")
                  : "ASAP"
                }
              </span>
              <span>{format(new Date(order.created_at), "MMM d, h:mm a")}</span>
            </div>
          </SheetHeader>
        </div>

        <div className="p-4 space-y-4">
          {/* Customer Info Card */}
          <Card>
            <CardContent className="p-4 space-y-3">
              <h3 className="font-semibold text-sm uppercase tracking-wide text-muted-foreground">Customer</h3>
              <div>
                <p className="font-medium text-lg">{order.customer_name || "Unknown Customer"}</p>
                {order.customer_phone && (
                  <div className="flex items-center gap-2 mt-1">
                    <a 
                      href={`tel:${order.customer_phone}`}
                      className="flex items-center gap-1.5 text-primary hover:underline"
                    >
                      <Phone className="h-4 w-4" />
                      {order.customer_phone}
                    </a>
                    <Button variant="ghost" size="icon" className="h-6 w-6" onClick={handleCopyPhone}>
                      <Copy className="h-3 w-3" />
                    </Button>
                  </div>
                )}
              </div>
              
              {isDelivery && (address || order.delivery_address) && (
                <div className="pt-2 border-t">
                  <div className="flex items-start gap-2 text-sm">
                    <MapPin className="h-4 w-4 mt-0.5 text-muted-foreground shrink-0" />
                    <div>
                      {address?.street || order.delivery_address}
                      {address?.city && <><br />{address.city} {address.zip}</>}
                    </div>
                  </div>
                </div>
              )}
            </CardContent>
          </Card>

          {/* Special Instructions - PROMINENT */}
          {order.special_instructions && (
            <Card className="border-2 border-amber-500/50 bg-amber-500/5">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 mb-2">
                  <AlertTriangle className="h-5 w-5 text-amber-400" />
                  <h3 className="font-bold text-amber-400">Special Instructions</h3>
                </div>
                <p className="whitespace-pre-wrap">{order.special_instructions}</p>
              </CardContent>
            </Card>
          )}

          {/* Items Card */}
          <Card>
            <CardContent className="p-4 space-y-3">
              <div className="flex items-center justify-between">
                <h3 className="font-semibold text-sm uppercase tracking-wide text-muted-foreground">
                  Items ({items.length})
                </h3>
              </div>
              
              {items.length === 0 ? (
                <p className="text-muted-foreground text-sm italic">No items recorded</p>
              ) : (
                <div className="space-y-3">
                  {items.map((item, idx) => {
                    // Support both price_cents (new) and base_price (legacy)
                    const priceCents = item.price_cents ?? (item.base_price ? item.base_price : null);
                    const lineTotal = priceCents ? priceCents * item.qty : null;
                    
                    return (
                      <div key={idx} className="flex justify-between items-start py-2 border-b last:border-0">
                        <div className="flex-1">
                          <div className="font-medium flex items-center gap-2">
                            <span className="text-primary font-bold">{item.qty}×</span>
                            <span>{item.name}</span>
                            {item.matched === false && (
                              <Badge variant="outline" className="text-xs bg-amber-500/10 text-amber-500 border-amber-500/30">
                                Unpriced
                              </Badge>
                            )}
                          </div>
                          {item.modifiers && item.modifiers.length > 0 && (
                            <div className="mt-1 text-sm text-muted-foreground">
                              {item.modifiers.map((mod, i) => (
                                <span key={i} className="block">+ {mod}</span>
                              ))}
                            </div>
                          )}
                          {item.item_notes && (
                            <p className="mt-1 text-sm italic text-muted-foreground">
                              "{item.item_notes}"
                            </p>
                          )}
                        </div>
                        {lineTotal !== null ? (
                          <span className="font-medium shrink-0 ml-4">
                            {formatCurrency(lineTotal)}
                          </span>
                        ) : (
                          <span className="text-sm text-muted-foreground shrink-0 ml-4">—</span>
                        )}
                      </div>
                    );
                  })}
                </div>
              )}

              {/* Totals */}
              <div className="pt-3 border-t space-y-1">
                {order.subtotal_cents != null && (
                  <div className="flex justify-between text-sm">
                    <span className="text-muted-foreground">Subtotal</span>
                    <span>{formatCurrency(order.subtotal_cents)}</span>
                  </div>
                )}
                {order.tax_cents != null && order.tax_cents > 0 && (
                  <div className="flex justify-between text-sm">
                    <span className="text-muted-foreground">Tax</span>
                    <span>{formatCurrency(order.tax_cents)}</span>
                  </div>
                )}
                <div className="flex justify-between text-lg font-bold pt-1">
                  <span>Total</span>
                  <span>{formatCurrency(order.total_cents)}</span>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Handoff Status (collapsible, minimal by default) */}
          {handoffAttempts && handoffAttempts.length > 0 && (
            <Card>
              <CardContent className="p-4 space-y-2">
                <h3 className="font-semibold text-sm uppercase tracking-wide text-muted-foreground">
                  Notifications
                </h3>
                <div className="space-y-2">
                  {handoffAttempts.slice(0, 3).map((attempt) => (
                    <div key={attempt.id} className="flex items-center justify-between text-sm">
                      <div className="flex items-center gap-2">
                        {attempt.status === "success" ? (
                          <CheckCircle2 className="h-4 w-4 text-emerald-500" />
                        ) : (
                          <XCircle className="h-4 w-4 text-destructive" />
                        )}
                        <span className="capitalize">{attempt.method}</span>
                      </div>
                      {attempt.status === "failed" && (
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => retryHandoffMutation.mutate(attempt.method)}
                          disabled={retryHandoffMutation.isPending}
                        >
                          {retryHandoffMutation.isPending ? (
                            <Loader2 className="h-3 w-3 animate-spin" />
                          ) : (
                            <RefreshCw className="h-3 w-3" />
                          )}
                        </Button>
                      )}
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}
        </div>

        {/* Sticky Footer Actions */}
        <div className="sticky bottom-0 bg-background border-t p-4 space-y-3">
          <div className="flex gap-2">
            <Select 
              value={order.status} 
              onValueChange={(v) => updateStatusMutation.mutate(v)}
            >
              <SelectTrigger className="flex-1">
                <SelectValue placeholder="Update status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="confirmed">Confirmed</SelectItem>
                <SelectItem value="preparing">Preparing</SelectItem>
                <SelectItem value="ready">Ready</SelectItem>
                <SelectItem value="out_for_delivery">Out for Delivery</SelectItem>
                <SelectItem value="completed">Completed</SelectItem>
                <SelectItem value="cancelled">Cancelled</SelectItem>
                <SelectItem value="needs_followup">Needs Follow-up</SelectItem>
              </SelectContent>
            </Select>

            <Button onClick={handlePrint}>
              <Printer className="h-4 w-4 mr-2" />
              Print
            </Button>
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

