          {/* Footer actions */}
          {campaign && (
            <div className="p-4 border-t bg-background flex-shrink-0">
              {campaign.status === "converted" ? (
                <div className="flex items-center gap-3 text-success">
                  <CheckCircle className="w-5 h-5" />
                  <div>
                    <p className="font-medium">Converted!</p>
