                    <CheckCircle className="w-4 h-4" /> Mark Converted
                  </Button>
                  
                  <div className="flex items-center gap-1">
                    {campaign.status === "active" && (
                      <Button variant="outline" size="icon" onClick={handlePause}>
                        <PauseCircle className="w-4 h-4" />
