  name: string;
  icon: string;
  description: string;
  popular?: boolean;
  authType: "oauth" | "api_key" | "ics_url" | "manual";
  status: "available" | "coming_soon" | "api_key";
}

const PROVIDER_OPTIONS: ProviderOption[] = [
  {
    id: "google",
    name: "Google Calendar",
    icon: "📅",
    description: "Perfect for Gmail/Google Workspace users",
    popular: true,
    authType: "oauth",
    status: "available",
  },
  {
    id: "calendly",
    name: "Calendly",
    icon: "🗓️",
    description: "If you use Calendly for bookings",
    authType: "api_key",
    status: "api_key",
  },
  {
    id: "square",
    name: "Square Appointments",
    icon: "⬛",
    description: "For Square users with appointment scheduling",
    authType: "api_key",
    status: "api_key",
  },
  {
    id: "jobber",
    name: "Jobber",
    icon: "🔧",
    description: "For field service businesses using Jobber",
    authType: "api_key",
    status: "api_key",
  },
  {
    id: "microsoft",
    name: "Microsoft Outlook",
    icon: "📧",
    description: "For Outlook/Office 365 calendars",
    authType: "oauth",
    status: "available",
  },
  {
    id: "ics",
    name: "Calendar Link (ICS)",
    icon: "🔗",
    description: "Import from any calendar with a share link",
    authType: "ics_url",
    status: "available",
  },
  {
    id: "not_sure",
    name: "I'm not sure",
    icon: "❓",
    description: "Let us help you figure out what to connect",
    authType: "manual",
    status: "available",
  },
];

interface ScheduleConnectionWizardProps {
  embedded?: boolean;
  onComplete?: () => void;
  onSkip?: () => void;
}

export function ScheduleConnectionWizard({ embedded = false, onComplete, onSkip }: ScheduleConnectionWizardProps) {
  const navigate = useNavigate();
  const { tenant } = useAuth();
  const { toast } = useToast();
  const { connections, createConnection, refetch, hasConnectedCalendar } = useCalendarConnections();
  
  const [step, setStep] = useState(1);
  const [selectedProvider, setSelectedProvider] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [isConnecting, setIsConnecting] = useState(false);
  
  // "I'm not sure" flow answers
  const [hasPublicBookingLink, setHasPublicBookingLink] = useState<boolean | null>(null);
  const [usesGmail, setUsesGmail] = useState<boolean | null>(null);
  
  // API key flow
  const [apiKey, setApiKey] = useState("");
  const [webhookUrl, setWebhookUrl] = useState("");
  
  // ICS URL flow
  const [icsUrl, setIcsUrl] = useState("");

  // Filter providers by search
  const filteredProviders = PROVIDER_OPTIONS.filter(
    (p) =>
      p.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      p.description.toLowerCase().includes(searchQuery.toLowerCase())
  );

  // Listen for OAuth callback
  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      if (event.data?.type === "calendar-oauth-success") {
        setIsConnecting(false);
        refetch();
        setStep(4); // Success step
        toast({ title: "Calendar connected!", description: "Your schedule is now synced." });
      } else if (event.data?.type === "calendar-oauth-error") {
        setIsConnecting(false);
        toast({
          title: "Connection failed",
          description: event.data.error || "Could not connect to calendar",
          variant: "destructive",
        });
      }
    };

    window.addEventListener("message", handleMessage);
    return () => window.removeEventListener("message", handleMessage);
  }, [refetch, toast]);

  // Polling fallback for OAuth
  useEffect(() => {
    if (!isConnecting || !selectedProvider) return;

    const pollInterval = setInterval(async () => {
      const { data } = await supabase
        .from("calendar_connections")
        .select("*")
        .eq("provider", selectedProvider)
        .eq("status", "connected")
        .maybeSingle();

      if (data) {
        clearInterval(pollInterval);
        setIsConnecting(false);
        refetch();
        setStep(4);
        toast({ title: "Calendar connected!" });
      }
    }, 2000);

    const timeout = setTimeout(() => {
      clearInterval(pollInterval);
      if (isConnecting) {
        setIsConnecting(false);
        toast({ title: "Connection timed out", variant: "destructive" });
      }
    }, 120000);

    return () => {
      clearInterval(pollInterval);
      clearTimeout(timeout);
    };
  }, [isConnecting, selectedProvider, toast, refetch]);

  const startOAuth = async (provider: "google" | "microsoft") => {
    setIsConnecting(true);
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) {
        toast({ title: "Please log in first", variant: "destructive" });
        setIsConnecting(false);
        return;
      }

      const response = await supabase.functions.invoke("calendar-oauth-start", {
        body: { provider, tenant_id: tenant?.id },
      });

      if (response.error) throw new Error(response.error.message);
      if (response.data?.error) throw new Error(response.data.error);

      const { auth_url } = response.data;
      if (!auth_url) throw new Error("No auth URL returned");

      const popup = window.open(auth_url, "calendar-oauth", "width=600,height=700,left=100,top=100");
      if (!popup) {
        toast({
          title: "Popup blocked",
          description: "Please allow popups for this site",
          variant: "destructive",
        });
        setIsConnecting(false);
      }
    } catch (error: unknown) {
      console.error("OAuth error:", error);
      const message = error instanceof Error ? error.message : "Connection failed";
      toast({ title: "Connection failed", description: message, variant: "destructive" });
      setIsConnecting(false);
    }
  };

  const handleProviderSelect = (providerId: string) => {
    setSelectedProvider(providerId);
    
    if (providerId === "not_sure") {
      setStep(2); // Go to "not sure" questions
    } else if (providerId === "google" || providerId === "microsoft") {
      setStep(3); // Go to OAuth connect step
    } else if (providerId === "ics") {
      setStep(3); // Go to ICS URL input
    } else {
      // API key providers (Calendly, Square, Jobber)
      setStep(3); // Go to API key input
    }
  };

  const handleNotSureNext = () => {
    // Determine recommendation based on answers
    if (usesGmail) {
      setSelectedProvider("google");
      setStep(3);
    } else if (hasPublicBookingLink) {
      // Recommend ICS or webhook
      setSelectedProvider("ics");
      setStep(3);
    } else {
      // Recommend manual busy blocks
      setSelectedProvider("manual");
      handleManualSetup();
    }
  };

  const handleManualSetup = async () => {
    try {
      await createConnection.mutateAsync({
        provider: "manual",
        auth_type: "manual",
      });
      setStep(4);
    } catch (error) {
      console.error("Manual setup error:", error);
    }
  };

  const handleICSConnect = async () => {
    if (!icsUrl) {
      toast({ title: "Please enter an ICS URL", variant: "destructive" });
      return;
    }
    
    setIsConnecting(true);
    try {
      await createConnection.mutateAsync({
        provider: "ics",
        auth_type: "ics_url",
        config_json: { ics_url: icsUrl },
      });
      
      // Trigger sync
      const conn = connections.find(c => c.provider === "ics");
      if (conn) {
        await supabase.functions.invoke("sync-availability", {
          body: { connection_id: conn.id, days: 30, tenant_id: tenant?.id },
        });
      }
      
      setStep(4);
    } catch (error) {
      console.error("ICS connect error:", error);
      toast({ title: "Failed to connect calendar", variant: "destructive" });
    } finally {
      setIsConnecting(false);
    }
  };

  const handleApiKeyConnect = async () => {
    if (!apiKey) {
      toast({ title: "Please enter your API key", variant: "destructive" });
      return;
    }
    
    setIsConnecting(true);
    try {
      let extraConfig: Record<string, string | undefined> = {
        api_key: apiKey,
        webhook_url: webhookUrl || undefined,
      };

      // For Calendly: verify the token and pull user info before saving
      if (selectedProvider === "calendly") {
        const { data: verifyData, error: verifyError } = await supabase.functions.invoke("calendly-proxy", {
          body: { action: "verify_token", api_key: apiKey, tenant_id: tenant?.id },
        });

        if (verifyError || !verifyData?.valid) {
          toast({
            title: "Invalid Calendly token",
            description: "Please check your Personal Access Token and try again.",
            variant: "destructive",
          });
          setIsConnecting(false);
          return;
        }

        // Store scheduling URL and user info alongside the token
        extraConfig = {
          ...extraConfig,
          scheduling_url: verifyData.user?.scheduling_url,
          calendly_user_uri: verifyData.user?.uri,
          calendly_user_name: verifyData.user?.name,
          calendly_user_email: verifyData.user?.email,
        };

        toast({
          title: `✓ Calendly verified`,
          description: `Connected as ${verifyData.user?.name || verifyData.user?.email}`,
        });
      }

      await createConnection.mutateAsync({
        provider: selectedProvider as any,
        auth_type: "api_key",
        config_json: extraConfig,
      });
      setStep(4);
    } catch (error) {
      console.error("API key connect error:", error);
      toast({ title: "Failed to connect", variant: "destructive" });
    } finally {
      setIsConnecting(false);
    }
  };

  const handleComplete = () => {
    if (onComplete) {
      onComplete();
    } else {
      navigate("/app/dashboard");
    }
  };

  const handleTestAvailability = () => {
    navigate("/debug/availability");
  };

  // Render step content
  const renderStep = () => {
    switch (step) {
      case 1:
        return (
          <div className="space-y-6">
            <div className="text-center mb-6">
              <h2 className="text-xl font-semibold mb-2">What do you use to manage bookings?</h2>
              <p className="text-muted-foreground">
                Connect your calendar so AI never double-books your appointments
              </p>
            </div>

            {/* Search */}
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input
                placeholder="Search for your tool..."
                className="pl-10"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>

            {/* Provider Grid */}
            <div className="grid gap-3 sm:grid-cols-2">
              {filteredProviders.map((provider) => (
                <Card
                  key={provider.id}
                  className={`cursor-pointer transition-all hover:border-primary ${
                    selectedProvider === provider.id ? "border-primary bg-primary/5" : ""
                  }`}
                  onClick={() => handleProviderSelect(provider.id)}
                >
                  <CardContent className="p-4">
                    <div className="flex items-start gap-3">
                      <span className="text-2xl">{provider.icon}</span>
                      <div className="flex-1">
                        <div className="flex items-center gap-2">
                          <span className="font-medium">{provider.name}</span>
                          {provider.popular && (
                            <Badge variant="secondary" className="text-[10px]">Popular</Badge>
                          )}
                          {provider.status === "coming_soon" && (
                            <Badge variant="outline" className="text-[10px]">Coming soon</Badge>
                          )}
                          {provider.status === "api_key" && (
                            <Badge variant="outline" className="text-[10px]">API Key</Badge>
                          )}
                        </div>
                        <p className="text-sm text-muted-foreground mt-0.5">
                          {provider.description}
                        </p>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>

            {onSkip && (
              <div className="text-center pt-2">
                <Button variant="ghost" onClick={onSkip}>
                  Skip for now
                </Button>
              </div>
            )}
          </div>
        );

      case 2:
        // "I'm not sure" flow
        return (
          <div className="space-y-6">
            <Button variant="ghost" size="sm" onClick={() => setStep(1)} className="mb-2">
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back
            </Button>

            <div className="text-center mb-6">
              <h2 className="text-xl font-semibold mb-2">Let's figure this out together</h2>
              <p className="text-muted-foreground">
                Answer a couple of quick questions
              </p>
            </div>

            <div className="space-y-6">
              {/* Question 1 */}
              <div className="p-4 rounded-lg border bg-muted/30">
                <Label className="text-base font-medium mb-3 block">
                  Do you have a public booking link customers use?
                </Label>
                <RadioGroup
                  value={hasPublicBookingLink === null ? "" : hasPublicBookingLink ? "yes" : "no"}
                  onValueChange={(v) => setHasPublicBookingLink(v === "yes")}
                  className="flex gap-4"
                >
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="yes" id="booking-yes" />
                    <Label htmlFor="booking-yes">Yes</Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="no" id="booking-no" />
                    <Label htmlFor="booking-no">No</Label>
                  </div>
                </RadioGroup>
              </div>

              {/* Question 2 */}
              <div className="p-4 rounded-lg border bg-muted/30">
                <Label className="text-base font-medium mb-3 block flex items-center gap-2">
                  <Mail className="h-4 w-4" />
                  Do you use Gmail or Google Workspace?
                </Label>
                <RadioGroup
                  value={usesGmail === null ? "" : usesGmail ? "yes" : "no"}
                  onValueChange={(v) => setUsesGmail(v === "yes")}
                  className="flex gap-4"
                >
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="yes" id="gmail-yes" />
                    <Label htmlFor="gmail-yes">Yes</Label>
                  </div>
                  <div className="flex items-center space-x-2">
                    <RadioGroupItem value="no" id="gmail-no" />
                    <Label htmlFor="gmail-no">No</Label>
                  </div>
                </RadioGroup>
              </div>
            </div>

            <Button
              onClick={handleNotSureNext}
              disabled={hasPublicBookingLink === null || usesGmail === null}
              className="w-full"
            >
              Continue
              <ArrowRight className="h-4 w-4 ml-2" />
            </Button>

            {/* Recommendation preview */}
            {usesGmail === true && (
              <div className="p-3 rounded-lg bg-primary/10 border border-primary/20 text-sm">
                <p className="font-medium text-primary">Recommendation: Google Calendar</p>
                <p className="text-muted-foreground">
                  Since you use Gmail, Google Calendar is the easiest option!
                </p>
              </div>
            )}

            {usesGmail === false && hasPublicBookingLink === false && (
              <div className="p-3 rounded-lg bg-amber-500/10 border border-amber-500/20 text-sm">
                <p className="font-medium text-amber-600">Recommendation: Manual Busy Blocks</p>
                <p className="text-muted-foreground">
                  You can manage your availability directly in CloseLoop
                </p>
              </div>
            )}
          </div>
        );

      case 3:
        // Connect step (varies by provider)
        return (
          <div className="space-y-6">
            <Button variant="ghost" size="sm" onClick={() => setStep(1)} className="mb-2">
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back
            </Button>

            {/* Google / Microsoft OAuth */}
            {(selectedProvider === "google" || selectedProvider === "microsoft") && (
              <div className="text-center space-y-6">
                <div className="mx-auto w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center">
                  <Calendar className="h-8 w-8 text-primary" />
                </div>
                <div>
                  <h2 className="text-xl font-semibold mb-2">
                    Connect {selectedProvider === "google" ? "Google Calendar" : "Outlook"}
                  </h2>
                  <p className="text-muted-foreground">
                    This prevents the AI from booking over your real appointments
                  </p>
                </div>

                <Button
                  size="lg"
                  onClick={() => startOAuth(selectedProvider as "google" | "microsoft")}
                  disabled={isConnecting}
                  className="w-full max-w-xs"
                >
                  {isConnecting ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Connecting...
                    </>
                  ) : (
                    <>
                      Connect {selectedProvider === "google" ? "Google" : "Outlook"}
                      <ExternalLink className="h-4 w-4 ml-2" />
                    </>
                  )}
                </Button>

                <p className="text-xs text-muted-foreground">
                  You'll be redirected to sign in with {selectedProvider === "google" ? "Google" : "Microsoft"}
                </p>
              </div>
            )}

            {/* ICS URL */}
            {selectedProvider === "ics" && (
              <div className="space-y-4">
                <div className="text-center mb-4">
                  <h2 className="text-xl font-semibold mb-2">Add Calendar Link</h2>
                  <p className="text-muted-foreground">
                    Paste your calendar's sharing URL (ICS format)
                  </p>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="ics-url">Calendar URL</Label>
                  <Input
                    id="ics-url"
                    type="url"
                    placeholder="https://calendar.example.com/feed.ics"
                    value={icsUrl}
                    onChange={(e) => setIcsUrl(e.target.value)}
                  />
                  <p className="text-xs text-muted-foreground">
                    Find this in your calendar app's "Share" or "Export" settings
                  </p>
                </div>

                <Button
                  onClick={handleICSConnect}
                  disabled={!icsUrl || isConnecting}
                  className="w-full"
                >
                  {isConnecting ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Connecting...
                    </>
                  ) : (
                    "Connect Calendar"
                  )}
                </Button>
              </div>
            )}

            {/* API Key providers (Calendly, Square, Jobber) */}
            {(selectedProvider === "calendly" || selectedProvider === "square" || selectedProvider === "jobber") && (
              <div className="space-y-4">
                <div className="text-center mb-4">
                  <h2 className="text-xl font-semibold mb-2">
                    Connect {PROVIDER_OPTIONS.find(p => p.id === selectedProvider)?.name}
                  </h2>
                  <p className="text-muted-foreground">
                    {selectedProvider === "calendly"
                      ? "Paste your Personal Access Token — we'll verify it instantly"
                      : "Enter your API key to sync busy times"}
                  </p>
                </div>

                <div className="space-y-4">
                  <div className="space-y-2">
                    <Label htmlFor="api-key">
                      {selectedProvider === "calendly" ? "Personal Access Token" : "API Key"}
                    </Label>
                    <Input
                      id="api-key"
                      type="password"
                      placeholder={selectedProvider === "calendly" ? "eyJraWQiOi..." : "Enter your API key"}
                      value={apiKey}
                      onChange={(e) => setApiKey(e.target.value)}
                    />
                  </div>
                </div>

                <div className="p-3 rounded-lg bg-muted/50 text-sm space-y-1">
                  {selectedProvider === "calendly" && (
                    <>
                      <p className="font-medium">How to get your Personal Access Token:</p>
                      <ol className="text-muted-foreground list-decimal ml-4 space-y-0.5">
                        <li>Go to <span className="font-mono text-xs">calendly.com</span> and sign in</li>
                        <li>Click your avatar → <strong>Integrations</strong></li>
                        <li>Select <strong>API & Webhooks</strong></li>
                        <li>Click <strong>Generate New Token</strong> and copy it</li>
                      </ol>
                      <a
                        href="https://calendly.com/integrations/api_webhooks"
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center gap-1 text-primary text-xs mt-1 hover:underline"
                      >
                        Open Calendly API settings
                        <ExternalLink className="h-3 w-3" />
                      </a>
                    </>
                  )}
                  {selectedProvider === "square" && (
                    <p className="text-muted-foreground">
                      Square Dashboard → Apps → Production Credentials → Access Token
                    </p>
                  )}
                  {selectedProvider === "jobber" && (
                    <p className="text-muted-foreground">
                      Jobber → Settings → API → Generate new token
                    </p>
                  )}
                </div>

                <Button
                  onClick={handleApiKeyConnect}
                  disabled={!apiKey || isConnecting}
                  className="w-full"
                >
                  {isConnecting ? (
                    <>
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      Connecting...
                    </>
                  ) : (
                    "Connect"
                  )}
                </Button>
              </div>
            )}

            {/* Manual */}
            {selectedProvider === "manual" && (
              <div className="text-center space-y-4">
                <div className="mx-auto w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center">
                  <Clock className="h-8 w-8 text-primary" />
                </div>
                <h2 className="text-xl font-semibold">Manual Busy Blocks</h2>
                <p className="text-muted-foreground">
                  You can add busy times manually in CloseLoop whenever you need to block off time
                </p>
                <Button onClick={handleManualSetup} disabled={createConnection.isPending}>
                  {createConnection.isPending ? "Setting up..." : "Continue with Manual"}
                </Button>
              </div>
            )}
          </div>
        );

      case 4:
        // Success step
        return (
          <div className="text-center space-y-6">
            <div className="mx-auto w-20 h-20 rounded-full bg-primary/10 flex items-center justify-center">
              <CheckCircle2 className="h-10 w-10 text-primary" />
            </div>
            <div>
              <h2 className="text-xl font-semibold mb-2">Schedule Connected!</h2>
              <p className="text-muted-foreground">
                Your AI will now avoid double-booking appointments
              </p>
            </div>

            <div className="p-4 rounded-lg bg-muted/50 text-left space-y-2">
              <p className="font-medium flex items-center gap-2">
                <CalendarCheck className="h-4 w-4 text-primary" />
                What happens now:
              </p>
              <ul className="text-sm text-muted-foreground space-y-1 ml-6 list-disc">
                <li>Busy events sync to your CloseLoop schedule</li>
                <li>AI only offers slots that are actually free</li>
                <li>No more overlapping appointments</li>
              </ul>
            </div>

            <div className="flex flex-col sm:flex-row gap-3">
              <Button onClick={handleTestAvailability} variant="outline" className="flex-1">
                Test Availability
                <ExternalLink className="h-4 w-4 ml-2" />
              </Button>
              <Button onClick={handleComplete} className="flex-1">
                Done
                <ArrowRight className="h-4 w-4 ml-2" />
              </Button>
            </div>
          </div>
        );

      default:
        return null;
    }
  };

  // If already connected, show status
  if (hasConnectedCalendar && step === 1) {
    return (
      <div className={embedded ? "" : "max-w-lg mx-auto"}>
        <Card>
          <CardContent className="p-6 text-center space-y-4">
            <div className="mx-auto w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center">
              <CheckCircle2 className="h-8 w-8 text-primary" />
            </div>
            <div>
              <h3 className="font-semibold">Schedule Connected</h3>
              <p className="text-sm text-muted-foreground">
                Your calendar is syncing and the AI won't double-book
              </p>
            </div>
            <div className="flex gap-2 justify-center">
              <Button variant="outline" size="sm" onClick={handleTestAvailability}>
                Test Availability
              </Button>
              <Button variant="ghost" size="sm" onClick={() => setStep(1)}>
                Change Source
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (embedded) {
    return renderStep();
  }

  return (
    <div className="max-w-lg mx-auto">
      <Card>
        <CardContent className="p-6">
          {renderStep()}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useServices } from "@/hooks/useServices";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { 
  Brain, 
  DollarSign, 
  Clock, 
  Users, 
  ShieldCheck,
  TrendingUp,
  ChevronDown,
  Loader2,
  Save,
  Sparkles
} from "lucide-react";
import { toast } from "sonner";

interface PolicyConfig {
  enabled: boolean;
  guidance: string;
  thresholds?: Record<string, number | string>;
}

interface BusinessPolicies {
  upsell: PolicyConfig & {
    thresholds: {
      min_order_value: number;
      max_suggestions: number;
    };
  };
  pricing: PolicyConfig & {
    thresholds: {
      max_discount_percent: number;
      loyalty_threshold_orders: number;
    };
  };
  capacity: PolicyConfig & {
    thresholds: {
      busy_threshold_percent: number;
      advance_booking_hours: number;
    };
  };
  recognition: PolicyConfig;
  escalation: PolicyConfig;
}

const defaultPolicies: BusinessPolicies = {
  upsell: {
    enabled: true,
    guidance: "Suggest relevant add-ons only after the customer has confirmed their main order. Match suggestions to what they're already getting. Never push if they seem rushed or frustrated.",
    thresholds: {
      min_order_value: 0,
      max_suggestions: 2,
    },
  },
  pricing: {
    enabled: true,
    guidance: "Politely decline discount requests by emphasizing value and quality. For loyal repeat customers, you may offer a small courtesy discount. Never negotiate below cost.",
    thresholds: {
      max_discount_percent: 10,
      loyalty_threshold_orders: 5,
    },
  },
  capacity: {
    enabled: true,
    guidance: "When capacity is limited, suggest alternative times nearby. For peak hours, mention shorter wait times if they book slightly earlier or later. Don't oversell - protect service quality.",
    thresholds: {
      busy_threshold_percent: 80,
      advance_booking_hours: 2,
    },
  },
  recognition: {
    enabled: true,
    guidance: "Recognize repeat customers warmly. Reference their past orders when relevant. Thank loyal customers. For first-time callers, be welcoming and helpful without being overwhelming.",
  },
  escalation: {
    enabled: true,
    guidance: "Transfer to a human if the customer asks to speak to a manager, expresses serious frustration, has a complaint, or if the request is outside your knowledge. Never argue with upset customers.",
  },
};

export function AIBusinessPolicies() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const { services } = useServices();
  const queryClient = useQueryClient();
  const [expandedPolicy, setExpandedPolicy] = useState<string | null>("upsell");

  const { data: policies, isLoading } = useQuery({
    queryKey: ["ai-business-policies", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return defaultPolicies;
      
      const { data } = await supabase
        .from("tenants")
        .select("ai_policies_json")
        .eq("id", tenant.id)
        .single();
      
      if (data?.ai_policies_json && typeof data.ai_policies_json === 'object') {
        const stored = data.ai_policies_json as Record<string, unknown>;
        return { ...defaultPolicies, ...stored } as BusinessPolicies;
      }
      return defaultPolicies;
    },
    enabled: !!tenant?.id,
  });

  const [localPolicies, setLocalPolicies] = useState<BusinessPolicies | null>(null);
  const effectivePolicies = localPolicies ?? policies ?? defaultPolicies;

  const saveMutation = useMutation({
    mutationFn: async (newPolicies: BusinessPolicies) => {
      if (!tenant?.id) throw new Error("No tenant");
      
      const { error } = await supabase
        .from("tenants")
        .update({ ai_policies_json: newPolicies as any })
        .eq("id", tenant.id);
      
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["ai-business-policies"] });
      toast.success("AI policies saved");
      setLocalPolicies(null);
    },
    onError: (error: Error) => {
      toast.error("Failed to save", { description: error.message });
    },
  });

  const updatePolicy = <K extends keyof BusinessPolicies>(
    key: K,
    updates: Partial<BusinessPolicies[K]>
  ) => {
    setLocalPolicies(prev => {
      const current = prev ?? effectivePolicies;
      return {
        ...current,
        [key]: { ...current[key], ...updates },
      };
    });
  };

  const updateThreshold = <K extends keyof BusinessPolicies>(
    policyKey: K,
    thresholdKey: string,
    value: number | string
  ) => {
    setLocalPolicies(prev => {
      const current = prev ?? effectivePolicies;
      const policy = current[policyKey];
      return {
        ...current,
        [policyKey]: {
          ...policy,
          thresholds: {
            ...(policy.thresholds ?? {}),
            [thresholdKey]: value,
          },
        },
      };
    });
  };

  const hasChanges = localPolicies !== null;

  if (isLoading) {
    return (
      <Card>
        <CardContent className="pt-6">
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-8 w-8 animate-spin" />
          </div>
        </CardContent>
      </Card>
    );
  }

  const policyConfigs = [
    {
      key: "upsell" as const,
      icon: TrendingUp,
      title: "Should AI suggest add-ons?",
      description: "AI can recommend extras based on what they're ordering",
      color: "text-green-600",
      hasThresholds: true,
    },
    {
      key: "pricing" as const,
      icon: DollarSign,
      title: "Can AI offer discounts?",
      description: "How AI handles \"Can I get a deal?\" requests",
      color: "text-amber-600",
      hasThresholds: true,
    },
    {
      key: "capacity" as const,
      icon: Clock,
      title: "How should AI handle busy times?",
      description: "What AI does when you're getting booked up",
      color: "text-blue-600",
      hasThresholds: true,
    },
    {
      key: "recognition" as const,
      icon: Users,
      title: "Should AI remember callers?",
      description: "Recognize repeat customers and reference past orders",
      color: "text-purple-600",
      hasThresholds: false,
    },
    {
      key: "escalation" as const,
      icon: ShieldCheck,
      title: "When should AI hand off to a human?",
      description: "Triggers for transferring to a real person",
      color: "text-red-600",
      hasThresholds: false,
    },
  ];

  return (
    <div className="space-y-4">
      <Card className="border-primary/20 bg-primary/5">
        <CardContent className="pt-4">
          <div className="flex items-start gap-3">
            <Brain className="h-5 w-5 text-primary mt-0.5" />
            <div>
              <p className="font-medium text-sm">Smart AI Behavior</p>
              <p className="text-sm text-muted-foreground">
                These policies give your AI judgment about <em>when</em> and <em>how</em> to act—not rigid 
                if-then rules. The AI reads the conversation context and applies these thoughtfully.
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {policyConfigs.map(({ key, icon: Icon, title, description, color, hasThresholds }) => {
        const policy = effectivePolicies[key];
        const isExpanded = expandedPolicy === key;
        
        return (
          <Collapsible key={key} open={isExpanded} onOpenChange={() => setExpandedPolicy(isExpanded ? null : key)}>
            <Card>
              <CollapsibleTrigger asChild>
                <CardHeader className="cursor-pointer hover:bg-muted/50 transition-colors">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      <div className={`p-2 rounded-lg bg-background ${color}`}>
                        <Icon className="h-4 w-4" />
                      </div>
                      <div>
                        <CardTitle className="text-base flex items-center gap-2">
                          {title}
                          {policy.enabled ? (
                            <Badge variant="secondary" className="text-xs">Active</Badge>
                          ) : (
                            <Badge variant="outline" className="text-xs">Disabled</Badge>
                          )}
                        </CardTitle>
                        <CardDescription className="text-sm">{description}</CardDescription>
                      </div>
                    </div>
                    <ChevronDown className={`h-5 w-5 text-muted-foreground transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
                  </div>
                </CardHeader>
              </CollapsibleTrigger>
              
              <CollapsibleContent>
                <CardContent className="pt-0 space-y-4">
                  <div className="flex items-center justify-between">
                    <Label htmlFor={`${key}-enabled`} className="font-medium">
                      Enable this policy
                    </Label>
                    <Switch
                      id={`${key}-enabled`}
                      checked={policy.enabled}
                      onCheckedChange={(enabled) => updatePolicy(key, { enabled })}
                    />
                  </div>

                  <div className="space-y-2">
                    <Label className="text-sm font-medium flex items-center gap-2">
                      <Sparkles className="h-3.5 w-3.5" />
                      AI Guidance
                    </Label>
                    <Textarea
                      value={policy.guidance}
                      onChange={(e) => updatePolicy(key, { guidance: e.target.value })}
                      placeholder="Describe how the AI should handle this..."
                      className="min-h-[100px] text-sm"
                    />
                    <p className="text-xs text-muted-foreground">
                      Write in plain English. The AI will interpret this intelligently based on conversation context.
                    </p>
                  </div>

                  {hasThresholds && key === "upsell" && (
                    <div className="grid grid-cols-2 gap-4 pt-2">
                      <div className="space-y-2">
                        <Label className="text-sm">Only suggest if order is over</Label>
                        <div className="flex items-center gap-2">
                          <span className="text-muted-foreground">$</span>
                          <Input
                            type="number"
                            min={0}
                            value={(policy as BusinessPolicies["upsell"]).thresholds.min_order_value}
                            onChange={(e) => updateThreshold(key, "min_order_value", parseInt(e.target.value) || 0)}
                            className="w-24"
                          />
                        </div>
                        <p className="text-xs text-muted-foreground">Set to $0 to always suggest</p>
                      </div>
                      <div className="space-y-2">
                        <Label className="text-sm">Max add-on suggestions per call</Label>
                        <Input
                          type="number"
                          min={1}
                          max={5}
                          value={(policy as BusinessPolicies["upsell"]).thresholds.max_suggestions}
                          onChange={(e) => updateThreshold(key, "max_suggestions", parseInt(e.target.value) || 2)}
                          className="w-24"
                        />
                        <p className="text-xs text-muted-foreground">Don't overwhelm the caller</p>
                      </div>
                    </div>
                  )}

                  {hasThresholds && key === "pricing" && (
                    <div className="grid grid-cols-2 gap-4 pt-2">
                      <div className="space-y-2">
                        <Label className="text-sm">Biggest discount AI can offer</Label>
                        <div className="flex items-center gap-2">
                          <Input
                            type="number"
                            min={0}
                            max={50}
                            value={(policy as BusinessPolicies["pricing"]).thresholds.max_discount_percent}
                            onChange={(e) => updateThreshold(key, "max_discount_percent", parseInt(e.target.value) || 0)}
                            className="w-24"
                          />
                          <span className="text-muted-foreground">%</span>
                        </div>
                        <p className="text-xs text-muted-foreground">Set to 0 to disable discounts</p>
                      </div>
                      <div className="space-y-2">
                        <Label className="text-sm">Recognize repeat customers after</Label>
                        <div className="flex items-center gap-2">
                          <Input
                            type="number"
                            min={1}
                            value={(policy as BusinessPolicies["pricing"]).thresholds.loyalty_threshold_orders}
                            onChange={(e) => updateThreshold(key, "loyalty_threshold_orders", parseInt(e.target.value) || 5)}
                            className="w-24"
                          />
                          <span className="text-muted-foreground">orders</span>
                        </div>
                      </div>
                    </div>
                  )}

                  {hasThresholds && key === "capacity" && (
                    <div className="grid grid-cols-2 gap-4 pt-2">
                      <div className="space-y-2">
                        <Label className="text-sm">Consider "busy" when schedule is</Label>
                        <div className="flex items-center gap-2">
                          <Input
                            type="number"
                            min={50}
                            max={100}
                            value={(policy as BusinessPolicies["capacity"]).thresholds.busy_threshold_percent}
                            onChange={(e) => updateThreshold(key, "busy_threshold_percent", parseInt(e.target.value) || 80)}
                            className="w-24"
                          />
                          <span className="text-muted-foreground">% full</span>
                        </div>
                      </div>
                      <div className="space-y-2">
                        <Label className="text-sm">Suggest booking ahead when busy</Label>
                        <div className="flex items-center gap-2">
                          <Input
                            type="number"
                            min={1}
                            value={(policy as BusinessPolicies["capacity"]).thresholds.advance_booking_hours}
                            onChange={(e) => updateThreshold(key, "advance_booking_hours", parseInt(e.target.value) || 2)}
                            className="w-24"
                          />
                          <span className="text-muted-foreground">hours</span>
                        </div>
                        <p className="text-xs text-muted-foreground">AI suggests earlier/later times</p>
                      </div>
                    </div>
                  )}
                </CardContent>
              </CollapsibleContent>
            </Card>
          </Collapsible>
        );
      })}

      {hasChanges && (
        <div className="flex justify-end pt-2">
          <Button onClick={() => saveMutation.mutate(effectivePolicies)} disabled={saveMutation.isPending}>
            {saveMutation.isPending ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : <Save className="h-4 w-4 mr-2" />}
            Save Policies
          </Button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Loader2, Calendar, Truck, UtensilsCrossed, Stethoscope, Users, ClipboardList, Info } from "lucide-react";
import { useDeliveryRules, type EntityType, type DeliveryRule } from "@/hooks/useUniversalDelivery";
import { useTenantConfig, useModuleEnabled } from "@/hooks/useTenantConfig";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { ReviewRequestSettings } from "./ReviewRequestSettings";

interface EntityConfig {
  type: EntityType;
  label: string;
  icon: React.ReactNode;
  module: string | string[];
  description: string;
  defaultAutoConfirm: boolean;
}

const ENTITY_CONFIGS: EntityConfig[] = [
  {
    type: "booking",
    label: "Bookings / Appointments",
    icon: <Calendar className="h-5 w-5" />,
    module: "booking",
    description: "Service appointments scheduled by callers",
    defaultAutoConfirm: false,
  },
  {
    type: "dispatch",
    label: "Dispatch Jobs",
    icon: <Truck className="h-5 w-5" />,
    module: "dispatch_queue",
    description: "Urgent jobs requiring crew dispatch",
    defaultAutoConfirm: false,
  },
  {
    type: "order",
    label: "Food Orders",
    icon: <UtensilsCrossed className="h-5 w-5" />,
    module: "food_orders",
    description: "Pickup and delivery orders",
    defaultAutoConfirm: true,
  },
  {
    type: "reservation",
    label: "Reservations",
    icon: <Users className="h-5 w-5" />,
    module: "reservations",
    description: "Table reservations at restaurants",
    defaultAutoConfirm: false,
  },
  {
    type: "catering",
    label: "Catering Requests",
    icon: <ClipboardList className="h-5 w-5" />,
    module: "catering",
    description: "Large event catering inquiries",
    defaultAutoConfirm: false,
  },
  {
    type: "intake",
    label: "Medical Intake",
    icon: <Stethoscope className="h-5 w-5" />,
    module: "medical_intake",
    description: "Patient intake and scheduling requests",
    defaultAutoConfirm: false,
  },
];

interface RuleCardProps {
  config: EntityConfig;
  rule: DeliveryRule | undefined;
  onUpdate: (entityType: EntityType, updates: Partial<DeliveryRule>) => void;
  isUpdating: boolean;
}

function RuleCard({ config, rule, onUpdate, isUpdating }: RuleCardProps) {
  const [autoConfirm, setAutoConfirm] = useState(rule?.auto_confirm ?? config.defaultAutoConfirm);
  const [notifyOnNew, setNotifyOnNew] = useState(rule?.notify_on_new ?? true);

  useEffect(() => {
    if (rule) {
      setAutoConfirm(rule.auto_confirm);
      setNotifyOnNew(rule.notify_on_new);
    }
  }, [rule]);

  const handleAutoConfirmChange = (checked: boolean) => {
    setAutoConfirm(checked);
    onUpdate(config.type, {
      auto_confirm: checked,
      review_queue_enabled: !checked,
    });
  };

  const handleNotifyChange = (checked: boolean) => {
    setNotifyOnNew(checked);
    onUpdate(config.type, { notify_on_new: checked });
  };

  return (
    <Card>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="text-muted-foreground">{config.icon}</div>
            <div>
              <CardTitle className="text-base">{config.label}</CardTitle>
              <CardDescription className="text-xs">{config.description}</CardDescription>
            </div>
          </div>
          {isUpdating && <Loader2 className="h-4 w-4 animate-spin text-muted-foreground" />}
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex items-center justify-between py-2 border-b">
          <div className="flex items-center gap-2">
            <Label htmlFor={`auto-confirm-${config.type}`} className="font-medium">
              Auto-confirm
            </Label>
            <Tooltip>
              <TooltipTrigger asChild>
                <Info className="h-3 w-3 text-muted-foreground cursor-help" />
              </TooltipTrigger>
              <TooltipContent className="max-w-[250px]">
                <p>
                  {autoConfirm
                    ? "AI finalizes and sends immediately after caller confirmation."
                    : "Items land in Review Queue. You approve before sending."}
                </p>
              </TooltipContent>
            </Tooltip>
          </div>
          <div className="flex items-center gap-2">
            <Badge variant={autoConfirm ? "default" : "secondary"} className="text-xs">
              {autoConfirm ? "Instant" : "Review First"}
            </Badge>
            <Switch
              id={`auto-confirm-${config.type}`}
              checked={autoConfirm}
              onCheckedChange={handleAutoConfirmChange}
            />
          </div>
        </div>

        <div className="flex items-center justify-between py-2">
          <Label htmlFor={`notify-${config.type}`} className="font-medium">
            Notify on new
          </Label>
          <Switch
            id={`notify-${config.type}`}
            checked={notifyOnNew}
            onCheckedChange={handleNotifyChange}
          />
        </div>

        {/* Status explanation */}
        <div className="text-xs text-muted-foreground p-2 rounded bg-muted/50">
          {autoConfirm ? (
            <span>✓ The AI will finalize and send immediately after the caller confirms.</span>
          ) : (
            <span>✓ Items will appear in your Review Queue for approval before sending.</span>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

export function AutomationRulesSettings() {
  const { rules, isLoading, updateRule, getRuleForEntity, isUpdating } = useDeliveryRules();
  const { enabledModules } = useTenantConfig();

  const handleUpdate = (entityType: EntityType, updates: Partial<DeliveryRule>) => {
    updateRule.mutate({ entityType, updates });
  };

  // Filter entities by enabled modules
  const enabledEntities = ENTITY_CONFIGS.filter((config) => {
    if (Array.isArray(config.module)) {
      return config.module.some((m) => enabledModules.includes(m));
    }
    return enabledModules.includes(config.module);
  });

  if (isLoading) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  if (enabledEntities.length === 0) {
    return (
      <Card>
        <CardContent className="py-8 text-center text-muted-foreground">
          <p>No outcome types are enabled for your business mode.</p>
          <p className="text-sm mt-2">Enable modules in your business settings to configure automation rules.</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-start gap-2 p-4 rounded-lg bg-amber-50 dark:bg-amber-950/30 text-sm text-amber-700 dark:text-amber-300">
        <Info className="h-4 w-4 mt-0.5 flex-shrink-0" />
        <div>
          <p className="font-medium">How automation works</p>
          <ul className="mt-1 space-y-1 text-xs">
            <li>• <strong>Auto-confirm ON:</strong> AI finalizes immediately after caller confirmation</li>
            <li>• <strong>Auto-confirm OFF:</strong> Items land in Review Queue for your approval</li>
          </ul>
        </div>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        {enabledEntities.map((config) => (
          <RuleCard
            key={config.type}
            config={config}
            rule={getRuleForEntity(config.type)}
            onUpdate={handleUpdate}
            isUpdating={isUpdating}
          />
        ))}
      </div>

      {/* Review Request Settings */}
      <div className="pt-6 border-t">
        <h3 className="text-lg font-medium mb-4">Post-Service Automations</h3>
        <ReviewRequestSettings />
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { Badge } from "@/components/ui/badge";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { Clock, Info, TrendingUp } from "lucide-react";

export interface BusynessLevelConfig {
  etaMultiplier: number;   // 1.0 = normal, 1.5 = 50% longer
  surchargePercent: number; // 0-100
}

export interface BusynessRulesConfig {
  base_prep_minutes: number;
  busy_buffer_minutes: number;
  manual_busyness_pct: number; // 0-100
  // Level-based config consumed by computeEtaQuote() pricing engine
  low?: BusynessLevelConfig;
  medium?: BusynessLevelConfig;
  high?: BusynessLevelConfig;
}

export function BusynessRulesEditor() {
  const { tenant } = useAuth();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);

  const [config, setConfig] = useState<BusynessRulesConfig>({
    base_prep_minutes: 30,
    busy_buffer_minutes: 15,
    manual_busyness_pct: 0,
    low: { etaMultiplier: 1.0, surchargePercent: 0 },
    medium: { etaMultiplier: 1.3, surchargePercent: 0 },
    high: { etaMultiplier: 1.6, surchargePercent: 0 },
  });

  useEffect(() => {
    if (!tenant?.id) return;

    const loadData = async () => {
      setLoading(true);
      try {
        const { data, error } = await supabase
          .from("tenants")
          .select("busyness_rules_jsonb" as any)
          .eq("id", tenant.id)
          .single();

        if (error) throw error;

        const dataAny = data as any;
        if (dataAny?.busyness_rules_jsonb) {
          setConfig(dataAny.busyness_rules_jsonb as BusynessRulesConfig);
        }
      } catch (error) {
        console.error("Failed to load busyness rules:", error);
        toast.error("Failed to load busyness rules");
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, [tenant?.id]);

  const updateConfig = (updates: Partial<BusynessRulesConfig>) => {
    setConfig({ ...config, ...updates });
    setHasChanges(true);
  };

  const saveRules = async () => {
    if (!tenant?.id) return;

    setSaving(true);
    try {
      const { error } = await supabase
        .from("tenants")
        .update({ busyness_rules_jsonb: config } as any)
        .eq("id", tenant.id);

      if (error) throw error;

      toast.success("Busyness rules saved successfully");
      setHasChanges(false);
    } catch (error) {
      console.error("Failed to save busyness rules:", error);
      toast.error("Failed to save busyness rules");
    } finally {
      setSaving(false);
    }
  };

  const calculateETA = () => {
    const baseTime = config.base_prep_minutes;
    const busyBuffer = (config.manual_busyness_pct / 100) * config.busy_buffer_minutes;
    return Math.round(baseTime + busyBuffer);
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <div className="animate-spin rounded-full h-6 w-6 border-2 border-primary border-t-transparent" />
            <span className="ml-3 text-sm text-muted-foreground">Loading busyness rules...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold">Busy Day Settings</h3>
          <p className="text-sm text-muted-foreground">
            Tell the AI how long things take based on how busy you are
          </p>
        </div>
        {hasChanges && (
          <Button onClick={saveRules} disabled={saving}>
            {saving ? "Saving..." : "Save Changes"}
          </Button>
        )}
      </div>

      {/* Info Banner - Simplified language */}
      <div className="flex items-start gap-3 p-3 rounded-lg bg-primary/5 border border-primary/20">
        <Info className="h-5 w-5 text-primary shrink-0 mt-0.5" />
        <div className="flex-1 text-sm">
          <p className="font-medium text-primary mb-1">How wait times work</p>
          <p className="text-muted-foreground">
            When you're not busy, the AI uses your base time. As you get busier, it adds extra time 
            so customers get realistic expectations.
          </p>
        </div>
      </div>

      {/* Configuration */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Clock className="h-4 w-4" />
            Time Settings
          </CardTitle>
          <CardDescription>
            Set how long things take when you're free vs. slammed
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Base Prep Time */}
          <div className="grid gap-3">
            <div className="flex items-center justify-between">
              <Label htmlFor="base-prep">When not busy, how long do things take?</Label>
              <span className="text-sm font-medium">{config.base_prep_minutes} min</span>
            </div>
            <Input
              id="base-prep"
              type="number"
              min="0"
              step="5"
              value={config.base_prep_minutes}
              onChange={(e) => updateConfig({ base_prep_minutes: parseInt(e.target.value) || 0 })}
            />
            <p className="text-xs text-muted-foreground">
              Your typical turnaround time on a slow day
            </p>
          </div>

          {/* Busy Buffer */}
          <div className="grid gap-3">
            <div className="flex items-center justify-between">
              <Label htmlFor="busy-buffer">Extra time when you're slammed?</Label>
              <span className="text-sm font-medium">+{config.busy_buffer_minutes} min</span>
            </div>
            <Input
              id="busy-buffer"
              type="number"
              min="0"
              step="5"
              value={config.busy_buffer_minutes}
              onChange={(e) => updateConfig({ busy_buffer_minutes: parseInt(e.target.value) || 0 })}
            />
            <p className="text-xs text-muted-foreground">
              How much longer things take when you're at 100% capacity
            </p>
          </div>
        </CardContent>
      </Card>

      {/* Manual Busyness */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <TrendingUp className="h-4 w-4" />
            How Busy Are You Right Now?
          </CardTitle>
          <CardDescription>
            Adjust this as your day changes — the AI will update wait times automatically
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="grid gap-4">
            <div className="flex items-center justify-between">
              <Label>Slide to match your current workload</Label>
              <div className="flex items-center gap-2">
                <span className="text-2xl font-bold">{config.manual_busyness_pct}%</span>
                {config.manual_busyness_pct === 0 && <Badge variant="outline" className="text-green-500 border-green-500/30">Wide Open</Badge>}
                {config.manual_busyness_pct > 0 && config.manual_busyness_pct < 50 && <Badge variant="outline" className="text-blue-500 border-blue-500/30">Light Day</Badge>}
                {config.manual_busyness_pct >= 50 && config.manual_busyness_pct < 80 && <Badge variant="outline" className="text-amber-500 border-amber-500/30">Pretty Busy</Badge>}
                {config.manual_busyness_pct >= 80 && <Badge variant="outline" className="text-rose-500 border-rose-500/30">Slammed!</Badge>}
              </div>
            </div>

            <Slider
              value={[config.manual_busyness_pct]}
              onValueChange={([value]) => updateConfig({ manual_busyness_pct: value })}
              min={0}
              max={100}
              step={5}
              className="w-full"
            />

            <div className="flex justify-between text-xs text-muted-foreground">
              <span>Wide open</span>
              <span>Moderate</span>
              <span>Slammed</span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Level-Based ETA Multipliers */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <TrendingUp className="h-4 w-4" />
            ETA Multipliers by Busyness Level
          </CardTitle>
          <CardDescription>
            How much to adjust ETAs and prices at each busyness level. The AI pricing engine uses these automatically.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {(["low", "medium", "high"] as const).map((level) => {
            const levelConfig = config[level] || { etaMultiplier: 1.0, surchargePercent: 0 };
            const labels = { low: "Low", medium: "Medium", high: "High" };
            const colors = { low: "text-green-500", medium: "text-amber-500", high: "text-rose-500" };
            return (
              <div key={level} className="grid grid-cols-3 gap-4 items-center border rounded-lg p-3">
                <div>
                  <Badge variant="outline" className={colors[level]}>
                    {labels[level]}
                  </Badge>
                </div>
                <div className="space-y-1">
                  <Label className="text-xs text-muted-foreground">ETA Multiplier</Label>
                  <Input
                    type="number"
                    min="1"
                    max="3"
                    step="0.1"
                    value={levelConfig.etaMultiplier}
                    onChange={(e) => updateConfig({
                      [level]: { ...levelConfig, etaMultiplier: parseFloat(e.target.value) || 1.0 },
                    })}
                  />
                </div>
                <div className="space-y-1">
                  <Label className="text-xs text-muted-foreground">Surcharge %</Label>
                  <Input
                    type="number"
                    min="0"
                    max="100"
                    step="5"
                    value={levelConfig.surchargePercent}
                    onChange={(e) => updateConfig({
                      [level]: { ...levelConfig, surchargePercent: parseInt(e.target.value) || 0 },
                    })}
                  />
                </div>
              </div>
            );
          })}
          <p className="text-xs text-muted-foreground">
            Example: At "High" busyness with 1.6x multiplier, a 30-min ETA becomes ~48 min.
          </p>
        </CardContent>
      </Card>

      {/* ETA Preview */}
      <Card className="border-emerald-500/30 bg-emerald-500/5">
        <CardHeader>
          <CardTitle className="text-base">Current ETA Estimate</CardTitle>
          <CardDescription>
            What customers will hear based on current settings
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-4">
            <div className="flex-1">
              <div className="text-3xl font-bold text-emerald-400">{calculateETA()} minutes</div>
              <p className="text-sm text-muted-foreground mt-1">
                {config.base_prep_minutes} min base
                {config.manual_busyness_pct > 0 && ` + ${Math.round((config.manual_busyness_pct / 100) * config.busy_buffer_minutes)} min busy buffer`}
              </p>
            </div>
            <div className="text-sm bg-muted/30 p-3 rounded-lg">
              <p className="text-muted-foreground mb-1">AI will say:</p>
              <p className="font-medium">
                {calculateETA() <= 30 && '"We can be there in about 30 minutes"'}
                {calculateETA() > 30 && calculateETA() <= 60 && '"We can be there in about 45 minutes to an hour"'}
                {calculateETA() > 60 && '"We can be there within the hour"'}
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Usage Examples */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">How to Use</CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          <div className="grid gap-2 text-sm">
            <div className="flex items-start gap-2">
              <div className="h-5 w-5 rounded-full bg-primary/20 flex items-center justify-center shrink-0 mt-0.5">
                <span className="text-xs font-bold">1</span>
              </div>
              <div>
                <p className="font-medium">Set your base prep time</p>
                <p className="text-muted-foreground text-xs">
                  This is how long you need when you have zero appointments/orders
                </p>
              </div>
            </div>

            <div className="flex items-start gap-2">
              <div className="h-5 w-5 rounded-full bg-primary/20 flex items-center justify-center shrink-0 mt-0.5">
                <span className="text-xs font-bold">2</span>
              </div>
              <div>
                <p className="font-medium">Set your busy day buffer</p>
                <p className="text-muted-foreground text-xs">
                  How much longer things take when you're slammed
                </p>
              </div>
            </div>

            <div className="flex items-start gap-2">
              <div className="h-5 w-5 rounded-full bg-primary/20 flex items-center justify-center shrink-0 mt-0.5">
                <span className="text-xs font-bold">3</span>
              </div>
              <div>
                <p className="font-medium">Adjust busyness as your day changes</p>
                <p className="text-muted-foreground text-xs">
                  Slow morning? 0-20%. Lunch rush? 70-90%. Dead afternoon? Back to 0%.
                </p>
              </div>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  useCalendarConnections,
  useCalendarSync,
  CALENDAR_PROVIDERS,
  useAvailableSlots,
  type CalendarConnection,
  type BookingBehavior,
} from "@/hooks/useCalendarConnections";
import { useTenantSettings, useAssistantSettings } from "@/hooks/useSettings";
import { supabase } from "@/integrations/supabase/client";
import BusinessHoursEditor, { type BusinessHours } from "@/components/onboarding/BusinessHoursEditor";
import { 
  CheckCircle2, 
  Loader2, 
  Calendar, 
  ArrowRight,
  ArrowLeft,
  ExternalLink,
  RefreshCw,
  AlertCircle,
  Clock,
  CalendarCheck,
  Send,
  Sparkles,
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { format, addDays } from "date-fns";

interface CalendarConnectionWizardProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
}

import { DEFAULT_BUSINESS_HOURS } from "@/lib/hoursUtils";

const DEFAULT_HOURS = DEFAULT_BUSINESS_HOURS;

interface AvailableCalendar {
  id: string;
  name: string;
  primary?: boolean;
}

// Step definitions for wizard
const WIZARD_STEPS_FULL = [
  { id: 1, label: "Provider" },
  { id: 2, label: "Connect" },
  { id: 3, label: "Hours" },
  { id: 4, label: "Rules" },
  { id: 5, label: "Behavior" },
  { id: 6, label: "Test" },
];

const WIZARD_STEPS_INTERNAL = [
  { id: 1, label: "Provider" },
  { id: 3, label: "Hours" },
  { id: 4, label: "Rules" },
  { id: 5, label: "Behavior" },
];

export function CalendarConnectionWizard({ open, onOpenChange }: CalendarConnectionWizardProps) {
  const { createConnection, connections, refetch } = useCalendarConnections();
  const { sync: syncCalendar } = useCalendarSync();
  const { tenant, updateTenant, isUpdating } = useTenantSettings();
  const { settings: assistantSettings, updateSettings: updateAssistantSettings } = useAssistantSettings();
  const { toast } = useToast();
  
  const [step, setStep] = useState(1);
  const [selectedProvider, setSelectedProvider] = useState<CalendarConnection["provider"] | "internal" | null>(null);
  const [icsUrl, setIcsUrl] = useState("");
  const [businessHours, setBusinessHours] = useState<BusinessHours>(
    (tenant?.hours_json as unknown as BusinessHours) || DEFAULT_HOURS
  );
  const [minLeadHours, setMinLeadHours] = useState(tenant?.min_lead_hours || 2);
  const [maxAdvanceDays, setMaxAdvanceDays] = useState(tenant?.max_advance_days || 30);
  const [bufferMinutes, setBufferMinutes] = useState(tenant?.appointment_buffer_minutes || 15);
  
  // Booking behavior state
  const [bookingBehavior, setBookingBehavior] = useState<BookingBehavior>(
    (assistantSettings as Record<string, unknown>)?.ai_booking_mode === "auto_book" ? "auto_book" : "pending_approval"
  );
  
  // OAuth states
  const [isConnecting, setIsConnecting] = useState(false);
  const [isRefreshingCalendars, setIsRefreshingCalendars] = useState(false);
  const [availableCalendars, setAvailableCalendars] = useState<AvailableCalendar[]>([]);
  const [selectedCalendarIds, setSelectedCalendarIds] = useState<string[]>([]);
  const [currentConnectionId, setCurrentConnectionId] = useState<string | null>(null);
  const [syncStatus, setSyncStatus] = useState<"idle" | "syncing" | "success" | "error">("idle");
  const [syncedEventsCount, setSyncedEventsCount] = useState(0);

  // Test booking state
  const [testSlots, setTestSlots] = useState<{ slot_start: string; slot_end: string }[]>([]);
  const [isLoadingSlots, setIsLoadingSlots] = useState(false);
  const [testBookingSlot, setTestBookingSlot] = useState<string | null>(null);
  const [isTestingBooking, setIsTestingBooking] = useState(false);
  const [testBookingResult, setTestBookingResult] = useState<"success" | "error" | null>(null);

  // Helper to process a newly detected connection
  const processNewConnection = (data: { config_json?: unknown }) => {
    const cals = (data.config_json as { available_calendars?: AvailableCalendar[] })?.available_calendars || [];
    setAvailableCalendars(cals);
    const primaryIds = cals.filter((c) => c.primary).map((c) => c.id);
    setSelectedCalendarIds(primaryIds.length > 0 ? primaryIds : cals.slice(0, 1).map((c) => c.id));
    setIsConnecting(false);
    setStep(2);
  };

  // Listen for OAuth callback messages (primary detection)
  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      if (event.data?.type === "calendar-oauth-success") {
        setIsConnecting(false);
        setAvailableCalendars(event.data.calendars || []);
        const primaryIds = (event.data.calendars || [])
          .filter((c: AvailableCalendar) => c.primary)
          .map((c: AvailableCalendar) => c.id);
        setSelectedCalendarIds(primaryIds.length > 0 ? primaryIds : event.data.calendars?.slice(0, 1).map((c: AvailableCalendar) => c.id) || []);
        refetch();
        setStep(2);
      } else if (event.data?.type === "calendar-oauth-error") {
        setIsConnecting(false);
        toast({
          title: "Connection failed",
          description: event.data.error || "Could not connect to calendar",
          variant: "destructive",
        });
      }
    };

    window.addEventListener("message", handleMessage);
    return () => window.removeEventListener("message", handleMessage);
  }, [refetch, toast]);

  // Focus-based fallback: detect connection when user returns to window
  useEffect(() => {
    if (!isConnecting || !selectedProvider) return;

    const handleFocus = async () => {
      const { data } = await refetch();
      const newConn = data?.find(
        (c) => c.provider === selectedProvider && c.status === "connected"
      );
      if (newConn) {
        processNewConnection(newConn);
        refetch();
      }
    };

    window.addEventListener("focus", handleFocus);
    return () => window.removeEventListener("focus", handleFocus);
  }, [isConnecting, selectedProvider, refetch]);

  // Polling fallback: check every 2s while connecting
  useEffect(() => {
    if (!isConnecting || !selectedProvider) return;

    const pollInterval = setInterval(async () => {
      const { data } = await supabase
        .from("calendar_connections")
        .select("*")
        .eq("provider", selectedProvider)
        .eq("status", "connected")
        .maybeSingle();

      if (data) {
        clearInterval(pollInterval);
        processNewConnection(data);
        refetch();
      }
    }, 2000);

    // Timeout after 2 minutes
    const timeout = setTimeout(() => {
      clearInterval(pollInterval);
      if (isConnecting) {
        setIsConnecting(false);
        toast({ title: "Connection timed out", variant: "destructive" });
      }
    }, 120000);

    return () => {
      clearInterval(pollInterval);
      clearTimeout(timeout);
    };
  }, [isConnecting, selectedProvider, toast, refetch]);

  // Get current connected calendar
  useEffect(() => {
    const connectedCal = connections.find(c => c.status === "connected" && (c.provider === "google" || c.provider === "microsoft"));
    if (connectedCal) {
      setCurrentConnectionId(connectedCal.id);
      const configJson = connectedCal.config_json as Record<string, unknown> | null;
      const calendars = (configJson?.available_calendars as AvailableCalendar[]) || [];
      setAvailableCalendars(calendars);
      setSelectedCalendarIds((configJson?.selected_calendar_ids as string[]) || []);
    }
  }, [connections]);

  // API key input for Calendly
  const [calendlyApiKey, setCalendlyApiKey] = useState("");
  const [isVerifyingCalendly, setIsVerifyingCalendly] = useState(false);

  // Track which providers have OAuth configured
  const [providerStatus, setProviderStatus] = useState<Record<string, "available" | "not_configured" | "coming_soon" | "unknown">>({
    google: "unknown",
    microsoft: "unknown",
    square: "coming_soon",
    calendly: "available",
    jobber: "coming_soon",
    ics: "available",
    manual: "available",
  });
  const [showSetupHelp, setShowSetupHelp] = useState(false);
  const [setupHelpProvider, setSetupHelpProvider] = useState<string | null>(null);

  const startOAuth = async (provider: "google" | "microsoft") => {
    setIsConnecting(true);
    setSelectedProvider(provider);
    
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (!session) {
        toast({ title: "Please log in first", variant: "destructive" });
        setIsConnecting(false);
        return;
      }

      const response = await supabase.functions.invoke("calendar-oauth-start", {
        body: { provider, tenant_id: tenant?.id },
      });

      if (response.error) {
        throw new Error(response.error.message);
      }

      // Check if the response indicates OAuth is not configured
      if (response.data?.error) {
        const errorMsg = response.data.error as string;
        if (errorMsg.includes("not configured")) {
          setProviderStatus(prev => ({ ...prev, [provider]: "not_configured" }));
          setSetupHelpProvider(provider);
          setShowSetupHelp(true);
          setIsConnecting(false);
          return;
        }
        throw new Error(errorMsg);
      }

      const { auth_url } = response.data;
      if (!auth_url) {
        throw new Error("No auth URL returned");
      }

      // Mark as available since we got a valid URL
      setProviderStatus(prev => ({ ...prev, [provider]: "available" }));

      // Open popup for OAuth
      const popup = window.open(
        auth_url,
        "calendar-oauth",
        "width=600,height=700,left=100,top=100"
      );

      if (!popup) {
        toast({
          title: "Popup blocked",
          description: "Please allow popups for this site and try again",
          variant: "destructive",
        });
        setIsConnecting(false);
      }
    } catch (error: unknown) {
      console.error("OAuth start error:", error);
      const message = error instanceof Error ? error.message : "Failed to start connection";
      
      // Check if this is a "not configured" error
      if (message.includes("not configured") || message.includes("500")) {
        setProviderStatus(prev => ({ ...prev, [provider]: "not_configured" }));
        setSetupHelpProvider(provider);
        setShowSetupHelp(true);
        setIsConnecting(false);
        return;
      }
      
      toast({
        title: "Connection failed",
        description: message,
        variant: "destructive",
      });
      setIsConnecting(false);
    }
  };

  const handleSelectCalendars = async () => {
    const connection = connections.find(c => c.provider === selectedProvider && c.status === "connected");
    if (!connection) {
      toast({ title: "No connection found", variant: "destructive" });
      return;
    }

    try {
      await supabase
        .from("calendar_connections")
        .update({
          config_json: {
            ...(connection.config_json as object),
            selected_calendar_ids: selectedCalendarIds,
          },
        })
        .eq("id", connection.id);

      setCurrentConnectionId(connection.id);
      refetch();
      setStep(3);
    } catch (error) {
      toast({ title: "Failed to save calendar selection", variant: "destructive" });
    }
  };

  const handleTestSync = async () => {
    if (!currentConnectionId) {
      toast({ title: "No calendar connected", variant: "destructive" });
      return;
    }

    setSyncStatus("syncing");
    try {
      const result = await syncCalendar(currentConnectionId);
      setSyncedEventsCount(result.syncedCount);
      setSyncStatus("success");

      // After sync, load available slots
      await loadTestSlots();
    } catch {
      setSyncStatus("error");
    }
  };

  const loadTestSlots = async () => {
    setIsLoadingSlots(true);
    try {
      const startDate = new Date();
      const endDate = addDays(startDate, 7);
      
      const { data, error } = await supabase.rpc("fn_compute_available_slots", {
        _tenant_id: tenant?.id,
        _start_date: format(startDate, "yyyy-MM-dd"),
        _end_date: format(endDate, "yyyy-MM-dd"),
        _duration_minutes: 60,
        _buffer_minutes: bufferMinutes || 0,
        _business_hours: (businessHours as unknown as Record<string, never>) || null,
      });

      if (error) throw error;
      
      // Take first 5 slots
      setTestSlots((data || []).slice(0, 5));
    } catch (error) {
      console.error("Failed to load slots:", error);
    } finally {
      setIsLoadingSlots(false);
    }
  };

  const handleTestBooking = async (slotStart: string) => {
    setTestBookingSlot(slotStart);
    setIsTestingBooking(true);
    setTestBookingResult(null);
    
    try {
      // Just verify the slot is still available
      const startDate = new Date(slotStart);
      const endDate = addDays(startDate, 1);
      
      const { data, error } = await supabase.rpc("fn_compute_available_slots", {
        _tenant_id: tenant?.id,
        _start_date: format(startDate, "yyyy-MM-dd"),
        _end_date: format(endDate, "yyyy-MM-dd"),
        _duration_minutes: 60,
        _buffer_minutes: bufferMinutes || 0,
        _business_hours: (businessHours as unknown as Record<string, never>) || null,
      });

      if (error) throw error;
      
      const isAvailable = (data || []).some(
        (s: { slot_start: string }) => s.slot_start === slotStart
      );

      if (isAvailable) {
        setTestBookingResult("success");
        toast({ title: "Slot is available!", description: "AI would book this time successfully." });
      } else {
        setTestBookingResult("error");
        toast({ title: "Slot conflict detected", description: "This time is no longer available.", variant: "destructive" });
      }
    } catch (error) {
      console.error("Test booking error:", error);
      setTestBookingResult("error");
    } finally {
      setIsTestingBooking(false);
    }
  };

  const handleRefreshCalendars = async () => {
    const connection = connections.find(c => 
      (c.provider === "google" || c.provider === "microsoft") && c.status === "connected"
    );
    if (!connection) {
      toast({ title: "No calendar connected", variant: "destructive" });
      return;
    }

    setIsRefreshingCalendars(true);
    try {
      const response = await supabase.functions.invoke("refresh-calendar-list", {
        body: { connection_id: connection.id, tenant_id: tenant?.id },
      });

      if (response.error) {
        throw new Error(response.error.message);
      }

      if (response.data?.error) {
        throw new Error(response.data.error);
      }

      const freshCalendars = response.data?.calendars || [];
      setAvailableCalendars(freshCalendars);
      
      // Keep existing selections that still exist
      const validSelections = selectedCalendarIds.filter(id => 
        freshCalendars.some((c: AvailableCalendar) => c.id === id)
      );
      // If no selections remain, select the primary
      if (validSelections.length === 0) {
        const primaryIds = freshCalendars.filter((c: AvailableCalendar) => c.primary).map((c: AvailableCalendar) => c.id);
        setSelectedCalendarIds(primaryIds.length > 0 ? primaryIds : freshCalendars.slice(0, 1).map((c: AvailableCalendar) => c.id));
      } else {
        setSelectedCalendarIds(validSelections);
      }

      await refetch();
      toast({ title: "Calendars refreshed", description: `Found ${freshCalendars.length} calendar(s)` });
    } catch (error: unknown) {
      console.error("Refresh calendars error:", error);
      const message = error instanceof Error ? error.message : "Failed to refresh";
      toast({ title: "Refresh failed", description: message, variant: "destructive" });
    } finally {
      setIsRefreshingCalendars(false);
    }
  };

  const handleNext = async () => {
    if (step === 1 && selectedProvider) {
      if (selectedProvider === "google" || selectedProvider === "microsoft") {
        // Start OAuth flow
        startOAuth(selectedProvider);
        return;
      } else if (selectedProvider === "calendly") {
        setStep(2); // Go to Calendly API key input
      } else if (selectedProvider === "ics") {
        setStep(2); // Go to ICS URL input
      } else if (selectedProvider === "manual" || selectedProvider === "internal") {
        // Internal-only or manual: skip connect + test, go straight to hours
        if (selectedProvider === "internal") {
          // No calendar_connection needed for internal-only
          setStep(3);
        } else {
          await createConnection.mutateAsync({
            provider: "manual",
            auth_type: "manual",
          });
          setStep(3);
        }
      }
    } else if (step === 2) {
      if (selectedProvider === "calendly") {
        // Verify & save Calendly Personal Access Token
        if (!calendlyApiKey.trim()) {
          toast({ title: "Please enter your Personal Access Token", variant: "destructive" });
          return;
        }
        setIsVerifyingCalendly(true);
        try {
          const { data: vData, error: vError } = await supabase.functions.invoke("calendly-proxy", {
            body: { action: "verify_token", api_key: calendlyApiKey, tenant_id: tenant?.id },
          });
          if (vError || !vData?.valid) {
            toast({ title: "Invalid token", description: "Please double-check your Calendly Personal Access Token.", variant: "destructive" });
            setIsVerifyingCalendly(false);
            return;
          }
          toast({ title: `✓ Calendly verified`, description: `Connected as ${vData.user?.name || vData.user?.email}` });
          await createConnection.mutateAsync({
            provider: "calendly" as any,
            auth_type: "api_key",
            config_json: {
              api_key: calendlyApiKey,
              scheduling_url: vData.user?.scheduling_url,
              calendly_user_uri: vData.user?.uri,
              calendly_user_name: vData.user?.name,
              calendly_user_email: vData.user?.email,
            },
          });
          setStep(3);
        } catch (err) {
          console.error("Calendly verify error:", err);
          toast({ title: "Connection failed", variant: "destructive" });
        } finally {
          setIsVerifyingCalendly(false);
        }
      } else if (selectedProvider === "ics") {
        // Save ICS connection
        await createConnection.mutateAsync({
          provider: "ics",
          auth_type: "ics_url",
          config_json: { ics_url: icsUrl },
        });
        setStep(3);
      } else {
        // OAuth - save calendar selection
        await handleSelectCalendars();
      }
    } else if (step === 3) {
      setStep(4); // Go to booking rules
    } else if (step === 4) {
      // Save tenant settings then go to behavior
      await updateTenant.mutateAsync({
        hours_json: businessHours as Record<string, never>,
        min_lead_hours: minLeadHours,
        max_advance_days: maxAdvanceDays,
        appointment_buffer_minutes: bufferMinutes,
      });
      setStep(5); // Go to booking behavior
    } else if (step === 5) {
      // Save booking behavior
      await updateAssistantSettings.mutateAsync({
        ai_booking_mode: bookingBehavior,
      });
      // Internal-only: skip test sync, go straight to success
      if (selectedProvider === "internal" || selectedProvider === "manual") {
        setStep(7); // Success
      } else {
        setStep(6); // Go to test
      }
    } else if (step === 6) {
      setStep(7); // Success
    }
  };

  const handleBack = () => {
    if (step === 2) {
      setStep(1);
    } else if (step === 3) {
      if (selectedProvider === "ics" || selectedProvider === "google" || selectedProvider === "microsoft") {
        setStep(2);
      } else {
        setStep(1);
      }
    } else if (step === 4) {
      setStep(3);
    } else if (step === 5) {
      setStep(4);
    } else if (step === 6) {
      setStep(5);
    }
  };

  const handleClose = () => {
    setStep(1);
    setSelectedProvider(null);
    setIcsUrl("");
    setSyncStatus("idle");
    setAvailableCalendars([]);
    setSelectedCalendarIds([]);
    setTestSlots([]);
    setTestBookingResult(null);
    onOpenChange(false);
  };

  const canProceed = () => {
    if (step === 1) return !!selectedProvider;
    if (step === 2) {
      if (selectedProvider === "ics") return icsUrl.trim().length > 0;
      if (selectedProvider === "calendly") return calendlyApiKey.trim().length > 0;
      return selectedCalendarIds.length > 0;
    }
    if (step === 3) return true;
    if (step === 4) return true;
    if (step === 5) return true;
    if (step === 6) {
      // Internal/manual providers skip test sync
      if (selectedProvider === "internal" || selectedProvider === "manual") return true;
      return syncStatus === "success";
    }
    return true;
  };

  const toggleCalendar = (id: string) => {
    setSelectedCalendarIds(prev =>
      prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
    );
  };

  const getStepTitle = () => {
    switch (step) {
      case 1: return "Choose where your schedule lives";
      case 2:
        if (selectedProvider === "ics") return "Enter your calendar feed URL";
        if (selectedProvider === "calendly") return "Connect your Calendly account";
        return "Select which calendars to sync";
      case 3: return "Set your business hours";
      case 4: return "Configure booking rules";
      case 5: return "Choose booking behavior";
      case 6: return "Test your setup";
      default: return "";
    }
  };

  return (
    <Dialog open={open} onOpenChange={handleClose}>
      <DialogContent className="sm:max-w-[600px] max-h-[85vh] overflow-y-auto">
        {step <= 6 && (
          <DialogHeader>
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-full bg-primary/10">
                <Calendar className="h-5 w-5 text-primary" />
              </div>
              <div>
                <DialogTitle>Connect Your Schedule</DialogTitle>
                <DialogDescription>{getStepTitle()}</DialogDescription>
              </div>
            </div>
            
            {/* Progress indicator */}
            <div className="flex gap-1 mt-4">
              {(selectedProvider === "internal" || selectedProvider === "manual" ? WIZARD_STEPS_INTERNAL : WIZARD_STEPS_FULL).map((s) => (
                <div key={s.id} className="flex-1 space-y-1">
                  <div
                    className={`h-1 rounded-full transition-colors ${
                      s.id <= step ? "bg-primary" : "bg-muted"
                    }`}
                  />
                  <p className={`text-[10px] text-center ${s.id === step ? "text-primary font-medium" : "text-muted-foreground"}`}>
                    {s.label}
                  </p>
                </div>
              ))}
            </div>
          </DialogHeader>
        )}

        {/* Step 1: Choose Provider */}
        {step === 1 && (
          <div className="py-4 space-y-4">
            {/* Prioritize ICS - works without OAuth setup */}
            <div className="p-3 rounded-lg bg-green-500/10 border border-green-500/20">
              <p className="text-sm font-medium text-green-700 dark:text-green-400 flex items-center gap-2">
                <CheckCircle2 className="h-4 w-4" />
                Recommended: Use a Calendar Link
              </p>
              <p className="text-xs text-muted-foreground mt-1">
                Works with any calendar (Google, Outlook, Apple) without extra setup
              </p>
            </div>

            <RadioGroup
              value={selectedProvider || ""}
              onValueChange={(v) => setSelectedProvider(v as CalendarConnection["provider"] | "internal")}
              className="space-y-2"
            >
              {/* Show ICS first as recommended option */}
              {CALENDAR_PROVIDERS.filter(p => p.id === "ics").map((provider) => (
                <label
                  key={provider.id}
                  className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                    selectedProvider === provider.id
                      ? "border-primary bg-primary/5"
                      : "border-green-500/30 hover:bg-muted/50"
                  }`}
                >
                  <RadioGroupItem value={provider.id} className="sr-only" />
                  <span className="text-2xl">{provider.icon}</span>
                  <div className="flex-1">
                    <p className="font-medium flex items-center gap-2">
                      {provider.name}
                      <Badge variant="secondary" className="text-xs bg-green-500/10 text-green-700 dark:text-green-400">
                        No setup needed
                      </Badge>
                    </p>
                    <p className="text-sm text-muted-foreground">{provider.description}</p>
                  </div>
                  {selectedProvider === provider.id && (
                    <CheckCircle2 className="h-5 w-5 text-primary" />
                  )}
                </label>
              ))}
              
              <Separator className="my-2" />
              <p className="text-xs text-muted-foreground px-1">Direct calendar sync:</p>
              
              {/* Google and Microsoft with status indicators */}
              {CALENDAR_PROVIDERS.filter(p => ["google", "microsoft"].includes(p.id)).map((provider) => {
                const status = providerStatus[provider.id];
                const isNotConfigured = status === "not_configured";
                
                return (
                  <label
                    key={provider.id}
                    className={`flex items-center gap-3 p-3 rounded-lg border transition-colors ${
                      isNotConfigured 
                        ? "opacity-60 cursor-not-allowed border-border bg-muted/20"
                        : selectedProvider === provider.id
                          ? "border-primary bg-primary/5 cursor-pointer"
                          : "border-border hover:bg-muted/50 cursor-pointer"
                    }`}
                  >
                    <RadioGroupItem value={provider.id} className="sr-only" disabled={isNotConfigured} />
                    <span className="text-2xl">{provider.icon}</span>
                    <div className="flex-1">
                      <p className="font-medium flex items-center gap-2">
                        {provider.name}
                        {isNotConfigured && (
                          <Badge variant="outline" className="text-xs text-amber-600 border-amber-300">
                            Setup required
                          </Badge>
                        )}
                      </p>
                      <p className="text-sm text-muted-foreground">{provider.description}</p>
                    </div>
                    {selectedProvider === provider.id && !isNotConfigured && (
                      <CheckCircle2 className="h-5 w-5 text-primary" />
                    )}
                    {isNotConfigured && (
                      <Button
                        variant="ghost"
                        size="sm"
                        className="text-xs"
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          setSetupHelpProvider(provider.id);
                          setShowSetupHelp(true);
                        }}
                      >
                        Learn more
                      </Button>
                    )}
                  </label>
                );
              })}


              <Separator className="my-2" />
              <p className="text-xs text-muted-foreground px-1">Booking platforms:</p>

              {/* Calendly — live, API key */}
              <label
                className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                  selectedProvider === "calendly"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:bg-muted/50"
                }`}
              >
                <RadioGroupItem value="calendly" className="sr-only" />
                <span className="text-2xl">🗓️</span>
                <div className="flex-1">
                  <p className="font-medium flex items-center gap-2">
                    Calendly
                    <Badge variant="secondary" className="text-xs">API Key</Badge>
                  </p>
                  <p className="text-sm text-muted-foreground">Sync with your Calendly schedule</p>
                </div>
                {selectedProvider === "calendly" && (
                  <CheckCircle2 className="h-5 w-5 text-primary" />
                )}
              </label>

              {/* Square, Jobber - still coming soon */}
              {CALENDAR_PROVIDERS.filter(p => ["square", "jobber"].includes(p.id)).map((provider) => (
                <label
                  key={provider.id}
                  className="flex items-center gap-3 p-3 rounded-lg border border-border bg-muted/20 cursor-not-allowed opacity-60"
                >
                  <RadioGroupItem value={provider.id} className="sr-only" disabled />
                  <span className="text-2xl">{provider.icon}</span>
                  <div className="flex-1">
                    <p className="font-medium flex items-center gap-2">
                      {provider.name}
                      <Badge variant="outline" className="text-xs">Coming Soon</Badge>
                    </p>
                    <p className="text-sm text-muted-foreground">{provider.description}</p>
                  </div>
                </label>
              ))}
              
              <Separator className="my-2" />
              <p className="text-xs text-muted-foreground px-1">No external calendar:</p>
              
              {/* Internal Only option */}
              <label
                className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                  selectedProvider === "internal"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:bg-muted/50"
                }`}
              >
                <RadioGroupItem value="internal" className="sr-only" />
                <span className="text-2xl">🏠</span>
                <div className="flex-1">
                  <p className="font-medium flex items-center gap-2">
                    Internal Only
                    <Badge variant="secondary" className="text-xs">No sync needed</Badge>
                  </p>
                  <p className="text-sm text-muted-foreground">
                    Manage availability directly in CloseLoop — no external calendar needed
                  </p>
                </div>
                {selectedProvider === "internal" && (
                  <CheckCircle2 className="h-5 w-5 text-primary" />
                )}
              </label>

              {/* Manual option last */}
              {CALENDAR_PROVIDERS.filter(p => p.id === "manual").map((provider) => (
                <label
                  key={provider.id}
                  className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                    selectedProvider === provider.id
                      ? "border-primary bg-primary/5"
                      : "border-border hover:bg-muted/50"
                  }`}
                >
                  <RadioGroupItem value={provider.id} className="sr-only" />
                  <span className="text-2xl">{provider.icon}</span>
                  <div className="flex-1">
                    <p className="font-medium">{provider.name}</p>
                    <p className="text-sm text-muted-foreground">{provider.description}</p>
                  </div>
                  {selectedProvider === provider.id && (
                    <CheckCircle2 className="h-5 w-5 text-primary" />
                  )}
                </label>
              ))}
            </RadioGroup>

            {/* Setup Help Dialog */}
            {showSetupHelp && (
              <div className="p-4 rounded-lg border border-amber-300 bg-amber-50 dark:bg-amber-950/20 dark:border-amber-800">
                <div className="flex items-start gap-3">
                  <AlertCircle className="h-5 w-5 text-amber-600 mt-0.5" />
                  <div className="flex-1">
                    <p className="font-medium text-amber-800 dark:text-amber-200">
                      {setupHelpProvider === "google" ? "Google Calendar" : "Microsoft Outlook"} requires OAuth setup
                    </p>
                    <p className="text-sm text-amber-700 dark:text-amber-300 mt-1">
                      To enable direct sync, an admin needs to configure OAuth credentials in the backend.
                    </p>
                    <div className="mt-3 space-y-2 text-sm text-muted-foreground">
                      <p className="font-medium">In the meantime, you can:</p>
                      <ul className="list-disc list-inside space-y-1 ml-2">
                        <li>Use <strong>Calendar Link (ICS)</strong> — works with any calendar</li>
                        <li>Use <strong>Manual Only</strong> — manage availability here</li>
                      </ul>
                    </div>
                    <Button 
                      variant="outline" 
                      size="sm" 
                      className="mt-3"
                      onClick={() => {
                        setShowSetupHelp(false);
                        setSelectedProvider("ics");
                      }}
                    >
                      Use Calendar Link Instead
                    </Button>
                  </div>
                </div>
              </div>
            )}
          </div>
        )}

        {/* Step 2: Calendar Selection (OAuth), ICS URL, or Calendly API Key */}
        {step === 2 && (
          <div className="py-4 space-y-4">
            {selectedProvider === "calendly" ? (
              <>
                <div className="space-y-2">
                  <Label htmlFor="calendlyToken">Personal Access Token</Label>
                  <Input
                    id="calendlyToken"
                    type="password"
                    placeholder="eyJraWQiOi..."
                    value={calendlyApiKey}
                    onChange={(e) => setCalendlyApiKey(e.target.value)}
                    autoComplete="off"
                  />
                  <p className="text-xs text-muted-foreground">
                    We'll verify this instantly and store it securely.
                  </p>
                </div>

                <div className="p-3 rounded-lg bg-muted/50 text-sm space-y-1">
                  <p className="font-medium">How to get your token:</p>
                  <ol className="list-decimal list-inside space-y-0.5 text-muted-foreground ml-1">
                    <li>Go to <span className="font-mono text-xs">calendly.com</span> → sign in</li>
                    <li>Click your avatar → <strong>Integrations</strong></li>
                    <li>Select <strong>API & Webhooks</strong></li>
                    <li>Click <strong>Generate New Token</strong> and copy it here</li>
                  </ol>
                  <a
                    href="https://calendly.com/integrations/api_webhooks"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex items-center gap-1 text-primary text-xs mt-1 hover:underline"
                  >
                    Open Calendly API settings
                    <ExternalLink className="h-3 w-3" />
                  </a>
                </div>
              </>
            ) : selectedProvider === "ics" ? (
              <>
                <div className="space-y-2">
                  <Label htmlFor="icsUrl">Calendar Feed URL</Label>
                  <Input
                    id="icsUrl"
                    type="url"
                    placeholder="https://calendar.google.com/calendar/ical/..."
                    value={icsUrl}
                    onChange={(e) => setIcsUrl(e.target.value)}
                  />
                  <p className="text-xs text-muted-foreground">
                    Most calendars have an option to export as ICS/iCal.
                  </p>
                </div>
                
                <div className="p-3 rounded-lg bg-muted/50 text-sm">
                  <p className="font-medium mb-1">How to find your ICS URL:</p>
                  <ul className="list-disc list-inside space-y-1 text-muted-foreground">
                    <li>Google Calendar: Settings → Share → "Secret address in iCal format"</li>
                    <li>Apple Calendar: File → Export → Copy the URL</li>
                    <li>Outlook: Settings → View all settings → Calendar → Shared calendars</li>
                  </ul>
                </div>
              </>
            ) : (
              <>
                <div className="flex items-center justify-between">
                  <p className="text-sm text-muted-foreground">
                    Select which calendars should block your availability:
                  </p>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleRefreshCalendars}
                    disabled={isRefreshingCalendars}
                    className="text-xs"
                  >
                    {isRefreshingCalendars ? (
                      <Loader2 className="h-3 w-3 animate-spin mr-1" />
                    ) : (
                      <RefreshCw className="h-3 w-3 mr-1" />
                    )}
                    Refresh list
                  </Button>
                </div>
                
                {availableCalendars.length === 0 ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <Loader2 className="h-6 w-6 animate-spin mx-auto mb-2" />
                    <p>Loading calendars...</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {availableCalendars.map((cal) => (
                      <label
                        key={cal.id}
                        className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                          selectedCalendarIds.includes(cal.id)
                            ? "border-primary bg-primary/5"
                            : "border-border hover:bg-muted/50"
                        }`}
                      >
                        <Checkbox
                          checked={selectedCalendarIds.includes(cal.id)}
                          onCheckedChange={() => toggleCalendar(cal.id)}
                        />
                        <div className="flex-1">
                          <p className="font-medium">{cal.name}</p>
                          {cal.primary && (
                            <Badge variant="secondary" className="text-xs">Primary</Badge>
                          )}
                        </div>
                      </label>
                    ))}
                  </div>
                )}
              </>
            )}
          </div>
        )}

        {/* Step 3: Business Hours */}
        {step === 3 && (
          <div className="py-4">
            <p className="text-sm text-muted-foreground mb-4">
              AI will only offer appointments during these hours.
            </p>
            <BusinessHoursEditor hours={businessHours} onChange={setBusinessHours} />
          </div>
        )}

        {/* Step 4: Booking Rules */}
        {step === 4 && (
          <div className="py-4 space-y-4">
            <div className="space-y-2">
              <Label>Minimum notice required</Label>
              <select
                value={minLeadHours}
                onChange={(e) => setMinLeadHours(Number(e.target.value))}
                className="w-full h-11 rounded-lg border border-input bg-background px-4"
              >
                <option value={0}>No minimum</option>
                <option value={1}>1 hour</option>
                <option value={2}>2 hours</option>
                <option value={4}>4 hours</option>
                <option value={12}>12 hours</option>
                <option value={24}>24 hours (1 day)</option>
                <option value={48}>48 hours (2 days)</option>
              </select>
              <p className="text-xs text-muted-foreground">
                AI won't book anything sooner than this
              </p>
            </div>

            <div className="space-y-2">
              <Label>How far in advance can people book?</Label>
              <select
                value={maxAdvanceDays}
                onChange={(e) => setMaxAdvanceDays(Number(e.target.value))}
                className="w-full h-11 rounded-lg border border-input bg-background px-4"
              >
                <option value={7}>1 week</option>
                <option value={14}>2 weeks</option>
                <option value={30}>1 month</option>
                <option value={60}>2 months</option>
                <option value={90}>3 months</option>
              </select>
            </div>

            <div className="space-y-2">
              <Label>Buffer between appointments</Label>
              <select
                value={bufferMinutes}
                onChange={(e) => setBufferMinutes(Number(e.target.value))}
                className="w-full h-11 rounded-lg border border-input bg-background px-4"
              >
                <option value={0}>No buffer</option>
                <option value={15}>15 minutes</option>
                <option value={30}>30 minutes</option>
                <option value={45}>45 minutes</option>
                <option value={60}>1 hour</option>
              </select>
              <p className="text-xs text-muted-foreground">
                Time between back-to-back appointments
              </p>
            </div>
          </div>
        )}

        {/* Step 5: Booking Behavior */}
        {step === 5 && (
          <div className="py-4 space-y-4">
            <p className="text-sm text-muted-foreground">
              Choose how AI handles booking confirmations
            </p>
            
            <RadioGroup
              value={bookingBehavior}
              onValueChange={(v) => setBookingBehavior(v as BookingBehavior)}
              className="space-y-3"
            >
              <label
                className={`flex items-start gap-4 p-4 rounded-lg border cursor-pointer transition-colors ${
                  bookingBehavior === "auto_book"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:bg-muted/50"
                }`}
              >
                <RadioGroupItem value="auto_book" className="mt-1" />
                <div className="flex-1 space-y-1">
                  <div className="flex items-center gap-2">
                    <Sparkles className="h-4 w-4 text-primary" />
                    <span className="font-medium">Auto-Book</span>
                    <Badge variant="secondary" className="text-xs">Recommended</Badge>
                  </div>
                  <p className="text-sm text-muted-foreground">
                    AI confirms appointments instantly and syncs to your calendar. 
                    Best for established businesses with predictable schedules.
                  </p>
                  <div className="flex items-center gap-4 mt-2 text-xs text-muted-foreground">
                    <span className="flex items-center gap-1">
                      <CalendarCheck className="h-3 w-3" /> Adds to calendar
                    </span>
                    <span className="flex items-center gap-1">
                      <Send className="h-3 w-3" /> Sends confirmation
                    </span>
                  </div>
                </div>
              </label>

              <label
                className={`flex items-start gap-4 p-4 rounded-lg border cursor-pointer transition-colors ${
                  bookingBehavior === "pending_approval"
                    ? "border-primary bg-primary/5"
                    : "border-border hover:bg-muted/50"
                }`}
              >
                <RadioGroupItem value="pending_approval" className="mt-1" />
                <div className="flex-1 space-y-1">
                  <div className="flex items-center gap-2">
                    <Clock className="h-4 w-4 text-amber-500" />
                    <span className="font-medium">Pending Approval</span>
                  </div>
                  <p className="text-sm text-muted-foreground">
                    AI collects booking details but waits for your approval before confirming. 
                    Good for complex services or when you need manual review.
                  </p>
                  <div className="flex items-center gap-4 mt-2 text-xs text-muted-foreground">
                    <span className="flex items-center gap-1">
                      <AlertCircle className="h-3 w-3" /> Creates request
                    </span>
                    <span className="flex items-center gap-1">
                      You approve manually
                    </span>
                  </div>
                </div>
              </label>
            </RadioGroup>

            <div className="p-3 rounded-lg bg-muted/50 text-sm text-muted-foreground">
              <p>💡 You can change this anytime in Settings → Booking Delivery</p>
            </div>
          </div>
        )}

        {/* Step 6: Test Sync */}
        {step === 6 && (
          <div className="py-4 space-y-4">
            <div className="text-center">
              {syncStatus === "idle" && (
                <>
                  <p className="text-sm text-muted-foreground mb-4">
                    Let's verify your calendar sync is working correctly.
                  </p>
                  <Button onClick={handleTestSync} size="lg">
                    <RefreshCw className="h-4 w-4 mr-2" />
                    Test Sync Now
                  </Button>
                </>
              )}

              {syncStatus === "syncing" && (
                <div className="py-8">
                  <Loader2 className="h-8 w-8 animate-spin mx-auto mb-4 text-primary" />
                  <p className="text-muted-foreground">Syncing your calendar...</p>
                </div>
              )}

              {syncStatus === "success" && (
                <div className="py-4 space-y-4">
                  <div className="mx-auto w-12 h-12 rounded-full bg-green-500/10 flex items-center justify-center mb-4">
                    <CheckCircle2 className="h-6 w-6 text-green-500" />
                  </div>
                  <p className="font-medium text-green-600 mb-2">Sync successful!</p>
                  <p className="text-sm text-muted-foreground">
                    Found {syncedEventsCount} busy time{syncedEventsCount !== 1 ? "s" : ""} in the next 30 days
                  </p>

                  {/* Available Slots Test */}
                  <Separator className="my-4" />
                  
                  <div className="text-left">
                    <div className="flex items-center justify-between mb-3">
                      <p className="font-medium text-sm">Next 5 Available Slots</p>
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={loadTestSlots}
                        disabled={isLoadingSlots}
                      >
                        {isLoadingSlots ? (
                          <Loader2 className="h-3 w-3 animate-spin" />
                        ) : (
                          <RefreshCw className="h-3 w-3" />
                        )}
                      </Button>
                    </div>
                    
                    {isLoadingSlots ? (
                      <div className="text-center py-4">
                        <Loader2 className="h-5 w-5 animate-spin mx-auto" />
                      </div>
                    ) : testSlots.length === 0 ? (
                      <p className="text-sm text-muted-foreground text-center py-4">
                        No available slots found in the next 7 days
                      </p>
                    ) : (
                      <div className="space-y-2">
                        {testSlots.map((slot, i) => {
                          const startDate = new Date(slot.slot_start);
                          const isSelected = testBookingSlot === slot.slot_start;
                          const showSuccess = isSelected && testBookingResult === "success";
                          
                          return (
                            <div
                              key={i}
                              className={`flex items-center justify-between p-3 rounded-lg border ${
                                showSuccess 
                                  ? "border-green-500 bg-green-50 dark:bg-green-950/20" 
                                  : "border-border"
                              }`}
                            >
                              <div className="flex items-center gap-3">
                                <Calendar className="h-4 w-4 text-muted-foreground" />
                                <div>
                                  <p className="text-sm font-medium">
                                    {format(startDate, "EEEE, MMM d")}
                                  </p>
                                  <p className="text-xs text-muted-foreground">
                                    {format(startDate, "h:mm a")}
                                  </p>
                                </div>
                              </div>
                              <Button
                                variant={showSuccess ? "secondary" : "outline"}
                                size="sm"
                                onClick={() => handleTestBooking(slot.slot_start)}
                                disabled={isTestingBooking}
                              >
                                {isTestingBooking && isSelected ? (
                                  <Loader2 className="h-3 w-3 animate-spin" />
                                ) : showSuccess ? (
                                  <>
                                    <CheckCircle2 className="h-3 w-3 mr-1 text-green-600" />
                                    Available
                                  </>
                                ) : (
                                  "Test Book"
                                )}
                              </Button>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </div>
                </div>
              )}

              {syncStatus === "error" && (
                <div className="py-4">
                  <div className="mx-auto w-12 h-12 rounded-full bg-red-500/10 flex items-center justify-center mb-4">
                    <AlertCircle className="h-6 w-6 text-red-500" />
                  </div>
                  <p className="font-medium text-red-600 mb-2">Sync failed</p>
                  <p className="text-sm text-muted-foreground mb-4">
                    There was an issue syncing your calendar.
                  </p>
                  <Button onClick={handleTestSync} variant="outline">
                    Try Again
                  </Button>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Step 7: Success */}
        {step === 7 && (
          <div className="py-8 text-center">
            <div className="mx-auto w-12 h-12 rounded-full bg-green-500/10 flex items-center justify-center mb-4">
              <CheckCircle2 className="h-6 w-6 text-green-500" />
            </div>
            <DialogTitle className="mb-2">Schedule Connected!</DialogTitle>
            <DialogDescription>
              AI can now see your availability and book appointments without conflicts.
            </DialogDescription>
            
            <div className="mt-6 p-4 rounded-lg bg-muted/50 text-left space-y-2">
              <p className="text-sm font-medium">Your setup:</p>
              <ul className="text-sm text-muted-foreground space-y-1">
                <li className="flex items-center gap-2">
                  <CheckCircle2 className="h-3 w-3 text-green-500" />
                  {selectedProvider === "ics" ? "Calendar link connected" : 
                   selectedProvider === "manual" ? "Manual availability mode" :
                   selectedProvider === "internal" ? "Internal availability management" : 
                   `${selectedProvider} calendar synced`}
                </li>
                <li className="flex items-center gap-2">
                  <CheckCircle2 className="h-3 w-3 text-green-500" />
                  Business hours configured
                </li>
                <li className="flex items-center gap-2">
                  <CheckCircle2 className="h-3 w-3 text-green-500" />
                  Booking mode: {bookingBehavior === "auto_book" ? "Auto-Book" : "Pending Approval"}
                </li>
              </ul>
            </div>
          </div>
        )}

        <DialogFooter>
          {step <= 6 ? (
            <>
              {step > 1 && (
                <Button variant="outline" onClick={handleBack} disabled={isConnecting}>
                  <ArrowLeft className="h-4 w-4 mr-2" />
                  Back
                </Button>
              )}
              <Button
                onClick={handleNext}
                disabled={!canProceed() || isConnecting || isVerifyingCalendly || createConnection.isPending || isUpdating}
              >
                {(isConnecting || isVerifyingCalendly || createConnection.isPending || isUpdating) ? (
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                ) : null}
                {step === 1 && (selectedProvider === "google" || selectedProvider === "microsoft")
                  ? "Connect"
                  : step === 2 && selectedProvider === "calendly"
                    ? (isVerifyingCalendly ? "Verifying..." : "Verify & Connect")
                    : step === 6
                      ? "Complete Setup"
                      : "Next"}
                {step !== 6 && !isConnecting && !isVerifyingCalendly && <ArrowRight className="h-4 w-4 ml-2" />}
              </Button>
            </>
          ) : (
            <Button onClick={handleClose} className="w-full">
              Done
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Loader2, Phone, Mail, Webhook, Info, Save } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface CallbackSettings {
  sms_enabled: boolean;
  sms_recipient_phone: string;
  email_enabled: boolean;
  email_recipient: string;
  webhook_url: string;
  webhook_secret: string;
}

export function CallbackDeliverySettings() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const tenantId = tenant?.id;

  const [settings, setSettings] = useState<CallbackSettings>({
    sms_enabled: false,
    sms_recipient_phone: "",
    email_enabled: false,
    email_recipient: "",
    webhook_url: "",
    webhook_secret: "",
  });

  const { data, isLoading } = useQuery({
    queryKey: ["callback-delivery-settings", tenantId],
    queryFn: async () => {
      if (!tenantId) return null;
      const { data } = await (supabase as any)
        .from("callback_delivery_settings")
        .select("*")
        .eq("tenant_id", tenantId)
        .maybeSingle();
      return data;
    },
    enabled: !!tenantId,
  });

  useEffect(() => {
    if (data) {
      setSettings({
        sms_enabled: data.sms_enabled ?? false,
        sms_recipient_phone: data.sms_recipient_phone ?? "",
        email_enabled: data.email_enabled ?? false,
        email_recipient: data.email_recipient ?? "",
        webhook_url: data.webhook_url ?? "",
        webhook_secret: data.webhook_secret ?? "",
      });
    }
  }, [data]);

  const saveMutation = useMutation({
    mutationFn: async () => {
      if (!tenantId) throw new Error("No tenant");
      const payload = { tenant_id: tenantId, ...settings };
      const { error } = await (supabase as any)
        .from("callback_delivery_settings")
        .upsert(payload, { onConflict: "tenant_id" });
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["callback-delivery-settings"] });
      toast({ title: "Saved", description: "Callback notification settings updated." });
    },
    onError: (err) => {
      toast({ title: "Error", description: err instanceof Error ? err.message : "Failed to save", variant: "destructive" });
    },
  });

  if (isLoading) return <div className="flex items-center gap-2 p-4"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2"><Phone className="h-5 w-5" /> Callback Request Notifications</CardTitle>
        <CardDescription>Configure how you're notified when a caller requests a callback.</CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <Alert>
          <Info className="h-4 w-4" />
          <AlertDescription>
            When a caller asks for a callback, their request is saved automatically. Configure notifications below to be alerted in real time.
          </AlertDescription>
        </Alert>

        {/* SMS */}
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <Label className="flex items-center gap-2"><Phone className="h-4 w-4" /> SMS Notification</Label>
            <Switch checked={settings.sms_enabled} onCheckedChange={(v) => setSettings(s => ({ ...s, sms_enabled: v }))} />
          </div>
          {settings.sms_enabled && (
            <Input
              placeholder="Recipient phone number"
              value={settings.sms_recipient_phone}
              onChange={(e) => setSettings(s => ({ ...s, sms_recipient_phone: e.target.value }))}
            />
          )}
        </div>

        {/* Email */}
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <Label className="flex items-center gap-2"><Mail className="h-4 w-4" /> Email Notification</Label>
            <Switch checked={settings.email_enabled} onCheckedChange={(v) => setSettings(s => ({ ...s, email_enabled: v }))} />
          </div>
          {settings.email_enabled && (
            <Input
              type="email"
              placeholder="Recipient email"
              value={settings.email_recipient}
              onChange={(e) => setSettings(s => ({ ...s, email_recipient: e.target.value }))}
            />
          )}
        </div>

        {/* Webhook */}
        <div className="space-y-3">
          <Label className="flex items-center gap-2"><Webhook className="h-4 w-4" /> Webhook (Optional)</Label>
          <Input
            placeholder="https://your-crm.com/webhook"
            value={settings.webhook_url}
            onChange={(e) => setSettings(s => ({ ...s, webhook_url: e.target.value }))}
          />
          {settings.webhook_url && (
            <Input
              placeholder="Webhook secret (optional)"
              value={settings.webhook_secret}
              onChange={(e) => setSettings(s => ({ ...s, webhook_secret: e.target.value }))}
            />
          )}
        </div>

        <Button onClick={() => saveMutation.mutate()} disabled={saveMutation.isPending}>
          {saveMutation.isPending ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <Save className="h-4 w-4 mr-2" />}
          Save Settings
        </Button>
      </CardContent>
    </Card>
  );
}

 import { useState } from "react";
 import { useAuth } from "@/contexts/AuthContext";
 import { supabase } from "@/integrations/supabase/client";
 import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
 import { Button } from "@/components/ui/button";
 import { Input } from "@/components/ui/input";
 import { Label } from "@/components/ui/label";
 import {
   AlertDialog,
   AlertDialogAction,
   AlertDialogCancel,
   AlertDialogContent,
   AlertDialogDescription,
   AlertDialogFooter,
   AlertDialogHeader,
   AlertDialogTitle,
   AlertDialogTrigger,
 } from "@/components/ui/alert-dialog";
 import { AlertTriangle, Download, Trash2, Loader2 } from "lucide-react";
 import { toast } from "sonner";
 
 export function DangerZoneSection() {
   const { tenant, signOut } = useAuth();
   const [confirmText, setConfirmText] = useState("");
   const [isExporting, setIsExporting] = useState(false);
   const [isDeleting, setIsDeleting] = useState(false);
 
   const handleExportData = async () => {
     if (!tenant?.id) return;
     setIsExporting(true);
     try {
       // Fetch tenant data from multiple tables
       const [tenantData, bookings, customers, services, conversations] = await Promise.all([
         supabase.from("tenants").select("*").eq("id", tenant.id).single(),
         supabase.from("bookings").select("*").eq("tenant_id", tenant.id).limit(5000),
         supabase.from("customers").select("*").eq("tenant_id", tenant.id).limit(5000),
         supabase.from("services").select("*").eq("tenant_id", tenant.id).limit(5000),
         supabase.from("conversations").select("*").eq("tenant_id", tenant.id).limit(5000),
       ]);

       const exportData = {
         exported_at: new Date().toISOString(),
         tenant: tenantData.data,
         bookings: bookings.data || [],
         customers: customers.data || [],
         services: services.data || [],
         conversations: conversations.data || [],
       };

       const blob = new Blob([JSON.stringify(exportData, null, 2)], { type: "application/json" });
       const url = URL.createObjectURL(blob);
       const link = document.createElement("a");
       link.href = url;
       link.download = `closeloop-export-${tenant.id.slice(0, 8)}-${new Date().toISOString().slice(0, 10)}.json`;
       link.click();
       URL.revokeObjectURL(url);

       toast.success("Export complete", {
         description: "Your data has been downloaded as a JSON file.",
       });
     } catch (error) {
       toast.error("Export failed", {
         description: "Please try again or contact support.",
       });
     } finally {
       setIsExporting(false);
     }
   };
 
   const businessName = tenant?.name || "";
   const confirmTarget = businessName || "DELETE";

   const handleDeleteAccount = async () => {
     if (confirmText !== confirmTarget) return;

     setIsDeleting(true);
     try {
       toast.success("Account deletion requested", {
         description: "To complete data deletion, please contact support@closeloop.com. You have been signed out.",
       });
       signOut?.();
     } catch (error) {
       toast.error("Failed to process request", {
         description: "Please try again or contact support.",
       });
       setIsDeleting(false);
     }
   };
 
   return (
     <Card className="border-destructive/50">
       <CardHeader>
         <CardTitle className="text-destructive flex items-center gap-2">
           <AlertTriangle className="w-5 h-5" />
           Danger Zone
         </CardTitle>
         <CardDescription>
           Irreversible and destructive actions. Proceed with caution.
         </CardDescription>
       </CardHeader>
       <CardContent className="space-y-4">
         {/* Export Data */}
         <div className="flex items-center justify-between p-4 rounded-lg border">
           <div className="min-w-0 flex-1">
             <p className="font-medium">Export Data</p>
             <p className="text-sm text-muted-foreground">
               Download all your data including calls, leads, and settings.
             </p>
           </div>
           <Button
             variant="outline"
             onClick={handleExportData}
             disabled={isExporting}
             className="shrink-0 ml-4"
           >
             {isExporting ? (
               <Loader2 className="w-4 h-4 mr-2 animate-spin" />
             ) : (
               <Download className="w-4 h-4 mr-2" />
             )}
             Export
           </Button>
         </div>
 
         {/* Delete Account */}
         <div className="flex items-center justify-between p-4 rounded-lg border border-destructive/30 bg-destructive/5">
           <div className="min-w-0 flex-1">
             <p className="font-medium">Delete Account</p>
             <p className="text-sm text-muted-foreground">
               Permanently delete your account and all data. This cannot be undone.
             </p>
           </div>
           <AlertDialog>
             <AlertDialogTrigger asChild>
               <Button variant="destructive" className="shrink-0 ml-4">
                 <Trash2 className="w-4 h-4 mr-2" />
                 Delete Account
               </Button>
             </AlertDialogTrigger>
             <AlertDialogContent>
               <AlertDialogHeader>
                 <AlertDialogTitle>Are you absolutely sure?</AlertDialogTitle>
                 <AlertDialogDescription>
                   This will sign you out and request account deletion. Actual data
                   deletion requires contacting support. This cannot be undone once
                   processed.
                 </AlertDialogDescription>
               </AlertDialogHeader>
               <div className="py-4 space-y-2">
                 <Label htmlFor="confirm-delete">
                   Type <span className="font-mono font-bold">{confirmTarget}</span> to confirm
                 </Label>
                 <Input
                   id="confirm-delete"
                   placeholder={confirmTarget}
                   value={confirmText}
                   onChange={(e) => setConfirmText(e.target.value)}
                   className="font-mono"
                 />
               </div>
               <AlertDialogFooter>
                 <AlertDialogCancel onClick={() => setConfirmText("")}>
                   Cancel
                 </AlertDialogCancel>
                 <AlertDialogAction
                   className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
                   disabled={confirmText !== confirmTarget || isDeleting}
                   onClick={handleDeleteAccount}
                 >
                   {isDeleting ? (
                     <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                   ) : (
                     <Trash2 className="w-4 h-4 mr-2" />
                   )}
                   Delete Account
                 </AlertDialogAction>
               </AlertDialogFooter>
             </AlertDialogContent>
           </AlertDialog>
         </div>
       </CardContent>
     </Card>
   );
 }

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Brain, Lock, RefreshCw, Settings2 } from "lucide-react";
import { useIntelligenceSettings } from "@/hooks/useIntelligenceSettings";
import { Link } from "react-router-dom";

export function IntelligenceSettingsForm() {
  const { 
    settings, 
    isLoading, 
    updateSettings,
    toggleMemory,
    toggleCrossLocationSharing,
    isUpdating,
    hipaaMode,
    customerMemoryBlocked
  } = useIntelligenceSettings();

  if (isLoading) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center py-8">
          <RefreshCw className="h-5 w-5 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center gap-3">
          <div className="h-10 w-10 rounded-lg bg-primary/15 flex items-center justify-center">
            <Brain className="h-5 w-5 text-primary" />
          </div>
          <div>
            <CardTitle>AI Intelligence</CardTitle>
            <CardDescription>
              Configure how your AI learns and adapts over time
            </CardDescription>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* HIPAA Notice */}
        {hipaaMode && (
          <div className="flex items-center gap-3 p-3 rounded-lg bg-amber-500/10 border border-amber-500/20">
            <Lock className="h-4 w-4 text-amber-500" />
            <p className="text-sm">
              HIPAA mode is active. Customer-specific memory is automatically disabled.
            </p>
          </div>
        )}

        {/* Memory Toggle */}
        <div className="flex items-center justify-between">
          <div className="space-y-0.5">
            <Label htmlFor="memory-toggle" className="text-sm font-medium">
              Should AI learn from calls?
            </Label>
            <p className="text-xs text-muted-foreground">
              AI notices patterns and improves over time
            </p>
          </div>
          <Switch
            id="memory-toggle"
            checked={settings.memory_enabled}
            onCheckedChange={(checked) => toggleMemory(checked)}
            disabled={isUpdating}
          />
        </div>

        {settings.memory_enabled && (
          <>
            {/* Cross-Location Sharing */}
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="share-toggle" className="text-sm font-medium">
                  Share learnings with all locations
                </Label>
                <p className="text-xs text-muted-foreground">
                  What AI learns at one location helps all your locations
                </p>
              </div>
              <Switch
                id="share-toggle"
                checked={settings.share_memory_across_locations}
                onCheckedChange={(checked) => toggleCrossLocationSharing(checked)}
                disabled={isUpdating}
              />
            </div>

            {/* Copilot Rule Suggestions */}
            <div className="flex items-center justify-between">
              <div className="space-y-0.5">
                <Label htmlFor="copilot-toggle" className="text-sm font-medium">
                  Suggest new rules from patterns
                </Label>
                <p className="text-xs text-muted-foreground">
                  AI notices patterns and suggests rules for you to approve
                </p>
              </div>
              <Switch
                id="copilot-toggle"
                checked={settings.copilot_can_suggest_rules}
                onCheckedChange={(checked) => updateSettings.mutate({ copilot_can_suggest_rules: checked })}
                disabled={isUpdating}
              />
            </div>

            {/* Thresholds */}
            <div className="grid grid-cols-2 gap-4 pt-2">
              <div className="space-y-2">
                <Label className="text-xs text-muted-foreground">Learn after seeing pattern...</Label>
                <div className="flex items-center gap-2">
                  <Input
                    type="number"
                    value={settings.min_observation_threshold}
                    onChange={(e) => updateSettings.mutate({
                      min_observation_threshold: parseInt(e.target.value) || 3
                    })}
                    min={1}
                    max={10}
                    className="w-20"
                    disabled={isUpdating}
                  />
                  <span className="text-xs text-muted-foreground">times</span>
                </div>
                <p className="text-xs text-muted-foreground">Higher = more confident but slower</p>
              </div>
              <div className="space-y-2">
                <Label className="text-xs text-muted-foreground">Only use patterns AI is...</Label>
                <div className="flex items-center gap-2">
                  <Input
                    type="number"
                    value={Math.round(settings.min_confidence_threshold * 100)}
                    onChange={(e) => updateSettings.mutate({
                      min_confidence_threshold: (parseInt(e.target.value) || 65) / 100
                    })}
                    min={50}
                    max={100}
                    className="w-20"
                    disabled={isUpdating}
                  />
                  <span className="text-xs text-muted-foreground">% sure about</span>
                </div>
                <p className="text-xs text-muted-foreground">Higher = more cautious AI</p>
              </div>
            </div>
          </>
        )}

        {/* Link to Memory Tab */}
        {settings.memory_enabled && (
          <div className="pt-2">
            <Button variant="outline" size="sm" asChild>
              <Link to="/app/business-brain?tab=memory">
                <Settings2 className="h-4 w-4 mr-2" />
                Manage Learned Patterns
              </Link>
            </Button>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

