export function MedicalHIPAASettings() {
  const { tenant } = useAuth();
  const { hipaaMode } = useTenantConfig();
  const queryClient = useQueryClient();

  const { data: settings, isLoading } = useQuery({
    queryKey: ["medical-settings", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data, error } = await supabase
        .from("medical_settings")
        .select("*")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error) throw error;
      return data;
    },
    enabled: !!tenant?.id,
  });

  const [formValues, setFormValues] = useState({
    store_recordings: false,
    store_transcripts: false,
    require_verbal_consent: true,
    retention_days: 30,
  });

  // Update form values when settings load
  const effectiveValues = settings ? {
    store_recordings: settings.store_recordings,
    store_transcripts: settings.store_transcripts,
    require_verbal_consent: settings.require_verbal_consent,
    retention_days: settings.retention_days,
  } : formValues;

  const updateMutation = useMutation({
    mutationFn: async (updates: typeof formValues) => {
      if (!tenant?.id) throw new Error("No tenant");
      
      const { error } = await supabase
        .from("medical_settings")
        .upsert({
          tenant_id: tenant.id,
          ...updates,
          updated_at: new Date().toISOString(),
        });
      
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["medical-settings"] });
      toast.success("HIPAA settings updated");
    },
    onError: (error: Error) => {
      toast.error("Failed to update settings", { description: error.message });
    },
  });

  const handleSave = () => {
    updateMutation.mutate({
      store_recordings: effectiveValues.store_recordings,
      store_transcripts: effectiveValues.store_transcripts,
      require_verbal_consent: effectiveValues.require_verbal_consent,
      retention_days: effectiveValues.retention_days,
    });
  };

  if (!hipaaMode) {
    return (
      <Card>
        <CardContent className="pt-6">
          <div className="text-center py-8 text-muted-foreground">
            <Shield className="h-12 w-12 mx-auto mb-3 opacity-50" />
            <p>HIPAA settings are only available for medical practices</p>
            <p className="text-sm mt-2">
              Switch to Medical mode to access these settings
            </p>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (isLoading) {
    return (
      <Card>
        <CardContent className="pt-6">
          <div className="flex items-center justify-center py-8">
            <Loader2 className="h-8 w-8 animate-spin" />
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <Alert>
        <Shield className="h-4 w-4" />
        <AlertDescription>
          <strong>HIPAA Mode Active:</strong> These settings control how patient data 
          is stored and retained. Changes apply to all future calls immediately.
        </AlertDescription>
      </Alert>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Lock className="h-5 w-5" />
            Data Storage Settings
          </CardTitle>
          <CardDescription>
            Control what call data is stored for compliance
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {/* Recording Storage */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <div className="flex items-center gap-2">
                <Mic className="h-4 w-4 text-muted-foreground" />
                <Label htmlFor="store-recordings" className="font-medium">
                  Store Call Recordings
                </Label>
              </div>
              <p className="text-sm text-muted-foreground">
                Audio recordings contain PHI and require extra security measures
              </p>
            </div>
            <div className="flex items-center gap-2">
              {effectiveValues.store_recordings ? (
                <Badge variant="destructive" className="text-xs">Not recommended</Badge>
              ) : (
                <Badge variant="secondary" className="text-xs">Secure</Badge>
              )}
              <Switch
                id="store-recordings"
                checked={effectiveValues.store_recordings}
                onCheckedChange={(checked) => 
                  setFormValues({ ...effectiveValues, store_recordings: checked })
                }
              />
            </div>
          </div>

          {effectiveValues.store_recordings && (
            <Alert variant="destructive">
              <AlertTriangle className="h-4 w-4" />
              <AlertDescription>
                Storing recordings increases compliance requirements. Ensure your 
                organization has proper BAAs and security measures in place.
              </AlertDescription>
            </Alert>
          )}

          {/* Transcript Storage */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <div className="flex items-center gap-2">
                <FileText className="h-4 w-4 text-muted-foreground" />
                <Label htmlFor="store-transcripts" className="font-medium">
                  Store Full Transcripts
                </Label>
              </div>
              <p className="text-sm text-muted-foreground">
                Full transcripts may contain patient details. AI summaries are always stored.
              </p>
            </div>
            <div className="flex items-center gap-2">
              {effectiveValues.store_transcripts ? (
                <Badge variant="secondary" className="text-xs">Enabled</Badge>
              ) : (
                <Badge variant="secondary" className="text-xs">Summaries only</Badge>
              )}
              <Switch
                id="store-transcripts"
                checked={effectiveValues.store_transcripts}
                onCheckedChange={(checked) => 
                  setFormValues({ ...effectiveValues, store_transcripts: checked })
                }
              />
            </div>
          </div>

          {/* Verbal Consent */}
          <div className="flex items-center justify-between">
            <div className="space-y-0.5">
              <div className="flex items-center gap-2">
                <Shield className="h-4 w-4 text-muted-foreground" />
                <Label htmlFor="require-consent" className="font-medium">
                  Require Verbal Consent
                </Label>
              </div>
              <p className="text-sm text-muted-foreground">
                AI will ask callers to confirm consent before collecting intake information
              </p>
            </div>
            <Switch
              id="require-consent"
              checked={effectiveValues.require_verbal_consent}
              onCheckedChange={(checked) => 
                setFormValues({ ...effectiveValues, require_verbal_consent: checked })
              }
            />
          </div>

          {/* Retention Period */}
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <Clock className="h-4 w-4 text-muted-foreground" />
              <Label htmlFor="retention-days" className="font-medium">
                Data Retention Period
              </Label>
            </div>
            <p className="text-sm text-muted-foreground">
              Call summaries and intake data older than this will be automatically deleted
            </p>
            <div className="flex items-center gap-2">
              <Input
                id="retention-days"
                type="number"
                min={7}
                max={365}
                value={effectiveValues.retention_days}
                onChange={(e) => 
                  setFormValues({ 
                    ...effectiveValues, 
                    retention_days: parseInt(e.target.value) || 30 
                  })
                }
                className="w-24"
              />
              <span className="text-sm text-muted-foreground">days</span>
            </div>
          </div>

          <Button 
            onClick={handleSave} 
            disabled={updateMutation.isPending}
            className="w-full sm:w-auto"
          >
            {updateMutation.isPending ? (
              <Loader2 className="h-4 w-4 mr-2 animate-spin" />
            ) : (
              <Save className="h-4 w-4 mr-2" />
            )}
            Save HIPAA Settings
          </Button>
        </CardContent>
      </Card>

      <Card className="border-muted bg-muted/30">
        <CardContent className="pt-6">
          <div className="flex items-start gap-3">
            <Eye className="h-5 w-5 text-muted-foreground mt-0.5" />
            <div>
              <p className="font-medium">What the AI stores by default</p>
              <ul className="text-sm text-muted-foreground mt-2 space-y-1">
                <li>• Structured intake fields (reason for visit, preferred time, etc.)</li>
                <li>• AI-generated summary of the call (no verbatim PHI)</li>
                <li>• Consent timestamp (if verbal consent required)</li>
                <li>• Caller phone is redacted in stored context</li>
              </ul>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Loader2, Phone, Mail, Webhook, ShieldCheck, Save } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface MedicalDeliverySettings {
  sms_enabled: boolean;
  sms_recipient_phone: string;
  email_enabled: boolean;
  email_recipient: string;
  webhook_url: string;
  webhook_secret: string;
  hipaa_redact: boolean;
}

export function MedicalIntakeDeliverySettings() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const tenantId = tenant?.id;

  const [settings, setSettings] = useState<MedicalDeliverySettings>({
    sms_enabled: false,
    sms_recipient_phone: "",
    email_enabled: false,
    email_recipient: "",
    webhook_url: "",
    webhook_secret: "",
    hipaa_redact: true,
  });

  const { data, isLoading } = useQuery({
    queryKey: ["medical-intake-delivery-settings", tenantId],
    queryFn: async () => {
      if (!tenantId) return null;
      const { data } = await (supabase as any)
        .from("medical_intake_delivery_settings")
        .select("*")
        .eq("tenant_id", tenantId)
        .maybeSingle();
      return data;
    },
    enabled: !!tenantId,
  });

  useEffect(() => {
    if (data) {
      setSettings({
        sms_enabled: data.sms_enabled ?? false,
        sms_recipient_phone: data.sms_recipient_phone ?? "",
        email_enabled: data.email_enabled ?? false,
        email_recipient: data.email_recipient ?? "",
        webhook_url: data.webhook_url ?? "",
        webhook_secret: data.webhook_secret ?? "",
        hipaa_redact: data.hipaa_redact ?? true,
      });
    }
  }, [data]);

  const saveMutation = useMutation({
    mutationFn: async () => {
      if (!tenantId) throw new Error("No tenant");
      const payload = { tenant_id: tenantId, ...settings };
      const { error } = await (supabase as any)
        .from("medical_intake_delivery_settings")
        .upsert(payload, { onConflict: "tenant_id" });
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["medical-intake-delivery-settings"] });
      toast({ title: "Saved", description: "Medical intake notification settings updated." });
    },
    onError: (err) => {
      toast({ title: "Error", description: err instanceof Error ? err.message : "Failed to save", variant: "destructive" });
    },
  });

  if (isLoading) return <div className="flex items-center gap-2 p-4"><Loader2 className="h-4 w-4 animate-spin" /> Loading...</div>;

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2"><ShieldCheck className="h-5 w-5" /> Medical Intake Notifications</CardTitle>
        <CardDescription>Configure how you're notified when a patient intake is completed via AI call.</CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        <Alert>
          <ShieldCheck className="h-4 w-4" />
          <AlertDescription>
            HIPAA redaction is enabled by default. Patient details (phone, email) are removed from notifications. Disable only if your notification channels are HIPAA-compliant.
          </AlertDescription>
        </Alert>

        {/* HIPAA Redaction */}
        <div className="flex items-center justify-between">
          <Label className="flex items-center gap-2"><ShieldCheck className="h-4 w-4" /> HIPAA Redaction</Label>
          <Switch checked={settings.hipaa_redact} onCheckedChange={(v) => setSettings(s => ({ ...s, hipaa_redact: v }))} />
        </div>

        {/* SMS */}
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <Label className="flex items-center gap-2"><Phone className="h-4 w-4" /> SMS Notification</Label>
            <Switch checked={settings.sms_enabled} onCheckedChange={(v) => setSettings(s => ({ ...s, sms_enabled: v }))} />
          </div>
          {settings.sms_enabled && (
            <Input
              placeholder="Recipient phone number"
              value={settings.sms_recipient_phone}
              onChange={(e) => setSettings(s => ({ ...s, sms_recipient_phone: e.target.value }))}
            />
          )}
        </div>

        {/* Email */}
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <Label className="flex items-center gap-2"><Mail className="h-4 w-4" /> Email Notification</Label>
            <Switch checked={settings.email_enabled} onCheckedChange={(v) => setSettings(s => ({ ...s, email_enabled: v }))} />
          </div>
          {settings.email_enabled && (
            <Input
              type="email"
              placeholder="Recipient email"
              value={settings.email_recipient}
              onChange={(e) => setSettings(s => ({ ...s, email_recipient: e.target.value }))}
            />
          )}
        </div>

        {/* Webhook */}
        <div className="space-y-3">
          <Label className="flex items-center gap-2"><Webhook className="h-4 w-4" /> Webhook (Optional)</Label>
          <Input
            placeholder="https://your-ehr.com/webhook"
            value={settings.webhook_url}
            onChange={(e) => setSettings(s => ({ ...s, webhook_url: e.target.value }))}
          />
          {settings.webhook_url && (
            <Input
              placeholder="Webhook secret (optional)"
              value={settings.webhook_secret}
              onChange={(e) => setSettings(s => ({ ...s, webhook_secret: e.target.value }))}
            />
          )}
        </div>

        <Button onClick={() => saveMutation.mutate()} disabled={saveMutation.isPending}>
          {saveMutation.isPending ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : <Save className="h-4 w-4 mr-2" />}
          Save Settings
        </Button>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useSubscription } from "@/hooks/useSubscription";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import { Plus, Trash2, Phone, MapPin, Loader2, AlertCircle } from "lucide-react";
import { 
  getLocationAddOnPrice, 
  getTierFromSku,
  formatPrice,
  type PlanSku,
} from "@/config/pricing";

interface Location {
  id: string;
  tenant_id: string;
  location_name: string;
  phone_number_id: string | null;
  is_primary: boolean;
  monthly_fee_cents: number;
  status: string;
  created_at: string;
}

interface PhoneNumber {
  id: string;
  phone_e164: string;
  status: string;
}

export function MultiLocationManager() {
  const { tenant } = useAuth();
  const { planSku, hasVoice } = useSubscription(tenant?.id || null);
  const queryClient = useQueryClient();
  const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
  const [newLocationName, setNewLocationName] = useState("");

  // Fetch locations
  const { data: locations, isLoading: locationsLoading } = useQuery({
    queryKey: ["tenant_locations", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("tenant_locations")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("is_primary", { ascending: false })
        .order("created_at", { ascending: true });
      if (error) throw error;
      return data as Location[];
    },
    enabled: !!tenant?.id,
  });

  // Fetch phone numbers
  const { data: phoneNumbers } = useQuery({
    queryKey: ["phone_numbers", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("phone_numbers")
        .select("*")
        .eq("tenant_id", tenant.id);
      if (error) throw error;
      return data as PhoneNumber[];
    },
    enabled: !!tenant?.id,
  });

  // Get phone number for a location
  const getPhoneForLocation = (phoneNumberId: string | null) => {
    if (!phoneNumberId) return null;
    return phoneNumbers?.find(p => p.id === phoneNumberId);
  };

  // Calculate add-on price - voice only now
  const addOnPrice = getLocationAddOnPrice("voice");

  // Add location mutation
  const addLocation = useMutation({
    mutationFn: async (name: string) => {
      if (!tenant?.id || !planSku) throw new Error("Missing tenant or plan");

      // Create location record
      const { data: location, error: locationError } = await supabase
        .from("tenant_locations")
        .insert({
          tenant_id: tenant.id,
          location_name: name,
          is_primary: false,
          monthly_fee_cents: addOnPrice * 100,
          status: "pending_number",
        })
        .select()
        .single();

      if (locationError) throw locationError;

      // Provision a phone number for voice/both plans
      if (hasVoice) {
        try {
          const { data, error: provisionError } = await supabase.functions.invoke("provision-twilio-number", {
            body: { 
              tenant_id: tenant.id, 
              number_type: "local",
              location_id: location.id,
            },
          });

          if (provisionError) {
            console.error("Failed to provision number:", provisionError);
          } else if (data?.phone_number_id) {
            // Update location with phone number
            await supabase
              .from("tenant_locations")
              .update({ 
                phone_number_id: data.phone_number_id,
                status: "active",
              })
              .eq("id", location.id);
          }
        } catch (err) {
          console.error("Provisioning error:", err);
        }
      } else {
        // SMS-only: mark as active (no phone number needed for Twilio voice)
        await supabase
          .from("tenant_locations")
          .update({ status: "active" })
          .eq("id", location.id);
      }

      return location;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["tenant_locations"] });
      queryClient.invalidateQueries({ queryKey: ["phone_numbers"] });
      setIsAddDialogOpen(false);
      setNewLocationName("");
      toast.success("Location added successfully");
    },
    onError: (error) => {
      console.error("Failed to add location:", error);
      toast.error("Failed to add location");
    },
  });

  // Remove location mutation
  const removeLocation = useMutation({
    mutationFn: async (locationId: string) => {
      const { error } = await supabase
        .from("tenant_locations")
        .delete()
        .eq("id", locationId)
        .eq("is_primary", false); // Can't delete primary
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["tenant_locations"] });
      toast.success("Location removed");
    },
    onError: () => {
      toast.error("Failed to remove location");
    },
  });

  if (locationsLoading) {
    return (
      <Card>
        <CardHeader>
          <Skeleton className="h-6 w-32" />
          <Skeleton className="h-4 w-48" />
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <Skeleton className="h-16" />
            <Skeleton className="h-16" />
          </div>
        </CardContent>
      </Card>
    );
  }

  const additionalLocations = locations?.filter(l => !l.is_primary) || [];
  const monthlyTotal = additionalLocations.reduce((sum, l) => sum + (l.monthly_fee_cents / 100), 0);

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle>Multi-Location</CardTitle>
            <CardDescription>
              Add additional locations with dedicated phone numbers
            </CardDescription>
          </div>
          <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
            <DialogTrigger asChild>
              <Button size="sm">
                <Plus className="h-4 w-4 mr-1" />
                Add Location
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Add New Location</DialogTitle>
                <DialogDescription>
                  Each additional location includes a dedicated phone number and costs{" "}
                  <strong>{formatPrice(addOnPrice)}/month</strong>.
                </DialogDescription>
              </DialogHeader>
              <div className="space-y-4 py-4">
                <div className="space-y-2">
                  <Label>Location Name</Label>
                  <Input
                    value={newLocationName}
                    onChange={(e) => setNewLocationName(e.target.value)}
                    placeholder="Downtown Office"
                  />
                </div>
                <div className="rounded-lg bg-muted p-3 text-sm">
                  <div className="flex items-center gap-2 text-muted-foreground">
                    <AlertCircle className="h-4 w-4" />
                    <span>
                      {hasVoice 
                        ? "A new phone number will be provisioned for this location."
                        : "SMS routing will be configured for this location."}
                    </span>
                  </div>
                </div>
              </div>
              <DialogFooter>
                <Button variant="outline" onClick={() => setIsAddDialogOpen(false)}>
                  Cancel
                </Button>
                <Button 
                  onClick={() => addLocation.mutate(newLocationName)}
                  disabled={!newLocationName.trim() || addLocation.isPending}
                >
                  {addLocation.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                  Add Location ({formatPrice(addOnPrice)}/mo)
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Primary Location */}
        {locations?.filter(l => l.is_primary).map((location) => {
          const phone = getPhoneForLocation(location.phone_number_id);
          return (
            <div
              key={location.id}
              className="flex items-center justify-between p-4 rounded-lg border bg-primary/5 border-primary/20"
            >
              <div className="flex items-center gap-3">
                <MapPin className="h-5 w-5 text-primary" />
                <div>
                  <div className="font-medium flex items-center gap-2">
                    {location.location_name}
                    <Badge variant="secondary" className="text-xs">Primary</Badge>
                  </div>
                  {phone && (
                    <div className="text-sm text-muted-foreground flex items-center gap-1">
                      <Phone className="h-3 w-3" />
                      {phone.phone_e164}
                    </div>
                  )}
                </div>
              </div>
              <span className="text-sm text-muted-foreground">Included</span>
            </div>
          );
        })}

        {/* Additional Locations */}
        {additionalLocations.map((location) => {
          const phone = getPhoneForLocation(location.phone_number_id);
          return (
            <div
              key={location.id}
              className="flex items-center justify-between p-4 rounded-lg border"
            >
              <div className="flex items-center gap-3">
                <MapPin className="h-5 w-5 text-muted-foreground" />
                <div>
                  <div className="font-medium flex items-center gap-2">
                    {location.location_name}
                    <Badge variant={location.status === "active" ? "default" : "secondary"}>
                      {location.status}
                    </Badge>
                  </div>
                  {phone ? (
                    <div className="text-sm text-muted-foreground flex items-center gap-1">
                      <Phone className="h-3 w-3" />
                      {phone.phone_e164}
                    </div>
                  ) : (
                    <div className="text-sm text-muted-foreground">
                      {location.status === "pending_number" ? "Provisioning number..." : "No number assigned"}
                    </div>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-3">
                <span className="text-sm text-muted-foreground">
                  {formatPrice(location.monthly_fee_cents / 100)}/mo
                </span>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={() => removeLocation.mutate(location.id)}
                  disabled={removeLocation.isPending}
                >
                  <Trash2 className="h-4 w-4 text-muted-foreground hover:text-destructive" />
                </Button>
              </div>
            </div>
          );
        })}

        {additionalLocations.length === 0 && (
          <div className="text-center py-6 text-muted-foreground">
            <MapPin className="h-8 w-8 mx-auto mb-2 opacity-50" />
            <p>No additional locations</p>
            <p className="text-sm">Add locations to expand your coverage</p>
          </div>
        )}

        {/* Monthly Total */}
        {additionalLocations.length > 0 && (
          <div className="flex items-center justify-between pt-4 border-t">
            <span className="font-medium">Additional locations total</span>
            <span className="font-bold">{formatPrice(monthlyTotal)}/mo</span>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useSubscription } from "@/hooks/useSubscription";
import { useUsage } from "@/hooks/useUsage";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { toast } from "sonner";
import { ArrowUpRight, Check, Loader2, TrendingUp, MapPin } from "lucide-react";
import {
  getLadderStep,
  getLadderStepsForTier,
  getTierInfo,
  formatPrice,
  mapLegacyToNewSku,
  LOCATION_ADD_ONS,
  type PlanSku,
  type PlanLadderStep,
} from "@/config/pricing";

export function PlanUpgradeCard() {
  const { tenant } = useAuth();
  const { subscription, planSku, hasVoice, hasSms, refetch } = useSubscription(tenant?.id || null);
  const { usage, nextUpgrade } = useUsage(tenant?.id || null, planSku);
  const [isUpgrading, setIsUpgrading] = useState(false);
  const [selectedUpgradeSku, setSelectedUpgradeSku] = useState<PlanSku | null>(null);
  const [showUpgradeDialog, setShowUpgradeDialog] = useState(false);

  // Map legacy SKU if needed
  const mappedSku = planSku ? mapLegacyToNewSku(planSku) : null;
  const currentStep = mappedSku ? getLadderStep(mappedSku) : null;
  const tierInfo = currentStep ? getTierInfo(currentStep.tier) : null;
  const tierSteps = currentStep ? getLadderStepsForTier(currentStep.tier) : [];
  const currentIndex = tierSteps.findIndex(s => s.sku === mappedSku);

  const handleUpgrade = async () => {
    if (!tenant?.id || !selectedUpgradeSku) return;

    setIsUpgrading(true);
    try {
      const newStep = getLadderStep(selectedUpgradeSku);
      if (!newStep) throw new Error("Invalid SKU");

      // Update subscription with new plan (cast to any for DB type compatibility)
      const { error } = await supabase
        .from("subscriptions")
        .update({
          plan_code: selectedUpgradeSku as string,
          included_minutes: newStep.includedMinutes,
          included_sms_segments: newStep.includedSmsSegments,
          overage_minute_rate_cents: newStep.overageMinuteRate ? Math.round(newStep.overageMinuteRate * 100) : null,
          overage_sms_rate_cents: Math.round((newStep.overageSmsRate || 0) * 100),
        } as any)
        .eq("tenant_id", tenant.id);

      if (error) throw error;

      toast.success(`Upgraded to ${newStep.name}!`, {
        description: `Your new included limits are now active.`,
      });

      setShowUpgradeDialog(false);
      setSelectedUpgradeSku(null);
      await refetch();
    } catch (error) {
      console.error("Upgrade failed:", error);
      toast.error("Failed to upgrade plan");
    } finally {
      setIsUpgrading(false);
    }
  };

  if (!subscription || !currentStep || !tierInfo) {
    return null;
  }

  const totalOverage = usage?.projectedVoiceOverage || 0;
  const availableUpgrades = tierSteps.slice(currentIndex + 1);

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle>Current Plan</CardTitle>
            <CardDescription>{tierInfo.displayName}</CardDescription>
          </div>
          <Badge variant="default">Active</Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Current Plan Details */}
        <div className="p-4 rounded-lg border-2 border-primary/20 bg-primary/5">
          <div className="flex items-center justify-between mb-2">
            <span className="font-semibold text-lg">{currentStep.name}</span>
            <span className="font-bold text-xl">{formatPrice(currentStep.price)}/mo</span>
          </div>
          <div className="text-sm text-muted-foreground">
            {currentStep.includedMinutes?.toLocaleString()} pooled minutes included
          </div>
          {currentStep.overageMinuteRate && (
            <div className="text-sm text-muted-foreground">
              Overage rate: ${currentStep.overageMinuteRate}/min
            </div>
          )}
        </div>

        {/* Location Info */}
        <div className="p-3 rounded-lg bg-muted/50 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <MapPin className="h-4 w-4 text-muted-foreground" />
            <span className="text-sm">Locations</span>
          </div>
          <div className="text-sm">
            <span className="font-medium">1 location</span>
            <span className="text-muted-foreground"> • Additional: ${LOCATION_ADD_ONS.voice}/mo each</span>
          </div>
        </div>

        {/* Usage Summary */}
        {usage && hasVoice && usage.includedMinutes !== null && (
          <div className="space-y-3">
            <div>
              <div className="flex justify-between text-sm mb-1">
                <span>Voice minutes</span>
                <span>{usage.voiceMinutesUsed.toLocaleString()} / {usage.includedMinutes.toLocaleString()}</span>
              </div>
              <Progress 
                value={usage.voicePercentUsed} 
                className={usage.voicePercentUsed >= 90 ? "bg-destructive/20" : ""}
              />
            </div>
            {totalOverage > 0 && (
              <div className="flex items-center justify-between p-3 rounded-lg bg-amber-500/10 text-amber-700 dark:text-amber-400">
                <span className="text-sm font-medium">Projected overage this period</span>
                <span className="font-bold">${totalOverage.toFixed(2)}</span>
              </div>
            )}
          </div>
        )}

        {/* Upgrade Options */}
        {availableUpgrades.length > 0 && (
          <>
            <div className="border-t pt-4">
              <div className="flex items-center gap-2 mb-3">
                <TrendingUp className="h-4 w-4 text-primary" />
                <span className="font-medium">Upgrade for more minutes</span>
              </div>
              
              <div className="space-y-2">
                {availableUpgrades.map((step) => {
                  const priceDiff = step.price - currentStep.price;
                  const wouldSave = totalOverage > priceDiff;
                  
                  return (
                    <button
                      key={step.sku}
                      className="w-full flex items-center justify-between p-3 rounded-lg border hover:border-primary hover:bg-primary/5 transition-colors text-left"
                      onClick={() => {
                        setSelectedUpgradeSku(step.sku);
                        setShowUpgradeDialog(true);
                      }}
                    >
                      <div>
                        <div className="font-medium">{step.name}</div>
                        <div className="text-sm text-muted-foreground">
                          {step.includedMinutes?.toLocaleString()} pooled minutes
                        </div>
                      </div>
                      <div className="text-right">
                        <div className="font-bold">{formatPrice(step.price)}/mo</div>
                        <div className="text-xs text-muted-foreground">
                          +{formatPrice(priceDiff)}/mo
                        </div>
                        {wouldSave && (
                          <Badge variant="secondary" className="text-xs mt-1 bg-primary/10 text-primary">
                            Saves ${(totalOverage - priceDiff).toFixed(2)}
                          </Badge>
                        )}
                      </div>
                    </button>
                  );
                })}
              </div>
            </div>
          </>
        )}

        {/* Overage Rates */}
        <div className="text-xs text-muted-foreground border-t pt-4">
          <strong>Overage rate:</strong>{" "}
          {currentStep.overageMinuteRate ? `$${currentStep.overageMinuteRate.toFixed(2)}/min` : "N/A"}
        </div>
      </CardContent>

      {/* Upgrade Confirmation Dialog */}
      <Dialog open={showUpgradeDialog} onOpenChange={setShowUpgradeDialog}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Confirm Plan Upgrade</DialogTitle>
            <DialogDescription>
              You're upgrading to a plan with more included minutes.
            </DialogDescription>
          </DialogHeader>
          
          {selectedUpgradeSku && (() => {
            const newStep = getLadderStep(selectedUpgradeSku);
            if (!newStep) return null;
            const priceDiff = newStep.price - currentStep.price;
            
            return (
              <div className="space-y-4 py-4">
                <div className="flex items-center justify-between p-4 rounded-lg bg-muted">
                  <div>
                    <div className="font-medium">{currentStep.name}</div>
                    <div className="text-sm text-muted-foreground">Current plan</div>
                  </div>
                  <ArrowUpRight className="h-5 w-5" />
                  <div className="text-right">
                    <div className="font-medium">{newStep.name}</div>
                    <div className="text-sm text-muted-foreground">New plan</div>
                  </div>
                </div>
                
                <div className="space-y-2">
                  <div className="flex justify-between">
                    <span>New monthly rate</span>
                    <span className="font-bold">{formatPrice(newStep.price)}/mo</span>
                  </div>
                  <div className="flex justify-between text-sm text-muted-foreground">
                    <span>Increase from current</span>
                    <span>+{formatPrice(priceDiff)}/mo</span>
                  </div>
                </div>

                <div className="p-3 rounded-lg bg-primary/10 text-sm">
                  <div className="font-medium mb-1">New included limits:</div>
                  <ul className="space-y-1 text-muted-foreground">
                    {newStep.includedMinutes && (
                      <li className="flex items-center gap-2">
                        <Check className="h-3 w-3 text-primary" />
                        {newStep.includedMinutes.toLocaleString()} pooled voice minutes
                      </li>
                    )}
                    {newStep.overageMinuteRate && (
                      <li className="flex items-center gap-2">
                        <Check className="h-3 w-3 text-primary" />
                        Lower overage rate: ${newStep.overageMinuteRate}/min
                      </li>
                    )}
                  </ul>
                </div>
              </div>
            );
          })()}

          <DialogFooter>
            <Button variant="outline" onClick={() => setShowUpgradeDialog(false)}>
              Cancel
            </Button>
            <Button onClick={handleUpgrade} disabled={isUpgrading}>
              {isUpgrading && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Confirm Upgrade
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Badge } from "@/components/ui/badge";
import { Loader2, Plus, Trash2, DollarSign, AlertCircle } from "lucide-react";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { PricingEtaGuidance } from "@/components/brain/guidance";

interface PricingRule {
  id: string;
  name: string;
  ruleType: "fixed" | "range" | "conditional";
  enabled?: boolean;
  conditions?: Record<string, any>;
  requiredInputs?: string[];
  fixedPrice?: number; // cents
  rangeMin?: number; // cents
  rangeMax?: number; // cents
  priority: number;
}

const RULE_TYPE_OPTIONS = [
  { value: "fixed", label: "Fixed Price", description: "A single, exact price for this rule" },
  { value: "range", label: "Price Range", description: "Minimum and maximum price estimate" },
  { value: "conditional", label: "Conditional", description: "Price depends on specific conditions" },
];

export function PricingRulesEditor() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [isAddDialogOpen, setIsAddDialogOpen] = useState(false);
  const [editingRule, setEditingRule] = useState<PricingRule | null>(null);

  // Wizard state
  const [wizardStep, setWizardStep] = useState(1);
  const [newRule, setNewRule] = useState<Partial<PricingRule>>({
    name: "",
    ruleType: "fixed",
    enabled: true,
    priority: 10,
    requiredInputs: [],
  });

  // Fetch existing pricing rules
  const rulesQuery = useQuery({
    queryKey: ["pricing_rules", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];

      const { data, error } = await supabase
        .from("tenants")
        .select("pricing_rules_jsonb")
        .eq("id", tenant.id)
        .single();

      if (error) throw error;
      
      // Safe extraction: handle array, object with rules, or null
      const jsonb = data?.pricing_rules_jsonb;
      if (!jsonb) return [];
      if (Array.isArray(jsonb)) return jsonb as unknown as PricingRule[];
      if (typeof jsonb === 'object' && 'rules' in jsonb && Array.isArray((jsonb as Record<string, unknown>).rules)) {
        return (jsonb as Record<string, unknown>).rules as unknown as PricingRule[];
      }
      return [];
    },
    enabled: !!tenant?.id,
  });

  // Save pricing rules mutation
  const saveMutation = useMutation({
    mutationFn: async (rules: PricingRule[]) => {
      if (!tenant?.id) throw new Error("No tenant");

      const { error } = await supabase
        .from("tenants")
        .update({ pricing_rules_jsonb: rules as any })
        .eq("id", tenant.id);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["pricing_rules", tenant?.id] });
      toast({ title: "Pricing rules saved", description: "Your changes have been saved." });
    },
    onError: (error: Error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const rules = rulesQuery.data || [];

  const handleAddRule = () => {
    // Validate
    const errors = validateRule(newRule);
    if (errors.length > 0) {
      toast({
        title: "Validation errors",
        description: errors.join(". "),
        variant: "destructive",
      });
      return;
    }

    const ruleToAdd: PricingRule = {
      id: crypto.randomUUID(),
      name: newRule.name!,
      ruleType: newRule.ruleType as "fixed" | "range" | "conditional",
      enabled: newRule.enabled ?? true,
      priority: newRule.priority || 10,
      requiredInputs: newRule.requiredInputs || [],
      conditions: newRule.conditions,
      fixedPrice: newRule.fixedPrice,
      rangeMin: newRule.rangeMin,
      rangeMax: newRule.rangeMax,
    };

    saveMutation.mutate([...rules, ruleToAdd]);
    resetWizard();
  };

  const handleToggleRule = (ruleId: string, enabled: boolean) => {
    const updatedRules = rules.map((r) =>
      r.id === ruleId ? { ...r, enabled } : r
    );
    saveMutation.mutate(updatedRules);
  };

  const handleDeleteRule = (ruleId: string) => {
    const updatedRules = rules.filter((r) => r.id !== ruleId);
    saveMutation.mutate(updatedRules);
  };

  const resetWizard = () => {
    setNewRule({
      name: "",
      ruleType: "fixed",
      enabled: true,
      priority: 10,
      requiredInputs: [],
    });
    setWizardStep(1);
    setIsAddDialogOpen(false);
  };

  const validateRule = (rule: Partial<PricingRule>): string[] => {
    const errors: string[] = [];

    if (!rule.name || rule.name.trim() === "") {
      errors.push("Rule name is required");
    }

    if (rule.ruleType === "fixed") {
      if (rule.fixedPrice === undefined || rule.fixedPrice < 0) {
        errors.push("Fixed price must be a positive number");
      }
    }

    if (rule.ruleType === "range") {
      if (rule.rangeMin === undefined || rule.rangeMin < 0) {
        errors.push("Range minimum must be a positive number");
      }
      if (rule.rangeMax === undefined || rule.rangeMax < 0) {
        errors.push("Range maximum must be a positive number");
      }
      if (rule.rangeMin !== undefined && rule.rangeMax !== undefined && rule.rangeMin > rule.rangeMax) {
        errors.push("Range minimum cannot be greater than maximum");
      }
    }

    if (rule.ruleType === "conditional") {
      if (rule.fixedPrice === undefined || rule.fixedPrice < 0) {
        errors.push("Conditional rules must have a fixed price");
      }
    }

    return errors;
  };

  const formatPrice = (cents?: number) => {
    if (cents === undefined) return "-";
    return `$${(cents / 100).toFixed(2)}`;
  };

  const getRuleTypeBadgeColor = (type: string) => {
    switch (type) {
      case "fixed":
        return "bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200";
      case "range":
        return "bg-purple-100 text-purple-800 dark:bg-purple-900 dark:text-purple-200";
      case "conditional":
        return "bg-amber-100 text-amber-800 dark:bg-amber-900 dark:text-amber-200";
      default:
        return "";
    }
  };

  const renderWizardStep = () => {
    switch (wizardStep) {
      case 1:
        return (
          <div className="space-y-4">
            <div className="space-y-2">
              <Label>Rule Name *</Label>
              <Input
                value={newRule.name}
                onChange={(e) => setNewRule({ ...newRule, name: e.target.value })}
                placeholder="e.g., Standard Service Pricing"
              />
            </div>

            <div className="space-y-2">
              <Label>Rule Type *</Label>
              <Select
                value={newRule.ruleType}
                onValueChange={(value) =>
                  setNewRule({ ...newRule, ruleType: value as "fixed" | "range" | "conditional" })
                }
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {RULE_TYPE_OPTIONS.map((opt) => (
                    <SelectItem key={opt.value} value={opt.value}>
                      <div>
                        <div className="font-medium">{opt.label}</div>
                        <div className="text-xs text-muted-foreground">{opt.description}</div>
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-2">
              <Label>Priority</Label>
              <Input
                type="number"
                value={newRule.priority}
                onChange={(e) => setNewRule({ ...newRule, priority: parseInt(e.target.value) || 10 })}
                placeholder="10"
              />
              <p className="text-xs text-muted-foreground">
                Higher priority rules are checked first
              </p>
            </div>
          </div>
        );

      case 2:
        return (
          <div className="space-y-4">
            {newRule.ruleType === "fixed" && (
              <div className="space-y-2">
                <Label>Fixed Price (USD) *</Label>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">
                    $
                  </span>
                  <Input
                    type="number"
                    step="0.01"
                    min="0"
                    className="pl-8"
                    value={newRule.fixedPrice ? newRule.fixedPrice / 100 : ""}
                    onChange={(e) =>
                      setNewRule({ ...newRule, fixedPrice: Math.round(parseFloat(e.target.value) * 100) || 0 })
                    }
                    placeholder="149.00"
                  />
                </div>
              </div>
            )}

            {newRule.ruleType === "range" && (
              <>
                <div className="space-y-2">
                  <Label>Minimum Price (USD) *</Label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">
                      $
                    </span>
                    <Input
                      type="number"
                      step="0.01"
                      min="0"
                      className="pl-8"
                      value={newRule.rangeMin ? newRule.rangeMin / 100 : ""}
                      onChange={(e) =>
                        setNewRule({ ...newRule, rangeMin: Math.round(parseFloat(e.target.value) * 100) || 0 })
                      }
                      placeholder="100.00"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <Label>Maximum Price (USD) *</Label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">
                      $
                    </span>
                    <Input
                      type="number"
                      step="0.01"
                      min="0"
                      className="pl-8"
                      value={newRule.rangeMax ? newRule.rangeMax / 100 : ""}
                      onChange={(e) =>
                        setNewRule({ ...newRule, rangeMax: Math.round(parseFloat(e.target.value) * 100) || 0 })
                      }
                      placeholder="300.00"
                    />
                  </div>
                </div>
              </>
            )}

            {newRule.ruleType === "conditional" && (
              <>
                <div className="space-y-2">
                  <Label>Condition Field</Label>
                  <Input
                    value={(newRule.conditions as any)?.field || ""}
                    onChange={(e) =>
                      setNewRule({
                        ...newRule,
                        conditions: { ...(newRule.conditions || {}), field: e.target.value },
                      })
                    }
                    placeholder="e.g., urgency, service_type"
                  />
                </div>

                <div className="space-y-2">
                  <Label>Condition Value</Label>
                  <Input
                    value={(newRule.conditions as any)?.value || ""}
                    onChange={(e) =>
                      setNewRule({
                        ...newRule,
                        conditions: { ...(newRule.conditions || {}), value: e.target.value },
                      })
                    }
                    placeholder="e.g., high, drain_cleaning"
                  />
                </div>

                <div className="space-y-2">
                  <Label>Price (USD) *</Label>
                  <div className="relative">
                    <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground">
                      $
                    </span>
                    <Input
                      type="number"
                      step="0.01"
                      min="0"
                      className="pl-8"
                      value={newRule.fixedPrice ? newRule.fixedPrice / 100 : ""}
                      onChange={(e) =>
                        setNewRule({ ...newRule, fixedPrice: Math.round(parseFloat(e.target.value) * 100) || 0 })
                      }
                      placeholder="199.00"
                    />
                  </div>
                </div>
              </>
            )}

            <Alert>
              <AlertCircle className="h-4 w-4" />
              <AlertDescription>
                Prices are stored in cents to avoid rounding errors. Enter dollar amounts and they'll be
                converted automatically.
              </AlertDescription>
            </Alert>
          </div>
        );

      default:
        return null;
    }
  };

  if (rulesQuery.isLoading) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center py-12">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Pricing & ETA Guidance */}
      <PricingEtaGuidance businessMode={businessMode} />
      
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between">
            <div>
              <CardTitle>Pricing Rules</CardTitle>
              <CardDescription>
                Define pricing rules for services, estimates, and quotes. These power your AI's pricing
                decisions.
              </CardDescription>
            </div>
            <Dialog open={isAddDialogOpen} onOpenChange={setIsAddDialogOpen}>
              <DialogTrigger asChild>
                <Button>
                  <Plus className="h-4 w-4 mr-2" />
                  Add Rule
                </Button>
              </DialogTrigger>
              <DialogContent className="sm:max-w-[500px]">
                <DialogHeader>
                  <DialogTitle>
                    {wizardStep === 1 ? "New Pricing Rule" : "Set Price Amount"}
                  </DialogTitle>
                  <DialogDescription>
                    {wizardStep === 1
                      ? "Choose a name and type for your pricing rule"
                      : "Configure the price or price range for this rule"}
                  </DialogDescription>
                </DialogHeader>

                {renderWizardStep()}

                <DialogFooter>
                  {wizardStep > 1 && (
                    <Button variant="outline" onClick={() => setWizardStep(wizardStep - 1)}>
                      Back
                    </Button>
                  )}
                  {wizardStep < 2 ? (
                    <Button onClick={() => setWizardStep(2)}>Next</Button>
                  ) : (
                    <Button onClick={handleAddRule} disabled={saveMutation.isPending}>
                      {saveMutation.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                      Add Rule
                    </Button>
                  )}
                </DialogFooter>
              </DialogContent>
            </Dialog>
          </div>
        </CardHeader>
        <CardContent>
          {rules.length === 0 ? (
            <div className="text-center py-12">
              <DollarSign className="h-12 w-12 mx-auto text-muted-foreground mb-4" />
              <h3 className="text-lg font-medium mb-2">No pricing rules yet</h3>
              <p className="text-sm text-muted-foreground mb-4">
                Add your first pricing rule to help your AI provide accurate quotes and estimates.
              </p>
              <Button onClick={() => setIsAddDialogOpen(true)}>
                <Plus className="h-4 w-4 mr-2" />
                Add Your First Rule
              </Button>
            </div>
          ) : (
            <div className="space-y-3">
              {rules.map((rule) => (
                <div
                  key={rule.id}
                  className="flex items-center justify-between p-4 rounded-lg border bg-card"
                >
                  <div className="flex-1">
                    <div className="flex items-center gap-3 mb-2">
                      <h4 className="font-medium">{rule.name}</h4>
                      <Badge className={getRuleTypeBadgeColor(rule.ruleType)}>
                        {rule.ruleType}
                      </Badge>
                      {!rule.enabled && (
                        <Badge variant="outline" className="text-muted-foreground">
                          Disabled
                        </Badge>
                      )}
                    </div>
                    <div className="text-sm text-muted-foreground">
                      {rule.ruleType === "fixed" && (
                        <span>Fixed price: {formatPrice(rule.fixedPrice)}</span>
                      )}
                      {rule.ruleType === "range" && (
                        <span>
                          Range: {formatPrice(rule.rangeMin)} - {formatPrice(rule.rangeMax)}
                        </span>
                      )}
                      {rule.ruleType === "conditional" && (
                        <span>
                          Conditional: {formatPrice(rule.fixedPrice)} •{" "}
                          {rule.conditions && Object.keys(rule.conditions).length > 0
                            ? `${Object.keys(rule.conditions).length} condition(s)`
                            : "No conditions"}
                        </span>
                      )}
                      {" • "}Priority: {rule.priority}
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Switch
                      checked={rule.enabled !== false}
                      onCheckedChange={(checked) => handleToggleRule(rule.id, checked)}
                      disabled={saveMutation.isPending}
                    />
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => handleDeleteRule(rule.id)}
                      disabled={saveMutation.isPending}
                    >
                      <Trash2 className="h-4 w-4 text-destructive" />
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>How Pricing Rules Work</CardTitle>
        </CardHeader>
        <CardContent className="space-y-3 text-sm text-muted-foreground">
          <div>
            <strong className="text-foreground">Fixed Price:</strong> Use when you have a single,
            exact price for a service (e.g., "Oil change: $49.99").
          </div>
          <div>
            <strong className="text-foreground">Price Range:</strong> Use when pricing varies but you
            can provide a minimum and maximum (e.g., "HVAC repair: $200-$500").
          </div>
          <div>
            <strong className="text-foreground">Conditional:</strong> Use when price depends on
            specific conditions (e.g., "Urgent service: $199" vs "Standard service: $149").
          </div>
          <div>
            <strong className="text-foreground">Priority:</strong> Higher priority rules are matched
            first. Use this to create specific rules that override general ones.
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

