};

const intentLabels: Record<Intent, string> = {
  booking: "Booking",
  dispatch: "Dispatch",
  order: "Order",
  reservation: "Reservation",
  callback: "Callback"
};

const intentDescriptions: Record<Intent, string> = {
  booking: "Service bookings and appointments",
  dispatch: "Towing, delivery, and dispatch requests",
  order: "Food orders and product purchases",
  reservation: "Restaurant reservations",
  callback: "Callback requests"
};

export function RequiredQuestionsEditor() {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [hasChanges, setHasChanges] = useState(false);
  const [configs, setConfigs] = useState<Record<Intent, IntentRequiredInputsConfig>>({} as any);
  const [activeIntent, setActiveIntent] = useState<Intent | null>(null);

  // Determine which intents are relevant based on business mode
  const relevantIntents: Intent[] = useMemo(() => {
    switch (businessMode) {
      case "food":
        return ["order", "reservation", "callback"];
      case "dispatch":
        return ["dispatch", "callback"];
      case "service":
        return ["booking", "callback"];
      case "medical":
        return ["booking", "callback"];
      case "sales":
        return ["booking", "callback"];
      case "general":
        return ["booking", "callback"];
      default:
        return ["booking", "callback"];
    }
  }, [businessMode]);

  // Set active intent to first relevant one when business mode changes
  useEffect(() => {
    if (!activeIntent || !relevantIntents.includes(activeIntent)) {
      setActiveIntent(relevantIntents[0]);
    }
  }, [relevantIntents, activeIntent]);

  // Load existing configurations
  useEffect(() => {
    if (!tenant?.id) return;

    const loadConfigs = async () => {
      setLoading(true);
      try {
        const baseQuery = supabase
          .from("business_intent_rules")
          .select("*")
          .eq("tenant_id", tenant.id);
        const { data: rules, error } = await (baseQuery as any).eq("rule_type", "required_inputs");

        if (error) throw error;

        const loadedConfigs: Record<Intent, IntentRequiredInputsConfig> = {} as any;

        // Initialize with defaults for relevant intents
        for (const intent of relevantIntents) {
          const existingRule = rules?.find((r) => (r.action_json as any)?.intent === intent);

          if (existingRule && existingRule.action_json) {
            loadedConfigs[intent] = existingRule.action_json as unknown as IntentRequiredInputsConfig;
          } else {
            // Default: some standard fields required, others optional
            const standard = standardFields[intent] || [];
            loadedConfigs[intent] = {
              intent,
              required_inputs: standard.slice(0, 3), // First 3 required by default
              optional_inputs: standard.slice(3), // Rest optional
            };
          }
        }

        setConfigs(loadedConfigs);
      } catch (error) {
        console.error("Failed to load required questions:", error);
        toast.error("Failed to load configurations");
      } finally {
        setLoading(false);
      }
    };

    loadConfigs();
  }, [tenant?.id, businessMode]);

  const currentConfig = activeIntent ? configs[activeIntent] : null;

  const toggleFieldRequired = (field: InputField, isRequired: boolean) => {
    if (!currentConfig || !activeIntent) return;
    const newConfig = { ...currentConfig };

    if (isRequired) {
      // Move from optional to required
      newConfig.optional_inputs = newConfig.optional_inputs.filter((f) => f.key !== field.key);
      newConfig.required_inputs.push(field);
    } else {
      // Move from required to optional
      newConfig.required_inputs = newConfig.required_inputs.filter((f) => f.key !== field.key);
      newConfig.optional_inputs.push(field);
    }

    setConfigs({ ...configs, [activeIntent]: newConfig });
    setHasChanges(true);
  };

  const updateField = (
    field: InputField,
    updates: Partial<InputField>,
    isRequired: boolean
  ) => {
    if (!currentConfig || !activeIntent) return;
    const newConfig = { ...currentConfig };
    const targetArray = isRequired ? newConfig.required_inputs : newConfig.optional_inputs;
    const index = targetArray.findIndex((f) => f.key === field.key);

    if (index !== -1) {
      targetArray[index] = { ...targetArray[index], ...updates };
      setConfigs({ ...configs, [activeIntent]: newConfig });
      setHasChanges(true);
    }
  };

  const addCustomField = (isRequired: boolean) => {
    if (!currentConfig || !activeIntent) return;
    const newField: InputField = {
      key: `custom_${Date.now()}`,
      label: "New Custom Question",
      ask_prompt: "Please provide...",
      why_needed: "Required for processing"
    };

    const newConfig = { ...currentConfig };
    if (isRequired) {
      newConfig.required_inputs.push(newField);
    } else {
      newConfig.optional_inputs.push(newField);
    }

    setConfigs({ ...configs, [activeIntent]: newConfig });
    setHasChanges(true);
  };

  const removeField = (field: InputField, isRequired: boolean) => {
    if (!currentConfig || !activeIntent) return;
    const newConfig = { ...currentConfig };
    if (isRequired) {
      newConfig.required_inputs = newConfig.required_inputs.filter((f) => f.key !== field.key);
    } else {
      newConfig.optional_inputs = newConfig.optional_inputs.filter((f) => f.key !== field.key);
    }
    setConfigs({ ...configs, [activeIntent]: newConfig });
    setHasChanges(true);
  };

  const saveConfigurations = async () => {
    if (!tenant?.id) return;

    setSaving(true);
    try {
      // Delete existing required_inputs rules
      const deleteQuery = supabase
        .from("business_intent_rules")
        .delete()
        .eq("tenant_id", tenant.id);
      await (deleteQuery as any).eq("rule_type", "required_inputs");

      // Insert new rules for each intent
      const rulesToInsert = relevantIntents.map((intent) => ({
        tenant_id: tenant.id,
        rule_type: "required_inputs",
        name: `Required Questions: ${intentLabels[intent]}`,
        description: `Input requirements for ${intentLabels[intent].toLowerCase()} intent`,
        condition_json: {},
        action_json: configs[intent] as any,
        priority: 0,
        is_enabled: true,
        is_suggested: false
      }));

      const { error } = await supabase
        .from("business_intent_rules")
        .insert(rulesToInsert as any);

      if (error) throw error;

      toast.success("Required questions saved successfully");
      setHasChanges(false);
    } catch (error) {
      console.error("Failed to save required questions:", error);
      toast.error("Failed to save configurations");
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <Card>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <div className="animate-spin rounded-full h-6 w-6 border-2 border-primary border-t-transparent" />
            <span className="ml-3 text-sm text-muted-foreground">Loading configurations...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!currentConfig) {
    return (
      <Card>
        <CardContent className="p-6">
          <p className="text-sm text-muted-foreground text-center">
            No configuration available for this intent.
          </p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold">What AI Collects</h3>
          <p className="text-sm text-muted-foreground">
            Choose what info your AI asks for on each type of call
          </p>
        </div>
        {hasChanges && (
          <Button onClick={saveConfigurations} disabled={saving}>
            {saving ? "Saving..." : "Save Changes"}
          </Button>
        )}
      </div>

      {/* Intent Tabs */}
      <Tabs value={activeIntent || relevantIntents[0]} onValueChange={(v) => setActiveIntent(v as Intent)}>
        <TabsList className="grid grid-cols-2 lg:grid-cols-5 w-full">
          {relevantIntents.map((intent) => {
            const Icon = intentIcons[intent];
            const config = configs[intent];
            const requiredCount = config?.required_inputs?.length || 0;

            return (
              <TabsTrigger key={intent} value={intent} className="gap-2">
                <Icon className="h-4 w-4" />
                <span className="hidden sm:inline">{intentLabels[intent]}</span>
                <Badge variant="secondary" className="text-xs">
                  {requiredCount}
                </Badge>
              </TabsTrigger>
            );
          })}
        </TabsList>

        {relevantIntents.map((intent) => {
          const config = configs[intent];
          if (!config) return null;

          return (
            <TabsContent key={intent} value={intent} className="mt-6 space-y-6">
              {/* Intent Description */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-base flex items-center gap-2">
                    {intentLabels[intent]} Questions
                  </CardTitle>
                  <CardDescription>{intentDescriptions[intent]}</CardDescription>
                </CardHeader>
              </Card>

              {/* Required Fields */}
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle className="text-base flex items-center gap-2">
                        <AlertCircle className="h-4 w-4 text-rose-400" />
                        Must Have Before Booking
                        <Badge variant="outline" className="bg-rose-500/10 text-rose-400 border-rose-500/30">
                          {config.required_inputs.length} required
                        </Badge>
                      </CardTitle>
                      <CardDescription>
                        AI won't complete the {intent} without these
                      </CardDescription>
                    </div>
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => addCustomField(true)}
                      className="gap-1"
                    >
                      <Plus className="h-3 w-3" />
                      Add Custom
                    </Button>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  {config.required_inputs.length === 0 ? (
                    <div className="text-center py-6 text-sm text-muted-foreground">
                      No required fields. Add standard or custom questions above.
                    </div>
                  ) : (
                    config.required_inputs.map((field) => (
                      <FieldEditor
                        key={field.key}
                        field={field}
                        isRequired={true}
                        onToggleRequired={(isReq) => toggleFieldRequired(field, isReq)}
                        onUpdate={(updates) => updateField(field, updates, true)}
                        onRemove={() => removeField(field, true)}
                        isCustom={field.key.startsWith("custom_")}
                      />
                    ))
                  )}
                </CardContent>
              </Card>

              {/* Optional Fields */}
              <Card>
                <CardHeader>
                  <div className="flex items-center justify-between">
                    <div>
                      <CardTitle className="text-base flex items-center gap-2">
                        <CheckCircle2 className="h-4 w-4 text-blue-400" />
                        Nice to Have
                        <Badge variant="outline" className="bg-blue-500/10 text-blue-400 border-blue-500/30">
                          {config.optional_inputs.length} optional
                        </Badge>
                      </CardTitle>
                      <CardDescription>
                        AI asks when relevant but can proceed without them
                      </CardDescription>
                    </div>
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => addCustomField(false)}
                      className="gap-1"
                    >
                      <Plus className="h-3 w-3" />
                      Add Custom
                    </Button>
                  </div>
                </CardHeader>
                <CardContent className="space-y-4">
                  {config.optional_inputs.length === 0 ? (
                    <div className="text-center py-6 text-sm text-muted-foreground">
                      No optional fields. Add custom questions above.
                    </div>
                  ) : (
                    config.optional_inputs.map((field) => (
                      <FieldEditor
                        key={field.key}
                        field={field}
                        isRequired={false}
                        onToggleRequired={(isReq) => toggleFieldRequired(field, isReq)}
                        onUpdate={(updates) => updateField(field, updates, false)}
                        onRemove={() => removeField(field, false)}
                        isCustom={field.key.startsWith("custom_")}
                      />
                    ))
                  )}
                </CardContent>
              </Card>
            </TabsContent>
          );
        })}
      </Tabs>
    </div>
  );
}

interface FieldEditorProps {
  field: InputField;
  isRequired: boolean;
  onToggleRequired: (isRequired: boolean) => void;
  onUpdate: (updates: Partial<InputField>) => void;
  onRemove: () => void;
  isCustom: boolean;
}

// Helper function to get validation hints for a field
function getValidationHint(fieldKey: string): { type: string; examples: string; invalid: string } | null {
  const key = fieldKey.toLowerCase();

  if (key.includes('address') && !key.includes('email')) {
    return {
      type: "Address",
      examples: "✓ '123 Main St, Chicago' or '✓ Main & Oak, 62701'",
      invalid: "✗ 'downtown' or ✗ '123 Main' (no city/ZIP)"
    };
  }

  if (key.includes('date')) {
    return {
      type: "Date",
      examples: "✓ 'tomorrow' or ✓ 'December 25th'",
      invalid: "✗ 'soon' or ✗ 'later'"
    };
  }

  if (key.includes('time') && !key.includes('estimated')) {
    return {
      type: "Time",
      examples: "✓ '2pm' or ✓ 'morning'",
      invalid: "✗ 'later' or ✗ 'whenever'"
    };
  }

  if (key.includes('miles') || key === 'estimated_miles') {
    return {
      type: "Distance",
      examples: "✓ '5 miles' or ✓ 'about 10'",
      invalid: "✗ 'not far' (needs number)"
    };
  }

  if (key.includes('email')) {
    return {
      type: "Email",
      examples: "✓ 'john@example.com'",
      invalid: "✗ Missing @ or domain"
    };
  }

  if (key.includes('phone')) {
    return {
      type: "Phone",
      examples: "✓ '555-123-4567'",
      invalid: "✗ Fewer than 7 digits"
    };
  }

  if (key === 'party_size') {
    return {
      type: "Party Size",
      examples: "✓ '2' or ✓ 'party of 4'",
      invalid: "✗ 'a few' (needs number)"
    };
  }

  return null;
}

function FieldEditor({
  field,
  isRequired,
  onToggleRequired,
  onUpdate,
  onRemove,
  isCustom
}: FieldEditorProps) {
  const validationHint = getValidationHint(field.key);

  return (
    <div className="p-4 rounded-lg border bg-muted/30 space-y-4">
      {/* Header with toggle */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Switch
            checked={isRequired}
            onCheckedChange={onToggleRequired}
          />
          <div>
            <Label className="font-medium">{field.label}</Label>
            <p className="text-xs text-muted-foreground">
              {isRequired ? "Required field" : "Optional field"}
            </p>
          </div>
        </div>
        {isCustom && (
          <Button
            size="sm"
            variant="ghost"
            onClick={onRemove}
            className="text-rose-400 hover:text-rose-300 hover:bg-rose-500/10"
          >
            <Trash2 className="h-4 w-4" />
          </Button>
        )}
      </div>

      {/* Validation Hint */}
      {validationHint && (
        <div className="p-2 rounded bg-blue-500/10 border border-blue-500/20">
          <p className="text-xs font-medium text-blue-400 mb-1">
            {validationHint.type} Validation
          </p>
          <p className="text-xs text-muted-foreground">
            {validationHint.examples}
          </p>
          <p className="text-xs text-muted-foreground">
            {validationHint.invalid}
          </p>
        </div>
      )}

      <Separator />

      {/* Field Configuration */}
      <div className="grid gap-4">
        <div className="grid gap-2">
          <Label htmlFor={`${field.key}-label`} className="text-xs">
            Field Label
          </Label>
          <Input
            id={`${field.key}-label`}
            value={field.label}
            onChange={(e) => onUpdate({ label: e.target.value })}
            placeholder="e.g., Customer Name"
          />
        </div>

        <div className="grid gap-2">
          <Label htmlFor={`${field.key}-ask`} className="text-xs">
            AI will ask:
          </Label>
          <Textarea
            id={`${field.key}-ask`}
            value={field.ask_prompt}
            onChange={(e) => onUpdate({ ask_prompt: e.target.value })}
            placeholder="e.g., May I have your name please?"
            rows={2}
          />
        </div>

        <div className="grid gap-2">
          <Label htmlFor={`${field.key}-why`} className="text-xs">
            You need this because:
          </Label>
          <Textarea
            id={`${field.key}-why`}
            value={field.why_needed}
            onChange={(e) => onUpdate({ why_needed: e.target.value })}
            placeholder="e.g., Required to identify the customer"
            rows={2}
          />
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { useRevenueSettings } from "@/hooks/useRevenueSettings";
import { useAuth } from "@/contexts/AuthContext";
import { getLadderStep, mapLegacyToNewSku, formatPrice } from "@/config/pricing";

export function RevenueSettingsSection() {
  const { subscription } = useAuth();
  const { settings, isLoading, upsertSettings } = useRevenueSettings();

  const [defaultValue, setDefaultValue] = useState("100.00");
  const [costOverride, setCostOverride] = useState("");
  const [useOverride, setUseOverride] = useState(false);
  const [sendReport, setSendReport] = useState(false);

  // Derive auto-detected plan price
  const planCode = (subscription as any)?.plan_code;
  const mappedSku = planCode ? mapLegacyToNewSku(planCode) : null;
  const planStep = mappedSku ? getLadderStep(mappedSku) : null;
  const autoPlanPrice = planStep?.price ?? 249;

  // Sync state from loaded settings
  useEffect(() => {
    if (settings) {
      setDefaultValue((settings.default_service_value_cents / 100).toFixed(2));
      setSendReport(settings.send_monthly_report);
      if (settings.subscription_cost_override_cents !== null) {
        setUseOverride(true);
        setCostOverride((settings.subscription_cost_override_cents / 100).toFixed(2));
      } else {
        setUseOverride(false);
        setCostOverride("");
      }
    }
  }, [settings]);

  const handleSave = () => {
    const defaultCents = Math.round(parseFloat(defaultValue || "100") * 100);
    const overrideCents = useOverride && costOverride
      ? Math.round(parseFloat(costOverride) * 100)
      : null;

    upsertSettings.mutate({
      default_service_value_cents: defaultCents,
      subscription_cost_override_cents: overrideCents,
      send_monthly_report: sendReport,
    });
  };

  if (isLoading) {
    return (
      <Card>
        <CardHeader>
          <Skeleton className="h-5 w-40" />
          <Skeleton className="h-4 w-64" />
        </CardHeader>
        <CardContent className="space-y-4">
          <Skeleton className="h-10 w-full" />
          <Skeleton className="h-10 w-full" />
          <Skeleton className="h-6 w-48" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle>Revenue Tracking</CardTitle>
        <CardDescription>
          Configure how your AI-generated revenue and ROI are calculated.
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Default Service Value */}
        <div className="space-y-2">
          <label className="text-sm font-medium">Default Service Value</label>
          <div className="relative max-w-xs">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">
              $
            </span>
            <Input
              type="number"
              step="0.01"
              min="0"
              value={defaultValue}
              onChange={(e) => setDefaultValue(e.target.value)}
              className="pl-7"
              placeholder="100.00"
            />
          </div>
          <p className="text-xs text-muted-foreground">
            Used as a fallback when a service doesn't have a set price (e.g., quote-only services).
          </p>
        </div>

        {/* Subscription Cost */}
        <div className="space-y-3">
          <label className="text-sm font-medium">Monthly Subscription Cost</label>
          <div className="flex items-center gap-3">
            <Badge variant="muted" size="sm">
              Auto-detected: {formatPrice(autoPlanPrice)}/mo
            </Badge>
          </div>

          <div className="flex items-center gap-3">
            <Switch
              checked={useOverride}
              onCheckedChange={setUseOverride}
            />
            <span className="text-sm text-muted-foreground">
              Override with custom amount
            </span>
          </div>

          {useOverride && (
            <div className="relative max-w-xs">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground text-sm">
                $
              </span>
              <Input
                type="number"
                step="0.01"
                min="0"
                value={costOverride}
                onChange={(e) => setCostOverride(e.target.value)}
                className="pl-7"
                placeholder={autoPlanPrice.toFixed(2)}
              />
            </div>
          )}
          <p className="text-xs text-muted-foreground">
            Used to calculate your ROI. Override if you have a custom deal or annual plan.
          </p>
        </div>

        {/* Monthly Report Toggle */}
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium">Monthly ROI Email</p>
            <p className="text-xs text-muted-foreground">
              Receive a monthly revenue report via email
            </p>
          </div>
          <Switch
            checked={sendReport}
            onCheckedChange={setSendReport}
          />
        </div>

        {/* Save */}
        <Button
          onClick={handleSave}
          disabled={upsertSettings.isPending}
        >
          {upsertSettings.isPending ? "Saving..." : "Save Changes"}
        </Button>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Star, Info, Loader2, ExternalLink } from "lucide-react";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";

interface ReviewSettings {
  auto_send_reviews: boolean;
  review_delay_hours: number;
  review_channel: "sms" | "email" | "both";
  google_review_url: string;
  yelp_review_url: string;
}

export function ReviewRequestSettings() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  const [settings, setSettings] = useState<ReviewSettings>({
    auto_send_reviews: false,
    review_delay_hours: 24,
    review_channel: "both",
    google_review_url: "",
    yelp_review_url: "",
  });

  useEffect(() => {
    if (tenant?.id) {
      loadSettings();
    }
  }, [tenant?.id]);

  const loadSettings = async () => {
    try {
      const { data } = await supabase
        .from("tenants")
        .select("auto_send_reviews, review_delay_hours, review_channel, google_review_url, yelp_review_url")
        .eq("id", tenant?.id)
        .single();

      if (data) {
        setSettings({
          auto_send_reviews: data.auto_send_reviews ?? false,
          review_delay_hours: data.review_delay_hours ?? 24,
          review_channel: (data.review_channel as "sms" | "email" | "both") ?? "both",
          google_review_url: data.google_review_url ?? "",
          yelp_review_url: data.yelp_review_url ?? "",
        });
      }
    } catch (err) {
      console.error("Error loading review settings:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const saveSettings = async () => {
    if (!tenant?.id) return;

    setIsSaving(true);
    try {
      const { error } = await supabase
        .from("tenants")
        .update({
          auto_send_reviews: settings.auto_send_reviews,
          review_delay_hours: settings.review_delay_hours,
          review_channel: settings.review_channel,
          google_review_url: settings.google_review_url,
          yelp_review_url: settings.yelp_review_url,
        })
        .eq("id", tenant.id);

      if (error) throw error;

      toast({
        title: "Settings saved",
        description: "Review request settings have been updated.",
      });
    } catch (err: any) {
      toast({
        title: "Error",
        description: err.message || "Failed to save settings",
        variant: "destructive",
      });
    } finally {
      setIsSaving(false);
    }
  };

  if (isLoading) {
    return (
      <Card>
        <CardContent className="flex items-center justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="text-yellow-500">
              <Star className="h-5 w-5 fill-yellow-500" />
            </div>
            <div>
              <CardTitle className="text-base">Review Requests</CardTitle>
              <CardDescription className="text-xs">
                Automatically request reviews after completed jobs
              </CardDescription>
            </div>
          </div>
          <Badge variant={settings.auto_send_reviews ? "default" : "secondary"}>
            {settings.auto_send_reviews ? "Active" : "Off"}
          </Badge>
        </div>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Auto-send toggle */}
        <div className="flex items-center justify-between py-2 border-b">
          <div className="flex items-center gap-2">
            <Label htmlFor="auto-reviews" className="font-medium">
              Auto-send review requests
            </Label>
            <Tooltip>
              <TooltipTrigger asChild>
                <Info className="h-3 w-3 text-muted-foreground cursor-help" />
              </TooltipTrigger>
              <TooltipContent className="max-w-[250px]">
                <p>
                  Automatically send review request to customers after a job is marked complete.
                </p>
              </TooltipContent>
            </Tooltip>
          </div>
          <Switch
            id="auto-reviews"
            checked={settings.auto_send_reviews}
            onCheckedChange={(checked) =>
              setSettings((prev) => ({ ...prev, auto_send_reviews: checked }))
            }
          />
        </div>

        {settings.auto_send_reviews && (
          <>
            {/* Delay setting */}
            <div className="space-y-2">
              <Label htmlFor="delay">Send request after</Label>
              <Select
                value={settings.review_delay_hours.toString()}
                onValueChange={(value) =>
                  setSettings((prev) => ({ ...prev, review_delay_hours: parseInt(value) }))
                }
              >
                <SelectTrigger id="delay">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="1">1 hour</SelectItem>
                  <SelectItem value="2">2 hours</SelectItem>
                  <SelectItem value="4">4 hours</SelectItem>
                  <SelectItem value="24">24 hours (recommended)</SelectItem>
                  <SelectItem value="48">48 hours</SelectItem>
                </SelectContent>
              </Select>
            </div>

            {/* Channel setting */}
            <div className="space-y-2">
              <Label htmlFor="channel">Send via</Label>
              <Select
                value={settings.review_channel}
                onValueChange={(value: "sms" | "email" | "both") =>
                  setSettings((prev) => ({ ...prev, review_channel: value }))
                }
              >
                <SelectTrigger id="channel">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="sms">SMS only</SelectItem>
                  <SelectItem value="email">Email only</SelectItem>
                  <SelectItem value="both">Both SMS and Email</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </>
        )}

        {/* Review URLs */}
        <div className="space-y-4 pt-4 border-t">
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <Label htmlFor="google-url">Google Review URL</Label>
              <a
                href="https://support.google.com/business/answer/7035772"
                target="_blank"
                rel="noopener noreferrer"
                className="text-xs text-muted-foreground hover:text-primary flex items-center gap-1"
              >
                How to find <ExternalLink className="h-3 w-3" />
              </a>
            </div>
            <Input
              id="google-url"
              type="url"
              placeholder="https://g.page/r/..."
              value={settings.google_review_url}
              onChange={(e) =>
                setSettings((prev) => ({ ...prev, google_review_url: e.target.value }))
              }
            />
          </div>

          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <Label htmlFor="yelp-url">Yelp Review URL</Label>
              <a
                href="https://biz.yelp.com"
                target="_blank"
                rel="noopener noreferrer"
                className="text-xs text-muted-foreground hover:text-primary flex items-center gap-1"
              >
                Find on Yelp <ExternalLink className="h-3 w-3" />
              </a>
            </div>
            <Input
              id="yelp-url"
              type="url"
              placeholder="https://www.yelp.com/writeareview/biz/..."
              value={settings.yelp_review_url}
              onChange={(e) =>
                setSettings((prev) => ({ ...prev, yelp_review_url: e.target.value }))
              }
            />
          </div>
        </div>

        {/* Save button */}
        <div className="flex justify-end pt-4">
          <Button onClick={saveSettings} disabled={isSaving}>
            {isSaving && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
            Save Settings
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import {
  Users,
  CreditCard,
  Bell,
  Shield,
  Webhook,
  Zap,
  Bug,
  AlertTriangle,
  ChevronDown,
  ChevronRight,
  DollarSign,
  RefreshCw,
  MessageSquare,
  Network,
} from "lucide-react";
import { SettingsNavItem } from "./SettingsNavItem";
import { cn } from "@/lib/utils";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";

export interface SettingsNavConfig {
  showHipaa: boolean;
  showBookingDelivery: boolean;
  showDispatchDelivery: boolean;
  showFoodSettings: boolean;
  showRecovery: boolean;
  showReferralNetwork: boolean;
  hasCallData?: boolean;
  isSuperAdmin?: boolean;
}

interface SettingsSidebarProps {
  activeSection: string;
  onSectionChange: (section: string) => void;
  config: SettingsNavConfig;
  complexityTier?: "simple" | "standard" | "complex";
}

interface NavGroup {
  id: string;
  label: string;
  colorClass: string;
  items: NavItem[];
}

interface NavItem {
  id: string;
  label: string;
  icon: typeof Users;
  visible?: boolean;
}

export function SettingsSidebar({ activeSection, onSectionChange, config, complexityTier }: SettingsSidebarProps) {
  // For simple businesses, collapse advanced sections by default
  const isSimple = complexityTier === "simple";
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(!isSimple);
  const [aiFeaturesOpen, setAiFeaturesOpen] = useState(!isSimple);

  // Simplified nav groups: Account, Data & Privacy, Notifications, Advanced
  const navGroups: NavGroup[] = [
    {
      id: "account",
      label: "Account",
      colorClass: "text-primary",
      items: [
        { id: "team", label: "Team Members", icon: Users },
        { id: "plan", label: "Plan & Billing", icon: CreditCard },
        { id: "revenue", label: "Revenue Tracking", icon: DollarSign, visible: config.hasCallData === true },
      ],
    },
    {
      id: "data-privacy",
      label: "Data & Privacy",
      colorClass: "text-violet-500",
      items: [
        { id: "data-privacy", label: "Data Controls", icon: Shield },
      ],
    },
    {
      id: "notifications",
      label: "Notifications",
      colorClass: "text-amber-500",
      items: [
        { id: "alerts", label: "Alerts", icon: Bell },
        { id: "integrations", label: "Integrations", icon: Webhook },
        { id: "automation", label: "Automation", icon: Zap },
      ],
    },
    {
      id: "ai-features",
      label: "AI Features",
      colorClass: "text-emerald-500",
      items: [
        { id: "sms", label: "SMS Messaging (Coming Soon)", icon: MessageSquare },
        { id: "recovery", label: "Lead Recovery", icon: RefreshCw, visible: config.showRecovery },
        { id: "referral-network", label: "Referral Network", icon: Network, visible: config.showReferralNetwork },
      ],
    },
  ];

  return (
    <aside className="w-64 shrink-0 border-r border-border/20 bg-sidebar/95 backdrop-blur-md p-4 space-y-6 hidden md:block">
      <div className="font-semibold text-lg px-3 text-foreground/90">Settings</div>

      <nav className="space-y-4">
        {navGroups.map((group) => {
          const visibleItems = group.items.filter((item) => item.visible !== false);
          if (visibleItems.length === 0) return null;

          // For simple tier, make Notifications and AI Features collapsible
          const isCollapsibleGroup = isSimple && (group.id === "notifications" || group.id === "ai-features");
          const groupOpen = group.id === "notifications" ? notificationsOpen : group.id === "ai-features" ? aiFeaturesOpen : true;
          const setGroupOpen = group.id === "notifications" ? setNotificationsOpen : group.id === "ai-features" ? setAiFeaturesOpen : undefined;
          const hasActiveChild = visibleItems.some((item) => activeSection === item.id);

          if (isCollapsibleGroup && setGroupOpen) {
            return (
              <Collapsible key={group.id} open={groupOpen || hasActiveChild} onOpenChange={setGroupOpen}>
                <CollapsibleTrigger className="flex items-center gap-2 w-full px-3 py-1.5 text-[11px] font-semibold text-muted-foreground/60 uppercase tracking-wider hover:text-foreground transition-colors">
                  {groupOpen || hasActiveChild ? (
                    <ChevronDown className="h-3 w-3" />
                  ) : (
                    <ChevronRight className="h-3 w-3" />
                  )}
                  {group.label}
                </CollapsibleTrigger>
                <CollapsibleContent className="space-y-1 pt-1">
                  {visibleItems.map((item) => (
                    <SettingsNavItem
                      key={item.id}
                      icon={item.icon}
                      label={item.label}
                      isActive={activeSection === item.id}
                      onClick={() => onSectionChange(item.id)}
                    />
                  ))}
                </CollapsibleContent>
              </Collapsible>
            );
          }

          return (
            <div key={group.id} className="space-y-1">
              <div className="text-[11px] font-semibold px-3 py-1.5 uppercase tracking-wider text-muted-foreground/60">
                {group.label}
              </div>
              {visibleItems.map((item) => (
                <SettingsNavItem
                  key={item.id}
                  icon={item.icon}
                  label={item.label}
                  isActive={activeSection === item.id}
                  onClick={() => onSectionChange(item.id)}
                />
              ))}
            </div>
          );
        })}

        {/* Advanced Section - Only for super admins */}
        {config.isSuperAdmin && (
          <Collapsible open={advancedOpen || activeSection === "developer" || activeSection === "danger"} onOpenChange={setAdvancedOpen}>
            <CollapsibleTrigger className="flex items-center gap-2 w-full px-3 py-1.5 text-[11px] font-semibold text-muted-foreground/60 uppercase tracking-wider hover:text-foreground transition-colors">
              {advancedOpen || activeSection === "developer" || activeSection === "danger" ? (
                <ChevronDown className="h-3 w-3" />
              ) : (
                <ChevronRight className="h-3 w-3" />
              )}
              Advanced
            </CollapsibleTrigger>
            <CollapsibleContent className="space-y-1 pt-1">
              <SettingsNavItem
                icon={Bug}
                label="Developer Tools"
                isActive={activeSection === "developer"}
                onClick={() => onSectionChange("developer")}
              />
              <SettingsNavItem
                icon={AlertTriangle}
                label="Danger Zone"
                isActive={activeSection === "danger"}
                onClick={() => onSectionChange("danger")}
              />
            </CollapsibleContent>
          </Collapsible>
        )}
      </nav>
    </aside>
  );
}

