  { key: "{{appointment_date}}", desc: "Appointment date" },
  { key: "{{appointment_time}}", desc: "Appointment time" },
  { key: "{{service_name}}", desc: "Service booked" },
  { key: "{{review_link}}", desc: "Review page link" },
];

export function SmsSettingsSection() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  // Fetch A2P status
  const { data: a2pStatus } = useQuery({
    queryKey: ["a2p-status", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data, error } = await supabase
        .from("a2p_registrations")
        .select("status, failure_reason, toll_free_verified")
        .eq("tenant_id", tenant.id)
        .maybeSingle();
      if (error) throw error;
      return data;
    },
    enabled: !!tenant?.id,
    refetchInterval: 60_000,
  });

  // Fetch settings from assistant_settings.settings_json
  const { data: assistantSettings } = useQuery({
    queryKey: ["assistant-settings-sms", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data, error } = await supabase
        .from("assistant_settings")
        .select("settings_json")
        .eq("tenant_id", tenant.id)
        .maybeSingle();
      if (error) throw error;
      return data;
    },
    enabled: !!tenant?.id,
  });

  // Fetch review link from tenants table
  const { data: tenantData } = useQuery({
    queryKey: ["tenant-review-link", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data, error } = await supabase
        .from("tenants")
        .select("review_link")
        .eq("id", tenant.id)
        .single();
      if (error) throw error;
      return data;
    },
    enabled: !!tenant?.id,
  });

  const savedSmsSettings = (assistantSettings?.settings_json as any)?.sms_templates as SmsSettings | undefined;
  const [settings, setSettings] = useState<SmsSettings>(DEFAULT_SETTINGS);
  const [reviewLink, setReviewLink] = useState("");
  const [isDirty, setIsDirty] = useState(false);

  // Sync from server when data loads
  useEffect(() => {
    if (savedSmsSettings) {
      setSettings(savedSmsSettings);
    }
  }, [savedSmsSettings]);

  useEffect(() => {
    if (tenantData?.review_link) {
      setReviewLink(tenantData.review_link);
    }
  }, [tenantData?.review_link]);

  const saveMutation = useMutation({
    mutationFn: async (newSettings: SmsSettings) => {
      if (!tenant?.id) throw new Error("No tenant");

      // Save SMS templates to assistant_settings
      const existingJson = (assistantSettings?.settings_json as Record<string, unknown>) || {};
      const updatedJson = JSON.parse(JSON.stringify({ ...existingJson, sms_templates: newSettings }));
      const { error: settingsError } = await supabase
        .from("assistant_settings")
        .update({
          settings_json: updatedJson,
          updated_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant.id);
      if (settingsError) throw settingsError;

      // Save review link to tenants table
      if (reviewLink !== (tenantData?.review_link || "")) {
        const { error: tenantError } = await supabase
          .from("tenants")
          .update({ review_link: reviewLink || null })
          .eq("id", tenant.id);
        if (tenantError) throw tenantError;
      }
    },
    onSuccess: () => {
      toast.success("SMS settings saved");
      setIsDirty(false);
      queryClient.invalidateQueries({ queryKey: ["assistant-settings-sms"] });
      queryClient.invalidateQueries({ queryKey: ["tenant-review-link"] });
    },
    onError: () => toast.error("Failed to save SMS settings"),
  });

  const updateTemplate = (
    key: keyof SmsSettings,
    field: keyof SmsTemplate,
    value: string | boolean | number
  ) => {
    setSettings((prev) => ({
      ...prev,
      [key]: { ...prev[key], [field]: value },
    }));
    setIsDirty(true);
  };

  const isApproved = a2pStatus?.status === "approved";
  const isTollFreeActive = a2pStatus?.toll_free_verified && !isApproved;
  const canSend = isApproved || isTollFreeActive;
  const isPending = a2pStatus && !["approved", "failed"].includes(a2pStatus.status) && !isTollFreeActive;
  const noRegistration = !a2pStatus;

  return (
    <div className="space-y-6">
      {/* Registration Status Banner */}
      <SettingsCard
        title="SMS Registration Status"
        description="Your number must be registered for A2P 10DLC compliance before sending SMS."
      >
        <div className="space-y-3">
          <div className="flex items-center gap-3">
            <SmsRegistrationStatus />
          </div>
          {canSend && (
            <div className="flex items-center gap-2 text-sm">
              <Badge variant={isApproved ? "default" : "secondary"} className="text-xs">
                {isApproved ? "Sending via 10DLC" : "Sending via Toll-Free"}
              </Badge>
              {isTollFreeActive && (
                <span className="text-muted-foreground text-xs">
                  Messages route via toll-free while 10DLC registration completes
                </span>
              )}
            </div>
          )}
          {isPending && (
            <p className="text-sm text-muted-foreground">
              Registration is in progress. You can configure templates now — they'll activate once a channel is verified.
            </p>
          )}
          {noRegistration && (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <AlertCircle className="h-4 w-4 text-destructive" />
              <span>
                Complete your business identity in onboarding to start SMS registration.
              </span>
            </div>
          )}
          {a2pStatus?.status === "failed" && (
            <div className="text-sm text-destructive">
              <p>Registration failed: {a2pStatus.failure_reason}</p>
              <p className="text-muted-foreground mt-1">Contact support for assistance.</p>
            </div>
          )}
        </div>
      </SettingsCard>

      {/* Template Variables Reference */}
      <SettingsCard
        title="Available Variables"
        description="Use these placeholders in your message templates."
      >
        <div className="flex flex-wrap gap-2">
          {TEMPLATE_VARIABLES.map((v) => (
            <Badge key={v.key} variant="secondary" className="gap-1 font-mono text-xs">
              {v.key}
              <span className="font-sans text-muted-foreground">— {v.desc}</span>
            </Badge>
          ))}
        </div>
      </SettingsCard>

      {/* Appointment Confirmation */}
      <SettingsCard
        title="Appointment Confirmation"
        description="Sent immediately when a booking is confirmed."
        onSave={() => saveMutation.mutate(settings)}
        isSaving={saveMutation.isPending}
        isDirty={isDirty}
      >
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <CalendarCheck className="h-4 w-4 text-primary" />
              <Label>Send confirmation SMS</Label>
            </div>
            <Switch
              checked={settings.appointment_confirmation.enabled}
              onCheckedChange={(v) => updateTemplate("appointment_confirmation", "enabled", v)}
            />
          </div>
          {settings.appointment_confirmation.enabled && (
            <div className="space-y-2">
              <Label className="text-sm text-muted-foreground">Message template</Label>
              <Textarea
                value={settings.appointment_confirmation.message}
                onChange={(e) =>
                  updateTemplate("appointment_confirmation", "message", e.target.value)
                }
                rows={3}
                className="font-mono text-sm"
                placeholder="Type your confirmation message..."
              />
              <p className="text-xs text-muted-foreground">
                {settings.appointment_confirmation.message.length}/1600 characters
              </p>
            </div>
          )}
        </div>
      </SettingsCard>

      {/* Appointment Reminder */}
      <SettingsCard
        title="Appointment Reminder"
        description="Sent before the appointment to reduce no-shows."
        onSave={() => saveMutation.mutate(settings)}
        isSaving={saveMutation.isPending}
        isDirty={isDirty}
      >
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Bell className="h-4 w-4 text-muted-foreground" />
              <Label>Send reminder SMS</Label>
            </div>
            <Switch
              checked={settings.appointment_reminder.enabled}
              onCheckedChange={(v) => updateTemplate("appointment_reminder", "enabled", v)}
            />
          </div>
          {settings.appointment_reminder.enabled && (
            <div className="space-y-4">
              <div className="space-y-2">
                <Label className="text-sm text-muted-foreground">Send reminder</Label>
                <select
                  value={settings.appointment_reminder.delayMinutes}
                  onChange={(e) =>
                    updateTemplate("appointment_reminder", "delayMinutes", Number(e.target.value))
                  }
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  {REMINDER_OPTIONS.map((opt) => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label className="text-sm text-muted-foreground">Message template</Label>
                <Textarea
                  value={settings.appointment_reminder.message}
                  onChange={(e) =>
                    updateTemplate("appointment_reminder", "message", e.target.value)
                  }
                  rows={3}
                  className="font-mono text-sm"
                  placeholder="Type your reminder message..."
                />
                <p className="text-xs text-muted-foreground">
                  {settings.appointment_reminder.message.length}/1600 characters
                </p>
              </div>
            </div>
          )}
        </div>
      </SettingsCard>

      {/* Review Request */}
      <SettingsCard
        title="Review Request"
        description="Ask for a review after the appointment is completed."
        onSave={() => saveMutation.mutate(settings)}
        isSaving={saveMutation.isPending}
        isDirty={isDirty}
      >
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Star className="h-4 w-4 text-primary" />
              <Label>Send review request SMS</Label>
            </div>
            <Switch
              checked={settings.review_request.enabled}
              onCheckedChange={(v) => updateTemplate("review_request", "enabled", v)}
            />
          </div>
          {settings.review_request.enabled && (
            <div className="space-y-4">
              <div className="space-y-2">
                <Label className="text-sm text-muted-foreground">Send review request</Label>
                <select
                  value={settings.review_request.delayMinutes}
                  onChange={(e) =>
                    updateTemplate("review_request", "delayMinutes", Number(e.target.value))
                  }
                  className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                >
                  {REVIEW_DELAY_OPTIONS.map((opt) => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
              </div>
              <div className="space-y-2">
                <Label className="text-sm text-muted-foreground">Review link URL</Label>
                <Input
                  value={reviewLink}
                  onChange={(e) => {
                    setReviewLink(e.target.value);
                    setIsDirty(true);
                  }}
                  placeholder="https://g.page/your-business/review"
                />
                <p className="text-xs text-muted-foreground flex items-center gap-1">
                  <Info className="h-3 w-3" />
                  Paste your Google, Yelp, or other review page link
                </p>
              </div>
              <div className="space-y-2">
                <Label className="text-sm text-muted-foreground">Message template</Label>
                <Textarea
                  value={settings.review_request.message}
                  onChange={(e) =>
                    updateTemplate("review_request", "message", e.target.value)
                  }
                  rows={3}
                  className="font-mono text-sm"
                  placeholder="Type your review request message..."
                />
                <p className="text-xs text-muted-foreground">
                  {settings.review_request.message.length}/1600 characters
                </p>
              </div>
            </div>
          )}
        </div>
      </SettingsCard>
    </div>
  );
}

import { useState, useCallback } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Slider } from "@/components/ui/slider";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { useToast } from "@/hooks/use-toast";
import {
  Phone,
  MessageSquare,
  Mic,
  PhoneCall,
  Check,
  Copy,
  Loader2,
  ArrowRight,
  Settings,
} from "lucide-react";
import VoiceAgentTest from "@/components/ai/VoiceAgentTest";

interface QuickSetupWizardProps {
  onComplete?: () => void;
}

export default function QuickSetupWizard({ onComplete }: QuickSetupWizardProps) {
  const { effectiveTenantId } = useAuth();
  const { toast } = useToast();
  
  // Phone connection state
  const [phoneNumber, setPhoneNumber] = useState("");
  const [testPhoneNumber, setTestPhoneNumber] = useState("");
  const [phoneConnected, setPhoneConnected] = useState(false);
  const [copied, setCopied] = useState(false);
  
  // AI settings state (Agent ID is managed globally via environment variable)
  const [textBackEnabled, setTextBackEnabled] = useState(true);
  const [textBackDelay, setTextBackDelay] = useState([30]); // seconds
  
  // Loading states
  const [connecting, setConnecting] = useState(false);
  const [callingPhone, setCallingPhone] = useState(false);
  const [saving, setSaving] = useState(false);

  // Mock forwarding number
  const forwardingNumber = "+1 (555) 123-4567";

  const copyForwardingNumber = () => {
    navigator.clipboard.writeText(forwardingNumber.replace(/\D/g, ""));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    toast({ title: "Copied!", description: "Forwarding number copied to clipboard" });
  };

  const handleConnectPhone = async () => {
    if (!effectiveTenantId || !phoneNumber.trim()) return;
    
    setConnecting(true);
    try {
      const { error } = await supabase
        .from("assistant_settings")
        .upsert({
          tenant_id: effectiveTenantId,
          business_phone_number: phoneNumber.trim(),
          phone_connected: true,
          sms_first_delay_seconds: textBackDelay[0],
          instant_text_enabled: textBackEnabled,
          updated_at: new Date().toISOString(),
        }, {
          onConflict: "tenant_id",
        });

      if (error) throw error;

      setPhoneConnected(true);
      toast({
        title: "Phone Connected! ✅",
        description: "Now set up call forwarding to complete the setup.",
      });
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Connection Failed",
        description: error.message,
      });
    } finally {
      setConnecting(false);
    }
  };

  const handleTestCallToPhone = async () => {
    if (!testPhoneNumber.trim()) {
      toast({
        variant: "destructive",
        title: "Enter phone number",
        description: "Please enter the phone number to call",
      });
      return;
    }

    setCallingPhone(true);
    try {
      // Agent ID is now managed server-side
      const { data, error } = await supabase.functions.invoke("test-call-phone", {
        body: { 
          tenantId: effectiveTenantId, 
          phoneNumber: testPhoneNumber.trim(),
        },
      });

      if (error) {
        // Show exact error reason for debugging
        const errorDetail = error.message || "Unknown error";
        toast({
          variant: "destructive",
          title: "Test Call Failed",
          description: `${errorDetail}. Check /debug/telephony for details.`,
        });
        return;
      }

      if (data?.error) {
        // Handle non-2xx response that still returned JSON
        toast({
          variant: "destructive",
          title: "Test Call Error",
          description: data.error,
        });
        return;
      }

      toast({
        title: "📞 Test Call Initiated",
        description: data?.message || "Your phone should ring in a few seconds. Answer to talk to your AI!",
      });
    } catch (error: any) {
      // Show full error for troubleshooting
      const errorMessage = error?.message || String(error);
      toast({
        variant: "destructive",
        title: "Test Call Failed",
        description: `Error: ${errorMessage}. Visit /debug/telephony for troubleshooting.`,
      });
    } finally {
      setCallingPhone(false);
    }
  };

  const handleSaveSettings = async () => {
    if (!effectiveTenantId) return;
    
    setSaving(true);
    try {
      // Save assistant settings
      const { error: settingsError } = await supabase
        .from("assistant_settings")
        .upsert({
          tenant_id: effectiveTenantId,
          sms_first_delay_seconds: textBackDelay[0],
          instant_text_enabled: textBackEnabled,
          updated_at: new Date().toISOString(),
        }, {
          onConflict: "tenant_id",
        });

      if (settingsError) throw settingsError;

      toast({ title: "Settings Saved!" });
      onComplete?.();
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Save Failed",
        description: error.message,
      });
    } finally {
      setSaving(false);
    }
  };

  const formatDelay = (seconds: number) => {
    if (seconds === 0) return "Instantly";
    if (seconds < 60) return `${seconds} seconds`;
    return `${Math.floor(seconds / 60)} minute${seconds >= 120 ? 's' : ''}`;
  };

  return (
    <div className="space-y-6">
      <Tabs defaultValue="connect" className="w-full">
        <TabsList className="grid w-full grid-cols-3">
          <TabsTrigger value="connect" className="gap-2">
            <Phone className="h-4 w-4" />
            <span className="hidden sm:inline">Connect Phone</span>
            <span className="sm:hidden">Phone</span>
          </TabsTrigger>
          <TabsTrigger value="test" className="gap-2">
            <Mic className="h-4 w-4" />
            <span className="hidden sm:inline">Test AI</span>
            <span className="sm:hidden">Test</span>
          </TabsTrigger>
          <TabsTrigger value="settings" className="gap-2">
            <Settings className="h-4 w-4" />
            <span className="hidden sm:inline">Settings</span>
            <span className="sm:hidden">Settings</span>
          </TabsTrigger>
        </TabsList>

        {/* Step 1: Connect Phone */}
        <TabsContent value="connect" className="space-y-4 mt-6">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Phone className="h-5 w-5" />
                Connect Your Business Phone
              </CardTitle>
              <CardDescription>
                Enter your business phone number and set up call forwarding
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Phone number input */}
              <div className="space-y-2">
                <Label htmlFor="business-phone">Your Business Phone Number</Label>
                <Input
                  id="business-phone"
                  type="tel"
                  placeholder="+1 (555) 123-4567"
                  value={phoneNumber}
                  onChange={(e) => setPhoneNumber(e.target.value)}
                  disabled={phoneConnected}
                />
              </div>

              {!phoneConnected ? (
                <Button
                  onClick={handleConnectPhone}
                  disabled={connecting || !phoneNumber.trim()}
                  className="w-full"
                >
                  {connecting ? (
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  ) : (
                    <ArrowRight className="mr-2 h-4 w-4" />
                  )}
                  Connect Number
                </Button>
              ) : (
                <>
                  <div className="flex items-center gap-2 text-primary">
                    <Check className="h-5 w-5" />
                    <span className="font-medium">Phone number connected!</span>
                  </div>

                  {/* Call forwarding instructions */}
                  <div className="rounded-lg border bg-muted/50 p-4 space-y-4">
                    <p className="font-medium">Set up call forwarding:</p>
                    <ol className="space-y-3 text-sm">
                      <li className="flex items-start gap-3">
                        <Badge variant="outline" className="shrink-0 mt-0.5">1</Badge>
                        <span>Go to your phone carrier settings or dial *72</span>
                      </li>
                      <li className="flex items-start gap-3">
                        <Badge variant="outline" className="shrink-0 mt-0.5">2</Badge>
                        <span>Enable call forwarding when busy or unanswered</span>
                      </li>
                      <li className="flex items-start gap-3">
                        <Badge variant="outline" className="shrink-0 mt-0.5">3</Badge>
                        <div className="flex-1">
                          <span>Forward calls to:</span>
                          <div className="flex items-center gap-2 mt-2">
                            <code className="bg-background px-3 py-1.5 rounded text-sm font-mono">
                              {forwardingNumber}
                            </code>
                            <Button
                              size="sm"
                              variant="ghost"
                              onClick={copyForwardingNumber}
                            >
                              {copied ? (
                                <Check className="h-4 w-4 text-primary" />
                              ) : (
                                <Copy className="h-4 w-4" />
                              )}
                            </Button>
                          </div>
                        </div>
                      </li>
                    </ol>
                  </div>
                </>
              )}
            </CardContent>
          </Card>
        </TabsContent>

        {/* Step 2: Test AI */}
        <TabsContent value="test" className="space-y-4 mt-6">
          <div className="grid md:grid-cols-2 gap-4">
            {/* Browser Test */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-lg">
                  <Mic className="h-5 w-5" />
                  Browser Test
                </CardTitle>
                <CardDescription>
                  Speak directly to your AI in the browser
                </CardDescription>
              </CardHeader>
              <CardContent>
                <VoiceAgentTest />
              </CardContent>
            </Card>

            {/* Phone Test */}
            <Card>
              <CardHeader>
                <CardTitle className="flex items-center gap-2 text-lg">
                  <PhoneCall className="h-5 w-5" />
                  Call My Phone
                </CardTitle>
                <CardDescription>
                  Have your AI call you to experience it as a customer would
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="test-phone">Your Phone Number</Label>
                  <Input
                    id="test-phone"
                    type="tel"
                    placeholder="+1 (555) 123-4567"
                    value={testPhoneNumber}
                    onChange={(e) => setTestPhoneNumber(e.target.value)}
                  />
                </div>

                <Button
                  onClick={handleTestCallToPhone}
                  disabled={callingPhone || !testPhoneNumber.trim()}
                  className="w-full"
                  variant="outline"
                >
                  {callingPhone ? (
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  ) : (
                    <PhoneCall className="mr-2 h-4 w-4" />
                  )}
                  Call My Phone
                </Button>

                <p className="text-xs text-muted-foreground text-center">
                  Demo mode: Real calls require Twilio integration
                </p>
              </CardContent>
            </Card>
          </div>
        </TabsContent>

        {/* Step 3: Settings */}
        <TabsContent value="settings" className="space-y-4 mt-6">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <MessageSquare className="h-5 w-5" />
                Missed Call Text-Back
              </CardTitle>
              <CardDescription>
                Automatically send an AI-generated text when calls are missed
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              {/* Enable toggle */}
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label>Auto Text-Back</Label>
                  <p className="text-sm text-muted-foreground">
                    Send AI message when calls go unanswered
                  </p>
                </div>
                <Switch
                  checked={textBackEnabled}
                  onCheckedChange={setTextBackEnabled}
                />
              </div>

              {/* Delay slider */}
              {textBackEnabled && (
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <Label>Response Delay</Label>
                    <Badge variant="secondary">
                      {formatDelay(textBackDelay[0])}
                    </Badge>
                  </div>
                  <Slider
                    value={textBackDelay}
                    onValueChange={setTextBackDelay}
                    max={120}
                    min={0}
                    step={10}
                    className="w-full"
                  />
                  <p className="text-xs text-muted-foreground">
                    Wait time after missed call before sending text (0 = instant)
                  </p>
                </div>
              )}
            </CardContent>
          </Card>

          <Button
            onClick={handleSaveSettings}
            disabled={saving}
            className="w-full"
            size="lg"
          >
            {saving ? (
              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
            ) : (
              <Check className="mr-2 h-4 w-4" />
            )}
            Save & Go Live
          </Button>
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { useToast } from "@/hooks/use-toast";
import { 
  Brain, Search, MessageSquare, ChevronDown, 
  Loader2, AlertTriangle, CheckCircle2, Info
} from "lucide-react";

interface KnowledgeSnippet {
  source_type: string;
  id: string;
  title: string;
  content: string;
  relevance_score: number;
}

interface ResponsePlan {
  intent: string;
  confidence: string;
  required_info_to_collect: string[];
  facts_to_use: Array<{ source: string; content: string }>;
  policy_constraints: string[];
  guardrails_applied: string[];
  next_action: string;
  draft_reply: string;
  sources_used: Array<{ type: string; id: string }>;
  knowledge_gap_detected: boolean;
  gap_description?: string;
}

export default function AIBrainDebugger() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  
  const [testMessage, setTestMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const [brain, setBrain] = useState<any>(null);
  const [snippets, setSnippets] = useState<KnowledgeSnippet[]>([]);
  const [plan, setPlan] = useState<ResponsePlan | null>(null);
  const [brainOpen, setBrainOpen] = useState(false);
  const [snippetsOpen, setSnippetsOpen] = useState(true);

  const loadBrain = async () => {
    if (!tenant?.id) return;
    
    setLoading(true);
    try {
      const { data, error } = await supabase.functions.invoke('build-business-brain', {
        body: { tenantId: tenant.id },
      });

      if (error) throw error;
      setBrain(data.brain);
      toast({ title: "Business brain loaded!" });
    } catch (error: any) {
      toast({ 
        variant: "destructive", 
        title: "Failed to load brain",
        description: error.message,
      });
    } finally {
      setLoading(false);
    }
  };

  const testQuery = async () => {
    if (!tenant?.id || !testMessage.trim()) return;

    setLoading(true);
    try {
      // Call the response planner which internally calls brain and retrieval
      const { data, error } = await supabase.functions.invoke('ai-plan-response', {
        body: { 
          tenantId: tenant.id, 
          userMessage: testMessage,
          channel: 'call',
        },
      });

      if (error) throw error;

      setPlan(data.plan);
      
      // Also fetch snippets directly for display
      const { data: knowledgeData } = await supabase.functions.invoke('retrieve-knowledge', {
        body: { 
          tenantId: tenant.id, 
          queryText: testMessage,
          intent: data.plan.intent,
          topK: 8,
        },
      });
      
      if (knowledgeData) {
        setSnippets(knowledgeData.snippets || []);
      }

      // Load brain if not already loaded
      if (!brain) {
        const { data: brainData } = await supabase.functions.invoke('build-business-brain', {
          body: { tenantId: tenant.id },
        });
        if (brainData) setBrain(brainData.brain);
      }

    } catch (error: any) {
      toast({ 
        variant: "destructive", 
        title: "Query failed",
        description: error.message,
      });
    } finally {
      setLoading(false);
    }
  };

  const confidenceColor = (confidence: string) => {
    switch (confidence) {
      case 'high': return 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200';
      case 'medium': return 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200';
      default: return 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200';
    }
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Brain className="h-5 w-5 text-primary" />
          AI Brain Debugger
        </CardTitle>
        <CardDescription>
          Test how your AI processes questions using real business data
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Test Input */}
        <div className="space-y-2">
          <Textarea
            value={testMessage}
            onChange={(e) => setTestMessage(e.target.value)}
            placeholder="Enter a customer question to test, e.g. 'How much do you charge for a detail?'"
            rows={3}
          />
          <div className="flex gap-2">
            <Button onClick={testQuery} disabled={loading || !testMessage.trim()} className="gap-2">
              {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}
              Test Query
            </Button>
            <Button variant="outline" onClick={loadBrain} disabled={loading}>
              Load Brain Only
            </Button>
          </div>
        </div>

        {/* Results */}
        {plan && (
          <Tabs defaultValue="response" className="w-full">
            <TabsList className="w-full justify-start">
              <TabsTrigger value="response" className="gap-1">
                <MessageSquare className="h-4 w-4" />
                Response
              </TabsTrigger>
              <TabsTrigger value="snippets" className="gap-1">
                <Search className="h-4 w-4" />
                Retrieved ({snippets.length})
              </TabsTrigger>
              <TabsTrigger value="brain" className="gap-1">
                <Brain className="h-4 w-4" />
                Brain
              </TabsTrigger>
            </TabsList>

            {/* Response Plan Tab */}
            <TabsContent value="response" className="space-y-4 mt-4">
              {/* Intent & Confidence */}
              <div className="flex flex-wrap gap-2">
                <Badge variant="outline">Intent: {plan.intent}</Badge>
                <Badge className={confidenceColor(plan.confidence)}>
                  Confidence: {plan.confidence}
                </Badge>
                <Badge variant="outline">Action: {plan.next_action}</Badge>
              </div>

              {/* Knowledge Gap Warning */}
              {plan.knowledge_gap_detected && (
                <div className="flex items-start gap-2 p-3 rounded-lg bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800">
                  <AlertTriangle className="h-5 w-5 text-yellow-600 flex-shrink-0 mt-0.5" />
                  <div>
                    <p className="font-medium text-yellow-800 dark:text-yellow-200">Knowledge Gap Detected</p>
                    <p className="text-sm text-yellow-700 dark:text-yellow-300">{plan.gap_description}</p>
                  </div>
                </div>
              )}

              {/* Draft Reply */}
              <div className="space-y-2">
                <p className="text-sm font-medium">AI Response:</p>
                <div className="p-4 rounded-lg bg-primary/5 border">
                  <p className="text-sm">{plan.draft_reply}</p>
                </div>
              </div>

              {/* Facts Used */}
              {plan.facts_to_use.length > 0 && (
                <div className="space-y-2">
                  <p className="text-sm font-medium">Facts Used:</p>
                  <div className="space-y-1">
                    {plan.facts_to_use.map((fact, i) => (
                      <div key={i} className="flex items-start gap-2 text-sm">
                        <Badge variant="secondary" className="shrink-0">{fact.source}</Badge>
                        <span className="text-muted-foreground line-clamp-2">{fact.content}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Policy Constraints */}
              {plan.policy_constraints.length > 0 && (
                <div className="space-y-2">
                  <p className="text-sm font-medium">Policies Applied:</p>
                  <ul className="text-sm text-muted-foreground list-disc list-inside">
                    {plan.policy_constraints.map((p, i) => (
                      <li key={i}>{p}</li>
                    ))}
                  </ul>
                </div>
              )}

              {/* Required Info */}
              {plan.required_info_to_collect.length > 0 && (
                <div className="space-y-2">
                  <p className="text-sm font-medium">Should Collect:</p>
                  <div className="flex flex-wrap gap-1">
                    {plan.required_info_to_collect.map((info, i) => (
                      <Badge key={i} variant="outline">{info}</Badge>
                    ))}
                  </div>
                </div>
              )}

              {/* Sources */}
              <div className="space-y-2">
                <p className="text-sm font-medium">Sources Used:</p>
                <div className="flex flex-wrap gap-1">
                  {plan.sources_used.map((s, i) => (
                    <Badge key={i} variant="secondary">{s.type}: {s.id.slice(0, 8)}</Badge>
                  ))}
                </div>
              </div>
            </TabsContent>

            {/* Retrieved Snippets Tab */}
            <TabsContent value="snippets" className="mt-4">
              <ScrollArea className="h-[400px]">
                <div className="space-y-3">
                  {snippets.length === 0 ? (
                    <p className="text-muted-foreground text-center py-8">
                      No relevant snippets found for this query.
                    </p>
                  ) : (
                    snippets.map((snippet, i) => (
                      <div key={i} className="border rounded-lg p-3 space-y-2">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            <Badge variant="outline">{snippet.source_type}</Badge>
                            <span className="font-medium text-sm">{snippet.title}</span>
                          </div>
                          <Badge className={
                            snippet.relevance_score > 0.6 ? 'bg-green-100 text-green-800' :
                            snippet.relevance_score > 0.3 ? 'bg-yellow-100 text-yellow-800' :
                            'bg-red-100 text-red-800'
                          }>
                            {(snippet.relevance_score * 100).toFixed(0)}%
                          </Badge>
                        </div>
                        <p className="text-sm text-muted-foreground">{snippet.content}</p>
                      </div>
                    ))
                  )}
                </div>
              </ScrollArea>
            </TabsContent>

            {/* Brain Tab */}
            <TabsContent value="brain" className="mt-4">
              {brain ? (
                <ScrollArea className="h-[400px]">
                  <pre className="text-xs bg-muted p-4 rounded-lg overflow-x-auto">
                    {JSON.stringify(brain, null, 2)}
                  </pre>
                </ScrollArea>
              ) : (
                <div className="text-center py-8 text-muted-foreground">
                  <Brain className="h-12 w-12 mx-auto mb-3 opacity-50" />
                  <p>Click "Load Brain Only" or run a test query to see the full business brain.</p>
                </div>
              )}
            </TabsContent>
          </Tabs>
        )}

        {/* Initial State */}
        {!plan && !loading && (
          <div className="text-center py-8 text-muted-foreground">
            <Info className="h-12 w-12 mx-auto mb-3 opacity-50" />
            <p>Enter a customer question above to see how your AI processes it.</p>
            <p className="text-sm mt-1">Shows: business brain, retrieved knowledge, response plan, and final reply.</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { resolveCustomer, createOpportunity, createSyncEvent } from "@/hooks/useCustomerResolver";
import { Phone, PhoneIncoming, PhoneOff, User, MessageCircle, Loader2, Brain, AlertTriangle, DollarSign } from "lucide-react";
import { computePriceQuote, detectPricingQuestion, type QuoteResult, type PricingRule } from "@/lib/computeQuote";
import { useQuery } from "@tanstack/react-query";

interface SimulatedMessage {
  role: 'customer' | 'ai';
  content: string;
  timestamp: Date;
  metadata?: {
    intent?: string;
    confidence?: string;
    sources?: Array<{ type: string; id: string }>;
    knowledgeGap?: boolean;
    priceQuote?: QuoteResult;
  };
}

export default function CallSimulator() {
  const { effectiveTenantId, effectiveTenant } = useAuth();
  const { toast } = useToast();
  
  const [callerPhone, setCallerPhone] = useState('');
  const [callerName, setCallerName] = useState('');
  const [callerEmail, setCallerEmail] = useState('');
  const [isCallActive, setIsCallActive] = useState(false);
  const [callLog, setCallLog] = useState<SimulatedMessage[]>([]);
  const [customerInput, setCustomerInput] = useState('');
  const [resolvedCustomer, setResolvedCustomer] = useState<{
    id: string;
    isNew: boolean;
    hasConflict: boolean;
  } | null>(null);
  const [opportunityId, setOpportunityId] = useState<string | null>(null);
  const [aiLoading, setAiLoading] = useState(false);

  // Fetch pricing rules from effective tenant (respects admin tenant switching)
  const { data: pricingRulesData } = useQuery({
    queryKey: ['tenant-pricing-rules', effectiveTenantId],
    queryFn: async () => {
      if (!effectiveTenantId) return null;
      const { data } = await supabase
        .from('tenants')
        .select('pricing_rules_jsonb, business_mode')
        .eq('id', effectiveTenantId)
        .single();
      return data;
    },
    enabled: !!effectiveTenantId,
  });

  const pricingRules: PricingRule[] = (pricingRulesData?.pricing_rules_jsonb as any) || [];
  const businessMode = pricingRulesData?.business_mode || effectiveTenant?.business_mode || 'service';

  // Listen for suggested test clicks from SuggestedTestsBanner
  useEffect(() => {
    const handleSuggestedTest = (event: CustomEvent<{ text: string }>) => {
      if (isCallActive && event.detail?.text) {
        setCustomerInput(event.detail.text);
      }
    };

    window.addEventListener('suggested-test-clicked', handleSuggestedTest as EventListener);
    return () => {
      window.removeEventListener('suggested-test-clicked', handleSuggestedTest as EventListener);
    };
  }, [isCallActive]);

  const getAIResponse = async (customerMessage: string): Promise<SimulatedMessage> => {
    if (!effectiveTenantId) {
      return {
        role: 'ai',
        content: "I'm sorry, I'm having trouble accessing the system. Let me have someone call you back.",
        timestamp: new Date(),
      };
    }

    // Detect pricing question and compute quote if applicable
    let priceQuote: QuoteResult | undefined;
    if (detectPricingQuestion(customerMessage)) {
      priceQuote = computePriceQuote({
        rules: pricingRules,
        businessMode: businessMode,
        offering: {
          serviceName: "General Service", // In real scenario, would extract from context
        },
        inputs: {}, // In real scenario, would extract from conversation
      });
    }

    try {
      const { data, error } = await supabase.functions.invoke('ai-plan-response', {
        body: {
          tenantId: effectiveTenantId,
          userMessage: customerMessage,
          channel: 'call',
          customerId: resolvedCustomer?.id,
        },
      });

      if (error) throw error;

      const plan = data.plan;

      return {
        role: 'ai',
        content: plan.draft_reply,
        timestamp: new Date(),
        metadata: {
          intent: plan.intent,
          confidence: plan.confidence,
          sources: plan.sources_used,
          knowledgeGap: plan.knowledge_gap_detected,
          priceQuote,
        },
      };
    } catch (error) {
      console.error('AI response error:', error);
      return {
        role: 'ai',
        content: "I'd be happy to help! Let me have someone call you back with more details.",
        timestamp: new Date(),
        metadata: { confidence: 'low', priceQuote },
      };
    }
  };

  const startCall = async () => {
    if (!effectiveTenantId) {
      toast({ variant: "destructive", title: "No business configured" });
      return;
    }

    if (!callerPhone) {
      toast({ variant: "destructive", title: "Please enter a phone number" });
      return;
    }

    setAiLoading(true);
    try {
      // Resolve customer through the unified pipeline
      const result = await resolveCustomer(
        effectiveTenantId,
        callerPhone,
        callerName || undefined,
        callerEmail || undefined,
        'inbound_call'
      );

      setResolvedCustomer({
        id: result.customer_id,
        isNew: result.is_new,
        hasConflict: result.has_conflict,
      });

      // Create opportunity for this call
      const oppId = await createOpportunity(
        effectiveTenantId,
        result.customer_id,
        'inbound_call',
        undefined,
        'Inbound call via simulator'
      );
      setOpportunityId(oppId);

      // Fire sync event
      await createSyncEvent(
        effectiveTenantId,
        result.is_new ? 'customer_created' : 'customer_updated',
        'customer',
        result.customer_id,
        { phone: callerPhone, name: callerName, source: 'simulator_call' }
      );

      // Get AI greeting
      const greetingResponse = await getAIResponse('Hello');
      
      setIsCallActive(true);
      setCallLog([greetingResponse]);

      toast({
        title: result.is_new ? "New customer created" : "Existing customer found",
        description: result.has_conflict 
          ? "Conflict detected - check merge queue" 
          : `Customer resolved successfully`,
      });

    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Failed to start call",
        description: error.message,
      });
    } finally {
      setAiLoading(false);
    }
  };

  const sendMessage = async () => {
    if (!customerInput.trim()) return;

    const customerMessage: SimulatedMessage = {
      role: 'customer',
      content: customerInput,
      timestamp: new Date(),
    };

    setCallLog(prev => [...prev, customerMessage]);
    setCustomerInput('');
    setAiLoading(true);

    const aiResponse = await getAIResponse(customerInput);
    setCallLog(prev => [...prev, aiResponse]);
    setAiLoading(false);
  };

  const endCall = async () => {
    if (effectiveTenantId && opportunityId) {
      await createSyncEvent(
        effectiveTenantId,
        'call_completed',
        'opportunity',
        opportunityId,
        { 
          duration_seconds: callLog.length * 10, 
          outcome: 'completed',
          message_count: callLog.length 
        }
      );
    }

    setIsCallActive(false);
    toast({ title: "Call ended", description: "Call session completed and logged" });
  };

  const resetSimulator = () => {
    setCallerPhone('');
    setCallerName('');
    setCallerEmail('');
    setCallLog([]);
    setResolvedCustomer(null);
    setOpportunityId(null);
    setIsCallActive(false);
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Phone className="h-5 w-5" />
          Call Simulator
          <Badge variant="secondary" className="gap-1">
            <Brain className="h-3 w-3" />
            AI-Powered
          </Badge>
        </CardTitle>
        <CardDescription>
          Test your AI voice assistant with real business data and knowledge retrieval
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {!isCallActive ? (
          <>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label htmlFor="phone">Caller Phone *</Label>
                <Input
                  id="phone"
                  placeholder="(555) 123-4567"
                  value={callerPhone}
                  onChange={(e) => setCallerPhone(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="name">Caller Name</Label>
                <Input
                  id="name"
                  placeholder="John Smith"
                  value={callerName}
                  onChange={(e) => setCallerName(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="email">Caller Email</Label>
                <Input
                  id="email"
                  type="email"
                  placeholder="john@example.com"
                  value={callerEmail}
                  onChange={(e) => setCallerEmail(e.target.value)}
                />
              </div>
            </div>
            
            <Button onClick={startCall} className="w-full gap-2" disabled={aiLoading}>
              {aiLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <PhoneIncoming className="h-4 w-4" />}
              {aiLoading ? "Connecting..." : "Simulate Inbound Call"}
            </Button>
          </>
        ) : (
          <>
            {/* Customer Info Banner */}
            {resolvedCustomer && (
              <div className="flex items-center gap-3 p-3 rounded-lg bg-secondary/50">
                <User className="h-5 w-5 text-primary" />
                <div className="flex-1">
                  <p className="font-medium">{callerName || 'Unknown Caller'}</p>
                  <p className="text-sm text-muted-foreground">{callerPhone}</p>
                </div>
                <div className="flex gap-2">
                  <Badge variant={resolvedCustomer.isNew ? "default" : "secondary"}>
                    {resolvedCustomer.isNew ? "New Customer" : "Returning"}
                  </Badge>
                  {resolvedCustomer.hasConflict && (
                    <Badge variant="destructive">Conflict</Badge>
                  )}
                </div>
              </div>
            )}

            {/* Call Log */}
            <div className="border rounded-lg p-3 h-72 overflow-y-auto space-y-3">
              {callLog.map((msg, idx) => (
                <div
                  key={idx}
                  className={`flex ${msg.role === 'customer' ? 'justify-end' : 'justify-start'}`}
                >
                  <div
                    className={`max-w-[85%] p-3 rounded-lg ${
                      msg.role === 'customer'
                        ? 'bg-primary text-primary-foreground'
                        : 'bg-muted'
                    }`}
                  >
                    <p className="text-sm">{msg.content}</p>
                    {msg.metadata && msg.role === 'ai' && (
                      <div className="flex flex-wrap gap-1 mt-2 pt-2 border-t border-primary/10">
                        {msg.metadata.intent && (
                          <Badge variant="outline" className="text-[10px]">
                            {msg.metadata.intent}
                          </Badge>
                        )}
                        {msg.metadata.confidence && (
                          <Badge
                            variant="outline"
                            className={`text-[10px] ${
                              msg.metadata.confidence === 'high' ? 'border-green-500 text-green-700' :
                              msg.metadata.confidence === 'medium' ? 'border-yellow-500 text-yellow-700' :
                              'border-red-500 text-red-700'
                            }`}
                          >
                            {msg.metadata.confidence}
                          </Badge>
                        )}
                        {msg.metadata.knowledgeGap && (
                          <Badge variant="destructive" className="text-[10px] gap-0.5">
                            <AlertTriangle className="h-2.5 w-2.5" />
                            Gap
                          </Badge>
                        )}
                        {msg.metadata.priceQuote && (
                          <Badge
                            variant="outline"
                            className={`text-[10px] gap-0.5 ${
                              msg.metadata.priceQuote.confidence >= 0.8 ? 'border-green-500 text-green-700' :
                              msg.metadata.priceQuote.confidence >= 0.5 ? 'border-yellow-500 text-yellow-700' :
                              'border-orange-500 text-orange-700'
                            }`}
                          >
                            <DollarSign className="h-2.5 w-2.5" />
                            {msg.metadata.priceQuote.type} ({msg.metadata.priceQuote.confidence.toFixed(1)})
                          </Badge>
                        )}
                      </div>
                    )}
                    {msg.metadata?.priceQuote?.missingInputs && msg.metadata.priceQuote.missingInputs.length > 0 && (
                      <div className="mt-2 pt-2 border-t border-primary/10">
                        <p className="text-[10px] text-muted-foreground mb-1">Missing inputs for exact quote:</p>
                        <div className="flex flex-wrap gap-1">
                          {msg.metadata.priceQuote.missingInputs.map((input, i) => (
                            <Badge key={i} variant="secondary" className="text-[9px]">
                              {input.label}
                            </Badge>
                          ))}
                        </div>
                      </div>
                    )}
                    <p className="text-xs opacity-70 mt-1">
                      {msg.timestamp.toLocaleTimeString()}
                    </p>
                  </div>
                </div>
              ))}
              {aiLoading && (
                <div className="flex justify-start">
                  <div className="bg-muted p-3 rounded-lg flex items-center gap-2">
                    <Loader2 className="h-4 w-4 animate-spin" />
                    <span className="text-sm text-muted-foreground">AI thinking...</span>
                  </div>
                </div>
              )}
            </div>

            {/* Message Input */}
            <div className="flex gap-2">
              <Textarea
                placeholder="Type customer response..."
                value={customerInput}
                onChange={(e) => setCustomerInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendMessage();
                  }
                }}
                rows={2}
                className="flex-1"
                disabled={aiLoading}
              />
              <Button onClick={sendMessage} size="icon" disabled={aiLoading}>
                <MessageCircle className="h-4 w-4" />
              </Button>
            </div>

            {/* Call Controls */}
            <div className="flex gap-2">
              <Button variant="destructive" onClick={endCall} className="flex-1 gap-2">
                <PhoneOff className="h-4 w-4" />
                End Call
              </Button>
              <Button variant="outline" onClick={resetSimulator}>
                Reset
              </Button>
            </div>
          </>
        )}
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { resolveCustomer, createOpportunity, createSyncEvent } from "@/hooks/useCustomerResolver";
import { MessageSquare, Send, User, Loader2, Brain, AlertTriangle } from "lucide-react";

interface SimulatedSMS {
  direction: 'inbound' | 'outbound';
  content: string;
  timestamp: Date;
  metadata?: {
    intent?: string;
    confidence?: string;
    sources?: Array<{ type: string; id: string }>;
    knowledgeGap?: boolean;
  };
}

export default function SMSSimulator() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  
  const [senderPhone, setSenderPhone] = useState('');
  const [senderName, setSenderName] = useState('');
  const [isConversationActive, setIsConversationActive] = useState(false);
  const [messages, setMessages] = useState<SimulatedSMS[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [resolvedCustomer, setResolvedCustomer] = useState<{
    id: string;
    isNew: boolean;
    hasConflict: boolean;
  } | null>(null);
  const [opportunityId, setOpportunityId] = useState<string | null>(null);
  const [aiLoading, setAiLoading] = useState(false);

  const getAIResponse = async (customerMessage: string): Promise<SimulatedSMS> => {
    if (!tenant?.id) {
      return {
        direction: 'outbound',
        content: "Thanks for reaching out! We'll get back to you shortly.",
        timestamp: new Date(),
      };
    }

    try {
      const { data, error } = await supabase.functions.invoke('ai-plan-response', {
        body: {
          tenantId: tenant.id,
          userMessage: customerMessage,
          channel: 'sms',
          customerId: resolvedCustomer?.id,
        },
      });

      if (error) throw error;

      const plan = data.plan;
      
      return {
        direction: 'outbound',
        content: plan.draft_reply,
        timestamp: new Date(),
        metadata: {
          intent: plan.intent,
          confidence: plan.confidence,
          sources: plan.sources_used,
          knowledgeGap: plan.knowledge_gap_detected,
        },
      };
    } catch (error) {
      console.error('AI response error:', error);
      return {
        direction: 'outbound',
        content: "Thanks for your message! Someone from our team will get back to you shortly.",
        timestamp: new Date(),
        metadata: { confidence: 'low' },
      };
    }
  };

  const startConversation = async () => {
    if (!tenant?.id) {
      toast({ variant: "destructive", title: "No business configured" });
      return;
    }

    if (!senderPhone) {
      toast({ variant: "destructive", title: "Please enter a phone number" });
      return;
    }

    setAiLoading(true);
    try {
      // Resolve customer through the unified pipeline
      const result = await resolveCustomer(
        tenant.id,
        senderPhone,
        senderName || undefined,
        undefined,
        'sms'
      );

      setResolvedCustomer({
        id: result.customer_id,
        isNew: result.is_new,
        hasConflict: result.has_conflict,
      });

      // Create opportunity
      const oppId = await createOpportunity(
        tenant.id,
        result.customer_id,
        'sms',
        undefined,
        'Inbound SMS via simulator'
      );
      setOpportunityId(oppId);

      // Fire sync event
      await createSyncEvent(
        tenant.id,
        result.is_new ? 'customer_created' : 'customer_updated',
        'customer',
        result.customer_id,
        { phone: senderPhone, name: senderName, source: 'simulator_sms' }
      );

      setIsConversationActive(true);

      toast({
        title: result.is_new ? "New customer created" : "Existing customer found",
        description: result.has_conflict 
          ? "Conflict detected - check merge queue" 
          : "Customer resolved successfully",
      });

    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Failed to start conversation",
        description: error.message,
      });
    } finally {
      setAiLoading(false);
    }
  };

  const sendInboundSMS = async () => {
    if (!newMessage.trim()) return;

    const inboundMsg: SimulatedSMS = {
      direction: 'inbound',
      content: newMessage,
      timestamp: new Date(),
    };

    setMessages(prev => [...prev, inboundMsg]);
    setNewMessage('');
    setAiLoading(true);

    const aiResponse = await getAIResponse(newMessage);
    setMessages(prev => [...prev, aiResponse]);
    setAiLoading(false);
  };

  const resetSimulator = () => {
    setSenderPhone('');
    setSenderName('');
    setMessages([]);
    setResolvedCustomer(null);
    setOpportunityId(null);
    setIsConversationActive(false);
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <MessageSquare className="h-5 w-5" />
          SMS Simulator
          <Badge variant="secondary" className="gap-1">
            <Brain className="h-3 w-3" />
            AI-Powered
          </Badge>
        </CardTitle>
        <CardDescription>
          Test your AI text responses with real business data and knowledge retrieval
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {!isConversationActive ? (
          <>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="sms-phone">Sender Phone *</Label>
                <Input
                  id="sms-phone"
                  placeholder="(555) 123-4567"
                  value={senderPhone}
                  onChange={(e) => setSenderPhone(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="sms-name">Sender Name (optional)</Label>
                <Input
                  id="sms-name"
                  placeholder="Jane Doe"
                  value={senderName}
                  onChange={(e) => setSenderName(e.target.value)}
                />
              </div>
            </div>
            
            <Button onClick={startConversation} className="w-full gap-2" disabled={aiLoading}>
              {aiLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <MessageSquare className="h-4 w-4" />}
              {aiLoading ? "Starting..." : "Start SMS Conversation"}
            </Button>
          </>
        ) : (
          <>
            {/* Customer Info */}
            {resolvedCustomer && (
              <div className="flex items-center gap-3 p-3 rounded-lg bg-secondary/50">
                <User className="h-5 w-5 text-primary" />
                <div className="flex-1">
                  <p className="font-medium">{senderName || 'Unknown'}</p>
                  <p className="text-sm text-muted-foreground">{senderPhone}</p>
                </div>
                <div className="flex gap-2">
                  <Badge variant={resolvedCustomer.isNew ? "default" : "secondary"}>
                    {resolvedCustomer.isNew ? "New" : "Returning"}
                  </Badge>
                  {resolvedCustomer.hasConflict && (
                    <Badge variant="destructive">Conflict</Badge>
                  )}
                </div>
              </div>
            )}

            {/* Message Thread */}
            <div className="border rounded-lg p-3 h-72 overflow-y-auto space-y-3">
              {messages.length === 0 ? (
                <p className="text-center text-muted-foreground py-8">
                  Type a message to simulate an inbound SMS
                </p>
              ) : (
                messages.map((msg, idx) => (
                  <div
                    key={idx}
                    className={`flex ${msg.direction === 'inbound' ? 'justify-end' : 'justify-start'}`}
                  >
                    <div
                      className={`max-w-[85%] p-3 rounded-lg ${
                        msg.direction === 'inbound'
                          ? 'bg-primary text-primary-foreground'
                          : 'bg-muted'
                      }`}
                    >
                      <p className="text-sm">{msg.content}</p>
                      {msg.metadata && msg.direction === 'outbound' && (
                        <div className="flex flex-wrap gap-1 mt-2 pt-2 border-t border-primary/10">
                          {msg.metadata.intent && (
                            <Badge variant="outline" className="text-[10px]">
                              {msg.metadata.intent}
                            </Badge>
                          )}
                          {msg.metadata.confidence && (
                            <Badge 
                              variant="outline" 
                              className={`text-[10px] ${
                                msg.metadata.confidence === 'high' ? 'border-green-500 text-green-700' :
                                msg.metadata.confidence === 'medium' ? 'border-yellow-500 text-yellow-700' :
                                'border-red-500 text-red-700'
                              }`}
                            >
                              {msg.metadata.confidence}
                            </Badge>
                          )}
                          {msg.metadata.knowledgeGap && (
                            <Badge variant="destructive" className="text-[10px] gap-0.5">
                              <AlertTriangle className="h-2.5 w-2.5" />
                              Gap
                            </Badge>
                          )}
                        </div>
                      )}
                      <p className="text-xs opacity-70 mt-1">
                        {msg.timestamp.toLocaleTimeString()}
                      </p>
                    </div>
                  </div>
                ))
              )}
              {aiLoading && (
                <div className="flex justify-start">
                  <div className="bg-muted p-3 rounded-lg flex items-center gap-2">
                    <Loader2 className="h-4 w-4 animate-spin" />
                    <span className="text-sm text-muted-foreground">AI composing...</span>
                  </div>
                </div>
              )}
            </div>

            {/* Message Input */}
            <div className="flex gap-2">
              <Textarea
                placeholder="Simulate inbound SMS..."
                value={newMessage}
                onChange={(e) => setNewMessage(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter' && !e.shiftKey) {
                    e.preventDefault();
                    sendInboundSMS();
                  }
                }}
                rows={2}
                className="flex-1"
                disabled={aiLoading}
              />
              <Button onClick={sendInboundSMS} size="icon" disabled={aiLoading}>
                <Send className="h-4 w-4" />
              </Button>
            </div>

            <Button variant="outline" onClick={resetSimulator} className="w-full">
              End Conversation & Reset
            </Button>
          </>
        )}
      </CardContent>
    </Card>
  );
}

import { useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useServices } from "@/hooks/useServices";
import { useKnowledgeGaps } from "@/hooks/useKnowledgeGaps";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Sparkles, X } from "lucide-react";
import { buildTestScenarios } from "@/lib/testScenarioBuilder";
import type { BusinessMode } from "@/hooks/useTenantConfig";

interface SuggestedTestsBannerProps {
  onDismiss?: () => void;
}

/**
 * Suggested Tests Banner
 *
 * Shows business-aware test scenarios built from real data:
 * 1. Knowledge gaps — questions the AI couldn't answer
 * 2. Actual services — questions about real service names/prices
 * 3. Industry/mode fallback — generic questions for the business type
 */
export function SuggestedTestsBanner({ onDismiss }: SuggestedTestsBannerProps) {
  const { tenant } = useAuth();
  const businessMode = (tenant?.business_mode as BusinessMode) || "service";
  const businessName = (tenant as any)?.business_name || tenant?.name || "";
  const { services: allServices } = useServices();
  const { topGaps } = useKnowledgeGaps();
  const { slug } = useIndustryContext();

  const activeServices = useMemo(
    () => (allServices || []).filter((s) => s.is_active !== false),
    [allServices],
  );

  const scenarios = useMemo(
    () => buildTestScenarios(activeServices, topGaps, businessMode, slug),
    [activeServices, topGaps, businessMode, slug],
  );

  const hasRealData = scenarios.some((s) => s.source !== "industry");
  const bannerText = hasRealData && businessName
    ? `Questions ${businessName} customers actually ask:`
    : `Common questions for ${businessMode} businesses:`;

  return (
    <Card className="border-primary/20 bg-gradient-to-r from-primary/5 to-primary/10">
      <CardContent className="p-4">
        <div className="flex items-start gap-3">
          <Sparkles className="h-5 w-5 text-primary mt-0.5 shrink-0" />

          <div className="flex-1 min-w-0">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-medium">Try these test scenarios</h3>
              {onDismiss && (
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={onDismiss}
                  className="h-6 w-6 p-0"
                >
                  <X className="h-4 w-4" />
                </Button>
              )}
            </div>

            <p className="text-sm text-muted-foreground mb-3">
              {bannerText}
            </p>

            <div className="flex flex-wrap gap-2">
              {scenarios.map((scenario, i) => (
                <Button
                  key={i}
                  variant="outline"
                  size="sm"
                  className="h-auto py-2 px-3 text-xs font-normal whitespace-normal text-left gap-1.5"
                  onClick={() => {
                    navigator.clipboard.writeText(scenario.text);
                    window.dispatchEvent(
                      new CustomEvent('suggested-test-clicked', {
                        detail: { text: scenario.text }
                      })
                    );
                  }}
                >
                  "{scenario.text}"
                  {scenario.badge && (
                    <Badge variant="secondary" className="text-[9px] px-1.5 py-0 h-4 ml-1 shrink-0">
                      {scenario.badge}
                    </Badge>
                  )}
                </Button>
              ))}
            </div>

            <p className="text-xs text-muted-foreground mt-3">
              Click any test to copy it to your clipboard
            </p>
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

import { cn } from "@/lib/utils";
import { Link, LinkProps } from "react-router-dom";
import React, { useState, createContext, useContext } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { Menu, X } from "lucide-react";

interface Links {
  label: string;
  href: string;
  icon: React.ReactNode;
  badge?: number;
}

interface SidebarContextProps {
  open: boolean;
  setOpen: React.Dispatch<React.SetStateAction<boolean>>;
  animate: boolean;
}

const SidebarContext = createContext<SidebarContextProps | undefined>(undefined);

export const useAnimatedSidebar = () => {
  const context = useContext(SidebarContext);
  if (!context) {
    throw new Error("useAnimatedSidebar must be used within an AnimatedSidebarProvider");
  }
  return context;
};

export const AnimatedSidebarProvider = ({
  children,
  open: openProp,
  setOpen: setOpenProp,
  animate = true,
}: {
  children: React.ReactNode;
  open?: boolean;
  setOpen?: React.Dispatch<React.SetStateAction<boolean>>;
  animate?: boolean;
}) => {
  const [openState, setOpenState] = useState(false);
  const open = openProp !== undefined ? openProp : openState;
  const setOpen = setOpenProp !== undefined ? setOpenProp : setOpenState;

  return (
    <SidebarContext.Provider value={{ open, setOpen, animate }}>
      {children}
    </SidebarContext.Provider>
  );
};

export const AnimatedSidebar = ({
  children,
  open,
  setOpen,
  animate,
}: {
  children: React.ReactNode;
  open?: boolean;
  setOpen?: React.Dispatch<React.SetStateAction<boolean>>;
  animate?: boolean;
}) => {
  return (
    <AnimatedSidebarProvider open={open} setOpen={setOpen} animate={animate}>
      {children}
    </AnimatedSidebarProvider>
  );
};

export const SidebarBody = ({
  children,
  className,
  ...props
}: React.ComponentProps<typeof motion.div>) => {
  return (
    <>
      <DesktopSidebar className={className} {...props}>{children}</DesktopSidebar>
      <MobileSidebar className={className}>{children as React.ReactNode}</MobileSidebar>
    </>
  );
};

export const DesktopSidebar = ({
  className,
  children,
  ...props
}: React.ComponentProps<typeof motion.div>) => {
  const { open, setOpen, animate } = useAnimatedSidebar();
  return (
    <motion.div
      className={cn(
        "h-full px-2.5 py-4 hidden md:flex md:flex-col bg-sidebar/95 backdrop-blur-md flex-shrink-0 border-r border-border/20",
        className
      )}
      animate={{
        width: animate ? (open ? "240px" : "56px") : "240px",
      }}
      transition={{ duration: 0.2, ease: "easeOut" }}
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
      {...props}
    >
      {children}
    </motion.div>
  );
};

export const MobileSidebar = ({
  className,
  children,
  ...props
}: React.ComponentProps<"div">) => {
  const { open, setOpen } = useAnimatedSidebar();
  return (
    <div className={cn("md:hidden", className)} {...props}>
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ x: "-100%", opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: "-100%", opacity: 0 }}
            transition={{ duration: 0.3, ease: "easeInOut" }}
            className={cn(
              "fixed inset-0 z-[100] flex flex-col bg-sidebar p-6",
            )}
          >
            <div
              className="absolute right-4 top-4 cursor-pointer text-sidebar-foreground"
              onClick={() => setOpen(false)}
            >
              <X className="h-5 w-5" />
            </div>
            {children}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
};

export const SidebarLink = ({
  link,
  className,
  isActive,
  isLocked,
  ...props
}: {
  link: Links;
  className?: string;
  isActive?: boolean;
  isLocked?: boolean;
  props?: LinkProps;
}) => {
  const { open, animate } = useAnimatedSidebar();
  return (
    <Link
      to={isLocked ? "/app/go-live" : link.href}
      title={!open ? link.label : undefined}
      className={cn(
        "flex items-center gap-3 group/sidebar rounded-lg px-3 py-2 h-9 transition-all duration-150",
        isActive
          ? "bg-primary/10 text-primary font-medium [box-shadow:inset_2px_0_0_0_hsl(var(--primary)),0_0_12px_-3px_hsl(230_70%_62%/0.15)]"
          : "text-sidebar-foreground hover:bg-accent/80 hover:text-foreground",
        isLocked && "opacity-30 pointer-events-none",
        className
      )}
      {...props}
    >
      <span className={cn("shrink-0 transition-colors", isActive && "text-primary")}>{link.icon}</span>
      <motion.span
        animate={{
          display: animate ? (open ? "inline-block" : "none") : "inline-block",
          opacity: animate ? (open ? 1 : 0) : 1,
        }}
        transition={{ duration: 0.15 }}
        className="text-[13px] font-medium whitespace-pre"
      >
        {link.label}
      </motion.span>
      {link.badge && link.badge > 0 && open && (
        <span className="ml-auto bg-destructive text-destructive-foreground text-[9px] font-semibold rounded-full h-4 min-w-4 px-1 flex items-center justify-center">
          {link.badge}
        </span>
      )}
    </Link>
  );
};

import { motion, type Variants } from "framer-motion";
import { cn } from "@/lib/utils";

// --- Page transition wrapper ---

const pageVariants: Variants = {
  initial: { opacity: 0, y: 8 },
  animate: { opacity: 1, y: 0, transition: { duration: 0.2, ease: "easeOut" } },
