import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";
import { NODE_TYPE_METADATA, type WorkflowNode } from "@/types/workflow";
import { VariablePicker } from "./VariablePicker";

interface NodeConfigEditorProps {
  node: WorkflowNode;
  open: boolean;
  onClose: () => void;
  onSave: (config: Record<string, unknown>) => Promise<void>;
  availableVariables: string[];
}

export function NodeConfigEditor({
  node,
  open,
  onClose,
  onSave,
  availableVariables,
}: NodeConfigEditorProps) {
  const [config, setConfig] = useState<Record<string, any>>({});
  const [saving, setSaving] = useState(false);
  
  const meta = NODE_TYPE_METADATA[node.node_type];

  useEffect(() => {
    setConfig(node.config as Record<string, any>);
  }, [node]);

  const handleSave = async () => {
    setSaving(true);
    try {
      await onSave(config);
    } finally {
      setSaving(false);
    }
  };

  const updateField = (field: string, value: any) => {
    setConfig((prev) => ({ ...prev, [field]: value }));
  };

  const insertVariable = (field: string, variable: string) => {
    const current = config[field] || "";
    updateField(field, current + `{{${variable}}}`);
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-lg">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <span className="text-2xl">{meta?.icon}</span>
            Configure: {meta?.label}
          </DialogTitle>
          <DialogDescription>{meta?.description}</DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          {/* SMS Configuration */}
          {node.node_type === "notify_sms" && (
            <>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label>To (Phone Number)</Label>
                  <VariablePicker
                    variables={availableVariables.filter(v => v.includes("phone"))}
                    onSelect={(v) => insertVariable("to", v)}
                  />
                </div>
                <Input
                  value={config.to || ""}
                  onChange={(e) => updateField("to", e.target.value)}
                  placeholder="{{customer_phone}} or +1234567890"
                />
              </div>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label>Message</Label>
                  <VariablePicker
                    variables={availableVariables}
                    onSelect={(v) => insertVariable("message", v)}
                  />
                </div>
                <Textarea
                  value={config.message || ""}
                  onChange={(e) => updateField("message", e.target.value)}
                  placeholder="Your order #{{order_number}} is confirmed!"
                  rows={4}
                />
              </div>
            </>
          )}

          {/* Email Configuration */}
          {node.node_type === "notify_email" && (
            <>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label>To (Email)</Label>
                  <VariablePicker
                    variables={availableVariables.filter(v => v.includes("email"))}
                    onSelect={(v) => insertVariable("to", v)}
                  />
                </div>
                <Input
                  value={config.to || ""}
                  onChange={(e) => updateField("to", e.target.value)}
                  placeholder="{{customer_email}}"
                />
              </div>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label>Subject</Label>
                  <VariablePicker
                    variables={availableVariables}
                    onSelect={(v) => insertVariable("subject", v)}
                  />
                </div>
                <Input
                  value={config.subject || ""}
                  onChange={(e) => updateField("subject", e.target.value)}
                  placeholder="Order Confirmation #{{order_number}}"
                />
              </div>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label>Body</Label>
                  <VariablePicker
                    variables={availableVariables}
                    onSelect={(v) => insertVariable("body", v)}
                  />
                </div>
                <Textarea
                  value={config.body || ""}
                  onChange={(e) => updateField("body", e.target.value)}
                  placeholder="Hello {{customer_name}}, your order has been confirmed..."
                  rows={6}
                />
              </div>
            </>
          )}

          {/* Delay Configuration */}
          {node.node_type === "delay" && (
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Minutes</Label>
                <Input
                  type="number"
                  min={0}
                  value={config.minutes || ""}
                  onChange={(e) => updateField("minutes", parseInt(e.target.value) || 0)}
                  placeholder="5"
                />
              </div>
              <div className="space-y-2">
                <Label>Or Hours</Label>
                <Input
                  type="number"
                  min={0}
                  value={config.hours || ""}
                  onChange={(e) => updateField("hours", parseInt(e.target.value) || 0)}
                  placeholder="1"
                />
              </div>
            </div>
          )}

          {/* Webhook Configuration */}
          {node.node_type === "webhook_push" && (
            <>
              <div className="space-y-2">
                <Label>URL</Label>
                <Input
                  value={config.url || ""}
                  onChange={(e) => updateField("url", e.target.value)}
                  placeholder="https://your-api.com/webhook"
                />
              </div>
              <div className="space-y-2">
                <Label>Method</Label>
                <Select
                  value={config.method || "POST"}
                  onValueChange={(v) => updateField("method", v)}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="POST">POST</SelectItem>
                    <SelectItem value="PUT">PUT</SelectItem>
                    <SelectItem value="PATCH">PATCH</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </>
          )}

          {/* Print Ticket Configuration */}
          {node.node_type === "print_ticket" && (
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Format</Label>
                <Select
                  value={config.format || "thermal"}
                  onValueChange={(v) => updateField("format", v)}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="thermal">Thermal (Receipt)</SelectItem>
                    <SelectItem value="full">Full Page</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Copies</Label>
                <Input
                  type="number"
                  min={1}
                  max={10}
                  value={config.copies || 1}
                  onChange={(e) => updateField("copies", parseInt(e.target.value) || 1)}
                />
              </div>
            </div>
          )}

          {/* Set Field Configuration */}
          {node.node_type === "set_field" && (
            <>
              <div className="space-y-2">
                <Label>Field Name</Label>
                <Input
                  value={config.entity_field || ""}
                  onChange={(e) => updateField("entity_field", e.target.value)}
                  placeholder="status"
                />
              </div>
              <div className="space-y-2">
                <div className="flex items-center justify-between">
                  <Label>Value</Label>
                  <VariablePicker
                    variables={availableVariables}
                    onSelect={(v) => insertVariable("value", v)}
                  />
                </div>
                <Input
                  value={config.value || ""}
                  onChange={(e) => updateField("value", e.target.value)}
                  placeholder="confirmed"
                />
              </div>
            </>
          )}

          {/* Branch Configuration */}
          {node.node_type === "branch" && (
            <div className="space-y-4">
              <p className="text-sm text-muted-foreground">
                Branching logic allows you to route the workflow based on conditions.
                This is an advanced feature.
              </p>
              <div className="space-y-2">
                <Label>Condition Field</Label>
                <Select
                  value={config.field || ""}
                  onValueChange={(v) => updateField("field", v)}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Select field" />
                  </SelectTrigger>
                  <SelectContent>
                    {availableVariables.map((v) => (
                      <SelectItem key={v} value={v}>{v}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Operator</Label>
                <Select
                  value={config.op || "eq"}
                  onValueChange={(v) => updateField("op", v)}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="eq">Equals</SelectItem>
                    <SelectItem value="neq">Not Equals</SelectItem>
                    <SelectItem value="contains">Contains</SelectItem>
                    <SelectItem value="gt">Greater Than</SelectItem>
                    <SelectItem value="lt">Less Than</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Value</Label>
                <Input
                  value={config.check_value || ""}
                  onChange={(e) => updateField("check_value", e.target.value)}
                  placeholder="Value to compare"
                />
              </div>
            </div>
          )}

          {/* Default for unsupported types */}
          {!["notify_sms", "notify_email", "delay", "webhook_push", "print_ticket", "set_field", "branch"].includes(node.node_type) && (
            <div className="text-center py-4 text-muted-foreground">
              <p>Configuration for this node type is coming soon.</p>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={saving}>
            {saving ? "Saving..." : "Save"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Pencil, Check, X, Eye, Variable, HelpCircle } from "lucide-react";
import { VARIABLE_INFO, getVariablesByCategory, CATEGORY_LABELS, type VariableCategory } from "@/data/workflowGuides";
import { useTenantConfig } from "@/hooks/useTenantConfig";

interface QuickMessageEditorProps {
  message: string;
  onSave: (message: string) => void;
  variables: string[];
  isLoading?: boolean;
}

export function QuickMessageEditor({
  message,
  onSave,
  variables,
  isLoading = false,
}: QuickMessageEditorProps) {
  const { businessMode } = useTenantConfig();
  const [isOpen, setIsOpen] = useState(false);
  const [editedMessage, setEditedMessage] = useState(message);
  const [activeTab, setActiveTab] = useState<"edit" | "preview">("edit");

  const handleOpen = () => {
    setEditedMessage(message);
    setIsOpen(true);
  };

  const handleSave = () => {
    onSave(editedMessage);
    setIsOpen(false);
  };

  const handleInsertVariable = (variable: string) => {
    setEditedMessage((prev) => prev + `{{${variable}}}`);
  };

  // Get variable info for the available variables
  const variableInfo = useMemo(() => {
    return variables
      .map((v) => VARIABLE_INFO[v])
      .filter(Boolean);
  }, [variables]);

  // Group variables by category
  const groupedVariables = useMemo(() => {
    const grouped: Record<VariableCategory, typeof variableInfo> = {
      customer: [],
      order: [],
      booking: [],
      dispatch: [],
      call: [],
      business: [],
    };

    for (const v of variableInfo) {
      grouped[v.category].push(v);
    }

    return grouped;
  }, [variableInfo]);

  // Generate preview with example values
  const previewMessage = useMemo(() => {
    let preview = editedMessage;
    for (const v of variableInfo) {
      preview = preview.replace(new RegExp(`{{${v.key}}}`, "g"), v.example);
    }
    return preview;
  }, [editedMessage, variableInfo]);

  // Character count for SMS (160 chars per segment)
  const charCount = editedMessage.length;
  const segments = Math.ceil(charCount / 160) || 1;

  return (
    <>
      <Button
        variant="ghost"
        size="sm"
        onClick={handleOpen}
        className="h-7 px-2 text-xs text-muted-foreground hover:text-foreground"
      >
        <Pencil className="h-3 w-3 mr-1" />
        Edit message
      </Button>

      <Dialog open={isOpen} onOpenChange={setIsOpen}>
        <DialogContent className="sm:max-w-xl">
          <DialogHeader>
            <DialogTitle>Edit SMS Message</DialogTitle>
            <DialogDescription>
              Customize the message sent to customers. Use variables to personalize.
            </DialogDescription>
          </DialogHeader>

          <Tabs value={activeTab} onValueChange={(v) => setActiveTab(v as "edit" | "preview")}>
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="edit" className="gap-2">
                <Pencil className="h-4 w-4" />
                Edit
              </TabsTrigger>
              <TabsTrigger value="preview" className="gap-2">
                <Eye className="h-4 w-4" />
                Preview
              </TabsTrigger>
            </TabsList>

            <TabsContent value="edit" className="space-y-4 mt-4">
              <div className="space-y-2">
                <Label>Message</Label>
                <Textarea
                  value={editedMessage}
                  onChange={(e) => setEditedMessage(e.target.value)}
                  rows={4}
                  placeholder="Enter your message..."
                  className="resize-none font-mono text-sm"
                />
                <div className="flex items-center justify-between text-xs text-muted-foreground">
                  <span>
                    {charCount} characters ({segments} SMS segment{segments !== 1 ? "s" : ""})
                  </span>
                  {charCount > 320 && (
                    <span className="text-amber-500">Long message may incur extra costs</span>
                  )}
                </div>
              </div>

              {/* Enhanced Variable Picker */}
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <Variable className="h-4 w-4 text-muted-foreground" />
                  <Label className="text-sm">Insert Variables</Label>
                  <span className="text-xs text-muted-foreground">(click to add)</span>
                </div>
                <ScrollArea className="h-48 rounded-md border bg-muted/30 p-3">
                  <div className="space-y-4">
                    {Object.entries(groupedVariables).map(([category, vars]) => {
                      if (vars.length === 0) return null;
                      const categoryInfo = CATEGORY_LABELS[category as VariableCategory];
                      return (
                        <div key={category}>
                          <div className="flex items-center gap-2 mb-2">
                            <span className="text-sm">{categoryInfo.icon}</span>
                            <span className="text-xs font-medium text-muted-foreground">
                              {categoryInfo.label}
                            </span>
                          </div>
                          <div className="space-y-1">
                            {vars.map((v) => (
                              <button
                                key={v.key}
                                onClick={() => handleInsertVariable(v.key)}
                                className="w-full text-left px-2 py-1.5 rounded-md hover:bg-background transition-colors group border border-transparent hover:border-primary/30"
                              >
                                <div className="flex items-center justify-between">
                                  <code className="text-xs font-mono text-primary font-medium">
                                    {`{{${v.key}}}`}
                                  </code>
                                  <span className="text-xs text-muted-foreground opacity-0 group-hover:opacity-100 transition-opacity">
                                    + Add
                                  </span>
                                </div>
                                <p className="text-xs text-muted-foreground mt-0.5">
                                  {v.description} → <span className="font-medium">"{v.example}"</span>
                                </p>
                              </button>
                            ))}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </ScrollArea>
              </div>
            </TabsContent>

            <TabsContent value="preview" className="space-y-4 mt-4">
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                  <Eye className="h-4 w-4 text-muted-foreground" />
                  <Label>Message Preview</Label>
                </div>
                <div className="rounded-lg bg-muted p-4 min-h-[100px]">
                  <p className="text-sm whitespace-pre-wrap">
                    {previewMessage || <span className="text-muted-foreground italic">Your message will appear here...</span>}
                  </p>
                </div>
                <p className="text-xs text-muted-foreground flex items-center gap-1">
                  <HelpCircle className="h-3 w-3" />
                  Variables are replaced with example values in this preview
                </p>
              </div>
            </TabsContent>
          </Tabs>

          <DialogFooter>
            <Button variant="outline" onClick={() => setIsOpen(false)}>
              <X className="h-4 w-4 mr-1" />
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={isLoading}>
              <Check className="h-4 w-4 mr-1" />
              Save Message
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useMemo } from "react";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Button } from "@/components/ui/button";
import { MessageSquare, Printer, Webhook, Phone, Truck, UtensilsCrossed, Calendar, HelpCircle } from "lucide-react";
import { useTenantConfig, type BusinessMode } from "@/hooks/useTenantConfig";
import { useAuth } from "@/contexts/AuthContext";
import { useWorkflows, useWorkflowMutations } from "@/hooks/useWorkflows";
import { useToast } from "@/hooks/use-toast";
import { QuickMessageEditor } from "./QuickMessageEditor";
import { WebhookSetup } from "./WebhookSetup";
import { InlineHelpTooltip, AUTOMATION_HELP } from "./InlineHelpTooltip";
import { getAutomationTogglesForMode, type AutomationToggle } from "@/lib/createDefaultWorkflows";
import { TEMPLATE_VARIABLES, type WorkflowTrigger, type Workflow } from "@/types/workflow";
import { supabase } from "@/integrations/supabase/client";

interface SimpleAutomationPanelProps {
  onAdvancedClick: () => void;
}

export function SimpleAutomationPanel({ onAdvancedClick }: SimpleAutomationPanelProps) {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();
  const tenantId = tenant?.id ?? null;
  const { toast } = useToast();

  const { data: workflows, isLoading, refetch } = useWorkflows(tenantId);
  const { activateWorkflow, pauseWorkflow, createWorkflow } = useWorkflowMutations(tenantId);

  // Get toggles for this business mode
  const toggles = useMemo(() => getAutomationTogglesForMode(businessMode), [businessMode]);

  // Group toggles by category
  const groupedToggles = useMemo(() => {
    return {
      notifications: toggles.filter(t => t.category === "notifications"),
      kitchen: toggles.filter(t => t.category === "kitchen"),
      integrations: toggles.filter(t => t.category === "integrations"),
    };
  }, [toggles]);

  // Map toggles to their workflow status
  const toggleStates = useMemo(() => {
    if (!workflows) return {};

    const states: Record<string, { enabled: boolean; workflow?: Workflow; message?: string; webhookUrl?: string }> = {};

    for (const toggle of toggles) {
      // Find matching workflow by trigger and node type
      const matchingWorkflow = workflows.find(w => 
        w.trigger === toggle.trigger && w.status === "active"
      );
      
      // Also check for paused/draft workflows
      const anyWorkflow = workflows.find(w => w.trigger === toggle.trigger);

      states[toggle.id] = {
        enabled: !!matchingWorkflow,
        workflow: anyWorkflow,
        message: toggle.defaultMessage,
        webhookUrl: "",
      };
    }

    return states;
  }, [workflows, toggles]);

  const handleToggle = async (toggle: AutomationToggle, enabled: boolean) => {
    const state = toggleStates[toggle.id];

    try {
      if (enabled) {
        if (state?.workflow) {
          // Activate existing workflow
          await activateWorkflow.mutateAsync(state.workflow.id);
        } else {
          // Create new workflow with default node
          const workflow = await createWorkflow.mutateAsync({
            name: toggle.label,
            trigger: toggle.trigger,
          });

          // Add the default node
          await supabase
            .from("workflow_nodes")
            .insert({
              workflow_id: workflow.id,
              node_type: toggle.primaryNodeType,
              name: toggle.label,
              config: toggle.primaryNodeType === "notify_sms" 
                ? { to: "{{customer_phone}}", message: toggle.defaultMessage || "" }
                : toggle.primaryNodeType === "print_ticket"
                ? { format: "thermal", copies: 1 }
                : { url: "", method: "POST" },
              position: { x: 100, y: 100 },
            });

          // Activate the workflow
          await activateWorkflow.mutateAsync(workflow.id);
        }
        toast({ title: `${toggle.label} enabled` });
      } else {
        if (state?.workflow) {
          await pauseWorkflow.mutateAsync(state.workflow.id);
          toast({ title: `${toggle.label} disabled` });
        }
      }
      
      refetch();
    } catch (error) {
      console.error("Toggle error:", error);
      toast({ 
        title: "Failed to update automation", 
        description: String(error),
        variant: "destructive" 
      });
    }
  };

  const handleMessageSave = async (toggle: AutomationToggle, message: string) => {
    const state = toggleStates[toggle.id];
    if (!state?.workflow) return;

    try {
      // Find the SMS node and update it
      const { data: nodes } = await supabase
        .from("workflow_nodes")
        .select("*")
        .eq("workflow_id", state.workflow.id)
        .eq("node_type", "notify_sms")
        .limit(1);

      if (nodes && nodes.length > 0) {
        const existingConfig = (nodes[0].config as Record<string, unknown>) || {};
        await supabase
          .from("workflow_nodes")
          .update({
            config: { ...existingConfig, message } as any,
          })
          .eq("id", nodes[0].id);

        toast({ title: "Message updated" });
      }
    } catch (error) {
      console.error("Message save error:", error);
      toast({ title: "Failed to save message", variant: "destructive" });
    }
  };

  const handleWebhookSave = async (toggle: AutomationToggle, url: string) => {
    const state = toggleStates[toggle.id];
    if (!state?.workflow) return;

    try {
      // Find the webhook node and update it
      const { data: nodes } = await supabase
        .from("workflow_nodes")
        .select("*")
        .eq("workflow_id", state.workflow.id)
        .eq("node_type", "webhook_push")
        .limit(1);

      if (nodes && nodes.length > 0) {
        const existingConfig = (nodes[0].config as Record<string, unknown>) || {};
        await supabase
          .from("workflow_nodes")
          .update({
            config: { ...existingConfig, url } as any,
          })
          .eq("id", nodes[0].id);

        toast({ title: "Webhook URL updated" });
      }
    } catch (error) {
      console.error("Webhook save error:", error);
      toast({ title: "Failed to save webhook", variant: "destructive" });
    }
  };

  // Get variables for entity type
  const getVariables = (trigger: WorkflowTrigger): string[] => {
    const entityType = trigger.split(".")[0] as keyof typeof TEMPLATE_VARIABLES;
    const entityVars = TEMPLATE_VARIABLES[entityType] || [];
    return [...entityVars, ...TEMPLATE_VARIABLES.common];
  };

  if (isLoading) {
    return (
      <div className="space-y-6">
        {[1, 2, 3].map(i => (
          <Card key={i}>
            <CardHeader>
              <Skeleton className="h-5 w-48" />
            </CardHeader>
            <CardContent className="space-y-4">
              <Skeleton className="h-16 w-full" />
              <Skeleton className="h-16 w-full" />
            </CardContent>
          </Card>
        ))}
      </div>
    );
  }

  // Get help content for a toggle
  const getHelpForToggle = (toggle: AutomationToggle) => {
    if (toggle.trigger === "order.confirmed") return AUTOMATION_HELP.orderConfirmed;
    if (toggle.trigger === "order.ready") return AUTOMATION_HELP.orderReady;
    if (toggle.trigger === "booking.confirmed") return AUTOMATION_HELP.bookingConfirmed;
    if (toggle.trigger === "missed_call") return AUTOMATION_HELP.missedCall;
    if (toggle.trigger === "dispatch.created") return AUTOMATION_HELP.dispatchCreated;
    if (toggle.trigger === "dispatch.completed") return AUTOMATION_HELP.dispatchCompleted;
    if (toggle.primaryNodeType === "print_ticket") return AUTOMATION_HELP.printTicket;
    if (toggle.primaryNodeType === "webhook_push") return AUTOMATION_HELP.webhookCrm;
    return null;
  };

  return (
    <div className="space-y-6">
      {/* Help Banner */}
      <div className="flex items-center justify-between p-3 rounded-lg bg-muted/50 border">
        <div className="flex items-center gap-2">
          <HelpCircle className="h-4 w-4 text-muted-foreground" />
          <span className="text-sm text-muted-foreground">
            Need help setting up automations?
          </span>
        </div>
        <Button variant="ghost" size="sm" asChild>
          <a href="/app/help" className="text-xs">
            View full guide →
          </a>
        </Button>
      </div>

      {/* Customer Notifications */}
      {groupedToggles.notifications.length > 0 && (
        <Card>
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <MessageSquare className="h-5 w-5 text-primary" />
              <CardTitle className="text-lg">Customer Notifications</CardTitle>
              <InlineHelpTooltip
                title="Customer Notifications"
                description="Send automatic text messages to customers when events happen in your business."
              />
            </div>
            <CardDescription>
              Automatic text messages to keep customers informed
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {groupedToggles.notifications.map(toggle => {
              const helpContent = getHelpForToggle(toggle);
              const state = toggleStates[toggle.id];
              const Icon = getToggleIcon(toggle);
              return (
                <div
                  key={toggle.id}
                  className="flex items-start justify-between gap-4 p-4 rounded-lg border bg-card"
                >
                  <div className="flex items-start gap-3 min-w-0">
                    <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10 shrink-0">
                      <Icon className="h-4 w-4 text-primary" />
                    </div>
                    <div className="min-w-0">
                      <div className="flex items-center gap-2">
                        <p className="font-medium text-sm">{toggle.label}</p>
                        {helpContent && (
                          <InlineHelpTooltip
                            title={helpContent.title}
                            description={helpContent.description}
                            steps={helpContent.steps}
                          />
                        )}
                        {state?.enabled && (
                          <Badge variant="outline" className="text-xs bg-primary/10 text-primary border-primary/30">
                            Active
                          </Badge>
                        )}
                      </div>
                      <p className="text-xs text-muted-foreground truncate max-w-xs">
                        {state?.message || toggle.description}
                      </p>
                      {state?.enabled && toggle.primaryNodeType === "notify_sms" && (
                        <QuickMessageEditor
                          message={state.message || toggle.defaultMessage || ""}
                          onSave={(msg) => handleMessageSave(toggle, msg)}
                          variables={getVariables(toggle.trigger)}
                        />
                      )}
                    </div>
                  </div>
                  <Switch
                    checked={state?.enabled || false}
                    onCheckedChange={(checked) => handleToggle(toggle, checked)}
                    disabled={activateWorkflow.isPending || pauseWorkflow.isPending || createWorkflow.isPending}
                  />
                </div>
              );
            })}
          </CardContent>
        </Card>
      )}

      {/* Kitchen / Team Alerts */}
      {groupedToggles.kitchen.length > 0 && (
        <Card>
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <Printer className="h-5 w-5 text-primary" />
              <CardTitle className="text-lg">Kitchen / Team Alerts</CardTitle>
              <InlineHelpTooltip
                title="Kitchen & Team Alerts"
                description="Automatically print tickets or alert your team when orders come in."
              />
            </div>
            <CardDescription>
              Instant notifications for your team
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {groupedToggles.kitchen.map(toggle => {
              const state = toggleStates[toggle.id];
              const Icon = getToggleIcon(toggle);
              return (
                <div
                  key={toggle.id}
                  className="flex items-start justify-between gap-4 p-4 rounded-lg border bg-card"
                >
                  <div className="flex items-start gap-3">
                    <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10 shrink-0">
                      <Icon className="h-4 w-4 text-primary" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <p className="font-medium text-sm">{toggle.label}</p>
                        {state?.enabled && (
                          <Badge variant="outline" className="text-xs bg-primary/10 text-primary border-primary/30">
                            Active
                          </Badge>
                        )}
                      </div>
                      <p className="text-xs text-muted-foreground">{toggle.description}</p>
                    </div>
                  </div>
                  <Switch
                    checked={state?.enabled || false}
                    onCheckedChange={(checked) => handleToggle(toggle, checked)}
                    disabled={activateWorkflow.isPending || pauseWorkflow.isPending || createWorkflow.isPending}
                  />
                </div>
              );
            })}
          </CardContent>
        </Card>
      )}

      {/* External Integrations */}
      {groupedToggles.integrations.length > 0 && (
        <Card>
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <Webhook className="h-5 w-5 text-primary" />
              <CardTitle className="text-lg">External Integrations</CardTitle>
              <InlineHelpTooltip
                title="External Integrations"
                description="Send data to your CRM, Zapier, or other external services when events happen."
                steps={[
                  "Toggle ON to enable the integration",
                  "Click 'Set up webhook' to configure",
                  "Enter your webhook URL or use Zapier",
                  "Test the connection",
                ]}
              />
            </div>
            <CardDescription>
              Connect with your CRM, Zapier, and other tools
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {groupedToggles.integrations.map(toggle => {
              const state = toggleStates[toggle.id];
              const Icon = getToggleIcon(toggle);
              return (
                <div
                  key={toggle.id}
                  className="flex items-start justify-between gap-4 p-4 rounded-lg border bg-card"
                >
                  <div className="flex items-start gap-3">
                    <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10 shrink-0">
                      <Icon className="h-4 w-4 text-primary" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <p className="font-medium text-sm">{toggle.label}</p>
                        {state?.enabled && state.webhookUrl ? (
                          <Badge variant="outline" className="text-xs bg-primary/10 text-primary border-primary/30">
                            Connected
                          </Badge>
                        ) : state?.enabled ? (
                          <Badge variant="outline" className="text-xs bg-accent/10 text-accent-foreground border-accent/30">
                            No URL
                          </Badge>
                        ) : null}
                      </div>
                      <p className="text-xs text-muted-foreground">{toggle.description}</p>
                      {state?.enabled && toggle.primaryNodeType === "webhook_push" && (
                        <WebhookSetup
                          currentUrl={state.webhookUrl || ""}
                          onSave={(url) => handleWebhookSave(toggle, url)}
                        />
                      )}
                    </div>
                  </div>
                  <Switch
                    checked={state?.enabled || false}
                    onCheckedChange={(checked) => handleToggle(toggle, checked)}
                    disabled={activateWorkflow.isPending || pauseWorkflow.isPending || createWorkflow.isPending}
                  />
                </div>
              );
            })}
          </CardContent>
        </Card>
      )}

      {/* Advanced Mode Link */}
      <div className="flex justify-center pt-4">
        <button
          onClick={onAdvancedClick}
          className="text-sm text-muted-foreground hover:text-foreground transition-colors underline-offset-4 hover:underline"
        >
          Show Advanced Workflow Editor →
        </button>
      </div>
    </div>
  );
}

function getToggleIcon(toggle: AutomationToggle) {
  switch (toggle.trigger) {
    case "booking.confirmed":
      return Calendar;
    case "order.confirmed":
    case "order.ready":
      return UtensilsCrossed;
    case "dispatch.created":
    case "dispatch.completed":
      return Truck;
    case "missed_call":
    case "call.ended":
      return Phone;
    default:
      return MessageSquare;
  }
}

import { useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Settings2, Link2, Zap, Copy, Check, Loader2, ExternalLink } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

interface WebhookSetupProps {
  currentUrl: string;
  onSave: (url: string) => void;
  isLoading?: boolean;
  samplePayload?: Record<string, unknown>;
}

export function WebhookSetup({
  currentUrl,
  onSave,
  isLoading = false,
  samplePayload,
}: WebhookSetupProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [url, setUrl] = useState(currentUrl);
  const [isTesting, setIsTesting] = useState(false);
  const [testResult, setTestResult] = useState<"success" | "error" | null>(null);
  const [copied, setCopied] = useState(false);
  const { toast } = useToast();

  const handleOpen = () => {
    setUrl(currentUrl);
    setTestResult(null);
    setIsOpen(true);
  };

  const handleSave = () => {
    onSave(url);
    setIsOpen(false);
    toast({ title: "Webhook URL saved" });
  };

  const handleTest = async () => {
    if (!url) return;

    setIsTesting(true);
    setTestResult(null);

    try {
      // Simulate a test request (in production, this would call an edge function)
      await new Promise((resolve) => setTimeout(resolve, 1500));
      // For demo purposes, assume success if URL is valid format
      if (url.startsWith("http://") || url.startsWith("https://")) {
        setTestResult("success");
        toast({ title: "Test successful", description: "Webhook endpoint responded correctly" });
      } else {
        setTestResult("error");
        toast({ title: "Test failed", description: "Invalid URL format", variant: "destructive" });
      }
    } catch (error) {
      setTestResult("error");
      toast({ title: "Test failed", description: "Could not reach webhook endpoint", variant: "destructive" });
    } finally {
      setIsTesting(false);
    }
  };

  const handleCopyPayload = () => {
    const payload = samplePayload || {
      event: "call.ended",
      timestamp: new Date().toISOString(),
      customer_name: "John Doe",
      customer_phone: "+15551234567",
      summary: "Customer inquired about availability for next week",
      outcome: "booked",
    };
    navigator.clipboard.writeText(JSON.stringify(payload, null, 2));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    toast({ title: "Copied to clipboard" });
  };

  const isConfigured = !!currentUrl;

  return (
    <>
      <Button
        variant="ghost"
        size="sm"
        onClick={handleOpen}
        className="h-7 px-2 text-xs text-muted-foreground hover:text-foreground"
      >
        <Settings2 className="h-3 w-3 mr-1" />
        {isConfigured ? "Configure" : "Set up webhook"}
      </Button>

      <Dialog open={isOpen} onOpenChange={setIsOpen}>
        <DialogContent className="sm:max-w-lg">
          <DialogHeader>
            <DialogTitle>Webhook Integration</DialogTitle>
            <DialogDescription>
              Send data to your CRM, Zapier, or any external service
            </DialogDescription>
          </DialogHeader>

          <Tabs defaultValue="url" className="mt-4">
            <TabsList className="grid w-full grid-cols-2">
              <TabsTrigger value="url">
                <Link2 className="h-4 w-4 mr-2" />
                Custom URL
              </TabsTrigger>
              <TabsTrigger value="zapier">
                <Zap className="h-4 w-4 mr-2" />
                Zapier
              </TabsTrigger>
            </TabsList>

            <TabsContent value="url" className="space-y-4 mt-4">
              <div className="space-y-2">
                <Label>Webhook URL</Label>
                <Input
                  placeholder="https://your-service.com/webhook"
                  value={url}
                  onChange={(e) => setUrl(e.target.value)}
                />
                <p className="text-xs text-muted-foreground">
                  We'll send a POST request with JSON data to this URL
                </p>
              </div>

              <div className="flex gap-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={handleTest}
                  disabled={!url || isTesting}
                >
                  {isTesting ? (
                    <Loader2 className="h-4 w-4 mr-1 animate-spin" />
                  ) : testResult === "success" ? (
                    <Check className="h-4 w-4 mr-1 text-green-500" />
                  ) : (
                    <ExternalLink className="h-4 w-4 mr-1" />
                  )}
                  Test Webhook
                </Button>
              </div>

              <div className="rounded-lg bg-muted/50 p-3 space-y-2">
                <div className="flex items-center justify-between">
                  <p className="text-xs font-medium">Sample Payload</p>
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={handleCopyPayload}
                    className="h-6 px-2 text-xs"
                  >
                    {copied ? (
                      <Check className="h-3 w-3 mr-1" />
                    ) : (
                      <Copy className="h-3 w-3 mr-1" />
                    )}
                    Copy
                  </Button>
                </div>
                <pre className="text-xs bg-background rounded p-2 overflow-x-auto">
                  {JSON.stringify(
                    samplePayload || {
                      event: "call.ended",
                      customer_name: "John Doe",
                      summary: "...",
                    },
                    null,
                    2
                  )}
                </pre>
              </div>
            </TabsContent>

            <TabsContent value="zapier" className="space-y-4 mt-4">
              <div className="rounded-lg border p-4 space-y-3">
                <div className="flex items-start gap-3">
                  <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-orange-100 dark:bg-orange-900/30">
                    <Zap className="h-5 w-5 text-orange-600" />
                  </div>
                  <div>
                    <h4 className="font-medium">Connect with Zapier</h4>
                    <p className="text-sm text-muted-foreground">
                      Use Zapier to connect with 5,000+ apps
                    </p>
                  </div>
                </div>

                <ol className="space-y-2 text-sm text-muted-foreground list-decimal list-inside">
                  <li>Go to Zapier and create a new Zap</li>
                  <li>Choose "Webhooks by Zapier" as your trigger</li>
                  <li>Select "Catch Hook" as the event</li>
                  <li>Copy the webhook URL Zapier provides</li>
                  <li>Paste it in the "Custom URL" tab above</li>
                </ol>

                <Button
                  variant="outline"
                  size="sm"
                  className="w-full"
                  onClick={() => window.open("https://zapier.com/apps/webhook", "_blank")}
                >
                  <ExternalLink className="h-4 w-4 mr-2" />
                  Open Zapier
                </Button>
              </div>
            </TabsContent>
          </Tabs>

          <DialogFooter className="mt-4">
            <Button variant="outline" onClick={() => setIsOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleSave} disabled={isLoading}>
              Save
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

