      const { error } = await supabase
        .from("agency_saved_leads" as any)
        .delete()
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["agency-saved-leads", agencyId] });
