import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";
import { useEffect, useMemo } from "react";
import type { Database } from "@/integrations/supabase/types";

type Booking = Database["public"]["Tables"]["bookings"]["Row"];
type BookingInsert = Database["public"]["Tables"]["bookings"]["Insert"];
type Lead = Database["public"]["Tables"]["leads"]["Row"];
type Service = Database["public"]["Tables"]["services"]["Row"];

// Extended booking type with joined data
export interface BookingWithDetails extends Booking {
  lead?: Lead | null;
  service?: Service | null;
}

export function useBookings() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const bookingsQuery = useQuery({
    queryKey: ["bookings", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      
      const { data, error } = await supabase
        .from("bookings")
        .select(`
          *,
          lead:leads(*),
          service:services(*)
        `)
        .eq("tenant_id", tenant.id)
        .order("start_at", { ascending: true });

      if (error) throw error;
      return data as BookingWithDetails[];
    },
    enabled: !!tenant?.id,
  });

  // Realtime subscription for instant booking updates
  useEffect(() => {
    if (!tenant?.id) return;

    const channel = supabase
      .channel(`bookings-realtime-${tenant.id}`)
      .on(
        'postgres_changes',
        { 
          event: '*', 
          schema: 'public', 
          table: 'bookings',
          filter: `tenant_id=eq.${tenant.id}`
        },
        () => {
          // Refetch bookings when any change occurs for this tenant
          queryClient.invalidateQueries({ queryKey: ["bookings", tenant.id] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [tenant?.id, queryClient]);

  const createBooking = useMutation({
    mutationFn: async (booking: Omit<BookingInsert, "tenant_id">) => {
      if (!tenant?.id) throw new Error("No tenant");
      
      const { data, error } = await supabase
        .from("bookings")
        .insert({ ...booking, tenant_id: tenant.id })
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["bookings", tenant?.id] });
      toast({ title: "Booking confirmed", description: "Customer has been notified." });
    },
    onError: (error) => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const updateBooking = useMutation({
    mutationFn: async ({ id, ...updates }: Partial<Booking> & { id: string }) => {
      const { data, error } = await supabase
        .from("bookings")
        .update(updates)
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["bookings", tenant?.id] });
      toast({ title: "Booking updated", description: "Changes saved." });
    },
    onError: (error) => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const completeBooking = useMutation({
    mutationFn: async (id: string) => {
      const { data, error } = await supabase
        .from("bookings")
        .update({ status: "completed" })
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;

      // Fire booking.completed workflow trigger for automations (review requests, follow-ups)
      if (tenant?.id) {
        supabase.functions.invoke("trigger-workflow", {
          body: {
            tenant_id: tenant.id,
            trigger: "booking.completed",
            entity_type: "booking",
            entity_id: id,
          },
        }).catch((err) => console.error("trigger-workflow error:", err));
      }

      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["bookings", tenant?.id] });
      toast({ title: "Booking completed", description: "Service marked as finished." });
    },
    onError: (error) => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const confirmBooking = useMutation({
    mutationFn: async (id: string) => {
      const { data, error } = await supabase
        .from("bookings")
        .update({ status: "confirmed" })
        .eq("id", id)
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["bookings", tenant?.id] });
      toast({ title: "Booking confirmed", description: "Appointment approved." });
    },
    onError: () => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const rescheduleBooking = useMutation({
    mutationFn: async ({ id, start_at, end_at, notes }: { id: string; start_at: string; end_at?: string; notes?: string }) => {
      const updates: Record<string, unknown> = { start_at };
      if (end_at) updates.end_at = end_at;
      if (notes !== undefined) updates.notes = notes;
      const { data, error } = await supabase
        .from("bookings")
        .update(updates)
        .eq("id", id)
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["bookings", tenant?.id] });
      toast({ title: "Booking rescheduled", description: "New time saved." });
    },
    onError: () => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const noShowBooking = useMutation({
    mutationFn: async (id: string) => {
      const { data, error } = await supabase
        .from("bookings")
        .update({ status: "no_show" })
        .eq("id", id)
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["bookings", tenant?.id] });
      toast({ title: "Marked as no-show" });
    },
    onError: () => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const cancelBooking = useMutation({
    mutationFn: async (id: string) => {
      const { data, error } = await supabase
        .from("bookings")
        .update({ status: "canceled" })
        .eq("id", id)
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["bookings", tenant?.id] });
      toast({ title: "Booking cancelled" });
    },
    onError: () => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const deleteBooking = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from("bookings").delete().eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["bookings", tenant?.id] });
      toast({ title: "Booking deleted", description: "Appointment removed." });
    },
    onError: (error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const stats = useMemo(() => {
    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const endOfToday = new Date(startOfToday.getTime() + 24 * 60 * 60 * 1000);
    const endOfWeek = new Date(startOfToday.getTime() + 7 * 24 * 60 * 60 * 1000);

    return {
      today: bookingsQuery.data?.filter((b) => {
        const start = new Date(b.start_at);
        return start >= startOfToday && start < endOfToday;
      }).length ?? 0,
      thisWeek: bookingsQuery.data?.filter((b) => {
        const start = new Date(b.start_at);
        return start >= startOfToday && start < endOfWeek;
      }).length ?? 0,
      pendingDeposits: bookingsQuery.data?.filter((b) => b.status === "pending_deposit").length ?? 0,
      completed: bookingsQuery.data?.filter((b) => b.status === "completed").length ?? 0,
    };
  }, [bookingsQuery.data]);

  return {
    bookings: bookingsQuery.data ?? [],
    isLoading: bookingsQuery.isLoading,
    error: bookingsQuery.error,
    stats,
    createBooking,
    updateBooking,
    confirmBooking,
    rescheduleBooking,
    completeBooking,
    noShowBooking,
    cancelBooking,
    deleteBooking,
    refetch: bookingsQuery.refetch,
  };
}

/**
 * Hook to fetch summary previews for all Business Brain sections
 * Used by CollapsibleBrainSection to show 1-line previews
 * 
 * Updated to use the new dynamic completion system from useBrainCompletion
 */

import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useBrainCompletion, type CompletionStats } from "./useBrainCompletion";

interface BrainSummaries {
  // Profile
  businessInfo: string;
  templates: string;
  
  // Hours
  hours: string;
  
  // Services
  pricingReadiness: string;
  pricingRules: string;
  catalog: string;
  
  // Service Area
  coverage: string;
  travelTimes: string;
  workload: string;
  
  // Availability
  calendar: string;
  
  // Policies
  policies: string;
  guardrails: string;
  requiredQuestions: string;
  bookingDelivery: string;
  foodSettings: string;
  dispatchSettings: string;
  hipaa: string;
  
  // AI Behavior
  scripts: string;
  guidelines: string;
  intelligence: string;
  
  // Knowledge
  review: string;
  faqs: string;
  objections: string;
  custom: string;
  documents: string;

  // NEW: Dynamic completion tracking (from useBrainCompletion)
  completionStats: {
    completed: number;
    total: number;
    percentage: number;
    incompleteItems: { section: string; label: string }[];
  };
  
  // Extended completion info
  fullCompletionStats: CompletionStats;
}

export function useBrainSummaries(): BrainSummaries {
  const { tenant } = useAuth();
  const fullCompletionStats = useBrainCompletion();

  // Fetch tenant data for multiple sections
  const { data: tenantData } = useQuery({
    queryKey: ["brain-summaries-tenant", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data } = await supabase
        .from("tenants")
        .select("business_mode, cancellation_policy, deposit_policy, refund_policy, ai_never_promise, ai_policies_json")
        .eq("id", tenant.id)
        .single();
      return data;
    },
    enabled: !!tenant?.id,
    staleTime: 30000,
  });

  // Fetch AI assistant for greeting script
  const { data: assistantData } = useQuery({
    queryKey: ["brain-summaries-assistant", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data } = await supabase
        .from("ai_assistants")
        .select("greeting_script")
        .eq("tenant_id", tenant.id)
        .single();
      return data;
    },
    enabled: !!tenant?.id,
    staleTime: 30000,
  });

  // Fetch counts for various entities
  const { data: counts } = useQuery({
    queryKey: ["brain-summaries-counts", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      
      const [services, faqs, objections, knowledge, slots] = await Promise.all([
        supabase.from("services").select("id", { count: "exact", head: true }).eq("tenant_id", tenant.id).eq("is_active", true),
        supabase.from("business_faqs").select("id", { count: "exact", head: true }).eq("tenant_id", tenant.id),
        supabase.from("objection_responses").select("id", { count: "exact", head: true }).eq("tenant_id", tenant.id),
        supabase.from("ai_knowledge_base").select("id", { count: "exact", head: true }).eq("tenant_id", tenant.id),
        supabase.from("availability_slots").select("id", { count: "exact", head: true }).eq("tenant_id", tenant.id).eq("is_available", true),
      ]);

      return {
        services: services.count || 0,
        faqs: faqs.count || 0,
        objections: objections.count || 0,
        knowledge: knowledge.count || 0,
        slots: slots.count || 0,
      };
    },
    enabled: !!tenant?.id,
    staleTime: 30000,
  });

  // Fetch required questions
  const { data: intentRules } = useQuery({
    queryKey: ["brain-summaries-intent-rules", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data } = await supabase
        .from("business_intent_rules")
        .select("action_json")
        .eq("tenant_id", tenant.id)
        .eq("rule_type", "required_inputs" as any);
      return data || [];
    },
    enabled: !!tenant?.id,
    staleTime: 30000,
  });

  // Fetch delivery settings
  const { data: bookingDelivery } = useQuery({
    queryKey: ["brain-summaries-booking-delivery", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data } = await supabase
        .from("booking_delivery_settings")
        .select("enabled, notify_email, webhook_url")
        .eq("tenant_id", tenant.id)
        .single();
      return data;
    },
    enabled: !!tenant?.id,
    staleTime: 30000,
  });

  const { data: dispatchDelivery } = useQuery({
    queryKey: ["brain-summaries-dispatch-delivery", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data } = await supabase
        .from("dispatch_delivery_settings")
        .select("enabled, notify_email, urgent_sms_phone")
        .eq("tenant_id", tenant.id)
        .single();
      return data;
    },
    enabled: !!tenant?.id,
    staleTime: 30000,
  });

  // Fetch calendar connections
  const { data: calendarConnections } = useQuery({
    queryKey: ["brain-summaries-calendar", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data } = await supabase
        .from("calendar_connections")
        .select("provider, status")
        .eq("tenant_id", tenant.id);
      return data || [];
    },
    enabled: !!tenant?.id,
    staleTime: 30000,
  });

  // Build preview strings
  // Check if hours are configured (has at least one non-closed day with windows)
  const hasHoursConfigured = (() => {
    const hoursJson = tenant?.hours_json as unknown as Record<string, { closed?: boolean; windows?: { open: string; close: string }[]; open?: string; close?: string }> | null;
    if (!hoursJson || typeof hoursJson !== "object") return false;
    
    // Check for at least one open day with valid hours
    return Object.values(hoursJson).some(day => {
      if (!day || day.closed) return false;
      // New format: has windows array
      if (Array.isArray(day.windows) && day.windows.length > 0) return true;
      // Legacy format: has open/close times
      if (day.open && day.close) return true;
      return false;
    });
  })();

  return {
    // Profile
    businessInfo: tenant?.name ? `${tenant.name} — Your business identity` : "Not set up yet",
    templates: "Pre-built setups for common business types",

    // Hours - check hours_json instead of availability_slots
    hours: hasHoursConfigured 
      ? "Operating hours configured" 
      : "No hours set yet",

    // Services
    pricingReadiness: "Check if your AI can quote prices",
    pricingRules: "Configure how prices are calculated",
    catalog: counts?.services
      ? `${counts.services} item${counts.services === 1 ? "" : "s"} in catalog`
      : "No services added yet",

    // Service Area
    coverage: "Define where you can serve customers",
    travelTimes: "Set arrival time estimates",
    workload: "Set how busy you are to adjust wait times",

    // Availability
    calendar: (() => {
      if (!calendarConnections || calendarConnections.length === 0) return "Connect your calendar for real-time availability";
      const connected = calendarConnections.filter(c => c.status === "connected");
      if (connected.length === 0) return "Calendar needs reconnection";
      return `${connected.length} calendar${connected.length === 1 ? "" : "s"} connected`;
    })(),

    // Policies
    policies: (() => {
      const parts: string[] = [];
      if (tenantData?.cancellation_policy) parts.push("Cancellation");
      if (tenantData?.deposit_policy) parts.push("Deposit");
      if (tenantData?.refund_policy) parts.push("Refund");
      return parts.length > 0 ? `${parts.join(", ")} policies set` : "No policies set yet";
    })(),
    guardrails: (() => {
      const neverPromise = tenantData?.ai_never_promise;
      if (Array.isArray(neverPromise) && neverPromise.length > 0) {
        return `${neverPromise.length} guardrail${neverPromise.length === 1 ? "" : "s"} set`;
      }
      return "No limits set yet";
    })(),
    requiredQuestions: (() => {
      if (!intentRules || intentRules.length === 0) return "Not set up yet";
      let totalRequired = 0;
      for (const rule of intentRules) {
        const action = rule.action_json as { required_inputs?: string[] } | null;
        if (action?.required_inputs) {
          totalRequired += action.required_inputs.length;
        }
      }
      return totalRequired > 0 
        ? `${totalRequired} required field${totalRequired === 1 ? "" : "s"}` 
        : "No required fields set";
    })(),
    bookingDelivery: (() => {
      if (!bookingDelivery) return "Not set up yet";
      const methods: string[] = [];
      if (bookingDelivery.notify_email) methods.push("Email");
      if (bookingDelivery.webhook_url) methods.push("Webhook");
      if (methods.length === 0) return "No delivery method set";
      return `Sending to ${methods.join(" & ")}`;
    })(),
    foodSettings: "Order pickup and delivery settings",
    dispatchSettings: (() => {
      if (!dispatchDelivery) return "Not set up yet";
      const methods: string[] = [];
      if (dispatchDelivery.notify_email) methods.push("Email");
      if (dispatchDelivery.urgent_sms_phone) methods.push("SMS");
      if (methods.length === 0) return "No notifications set";
      return `Notifying via ${methods.join(" & ")}`;
    })(),
    hipaa: "HIPAA compliance and data retention",

    // AI Behavior
    scripts: assistantData?.greeting_script ? "Custom greeting configured" : "Using the default — customize to match your style",
    guidelines: (() => {
      const policies = tenantData?.ai_policies_json;
      if (Array.isArray(policies) && policies.length > 0) {
        return `${policies.length} guideline${policies.length === 1 ? "" : "s"} set`;
      }
      return "No special instructions yet";
    })(),
    intelligence: "How your AI remembers and improves",

    // Knowledge
    review: "Items needing your approval",
    faqs: counts?.faqs
      ? `${counts.faqs} question${counts.faqs === 1 ? "" : "s"} added`
      : "No questions added yet — your AI says 'I'm not sure' to unknowns",
    objections: counts?.objections
      ? `${counts.objections} response${counts.objections === 1 ? "" : "s"} configured`
      : "No responses set — your AI uses generic replies to pushback",
    custom: counts?.knowledge
      ? `${counts.knowledge} custom fact${counts.knowledge === 1 ? "" : "s"}`
      : "Nothing extra added yet",
    documents: "Uploaded files and references",

    // Completion stats - now using the dynamic completion system
    // Keep legacy format for backward compatibility
    completionStats: (() => {
      const incompleteItems = [
        ...fullCompletionStats.incompleteRequired.map(s => ({
          section: s.field.section,
          label: s.field.label,
        })),
      ];
      
      return {
        completed: fullCompletionStats.completedRequired,
        total: fullCompletionStats.totalRequired,
        percentage: fullCompletionStats.requiredPercentage,
        incompleteItems,
      };
    })(),
    
    // Extended completion info from the new dynamic system
    fullCompletionStats,
  };
}

import { useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useIndustryContext, type IndustryContext } from "@/hooks/useIndustryContext";
import { useCapabilities, type Capabilities } from "@/hooks/useCapabilities";
import { useServices } from "@/hooks/useServices";
import { useKnowledgeGaps, type TopGap } from "@/hooks/useKnowledgeGaps";
import { useConversionMetrics } from "@/hooks/useIntelligence";
import { useCalendarConnections } from "@/hooks/useCalendarConnections";
import type { IndustryTerms } from "@/lib/terminology";
import type { IndustryTerminology } from "@/data/industryTerminology";
import type { BusinessMode } from "@/hooks/useTenantConfig";

export type ComplexityTier = "simple" | "standard" | "complex";

export interface BusinessAwareness {
  // From useIndustryContext
  slug: string | null;
  category: string | null;
  mode: BusinessMode;
  terminology: IndustryTerminology;
  terms: IndustryTerms;

  // From useCapabilities
  caps: Capabilities;

  // From useServices
  serviceCount: number;
  serviceNames: string[];
  servicesWithoutPrices: string[];

  // From useKnowledgeGaps
  gapCount: number;
  topGaps: TopGap[];

  // From useConversionMetrics(30)
  recentCallCount: number;
  conversionRate: number;
  hangupRate: number;

  // From useCalendarConnections
  hasCalendar: boolean;

  // From useAuth
  businessName: string;
  aiBehaviorMode: string;

  // Lightweight query
  staffCount: number;

  // Computed
  complexityTier: ComplexityTier;
  isNewBusiness: boolean;
  hasDataForAnalysis: boolean;
  missingCritical: string[];

  // FAQ count (from knowledge gaps query context)
  faqCount: number;
}

function computeComplexityTier(
  staffCount: number,
  serviceCount: number,
  caps: Capabilities,
): ComplexityTier {
  if (
    staffCount > 5 ||
    caps.hasFleetManagement ||
    caps.hasImpoundLot ||
    serviceCount > 30
  ) {
    return "complex";
  }
  if (staffCount <= 1 && serviceCount < 10 && !caps.hasFleetManagement) {
    return "simple";
  }
  return "standard";
}

/**
 * Composes existing hooks into a single business-aware context.
 * No new DB queries except a lightweight staff count.
 */
export function useBusinessAwareness(): BusinessAwareness {
  const { tenant, assistantSettings } = useAuth();
  const industry = useIndustryContext();
  const caps = useCapabilities();
  const { services } = useServices();
  const { topGaps, totalUnresolvedCount } = useKnowledgeGaps();
  const { metrics } = useConversionMetrics(30);
  const { hasConnectedCalendar } = useCalendarConnections();

  // One lightweight query: staff count
  const { data: staffCount = 0 } = useQuery({
    queryKey: ["staff-count", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count, error } = await supabase
        .from("tenant_users")
        .select("id", { count: "exact", head: true })
        .eq("tenant_id", tenant.id);
      if (error) return 0;
      return count || 0;
    },
    enabled: !!tenant?.id,
    staleTime: 300_000, // 5 minutes — staff rarely changes
  });

  // FAQ count (lightweight, separate from knowledge gaps)
  const { data: faqCount = 0 } = useQuery({
    queryKey: ["faq-count", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return 0;
      const { count, error } = await supabase
        .from("business_faqs")
        .select("id", { count: "exact", head: true })
        .eq("tenant_id", tenant.id);
      if (error) return 0;
      return count || 0;
    },
    enabled: !!tenant?.id,
    staleTime: 60_000,
  });

  return useMemo(() => {
    const activeServices = (services || []).filter((s) => s.is_active !== false);
    const serviceNames = activeServices.slice(0, 10).map((s) => s.name);
    const servicesWithoutPrices = activeServices
      .filter((s) => !s.price_amount && s.price_type !== "quote_only")
      .map((s) => s.name);

    const complexityTier = computeComplexityTier(staffCount, activeServices.length, caps);

    const missingCritical: string[] = [];
    if (activeServices.length === 0 && !caps.isFoodBusiness) missingCritical.push("no_services");
    if (faqCount === 0) missingCritical.push("no_faqs");
    if (!hasConnectedCalendar && caps.hasBooking) missingCritical.push("no_calendar");
    if (!tenant?.hours_json || Object.keys((tenant.hours_json as Record<string, unknown>) || {}).length === 0) {
      missingCritical.push("no_hours");
    }

    return {
      // Industry context
      slug: industry.slug,
      category: industry.category,
      mode: industry.mode,
      terminology: industry.terminology,
      terms: industry.terms,

      // Capabilities
      caps,

      // Services
      serviceCount: activeServices.length,
      serviceNames,
      servicesWithoutPrices,

      // Knowledge gaps
      gapCount: totalUnresolvedCount,
      topGaps: topGaps.slice(0, 5),

      // Conversion metrics (30 days)
      recentCallCount: metrics.totalCalls,
      conversionRate: metrics.conversionRate,
      hangupRate: metrics.hangupRate,

      // Calendar
      hasCalendar: hasConnectedCalendar,

      // Auth/tenant
      businessName: (tenant as any)?.business_name || tenant?.name || "",
      aiBehaviorMode: (assistantSettings as Record<string, unknown>)?.ai_booking_mode as string || "full_service",

      // Staff
      staffCount,

      // Computed
      complexityTier,
      isNewBusiness: metrics.totalCalls < 5,
      hasDataForAnalysis: metrics.totalCalls >= 10,
      missingCritical,

      // FAQ count
      faqCount,
    };
  }, [
    services,
    caps,
    topGaps,
    totalUnresolvedCount,
    metrics,
    hasConnectedCalendar,
    tenant?.id,
    (tenant as any)?.business_name,
    tenant?.hours_json,
    assistantSettings,
    industry,
    staffCount,
    faqCount,
  ]);
}

/**
 * Business Capabilities Discovery Hook
 * 
 * Single source of truth for what a business actually offers/does.
 * Used to conditionally show/hide sections in Business Brain based on
 * the business's actual capabilities rather than just their mode.
 * 
 * This hook aggregates data from multiple sources:
 * - tenants.business_mode
 * - tenants.enabled_modules
 * - tenants.config_json (scenario answers)
 * - food_order_settings
 * - assistant_settings
 * - services table (what they've actually added)
 */

import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useTenantConfig, type BusinessMode } from "./useTenantConfig";
import { useFoodOrderSettings } from "./useFoodOrderSettings";

// ============================================================================
// TYPES
// ============================================================================

export interface FoodCapabilities {
  offersPickup: boolean;
  offersDelivery: boolean;
  offersDineIn: boolean;
  offersCatering: boolean;
  offersReservations: boolean;
  hasMenuItems: boolean;
  needsDeliveryZones: boolean;
  needsCateringSettings: boolean;
  collectsDietaryRestrictions: boolean;
  offersCurbside: boolean;
  hasKDSIntegration: boolean;
  servesAlcohol: boolean;
  offersFamilyMeals: boolean;
  hasLoyaltyProgram: boolean;
  acceptsOnlineOrders: boolean;
  offersMealPrep: boolean;
  handlesGroupOrders: boolean;
  // Cross-mode capabilities
  offersEventBooking: boolean;
}

export interface DispatchCapabilities {
  offersTowing: boolean;
  offersRoadside: boolean;
  hasImpoundLot: boolean;
  offersMotorClub: boolean;
  hasFleet: boolean;
  needsDistancePricing: boolean;
  needsEquipmentFees: boolean;
  needsStorageRates: boolean;
  handlesPoliceImpound: boolean;
  handlesPPITowing: boolean;
  offersRecovery: boolean;
  offersPhoneQuotes: boolean;
  operates24Hours: boolean;
  handlesHeavyDuty: boolean;
  worksWithInsurance: boolean;
  offersStorage: boolean;
  offersLockoutJumpstart: boolean;
  handlesAccidentTowing: boolean;
}

export interface ServiceCapabilities {
  offersMobileService: boolean;
  offersInShopService: boolean;
  offersSameDayEmergency: boolean;
  offersAppointments: boolean;
  offersWalkIns: boolean;
  requiresDeposits: boolean;
  needsServiceArea: boolean;
  needsTravelTimes: boolean;
  hasMultipleStaff: boolean;
  offersPackages: boolean;
  collectsStylistPreference: boolean;
