/**
 * Updates the scenario capability flags stored in tenants.context_fields_json
 * Call this when users answer scenario questions
 */
export async function updateCapabilityFlags(
  tenantId: string,
  flags: Partial<Record<string, boolean>>
): Promise<void> {
  // Fetch current context_fields_json
  const { data: tenant } = await supabase
    .from("tenants")
    .select("context_fields_json")
    .eq("id", tenantId)
    .single();

  const currentConfig = (tenant?.context_fields_json as Record<string, unknown>) || {};
  const currentCapabilities = (currentConfig.capabilities as Record<string, boolean>) || {};

  // Merge new flags
  const updatedCapabilities = {
    ...currentCapabilities,
    ...flags,
  };

  // Save back
  await supabase
    .from("tenants")
    .update({
      context_fields_json: {
        ...currentConfig,
        capabilities: updatedCapabilities,
      },
    })
    .eq("id", tenantId);
}

import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import type { BusinessContext } from "@/types/database";

/**
 * Hook to fetch and manage business context for AI injection
 */
export function useBusinessContext(tenantId: string | null) {
  const [context, setContext] = useState<BusinessContext | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchContext = useCallback(async () => {
    if (!tenantId) {
      setContext(null);
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const { data, error: rpcError } = await supabase.rpc('fn_build_business_context', {
        _tenant_id: tenantId,
      });

      if (rpcError) {
        throw new Error(rpcError.message);
      }

      setContext(data as unknown as BusinessContext);
    } catch (err: any) {
      console.error('Failed to fetch business context:', err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [tenantId]);

  useEffect(() => {
    fetchContext();
  }, [fetchContext]);

  return { context, loading, error, refetch: fetchContext };
}

/**
 * Calculate AI readiness score from context
 */
export function calculateReadinessFromContext(context: BusinessContext | null): number {
  if (!context) return 0;

  let score = 0;

  // Business identity (20 points)
  if (context.business.name) score += 5;
  if (context.business.phone) score += 5;
  if (context.business.address) score += 5;
  if (context.business.tagline) score += 5;

  // Services (20 points)
  const serviceCount = context.services?.length || 0;
  if (serviceCount >= 1) score += 10;
  if (serviceCount >= 3) score += 10;

  // Hours (10 points)
  if (context.hours && Object.keys(context.hours).length > 0) score += 10;

  // Policies (15 points)
  if (context.policies.cancellation) score += 5;
  if (context.policies.deposit) score += 5;
  if (context.policies.payment_methods && context.policies.payment_methods.length > 0) score += 5;

  // FAQs (20 points)
  const faqCount = context.faqs?.length || 0;
  if (faqCount >= 3) score += 10;
  if (faqCount >= 6) score += 10;

  // Objections (15 points)
  const objectionCount = context.objection_responses?.length || 0;
  if (objectionCount >= 2) score += 8;
  if (objectionCount >= 4) score += 7;

  return Math.min(score, 100);
}

/**
 * Get missing items for AI knowledge gaps
 */
export function getMissingKnowledge(context: BusinessContext | null): string[] {
  if (!context) return ['No business data configured'];

  const missing: string[] = [];

  if (!context.business.name) missing.push('Business name');
  if (!context.business.phone) missing.push('Public phone number');
  if (!context.business.address) missing.push('Business address');
  
  if (!context.services || context.services.length === 0) {
    missing.push('Services and pricing');
  }

  if (!context.hours || Object.keys(context.hours).length === 0) {
    missing.push('Business hours');
  }

  if (!context.policies.cancellation) missing.push('Cancellation policy');
  if (!context.policies.deposit) missing.push('Deposit policy');
  if (!context.policies.payment_methods || context.policies.payment_methods.length === 0) {
    missing.push('Payment methods');
  }

  if (!context.faqs || context.faqs.length < 3) {
    missing.push('FAQs (minimum 3 recommended)');
  }

  if (!context.objection_responses || context.objection_responses.length < 2) {
    missing.push('Objection responses (minimum 2 recommended)');
  }

  return missing;
}

/**
 * Category-level completion hook
 *
 * Uses the mode-specific `completionSections` from brainModeLayout.ts
 * so percentages always align with the actual tabs shown on the dashboard.
 *
 * Read-only dependency on essentialFields + brainModeLayout.
 */

import { useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useBusinessCapabilities } from "./useBusinessCapabilities";
import { useTenantConfig } from "./useTenantConfig";
import {
  getFieldsForMode,
  shouldShowField,
} from "@/config/essentialFields";
import { isFieldComplete } from "@/lib/brainFieldCompletion";
import { getModeTabDef } from "@/config/brainModeLayout";

// ── Types ──────────────────────────────────────────────────────────────────

export interface CategoryCompletionStats {
  totalFields: number;
  completedFields: number;
  percentage: number;
  hasRequiredIncomplete: boolean;
}

// ── Capability flags builder (shared) ──────────────────────────────────────

function buildCapabilityFlags(capabilities: ReturnType<typeof useBusinessCapabilities>) {
  return {
    offersDelivery: capabilities.food.offersDelivery,
    offersCatering: capabilities.food.offersCatering,
    offersReservations: capabilities.food.offersReservations,
    hasImpoundLot: capabilities.dispatch.hasImpoundLot,
    offersMobileService: capabilities.service.offersMobileService,
    hasTelehealth: capabilities.medical.hasTelehealth,
    needsSymptomTriage: capabilities.medical.needsSymptomTriage,
  };
}

/**
 * Resolve completion sections for a category using the mode layout.
 * Falls back to a static map for legacy/unmapped sections.
 */
function getCompletionSections(mode: string, categorySection: string): string[] {
  // Try mode layout first (source of truth)
  const tabDef = getModeTabDef(mode as any, categorySection);
  if (tabDef && tabDef.completionSections.length > 0) {
    return tabDef.completionSections;
  }

  // Legacy fallback for sections not in mode layout
  const LEGACY_MAP: Record<string, string[]> = {
    business: ["profile", "hours", "calendar"],
    "ai-voice": ["ai-behavior"],
    rules: ["policies"],
  };
  return LEGACY_MAP[categorySection] ?? [];
}

// ── Hooks ──────────────────────────────────────────────────────────────────

/**
 * Completion stats for a single dashboard category.
 */
export function useCategoryCompletion(categorySection: string): CategoryCompletionStats {
  const { tenant } = useAuth();
  const capabilities = useBusinessCapabilities();
  const { businessMode } = useTenantConfig();

  return useMemo(() => {
    const essentialSections = getCompletionSections(businessMode, categorySection);
    if (essentialSections.length === 0) {
      return { totalFields: 0, completedFields: 0, percentage: 100, hasRequiredIncomplete: false };
    }

    const allFields = getFieldsForMode(capabilities.mode);
    const capFlags = buildCapabilityFlags(capabilities);

    const sectionFields = allFields.filter(
      (f) => essentialSections.includes(f.section) && shouldShowField(f, capFlags),
    );

    let completed = 0;
    let hasRequiredIncomplete = false;

    for (const field of sectionFields) {
      if (isFieldComplete(field.id, capabilities, tenant as Record<string, unknown> | null)) {
        completed++;
      } else if (field.priority === "required") {
        hasRequiredIncomplete = true;
      }
    }

    const total = sectionFields.length;
    const percentage = total > 0 ? Math.round((completed / total) * 100) : 100;

    return { totalFields: total, completedFields: completed, percentage, hasRequiredIncomplete };
  }, [categorySection, tenant, capabilities, businessMode]);
}

/**
 * Completion stats for dashboard categories.
 * Uses mode-aware completion sections from brainModeLayout.ts.
 * Pass specific section keys to compute only for those categories.
 */
export function useAllCategoriesCompletion(
  sectionKeys?: string[],
): Record<string, CategoryCompletionStats> {
  const { tenant } = useAuth();
  const capabilities = useBusinessCapabilities();
  const { businessMode } = useTenantConfig();

  return useMemo(() => {
    const allFields = getFieldsForMode(capabilities.mode);
    const capFlags = buildCapabilityFlags(capabilities);

    const result: Record<string, CategoryCompletionStats> = {};

    // Default section keys: the standard mode tabs
    const keys = sectionKeys ?? ["about", "services", "operations", "training"];

    for (const catSection of keys) {
      const essentialSections = getCompletionSections(businessMode, catSection);

      if (essentialSections.length === 0) {
        result[catSection] = { totalFields: 0, completedFields: 0, percentage: 100, hasRequiredIncomplete: false };
        continue;
      }

      const sectionFields = allFields.filter(
        (f) => essentialSections.includes(f.section) && shouldShowField(f, capFlags),
      );

      let completed = 0;
      let hasRequiredIncomplete = false;

      for (const field of sectionFields) {
        if (isFieldComplete(field.id, capabilities, tenant as Record<string, unknown> | null)) {
          completed++;
        } else if (field.priority === "required") {
          hasRequiredIncomplete = true;
        }
      }

      const total = sectionFields.length;
      const percentage = total > 0 ? Math.round((completed / total) * 100) : 100;

      result[catSection] = { totalFields: total, completedFields: completed, percentage, hasRequiredIncomplete };
    }

    return result;
  }, [tenant, capabilities, sectionKeys, businessMode]);
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";
import type { Database } from "@/integrations/supabase/types";

type Conversation = Database["public"]["Tables"]["conversations"]["Row"];
type Message = Database["public"]["Tables"]["messages"]["Row"];
type Lead = Database["public"]["Tables"]["leads"]["Row"];

export interface ConversationWithDetails extends Conversation {
  lead: Lead | null;
  messages: Message[];
  lastMessage?: Message | null;
}

export function useConversations() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const conversationsQuery = useQuery({
    queryKey: ["conversations", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      
      // Fetch conversations with lead info
      const { data: convos, error: convosError } = await supabase
        .from("conversations")
        .select(`
          *,
          lead:leads(*)
        `)
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false });

      if (convosError) throw convosError;

      // Fetch messages for all conversations
      const convoIds = convos.map((c) => c.id);
      if (convoIds.length === 0) return [];

      const { data: messages, error: msgsError } = await supabase
        .from("messages")
        .select("*")
        .in("conversation_id", convoIds)
        .order("sent_at", { ascending: false })
        .limit(100);

      if (msgsError) throw msgsError;

      // Group messages by conversation and attach last message
      const messagesByConvo = messages.reduce((acc, msg) => {
        if (!acc[msg.conversation_id]) {
          acc[msg.conversation_id] = [];
        }
        acc[msg.conversation_id].push(msg);
        return acc;
      }, {} as Record<string, Message[]>);

      return convos.map((convo) => ({
        ...convo,
        messages: messagesByConvo[convo.id] || [],
        lastMessage: messagesByConvo[convo.id]?.[0] || null,
      })) as ConversationWithDetails[];
    },
    enabled: !!tenant?.id,
  });

  return {
    conversations: conversationsQuery.data ?? [],
    isLoading: conversationsQuery.isLoading,
    error: conversationsQuery.error,
    refetch: conversationsQuery.refetch,
  };
}

export function useMessages(conversationId: string | null) {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const messagesQuery = useQuery({
    queryKey: ["messages", conversationId],
    queryFn: async () => {
      if (!conversationId) return [];
      
      const { data, error } = await supabase
        .from("messages")
        .select("*")
        .eq("conversation_id", conversationId)
        .order("sent_at", { ascending: true });

      if (error) throw error;
      return data as Message[];
    },
    enabled: !!conversationId,
  });

  const sendMessage = useMutation({
    mutationFn: async ({ body }: { body: string }) => {
      if (!conversationId || !tenant?.id) throw new Error("Missing context");
      
      const { data, error } = await supabase
        .from("messages")
        .insert({
          conversation_id: conversationId,
          tenant_id: tenant.id,
          body,
          direction: "outbound" as const,
          status: "queued" as const,
        })
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["messages", conversationId] });
      queryClient.invalidateQueries({ queryKey: ["conversations", tenant?.id] });
    },
    onError: (error) => {
      toast({ title: "Failed to send", description: error.message, variant: "destructive" });
    },
  });

  return {
    messages: messagesQuery.data ?? [],
    isLoading: messagesQuery.isLoading,
    error: messagesQuery.error,
    sendMessage,
    refetch: messagesQuery.refetch,
  };
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";

interface CustomerEnrichment {
  customerId: string;
  lastServiceDate: string | null;
  recentCallCount: number;
}

/**
 * Batch-fetches last service date and recent call count for all customers
 * belonging to the current tenant.
 */
export function useCustomerEnrichment(customerIds: string[]) {
  const { tenant } = useAuth();
  const tenantId = tenant?.id ?? null;

  return useQuery({
    queryKey: ["customer-enrichment", tenantId, customerIds.length],
    queryFn: async (): Promise<Map<string, CustomerEnrichment>> => {
      if (!tenantId || customerIds.length === 0) return new Map();

      const map = new Map<string, CustomerEnrichment>();

      // Fetch most recent completed booking per customer via lead linkage
      // Bookings link through leads, so we join leads -> bookings
      const { data: bookings } = await supabase
        .from("bookings")
        .select("lead_id, start_at, status, leads!inner(customer_id)")
        .eq("tenant_id", tenantId)
        .eq("status", "completed")
        .order("start_at", { ascending: false });

      // Build last-service map by customer_id
      const lastServiceMap = new Map<string, string>();
      for (const b of bookings || []) {
        const custId = (b.leads as any)?.customer_id;
        if (custId && !lastServiceMap.has(custId)) {
          lastServiceMap.set(custId, b.start_at);
        }
      }

      // Fetch recent call counts (last 30 days)
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

      const { data: calls } = await supabase
        .from("ai_call_sessions")
        .select("customer_id")
        .eq("tenant_id", tenantId)
        .in("customer_id", customerIds)
        .gte("started_at", thirtyDaysAgo.toISOString());

      const callCountMap = new Map<string, number>();
      for (const c of calls || []) {
        if (c.customer_id) {
          callCountMap.set(c.customer_id, (callCountMap.get(c.customer_id) || 0) + 1);
        }
      }

      for (const id of customerIds) {
        map.set(id, {
          customerId: id,
          lastServiceDate: lastServiceMap.get(id) ?? null,
          recentCallCount: callCountMap.get(id) ?? 0,
        });
      }

      return map;
    },
    enabled: !!tenantId && customerIds.length > 0,
    staleTime: 60000,
  });
}

import { supabase } from "@/integrations/supabase/client";
import type { CustomerResolverResult } from "@/types/database";
import type { Json } from "@/integrations/supabase/types";

/**
 * Normalizes a phone number to E.164 format (client-side version)
 */
export function normalizePhoneE164(phone: string): string | null {
  if (!phone || phone.trim() === '') {
    return null;
  }

  // Remove all non-digit characters except leading +
  const cleaned = phone.replace(/[^0-9+]/g, '');

  // If starts with +, keep it
  if (cleaned.startsWith('+')) {
    return cleaned;
  }

  // If 10 digits, assume US and add +1
  if (cleaned.length === 10) {
    return '+1' + cleaned;
  }

  // If 11 digits starting with 1, add +
  if (cleaned.length === 11 && cleaned.startsWith('1')) {
    return '+' + cleaned;
  }

  // Otherwise return as-is with + prefix
  return '+' + cleaned;
}

/**
 * Resolves a customer by phone number using the database resolver function.
 * Creates a new customer if not found, or returns existing customer and flags conflicts.
 */
export async function resolveCustomer(
  tenantId: string,
  phone: string,
  name?: string,
  email?: string,
  source: string = 'manual'
): Promise<CustomerResolverResult> {
  const { data, error } = await supabase.rpc('resolve_customer', {
    _tenant_id: tenantId,
    _phone: phone,
    _name: name || null,
    _email: email || null,
    _source: source,
  });

  if (error) {
    throw new Error(`Failed to resolve customer: ${error.message}`);
  }

  if (!data || data.length === 0) {
    throw new Error('Customer resolver returned no data');
  }

  const result = data[0];
  return {
    customer_id: result.customer_id,
    is_new: result.is_new,
    has_conflict: result.has_conflict,
    conflict_id: result.conflict_id,
  };
}

/**
 * Creates an opportunity for a customer
 */
export async function createOpportunity(
  tenantId: string,
  customerId: string,
  source: string,
  serviceId?: string,
  notes?: string,
  contextJson?: Record<string, unknown>
): Promise<string> {
  const { data, error } = await supabase
    .from('opportunities')
    .insert([{
      tenant_id: tenantId,
      customer_id: customerId,
      service_id: serviceId || null,
      source,
      notes: notes || null,
      context_json: (contextJson || {}) as Json,
      status: 'new',
    }])
    .select('id')
    .single();

  if (error) {
    throw new Error(`Failed to create opportunity: ${error.message}`);
  }

  return data.id;
}

/**
 * Logs a knowledge gap when AI couldn't answer a question
 */
export async function logKnowledgeGap(
  tenantId: string,
  gapType: string,
  description: string,
  customerQuestion?: string,
  aiSessionId?: string,
  priority: number = 1
): Promise<void> {
  // Check if similar gap already exists (to increment count instead of duplicating)
  const { data: existing } = await supabase
    .from('knowledge_gaps')
    .select('id, occurrence_count')
    .eq('tenant_id', tenantId)
    .eq('gap_type', gapType)
    .eq('description', description)
    .eq('resolved', false)
    .single();

  if (existing) {
    // Increment occurrence count
    await supabase
      .from('knowledge_gaps')
      .update({ 
        occurrence_count: existing.occurrence_count + 1,
        priority: Math.min(priority + 1, 3), // Increase priority if recurring
      })
      .eq('id', existing.id);
  } else {
    // Create new gap
    await supabase
      .from('knowledge_gaps')
      .insert({
        tenant_id: tenantId,
        gap_type: gapType as any,
        description,
        customer_question: customerQuestion || null,
        ai_session_id: aiSessionId || null,
        priority,
      });
  }
}

/**
 * Creates a sync event for external integrations (Sheets, CRM, etc.)
 */
export async function createSyncEvent(
  tenantId: string,
  eventType: string,
  entityType: string,
  entityId: string,
  payload: Record<string, unknown>,
  syncTarget?: string
): Promise<void> {
  await supabase
    .from('sync_events')
    .insert([{
      tenant_id: tenantId,
      event_type: eventType as any,
      entity_type: entityType,
      entity_id: entityId,
      payload_json: payload as Json,
      sync_target: syncTarget || null,
    }]);
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";

export interface CustomerVehicle {
  id: string;
  tenant_id: string;
  customer_id: string;
  year: number | null;
  make: string | null;
  model: string | null;
  color: string | null;
  vin: string | null;
  license_plate: string | null;
  notes: string | null;
  created_at: string;
  updated_at: string;
}

export type VehicleInput = {
  customer_id: string;
  year?: number | null;
  make?: string;
  model?: string;
  color?: string;
  vin?: string;
  license_plate?: string;
  notes?: string;
};

export function useCustomerVehicles(customerId: string | null) {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const queryKey = ["customer-vehicles", tenant?.id, customerId];

  const vehiclesQuery = useQuery({
    queryKey,
    queryFn: async () => {
      if (!tenant?.id || !customerId) return [];
      const { data, error } = await (supabase as any)
        .from("customer_vehicles")
        .select("*")
        .eq("tenant_id", tenant.id)
        .eq("customer_id", customerId)
        .order("created_at", { ascending: false });
      if (error) throw error;
      return (data ?? []) as CustomerVehicle[];
    },
    enabled: !!tenant?.id && !!customerId,
  });

  const addVehicle = useMutation({
    mutationFn: async (input: VehicleInput) => {
      if (!tenant?.id) throw new Error("No tenant");
      const { data, error } = await (supabase as any)
        .from("customer_vehicles")
        .insert({
          tenant_id: tenant.id,
          customer_id: input.customer_id,
          year: input.year || null,
          make: input.make || null,
          model: input.model || null,
          color: input.color || null,
          vin: input.vin || null,
          license_plate: input.license_plate || null,
          notes: input.notes || null,
        })
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success("Vehicle added");
    },
    onError: () => toast.error("Failed to add vehicle"),
  });

  const updateVehicle = useMutation({
    mutationFn: async ({ id, ...updates }: Partial<CustomerVehicle> & { id: string }) => {
      const { data, error } = await (supabase as any)
        .from("customer_vehicles")
        .update(updates)
        .eq("id", id)
        .select()
        .single();
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success("Vehicle updated");
    },
    onError: () => toast.error("Failed to update vehicle"),
  });

  const deleteVehicle = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await (supabase as any)
        .from("customer_vehicles")
        .delete()
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
      toast.success("Vehicle removed");
    },
    onError: () => toast.error("Failed to remove vehicle"),
  });

  return {
    vehicles: vehiclesQuery.data ?? [],
    isLoading: vehiclesQuery.isLoading,
    addVehicle,
    updateVehicle,
    deleteVehicle,
  };
}

/**
 * useDispatchMutations — extracted CRUD mutations for dispatch_jobs.
 *
 * Replaces inline mutations scattered across DispatchPage.
 */
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";

export function useDispatchMutations() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: ["dispatch-jobs", tenant?.id] });
    queryClient.invalidateQueries({ queryKey: ["dispatch-dashboard", tenant?.id] });
  };

  /** Generic update — used by other convenience mutations */
  const updateJob = useMutation({
    mutationFn: async ({ jobId, updates }: { jobId: string; updates: Record<string, unknown> }) => {
      const { error } = await supabase
        .from("dispatch_jobs")
        .update(updates)
        .eq("id", jobId);
      if (error) throw error;
    },
    onSuccess: () => {
      invalidate();
      toast({ title: "Job updated" });
    },
    onError: (error) => {
      toast({ title: "Failed to update job", description: String(error), variant: "destructive" });
    },
  });

  /** Update job status with auto-timestamps */
  const updateStatus = useMutation({
    mutationFn: async ({ jobId, status }: { jobId: string; status: string }) => {
      const updates: Record<string, unknown> = { status };
      if (status === "completed") updates.completed_at = new Date().toISOString();
      if (status === "on_site") updates.arrived_at = new Date().toISOString();
      if (status === "en_route") updates.dispatched_at = updates.dispatched_at || new Date().toISOString();
      const { error } = await supabase
        .from("dispatch_jobs")
        .update(updates)
        .eq("id", jobId);
      if (error) throw error;

      // Trigger workflow for completed jobs
      if (status === "completed" && tenant?.id) {
        supabase.functions.invoke("trigger-workflow", {
          body: {
            tenant_id: tenant.id,
            trigger: "dispatch_job.completed",
            entity_type: "dispatch_job",
            entity_id: jobId,
          },
        }).catch((err) => console.error("trigger-workflow error:", err));
      }
    },
    onSuccess: (_, { status }) => {
      invalidate();
      const label = STATUS_LABELS[status] || status;
      toast({ title: `Job ${label.toLowerCase()}` });
    },
    onError: (error) => {
      toast({ title: "Failed to update status", description: String(error), variant: "destructive" });
    },
  });

  /** Assign a job to a driver/vehicle */
  const assignJob = useMutation({
    mutationFn: async ({
      jobId,
      crew,
      vehicle,
      driverId,
      vehicleId,
    }: {
      jobId: string;
      crew?: string;
      vehicle?: string;
      driverId?: string;
      vehicleId?: string;
    }) => {
      const updates: Record<string, unknown> = {
        status: "assigned",
        assigned_crew: crew || null,
        assigned_vehicle: vehicle || null,
        driver_id: driverId || null,
        vehicle_id: vehicleId || null,
        dispatched_at: new Date().toISOString(),
      };
      const { error } = await supabase
        .from("dispatch_jobs")
        .update(updates)
        .eq("id", jobId);
      if (error) throw error;
    },
    onSuccess: () => {
      invalidate();
      toast({ title: "Job assigned" });
    },
    onError: (error) => {
      toast({ title: "Failed to assign job", description: String(error), variant: "destructive" });
    },
  });

  /** Cancel a dispatch job */
  const cancelJob = useMutation({
    mutationFn: async ({ jobId, reason }: { jobId: string; reason?: string }) => {
      const updates: Record<string, unknown> = {
        status: "cancelled",
        completed_at: new Date().toISOString(),
      };
      if (reason) updates.notes = reason;
      const { error } = await supabase
        .from("dispatch_jobs")
        .update(updates)
        .eq("id", jobId);
      if (error) throw error;
    },
    onSuccess: () => {
      invalidate();
      toast({ title: "Job cancelled" });
    },
    onError: (error) => {
      toast({ title: "Failed to cancel job", description: String(error), variant: "destructive" });
    },
  });

  /** Create a new dispatch job */
  const createJob = useMutation({
    mutationFn: async (data: {
      customer_name: string;
      customer_phone?: string;
      pickup_address?: string;
      dropoff_address?: string;
      job_type?: string;
      priority?: string;
      description?: string;
      notes?: string;
      price_cents?: number;
    }) => {
      if (!tenant?.id) throw new Error("No tenant");
      const jobNum = `JOB-${Date.now().toString(36).toUpperCase()}`;
      const { data: job, error } = await (supabase as any)
        .from("dispatch_jobs")
        .insert({
          tenant_id: tenant.id,
          job_number: jobNum,
          customer_name: data.customer_name,
          customer_phone: data.customer_phone || null,
          pickup_address: data.pickup_address || null,
          dropoff_address: data.dropoff_address || null,
          job_type: data.job_type || null,
          priority: data.priority || "normal",
          description: data.description || null,
          notes: data.notes || null,
          price_cents: data.price_cents || null,
          status: "pending",
        })
        .select()
        .single();
      if (error) throw error;
      return job;
    },
    onSuccess: () => {
      invalidate();
      toast({ title: "Job created" });
    },
    onError: (error) => {
      toast({ title: "Failed to create job", description: String(error), variant: "destructive" });
    },
  });

  /** Mark a job as paid */
  const markPaid = useMutation({
    mutationFn: async ({ jobId, paymentMethod }: { jobId: string; paymentMethod?: string }) => {
      const { error } = await supabase
        .from("dispatch_jobs")
        .update({
          payment_status: "paid",
          payment_method: paymentMethod || "cash",
        } as any)
        .eq("id", jobId);
      if (error) throw error;
    },
    onSuccess: () => {
      invalidate();
      toast({ title: "Marked as paid" });
    },
    onError: (error) => {
      toast({ title: "Failed to mark as paid", description: String(error), variant: "destructive" });
    },
  });

  return {
    updateJob,
    updateStatus,
    assignJob,
    cancelJob,
    createJob,
    markPaid,
  };
}

const STATUS_LABELS: Record<string, string> = {
  pending: "Pending",
  assigned: "Assigned",
  en_route: "En Route",
  on_site: "On Site",
  completed: "Completed",
  cancelled: "Cancelled",
};

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";

export interface EstimateLineItem {
  id: string;
  name: string;
  description?: string;
  quantity: number;
  unit_price_cents: number;
  total_cents: number;
}

export interface PricingOption {
  id: string;
  name: string; // "Basic", "Standard", "Premium"
  description?: string;
  line_items: EstimateLineItem[];
  total_cents: number;
}

export interface Estimate {
  id: string;
  tenant_id: string;
  customer_id: string | null;
  job_id: string | null;
  booking_id: string | null;
  estimate_number: string;
  title: string | null;
  status: "draft" | "sent" | "viewed" | "accepted" | "declined" | "expired" | "converted";
  line_items: EstimateLineItem[];
  pricing_options: PricingOption[] | null;
  selected_option: string | null;
  subtotal_cents: number | null;
  tax_rate_percent: number | null;
  tax_cents: number | null;
  discount_cents: number | null;
  total_cents: number | null;
  valid_until: string | null;
  signature_data: string | null;
  signed_at: string | null;
  pdf_url: string | null;
  internal_notes: string | null;
  customer_notes: string | null;
  terms_and_conditions: string | null;
  sent_at: string | null;
  viewed_at: string | null;
  created_at: string;
  updated_at: string;
}

export interface EstimateWithCustomer extends Estimate {
  customer?: {
    id: string;
    full_name: string | null;
    phone_e164: string | null;
    email: string | null;
  } | null;
}

export interface CreateEstimateInput {
  customer_id?: string;
  job_id?: string;
  booking_id?: string;
  title?: string;
  line_items: EstimateLineItem[];
  pricing_options?: PricingOption[];
  tax_rate_percent?: number;
  discount_cents?: number;
  valid_until?: string;
  internal_notes?: string;
  customer_notes?: string;
  terms_and_conditions?: string;
}

export interface UpdateEstimateInput extends Partial<CreateEstimateInput> {
  id: string;
  status?: Estimate["status"];
}

// Generate next estimate number
async function generateEstimateNumber(tenantId: string): Promise<string> {
  const prefix = "EST";
  const year = new Date().getFullYear().toString().slice(-2);

  try {
    const { data, error } = await supabase
      .from("estimates")
      .select("estimate_number")
      .eq("tenant_id", tenantId)
      .order("created_at", { ascending: false })
      .limit(1);

    if (error || !data || data.length === 0) {
      return `${prefix}-${year}-0001`;
    }

    const lastNumber = data[0].estimate_number;
    const match = lastNumber.match(/(\d+)$/);
    const nextNum = match ? parseInt(match[1], 10) + 1 : 1;

    return `${prefix}-${year}-${nextNum.toString().padStart(4, "0")}`;
  } catch {
    // If table doesn't exist, return first estimate number
    return `${prefix}-${year}-0001`;
  }
}

// Calculate totals from line items
function calculateTotals(
  lineItems: EstimateLineItem[],
  taxRatePercent: number = 0,
  discountCents: number = 0
): { subtotal: number; tax: number; total: number } {
  const subtotal = lineItems.reduce((sum, item) => sum + item.total_cents, 0);
  const taxableAmount = subtotal - discountCents;
  const tax = Math.round((taxableAmount * taxRatePercent) / 100);
  const total = subtotal - discountCents + tax;

  return { subtotal, tax, total };
}

export function useEstimates() {
  const { tenant } = useAuth();
  const tenantId = tenant?.id ?? null;
  const { toast } = useToast();
  const queryClient = useQueryClient();

  // Fetch all estimates for the tenant
  // Note: Gracefully handles the case where the estimates table doesn't exist yet
  const {
    data: estimates = [],
    isLoading,
    error,
    refetch,
  } = useQuery({
    queryKey: ["estimates", tenantId],
    queryFn: async () => {
      if (!tenantId) return [];

      try {
        const { data, error } = await supabase
          .from("estimates")
          .select(`
            *,
            customer:customers(id, full_name, phone_e164, email)
          `)
          .eq("tenant_id", tenantId)
          .order("created_at", { ascending: false });

        if (error) {
          console.error("Failed to fetch estimates:", error);
          return [];
        }
      return (data || []).map((item: any) => ({
        ...item,
        line_items: Array.isArray(item.line_items) ? item.line_items : [],
        pricing_options: Array.isArray(item.pricing_options) ? item.pricing_options : null,
        customer: item.customer && !item.customer.error ? item.customer : null,
      })) as EstimateWithCustomer[];
      } catch (err) {
        console.error("Failed to fetch estimates:", err);
        return [];
      }
    },
    enabled: !!tenantId,
    retry: false, // Don't retry on failure
    staleTime: 30 * 1000, // Cache for 30 seconds
  });

  // Create estimate mutation
  const createEstimate = useMutation({
    mutationFn: async (input: CreateEstimateInput) => {
      if (!tenantId) throw new Error("No tenant ID");

      const estimateNumber = await generateEstimateNumber(tenantId);
      const { subtotal, tax, total } = calculateTotals(
        input.line_items,
        input.tax_rate_percent || 0,
        input.discount_cents || 0
      );

      const { data, error } = await supabase
        .from("estimates")
        .insert({
          tenant_id: tenantId as string,
          customer_id: input.customer_id || null,
          job_id: input.job_id || null,
          booking_id: input.booking_id || null,
          estimate_number: estimateNumber,
          title: input.title || null,
          status: "draft",
          line_items: input.line_items as unknown as any,
          pricing_options: (input.pricing_options || null) as unknown as any,
          subtotal_cents: subtotal,
          tax_rate_percent: input.tax_rate_percent || 0,
          tax_cents: tax,
          discount_cents: input.discount_cents || 0,
          total_cents: total,
          valid_until: input.valid_until || null,
          internal_notes: input.internal_notes || null,
          customer_notes: input.customer_notes || null,
          terms_and_conditions: input.terms_and_conditions || null,
        })
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["estimates", tenantId] });
      toast({ title: "Estimate created", description: "Your estimate has been saved as a draft." });
    },
    onError: (error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  // Update estimate mutation
  const updateEstimate = useMutation({
    mutationFn: async (input: UpdateEstimateInput) => {
      const { id, ...updates } = input;

      // Recalculate totals if line items changed
      let totals = {};
      if (updates.line_items) {
        const calculated = calculateTotals(
          updates.line_items,
          updates.tax_rate_percent || 0,
          updates.discount_cents || 0
        );
        totals = {
          subtotal_cents: calculated.subtotal,
          tax_cents: calculated.tax,
          total_cents: calculated.total,
        };
      }

      const { data, error } = await supabase
        .from("estimates")
        .update({
          ...(updates as any),
          ...totals,
          updated_at: new Date().toISOString(),
        })
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["estimates", tenantId] });
      toast({ title: "Estimate updated" });
    },
    onError: (error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  // Send estimate to customer via email
  const sendEstimate = useMutation({
    mutationFn: async ({ estimateId }: { estimateId: string; email?: string }) => {
      // Call the edge function to send the email
      const { data, error } = await supabase.functions.invoke("estimate-send-email", {
        body: { estimate_id: estimateId },
      });

      if (error) throw error;
      if (!data?.success) throw new Error(data?.error || "Failed to send estimate");

      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["estimates", tenantId] });
      toast({ title: "Estimate sent", description: "The customer will receive an email with the estimate." });
    },
    onError: (error) => {
      toast({ title: "Error sending estimate", description: error.message, variant: "destructive" });
    },
  });

  // Delete estimate
  const deleteEstimate = useMutation({
    mutationFn: async (estimateId: string) => {
      const { error } = await supabase
        .from("estimates")
        .delete()
        .eq("id", estimateId);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["estimates", tenantId] });
      toast({ title: "Estimate deleted" });
    },
    onError: (error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  // Calculate stats
  const stats = {
    total: estimates.length,
    draft: estimates.filter((e) => e.status === "draft").length,
    sent: estimates.filter((e) => e.status === "sent").length,
    viewed: estimates.filter((e) => e.status === "viewed").length,
    accepted: estimates.filter((e) => e.status === "accepted").length,
    declined: estimates.filter((e) => e.status === "declined").length,
    totalValue: estimates
      .filter((e) => e.status === "accepted")
      .reduce((sum, e) => sum + (e.total_cents || 0), 0),
  };

  return {
    estimates,
    isLoading,
    error,
    stats,
    refetch,
    createEstimate,
    updateEstimate,
    sendEstimate,
    deleteEstimate,
  };
}

export function useEstimate(estimateId: string | undefined) {
  const { tenant } = useAuth();
  const tenantId = tenant?.id ?? null;

  return useQuery({
    queryKey: ["estimate", estimateId],
    queryFn: async () => {
      if (!estimateId || !tenantId) return null;

      const { data, error } = await supabase
        .from("estimates")
        .select(`
          *,
          customer:customers(id, full_name, phone_e164, email)
        `)
        .eq("id", estimateId)
        .eq("tenant_id", tenantId)
        .single();

      if (error) throw error;
      const result = {
        ...(data as any),
        line_items: Array.isArray((data as any).line_items) ? (data as any).line_items : [],
        pricing_options: Array.isArray((data as any).pricing_options) ? (data as any).pricing_options : null,
        customer: (data as any).customer && !((data as any).customer as any).error ? (data as any).customer : null,
      };
      return result as unknown as EstimateWithCustomer;
    },
    enabled: !!estimateId && !!tenantId,
  });
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";

export interface FieldEdgeIntegration {
  id: string;
  is_active: boolean;
  last_synced_at: string | null;
  config_json: {
    base_url?: string;
    company_name?: string;
  };
}

export function useFieldEdgeIntegration() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  const integrationQuery = useQuery({
    queryKey: ["fieldedge-integration", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data, error } = await (supabase as any)
        .from("tenant_integrations")
        .select("id, is_active, last_synced_at, config_json")
        .eq("tenant_id", tenant.id)
        .eq("provider", "fieldedge")
        .maybeSingle();

      if (error) throw error;
      return data as FieldEdgeIntegration | null;
    },
    enabled: !!tenant?.id,
  });

  const authenticate = useMutation({
    mutationFn: async ({ api_key, base_url }: { api_key: string; base_url?: string }) => {
      const { data, error } = await supabase.functions.invoke("fieldedge-auth", {
        body: { action: "connect", api_key, base_url, tenant_id: tenant?.id },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["fieldedge-integration", tenant?.id] });
      toast.success("Connected to FieldEdge!");
    },
    onError: (err: Error) => {
      toast.error(err.message || "Failed to connect to FieldEdge");
    },
  });

  const toggle = useMutation({
    mutationFn: async (is_active: boolean) => {
      const { data, error } = await supabase.functions.invoke("fieldedge-auth", {
        body: { action: "toggle", is_active, tenant_id: tenant?.id },
      });
      if (error) throw error;
      return data;
    },
    onSuccess: (_, is_active) => {
      queryClient.invalidateQueries({ queryKey: ["fieldedge-integration", tenant?.id] });
      toast.success(is_active ? "Sync resumed" : "Sync paused");
    },
  });

  const syncNow = useMutation({
    mutationFn: async () => {
      const { data, error } = await supabase.functions.invoke("sync-fieldedge", {
        body: { tenant_id: tenant?.id },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      return data;
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["fieldedge-integration", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["active-jobs", tenant?.id] });
      const r = data?.results || {};
      toast.success(`Synced: ${r.created || 0} new, ${r.updated || 0} updated`);
    },
    onError: (err: Error) => {
      toast.error(err.message || "Sync failed");
    },
  });

  const disconnect = useMutation({
    mutationFn: async () => {
      const { data, error } = await supabase.functions.invoke("fieldedge-auth", {
        body: { action: "disconnect", tenant_id: tenant?.id },
      });
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["fieldedge-integration", tenant?.id] });
      toast.success("FieldEdge disconnected");
    },
  });

  return {
    integration: integrationQuery.data,
    isLoading: integrationQuery.isLoading,
    isConnected: !!integrationQuery.data?.is_active,
    authenticate,
    toggle,
    syncNow,
    disconnect,
  };
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

/**
 * Automated Golden Path checks - verifies end-to-end functionality
 */

export interface AutoCheck {
  id: string;
  label: string;
  description: string;
  category: "provisioning" | "telephony" | "webhook" | "extraction" | "entity" | "calendar" | "automation";
  passed: boolean;
  details?: string;
  value?: string | number | null;
}

export interface GoldenPathCheckResult {
  checks: AutoCheck[];
  loading: boolean;
  refetch: () => void;
}

export function useGoldenPathChecks(tenantId: string | null): GoldenPathCheckResult {
  const query = useQuery({
    queryKey: ["golden-path-checks", tenantId],
    queryFn: async (): Promise<AutoCheck[]> => {
      if (!tenantId) return [];
      
      const checks: AutoCheck[] = [];

      // 1. Subscription -> hasVoiceFeature -> Twilio provisioning -> phone_numbers row
      const { data: subscription } = await supabase
        .from("subscriptions")
        .select("plan_code, status")
        .eq("tenant_id", tenantId)
        .maybeSingle();

      const planCode = subscription?.plan_code || "";
      const hasVoice = planCode.startsWith("voice") || planCode.startsWith("both");
      
      checks.push({
        id: "subscription_sku",
        label: "Subscription SKU set",
        description: "Active subscription with valid plan code",
        category: "provisioning",
        passed: !!subscription && (subscription.status === "active" || subscription.status === "trialing"),
        value: subscription?.plan_code || null,
        details: subscription ? `${subscription.plan_code} (${subscription.status})` : "No subscription",
      });

      const { data: phoneNumbers } = await supabase
        .from("phone_numbers")
        .select("phone_e164, status")
        .eq("tenant_id", tenantId);

      checks.push({
        id: "has_voice_feature",
        label: "Voice feature enabled",
        description: "Plan code includes voice capability",
        category: "provisioning",
        passed: hasVoice,
        details: hasVoice ? `Plan ${planCode} includes voice` : "SMS-only plan",
      });

      checks.push({
        id: "phone_provisioned",
        label: "Twilio number provisioned",
        description: "Phone number exists in phone_numbers table",
        category: "provisioning",
        passed: (phoneNumbers?.length || 0) > 0,
        value: phoneNumbers?.[0]?.phone_e164 || null,
        details: phoneNumbers?.[0]?.phone_e164 || "No number provisioned",
      });

      // 2. Inbound call -> twilio_event_logs stages present
      const { data: twilioLogs } = await supabase
        .from("twilio_event_logs")
        .select("stage, error_message")
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(20);

      const twilioStages = new Set(twilioLogs?.map(l => l.stage) || []);
      const hasInbound = twilioStages.has("call_received") || twilioStages.has("inbound_started");
      const hasContextBuilt = twilioStages.has("context_built");
      const hasElevenLabsSuccess = twilioStages.has("elevenlabs_success");

      checks.push({
        id: "twilio_inbound_received",
        label: "Inbound call received",
        description: "twilio_event_logs has call_received stage",
        category: "telephony",
        passed: hasInbound,
        details: hasInbound ? `${twilioLogs?.length || 0} events logged` : "No inbound calls logged",
      });

      checks.push({
        id: "context_built",
        label: "Context built for call",
        description: "Business context was assembled for voice AI",
        category: "telephony",
        passed: hasContextBuilt,
      });

      checks.push({
        id: "elevenlabs_handoff",
        label: "ElevenLabs handoff successful",
        description: "Call was successfully routed to ElevenLabs",
        category: "telephony",
        passed: hasElevenLabsSuccess,
      });

      // 3. elevenlabs-webhook receives post_call_transcription
      const { data: aiEventLogs } = await supabase
        .from("ai_event_logs")
        .select("stage, error_message")
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(30);

      const aiStages = new Set(aiEventLogs?.map(l => l.stage) || []);
      const webhookReceived = aiStages.has("webhook_received");
      const summarySaved = aiStages.has("summary_saved");
      const extractionSaved = aiStages.has("extraction_saved");
      const customerResolved = aiStages.has("customer_resolved");

      checks.push({
        id: "webhook_received",
        label: "ElevenLabs webhook received",
        description: "post_call_transcription event received",
        category: "webhook",
        passed: webhookReceived,
        details: webhookReceived ? "Webhook processed" : "No webhook events",
      });

      checks.push({
        id: "summary_transcript_saved",
        label: "Summary + transcript saved",
        description: "Call summary persisted to ai_call_sessions",
        category: "webhook",
        passed: summarySaved,
      });

      // 4. extracted_payload created
      const { data: callSessions } = await supabase
        .from("ai_call_sessions")
        .select("id, extracted_payload, summary, outcome")
        .eq("tenant_id", tenantId)
        .not("extracted_payload", "is", null)
        .order("created_at", { ascending: false })
        .limit(5);

      const hasExtraction = (callSessions?.length || 0) > 0;
      const latestExtraction = callSessions?.[0]?.extracted_payload;

      checks.push({
        id: "extraction_created",
        label: "Extracted payload created",
        description: "Structured data extracted from transcript",
        category: "extraction",
        passed: hasExtraction,
        details: hasExtraction 
          ? `${callSessions?.length} sessions with extraction` 
          : "No extractions found",
      });

      checks.push({
        id: "customer_resolved",
        label: "Customer resolved/created",
        description: "Caller linked to customers table",
        category: "extraction",
        passed: customerResolved,
      });

      // 5. Derived entity persisted into correct module table
      const { data: tenant } = await supabase
        .from("tenants")
        .select("business_mode")
        .eq("id", tenantId)
        .single();

      const mode = tenant?.business_mode || "service";
      let entityTable = "bookings";
      if (mode === "food") entityTable = "food_orders";
      else if (mode === "dispatch") entityTable = "dispatch_jobs";
      else if (mode === "medical") entityTable = "medical_intakes";

      // Check if any entities have session_id linkage
      let hasLinkedEntity = false;
      if (entityTable === "bookings") {
        const { count } = await supabase
          .from("bookings")
          .select("*", { count: "exact", head: true })
          .eq("tenant_id", tenantId)
          .not("session_id", "is", null);
        hasLinkedEntity = (count || 0) > 0;
      } else if (entityTable === "food_orders") {
        const { count } = await supabase
          .from("food_orders")
          .select("*", { count: "exact", head: true })
          .eq("tenant_id", tenantId)
          .not("session_id", "is", null);
        hasLinkedEntity = (count || 0) > 0;
      } else if (entityTable === "dispatch_jobs") {
        const { count } = await supabase
          .from("dispatch_jobs")
          .select("*", { count: "exact", head: true })
          .eq("tenant_id", tenantId)
          .not("session_id", "is", null);
        hasLinkedEntity = (count || 0) > 0;
      }

      checks.push({
        id: "entity_persisted",
        label: `Derived entity persisted (${entityTable})`,
        description: `Call outcome routed to correct table for ${mode} mode`,
        category: "entity",
        passed: hasLinkedEntity,
        details: hasLinkedEntity ? `Found linked ${entityTable}` : `No ${entityTable} linked to sessions`,
      });

      // 6. Calendar sync creates external_busy busy_blocks
      const { data: busyBlocks } = await supabase
        .from("busy_blocks")
        .select("id, block_type")
        .eq("tenant_id", tenantId)
        .eq("block_type", "external_busy")
        .limit(5);

      const hasExternalBlocks = (busyBlocks?.length || 0) > 0;

      checks.push({
        id: "calendar_sync_blocks",
        label: "Calendar sync creates busy_blocks",
        description: "External calendar events synced as external_busy",
        category: "calendar",
        passed: hasExternalBlocks,
        details: hasExternalBlocks 
          ? `${busyBlocks?.length} external blocks found` 
          : "No external_busy blocks",
      });

      // Check if AI respects busy blocks (context snapshot has availability data)
      const { data: contextSnapshots } = await supabase
        .from("ai_context_snapshots")
        .select("context_json")
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(1);

      const latestContext = contextSnapshots?.[0]?.context_json as Record<string, unknown> | undefined;
      const hasSchedulingContext = !!(latestContext?.scheduling);

      checks.push({
        id: "ai_respects_availability",
        label: "AI receives scheduling context",
        description: "Context snapshots include scheduling/availability data",
        category: "calendar",
        passed: hasSchedulingContext,
      });

      // 7. Automations preset test sends payload and logs run steps
      const { data: automationRuns } = await supabase
        .from("automation_runs")
        .select("id, status, trigger_event")
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(10);

      const hasRuns = (automationRuns?.length || 0) > 0;
      const successfulRuns = automationRuns?.filter(r => r.status === "success") || [];

      checks.push({
        id: "automation_executed",
        label: "Automation runs executed",
        description: "Trigger events fire automation_runs",
        category: "automation",
        passed: hasRuns,
        details: hasRuns ? `${automationRuns?.length} runs, ${successfulRuns.length} successful` : "No runs logged",
      });

      const { data: runSteps } = await supabase
        .from("automation_run_steps")
        .select("id, status")
        .in("run_id", automationRuns?.map(r => r.id) || [])
        .limit(10);

      const hasSteps = (runSteps?.length || 0) > 0;

      checks.push({
        id: "automation_steps_logged",
        label: "Automation steps logged",
        description: "Run steps with request/response payloads",
        category: "automation",
        passed: hasSteps,
        details: hasSteps ? `${runSteps?.length} steps logged` : "No steps found",
      });

      return checks;
    },
    enabled: !!tenantId,
    staleTime: 30_000,
  });

  return {
    checks: query.data || [],
    loading: query.isLoading,
    refetch: query.refetch,
  };
}

import { useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import type { BusinessMode } from "@/types/database";

export interface TestResult {
  id: string;
  category: "provisioning" | "telephony" | "webhook" | "extraction" | "entity" | "calendar" | "automation";
  label: string;
  description: string;
  passed: boolean;
  details?: string;
  value?: string | number | null;
  fixSuggestion?: string;
  fixLink?: string;
}

export interface GoldenPathRun {
  id: string;
  tenant_id: string;
  started_at: string;
  finished_at: string | null;
  overall_status: "running" | "passed" | "partial" | "failed";
  results_json: TestResult[];
  pass_count: number;
  fail_count: number;
  mode: string | null;
}

export function useGoldenPathRunner() {
  const [isRunning, setIsRunning] = useState(false);
  const [currentRun, setCurrentRun] = useState<GoldenPathRun | null>(null);

  const runTests = useCallback(async (tenantId: string): Promise<GoldenPathRun | null> => {
    if (!tenantId) return null;
    
    setIsRunning(true);
    const results: TestResult[] = [];

    try {
      // Get tenant info
      const { data: tenant } = await supabase
        .from("tenants")
        .select("id, name, business_mode, hipaa_mode")
        .eq("id", tenantId)
        .single();

      if (!tenant) {
        toast.error("Tenant not found");
        setIsRunning(false);
        return null;
      }

      const mode = tenant.business_mode as BusinessMode;

      // Create initial run record
      const { data: run, error: insertError } = await supabase
        .from("golden_path_runs")
        .insert({
          tenant_id: tenantId,
          mode: mode,
          overall_status: "running",
          results_json: [],
        })
        .select()
        .single();

      if (insertError || !run) {
        toast.error("Failed to start test run");
        setIsRunning(false);
        return null;
      }

      // ============================================
      // TEST 1: Voice Provisioning
      // ============================================
      const { data: subscription } = await supabase
        .from("subscriptions")
        .select("plan_code, status")
        .eq("tenant_id", tenantId)
        .maybeSingle();

      const planCode = subscription?.plan_code || "";
      const hasVoice = planCode.startsWith("voice") || planCode.startsWith("both");
      const isActive = subscription?.status === "active" || subscription?.status === "trialing";

      results.push({
        id: "subscription_active",
        category: "provisioning",
        label: "Active subscription with voice SKU",
        description: "Plan code includes voice/both and status is active",
        passed: hasVoice && isActive,
        value: subscription?.plan_code || null,
        details: subscription ? `${subscription.plan_code} (${subscription.status})` : "No subscription",
        fixSuggestion: !subscription 
          ? "Add a subscription for this tenant" 
          : !hasVoice 
            ? "Upgrade to voice or both plan" 
            : !isActive 
              ? "Activate subscription" 
              : undefined,
        fixLink: "/app/settings",
      });

      const { data: phoneNumbers } = await supabase
        .from("phone_numbers")
        .select("phone_e164, status")
        .eq("tenant_id", tenantId);

      const hasPhoneNumber = (phoneNumbers?.length || 0) > 0;
      
      results.push({
        id: "phone_provisioned",
        category: "provisioning",
        label: "Twilio number provisioned",
        description: "phone_numbers row exists with valid E.164",
        passed: hasPhoneNumber,
        value: phoneNumbers?.[0]?.phone_e164 || null,
        details: phoneNumbers?.[0]?.phone_e164 || "No number provisioned",
        fixSuggestion: !hasPhoneNumber ? "Provision a Twilio number via subscription activation" : undefined,
        fixLink: "/app/go-live",
      });

      const { data: settings } = await supabase
        .from("assistant_settings")
        .select("closeloop_number, phone_connected")
        .eq("tenant_id", tenantId)
        .maybeSingle();

      const hasCloseloopNumber = !!settings?.closeloop_number;
      
      results.push({
        id: "assistant_settings_linked",
        category: "provisioning",
        label: "assistant_settings.closeloop_number set",
        description: "AI knows which number to use",
        passed: hasCloseloopNumber,
        value: settings?.closeloop_number || null,
        details: settings?.closeloop_number || "Not set",
        fixSuggestion: !hasCloseloopNumber ? "Complete phone provisioning" : undefined,
        fixLink: "/app/go-live",
      });

      // ============================================
      // TEST 2: Inbound Call Processing
      // ============================================
      const { data: twilioLogs } = await supabase
        .from("twilio_event_logs")
        .select("stage, error_message, created_at")
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(50);

      const twilioStages = new Set(twilioLogs?.map(l => l.stage) || []);
      const hasInbound = twilioStages.has("call_received") || twilioStages.has("inbound_started");
      const hasContextBuilt = twilioStages.has("context_built");
      const hasElevenLabsSuccess = twilioStages.has("elevenlabs_success");
      const twilioErrors = twilioLogs?.filter(l => l.error_message);

      results.push({
        id: "inbound_received",
        category: "telephony",
        label: "Inbound call received by twilio-inbound",
        description: "Tenant resolved from To number",
        passed: hasInbound,
        details: hasInbound ? `${twilioLogs?.length || 0} events logged` : "No inbound calls logged",
        fixSuggestion: !hasInbound ? "Make a test call to the CloseLoop number" : undefined,
        fixLink: "/debug/telephony",
      });

      results.push({
        id: "context_built",
        category: "telephony",
        label: "Business context built successfully",
        description: "buildBusinessContext ran without errors",
        passed: hasContextBuilt,
        details: hasContextBuilt ? "Context assembled" : twilioErrors?.[0]?.error_message || "Not reached",
        fixSuggestion: !hasContextBuilt ? "Check debug page for context build errors" : undefined,
        fixLink: "/debug/ai-context",
      });

      results.push({
        id: "elevenlabs_registered",
        category: "telephony",
        label: "ElevenLabs call registered",
        description: "register-call returned conversation_id",
        passed: hasElevenLabsSuccess,
        details: hasElevenLabsSuccess ? "ElevenLabs handoff successful" : "Registration failed",
        fixSuggestion: !hasElevenLabsSuccess ? "Check ELEVENLABS_API_KEY secret" : undefined,
        fixLink: "/debug/telephony",
      });

      // Check ai_call_sessions created
      const { data: callSessions } = await supabase
        .from("ai_call_sessions")
        .select("id, outcome, summary, transcript, extracted_payload, twilio_call_sid, elevenlabs_conversation_id")
        .eq("tenant_id", tenantId)
        .order("started_at", { ascending: false })
        .limit(10);

      const hasCallSession = (callSessions?.length || 0) > 0;
      
      results.push({
        id: "call_session_created",
        category: "telephony",
        label: "ai_call_sessions record created",
        description: "Call tracking row exists",
        passed: hasCallSession,
        details: hasCallSession ? `${callSessions?.length} sessions` : "No sessions",
        fixSuggestion: !hasCallSession ? "Complete a test call end-to-end" : undefined,
        fixLink: "/app/calls",
      });

      // ============================================
      // TEST 3: Post-call Webhook
      // ============================================
      const { data: aiEventLogs } = await supabase
        .from("ai_event_logs")
        .select("stage, error_message, event_data")
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(50);

      const aiStages = new Set(aiEventLogs?.map(l => l.stage) || []);
      const webhookReceived = aiStages.has("webhook_received");
      const summarySaved = aiStages.has("summary_saved") || aiStages.has("transcript_saved");

      results.push({
        id: "webhook_received",
        category: "webhook",
        label: "elevenlabs-webhook received post_call_transcription",
        description: "HMAC verified, payload parsed",
        passed: webhookReceived,
        details: webhookReceived ? "Webhook processed" : "No webhook events",
        fixSuggestion: !webhookReceived ? "Check ElevenLabs agent webhook configuration" : undefined,
        fixLink: "/debug/telephony",
      });

      // Check for transcript/summary
      const hasTranscript = callSessions?.some(s => s.transcript);
      const hasSummary = callSessions?.some(s => s.summary);
      
      results.push({
        id: "transcript_summary_saved",
        category: "webhook",
        label: "Transcript + summary persisted",
        description: "ai_call_sessions has transcript and summary",
        passed: hasTranscript && hasSummary,
        details: `Transcript: ${hasTranscript ? "✓" : "✗"}, Summary: ${hasSummary ? "✓" : "✗"}`,
        fixSuggestion: !hasTranscript || !hasSummary ? "Webhook may have failed to parse response" : undefined,
        fixLink: "/app/calls",
      });

      // ============================================
      // TEST 4: Extraction + Normalization
      // ============================================
      const hasExtraction = callSessions?.some(s => s.extracted_payload);
      const extractedPayloads = callSessions?.filter(s => s.extracted_payload).map(s => s.extracted_payload) || [];
      
      results.push({
        id: "extraction_created",
        category: "extraction",
        label: "extracted_payload populated",
        description: "Structured data parsed from transcript",
        passed: hasExtraction,
        details: hasExtraction ? `${extractedPayloads.length} extractions found` : "No extractions",
        fixSuggestion: !hasExtraction ? "Extraction parser may need debugging" : undefined,
        fixLink: "/debug/extraction",
      });

      // Check for intent detection
      const hasOutcome = callSessions?.some(s => s.outcome);
      const outcomes = [...new Set(callSessions?.map(s => s.outcome).filter(Boolean))];
      
      results.push({
        id: "intent_detected",
        category: "extraction",
        label: "Intent/outcome determined",
        description: "Call classified (order, booked, dispatch, etc.)",
        passed: hasOutcome,
        details: hasOutcome ? `Outcomes: ${outcomes.join(", ")}` : "No outcomes detected",
        fixSuggestion: !hasOutcome ? "Check extraction pipeline" : undefined,
        fixLink: "/debug/extraction",
      });

      const customerResolved = aiStages.has("customer_resolved");
      
      results.push({
        id: "customer_resolved",
        category: "extraction",
        label: "Customer resolved/created",
        description: "Caller linked to customers table by phone_e164",
        passed: customerResolved,
        details: customerResolved ? "Customer linked" : "No customer linkage",
        fixSuggestion: !customerResolved ? "Check customer resolver in webhook" : undefined,
        fixLink: "/app/leads",
      });

      // ============================================
      // TEST 5: Deterministic Entity Routing (MODE-AWARE)
      // ============================================
      const entityChecks: { table: string; label: string; modes: BusinessMode[] }[] = [
        { table: "bookings", label: "bookings", modes: ["service", "general"] },
        { table: "food_orders", label: "food_orders", modes: ["food"] },
        { table: "reservations", label: "reservations", modes: ["food"] },
        { table: "dispatch_jobs", label: "dispatch_jobs", modes: ["dispatch"] },
        { table: "medical_intakes", label: "medical_intakes", modes: ["medical"] },
      ];

      for (const check of entityChecks) {
        if (!check.modes.includes(mode)) continue;

        let hasLinkedEntity = false;
        let entityCount = 0;

        if (check.table === "bookings") {
          const { count } = await supabase
            .from("bookings")
            .select("*", { count: "exact", head: true })
            .eq("tenant_id", tenantId)
            .not("session_id", "is", null);
          hasLinkedEntity = (count || 0) > 0;
          entityCount = count || 0;
        } else if (check.table === "food_orders") {
          const { count } = await supabase
            .from("food_orders")
            .select("*", { count: "exact", head: true })
            .eq("tenant_id", tenantId)
            .not("session_id", "is", null);
          hasLinkedEntity = (count || 0) > 0;
          entityCount = count || 0;
        } else if (check.table === "reservations") {
          const { count } = await supabase
            .from("reservations")
            .select("*", { count: "exact", head: true })
            .eq("tenant_id", tenantId)
            .not("session_id", "is", null);
          hasLinkedEntity = (count || 0) > 0;
          entityCount = count || 0;
        } else if (check.table === "dispatch_jobs") {
          const { count } = await supabase
            .from("dispatch_jobs")
            .select("*", { count: "exact", head: true })
            .eq("tenant_id", tenantId)
            .not("session_id", "is", null);
          hasLinkedEntity = (count || 0) > 0;
          entityCount = count || 0;
        } else if (check.table === "medical_intakes") {
          const { count } = await supabase
            .from("medical_intakes")
            .select("*", { count: "exact", head: true })
            .eq("tenant_id", tenantId)
            .not("session_id", "is", null);
          hasLinkedEntity = (count || 0) > 0;
          entityCount = count || 0;
        }

        results.push({
          id: `entity_${check.table}`,
          category: "entity",
          label: `${check.label} created from call`,
          description: `${mode} mode routes to ${check.table}`,
          passed: hasLinkedEntity,
          value: entityCount,
          details: hasLinkedEntity ? `${entityCount} linked records` : `No ${check.table} linked to sessions`,
          fixSuggestion: !hasLinkedEntity ? `Complete a call that results in a ${check.label.replace("_", " ")}` : undefined,
          fixLink: check.table === "bookings" ? "/app/bookings" 
            : check.table === "food_orders" ? "/app/orders"
            : check.table === "reservations" ? "/app/reservations"
            : check.table === "dispatch_jobs" ? "/app/dispatch"
            : "/app/medical-intake",
        });
      }

      // ============================================
      // TEST 6: Automation Runner
      // ============================================
      const { data: enabledRules } = await supabase
        .from("automation_rules")
        .select("id, enabled, trigger_event, action_type")
        .eq("tenant_id", tenantId)
        .eq("enabled", true);

      const hasEnabledRules = (enabledRules?.length || 0) > 0;
      
      results.push({
        id: "automation_rules_enabled",
        category: "automation",
        label: "Automation rules enabled",
        description: "At least one rule is active",
        passed: hasEnabledRules,
        details: hasEnabledRules ? `${enabledRules?.length} active rules` : "No enabled rules",
        fixSuggestion: !hasEnabledRules ? "Enable automations in Integrations page" : undefined,
        fixLink: "/app/integrations",
      });

      const { data: automationRuns } = await supabase
        .from("automation_runs")
        .select("id, status, trigger_event, error_message")
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(20);

      const hasRuns = (automationRuns?.length || 0) > 0;
      const successfulRuns = automationRuns?.filter(r => r.status === "success") || [];
      const failedRuns = automationRuns?.filter(r => r.status === "failed") || [];

      results.push({
        id: "automation_runs_executed",
        category: "automation",
        label: "automation_runs executed",
        description: "Trigger events created run records",
        passed: hasRuns && successfulRuns.length > 0,
        details: hasRuns 
          ? `${successfulRuns.length} succeeded, ${failedRuns.length} failed` 
          : "No runs logged",
        fixSuggestion: !hasRuns 
          ? "Trigger an event that matches an enabled rule" 
          : failedRuns.length > 0 
            ? "Check failed run logs for errors" 
            : undefined,
        fixLink: "/app/integrations",
      });

      // ============================================
      // TEST 7: Calendar Busy Blocks
      // ============================================
      const { data: calendarConnections } = await supabase
        .from("calendar_connections")
        .select("id, provider, status")
        .eq("tenant_id", tenantId);

      const hasCalendarConnection = calendarConnections?.some(c => c.status === "connected");
      
      results.push({
        id: "calendar_connected",
        category: "calendar",
        label: "Calendar connection established",
        description: "External calendar linked for availability",
        passed: !!hasCalendarConnection,
        details: hasCalendarConnection 
          ? `Connected: ${calendarConnections?.filter(c => c.status === "connected").map(c => c.provider).join(", ")}` 
          : "No calendar connected",
        fixSuggestion: !hasCalendarConnection ? "Connect Google Calendar or other provider" : undefined,
        fixLink: "/app/integrations/schedule",
      });

      const { data: busyBlocks } = await supabase
        .from("busy_blocks")
        .select("id, block_type, start_at, end_at")
        .eq("tenant_id", tenantId)
        .eq("block_type", "external_busy")
        .order("created_at", { ascending: false })
        .limit(10);

      const hasExternalBlocks = (busyBlocks?.length || 0) > 0;

      results.push({
        id: "external_busy_synced",
        category: "calendar",
        label: "external_busy blocks inserted",
        description: "Calendar events sync to busy_blocks table",
        passed: hasExternalBlocks || !hasCalendarConnection, // Pass if no calendar to sync
        details: hasExternalBlocks 
          ? `${busyBlocks?.length} external blocks` 
          : hasCalendarConnection 
            ? "No blocks synced yet" 
            : "N/A (no calendar)",
        fixSuggestion: hasCalendarConnection && !hasExternalBlocks ? "Run calendar sync or add events to source calendar" : undefined,
        fixLink: "/debug/availability",
      });

      // Check AI context includes scheduling
      const { data: contextSnapshots } = await supabase
        .from("ai_context_snapshots")
        .select("context_json")
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(1);

      const latestContext = contextSnapshots?.[0]?.context_json as Record<string, unknown> | undefined;
      const hasSchedulingContext = !!(latestContext?.scheduling);

      results.push({
        id: "ai_avoids_busy",
        category: "calendar",
        label: "AI receives availability context",
        description: "Context snapshots include scheduling data",
        passed: hasSchedulingContext,
        details: hasSchedulingContext ? "Scheduling context present" : "No scheduling in context",
        fixSuggestion: !hasSchedulingContext ? "Make a test call to generate context snapshot" : undefined,
        fixLink: "/debug/ai-context",
      });

      // ============================================
      // CALCULATE FINAL STATUS
      // ============================================
      const passCount = results.filter(r => r.passed).length;
      const failCount = results.filter(r => !r.passed).length;
      const overallStatus: "passed" | "partial" | "failed" = 
        failCount === 0 ? "passed" : passCount > 0 ? "partial" : "failed";

      // Update run with results
      const { error: updateError } = await supabase
        .from("golden_path_runs")
        .update({
          finished_at: new Date().toISOString(),
          overall_status: overallStatus,
          results_json: JSON.parse(JSON.stringify(results)),
          pass_count: passCount,
          fail_count: failCount,
        })
        .eq("id", run.id);

      // Silently handle update errors - run data still returned

      const finalRun: GoldenPathRun = {
        id: run.id,
        tenant_id: tenantId,
        started_at: run.started_at,
        finished_at: new Date().toISOString(),
        overall_status: overallStatus,
        results_json: results,
        pass_count: passCount,
        fail_count: failCount,
        mode: mode,
      };

      setCurrentRun(finalRun);
      setIsRunning(false);

      if (overallStatus === "passed") {
        toast.success(`All ${passCount} tests passed!`);
      } else if (overallStatus === "partial") {
        toast.warning(`${passCount} passed, ${failCount} failed`);
      } else {
        toast.error(`${failCount} tests failed`);
      }

      return finalRun;
    } catch {
      toast.error("Test run failed unexpectedly");
      setIsRunning(false);
      return null;
    }
  }, []);

  return {
    runTests,
    isRunning,
    currentRun,
  };
}

import { useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig, type BusinessMode } from "@/hooks/useTenantConfig";
import {
  getIndustryBySlug,
  type IndustryCatalogEntry,
  type IndustryCategory,
} from "@/data/industryCatalog";
import {
  getIndustryTerminology,
  type IndustryTerminology,
} from "@/data/industryTerminology";
import { getTerminology, type IndustryTerms } from "@/lib/terminology";
import {
  getIndustryBrainConfig,
  type IndustryBrainConfig,
} from "@/config/industryBrainConfig";

export interface IndustryContext {
  /** Industry slug from tenant (e.g. "hair-salon", "towing") or null */
  slug: string | null;
  /** Resolved category (e.g. "beauty_wellness", "dispatch_logistics") or null */
  category: IndustryCategory | null;
  /** Business mode — always resolved, falls back to "service" */
  mode: BusinessMode;
  /** Rich 29-field Brain terminology (mode → category → slug resolution) */
  terminology: IndustryTerminology;
  /** Simpler UI-level terms (booking/customer/service labels) */
  terms: IndustryTerms;
  /** Full catalog entry if slug matched, otherwise null */
  catalog: IndustryCatalogEntry | null;
  /** Brain, pricing, inbox, dashboard, and priority configuration */
  config: IndustryBrainConfig;
}

/**
 * Unified hook for all industry-aware presentation logic.
 *
 * Reads `tenant.industry` (slug) from AuthContext, resolves it through
 * the industry catalog, and computes terminology + configuration using
 * the 3-tier hierarchy: mode → category → slug.
 *
 * Falls back gracefully when no industry slug is set.
 */
export function useIndustryContext(): IndustryContext {
  const { tenant } = useAuth();
  const { businessMode } = useTenantConfig();

  return useMemo(() => {
    const slug = (tenant?.industry as string) || null;
    const catalogEntry = slug ? getIndustryBySlug(slug) : null;
    const category = catalogEntry?.category ?? null;
    const mode = catalogEntry?.businessMode ?? businessMode;

    const terminology = getIndustryTerminology(mode, category ?? undefined, slug ?? undefined);
    const terms = getTerminology(mode);
    const config = getIndustryBrainConfig(mode, category ?? undefined, slug ?? undefined);

    return {
      slug,
      category,
      mode,
      terminology,
      terms,
      catalog: catalogEntry ?? null,
      config,
    };
  }, [tenant?.id, tenant?.industry, tenant?.business_mode, businessMode]);
}

import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

export interface IndustryDemo {
  id: string;
  industry_key: string;
  title: string;
  audio_url: string | null;
  caption_bullets: string[];
  transcript_excerpt: string | null;
  is_active: boolean;
  created_at: string;
  updated_at: string;
}

export function useIndustryDemos(activeOnly = true) {
  const [demos, setDemos] = useState<IndustryDemo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchDemos = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      let query = supabase
        .from("industry_demos")
        .select("*")
        .order("created_at", { ascending: true });

      if (activeOnly) {
        query = query.eq("is_active", true);
      }

      const { data, error: fetchError } = await query;

      if (fetchError) throw fetchError;

      // Parse caption_bullets from JSONB
      const parsed = (data || []).map((d: any) => ({
        ...d,
        caption_bullets: Array.isArray(d.caption_bullets) 
          ? d.caption_bullets 
          : JSON.parse(d.caption_bullets || "[]"),
      }));

      setDemos(parsed);
    } catch (err: any) {
      console.error("Error fetching demos:", err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [activeOnly]);

  useEffect(() => {
    fetchDemos();
  }, [fetchDemos]);

  return { demos, loading, error, refetch: fetchDemos };
}

export function useIndustryDemoAdmin() {
  const { demos, loading, error, refetch } = useIndustryDemos(false);

  const updateDemo = async (id: string, updates: Partial<IndustryDemo>) => {
    const { error } = await supabase
      .from("industry_demos")
      .update({
        ...updates,
        caption_bullets: updates.caption_bullets 
          ? JSON.stringify(updates.caption_bullets) 
          : undefined,
      } as any)
      .eq("id", id);

    if (error) throw error;
    await refetch();
  };

  const uploadAudio = async (industryKey: string, file: File): Promise<string> => {
    const ext = file.name.split(".").pop();
    const path = `${industryKey}-demo.${ext}`;

    // Delete existing file if any
    await supabase.storage.from("demo-audio").remove([path]);

    // Upload new file
    const { error: uploadError } = await supabase.storage
      .from("demo-audio")
      .upload(path, file, { upsert: true });

    if (uploadError) throw uploadError;

    // Get public URL
    const { data } = supabase.storage.from("demo-audio").getPublicUrl(path);
    return data.publicUrl;
  };

  const deleteAudio = async (industryKey: string) => {
    const { data: files } = await supabase.storage
      .from("demo-audio")
      .list("", { search: industryKey });

    if (files && files.length > 0) {
      await supabase.storage
        .from("demo-audio")
        .remove(files.map((f) => f.name));
    }
  };

  return { demos, loading, error, refetch, updateDemo, uploadAudio, deleteAudio };
}

