        .from("integrations")
        .update(updateData as any)
        .eq("id", id)
        .select()
        .single();
      if (error) throw error;
      return integration as Integration;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["integrations", tenantId] });
