import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";
import { useEffect, useMemo } from "react";
import type { JobServiceItem } from "./useActiveJobs";

export function useJobServiceItems(jobId: string | null) {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const itemsQuery = useQuery({
    queryKey: ["job-service-items", jobId],
    queryFn: async () => {
      if (!jobId) return [];

      const { data, error } = await (supabase as any)
        .from("job_service_items")
        .select("*")
        .eq("job_id", jobId)
        .order("sort_order", { ascending: true });

      if (error) throw error;
      return (data ?? []) as JobServiceItem[];
    },
    enabled: !!jobId,
  });

  // Realtime subscription for this job's items
  useEffect(() => {
    if (!jobId || !tenant?.id) return;

    const channel = supabase
      .channel(`job-items-${jobId}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "job_service_items",
          filter: `job_id=eq.${jobId}`,
        },
        () => {
          queryClient.invalidateQueries({ queryKey: ["job-service-items", jobId] });
          queryClient.invalidateQueries({ queryKey: ["active-jobs", tenant.id] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [jobId, tenant?.id, queryClient]);

  const toggleItemStatus = useMutation({
    mutationFn: async ({ itemId, currentStatus }: { itemId: string; currentStatus: string }) => {
      const newStatus = currentStatus === "completed" ? "pending" : "completed";
      const updates: Record<string, unknown> = { status: newStatus };

      if (newStatus === "completed") {
        updates.completed_at = new Date().toISOString();
      } else {
        updates.completed_at = null;
      }

      const { data, error } = await (supabase as any)
        .from("job_service_items")
        .update(updates)
        .eq("id", itemId)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["job-service-items", jobId] });
      queryClient.invalidateQueries({ queryKey: ["active-jobs", tenant?.id] });
    },
    onError: () => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const addItem = useMutation({
    mutationFn: async (input: { title: string; service_id?: string }) => {
      if (!jobId || !tenant?.id) throw new Error("Missing job or tenant");

      const maxSort = (itemsQuery.data ?? []).reduce(
        (max, item) => Math.max(max, item.sort_order),
        -1
      );

      const { data, error } = await (supabase as any)
        .from("job_service_items")
        .insert({
          job_id: jobId,
          tenant_id: tenant.id,
          title: input.title,
          service_id: input.service_id || null,
          sort_order: maxSort + 1,
          status: "pending",
        })
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["job-service-items", jobId] });
      queryClient.invalidateQueries({ queryKey: ["active-jobs", tenant?.id] });
    },
    onError: () => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const removeItem = useMutation({
    mutationFn: async (itemId: string) => {
      const { error } = await (supabase as any)
        .from("job_service_items")
        .delete()
        .eq("id", itemId);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["job-service-items", jobId] });
      queryClient.invalidateQueries({ queryKey: ["active-jobs", tenant?.id] });
    },
    onError: () => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const reorderItems = useMutation({
    mutationFn: async (orderedIds: string[]) => {
      const updates = orderedIds.map((id, index) =>
        (supabase as any)
          .from("job_service_items")
          .update({ sort_order: index })
          .eq("id", id)
      );
      await Promise.all(updates);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["job-service-items", jobId] });
    },
  });

  const computed = useMemo(() => {
    const items = itemsQuery.data ?? [];
    const completedCount = items.filter((i) => i.status === "completed").length;
    const totalCount = items.length;
    return {
      completedCount,
      totalCount,
      progressPercent: totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0,
    };
  }, [itemsQuery.data]);

  return {
    items: itemsQuery.data ?? [],
    isLoading: itemsQuery.isLoading,
    ...computed,
    toggleItemStatus,
    addItem,
    removeItem,
    reorderItems,
  };
}

import { useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

export type ConflictType = "price_mismatch" | "description_mismatch" | "name_mismatch" | "duration_mismatch" | "field_mismatch" | "other";
export type ConflictStatus = "unresolved" | "keep_existing" | "accept_upload" | "custom_merged";

export const conflictTypeLabels: Record<ConflictType | string, string> = {
  price_mismatch: "Price Difference",
  description_mismatch: "Description Difference",
  name_mismatch: "Name Difference",
  duration_mismatch: "Duration Difference",
  field_mismatch: "Field Difference",
  other: "Other Difference",
};

export const entityTypeLabels: Record<string, string> = {
  service: "Service",
  menu_item: "Menu Item",
  faq: "FAQ",
  policy: "Policy",
  hours: "Hours",
};

export interface KnowledgeConflict {
  id: string;
  tenant_id: string;
  source_id: string;
  conflict_type: ConflictType;
  entity_type: string;
  existing_entity_id: string | null;
  existing_data: Record<string, any>;
  proposed_data: Record<string, any>;
  differing_fields: string[];
  status: ConflictStatus;
  resolved_at: string | null;
  resolved_by: string | null;
  created_at: string;
}

export function useKnowledgeConflicts() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  // Fetch all conflicts
  const { data: conflicts = [], isLoading, error, refetch } = useQuery({
    queryKey: ["knowledge-conflicts", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];

      const { data, error } = await supabase
        .from("knowledge_conflicts")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false });

      if (error) throw error;
      return data as KnowledgeConflict[];
    },
    enabled: !!tenant?.id,
  });

  // Subscribe to realtime updates
  useEffect(() => {
    if (!tenant?.id) return;

    const channel = supabase
      .channel(`knowledge-conflicts-${tenant.id}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "knowledge_conflicts",
          filter: `tenant_id=eq.${tenant.id}`,
        },
        () => {
          queryClient.invalidateQueries({ queryKey: ["knowledge-conflicts", tenant.id] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [tenant?.id, queryClient]);

  // Keep existing (dismiss the conflict, keep current data)
  const keepExistingMutation = useMutation({
    mutationFn: async (conflictId: string) => {
      const { error } = await supabase
        .from("knowledge_conflicts")
        .update({
          status: "keep_existing",
          resolved_at: new Date().toISOString(),
        })
        .eq("id", conflictId);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-conflicts", tenant?.id] });
    },
  });

  // Accept upload (update existing entity with proposed data)
  const acceptUploadMutation = useMutation({
    mutationFn: async (conflictId: string) => {
      const conflict = conflicts.find((c) => c.id === conflictId);
      if (!conflict) throw new Error("Conflict not found");

      const { entity_type, existing_entity_id, proposed_data } = conflict;

      if (existing_entity_id) {
        // Update the existing entity based on type
        switch (entity_type) {
          case "service":
            await supabase
              .from("services")
              .update({
                name: proposed_data.name,
                description: proposed_data.description,
                price_amount: proposed_data.price_amount,
                duration_minutes: proposed_data.duration_minutes,
              })
              .eq("id", existing_entity_id);
            break;

          case "menu_item":
            await supabase
              .from("menu_items")
              .update({
                name: proposed_data.name,
                description: proposed_data.description,
                price_cents: proposed_data.price_cents,
                category: proposed_data.category,
              })
              .eq("id", existing_entity_id);
            break;

          case "faq":
            await supabase
              .from("business_faqs")
              .update({
                question: proposed_data.question,
                answer: proposed_data.answer,
              })
              .eq("id", existing_entity_id);
            break;

          case "hours":
            await supabase
              .from("availability_slots")
              .update({
                start_time: proposed_data.start_time,
                end_time: proposed_data.end_time,
                is_available: proposed_data.is_available,
              })
              .eq("id", existing_entity_id);
            break;
        }
      }

      // Mark conflict as resolved
      const { error: updateError } = await supabase
        .from("knowledge_conflicts")
        .update({
          status: "accept_upload",
          resolved_at: new Date().toISOString(),
        })
        .eq("id", conflictId);

      if (updateError) throw updateError;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-conflicts", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["menu-items"] });
      queryClient.invalidateQueries({ queryKey: ["faqs"] });
      queryClient.invalidateQueries({ queryKey: ["knowledge-stats"] });
    },
  });

  // Custom merge (apply custom data to existing entity)
  const customMergeMutation = useMutation({
    mutationFn: async (params: { conflictId: string; mergedData: Record<string, any> }) => {
      const conflict = conflicts.find((c) => c.id === params.conflictId);
      if (!conflict) throw new Error("Conflict not found");

      const { entity_type, existing_entity_id } = conflict;

      if (existing_entity_id) {
        switch (entity_type) {
          case "service":
            await supabase
              .from("services")
              .update(params.mergedData)
              .eq("id", existing_entity_id);
            break;

          case "menu_item":
            await supabase
              .from("menu_items")
              .update(params.mergedData)
              .eq("id", existing_entity_id);
            break;

          case "faq":
            await supabase
              .from("business_faqs")
              .update(params.mergedData)
              .eq("id", existing_entity_id);
            break;

          case "hours":
            await supabase
              .from("availability_slots")
              .update(params.mergedData)
              .eq("id", existing_entity_id);
            break;
        }
      }

      const { error: updateError } = await supabase
        .from("knowledge_conflicts")
        .update({
          status: "custom_merged",
          resolved_at: new Date().toISOString(),
        })
        .eq("id", params.conflictId);

      if (updateError) throw updateError;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-conflicts", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["menu-items"] });
      queryClient.invalidateQueries({ queryKey: ["faqs"] });
    },
  });

  // Batch: Keep all existing
  const keepAllExistingMutation = useMutation({
    mutationFn: async () => {
      const { error } = await supabase
        .from("knowledge_conflicts")
        .update({
          status: "keep_existing",
          resolved_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant?.id)
        .eq("status", "unresolved");

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-conflicts", tenant?.id] });
    },
  });

  // Batch: Accept all uploads
  const acceptAllUploadsMutation = useMutation({
    mutationFn: async () => {
      const unresolved = conflicts.filter((c) => c.status === "unresolved");
      
      for (const conflict of unresolved) {
        const { entity_type, existing_entity_id, proposed_data } = conflict;

        if (existing_entity_id) {
          switch (entity_type) {
            case "service":
              await supabase
                .from("services")
                .update({
                  name: proposed_data.name,
                  description: proposed_data.description,
                  price_amount: proposed_data.price_amount,
                  duration_minutes: proposed_data.duration_minutes,
                })
                .eq("id", existing_entity_id);
              break;

            case "menu_item":
              await supabase
                .from("menu_items")
                .update({
                  name: proposed_data.name,
                  description: proposed_data.description,
                  price_cents: proposed_data.price_cents,
                  category: proposed_data.category,
                })
                .eq("id", existing_entity_id);
              break;

            case "faq":
              await supabase
                .from("business_faqs")
                .update({
                  question: proposed_data.question,
                  answer: proposed_data.answer,
                })
                .eq("id", existing_entity_id);
              break;

            case "hours":
              await supabase
                .from("availability_slots")
                .update({
                  start_time: proposed_data.start_time,
                  end_time: proposed_data.end_time,
                  is_available: proposed_data.is_available,
                })
                .eq("id", existing_entity_id);
              break;
          }
        }
      }

      // Mark all as resolved
      const { error } = await supabase
        .from("knowledge_conflicts")
        .update({
          status: "accept_upload",
          resolved_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant?.id)
        .eq("status", "unresolved");

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-conflicts", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["menu-items"] });
      queryClient.invalidateQueries({ queryKey: ["faqs"] });
      queryClient.invalidateQueries({ queryKey: ["knowledge-stats"] });
    },
  });

  // Computed values
  const unresolvedCount = conflicts.filter((c) => c.status === "unresolved").length;
  const resolvedCount = conflicts.filter((c) => c.status !== "unresolved").length;
  const unresolvedConflicts = conflicts.filter((c) => c.status === "unresolved");

  return {
    conflicts,
    unresolvedConflicts,
    isLoading,
    error,
    refetch,
    unresolvedCount,
    resolvedCount,
    keepExisting: keepExistingMutation.mutateAsync,
    acceptUpload: acceptUploadMutation.mutateAsync,
    customMerge: customMergeMutation.mutateAsync,
    keepAllExisting: keepAllExistingMutation.mutateAsync,
    acceptAllUploads: acceptAllUploadsMutation.mutateAsync,
    isResolving:
      keepExistingMutation.isPending ||
      acceptUploadMutation.isPending ||
      customMergeMutation.isPending ||
      keepAllExistingMutation.isPending ||
      acceptAllUploadsMutation.isPending,
  };
}

import { useEffect } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

export interface KnowledgeMergeItem {
  id: string;
  tenant_id: string;
  upload_id: string | null;
  entity_type: "service" | "menu_item" | "policy" | "faq" | "intake_field" | "menu_category";
  entity_key: string;
  existing_value: Record<string, unknown> | null;
  proposed_value: Record<string, unknown>;
  conflict_type: "different_price" | "missing_field" | "name_mismatch" | "duplicate" | "new_item" | "other";
  status: "pending" | "accepted" | "rejected";
  created_at: string;
}

export function useKnowledgeMergeQueue() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  // Fetch pending merge queue items
  const { data: pendingItems = [], isLoading, refetch } = useQuery({
    queryKey: ["knowledge-merge-queue", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];

      const { data, error } = await supabase
        .from("knowledge_merge_queue")
        .select("*")
        .eq("tenant_id", tenant.id)
        .eq("status", "pending")
        .order("created_at", { ascending: false });

      if (error) throw error;
      return data as KnowledgeMergeItem[];
    },
    enabled: !!tenant?.id,
  });

  // Subscribe to realtime updates
  useEffect(() => {
    if (!tenant?.id) return;

    const channel = supabase
      .channel(`knowledge-merge-${tenant.id}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "knowledge_merge_queue",
          filter: `tenant_id=eq.${tenant.id}`,
        },
        () => {
          queryClient.invalidateQueries({ queryKey: ["knowledge-merge-queue", tenant.id] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [tenant?.id, queryClient]);

  // Accept a merge item (apply to structured truth)
  const acceptMutation = useMutation({
    mutationFn: async (item: KnowledgeMergeItem) => {
      // Apply the change to the appropriate table
      await applyMergeItem(item, tenant?.id!);

      // Mark as accepted
      const { error } = await supabase
        .from("knowledge_merge_queue")
        .update({ status: "accepted" })
        .eq("id", item.id);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-merge-queue", tenant?.id] });
      // Also invalidate related data
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["menu-items"] });
      queryClient.invalidateQueries({ queryKey: ["business-faqs"] });
    },
  });

  // Reject a merge item
  const rejectMutation = useMutation({
    mutationFn: async (itemId: string) => {
      const { error } = await supabase
        .from("knowledge_merge_queue")
        .update({ status: "rejected" })
        .eq("id", itemId);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-merge-queue", tenant?.id] });
    },
  });

  // Accept all pending items
  const acceptAllMutation = useMutation({
    mutationFn: async () => {
      for (const item of pendingItems) {
        await applyMergeItem(item, tenant?.id!);
        await supabase
          .from("knowledge_merge_queue")
          .update({ status: "accepted" })
          .eq("id", item.id);
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-merge-queue", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["menu-items"] });
      queryClient.invalidateQueries({ queryKey: ["business-faqs"] });
    },
  });

  // Reject all pending items
  const rejectAllMutation = useMutation({
    mutationFn: async () => {
      const { error } = await supabase
        .from("knowledge_merge_queue")
        .update({ status: "rejected" })
        .eq("tenant_id", tenant?.id)
        .eq("status", "pending");

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-merge-queue", tenant?.id] });
    },
  });

  return {
    pendingItems,
    pendingCount: pendingItems.length,
    isLoading,
    refetch,
    acceptItem: acceptMutation.mutateAsync,
    rejectItem: rejectMutation.mutateAsync,
    acceptAll: acceptAllMutation.mutateAsync,
    rejectAll: rejectAllMutation.mutateAsync,
    isAccepting: acceptMutation.isPending,
    isRejecting: rejectMutation.isPending,
  };
}

// Helper to apply merge item to structured truth
async function applyMergeItem(item: KnowledgeMergeItem, tenantId: string) {
  const { entity_type, entity_key, existing_value, proposed_value } = item;

  switch (entity_type) {
    case "service": {
      if (existing_value?.id) {
        // Update existing service
        await supabase
          .from("services")
          .update({
            name: proposed_value.name as string,
            description: proposed_value.description as string || null,
            duration_minutes: proposed_value.duration_minutes as number || 60,
            price_cents: proposed_value.price_cents as number || proposed_value.price as number * 100 || 0,
          })
          .eq("id", existing_value.id as string);
      } else {
        // Insert new service
        await supabase.from("services").insert({
          tenant_id: tenantId,
          name: proposed_value.name as string || entity_key,
          description: proposed_value.description as string || null,
          duration_minutes: proposed_value.duration_minutes as number || 60,
          price_cents: proposed_value.price_cents as number || (proposed_value.price as number || 0) * 100,
          is_active: true,
        });
      }
      break;
    }

    case "menu_item": {
      if (existing_value?.id) {
        await supabase
          .from("menu_items")
          .update({
            name: proposed_value.name as string,
            description: proposed_value.description as string || null,
            price_cents: proposed_value.price_cents as number || (proposed_value.price as number || 0) * 100,
            category_id: proposed_value.category_id as string || null,
          })
          .eq("id", existing_value.id as string);
      } else {
        await supabase.from("menu_items").insert({
          tenant_id: tenantId,
          name: proposed_value.name as string || entity_key,
          description: proposed_value.description as string || null,
          price_cents: proposed_value.price_cents as number || (proposed_value.price as number || 0) * 100,
          is_available: true,
        });
      }
      break;
    }

    case "faq": {
      if (existing_value?.id) {
        await supabase
          .from("business_faqs")
          .update({
            question: proposed_value.question as string || entity_key,
            answer: proposed_value.answer as string,
          })
          .eq("id", existing_value.id as string);
      } else {
        await supabase.from("business_faqs").insert({
          tenant_id: tenantId,
          question: proposed_value.question as string || entity_key,
          answer: proposed_value.answer as string || "",
        });
      }
      break;
    }

    case "menu_category": {
      // Menu categories may not exist in all schemas - handle gracefully
      try {
        if (existing_value?.id) {
          const { error } = await supabase
            .from("menu_categories" as any)
            .update({
              name: proposed_value.name as string || entity_key,
              description: proposed_value.description as string || null,
            })
            .eq("id", existing_value.id as string);
          if (error) console.warn("Menu category update error:", error);
        } else {
          const { error } = await supabase
            .from("menu_categories" as any)
            .insert({
              tenant_id: tenantId,
              name: proposed_value.name as string || entity_key,
              description: proposed_value.description as string || null,
              display_order: proposed_value.display_order as number || 0,
            });
          if (error) console.warn("Menu category insert error:", error);
        }
      } catch (e) {
        console.warn("Menu category operation failed:", e);
      }
      break;
    }

    case "policy": {
      // Update the tenant's policies JSON field
      const { data: tenantPolicyData } = await (supabase as any)
        .from("tenants")
        .select("policies")
        .eq("id", tenantId)
        .single();

      const currentPolicies = (tenantPolicyData?.policies as Record<string, unknown>) || {};
      const updatedPolicies = {
        ...currentPolicies,
        [entity_key]: proposed_value,
      };

      const { error: policyError } = await (supabase as any)
        .from("tenants")
        .update({ policies: updatedPolicies })
        .eq("id", tenantId);

      if (policyError) console.warn("Policy update error:", policyError);
      break;
    }

    case "intake_field": {
      // Update the tenant's intake_fields JSON field
      const { data: tenantIntakeData } = await (supabase as any)
        .from("tenants")
        .select("intake_fields")
        .eq("id", tenantId)
        .single();

      const currentFields = Array.isArray(tenantIntakeData?.intake_fields)
        ? (tenantIntakeData.intake_fields as Record<string, unknown>[])
        : [];

      const existingIdx = currentFields.findIndex(
        (f: any) => f.key === entity_key || f.name === entity_key
      );

      let updatedFields: Record<string, unknown>[];
      if (existingIdx >= 0) {
        updatedFields = [...currentFields];
        updatedFields[existingIdx] = { ...updatedFields[existingIdx], ...proposed_value };
      } else {
        updatedFields = [...currentFields, { key: entity_key, ...proposed_value }];
      }

      const { error: intakeError } = await (supabase as any)
        .from("tenants")
        .update({ intake_fields: updatedFields })
        .eq("id", tenantId);

      if (intakeError) console.warn("Intake field update error:", intakeError);
      break;
    }
  }
}

import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";

export type SuggestionType = "service" | "faq" | "menu_item" | "policy" | "objection";
export type SuggestionStatus = "pending_review" | "approved" | "rejected" | "merged";

export interface ExtractedKnowledgeSuggestion {
  id: string;
  tenant_id: string;
  source_id: string;
  suggestion_type: SuggestionType;
  extracted_data: Record<string, any>;
  status: SuggestionStatus;
  reviewed_at: string | null;
  reviewed_by: string | null;
  created_at: string;
}

export function useKnowledgeSuggestions() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  // Fetch all suggestions (optionally filter by status)
  const { data: suggestions = [], isLoading, error, refetch } = useQuery({
    queryKey: ["knowledge-suggestions", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];

      const { data, error } = await supabase
        .from("extracted_knowledge_suggestions")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false });

      if (error) throw error;
      return data as ExtractedKnowledgeSuggestion[];
    },
    enabled: !!tenant?.id,
  });

  // Approve a suggestion (creates the actual entity)
  const approveMutation = useMutation({
    mutationFn: async (suggestionId: string) => {
      const suggestion = suggestions.find((s) => s.id === suggestionId);
      if (!suggestion) throw new Error("Suggestion not found");

      // Based on suggestion type, create the appropriate entity
      const { suggestion_type, extracted_data } = suggestion;

      switch (suggestion_type) {
        case "service":
          await supabase.from("services").insert({
            tenant_id: tenant?.id,
            name: extracted_data.name,
            description: extracted_data.description,
            duration_minutes: extracted_data.duration_minutes || 60,
            price_type: extracted_data.price_type || "fixed",
            price_amount: extracted_data.price_amount,
            is_active: true,
          });
          break;

        case "faq":
          await supabase.from("business_faqs").insert({
            tenant_id: tenant?.id,
            question: extracted_data.question,
            answer: extracted_data.answer,
          });
          break;

        case "menu_item":
          await supabase.from("menu_items").insert({
            tenant_id: tenant?.id,
            name: extracted_data.name,
            description: extracted_data.description,
            price_cents: extracted_data.price_cents,
            category: extracted_data.category,
            dietary_tags: extracted_data.dietary_tags || [],
            is_available: true,
          });
          break;

        case "objection":
          await supabase.from("objection_responses").insert({
            tenant_id: tenant?.id,
            objection: extracted_data.objection,
            response: extracted_data.response,
          });
          break;

        case "policy":
          await supabase.from("ai_knowledge_base").insert({
            tenant_id: tenant?.id,
            type: "policy",
            title: extracted_data.title,
            content: extracted_data.content,
          });
          break;
      }

      // Mark suggestion as approved
      const { error: updateError } = await supabase
        .from("extracted_knowledge_suggestions")
        .update({
          status: "approved",
          reviewed_at: new Date().toISOString(),
        })
        .eq("id", suggestionId);

      if (updateError) throw updateError;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-suggestions", tenant?.id] });
      // Also invalidate related queries
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["faqs"] });
      queryClient.invalidateQueries({ queryKey: ["menu-items"] });
      queryClient.invalidateQueries({ queryKey: ["knowledge-stats"] });
    },
  });

  // Reject a suggestion
  const rejectMutation = useMutation({
    mutationFn: async (suggestionId: string) => {
      const { error } = await supabase
        .from("extracted_knowledge_suggestions")
        .update({
          status: "rejected",
          reviewed_at: new Date().toISOString(),
        })
        .eq("id", suggestionId);

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-suggestions", tenant?.id] });
    },
  });

  // Batch approve all pending suggestions
  const approveAllMutation = useMutation({
    mutationFn: async () => {
      const pending = suggestions.filter((s) => s.status === "pending_review");
      
      for (const suggestion of pending) {
        const { suggestion_type, extracted_data } = suggestion;

        switch (suggestion_type) {
          case "service":
            await supabase.from("services").insert({
              tenant_id: tenant?.id,
              name: extracted_data.name,
              description: extracted_data.description,
              duration_minutes: extracted_data.duration_minutes || 60,
              price_type: extracted_data.price_type || "fixed",
              price_amount: extracted_data.price_amount,
              is_active: true,
            });
            break;

          case "faq":
            await supabase.from("business_faqs").insert({
              tenant_id: tenant?.id,
              question: extracted_data.question,
              answer: extracted_data.answer,
            });
            break;

          case "menu_item":
            await supabase.from("menu_items").insert({
              tenant_id: tenant?.id,
              name: extracted_data.name,
              description: extracted_data.description,
              price_cents: extracted_data.price_cents,
              category: extracted_data.category,
              dietary_tags: extracted_data.dietary_tags || [],
              is_available: true,
            });
            break;

          case "objection":
            await supabase.from("objection_responses").insert({
              tenant_id: tenant?.id,
              objection: extracted_data.objection,
              response: extracted_data.response,
            });
            break;

          case "policy":
            await supabase.from("ai_knowledge_base").insert({
              tenant_id: tenant?.id,
              type: "policy",
              title: extracted_data.title,
              content: extracted_data.content,
            });
            break;
        }
      }

      // Mark all as approved
      const { error } = await supabase
        .from("extracted_knowledge_suggestions")
        .update({
          status: "approved",
          reviewed_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant?.id)
        .eq("status", "pending_review");

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-suggestions", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["services"] });
      queryClient.invalidateQueries({ queryKey: ["faqs"] });
      queryClient.invalidateQueries({ queryKey: ["menu-items"] });
      queryClient.invalidateQueries({ queryKey: ["knowledge-stats"] });
    },
  });

  // Batch reject all pending suggestions
  const rejectAllMutation = useMutation({
    mutationFn: async () => {
      const { error } = await supabase
        .from("extracted_knowledge_suggestions")
        .update({
          status: "rejected",
          reviewed_at: new Date().toISOString(),
        })
        .eq("tenant_id", tenant?.id)
        .eq("status", "pending_review");

      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["knowledge-suggestions", tenant?.id] });
    },
  });

  // Computed values
  const pendingCount = suggestions.filter((s) => s.status === "pending_review").length;
  const approvedCount = suggestions.filter((s) => s.status === "approved").length;
  const rejectedCount = suggestions.filter((s) => s.status === "rejected").length;

  const pendingSuggestions = suggestions.filter((s) => s.status === "pending_review");

  return {
    suggestions,
    pendingSuggestions,
    isLoading,
    error,
    refetch,
    pendingCount,
    approvedCount,
    rejectedCount,
    approve: approveMutation.mutateAsync,
    reject: rejectMutation.mutateAsync,
    approveAll: approveAllMutation.mutateAsync,
    rejectAll: rejectAllMutation.mutateAsync,
    isApproving: approveMutation.isPending,
    isRejecting: rejectMutation.isPending,
  };
}

import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";

export type CampaignStatus = "active" | "paused" | "converted" | "stopped" | "declined" | "expired" | "all";

export interface CampaignFilters {
  status?: CampaignStatus;
  search?: string;
  limit?: number;
  offset?: number;
}

export interface CampaignWithDetails {
  id: string;
  status: string;
  current_step: number;
  next_action_at: string | null;
  created_at: string;
  converted_at: string | null;
  recovered_value_cents: number | null;
  original_intent: string | null;
  original_service_interest: string | null;
  original_objection: string | null;
  original_call_outcome: string | null;
  total_attempts: number;
  total_responses: number;
  last_attempt_at: string | null;
  stopped_at: string | null;
  stopped_reason: string | null;
  converted_booking_id: string | null;
  customer: {
    id: string;
    full_name: string;
    phone_e164: string;
    email: string | null;
  } | null;
  sequence: {
    name: string;
    id: string;
  } | null;
  last_action: {
    action_type: string;
    executed_at: string;
    response_received: boolean;
    response_content: string | null;
    response_sentiment: string | null;
  } | null;
}

export interface CampaignCounts {
  all: number;
  active: number;
  paused: number;
  converted: number;
  stopped: number;
  declined: number;
}

export function useLeadRecoveryCampaigns(filters: CampaignFilters = {}) {
  const { tenant } = useAuth();
  const tenantId = tenant?.id;

  return useQuery({
    queryKey: ["lead-recovery-campaigns", tenantId, filters],
    queryFn: async (): Promise<{ campaigns: CampaignWithDetails[]; counts: CampaignCounts }> => {
      if (!tenantId) {
        return { campaigns: [], counts: { all: 0, active: 0, paused: 0, converted: 0, stopped: 0, declined: 0 } };
      }

      // Get counts for all statuses
      const { data: allCampaigns, error: countError } = await supabase
        .from("lead_recovery_campaigns")
        .select("status")
        .eq("tenant_id", tenantId);

      if (countError) {
        console.error("Error fetching campaign counts:", countError);
        throw countError;
      }

      const counts: CampaignCounts = {
        all: allCampaigns?.length || 0,
        active: allCampaigns?.filter(c => c.status === "active").length || 0,
        paused: allCampaigns?.filter(c => c.status === "paused").length || 0,
        converted: allCampaigns?.filter(c => c.status === "converted").length || 0,
        stopped: allCampaigns?.filter(c => c.status === "stopped" || c.status === "expired").length || 0,
        declined: allCampaigns?.filter(c => c.status === "declined").length || 0,
      };

      // Build filtered query
      let query = supabase
        .from("lead_recovery_campaigns")
        .select(`
          id,
          status,
          current_step,
          next_action_at,
          created_at,
          converted_at,
          recovered_value_cents,
          original_intent,
          original_service_interest,
          original_objection,
          original_call_outcome,
          total_attempts,
          total_responses,
          last_attempt_at,
          stopped_at,
          stopped_reason,
          converted_booking_id,
          customer:customers!lead_recovery_campaigns_customer_id_fkey(
            id,
            full_name,
            phone_e164,
            email
          ),
          sequence:lead_recovery_sequences!lead_recovery_campaigns_sequence_id_fkey(
            id,
            name
          )
        `)
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false });

      // Apply status filter
      if (filters.status && filters.status !== "all") {
        if (filters.status === "stopped") {
          // Include both stopped and expired
          query = query.in("status", ["stopped", "expired"]);
        } else {
          query = query.eq("status", filters.status);
        }
      }

      // Apply pagination
      const limit = filters.limit || 20;
      const offset = filters.offset || 0;
      query = query.range(offset, offset + limit - 1);

      const { data: campaigns, error } = await query;

      if (error) {
        console.error("Error fetching campaigns:", error);
        throw error;
      }

      // Fetch last action for each campaign
      const campaignIds = campaigns?.map(c => c.id) || [];
      
      const actionsMap: Record<string, any> = {};
      if (campaignIds.length > 0) {
        const { data: actions } = await supabase
          .from("lead_recovery_actions")
          .select("campaign_id, action_type, executed_at, response_received, response_content, response_sentiment")
          .in("campaign_id", campaignIds)
          .order("executed_at", { ascending: false });

        // Group by campaign_id and take first (most recent)
        if (actions) {
          for (const action of actions) {
            if (!actionsMap[action.campaign_id]) {
              actionsMap[action.campaign_id] = action;
            }
          }
        }
      }

      // Filter by search if provided
      let filteredCampaigns = campaigns || [];
      if (filters.search) {
        const searchLower = filters.search.toLowerCase();
        filteredCampaigns = filteredCampaigns.filter(c => {
          const name = c.customer?.full_name?.toLowerCase() || "";
          const phone = c.customer?.phone_e164 || "";
          return name.includes(searchLower) || phone.includes(filters.search || "");
        });
      }

      // Map campaigns with last action
      const campaignsWithDetails: CampaignWithDetails[] = filteredCampaigns.map(c => ({
        ...c,
        customer: c.customer as CampaignWithDetails["customer"],
        sequence: c.sequence as CampaignWithDetails["sequence"],
        last_action: actionsMap[c.id] || null,
      }));

      return { campaigns: campaignsWithDetails, counts };
    },
    enabled: !!tenantId,
    refetchInterval: 30000, // Refresh every 30 seconds
  });
}

export function useRecentBookings() {
  const { tenant } = useAuth();
  const tenantId = tenant?.id;

  return useQuery({
    queryKey: ["recent-bookings-for-recovery", tenantId],
    queryFn: async () => {
      if (!tenantId) return [];

      const { data, error } = await supabase
        .from("bookings")
        .select(`
          id,
          start_at,
          status,
          service:services(name)
        `)
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(20);

      if (error) {
        console.error("Error fetching recent bookings:", error);
        return [];
      }

      return data || [];
    },
    enabled: !!tenantId,
  });
}

import { useState, useCallback } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";

export interface ChatMessage {
  id?: string;
  role: "user" | "assistant";
  content: string;
  category: string;
  created_at?: string;
}

export function useMarketingChatHistory(userId: string | undefined, sessionId: string) {
  return useQuery({
    queryKey: ["marketing-chat-history", userId, sessionId],
    enabled: !!userId && !!sessionId,
    queryFn: async () => {
      const { data, error } = await supabase
        .from("admin_marketing_chats" as any)
        .select("*")
        .eq("user_id", userId!)
        .eq("session_id", sessionId)
        .order("created_at", { ascending: true });
      if (error) throw error;
      return (data ?? []) as unknown as ChatMessage[];
    },
  });
}

export function useMarketingChat(userId: string | undefined) {
  const qc = useQueryClient();
  const [sessionId] = useState(() => crypto.randomUUID());
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isStreaming, setIsStreaming] = useState(false);

  const sendMessage = useCallback(async (content: string, category: string) => {
    if (!userId) return;

    const userMsg: ChatMessage = { role: "user", content, category };
    setMessages((prev) => [...prev, userMsg]);

    // Save user message to DB
    await supabase.from("admin_marketing_chats" as any).insert({
      user_id: userId,
      session_id: sessionId,
      role: "user",
      content,
      category,
    } as any);

    setIsStreaming(true);
    try {
      const { data, error } = await supabase.functions.invoke("marketing-chat", {
        body: {
          messages: [...messages, userMsg].map((m) => ({
            role: m.role,
            content: m.content,
          })),
          category,
        },
      });

      if (error) throw error;

      const assistantContent = data?.content || "I apologize, I couldn't generate a response. Please try again.";
      const assistantMsg: ChatMessage = { role: "assistant", content: assistantContent, category };
      setMessages((prev) => [...prev, assistantMsg]);

      // Save assistant message to DB
      await supabase.from("admin_marketing_chats" as any).insert({
        user_id: userId,
        session_id: sessionId,
        role: "assistant",
        content: assistantContent,
        category,
      } as any);
    } catch (err) {
      console.error("Marketing chat error:", err);
      toast.error("Failed to get AI response. Try again.");
    } finally {
      setIsStreaming(false);
    }
  }, [userId, sessionId, messages]);

  const clearChat = useCallback(() => {
    setMessages([]);
  }, []);

  return {
    messages,
    isStreaming,
    sendMessage,
    clearChat,
    sessionId,
  };
}

