import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig, type BusinessMode } from "@/hooks/useTenantConfig";

export interface NotificationEvent {
  eventType: string;
  label: string;
  description: string;
  category: "calls" | "bookings" | "intelligence" | "reports" | "mode_specific";
  requiredModule?: string;
  requiredMode?: BusinessMode[];
}

export const NOTIFICATION_EVENTS: NotificationEvent[] = [
  // Calls & Leads
  { eventType: "missed_call", label: "Missed calls", description: "When an inbound call is missed", category: "calls" },
  { eventType: "new_lead", label: "New leads", description: "When a new lead is captured", category: "calls" },
  { eventType: "ai_escalation", label: "AI escalations", description: "When the AI needs human help", category: "calls" },

  // Bookings
  { eventType: "new_booking", label: "New bookings", description: "When a booking is created", category: "bookings", requiredModule: "booking" },
  { eventType: "booking_cancelled", label: "Cancellations", description: "When a booking is cancelled", category: "bookings", requiredModule: "booking" },

  // Intelligence
  { eventType: "knowledge_gap", label: "Knowledge gaps", description: "When the AI encounters an unanswered question", category: "intelligence" },
  { eventType: "handoff_failure", label: "Handoff failures", description: "When a booking/order handoff fails", category: "intelligence" },

  // Reports
  { eventType: "daily_summary", label: "Daily summary", description: "A daily digest of calls and bookings", category: "reports" },

  // Mode-specific
  { eventType: "dispatch_urgent", label: "Urgent dispatches", description: "When a high-priority job comes in", category: "mode_specific", requiredModule: "dispatch_queue" },
  { eventType: "new_order", label: "New orders", description: "When a food order is placed", category: "mode_specific", requiredModule: "food_orders" },
  { eventType: "new_estimate_request", label: "Estimate requests", description: "When a customer requests an estimate", category: "mode_specific" },
];

interface NotificationPref {
  id: string;
  event_type: string;
  channel_email: boolean;
  channel_sms: boolean;
  channel_push: boolean;
  enabled: boolean;
}

export function useNotificationPreferences() {
  const { user, tenant } = useAuth();
  const { enabledModules, businessMode } = useTenantConfig();
  const queryClient = useQueryClient();
  const tenantId = tenant?.id;
  const userId = user?.id;

  // Filter visible events based on enabled modules and business mode
  const visibleEvents = NOTIFICATION_EVENTS.filter((event) => {
    if (event.requiredModule && !enabledModules.includes(event.requiredModule)) return false;
    if (event.requiredMode && !event.requiredMode.includes(businessMode)) return false;
    return true;
  });

  const prefsQuery = useQuery({
    queryKey: ["notification-preferences", tenantId, userId],
    queryFn: async () => {
      if (!tenantId || !userId) return [];

      const { data, error } = await (supabase as any)
        .from("notification_preferences")
        .select("id, event_type, channel_email, channel_sms, channel_push, enabled")
        .eq("tenant_id", tenantId)
        .eq("user_id", userId);

      if (error) throw error;
      return (data ?? []) as NotificationPref[];
    },
    enabled: !!tenantId && !!userId,
  });

  const togglePreference = useMutation({
    mutationFn: async ({ eventType, enabled }: { eventType: string; enabled: boolean }) => {
      if (!tenantId || !userId) throw new Error("Missing tenant or user");

      const { error } = await (supabase as any)
        .from("notification_preferences")
        .upsert(
          {
            tenant_id: tenantId,
            user_id: userId,
            event_type: eventType,
            enabled,
            channel_email: true,
            updated_at: new Date().toISOString(),
          },
          { onConflict: "tenant_id,user_id,event_type" },
        );

      if (error) throw error;
    },
    onMutate: async ({ eventType, enabled }) => {
      await queryClient.cancelQueries({ queryKey: ["notification-preferences", tenantId, userId] });
      const previous = queryClient.getQueryData<NotificationPref[]>(["notification-preferences", tenantId, userId]);

      queryClient.setQueryData<NotificationPref[]>(
        ["notification-preferences", tenantId, userId],
        (old = []) => {
          const exists = old.find((p) => p.event_type === eventType);
          if (exists) {
            return old.map((p) => (p.event_type === eventType ? { ...p, enabled } : p));
          }
          return [...old, { id: "temp", event_type: eventType, channel_email: true, channel_sms: false, channel_push: false, enabled }];
        },
      );

      return { previous };
    },
    onError: (_err, _vars, context) => {
      if (context?.previous) {
        queryClient.setQueryData(["notification-preferences", tenantId, userId], context.previous);
      }
    },
    onSettled: () => {
      queryClient.invalidateQueries({ queryKey: ["notification-preferences", tenantId, userId] });
    },
  });

  // Helper to get the enabled status for an event type
  const getPreference = (eventType: string): boolean => {
    const pref = prefsQuery.data?.find((p) => p.event_type === eventType);
    // Default to enabled if no preference exists
    return pref ? pref.enabled : true;
  };

  return {
    preferences: prefsQuery.data ?? [],
    visibleEvents,
    isLoading: prefsQuery.isLoading,
    getPreference,
    togglePreference,
  };
}

/**
 * useOAuthConnect — reusable hook for initiating OAuth popup flows.
 *
 * Works with both:
 * - The existing calendar-oauth-start/callback (for Google/Microsoft calendars)
 * - The new universal integration-oauth-start/callback (for all providers)
 *
 * Usage:
 *   const { connect, isConnecting } = useOAuthConnect({ onSuccess, onError });
 *   connect("hubspot");
 */
import { useState, useEffect, useCallback, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";
import { useQueryClient } from "@tanstack/react-query";

interface UseOAuthConnectOptions {
  onSuccess?: (provider: string) => void;
  onError?: (provider: string, error: string) => void;
}

export function useOAuthConnect(options: UseOAuthConnectOptions = {}) {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [isConnecting, setIsConnecting] = useState(false);
  const [connectingProvider, setConnectingProvider] = useState<string | null>(null);
  const popupRef = useRef<Window | null>(null);

  // Listen for postMessage from popup
  useEffect(() => {
    function handleMessage(event: MessageEvent) {
      const { type, provider, error, calendars } = event.data || {};

      // Handle universal integration OAuth
      if (type === "integration-oauth-success") {
        setIsConnecting(false);
        setConnectingProvider(null);
        popupRef.current = null;

        // Invalidate relevant queries
        queryClient.invalidateQueries({ queryKey: ["integrations", tenant?.id] });
        queryClient.invalidateQueries({ queryKey: ["calendar_connections", tenant?.id] });

        toast({ title: `${provider || "Integration"} connected` });
        options.onSuccess?.(provider);
      }

      if (type === "integration-oauth-error") {
        setIsConnecting(false);
        setConnectingProvider(null);
        popupRef.current = null;

        toast({
          title: "Connection failed",
          description: error || "Something went wrong",
          variant: "destructive",
        });
        options.onError?.(connectingProvider || "", error);
      }

      // Handle legacy calendar OAuth (backward compat)
      if (type === "calendar-oauth-success") {
        setIsConnecting(false);
        setConnectingProvider(null);
        popupRef.current = null;

        queryClient.invalidateQueries({ queryKey: ["calendar_connections", tenant?.id] });

        toast({ title: "Calendar connected" });
        options.onSuccess?.(connectingProvider || "calendar");
      }

      if (type === "calendar-oauth-error") {
        setIsConnecting(false);
        setConnectingProvider(null);
        popupRef.current = null;

        toast({
          title: "Calendar connection failed",
          description: error || "Something went wrong",
          variant: "destructive",
        });
        options.onError?.(connectingProvider || "", error);
      }
    }

    window.addEventListener("message", handleMessage);
    return () => window.removeEventListener("message", handleMessage);
  }, [tenant?.id, connectingProvider, queryClient, toast, options]);

  const connect = useCallback(
    async (providerId: string) => {
      if (!tenant?.id) {
        toast({
          title: "No active business",
          description: "Please select a business first.",
          variant: "destructive",
        });
        return;
      }

      setIsConnecting(true);
      setConnectingProvider(providerId);

      try {
        // Call universal OAuth start
        const { data, error } = await supabase.functions.invoke(
          "integration-oauth-start",
          {
            body: { provider: providerId, tenant_id: tenant.id },
          },
        );

        if (error) throw new Error(error.message);
        if (!data?.auth_url) throw new Error("No auth URL returned");

        // Open popup
        const width = 600;
        const height = 700;
        const left = window.screenX + (window.outerWidth - width) / 2;
        const top = window.screenY + (window.outerHeight - height) / 2;

        const popup = window.open(
          data.auth_url,
          `oauth-${providerId}`,
          `width=${width},height=${height},left=${left},top=${top},scrollbars=yes`,
        );

        if (!popup) {
          throw new Error("Popup blocked — please allow popups for this site.");
        }

        popupRef.current = popup;

        // Poll for popup close (in case user closes without completing)
        const pollTimer = setInterval(() => {
          if (popup.closed) {
            clearInterval(pollTimer);
            // Give a moment for postMessage to arrive before declaring failure
            setTimeout(() => {
              if (isConnecting) {
                setIsConnecting(false);
                setConnectingProvider(null);
              }
            }, 1000);
          }
        }, 500);
      } catch (err) {
        setIsConnecting(false);
        setConnectingProvider(null);

        const message = err instanceof Error ? err.message : "Failed to start OAuth";
        toast({
          title: "Connection failed",
          description: message,
          variant: "destructive",
        });
        options.onError?.(providerId, message);
      }
    },
    [tenant?.id, toast, options, isConnecting],
  );

  const disconnect = useCallback(
    async (providerId: string) => {
      if (!tenant?.id) return;

      try {
        // Remove from integrations table
        await supabase
          .from("integrations")
          .delete()
          .eq("tenant_id", tenant.id)
          .eq("provider", providerId);

        // Remove OAuth tokens
        await (supabase as any)
          .from("integration_oauth_tokens")
          .delete()
          .eq("tenant_id", tenant.id)
          .eq("provider", providerId);

        queryClient.invalidateQueries({ queryKey: ["integrations", tenant.id] });
        toast({ title: "Integration disconnected" });
      } catch (err) {
        const message = err instanceof Error ? err.message : "Failed to disconnect";
        toast({ title: "Error", description: message, variant: "destructive" });
      }
    },
    [tenant?.id, queryClient, toast],
  );

  return {
    connect,
    disconnect,
    isConnecting,
    connectingProvider,
  };
}

/**
 * useOnboardingFormState — All onboarding form state, initialization effects, and auto-save.
 * Extracted from OnboardingPage.tsx for maintainability.
 */
import { useState, useEffect, useRef, useCallback, useMemo } from "react";
import type { MappedOnboardingData } from "@/lib/mapWebsiteImportToOnboarding";
import { type BusinessMode, getDefaultModulesForMode } from "@/components/onboarding/BusinessModeSelector";
import { getDefaultCommunicationPrefs, type CommunicationPrefs, type AITone, type AIBookingMode } from "@/components/onboarding/CommunicationPreferences";
import { getDefaultBusinessDetails, type BusinessDetails } from "@/components/onboarding/BusinessDetailsForm";
import { getDefaultA2PData, type A2PBusinessData } from "@/components/onboarding/A2PBusinessFields";
import { getDefaultSchedulingPrefs, getDefaultHoursForMode, type SchedulingPrefs } from "@/components/onboarding/SchedulingSetup";
import { type TeamMember } from "@/components/onboarding/TeamSetupStep";
import { getQuestionsForMode, getDefaultAnswers, deriveModulesFromScenario } from "@/lib/scenarioQuestions";
import { DEFAULT_BUSINESS_HOURS } from "@/lib/hoursUtils";
import { type EditableService } from "@/components/onboarding/ServicePreviewStep";
import { getDefaultServiceArea, type ServiceAreaConfig } from "@/components/onboarding/ServiceAreaStep";
import type { EditablePolicies } from "@/components/onboarding/PolicyPreviewStep";
import type { EditableFAQ } from "@/components/onboarding/FAQPreviewStep";
import { getIndustryOnboardingConfig } from "@/config/industryOnboardingConfig";
import type { BusinessHours } from "@/components/onboarding/BusinessHoursEditor";
import { getIndustryBySlug } from "@/data/industryCatalog";
import { resolveIndustryTemplate } from "@/lib/templateResolver";
import type { WorkStyle } from "@/components/onboarding/phases/OnboardingIdentity";
import type { AfterHoursBehavior } from "@/components/onboarding/phases/OnboardingAI";

// ─── Persistence helpers ────────────────────────────────────────────────────

export interface OnboardingDataState {
  businessName: string;
  businessAddress: string;
  businessMode: BusinessMode;
  industrySlug: string;
  workStyle: WorkStyle;
  scenarioAnswers: Record<string, boolean>;
  scenarioDetails: Record<string, string>;
  schedulingPrefs: SchedulingPrefs;
  communicationPrefs: CommunicationPrefs;
  templateServices: EditableService[];
  templateFAQs: EditableFAQ[];
  templatePolicies: EditablePolicies;
  serviceArea: ServiceAreaConfig;
  businessDetails: BusinessDetails;
  businessHours: BusinessHours;
  teamMembers: TeamMember[];
  isSoloOperator: boolean;
  a2pData: A2PBusinessData;
  aiTone: AITone;
  bookingMode: AIBookingMode;
  afterHours: AfterHoursBehavior;
  customGreeting: string;
  notificationPhone: string;
  otherDescription: string;
  savedAt?: string;
}

function getOldStorageKey(userId?: string) {
  return `voxly_onboarding_progress_${userId || "anon"}`;
}

function getDataStorageKey(userId?: string) {
  return `voxly_onboarding_data_v2_${userId || "anon"}`;
}

export function saveOnboardingData(state: Partial<OnboardingDataState>, userId?: string) {
  try {
    localStorage.setItem(getDataStorageKey(userId), JSON.stringify({ ...state, savedAt: new Date().toISOString() }));
  } catch { /* ignore */ }
}

export function loadOnboardingData(userId?: string): OnboardingDataState | null {
  try {
    const raw = localStorage.getItem(getDataStorageKey(userId));
    if (raw) return JSON.parse(raw) as OnboardingDataState;
    const oldRaw = localStorage.getItem(getOldStorageKey(userId));
    if (oldRaw) return JSON.parse(oldRaw) as OnboardingDataState;
  } catch { /* ignore */ }
  return null;
}

export function clearOnboardingData(userId?: string) {
  localStorage.removeItem(getDataStorageKey(userId));
  localStorage.removeItem(getOldStorageKey(userId));
}

// ─── Hook ───────────────────────────────────────────────────────────────────

export function useOnboardingFormState(userId?: string) {
  const saved = useRef(loadOnboardingData(userId));
  const initializedIndustryRef = useRef<string | null>(saved.current?.industrySlug || null);
  const websiteImportActiveRef = useRef(false);

  // Auto-save indicator
  const [saveStatus, setSaveStatus] = useState<"idle" | "saving" | "saved">("idle");
  const saveTimerRef = useRef<ReturnType<typeof setTimeout>>();

  // --- All form state ---
  const initialBusinessName = saved.current?.businessName || sessionStorage.getItem("businessName") || "";
  const [businessName, setBusinessName] = useState(initialBusinessName);
  const [businessAddress, setBusinessAddress] = useState(saved.current?.businessAddress ?? "");
  const [businessMode, setBusinessMode] = useState<BusinessMode>(saved.current?.businessMode ?? "service");
  const [industrySlug, setIndustrySlug] = useState(saved.current?.industrySlug ?? "");
  const [workStyle, setWorkStyle] = useState<WorkStyle>(saved.current?.workStyle ?? "customer_comes");
  const [enabledModules, setEnabledModules] = useState<string[]>([]);
  const baseModulesRef = useRef<string[]>([]);
  const [businessDetails, setBusinessDetails] = useState<BusinessDetails>(saved.current?.businessDetails ?? getDefaultBusinessDetails());
  const [scenarioAnswers, setScenarioAnswers] = useState<Record<string, boolean>>(saved.current?.scenarioAnswers ?? {});
  const [scenarioDetails, setScenarioDetails] = useState<Record<string, string>>(saved.current?.scenarioDetails ?? {});
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>(saved.current?.teamMembers ?? []);
  const [isSoloOperator, setIsSoloOperator] = useState(saved.current?.isSoloOperator ?? true);
  const [a2pData, setA2pData] = useState<A2PBusinessData>(saved.current?.a2pData ?? getDefaultA2PData());
  const [businessHours, setBusinessHours] = useState<BusinessHours>(saved.current?.businessHours ?? DEFAULT_BUSINESS_HOURS);
  const [schedulingPrefs, setSchedulingPrefs] = useState<SchedulingPrefs>(saved.current?.schedulingPrefs ?? getDefaultSchedulingPrefs("service"));
  const [communicationPrefs, setCommunicationPrefs] = useState<CommunicationPrefs>(
    saved.current?.communicationPrefs ?? getDefaultCommunicationPrefs("service")
  );
  const [templateServices, setTemplateServices] = useState<EditableService[]>(saved.current?.templateServices ?? []);
  const [templateFAQs, setTemplateFAQs] = useState<EditableFAQ[]>(saved.current?.templateFAQs ?? []);
  const [templatePolicies, setTemplatePolicies] = useState<EditablePolicies>(saved.current?.templatePolicies ?? { cancellation: "", deposit: "", refund: "" });
  const [serviceArea, setServiceArea] = useState<ServiceAreaConfig>(saved.current?.serviceArea ?? getDefaultServiceArea("service"));

  // Phase 3 state
  const [aiTone, setAiTone] = useState<AITone>(saved.current?.aiTone ?? "friendly");
  const [bookingMode, setBookingMode] = useState<AIBookingMode>(saved.current?.bookingMode ?? "auto_book");
  const [afterHours, setAfterHours] = useState<AfterHoursBehavior>(saved.current?.afterHours ?? "ai_24_7");
  const [customGreeting, setCustomGreeting] = useState(saved.current?.customGreeting ?? "");

  // Phase 4 state
  const [notificationPhone, setNotificationPhone] = useState(saved.current?.notificationPhone ?? "");
  const [calendarConnected] = useState(false);

  // "Other" industry description
  const [otherDescription, setOtherDescription] = useState(saved.current?.otherDescription ?? "");

  // Clear signup sessionStorage
  useEffect(() => { sessionStorage.removeItem("businessName"); }, []);

  // Load industry from sessionStorage
  useEffect(() => {
    const storedIndustry = sessionStorage.getItem("selectedIndustry");
    if (storedIndustry && storedIndustry !== industrySlug) {
      const isValid = getIndustryBySlug(storedIndustry);
      if (isValid) setIndustrySlug(storedIndustry);
      sessionStorage.removeItem("selectedIndustry");
    }
  }, []);

  // Initialize when industry changes
  useEffect(() => {
    if (!industrySlug) return;
    if (initializedIndustryRef.current === industrySlug) return;
    const industryEntry = getIndustryBySlug(industrySlug);
    const newMode = industryEntry?.businessMode || businessMode;
    if (industryEntry?.businessMode) {
      setBusinessMode(newMode);
      setCommunicationPrefs(getDefaultCommunicationPrefs(newMode));
      setSchedulingPrefs(getDefaultSchedulingPrefs(newMode, undefined, industrySlug));
      const ctx = { slug: industrySlug, category: industryEntry.category };
      const defaults = getDefaultAnswers(newMode, ctx);
      const onboardingConfig = getIndustryOnboardingConfig(newMode, industryEntry.category, industrySlug);
      setScenarioAnswers({ ...defaults, ...onboardingConfig.preAnswers });
      const modePrefs = getDefaultCommunicationPrefs(newMode);
      setAiTone(modePrefs.aiTone);
      setBookingMode(modePrefs.aiBookingMode);
    }
    const modules = industryEntry?.enabledModules ?? getDefaultModulesForMode(businessMode);
    setEnabledModules(modules);
    baseModulesRef.current = modules;

    // GUARD: If website import is active, skip overwriting services/FAQs/hours
    if (!websiteImportActiveRef.current) {
      const config = resolveIndustryTemplate(industrySlug);
      setTemplateServices(config.services.map(s => ({
        name: s.name, duration: s.duration, price: s.price,
        priceType: s.priceType || "fixed", description: s.description, enabled: true,
      })));
      setTemplateFAQs(config.faqs.map(f => ({ question: f.question, answer: f.answer, enabled: true })));
      setTemplatePolicies({
        cancellation: config.defaultPolicies?.cancellation || "",
        deposit: config.defaultPolicies?.deposit || "",
        refund: config.defaultPolicies?.refund || "",
      });
      setBusinessHours(getDefaultHoursForMode(newMode));
      setServiceArea(getDefaultServiceArea(newMode as BusinessMode));
    }
    if (newMode === "dispatch") setWorkStyle("go_to_customer");
    else if (newMode === "food") setWorkStyle("customer_comes");
    initializedIndustryRef.current = industrySlug;
  }, [industrySlug, businessMode]);

  // Derive modules from scenario answers
  useEffect(() => {
    if (Object.keys(scenarioAnswers).length === 0) return;
    const industryEntry = industrySlug ? getIndustryBySlug(industrySlug) : undefined;
    const ctx = industryEntry ? { slug: industrySlug, category: industryEntry.category } : undefined;
    const questions = getQuestionsForMode(businessMode, ctx);
    const derived = deriveModulesFromScenario(baseModulesRef.current, scenarioAnswers, questions);
    setEnabledModules(derived);
  }, [scenarioAnswers, businessMode, industrySlug]);

  const handleBusinessModeChange = useCallback((mode: BusinessMode) => {
    setBusinessMode(mode);
    const industryEntry = industrySlug ? getIndustryBySlug(industrySlug) : undefined;
    const ctx = industryEntry ? { slug: industrySlug, category: industryEntry.category } : undefined;
    setScenarioAnswers(getDefaultAnswers(mode, ctx));
    setCommunicationPrefs(getDefaultCommunicationPrefs(mode));
    setSchedulingPrefs(getDefaultSchedulingPrefs(mode, undefined, industrySlug));
    setBusinessHours(getDefaultHoursForMode(mode));
    setServiceArea(getDefaultServiceArea(mode));
    const modePrefs = getDefaultCommunicationPrefs(mode);
    setAiTone(modePrefs.aiTone);
    setBookingMode(modePrefs.aiBookingMode);
  }, [industrySlug]);

  // Auto-save debounced
  const triggerAutoSave = useCallback((isComplete: boolean, resumeDecided: boolean) => {
    if (isComplete || !resumeDecided) return;
    setSaveStatus("saving");
    const timer = setTimeout(() => {
      saveOnboardingData({
        businessName, businessAddress, businessMode, industrySlug, workStyle,
        scenarioAnswers, scenarioDetails, schedulingPrefs, communicationPrefs,
        templateServices, templateFAQs, templatePolicies,
        serviceArea, businessDetails, businessHours,
        teamMembers, isSoloOperator, a2pData,
        aiTone, bookingMode, afterHours, customGreeting, notificationPhone, otherDescription,
      }, userId);
      setSaveStatus("saved");
      if (saveTimerRef.current) clearTimeout(saveTimerRef.current);
      saveTimerRef.current = setTimeout(() => setSaveStatus("idle"), 2000);
    }, 3000);
    return () => clearTimeout(timer);
  }, [businessName, businessAddress, businessMode, industrySlug, workStyle, scenarioAnswers, scenarioDetails, schedulingPrefs, communicationPrefs, templateServices, templateFAQs, templatePolicies, serviceArea, businessDetails, businessHours, teamMembers, isSoloOperator, a2pData, aiTone, bookingMode, afterHours, customGreeting, notificationPhone, otherDescription, userId]);

  // --- Website import support ---
  const applyWebsiteImport = useCallback((mapped: MappedOnboardingData) => {
    websiteImportActiveRef.current = true;

    if (mapped.businessName) setBusinessName(mapped.businessName);
    if (mapped.suggestedIndustrySlug) setIndustrySlug(mapped.suggestedIndustrySlug);
    if (mapped.address) {
      setBusinessAddress(mapped.address);
      setBusinessDetails(prev => ({ ...prev, location: mapped.address! }));
    }

    // Direct-set imported data (protected from template override by the guard)
    if (mapped.services.length > 0) setTemplateServices(mapped.services);
    if (mapped.faqs.length > 0) setTemplateFAQs(mapped.faqs);
    if (mapped.hours) setBusinessHours(mapped.hours);
  }, []);

  const clearWebsiteImport = useCallback(() => {
    websiteImportActiveRef.current = false;
  }, []);

  const websiteImportActive = useMemo(() => websiteImportActiveRef.current, [
    // Re-derive when industry changes (the ref is set in applyWebsiteImport/clearWebsiteImport)
    industrySlug,
  ]);

  const resetFormState = useCallback(() => {
    setBusinessName(sessionStorage.getItem("businessName") || "");
    setBusinessAddress("");
    setIndustrySlug("");
    setScenarioAnswers({});
    setScenarioDetails({});
    setTemplateServices([]);
    setTemplateFAQs([]);
    setTemplatePolicies({ cancellation: "", deposit: "", refund: "" });
    setOtherDescription("");
    initializedIndustryRef.current = null;
    websiteImportActiveRef.current = false;
  }, []);

  return {
    // Form state
    businessName, setBusinessName,
    businessAddress, setBusinessAddress,
    businessMode, setBusinessMode,
    industrySlug, setIndustrySlug,
    workStyle, setWorkStyle,
    enabledModules, setEnabledModules,
    businessDetails, setBusinessDetails,
    scenarioAnswers, setScenarioAnswers,
    scenarioDetails, setScenarioDetails,
    teamMembers, setTeamMembers,
    isSoloOperator, setIsSoloOperator,
    a2pData, setA2pData,
    businessHours, setBusinessHours,
    schedulingPrefs, setSchedulingPrefs,
    communicationPrefs, setCommunicationPrefs,
    templateServices, setTemplateServices,
    templateFAQs, setTemplateFAQs,
    templatePolicies, setTemplatePolicies,
    serviceArea, setServiceArea,
    aiTone, setAiTone,
    bookingMode, setBookingMode,
    afterHours, setAfterHours,
    customGreeting, setCustomGreeting,
    notificationPhone, setNotificationPhone,
    otherDescription, setOtherDescription,
    calendarConnected,
    // Actions
    handleBusinessModeChange,
    triggerAutoSave,
    resetFormState,
    // Website import
    applyWebsiteImport,
    clearWebsiteImport,
    websiteImportActive,
    // Auto-save
    saveStatus,
    saved,
  };
}

/**
 * useOnboardingSubmit — Handles the complete onboarding submission flow.
 * Extracted from OnboardingPage.tsx for maintainability.
 */
import { useState, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { formatErrorForToast } from "@/lib/errorMessages";
import { resolveIndustryTemplate } from "@/lib/templateResolver";
import { getIndustryBySlug } from "@/data/industryCatalog";
import { getTemplate, fetchCurrentBrainState, previewTemplateApplication, applyTemplate } from "@/lib/industryTemplates";
import { updateCapabilityFlags } from "@/hooks/useBusinessCapabilities";
import { applyScenarioSeeds } from "@/lib/scenarioSeeding";
import { createDefaultWorkflowsForMode } from "@/lib/createDefaultWorkflows";
import { clearOnboardingData } from "@/hooks/useOnboardingFormState";
import type { BusinessMode } from "@/components/onboarding/BusinessModeSelector";
import type { EditableService } from "@/components/onboarding/ServicePreviewStep";
import type { EditableFAQ } from "@/components/onboarding/FAQPreviewStep";
import type { EditablePolicies } from "@/components/onboarding/PolicyPreviewStep";
import type { ServiceAreaConfig } from "@/components/onboarding/ServiceAreaStep";
import type { BusinessDetails } from "@/components/onboarding/BusinessDetailsForm";
import type { CommunicationPrefs, AITone, AIBookingMode } from "@/components/onboarding/CommunicationPreferences";
import type { SchedulingPrefs } from "@/components/onboarding/SchedulingSetup";
import type { A2PBusinessData } from "@/components/onboarding/A2PBusinessFields";
import type { WorkStyle } from "@/components/onboarding/phases/OnboardingIdentity";
import type { AfterHoursBehavior } from "@/components/onboarding/phases/OnboardingAI";
import type { PlanCode } from "@/types/database";

const MAX_RETRIES = 3;

interface SubmitParams {
  businessName: string;
  businessAddress: string;
  businessMode: BusinessMode;
  industrySlug: string;
  workStyle: WorkStyle;
  enabledModules: string[];
  scenarioAnswers: Record<string, boolean>;
  scenarioDetails: Record<string, string>;
  schedulingPrefs: SchedulingPrefs;
  communicationPrefs: CommunicationPrefs;
  templateServices: EditableService[];
  templateFAQs: EditableFAQ[];
  templatePolicies: EditablePolicies;
  serviceArea: ServiceAreaConfig;
  businessDetails: BusinessDetails;
  businessHours: Record<string, unknown>;
  teamMembers: { name: string; role: string; phone?: string; email?: string; canPerformAllServices: boolean; serviceNames: string[] }[];
  isSoloOperator: boolean;
  a2pData: A2PBusinessData;
  aiTone: AITone;
  bookingMode: AIBookingMode;
  afterHours: AfterHoursBehavior;
  customGreeting: string;
  notificationPhone: string;
}

export function useOnboardingSubmit(userId?: string) {
  const { user, refreshTenant, isSuperAdmin } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();

  const [loading, setLoading] = useState(false);
  const [isComplete, setIsComplete] = useState(false);
  const [provisionedPhone, setProvisionedPhone] = useState<string | undefined>();
  const [retryCount, setRetryCount] = useState(0);
  const [showRetry, setShowRetry] = useState(false);
  const [completionError, setCompletionError] = useState<string | null>(null);
  // Idempotency: remember the tenant ID created in step 1 so retries don't duplicate
  const [createdTenantId, setCreatedTenantId] = useState<string | null>(null);

  const handleComplete = useCallback(async (params: SubmitParams, clearProgress: () => void) => {
    if (!user) {
      toast({ variant: "destructive", title: "Not logged in", description: "Please log in to complete setup." });
      navigate("/login?redirect=/app/onboarding");
      return;
    }
    setLoading(true);
    try {
      const {
        businessName, businessAddress, businessMode, industrySlug, workStyle, enabledModules,
        scenarioAnswers, scenarioDetails, schedulingPrefs, communicationPrefs,
        templateServices, templateFAQs, templatePolicies, serviceArea,
        businessDetails, businessHours, teamMembers, isSoloOperator, a2pData,
        aiTone, bookingMode, afterHours, customGreeting, notificationPhone,
      } = params;

      const isFoodMode = businessMode === "food" || enabledModules.includes("food_orders");
      const industryEntry = getIndustryBySlug(industrySlug);
      const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

      // Build capabilities_json
      const capabilitiesJson: Record<string, boolean | string> = {};
      for (const mod of enabledModules) capabilitiesJson[mod] = true;
      for (const [key, val] of Object.entries(scenarioAnswers)) capabilitiesJson[key] = val;
      for (const [key, val] of Object.entries(scenarioDetails)) {
        if (val) capabilitiesJson[`_${key}`] = val;
      }
      capabilitiesJson._teamSize = businessDetails.teamSize;
      capabilitiesJson._locationType = businessDetails.locationType;
      capabilitiesJson._pricingPosition = businessDetails.pricingPosition;
      capabilitiesJson._customerType = businessDetails.customerType;
      capabilitiesJson._expectedCallVolume = businessDetails.expectedCallVolume;
      capabilitiesJson._yearsInBusiness = businessDetails.yearsInBusiness;
      capabilitiesJson._isSoloOperator = isSoloOperator;
      capabilitiesJson._workStyle = workStyle;

      const discoveryTeamSize = (scenarioAnswers as Record<string, any>)._teamSize as string | undefined;
      const effectiveTeamSize = discoveryTeamSize || businessDetails.teamSize;
      const hasTeam = effectiveTeamSize === "small" || effectiveTeamSize === "medium" || effectiveTeamSize === "large";
      if (hasTeam) {
        capabilitiesJson.hasMultipleStaff = true;
        capabilitiesJson.fleet_management = true;
        if (!enabledModules.includes("fleet_management")) enabledModules.push("fleet_management");
      }

      const teamCapacityMap: Record<string, number> = { solo: 1, small: 3, medium: 9, large: 20 };
      const defaultCapacity = teamCapacityMap[effectiveTeamSize] || 1;

      const hoursToSave = schedulingPrefs.is24x7
        ? (await import("@/lib/hoursUtils")).HOURS_24_7
        : businessHours;

      const selectedPlan = sessionStorage.getItem("selectedPlan") as PlanCode | null;
      const planCode: PlanCode = selectedPlan || "voice";

      // 1. Create tenant (idempotent: skip if already created on a previous attempt)
      let tenantId = createdTenantId;
      if (!tenantId) {
        const agencySlug = sessionStorage.getItem("referralAgencySlug") || undefined;
        const { data: createResult, error: createError } = await supabase.functions.invoke("create-tenant", {
          body: {
            name: businessName.trim(), business_mode: businessMode, timezone,
            hours_json: hoursToSave, industry: industrySlug, enabled_modules: enabledModules,
            capabilities_json: capabilitiesJson, hipaa_mode: businessMode === "medical",
            address: businessAddress || businessDetails.location || undefined, default_capacity: defaultCapacity,
            plan_code: planCode,
            agency_slug: agencySlug,
          },
        });
        if (createError) throw new Error(createError.message || "Failed to create business profile");
        if (createResult?.error) throw new Error(createResult.error);
        tenantId = createResult.tenant_id;
        if (!tenantId) throw new Error("No tenant ID returned");
        setCreatedTenantId(tenantId);
      }

      // 2. Services
      const config = resolveIndustryTemplate(industrySlug);
      const servicesToInsert = templateServices
        .filter(s => s.enabled && s.name.trim().length > 0)
        .map(s => ({
          tenant_id: tenantId, name: s.name, description: s.description || null,
          duration_minutes: s.duration, price_amount: s.price,
          price_type: (s.priceType || "fixed") as "fixed" | "starting_at" | "quote_only",
          is_active: true,
        }));
      if (servicesToInsert.length > 0) {
        const { error: svcErr } = await supabase.from("services").insert(servicesToInsert);
        if (svcErr) console.error("Onboarding step 2 (services):", svcErr.message);
      }

      // 3. FAQs
      const faqsToInsert = templateFAQs
        .filter(f => f.enabled && f.question.trim().length > 0 && f.answer.trim().length > 0)
        .map((faq, i) => ({ tenant_id: tenantId, question: faq.question, answer: faq.answer, priority_weight: i }));
      if (faqsToInsert.length > 0) {
        const { error: faqErr } = await supabase.from("business_faqs").insert(faqsToInsert);
        if (faqErr) console.error("Onboarding step 3 (FAQs):", faqErr.message);
      }

      // 4. Objections
      const objectionsToInsert = config.objections
        .filter(o => o.objection.trim().length > 0 && o.response.trim().length > 0)
        .map((obj, i) => ({ tenant_id: tenantId, objection: obj.objection, response: obj.response, priority_weight: i }));
      if (objectionsToInsert.length > 0) {
        const { error: objErr } = await supabase.from("objection_responses").insert(objectionsToInsert);
        if (objErr) console.error("Onboarding step 4 (objections):", objErr.message);
      }

      // 5. Policies
      await supabase.from("tenants").update({
        cancellation_policy: templatePolicies.cancellation || null,
        deposit_policy: templatePolicies.deposit || null,
        refund_policy: templatePolicies.refund || null,
      }).eq("id", tenantId);

      // 5b. Auto-apply rich industry template (best-effort merge to fill gaps)
      try {
        const richTemplate = getTemplate(industrySlug);
        if (richTemplate && tenantId) {
          const currentState = await fetchCurrentBrainState(tenantId);
          const preview = previewTemplateApplication(currentState, richTemplate, "merge");
          if (preview.totals.itemsToAdd > 0) {
            await applyTemplate(tenantId, richTemplate, "merge", preview);
          }
        }
      } catch (e) {
        console.error("Onboarding step 5b (template merge):", e);
      }

      // 6. Service area
      const showsCoverage = workStyle === "go_to_customer" || workStyle === "both" || ["dispatch", "food"].includes(businessMode);
      if (showsCoverage) {
        await supabase.from("tenants").update({
          service_area_json: {
            radius_miles: serviceArea.radiusMiles,
            zip_codes: serviceArea.zipCodes ? serviceArea.zipCodes.split(",").map(z => z.trim()).filter(Boolean) : [],
            out_of_area_message: serviceArea.outOfAreaMessage,
          },
        }).eq("id", tenantId);
      }

      // 7. Scenario flags + seeds
      await updateCapabilityFlags(tenantId, scenarioAnswers);
      await applyScenarioSeeds(tenantId, scenarioAnswers, businessMode);

      // 8. Food settings
      if (isFoodMode) {
        const { error: foodErr } = await supabase.from("food_order_settings").insert({
          tenant_id: tenantId, accepts_pickup: true,
          accepts_delivery: scenarioAnswers.offersDelivery ?? false,
          accepts_dine_in: true, accepts_catering: scenarioAnswers.offersCatering ?? false,
          order_confirmation_mode: "auto_confirm",
        });
        if (foodErr) console.error("Onboarding step 8 (food settings):", foodErr.message);
      }

      // 9. Automations
      const { error: autoErr } = await supabase.from("automations").insert([
        { tenant_id: tenantId, name: "Missed Call Follow-up", trigger: "missed_call" as const, is_enabled: true, steps_json: [{ type: "send_message", body: "Hi! We noticed we missed your call. How can we help you today?" }] },
        { tenant_id: tenantId, name: "Booking Confirmation", trigger: "booking_created" as const, is_enabled: true, steps_json: [{ type: "send_message", body: "Your appointment is confirmed! We'll see you soon." }] },
      ]);
      if (autoErr) console.error("Onboarding step 9 (automations):", autoErr.message);

      // 10. Communication / AI settings
      const mappedAfterHours = afterHours === "ai_24_7" ? undefined : afterHours === "voicemail" ? "voicemail" : "text_back";
      const commUpdate: Record<string, unknown> = {
        ai_booking_mode: bookingMode,
        missed_call_behavior: communicationPrefs.missedCallBehavior,
      };
      if (mappedAfterHours) commUpdate.off_behavior = mappedAfterHours;

      const settingsJson: Record<string, unknown> = {};
      settingsJson.ai_tone = aiTone;
      if (customGreeting) settingsJson.custom_greeting = customGreeting;
      if (notificationPhone) settingsJson.notification_phone = notificationPhone;
      if (communicationPrefs.aiGuardrails) settingsJson.ai_guardrails = communicationPrefs.aiGuardrails;
      if (communicationPrefs.requiredIntakeFields?.length) settingsJson.required_intake_fields = communicationPrefs.requiredIntakeFields;
      if (communicationPrefs.escalationRules) settingsJson.escalation_rules = communicationPrefs.escalationRules;
      commUpdate.settings_json = settingsJson;

      await supabase.from("assistant_settings").update(commUpdate).eq("tenant_id", tenantId);

      // AI assistant tone & greeting
      const assistantData: Record<string, unknown> = { tone: aiTone };
      if (customGreeting) assistantData.greeting_script = customGreeting;
      const { data: existingAssistant } = await supabase.from("ai_assistants").select("id").eq("tenant_id", tenantId).maybeSingle();
      if (existingAssistant) {
        await supabase.from("ai_assistants").update(assistantData).eq("tenant_id", tenantId);
      } else {
        await supabase.from("ai_assistants").insert({ tenant_id: tenantId, ...assistantData });
      }

      // 11. Team members
      if (!isSoloOperator && teamMembers.length > 0) {
        const teamData = teamMembers.filter(m => m.name.trim().length > 0).map(m => ({
          name: m.name.trim(), role: m.role, phone: m.phone || null,
          email: m.email || null, canPerformAllServices: m.canPerformAllServices,
          serviceNames: m.serviceNames,
        }));
        if (teamData.length > 0) {
          await supabase.from("tenants").update({
            capabilities_json: { ...(capabilitiesJson as Record<string, unknown>), _team_members: teamData } as unknown as import("@/integrations/supabase/types").Json,
          }).eq("id", tenantId);
        }
      }

      // 12. Pricing rules
      const pricingFromDetails: Record<string, unknown> = {};
      if (scenarioDetails.depositType) pricingFromDetails.deposit_type = scenarioDetails.depositType;
      if (scenarioDetails.depositAmount) pricingFromDetails.deposit_amount = Number(scenarioDetails.depositAmount);
      if (scenarioDetails.tripFeeAmount) pricingFromDetails.trip_fee = Number(scenarioDetails.tripFeeAmount);
      if (scenarioDetails.minimumChargeAmount) pricingFromDetails.minimum_charge = Number(scenarioDetails.minimumChargeAmount);
      if (scenarioDetails.afterHoursSurcharge) pricingFromDetails.after_hours_surcharge = Number(scenarioDetails.afterHoursSurcharge);
      if (scenarioDetails.baseRate) pricingFromDetails.base_rate = Number(scenarioDetails.baseRate);
      if (scenarioDetails.perMileRate) pricingFromDetails.per_mile_rate = Number(scenarioDetails.perMileRate);
      if (Object.keys(pricingFromDetails).length > 0) {
        await supabase.from("tenants").update({ pricing_rules_jsonb: pricingFromDetails as unknown as import("@/integrations/supabase/types").Json }).eq("id", tenantId);
      }

      // 13. Service area from details
      if (scenarioDetails.serviceRadiusMiles || scenarioDetails.deliveryRadiusMiles) {
        const currentRadius = Number(scenarioDetails.serviceRadiusMiles || scenarioDetails.deliveryRadiusMiles);
        if (currentRadius > 0) {
          await supabase.from("tenants").update({
            service_area_json: {
              radius_miles: currentRadius,
              zip_codes: serviceArea.zipCodes ? serviceArea.zipCodes.split(",").map(z => z.trim()).filter(Boolean) : [],
              out_of_area_message: serviceArea.outOfAreaMessage,
            },
          }).eq("id", tenantId);
        }
      }

      // 14. A2P registration
      if (a2pData.legalBusinessName || a2pData.ein || a2pData.entityType) {
        await supabase.from("a2p_registrations").upsert({
          tenant_id: tenantId, status: "pending_data",
          legal_business_name: a2pData.legalBusinessName || businessName,
          ein: a2pData.ein || null, entity_type: a2pData.entityType || null,
          street_address: a2pData.streetAddress || null, city: a2pData.city || null,
          state: a2pData.state || null, zip_code: a2pData.zipCode || null,
          contact_first_name: a2pData.contactFirstName || null,
          contact_last_name: a2pData.contactLastName || null,
          contact_email: a2pData.contactEmail || user?.email || null,
          contact_phone: null, website_url: a2pData.websiteUrl || null,
        }, { onConflict: "tenant_id" });
      }

      // 15. Twilio provisioning
      const voicePlans = ["voice", "both", "base-", "growth-", "scale-", "power-", "enterprise"];
      const shouldProvision = voicePlans.some(p => planCode.startsWith(p));
      if (shouldProvision && !isSuperAdmin) {
        try {
          const { data: provisionData, error: provisionError } = await supabase.functions.invoke("provision-twilio-number", {
            body: { tenant_id: tenantId, number_type: "local" },
          });
          if (!provisionError && provisionData?.success && provisionData.phone_number) {
            setProvisionedPhone(provisionData.phone_number);
          }
        } catch (e) { console.error("TwilioProvision: exception", e); }
      }

      // 16. Default workflows
      try {
        await createDefaultWorkflowsForMode(tenantId, (industryEntry?.businessMode || "service") as BusinessMode);
      } catch (e) { console.error("WorkflowsAutoCreate: exception", e); }

      // 17. Mark complete
      await supabase.from("tenants").update({ onboarding_completed_at: new Date().toISOString() }).eq("id", tenantId);
      sessionStorage.removeItem("selectedPlan");
      sessionStorage.removeItem("referralAgencySlug");
      await refreshTenant();
      await new Promise(r => setTimeout(r, 100));
      clearOnboardingData(userId);
      clearProgress();
      setIsComplete(true);
    } catch (error: unknown) {
      console.error("Onboarding error:", error);
      const errorInfo = formatErrorForToast(error);
      toast({ variant: "destructive", title: errorInfo.title, description: errorInfo.description });
      if (retryCount < MAX_RETRIES) {
        setShowRetry(true);
      } else {
        setShowRetry(false);
        setCompletionError("We're having trouble saving. Please refresh and try again, or contact support.");
      }
    } finally {
      setLoading(false);
    }
  }, [user, navigate, toast, refreshTenant, isSuperAdmin, retryCount, userId, createdTenantId]);

  const handleRetry = useCallback(async (params: SubmitParams, clearProgress: () => void) => {
    if (retryCount >= MAX_RETRIES) {
      setCompletionError("We're having trouble saving. Please refresh and try again, or contact support.");
      return;
    }
    setLoading(true);
    setCompletionError(null);
    await new Promise(r => setTimeout(r, Math.pow(2, retryCount) * 1000));
    setRetryCount(prev => prev + 1);
    handleComplete(params, clearProgress);
  }, [retryCount, handleComplete]);

  return {
    loading,
    isComplete,
    provisionedPhone,
    retryCount,
    showRetry,
    completionError,
    handleComplete,
    handleRetry,
    MAX_RETRIES,
  };
}

import { useState, useCallback, useRef } from "react";

export interface FieldError {
  field: string;
  message: string;
}

export interface StepValidationResult {
  isValid: boolean;
  errors: FieldError[];
}

const EMAIL_REGEX = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;
const PHONE_REGEX = /^[\d\s()+-]{7,20}$/;

export function validateIdentityStep(
  businessName: string,
  industrySlug: string,
  businessDetails?: { location?: string },
): StepValidationResult {
  const errors: FieldError[] = [];

  if (!businessName.trim()) {
    errors.push({ field: "business-name", message: "Business name is required" });
  } else if (businessName.trim().length < 2) {
    errors.push({ field: "business-name", message: "Business name must be at least 2 characters" });
  }

  if (!industrySlug) {
    errors.push({ field: "industry-selector", message: "Please select your industry" });
  }

  return { isValid: errors.length === 0, errors };
}

export function validateServicesStep(services: Array<{ enabled: boolean; name: string }>): StepValidationResult {
  const errors: FieldError[] = [];
  const hasEnabledService = services.some(s => s.enabled && s.name.trim().length > 0);
  if (!hasEnabledService) {
    errors.push({ field: "services-list", message: "Please select at least one service" });
  }
  return { isValid: errors.length === 0, errors };
}

export function useOnboardingValidation() {
  const [fieldErrors, setFieldErrors] = useState<FieldError[]>([]);
  const [hasAttemptedSubmit, setHasAttemptedSubmit] = useState(false);

  const scrollToFirstError = useCallback((errors: FieldError[]) => {
    if (errors.length === 0) return;
    const firstField = errors[0].field;
    // Try to find by id, then by data-field
    const el =
      document.getElementById(firstField) ||
      document.querySelector(`[data-field="${firstField}"]`);
    if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "center" });
      // Try to focus if it's an input
      if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement || el instanceof HTMLSelectElement) {
        setTimeout(() => el.focus(), 300);
      }
    }
  }, []);

  const validateStep = useCallback(
    (
      stepId: string,
      data: {
        businessName?: string;
        industrySlug?: string;
        businessDetails?: { location?: string };
        templateServices?: Array<{ enabled: boolean; name: string }>;
      }
    ): boolean => {
      setHasAttemptedSubmit(true);
      let result: StepValidationResult = { isValid: true, errors: [] };

      switch (stepId) {
        case "identity":
          result = validateIdentityStep(
            data.businessName || "",
            data.industrySlug || "",
            data.businessDetails,
          );
          break;
        case "services-preview":
          result = validateServicesStep(data.templateServices || []);
          break;
        // Other steps always pass (scheduling, team, communication, confirm)
        default:
          result = { isValid: true, errors: [] };
      }

      setFieldErrors(result.errors);
      if (!result.isValid) {
        scrollToFirstError(result.errors);
      }
      return result.isValid;
    },
    [scrollToFirstError]
  );

  const getFieldError = useCallback(
    (fieldId: string): string | undefined => {
      if (!hasAttemptedSubmit) return undefined;
      return fieldErrors.find(e => e.field === fieldId)?.message;
    },
    [fieldErrors, hasAttemptedSubmit]
  );

  const clearErrors = useCallback(() => {
    setFieldErrors([]);
    setHasAttemptedSubmit(false);
  }, []);

  return {
    fieldErrors,
    hasAttemptedSubmit,
    validateStep,
    getFieldError,
    clearErrors,
  };
}

/**
 * useOrderMutations — extracted CRUD mutations for food_orders.
 *
 * Replaces inline mutations scattered across OrdersPage and OrderDetailsDrawer.
 */
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";
import type { Database } from "@/integrations/supabase/types";

type OrderStatus = Database["public"]["Enums"]["order_status"];

export interface OrderMutationInput {
  orderId: string;
  status: OrderStatus;
}

export function useOrderMutations() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const invalidate = () => {
    queryClient.invalidateQueries({ queryKey: ["food-orders", tenant?.id] });
  };

  /** Update order status (the most common operation) */
  const updateStatus = useMutation({
    mutationFn: async ({ orderId, status }: OrderMutationInput) => {
      const updates: Record<string, unknown> = { status };
      // Auto-set timestamps for terminal states
      if (status === "completed" || status === "cancelled") {
        updates.completed_at = new Date().toISOString();
      }
      const { error } = await supabase
        .from("food_orders")
        .update(updates)
        .eq("id", orderId);
      if (error) throw error;
    },
    onSuccess: (_, { status }) => {
      invalidate();
      const label = STATUS_LABELS[status] || status;
      toast({ title: `Order ${label.toLowerCase()}` });
    },
    onError: (error) => {
      toast({ title: "Failed to update order", description: String(error), variant: "destructive" });
    },
  });

  /** Cancel an order with optional reason */
  const cancelOrder = useMutation({
    mutationFn: async ({ orderId, reason }: { orderId: string; reason?: string }) => {
      const updates: Record<string, unknown> = {
        status: "cancelled" as OrderStatus,
        completed_at: new Date().toISOString(),
      };
      if (reason) {
        updates.special_instructions = reason;
      }
      const { error } = await supabase
        .from("food_orders")
        .update(updates)
        .eq("id", orderId);
      if (error) throw error;
    },
    onSuccess: () => {
      invalidate();
      toast({ title: "Order cancelled" });
    },
    onError: (error) => {
      toast({ title: "Failed to cancel order", description: String(error), variant: "destructive" });
    },
  });

  /** Create a new order */
  const createOrder = useMutation({
    mutationFn: async (data: {
      customer_name: string;
      customer_phone?: string;
      order_type: string;
      items_json: unknown[];
      special_instructions?: string;
    }) => {
      if (!tenant?.id) throw new Error("No tenant");
      const orderNum = `ORD-${Date.now().toString(36).toUpperCase()}`;
      const { data: order, error } = await (supabase as any)
        .from("food_orders")
        .insert({
          tenant_id: tenant.id,
          order_number: orderNum,
          customer_name: data.customer_name,
          customer_phone: data.customer_phone || null,
          order_type: data.order_type,
          items_json: data.items_json as any,
          special_instructions: data.special_instructions || null,
          status: "pending",
        })
        .select()
        .single();
      if (error) throw error;
      return order;
    },
    onSuccess: () => {
      invalidate();
      toast({ title: "Order created" });
    },
    onError: (error) => {
      toast({ title: "Failed to create order", description: String(error), variant: "destructive" });
    },
  });

  /** Retry handoff (notification delivery) for an order */
  const retryHandoff = useMutation({
    mutationFn: async (orderId: string) => {
      const { data, error } = await supabase.functions.invoke("order-handoff", {
        body: { order_id: orderId, tenant_id: tenant?.id },
      });
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      invalidate();
      toast({ title: "Handoff retried" });
    },
    onError: (error) => {
      toast({ title: "Handoff retry failed", description: String(error), variant: "destructive" });
    },
  });

  /** Mark an order as paid */
  const markPaid = useMutation({
    mutationFn: async ({ orderId, paymentMethod }: { orderId: string; paymentMethod?: string }) => {
      const { error } = await supabase
        .from("food_orders")
        .update({
          payment_status: "paid",
          payment_method: paymentMethod || "cash",
        } as any)
        .eq("id", orderId);
      if (error) throw error;
    },
    onSuccess: () => {
      invalidate();
      toast({ title: "Marked as paid" });
    },
    onError: (error) => {
      toast({ title: "Failed to mark as paid", description: String(error), variant: "destructive" });
    },
  });

  return {
    updateStatus,
    cancelOrder,
    createOrder,
    retryHandoff,
    markPaid,
  };
}

const STATUS_LABELS: Record<string, string> = {
  pending: "Pending",
  confirmed: "Confirmed",
  preparing: "Preparing",
  ready: "Ready",
  out_for_delivery: "Out for Delivery",
  completed: "Completed",
  cancelled: "Cancelled",
};

/**
 * usePartnerAnalysis — React Query hook for AI-generated business analysis
 *
 * Fetches cached analysis from the partner-analysis edge function.
 * Supports manual refresh with rate limiting (3/day).
 */

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";
import type { PartnerAnalysis, PartnerAnalysisResponse } from "@/types/partnerAnalysis";

async function fetchAnalysis(
  tenantId: string,
  forceRefresh: boolean
): Promise<PartnerAnalysisResponse> {
  const { data, error } = await supabase.functions.invoke("partner-analysis", {
    body: { tenant_id: tenantId, force_refresh: forceRefresh },
  });

  if (error) {
    throw new Error(error.message || "Failed to fetch analysis");
  }

  return data as PartnerAnalysisResponse;
}

export function usePartnerAnalysis() {
  const { tenant } = useAuth();
  const tenantId = tenant?.id;
  const queryClient = useQueryClient();

  const queryKey = ["partner-analysis", tenantId];

  const query = useQuery<PartnerAnalysisResponse>({
    queryKey,
    queryFn: () => fetchAnalysis(tenantId!, false),
    enabled: !!tenantId,
    staleTime: 5 * 60 * 1000, // 5 min React Query cache
    retry: 1,
  });

  const refreshMutation = useMutation({
    mutationFn: () => fetchAnalysis(tenantId!, true),
    onSuccess: (data) => {
      queryClient.setQueryData(queryKey, data);
      toast.success("Analysis refreshed");
    },
    onError: (err: Error) => {
      if (err.message?.includes("429") || err.message?.includes("refresh limit")) {
        toast.error("Daily refresh limit reached. Try again tomorrow.");
      } else {
        toast.error("Failed to refresh analysis");
      }
    },
  });

  const refreshCountToday = query.data?.refresh_count_today ?? 0;
  const maxRefreshes = query.data?.max_refreshes_per_day ?? 3;

  return {
    analysis: query.data?.analysis ?? null,
    isLoading: query.isLoading,
    isRefreshing: refreshMutation.isPending,
    generatedAt: query.data?.generated_at ?? null,
    isCached: query.data?.is_cached ?? false,
    error: query.error ?? null,
    refresh: () => refreshMutation.mutate(),
    canRefresh: refreshCountToday < maxRefreshes,
    refreshCountToday,
    maxRefreshes,
  };
}

import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { supabase } from "@/integrations/supabase/client";
import { getIndustryRevenueConfig, type HeroIconName } from "@/config/industryRevenueConfig";
import { getLadderStep, mapLegacyToNewSku } from "@/config/pricing";
import { calculateROI, percentChange } from "@/lib/revenueUtils";
import { startOfMonth, endOfMonth, subMonths } from "date-fns";

export interface ROIDashboardData {
  // Current month
  aiRevenueCents: number;
  entitiesCreated: number;
  totalCalls: number;
  conversionRate: number;
  subscriptionCostCents: number;
  roiMultiplier: number;

  // Previous month (for trends)
  previousMonth: {
    aiRevenueCents: number;
    entitiesCreated: number;
    totalCalls: number;
    conversionRate: number;
  } | null;

  // Trends (percentage change)
  trends: {
    revenue: number;
    entities: number;
    calls: number;
    conversion: number;
  };

  // Industry config for UI
  entityName: string;
  entityNameSingular: string;
  actionVerbPast: string;
  emptyStateMessage: string;
  emptyStateCta: string;
  successMessage: string;

  // Story-driven UI config
  storyTemplate: string;
  callsLabel: string;
  heroIcon: HeroIconName;
  celebratoryTone: boolean;
  emptyStateSteps: [string, string, string];
  emptyStateEncouragement: string;

  // State
  hasData: boolean;
}

// Mode-specific empty state configuration
interface ModeEmptyStateConfig {
  steps: [string, string, string];
  encouragement: string;
}

const MODE_EMPTY_STATES: Record<string, ModeEmptyStateConfig> = {
  service: {
    steps: ["Add your services & pricing", "Connect your phone", "Book appointments via AI"],
    encouragement: "Your AI is ready to book appointments and answer questions 24/7.",
  },
  dispatch: {
    steps: ["Add service types & rates", "Connect your phone", "Dispatch jobs via AI calls"],
    encouragement: "Your AI is ready to dispatch jobs and provide ETAs around the clock.",
  },
  food: {
    steps: ["Add your menu items", "Configure order settings", "Take orders via AI calls"],
    encouragement: "Your AI is ready to take orders, reservations, and answer menu questions.",
  },
  medical: {
    steps: ["Add services & visit types", "Configure patient intake", "Schedule patients via AI"],
    encouragement: "Your AI is ready to schedule appointments and handle patient inquiries securely.",
  },
  general: {
    steps: ["Add your offerings", "Connect your phone", "Capture leads via AI calls"],
    encouragement: "Your AI is ready to answer calls and capture leads for your business.",
  },
};

async function fetchMonthStats(tenantId: string, monthStart: string, monthEnd: string) {
  // Fetch AI-attributed entities for this month
  const { data: attributions, error: attrError } = await supabase
    .from("revenue_attributions" as any)
    .select("revenue_cents, status")
    .eq("tenant_id", tenantId)
    .eq("source_type", "ai_call")
    .gte("attributed_at", monthStart)
    .lte("attributed_at", monthEnd);

  if (attrError) throw attrError;

  // Fetch total calls for this month
  const { count: totalCalls, error: callsError } = await supabase
    .from("ai_call_sessions")
    .select("*", { count: "exact", head: true })
    .eq("tenant_id", tenantId)
    .gte("started_at", monthStart)
    .lte("started_at", monthEnd);

  if (callsError) throw callsError;

  const items = (attributions as any[]) || [];
  const activeItems = items.filter((a) => a.status !== "cancelled");
  const aiRevenueCents = activeItems.reduce((sum: number, a: any) => sum + (a.revenue_cents || 0), 0);
  const entitiesCreated = activeItems.length;
  const calls = totalCalls || 0;
  const conversionRate = calls > 0 ? (entitiesCreated / calls) * 100 : 0;

  return { aiRevenueCents, entitiesCreated, totalCalls: calls, conversionRate };
}

export function useROIDashboard() {
  const { tenant, subscription } = useAuth();
  const { businessMode } = useTenantConfig();
  const config = getIndustryRevenueConfig(businessMode);

  // Get mode-specific empty state config
  const modeEmptyState = MODE_EMPTY_STATES[businessMode] || MODE_EMPTY_STATES.general;

  const query = useQuery({
    queryKey: ["roi-dashboard", tenant?.id, businessMode],
    queryFn: async (): Promise<ROIDashboardData> => {
      if (!tenant?.id) throw new Error("No tenant");

      const now = new Date();
      const currentMonthStart = startOfMonth(now).toISOString();
      const currentMonthEnd = endOfMonth(now).toISOString();

      const prevMonth = subMonths(now, 1);
      const prevMonthStart = startOfMonth(prevMonth).toISOString();
      const prevMonthEnd = endOfMonth(prevMonth).toISOString();

      // Fetch current and previous month in parallel
      const [current, previous] = await Promise.all([
        fetchMonthStats(tenant.id, currentMonthStart, currentMonthEnd),
        fetchMonthStats(tenant.id, prevMonthStart, prevMonthEnd),
      ]);

      // Get subscription cost
      let subscriptionCostCents = 24900; // Default $249

      // Check for manual override
      const { data: revenueSettings } = await supabase
        .from("tenant_revenue_settings" as any)
        .select("subscription_cost_override_cents")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if ((revenueSettings as any)?.subscription_cost_override_cents) {
        subscriptionCostCents = (revenueSettings as any).subscription_cost_override_cents;
      } else if (subscription) {
        // Derive from plan_code
        const planCode = (subscription as any).plan_code;
        if (planCode) {
          const mappedSku = mapLegacyToNewSku(planCode);
          const step = getLadderStep(mappedSku);
          if (step && step.price > 0) {
            subscriptionCostCents = step.price * 100;
          }
        }
      }

      const roiMultiplier = calculateROI(current.aiRevenueCents, subscriptionCostCents);

      const hasPrevData = previous.totalCalls > 0;

      return {
        ...current,
        subscriptionCostCents,
        roiMultiplier,
        previousMonth: hasPrevData ? previous : null,
        trends: {
          revenue: hasPrevData ? percentChange(current.aiRevenueCents, previous.aiRevenueCents) : 0,
          entities: hasPrevData ? percentChange(current.entitiesCreated, previous.entitiesCreated) : 0,
          calls: hasPrevData ? percentChange(current.totalCalls, previous.totalCalls) : 0,
          conversion: hasPrevData ? percentChange(current.conversionRate, previous.conversionRate) : 0,
        },
        entityName: config.entityName,
        entityNameSingular: config.entityNameSingular,
        actionVerbPast: config.actionVerbPast,
        emptyStateMessage: config.emptyStateMessage,
        emptyStateCta: config.emptyStateCta,
        successMessage: config.successMessage,
        storyTemplate: config.storyTemplate,
        callsLabel: config.callsLabel,
        heroIcon: config.heroIcon,
        celebratoryTone: config.celebratoryTone,
        // Use mode-specific empty state config instead of generic config
        emptyStateSteps: modeEmptyState.steps,
        emptyStateEncouragement: modeEmptyState.encouragement,
        hasData: current.totalCalls > 0 || current.entitiesCreated > 0,
      };
    },
    enabled: !!tenant?.id,
    refetchInterval: 60000, // Refresh every minute
  });

  return {
    data: query.data ?? null,
    isLoading: query.isLoading,
    error: query.error,
    refetch: query.refetch,
  };
}

import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { supabase } from "@/integrations/supabase/client";
import { getIndustryRevenueConfig, type HeroIconName } from "@/config/industryRevenueConfig";
import { getLadderStep, mapLegacyToNewSku } from "@/config/pricing";
import { startOfMonth, endOfMonth, subMonths, format } from "date-fns";

export type DateRangeOption = "this_month" | "last_month" | "last_3_months" | "last_6_months";

export interface MonthlyDataPoint {
  month: string; // "2026-02"
  monthLabel: string; // "Feb"
  aiRevenueCents: number;
  manualRevenueCents: number;
  totalRevenueCents: number;
  entitiesCreated: number;
  totalCalls: number;
  conversionRate: number;
}

export interface ConversionFunnel {
  totalCalls: number;
  callsWithOutcome: number;
  entitiesCreated: number;
  entitiesCompleted: number;
}

export interface RevenueByServiceItem {
  serviceName: string;
  revenueCents: number;
  count: number;
}

export interface ROIReportData {
  // Summary for selected range
  aiRevenueCents: number;
  totalRevenueCents: number;
  totalCalls: number;
  entitiesCreated: number;
  conversionRate: number;
  roiMultiplier: number;
  subscriptionCostCents: number;

  // Lead recovery stats
  leadsRecovered: number;
  recoveredRevenueCents: number;
  recoveryRate: number;
  totalRecoveryCampaigns: number;

  // Trends vs previous period
  trends: {
    revenue: number;
    calls: number;
    entities: number;
    conversion: number;
  };

  // Chart data
  monthlyData: MonthlyDataPoint[];
  revenueBySource: { ai: number; manual: number; recovery: number };
  revenueByService: RevenueByServiceItem[];
  conversionFunnel: ConversionFunnel;

  // Config
  entityName: string;
  entityNameSingular: string;
  actionVerbPast: string;

  // Story-driven UI config
  storyTemplate: string;
  callsLabel: string;
  heroIcon: HeroIconName;
  celebratoryTone: boolean;
  emptyStateSteps: [string, string, string];
  emptyStateEncouragement: string;
  funnelLabels: [string, string, string, string];
}

function getMonthRange(option: DateRangeOption): { start: Date; end: Date; months: number } {
  const now = new Date();
  const end = endOfMonth(now);

  switch (option) {
    case "last_month": {
      const prev = subMonths(now, 1);
      return { start: startOfMonth(prev), end: endOfMonth(prev), months: 1 };
    }
    case "last_3_months":
      return { start: startOfMonth(subMonths(now, 2)), end, months: 3 };
    case "last_6_months":
      return { start: startOfMonth(subMonths(now, 5)), end, months: 6 };
    case "this_month":
    default:
      return { start: startOfMonth(now), end, months: 1 };
  }
}

export function useROIReport(dateRange: DateRangeOption = "this_month") {
  const { tenant, subscription } = useAuth();
  const { businessMode } = useTenantConfig();
  const config = getIndustryRevenueConfig(businessMode);

  const query = useQuery({
    queryKey: ["roi-report", tenant?.id, dateRange, businessMode],
    queryFn: async (): Promise<ROIReportData> => {
      if (!tenant?.id) throw new Error("No tenant");

      const { start, end, months } = getMonthRange(dateRange);
      const startStr = start.toISOString();
      const endStr = end.toISOString();

      // Fetch all attributions in range
      const { data: attributions, error: attrErr } = await supabase
        .from("revenue_attributions" as any)
        .select("revenue_cents, source_type, status, attributed_at")
        .eq("tenant_id", tenant.id)
        .gte("attributed_at", startStr)
        .lte("attributed_at", endStr);

      if (attrErr) throw attrErr;

      // Fetch all calls in range
      const { data: sessions, error: sessErr } = await supabase
        .from("ai_call_sessions")
        .select("started_at, outcome")
        .eq("tenant_id", tenant.id)
        .gte("started_at", startStr)
        .lte("started_at", endStr);

      if (sessErr) throw sessErr;

      const items = (attributions as any[]) || [];
      const calls = sessions || [];

      // Active (non-cancelled) attributions
      const active = items.filter((a) => a.status !== "cancelled");
      const aiItems = active.filter((a) => a.source_type === "ai_call");
      const recoveryItems = active.filter((a) => a.source_type === "lead_recovery");
      const manualItems = active.filter((a) => a.source_type !== "ai_call" && a.source_type !== "lead_recovery");

      const aiRevenueCents = aiItems.reduce((s: number, a: any) => s + (a.revenue_cents || 0), 0);
      const recoveryRevenueCents = recoveryItems.reduce((s: number, a: any) => s + (a.revenue_cents || 0), 0);
      const manualRevenueCents = manualItems.reduce((s: number, a: any) => s + (a.revenue_cents || 0), 0);
      const totalRevenueCents = aiRevenueCents + recoveryRevenueCents + manualRevenueCents;

      const totalCalls = calls.length;
      const callsWithOutcome = calls.filter((c) => c.outcome && c.outcome !== "lost").length;
      const entitiesCreated = aiItems.length;
      const entitiesCompleted = aiItems.filter((a) => a.status === "completed").length;
      const conversionRate = totalCalls > 0 ? (entitiesCreated / totalCalls) * 100 : 0;

      // Fetch lead recovery campaign stats
      const { data: recoveryCampaigns } = await supabase
        .from("lead_recovery_campaigns")
        .select("id, recovered_value_cents, status")
        .eq("tenant_id", tenant.id)
        .gte("created_at", startStr)
        .lte("created_at", endStr);

      const allCampaigns = (recoveryCampaigns as any[]) || [];
      const convertedCampaigns = allCampaigns.filter((c) => c.status === "converted");
      const leadsRecovered = convertedCampaigns.length;
      const recoveredRevenueCentsFromCampaigns = convertedCampaigns.reduce(
        (s: number, c: any) => s + (c.recovered_value_cents || 0),
        0
      );
      const totalRecoveryCampaigns = allCampaigns.length;
      const recoveryRate = totalRecoveryCampaigns > 0 ? (leadsRecovered / totalRecoveryCampaigns) * 100 : 0;

      // Subscription cost
      let subscriptionCostCents = 24900;
      const { data: revSettings } = await supabase
        .from("tenant_revenue_settings" as any)
        .select("subscription_cost_override_cents")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if ((revSettings as any)?.subscription_cost_override_cents) {
        subscriptionCostCents = (revSettings as any).subscription_cost_override_cents;
      } else if (subscription) {
        const planCode = (subscription as any).plan_code;
        if (planCode) {
          const step = getLadderStep(mapLegacyToNewSku(planCode));
          if (step && step.price > 0) subscriptionCostCents = step.price * 100;
        }
      }

      const totalCostCents = subscriptionCostCents * months;
      const roiMultiplier = totalCostCents > 0 ? Math.round((aiRevenueCents / totalCostCents) * 10) / 10 : 0;

      // Revenue by service type — join bookings → services for AI-attributed revenue
      const revenueByService: RevenueByServiceItem[] = [];
      try {
        const { data: bookingsWithService } = await supabase
          .from("bookings")
          .select("id, service_id, services(name, price_amount)")
          .eq("tenant_id", tenant.id)
          .gte("start_at", startStr)
          .lte("start_at", endStr)
          .in("status", ["confirmed", "completed", "pending"]);

        if (bookingsWithService && bookingsWithService.length > 0) {
          const serviceMap = new Map<string, { name: string; revenueCents: number; count: number }>();
          for (const b of bookingsWithService as any[]) {
            const svc = b.services;
            const name = svc?.name || "Unknown Service";
            const rev = (svc?.price_amount || 0) * 100; // price_amount is in dollars
            const existing = serviceMap.get(name);
            if (existing) {
              existing.revenueCents += rev;
              existing.count++;
            } else {
              serviceMap.set(name, { name, revenueCents: rev, count: 1 });
            }
          }
          // Sort by revenue descending
          const sorted = Array.from(serviceMap.values()).sort((a, b) => b.revenueCents - a.revenueCents);
          for (const s of sorted) {
            revenueByService.push({ serviceName: s.name, revenueCents: s.revenueCents, count: s.count });
          }
        }
      } catch (err) {
        console.error("Error fetching revenue by service:", err);
      }

      // Build monthly data points
      const monthlyData: MonthlyDataPoint[] = [];
      for (let i = months - 1; i >= 0; i--) {
        const m = subMonths(new Date(), i);
        const mStart = startOfMonth(m);
        const mEnd = endOfMonth(m);
        const mKey = format(mStart, "yyyy-MM");
        const mLabel = format(mStart, "MMM");

        const mAttr = active.filter((a) => {
          const d = new Date(a.attributed_at);
          return d >= mStart && d <= mEnd;
        });
        const mAi = mAttr.filter((a) => a.source_type === "ai_call");
        const mManual = mAttr.filter((a) => a.source_type !== "ai_call");
        const mCalls = calls.filter((c) => {
          const d = new Date(c.started_at);
          return d >= mStart && d <= mEnd;
        });

        const aiRev = mAi.reduce((s: number, a: any) => s + (a.revenue_cents || 0), 0);
        const manualRev = mManual.reduce((s: number, a: any) => s + (a.revenue_cents || 0), 0);

        monthlyData.push({
          month: mKey,
          monthLabel: mLabel,
          aiRevenueCents: aiRev,
          manualRevenueCents: manualRev,
          totalRevenueCents: aiRev + manualRev,
          entitiesCreated: mAi.length,
          totalCalls: mCalls.length,
          conversionRate: mCalls.length > 0 ? (mAi.length / mCalls.length) * 100 : 0,
        });
      }

      // Trends: compare first half to second half of range, or current vs previous period
      let trends = { revenue: 0, calls: 0, entities: 0, conversion: 0 };
      if (months === 1 && dateRange === "this_month") {
        // Compare to last month
        const prevStart = startOfMonth(subMonths(new Date(), 1)).toISOString();
        const prevEnd = endOfMonth(subMonths(new Date(), 1)).toISOString();

        const { data: prevAttr } = await supabase
          .from("revenue_attributions" as any)
          .select("revenue_cents, status")
          .eq("tenant_id", tenant.id)
          .eq("source_type", "ai_call")
          .gte("attributed_at", prevStart)
          .lte("attributed_at", prevEnd);

        const { count: prevCalls } = await supabase
          .from("ai_call_sessions")
          .select("*", { count: "exact", head: true })
          .eq("tenant_id", tenant.id)
          .gte("started_at", prevStart)
          .lte("started_at", prevEnd);

        const prevActive = ((prevAttr as any[]) || []).filter((a) => a.status !== "cancelled");
        const prevRev = prevActive.reduce((s: number, a: any) => s + (a.revenue_cents || 0), 0);
        const prevEntities = prevActive.length;
        const pc = prevCalls || 0;
        const prevConv = pc > 0 ? (prevEntities / pc) * 100 : 0;

        const pctChange = (curr: number, prev: number) => prev === 0 ? (curr > 0 ? 100 : 0) : ((curr - prev) / prev) * 100;

        trends = {
          revenue: pctChange(aiRevenueCents, prevRev),
          calls: pctChange(totalCalls, pc),
          entities: pctChange(entitiesCreated, prevEntities),
          conversion: pctChange(conversionRate, prevConv),
        };
      }

      return {
        aiRevenueCents,
        totalRevenueCents,
        totalCalls,
        entitiesCreated,
        conversionRate,
        roiMultiplier,
        subscriptionCostCents: totalCostCents,

        // Lead recovery stats
        leadsRecovered,
        recoveredRevenueCents: recoveredRevenueCentsFromCampaigns,
        recoveryRate,
        totalRecoveryCampaigns,

        trends,
        monthlyData,
        revenueBySource: { ai: aiRevenueCents, manual: manualRevenueCents, recovery: recoveryRevenueCents },
        revenueByService,
        conversionFunnel: {
          totalCalls,
          callsWithOutcome,
          entitiesCreated,
          entitiesCompleted,
        },
        entityName: config.entityName,
        entityNameSingular: config.entityNameSingular,
        actionVerbPast: config.actionVerbPast,
        storyTemplate: config.storyTemplate,
        callsLabel: config.callsLabel,
        heroIcon: config.heroIcon,
        celebratoryTone: config.celebratoryTone,
        emptyStateSteps: config.emptyStateSteps,
        emptyStateEncouragement: config.emptyStateEncouragement,
        funnelLabels: config.funnelLabels,
      };
    },
    enabled: !!tenant?.id,
  });

  return {
    data: query.data ?? null,
    isLoading: query.isLoading,
    error: query.error,
    refetch: query.refetch,
  };
}

