import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import {
  getLadderStep,
  hasVoiceFeature,
  hasSmsFeature,
  mapLegacyToNewSku,
  type PlanSku,
} from "@/config/pricing";
import type { Subscription, AssistantSettings } from "@/types/database";

interface UseSubscriptionResult {
  subscription: Subscription | null;
  assistantSettings: AssistantSettings | null;
  loading: boolean;
  error: string | null;
  hasActiveSubscription: boolean;
  canAccessApp: boolean;
  planSku: PlanSku | null;
  hasVoice: boolean;
  hasSms: boolean;
  createSubscription: (sku: PlanSku, additionalLocations?: number) => Promise<void>;
  refetch: () => Promise<void>;
}

export function useSubscription(tenantId: string | null, isSuperAdmin: boolean = false): UseSubscriptionResult {
  const [subscription, setSubscription] = useState<Subscription | null>(null);
  const [assistantSettings, setAssistantSettings] = useState<AssistantSettings | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchData = useCallback(async () => {
    if (!tenantId) {
      setSubscription(null);
      setAssistantSettings(null);
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);

    try {
      // Fetch subscription
      const { data: subData, error: subError } = await supabase
        .from("subscriptions")
        .select("*")
        .eq("tenant_id", tenantId)
        .maybeSingle();

      if (subError) throw subError;
      setSubscription(subData);

      // Fetch assistant settings
      const { data: settingsData, error: settingsError } = await supabase
        .from("assistant_settings")
        .select("*")
        .eq("tenant_id", tenantId)
        .maybeSingle();

      if (settingsError) throw settingsError;
      setAssistantSettings(settingsData);
    } catch (err: any) {
      console.error("Failed to fetch subscription data:", err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [tenantId]);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  const hasActiveSubscription = subscription?.status === "active" || subscription?.status === "trialing";
  
  // Users can access app if they have active subscription
  const canAccessApp = hasActiveSubscription;

  // Get the plan SKU (handle both new SKUs and legacy plan codes)
  const rawPlanCode = subscription?.plan_code || null;
  const planSku = rawPlanCode ? mapLegacyToNewSku(rawPlanCode) : null;
  const hasVoice = hasVoiceFeature(planSku);
  const hasSms = hasSmsFeature(planSku);

  const createSubscription = async (sku: PlanSku, additionalLocations: number = 0) => {
    if (!tenantId) throw new Error("No tenant ID");

    // Get the ladder step details for usage limits
    const step = getLadderStep(sku);
    if (!step) throw new Error("Invalid plan SKU");

    // Check for existing subscription first
    const { data: existingSub } = await supabase
      .from("subscriptions")
      .select("id")
      .eq("tenant_id", tenantId)
      .maybeSingle();

    if (existingSub) {
      // Update existing subscription
      const { error: updateError } = await supabase
        .from("subscriptions")
        .update({
          plan_code: sku as string, // Cast to string for DB compatibility
          status: "active",
          current_period_end: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
          included_minutes: step.includedMinutes,
          included_sms_segments: step.includedSmsSegments,
          overage_minute_rate_cents: step.overageMinuteRate ? Math.round(step.overageMinuteRate * 100) : null,
          overage_sms_rate_cents: Math.round((step.overageSmsRate || 0) * 100),
        } as any)
        .eq("id", existingSub.id);

      if (updateError) throw updateError;
    } else {
      // Create new subscription with active status (requires payment)
      const { error: subError } = await supabase
        .from("subscriptions")
        .insert({
          tenant_id: tenantId,
          plan_code: sku as string, // Cast to string for DB compatibility
          status: "active",
          current_period_end: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
          included_minutes: step.includedMinutes,
          included_sms_segments: step.includedSmsSegments,
          overage_minute_rate_cents: step.overageMinuteRate ? Math.round(step.overageMinuteRate * 100) : null,
          overage_sms_rate_cents: Math.round((step.overageSmsRate || 0) * 100),
        } as any);

      if (subError) throw subError;
    }

    // Store additional locations in tenant metadata (for billing display)
    if (additionalLocations > 0) {
      await supabase
        .from("tenants")
        .update({ 
          // Store in existing metadata field or a suitable column
          // For now, we'll just log this - actual location management would need schema support
        })
        .eq("id", tenantId);
    }

    // Initialize assistant settings based on SKU
    try {
      const { error: settingsError } = await supabase.rpc("initialize_assistant_settings", {
        _tenant_id: tenantId,
        _plan_code: sku as string,
      } as any);

      if (settingsError) {
        console.error("Failed to initialize assistant settings:", settingsError);
      }
    } catch (err) {
      console.error("Error initializing assistant settings:", err);
    }

    // Initialize usage tracking for this billing period
    const periodStart = new Date();
    const periodEnd = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000); // 30 days
    
    // Check for existing usage record first
    const { data: existingUsage } = await supabase
      .from("subscription_usage")
      .select("id")
      .eq("tenant_id", tenantId)
      .maybeSingle();

    if (!existingUsage) {
      await supabase
        .from("subscription_usage")
        .insert({
          tenant_id: tenantId,
          billing_period_start: periodStart.toISOString(),
          billing_period_end: periodEnd.toISOString(),
          voice_minutes_used: 0,
          sms_segments_used: 0,
        });
    }

    // Provision Twilio number for voice plans (skip for super admin test tenants)
    if (hasVoiceFeature(sku) && !isSuperAdmin) {
      try {
        console.log("Provisioning Twilio number for voice plan...");
        const { data, error: provisionError } = await supabase.functions.invoke("provision-twilio-number", {
          body: { tenant_id: tenantId, number_type: "local" },
        });
        
        if (provisionError) {
          console.error("Failed to provision number:", provisionError);
        } else if (data?.success) {
          console.log("Provisioned number:", data.phone_number);
        } else {
          console.error("Provisioning failed:", data?.error);
        }
      } catch (err) {
        console.error("Error calling provision function:", err);
        // Don't fail subscription creation if provisioning fails
      }
    }

    // Mark onboarding as complete
    await supabase
      .from("tenants")
      .update({ onboarding_completed_at: new Date().toISOString() })
      .eq("id", tenantId);

    await fetchData();
  };

  return {
    subscription,
    assistantSettings,
    loading,
    error,
    hasActiveSubscription,
    canAccessApp,
    planSku,
    hasVoice,
    hasSms,
    createSubscription,
    refetch: fetchData,
  };
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";

export interface TekmetricShop {
  id: string | number;
  name: string;
  phone?: string;
  address?: string;
}

export interface TekmetricIntegration {
  id: string;
  is_active: boolean;
  last_synced_at: string | null;
  config_json: {
    shops?: TekmetricShop[];
    selected_shop_id?: string | number | null;
    selected_shop_name?: string | null;
  };
}

export function useTekmetricIntegration() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();

  const integrationQuery = useQuery({
    queryKey: ["tekmetric-integration", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data, error } = await (supabase as any)
        .from("tenant_integrations")
        .select("id, is_active, last_synced_at, config_json")
        .eq("tenant_id", tenant.id)
        .eq("provider", "tekmetric")
        .maybeSingle();

      if (error) throw error;
      return data as TekmetricIntegration | null;
    },
    enabled: !!tenant?.id,
  });

  const authenticate = useMutation({
    mutationFn: async ({ client_id, client_secret }: { client_id: string; client_secret: string }) => {
      const { data, error } = await supabase.functions.invoke("tekmetric-auth", {
        body: { action: "exchange-token", client_id, client_secret, tenant_id: tenant?.id },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      return data as { shops: TekmetricShop[] };
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["tekmetric-integration", tenant?.id] });
      toast.success("Connected to Tekmetric!");
    },
    onError: (err: Error) => {
      toast.error(err.message || "Failed to connect to Tekmetric");
    },
  });

  const selectShop = useMutation({
    mutationFn: async (shop_id: string | number) => {
      const { data, error } = await supabase.functions.invoke("tekmetric-auth", {
        body: { action: "select-shop", shop_id, tenant_id: tenant?.id },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["tekmetric-integration", tenant?.id] });
      toast.success("Shop selected — sync is now active!");
    },
    onError: (err: Error) => {
      toast.error(err.message || "Failed to select shop");
    },
  });

  const toggle = useMutation({
    mutationFn: async (is_active: boolean) => {
      const { data, error } = await supabase.functions.invoke("tekmetric-auth", {
        body: { action: "toggle", is_active, tenant_id: tenant?.id },
      });
      if (error) throw error;
      return data;
    },
    onSuccess: (_, is_active) => {
      queryClient.invalidateQueries({ queryKey: ["tekmetric-integration", tenant?.id] });
      toast.success(is_active ? "Sync resumed" : "Sync paused");
    },
  });

  const syncNow = useMutation({
    mutationFn: async () => {
      const { data, error } = await supabase.functions.invoke("sync-tekmetric", {
        body: { tenant_id: tenant?.id },
      });
      if (error) throw error;
      if (data?.error) throw new Error(data.error);
      return data;
    },
    onSuccess: (data) => {
      queryClient.invalidateQueries({ queryKey: ["tekmetric-integration", tenant?.id] });
      queryClient.invalidateQueries({ queryKey: ["active-jobs", tenant?.id] });
      const results = data?.results?.[0] || {};
      toast.success(`Synced: ${results.created || 0} new, ${results.updated || 0} updated`);
    },
    onError: (err: Error) => {
      toast.error(err.message || "Sync failed");
    },
  });

  const disconnect = useMutation({
    mutationFn: async () => {
      const { data, error } = await supabase.functions.invoke("tekmetric-auth", {
        body: { action: "disconnect", tenant_id: tenant?.id },
      });
      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["tekmetric-integration", tenant?.id] });
      toast.success("Tekmetric disconnected");
    },
  });

  return {
    integration: integrationQuery.data,
    isLoading: integrationQuery.isLoading,
    isConnected: !!integrationQuery.data?.is_active && !!integrationQuery.data?.config_json?.selected_shop_id,
    authenticate,
    selectShop,
    toggle,
    syncNow,
    disconnect,
  };
}

import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";

/**
 * Distance & ETA settings for a tenant
 */
export interface TenantDistanceSettings {
  tenant_id: string;
  distance_provider_enabled: boolean;
  provider: string;
  base_lat: number | null;
  base_lng: number | null;
  base_place_name: string | null;
  mapbox_route_profile: string;
  eta_base_minutes: number;
  eta_per_mile_minutes: number | null;
  eta_min_minutes: number | null;
  eta_max_minutes: number | null;
  eta_rounding_minutes: number;
  /** Default distance basis for pricing: tow_distance | dispatch_distance | total_trip | flat */
  default_distance_basis: string;
  /** Dropoff coverage mode: none | same_area | extended */
  dropoff_coverage_mode: string;
  /** Max miles for extended dropoff coverage */
  dropoff_max_miles: number | null;
  created_at: string;
  updated_at: string;
}

const DEFAULT_SETTINGS: Omit<TenantDistanceSettings, "tenant_id" | "created_at" | "updated_at"> = {
  distance_provider_enabled: false,
  provider: "mapbox",
  base_lat: null,
  base_lng: null,
  base_place_name: null,
  mapbox_route_profile: "mapbox/driving-traffic",
  eta_base_minutes: 0,
  eta_per_mile_minutes: null,
  eta_min_minutes: null,
  eta_max_minutes: null,
  eta_rounding_minutes: 5,
  default_distance_basis: "tow_distance",
  dropoff_coverage_mode: "none",
  dropoff_max_miles: null,
};

export function useTenantDistanceSettings() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const [settings, setSettings] = useState<TenantDistanceSettings | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [isGeocoding, setIsGeocoding] = useState(false);

  // Fetch settings
  const fetchSettings = useCallback(async () => {
    if (!tenant?.id) return;
    
    setIsLoading(true);
    try {
      const { data, error } = await supabase
        .from("tenant_distance_settings")
        .select("*")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error) throw error;

      if (data) {
        setSettings(data as TenantDistanceSettings);
      } else {
        // No settings exist yet - use defaults
        setSettings({
          ...DEFAULT_SETTINGS,
          tenant_id: tenant.id,
          created_at: new Date().toISOString(),
          updated_at: new Date().toISOString(),
        });
      }
    } catch (err) {
      console.error("Failed to fetch distance settings:", err);
      toast({
        title: "Error",
        description: "Failed to load distance settings",
        variant: "destructive",
      });
    } finally {
      setIsLoading(false);
    }
  }, [tenant?.id, toast]);

  useEffect(() => {
    fetchSettings();
  }, [fetchSettings]);

  // Save settings (upsert)
  const saveSettings = useCallback(async (updates: Partial<TenantDistanceSettings>) => {
    if (!tenant?.id || !settings) return false;

    setIsSaving(true);
    try {
      const updatedSettings = {
        ...settings,
        ...updates,
        tenant_id: tenant.id,
        updated_at: new Date().toISOString(),
      };

      // Remove computed fields
      const { created_at, ...upsertData } = updatedSettings;

      const { error } = await supabase
        .from("tenant_distance_settings")
        .upsert(upsertData, { onConflict: "tenant_id" });

      if (error) throw error;

      setSettings({ ...updatedSettings, created_at: settings.created_at });
      toast({
        title: "Saved",
        description: "Distance settings updated",
      });
      return true;
    } catch (err) {
      console.error("Failed to save distance settings:", err);
      toast({
        title: "Error",
        description: "Failed to save distance settings",
        variant: "destructive",
      });
      return false;
    } finally {
      setIsSaving(false);
    }
  }, [tenant?.id, settings, toast]);

  // Geocode an address and set base location
  const setBaseLocationFromAddress = useCallback(async (addressText: string) => {
    if (!tenant?.id) return false;

    setIsGeocoding(true);
    try {
      const { data, error } = await supabase.functions.invoke("mapbox-geocode", {
        body: {
          tenant_id: tenant.id,
          address_text: addressText,
        },
      });

      if (error) throw error;

      if (data?.error) {
        toast({
          title: "Geocoding failed",
          description: data.error,
          variant: "destructive",
        });
        return false;
      }

      if (data?.lat && data?.lng) {
        // Save the geocoded location
        const saved = await saveSettings({
          base_lat: data.lat,
          base_lng: data.lng,
          base_place_name: data.place_name || addressText,
        });

        if (saved) {
          toast({
            title: "Location set",
            description: data.place_name || "Base location updated",
          });
        }
        return saved;
      }

      toast({
        title: "Address not found",
        description: "Could not geocode the address. Please try a more specific address.",
        variant: "destructive",
      });
      return false;
    } catch (err) {
      console.error("Geocoding failed:", err);
      toast({
        title: "Error",
        description: "Failed to geocode address",
        variant: "destructive",
      });
      return false;
    } finally {
      setIsGeocoding(false);
    }
  }, [tenant?.id, saveSettings, toast]);

  // Toggle enabled state
  const toggleEnabled = useCallback(async (enabled: boolean) => {
    return saveSettings({ distance_provider_enabled: enabled });
  }, [saveSettings]);

  // Update route profile
  const setRouteProfile = useCallback(async (profile: string) => {
    return saveSettings({ mapbox_route_profile: profile });
  }, [saveSettings]);

  // Update ETA parameters
  const setEtaParams = useCallback(async (params: {
    eta_base_minutes?: number;
    eta_per_mile_minutes?: number | null;
    eta_min_minutes?: number | null;
    eta_max_minutes?: number | null;
    eta_rounding_minutes?: number;
  }) => {
    return saveSettings(params);
  }, [saveSettings]);

  return {
    settings,
    isLoading,
    isSaving,
    isGeocoding,
    fetchSettings,
    saveSettings,
    toggleEnabled,
    setBaseLocationFromAddress,
    setRouteProfile,
    setEtaParams,
  };
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";
import { useEffect, useMemo } from "react";

interface TestDrive {
  id: string;
  tenant_id: string;
  customer_id: string | null;
  session_id: string | null;
  vehicle_stock_number: string | null;
  vehicle_year: string | null;
  vehicle_make: string | null;
  vehicle_model: string | null;
  vehicle_trim: string | null;
  vehicle_vin: string | null;
  vehicle_color: string | null;
  vehicle_type: string | null;
  scheduled_at: string | null;
  scheduled_date: string | null;
  scheduled_time: string | null;
  duration_minutes: number;
  sales_rep_requested: string | null;
  trade_in_interest: boolean;
  trade_in_vehicle_info: string | null;
  financing_interest: boolean;
  budget_range: string | null;
  status: string;
  notes: string | null;
  created_at: string;
  updated_at: string;
  customer?: {
    full_name: string | null;
    phone_e164: string | null;
    email: string | null;
  } | null;
}

type TestDriveInsert = Omit<TestDrive, "id" | "created_at" | "updated_at" | "customer">;

export function useTestDrives() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const drivesQuery = useQuery({
    queryKey: ["test-drives", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];

      const { data, error } = await (supabase as any)
        .from("test_drives")
        .select("*, customer:customers(full_name, phone_e164, email)")
        .eq("tenant_id", tenant.id)
        .order("scheduled_date", { ascending: true });

      if (error) throw error;
      return data as TestDrive[];
    },
    enabled: !!tenant?.id,
  });

  // Realtime subscription
  useEffect(() => {
    if (!tenant?.id) return;

    const channel = supabase
      .channel(`test-drives-realtime-${tenant.id}`)
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "test_drives",
          filter: `tenant_id=eq.${tenant.id}`,
        },
        () => {
          queryClient.invalidateQueries({ queryKey: ["test-drives", tenant.id] });
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [tenant?.id, queryClient]);

  const createTestDrive = useMutation({
    mutationFn: async (drive: Omit<TestDriveInsert, "tenant_id">) => {
      if (!tenant?.id) throw new Error("No tenant");

      const { data, error } = await (supabase as any)
        .from("test_drives")
        .insert({ ...drive, tenant_id: tenant.id })
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["test-drives", tenant?.id] });
      toast({ title: "Test drive scheduled", description: "Customer has been notified." });
    },
    onError: () => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const updateTestDrive = useMutation({
    mutationFn: async ({ id, ...updates }: Partial<TestDrive> & { id: string }) => {
      const { data, error } = await (supabase as any)
        .from("test_drives")
        .update(updates)
        .eq("id", id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["test-drives", tenant?.id] });
      toast({ title: "Test drive updated", description: "Changes saved." });
    },
    onError: () => {
      toast({ title: "Something went wrong", description: "Try again?", variant: "destructive" });
    },
  });

  const deleteTestDrive = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await (supabase as any).from("test_drives").delete().eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["test-drives", tenant?.id] });
      toast({ title: "Test drive cancelled", description: "Appointment removed." });
    },
    onError: (error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const stats = useMemo(() => {
    const now = new Date();
    const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const endOfToday = new Date(startOfToday.getTime() + 24 * 60 * 60 * 1000);
    const endOfWeek = new Date(startOfToday.getTime() + 7 * 24 * 60 * 60 * 1000);
    const drives = drivesQuery.data ?? [];

    return {
      today: drives.filter((d) => {
        if (!d.scheduled_date) return false;
        const date = new Date(d.scheduled_date);
        return date >= startOfToday && date < endOfToday;
      }).length,
      thisWeek: drives.filter((d) => {
        if (!d.scheduled_date) return false;
        const date = new Date(d.scheduled_date);
        return date >= startOfToday && date < endOfWeek;
      }).length,
      pending: drives.filter((d) => d.status === "pending").length,
      completed: drives.filter((d) => d.status === "completed").length,
    };
  }, [drivesQuery.data]);

  return {
    testDrives: drivesQuery.data ?? [],
    isLoading: drivesQuery.isLoading,
    error: drivesQuery.error,
    stats,
    createTestDrive,
    updateTestDrive,
    deleteTestDrive,
    refetch: drivesQuery.refetch,
  };
}

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useToast } from "@/hooks/use-toast";

export type EntityType = "order" | "booking" | "dispatch" | "reservation" | "catering" | "intake";
export type AuthMode = "none" | "header" | "basic";

export interface UniversalDeliverySettings {
  tenant_id: string;
  internal_enabled: boolean;
  webhook_enabled: boolean;
  webhook_url: string | null;
  webhook_secret: string | null;
  email_enabled: boolean;
  notify_email: string | null;
  sms_enabled: boolean;
  notify_phone: string | null;
  auth_mode: AuthMode;
  auth_header_name: string | null;
  auth_header_value: string | null;
  basic_user: string | null;
  basic_pass: string | null;
  created_at: string;
  updated_at: string;
}

export interface DeliveryRule {
  id: string;
  tenant_id: string;
  entity_type: EntityType;
  auto_confirm: boolean;
  review_queue_enabled: boolean;
  notify_on_new: boolean;
  created_at: string;
  updated_at: string;
}

export interface DeliveryAttempt {
  id: string;
  tenant_id: string;
  entity_type: EntityType;
  entity_id: string;
  method: "webhook" | "email" | "sms";
  status: "pending" | "success" | "failed";
  error_message: string | null;
  request_payload: Record<string, unknown> | null;
  response_body: string | null;
  created_at: string;
}

export function useUniversalDeliverySettings() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: ["universal_delivery_settings", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      
      const { data, error } = await supabase
        .from("universal_delivery_settings")
        .select("*")
        .eq("tenant_id", tenant.id)
        .maybeSingle();

      if (error) throw error;
      
      // Initialize if not exists
      if (!data) {
        const { data: newData, error: insertError } = await supabase
          .from("universal_delivery_settings")
          .insert({ tenant_id: tenant.id })
          .select()
          .single();
        
        if (insertError) throw insertError;
        return newData as unknown as UniversalDeliverySettings;
      }
      
      return data as unknown as UniversalDeliverySettings;
    },
    enabled: !!tenant?.id,
  });

  const updateSettings = useMutation({
    mutationFn: async (updates: Partial<UniversalDeliverySettings>) => {
      if (!tenant?.id) throw new Error("No tenant");
      
      const { data, error } = await supabase
        .from("universal_delivery_settings")
        .update(updates as Record<string, unknown>)
        .eq("tenant_id", tenant.id)
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["universal_delivery_settings", tenant?.id] });
      toast({ title: "Settings saved", description: "Delivery settings updated." });
    },
    onError: (error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  return {
    settings: query.data,
    isLoading: query.isLoading,
    updateSettings,
    isUpdating: updateSettings.isPending,
    refetch: query.refetch,
  };
}

export function useDeliveryRules() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();

  const query = useQuery({
    queryKey: ["delivery_rules", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      
      const { data, error } = await supabase
        .from("delivery_rules")
        .select("*")
        .eq("tenant_id", tenant.id);

      if (error) throw error;
      return data as unknown as DeliveryRule[];
    },
    enabled: !!tenant?.id,
  });

  const updateRule = useMutation({
    mutationFn: async ({ entityType, updates }: { entityType: EntityType; updates: Partial<DeliveryRule> }) => {
      if (!tenant?.id) throw new Error("No tenant");
      
      // Upsert the rule
      const { data, error } = await supabase
        .from("delivery_rules")
        .upsert({
          tenant_id: tenant.id,
          entity_type: entityType,
          ...updates,
        }, {
          onConflict: "tenant_id,entity_type",
        })
        .select()
        .single();

      if (error) throw error;
      return data;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["delivery_rules", tenant?.id] });
      toast({ title: "Rule updated", description: "Automation rule saved." });
    },
    onError: (error) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const getRuleForEntity = (entityType: EntityType): DeliveryRule | undefined => {
    return query.data?.find((r) => r.entity_type === entityType);
  };

  return {
    rules: query.data || [],
    isLoading: query.isLoading,
    updateRule,
    getRuleForEntity,
    isUpdating: updateRule.isPending,
    refetch: query.refetch,
  };
}

export function useDeliveryAttempts(entityType?: EntityType, entityId?: string) {
  const { tenant } = useAuth();

  return useQuery({
    queryKey: ["delivery_attempts", tenant?.id, entityType, entityId],
    queryFn: async () => {
      if (!tenant?.id) return [];
      
      let query = supabase
        .from("delivery_attempts")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false })
        .limit(50);

      if (entityType) {
        query = query.eq("entity_type", entityType);
      }
      if (entityId) {
        query = query.eq("entity_id", entityId);
      }

      const { data, error } = await query;
      if (error) throw error;
      return data as unknown as DeliveryAttempt[];
    },
    enabled: !!tenant?.id,
  });
}

export function useTestDelivery() {
  const { tenant } = useAuth();
  const { toast } = useToast();

  return useMutation({
    mutationFn: async ({ entityType, method }: { entityType: EntityType; method: "webhook" | "email" | "sms" }) => {
      if (!tenant?.id) throw new Error("No tenant");
      
      const response = await supabase.functions.invoke("universal-delivery", {
        body: {
          tenant_id: tenant.id,
          entity_type: entityType,
          entity_id: "test-" + Date.now(),
          test_mode: true,
        },
      });

      if (response.error) throw response.error;
      return response.data;
    },
    onSuccess: (data) => {
      if (data?.results?.webhook?.success || data?.results?.email?.success || data?.results?.sms?.success) {
        toast({ title: "Test sent", description: "Test delivery was successful." });
      } else {
        toast({ 
          title: "Test completed", 
          description: "Check results for any errors.",
          variant: "default",
        });
      }
    },
    onError: (error) => {
      toast({ title: "Test failed", description: error.message, variant: "destructive" });
    },
  });
}

export function useTriggerDelivery() {
  const { tenant } = useAuth();
  const { toast } = useToast();

  return useMutation({
    mutationFn: async ({ entityType, entityId }: { entityType: EntityType; entityId: string }) => {
      if (!tenant?.id) throw new Error("No tenant");
      
      const response = await supabase.functions.invoke("universal-delivery", {
        body: {
          tenant_id: tenant.id,
          entity_type: entityType,
          entity_id: entityId,
        },
      });

      if (response.error) throw response.error;
      return response.data;
    },
    onSuccess: () => {
      toast({ title: "Delivery triggered", description: "Item sent to configured destinations." });
    },
    onError: (error) => {
      toast({ title: "Delivery failed", description: error.message, variant: "destructive" });
    },
  });
}

import { useState, useEffect, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import {
  getLadderStep,
  calculateOverageCost,
  getNextUpgrade,
  type PlanSku,
  type PlanLadderStep,
} from "@/config/pricing";
import type { SubscriptionUsage, Subscription } from "@/types/database";

export interface UsageData {
  voiceMinutesUsed: number;
  smsSegmentsUsed: number;
  includedMinutes: number | null;
  includedSmsSegments: number | null;
  overageMinuteRate: number | null;
  overageSmsRate: number;
  projectedVoiceOverage: number;
  projectedSmsOverage: number;
  billingPeriodStart: Date | null;
  billingPeriodEnd: Date | null;
  voicePercentUsed: number;
  smsPercentUsed: number;
}

interface UseUsageResult {
  usage: UsageData | null;
  loading: boolean;
  error: string | null;
  nextUpgrade: PlanLadderStep | null;
  refetch: () => Promise<void>;
}

export function useUsage(tenantId: string | null, planSku: PlanSku | null): UseUsageResult {
  const [usage, setUsage] = useState<UsageData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchUsage = useCallback(async () => {
    if (!tenantId) {
      setUsage(null);
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);

    try {
      // Fetch current billing period usage
      const now = new Date().toISOString();
      const { data: usageData, error: usageError } = await supabase
        .from("subscription_usage")
        .select("*")
        .eq("tenant_id", tenantId)
        .lte("billing_period_start", now)
        .gte("billing_period_end", now)
        .maybeSingle();

      if (usageError) throw usageError;

      // Fetch subscription for limits
      const { data: subData, error: subError } = await supabase
        .from("subscriptions")
        .select("*")
        .eq("tenant_id", tenantId)
        .maybeSingle();

      if (subError) throw subError;

      // Get plan details from config if we have a SKU
      const step = planSku ? getLadderStep(planSku) : null;

      // Use subscription data or fall back to plan config
      const includedMinutes = (subData as any)?.included_minutes ?? step?.includedMinutes ?? null;
      const includedSmsSegments = (subData as any)?.included_sms_segments ?? step?.includedSmsSegments ?? null;
      const overageMinuteRateCents = (subData as any)?.overage_minute_rate_cents;
      const overageSmsRateCents = (subData as any)?.overage_sms_rate_cents;

      const overageMinuteRate = overageMinuteRateCents 
        ? overageMinuteRateCents / 100 
        : step?.overageMinuteRate ?? null;
      const overageSmsRate = overageSmsRateCents 
        ? overageSmsRateCents / 100 
        : step?.overageSmsRate ?? 0.03;

      const voiceMinutesUsed = usageData?.voice_minutes_used ?? 0;
      const smsSegmentsUsed = usageData?.sms_segments_used ?? 0;

      const projectedVoiceOverage = includedMinutes !== null && overageMinuteRate !== null
        ? calculateOverageCost(voiceMinutesUsed, includedMinutes, overageMinuteRate)
        : 0;

      const projectedSmsOverage = includedSmsSegments !== null
        ? calculateOverageCost(smsSegmentsUsed, includedSmsSegments, overageSmsRate)
        : 0;

      const voicePercentUsed = includedMinutes 
        ? Math.min(100, Math.round((voiceMinutesUsed / includedMinutes) * 100))
        : 0;
      const smsPercentUsed = includedSmsSegments 
        ? Math.min(100, Math.round((smsSegmentsUsed / includedSmsSegments) * 100))
        : 0;

      setUsage({
        voiceMinutesUsed,
        smsSegmentsUsed,
        includedMinutes,
        includedSmsSegments,
        overageMinuteRate,
        overageSmsRate,
        projectedVoiceOverage,
        projectedSmsOverage,
        billingPeriodStart: usageData?.billing_period_start 
          ? new Date(usageData.billing_period_start) 
          : null,
        billingPeriodEnd: usageData?.billing_period_end 
          ? new Date(usageData.billing_period_end) 
          : null,
        voicePercentUsed,
        smsPercentUsed,
      });
    } catch (err: any) {
      console.error("Failed to fetch usage data:", err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [tenantId, planSku]);

  useEffect(() => {
    fetchUsage();
  }, [fetchUsage]);

  const nextUpgrade = planSku ? getNextUpgrade(planSku) : null;

  return {
    usage,
    loading,
    error,
    nextUpgrade,
    refetch: fetchUsage,
  };
}

/**
 * useVinDecoder - Hook for decoding VINs using the free NHTSA vPIC API
 * Returns vehicle year, make, model from a 17-character VIN
 */

import { useState, useCallback } from "react";
import { toast } from "sonner";

interface VehicleInfo {
  year: string;
  make: string;
  model: string;
  bodyClass?: string;
  vehicleType?: string;
}

interface NHTSAResult {
  Variable: string;
  Value: string | null;
}

export function useVinDecoder() {
  const [isDecoding, setIsDecoding] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const decodeVin = useCallback(async (vin: string): Promise<VehicleInfo | null> => {
    // Validate VIN format (17 alphanumeric, no I, O, Q)
    const cleanVin = vin.toUpperCase().replace(/[^A-HJ-NPR-Z0-9]/g, "");
    
    if (cleanVin.length !== 17) {
      setError("VIN must be exactly 17 characters");
      return null;
    }
    
    setIsDecoding(true);
    setError(null);
    
    try {
      const response = await fetch(
        `https://vpic.nhtsa.dot.gov/api/vehicles/DecodeVinValues/${cleanVin}?format=json`
      );
      
      if (!response.ok) {
        throw new Error("Failed to decode VIN");
      }
      
      const data = await response.json();
      const results = data.Results?.[0];
      
      if (!results) {
        throw new Error("No results from VIN decoder");
      }
      
      // Check for errors in the response
      if (results.ErrorCode && results.ErrorCode !== "0") {
        const errorText = results.ErrorText || "Invalid VIN";
        // Only show error for completely invalid VINs
        if (results.ErrorCode.includes("1")) {
          setError(errorText);
          toast.error(`VIN Error: ${errorText}`);
          return null;
        }
      }
      
      const vehicleInfo: VehicleInfo = {
        year: results.ModelYear || "",
        make: results.Make || "",
        model: results.Model || "",
        bodyClass: results.BodyClass || "",
        vehicleType: results.VehicleType || "",
      };
      
      // Only return if we got meaningful data
      if (vehicleInfo.year || vehicleInfo.make || vehicleInfo.model) {
        toast.success(`Found: ${vehicleInfo.year} ${vehicleInfo.make} ${vehicleInfo.model}`);
        return vehicleInfo;
      }
      
      setError("Could not decode VIN - no vehicle data found");
      return null;
    } catch (err) {
      const message = err instanceof Error ? err.message : "Failed to decode VIN";
      setError(message);
      toast.error(message);
      return null;
    } finally {
      setIsDecoding(false);
    }
  }, []);

  return {
    decodeVin,
    isDecoding,
    error,
  };
}

