import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Loader2, CheckCircle2, DollarSign } from "lucide-react";
import { toast } from "sonner";

interface Commission {
  id: string;
  agency_id: string;
  tenant_id: string;
  stripe_invoice_id: string;
  invoice_amount_cents: number;
  commission_rate: number;
  commission_cents: number;
  status: string;
  period_start: string | null;
  period_end: string | null;
  created_at: string;
  paid_at: string | null;
  payout_method: string | null;
  payout_reference: string | null;
  // Joined
  agency_name?: string;
  tenant_name?: string;
}

function formatCents(cents: number) {
  return `$${(cents / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function useAdminCommissions() {
  return useQuery({
    queryKey: ["admin-commissions"],
    queryFn: async () => {
      const { data, error } = await (supabase as any)
        .from("agency_commissions")
        .select("*")
        .order("created_at", { ascending: false });

      if (error) throw error;

      const commissions: Commission[] = data || [];

      // Fetch agency names
      const agencyIds = [...new Set(commissions.map((c) => c.agency_id))];
      const agencyMap = new Map<string, string>();
      if (agencyIds.length > 0) {
        const { data: agencies } = await (supabase as any)
          .from("agency_accounts")
          .select("id, agency_name")
          .in("id", agencyIds);
        for (const a of agencies || []) {
          agencyMap.set(a.id, a.agency_name || "Unknown");
        }
      }

      // Fetch tenant names
      const tenantIds = [...new Set(commissions.map((c) => c.tenant_id))];
      const tenantMap = new Map<string, string>();
      if (tenantIds.length > 0) {
        const { data: tenants } = await supabase
          .from("tenants")
          .select("id, name")
          .in("id", tenantIds);
        for (const t of tenants || []) {
          tenantMap.set(t.id, (t as any).name || "Unknown");
        }
      }

      return commissions.map((c) => ({
        ...c,
        agency_name: agencyMap.get(c.agency_id) || "Unknown",
        tenant_name: tenantMap.get(c.tenant_id) || "Unknown",
      }));
    },
  });
}

export default function AdminCommissionPayoutsPage() {
  const queryClient = useQueryClient();
  const { data: commissions, isLoading } = useAdminCommissions();

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [payoutDialogOpen, setPayoutDialogOpen] = useState(false);
  const [payoutMethod, setPayoutMethod] = useState("paypal");
  const [payoutReference, setPayoutReference] = useState("");
  const [payoutNotes, setPayoutNotes] = useState("");
  const [statusFilter, setStatusFilter] = useState<"all" | "pending" | "paid">("pending");

  const payoutMutation = useMutation({
    mutationFn: async () => {
      const { data: sessionData } = await supabase.auth.getSession();
      const token = sessionData?.session?.access_token;

      const { data, error } = await supabase.functions.invoke("process-commission-payout", {
        body: {
          commission_ids: [...selectedIds],
          payout_method: payoutMethod,
          payout_reference: payoutReference || undefined,
          notes: payoutNotes || undefined,
        },
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });

      if (error) throw new Error(error.message || "Failed to process payout");
      return data;
    },
    onSuccess: (data) => {
      toast.success(`${data.paid_count} commission(s) marked as paid`);
      setSelectedIds(new Set());
      setPayoutDialogOpen(false);
      setPayoutReference("");
      setPayoutNotes("");
      queryClient.invalidateQueries({ queryKey: ["admin-commissions"] });
    },
    onError: (err: Error) => {
      toast.error(err.message || "Failed to process payout");
    },
  });

  const toggleSelection = (id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const pendingCommissions = commissions?.filter((c) => c.status === "pending") || [];
  const filtered = (commissions || []).filter((c) =>
    statusFilter === "all" ? true : c.status === statusFilter
  );

  // Group pending by agency for summary
  const agencyPendingSummary = new Map<string, { name: string; total: number; count: number }>();
  for (const c of pendingCommissions) {
    const existing = agencyPendingSummary.get(c.agency_id) || { name: c.agency_name || "Unknown", total: 0, count: 0 };
    existing.total += c.commission_cents;
    existing.count += 1;
    agencyPendingSummary.set(c.agency_id, existing);
  }

  const totalPendingCents = pendingCommissions.reduce((s, c) => s + c.commission_cents, 0);

  return (
    <div className="container max-w-6xl py-8 px-4 sm:px-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold tracking-tight">Commission Payouts</h1>
        <p className="text-sm text-muted-foreground">Review and process agency commission payments.</p>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
        <Card>
          <CardContent className="pt-4 pb-4">
            <p className="text-xs text-muted-foreground">Total Pending</p>
            <p className="text-2xl font-bold text-amber-600">{formatCents(totalPendingCents)}</p>
          </CardContent>
        </Card>
        {[...agencyPendingSummary.entries()].map(([agencyId, info]) => (
          <Card key={agencyId}>
            <CardContent className="pt-4 pb-4">
              <p className="text-xs text-muted-foreground">{info.name}</p>
              <p className="text-lg font-semibold">{formatCents(info.total)}</p>
              <p className="text-xs text-muted-foreground">{info.count} pending</p>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Actions */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Select value={statusFilter} onValueChange={(v) => setStatusFilter(v as any)}>
            <SelectTrigger className="h-8 w-[120px]">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="pending">Pending</SelectItem>
              <SelectItem value="paid">Paid</SelectItem>
              <SelectItem value="all">All</SelectItem>
            </SelectContent>
          </Select>
        </div>
        {selectedIds.size > 0 && (
          <Button size="sm" onClick={() => setPayoutDialogOpen(true)}>
            <DollarSign className="h-4 w-4 mr-1.5" />
            Mark {selectedIds.size} as Paid
          </Button>
        )}
      </div>

      {/* Table */}
      {isLoading ? (
        <div className="space-y-3">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="h-12 bg-muted animate-pulse rounded" />
          ))}
        </div>
      ) : (
        <div className="rounded-lg border overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow>
                {statusFilter === "pending" && <TableHead className="w-10" />}
                <TableHead>Agency</TableHead>
                <TableHead>Client</TableHead>
                <TableHead className="text-right">Invoice</TableHead>
                <TableHead className="text-right">Rate</TableHead>
                <TableHead className="text-right">Commission</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Payout</TableHead>
                <TableHead>Date</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filtered.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={statusFilter === "pending" ? 9 : 8} className="text-center text-muted-foreground py-8">
                    No commissions found.
                  </TableCell>
                </TableRow>
              ) : (
                filtered.map((c) => (
                  <TableRow key={c.id}>
                    {statusFilter === "pending" && (
                      <TableCell>
                        <input
                          type="checkbox"
                          checked={selectedIds.has(c.id)}
                          onChange={() => toggleSelection(c.id)}
                          className="rounded border-muted-foreground"
                        />
                      </TableCell>
                    )}
                    <TableCell className="font-medium text-sm">{c.agency_name}</TableCell>
                    <TableCell className="text-sm">{c.tenant_name}</TableCell>
                    <TableCell className="text-right text-sm tabular-nums">{formatCents(c.invoice_amount_cents)}</TableCell>
                    <TableCell className="text-right text-sm tabular-nums">{Math.round(c.commission_rate * 100)}%</TableCell>
                    <TableCell className="text-right text-sm font-medium tabular-nums">{formatCents(c.commission_cents)}</TableCell>
                    <TableCell>
                      <Badge
                        variant="secondary"
                        className={
                          c.status === "paid"
                            ? "bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300"
                            : c.status === "pending"
                              ? "bg-amber-100 text-amber-800 dark:bg-amber-900/30 dark:text-amber-300"
                              : ""
                        }
                      >
                        {c.status}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-xs text-muted-foreground">
                      {c.payout_method ? `${c.payout_method}${c.payout_reference ? ` #${c.payout_reference}` : ""}` : "-"}
                    </TableCell>
                    <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                      {c.paid_at
                        ? new Date(c.paid_at).toLocaleDateString()
                        : c.created_at
                          ? new Date(c.created_at).toLocaleDateString()
                          : "-"}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </div>
      )}

      {/* Payout Dialog */}
      <Dialog open={payoutDialogOpen} onOpenChange={setPayoutDialogOpen}>
        <DialogContent className="max-w-sm">
          <DialogHeader>
            <DialogTitle>Process Payout</DialogTitle>
            <DialogDescription>
              Mark {selectedIds.size} commission{selectedIds.size > 1 ? "s" : ""} as paid.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label>Payout Method</Label>
              <Select value={payoutMethod} onValueChange={setPayoutMethod}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="paypal">PayPal</SelectItem>
                  <SelectItem value="zelle">Zelle</SelectItem>
                  <SelectItem value="wire">Wire Transfer</SelectItem>
                  <SelectItem value="check">Check</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Reference ID (optional)</Label>
              <Input
                value={payoutReference}
                onChange={(e) => setPayoutReference(e.target.value)}
                placeholder="e.g., PayPal transaction ID"
              />
            </div>
            <div className="space-y-2">
              <Label>Notes (optional)</Label>
              <Textarea
                value={payoutNotes}
                onChange={(e) => setPayoutNotes(e.target.value)}
                placeholder="Internal notes about this payout..."
                rows={2}
              />
            </div>
            <Button
              className="w-full"
              onClick={() => payoutMutation.mutate()}
              disabled={payoutMutation.isPending}
            >
              {payoutMutation.isPending ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : (
                <CheckCircle2 className="h-4 w-4 mr-2" />
              )}
              Confirm Payout
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useRef } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { 
  Upload, Play, Pause, Trash2, Save, 
  Music, CheckCircle, AlertCircle, Loader2 
} from "lucide-react";
import { useIndustryDemoAdmin, IndustryDemo } from "@/hooks/useIndustryDemos";
import { toast } from "sonner";

export default function AdminDemoLibraryPage() {
  const { demos, loading, updateDemo, uploadAudio, deleteAudio, refetch } = useIndustryDemoAdmin();
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<IndustryDemo>>({});
  const [uploading, setUploading] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const uploadTargetRef = useRef<IndustryDemo | null>(null);

  const handleEdit = (demo: IndustryDemo) => {
    setEditingId(demo.id);
    setEditForm({
      title: demo.title,
      caption_bullets: demo.caption_bullets,
      transcript_excerpt: demo.transcript_excerpt || "",
      is_active: demo.is_active,
    });
  };

  const handleSave = async (id: string) => {
    setSaving(true);
    try {
      await updateDemo(id, editForm);
      setEditingId(null);
      toast.success("Demo updated");
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setSaving(false);
    }
  };

  const handleUploadAudio = async (demo: IndustryDemo, file: File) => {
    setUploading(demo.id);
    try {
      const url = await uploadAudio(demo.industry_key, file);
      await updateDemo(demo.id, { audio_url: url });
      toast.success("Audio uploaded");
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setUploading(null);
    }
  };

  const handleDeleteAudio = async (demo: IndustryDemo) => {
    try {
      await deleteAudio(demo.industry_key);
      await updateDemo(demo.id, { audio_url: null });
      toast.success("Audio removed");
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const handleToggleActive = async (demo: IndustryDemo) => {
    try {
      await updateDemo(demo.id, { is_active: !demo.is_active });
      toast.success(demo.is_active ? "Demo hidden" : "Demo visible");
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const updateBullet = (index: number, value: string) => {
    const bullets = [...(editForm.caption_bullets || [])];
    bullets[index] = value;
    setEditForm({ ...editForm, caption_bullets: bullets });
  };

  const addBullet = () => {
    const bullets = [...(editForm.caption_bullets || []), ""];
    setEditForm({ ...editForm, caption_bullets: bullets });
  };

  const removeBullet = (index: number) => {
    const bullets = (editForm.caption_bullets || []).filter((_, i) => i !== index);
    setEditForm({ ...editForm, caption_bullets: bullets });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const triggerUpload = (demo: IndustryDemo) => {
    uploadTargetRef.current = demo;
    fileInputRef.current?.click();
  };

  const onFileSelected = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    const demo = uploadTargetRef.current;
    if (file && demo) handleUploadAudio(demo, file);
    // Reset so the same file can be re-selected
    e.target.value = "";
  };

  return (
    <div className="space-y-6">
      {/* Single shared file input outside the loop */}
      <input
        type="file"
        accept="audio/*"
        className="hidden"
        ref={fileInputRef}
        onChange={onFileSelected}
      />

      <div>
        <h1 className="text-2xl font-bold">Demo Library</h1>
        <p className="text-muted-foreground">
          Upload real call recordings for each industry demo on the home page.
        </p>
      </div>

      <div className="grid gap-6">
        {demos.map((demo) => (
          <Card key={demo.id} className={!demo.is_active ? "opacity-60" : ""}>
            <CardHeader className="flex flex-row items-center justify-between pb-2">
              <div className="flex items-center gap-3">
                <CardTitle className="text-lg">{demo.title}</CardTitle>
                <Badge variant={demo.is_active ? "default" : "secondary"}>
                  {demo.is_active ? "Active" : "Hidden"}
                </Badge>
                <Badge variant="outline">{demo.industry_key}</Badge>
              </div>
              <div className="flex items-center gap-2">
                <Switch
                  checked={demo.is_active}
                  onCheckedChange={() => handleToggleActive(demo)}
                />
                {editingId !== demo.id && (
                  <Button variant="outline" size="sm" onClick={() => handleEdit(demo)}>
                    Edit
                  </Button>
                )}
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              {/* Audio Section */}
              <div className="flex items-center gap-4 p-4 bg-muted/50 rounded-lg">
                <Music className="h-8 w-8 text-muted-foreground" />
                <div className="flex-1">
                  {demo.audio_url ? (
                    <div className="flex items-center gap-3">
                      <CheckCircle className="h-4 w-4 text-green-500" />
                      <span className="text-sm">Audio uploaded</span>
                      <audio controls className="h-8 max-w-xs">
                        <source src={demo.audio_url} />
                      </audio>
                    </div>
                  ) : (
                    <div className="flex items-center gap-2 text-amber-600">
                      <AlertCircle className="h-4 w-4" />
                      <span className="text-sm">No audio uploaded</span>
                    </div>
                  )}
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => triggerUpload(demo)}
                    disabled={uploading === demo.id}
                  >
                    {uploading === demo.id ? (
                      <Loader2 className="h-4 w-4 animate-spin mr-1" />
                    ) : (
                      <Upload className="h-4 w-4 mr-1" />
                    )}
                    Upload
                  </Button>
                  {demo.audio_url && (
                    <Button
                      variant="ghost"
                      size="sm"
                      onClick={() => handleDeleteAudio(demo)}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  )}
                </div>
              </div>

              {/* Edit Form */}
              {editingId === demo.id ? (
                <div className="space-y-4 border-t pt-4">
                  <div>
                    <Label>Title</Label>
                    <Input
                      value={editForm.title || ""}
                      onChange={(e) => setEditForm({ ...editForm, title: e.target.value })}
                    />
                  </div>

                  <div>
                    <Label>Caption Bullets (shown during playback)</Label>
                    <div className="space-y-2 mt-2">
                      {(editForm.caption_bullets || []).map((bullet, i) => (
                        <div key={i} className="flex gap-2">
                          <Input
                            value={bullet}
                            onChange={(e) => updateBullet(i, e.target.value)}
                            placeholder={`Bullet ${i + 1}`}
                          />
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => removeBullet(i)}
                          >
                            <Trash2 className="h-4 w-4" />
                          </Button>
                        </div>
                      ))}
                      <Button variant="outline" size="sm" onClick={addBullet}>
                        Add Bullet
                      </Button>
                    </div>
                  </div>

                  <div>
                    <Label>Transcript Excerpt (optional)</Label>
                    <Textarea
                      value={editForm.transcript_excerpt || ""}
                      onChange={(e) =>
                        setEditForm({ ...editForm, transcript_excerpt: e.target.value })
                      }
                      placeholder='AI: "Hi, thanks for calling..."'
                      rows={3}
                    />
                  </div>

                  <div className="flex gap-2">
                    <Button onClick={() => handleSave(demo.id)} disabled={saving}>
                      {saving && <Loader2 className="h-4 w-4 animate-spin mr-1" />}
                      <Save className="h-4 w-4 mr-1" />
                      Save
                    </Button>
                    <Button variant="ghost" onClick={() => setEditingId(null)}>
                      Cancel
                    </Button>
                  </div>
                </div>
              ) : (
                <div className="text-sm text-muted-foreground">
                  <p className="font-medium mb-1">Bullets:</p>
                  <ul className="list-disc list-inside space-y-1">
                    {demo.caption_bullets.map((b, i) => (
                      <li key={i}>{b}</li>
                    ))}
                  </ul>
                  {demo.transcript_excerpt && (
                    <p className="mt-2 italic">"{demo.transcript_excerpt}"</p>
                  )}
                </div>
              )}
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import {
  Settings, Rocket, Search, Mail, Share2, Megaphone,
  Activity, Users, MessageSquare, CheckCircle2, Loader2, Clock,
} from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { useAdminGrowthSettings } from "@/hooks/useAdminGrowthSettings";
import { useOutreachCampaigns } from "@/hooks/useAdminOutreach";
import { useAdminSocialPosts, useGrowthActivityLog } from "@/hooks/useAdminSocialPosts";
import { GrowthSettingsPanel } from "@/components/admin/growth/GrowthSettingsPanel";
import { GrowthSetupWizard } from "@/components/admin/growth/GrowthSetupWizard";
import { OutreachSequenceEditor } from "@/components/admin/growth/OutreachSequenceEditor";
import { OutreachCampaignManager } from "@/components/admin/growth/OutreachCampaignManager";
import { AdCampaignGenerator } from "@/components/admin/growth/AdCampaignGenerator";
import { AdCampaignList } from "@/components/admin/growth/AdCampaignList";
import { SocialContentCalendar } from "@/components/admin/growth/SocialContentCalendar";

const ACTIVITY_ICONS: Record<string, any> = {
  discovery: Search,
  outreach_sent: Mail,
  outreach_response: MessageSquare,
  social_posted: Share2,
  ad_created: Megaphone,
  enrollment: Users,
  conversion: CheckCircle2,
};

const ACTIVITY_COLORS: Record<string, string> = {
  discovery: "text-blue-600",
  outreach_sent: "text-green-600",
  outreach_response: "text-amber-600",
  social_posted: "text-purple-600",
  ad_created: "text-pink-600",
  enrollment: "text-cyan-600",
  conversion: "text-emerald-600",
};

export default function AdminGrowthEnginePage() {
  const { data: settings, isLoading: settingsLoading } = useAdminGrowthSettings();
  const { data: campaigns } = useOutreachCampaigns();
  const { data: socialPosts } = useAdminSocialPosts();
  const { data: activityLog, isLoading: activityLoading } = useGrowthActivityLog(100);
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");

  const modules = [
    { key: "discovery", label: "Discovery", enabled: settings?.auto_discovery_enabled, icon: Search },
    { key: "outreach", label: "Outreach", enabled: settings?.auto_outreach_enabled, icon: Mail },
    { key: "social", label: "Social", enabled: settings?.auto_social_enabled, icon: Share2 },
    { key: "ads", label: "Ads", enabled: settings?.auto_ads_enabled, icon: Megaphone },
  ];

  const activeCampaigns = (campaigns ?? []).filter((c) => c.status === "active");
  const totalEnrolled = activeCampaigns.reduce((sum, c) => sum + c.total_enrolled, 0);
  const totalResponded = activeCampaigns.reduce((sum, c) => sum + c.total_responded, 0);
  const totalConverted = activeCampaigns.reduce((sum, c) => sum + c.total_converted, 0);
  const scheduledPosts = (socialPosts ?? []).filter((p) => p.status === "scheduled").length;

  return (
    <div className="p-4 md:p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
            <Rocket className="h-5 w-5 text-primary" />
          </div>
          <div>
            <h1 className="text-2xl font-bold">Growth Engine</h1>
            <p className="text-sm text-muted-foreground">Autonomous lead discovery, outreach, and content</p>
          </div>
        </div>
        <Button variant="outline" size="sm" onClick={() => setSettingsOpen(true)}>
          <Settings className="h-4 w-4 mr-2" /> Settings
        </Button>
      </div>

      {/* Autopilot Status Bar */}
      <div className="flex items-center gap-2 flex-wrap">
        {modules.map((mod) => {
          const Icon = mod.icon;
          return (
            <Badge
              key={mod.key}
              variant="outline"
              className={`text-xs px-3 py-1.5 ${mod.enabled
                ? "bg-green-500/10 text-green-700 border-green-500/30"
                : "bg-muted text-muted-foreground"
              }`}
            >
              <Icon className="h-3.5 w-3.5 mr-1.5" />
              {mod.label}
              <span className={`ml-1.5 inline-block h-2 w-2 rounded-full ${mod.enabled ? "bg-green-500" : "bg-muted-foreground/30"}`} />
            </Badge>
          );
        })}
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <StatCard label="Active Campaigns" value={activeCampaigns.length} icon={Rocket} />
        <StatCard label="Leads Enrolled" value={totalEnrolled} icon={Users} />
        <StatCard label="Responses" value={totalResponded} icon={MessageSquare} />
        <StatCard label="Conversions" value={totalConverted} icon={CheckCircle2} />
      </div>

      {/* Setup Wizard */}
      <GrowthSetupWizard />

      {/* Main Content Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList className="h-9">
          <TabsTrigger value="overview" className="text-xs px-4">Activity Feed</TabsTrigger>
          <TabsTrigger value="sequences" className="text-xs px-4">Sequences</TabsTrigger>
          <TabsTrigger value="campaigns" className="text-xs px-4">Campaigns</TabsTrigger>
          <TabsTrigger value="ads" className="text-xs px-4">Ads</TabsTrigger>
          <TabsTrigger value="social" className="text-xs px-4">Social</TabsTrigger>
        </TabsList>

        <TabsContent value="overview" className="mt-4 space-y-4">
          <div className="grid md:grid-cols-3 gap-4">
            {/* Activity Feed */}
            <div className="md:col-span-2">
              <Card>
                <CardHeader className="pb-3">
                  <CardTitle className="text-sm flex items-center gap-2">
                    <Activity className="h-4 w-4" /> Activity Feed
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  {activityLoading ? (
                    <div className="flex items-center justify-center py-8">
                      <Loader2 className="h-5 w-5 animate-spin" />
                    </div>
                  ) : !activityLog?.length ? (
                    <p className="text-sm text-muted-foreground text-center py-8">
                      No activity yet. Enable autopilot modules in Settings.
                    </p>
                  ) : (
                    <div className="space-y-1 max-h-[500px] overflow-y-auto">
                      {activityLog.map((entry) => {
                        const Icon = ACTIVITY_ICONS[entry.activity_type] || Activity;
                        const color = ACTIVITY_COLORS[entry.activity_type] || "text-muted-foreground";
                        return (
                          <div key={entry.id} className="flex items-start gap-2 py-1.5 px-2 rounded hover:bg-muted/50 text-xs">
                            <Icon className={`h-3.5 w-3.5 mt-0.5 shrink-0 ${color}`} />
                            <div className="flex-1 min-w-0">
                              <span className="font-medium">{entry.title}</span>
                              {entry.description && (
                                <p className="text-muted-foreground truncate">{entry.description}</p>
                              )}
                            </div>
                            <span className="text-[10px] text-muted-foreground whitespace-nowrap">
                              {formatDistanceToNow(new Date(entry.created_at), { addSuffix: true })}
                            </span>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </CardContent>
              </Card>
            </div>

            {/* Sidebar: Upcoming */}
            <div className="space-y-4">
              <Card>
                <CardHeader className="pb-3">
                  <CardTitle className="text-sm flex items-center gap-2">
                    <Clock className="h-4 w-4" /> Upcoming
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-2">
                  {scheduledPosts > 0 && (
                    <div className="text-xs flex items-center gap-2">
                      <Share2 className="h-3.5 w-3.5 text-purple-600" />
                      <span>{scheduledPosts} social post{scheduledPosts !== 1 ? "s" : ""} scheduled</span>
                    </div>
                  )}
                  {activeCampaigns.length > 0 && (
                    <div className="text-xs flex items-center gap-2">
                      <Mail className="h-3.5 w-3.5 text-green-600" />
                      <span>{activeCampaigns.length} active outreach campaign{activeCampaigns.length !== 1 ? "s" : ""}</span>
                    </div>
                  )}
                  {!scheduledPosts && !activeCampaigns.length && (
                    <p className="text-xs text-muted-foreground">Nothing scheduled</p>
                  )}
                </CardContent>
              </Card>

              <Card>
                <CardHeader className="pb-3">
                  <CardTitle className="text-sm">Active Campaigns</CardTitle>
                </CardHeader>
                <CardContent className="space-y-1">
                  {activeCampaigns.length === 0 ? (
                    <p className="text-xs text-muted-foreground">No active campaigns</p>
                  ) : (
                    activeCampaigns.map((c) => (
                      <div key={c.id} className="flex items-center justify-between text-xs py-1">
                        <span className="font-medium truncate">{c.name}</span>
                        <span className="text-muted-foreground">{c.total_enrolled}</span>
                      </div>
                    ))
                  )}
                </CardContent>
              </Card>
            </div>
          </div>
        </TabsContent>

        <TabsContent value="sequences" className="mt-4">
          <OutreachSequenceEditor />
        </TabsContent>

        <TabsContent value="campaigns" className="mt-4">
          <OutreachCampaignManager />
        </TabsContent>

        <TabsContent value="ads" className="mt-4 space-y-4">
          <AdCampaignGenerator />
          <AdCampaignList />
        </TabsContent>

        <TabsContent value="social" className="mt-4">
          <SocialContentCalendar />
        </TabsContent>
      </Tabs>

      <GrowthSettingsPanel open={settingsOpen} onClose={() => setSettingsOpen(false)} />
    </div>
  );
}

function StatCard({ label, value, icon: Icon }: { label: string; value: number; icon: any }) {
  return (
    <Card>
      <CardContent className="p-3 flex items-center gap-3">
        <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-primary/10">
          <Icon className="h-4 w-4 text-primary" />
        </div>
        <div>
          <p className="text-xl font-bold">{value}</p>
          <p className="text-[10px] text-muted-foreground">{label}</p>
        </div>
      </CardContent>
    </Card>
  );
}

