                  </Button>
                  <Button size="sm" variant="outline" onClick={() => document.getElementById("lead-finder")?.scrollIntoView({ behavior: "smooth" })}>
                    Find Leads
                  </Button>
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* KPI Cards */}
      <AgencyOverview
        metrics={metrics}
        isLoading={metricsLoading}
        commissionThisMonthCents={commissionData?.thisMonthCents ?? 0}
