                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 mb-1">
                        <span className="font-medium">
                          {getGapTypeLabel(aggregate.gap_type)}
                        </span>
                        <Badge
                          variant="outline"
                          className={
                            priorityLabels[aggregate.highest_priority].color
