const statusColors: Record<string, string> = {
  inquiry: "bg-muted text-muted-foreground",
  quoted: "bg-blue-500/10 text-blue-700 dark:text-blue-300",
  confirmed: "bg-green-500/10 text-green-700 dark:text-green-300",
  completed: "bg-muted text-muted-foreground",
  cancelled: "bg-destructive/10 text-destructive",
};

export default function CateringPage() {
  // P0-3: Route protection - redirect if catering module not enabled
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["catering"]);
  
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [newReq, setNewReq] = useState({ customer_name: "", customer_phone: "", event_type: "", event_date: "", guest_count: "", location: "", notes: "" });
  const [isCreating, setIsCreating] = useState(false);

  const { data: requests, isLoading } = useQuery({
    queryKey: ["catering-requests", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("catering_requests")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("event_date", { ascending: true });

      if (error) throw error;
      return data || [];
    },
    enabled: !!tenant?.id,
  });

  const updateStatusMutation = useMutation({
    mutationFn: async ({ id, status }: { id: string; status: string }) => {
      const { error } = await supabase
        .from("catering_requests")
        .update({ status })
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["catering-requests"] });
      toast({ title: "Request updated" });
    },
    onError: (error: Error) => {
      toast({ variant: "destructive", title: "Error", description: error.message });
    },
  });

  const filteredRequests = requests?.filter(r => 
    statusFilter === "all" || r.status === statusFilter
  ) || [];

  const upcomingEvents = requests?.filter(r => 
    r.event_date && new Date(r.event_date) >= new Date() && r.status === "confirmed"
  ) || [];

  const totalQuotedValue = requests
    ?.filter(r => r.status === "quoted" || r.status === "confirmed")
    .reduce((sum, r) => sum + (r.quote_amount_cents || 0), 0) || 0;

  const handleCreateRequest = async () => {
    if (!tenant?.id || !newReq.customer_name.trim()) return;
    setIsCreating(true);
    try {
      const { error } = await supabase.from("catering_requests").insert({
        tenant_id: tenant.id,
        customer_name: newReq.customer_name,
        customer_phone: newReq.customer_phone || null,
        event_type: newReq.event_type || null,
        event_date: newReq.event_date || null,
        guest_count: newReq.guest_count ? parseInt(newReq.guest_count) : null,
        location: newReq.location || null,
        notes: newReq.notes || null,
        status: "inquiry",
      });
      if (error) throw error;
      queryClient.invalidateQueries({ queryKey: ["catering-requests"] });
      toast({ title: "Catering request created" });
      setIsDialogOpen(false);
      setNewReq({ customer_name: "", customer_phone: "", event_type: "", event_date: "", guest_count: "", location: "", notes: "" });
    } catch (err: any) {
      toast({ variant: "destructive", title: "Error", description: err.message });
    } finally {
      setIsCreating(false);
    }
  };

  // Show loading while checking module access
  if (moduleLoading || !isAllowed) {
    return (
      <div className="p-6 flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="p-6 flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Catering Requests</h1>
          <p className="text-muted-foreground">Manage catering inquiries and events</p>
        </div>
        <Button onClick={() => setIsDialogOpen(true)}>
          <Plus className="h-4 w-4 mr-2" />
          New Request
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <Cake className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">New Inquiries</span>
            </div>
            <p className="text-2xl font-bold mt-1">
              {requests?.filter(r => r.status === "inquiry").length || 0}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">Upcoming Events</span>
            </div>
            <p className="text-2xl font-bold mt-1">{upcomingEvents.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <Users className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">Total Guests</span>
            </div>
            <p className="text-2xl font-bold mt-1">
              {upcomingEvents.reduce((sum, r) => sum + (r.guest_count || 0), 0)}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <DollarSign className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">Pipeline Value</span>
            </div>
            <p className="text-2xl font-bold mt-1">
              ${(totalQuotedValue / 100).toLocaleString()}
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Filter */}
      <div className="flex items-center gap-4">
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-[180px]">
            <SelectValue placeholder="Filter by status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Requests</SelectItem>
            <SelectItem value="inquiry">Inquiries</SelectItem>
            <SelectItem value="quoted">Quoted</SelectItem>
            <SelectItem value="confirmed">Confirmed</SelectItem>
            <SelectItem value="completed">Completed</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Requests Table */}
      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Event Date</TableHead>
                <TableHead>Customer</TableHead>
                <TableHead>Event Type</TableHead>
                <TableHead>Guests</TableHead>
                <TableHead>Location</TableHead>
                <TableHead>Quote</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredRequests.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={8} className="h-24">
                    <div className="flex flex-col items-center justify-center text-center">
                      <Cake className="h-8 w-8 text-muted-foreground/40 mb-2" />
                      <p className="text-sm font-medium">No catering requests yet</p>
                      <p className="text-xs text-muted-foreground mt-0.5">
                        {statusFilter !== "all"
                          ? "Try adjusting your filters."
                          : "When customers inquire about catering, their requests will appear here."}
                      </p>
                    </div>
                  </TableCell>
                </TableRow>
              ) : (
                filteredRequests.map((request) => (
                  <TableRow key={request.id}>
                    <TableCell>
                      {request.event_date 
                        ? format(new Date(request.event_date), "MMM d, yyyy")
                        : "TBD"
                      }
                      {request.event_time && (
                        <p className="text-sm text-muted-foreground">{request.event_time}</p>
                      )}
                    </TableCell>
                    <TableCell>
                      <div>
                        <p className="font-medium">{request.customer_name}</p>
                        {request.customer_phone && (
                          <p className="text-sm text-muted-foreground flex items-center gap-1">
                            <Phone className="h-3 w-3" />
                            {request.customer_phone}
                          </p>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>{request.event_type || "-"}</TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1">
                        <Users className="h-4 w-4 text-muted-foreground" />
                        {request.guest_count || "-"}
                      </div>
                    </TableCell>
                    <TableCell className="max-w-[150px] truncate">
                      {request.location || "-"}
                    </TableCell>
                    <TableCell>
                      {request.quote_amount_cents
                        ? `$${(request.quote_amount_cents / 100).toLocaleString()}`
                        : "-"
                      }
                    </TableCell>
                    <TableCell>
                      <Badge className={statusColors[request.status] || ""}>
                        {request.status}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Select
                        value={request.status}
                        onValueChange={(status) => 
                          updateStatusMutation.mutate({ id: request.id, status })
                        }
                      >
                        <SelectTrigger className="w-[120px]">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="inquiry">Inquiry</SelectItem>
                          <SelectItem value="quoted">Quoted</SelectItem>
                          <SelectItem value="confirmed">Confirmed</SelectItem>
                          <SelectItem value="completed">Completed</SelectItem>
                          <SelectItem value="cancelled">Cancelled</SelectItem>
                        </SelectContent>
                      </Select>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* New Catering Request Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>New Catering Request</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label htmlFor="cat-name">Customer Name</Label>
              <Input id="cat-name" placeholder="Customer name" value={newReq.customer_name} onChange={(e) => setNewReq(prev => ({ ...prev, customer_name: e.target.value }))} />
            </div>
            <div className="space-y-2">
              <Label htmlFor="cat-phone">Phone (optional)</Label>
              <Input id="cat-phone" placeholder="(555) 123-4567" value={newReq.customer_phone} onChange={(e) => setNewReq(prev => ({ ...prev, customer_phone: e.target.value }))} />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="cat-type">Event Type</Label>
                <Input id="cat-type" placeholder="Wedding, Corporate, etc." value={newReq.event_type} onChange={(e) => setNewReq(prev => ({ ...prev, event_type: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <Label htmlFor="cat-date">Event Date</Label>
                <Input id="cat-date" type="date" value={newReq.event_date} onChange={(e) => setNewReq(prev => ({ ...prev, event_date: e.target.value }))} />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="cat-guests">Guest Count</Label>
                <Input id="cat-guests" type="number" min="1" placeholder="50" value={newReq.guest_count} onChange={(e) => setNewReq(prev => ({ ...prev, guest_count: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <Label htmlFor="cat-location">Location</Label>
                <Input id="cat-location" placeholder="Venue or address" value={newReq.location} onChange={(e) => setNewReq(prev => ({ ...prev, location: e.target.value }))} />
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="cat-notes">Notes</Label>
              <Textarea id="cat-notes" placeholder="Special requirements, dietary restrictions..." rows={3} value={newReq.notes} onChange={(e) => setNewReq(prev => ({ ...prev, notes: e.target.value }))} />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>Cancel</Button>
            <Button onClick={handleCreateRequest} disabled={isCreating || !newReq.customer_name.trim()}>
              {isCreating ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : null}
              Create Request
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useMemo } from "react";
import { useCustomers, type Customer } from "@/hooks/useCustomers";
import { useCustomerEnrichment } from "@/hooks/useCustomerEnrichment";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import { StatCard } from "@/components/layout/StatCard";
import { SectionCard } from "@/components/layout/SectionCard";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { EmptyState } from "@/components/ui/empty-state";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  Select, SelectContent, SelectItem, SelectTrigger, SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Users, Plus, Search, Upload, ChevronDown, Phone as PhoneIcon,
  MapPin, CalendarCheck, UserPlus,
} from "lucide-react";
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { format, formatDistanceToNow } from "date-fns";
import { CustomerDetailSheet } from "@/components/customers/CustomerDetailSheet";
import { CreateCustomerDialog } from "@/components/customers/CreateCustomerDialog";
import CustomerMergeQueue from "@/components/customers/CustomerMergeQueue";
import { CreateBookingDialog } from "@/components/calendar/CreateBookingDialog";
import { CustomerCSVImportDialog } from "@/components/customers/CustomerCSVImportDialog";
import { cn } from "@/lib/utils";

const sourceLabels: Record<string, string> = {
  ai_call: "AI Call",
  manual: "Manual",
  referral: "Referral",
  website_form: "Website",
  walk_in: "Walk-in",
};

function getInitials(name: string) {
  return name
    .split(" ")
    .map((n) => n.charAt(0))
    .slice(0, 2)
    .join("")
    .toUpperCase();
}

function getModeLabels(mode: string) {
  const map: Record<string, { address: string; lastService: string; customerLabel: string; customersLabel: string }> = {
    service: { address: "Service Address", lastService: "Last Service", customerLabel: "Customer", customersLabel: "Customers" },
    dispatch: { address: "Pickup Location", lastService: "Last Job", customerLabel: "Customer", customersLabel: "Customers" },
    food: { address: "Delivery Address", lastService: "Last Order", customerLabel: "Guest", customersLabel: "Guests" },
    medical: { address: "Patient Address", lastService: "Last Visit", customerLabel: "Patient", customersLabel: "Patients" },
    sales: { address: "Address", lastService: "Last Appointment", customerLabel: "Prospect", customersLabel: "Prospects" },
    general: { address: "Address", lastService: "Last Interaction", customerLabel: "Customer", customersLabel: "Customers" },
  };
  return map[mode] || map.service;
}

export default function CustomersPage() {
  const { customers, isLoading } = useCustomers();
  const { terms, mode } = useIndustryContext();
  const { businessMode } = useTenantConfig();
  const modeLabels = getModeLabels(mode);

  const customerIds = useMemo(() => customers.map((c) => c.id), [customers]);
  const { data: enrichmentMap } = useCustomerEnrichment(customerIds);

  const [activeTab, setActiveTab] = useState("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [sourceFilter, setSourceFilter] = useState("all");
  const [sortBy, setSortBy] = useState<"name" | "recent">("name");

  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);
  const [createDialogOpen, setCreateDialogOpen] = useState(false);
  const [bookingDialogOpen, setBookingDialogOpen] = useState(false);
  const [importDialogOpen, setImportDialogOpen] = useState(false);
  const [bookingCustomerName, setBookingCustomerName] = useState("");
  const [bookingCustomerPhone, setBookingCustomerPhone] = useState("");

  const activeCustomers = useMemo(
    () => customers.filter((c) => (c.tags as string[] | null)?.includes("active_customer")),
    [customers]
  );

  const baseList = activeTab === "active" ? activeCustomers : customers;

  const filteredCustomers = useMemo(() => {
    let result = baseList;
    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      result = result.filter(
        (c) =>
          c.full_name.toLowerCase().includes(q) ||
          c.phone_e164.includes(q) ||
          c.email?.toLowerCase().includes(q) ||
          c.service_address?.toLowerCase().includes(q)
      );
    }
    if (sourceFilter !== "all") {
      result = result.filter((c) => c.source === sourceFilter);
    }
    if (sortBy === "recent") {
      result = [...result].sort(
        (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
      );
    }
    return result;
  }, [baseList, searchQuery, sourceFilter, sortBy]);

  // Stats
  const totalCount = customers.length;
  const activeCount = activeCustomers.length;
  const withEmail = customers.filter((c) => c.email).length;
  const recentCount = customers.filter((c) => {
    const created = new Date(c.created_at).getTime();
    return Date.now() - created < 30 * 24 * 60 * 60 * 1000;
  }).length;

  const handleRowClick = (customer: Customer) => {
    setSelectedCustomer(customer);
    setDetailOpen(true);
  };

  const handleBookFromDetail = (customer: Customer) => {
    setBookingCustomerName(customer.full_name);
    setBookingCustomerPhone(customer.phone_e164);
    setBookingDialogOpen(true);
  };

  return (
    <PageContainer maxWidth="xl">
      <PageHeader
        title={modeLabels.customersLabel === "Customer" ? "Customers" : modeLabels.customersLabel}
        description={`Your complete ${modeLabels.customersLabel.toLowerCase()} database`}
        action={
          <div className="flex items-center gap-2">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button variant="outline">
                  <Upload className="h-4 w-4 mr-1" />
                  Import
                  <ChevronDown className="h-3.5 w-3.5 ml-1" />
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end">
                <DropdownMenuItem onClick={() => setImportDialogOpen(true)}>
                  Import from CSV
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
            <Button onClick={() => setCreateDialogOpen(true)}>
              <Plus className="h-4 w-4 mr-1" />
              Add {modeLabels.customerLabel}
            </Button>
          </div>
        }
      />

      <Tabs value={activeTab} onValueChange={setActiveTab}>
        <TabsList>
          <TabsTrigger value="all">
            All
            <Badge variant="secondary" className="ml-1.5 h-5 px-1.5 text-xs">{customers.length}</Badge>
          </TabsTrigger>
          <TabsTrigger value="active">
            Active
            <Badge variant="secondary" className="ml-1.5 h-5 px-1.5 text-xs">{activeCustomers.length}</Badge>
          </TabsTrigger>
          <TabsTrigger value="merge">
            Merge Queue
          </TabsTrigger>
        </TabsList>

        {["all", "active"].map((tabKey) => (
          <TabsContent key={tabKey} value={tabKey} className="mt-6 space-y-4">
            {/* Toolbar */}
            <div className="flex flex-col sm:flex-row sm:items-center gap-3">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <Input
                  placeholder={`Search ${modeLabels.customersLabel.toLowerCase()}...`}
                  className="pl-10"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                />
              </div>
              <div className="flex items-center gap-2">
                <Select value={sourceFilter} onValueChange={setSourceFilter}>
                  <SelectTrigger className="w-32">
                    <SelectValue placeholder="Source" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Sources</SelectItem>
                    <SelectItem value="ai_call">AI Call</SelectItem>
                    <SelectItem value="manual">Manual</SelectItem>
                    <SelectItem value="referral">Referral</SelectItem>
                    <SelectItem value="website_form">Website</SelectItem>
                  </SelectContent>
                </Select>
                <Select value={sortBy} onValueChange={(v) => setSortBy(v as "name" | "recent")}>
                  <SelectTrigger className="w-32">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="name">By Name</SelectItem>
                    <SelectItem value="recent">Most Recent</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            {/* Table */}
            {isLoading ? (
              <div className="space-y-3">
                {Array.from({ length: 5 }).map((_, i) => (
                  <Skeleton key={i} className="h-14 w-full" />
                ))}
              </div>
            ) : filteredCustomers.length === 0 ? (
              <EmptyState
                icon={Users}
                title={searchQuery || sourceFilter !== "all" ? "No matches" : `No ${modeLabels.customersLabel.toLowerCase()} yet`}
                description={
                  searchQuery || sourceFilter !== "all"
                    ? "Try adjusting your search or filters."
                    : `${modeLabels.customersLabel} will appear here when they call or are added manually.`
                }
                action={
                  !searchQuery && sourceFilter === "all"
                    ? { label: `Add ${modeLabels.customerLabel}`, onClick: () => setCreateDialogOpen(true) }
                    : undefined
                }
              />
            ) : (
              <SectionCard noPadding>
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>Name</TableHead>
                      <TableHead className="hidden sm:table-cell">Phone</TableHead>
                      <TableHead className="hidden md:table-cell">Email</TableHead>
                      <TableHead className="hidden lg:table-cell">{modeLabels.address}</TableHead>
                      <TableHead className="hidden md:table-cell">{modeLabels.lastService}</TableHead>
                      <TableHead className="hidden lg:table-cell">Calls</TableHead>
                      <TableHead className="hidden sm:table-cell">Source</TableHead>
                      <TableHead className="hidden sm:table-cell">Added</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {filteredCustomers.map((customer) => {
                      const enrichment = enrichmentMap?.get(customer.id);
                      return (
                        <TableRow
                          key={customer.id}
                          className="cursor-pointer hover:bg-muted/50"
                          onClick={() => handleRowClick(customer)}
                        >
                          <TableCell>
                            <div className="flex items-center gap-3">
                              <div className="h-9 w-9 rounded-full bg-primary/10 flex items-center justify-center text-sm font-semibold text-primary shrink-0">
                                {getInitials(customer.full_name)}
                              </div>
                              <div>
                                <p className="font-medium">{customer.full_name}</p>
                                <p className="text-sm text-muted-foreground sm:hidden">
                                  {customer.phone_e164}
                                </p>
                              </div>
                            </div>
                          </TableCell>
                          <TableCell className="hidden sm:table-cell text-muted-foreground">
                            {customer.phone_e164}
                          </TableCell>
                          <TableCell className="hidden md:table-cell text-muted-foreground">
                            {customer.email || "—"}
                          </TableCell>
                          <TableCell className="hidden lg:table-cell text-muted-foreground text-sm max-w-[180px] truncate">
                            {customer.service_address ? (
                              <span className="flex items-center gap-1">
                                <MapPin className="h-3.5 w-3.5 shrink-0" />
                                {customer.service_address}
                              </span>
                            ) : "—"}
                          </TableCell>
                          <TableCell className="hidden md:table-cell text-muted-foreground text-sm">
                            {enrichment?.lastServiceDate
                              ? format(new Date(enrichment.lastServiceDate), "MMM d, yyyy")
                              : "Never"}
                          </TableCell>
                          <TableCell className="hidden lg:table-cell">
                            {enrichment?.recentCallCount ? (
                              <Badge variant="secondary" className="text-xs">
                                <PhoneIcon className="h-3 w-3 mr-1" />
                                {enrichment.recentCallCount}
                              </Badge>
                            ) : (
                              <span className="text-muted-foreground text-sm">0</span>
                            )}
                          </TableCell>
                          <TableCell className="hidden sm:table-cell">
                            <Badge variant="outline" className="text-xs">
                              {sourceLabels[customer.source || ""] || customer.source || "—"}
                            </Badge>
                          </TableCell>
                          <TableCell className="hidden sm:table-cell text-muted-foreground text-sm">
                            {formatDistanceToNow(new Date(customer.created_at), { addSuffix: true })}
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </SectionCard>
            )}

            <p className="text-xs text-muted-foreground text-center">
              {filteredCustomers.length} {filteredCustomers.length === 1 ? modeLabels.customerLabel.toLowerCase() : modeLabels.customersLabel.toLowerCase()}
            </p>
          </TabsContent>
        ))}

        <TabsContent value="merge" className="mt-6">
          <CustomerMergeQueue />
        </TabsContent>
      </Tabs>

      {/* Detail Sheet */}
      <CustomerDetailSheet
        customer={selectedCustomer}
        open={detailOpen}
        onOpenChange={setDetailOpen}
        onBookAppointment={handleBookFromDetail}
      />

      <CreateCustomerDialog open={createDialogOpen} onOpenChange={setCreateDialogOpen} />
      <CustomerCSVImportDialog open={importDialogOpen} onOpenChange={setImportDialogOpen} />
      <CreateBookingDialog
        open={bookingDialogOpen}
        onOpenChange={setBookingDialogOpen}
        initialCustomerName={bookingCustomerName}
        initialCustomerPhone={bookingCustomerPhone}
      />
    </PageContainer>
  );
}

import { useAuth } from "@/contexts/AuthContext";
import { SetupWizard } from "@/components/dashboard/SetupWizard";
import { LiveDashboard } from "@/components/dashboard/LiveDashboard";
import { PageContainer } from "@/components/layout/PageContainer";
import { useAIReadinessV2 } from "@/hooks/useAIReadinessV2";

export default function DashboardPage() {
  const { tenant, subscription, assistantSettings, refreshTenant, isSuperAdmin, hasActiveSubscription } = useAuth();
  const { canGoLive, p0Flags, loading: readinessLoading } = useAIReadinessV2();

  const setupComplete =
    isSuperAdmin ||
    assistantSettings?.go_live_enabled === true ||
    !!assistantSettings?.setup_completed_at;

  // No subscription — handled inside LiveDashboard's AgentControlPanel
  if (!hasActiveSubscription && !isSuperAdmin) {
    return (
      <PageContainer maxWidth="xl">
        <div className="pt-8">
          <LiveDashboard />
        </div>
      </PageContainer>
    );
  }

  return (
    <PageContainer maxWidth="xl">
      <div className="pt-8">
        {setupComplete ? (
          <LiveDashboard />
        ) : (
          <SetupWizard onSetupComplete={refreshTenant} />
        )}
      </div>
    </PageContainer>
  );
}

import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import {
  MapPin,
  Navigation,
  Loader2,
  RefreshCw,
  User,
  Clock,
  Signal,
  ExternalLink,
  Locate,
  Map,
  ArrowRight,
} from "lucide-react";
import { formatDistanceToNow } from "date-fns";
import { useTechnicianLocations, useAutoLocationReporting } from "@/hooks/useTechnicianLocations";
import { useModuleRequired } from "@/hooks/useModuleRequired";
import { useMapboxToken } from "@/hooks/useMapboxToken";
import { DispatchMapView } from "@/components/dispatch/DispatchMapView";

function formatCoordinate(value: number, isLat: boolean): string {
  const direction = isLat ? (value >= 0 ? "N" : "S") : (value >= 0 ? "E" : "W");
  return `${Math.abs(value).toFixed(6)}° ${direction}`;
}

function getGoogleMapsUrl(lat: number, lng: number): string {
  return `https://www.google.com/maps?q=${lat},${lng}`;
}

function getAccuracyBadge(accuracy: number | null) {
  if (accuracy === null) return null;
  if (accuracy < 10) return <Badge className="bg-green-100 text-green-700">High accuracy</Badge>;
  if (accuracy < 50) return <Badge className="bg-yellow-100 text-yellow-700">Medium</Badge>;
  return <Badge className="bg-red-100 text-red-700">Low accuracy</Badge>;
}

export default function DispatchMapPage() {
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["dispatch_queue"]);
  const { locations, isLoading, refetch } = useTechnicianLocations();
  const { token: mapboxToken, isLoading: tokenLoading } = useMapboxToken();
  const [trackingEnabled, setTrackingEnabled] = useState(false);
  const [lastRefresh, setLastRefresh] = useState(new Date());

  // Enable auto location reporting when toggle is on
  useAutoLocationReporting(trackingEnabled, 60000);

  const handleRefresh = () => {
    refetch();
    setLastRefresh(new Date());
  };

  // Auto-refresh every 30 seconds
  useEffect(() => {
    const interval = setInterval(() => {
      refetch();
      setLastRefresh(new Date());
    }, 30000);
    return () => clearInterval(interval);
  }, [refetch]);

  if (moduleLoading || !isAllowed) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isLoading || tokenLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <PageContainer maxWidth="xl">
      <PageHeader
        title="Dispatch Map"
        description="Real-time technician locations and tracking"
        action={
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2">
              <Switch
                id="tracking"
                checked={trackingEnabled}
                onCheckedChange={setTrackingEnabled}
              />
              <Label htmlFor="tracking" className="text-sm">
                Share my location
              </Label>
            </div>
            <Button variant="outline" onClick={handleRefresh}>
              <RefreshCw className="h-4 w-4 mr-2" />
              Refresh
            </Button>
          </div>
        }
      />

      {/* Live Map */}
      {mapboxToken ? (
        <div className="mb-6">
          <DispatchMapView token={mapboxToken} locations={locations} />
          {locations.length > 0 && (
            <p className="text-xs text-muted-foreground mt-2">
              {locations.length} technician{locations.length !== 1 ? "s" : ""} online · Last updated {formatDistanceToNow(lastRefresh, { addSuffix: true })}
            </p>
          )}
        </div>
      ) : (
        <Card className="mb-6">
          <CardContent className="py-12">
            <div className="flex flex-col items-center text-center space-y-4">
              <div className="h-16 w-16 rounded-full bg-muted flex items-center justify-center">
                <Map className="h-8 w-8 text-muted-foreground" />
              </div>
              <div>
                <h3 className="text-lg font-semibold">Map Unavailable</h3>
                <p className="text-sm text-muted-foreground max-w-md mt-1">
                  The map could not be loaded. Please contact support.
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Technician List */}
      <Card>
        <CardHeader>
          <CardTitle>Technician Locations</CardTitle>
          <CardDescription>
            Live location data from field technicians
          </CardDescription>
        </CardHeader>
        <CardContent>
          {locations.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              <Signal className="h-8 w-8 mx-auto mb-2 opacity-50" />
              <p>No location data available</p>
              <p className="text-sm">Enable location sharing to see technician positions</p>
            </div>
          ) : (
            <div className="space-y-4">
              {locations.map((location) => (
                <div
                  key={location.user_id}
                  className="flex items-center justify-between p-4 border rounded-lg hover:bg-muted/50 transition-colors"
                >
                  <div className="flex items-center gap-4">
                    <div className="h-12 w-12 rounded-full bg-primary/10 flex items-center justify-center relative">
                      <User className="h-6 w-6 text-primary" />
                      <div className="absolute -bottom-1 -right-1 h-4 w-4 rounded-full bg-green-500 border-2 border-background" />
                    </div>
                    <div>
                      <div className="flex items-center gap-2">
                        <p className="font-medium">Technician</p>
                        {getAccuracyBadge(location.accuracy_meters)}
                      </div>
                      <div className="flex items-center gap-4 text-sm text-muted-foreground">
                        <span className="flex items-center gap-1">
                          <Navigation className="h-3 w-3" />
                          {formatCoordinate(location.latitude, true)}, {formatCoordinate(location.longitude, false)}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground mt-1 flex items-center gap-1">
                        <Clock className="h-3 w-3" />
                        Updated {formatDistanceToNow(new Date(location.recorded_at), { addSuffix: true })}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {location.speed_mph !== null && location.speed_mph > 0 && (
                      <Badge variant="outline">
                        {Math.round(location.speed_mph)} mph
                      </Badge>
                    )}
                    <Button variant="outline" size="sm" asChild>
                      <a
                        href={getGoogleMapsUrl(location.latitude, location.longitude)}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <ExternalLink className="h-4 w-4 mr-2" />
                        Open in Maps
                      </a>
                    </Button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Location Sharing Info */}
      {trackingEnabled && (
        <Card className="mt-6">
          <CardContent className="pt-6">
            <div className="flex items-start gap-4">
              <div className="h-10 w-10 rounded-full bg-green-100 flex items-center justify-center flex-shrink-0">
                <Locate className="h-5 w-5 text-green-600" />
              </div>
              <div>
                <h4 className="font-medium">Location sharing is active</h4>
                <p className="text-sm text-muted-foreground">
                  Your location is being shared with dispatchers every 60 seconds.
                  Turn off the toggle above to stop sharing.
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </PageContainer>
  );
}

import { useState, useMemo, useEffect, useCallback } from "react";
import { AnimatedList, AnimatedListItem } from "@/components/ui/animated";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useModuleRequired } from "@/hooks/useModuleRequired";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import { Truck, Plus, Loader2, Map, Bell, AlertTriangle } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { DispatchJobCard } from "@/components/dispatch/DispatchJobCard";
import { DispatchCommandTable } from "@/components/dispatch/DispatchCommandTable";
import { DispatchCommandStats } from "@/components/dispatch/DispatchCommandStats";
import { DispatchFilters } from "@/components/dispatch/DispatchFilters";
import { DispatchJobDetailsSheet } from "@/components/dispatch/DispatchJobDetailsSheet";
import { AssignJobDialog } from "@/components/dispatch/AssignJobDialog";
import { EmptyState } from "@/components/ui/empty-state";
import { TooltipProvider } from "@/components/ui/tooltip";
import { Link } from "react-router-dom";
import { toast as sonnerToast } from "sonner";

interface PriceBreakdown {
  base_price?: number;
  per_mile_rate?: number;
  distance_charge?: number;
  vehicle_modifier?: number;
  urgency_modifier?: number;
  total?: number;
  description?: string;
  [key: string]: unknown;
}

interface DispatchJob {
  id: string;
  job_number?: string;
  status: string;
  priority: string;
  customer_name: string | null;
  customer_phone: string | null;
  pickup_address: string | null;
  pickup_lat?: number | null;
  pickup_lng?: number | null;
  dropoff_address?: string | null;
  dropoff_lat?: number | null;
  dropoff_lng?: number | null;
  job_type?: string | null;
  description?: string | null;
  notes?: string | null;
  price_cents?: number | null;
  estimated_duration_minutes?: number | null;
  assigned_crew: string | null;
  assigned_vehicle: string | null;
  created_at: string;
  dispatched_at?: string | null;
  arrived_at?: string | null;
  completed_at?: string | null;
  customers?: { full_name: string; phone_e164: string } | null;
  // Distance & Pricing fields
  dispatch_distance_miles?: number | null;
  tow_distance_miles?: number | null;
  total_distance_miles?: number | null;
  service_tier?: string | null;
  pricing_note?: string | null;
  price_breakdown?: PriceBreakdown | null;
}

export default function DispatchPage() {
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["dispatch_queue"]);
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  
  const [statusFilter, setStatusFilter] = useState<string>("active");
  const [priorityFilter, setPriorityFilter] = useState<string>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [viewMode, setViewMode] = useState<"table" | "grid">("table");
  
  // Sheet and Dialog state
  const [selectedJob, setSelectedJob] = useState<DispatchJob | null>(null);
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [assignDialogOpen, setAssignDialogOpen] = useState(false);
  const [jobToAssign, setJobToAssign] = useState<DispatchJob | null>(null);
  const [newJobOpen, setNewJobOpen] = useState(false);
  const [newJob, setNewJob] = useState({ customer_name: "", pickup_address: "", dropoff_address: "", job_type: "", priority: "normal", description: "" });
  const [isCreatingJob, setIsCreatingJob] = useState(false);

  const { data: jobs, isLoading, error: jobsError, refetch } = useQuery({
    queryKey: ["dispatch-jobs", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("dispatch_jobs")
        .select("*, customers(full_name, phone_e164)")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false });

      if (error) throw error;
      return (data || []) as DispatchJob[];
    },
    enabled: !!tenant?.id,
  });

  // Fetch callback requests from opportunities
  const { data: callbacks, refetch: refetchCallbacks } = useQuery({
    queryKey: ["dispatch-callbacks", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("opportunities")
        .select("*, customers(full_name, phone_e164)")
        .eq("tenant_id", tenant.id)
        .eq("source", "voice_callback")
        .order("created_at", { ascending: false })
        .limit(50);

      if (error) throw error;
      return data || [];
    },
    enabled: !!tenant?.id,
  });

  const pendingCallbacks = callbacks?.filter(c => c.status === "pending") || [];

  // Real-time subscription for new jobs and status updates
  useEffect(() => {
    if (!tenant?.id) return;

    const channel = supabase
      .channel(`dispatch-jobs-realtime-${tenant.id}`)
      .on(
        "postgres_changes",
        {
          event: "INSERT",
          schema: "public",
          table: "dispatch_jobs",
          filter: `tenant_id=eq.${tenant.id}`,
        },
        (payload) => {
          // Show alert for new job
          const newJob = payload.new as DispatchJob;
          sonnerToast.info("New Dispatch Job!", {
            description: `${newJob.customer_name || "Customer"} - ${newJob.pickup_address?.slice(0, 40) || "Unknown location"}`,
            duration: 10000,
            action: {
              label: "View",
              onClick: () => {
                setSelectedJob(newJob);
                setDetailsOpen(true);
              },
            },
          });
          // Play notification sound if available
          try {
            const audio = new Audio("/notification.mp3");
            audio.volume = 0.5;
            audio.play().catch(() => {});
          } catch {}
          // Refetch to get the new job
          refetch();
        }
      )
      .on(
        "postgres_changes",
        {
          event: "UPDATE",
          schema: "public",
          table: "dispatch_jobs",
          filter: `tenant_id=eq.${tenant.id}`,
        },
        () => {
          // Refetch on any update (driver status changes, etc.)
          refetch();
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [tenant?.id, refetch]);

  const updateJobMutation = useMutation({
    mutationFn: async ({ jobId, updates }: { jobId: string; updates: Record<string, unknown> }) => {
      const { error } = await supabase
        .from("dispatch_jobs")
        .update(updates)
        .eq("id", jobId);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["dispatch-jobs", tenant?.id] });
      sonnerToast.success("Job updated");
      setDetailsOpen(false);
      setAssignDialogOpen(false);
    },
    onError: (error: Error) => {
      sonnerToast.error("Error", { description: error.message });
    },
  });

  const activeStatuses = ["pending", "assigned", "en_route", "on_site"];

  const filteredJobs = useMemo(() => {
    if (!jobs) return [];

    // If callbacks filter is selected, we handle that separately in the render
    if (statusFilter === "callbacks") return [];

    return jobs.filter((job) => {
      // Status filter
      if (statusFilter === "active") {
        if (!activeStatuses.includes(job.status)) return false;
      } else if (statusFilter !== "all" && job.status !== statusFilter) {
        return false;
      }

      // Priority filter
      if (priorityFilter !== "all" && job.priority !== priorityFilter) {
        return false;
      }

      // Search filter
      if (searchQuery) {
        const query = searchQuery.toLowerCase();
        const customerName = job.customer_name?.toLowerCase() || "";
        const pickupAddress = job.pickup_address?.toLowerCase() || "";
        const dropoffAddress = job.dropoff_address?.toLowerCase() || "";
        const jobNumber = job.job_number?.toLowerCase() || "";
        const jobType = job.job_type?.toLowerCase() || "";
        const vehicle = job.assigned_vehicle?.toLowerCase() || "";
        const crew = job.assigned_crew?.toLowerCase() || "";
        return (
          customerName.includes(query) ||
          pickupAddress.includes(query) ||
          dropoffAddress.includes(query) ||
          jobNumber.includes(query) ||
          jobType.includes(query) ||
          vehicle.includes(query) ||
          crew.includes(query)
        );
      }

      return true;
    });
  }, [jobs, statusFilter, priorityFilter, searchQuery]);

  const handleAssign = (job: DispatchJob) => {
    setJobToAssign(job);
    setAssignDialogOpen(true);
  };

  const handleAssignSubmit = (jobId: string, crew: string, vehicle: string, driverId?: string, vehicleId?: string) => {
    const updates: Record<string, unknown> = {
      status: "assigned",
      assigned_crew: crew || null,
      assigned_vehicle: vehicle || null,
      driver_id: driverId || null,
      vehicle_id: vehicleId || null,
      dispatched_at: new Date().toISOString(),
    };
    updateJobMutation.mutate({ jobId, updates });
  };

  const handleUpdateStatus = (job: DispatchJob, newStatus: string) => {
    const updates: Record<string, unknown> = { status: newStatus };
    if (newStatus === "completed") {
      updates.completed_at = new Date().toISOString();
    }
    if (newStatus === "on_site") {
      updates.arrived_at = new Date().toISOString();
    }
    updateJobMutation.mutate({ jobId: job.id, updates });
  };

  const handleCall = (job: DispatchJob) => {
    const phone = job.customer_phone || job.customers?.phone_e164;
    if (phone) {
      window.open(`tel:${phone}`);
    }
  };

  const handleViewDetails = (job: DispatchJob) => {
    setSelectedJob(job);
    setDetailsOpen(true);
  };

  const handleCreateJob = async () => {
    if (!tenant?.id || !newJob.customer_name.trim()) return;
    setIsCreatingJob(true);
    try {
      const jobNum = `JOB-${Date.now().toString(36).toUpperCase()}`;
      const { error } = await (supabase as any).from("dispatch_jobs").insert({
        tenant_id: tenant.id,
        job_number: jobNum,
        customer_name: newJob.customer_name,
        pickup_address: newJob.pickup_address || null,
        dropoff_address: newJob.dropoff_address || null,
        job_type: newJob.job_type || null,
        priority: newJob.priority || "normal",
        description: newJob.description || null,
        status: "pending",
      });
      if (error) throw error;
      queryClient.invalidateQueries({ queryKey: ["dispatch-jobs", tenant.id] });
      sonnerToast.success("Job created");
      setNewJobOpen(false);
      setNewJob({ customer_name: "", pickup_address: "", dropoff_address: "", job_type: "", priority: "normal", description: "" });
    } catch (err: any) {
      sonnerToast.error("Error", { description: err.message });
    } finally {
      setIsCreatingJob(false);
    }
  };

  if (moduleLoading || !isAllowed) {
    return (
      <div className="p-6 flex items-center justify-center min-h-[400px]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="p-6 flex items-center justify-center min-h-[400px]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (jobsError) {
    return (
      <div className="container max-w-6xl py-8 px-4 sm:px-6">
        <div className="mx-auto max-w-lg py-16">
          <Card>
            <CardContent className="pt-8 pb-8 text-center space-y-4">
              <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-destructive/10">
                <AlertTriangle className="h-7 w-7 text-destructive" />
              </div>
              <h2 className="text-xl font-semibold">Something went wrong</h2>
              <p className="text-sm text-muted-foreground max-w-sm mx-auto">
                We couldn't load your dispatch jobs. Please refresh the page or try again later.
              </p>
              <Button variant="outline" onClick={() => window.location.reload()}>
                Refresh Page
              </Button>
            </CardContent>
          </Card>
        </div>
      </div>
    );
  }

  return (
    <TooltipProvider>
      <PageContainer maxWidth="full">
        <div className="space-y-6">
          <PageHeader
            title="Dispatch Command Center"
            description={`${filteredJobs.length} ${statusFilter === "active" ? "active " : ""}jobs in queue`}
            action={
              <div className="flex items-center gap-2">
                <Button variant="outline" asChild>
                  <Link to="/app/dispatch-map">
                    <Map className="h-4 w-4" />
                    Map View
                  </Link>
                </Button>
                <Button onClick={() => setNewJobOpen(true)}>
                  <Plus className="h-4 w-4" />
                  New Job
                </Button>
              </div>
            }
          />

          {/* Command Center Stats */}
          <DispatchCommandStats jobs={jobs || []} />

          {/* Filters */}
          <DispatchFilters
            statusFilter={statusFilter}
            onStatusFilterChange={setStatusFilter}
            priorityFilter={priorityFilter}
            onPriorityFilterChange={setPriorityFilter}
            searchQuery={searchQuery}
            onSearchChange={setSearchQuery}
            viewMode={viewMode}
            onViewModeChange={setViewMode}
            callbackCount={pendingCallbacks.length}
          />

          {/* Callbacks List */}
          {statusFilter === "callbacks" ? (
            callbacks && callbacks.length > 0 ? (
              <div className="space-y-3">
                <p className="text-sm text-muted-foreground">
                  Callback requests from callers who need follow-up
                </p>
                <div className="grid gap-3">
                  {callbacks.map((callback: any) => (
                    <div
                      key={callback.id}
                      className="flex items-start justify-between p-4 border rounded-lg bg-card hover:bg-accent/50 transition-colors"
                    >
                      <div className="space-y-1">
                        <div className="flex items-center gap-2">
                          <span className="font-medium">
                            {callback.customers?.full_name || "Unknown Caller"}
                          </span>
                          {callback.status === "pending" && (
                            <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-warning/15 text-warning border border-warning/30">
                              Pending
                            </span>
                          )}
                          {callback.status === "contacted" && (
                            <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-success/15 text-success border border-success/30">
                              Contacted
                            </span>
                          )}
                        </div>
                        <p className="text-sm text-muted-foreground whitespace-pre-line">
                          {callback.notes}
                        </p>
                        <p className="text-xs text-muted-foreground">
                          {new Date(callback.created_at).toLocaleString()}
                        </p>
                      </div>
                      <div className="flex gap-2">
                        {callback.customers?.phone_e164 && (
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={() => window.open(`tel:${callback.customers.phone_e164}`)}
                          >
                            Call Back
                          </Button>
                        )}
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={async () => {
                            await supabase
                              .from("opportunities")
                              .update({ status: "contacted" })
                              .eq("id", callback.id);
                            refetchCallbacks();
                          }}
                        >
                          Mark Done
                        </Button>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            ) : (
              <EmptyState
                icon={Truck}
                title="No callback requests"
                description="When callers request a callback, they'll appear here for follow-up."
              />
            )
          ) : filteredJobs.length === 0 ? (
            <EmptyState
              icon={Truck}
              title="No active jobs"
              description={
                statusFilter !== "all" || priorityFilter !== "all" || searchQuery
                  ? "Try adjusting your filters to see more results."
                  : "When dispatch requests come in, you'll see them here for assignment."
              }
              action={
                statusFilter === "all" && priorityFilter === "all" && !searchQuery
                  ? { label: "Create Job", onClick: () => setNewJobOpen(true) }
                  : undefined
              }
            />
          ) : viewMode === "table" ? (
            <DispatchCommandTable
              jobs={filteredJobs}
              onAssign={handleAssign}
              onUpdateStatus={handleUpdateStatus}
              onCall={handleCall}
              onViewDetails={handleViewDetails}
            />
          ) : (
            <AnimatedList className="grid gap-4 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
              {filteredJobs.map((job) => (
                <AnimatedListItem key={job.id}>
                  <DispatchJobCard
                    job={job}
                    onAssign={handleAssign}
                    onUpdateStatus={handleUpdateStatus}
                    onCall={handleCall}
                  />
                </AnimatedListItem>
              ))}
            </AnimatedList>
          )}
        </div>

        {/* Job Details Sheet */}
        <DispatchJobDetailsSheet
          job={selectedJob}
          open={detailsOpen}
          onOpenChange={setDetailsOpen}
          onAssign={handleAssign}
          onUpdateStatus={handleUpdateStatus}
          onCall={handleCall}
        />

        {/* Assign Job Dialog */}
        <AssignJobDialog
          job={jobToAssign}
          open={assignDialogOpen}
          onOpenChange={setAssignDialogOpen}
          onAssign={handleAssignSubmit}
          isLoading={updateJobMutation.isPending}
        />

        {/* New Job Dialog */}
        <Dialog open={newJobOpen} onOpenChange={setNewJobOpen}>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>Create New Job</DialogTitle>
            </DialogHeader>
            <div className="space-y-4 py-2">
              <div className="space-y-2">
                <Label htmlFor="job-customer">Customer Name</Label>
                <Input id="job-customer" placeholder="Customer name" value={newJob.customer_name} onChange={(e) => setNewJob(prev => ({ ...prev, customer_name: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <Label htmlFor="job-pickup">Pickup Address</Label>
                <Input id="job-pickup" placeholder="123 Main St" value={newJob.pickup_address} onChange={(e) => setNewJob(prev => ({ ...prev, pickup_address: e.target.value }))} />
              </div>
              <div className="space-y-2">
                <Label htmlFor="job-dropoff">Dropoff Address (optional)</Label>
                <Input id="job-dropoff" placeholder="456 Oak Ave" value={newJob.dropoff_address} onChange={(e) => setNewJob(prev => ({ ...prev, dropoff_address: e.target.value }))} />
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-2">
                  <Label htmlFor="job-type">Job Type</Label>
                  <Input id="job-type" placeholder="Tow, Lockout, etc." value={newJob.job_type} onChange={(e) => setNewJob(prev => ({ ...prev, job_type: e.target.value }))} />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="job-priority">Priority</Label>
                  <Select value={newJob.priority} onValueChange={(v) => setNewJob(prev => ({ ...prev, priority: v }))}>
                    <SelectTrigger id="job-priority"><SelectValue /></SelectTrigger>
                    <SelectContent>
                      <SelectItem value="low">Low</SelectItem>
                      <SelectItem value="normal">Normal</SelectItem>
                      <SelectItem value="high">High</SelectItem>
                      <SelectItem value="emergency">Emergency</SelectItem>
                    </SelectContent>
                  </Select>
                </div>
              </div>
              <div className="space-y-2">
                <Label htmlFor="job-desc">Description</Label>
                <Textarea id="job-desc" placeholder="Job details..." rows={3} value={newJob.description} onChange={(e) => setNewJob(prev => ({ ...prev, description: e.target.value }))} />
              </div>
            </div>
            <DialogFooter>
              <Button variant="outline" onClick={() => setNewJobOpen(false)}>Cancel</Button>
              <Button onClick={handleCreateJob} disabled={isCreatingJob || !newJob.customer_name.trim()}>
                {isCreatingJob ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : null}
                Create Job
              </Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>
      </PageContainer>
    </TooltipProvider>
  );
}

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import {
  FileText,
  Plus,
  Search,
  MoreHorizontal,
  Send,
  Eye,
  Trash2,
  Copy,
  Download,
  Loader2,
  DollarSign,
  Clock,
  CheckCircle2,
  XCircle,
  AlertCircle,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { format, formatDistanceToNow } from "date-fns";
import { useEstimates, EstimateWithCustomer } from "@/hooks/useEstimates";
import { EstimateBuilder } from "@/components/estimates/EstimateBuilder";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { useModuleRequired } from "@/hooks/useModuleRequired";
import { Label } from "@/components/ui/label";

const statusConfig: Record<string, { label: string; color: string; icon: typeof CheckCircle2 }> = {
  draft: { label: "Draft", color: "bg-muted text-muted-foreground", icon: FileText },
  sent: { label: "Sent", color: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400", icon: Send },
  viewed: { label: "Viewed", color: "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400", icon: Eye },
  accepted: { label: "Accepted", color: "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400", icon: CheckCircle2 },
  declined: { label: "Declined", color: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400", icon: XCircle },
  expired: { label: "Expired", color: "bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400", icon: AlertCircle },
  converted: { label: "Converted", color: "bg-emerald-100 text-emerald-700 dark:bg-emerald-900/30 dark:text-emerald-400", icon: CheckCircle2 },
};

function formatCurrency(cents: number | null): string {
  if (cents === null) return "—";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);
}

function EstimateListItem({
  estimate,
  onEdit,
  onSend,
  onDuplicate,
  onDelete,
  onDownloadPdf,
}: {
  estimate: EstimateWithCustomer;
  onEdit: () => void;
  onSend: () => void;
  onDuplicate: () => void;
  onDelete: () => void;
  onDownloadPdf: () => void;
}) {
  const status = statusConfig[estimate.status] || statusConfig.draft;
  const StatusIcon = status.icon;

  return (
    <div className="flex items-center justify-between p-4 rounded-lg border hover:bg-muted/50 transition-colors">
      <div className="flex items-center gap-4 flex-1 min-w-0">
        <div className="flex h-12 w-12 items-center justify-center rounded-lg bg-primary/10 flex-shrink-0">
          <FileText className="h-6 w-6 text-primary" />
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <p className="font-medium truncate">
              {estimate.title || estimate.estimate_number}
            </p>
            <Badge className={cn("flex-shrink-0", status.color)}>
              <StatusIcon className="h-3 w-3 mr-1" />
              {status.label}
            </Badge>
          </div>
          <p className="text-sm text-muted-foreground truncate">
            {estimate.customer?.full_name || "No customer"} •{" "}
            {estimate.estimate_number}
          </p>
          <p className="text-xs text-muted-foreground mt-1">
            Created {formatDistanceToNow(new Date(estimate.created_at), { addSuffix: true })}
            {estimate.valid_until && (
              <> • Valid until {format(new Date(estimate.valid_until), "MMM d, yyyy")}</>
            )}
          </p>
        </div>
      </div>
      <div className="flex items-center gap-4">
        <div className="text-right">
          <p className="font-bold text-lg">{formatCurrency(estimate.total_cents)}</p>
          {estimate.line_items && (
            <p className="text-xs text-muted-foreground">
              {estimate.line_items.length} item{estimate.line_items.length !== 1 ? "s" : ""}
            </p>
          )}
        </div>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="icon">
              <MoreHorizontal className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={onEdit}>
              <FileText className="h-4 w-4 mr-2" />
              Edit
            </DropdownMenuItem>
            {estimate.status === "draft" && (
              <DropdownMenuItem onClick={onSend}>
                <Send className="h-4 w-4 mr-2" />
                Send to Customer
              </DropdownMenuItem>
            )}
            <DropdownMenuItem onClick={onDuplicate}>
              <Copy className="h-4 w-4 mr-2" />
              Duplicate
            </DropdownMenuItem>
            <DropdownMenuItem onClick={onDownloadPdf}>
              <Download className="h-4 w-4 mr-2" />
              Download PDF
            </DropdownMenuItem>
            <DropdownMenuItem onClick={onDelete} className="text-destructive">
              <Trash2 className="h-4 w-4 mr-2" />
              Delete
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </div>
  );
}

export default function EstimatesPage() {
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["estimates", "phone_quotes"]);
  const { estimates, isLoading, stats, createEstimate, sendEstimate, deleteEstimate } = useEstimates();
  const { toast } = useToast();
  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [builderOpen, setBuilderOpen] = useState(false);
  const [editingEstimate, setEditingEstimate] = useState<EstimateWithCustomer | null>(null);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [estimateToDelete, setEstimateToDelete] = useState<string | null>(null);
  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
  const [emailDialogEstimate, setEmailDialogEstimate] = useState<EstimateWithCustomer | null>(null);
  const [emailInput, setEmailInput] = useState("");
  const [emailSending, setEmailSending] = useState(false);

  // Filter estimates
  const filteredEstimates = estimates.filter((estimate) => {
    const matchesSearch =
      !searchQuery ||
      estimate.estimate_number.toLowerCase().includes(searchQuery.toLowerCase()) ||
      estimate.title?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      estimate.customer?.full_name?.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesStatus = !statusFilter || estimate.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  const handleCreateNew = () => {
    setEditingEstimate(null);
    setBuilderOpen(true);
  };

  const handleEdit = (estimate: EstimateWithCustomer) => {
    setEditingEstimate(estimate);
    setBuilderOpen(true);
  };

  const handleSend = async (estimate: EstimateWithCustomer) => {
    if (!estimate.customer?.email) {
      // Open email dialog to collect the recipient email
      setEmailDialogEstimate(estimate);
      setEmailInput("");
      setEmailDialogOpen(true);
      return;
    }
    await sendEstimate.mutateAsync({
      estimateId: estimate.id,
      email: estimate.customer.email,
    });
  };

  const handleEmailDialogSend = async () => {
    if (!emailDialogEstimate || !emailInput) return;
    setEmailSending(true);
    try {
      const { data, error } = await supabase.functions.invoke("estimate-send-email", {
        body: {
          estimate_id: emailDialogEstimate.id,
          email: emailInput,
        },
      });
      if (error) throw error;
      if (!data?.success) throw new Error(data?.error || "Failed to send");
      toast({ title: "Estimate sent", description: `Email sent to ${emailInput}` });
      setEmailDialogOpen(false);
      setEmailDialogEstimate(null);
      setEmailInput("");
    } catch (err) {
      toast({ title: "Error sending estimate", description: err instanceof Error ? err.message : "Unknown error", variant: "destructive" });
    } finally {
      setEmailSending(false);
    }
  };

  const handleDuplicate = async (estimate: EstimateWithCustomer) => {
    await createEstimate.mutateAsync({
      customer_id: estimate.customer_id || undefined,
      title: `${estimate.title || estimate.estimate_number} (Copy)`,
      line_items: estimate.line_items || [],
      tax_rate_percent: estimate.tax_rate_percent || undefined,
      valid_until: estimate.valid_until || undefined,
      internal_notes: estimate.internal_notes || undefined,
      customer_notes: estimate.customer_notes || undefined,
      terms_and_conditions: estimate.terms_and_conditions || undefined,
    });
  };

  const handleDelete = (estimateId: string) => {
    setEstimateToDelete(estimateId);
    setDeleteDialogOpen(true);
  };

  const confirmDelete = async () => {
    if (estimateToDelete) {
      await deleteEstimate.mutateAsync(estimateToDelete);
      setDeleteDialogOpen(false);
      setEstimateToDelete(null);
    }
  };

  const handleDownloadPdf = async (estimate: EstimateWithCustomer) => {
    try {
      toast({ title: "Generating PDF..." });
      const { data, error } = await supabase.functions.invoke("estimate-generate-pdf", {
        body: { estimate_id: estimate.id },
      });
      if (error) throw error;
      if (data?.url) {
        window.open(data.url, "_blank");
      } else if (data?.pdf_base64) {
        const link = document.createElement("a");
        link.href = `data:application/pdf;base64,${data.pdf_base64}`;
        link.download = `${estimate.estimate_number}.pdf`;
        link.click();
      } else {
        toast({ title: "PDF generated", description: "Check your downloads." });
      }
    } catch (err: any) {
      toast({ variant: "destructive", title: "PDF generation failed", description: err.message || "Please try again." });
    }
  };

  if (moduleLoading || !isAllowed) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <>
      <PageContainer maxWidth="xl">
        <PageHeader
          icon={<FileText className="h-5 w-5" />}
          title="Estimates & Proposals"
          description="Create professional quotes with Good-Better-Best pricing options"
          action={
            <Button onClick={handleCreateNew}>
              <Plus className="h-4 w-4 mr-2" />
              New Estimate
            </Button>
          }
        />

        {/* Stats Cards */}
        <div className="grid gap-4 md:grid-cols-4 mb-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Estimates</CardTitle>
              <FileText className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{stats.total}</div>
              <p className="text-xs text-muted-foreground">
                {stats.draft} drafts, {stats.sent} sent
              </p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Awaiting Response</CardTitle>
              <Clock className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{stats.sent + stats.viewed}</div>
              <p className="text-xs text-muted-foreground">
                {stats.viewed} viewed by customer
              </p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Accepted</CardTitle>
              <CheckCircle2 className="h-4 w-4 text-green-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{stats.accepted}</div>
              <p className="text-xs text-muted-foreground">
                {stats.declined} declined
              </p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Value Won</CardTitle>
              <DollarSign className="h-4 w-4 text-green-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatCurrency(stats.totalValue)}</div>
              <p className="text-xs text-muted-foreground">From accepted estimates</p>
            </CardContent>
          </Card>
        </div>

        {/* Filters */}
        <div className="flex items-center gap-4 mb-4">
          <div className="relative flex-1 max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search estimates..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9"
            />
          </div>
          <div className="flex items-center gap-2">
            <Button
              variant={statusFilter === null ? "secondary" : "ghost"}
              size="sm"
              onClick={() => setStatusFilter(null)}
            >
              All
            </Button>
            <Button
              variant={statusFilter === "draft" ? "secondary" : "ghost"}
              size="sm"
              onClick={() => setStatusFilter("draft")}
            >
              Drafts
            </Button>
            <Button
              variant={statusFilter === "sent" ? "secondary" : "ghost"}
              size="sm"
              onClick={() => setStatusFilter("sent")}
            >
              Sent
            </Button>
            <Button
              variant={statusFilter === "accepted" ? "secondary" : "ghost"}
              size="sm"
              onClick={() => setStatusFilter("accepted")}
            >
              Accepted
            </Button>
          </div>
        </div>

        {/* Estimates List */}
        <Card>
          <CardContent className="p-0">
            {filteredEstimates.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-12 text-center">
                <FileText className="h-12 w-12 text-muted-foreground/50 mb-4" />
                <h3 className="text-lg font-medium">No estimates yet</h3>
                <p className="text-muted-foreground mb-4">
                  Create your first estimate to start sending professional quotes to customers.
                </p>
                <Button onClick={handleCreateNew}>
                  <Plus className="h-4 w-4 mr-2" />
                  Create Estimate
                </Button>
              </div>
            ) : (
              <div className="divide-y">
                {filteredEstimates.map((estimate) => (
                  <EstimateListItem
                    key={estimate.id}
                    estimate={estimate}
                    onEdit={() => handleEdit(estimate)}
                    onSend={() => handleSend(estimate)}
                    onDuplicate={() => handleDuplicate(estimate)}
                    onDelete={() => handleDelete(estimate.id)}
                    onDownloadPdf={() => handleDownloadPdf(estimate)}
                  />
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </PageContainer>

      {/* Estimate Builder Dialog */}
      <Dialog open={builderOpen} onOpenChange={setBuilderOpen}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>
              {editingEstimate ? "Edit Estimate" : "Create New Estimate"}
            </DialogTitle>
            <DialogDescription>
              Build a professional estimate with line items and optional Good-Better-Best pricing.
            </DialogDescription>
          </DialogHeader>
          <EstimateBuilder
            estimate={editingEstimate}
            onSave={() => setBuilderOpen(false)}
            onCancel={() => setBuilderOpen(false)}
          />
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Delete Estimate</DialogTitle>
            <DialogDescription>
              Are you sure you want to delete this estimate? This action cannot be undone.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDeleteDialogOpen(false)}>
              Cancel
            </Button>
            <Button variant="destructive" onClick={confirmDelete}>
              Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Email Share Dialog */}
      <Dialog open={emailDialogOpen} onOpenChange={setEmailDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Share Estimate via Email</DialogTitle>
            <DialogDescription>
              Enter the recipient's email address to send this estimate.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label htmlFor="share-email">Email Address</Label>
              <Input
                id="share-email"
                type="email"
                placeholder="customer@example.com"
                value={emailInput}
                onChange={(e) => setEmailInput(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && emailInput) handleEmailDialogSend();
                }}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setEmailDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleEmailDialogSend} disabled={!emailInput || emailSending}>
              {emailSending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              <Send className="h-4 w-4 mr-2" />
              Send
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState } from "react";
import { useNavigate, Navigate, Link } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { useSubscription } from "@/hooks/useSubscription";
import { useAIReadinessV2 } from "@/hooks/useAIReadinessV2";
import { AIReadinessPanel } from "@/components/dashboard/AIReadinessPanel";
import { ScheduleConnectionCard } from "@/components/schedule/ScheduleConnectionCard";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { 
  MessageSquare, Phone, Sparkles, Check, ArrowRight, Loader2, 
  Zap, Clock, Bot, Shield, ChevronRight, ChevronLeft, AlertTriangle
} from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useIsAgencyManagedTenant } from "@/hooks/useIsAgencyManagedTenant";
import { cn } from "@/lib/utils";
import {
  TIERS,
  TRIAL_CONFIG,
  getLadderStepsForTier,
  getDefaultStepForTier,
  formatPrice,
  type PlanTier,
  type PlanSku,
  type TierInfo,
} from "@/config/pricing";

const getIcon = (iconName: TierInfo["icon"]) => {
  switch (iconName) {
    case "MessageSquare":
      return MessageSquare;
    case "Phone":
      return Phone;
    case "Sparkles":
      return Sparkles;
  }
};

export default function GoLivePage() {
  const { user, tenant, refreshTenant, isSuperAdmin } = useAuth();
  const { createSubscription, loading: subLoading } = useSubscription(tenant?.id || null, isSuperAdmin);
  const { score, canGoLive, p0Flags, isReady } = useAIReadinessV2();
  const [step, setStep] = useState<"tier" | "usage">("tier");
  const [selectedTier, setSelectedTier] = useState<PlanTier | null>(null);
  const [selectedSku, setSelectedSku] = useState<PlanSku | null>(null);
  const [processing, setProcessing] = useState(false);
  const navigate = useNavigate();
  const { toast } = useToast();

  const { data: isAgencyManaged } = useIsAgencyManagedTenant(tenant?.id || null);

  if (!user) return <Navigate to="/login" replace />;

  // Go-live is blocked unless canGoLive is true — relaxed for agency-managed tenants
  const goLiveBlocked = isAgencyManaged ? false : !canGoLive;

  const handleTierSelect = (tier: PlanTier) => {
    setSelectedTier(tier);
    const defaultStep = getDefaultStepForTier(tier);
    if (defaultStep) {
      setSelectedSku(defaultStep.sku);
    }
    setStep("usage");
  };

  const handleBack = () => {
    setStep("tier");
  };

  const handleConfirm = async () => {
    if (!selectedSku || processing) return;

    // Block if readiness requirements not met
    if (goLiveBlocked) {
      toast({
        variant: "destructive",
        title: "Cannot Go Live Yet",
        description: `Please fix ${p0Flags.length} blocking issue${p0Flags.length > 1 ? 's' : ''} first. Scroll up to see details.`,
      });
      return;
    }

    setProcessing(true);

    try {
      // Create Stripe Checkout Session via edge function
      const { data, error } = await supabase.functions.invoke("create-checkout-session", {
        body: { plan_sku: selectedSku },
      });

      if (error) throw new Error(error.message || "Failed to create checkout session");
      if (!data?.checkout_url) throw new Error("No checkout URL returned");

      // Redirect to Stripe Checkout
      window.location.href = data.checkout_url;
    } catch (error: any) {
      console.error("Checkout error:", error);
      toast({
        variant: "destructive",
        title: "Failed to start checkout",
        description: error.message || "Please try again.",
      });
      setProcessing(false);
    }
  };

  const ladderSteps = selectedTier ? getLadderStepsForTier(selectedTier) : [];
  const selectedStep = ladderSteps.find((s) => s.sku === selectedSku);
  const tierInfo = selectedTier ? TIERS.find((t) => t.tier === selectedTier) : null;

  return (
    <div className="min-h-screen bg-background py-12 px-4">
      <div className="max-w-5xl mx-auto">
        {/* Header */}
        <div className="text-center mb-14">
          <h1 className="text-2xl font-bold tracking-tight mb-2">
            {step === "tier" ? "Choose Your Plan" : "Select Usage Level"}
          </h1>
          <p className="text-sm text-muted-foreground max-w-2xl mx-auto">
            {step === "tier"
              ? "Select your plan to get started."
              : `Choose how much usage you need for ${tierInfo?.displayName}.`}
          </p>
        </div>

        {/* AI Readiness Panel - Full version with P0/P1 checklists */}
        <div className="mb-8">
          <AIReadinessPanel alwaysShow={true} />
        </div>

        {/* Schedule Connection Card */}
        <div className="mb-8">
          <ScheduleConnectionCard />
        </div>
        
        {/* Blocking Message */}
        {goLiveBlocked && (
          <Card className="mb-8 border-destructive/50 bg-card/60 backdrop-blur-sm">
            <CardContent className="p-4">
              <div className="flex items-center gap-3">
                <AlertTriangle className="h-5 w-5 text-destructive" />
                <div>
                  <p className="font-medium text-destructive">
                    Finish {p0Flags.length} item{p0Flags.length > 1 ? 's' : ''} to go live
                  </p>
                  <p className="text-sm text-muted-foreground">
                    Fix the blocking issues above before activating your plan.
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>
        )}

        <div className="mb-6" />

        {/* Step 1: Tier Selection */}
        {step === "tier" && (
          <div className="grid md:grid-cols-3 gap-6">
            {TIERS.map((tier) => {
              const Icon = getIcon(tier.icon);

              return (
                <Card
                  key={tier.tier}
                  className={cn(
                    "relative transition-all duration-150 cursor-pointer hover:border-primary/50 bg-card/60 backdrop-blur-sm card-interactive",
                    tier.highlight ? 'border-primary glow-primary-sm glow-primary scale-[1.02]' : 'border-border/30'
                  )}
                  onClick={() => handleTierSelect(tier.tier)}
                >
                  {tier.highlight && (
                    <div className="absolute -top-3 left-1/2 -translate-x-1/2">
                      <Badge className="bg-primary text-primary-foreground glow-primary-sm">
                        Most Popular
                      </Badge>
                    </div>
                  )}

                  <CardHeader className="pb-4">
                    <div className={cn(
                      "flex h-12 w-12 items-center justify-center rounded-xl mb-3",
                      tier.highlight ? 'bg-primary text-primary-foreground glow-primary-sm' : 'bg-primary/10 text-primary border border-primary/15'
                    )}>
                      <Icon className="h-6 w-6" />
                    </div>
                    <CardTitle className="text-xl">{tier.displayName}</CardTitle>
                    <CardDescription>{tier.description}</CardDescription>
                  </CardHeader>

                  <CardContent className="space-y-6">
                    {/* Price */}
                    <div>
                      <div className="text-sm text-muted-foreground mb-1">Starting at</div>
                      <div className="flex items-baseline gap-1">
                        <span className="text-4xl font-bold">{formatPrice(tier.startingPrice)}</span>
                        <span className="text-muted-foreground">/month</span>
                      </div>
                    </div>

                    {/* Features */}
                    <ul className="space-y-3">
                      {tier.features.slice(0, 4).map((feature, i) => (
                        <li key={i} className="flex items-start gap-2">
                          <Check className="h-5 w-5 text-primary shrink-0 mt-0.5" />
                          <span className="text-sm">{feature}</span>
                        </li>
                      ))}
                    </ul>

                    {/* CTA */}
                    <Button 
                      className="w-full" 
                      variant={tier.highlight ? "default" : "outline"}
                    >
                      Select {tier.displayName}
                      <ChevronRight className="ml-2 h-4 w-4" />
                    </Button>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        )}

        {/* Step 2: Usage Level Selection */}
        {step === "usage" && tierInfo && (
          <div className="max-w-2xl mx-auto">
            <Button variant="ghost" onClick={handleBack} className="mb-6">
              <ChevronLeft className="mr-2 h-4 w-4" />
              Back to plans
            </Button>

            <Card>
              <CardHeader>
                <div className="flex items-center gap-3 mb-2">
                  {(() => {
                    const Icon = getIcon(tierInfo.icon);
                    return (
                      <div className={cn(
                        "flex h-10 w-10 items-center justify-center rounded-xl",
                        tierInfo.highlight ? 'bg-primary text-primary-foreground glow-primary-sm' : 'bg-primary/10 text-primary border border-primary/15'
                      )}>
                        <Icon className="h-5 w-5" />
                      </div>
                    );
                  })()}
                  <div>
                    <CardTitle>{tierInfo.displayName}</CardTitle>
                    <CardDescription>{tierInfo.shortDescription}</CardDescription>
                  </div>
                </div>
              </CardHeader>
              <CardContent className="space-y-6">
                <div>
                  <Label className="text-base font-medium mb-4 block">
                    Choose your usage level
                  </Label>
                  <RadioGroup
                    value={selectedSku || undefined}
                    onValueChange={(value) => setSelectedSku(value as PlanSku)}
                    className="space-y-3"
                  >
                    {ladderSteps.map((ladderStep) => (
                      <div
                        key={ladderStep.sku}
                        className={cn(
                          "flex items-center justify-between p-4 rounded-xl border cursor-pointer transition-all duration-150 bg-card/60 backdrop-blur-sm",
                          selectedSku === ladderStep.sku ? "border-primary bg-primary/5 shadow-sm" : "border-border/30 hover:border-primary/50"
                        )}
                        onClick={() => setSelectedSku(ladderStep.sku)}
                      >
                        <div className="flex items-center gap-3">
                          <RadioGroupItem value={ladderStep.sku} id={ladderStep.sku} />
                          <Label htmlFor={ladderStep.sku} className="cursor-pointer">
                            <div className="font-medium">{ladderStep.name}</div>
                            <div className="text-sm text-muted-foreground">
                              {ladderStep.includedMinutes && `${ladderStep.includedMinutes.toLocaleString()} minutes`}
                              {ladderStep.includedMinutes && ladderStep.includedSmsSegments && " + "}
                              {ladderStep.includedSmsSegments && `${ladderStep.includedSmsSegments.toLocaleString()} SMS segments`}
                              {" included"}
                            </div>
                          </Label>
                        </div>
                        <div className="text-right">
                          <div className="font-bold text-lg">{formatPrice(ladderStep.price)}</div>
                          <div className="text-sm text-muted-foreground">/month</div>
                        </div>
                      </div>
                    ))}
                  </RadioGroup>
                </div>

                {selectedStep && (
                  <div className="bg-card/60 backdrop-blur-sm border border-border/20 rounded-xl p-4 space-y-2 text-sm card-interactive">
                    <div className="font-medium">Overage rates:</div>
                    <div className="text-muted-foreground">
                      {selectedStep.overageMinuteRate && (
                        <span>${selectedStep.overageMinuteRate}/minute over included</span>
                      )}
                      {selectedStep.overageMinuteRate && selectedStep.overageSmsRate && " • "}
                      {selectedStep.overageSmsRate && (
                        <span>${selectedStep.overageSmsRate}/SMS segment over included</span>
                      )}
                    </div>
                  </div>
                )}

                <Button 
                  className="w-full" 
                  size="lg"
                  onClick={handleConfirm}
                  disabled={processing || !selectedSku || goLiveBlocked}
                  variant={goLiveBlocked ? "secondary" : "default"}
                >
                  {processing ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                      Setting up...
                    </>
                  ) : goLiveBlocked ? (
                    <>
                      <AlertTriangle className="mr-2 h-4 w-4" />
                      Fix Issues First
                    </>
                  ) : (
                    <>
                      Start {TRIAL_CONFIG.duration_days}-Day Free Trial
                      <ArrowRight className="ml-2 h-4 w-4" />
                    </>
                  )}
                </Button>
                {selectedStep && !goLiveBlocked && (
                  <p className="text-xs text-center text-muted-foreground">
                    {TRIAL_CONFIG.duration_days}-day free trial, then {formatPrice(selectedStep.price)}/month
                  </p>
                )}
                {goLiveBlocked && (
                  <p className="text-xs text-center text-muted-foreground">
                    Scroll up to see what needs to be fixed
                  </p>
                )}
              </CardContent>
            </Card>
          </div>
        )}

        {/* Footer note */}
        <p className="text-center text-sm text-muted-foreground mt-8">
          {TRIAL_CONFIG.duration_days}-day free trial with {TRIAL_CONFIG.included_minutes} minutes included. Cancel anytime.
          <br />
          Your card will be charged after the trial ends. By continuing, you agree to our Terms of Service.
        </p>
      </div>
    </div>
  );
}

