    forModes: ["service", "medical"]
  },
  { 
    id: "dispatch", 
    label: "Dispatch & Jobs", 
    icon: Truck,
    description: "Handle service requests and job assignments",
    requiredModules: ["dispatch_queue"],
    forModes: ["dispatch"]
  },
  { 
    id: "food", 
    label: "Orders & Menu", 
    icon: UtensilsCrossed,
    description: "Take orders, manage menu, and handle reservations",
