    forModes: ["food"]
  },
  { 
    id: "medical", 
    label: "Medical Intake", 
    icon: Stethoscope,
    description: "Patient intake, HIPAA compliance, and scheduling",
    requiredModules: ["medical_intake"],
    forModes: ["medical"]
  },
  { 
    id: "business-brain", 
    label: "Business Brain", 
    icon: Brain,
    description: "Train your AI with your business knowledge"
  },
  { 
    id: "automations", 
    label: "Automations", 
    icon: Zap,
    description: "Set up automatic workflows and triggers"
  },
  { 
    id: "settings", 
    label: "Settings & Team", 
    icon: Settings,
    description: "Configure your account and manage team"
  }
];

export default function HelpCenterPage() {
  const { businessMode, enabledModules } = useTenantConfig();
  const { tenant } = useAuth();
  const [searchQuery, setSearchQuery] = useState("");
  const [activeCategory, setActiveCategory] = useState("getting-started");

  // Filter categories based on business mode and enabled modules
  const filteredCategories = allCategories.filter(cat => {
    // If no mode requirement, always show
    if (!cat.forModes && !cat.requiredModules) return true;
    
    // Check mode-specific categories
    if (cat.forModes && !cat.forModes.includes(businessMode)) return false;
    
    // Check module requirements
    if (cat.requiredModules) {
      return cat.requiredModules.some(mod => enabledModules.includes(mod));
    }
    
    return true;
  });

  // Mode-specific welcome message
  const getModeDescription = () => {
    switch (businessMode) {
      case "service":
        return "Learn how to manage bookings, handle leads, and let your AI take care of missed calls.";
      case "dispatch":
        return "Learn how to manage dispatch jobs, prioritize urgent requests, and automate customer communication.";
      case "food":
        return "Learn how to take orders, manage your menu, handle reservations, and automate order confirmations.";
      case "medical":
        return "Learn how to handle patient intake, schedule appointments, and maintain HIPAA compliance.";
      case "sales":
        return "Learn how to manage prospects, schedule showroom appointments, and let your AI qualify every lead.";
      default:
        return "Learn how to manage leads, handle inquiries, and let your AI capture every opportunity.";
    }
  };

  return (
    <div className="p-4 md:p-6 max-w-5xl mx-auto">
      {/* Header */}
      <div className="text-center mb-10">
        <div className="inline-flex items-center justify-center h-14 w-14 rounded-2xl bg-primary/10 mb-4">
          <HelpCircle className="h-7 w-7 text-primary" />
        </div>
        <h1 className="text-2xl md:text-3xl font-bold tracking-tight mb-2">Help Center</h1>
        <p className="text-muted-foreground max-w-xl mx-auto">
          {getModeDescription()}
        </p>
        <Badge variant="secondary" className="mt-3">
          {businessMode.charAt(0).toUpperCase() + businessMode.slice(1)} Mode
        </Badge>
      </div>

      {/* Search */}
      <div className="relative max-w-md mx-auto mb-8">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
        <Input
          placeholder="Search help articles..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="pl-10"
        />
      </div>

      {/* Category Tabs */}
      <Tabs value={activeCategory} onValueChange={setActiveCategory} className="w-full">
        <div className="overflow-x-auto -mx-4 px-4 mb-6">
          <TabsList className="h-auto flex-wrap justify-start gap-2 bg-transparent p-0">
            {filteredCategories.map((cat) => {
              const Icon = cat.icon;
              return (
                <TabsTrigger
                  key={cat.id}
                  value={cat.id}
                  className="flex items-center gap-2 px-4 py-2 data-[state=active]:bg-primary data-[state=active]:text-primary-foreground rounded-full border border-border/30 bg-card/60 backdrop-blur-sm card-interactive transition-all duration-150"
                >
                  <Icon className="h-4 w-4" />
                  <span className="hidden sm:inline">{cat.label}</span>
                </TabsTrigger>
              );
            })}
          </TabsList>
        </div>

        {/* Content Panels */}
        <TabsContent value="getting-started" className="mt-0">
          <HelpGuideDashboard mode={businessMode} searchQuery={searchQuery} />
        </TabsContent>

        <TabsContent value="phone-setup" className="mt-0">
          <HelpGuidePhone searchQuery={searchQuery} />
        </TabsContent>

        <TabsContent value="bookings" className="mt-0">
          <HelpGuideBookings mode={businessMode} searchQuery={searchQuery} />
        </TabsContent>

        <TabsContent value="dispatch" className="mt-0">
          <HelpGuideDispatch searchQuery={searchQuery} />
        </TabsContent>

        <TabsContent value="food" className="mt-0">
          <HelpGuideFood searchQuery={searchQuery} />
        </TabsContent>

        <TabsContent value="medical" className="mt-0">
          <HelpGuideMedical searchQuery={searchQuery} />
        </TabsContent>

        <TabsContent value="business-brain" className="mt-0">
          <HelpGuideBrain mode={businessMode} searchQuery={searchQuery} />
        </TabsContent>

        <TabsContent value="automations" className="mt-0">
          <HelpGuideWorkflows mode={businessMode} searchQuery={searchQuery} />
        </TabsContent>

        <TabsContent value="settings" className="mt-0">
          <HelpGuideSettings searchQuery={searchQuery} />
        </TabsContent>
      </Tabs>
    </div>
  );
}

/**
 * ImpoundLotPage - Main impound lot inventory management
 * 
 * Features:
 * - View all vehicles in lot with search/filter
 * - Quick-add form for drivers (tablet-friendly)
 * - Bulk CSV import
 * - Vehicle status management (in_lot, pending_release, released)
 * - Fee tracking and release processing
 */

import { useState, useMemo } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useModuleRequired } from "@/hooks/useModuleRequired";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { EmptyState } from "@/components/ui/empty-state";
import {
  Warehouse,
  Plus,
  Upload,
  Search,
  Loader2,
  Car,
  Clock,
  DollarSign,
  CheckCircle2,
} from "lucide-react";
import { ImpoundVehicleCard } from "@/components/impound/ImpoundVehicleCard";
import { ImpoundQuickAddDialog } from "@/components/impound/ImpoundQuickAddDialog";
import { ImpoundBulkImportDialog } from "@/components/impound/ImpoundBulkImportDialog";
import { ImpoundVehicleDetailDialog } from "@/components/impound/ImpoundVehicleDetailDialog";

type ImpoundVehicle = {
  id: string;
  tenant_id: string;
  lot_id: string | null;
  license_plate: string | null;
  license_plate_state: string | null;
  vin: string | null;
  vehicle_year: string | null;
  vehicle_make: string | null;
  vehicle_model: string | null;
  vehicle_color: string | null;
  towed_from_address: string | null;
  towed_at: string;
  tow_reason: string | null;
  dispatch_job_id: string | null;
  status: string | null;
  base_tow_fee_cents: number | null;
  storage_fee_daily_cents: number | null;
  days_stored: number | null;
  total_fees_cents: number | null;
  admin_fee_cents: number | null;
  gate_fee_cents: number | null;
  released_at: string | null;
  released_to_name: string | null;
  released_to_phone: string | null;
  release_notes: string | null;
  payment_method: string | null;
  notes: string | null;
  created_at: string | null;
  impound_lots?: { name: string } | null;
};

export default function ImpoundLotPage() {
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["dispatch_queue"]);
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  
  const [statusFilter, setStatusFilter] = useState<string>("in_lot");
  const [searchQuery, setSearchQuery] = useState("");
  const [quickAddOpen, setQuickAddOpen] = useState(false);
  const [bulkImportOpen, setBulkImportOpen] = useState(false);
  const [selectedVehicle, setSelectedVehicle] = useState<ImpoundVehicle | null>(null);

  // Fetch vehicles
  const { data: vehicles, isLoading } = useQuery({
    queryKey: ["impound-vehicles", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("impound_vehicles")
        .select("*, impound_lots(name)")
        .eq("tenant_id", tenant.id)
        .order("towed_at", { ascending: false });

      if (error) throw error;
      return (data || []) as ImpoundVehicle[];
    },
    enabled: !!tenant?.id,
  });

  // Fetch lots for default selection
  const { data: lots } = useQuery({
    queryKey: ["impound-lots", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("impound_lots")
        .select("*")
        .eq("tenant_id", tenant.id)
        .eq("is_active", true);

      if (error) throw error;
      return data || [];
    },
    enabled: !!tenant?.id,
  });

  // Filter vehicles
  const filteredVehicles = useMemo(() => {
    if (!vehicles) return [];

    return vehicles.filter((vehicle) => {
      // Status filter
      if (statusFilter !== "all" && vehicle.status !== statusFilter) {
        return false;
      }

      // Search filter
      if (searchQuery) {
        const query = searchQuery.toLowerCase();
        const plate = vehicle.license_plate?.toLowerCase() || "";
        const vin = vehicle.vin?.toLowerCase() || "";
        const make = vehicle.vehicle_make?.toLowerCase() || "";
        const model = vehicle.vehicle_model?.toLowerCase() || "";
        const color = vehicle.vehicle_color?.toLowerCase() || "";
        return (
          plate.includes(query) ||
          vin.includes(query) ||
          make.includes(query) ||
          model.includes(query) ||
          color.includes(query)
        );
      }

      return true;
    });
  }, [vehicles, statusFilter, searchQuery]);

  // Stats
  const stats = useMemo(() => {
    if (!vehicles) return { inLot: 0, pendingRelease: 0, releasedToday: 0, totalFees: 0 };
    
    const today = new Date().toDateString();
    const inLot = vehicles.filter(v => v.status === "in_lot").length;
    const pendingRelease = vehicles.filter(v => v.status === "pending_release").length;
    const releasedToday = vehicles.filter(v => 
      v.status === "released" && 
      v.released_at && 
      new Date(v.released_at).toDateString() === today
    ).length;
    const totalFees = vehicles
      .filter(v => v.status === "in_lot" || v.status === "pending_release")
      .reduce((sum, v) => sum + (v.total_fees_cents || 0), 0);

    return { inLot, pendingRelease, releasedToday, totalFees };
  }, [vehicles]);

  const handleVehicleClick = (vehicle: ImpoundVehicle) => {
    setSelectedVehicle(vehicle);
  };

  const handleRefresh = () => {
    queryClient.invalidateQueries({ queryKey: ["impound-vehicles"] });
  };

  if (moduleLoading || !isAllowed) {
    return (
      <div className="p-6 flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="p-6 flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <PageContainer maxWidth="xl">
      <div className="space-y-6">
        <PageHeader
          icon={<Warehouse className="h-5 w-5" />}
          title="Impound Lot"
          description="Track vehicles in storage and process releases"
          action={
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setBulkImportOpen(true)}>
                <Upload className="h-4 w-4 mr-2" />
                Import
              </Button>
              <Button onClick={() => setQuickAddOpen(true)}>
                <Plus className="h-4 w-4 mr-2" />
                Add Vehicle
              </Button>
            </div>
          }
        />

        {/* Stats */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <Card>
            <CardContent className="pt-4">
              <div className="flex items-center gap-2">
                <Car className="h-4 w-4 text-primary" />
                <span className="text-sm text-muted-foreground">In Lot</span>
              </div>
              <p className="text-2xl font-bold mt-1">{stats.inLot}</p>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="pt-4">
              <div className="flex items-center gap-2">
                <Clock className="h-4 w-4 text-warning" />
                <span className="text-sm text-muted-foreground">Pending Release</span>
              </div>
              <p className="text-2xl font-bold mt-1">{stats.pendingRelease}</p>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="pt-4">
              <div className="flex items-center gap-2">
                <CheckCircle2 className="h-4 w-4 text-success" />
                <span className="text-sm text-muted-foreground">Released Today</span>
              </div>
              <p className="text-2xl font-bold mt-1">{stats.releasedToday}</p>
            </CardContent>
          </Card>

          <Card>
            <CardContent className="pt-4">
              <div className="flex items-center gap-2">
                <DollarSign className="h-4 w-4 text-success" />
                <span className="text-sm text-muted-foreground">Pending Fees</span>
              </div>
              <p className="text-2xl font-bold mt-1">
                ${(stats.totalFees / 100).toLocaleString()}
              </p>
            </CardContent>
          </Card>
        </div>

        {/* Filters */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <Select value={statusFilter} onValueChange={setStatusFilter}>
              <SelectTrigger className="w-40">
                <SelectValue placeholder="Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Vehicles</SelectItem>
                <SelectItem value="in_lot">In Lot</SelectItem>
                <SelectItem value="pending_release">Pending Release</SelectItem>
                <SelectItem value="released">Released</SelectItem>
              </SelectContent>
            </Select>
          </div>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input
              placeholder="Search plate, VIN, make..."
              className="w-64 pl-10"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
            />
          </div>
        </div>

        {/* Vehicle grid */}
        {filteredVehicles.length === 0 ? (
          <EmptyState
            icon={Warehouse}
            title="No vehicles found"
            description={
              statusFilter !== "all" || searchQuery
                ? "Try adjusting your filters to see more results."
                : "Add vehicles to your impound lot to start tracking inventory."
            }
            action={
              statusFilter === "all" && !searchQuery
                ? { label: "Add Vehicle", onClick: () => setQuickAddOpen(true) }
                : undefined
            }
          />
        ) : (
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {filteredVehicles.map((vehicle) => (
              <ImpoundVehicleCard
                key={vehicle.id}
                vehicle={vehicle}
                onClick={() => handleVehicleClick(vehicle)}
              />
            ))}
          </div>
        )}
      </div>

      {/* Dialogs */}
      <ImpoundQuickAddDialog
        open={quickAddOpen}
        onOpenChange={setQuickAddOpen}
        defaultLotId={lots?.[0]?.id}
        onSuccess={handleRefresh}
      />

      <ImpoundBulkImportDialog
        open={bulkImportOpen}
        onOpenChange={setBulkImportOpen}
        defaultLotId={lots?.[0]?.id}
        onSuccess={handleRefresh}
      />

      {selectedVehicle && (
        <ImpoundVehicleDetailDialog
          vehicle={selectedVehicle}
          open={!!selectedVehicle}
          onOpenChange={(open) => !open && setSelectedVehicle(null)}
          onUpdate={handleRefresh}
        />
      )}
    </PageContainer>
  );
}

import { useState, useMemo } from "react";
import {
  Link2, Zap, History, Settings2, Headset, ChevronDown, ChevronUp,
  Calendar, FileSpreadsheet, Printer, Webhook, MessageSquare, ExternalLink,
  CheckCircle, AlertCircle, Play, Loader2, Check, ArrowRight, HelpCircle
} from "lucide-react";
import { FieldEdgeSetupCard } from "@/components/integrations/FieldEdgeSetupCard";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { useAuth } from "@/contexts/AuthContext";
import { useTenantConfig, type BusinessMode } from "@/hooks/useTenantConfig";
import { 
  useIntegrations, 
  useIntegrationMutations,
  useAutomationRules,
  useAutomationRuleMutations,
  useAutomationRuns,
  useTestAutomation,
  PROVIDERS 
} from "@/hooks/useIntegrations";
import { useToast } from "@/hooks/use-toast";
import { AutomationRunHistorySection } from "@/components/automations/AutomationRunHistorySection";
import { ConciergeRequestDialog } from "@/components/integrations/ConciergeRequestDialog";
import { IntegrationConnectDialog } from "@/components/integrations/IntegrationConnectDialog";
import { IntegrationCard } from "@/components/integrations/IntegrationCard";
import { MoreIntegrationsDialog } from "@/components/integrations/MoreIntegrationsDialog";
import { IntegrationStatusDashboard } from "@/components/integrations/IntegrationStatusDashboard";
import { IntegrationHealthAlert, type HealthWarning } from "@/components/integrations/IntegrationHealthAlert";
import { AutomationActivityFeed } from "@/components/integrations/AutomationActivityFeed";
import { SELF_SETUP_INTEGRATIONS, FEATURED_EXPERT_INTEGRATIONS } from "@/data/popularIntegrations";

// Quick automation presets that create real automation_rules
interface QuickPreset {
  id: string;
  icon: React.ReactNode;
  label: string;
  description: string;
  trigger: string;
  action: string;
  provider: string;
  modes: BusinessMode[];
  requiresIntegration?: string;
  color: string;
}

const QUICK_PRESETS: QuickPreset[] = [
  {
    id: "booking-calendar",
    icon: <Calendar className="h-5 w-5" />,
    label: "Push bookings to Google Calendar",
    description: "Auto-create calendar events for confirmed bookings",
    trigger: "booking.created",
    action: "create_calendar_event",
    provider: "google_calendar",
    modes: ["service", "medical", "general"],
    requiresIntegration: "google_calendar",
    color: "text-blue-500 bg-blue-500/10",
  },
  {
    id: "booking-webhook",
    icon: <Webhook className="h-5 w-5" />,
    label: "Send bookings to webhook",
    description: "POST booking data to your external system",
    trigger: "booking.created",
    action: "send_webhook",
    provider: "webhook",
    modes: ["service", "medical", "general"],
    color: "text-violet-500 bg-violet-500/10",
  },
  {
    id: "order-printer",
    icon: <Printer className="h-5 w-5" />,
    label: "Print orders automatically",
    description: "Auto-print kitchen tickets for new orders",
    trigger: "order.created",
    action: "print_receipt",
    provider: "printer",
    modes: ["food"],
    color: "text-orange-500 bg-orange-500/10",
  },
  {
    id: "order-webhook",
    icon: <Webhook className="h-5 w-5" />,
    label: "Send orders to webhook",
    description: "POST order data to your POS or external system",
    trigger: "order.created",
    action: "send_webhook",
    provider: "webhook",
    modes: ["food"],
    color: "text-violet-500 bg-violet-500/10",
  },
  {
    id: "dispatch-sms",
    icon: <MessageSquare className="h-5 w-5" />,
    label: "SMS owner on new dispatch",
    description: "Notify team when new dispatch jobs come in",
    trigger: "dispatch_job.created",
    action: "send_sms_to_owner",
    provider: "sms",
    modes: ["dispatch"],
    color: "text-amber-500 bg-amber-500/10",
  },
  {
    id: "lead-sheets",
    icon: <FileSpreadsheet className="h-5 w-5" />,
    label: "Send leads to Google Sheets",
    description: "Auto-log new leads to a spreadsheet",
    trigger: "lead.captured",
    action: "append_sheet_row",
    provider: "google_sheets",
    modes: ["service", "medical", "dispatch", "general"],
    requiresIntegration: "google_sheets",
    color: "text-emerald-500 bg-emerald-500/10",
  },
  {
    id: "call-webhook",
    icon: <Webhook className="h-5 w-5" />,
    label: "Send call summaries to webhook",
    description: "POST call data after every completed call",
    trigger: "call.completed",
    action: "send_webhook",
    provider: "webhook",
    modes: ["service", "food", "dispatch", "medical", "general"],
    color: "text-violet-500 bg-violet-500/10",
  },
];

// Tool connections (used for status checking)
const CONNECT_TOOLS = [
  { id: "google_calendar", name: "Google Calendar", icon: "📅", description: "Sync bookings to your calendar" },
  { id: "google_sheets", name: "Google Sheets", icon: "📊", description: "Log data to spreadsheets" },
  { id: "webhook", name: "Webhook", icon: "🔗", description: "Send data to any URL" },
  { id: "printer", name: "Printer", icon: "🖨️", description: "Print kitchen tickets" },
] as const;

export default function IntegrationsPage() {
  const { tenant } = useAuth();
  const tenantId = tenant?.id ?? null;
  const { businessMode } = useTenantConfig();
  const { toast } = useToast();

  const [activeTab, setActiveTab] = useState("automations");
  const [showAdvanced, setShowAdvanced] = useState(false);
  const [conciergeOpen, setConciergeOpen] = useState(false);
  const [connectDialogOpen, setConnectDialogOpen] = useState(false);
  const [selectedProvider, setSelectedProvider] = useState<string | null>(null);
  const [webhookConfigDialog, setWebhookConfigDialog] = useState<QuickPreset | null>(null);
  const [webhookUrl, setWebhookUrl] = useState("");
  const [moreIntegrationsOpen, setMoreIntegrationsOpen] = useState(false);
  const [conciergePrefilledSystem, setConciergePrefilledSystem] = useState<string | null>(null);

  // Data hooks
  const { data: integrations, isLoading: integrationsLoading } = useIntegrations(tenantId);
  const { data: rules, isLoading: rulesLoading } = useAutomationRules(tenantId);
  const { data: automationRuns, isLoading: runsLoading } = useAutomationRuns(tenantId, 50);
  const { createRule, toggleRule } = useAutomationRuleMutations(tenantId);
  const { createIntegration, testIntegration, updateIntegration } = useIntegrationMutations(tenantId);
  const testAutomation = useTestAutomation();

  // Compute automation stats for dashboard
  const automationStats = useMemo(() => {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    
    const todayRuns = (automationRuns || []).filter(r => new Date(r.started_at) >= today);
    const successCount = todayRuns.filter(r => r.status === "success").length;
    const failureCount = todayRuns.filter(r => r.status === "failed").length;
    const lastRunAt = automationRuns?.[0]?.started_at || null;
    
    return {
      totalRuns: todayRuns.length,
      successCount,
      failureCount,
      lastRunAt,
    };
  }, [automationRuns]);

  // Check for health warnings
  const healthWarnings = useMemo((): HealthWarning[] => {
    const warnings: HealthWarning[] = [];
    
    // Check for error integrations
    (integrations || []).forEach(integration => {
      if (integration.status === "error") {
        warnings.push({
          id: `error-${integration.id}`,
          type: "sync_error",
          integrationId: integration.id,
          integrationName: integration.display_name,
          message: integration.error_message || "Connection error detected. Please reconnect.",
        });
      }
    });
    
    // Check for failed automation runs
    const recentFailures = (automationRuns || [])
      .filter(r => r.status === "failed")
      .slice(0, 3);
    
    if (recentFailures.length > 0) {
      const failedProviders = [...new Set(recentFailures.map(r => r.rule?.destination_provider).filter(Boolean))];
      if (failedProviders.length > 0) {
        warnings.push({
          id: "webhook-failures",
          type: "webhook_failing",
          integrationId: recentFailures[0].rule?.integration_id || "",
          integrationName: failedProviders.join(", "),
          message: `${recentFailures.length} recent automation${recentFailures.length > 1 ? "s" : ""} failed. Check the History tab for details.`,
          actionLabel: "View History",
        });
      }
    }
    
    return warnings;
  }, [integrations, automationRuns]);

  const [dismissedWarnings, setDismissedWarnings] = useState<string[]>([]);
  const activeWarnings = healthWarnings.filter(w => !dismissedWarnings.includes(w.id));

  if (!tenantId) {
    return (
      <div className="p-4 md:p-6 lg:p-8">
        <div className="text-center py-12">
          <p className="text-muted-foreground">Loading...</p>
        </div>
      </div>
    );
  }

  // Filter presets by business mode
  const availablePresets = QUICK_PRESETS.filter(p => p.modes.includes(businessMode));
  const connectedIntegrations = (integrations || []).filter(i => i.status === "connected");

  // Check if integration is connected
  const isIntegrationConnected = (provider: string): boolean => {
    if (provider === "webhook" || provider === "sms" || provider === "printer") return true;
    return connectedIntegrations.some(i => i.provider === provider);
  };

  // Get existing rule for preset
  const getPresetRule = (preset: QuickPreset) => {
    return rules?.find(
      r => r.trigger_event === preset.trigger && r.action_type === preset.action
    );
  };

  // Toggle automation - creates or updates automation_rules row
  const handleToggle = async (preset: QuickPreset) => {
    const existingRule = getPresetRule(preset);

    // Check if integration is required
    if (preset.requiresIntegration && !isIntegrationConnected(preset.requiresIntegration)) {
      setSelectedProvider(preset.requiresIntegration);
      setConnectDialogOpen(true);
      return;
    }

    if (existingRule) {
      // Toggle existing rule
      await toggleRule.mutateAsync({ id: existingRule.id, enabled: !existingRule.enabled });
    } else {
      // For webhook presets, prompt for URL first
      if (preset.action === "send_webhook") {
        setWebhookConfigDialog(preset);
        return;
      }

      // Create new rule
      await createRule.mutateAsync({
        name: preset.label,
        description: preset.description,
        trigger_event: preset.trigger,
        action_type: preset.action,
        destination_provider: preset.provider,
      });

      toast({
        title: "Automation enabled",
        description: preset.label,
      });
    }
  };

  // Create webhook automation with URL
  const handleCreateWebhookRule = async () => {
    if (!webhookConfigDialog || !webhookUrl) return;

    await createRule.mutateAsync({
      name: webhookConfigDialog.label,
      description: webhookConfigDialog.description,
      trigger_event: webhookConfigDialog.trigger,
      action_type: webhookConfigDialog.action,
      destination_provider: webhookConfigDialog.provider,
      field_mapping_json: { url: webhookUrl },
    });

    toast({
      title: "Automation enabled",
      description: webhookConfigDialog.label,
    });

    setWebhookConfigDialog(null);
    setWebhookUrl("");
  };

  // Test automation
  const handleTest = async (preset: QuickPreset) => {
    const existingRule = getPresetRule(preset);
    if (!existingRule) {
      toast({
        title: "Enable first",
        description: "Enable this automation before testing",
        variant: "destructive",
      });
      return;
    }

    await testAutomation.mutateAsync({
      rule_id: existingRule.id,
      dry_run: false,
    });
  };

  return (
    <PageContainer maxWidth="xl">
      <PageHeader
        title="Integrations"
        description="Connect your tools and automate what happens when calls, bookings, and orders come in"
        action={
          <Button
            variant="outline"
            className="gap-2"
            onClick={() => setConciergeOpen(true)}
          >
            <Headset className="h-4 w-4" />
            Have an expert set this up
          </Button>
        }
      />

      {/* Tabs */}
      <Tabs value={activeTab} onValueChange={setActiveTab} className="space-y-6">
        <TabsList className="grid w-full grid-cols-3 lg:w-auto lg:inline-flex">
          <TabsTrigger value="automations" className="gap-2">
            <Zap className="h-4 w-4" />
            <span className="hidden sm:inline">Automations</span>
          </TabsTrigger>
          <TabsTrigger value="connect" className="gap-2">
            <Link2 className="h-4 w-4" />
            <span className="hidden sm:inline">Connect</span>
          </TabsTrigger>
          <TabsTrigger value="history" className="gap-2">
            <History className="h-4 w-4" />
            <span className="hidden sm:inline">History</span>
          </TabsTrigger>
        </TabsList>

        {/* Automations Tab */}
        <TabsContent value="automations" className="space-y-6">
          {/* Quick Automations */}
          <section className="space-y-4">
            <div className="flex items-center gap-2">
              <Zap className="h-5 w-5 text-primary" />
              <h2 className="text-lg font-semibold">Quick Automations</h2>
              <Badge variant="secondary" className="text-xs">One-click setup</Badge>
            </div>
            <p className="text-sm text-muted-foreground -mt-2">
              Toggle these on to automate common tasks — each creates a real automation rule
            </p>

            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {availablePresets.map((preset) => {
                const rule = getPresetRule(preset);
                const isEnabled = rule?.enabled || false;
                const connected = preset.requiresIntegration 
                  ? isIntegrationConnected(preset.requiresIntegration)
                  : true;

                return (
                  <Card
                    key={preset.id}
                    className={`transition-all duration-150 ${isEnabled ? "border-primary/50 bg-primary/5" : "border-border/50"}`}
                  >
                    <CardContent className="p-4">
                      <div className="flex items-start gap-3">
                        <div className={`p-2 rounded-xl shrink-0 ${preset.color}`}>
                          {preset.icon}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center justify-between gap-2">
                            <h4 className="font-medium text-sm leading-tight">
                              {preset.label}
                            </h4>
                            <Switch
                              checked={isEnabled}
                              onCheckedChange={() => handleToggle(preset)}
                              disabled={toggleRule.isPending || createRule.isPending}
                            />
                          </div>
                          <p className="text-xs text-muted-foreground mt-1">
                            {preset.description}
                          </p>

                          {/* Status row */}
                          <div className="flex items-center gap-2 mt-2 flex-wrap">
                            {isEnabled && (
                              <Badge variant="default" className="text-[10px] h-5 gap-1">
                                <Check className="h-3 w-3" />
                                Active
                              </Badge>
                            )}

                            {preset.requiresIntegration && !connected && (
                              <Button
                                variant="outline"
                                size="sm"
                                className="h-5 text-[10px] px-2"
                                onClick={() => {
                                  setSelectedProvider(preset.requiresIntegration!);
                                  setConnectDialogOpen(true);
                                }}
                              >
                                Connect {preset.requiresIntegration.replace("_", " ")}
                              </Button>
                            )}

                            {isEnabled && (
                              <Button
                                variant="ghost"
                                size="sm"
                                className="h-5 px-1.5 text-[10px]"
                                onClick={() => handleTest(preset)}
                                disabled={testAutomation.isPending}
                              >
                                {testAutomation.isPending ? (
                                  <Loader2 className="h-3 w-3 animate-spin" />
                                ) : (
                                  <>
                                    <Play className="h-3 w-3 mr-1" />
                                    Test
                                  </>
                                )}
                              </Button>
                            )}
                          </div>
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          </section>

          {/* Advanced Section */}
          <Collapsible open={showAdvanced} onOpenChange={setShowAdvanced}>
            <CollapsibleTrigger asChild>
              <Button variant="ghost" className="w-full justify-between p-4 h-auto border border-border/40 rounded-xl bg-muted/30 hover:bg-muted/50 transition-all duration-150">
                <div className="flex items-center gap-2">
                  <Settings2 className="h-4 w-4" />
                  <span className="font-medium">Advanced</span>
                  <Badge variant="outline" className="text-xs">Custom webhooks</Badge>
                </div>
                {showAdvanced ? (
                  <ChevronUp className="h-4 w-4" />
                ) : (
                  <ChevronDown className="h-4 w-4" />
                )}
              </Button>
            </CollapsibleTrigger>
            <CollapsibleContent className="pt-4">
              <Card className="border-dashed">
                <CardHeader className="pb-3">
                  <CardTitle className="text-base">Custom Webhook Configuration</CardTitle>
                  <CardDescription>
                    For advanced users: send data to any URL with custom field mapping
                  </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <p className="text-sm text-muted-foreground">
                    Need to connect to a system we don't have a built-in integration for?
                    Our team can help set up custom webhook configurations.
                  </p>
                  <div className="flex gap-2">
                    <Button variant="outline" size="sm" onClick={() => setConciergeOpen(true)}>
                      Request custom setup
                      <ExternalLink className="h-3 w-3 ml-2" />
                    </Button>
                  </div>
                </CardContent>
              </Card>
            </CollapsibleContent>
          </Collapsible>
        </TabsContent>

        {/* Connect Tools Tab - Redesigned */}
        <TabsContent value="connect" className="space-y-8">
          {/* Status Dashboard - Shows connected integrations at a glance */}
          <IntegrationStatusDashboard
            integrations={integrations || []}
            automationStats={automationStats}
            onAddIntegration={() => setActiveTab("connect")}
            onReconnect={(id) => {
              const integration = integrations?.find(i => i.id === id);
              if (integration) {
                setSelectedProvider(integration.provider);
                setConnectDialogOpen(true);
              }
            }}
            isLoading={integrationsLoading}
          />

          {/* Health Alerts */}
          {activeWarnings.length > 0 && (
            <IntegrationHealthAlert
              warnings={activeWarnings}
              onReconnect={(id) => {
                const integration = integrations?.find(i => i.id === id);
                if (integration) {
                  setSelectedProvider(integration.provider);
                  setConnectDialogOpen(true);
                }
              }}
              onDismiss={(warningId) => setDismissedWarnings(prev => [...prev, warningId])}
            />
          )}

          {/* Intro Section */}
          <Card className="bg-muted/30 border-dashed border-border/40">
            <CardContent className="p-6">
              <div className="flex items-start gap-3">
                <div className="p-2 rounded-xl bg-primary/10">
                  <HelpCircle className="h-5 w-5 text-primary" />
                </div>
                <div>
                  <h3 className="font-medium mb-1">How Integrations Work</h3>
                  <p className="text-sm text-muted-foreground">
                    Connect CloseLoop to your existing tools. Some integrations you can set up yourself in minutes — others our team will configure for you (usually within 24 hours).
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* FieldEdge Self-Service Setup (for service/dispatch businesses) */}
          {(businessMode === "service" || businessMode === "dispatch") && (
            <section className="space-y-4">
              <div className="flex items-center gap-2">
                <span className="text-xl">⚙️</span>
                <h2 className="text-lg font-semibold">FieldEdge</h2>
              </div>
              <p className="text-sm text-muted-foreground -mt-2">
                Sync bookings and dispatches with your FieldEdge account
              </p>
              <FieldEdgeSetupCard />
            </section>
          )}

          {/* Section A: Self-Setup Integrations */}
          <section className="space-y-4">
            <div className="flex items-center gap-2">
              <CheckCircle className="h-5 w-5 text-primary" />
              <h2 className="text-lg font-semibold">Set Up Yourself</h2>
              <Badge variant="secondary" className="text-xs">Free</Badge>
            </div>
            <p className="text-sm text-muted-foreground -mt-2">
              These are quick to connect — just click and follow the steps
            </p>

            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              {SELF_SETUP_INTEGRATIONS.map((tool) => {
                const integration = integrations?.find(i => i.provider === tool.id);
                const isConnected = integration?.status === "connected";

                return (
                  <IntegrationCard
                    key={tool.id}
                    id={tool.id}
                    name={tool.name}
                    icon={tool.icon}
                    logo={'logo' in tool ? (tool as any).logo : undefined}
                    description={tool.description}
                    isConnected={isConnected}
                    isSelfSetup={true}
                    isLoading={testIntegration.isPending}
                    onConnect={() => {
                      setSelectedProvider(tool.id);
                      setConnectDialogOpen(true);
                    }}
                    onTest={isConnected ? () => integration && testIntegration.mutate(integration.id) : undefined}
                  />
                );
              })}
            </div>
          </section>

          {/* Section B: Expert-Setup Integrations */}
          <section className="space-y-4">
            <div className="flex items-center gap-2">
              <Headset className="h-5 w-5 text-primary" />
              <h2 className="text-lg font-semibold">We'll Set These Up For You</h2>
            </div>
            <p className="text-sm text-muted-foreground -mt-2">
              Need Square, ServiceTitan, or Toast? Our team will configure these for you — usually within 24 hours.
            </p>

            <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              {FEATURED_EXPERT_INTEGRATIONS.map((tool) => (
                <IntegrationCard
                  key={tool.id}
                  id={tool.id}
                  name={tool.name}
                  icon={tool.icon}
                  logo={'logo' in tool ? (tool as any).logo : undefined}
                  description={tool.description}
                  isConnected={false}
                  isSelfSetup={false}
                  onRequestSetup={() => {
                    setConciergePrefilledSystem(tool.name);
                    setConciergeOpen(true);
                  }}
                />
              ))}
            </div>

            {/* More Integrations Button */}
            <div className="flex justify-center pt-2">
              <Button
                variant="outline"
                className="gap-2"
                onClick={() => setMoreIntegrationsOpen(true)}
              >
                More Integrations
                <ArrowRight className="h-4 w-4" />
              </Button>
            </div>
          </section>

          {/* Section C: Don't See Your Tool */}
          <Card className="border-dashed border-border/40 bg-muted/20">
            <CardContent className="p-6">
              <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                <div>
                  <h3 className="font-medium mb-1 flex items-center gap-2">
                    <AlertCircle className="h-4 w-4 text-muted-foreground" />
                    Don't see your tool?
                  </h3>
                  <p className="text-sm text-muted-foreground">
                    We can connect to almost any system — FieldEdge, Towbook, AthenaHealth, GoHighLevel, and more.
                  </p>
                </div>
                <Button 
                  variant="outline" 
                  onClick={() => {
                    setConciergePrefilledSystem(null);
                    setConciergeOpen(true);
                  }}
                  className="shrink-0"
                >
                  Request Custom Integration
                </Button>
              </div>
            </CardContent>
          </Card>
        </TabsContent>

        {/* History Tab - Enhanced Activity Feed */}
        <TabsContent value="history" className="space-y-6">
          <AutomationActivityFeed
            runs={automationRuns || []}
            isLoading={runsLoading}
            onRetry={(runId) => {
              const run = automationRuns?.find(r => r.id === runId);
              if (run?.rule_id) {
                testAutomation.mutate({ rule_id: run.rule_id, dry_run: false });
              }
            }}
          />
        </TabsContent>
      </Tabs>

      {/* Dialogs */}
      <ConciergeRequestDialog
        open={conciergeOpen}
        onOpenChange={setConciergeOpen}
      />

      <MoreIntegrationsDialog
        open={moreIntegrationsOpen}
        onOpenChange={setMoreIntegrationsOpen}
        onRequestSetup={(systemName) => {
          setConciergePrefilledSystem(systemName);
          setConciergeOpen(true);
        }}
      />

      {selectedProvider && (
        <IntegrationConnectDialog
          open={connectDialogOpen}
          onOpenChange={setConnectDialogOpen}
          providerId={selectedProvider}
          onConnected={() => {
            setConnectDialogOpen(false);
            setSelectedProvider(null);
          }}
        />
      )}

      {/* Webhook Config Dialog */}
      <Dialog open={!!webhookConfigDialog} onOpenChange={() => setWebhookConfigDialog(null)}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Configure Webhook</DialogTitle>
            <DialogDescription>
              Enter the URL where you want to receive data when {webhookConfigDialog?.trigger} fires
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="webhook-url">Webhook URL</Label>
              <Input
                id="webhook-url"
                type="url"
                placeholder="https://your-system.com/webhook"
                value={webhookUrl}
                onChange={(e) => setWebhookUrl(e.target.value)}
              />
              <p className="text-xs text-muted-foreground">
                We'll POST event data to this URL whenever the trigger fires
              </p>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setWebhookConfigDialog(null)}>
              Cancel
            </Button>
            <Button
              onClick={handleCreateWebhookRule}
              disabled={!webhookUrl || createRule.isPending}
            >
              {createRule.isPending ? "Enabling..." : "Enable & Save"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </PageContainer>
  );
}

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import {
  Package,
  Plus,
  Search,
  AlertTriangle,
  Loader2,
  Warehouse,
  Truck,
  ArrowUpDown,
  Minus,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { useInventory, InventoryItem, InventoryLocation, InventoryStock } from "@/hooks/useInventory";
import { useModuleRequired } from "@/hooks/useModuleRequired";

function formatCurrency(cents: number | null): string {
  if (cents === null) return "—";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);
}

export default function InventoryPage() {
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["job_tracking", "dispatch_queue"]);
  const {
    items,
    locations,
    stockLevels,
    lowStockItems,
    isLoading,
    createItem,
    createLocation,
    recordUsage,
    restock,
  } = useInventory();

  const [searchQuery, setSearchQuery] = useState("");
  const [addItemOpen, setAddItemOpen] = useState(false);
  const [addLocationOpen, setAddLocationOpen] = useState(false);
  const [stockActionOpen, setStockActionOpen] = useState(false);
  const [stockAction, setStockAction] = useState<"restock" | "usage">("restock");
  const [selectedItem, setSelectedItem] = useState<InventoryItem | null>(null);

  // Form states
  const [newItemName, setNewItemName] = useState("");
  const [newItemSku, setNewItemSku] = useState("");
  const [newItemCategory, setNewItemCategory] = useState("");
  const [newItemCost, setNewItemCost] = useState("");
  const [newItemPrice, setNewItemPrice] = useState("");
  const [newItemMinStock, setNewItemMinStock] = useState("5");

  const [newLocationName, setNewLocationName] = useState("");
  const [newLocationType, setNewLocationType] = useState<"warehouse" | "truck">("warehouse");

  const [stockLocationId, setStockLocationId] = useState("");
  const [stockQuantity, setStockQuantity] = useState("");

  const filteredItems = items.filter(
    (item) =>
      !searchQuery ||
      item.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.sku?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.category?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const handleAddItem = async () => {
    await createItem.mutateAsync({
      name: newItemName,
      sku: newItemSku || undefined,
      category: newItemCategory || undefined,
      unit_cost_cents: newItemCost ? Math.round(parseFloat(newItemCost) * 100) : undefined,
      sell_price_cents: newItemPrice ? Math.round(parseFloat(newItemPrice) * 100) : undefined,
      min_stock_level: parseInt(newItemMinStock) || 5,
    });
    setAddItemOpen(false);
    resetItemForm();
  };

  const handleAddLocation = async () => {
    await createLocation.mutateAsync({
      name: newLocationName,
      location_type: newLocationType,
    });
    setAddLocationOpen(false);
    setNewLocationName("");
  };

  const handleStockAction = async () => {
    if (!selectedItem || !stockLocationId || !stockQuantity) return;

    if (stockAction === "restock") {
      await restock.mutateAsync({
        item_id: selectedItem.id,
        location_id: stockLocationId,
        quantity: parseInt(stockQuantity),
      });
    } else {
      await recordUsage.mutateAsync({
        item_id: selectedItem.id,
        location_id: stockLocationId,
        quantity: parseInt(stockQuantity),
      });
    }
    setStockActionOpen(false);
    setSelectedItem(null);
    setStockQuantity("");
  };

  const resetItemForm = () => {
    setNewItemName("");
    setNewItemSku("");
    setNewItemCategory("");
    setNewItemCost("");
    setNewItemPrice("");
    setNewItemMinStock("5");
  };

  const openStockAction = (item: InventoryItem, action: "restock" | "usage") => {
    setSelectedItem(item);
    setStockAction(action);
    setStockActionOpen(true);
  };

  const getStockForItem = (itemId: string): number => {
    return stockLevels
      .filter((s) => s.item_id === itemId)
      .reduce((sum, s) => sum + s.quantity, 0);
  };

  if (moduleLoading || !isAllowed) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <>
      <PageContainer maxWidth="xl">
        <PageHeader
          title="Inventory Management"
          description="Track parts, materials, and stock levels"
          action={
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setAddLocationOpen(true)}>
                <Warehouse className="h-4 w-4 mr-2" />
                Add Location
              </Button>
              <Button onClick={() => setAddItemOpen(true)}>
                <Plus className="h-4 w-4 mr-2" />
                Add Item
              </Button>
            </div>
          }
        />

        {/* Stats */}
        <div className="grid gap-4 md:grid-cols-4 mb-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Items</CardTitle>
              <Package className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{items.length}</div>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Locations</CardTitle>
              <Warehouse className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{locations.length}</div>
              <p className="text-xs text-muted-foreground">
                {locations.filter((l) => l.location_type === "truck").length} trucks
              </p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Low Stock</CardTitle>
              <AlertTriangle className="h-4 w-4 text-orange-500" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold text-orange-600">{lowStockItems.length}</div>
              <p className="text-xs text-muted-foreground">Items need restock</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Total Value</CardTitle>
              <Package className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                {formatCurrency(
                  stockLevels.reduce((sum, s) => {
                    const item = items.find((i) => i.id === s.item_id);
                    return sum + s.quantity * (item?.unit_cost_cents || 0);
                  }, 0)
                )}
              </div>
            </CardContent>
          </Card>
        </div>

        <Tabs defaultValue="items">
          <TabsList>
            <TabsTrigger value="items">Parts Catalog</TabsTrigger>
            <TabsTrigger value="locations">Stock by Location</TabsTrigger>
            <TabsTrigger value="low-stock">
              Low Stock
              {lowStockItems.length > 0 && (
                <Badge variant="destructive" className="ml-2">
                  {lowStockItems.length}
                </Badge>
              )}
            </TabsTrigger>
          </TabsList>

          <TabsContent value="items" className="mt-4">
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle>Parts Catalog</CardTitle>
                  <div className="relative w-64">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                      placeholder="Search items..."
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      className="pl-9"
                    />
                  </div>
                </div>
              </CardHeader>
              <CardContent>
                {filteredItems.length === 0 ? (
                  <div className="text-center py-8 text-muted-foreground">
                    <Package className="h-12 w-12 mx-auto mb-4 opacity-50" />
                    <p>No items found</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {filteredItems.map((item) => {
                      const totalStock = getStockForItem(item.id);
                      const isLowStock = totalStock <= item.min_stock_level;

                      return (
                        <div
                          key={item.id}
                          className={cn(
                            "flex items-center justify-between p-4 border rounded-lg",
                            isLowStock && "border-orange-300 bg-orange-50 dark:bg-orange-950/20"
                          )}
                        >
                          <div className="flex items-center gap-4">
                            <div className="h-10 w-10 rounded bg-muted flex items-center justify-center">
                              <Package className="h-5 w-5 text-muted-foreground" />
                            </div>
                            <div>
                              <div className="flex items-center gap-2">
                                <p className="font-medium">{item.name}</p>
                                {item.sku && (
                                  <Badge variant="outline" className="text-xs">
                                    {item.sku}
                                  </Badge>
                                )}
                                {isLowStock && (
                                  <Badge variant="destructive">Low Stock</Badge>
                                )}
                              </div>
                              <p className="text-sm text-muted-foreground">
                                {item.category || "Uncategorized"} • Cost: {formatCurrency(item.unit_cost_cents)} • Sell: {formatCurrency(item.sell_price_cents)}
                              </p>
                            </div>
                          </div>
                          <div className="flex items-center gap-4">
                            <div className="text-right">
                              <p className="text-2xl font-bold">{totalStock}</p>
                              <p className="text-xs text-muted-foreground">in stock</p>
                            </div>
                            <div className="flex gap-1">
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() => openStockAction(item, "restock")}
                              >
                                <Plus className="h-4 w-4" />
                              </Button>
                              <Button
                                variant="outline"
                                size="sm"
                                onClick={() => openStockAction(item, "usage")}
                              >
                                <Minus className="h-4 w-4" />
                              </Button>
                            </div>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="locations" className="mt-4">
            <div className="grid gap-4 md:grid-cols-2">
              {locations.map((location) => {
                const locationStock = stockLevels.filter((s) => s.location_id === location.id);
                const Icon = location.location_type === "truck" ? Truck : Warehouse;

                return (
                  <Card key={location.id}>
                    <CardHeader>
                      <div className="flex items-center gap-2">
                        <Icon className="h-5 w-5 text-muted-foreground" />
                        <CardTitle className="text-lg">{location.name}</CardTitle>
                        <Badge variant="outline">{location.location_type}</Badge>
                      </div>
                    </CardHeader>
                    <CardContent>
                      {locationStock.length === 0 ? (
                        <p className="text-muted-foreground text-sm">No items at this location</p>
                      ) : (
                        <div className="space-y-2">
                          {locationStock.map((stock) => {
                            const item = items.find((i) => i.id === stock.item_id);
                            if (!item) return null;
                            return (
                              <div
                                key={stock.id}
                                className="flex items-center justify-between text-sm"
                              >
                                <span>{item.name}</span>
                                <Badge variant={stock.quantity <= item.min_stock_level ? "destructive" : "secondary"}>
                                  {stock.quantity}
                                </Badge>
                              </div>
                            );
                          })}
                        </div>
                      )}
                    </CardContent>
                  </Card>
                );
              })}
            </div>
          </TabsContent>

          <TabsContent value="low-stock" className="mt-4">
            <Card>
              <CardHeader>
                <CardTitle>Low Stock Alerts</CardTitle>
                <CardDescription>Items that need to be restocked</CardDescription>
              </CardHeader>
              <CardContent>
                {lowStockItems.length === 0 ? (
                  <p className="text-center py-8 text-muted-foreground">
                    All items are adequately stocked
                  </p>
                ) : (
                  <div className="space-y-2">
                    {lowStockItems.map((stock) => {
                      const item = stock.item;
                      const location = stock.location;
                      if (!item || !location) return null;

                      return (
                        <div
                          key={stock.id}
                          className="flex items-center justify-between p-4 border border-orange-300 rounded-lg bg-orange-50 dark:bg-orange-950/20"
                        >
                          <div>
                            <p className="font-medium">{item.name}</p>
                            <p className="text-sm text-muted-foreground">
                              {location.name} • Min: {item.min_stock_level}
                            </p>
                          </div>
                          <div className="flex items-center gap-4">
                            <div className="text-right">
                              <p className="text-2xl font-bold text-orange-600">{stock.quantity}</p>
                              <p className="text-xs text-muted-foreground">current</p>
                            </div>
                            <Button size="sm" onClick={() => openStockAction(item, "restock")}>
                              Restock
                            </Button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </PageContainer>

      {/* Add Item Dialog */}
      <Dialog open={addItemOpen} onOpenChange={setAddItemOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Add Inventory Item</DialogTitle>
            <DialogDescription>Add a new part or material to your catalog</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Name *</Label>
                <Input
                  value={newItemName}
                  onChange={(e) => setNewItemName(e.target.value)}
                  placeholder="e.g., Air Filter 16x20"
                />
              </div>
              <div className="space-y-2">
                <Label>SKU</Label>
                <Input
                  value={newItemSku}
                  onChange={(e) => setNewItemSku(e.target.value)}
                  placeholder="e.g., AF-16-20"
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Category</Label>
              <Input
                value={newItemCategory}
                onChange={(e) => setNewItemCategory(e.target.value)}
                placeholder="e.g., Filters, Parts, Supplies"
              />
            </div>
            <div className="grid grid-cols-3 gap-4">
              <div className="space-y-2">
                <Label>Cost ($)</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={newItemCost}
                  onChange={(e) => setNewItemCost(e.target.value)}
                  placeholder="0.00"
                />
              </div>
              <div className="space-y-2">
                <Label>Sell Price ($)</Label>
                <Input
                  type="number"
                  step="0.01"
                  value={newItemPrice}
                  onChange={(e) => setNewItemPrice(e.target.value)}
                  placeholder="0.00"
                />
              </div>
              <div className="space-y-2">
                <Label>Min Stock</Label>
                <Input
                  type="number"
                  value={newItemMinStock}
                  onChange={(e) => setNewItemMinStock(e.target.value)}
                />
              </div>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddItemOpen(false)}>Cancel</Button>
            <Button onClick={handleAddItem} disabled={!newItemName || createItem.isPending}>
              {createItem.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Add Item
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Add Location Dialog */}
      <Dialog open={addLocationOpen} onOpenChange={setAddLocationOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Add Stock Location</DialogTitle>
            <DialogDescription>Add a warehouse or truck for inventory tracking</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Name *</Label>
              <Input
                value={newLocationName}
                onChange={(e) => setNewLocationName(e.target.value)}
                placeholder="e.g., Main Warehouse, Truck #1"
              />
            </div>
            <div className="space-y-2">
              <Label>Type</Label>
              <Select value={newLocationType} onValueChange={(v) => setNewLocationType(v as any)}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="warehouse">Warehouse</SelectItem>
                  <SelectItem value="truck">Truck</SelectItem>
                  <SelectItem value="van">Van</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddLocationOpen(false)}>Cancel</Button>
            <Button onClick={handleAddLocation} disabled={!newLocationName || createLocation.isPending}>
              {createLocation.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Add Location
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Stock Action Dialog */}
      <Dialog open={stockActionOpen} onOpenChange={setStockActionOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>
              {stockAction === "restock" ? "Restock Item" : "Record Usage"}
            </DialogTitle>
            <DialogDescription>
              {selectedItem?.name}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Location *</Label>
              <Select value={stockLocationId} onValueChange={setStockLocationId}>
                <SelectTrigger>
                  <SelectValue placeholder="Select location" />
                </SelectTrigger>
                <SelectContent>
                  {locations.map((loc) => (
                    <SelectItem key={loc.id} value={loc.id}>
                      {loc.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Quantity *</Label>
              <Input
                type="number"
                min="1"
                value={stockQuantity}
                onChange={(e) => setStockQuantity(e.target.value)}
                placeholder="Enter quantity"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setStockActionOpen(false)}>Cancel</Button>
            <Button
              onClick={handleStockAction}
              disabled={!stockLocationId || !stockQuantity || restock.isPending || recordUsage.isPending}
            >
              {(restock.isPending || recordUsage.isPending) && (
                <Loader2 className="h-4 w-4 mr-2 animate-spin" />
              )}
              {stockAction === "restock" ? "Add Stock" : "Record Usage"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState, useEffect } from "react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import {
  UtensilsCrossed,
  Clock,
  CheckCircle,
  AlertTriangle,
  Loader2,
  Volume2,
  VolumeX,
  Maximize,
  RefreshCw,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { formatDistanceToNow, differenceInMinutes } from "date-fns";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useModuleRequired } from "@/hooks/useModuleRequired";

interface KitchenOrder {
  id: string;
  order_number: string;
  order_type: string;
  customer_name: string | null;
  items: Array<{
    name: string;
    quantity: number;
    modifications?: string[];
    notes?: string;
  }>;
  status: string;
  created_at: string;
  estimated_ready_at?: string | null;
  table_number?: string;
  priority?: boolean;
}

function getOrderAge(createdAt: string): number {
  return differenceInMinutes(new Date(), new Date(createdAt));
}

function getAgeColor(minutes: number): string {
  if (minutes < 10) return "text-green-600";
  if (minutes < 20) return "text-yellow-600";
  return "text-red-600";
}

function getAgeBadgeColor(minutes: number): string {
  if (minutes < 10) return "bg-green-100 text-green-700";
  if (minutes < 20) return "bg-yellow-100 text-yellow-700";
  return "bg-red-100 text-red-700 animate-pulse";
}

function OrderCard({
  order,
  onBump,
  onRecall,
}: {
  order: KitchenOrder;
  onBump: () => void;
  onRecall: () => void;
}) {
  const ageMinutes = getOrderAge(order.created_at);
  const isOverdue = ageMinutes >= 20;

  return (
    <Card
      className={cn(
        "relative overflow-hidden transition-all",
        order.status === "preparing" && "ring-2 ring-primary",
        isOverdue && "ring-2 ring-red-500"
      )}
    >
      {/* Header */}
      <div
        className={cn(
          "px-4 py-2 flex items-center justify-between",
          order.order_type === "delivery" && "bg-blue-500 text-white",
          order.order_type === "pickup" && "bg-green-500 text-white",
          order.order_type === "dine_in" && "bg-purple-500 text-white"
        )}
      >
        <div className="flex items-center gap-2">
          <span className="font-bold text-lg">#{order.order_number}</span>
          {order.priority && (
            <Badge variant="destructive" className="text-xs">RUSH</Badge>
          )}
        </div>
        <div className="flex items-center gap-2">
          <Badge className={getAgeBadgeColor(ageMinutes)}>
            <Clock className="h-3 w-3 mr-1" />
            {ageMinutes}m
          </Badge>
        </div>
      </div>

      {/* Order Info */}
      <div className="px-4 py-2 border-b bg-muted/50">
        <div className="flex items-center justify-between text-sm">
          <span className="font-medium">
            {order.customer_name || "Guest"}
            {order.table_number && ` • Table ${order.table_number}`}
          </span>
          <Badge variant="outline" className="uppercase text-xs">
            {order.order_type.replace("_", " ")}
          </Badge>
        </div>
      </div>

      {/* Items */}
      <CardContent className="p-4">
        <div className="space-y-3">
          {order.items.map((item, idx) => (
            <div key={idx} className="flex gap-3">
              <span className="font-bold text-lg w-6">{item.quantity}x</span>
              <div className="flex-1">
                <p className="font-medium">{item.name}</p>
                {item.modifications && item.modifications.length > 0 && (
                  <p className="text-sm text-orange-600">
                    {item.modifications.join(", ")}
                  </p>
                )}
                {item.notes && (
                  <p className="text-sm text-muted-foreground italic">
                    Note: {item.notes}
                  </p>
                )}
              </div>
            </div>
          ))}
        </div>
      </CardContent>

      {/* Actions */}
      <div className="px-4 py-3 border-t bg-muted/30 flex gap-2">
        {order.status === "pending" && (
          <Button className="flex-1" onClick={onBump}>
            Start Preparing
          </Button>
        )}
        {order.status === "preparing" && (
          <Button className="flex-1 bg-green-600 hover:bg-green-700" onClick={onBump}>
            <CheckCircle className="h-4 w-4 mr-2" />
            Ready
          </Button>
        )}
        {order.status === "ready" && (
          <>
            <Button className="flex-1" variant="outline" onClick={onRecall}>
              Recall
            </Button>
            <Button className="flex-1" onClick={onBump}>
              Complete
            </Button>
          </>
        )}
      </div>
    </Card>
  );
}

export default function KitchenDisplayPage() {
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["food_orders"]);
  const { tenant } = useAuth();
  const tenantId = tenant?.id ?? null;
  const [orders, setOrders] = useState<KitchenOrder[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [isFullscreen, setIsFullscreen] = useState(false);

  // Load orders
  useEffect(() => {
    if (!tenantId) return;
    loadOrders();

    // Subscribe to new orders
    const channel = supabase
      .channel("kitchen-orders")
      .on(
        "postgres_changes",
        {
          event: "*",
          schema: "public",
          table: "food_orders",
          filter: `tenant_id=eq.${tenantId}`,
        },
        () => {
          loadOrders();
          if (soundEnabled) {
            playNotificationSound();
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [tenantId, soundEnabled]);

  // Refresh every 30 seconds
  useEffect(() => {
    const interval = setInterval(loadOrders, 30000);
    return () => clearInterval(interval);
  }, [tenantId]);

  const loadOrders = async () => {
    if (!tenantId) return;

    try {
      setLoadError(null);
      const { data, error } = await supabase
        .from("food_orders")
        .select("*")
        .eq("tenant_id", tenantId)
        .in("status", ["pending", "preparing", "ready"])
        .order("created_at", { ascending: true });

      if (error) {
        console.error("Failed to load orders:", error);
        setLoadError(error.message || "Failed to load orders");
        setOrders([]);
      } else {
        // Transform database rows to KitchenOrder format
        const transformedOrders = (data || []).map((row: any) => ({
          id: row.id,
          order_number: row.order_number || row.id.slice(0, 8),
          order_type: row.order_type || "pickup",
          customer_name: row.customer_name,
          items: Array.isArray(row.items_json) ? row.items_json : [],
          status: row.status || "pending",
          created_at: row.created_at,
          estimated_ready_at: row.estimated_ready_at || null,
          table_number: row.table_number,
          priority: row.priority || false,
        })) as KitchenOrder[];
        setOrders(transformedOrders);
      }
    } catch (err: any) {
      setLoadError(err.message || "Failed to load orders");
      setOrders([]);
    } finally {
      setIsLoading(false);
    }
  };

  const playNotificationSound = () => {
    try {
      const audio = new Audio("/notification.mp3");
      audio.play().catch(() => {});
    } catch {}
  };

  const handleBump = async (order: KitchenOrder) => {
    const nextStatus: Record<string, string> = {
      pending: "preparing",
      preparing: "ready",
      ready: "completed",
    };

    const newStatus = nextStatus[order.status];
    await supabase
      .from("food_orders")
      .update({ status: newStatus as any })
      .eq("id", order.id);
  };

  const handleRecall = async (order: KitchenOrder) => {
    await supabase
      .from("food_orders")
      .update({ status: "preparing" })
      .eq("id", order.id);
  };

  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  };

  const pendingOrders = orders.filter((o) => o.status === "pending");
  const preparingOrders = orders.filter((o) => o.status === "preparing");
  const readyOrders = orders.filter((o) => o.status === "ready");

  if (moduleLoading || !isAllowed) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-900">
        <Loader2 className="h-12 w-12 animate-spin text-white" />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-screen bg-gray-900">
        <Loader2 className="h-12 w-12 animate-spin text-white" />
      </div>
    );
  }

  if (loadError) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center space-y-4 max-w-md">
          <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-destructive/10">
            <AlertTriangle className="h-7 w-7 text-destructive" />
          </div>
          <h2 className="text-xl font-semibold">Failed to load orders</h2>
          <p className="text-muted-foreground">{loadError}</p>
          <Button onClick={loadOrders} className="gap-2">
            <RefreshCw className="h-4 w-4" />
            Try Again
          </Button>
        </div>
      </div>
    );
  }

  return (
    <div className={cn("min-h-screen", isFullscreen ? "bg-gray-900" : "")}>
      <PageContainer maxWidth="full" className={isFullscreen ? "p-4" : ""}>
        <PageHeader
          icon={<UtensilsCrossed className="h-5 w-5" />}
          title="Kitchen Display"
          description="Real-time order queue for kitchen staff"
          action={
            <div className="flex gap-2">
              <Button
                variant="outline"
                size="icon"
                onClick={() => setSoundEnabled(!soundEnabled)}
              >
                {soundEnabled ? <Volume2 className="h-4 w-4" /> : <VolumeX className="h-4 w-4" />}
              </Button>
              <Button variant="outline" size="icon" onClick={loadOrders}>
                <RefreshCw className="h-4 w-4" />
              </Button>
              <Button variant="outline" size="icon" onClick={toggleFullscreen}>
                <Maximize className="h-4 w-4" />
              </Button>
            </div>
          }
        />

        {/* Stats Bar */}
        <div className="flex gap-4 mb-6">
          <Badge variant="outline" className="text-lg px-4 py-2">
            <Clock className="h-4 w-4 mr-2" />
            Pending: {pendingOrders.length}
          </Badge>
          <Badge variant="outline" className="text-lg px-4 py-2 bg-primary/10">
            <UtensilsCrossed className="h-4 w-4 mr-2" />
            Preparing: {preparingOrders.length}
          </Badge>
          <Badge variant="outline" className="text-lg px-4 py-2 bg-green-500/10 text-green-700">
            <CheckCircle className="h-4 w-4 mr-2" />
            Ready: {readyOrders.length}
          </Badge>
        </div>

        {/* Order Columns */}
        <div className="grid grid-cols-3 gap-4">
          {/* Pending Column */}
          <div>
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
              <Clock className="h-5 w-5 text-yellow-500" />
              New Orders ({pendingOrders.length})
            </h2>
            <div className="space-y-4">
              {pendingOrders.map((order) => (
                <OrderCard
                  key={order.id}
                  order={order}
                  onBump={() => handleBump(order)}
                  onRecall={() => {}}
                />
              ))}
              {pendingOrders.length === 0 && (
                <p className="text-center text-muted-foreground py-8">
                  No pending orders
                </p>
              )}
            </div>
          </div>

          {/* Preparing Column */}
          <div>
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
              <UtensilsCrossed className="h-5 w-5 text-primary" />
              Preparing ({preparingOrders.length})
            </h2>
            <div className="space-y-4">
              {preparingOrders.map((order) => (
                <OrderCard
                  key={order.id}
                  order={order}
                  onBump={() => handleBump(order)}
                  onRecall={() => {}}
                />
              ))}
              {preparingOrders.length === 0 && (
                <p className="text-center text-muted-foreground py-8">
                  No orders being prepared
                </p>
              )}
            </div>
          </div>

          {/* Ready Column */}
          <div>
            <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
              <CheckCircle className="h-5 w-5 text-green-500" />
              Ready ({readyOrders.length})
            </h2>
            <div className="space-y-4">
              {readyOrders.map((order) => (
                <OrderCard
                  key={order.id}
                  order={order}
                  onBump={() => handleBump(order)}
                  onRecall={() => handleRecall(order)}
                />
              ))}
              {readyOrders.length === 0 && (
                <p className="text-center text-muted-foreground py-8">
                  No orders ready
                </p>
              )}
            </div>
          </div>
        </div>
      </PageContainer>
    </div>
  );
}

import { useState, useEffect, useCallback } from "react";
import { useNavigate } from "react-router-dom";
import { RefreshCw, Search, Settings, Plus, Loader2 } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useLeadRecoveryCampaigns, type CampaignStatus, type CampaignWithDetails } from "@/hooks/useLeadRecoveryCampaigns";
import { RecoveryCampaignCard } from "@/components/recovery/RecoveryCampaignCard";
import { RecoveryEmptyState } from "@/components/recovery/RecoveryEmptyState";
import { SendSmsModal } from "@/components/recovery/SendSmsModal";
import { MarkConvertedModal } from "@/components/recovery/MarkConvertedModal";
import { LeadRecoveryDetailSheet } from "@/components/recovery/LeadRecoveryDetailSheet";
import { cn } from "@/lib/utils";

const PAGE_SIZE = 20;

export default function LeadRecoveryPage() {
  const navigate = useNavigate();
  const { tenant } = useAuth();
  const tenantId = tenant?.id || "";

  const [statusFilter, setStatusFilter] = useState<CampaignStatus>("all");
  const [search, setSearch] = useState("");
  const [selectedCampaign, setSelectedCampaign] = useState<CampaignWithDetails | null>(null);
  const [selectedCampaignId, setSelectedCampaignId] = useState<string | null>(null);
  const [detailSheetOpen, setDetailSheetOpen] = useState(false);
  const [smsModalOpen, setSmsModalOpen] = useState(false);
  const [convertModalOpen, setConvertModalOpen] = useState(false);
  const [extraCampaigns, setExtraCampaigns] = useState<CampaignWithDetails[]>([]);
  const [hasMore, setHasMore] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);

  const { data, isLoading, refetch } = useLeadRecoveryCampaigns({
    status: statusFilter,
    search: search || undefined,
    limit: PAGE_SIZE,
    offset: 0,
  });

  const firstPageCampaigns = data?.campaigns || [];
  const counts = data?.counts || { all: 0, active: 0, paused: 0, converted: 0, stopped: 0, declined: 0 };

  // Combine first page + extra loaded pages
  const campaigns = [...firstPageCampaigns, ...extraCampaigns];

  // Reset extra pages when filters/search change
  useEffect(() => {
    setExtraCampaigns([]);
    setHasMore(true);
  }, [statusFilter, search]);

  // Update hasMore based on first page data
  useEffect(() => {
    if (firstPageCampaigns.length < PAGE_SIZE) {
      setHasMore(false);
    } else {
      setHasMore(true);
    }
  }, [firstPageCampaigns]);

  const handleLoadMore = useCallback(async () => {
    if (!tenantId || loadingMore) return;
    setLoadingMore(true);

    try {
      const nextOffset = firstPageCampaigns.length + extraCampaigns.length;

      // Build a query matching the hook's logic
      let query = supabase
        .from("lead_recovery_campaigns")
        .select(`
          id, status, current_step, next_action_at, created_at, converted_at,
          recovered_value_cents, original_intent, original_service_interest,
          original_objection, original_call_outcome, total_attempts, total_responses,
          last_attempt_at, stopped_at, stopped_reason, converted_booking_id,
          customer:customers!lead_recovery_campaigns_customer_id_fkey(id, full_name, phone_e164, email),
          sequence:lead_recovery_sequences!lead_recovery_campaigns_sequence_id_fkey(id, name)
        `)
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false });

      if (statusFilter && statusFilter !== "all") {
        if (statusFilter === "stopped") {
          query = query.in("status", ["stopped", "expired"]);
        } else {
          query = query.eq("status", statusFilter);
        }
      }

      query = query.range(nextOffset, nextOffset + PAGE_SIZE - 1);

      const { data: newBatch, error } = await query;

      if (error) {
        console.error("Error loading more campaigns:", error);
        toast.error("Failed to load more");
        return;
      }

      const mapped: CampaignWithDetails[] = (newBatch || []).map((c: any) => ({
        ...c,
        customer: c.customer as CampaignWithDetails["customer"],
        sequence: c.sequence as CampaignWithDetails["sequence"],
        last_action: null,
      }));

      if (mapped.length < PAGE_SIZE) {
        setHasMore(false);
      }

      setExtraCampaigns((prev) => [...prev, ...mapped]);
    } finally {
      setLoadingMore(false);
    }
  }, [tenantId, statusFilter, firstPageCampaigns.length, extraCampaigns.length, loadingMore]);

  // Check if recovery is enabled (has any campaigns or settings indicate enabled)
  const isEnabled = counts.all > 0;

  const tabs = [
    { value: "all" as CampaignStatus, label: "All", count: counts.all },
    { value: "active" as CampaignStatus, label: "Active", count: counts.active },
    { value: "paused" as CampaignStatus, label: "Needs Response", count: counts.paused, highlight: counts.paused > 0 },
    { value: "converted" as CampaignStatus, label: "Converted", count: counts.converted },
    { value: "stopped" as CampaignStatus, label: "Stopped", count: counts.stopped + counts.declined },
  ];

  // Actions
  const handleCall = (campaign: CampaignWithDetails) => {
    if (campaign.customer?.phone_e164) {
      window.location.href = `tel:${campaign.customer.phone_e164}`;
    }
  };

  const handleSMS = (campaign: CampaignWithDetails) => {
    setSelectedCampaign(campaign);
    setSmsModalOpen(true);
  };

  const handleMarkConverted = (campaign: CampaignWithDetails) => {
    setSelectedCampaign(campaign);
    setConvertModalOpen(true);
  };

  const handleResume = async (campaign: CampaignWithDetails) => {
    try {
      const nextActionAt = new Date(Date.now() + 60 * 60 * 1000).toISOString(); // 1 hour from now
      
      await supabase
        .from("lead_recovery_campaigns")
        .update({
          status: "active",
          next_action_at: nextActionAt,
        })
        .eq("id", campaign.id);

      toast.success("Recovery resumed");
      refetch();
    } catch (error) {
      console.error("Error resuming campaign:", error);
      toast.error("Failed to resume campaign");
    }
  };

  const handleStop = async (campaign: CampaignWithDetails) => {
    try {
      await supabase
        .from("lead_recovery_campaigns")
        .update({
          status: "stopped",
          stopped_at: new Date().toISOString(),
          stopped_reason: "Manually stopped by user",
        })
        .eq("id", campaign.id);

      toast.success("Recovery stopped");
      refetch();
    } catch (error) {
      console.error("Error stopping campaign:", error);
      toast.error("Failed to stop campaign");
    }
  };

  const handleViewDetails = (campaign: CampaignWithDetails) => {
    setSelectedCampaignId(campaign.id);
    setDetailSheetOpen(true);
  };

  const handleViewBooking = (bookingId: string) => {
    navigate(`/app/bookings?id=${bookingId}`);
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-2xl font-semibold">Lead Recovery</h1>
          <p className="text-muted-foreground mt-1">
            Automatically follow up with leads who didn't book
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={() => navigate("/app/settings")}>
            <Settings className="w-4 h-4 mr-2" />
            Configure
          </Button>
        </div>
      </div>

      {/* Filters */}
      <div className="space-y-4">
        {/* Status tabs */}
        <Tabs value={statusFilter} onValueChange={(v) => setStatusFilter(v as CampaignStatus)}>
          <TabsList className="h-auto p-1 flex-wrap">
            {tabs.map((tab) => (
              <TabsTrigger
                key={tab.value}
                value={tab.value}
                className={cn(
                  "gap-2 data-[state=active]:bg-background",
                  tab.highlight && "relative"
                )}
              >
                {tab.label}
                <Badge 
                  variant={tab.highlight ? "destructive" : "secondary"} 
                  className={cn(
                    "h-5 min-w-5 px-1.5 text-xs",
                    tab.highlight && "animate-pulse"
                  )}
                >
                  {tab.count}
                </Badge>
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>

        {/* Search */}
        <div className="relative max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
          <Input
            placeholder="Search by name or phone..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="pl-9"
          />
        </div>
      </div>

      {/* Content */}
      {isLoading ? (
        <div className="space-y-4">
          {[1, 2, 3].map((i) => (
            <Skeleton key={i} className="h-48 w-full" />
          ))}
        </div>
      ) : campaigns.length === 0 ? (
        <RecoveryEmptyState status={statusFilter} isEnabled={isEnabled} />
      ) : (
        <div className="space-y-4">
          {campaigns.map((campaign) => (
            <RecoveryCampaignCard
              key={campaign.id}
              campaign={campaign}
              onCall={handleCall}
              onSMS={handleSMS}
              onMarkConverted={handleMarkConverted}
              onResume={handleResume}
              onStop={handleStop}
              onViewDetails={handleViewDetails}
              onViewBooking={handleViewBooking}
            />
          ))}

          {/* Load more */}
          {hasMore && campaigns.length >= PAGE_SIZE && (
            <div className="text-center pt-4">
              <Button variant="outline" onClick={handleLoadMore} disabled={loadingMore}>
                {loadingMore && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
                {loadingMore ? "Loading..." : "Load More"}
              </Button>
            </div>
          )}
        </div>
      )}

      {/* Modals and Sheets */}
      <LeadRecoveryDetailSheet
        open={detailSheetOpen}
        onOpenChange={setDetailSheetOpen}
        campaignId={selectedCampaignId}
        tenantId={tenantId}
        onCampaignUpdated={() => refetch()}
      />

      <SendSmsModal
        open={smsModalOpen}
        onOpenChange={setSmsModalOpen}
        campaign={selectedCampaign}
        tenantId={tenantId}
        onSuccess={() => refetch()}
      />

      <MarkConvertedModal
        open={convertModalOpen}
        onOpenChange={setConvertModalOpen}
        campaign={selectedCampaign}
        onSuccess={() => refetch()}
      />
    </div>
  );
}

import { useState, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import { useLeadIntelligence, type EnrichedLead, type LeadTemperature } from "@/hooks/useLeadIntelligence";
