import { Toolbar, FilterSelect } from "@/components/layout/Toolbar";
import {
  Plus, MoreHorizontal, Phone, Mail, Calendar, MessageSquare,
  Users, Flame, Thermometer, Snowflake, TrendingUp, UserCheck, UserX,
} from "lucide-react";
import { cn } from "@/lib/utils";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { formatDistanceToNow } from "date-fns";
import { CreateLeadDialog } from "@/components/leads/CreateLeadDialog";
import { LeadDetailPanel } from "@/components/leads/LeadDetailPanel";
import { PipelineSummaryBar, type PipelineStage } from "@/components/leads/PipelineSummaryBar";
import { CreateBookingDialog } from "@/components/calendar/CreateBookingDialog";
import { SendSmsDialog } from "@/components/messaging/SendSmsDialog";
import { toast } from "sonner";

const statusColors: Record<string, string> = {
  new: "bg-blue-500/10 text-blue-700 dark:text-blue-400",
  contacted: "bg-amber-500/10 text-amber-700 dark:text-amber-400",
  qualified: "bg-purple-500/10 text-purple-700 dark:text-purple-400",
  booked: "bg-emerald-500/10 text-emerald-700 dark:text-emerald-400",
  won: "bg-success/10 text-success",
  lost: "bg-muted text-muted-foreground",
};

const sourceLabels: Record<string, string> = {
  missed_call: "Missed Call",
  website_form: "Website",
  manual: "Manual",
  referral: "Referral",
  ai_call: "AI Call",
  walk_in: "Walk-in",
};

const temperatureConfig: Record<LeadTemperature, { icon: typeof Flame; label: string; color: string; badgeCls: string }> = {
  hot: {
    icon: Flame,
    label: "Hot",
    color: "text-red-500",
    badgeCls: "bg-red-500/10 text-red-600 dark:text-red-400 border-red-500/20",
  },
  warm: {
    icon: Thermometer,
    label: "Warm",
    color: "text-amber-500",
    badgeCls: "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20",
  },
  cold: {
    icon: Snowflake,
    label: "Cold",
    color: "text-sky-500",
    badgeCls: "bg-sky-500/10 text-sky-600 dark:text-sky-400 border-sky-500/20",
  },
};

function TemperatureBadge({ temp, reason }: { temp: LeadTemperature; reason?: string }) {
  const cfg = temperatureConfig[temp];
  const Icon = cfg.icon;
  const badge = (
    <Badge variant="outline" className={cn("gap-1 font-medium", cfg.badgeCls)}>
      <Icon className="h-3 w-3" />
      {cfg.label}
    </Badge>
  );
  
  if (!reason) return badge;
  
  return (
    <Tooltip>
      <TooltipTrigger asChild>{badge}</TooltipTrigger>
      <TooltipContent side="top" className="text-xs max-w-[200px]">
        {reason}
      </TooltipContent>
    </Tooltip>
  );
}

function getModeLabels(mode: string) {
  const map: Record<string, { leadLabel: string; leadsLabel: string; contextLabel: string; bookingLabel: string }> = {
    service: { leadLabel: "Lead", leadsLabel: "Leads", contextLabel: "Service Needed", bookingLabel: "Appointment" },
    dispatch: { leadLabel: "Caller", leadsLabel: "Callers", contextLabel: "Job Request", bookingLabel: "Pickup" },
    food: { leadLabel: "Lead", leadsLabel: "Leads", contextLabel: "Order Interest", bookingLabel: "Order" },
    medical: { leadLabel: "Patient", leadsLabel: "Patients", contextLabel: "Visit Reason", bookingLabel: "Visit" },
    sales: { leadLabel: "Prospect", leadsLabel: "Prospects", contextLabel: "Interest", bookingLabel: "Meeting" },
    general: { leadLabel: "Lead", leadsLabel: "Leads", contextLabel: "Request", bookingLabel: "Appointment" },
  };
  return map[mode] || map.service;
}

export default function LeadsPage() {
  const { data: enrichedLeads, isLoading: intelligenceLoading } = useLeadIntelligence();
  const { convertToCustomer, markAsLost } = useLeads();
  const { terms, mode } = useIndustryContext();
  const navigate = useNavigate();
  const caps = useCapabilities();
  const modeLabels = getModeLabels(mode);

  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [tempTab, setTempTab] = useState<string>("all");
  const [pipelineStage, setPipelineStage] = useState<PipelineStage | "all">("all");

  // Detail panel
  const [selectedLead, setSelectedLead] = useState<EnrichedLead | null>(null);

  // Dialog state
  const [createLeadOpen, setCreateLeadOpen] = useState(false);
  const [bookingDialogOpen, setBookingDialogOpen] = useState(false);
  const [bookingLeadName, setBookingLeadName] = useState("");
  const [bookingLeadPhone, setBookingLeadPhone] = useState("");
  const [smsOpen, setSmsOpen] = useState(false);
  const [smsRecipient, setSmsRecipient] = useState<{ phone: string; name: string; customerId?: string }>({ phone: "", name: "" });

  const leads = enrichedLeads ?? [];
  const isLoading = intelligenceLoading;

  // Temperature stats
  const stats = useMemo(() => {
    const hot = leads.filter((l) => l.temperature === "hot").length;
    const warm = leads.filter((l) => l.temperature === "warm").length;
    const cold = leads.filter((l) => l.temperature === "cold").length;
    return { total: leads.length, hot, warm, cold };
  }, [leads]);

  // Pipeline counts
  const pipelineCounts = useMemo(() => {
    const counts: Record<PipelineStage, number> = { new: 0, contacted: 0, quoted: 0, won: 0, lost: 0 };
    for (const lead of leads) {
      const stage = lead.status as PipelineStage;
      if (stage in counts) counts[stage]++;
    }
    return counts;
  }, [leads]);

  // Filtering
  const filteredLeads = useMemo(() => {
    return leads.filter((lead) => {
      if (tempTab !== "all" && lead.temperature !== tempTab) return false;
      if (pipelineStage !== "all" && lead.status !== pipelineStage) return false;
      if (statusFilter !== "all" && lead.status !== statusFilter) return false;
      if (searchQuery) {
        const q = searchQuery.toLowerCase();
        const matchesName = lead.full_name.toLowerCase().includes(q);
        const matchesPhone = lead.phone?.includes(q);
        const matchesEmail = lead.email?.toLowerCase().includes(q);
        const matchesContext = lead.vehicle_or_context?.toLowerCase().includes(q);
        if (!matchesName && !matchesPhone && !matchesEmail && !matchesContext) return false;
      }
      return true;
    });
  }, [leads, tempTab, pipelineStage, statusFilter, searchQuery]);

  const handleBookAppointment = (lead: EnrichedLead | { full_name: string; phone?: string | null }) => {
    setBookingLeadName(lead.full_name);
    setBookingLeadPhone(lead.phone || "");
    setBookingDialogOpen(true);
  };

  return (
    <PageContainer maxWidth="xl">
      <PageHeader
        title={modeLabels.leadsLabel}
        description={`Smart pipeline — ${modeLabels.leadsLabel.toLowerCase()} scored by engagement & intent`}
        action={
          <Button className="gap-2" onClick={() => setCreateLeadOpen(true)}>
            <Plus className="h-4 w-4" />
            Add {modeLabels.leadLabel}
          </Button>
        }
      />

      {/* Temperature Stats */}
      {isLoading ? (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <SkeletonStatCard /><SkeletonStatCard /><SkeletonStatCard /><SkeletonStatCard />
        </div>
      ) : (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <StatCard label={`Total ${modeLabels.leadsLabel}`} value={stats.total} icon={Users} description="All time" />
          <StatCard label="Hot" value={stats.hot} icon={Flame} description="Ready to convert" variant="destructive" />
          <StatCard label="Warm" value={stats.warm} icon={Thermometer} description="Engaged recently" variant="warning" />
          <StatCard label="Cold" value={stats.cold} icon={Snowflake} description="Needs follow-up" />
        </div>
      )}

      {/* Pipeline Summary */}
      <div className="overflow-x-auto">
        <PipelineSummaryBar
          counts={pipelineCounts}
          activeStage={pipelineStage}
          onStageClick={(stage) => {
            setPipelineStage(stage);
            setStatusFilter("all");
          }}
        />
      </div>

      {/* Temperature Tabs + Toolbar */}
      <div className="flex flex-col sm:flex-row sm:items-center gap-3">
        <Tabs value={tempTab} onValueChange={setTempTab}>
          <TabsList>
            <TabsTrigger value="all">All</TabsTrigger>
            <TabsTrigger value="hot" className="gap-1">
              <Flame className="h-3.5 w-3.5 text-red-500" />
              Hot
            </TabsTrigger>
            <TabsTrigger value="warm" className="gap-1">
              <Thermometer className="h-3.5 w-3.5 text-amber-500" />
              Warm
            </TabsTrigger>
            <TabsTrigger value="cold" className="gap-1">
              <Snowflake className="h-3.5 w-3.5 text-sky-500" />
              Cold
            </TabsTrigger>
          </TabsList>
        </Tabs>
        <div className="flex-1">
          <Toolbar
            searchPlaceholder={`Search ${modeLabels.leadsLabel.toLowerCase()}...`}
            searchValue={searchQuery}
            onSearchChange={setSearchQuery}
          />
        </div>
      </div>

      {/* Table */}
      <SectionCard noPadding>
        {isLoading ? (
          <div className="p-6"><SkeletonTable rows={8} columns={6} /></div>
        ) : filteredLeads.length > 0 ? (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Name</TableHead>
                <TableHead>Score</TableHead>
                <TableHead>Status</TableHead>
                <TableHead className="hidden md:table-cell">Source</TableHead>
                <TableHead className="hidden lg:table-cell">{modeLabels.contextLabel}</TableHead>
                <TableHead className="hidden sm:table-cell">Last Activity</TableHead>
                <TableHead className="text-right">Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredLeads.map((lead) => (
                <TableRow
                  key={lead.id}
                  className="cursor-pointer"
                  onClick={() => setSelectedLead(lead)}
                >
                  <TableCell>
                    <div className="flex items-center gap-3">
                      <div className={cn(
                        "h-9 w-9 rounded-full flex items-center justify-center text-sm font-semibold shrink-0",
                        lead.temperature === "hot" ? "bg-red-500/10 text-red-600" :
                        lead.temperature === "warm" ? "bg-amber-500/10 text-amber-600" :
                        "bg-muted text-muted-foreground"
                      )}>
                        {lead.full_name.charAt(0).toUpperCase()}
                      </div>
                      <div>
                        <p className="font-medium">{lead.full_name}</p>
                        <p className="text-sm text-muted-foreground">{lead.phone || "No phone"}</p>
                      </div>
                    </div>
                  </TableCell>
                  <TableCell>
                    <TemperatureBadge temp={lead.temperature} reason={lead.temperatureReason} />
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className={cn(statusColors[lead.status])}>
                      {lead.status}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden md:table-cell">
                    <Badge variant="outline" className="text-xs">
                      {sourceLabels[lead.source] || lead.source}
                    </Badge>
                  </TableCell>
                  <TableCell className="hidden lg:table-cell text-sm text-muted-foreground max-w-[200px] truncate">
                    {lead.vehicle_or_context || "—"}
                  </TableCell>
                  <TableCell className="hidden sm:table-cell text-muted-foreground text-sm">
                    {lead.last_message_at
                      ? formatDistanceToNow(new Date(lead.last_message_at), { addSuffix: true })
                      : lead.latestCallAt
                        ? formatDistanceToNow(new Date(lead.latestCallAt), { addSuffix: true })
                        : formatDistanceToNow(new Date(lead.created_at), { addSuffix: true })}
                  </TableCell>
                  <TableCell className="text-right" onClick={(e) => e.stopPropagation()}>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" size="icon">
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end">
                        {lead.phone && (
                          <DropdownMenuItem onClick={() => {
                            setSmsRecipient({ phone: lead.phone!, name: lead.full_name, customerId: lead.customer_id ?? undefined });
                            setSmsOpen(true);
                          }}>
                            <MessageSquare className="mr-2 h-4 w-4" />
                            Send Message
                          </DropdownMenuItem>
                        )}
                        {lead.phone && (
                          <DropdownMenuItem onClick={() => window.open(`tel:${lead.phone}`, "_self")}>
                            <Phone className="mr-2 h-4 w-4" />
                            Call
                          </DropdownMenuItem>
                        )}
                        <DropdownMenuItem onClick={() => handleBookAppointment(lead)}>
                          <Calendar className="mr-2 h-4 w-4" />
                          {modeLabels.bookingLabel}
                        </DropdownMenuItem>
                        {caps.hasEstimates && (
                          <DropdownMenuItem onClick={() => navigate("/app/estimates")}>
                            <Mail className="mr-2 h-4 w-4" />
                            Send Quote
                          </DropdownMenuItem>
                        )}
                        <DropdownMenuSeparator />
                        <DropdownMenuItem onClick={() => convertToCustomer.mutate(lead)}>
                          <UserCheck className="mr-2 h-4 w-4" />
                          Convert to {terms.customer || "Customer"}
                        </DropdownMenuItem>
                        <DropdownMenuItem
                          onClick={() => markAsLost.mutate(lead.id)}
                          className="text-destructive focus:text-destructive"
                        >
                          <UserX className="mr-2 h-4 w-4" />
                          Mark as Lost
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        ) : (
          <EmptyState
            icon={Users}
            title={`No ${modeLabels.leadsLabel.toLowerCase()} found`}
            description={
              searchQuery || statusFilter !== "all" || tempTab !== "all" || pipelineStage !== "all"
                ? "Try adjusting your filters."
                : `${modeLabels.leadsLabel} will appear here when you receive calls or add them manually.`
            }
            action={
              !searchQuery && statusFilter === "all" && tempTab === "all" && pipelineStage === "all"
                ? { label: `Add Your First ${modeLabels.leadLabel}`, onClick: () => setCreateLeadOpen(true) }
                : undefined
            }
            compact
          />
        )}
      </SectionCard>

      <p className="text-xs text-muted-foreground text-center">
        {filteredLeads.length} {filteredLeads.length === 1 ? modeLabels.leadLabel.toLowerCase() : modeLabels.leadsLabel.toLowerCase()}
      </p>

      {/* Lead Detail Panel */}
      <LeadDetailPanel
        lead={selectedLead}
        onClose={() => setSelectedLead(null)}
        onBookAppointment={(lead) => handleBookAppointment(lead)}
        onConvertToCustomer={(lead) => convertToCustomer.mutate(lead)}
        onMarkAsLost={(lead) => markAsLost.mutate(lead.id)}
        temperature={selectedLead?.temperature}
        temperatureReason={selectedLead?.temperatureReason}
      />

      {/* Dialogs */}
      <CreateLeadDialog open={createLeadOpen} onOpenChange={setCreateLeadOpen} />
      <CreateBookingDialog
        open={bookingDialogOpen}
        onOpenChange={setBookingDialogOpen}
        initialCustomerName={bookingLeadName}
        initialCustomerPhone={bookingLeadPhone}
      />
      <SendSmsDialog
        open={smsOpen}
        onOpenChange={setSmsOpen}
        recipientPhone={smsRecipient.phone}
        recipientName={smsRecipient.name}
        customerId={smsRecipient.customerId}
      />
    </PageContainer>
  );
}

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import {
  Star,
  Gift,
  Users,
  Settings,
  Plus,
  Loader2,
  Trophy,
  Coins,
  Search,
} from "lucide-react";
import { useLoyalty, LoyaltyBalance, LoyaltyReward } from "@/hooks/useLoyalty";
import { useCustomers } from "@/hooks/useCustomers";
import { useModuleRequired } from "@/hooks/useModuleRequired";

function formatPoints(points: number): string {
  return points.toLocaleString();
}

const tierConfig: Record<string, { color: string; minPoints: number }> = {
  member: { color: "bg-gray-100 text-gray-700", minPoints: 0 },
  silver: { color: "bg-gray-200 text-gray-800", minPoints: 500 },
  gold: { color: "bg-yellow-100 text-yellow-700", minPoints: 1500 },
  platinum: { color: "bg-purple-100 text-purple-700", minPoints: 5000 },
};

export default function LoyaltyPage() {
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["food_orders", "reservations"]);
  const {
    program,
    rewards,
    members,
    isLoading,
    updateProgram,
    createReward,
    earnPoints,
    redeemPoints,
  } = useLoyalty();
  const { customers } = useCustomers();

  const [searchQuery, setSearchQuery] = useState("");
  const [addRewardOpen, setAddRewardOpen] = useState(false);
  const [earnPointsOpen, setEarnPointsOpen] = useState(false);
  const [redeemOpen, setRedeemOpen] = useState(false);
  const [selectedMember, setSelectedMember] = useState<LoyaltyBalance | null>(null);

  // Reward form
  const [rewardName, setRewardName] = useState("");
  const [rewardDescription, setRewardDescription] = useState("");
  const [rewardPoints, setRewardPoints] = useState("");
  const [rewardType, setRewardType] = useState<"discount" | "free_item" | "percentage_off">("discount");
  const [rewardValue, setRewardValue] = useState("");

  // Earn points form
  const [earnCustomerId, setEarnCustomerId] = useState("");
  const [earnAmount, setEarnAmount] = useState("");

  // Redeem form
  const [selectedRewardId, setSelectedRewardId] = useState("");

  const filteredMembers = members.filter(
    (m) =>
      !searchQuery ||
      m.customer?.full_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      m.customer?.email?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      m.customer?.phone_e164?.includes(searchQuery)
  );

  const handleAddReward = async () => {
    await createReward.mutateAsync({
      name: rewardName,
      description: rewardDescription || undefined,
      points_required: parseInt(rewardPoints),
      reward_type: rewardType,
      reward_value_cents: rewardType === "discount" ? Math.round(parseFloat(rewardValue) * 100) : undefined,
      reward_percentage: rewardType === "percentage_off" ? parseInt(rewardValue) : undefined,
    });
    setAddRewardOpen(false);
    resetRewardForm();
  };

  const handleEarnPoints = async () => {
    if (!program) return;
    const orderAmount = parseFloat(earnAmount);
    const pointsToEarn = Math.floor(orderAmount * program.points_per_dollar);

    await earnPoints.mutateAsync({
      customer_id: earnCustomerId,
      points: pointsToEarn,
      notes: `Earned from $${orderAmount} purchase`,
    });
    setEarnPointsOpen(false);
    setEarnCustomerId("");
    setEarnAmount("");
  };

  const handleRedeem = async () => {
    if (!selectedMember) return;
    await redeemPoints.mutateAsync({
      customer_id: selectedMember.customer_id,
      reward_id: selectedRewardId,
    });
    setRedeemOpen(false);
    setSelectedMember(null);
    setSelectedRewardId("");
  };

  const resetRewardForm = () => {
    setRewardName("");
    setRewardDescription("");
    setRewardPoints("");
    setRewardType("discount");
    setRewardValue("");
  };

  const openRedeemDialog = (member: LoyaltyBalance) => {
    setSelectedMember(member);
    setRedeemOpen(true);
  };

  if (moduleLoading || !isAllowed) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const totalMembers = members.length;
  const totalPoints = members.reduce((sum, m) => sum + m.points_balance, 0);
  const lifetimePoints = members.reduce((sum, m) => sum + m.lifetime_points, 0);

  return (
    <>
      <PageContainer maxWidth="xl">
        <PageHeader
          icon={<Star className="h-5 w-5" />}
          title="Loyalty Program"
          description="Reward your customers and drive repeat business"
          action={
            <div className="flex gap-2">
              <Button variant="outline" onClick={() => setEarnPointsOpen(true)}>
                <Coins className="h-4 w-4 mr-2" />
                Award Points
              </Button>
              <Button onClick={() => setAddRewardOpen(true)}>
                <Plus className="h-4 w-4 mr-2" />
                Add Reward
              </Button>
            </div>
          }
        />

        {/* Stats */}
        <div className="grid gap-4 md:grid-cols-4 mb-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Members</CardTitle>
              <Users className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{totalMembers}</div>
              <p className="text-xs text-muted-foreground">Enrolled customers</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Points in Circulation</CardTitle>
              <Coins className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatPoints(totalPoints)}</div>
              <p className="text-xs text-muted-foreground">Unredeemed points</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Lifetime Points</CardTitle>
              <Trophy className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatPoints(lifetimePoints)}</div>
              <p className="text-xs text-muted-foreground">Total points earned</p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Rewards Available</CardTitle>
              <Gift className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{rewards.length}</div>
              <p className="text-xs text-muted-foreground">Active rewards</p>
            </CardContent>
          </Card>
        </div>

        <Tabs defaultValue="members">
          <TabsList>
            <TabsTrigger value="members">Members</TabsTrigger>
            <TabsTrigger value="rewards">Rewards</TabsTrigger>
            <TabsTrigger value="settings">Program Settings</TabsTrigger>
          </TabsList>

          <TabsContent value="members" className="mt-4">
            <Card>
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle>Loyalty Members</CardTitle>
                  <div className="relative w-64">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
                    <Input
                      placeholder="Search members..."
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      className="pl-9"
                    />
                  </div>
                </div>
              </CardHeader>
              <CardContent>
                {filteredMembers.length === 0 ? (
                  <p className="text-center py-8 text-muted-foreground">
                    No loyalty members yet. Points are automatically earned on purchases.
                  </p>
                ) : (
                  <div className="space-y-2">
                    {filteredMembers.map((member) => {
                      const tier = tierConfig[member.tier] || tierConfig.member;
                      const availableRewards = rewards.filter(
                        (r) => r.points_required <= member.points_balance
                      );

                      return (
                        <div
                          key={member.id}
                          className="flex items-center justify-between p-4 border rounded-lg"
                        >
                          <div className="flex items-center gap-4">
                            <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
                              <Star className="h-5 w-5 text-primary" />
                            </div>
                            <div>
                              <div className="flex items-center gap-2">
                                <p className="font-medium">
                                  {member.customer?.full_name || "Unknown"}
                                </p>
                                <Badge className={tier.color}>
                                  {member.tier.charAt(0).toUpperCase() + member.tier.slice(1)}
                                </Badge>
                              </div>
                              <p className="text-sm text-muted-foreground">
                                {member.customer?.email || member.customer?.phone_e164}
                              </p>
                            </div>
                          </div>
                          <div className="flex items-center gap-4">
                            <div className="text-right">
                              <p className="text-2xl font-bold">{formatPoints(member.points_balance)}</p>
                              <p className="text-xs text-muted-foreground">
                                {formatPoints(member.lifetime_points)} lifetime
                              </p>
                            </div>
                            <Button
                              variant="outline"
                              size="sm"
                              onClick={() => openRedeemDialog(member)}
                              disabled={availableRewards.length === 0}
                            >
                              <Gift className="h-4 w-4 mr-2" />
                              Redeem
                            </Button>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="rewards" className="mt-4">
            <Card>
              <CardHeader>
                <CardTitle>Available Rewards</CardTitle>
                <CardDescription>Rewards customers can redeem with their points</CardDescription>
              </CardHeader>
              <CardContent>
                {rewards.length === 0 ? (
                  <div className="text-center py-8">
                    <Gift className="h-12 w-12 mx-auto mb-4 text-muted-foreground/50" />
                    <p className="text-muted-foreground mb-4">No rewards created yet</p>
                    <Button onClick={() => setAddRewardOpen(true)}>
                      <Plus className="h-4 w-4 mr-2" />
                      Create First Reward
                    </Button>
                  </div>
                ) : (
                  <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
                    {rewards.map((reward) => (
                      <Card key={reward.id}>
                        <CardContent className="pt-6">
                          <div className="flex items-start justify-between">
                            <div>
                              <h3 className="font-bold">{reward.name}</h3>
                              {reward.description && (
                                <p className="text-sm text-muted-foreground">{reward.description}</p>
                              )}
                            </div>
                            <Gift className="h-5 w-5 text-primary" />
                          </div>
                          <div className="mt-4 flex items-center justify-between">
                            <Badge variant="secondary">
                              {reward.reward_type === "discount" && `$${(reward.reward_value_cents || 0) / 100} off`}
                              {reward.reward_type === "percentage_off" && `${reward.reward_percentage}% off`}
                              {reward.reward_type === "free_item" && "Free Item"}
                            </Badge>
                            <span className="font-bold text-primary">
                              {formatPoints(reward.points_required)} pts
                            </span>
                          </div>
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          <TabsContent value="settings" className="mt-4">
            <Card>
              <CardHeader>
                <CardTitle>Program Settings</CardTitle>
                <CardDescription>Configure how customers earn and redeem points</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="grid grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <Label>Points per $1 spent</Label>
                    <Input
                      type="number"
                      value={program?.points_per_dollar || 1}
                      onChange={(e) =>
                        updateProgram.mutate({ points_per_dollar: parseInt(e.target.value) || 1 })
                      }
                    />
                    <p className="text-xs text-muted-foreground">
                      Customers earn this many points for every dollar spent
                    </p>
                  </div>
                  <div className="space-y-2">
                    <Label>Signup Bonus Points</Label>
                    <Input
                      type="number"
                      value={program?.points_for_signup || 0}
                      onChange={(e) =>
                        updateProgram.mutate({ points_for_signup: parseInt(e.target.value) || 0 })
                      }
                    />
                    <p className="text-xs text-muted-foreground">
                      Bonus points awarded when a customer enrolls
                    </p>
                  </div>
                </div>

                <div className="pt-4 border-t">
                  <h4 className="font-medium mb-4">Tier Thresholds</h4>
                  <div className="grid grid-cols-4 gap-4">
                    {Object.entries(tierConfig).map(([tier, config]) => (
                      <div key={tier} className="text-center p-4 border rounded-lg">
                        <Badge className={config.color}>{tier}</Badge>
                        <p className="text-sm mt-2">{formatPoints(config.minPoints)}+ pts</p>
                      </div>
                    ))}
                  </div>
                </div>
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </PageContainer>

      {/* Add Reward Dialog */}
      <Dialog open={addRewardOpen} onOpenChange={setAddRewardOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Create Reward</DialogTitle>
            <DialogDescription>Add a new reward for customers to redeem</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Reward Name *</Label>
              <Input
                value={rewardName}
                onChange={(e) => setRewardName(e.target.value)}
                placeholder="e.g., $5 Off Your Order"
              />
            </div>
            <div className="space-y-2">
              <Label>Description</Label>
              <Input
                value={rewardDescription}
                onChange={(e) => setRewardDescription(e.target.value)}
                placeholder="Optional description"
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label>Points Required *</Label>
                <Input
                  type="number"
                  value={rewardPoints}
                  onChange={(e) => setRewardPoints(e.target.value)}
                  placeholder="100"
                />
              </div>
              <div className="space-y-2">
                <Label>Reward Type</Label>
                <Select value={rewardType} onValueChange={(v) => setRewardType(v as any)}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="discount">Fixed Discount ($)</SelectItem>
                    <SelectItem value="percentage_off">Percentage Off (%)</SelectItem>
                    <SelectItem value="free_item">Free Item</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            {rewardType !== "free_item" && (
              <div className="space-y-2">
                <Label>{rewardType === "discount" ? "Discount Amount ($)" : "Percentage Off"}</Label>
                <Input
                  type="number"
                  value={rewardValue}
                  onChange={(e) => setRewardValue(e.target.value)}
                  placeholder={rewardType === "discount" ? "5.00" : "10"}
                />
              </div>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddRewardOpen(false)}>Cancel</Button>
            <Button
              onClick={handleAddReward}
              disabled={!rewardName || !rewardPoints || createReward.isPending}
            >
              {createReward.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Create Reward
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Earn Points Dialog */}
      <Dialog open={earnPointsOpen} onOpenChange={setEarnPointsOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Award Points</DialogTitle>
            <DialogDescription>Award points to a customer based on purchase amount</DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Customer *</Label>
              <Select value={earnCustomerId} onValueChange={setEarnCustomerId}>
                <SelectTrigger>
                  <SelectValue placeholder="Select customer" />
                </SelectTrigger>
                <SelectContent>
                  {customers.map((c) => (
                    <SelectItem key={c.id} value={c.id}>
                      {c.full_name || c.phone_e164 || "Unknown"}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label>Purchase Amount ($) *</Label>
              <Input
                type="number"
                step="0.01"
                value={earnAmount}
                onChange={(e) => setEarnAmount(e.target.value)}
                placeholder="25.00"
              />
            </div>
            {earnAmount && program && (
              <p className="text-sm text-muted-foreground">
                Customer will earn <strong>{Math.floor(parseFloat(earnAmount) * program.points_per_dollar)}</strong> points
              </p>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setEarnPointsOpen(false)}>Cancel</Button>
            <Button
              onClick={handleEarnPoints}
              disabled={!earnCustomerId || !earnAmount || earnPoints.isPending}
            >
              {earnPoints.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Award Points
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Redeem Dialog */}
      <Dialog open={redeemOpen} onOpenChange={setRedeemOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Redeem Reward</DialogTitle>
            <DialogDescription>
              {selectedMember?.customer?.full_name} has {formatPoints(selectedMember?.points_balance || 0)} points
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label>Select Reward *</Label>
              <Select value={selectedRewardId} onValueChange={setSelectedRewardId}>
                <SelectTrigger>
                  <SelectValue placeholder="Choose a reward" />
                </SelectTrigger>
                <SelectContent>
                  {rewards
                    .filter((r) => r.points_required <= (selectedMember?.points_balance || 0))
                    .map((r) => (
                      <SelectItem key={r.id} value={r.id}>
                        {r.name} ({formatPoints(r.points_required)} pts)
                      </SelectItem>
                    ))}
                </SelectContent>
              </Select>
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setRedeemOpen(false)}>Cancel</Button>
            <Button
              onClick={handleRedeem}
              disabled={!selectedRewardId || redeemPoints.isPending}
            >
              {redeemPoints.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Redeem
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useModuleRequired } from "@/hooks/useModuleRequired";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { 
  Stethoscope, 
  Phone, 
  Clock, 
  Calendar,
  AlertTriangle,
  CheckCircle2,
  Shield,
  FileText,
  Loader2
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { format } from "date-fns";

const urgencyColors: Record<string, string> = {
  routine: "bg-muted text-muted-foreground",
  soon: "bg-blue-500/10 text-blue-700 dark:text-blue-300",
  urgent: "bg-destructive/10 text-destructive",
};

const statusColors: Record<string, string> = {
  pending: "bg-yellow-500/10 text-yellow-700 dark:text-yellow-300",
  scheduled: "bg-blue-500/10 text-blue-700 dark:text-blue-300",
  completed: "bg-green-500/10 text-green-700 dark:text-green-300",
  cancelled: "bg-muted text-muted-foreground",
};

export default function MedicalIntakePage() {
  // P0-3: Route protection - redirect if medical_intake module not enabled
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["medical_intake"]);
  
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [statusFilter, setStatusFilter] = useState<string>("pending");

  const { data: intakes, isLoading } = useQuery({
    queryKey: ["medical-intakes", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("medical_intakes")
        .select("*, customers(full_name, phone_e164), ai_call_sessions(started_at)")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false });

      if (error) throw error;
      return data || [];
    },
    enabled: !!tenant?.id,
  });

  const updateStatusMutation = useMutation({
    mutationFn: async ({ id, status }: { id: string; status: string }) => {
      const { error } = await supabase
        .from("medical_intakes")
        .update({ status })
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["medical-intakes"] });
      toast({ title: "Intake status updated" });
    },
    onError: (error: Error) => {
      toast({ variant: "destructive", title: "Error", description: error.message });
    },
  });

  const filteredIntakes = intakes?.filter(intake => 
    statusFilter === "all" || intake.status === statusFilter
  ) || [];

  const urgentIntakes = intakes?.filter(i => 
    i.urgency_level === "urgent" && i.status === "pending"
  ) || [];

  // Show loading while checking module access
  if (moduleLoading || !isAllowed) {
    return (
      <div className="p-6 flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="p-6 flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Medical Intake</h1>
          <p className="text-muted-foreground">Review patient intake requests from AI calls</p>
        </div>
        <Badge variant="outline" className="gap-1">
          <Shield className="h-3 w-3" />
          HIPAA Mode
        </Badge>
      </div>

      {/* Urgent Alert */}
      {urgentIntakes.length > 0 && (
        <Card className="border-destructive bg-destructive/5">
          <CardContent className="pt-4">
            <div className="flex items-center gap-3">
              <AlertTriangle className="h-5 w-5 text-destructive" />
              <div>
                <p className="font-medium text-destructive">
                  {urgentIntakes.length} Urgent Intake{urgentIntakes.length > 1 ? "s" : ""} Pending
                </p>
                <p className="text-sm text-muted-foreground">
                  These patients requested urgent appointments
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <Clock className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">Pending Review</span>
            </div>
            <p className="text-2xl font-bold mt-1">
              {intakes?.filter(i => i.status === "pending").length || 0}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">Scheduled</span>
            </div>
            <p className="text-2xl font-bold mt-1">
              {intakes?.filter(i => i.status === "scheduled").length || 0}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <Stethoscope className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">New Patients</span>
            </div>
            <p className="text-2xl font-bold mt-1">
              {intakes?.filter(i => i.intake_type === "new_patient").length || 0}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">With Consent</span>
            </div>
            <p className="text-2xl font-bold mt-1">
              {intakes?.filter(i => i.verbal_consent_given).length || 0}
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Filter */}
      <div className="flex items-center gap-4">
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-[180px]">
            <SelectValue placeholder="Filter by status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All Intakes</SelectItem>
            <SelectItem value="pending">Pending Review</SelectItem>
            <SelectItem value="scheduled">Scheduled</SelectItem>
            <SelectItem value="completed">Completed</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
          </SelectContent>
        </Select>
        <span className="text-sm text-muted-foreground">
          {filteredIntakes.length} intake{filteredIntakes.length !== 1 ? "s" : ""}
        </span>
      </div>

      {/* Intakes Table */}
      <Card>
        <CardContent className="p-0">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Date</TableHead>
                <TableHead>Type</TableHead>
                <TableHead>Urgency</TableHead>
                <TableHead>Reason</TableHead>
                <TableHead>Preferred Date</TableHead>
                <TableHead>Consent</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {filteredIntakes.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={8} className="h-24">
                    <div className="flex flex-col items-center justify-center text-center">
                      <Stethoscope className="h-8 w-8 text-muted-foreground/40 mb-2" />
                      <p className="text-sm font-medium">No patient intakes yet</p>
                      <p className="text-xs text-muted-foreground mt-0.5">
                        {statusFilter !== "all"
                          ? "Try adjusting your filters."
                          : "When patients call and provide intake information, it will appear here."}
                      </p>
                    </div>
                  </TableCell>
                </TableRow>
              ) : (
                filteredIntakes.map((intake) => (
                  <TableRow key={intake.id}>
                    <TableCell>
                      {format(new Date(intake.created_at), "MMM d, h:mm a")}
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline" className="capitalize">
                        {(intake.intake_type || "unknown").replace(/_/g, " ")}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge className={urgencyColors[intake.urgency_level || "routine"] || ""}>
                        {intake.urgency_level || "routine"}
                      </Badge>
                    </TableCell>
                    <TableCell className="max-w-[200px] truncate">
                      {intake.reason_for_visit || "-"}
                    </TableCell>
                    <TableCell>
                      {intake.preferred_date 
                        ? format(new Date(intake.preferred_date), "MMM d, yyyy")
                        : "-"
                      }
                    </TableCell>
                    <TableCell>
                      {intake.verbal_consent_given ? (
                        <CheckCircle2 className="h-4 w-4 text-success" />
                      ) : (
                        <span className="text-muted-foreground">-</span>
                      )}
                    </TableCell>
                    <TableCell>
                      <Badge className={statusColors[intake.status] || ""}>
                        {intake.status}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Select
                        value={intake.status}
                        onValueChange={(status) => 
                          updateStatusMutation.mutate({ id: intake.id, status })
                        }
                      >
                        <SelectTrigger className="w-[120px]">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="pending">Pending</SelectItem>
                          <SelectItem value="scheduled">Scheduled</SelectItem>
                          <SelectItem value="completed">Completed</SelectItem>
                          <SelectItem value="cancelled">Cancelled</SelectItem>
                        </SelectContent>
                      </Select>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      {/* Privacy Notice */}
      <Card className="border-muted bg-muted/20">
        <CardContent className="pt-4">
          <div className="flex items-start gap-3">
            <Shield className="h-5 w-5 text-muted-foreground mt-0.5" />
            <div>
              <p className="font-medium">HIPAA Compliance Notice</p>
              <p className="text-sm text-muted-foreground">
                Full call transcripts and recordings are not stored by default. Only structured intake 
                data and AI summaries are retained. Adjust retention settings in Medical Settings.
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * OnboardingPage — 7-phase industry-aware onboarding flow.
 * Form state extracted to useOnboardingFormState, submission to useOnboardingSubmit.
 */
import { useState, useEffect } from "react";
import { StepNavigator } from "@/components/onboarding/StepNavigator";
import { useNavigate, Navigate } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { useToast } from "@/hooks/use-toast";
import {
  Building2, CheckCircle2, Loader2,
  ChevronRight, ChevronLeft,
  RefreshCw, Briefcase, Sparkles, Link2, Rocket,
  Settings2, Clock,
} from "lucide-react";
import { useOnboardingValidation } from "@/hooks/useOnboardingValidation";
import { useOnboardingProgress, ONBOARDING_PHASES } from "@/hooks/useOnboardingProgress";
import { useOnboardingFormState, clearOnboardingData } from "@/hooks/useOnboardingFormState";
import { useOnboardingSubmit } from "@/hooks/useOnboardingSubmit";
import { OnboardingComplete } from "@/components/onboarding/OnboardingComplete";
import { ResumeOnboardingModal } from "@/components/onboarding/ResumeOnboardingModal";
import { AutoSaveIndicator } from "@/components/onboarding/AutoSaveIndicator";
import { WebsiteQuickStart } from "@/components/onboarding/WebsiteQuickStart";
import { mapWebsiteImportToOnboarding } from "@/lib/mapWebsiteImportToOnboarding";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel,
  AlertDialogContent, AlertDialogDescription, AlertDialogFooter,
  AlertDialogHeader, AlertDialogTitle,
} from "@/components/ui/alert-dialog";

// Phase sub-components
import { OnboardingIdentity } from "@/components/onboarding/phases/OnboardingIdentity";
import { OnboardingHowYouWork } from "@/components/onboarding/phases/OnboardingHowYouWork";
import { OnboardingOfferings } from "@/components/onboarding/phases/OnboardingOfferings";
import { OnboardingHoursArea } from "@/components/onboarding/phases/OnboardingHoursArea";
import { OnboardingAI } from "@/components/onboarding/phases/OnboardingAI";
import { OnboardingConnect } from "@/components/onboarding/phases/OnboardingConnect";
import { OnboardingReview } from "@/components/onboarding/phases/OnboardingReview";

/** Phase icons for sidebar — 7 phases */
const PHASE_ICONS = [Building2, Settings2, Briefcase, Clock, Sparkles, Link2, Rocket];

export default function OnboardingPage() {
  const { user, tenant, loading: authLoading } = useAuth();
  const userId = user?.id;
  const navigate = useNavigate();
  const { toast } = useToast();

  const {
    phase, currentPhase, progressPercent, totalPhases, totalMinutes,
    hasSavedProgress, goNext: progressGoNext, goBack: progressGoBack,
    goToPhase, resetProgress, clearProgress,
  } = useOnboardingProgress(userId);

  const form = useOnboardingFormState(userId);
  const submit = useOnboardingSubmit(userId);

  const { validateStep, getFieldError, clearErrors } = useOnboardingValidation();

  // Resume modal
  const [showResumeModal, setShowResumeModal] = useState(() => hasSavedProgress);
  const [resumeDecided, setResumeDecided] = useState(!hasSavedProgress);

  // Import conflict dialog
  const [showImportConflictDialog, setShowImportConflictDialog] = useState(false);
  const [pendingIndustrySlug, setPendingIndustrySlug] = useState("");

  const handleResume = () => { setShowResumeModal(false); setResumeDecided(true); };
  const handleStartFresh = () => {
    setShowResumeModal(false);
    setResumeDecided(true);
    clearOnboardingData(userId);
    resetProgress();
    form.resetFormState();
  };

  // Industry change handler that checks for import conflict
  const handleIndustryChange = (slug: string) => {
    if (form.websiteImportActive) {
      setPendingIndustrySlug(slug);
      setShowImportConflictDialog(true);
    } else {
      form.setIndustrySlug(slug);
    }
  };

  // Auto-save debounced
  useEffect(() => {
    return form.triggerAutoSave(submit.isComplete, resumeDecided);
  }, [phase, form.businessName, form.businessAddress, form.businessMode, form.industrySlug, form.workStyle,
    form.scenarioAnswers, form.scenarioDetails, form.schedulingPrefs, form.communicationPrefs,
    form.templateServices, form.templateFAQs, form.templatePolicies, form.serviceArea,
    form.businessDetails, form.businessHours, form.teamMembers, form.isSoloOperator,
    form.a2pData, form.aiTone, form.bookingMode, form.afterHours, form.customGreeting,
    form.notificationPhone, form.otherDescription, submit.isComplete, resumeDecided, userId]);

  // Redirect if already has tenant
  useEffect(() => {
    if (!authLoading && tenant) navigate("/app/dashboard", { replace: true });
  }, [authLoading, tenant, navigate]);

  // Phase validation
  const canProceed = (phaseNum: number) => {
    switch (phaseNum) {
      case 1: return form.businessName.trim().length > 0 && form.industrySlug.length > 0;
      case 2: return true; // work style + scenario questions are optional
      case 3: return form.templateServices.some(s => s.enabled && s.name.trim().length > 0);
      case 4: return true; // hours have defaults
      case 5: return true; // AI settings have defaults
      case 6: return true; // connect is optional
      case 7: return true; // review
      default: return false;
    }
  };

  // Loading state
  if (authLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="text-center space-y-4">
          <Loader2 className="h-8 w-8 animate-spin mx-auto text-primary" />
          <p className="text-muted-foreground">Loading...</p>
        </div>
      </div>
    );
  }

  if (!user) return <Navigate to="/login" replace />;

  if (tenant) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="text-center space-y-4">
          <CheckCircle2 className="h-8 w-8 mx-auto text-primary" />
          <p className="text-muted-foreground">Redirecting to dashboard...</p>
        </div>
      </div>
    );
  }

  const buildSubmitParams = () => ({
    businessName: form.businessName,
    businessAddress: form.businessAddress,
    businessMode: form.businessMode,
    industrySlug: form.industrySlug,
    workStyle: form.workStyle,
    enabledModules: form.enabledModules,
    scenarioAnswers: form.scenarioAnswers,
    scenarioDetails: form.scenarioDetails,
    schedulingPrefs: form.schedulingPrefs,
    communicationPrefs: form.communicationPrefs,
    templateServices: form.templateServices,
    templateFAQs: form.templateFAQs,
    templatePolicies: form.templatePolicies,
    serviceArea: form.serviceArea,
    businessDetails: form.businessDetails,
    businessHours: form.businessHours as Record<string, unknown>,
    teamMembers: form.teamMembers,
    isSoloOperator: form.isSoloOperator,
    a2pData: form.a2pData,
    aiTone: form.aiTone,
    bookingMode: form.bookingMode,
    afterHours: form.afterHours,
    customGreeting: form.customGreeting,
    notificationPhone: form.notificationPhone,
    otherDescription: form.otherDescription,
  });

  const goNext = () => {
    if (phase === 1) {
      const isValid = validateStep("identity", { businessName: form.businessName, industrySlug: form.industrySlug, businessDetails: form.businessDetails });
      if (!isValid) return;
    } else if (phase === 3) {
      const isValid = validateStep("services-preview", { templateServices: form.templateServices });
      if (!isValid) return;
    }
    clearErrors();
    if (phase < totalPhases) progressGoNext();
  };

  const goBack = () => {
    clearErrors();
    if (phase > 1) progressGoBack();
  };

  const REVIEW_PHASE = totalPhases; // 7

  return (
    <div className="min-h-screen bg-background flex">
      {/* Desktop Sidebar — hidden during quick start */}
      {phase >= 1 && (
        <StepNavigator
          steps={ONBOARDING_PHASES}
          icons={PHASE_ICONS}
          currentStep={phase}
          onStepClick={goToPhase}
          totalMinutes={totalMinutes}
        />
      )}

      {/* Main Content */}
      <main className="flex-1 flex flex-col min-h-screen">
        {/* Mobile Progress — hidden during quick start */}
        {phase >= 1 && (
          <div className="lg:hidden p-4 border-b bg-card">
            <div className="flex items-center justify-between mb-2">
              <p className="text-sm font-medium">
                Step {phase} of {totalPhases} — {currentPhase.title}
              </p>
              <span className="text-sm font-medium text-muted-foreground">{progressPercent}%</span>
            </div>
            <Progress value={progressPercent} className="h-1.5" />
          </div>
        )}

        {/* Desktop Progress Bar — hidden during quick start */}
        {phase >= 1 && (
          <div className="hidden lg:block px-6 pt-6">
            <div className="max-w-2xl mx-auto">
              <div className="flex items-center justify-between mb-2">
                <p className="text-sm text-muted-foreground">
                  Step {phase} of {totalPhases} — {currentPhase.title}
                </p>
                <div className="flex items-center gap-3">
                  <span className="text-sm font-medium text-muted-foreground">{progressPercent}%</span>
                  <AutoSaveIndicator status={form.saveStatus} />
                </div>
              </div>
              <Progress value={progressPercent} className="h-2" />
            </div>
          </div>
        )}

        {/* Step Content */}
        <div className={`flex-1 flex justify-center p-6 overflow-y-auto ${phase === 0 ? "items-center" : "items-start"}`}>
          <div className="w-full max-w-2xl">
            <AnimatePresence mode="wait">
              {phase === 0 ? (
                <motion.div
                  key="quickstart"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ duration: 0.2 }}
                >
                  <WebsiteQuickStart
                    onImportComplete={(result) => {
                      const mapped = mapWebsiteImportToOnboarding(result);
                      form.applyWebsiteImport(mapped);
                      progressGoNext(); // advance to Phase 1
                    }}
                    onSkip={() => progressGoNext()}
                  />
                </motion.div>
              ) : submit.isComplete ? (
                <motion.div
                  key="complete"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ duration: 0.2 }}
                >
                  <OnboardingComplete
                    businessName={form.businessName}
                    phoneNumber={submit.provisionedPhone}
                    businessMode={form.businessMode}
                    scenarioAnswers={form.scenarioAnswers}
                    industrySlug={form.industrySlug}
                  />
                </motion.div>
              ) : (
                <motion.div
                  key={phase}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -10 }}
                  transition={{ duration: 0.2 }}
                >
                  {/* Phase 1: Your Business */}
                  {phase === 1 && (
                    <OnboardingIdentity
                      businessName={form.businessName}
                      onBusinessNameChange={form.setBusinessName}
                      businessAddress={form.businessAddress}
                      onBusinessAddressChange={form.setBusinessAddress}
                      industrySlug={form.industrySlug}
                      onIndustryChange={handleIndustryChange}
                      businessMode={form.businessMode}
                      onBusinessModeChange={form.handleBusinessModeChange}
                      workStyle={form.workStyle}
                      getFieldError={getFieldError}
                      otherDescription={form.otherDescription}
                      onOtherDescriptionChange={form.setOtherDescription}
                    />
                  )}
                  {/* Phase 2: How You Work */}
                  {phase === 2 && (
                    <OnboardingHowYouWork
                      businessMode={form.businessMode}
                      industrySlug={form.industrySlug}
                      workStyle={form.workStyle}
                      onWorkStyleChange={form.setWorkStyle}
                      scenarioAnswers={form.scenarioAnswers}
                      onScenarioAnswersChange={form.setScenarioAnswers}
                      scenarioDetails={form.scenarioDetails}
                      onScenarioDetailsChange={form.setScenarioDetails}
                    />
                  )}
                  {/* Phase 3: Your Offerings */}
                  {phase === 3 && (
                    <OnboardingOfferings
                      businessMode={form.businessMode}
                      industrySlug={form.industrySlug}
                      services={form.templateServices}
                      onServicesChange={form.setTemplateServices}
                    />
                  )}
                  {/* Phase 4: Hours & Area */}
                  {phase === 4 && (
                    <OnboardingHoursArea
                      businessMode={form.businessMode}
                      hours={form.businessHours}
                      onHoursChange={form.setBusinessHours}
                      is24x7={form.schedulingPrefs.is24x7}
                      onIs24x7Change={(v) => form.setSchedulingPrefs({ ...form.schedulingPrefs, is24x7: v })}
                      serviceArea={form.serviceArea}
                      onServiceAreaChange={form.setServiceArea}
                      workStyle={form.workStyle}
                    />
                  )}
                  {/* Phase 5: Your AI Assistant */}
                  {phase === 5 && (
                    <OnboardingAI
                      businessName={form.businessName}
                      businessMode={form.businessMode}
                      aiTone={form.aiTone}
                      onAiToneChange={form.setAiTone}
                      bookingMode={form.bookingMode}
                      onBookingModeChange={form.setBookingMode}
                      afterHours={form.afterHours}
                      onAfterHoursChange={form.setAfterHours}
                      customGreeting={form.customGreeting}
                      onCustomGreetingChange={form.setCustomGreeting}
                    />
                  )}
                  {/* Phase 6: Connect Tools */}
                  {phase === 6 && (
                    <OnboardingConnect
                      businessMode={form.businessMode}
                      notificationPhone={form.notificationPhone}
                      onNotificationPhoneChange={form.setNotificationPhone}
                      calendarConnected={form.calendarConnected}
                      onConnectCalendar={() => {
                        toast({ title: "Calendar", description: "Calendar connection will be available after setup." });
                      }}
                      onConnectIntegration={(providerId) => {
                        toast({ title: "Coming soon", description: `${providerId} integration will be available after setup.` });
                      }}
                    />
                  )}
                  {/* Phase 7: Review & Launch */}
                  {phase === REVIEW_PHASE && (
                    <OnboardingReview
                      businessName={form.businessName}
                      businessAddress={form.businessAddress}
                      businessMode={form.businessMode}
                      industrySlug={form.industrySlug}
                      services={form.templateServices}
                      templateFAQs={form.templateFAQs}
                      templatePolicies={form.templatePolicies}
                      businessHours={form.businessHours}
                      aiTone={form.aiTone}
                      bookingMode={form.bookingMode}
                      afterHours={form.afterHours}
                      is24x7={form.schedulingPrefs.is24x7}
                      workStyle={form.workStyle}
                      serviceAreaRadius={form.serviceArea.radiusMiles}
                      scenarioAnswers={form.scenarioAnswers}
                      customGreeting={form.customGreeting}
                      onEditPhase={goToPhase}
                      onTestAI={() => toast({ title: "Test AI", description: "AI testing will be available after setup." })}
                      onGoLive={() => submit.handleComplete(buildSubmitParams(), clearProgress)}
                      loading={submit.loading}
                    />
                  )}
                </motion.div>
              )}
            </AnimatePresence>
          </div>
        </div>

        {/* Footer Navigation — hidden during quick start and review */}
        {!submit.isComplete && phase >= 1 && phase < REVIEW_PHASE && (
          <div className="border-t bg-card p-6">
            <div className="max-w-2xl mx-auto space-y-3">
              {submit.completionError && (
                <div className="p-3 rounded-md bg-destructive/10 text-destructive text-sm text-center">
                  {submit.completionError}
                </div>
              )}
              <div className="flex justify-between gap-4">
                <Button variant="ghost" onClick={goBack} disabled={phase === 1} className="gap-2">
                  <ChevronLeft className="w-4 h-4" />
                  Back
                </Button>
                <div className="flex gap-2">
                  {phase === 6 && (
                    <Button variant="ghost" onClick={goNext} className="text-muted-foreground">
                      Skip for now
                    </Button>
                  )}
                  <Button
                    variant="outline"
                    onClick={() => {
                      toast({ title: "Progress saved", description: "You can resume anytime." });
                      navigate("/");
                    }}
                  >
                    Save & Exit
                  </Button>
                  <Button
                    onClick={goNext}
                    disabled={!canProceed(phase)}
                    className="gap-2 min-w-[140px]"
                  >
                    Continue
                    <ChevronRight className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Review phase retry buttons */}
        {!submit.isComplete && phase === REVIEW_PHASE && submit.showRetry && !submit.loading && (
          <div className="border-t bg-card p-6">
            <div className="max-w-2xl mx-auto flex justify-center gap-3">
              <Button variant="ghost" onClick={() => goToPhase(1)} className="gap-2">
                <ChevronLeft className="w-4 h-4" />
                Go back and edit
              </Button>
              <Button variant="outline" onClick={() => submit.handleRetry(buildSubmitParams(), clearProgress)} className="gap-2">
                <RefreshCw className="w-4 h-4" />
                Retry ({submit.MAX_RETRIES - submit.retryCount} left)
              </Button>
            </div>
          </div>
        )}
      </main>

      {/* Resume Modal */}
      <ResumeOnboardingModal
        open={showResumeModal}
        savedAt={form.saved.current?.savedAt}
        onResume={handleResume}
        onStartFresh={handleStartFresh}
      />

      {/* Import Conflict Dialog */}
      <AlertDialog open={showImportConflictDialog} onOpenChange={setShowImportConflictDialog}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Replace imported data?</AlertDialogTitle>
            <AlertDialogDescription>
              You imported services, FAQs, and hours from your website. Changing your industry will replace them with default templates.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel
              onClick={() => {
                // Keep imported data, just change industry for mode/modules
                form.setIndustrySlug(pendingIndustrySlug);
                setShowImportConflictDialog(false);
              }}
            >
              Keep my imported data
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                form.clearWebsiteImport();
                form.setIndustrySlug(pendingIndustrySlug);
                setShowImportConflictDialog(false);
              }}
            >
              Use industry defaults
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

 import { useState, useMemo } from "react";
 import { useAuth } from "@/contexts/AuthContext";
 import { supabase } from "@/integrations/supabase/client";
import type { Database } from "@/integrations/supabase/types";
 import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
 import { useModuleRequired } from "@/hooks/useModuleRequired";
 import { Card, CardContent } from "@/components/ui/card";
 import { Button } from "@/components/ui/button";
 import { Badge } from "@/components/ui/badge";
 import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
 import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
 import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
 import { Input } from "@/components/ui/input";
 import { Label } from "@/components/ui/label";
 import { Textarea } from "@/components/ui/textarea";
 import { PageContainer } from "@/components/layout/PageContainer";
 import { PageHeader } from "@/components/layout/PageHeader";
 import {
   UtensilsCrossed,
   Plus,
   Loader2,
   ChevronLeft,
   ChevronRight,
   AlertTriangle,
 } from "lucide-react";
 import { useToast } from "@/hooks/use-toast";
 import { OrderDetailsDrawer } from "@/components/orders/OrderDetailsDrawer";
 import { OrderCard } from "@/components/orders/OrderCard";
 import { EmptyState } from "@/components/ui/empty-state";
 import { useNavigate } from "react-router-dom";
 
 interface FoodOrder {
   id: string;
   tenant_id: string;
   order_number: string;
   order_type: string;
   status: string;
   customer_id: string | null;
   customer_name: string | null;
   customer_phone: string | null;
   delivery_address: string | null;
   address_json: unknown;
   items_json: unknown;
   special_instructions: string | null;
   requested_time: string | null;
   totals_estimate: unknown;
   handoff_state: unknown;
   subtotal_cents: number | null;
   tax_cents: number | null;
   total_cents: number | null;
   created_at: string;
 }
 
 type StatusFilter = "all" | "pending" | "preparing" | "ready" | "completed";
 
 export default function OrdersPage() {
   const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["food_orders"]);
   
   const { tenant } = useAuth();
   const { toast } = useToast();
   const queryClient = useQueryClient();
   const navigate = useNavigate();
   const [statusFilter, setStatusFilter] = useState<StatusFilter>("all");
   const [orderTypeFilter, setOrderTypeFilter] = useState<string>("all");
   const [selectedOrder, setSelectedOrder] = useState<FoodOrder | null>(null);
   const [drawerOpen, setDrawerOpen] = useState(false);
   const [newOrderOpen, setNewOrderOpen] = useState(false);
   const [newOrder, setNewOrder] = useState({ customer_name: "", order_type: "pickup", items: "", special_instructions: "" });
   const [isCreating, setIsCreating] = useState(false);
  const [page, setPage] = useState(0);
  const pageSize = 24;
 
   const { data: orders, isLoading, error: ordersError } = useQuery({
     queryKey: ["food-orders", tenant?.id],
     queryFn: async () => {
       if (!tenant?.id) return [];
       const { data, error } = await supabase
         .from("food_orders")
         .select("*")
         .eq("tenant_id", tenant.id)
         .order("created_at", { ascending: false });
 
       if (error) throw error;
       return (data || []) as FoodOrder[];
     },
     enabled: !!tenant?.id,
     refetchInterval: 10000,
   });
 
   const updateStatusMutation = useMutation({
     mutationFn: async ({ orderId, status }: { orderId: string; status: string }) => {
       const { error } = await supabase
         .from("food_orders")
         .update({ status: status as Database["public"]["Enums"]["order_status"] })
         .eq("id", orderId);
       if (error) throw error;
     },
     onSuccess: () => {
       queryClient.invalidateQueries({ queryKey: ["food-orders", tenant?.id] });
       toast({ title: "Order status updated" });
     },
     onError: (error: Error) => {
       toast({ variant: "destructive", title: "Error", description: error.message });
     },
   });
 
   const handleViewOrder = (order: FoodOrder) => {
     setSelectedOrder(order);
     setDrawerOpen(true);
   };

   const handleCreateOrder = async () => {
     if (!tenant?.id || !newOrder.customer_name.trim()) return;
     setIsCreating(true);
     try {
       const itemsList = newOrder.items.split("\n").filter(Boolean).map((name, i) => ({
         id: `item-${i}`,
         name: name.trim(),
         quantity: 1,
       }));
       const orderNum = `ORD-${Date.now().toString(36).toUpperCase()}`;
       const { error } = await (supabase as any).from("food_orders").insert({
         tenant_id: tenant.id,
         order_number: orderNum,
         order_type: newOrder.order_type as any,
         status: "pending" as any,
         customer_name: newOrder.customer_name,
         items_json: itemsList as any,
         special_instructions: newOrder.special_instructions || null,
       });
       if (error) throw error;
       queryClient.invalidateQueries({ queryKey: ["food-orders", tenant.id] });
       toast({ title: "Order created" });
       setNewOrderOpen(false);
       setNewOrder({ customer_name: "", order_type: "pickup", items: "", special_instructions: "" });
     } catch (err: any) {
       toast({ variant: "destructive", title: "Error", description: err.message });
     } finally {
       setIsCreating(false);
     }
   };

   // Filter orders
   const filteredOrders = useMemo(() => {
     if (!orders) return [];
     
     return orders.filter((order) => {
       // Status filter
       if (statusFilter === "pending" && !["pending", "confirmed"].includes(order.status)) return false;
       if (statusFilter === "preparing" && order.status !== "preparing") return false;
       if (statusFilter === "ready" && !["ready", "out_for_delivery"].includes(order.status)) return false;
       if (statusFilter === "completed" && !["completed", "cancelled"].includes(order.status)) return false;
       
       // Order type filter
       if (orderTypeFilter !== "all" && order.order_type !== orderTypeFilter) return false;
       
       return true;
     });
   }, [orders, statusFilter, orderTypeFilter]);

  // Reset page when filters change
  const handleStatusFilter = (v: string) => {
    setStatusFilter(v as StatusFilter);
    setPage(0);
  };
  const handleTypeFilter = (v: string) => {
    setOrderTypeFilter(v);
    setPage(0);
  };

  // Pagination
  const totalPages = Math.ceil(filteredOrders.length / pageSize);
  const paginatedOrders = filteredOrders.slice(page * pageSize, (page + 1) * pageSize);

   // Stats
   const pendingCount = orders?.filter(o => ["pending", "confirmed"].includes(o.status)).length || 0;
   const preparingCount = orders?.filter(o => o.status === "preparing").length || 0;
   const readyCount = orders?.filter(o => ["ready", "out_for_delivery"].includes(o.status)).length || 0;
 
   if (moduleLoading || !isAllowed) {
     return (
       <div className="p-6 flex items-center justify-center">
         <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
       </div>
     );
   }
 
   if (isLoading) {
     return (
       <div className="p-6 flex items-center justify-center">
         <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
       </div>
     );
   }

   if (ordersError) {
     return (
       <div className="container max-w-6xl py-8 px-4 sm:px-6">
         <div className="mx-auto max-w-lg py-16">
           <Card>
             <CardContent className="pt-8 pb-8 text-center space-y-4">
               <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-destructive/10">
                 <AlertTriangle className="h-7 w-7 text-destructive" />
               </div>
               <h2 className="text-xl font-semibold">Something went wrong</h2>
               <p className="text-sm text-muted-foreground max-w-sm mx-auto">
                 We couldn't load your orders. Please refresh the page or try again later.
               </p>
               <Button variant="outline" onClick={() => window.location.reload()}>
                 Refresh Page
               </Button>
             </CardContent>
           </Card>
         </div>
       </div>
     );
   }

   return (
     <PageContainer maxWidth="xl">
       <div className="space-y-6">
         <PageHeader
           icon={<UtensilsCrossed className="h-5 w-5" />}
           title="Orders"
           description="Manage incoming food orders"
           action={
             <Button onClick={() => setNewOrderOpen(true)}>
               <Plus className="h-4 w-4 mr-2" />
               New Order
             </Button>
           }
         />
 
         {/* Filters */}
         <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
           <Tabs value={statusFilter} onValueChange={handleStatusFilter}>
             <TabsList>
               <TabsTrigger value="all">All</TabsTrigger>
               <TabsTrigger value="pending" className="gap-1.5">
                 Pending
                 {pendingCount > 0 && (
                   <Badge variant="secondary" className="h-5 px-1.5 text-xs">
                     {pendingCount}
                   </Badge>
                 )}
               </TabsTrigger>
               <TabsTrigger value="preparing" className="gap-1.5">
                 Preparing
                 {preparingCount > 0 && (
                   <Badge variant="secondary" className="h-5 px-1.5 text-xs">
                     {preparingCount}
                   </Badge>
                 )}
               </TabsTrigger>
               <TabsTrigger value="ready" className="gap-1.5">
                 Ready
                 {readyCount > 0 && (
                   <Badge variant="secondary" className="h-5 px-1.5 text-xs">
                     {readyCount}
                   </Badge>
                 )}
               </TabsTrigger>
               <TabsTrigger value="completed">Completed</TabsTrigger>
             </TabsList>
           </Tabs>
 
           <Select value={orderTypeFilter} onValueChange={handleTypeFilter}>
             <SelectTrigger className="w-32">
               <SelectValue placeholder="Type" />
             </SelectTrigger>
             <SelectContent>
               <SelectItem value="all">All Types</SelectItem>
               <SelectItem value="pickup">Pickup</SelectItem>
               <SelectItem value="delivery">Delivery</SelectItem>
               <SelectItem value="dine_in">Dine In</SelectItem>
             </SelectContent>
           </Select>
         </div>
 
         {/* Orders grid */}
         {filteredOrders.length === 0 ? (
           <EmptyState
             icon={UtensilsCrossed}
             title="No orders yet"
             description={
               statusFilter !== "all" || orderTypeFilter !== "all"
                 ? "Try adjusting your filters to see more results."
                 : "When customers place orders through your AI, they'll appear here."
             }
             action={
               statusFilter === "all" && orderTypeFilter === "all"
                 ? { label: "Create Order", onClick: () => setNewOrderOpen(true) }
                 : undefined
             }
           />
         ) : (
           <>
             <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
               {paginatedOrders.map((order) => (
                 <OrderCard
                   key={order.id}
                   order={order}
                   onView={() => handleViewOrder(order)}
                   onStatusChange={(status) => updateStatusMutation.mutate({ orderId: order.id, status })}
                   isUpdating={updateStatusMutation.isPending}
                 />
               ))}
             </div>
             {totalPages > 1 && (
               <div className="flex items-center justify-between pt-4">
                 <p className="text-sm text-muted-foreground">
                   Showing {page * pageSize + 1}–{Math.min((page + 1) * pageSize, filteredOrders.length)} of {filteredOrders.length}
                 </p>
                 <div className="flex items-center gap-2">
                   <Button variant="outline" size="sm" onClick={() => setPage(p => p - 1)} disabled={page === 0}>
                     <ChevronLeft className="h-4 w-4" />
                   </Button>
                   <span className="text-sm text-muted-foreground">
                     {page + 1} / {totalPages}
                   </span>
                   <Button variant="outline" size="sm" onClick={() => setPage(p => p + 1)} disabled={page >= totalPages - 1}>
                     <ChevronRight className="h-4 w-4" />
                   </Button>
                 </div>
               </div>
             )}
           </>
         )}
       </div>
 
       {/* Order Details Drawer */}
       <OrderDetailsDrawer
         order={selectedOrder}
         open={drawerOpen}
         onOpenChange={setDrawerOpen}
       />

       {/* New Order Dialog */}
       <Dialog open={newOrderOpen} onOpenChange={setNewOrderOpen}>
         <DialogContent>
           <DialogHeader>
             <DialogTitle>Create New Order</DialogTitle>
           </DialogHeader>
           <div className="space-y-4 py-2">
             <div className="space-y-2">
               <Label htmlFor="order-customer">Customer Name</Label>
               <Input
                 id="order-customer"
                 placeholder="Customer name"
                 value={newOrder.customer_name}
                 onChange={(e) => setNewOrder(prev => ({ ...prev, customer_name: e.target.value }))}
               />
             </div>
             <div className="space-y-2">
               <Label htmlFor="order-type">Order Type</Label>
               <Select value={newOrder.order_type} onValueChange={(v) => setNewOrder(prev => ({ ...prev, order_type: v }))}>
                 <SelectTrigger id="order-type">
                   <SelectValue />
                 </SelectTrigger>
                 <SelectContent>
                   <SelectItem value="pickup">Pickup</SelectItem>
                   <SelectItem value="delivery">Delivery</SelectItem>
                   <SelectItem value="dine_in">Dine In</SelectItem>
                 </SelectContent>
               </Select>
             </div>
             <div className="space-y-2">
               <Label htmlFor="order-items">Items (one per line)</Label>
               <Textarea
                 id="order-items"
                 placeholder={"Cheeseburger\nFrench Fries\nChocolate Shake"}
                 rows={4}
                 value={newOrder.items}
                 onChange={(e) => setNewOrder(prev => ({ ...prev, items: e.target.value }))}
               />
             </div>
             <div className="space-y-2">
               <Label htmlFor="order-instructions">Special Instructions</Label>
               <Textarea
                 id="order-instructions"
                 placeholder="Any special requests..."
                 rows={2}
                 value={newOrder.special_instructions}
                 onChange={(e) => setNewOrder(prev => ({ ...prev, special_instructions: e.target.value }))}
               />
             </div>
           </div>
           <DialogFooter>
             <Button variant="outline" onClick={() => setNewOrderOpen(false)}>Cancel</Button>
             <Button onClick={handleCreateOrder} disabled={isCreating || !newOrder.customer_name.trim()}>
               {isCreating ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : null}
               Create Order
             </Button>
           </DialogFooter>
         </DialogContent>
       </Dialog>
     </PageContainer>
   );
 }

/**
 * Readiness Fix Center
 *
 * Centralized page for diagnosing and fixing AI readiness issues.
 * Routes users to the correct place (Business Brain, Integrations, etc.)
 * instead of incorrectly sending them to plan selection.
 */

import { Link, useNavigate } from "react-router-dom";
import { useAIReadinessV2, formatReadinessFlag } from "@/hooks/useAIReadinessV2";
import { getIssueDetails, isPlanGatedIssue, type ReadinessIssue, type FixType } from "@/lib/readiness/issueMapping";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  Brain,
  AlertTriangle,
  CheckCircle2,
  ChevronRight,
  ChevronLeft,
  Sparkles,
  XCircle,
  Info,
  Loader2,
  Link2,
  CreditCard,
  Settings,
  Wrench,
  Rocket,
  ArrowRight,
} from "lucide-react";

const fixTypeIcons: Record<FixType, React.ElementType> = {
  brain: Brain,
  integration: Link2,
  plan: CreditCard,
  settings: Settings,
};

const fixTypeColors: Record<FixType, string> = {
  brain: "bg-purple-500/10 text-purple-600 dark:text-purple-400 border-purple-500/20",
  integration: "bg-blue-500/10 text-blue-600 dark:text-blue-400 border-blue-500/20",
  plan: "bg-amber-500/10 text-amber-600 dark:text-amber-400 border-amber-500/20",
  settings: "bg-slate-500/10 text-slate-600 dark:text-slate-400 border-slate-500/20",
};

export default function ReadinessFixCenterPage() {
  const navigate = useNavigate();
  const {
    score,
    p0Flags,
    p1Flags,
    recommendations,
    canGoLive,
    isReady,
    loading,
    businessMode,
    refetch,
  } = useAIReadinessV2();

  // Convert flags to full issue details
  const p0Issues = p0Flags.map(getIssueDetails);
  const p1Issues = p1Flags.map(getIssueDetails);
  const allIssues = [...p0Issues, ...p1Issues];

  // Separate plan-gated from fixable
  const planGatedIssues = allIssues.filter((i) => isPlanGatedIssue(i.code));
  const fixableIssues = allIssues.filter((i) => !isPlanGatedIssue(i.code));

  const getScoreColor = () => {
    if (score >= 85) return "text-emerald-500";
    if (score >= 70) return "text-amber-500";
    if (score >= 50) return "text-orange-500";
    return "text-rose-500";
  };

  const getProgressColor = () => {
    if (score >= 85) return "[&>div]:bg-emerald-500";
    if (score >= 70) return "[&>div]:bg-amber-500";
    if (score >= 50) return "[&>div]:bg-orange-500";
    return "[&>div]:bg-rose-500";
  };

  if (loading) {
    return (
      <div className="container max-w-4xl py-8 px-4">
        <div className="flex items-center justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
          <span className="ml-3 text-muted-foreground">Analyzing readiness...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="container max-w-4xl py-8 px-4">
      {/* Back Navigation */}
      <Button
        variant="ghost"
        size="sm"
        onClick={() => navigate("/app/dashboard")}
        className="mb-6"
      >
        <ChevronLeft className="h-4 w-4 mr-1" />
        Back to Dashboard
      </Button>

      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center gap-3 mb-4">
          <div className="flex items-center justify-center h-14 w-14 rounded-2xl bg-primary/10">
            <Wrench className="h-7 w-7 text-primary" />
          </div>
          <div>
            <h1 className="text-2xl font-bold">Readiness Fix Center</h1>
            <p className="text-muted-foreground">
              Fix issues to get your AI ready for production
            </p>
          </div>
        </div>
        {/* Encouragement message */}
        {(p0Issues.length > 0 || p1Issues.length > 0) && score >= 50 && (
          <div className="p-3 rounded-lg bg-primary/5 border border-primary/20">
            <p className="text-sm text-primary font-medium">
              🎯 You're almost there! Complete these items to launch your AI.
            </p>
          </div>
        )}
      </div>

      {/* Score Card */}
      <Card className="mb-8">
        <CardContent className="p-6">
          <div className="flex flex-col md:flex-row md:items-center gap-6">
            {/* Score Display */}
            <div className="flex items-center gap-4">
              <div className="relative">
                <div className={`text-5xl font-bold ${getScoreColor()}`}>
                  {score}%
                </div>
                <div className="text-sm text-muted-foreground mt-1">
                  Readiness Score
                </div>
              </div>
              <Separator orientation="vertical" className="h-16 hidden md:block" />
            </div>

            {/* Progress + Status */}
            <div className="flex-1 space-y-3">
              <Progress value={score} className={`h-3 ${getProgressColor()}`} />
              <div className="flex items-center justify-between text-sm">
                <span className="text-muted-foreground">
                  {businessMode.charAt(0).toUpperCase() + businessMode.slice(1)} mode
                </span>
                <span className={canGoLive ? "text-emerald-600 font-medium" : "text-muted-foreground"}>
                  {canGoLive ? "Ready to go live!" : "Need 85% + no blockers"}
                </span>
              </div>
            </div>

            {/* Go Live Button */}
            {canGoLive && (
              <Button asChild className="shrink-0">
                <Link to="/app/go-live">
                  <Rocket className="h-4 w-4 mr-2" />
                  Go Live
                </Link>
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* All Good State */}
      {p0Issues.length === 0 && p1Issues.length === 0 && (
        <Card className="border-emerald-500/30 bg-emerald-500/5">
          <CardContent className="p-6">
            <div className="flex items-center gap-4">
              <div className="flex items-center justify-center h-12 w-12 rounded-full bg-emerald-500/20">
                <CheckCircle2 className="h-6 w-6 text-emerald-500" />
              </div>
              <div>
                <h3 className="font-semibold text-emerald-600 dark:text-emerald-400">
                  All requirements met!
                </h3>
                <p className="text-sm text-muted-foreground">
                  Your AI assistant is configured and ready to go live.
                </p>
              </div>
              <Button asChild className="ml-auto">
                <Link to="/app/go-live">
                  Activate Plan
                  <ArrowRight className="h-4 w-4 ml-2" />
                </Link>
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Blocking Issues (P0) - Required */}
      {p0Issues.length > 0 && (
        <div className="mb-8">
          <div className="flex items-center gap-2 mb-4">
            <XCircle className="h-5 w-5 text-rose-500" />
            <h2 className="text-lg font-semibold text-rose-600 dark:text-rose-400">
              Required to Go Live ({p0Issues.length})
            </h2>
          </div>
          <div className="space-y-3">
            {p0Issues.map((issue) => (
              <IssueCard key={issue.code} issue={issue} variant="blocker" />
            ))}
          </div>
        </div>
      )}

      {/* Optional Improvements (P1) */}
      {p1Issues.length > 0 && (
        <div className="mb-8">
          <div className="flex items-center gap-2 mb-4">
            <Info className="h-5 w-5 text-amber-500" />
            <h2 className="text-lg font-semibold text-amber-600 dark:text-amber-400">
              Optional Improvements ({p1Issues.length})
            </h2>
          </div>
          <div className="space-y-3">
            {p1Issues.map((issue) => (
              <IssueCard key={issue.code} issue={issue} variant="recommended" />
            ))}
          </div>
        </div>
      )}

      {/* Plan-Gated Issues (if any) */}
      {planGatedIssues.length > 0 && (
        <div className="mb-8">
          <Card className="border-amber-500/30 bg-amber-500/5">
            <CardHeader className="pb-2">
              <CardTitle className="text-base flex items-center gap-2">
                <CreditCard className="h-4 w-4 text-amber-500" />
                Plan Required
              </CardTitle>
              <CardDescription>
                These features require a plan upgrade
              </CardDescription>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                {planGatedIssues.map((issue) => (
                  <div
                    key={issue.code}
                    className="flex items-center justify-between py-2"
                  >
                    <span className="text-sm">{issue.title}</span>
                    <Button size="sm" variant="outline" asChild>
                      <Link to={issue.fixLink}>View Plans</Link>
                    </Button>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Quick Actions */}
      <Card>
        <CardHeader>
          <CardTitle className="text-base">Quick Actions</CardTitle>
          <CardDescription>
            Common places to configure your AI
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <QuickActionButton
              icon={Brain}
              label="Business Brain"
              href="/app/business-brain"
            />
            <QuickActionButton
              icon={Link2}
              label="Integrations"
              href="/app/integrations"
            />
            <QuickActionButton
              icon={Sparkles}
              label="Test AI"
              href="/app/simulator"
            />
            <QuickActionButton
              icon={Settings}
              label="Settings"
              href="/app/settings"
            />
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

// ============================================================================
// SUB-COMPONENTS
// ============================================================================

interface IssueCardProps {
  issue: ReadinessIssue;
  variant: "blocker" | "recommended";
}

function IssueCard({ issue, variant }: IssueCardProps) {
  const Icon = fixTypeIcons[issue.fixType];
  const colorClass = fixTypeColors[issue.fixType];
  const borderClass = variant === "blocker"
    ? "border-rose-500/20 bg-rose-500/5"
    : "border-amber-500/20 bg-amber-500/5";

  return (
    <Card className={`${borderClass}`}>
      <CardContent className="p-4">
        <div className="flex items-start gap-4">
          {/* Icon */}
          <div className={`flex items-center justify-center h-10 w-10 rounded-lg border shrink-0 ${colorClass}`}>
            <Icon className="h-5 w-5" />
          </div>

          {/* Content */}
          <div className="flex-1 min-w-0">
            <div className="flex items-center gap-2 mb-1">
              <h3 className="font-medium">{issue.title}</h3>
              <Badge
                variant="outline"
                className={`text-xs ${
                  issue.fixType === "brain"
                    ? "border-purple-500/50 text-purple-600"
                    : issue.fixType === "integration"
                      ? "border-blue-500/50 text-blue-600"
                      : issue.fixType === "plan"
                        ? "border-amber-500/50 text-amber-600"
                        : "border-slate-500/50 text-slate-600"
                }`}
              >
                {issue.fixType === "brain"
                  ? "Business Brain"
                  : issue.fixType === "integration"
                    ? "Integration"
                    : issue.fixType === "plan"
                      ? "Plan Required"
                      : "Settings"}
              </Badge>
            </div>
            <p className="text-sm text-muted-foreground">{issue.reason}</p>
          </div>

          {/* Fix Button */}
          <Button
            size="sm"
            variant={variant === "blocker" ? "default" : "outline"}
            asChild
            className="shrink-0"
          >
            <Link to={issue.fixLink}>
              {issue.fixLabel}
              <ChevronRight className="h-3.5 w-3.5 ml-1" />
            </Link>
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

interface QuickActionButtonProps {
  icon: React.ElementType;
  label: string;
  href: string;
}

function QuickActionButton({ icon: Icon, label, href }: QuickActionButtonProps) {
  return (
    <Button variant="outline" asChild className="h-auto py-4 flex-col gap-2">
      <Link to={href}>
        <Icon className="h-5 w-5" />
        <span className="text-xs">{label}</span>
      </Link>
    </Button>
  );
}

