import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useModuleRequired } from "@/hooks/useModuleRequired";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { 
  Clock, 
  Users,
  Calendar,
  Phone,
  Mail,
  Plus,
  CheckCircle2,
  Loader2
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { format } from "date-fns";

const statusColors: Record<string, string> = {
  pending: "bg-yellow-500/10 text-yellow-700 dark:text-yellow-300",
  confirmed: "bg-blue-500/10 text-blue-700 dark:text-blue-300",
  seated: "bg-green-500/10 text-green-700 dark:text-green-300",
  completed: "bg-muted text-muted-foreground",
  cancelled: "bg-destructive/10 text-destructive",
  no_show: "bg-destructive/10 text-destructive",
};

export default function ReservationsPage() {
  // P0-3: Route protection - redirect if reservations module not enabled
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["reservations"]);
  
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [newRes, setNewRes] = useState({ customer_name: "", customer_phone: "", date: "", time: "", party_size: "2" });
  const [isCreating, setIsCreating] = useState(false);

  const { data: reservations, isLoading } = useQuery({
    queryKey: ["reservations", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("reservations")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("reservation_date", { ascending: true })
        .order("reservation_time", { ascending: true });

      if (error) throw error;
      return data || [];
    },
    enabled: !!tenant?.id,
  });

  const updateStatusMutation = useMutation({
    mutationFn: async ({ id, status }: { id: string; status: string }) => {
      const { error } = await supabase
        .from("reservations")
        .update({ status: status as any })
        .eq("id", id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["reservations"] });
      toast({ title: "Reservation updated" });
    },
    onError: (error: Error) => {
      toast({ variant: "destructive", title: "Error", description: error.message });
    },
  });

  const todayReservations = reservations?.filter(r => 
    r.reservation_date === format(new Date(), "yyyy-MM-dd")
  ) || [];

  const upcomingReservations = reservations?.filter(r => 
    r.reservation_date >= format(new Date(), "yyyy-MM-dd") &&
    r.status !== "completed" && r.status !== "cancelled" && r.status !== "no_show"
  ) || [];

  const filteredReservations = reservations?.filter(r =>
    statusFilter === "all" || r.status === statusFilter
  ) || [];

  const handleCreateReservation = async () => {
    if (!tenant?.id || !newRes.customer_name.trim() || !newRes.date || !newRes.time) return;
    setIsCreating(true);
    try {
      const { error } = await (supabase as any).from("reservations").insert({
        tenant_id: tenant.id,
        customer_name: newRes.customer_name,
        customer_phone: newRes.customer_phone || null,
        reservation_date: newRes.date,
        reservation_time: newRes.time,
        party_size: parseInt(newRes.party_size) || 2,
        status: "pending" as any,
      });
      if (error) throw error;
      queryClient.invalidateQueries({ queryKey: ["reservations"] });
      toast({ title: "Reservation created" });
      setIsDialogOpen(false);
      setNewRes({ customer_name: "", customer_phone: "", date: "", time: "", party_size: "2" });
    } catch (err: any) {
      toast({ variant: "destructive", title: "Error", description: err.message });
    } finally {
      setIsCreating(false);
    }
  };

  // Show loading while checking module access
  if (moduleLoading || !isAllowed) {
    return (
      <div className="p-6 flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="p-6 flex items-center justify-center">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary" />
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold">Reservations</h1>
          <p className="text-muted-foreground">Manage table reservations</p>
        </div>
        <Button onClick={() => setIsDialogOpen(true)}>
          <Plus className="h-4 w-4 mr-2" />
          New Reservation
        </Button>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">Today</span>
            </div>
            <p className="text-2xl font-bold mt-1">{todayReservations.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <Users className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">Total Guests Today</span>
            </div>
            <p className="text-2xl font-bold mt-1">
              {todayReservations.reduce((sum, r) => sum + (r.party_size || 0), 0)}
            </p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <Clock className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">Upcoming</span>
            </div>
            <p className="text-2xl font-bold mt-1">{upcomingReservations.length}</p>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="pt-4">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 text-muted-foreground" />
              <span className="text-sm text-muted-foreground">Confirmed</span>
            </div>
            <p className="text-2xl font-bold mt-1">
              {reservations?.filter(r => r.status === "confirmed").length || 0}
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Filter */}
      <div className="flex items-center gap-4">
        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="w-[180px]">
            <SelectValue placeholder="Filter by status" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All</SelectItem>
            <SelectItem value="pending">Pending</SelectItem>
            <SelectItem value="confirmed">Confirmed</SelectItem>
            <SelectItem value="seated">Seated</SelectItem>
            <SelectItem value="completed">Completed</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
            <SelectItem value="no_show">No Show</SelectItem>
          </SelectContent>
        </Select>
      </div>

      {/* Reservations Table */}
      <Card>
        <CardContent className="p-0">
          {filteredReservations.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-12 px-4 text-center">
              <Clock className="h-10 w-10 mx-auto text-muted-foreground/40 mb-4" />
              <h3 className="text-base font-semibold mb-1">No reservations found</h3>
              <p className="text-sm text-muted-foreground max-w-sm">
                {statusFilter !== "all"
                  ? "Try adjusting your filters to see more results."
                  : "When customers make reservations through your AI or you create them manually, they'll appear here."}
              </p>
            </div>
          ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Date & Time</TableHead>
                <TableHead>Customer</TableHead>
                <TableHead>Party Size</TableHead>
                <TableHead>Table Pref</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Actions</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
                {filteredReservations.map((reservation) => (
                  <TableRow key={reservation.id}>
                    <TableCell>
                      <div>
                        <p className="font-medium">
                          {format(new Date(reservation.reservation_date), "MMM d, yyyy")}
                        </p>
                        <p className="text-sm text-muted-foreground">
                          {reservation.reservation_time}
                        </p>
                      </div>
                    </TableCell>
                    <TableCell>
                      <div>
                        <p className="font-medium">{reservation.customer_name}</p>
                        {reservation.customer_phone && (
                          <p className="text-sm text-muted-foreground flex items-center gap-1">
                            <Phone className="h-3 w-3" />
                            {reservation.customer_phone}
                          </p>
                        )}
                      </div>
                    </TableCell>
                    <TableCell>
                      <div className="flex items-center gap-1">
                        <Users className="h-4 w-4 text-muted-foreground" />
                        {reservation.party_size}
                      </div>
                    </TableCell>
                    <TableCell>
                      {reservation.table_preference || "-"}
                    </TableCell>
                    <TableCell>
                      <Badge className={statusColors[reservation.status] || ""}>
                        {reservation.status.replace(/_/g, " ")}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Select
                        value={reservation.status}
                        onValueChange={(status) => 
                          updateStatusMutation.mutate({ id: reservation.id, status })
                        }
                      >
                        <SelectTrigger className="w-[130px]">
                          <SelectValue />
                        </SelectTrigger>
                        <SelectContent>
                          <SelectItem value="pending">Pending</SelectItem>
                          <SelectItem value="confirmed">Confirmed</SelectItem>
                          <SelectItem value="seated">Seated</SelectItem>
                          <SelectItem value="completed">Completed</SelectItem>
                          <SelectItem value="cancelled">Cancelled</SelectItem>
                          <SelectItem value="no_show">No Show</SelectItem>
                        </SelectContent>
                      </Select>
                    </TableCell>
                  </TableRow>
                ))}
            </TableBody>
          </Table>
          )}
        </CardContent>
      </Card>

      {/* New Reservation Dialog */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>New Reservation</DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label htmlFor="res-name">Customer Name</Label>
              <Input
                id="res-name"
                placeholder="Customer name"
                value={newRes.customer_name}
                onChange={(e) => setNewRes(prev => ({ ...prev, customer_name: e.target.value }))}
              />
            </div>
            <div className="space-y-2">
              <Label htmlFor="res-phone">Phone (optional)</Label>
              <Input
                id="res-phone"
                placeholder="(555) 123-4567"
                value={newRes.customer_phone}
                onChange={(e) => setNewRes(prev => ({ ...prev, customer_phone: e.target.value }))}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="res-date">Date</Label>
                <Input
                  id="res-date"
                  type="date"
                  value={newRes.date}
                  onChange={(e) => setNewRes(prev => ({ ...prev, date: e.target.value }))}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="res-time">Time</Label>
                <Input
                  id="res-time"
                  type="time"
                  value={newRes.time}
                  onChange={(e) => setNewRes(prev => ({ ...prev, time: e.target.value }))}
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="res-party">Party Size</Label>
              <Input
                id="res-party"
                type="number"
                min="1"
                max="50"
                value={newRes.party_size}
                onChange={(e) => setNewRes(prev => ({ ...prev, party_size: e.target.value }))}
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsDialogOpen(false)}>Cancel</Button>
            <Button onClick={handleCreateReservation} disabled={isCreating || !newRes.customer_name.trim() || !newRes.date || !newRes.time}>
              {isCreating ? <Loader2 className="h-4 w-4 mr-2 animate-spin" /> : null}
              Create Reservation
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useState, useMemo } from "react";
import { useModuleRequired } from "@/hooks/useModuleRequired";
import { Card, CardContent } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import { Warehouse, Search, Loader2 } from "lucide-react";
import { useSalesInventory } from "@/hooks/useSalesInventory";
import { EmptyState } from "@/components/ui/empty-state";
import { VehicleDetailDialog } from "@/components/inventory/VehicleDetailDialog";
import { cn } from "@/lib/utils";
import { proxyImageUrl } from "@/lib/proxyImage";
import { InventorySyncPanel } from "@/components/inventory/InventorySyncPanel";

const statusColors: Record<string, string> = {
  available: "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400",
  pending: "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400",
  sold: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
  hold: "bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400",
  incoming: "bg-cyan-100 text-cyan-700 dark:bg-cyan-900/30 dark:text-cyan-400",
};

function formatPrice(cents: number | null): string {
  if (!cents) return "--";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: 0,
  }).format(cents / 100);
}

export default function SalesInventoryPage() {
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["sales_inventory"]);
  const { inventory, isLoading, stats, refetch } = useSalesInventory();
  const [statusFilter, setStatusFilter] = useState<string>("all");
  const [conditionFilter, setConditionFilter] = useState<string>("all");
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedVehicle, setSelectedVehicle] = useState<any>(null);

  const filteredInventory = useMemo(() => {
    return inventory.filter((item) => {
      if (statusFilter !== "all" && item.status !== statusFilter) return false;
      if (conditionFilter !== "all" && item.condition !== conditionFilter) return false;
      if (searchQuery) {
        const q = searchQuery.toLowerCase();
        const desc = `${item.year || ""} ${item.make || ""} ${item.model || ""} ${item.trim || ""} ${item.stock_number || ""} ${item.vin || ""} ${item.color_exterior || ""}`.toLowerCase();
        return desc.includes(q);
      }
      return true;
    });
  }, [inventory, statusFilter, conditionFilter, searchQuery]);

  if (moduleLoading || !isAllowed || isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <PageContainer maxWidth="xl">
      <div className="space-y-6">
        <PageHeader
          icon={Warehouse}
          title="Inventory"
          description={`${stats.available} available, ${stats.total} total items`}
        />

        {/* Self-service inventory import */}
        <InventorySyncPanel
          lastSyncedAt={inventory.length > 0 ? inventory[0].last_synced_at ?? inventory[0].updated_at : null}
        />

        {/* Filters */}
        <div className="flex flex-wrap gap-3">
          <div className="relative flex-1 min-w-[200px] max-w-sm">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
            <Input
              placeholder="Search by year, make, model, color, stock #..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-9"
            />
          </div>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-[150px]">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Status</SelectItem>
              <SelectItem value="available">Available</SelectItem>
              <SelectItem value="pending">Pending</SelectItem>
              <SelectItem value="sold">Sold</SelectItem>
              <SelectItem value="hold">Hold</SelectItem>
              <SelectItem value="incoming">Incoming</SelectItem>
            </SelectContent>
          </Select>
          <Select value={conditionFilter} onValueChange={setConditionFilter}>
            <SelectTrigger className="w-[150px]">
              <SelectValue placeholder="Condition" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Condition</SelectItem>
              <SelectItem value="new">New</SelectItem>
              <SelectItem value="used">Used</SelectItem>
              <SelectItem value="certified">Certified</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {inventory.length === 0 ? (
          <EmptyState
            icon={Warehouse}
            title="No inventory yet"
            description="Add items manually or sync from your DMS system."
          />
        ) : filteredInventory.length === 0 ? (
          <EmptyState
            icon={Search}
            title="No matching items"
            description="Try adjusting your filters."
          />
        ) : (
          <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
            {filteredInventory.map((item) => {
              const titleParts: string[] = [];
              if (item.year) titleParts.push(item.year);
              if (item.make) titleParts.push(item.make);
              if (item.model) titleParts.push(item.model);
              const title = titleParts.join(" ") || "Unnamed Item";
              const hasPhoto = item.photo_urls && item.photo_urls.length > 0;

              return (
                <Card
                  key={item.id}
                  className="hover:shadow-md transition-shadow cursor-pointer hover:ring-1 hover:ring-primary/20"
                  onClick={() => setSelectedVehicle(item)}
                >
                  {/* Thumbnail */}
                  {hasPhoto && (
                    <div className="relative w-full h-32 overflow-hidden rounded-t-lg bg-muted">
                      <img
                        src={proxyImageUrl((item.photo_urls as string[])[0])}
                        alt={title}
                        className="w-full h-full object-cover"
                        loading="lazy"
                      />
                    </div>
                  )}
                  <CardContent className={cn("p-4 space-y-2", !hasPhoto && "pt-4")}>
                    <div className="flex items-start justify-between">
                      <div>
                        <h3 className="font-medium text-sm">{title}</h3>
                        {item.trim && <p className="text-xs text-muted-foreground">{item.trim}</p>}
                      </div>
                      <Badge className={cn("text-[10px]", statusColors[item.status] || statusColors.available)}>
                        {item.status}
                      </Badge>
                    </div>

                    <div className="flex items-center gap-2 text-xs text-muted-foreground flex-wrap">
                      {item.condition && (
                        <Badge variant="outline" className="text-[10px]">
                          {item.condition}
                        </Badge>
                      )}
                      {item.color_exterior && <span>{item.color_exterior}</span>}
                      {item.mileage != null && <span>{item.mileage.toLocaleString()} mi</span>}
                    </div>

                    <div className="flex items-baseline gap-2">
                      {item.asking_price_cents && (
                        <span className="text-sm font-semibold">
                          {formatPrice(item.asking_price_cents)}
                        </span>
                      )}
                      {item.msrp_cents && item.msrp_cents !== item.asking_price_cents && (
                        <span className="text-xs text-muted-foreground line-through">
                          {formatPrice(item.msrp_cents)}
                        </span>
                      )}
                    </div>

                    <div className="flex items-center gap-2 text-[10px] text-muted-foreground">
                      {item.stock_number && <span>Stock: {item.stock_number}</span>}
                      {item.days_on_lot > 0 && <span>{item.days_on_lot}d on lot</span>}
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        )}
      </div>

      <VehicleDetailDialog
        vehicle={selectedVehicle}
        open={!!selectedVehicle}
        onOpenChange={(open) => !open && setSelectedVehicle(null)}
      />
    </PageContainer>
  );
}

import { useState, useMemo } from "react";
import { useModuleRequired } from "@/hooks/useModuleRequired";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import { DollarSign, Search, Loader2, User, Phone, Clock, Mail, Car, Calendar } from "lucide-react";
import { useSalesLeads } from "@/hooks/useSalesLeads";
import { EmptyState } from "@/components/ui/empty-state";
import { cn } from "@/lib/utils";

const PIPELINE_COLUMNS = [
  { key: "new", label: "New", color: "bg-blue-500" },
  { key: "contacted", label: "Contacted", color: "bg-yellow-500" },
  { key: "qualified", label: "Qualified", color: "bg-purple-500" },
  { key: "appointment_set", label: "Appointment", color: "bg-indigo-500" },
  { key: "test_drive", label: "Test Drive", color: "bg-cyan-500" },
  { key: "negotiation", label: "Negotiation", color: "bg-orange-500" },
  { key: "sold", label: "Sold", color: "bg-green-500" },
  { key: "lost", label: "Lost", color: "bg-gray-500" },
] as const;

const priorityColors: Record<string, string> = {
  hot: "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400",
  high: "bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400",
  normal: "bg-gray-100 text-gray-700 dark:bg-gray-900/30 dark:text-gray-400",
  low: "bg-blue-100 text-blue-700 dark:bg-blue-900/30 dark:text-blue-400",
};

export default function SalesPipelinePage() {
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["sales_leads"]);
  const { leads, isLoading, stats, updateLead } = useSalesLeads();
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedLead, setSelectedLead] = useState<(typeof leads)[number] | null>(null);

  const filteredLeads = useMemo(() => {
    if (!searchQuery) return leads;
    const q = searchQuery.toLowerCase();
    return leads.filter(
      (l) =>
        l.customer?.full_name?.toLowerCase().includes(q) ||
        l.vehicle_interest?.toLowerCase().includes(q) ||
        l.lead_number?.toLowerCase().includes(q)
    );
  }, [leads, searchQuery]);

  const leadsByStatus = useMemo(() => {
    const grouped: Record<string, typeof leads> = {};
    for (const col of PIPELINE_COLUMNS) {
      grouped[col.key] = filteredLeads.filter((l) => l.status === col.key);
    }
    return grouped;
  }, [filteredLeads]);

  if (moduleLoading || !isAllowed || isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-6 w-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <PageContainer maxWidth="full">
      <div className="space-y-6">
        <PageHeader
          title="Sales Pipeline"
          description={`${stats.total} leads total — ${stats.hot} hot, ${stats.new} new`}
        />

        {/* Search */}
        <div className="relative max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Search leads..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="pl-9"
          />
        </div>

        {leads.length === 0 ? (
          <EmptyState
            icon={DollarSign}
            title="No sales leads yet"
            description="Sales leads will appear here as your AI agent qualifies callers."
          />
        ) : (
          /* Kanban board */
          <div className="overflow-x-auto pb-4">
            <div className="flex gap-4 min-w-max">
              {PIPELINE_COLUMNS.map((col) => (
                <div key={col.key} className="w-72 flex-shrink-0">
                  <div className="flex items-center gap-2 mb-3 px-1">
                    <div className={cn("w-2 h-2 rounded-full", col.color)} />
                    <span className="text-sm font-medium">{col.label}</span>
                    <Badge variant="secondary" className="ml-auto text-xs">
                      {leadsByStatus[col.key]?.length || 0}
                    </Badge>
                  </div>

                  <div className="space-y-2 min-h-[200px]">
                    {leadsByStatus[col.key]?.map((lead) => (
                      <Card key={lead.id} className="cursor-pointer hover:shadow-md transition-shadow" onClick={() => setSelectedLead(lead)}>
                        <CardContent className="p-3 space-y-2">
                          <div className="flex items-start justify-between">
                            <div className="flex items-center gap-1.5">
                              <User className="h-3.5 w-3.5 text-muted-foreground" />
                              <span className="text-sm font-medium truncate">
                                {lead.customer?.full_name || "Unknown"}
                              </span>
                            </div>
                            <Badge className={cn("text-[10px] px-1.5", priorityColors[lead.priority])}>
                              {lead.priority}
                            </Badge>
                          </div>

                          {lead.vehicle_interest && (
                            <p className="text-xs text-muted-foreground truncate">
                              {lead.vehicle_interest}
                            </p>
                          )}

                          <div className="flex items-center gap-3 text-xs text-muted-foreground">
                            {lead.customer?.phone_e164 && (
                              <span className="flex items-center gap-1">
                                <Phone className="h-3 w-3" />
                                {lead.customer.phone_e164}
                              </span>
                            )}
                            {lead.timeline && (
                              <span className="flex items-center gap-1">
                                <Clock className="h-3 w-3" />
                                {lead.timeline.replace("_", " ")}
                              </span>
                            )}
                          </div>

                          {/* Status dropdown */}
                          <div onClick={(e) => e.stopPropagation()}>
                            <Select
                              value={lead.status}
                              onValueChange={(newStatus) =>
                                updateLead.mutate({ id: lead.id, status: newStatus })
                              }
                            >
                              <SelectTrigger className="h-7 text-[11px]">
                                <SelectValue />
                              </SelectTrigger>
                              <SelectContent>
                                {PIPELINE_COLUMNS.map((s) => (
                                  <SelectItem key={s.key} value={s.key}>
                                    {s.label}
                                  </SelectItem>
                                ))}
                              </SelectContent>
                            </Select>
                          </div>

                          {lead.lead_number && (
                            <p className="text-[10px] text-muted-foreground">{lead.lead_number}</p>
                          )}
                        </CardContent>
                      </Card>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Lead Detail Dialog */}
      <Dialog open={!!selectedLead} onOpenChange={(open) => !open && setSelectedLead(null)}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-2">
              <User className="h-5 w-5" />
              {selectedLead?.customer?.full_name || "Unknown Lead"}
            </DialogTitle>
          </DialogHeader>
          {selectedLead && (
            <div className="space-y-4">
              <div className="flex items-center justify-between">
                <Badge className={cn("text-xs", priorityColors[selectedLead.priority])}>
                  {selectedLead.priority} priority
                </Badge>
                {selectedLead.lead_number && (
                  <span className="text-xs text-muted-foreground">{selectedLead.lead_number}</span>
                )}
              </div>

              <div className="space-y-3 text-sm">
                {selectedLead.customer?.phone_e164 && (
                  <div className="flex items-center gap-2">
                    <Phone className="h-4 w-4 text-muted-foreground" />
                    <span>{selectedLead.customer.phone_e164}</span>
                  </div>
                )}
                {selectedLead.customer?.email && (
                  <div className="flex items-center gap-2">
                    <Mail className="h-4 w-4 text-muted-foreground" />
                    <span>{selectedLead.customer.email}</span>
                  </div>
                )}
                {selectedLead.vehicle_interest && (
                  <div className="flex items-center gap-2">
                    <Car className="h-4 w-4 text-muted-foreground" />
                    <span>{selectedLead.vehicle_interest}</span>
                  </div>
                )}
                {selectedLead.budget_range && (
                  <div className="flex items-center gap-2">
                    <DollarSign className="h-4 w-4 text-muted-foreground" />
                    <span>Budget: {selectedLead.budget_range}</span>
                  </div>
                )}
                {selectedLead.timeline && (
                  <div className="flex items-center gap-2">
                    <Calendar className="h-4 w-4 text-muted-foreground" />
                    <span>Timeline: {selectedLead.timeline.replace("_", " ")}</span>
                  </div>
                )}
                {selectedLead.assigned_sales_rep && (
                  <div className="flex items-center gap-2">
                    <User className="h-4 w-4 text-muted-foreground" />
                    <span>Rep: {selectedLead.assigned_sales_rep}</span>
                  </div>
                )}
                {selectedLead.notes && (
                  <div className="pt-2 border-t">
                    <p className="text-xs text-muted-foreground mb-1">Notes</p>
                    <p className="text-sm">{selectedLead.notes}</p>
                  </div>
                )}
              </div>

              <div className="pt-2 border-t">
                <label className="text-xs font-medium text-muted-foreground mb-1.5 block">
                  Move to Stage
                </label>
                <Select
                  value={selectedLead.status}
                  onValueChange={(newStatus) => {
                    updateLead.mutate({ id: selectedLead.id, status: newStatus });
                    setSelectedLead({ ...selectedLead, status: newStatus });
                  }}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {PIPELINE_COLUMNS.map((s) => (
                      <SelectItem key={s.key} value={s.key}>
                        {s.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          )}
        </DialogContent>
      </Dialog>
    </PageContainer>
  );
}

import { Link } from "react-router-dom";
import { useServices } from "@/hooks/useServices";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { EmptyState } from "@/components/ui/empty-state";
import { Brain, DollarSign, Clock, Briefcase, Loader2 } from "lucide-react";

/**
 * ServicesPage - Read-only view with CTA to Business Brain
 *
 * Service management has moved to Business Brain for centralized control.
 * This page now shows a read-only list with a redirect to edit in Brain.
 */
export default function ServicesPage() {
  const { services, isLoading } = useServices();
  const { terms } = useIndustryContext();

  const formatDuration = (minutes: number) => {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    if (hours === 0) return `${mins}min`;
    if (mins === 0) return `${hours}h`;
    return `${hours}h ${mins}min`;
  };

  const formatPrice = (service: any) => {
    if (service.price_type === "quote_only") return "Quote Required";
    if (!service.price_amount) return "Not Set";
    const prefix = service.price_type === "starting_at" ? "From " : "";
    return `${prefix}$${service.price_amount}`;
  };

  if (isLoading) {
    return (
      <div className="p-6 md:p-8">
        <div className="flex items-center justify-center py-12">
          <Loader2 className="h-8 w-8 animate-spin text-primary" />
          <span className="ml-3 text-muted-foreground">Loading services...</span>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 md:p-8 space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-3xl font-bold">{terms.servicesPageTitle}</h1>
          <p className="text-muted-foreground mt-1">
            {terms.servicesPageSubtitle}
          </p>
        </div>
        <Button asChild size="lg">
          <Link to="/app/business-brain">
            <Brain className="mr-2 h-4 w-4" />
            Edit in Business Brain
          </Link>
        </Button>
      </div>

      {/* Migration Notice */}
      <Card className="border-primary/20 bg-primary/5">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Brain className="h-5 w-5 text-primary" />
            Service Management Has Moved
          </CardTitle>
          <CardDescription>
            All service editing now happens in Business Brain for centralized control
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 text-sm text-muted-foreground">
            <div className="flex items-center gap-2">
              <div className="h-1.5 w-1.5 rounded-full bg-primary" />
              <span>Add, edit, and delete services</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="h-1.5 w-1.5 rounded-full bg-primary" />
              <span>Configure pricing rules and estimates</span>
            </div>
            <div className="flex items-center gap-2">
              <div className="h-1.5 w-1.5 rounded-full bg-primary" />
              <span>Manage service details in one place</span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Services List (Read-Only) */}
      {services && services.length > 0 ? (
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
          {services.map((service) => (
            <Card key={service.id} className="relative">
              <CardHeader>
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <CardTitle className="text-lg">{service.name}</CardTitle>
                    {service.description && (
                      <CardDescription className="mt-1">{service.description}</CardDescription>
                    )}
                  </div>
                  {!service.is_active && (
                    <Badge variant="outline" className="ml-2">
                      Inactive
                    </Badge>
                  )}
                </div>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  <div className="flex items-center gap-2 text-sm">
                    <DollarSign className="h-4 w-4 text-muted-foreground" />
                    <span className="font-medium">{formatPrice(service)}</span>
                  </div>
                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <Clock className="h-4 w-4" />
                    <span>{formatDuration(service.duration_minutes)}</span>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      ) : (
        <Card>
          <CardContent className="p-0">
            <EmptyState
              icon={Briefcase}
              title="No services yet"
              description="Add what you offer so your AI can quote accurate prices."
              action={{
                label: "Add Service",
                onClick: () => window.location.href = "/app/business-brain?section=offerings",
              }}
            />
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/contexts/AuthContext";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Lock, Settings, UserPlus } from "lucide-react";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import { CallContextDebugger } from "@/components/ai/CallContextDebugger";
import { PlanUpgradeCard } from "@/components/settings/PlanUpgradeCard";
import { MultiLocationManager } from "@/components/settings/MultiLocationManager";
import { DeliveryIntegrationsSettings } from "@/components/settings/DeliveryIntegrationsSettings";
import { AutomationRulesSettings } from "@/components/settings/AutomationRulesSettings";
import { DataControlsPanel } from "@/components/settings/DataControlsPanel";
import { SettingsSidebar, SettingsNavConfig } from "@/components/settings/SettingsSidebar";
import { MobileSettingsNav } from "@/components/settings/MobileSettingsNav";
// BusinessBrainCTA removed for cleaner settings layout
import { DangerZoneSection } from "@/components/settings/DangerZoneSection";
import { NotificationPreferencesPanel } from "@/components/settings/NotificationPreferencesPanel";
import { SettingsCard } from "@/components/settings/SettingsSection";
import { RevenueSettingsSection } from "@/components/settings/RevenueSettingsSection";
import { RecoverySettingsSection } from "@/components/settings/recovery/RecoverySettingsSection";
import { SmsSettingsSection } from "@/components/settings/SmsSettingsSection";
import { ReferralNetworkSettings } from "@/components/settings/ReferralNetworkSettings";
import { ReferralTransferLog } from "@/components/settings/ReferralTransferLog";
import { useFoodMode } from "@/hooks/useFoodMode";
import { useModuleEnabled, useTenantConfig } from "@/hooks/useTenantConfig";
import { useCapabilities } from "@/hooks/useCapabilities";

export default function SettingsPage() {
  const { user, signOut, tenant, isSuperAdmin } = useAuth();
  const { toast } = useToast();
  const { isFoodMode } = useFoodMode();
  const { hipaaMode } = useTenantConfig();
  const { terms } = useIndustryContext();
  const isBookingEnabled = useModuleEnabled("booking");
  const isDispatchEnabled = useModuleEnabled("dispatch_queue");
  const isMedicalMode = useModuleEnabled("medical_intake");
  const { hasReferralNetwork, hasLeadFollowUp } = useCapabilities();

  // Check if tenant has any call data
  const { data: hasCallData } = useQuery({
    queryKey: ["has-call-data", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return false;
      const { count } = await supabase
        .from("ai_call_sessions")
        .select("id", { count: "exact", head: true })
        .eq("tenant_id", tenant.id)
        .limit(1);
      return (count || 0) > 0;
    },
    enabled: !!tenant?.id,
  });

  // Default to first available section
  const [activeSection, setActiveSection] = useState("team");
  const [inviteOpen, setInviteOpen] = useState(false);
  const [inviteEmail, setInviteEmail] = useState("");
  const [inviteRole, setInviteRole] = useState<string>("staff");
  const [inviteSending, setInviteSending] = useState(false);

  const handleInviteMember = async () => {
    if (!inviteEmail || !tenant?.id) return;
    setInviteSending(true);
    try {
      const { error } = await (supabase as any)
        .from("tenant_users")
        .insert({
          tenant_id: tenant.id,
          invited_email: inviteEmail,
          role: inviteRole,
        });

      if (error) {
        if (error.message.includes("invited_email") || error.code === "42703") {
          toast({
            title: "Invite sent",
            description: `Share this link with ${inviteEmail}: ${window.location.origin}/signup?invite=${tenant.id}&role=${inviteRole}`,
          });
        } else {
          throw error;
        }
      } else {
        toast({ title: "Invite sent", description: `${inviteEmail} has been invited as ${inviteRole}.` });
      }

      setInviteOpen(false);
      setInviteEmail("");
      setInviteRole("staff");
    } catch (err) {
      toast({ title: "Failed to invite", description: err instanceof Error ? err.message : "Unknown error", variant: "destructive" });
    } finally {
      setInviteSending(false);
    }
  };

  // Navigation config based on enabled modules and business mode
  const isDispatchMode = isDispatchEnabled && !isBookingEnabled && !isFoodMode;
  const navConfig: SettingsNavConfig = {
    showHipaa: isMedicalMode || hipaaMode,
    showBookingDelivery: isBookingEnabled,
    showDispatchDelivery: isDispatchEnabled,
    showFoodSettings: isFoodMode,
    showRecovery: hasLeadFollowUp,
    showReferralNetwork: hasReferralNetwork,
    hasCallData: hasCallData ?? false,
    isSuperAdmin,
  };

  // Simplified section metadata
  const sectionMeta: Record<string, { title: string; description: string }> = {
    team: {
      title: "Team Members",
      description: "Manage who has access to your account and their permissions.",
    },
    plan: {
      title: "Plan & Billing",
      description: "View your current plan, usage limits, and upgrade options.",
    },
    revenue: {
      title: "Revenue Tracking",
      description: "Configure how your AI-generated revenue and ROI are calculated.",
    },
    "data-privacy": {
      title: "Data Controls",
      description: "Control what call data is saved and for how long. Manage recording and transcript storage.",
    },
    alerts: {
      title: "Alerts",
      description: "Choose which events trigger email and SMS alerts to you.",
    },
    integrations: {
      title: "Integrations",
      description: "Push bookings, orders, and leads to your existing tools via webhooks.",
    },
    automation: {
      title: "Automation Rules",
      description: "Auto-confirm bookings, send follow-ups, and route leads automatically.",
    },
    developer: {
      title: "Developer Tools",
      description: "Advanced debugging tools for troubleshooting.",
    },
    danger: {
      title: "Danger Zone",
      description: "Irreversible and destructive actions. Proceed with caution.",
    },
    recovery: {
      title: "Lead Recovery",
      description: "Configure automatic follow-up for leads who don't book.",
    },
    sms: {
      title: "SMS Messaging",
      description: "Configure automated text messages for confirmations, reminders, and reviews.",
    },
    "referral-network": {
      title: "Referral Network",
      description: "Connect callers with other businesses when you can't help them directly.",
    },
  };

  const currentMeta = sectionMeta[activeSection] || { title: "Settings", description: "" };

  const renderSectionContent = () => {
    switch (activeSection) {
      case "team":
        return (
          <>
            <SettingsCard
              title="Team Members"
              description="People who can access this account."
              headerAction={
                <Button size="sm" onClick={() => setInviteOpen(true)}>
                  <UserPlus className="h-4 w-4 mr-2" />
                  Invite Member
                </Button>
              }
            >
              <div className="flex items-center justify-between p-4 rounded-lg border">
                <div className="flex items-center gap-3">
                  <div className="flex h-10 w-10 items-center justify-center rounded-full bg-primary text-primary-foreground font-medium">
                    {user?.email?.[0].toUpperCase()}
                  </div>
                  <div>
                    <p className="font-medium">{user?.email}</p>
                    <p className="text-sm text-muted-foreground">Owner</p>
                  </div>
                </div>
                <span className="text-sm text-muted-foreground">You</span>
              </div>
            </SettingsCard>

            {/* Invite Member Dialog */}
            <Dialog open={inviteOpen} onOpenChange={setInviteOpen}>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>Invite Team Member</DialogTitle>
                  <DialogDescription>
                    Send an invitation to join your team. They will receive access based on their assigned role.
                  </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-2">
                  <div className="space-y-2">
                    <Label htmlFor="invite-email">Email Address</Label>
                    <Input
                      id="invite-email"
                      type="email"
                      placeholder="teammate@example.com"
                      value={inviteEmail}
                      onChange={(e) => setInviteEmail(e.target.value)}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>Role</Label>
                    <Select value={inviteRole} onValueChange={setInviteRole}>
                      <SelectTrigger>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="manager">Manager</SelectItem>
                        <SelectItem value="staff">Staff</SelectItem>
                        <SelectItem value="viewer">Viewer</SelectItem>
                      </SelectContent>
                    </Select>
                    <p className="text-xs text-muted-foreground">
                      {inviteRole === "manager" && "Full access to manage settings, team, and data."}
                      {inviteRole === "staff" && "Can manage bookings, leads, and day-to-day operations."}
                      {inviteRole === "viewer" && "Read-only access to dashboards and reports."}
                    </p>
                  </div>
                </div>
                <DialogFooter>
                  <Button variant="outline" onClick={() => setInviteOpen(false)}>
                    Cancel
                  </Button>
                  <Button onClick={handleInviteMember} disabled={!inviteEmail || inviteSending}>
                    {inviteSending ? "Sending..." : "Send Invite"}
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>
          </>
        );

      case "plan":
        return (
          <>
            <PlanUpgradeCard />
            <MultiLocationManager />
          </>
        );

      case "revenue":
        return <RevenueSettingsSection />;

      case "data-privacy":
        return <DataControlsPanel />;

      case "alerts":
        return <NotificationPreferencesPanel />;

      case "integrations":
        return <DeliveryIntegrationsSettings />;

      case "automation":
        return <AutomationRulesSettings />;

      case "developer":
        return (
          <>
            <SettingsCard
              title="Debug Tools"
              description="Inspect what data is passed to the AI during calls."
            >
              <p className="text-sm text-muted-foreground">
                These tools help you understand and troubleshoot AI behavior. Only use if you're comfortable with technical details.
              </p>
            </SettingsCard>
            {tenant?.id && <CallContextDebugger tenantId={tenant.id} />}
          </>
        );

      case "danger":
        return <DangerZoneSection />;

      case "recovery":
        return <RecoverySettingsSection />;

      case "sms":
        return <SmsSettingsSection />;

      case "referral-network":
        return (
          <>
            <ReferralNetworkSettings />
            <ReferralTransferLog />
          </>
        );

      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row">
      {/* Desktop Sidebar */}
      <SettingsSidebar
        activeSection={activeSection}
        onSectionChange={setActiveSection}
        config={navConfig}
      />

      {/* Main Content Area */}
      <main className="flex-1 min-w-0">
        {/* Page Header - Sticky */}
        <header className="sticky top-0 z-20 bg-background/80 backdrop-blur-md py-6 px-6 md:px-8 lg:px-12 relative">
          {/* Mobile Navigation */}
          <div className="md:hidden mb-4">
            <MobileSettingsNav
              activeSection={activeSection}
              onSectionChange={setActiveSection}
              config={navConfig}
            />
          </div>

          <div className="flex items-center gap-2.5">
            <div className="flex-shrink-0 text-muted-foreground">
              <Settings className="h-5 w-5" />
            </div>
            <div>
              <h1 className="text-xl font-semibold tracking-tight text-foreground">
                {currentMeta.title}
              </h1>
              {currentMeta.description && (
                <p className="text-sm text-muted-foreground/70 mt-0.5">
                  {currentMeta.description}
                </p>
              )}
            </div>
          </div>
          <div className="divider-gradient absolute bottom-0 left-0 right-0" />
        </header>

        {/* Content */}
        <div className="px-6 md:px-8 lg:px-12 py-6 space-y-6 max-w-4xl">

          {/* Section Content */}
          <div className="space-y-6">
            {renderSectionContent()}
          </div>

          {/* Account Access - Always visible at bottom */}
          <Card className="border-border/30 bg-card/60 backdrop-blur-sm card-interactive">
            <CardHeader>
              <CardTitle className="text-foreground text-base">Account Access</CardTitle>
            </CardHeader>
            <CardContent className="flex items-center justify-between">
              <div>
                <p className="font-medium text-sm">Sign out of your account</p>
                <p className="text-sm text-muted-foreground">You can sign back in anytime</p>
              </div>
              <Button variant="outline" onClick={signOut}>
                <Lock className="h-4 w-4 mr-2" />
                Sign Out
              </Button>
            </CardContent>
          </Card>
        </div>
      </main>
    </div>
  );
}

import { useState } from "react";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useToast } from "@/hooks/use-toast";
import {
  Phone,
  Loader2,
  RotateCcw,
  User,
  Clock,
  Wrench,
  PhoneCall,
  MessageSquare,
  Zap,
  AlertTriangle,
  CheckCircle2,
} from "lucide-react";

interface SimulationResult {
  aiResponse: string;
  intent: string;
  confidence: string;
  customerName: string;
  serviceRequested: string;
  preferredTime: string;
  phoneNumber: string;
  nextAction: string;
  knowledgeGap: boolean;
  gapDescription?: string;
  sourcesCount: number;
}

const QUICK_SUGGESTIONS = [
  "I need an emergency repair",
  "How much do you charge?",
  "What are your hours?",
  "I'd like to book an appointment",
];

function confidenceToPercent(confidence: string): number {
  switch (confidence) {
    case "high":
      return 90;
    case "medium":
      return 60;
    case "low":
      return 30;
    default:
      return 50;
  }
}

function nextActionLabel(action: string, intent: string): string {
  switch (action) {
    case "offer_slots":
      return "Would offer available time slots";
    case "book":
      return "Would book appointment";
    case "request_details":
      return "Would ask for more details";
    case "escalate":
      return "Would transfer to human";
    case "callback":
      return "Would schedule a callback";
    case "provide_info":
      return "Would provide information";
    default:
      return "Would take a message";
  }
}

export default function TestAIPage() {
  const { effectiveTenantId } = useAuth();
  const { toast } = useToast();

  const [message, setMessage] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<SimulationResult | null>(null);

  const simulate = async (text?: string) => {
    const input = text || message;
    if (!input.trim()) return;

    if (!effectiveTenantId) {
      toast({ variant: "destructive", title: "No business configured" });
      return;
    }

    setIsLoading(true);
    setResult(null);
    if (text) setMessage(text);

    try {
      const { data, error } = await supabase.functions.invoke("ai-plan-response", {
        body: {
          tenantId: effectiveTenantId,
          userMessage: input,
          channel: "call",
        },
      });

      if (error) throw error;

      const plan = data.plan;

      // Extract structured info from the reply & plan
      const nameMatch = input.match(/(?:my name is|i'm|this is)\s+([A-Z][a-z]+(?:\s+[A-Z][a-z]+)?)/i);
      const phoneMatch = input.match(/(\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4})/);
      const timeMatch = input.match(/(?:tomorrow|today|monday|tuesday|wednesday|thursday|friday|saturday|sunday|morning|afternoon|evening|\d{1,2}(?::\d{2})?\s*(?:am|pm))/i);

      setResult({
        aiResponse: plan.draft_reply,
        intent: plan.intent,
        confidence: plan.confidence,
        customerName: nameMatch?.[1] || "Not provided",
        serviceRequested:
          plan.required_info_to_collect?.find((i: string) => i.toLowerCase().includes("service"))
            ? plan.facts_to_use?.[0]?.content?.slice(0, 50) || "General inquiry"
            : plan.intent === "booking"
            ? "Appointment request"
            : plan.intent === "quote"
            ? "Price inquiry"
            : "General inquiry",
        preferredTime: timeMatch?.[0] || "Not specified",
        phoneNumber: phoneMatch?.[1] || "Not provided",
        nextAction: nextActionLabel(plan.next_action, plan.intent),
        knowledgeGap: plan.knowledge_gap_detected,
        gapDescription: plan.gap_description,
        sourcesCount: plan.sources_used?.length || 0,
      });
    } catch (err: any) {
      console.error("Simulation error:", err);
      toast({
        variant: "destructive",
        title: "Simulation failed",
        description: err.message || "Could not reach AI backend",
      });
    } finally {
      setIsLoading(false);
    }
  };

  const reset = () => {
    setMessage("");
    setResult(null);
  };

  const confidencePct = result ? confidenceToPercent(result.confidence) : 0;

  return (
    <PageContainer maxWidth="xl">
      <PageHeader
        title="Test Your AI Receptionist"
        description="See how your AI handles customer calls"
      />

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* LEFT – Input */}
        <div className="space-y-4">
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-base">
                <Phone className="h-4 w-4 text-primary" />
                Customer Message
              </CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <Textarea
                placeholder="Enter a sample customer message... (e.g., 'Hi, I need a plumber to fix a leaky faucet. Do you have availability tomorrow morning?')"
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                rows={5}
                disabled={isLoading}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    simulate();
                  }
                }}
              />

              <div className="flex gap-2">
                <Button
                  onClick={() => simulate()}
                  disabled={isLoading || !message.trim()}
                  className="flex-1 gap-2"
                >
                  {isLoading ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <PhoneCall className="h-4 w-4" />
                  )}
                  {isLoading ? "Simulating..." : "Simulate Call"}
                </Button>
                {result && (
                  <Button variant="outline" onClick={reset} className="gap-2">
                    <RotateCcw className="h-4 w-4" />
                    Reset
                  </Button>
                )}
              </div>

              {/* Quick suggestion chips */}
              <div className="space-y-2">
                <p className="text-xs text-muted-foreground font-medium">Quick scenarios:</p>
                <div className="flex flex-wrap gap-2">
                  {QUICK_SUGGESTIONS.map((s) => (
                    <button
                      key={s}
                      onClick={() => {
                        setMessage(s);
                        simulate(s);
                      }}
                      disabled={isLoading}
                      className="text-xs px-3 py-1.5 rounded-full border border-border bg-background hover:bg-muted transition-colors disabled:opacity-50"
                    >
                      {s}
                    </button>
                  ))}
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* RIGHT – Results */}
        <div className="space-y-4">
          {isLoading && (
            <Card>
              <CardContent className="py-12 flex flex-col items-center gap-3">
                <Loader2 className="h-8 w-8 animate-spin text-primary" />
                <p className="text-sm text-muted-foreground">
                  Running simulation with your real business data…
                </p>
              </CardContent>
            </Card>
          )}

          {!isLoading && !result && (
            <Card>
              <CardContent className="py-12 flex flex-col items-center gap-3 text-center">
                <MessageSquare className="h-8 w-8 text-muted-foreground/40" />
                <p className="text-sm text-muted-foreground">
                  Enter a message and click "Simulate Call" to see how your AI responds
                </p>
              </CardContent>
            </Card>
          )}

          {result && (
            <>
              {/* AI Response */}
              <Card>
                <CardHeader>
                  <CardTitle className="flex items-center gap-2 text-base">
                    <Zap className="h-4 w-4 text-primary" />
                    AI Response
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <p className="text-sm leading-relaxed">{result.aiResponse}</p>
                  {result.knowledgeGap && (
                    <div className="mt-3 flex items-start gap-2 p-2 rounded-md bg-destructive/10 text-destructive text-xs">
                      <AlertTriangle className="h-3.5 w-3.5 mt-0.5 shrink-0" />
                      <span>{result.gapDescription || "Knowledge gap detected — consider adding more info to your Business Brain."}</span>
                    </div>
                  )}
                </CardContent>
              </Card>

              {/* Extracted Information */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-base">Extracted Information</CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-2 gap-y-3 gap-x-4 text-sm">
                    <div className="flex items-center gap-2 text-muted-foreground">
                      <User className="h-3.5 w-3.5" /> Customer Name
                    </div>
                    <div className="font-medium">{result.customerName}</div>

                    <div className="flex items-center gap-2 text-muted-foreground">
                      <Wrench className="h-3.5 w-3.5" /> Service Requested
                    </div>
                    <div className="font-medium">{result.serviceRequested}</div>

                    <div className="flex items-center gap-2 text-muted-foreground">
                      <Clock className="h-3.5 w-3.5" /> Preferred Time
                    </div>
                    <div className="font-medium">{result.preferredTime}</div>

                    <div className="flex items-center gap-2 text-muted-foreground">
                      <Phone className="h-3.5 w-3.5" /> Phone Number
                    </div>
                    <div className="font-medium">{result.phoneNumber}</div>
                  </div>
                </CardContent>
              </Card>

              {/* Action & Confidence */}
              <Card>
                <CardHeader>
                  <CardTitle className="text-base">Action & Confidence</CardTitle>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center gap-2">
                    <CheckCircle2 className="h-4 w-4 text-primary" />
                    <span className="text-sm font-medium">{result.nextAction}</span>
                  </div>

                  <div className="space-y-1.5">
                    <div className="flex items-center justify-between text-sm">
                      <span className="text-muted-foreground">Confidence</span>
                      <Badge
                        variant="outline"
                        className={
                          result.confidence === "high"
                            ? "border-green-500 text-green-700"
                            : result.confidence === "medium"
                            ? "border-yellow-500 text-yellow-700"
                            : "border-red-500 text-red-700"
                        }
                      >
                        {result.confidence}
                      </Badge>
                    </div>
                    <Progress value={confidencePct} />
                  </div>

                  <div className="flex items-center gap-2 text-xs text-muted-foreground">
                    <Badge variant="secondary" className="text-[10px]">
                      Intent: {result.intent}
                    </Badge>
                    <Badge variant="secondary" className="text-[10px]">
                      {result.sourcesCount} source{result.sourcesCount !== 1 ? "s" : ""} used
                    </Badge>
                  </div>
                </CardContent>
              </Card>
            </>
          )}
        </div>
      </div>
    </PageContainer>
  );
}

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import {
  Clock,
  Play,
  Square,
  Loader2,
  MoreHorizontal,
  Trash2,
  Download,
  Calendar,
  Coffee,
  Car,
  Briefcase,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { format, formatDistanceToNow, startOfWeek, endOfWeek, eachDayOfInterval } from "date-fns";
import { useTimeTracking, TimeEntry } from "@/hooks/useTimeTracking";
import { useModuleRequired } from "@/hooks/useModuleRequired";

const entryTypeConfig: Record<string, { label: string; color: string; icon: typeof Clock }> = {
  work: { label: "Work", color: "bg-green-100 text-green-700", icon: Briefcase },
  break: { label: "Break", color: "bg-yellow-100 text-yellow-700", icon: Coffee },
  travel: { label: "Travel", color: "bg-blue-100 text-blue-700", icon: Car },
  admin: { label: "Admin", color: "bg-purple-100 text-purple-700", icon: Clock },
};

function formatDuration(minutes: number | null): string {
  if (minutes === null || minutes === 0) return "—";
  const hours = Math.floor(minutes / 60);
  const mins = minutes % 60;
  if (hours === 0) return `${mins}m`;
  if (mins === 0) return `${hours}h`;
  return `${hours}h ${mins}m`;
}

function formatHoursDecimal(minutes: number): string {
  return (minutes / 60).toFixed(2);
}

function TimeEntryRow({
  entry,
  onDelete,
}: {
  entry: TimeEntry;
  onDelete: () => void;
}) {
  const config = entryTypeConfig[entry.entry_type] || entryTypeConfig.work;
  const Icon = config.icon;
  const isActive = !entry.clock_out;

  return (
    <div className={cn(
      "flex items-center justify-between p-4 border rounded-lg",
      isActive && "border-green-500 bg-green-50 dark:bg-green-950/20"
    )}>
      <div className="flex items-center gap-4">
        <div className={cn(
          "h-10 w-10 rounded-full flex items-center justify-center",
          isActive ? "bg-green-500 text-white animate-pulse" : "bg-muted"
        )}>
          <Icon className="h-5 w-5" />
        </div>
        <div>
          <div className="flex items-center gap-2">
            <p className="font-medium">
              {format(new Date(entry.clock_in), "h:mm a")}
              {entry.clock_out && (
                <> — {format(new Date(entry.clock_out), "h:mm a")}</>
              )}
            </p>
            <Badge className={config.color}>{config.label}</Badge>
            {isActive && (
              <Badge variant="outline" className="text-green-600 border-green-600">
                Active
              </Badge>
            )}
          </div>
          <p className="text-sm text-muted-foreground">
            {format(new Date(entry.clock_in), "EEEE, MMM d")}
            {entry.notes && <> • {entry.notes}</>}
          </p>
        </div>
      </div>
      <div className="flex items-center gap-4">
        <div className="text-right">
          <p className="font-bold text-lg">{formatDuration(entry.duration_minutes)}</p>
          {entry.duration_minutes && (
            <p className="text-xs text-muted-foreground">
              {formatHoursDecimal(entry.duration_minutes)} hrs
            </p>
          )}
        </div>
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="icon">
              <MoreHorizontal className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end">
            <DropdownMenuItem onClick={onDelete} className="text-destructive">
              <Trash2 className="h-4 w-4 mr-2" />
              Delete
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </div>
  );
}

export default function TimeTrackingPage() {
  const { isAllowed, isLoading: moduleLoading } = useModuleRequired(["booking", "dispatch_queue", "job_tracking"]);
  const { entries, isLoading, stats, clockIn, clockOut, createEntry, deleteEntry } = useTimeTracking();
  const [addDialogOpen, setAddDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [entryToDelete, setEntryToDelete] = useState<string | null>(null);

  // Manual entry form state
  const [manualDate, setManualDate] = useState(format(new Date(), "yyyy-MM-dd"));
  const [manualClockIn, setManualClockIn] = useState("09:00");
  const [manualClockOut, setManualClockOut] = useState("17:00");
  const [manualType, setManualType] = useState<TimeEntry["entry_type"]>("work");
  const [manualNotes, setManualNotes] = useState("");

  const handleClockIn = async (type: TimeEntry["entry_type"] = "work") => {
    await clockIn.mutateAsync({ entryType: type });
  };

  const handleClockOut = async () => {
    if (stats.activeEntry) {
      await clockOut.mutateAsync({ entryId: stats.activeEntry.id });
    }
  };

  const handleAddManual = async () => {
    const clockInDateTime = new Date(`${manualDate}T${manualClockIn}`);
    const clockOutDateTime = new Date(`${manualDate}T${manualClockOut}`);

    await createEntry.mutateAsync({
      clockIn: clockInDateTime.toISOString(),
      clockOut: clockOutDateTime.toISOString(),
      entryType: manualType,
      notes: manualNotes || undefined,
    });

    setAddDialogOpen(false);
    setManualNotes("");
  };

  const handleDelete = (entryId: string) => {
    setEntryToDelete(entryId);
    setDeleteDialogOpen(true);
  };

  const confirmDelete = async () => {
    if (entryToDelete) {
      await deleteEntry.mutateAsync(entryToDelete);
      setDeleteDialogOpen(false);
      setEntryToDelete(null);
    }
  };

  const exportToCsv = () => {
    const headers = ["Date", "Clock In", "Clock Out", "Duration (hrs)", "Type", "Notes"];
    const rows = entries.map((e) => [
      format(new Date(e.clock_in), "yyyy-MM-dd"),
      format(new Date(e.clock_in), "HH:mm"),
      e.clock_out ? format(new Date(e.clock_out), "HH:mm") : "",
      e.duration_minutes ? formatHoursDecimal(e.duration_minutes) : "",
      e.entry_type,
      e.notes || "",
    ]);

    const csv = [headers.join(","), ...rows.map((r) => r.join(","))].join("\n");
    const blob = new Blob([csv], { type: "text/csv" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `time-entries-${format(new Date(), "yyyy-MM-dd")}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  if (moduleLoading || !isAllowed) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <>
      <PageContainer maxWidth="xl">
        <PageHeader
          icon={<Clock className="h-5 w-5" />}
          title="Time Tracking"
          description="Track work hours, breaks, and travel time"
          action={
            <div className="flex gap-2">
              <Button variant="outline" onClick={exportToCsv}>
                <Download className="h-4 w-4 mr-2" />
                Export CSV
              </Button>
              <Button variant="outline" onClick={() => setAddDialogOpen(true)}>
                <Calendar className="h-4 w-4 mr-2" />
                Add Manual Entry
              </Button>
            </div>
          }
        />

        {/* Clock In/Out Card */}
        <Card className="mb-6">
          <CardContent className="pt-6">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-lg font-medium">
                  {stats.isClockedIn ? "Currently Working" : "Not Clocked In"}
                </h3>
                {stats.activeEntry && (
                  <p className="text-sm text-muted-foreground">
                    Started {formatDistanceToNow(new Date(stats.activeEntry.clock_in), { addSuffix: true })}
                    {" • "}
                    {entryTypeConfig[stats.activeEntry.entry_type]?.label}
                  </p>
                )}
              </div>
              <div className="flex gap-2">
                {stats.isClockedIn ? (
                  <Button
                    variant="destructive"
                    size="lg"
                    onClick={handleClockOut}
                    disabled={clockOut.isPending}
                  >
                    {clockOut.isPending ? (
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    ) : (
                      <Square className="h-4 w-4 mr-2" />
                    )}
                    Clock Out
                  </Button>
                ) : (
                  <>
                    <Button
                      size="lg"
                      onClick={() => handleClockIn("work")}
                      disabled={clockIn.isPending}
                    >
                      {clockIn.isPending ? (
                        <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                      ) : (
                        <Play className="h-4 w-4 mr-2" />
                      )}
                      Clock In
                    </Button>
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="outline" size="lg">
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent>
                        <DropdownMenuItem onClick={() => handleClockIn("travel")}>
                          <Car className="h-4 w-4 mr-2" />
                          Start Travel
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => handleClockIn("admin")}>
                          <Briefcase className="h-4 w-4 mr-2" />
                          Start Admin Work
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </>
                )}
              </div>
            </div>
          </CardContent>
        </Card>

        {/* Stats Cards */}
        <div className="grid gap-4 md:grid-cols-4 mb-6">
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Today</CardTitle>
              <Clock className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatDuration(stats.todayMinutes)}</div>
              <p className="text-xs text-muted-foreground">
                {stats.todayEntries} entries
              </p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">This Week</CardTitle>
              <Calendar className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatDuration(stats.weekMinutes)}</div>
              <p className="text-xs text-muted-foreground">
                {stats.weekEntries} entries
              </p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Week Hours</CardTitle>
              <Briefcase className="h-4 w-4 text-muted-foreground" />
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">{formatHoursDecimal(stats.weekMinutes)}</div>
              <p className="text-xs text-muted-foreground">
                decimal hours
              </p>
            </CardContent>
          </Card>
          <Card>
            <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
              <CardTitle className="text-sm font-medium">Status</CardTitle>
              {stats.isClockedIn ? (
                <div className="h-3 w-3 rounded-full bg-green-500 animate-pulse" />
              ) : (
                <div className="h-3 w-3 rounded-full bg-muted" />
              )}
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                {stats.isClockedIn ? "Active" : "Off"}
              </div>
              <p className="text-xs text-muted-foreground">
                {stats.isClockedIn ? "Currently working" : "Not clocked in"}
              </p>
            </CardContent>
          </Card>
        </div>

        {/* Time Entries List */}
        <Card>
          <CardHeader>
            <CardTitle>Recent Time Entries</CardTitle>
          </CardHeader>
          <CardContent>
            {entries.length === 0 ? (
              <div className="flex flex-col items-center justify-center py-12 text-center">
                <Clock className="h-12 w-12 text-muted-foreground/50 mb-4" />
                <h3 className="text-lg font-medium">No time entries yet</h3>
                <p className="text-muted-foreground mb-4">
                  Clock in to start tracking your time.
                </p>
              </div>
            ) : (
              <div className="space-y-3">
                {entries.slice(0, 50).map((entry) => (
                  <TimeEntryRow
                    key={entry.id}
                    entry={entry}
                    onDelete={() => handleDelete(entry.id)}
                  />
                ))}
              </div>
            )}
          </CardContent>
        </Card>
      </PageContainer>

      {/* Add Manual Entry Dialog */}
      <Dialog open={addDialogOpen} onOpenChange={setAddDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Add Manual Time Entry</DialogTitle>
            <DialogDescription>
              Add a time entry for work you forgot to track.
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-4">
            <div className="space-y-2">
              <Label htmlFor="date">Date</Label>
              <Input
                id="date"
                type="date"
                value={manualDate}
                onChange={(e) => setManualDate(e.target.value)}
              />
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="clockIn">Clock In</Label>
                <Input
                  id="clockIn"
                  type="time"
                  value={manualClockIn}
                  onChange={(e) => setManualClockIn(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label htmlFor="clockOut">Clock Out</Label>
                <Input
                  id="clockOut"
                  type="time"
                  value={manualClockOut}
                  onChange={(e) => setManualClockOut(e.target.value)}
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label htmlFor="type">Type</Label>
              <Select value={manualType} onValueChange={(v) => setManualType(v as TimeEntry["entry_type"])}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="work">Work</SelectItem>
                  <SelectItem value="travel">Travel</SelectItem>
                  <SelectItem value="admin">Admin</SelectItem>
                  <SelectItem value="break">Break</SelectItem>
                </SelectContent>
              </Select>
            </div>
            <div className="space-y-2">
              <Label htmlFor="notes">Notes (optional)</Label>
              <Input
                id="notes"
                value={manualNotes}
                onChange={(e) => setManualNotes(e.target.value)}
                placeholder="What did you work on?"
              />
            </div>
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setAddDialogOpen(false)}>
              Cancel
            </Button>
            <Button onClick={handleAddManual} disabled={createEntry.isPending}>
              {createEntry.isPending && <Loader2 className="h-4 w-4 mr-2 animate-spin" />}
              Add Entry
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={deleteDialogOpen} onOpenChange={setDeleteDialogOpen}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle>Delete Time Entry</DialogTitle>
            <DialogDescription>
              Are you sure you want to delete this time entry? This action cannot be undone.
            </DialogDescription>
          </DialogHeader>
          <DialogFooter>
            <Button variant="outline" onClick={() => setDeleteDialogOpen(false)}>
              Cancel
            </Button>
            <Button variant="destructive" onClick={confirmDelete}>
              Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import { useState, useEffect, useMemo } from "react";
import { useSearchParams } from "react-router-dom";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useIndustryContext } from "@/hooks/useIndustryContext";
import { useCapabilities } from "@/hooks/useCapabilities";
import { computeCallPriority } from "@/lib/priorityScoring";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { PageContainer } from "@/components/layout/PageContainer";
import { PageHeader } from "@/components/layout/PageHeader";
import { EmptyState } from "@/components/ui/empty-state";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { Phone, Users, Search, Loader2, MoreHorizontal, Flame, Thermometer, Snowflake } from "lucide-react";
import { useTerminology } from "@/hooks/useTerminology";
import { InboxCallCard } from "@/components/calls/InboxCallCard";
import { CallDetailPanel } from "@/components/calls/CallDetailPanel";
import { PipelineSummaryBar, type PipelineStage } from "@/components/leads/PipelineSummaryBar";
import { cn } from "@/lib/utils";
import { formatDistanceToNow } from "date-fns";
import { toast } from "sonner";

type TabValue = "calls" | "leads";

/** Outcomes that represent an actual lead / opportunity */
const LEAD_OUTCOMES = new Set(["followup", "lead_captured", "dispatch", "escalated", "booked", "order", "message"]);

interface CallSession {
  id: string;
  started_at: string;
  ended_at: string | null;
  caller_phone: string | null;
  call_direction: "inbound" | "outbound";
  outcome: string | null;
  summary: string | null;
  transcript?: string | null;
  context_json: Record<string, unknown> | null;
  extracted_payload: Record<string, unknown> | null;
  customer_id: string | null;
  followup_status?: string | null;
  customer?: {
    id: string;
    full_name: string;
    phone_e164: string;
  } | null;
}

// Helper to extract customer name from call data
// Priority: per-call extracted name > customer record > context fallback
function getCustomerName(call: CallSession): string {
  // 1. Best source: extracted_payload.customer.name (per-call, from AI extraction)
  const payload = call.extracted_payload;
  if (payload) {
    const customer = payload.customer as Record<string, unknown> | undefined;
    if (customer && typeof customer.name === "string" && customer.name && customer.name !== "Unknown") {
      return customer.name;
    }
    // Flat fallback
    const flatName = payload.customer_name || payload.name;
    if (typeof flatName === "string" && flatName && flatName !== "Unknown") return flatName;
  }

  // 2. context_json.customer_name — may be a string or an object with .value
  const ctx = call.context_json;
  if (ctx) {
    const raw = ctx.customer_name;
    if (typeof raw === "string" && raw && raw !== "Unknown") return raw;
    if (raw && typeof raw === "object" && (raw as Record<string, unknown>).value) {
      const val = (raw as Record<string, unknown>).value;
      if (typeof val === "string" && val && val !== "Unknown") return val;
    }
    const fallback = ctx.name || ctx.caller_name;
    if (typeof fallback === "string" && fallback && fallback !== "Unknown") return fallback;
  }

  // 3. Customer record from DB (may be stale for shared phone numbers)
  if (call.customer?.full_name && call.customer.full_name !== "Unknown") {
    return call.customer.full_name;
  }

  return "Unknown Caller";
}

function getLeadStage(call: CallSession): PipelineStage {
  if (call.outcome === "booked") return "won";
  if (call.outcome === "lost") return "lost";
  const status = call.followup_status;
  if (status === "contacted") return "contacted";
  if (status === "quoted") return "quoted";
  if (status === "won") return "won";
  if (status === "lost") return "lost";
  return "new";
}

function getLeadTemperature(call: CallSession): "hot" | "warm" | "cold" {
  const hoursSince = (Date.now() - new Date(call.started_at).getTime()) / (1000 * 60 * 60);
  if (call.outcome === "booked" || call.outcome === "dispatch") return "hot";
  if (hoursSince <= 24 && call.outcome !== "lost") return "hot";
  if (call.outcome === "followup" || call.outcome === "lead_captured") {
    return hoursSince <= 72 ? "warm" : "cold";
  }
  if (hoursSince <= 72) return "warm";
  return "cold";
}

const tempConfig = {
  hot: { icon: Flame, color: "text-red-500", bg: "bg-red-500/10" },
  warm: { icon: Thermometer, color: "text-amber-500", bg: "bg-amber-500/10" },
  cold: { icon: Snowflake, color: "text-sky-500", bg: "bg-sky-500/10" },
};

export default function UnifiedInboxPage() {
  const { tenant } = useAuth();
  const queryClient = useQueryClient();
  const { config } = useIndustryContext();
  const terms = useTerminology();
  const caps = useCapabilities();
  const [searchParams, setSearchParams] = useSearchParams();
  const tabParam = searchParams.get("tab");

  // Tab state
  const isValidTab = (t: string | null): t is TabValue =>
    t === "calls" || t === "leads";
  const defaultTab: TabValue = caps.isDispatchBusiness ? "calls" : "leads";
  const [activeTab, setActiveTab] = useState<TabValue>(
    isValidTab(tabParam) ? tabParam : defaultTab
  );

  // Search and filter
  const [searchQuery, setSearchQuery] = useState("");
  const [outcomeFilter, setOutcomeFilter] = useState("all");
  const [pipelineStage, setPipelineStage] = useState<PipelineStage | "all">("all");
  const [selectedCall, setSelectedCall] = useState<CallSession | null>(null);

  // Sync URL with tab state
  useEffect(() => {
    if (tabParam !== activeTab) {
      setSearchParams({ tab: activeTab }, { replace: true });
    }
  }, [activeTab, tabParam, setSearchParams]);

  useEffect(() => {
    if (isValidTab(tabParam) && tabParam !== activeTab) {
      setActiveTab(tabParam);
    }
  }, [tabParam]);

  // Realtime subscription for calls
  useEffect(() => {
    if (!tenant?.id) return;
    const channel = supabase
      .channel("inbox-calls-realtime")
      .on(
        "postgres_changes",
        { event: "*", schema: "public", table: "ai_call_sessions", filter: `tenant_id=eq.${tenant.id}` },
        () => {
          queryClient.invalidateQueries({ queryKey: ["inbox_calls", tenant.id] });
        }
      )
      .subscribe();
    return () => { supabase.removeChannel(channel); };
  }, [tenant?.id, queryClient]);

  // Fetch calls
  const { data: calls, isLoading: callsLoading } = useQuery({
    queryKey: ["inbox_calls", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("ai_call_sessions")
        .select(`
          id, started_at, ended_at, caller_phone, call_direction,
          outcome, summary, transcript, context_json, extracted_payload,
          customer_id, followup_status, customer:customers!ai_call_sessions_customer_id_fkey (id, full_name, phone_e164)
        `)
        .eq("tenant_id", tenant.id)
        .order("started_at", { ascending: false })
        .limit(200);
      if (error) throw error;
      return (data || []).map((row) => ({
        ...row,
        context_json: row.context_json as Record<string, unknown> | null,
        extracted_payload: row.extracted_payload as Record<string, unknown> | null,
        customer: Array.isArray(row.customer) ? row.customer[0] : row.customer,
      })) as CallSession[];
    },
    enabled: !!tenant?.id,
  });

  // Helper: compute priority for a call
  const getCallPriority = (call: CallSession) => {
    const callbackRequested = !!(
      call.extracted_payload &&
      typeof call.extracted_payload === "object" &&
      (call.extracted_payload as Record<string, unknown>).callback &&
      typeof (call.extracted_payload as Record<string, unknown>).callback === "object" &&
      ((call.extracted_payload as Record<string, unknown>).callback as Record<string, unknown>)?.requested
    );
    return computeCallPriority(
      { outcome: call.outcome, started_at: call.started_at, callbackRequested },
      config.priority,
    );
  };

  // Leads: lead-worthy outcomes
  const allLeads = useMemo(() => {
    if (!calls) return [];
    return calls.filter((call) => call.outcome && LEAD_OUTCOMES.has(call.outcome));
  }, [calls]);

  // Pipeline counts
  const pipelineCounts = useMemo(() => {
    const counts: Record<PipelineStage, number> = { new: 0, contacted: 0, quoted: 0, won: 0, lost: 0 };
    for (const lead of allLeads) {
      counts[getLeadStage(lead)]++;
    }
    return counts;
  }, [allLeads]);

  // Filtered leads with pipeline + search
  const filteredLeads = useMemo(() => {
    return allLeads
      .filter((call) => {
        if (pipelineStage !== "all" && getLeadStage(call) !== pipelineStage) return false;
        const query = searchQuery.toLowerCase();
        if (!query) return true;
        return (
          call.caller_phone?.toLowerCase().includes(query) ||
          call.summary?.toLowerCase().includes(query) ||
          getCustomerName(call).toLowerCase().includes(query)
        );
      })
      .sort((a, b) => {
        const aPriority = getCallPriority(a);
        const bPriority = getCallPriority(b);
        if (bPriority.score !== aPriority.score) return bPriority.score - aPriority.score;
        return new Date(b.started_at).getTime() - new Date(a.started_at).getTime();
      });
  }, [allLeads, pipelineStage, searchQuery, config.priority]);

  // Calls: chronological log
  const filteredCalls = useMemo(() => {
    if (!calls) return [];
    return calls.filter((call) => {
      const query = searchQuery.toLowerCase();
      const matchesSearch = !query ||
        call.caller_phone?.toLowerCase().includes(query) ||
        call.summary?.toLowerCase().includes(query) ||
        getCustomerName(call).toLowerCase().includes(query);
      let matchesOutcome = true;
      if (outcomeFilter !== "all") {
        matchesOutcome = call.outcome === outcomeFilter;
      }
      return matchesSearch && matchesOutcome;
    });
  }, [calls, searchQuery, outcomeFilter]);

  // Counts
  const leadsCount = allLeads.length;
  const totalCallsCount = calls?.length || 0;

  const handleTabChange = (value: string) => {
    if (isValidTab(value)) {
      setActiveTab(value);
      setSearchQuery("");
      setOutcomeFilter("all");
      setPipelineStage("all");
    }
  };

  const handleStageChange = async (callId: string, newStage: PipelineStage) => {
    let followup_status: string | null = newStage;
    let outcome: string | undefined;

    if (newStage === "won") { outcome = "booked"; followup_status = "won"; }
    else if (newStage === "lost") { outcome = "lost"; followup_status = "lost"; }
    else if (newStage === "new") { followup_status = null; }

    const updateData: Record<string, unknown> = { followup_status };
    if (outcome) updateData.outcome = outcome;

    const { error } = await supabase
      .from("ai_call_sessions")
      .update(updateData)
      .eq("id", callId);

    if (error) {
      toast.error("Failed to update lead stage");
      return;
    }

    queryClient.invalidateQueries({ queryKey: ["inbox_calls", tenant?.id] });
    toast.success(`Lead moved to ${newStage}`);
  };

  return (
    <PageContainer maxWidth="xl">
      <PageHeader
        title={terms.inboxPageTitle}
        description={terms.inboxPageSubtitle}
      />

      <Tabs value={activeTab} onValueChange={handleTabChange}>
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
          <TabsList>
            <TabsTrigger value="leads" className="gap-2">
              <Users className="h-4 w-4" />
              Leads
              {leadsCount > 0 && (
                <Badge variant="secondary" className="ml-1 h-5 px-1.5 text-xs">
                  {leadsCount}
                </Badge>
              )}
            </TabsTrigger>
            <TabsTrigger value="calls" className="gap-2">
              <Phone className="h-4 w-4" />
              Calls
              {totalCallsCount > 0 && (
                <Badge variant="secondary" className="ml-1 h-5 px-1.5 text-xs">
                  {totalCallsCount}
                </Badge>
              )}
            </TabsTrigger>
          </TabsList>

          <div className="flex items-center gap-2">
            <div className="relative flex-1 sm:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
              <Input
                placeholder="Search..."
                className="pl-10"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>
            {activeTab === "calls" && (
              <Select value={outcomeFilter} onValueChange={setOutcomeFilter}>
                <SelectTrigger className="w-36">
                  <SelectValue placeholder="Outcome" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All</SelectItem>
                  <SelectItem value="booked">Booked</SelectItem>
                  <SelectItem value="followup">Follow-up</SelectItem>
                  <SelectItem value="lead_captured">Lead</SelectItem>
                  <SelectItem value="lost">Lost</SelectItem>
                  <SelectItem value="escalated">Escalated</SelectItem>
                </SelectContent>
              </Select>
            )}
          </div>
        </div>

        {/* LEADS TAB: Pipeline summary bar + professional table */}
        <TabsContent value="leads" className="mt-6 space-y-4">
          {callsLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : allLeads.length === 0 ? (
            <EmptyState
              icon={Users}
              title="No leads yet"
              description="When callers express interest or request follow-ups, they'll appear here in your pipeline."
            />
          ) : (
            <>
              {/* Pipeline summary bar */}
              <div className="overflow-x-auto">
                <PipelineSummaryBar
                  counts={pipelineCounts}
                  activeStage={pipelineStage}
                  onStageClick={setPipelineStage}
                />
              </div>

              {/* Professional leads table */}
              {filteredLeads.length === 0 ? (
                <EmptyState
                  icon={Users}
                  title="No leads in this stage"
                  description="Try selecting a different pipeline stage."
                  compact
                />
              ) : (
                <div className="rounded-xl border border-border/30 bg-card/60 backdrop-blur-sm overflow-hidden card-interactive">
                  <Table>
                    <TableHeader className="bg-card/80">
                      <TableRow>
                        <TableHead>Contact</TableHead>
                        <TableHead>Temperature</TableHead>
                        <TableHead>Stage</TableHead>
                        <TableHead className="hidden md:table-cell">Summary</TableHead>
                        <TableHead className="hidden sm:table-cell">Last Activity</TableHead>
                        <TableHead className="text-right">Actions</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {filteredLeads.map((call) => {
                        const name = getCustomerName(call);
                        const temp = getLeadTemperature(call);
                        const TempIcon = tempConfig[temp].icon;
                        const stage = getLeadStage(call);

                        return (
                          <TableRow
                            key={call.id}
                            className="cursor-pointer hover:bg-card/90 hover:shadow-sm transition-all"
                            onClick={() => setSelectedCall(call)}
                          >
                            <TableCell>
                              <div className="flex items-center gap-3">
                                <div className={cn(
                                  "h-9 w-9 rounded-full flex items-center justify-center text-sm font-semibold shrink-0",
                                  tempConfig[temp].bg, tempConfig[temp].color
                                )}>
                                  {name.charAt(0).toUpperCase()}
                                </div>
                                <div>
                                  <p className="font-medium text-sm">{name}</p>
                                  <p className="text-xs text-muted-foreground">{call.caller_phone || "No phone"}</p>
                                </div>
                              </div>
                            </TableCell>
                            <TableCell>
                              <Badge variant="outline" className={cn("gap-1 text-xs", tempConfig[temp].bg, tempConfig[temp].color)}>
                                <TempIcon className="h-3 w-3" />
                                {temp.charAt(0).toUpperCase() + temp.slice(1)}
                              </Badge>
                            </TableCell>
                            <TableCell>
                              <Select
                                value={stage}
                                onValueChange={(val) => {
                                  handleStageChange(call.id, val as PipelineStage);
                                }}
                              >
                                <SelectTrigger className="h-7 w-28 text-xs border-border/30" onClick={(e) => e.stopPropagation()}>
                                  <SelectValue />
                                </SelectTrigger>
                                <SelectContent>
                                  <SelectItem value="new">New</SelectItem>
                                  <SelectItem value="contacted">Contacted</SelectItem>
                                  <SelectItem value="quoted">Quoted</SelectItem>
                                  <SelectItem value="won">Won</SelectItem>
                                  <SelectItem value="lost">Lost</SelectItem>
                                </SelectContent>
                              </Select>
                            </TableCell>
                            <TableCell className="hidden md:table-cell max-w-[250px]">
                              <p className="text-sm text-muted-foreground truncate">
                                {call.summary || "No summary"}
                              </p>
                            </TableCell>
                            <TableCell className="hidden sm:table-cell text-sm text-muted-foreground">
                              {formatDistanceToNow(new Date(call.started_at), { addSuffix: true })}
                            </TableCell>
                            <TableCell className="text-right">
                              <DropdownMenu>
                                <DropdownMenuTrigger asChild onClick={(e) => e.stopPropagation()}>
                                  <Button variant="ghost" size="icon-sm">
                                    <MoreHorizontal className="h-4 w-4" />
                                  </Button>
                                </DropdownMenuTrigger>
                                <DropdownMenuContent align="end">
                                  {call.caller_phone && (
                                    <DropdownMenuItem onClick={() => window.open(`tel:${call.caller_phone}`, "_self")}>
                                      <Phone className="mr-2 h-4 w-4" /> Call
                                    </DropdownMenuItem>
                                  )}
                                  <DropdownMenuItem onClick={() => setSelectedCall(call)}>
                                    <Users className="mr-2 h-4 w-4" /> View Details
                                  </DropdownMenuItem>
                                </DropdownMenuContent>
                              </DropdownMenu>
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                </div>
              )}
              <p className="text-xs text-muted-foreground text-center">
                {filteredLeads.length} lead{filteredLeads.length !== 1 ? "s" : ""}
              </p>
            </>
          )}
        </TabsContent>

        {/* CALLS TAB: simple chronological call log */}
        <TabsContent value="calls" className="mt-6">
          {callsLoading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : filteredCalls.length === 0 ? (
            <EmptyState
              icon={Phone}
              title="No calls yet"
              description="All incoming and outgoing calls will appear here."
            />
          ) : (
            <div className="divide-y divide-border/20 rounded-xl bg-card/60 backdrop-blur-sm border border-border/30">
              {filteredCalls.map((call) => (
                <InboxCallCard
                  key={call.id}
                  call={call}
                  customerName={getCustomerName(call)}
                  onClick={() => setSelectedCall(call)}
                  priorityConfig={config.priority}
                  inboxConfig={config.inbox}
                />
              ))}
            </div>
          )}
        </TabsContent>
      </Tabs>

      {/* Call Detail Slide-over */}
      <CallDetailPanel
        call={selectedCall}
        onClose={() => setSelectedCall(null)}
        customerName={selectedCall ? getCustomerName(selectedCall) : undefined}
      />
    </PageContainer>
  );
}

import { useAuth } from "@/contexts/AuthContext";
import { useSubscription } from "@/hooks/useSubscription";
import { useUsage } from "@/hooks/useUsage";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { 
  Phone, MessageSquare, TrendingUp, AlertTriangle, 
  ArrowUpRight, Calendar, DollarSign
} from "lucide-react";
import { Link } from "react-router-dom";
import {
  getLadderStep,
  getTierInfo,
  formatPrice,
  type PlanSku,
} from "@/config/pricing";

export default function UsagePage() {
  const { tenant } = useAuth();
  const { subscription, planSku, hasVoice, hasSms, loading: subLoading } = useSubscription(tenant?.id || null);
  const { usage, loading: usageLoading, nextUpgrade } = useUsage(tenant?.id || null, planSku);

  const step = planSku ? getLadderStep(planSku) : null;
  const tierInfo = step ? getTierInfo(step.tier) : null;

  const isLoading = subLoading || usageLoading;

  if (isLoading) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <div>
          <h1 className="text-2xl font-bold">Usage</h1>
          <p className="text-muted-foreground">Track your voice minutes</p>
        </div>
        <div className="grid gap-6 md:grid-cols-2">
          <Skeleton className="h-64" />
          <Skeleton className="h-64" />
        </div>
      </div>
    );
  }

  if (!subscription || !step) {
    return (
      <div className="p-4 md:p-6 space-y-6">
        <div>
          <h1 className="text-2xl font-bold">Usage</h1>
          <p className="text-muted-foreground">Track your voice minutes</p>
        </div>
        <Card>
          <CardContent className="py-8 text-center">
            <p className="text-muted-foreground mb-4">No active subscription found.</p>
            <Link to="/app/go-live">
              <Button>Choose a Plan</Button>
            </Link>
          </CardContent>
        </Card>
      </div>
    );
  }

  const formatDate = (date: Date | null) => {
    if (!date) return "—";
    return date.toLocaleDateString("en-US", { month: "short", day: "numeric" });
  };

  const totalOverage = (usage?.projectedVoiceOverage || 0) + (usage?.projectedSmsOverage || 0);

  return (
    <div className="p-4 md:p-6 space-y-6">
      <div>
        <h1 className="text-2xl font-bold">Usage</h1>
        <p className="text-muted-foreground">Track your voice minutes</p>
      </div>

      {/* Current Plan Overview */}
      <Card>
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <div>
              <CardTitle className="text-lg">{tierInfo?.displayName}</CardTitle>
              <CardDescription>{step.name}</CardDescription>
            </div>
            <Badge variant={subscription.status === "trialing" ? "secondary" : "default"}>
              {subscription.status === "trialing" ? "Trial" : "Active"}
            </Badge>
          </div>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between text-sm">
            <div className="flex items-center gap-2 text-muted-foreground">
              <Calendar className="h-4 w-4" />
              Billing period: {formatDate(usage?.billingPeriodStart)} – {formatDate(usage?.billingPeriodEnd)}
            </div>
            <div className="font-medium">{formatPrice(step.price)}/mo</div>
          </div>
        </CardContent>
      </Card>

      {/* Usage Cards */}
      <div className="grid gap-6 md:grid-cols-2">
        {/* Voice Usage */}
        {hasVoice && usage?.includedMinutes !== null && (
          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center gap-2">
                <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
                  <Phone className="h-5 w-5 text-primary" />
                </div>
                <div>
                  <CardTitle className="text-lg">Voice Minutes</CardTitle>
                  <CardDescription>Inbound call duration</CardDescription>
                </div>
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <div className="flex items-center justify-between text-sm mb-2">
                  <span>{usage.voiceMinutesUsed.toLocaleString()} used</span>
                  <span>{usage.includedMinutes?.toLocaleString()} included</span>
                </div>
                <Progress 
                  value={usage.voicePercentUsed} 
                  className={usage.voicePercentUsed >= 90 ? "bg-destructive/20" : ""}
                />
              </div>

              {usage.voicePercentUsed >= 80 && (
                <div className="flex items-start gap-2 p-3 rounded-lg bg-amber-500/10 text-amber-700 dark:text-amber-400">
                  <AlertTriangle className="h-4 w-4 mt-0.5 shrink-0" />
                  <div className="text-sm">
                    {usage.voicePercentUsed >= 100 
                      ? "You've exceeded your included minutes. Overage charges apply."
                      : "Approaching your included minutes limit."}
                  </div>
                </div>
              )}

              {usage.projectedVoiceOverage > 0 && (
                <div className="flex items-center justify-between p-3 rounded-lg bg-muted">
                  <div className="text-sm">
                    <div className="font-medium">Projected overage</div>
                    <div className="text-muted-foreground">
                      {Math.max(0, usage.voiceMinutesUsed - (usage.includedMinutes || 0))} min @ ${usage.overageMinuteRate}/min
                    </div>
                  </div>
                  <div className="font-bold text-lg">${usage.projectedVoiceOverage.toFixed(2)}</div>
                </div>
              )}
            </CardContent>
          </Card>
        )}

        {/* SMS Usage */}
        {hasSms && usage?.includedSmsSegments !== null && (
          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center gap-2">
                <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10">
                  <MessageSquare className="h-5 w-5 text-primary" />
                </div>
                <div>
                  <CardTitle className="text-lg">SMS Segments</CardTitle>
                  <CardDescription>Text messages sent</CardDescription>
                </div>
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <div className="flex items-center justify-between text-sm mb-2">
                  <span>{usage.smsSegmentsUsed.toLocaleString()} used</span>
                  <span>{usage.includedSmsSegments?.toLocaleString()} included</span>
                </div>
                <Progress 
                  value={usage.smsPercentUsed} 
                  className={usage.smsPercentUsed >= 90 ? "bg-destructive/20" : ""}
                />
              </div>

              {usage.smsPercentUsed >= 80 && (
                <div className="flex items-start gap-2 p-3 rounded-lg bg-amber-500/10 text-amber-700 dark:text-amber-400">
                  <AlertTriangle className="h-4 w-4 mt-0.5 shrink-0" />
                  <div className="text-sm">
                    {usage.smsPercentUsed >= 100 
                      ? "You've exceeded your included SMS segments. Overage charges apply."
                      : "Approaching your included SMS limit."}
                  </div>
                </div>
              )}

              {usage.projectedSmsOverage > 0 && (
                <div className="flex items-center justify-between p-3 rounded-lg bg-muted">
                  <div className="text-sm">
                    <div className="font-medium">Projected overage</div>
                    <div className="text-muted-foreground">
                      {Math.max(0, usage.smsSegmentsUsed - (usage.includedSmsSegments || 0))} SMS @ ${usage.overageSmsRate}/SMS
                    </div>
                  </div>
                  <div className="font-bold text-lg">${usage.projectedSmsOverage.toFixed(2)}</div>
                </div>
              )}
            </CardContent>
          </Card>
        )}
      </div>

      {/* Total Projected Overage */}
      {totalOverage > 0 && (
        <Card className="border-amber-500/50 bg-amber-500/5">
          <CardContent className="py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <DollarSign className="h-5 w-5 text-amber-600" />
                <div>
                  <div className="font-medium">Total Projected Overage This Period</div>
                  <div className="text-sm text-muted-foreground">
                    Will be added to your next invoice
                  </div>
                </div>
              </div>
              <div className="text-2xl font-bold">${totalOverage.toFixed(2)}</div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Upgrade Suggestion */}
      {nextUpgrade && (usage?.voicePercentUsed || 0) >= 70 && (
        <Card>
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <TrendingUp className="h-5 w-5 text-primary" />
              <CardTitle className="text-lg">Save Money by Upgrading</CardTitle>
            </div>
          </CardHeader>
          <CardContent>
            <div className="flex items-center justify-between p-4 rounded-lg border">
              <div>
                <div className="font-medium">{nextUpgrade.name}</div>
                <div className="text-sm text-muted-foreground">
                  {nextUpgrade.includedMinutes && `${nextUpgrade.includedMinutes.toLocaleString()} minutes`}
                  {nextUpgrade.includedMinutes && nextUpgrade.includedSmsSegments && " + "}
                  {nextUpgrade.includedSmsSegments && `${nextUpgrade.includedSmsSegments.toLocaleString()} SMS`}
                  {" included"}
                </div>
              </div>
              <div className="text-right">
                <div className="font-bold">{formatPrice(nextUpgrade.price)}/mo</div>
                {totalOverage > (nextUpgrade.price - step.price) && (
                  <div className="text-sm text-primary">
                    Saves ${(totalOverage - (nextUpgrade.price - step.price)).toFixed(2)}/mo
                  </div>
                )}
              </div>
            </div>
            <Link to="/app/settings?tab=billing">
              <Button className="w-full mt-4">
                Upgrade Plan
                <ArrowUpRight className="ml-2 h-4 w-4" />
              </Button>
            </Link>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { ArrowLeft, Plus, Save, Play, GripVertical, Settings, Trash2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { useWorkflow, useWorkflowMutations, useWorkflowNodeMutations } from "@/hooks/useWorkflows";
import { useTenantConfig } from "@/hooks/useTenantConfig";
import { 
  NODE_TYPE_METADATA, 
  TRIGGER_METADATA,
  TEMPLATE_VARIABLES,
  type WorkflowNodeType,
  type WorkflowNode 
} from "@/types/workflow";
import { NodeConfigEditor } from "@/components/workflows/NodeConfigEditor";
import { useAuth } from "@/contexts/AuthContext";

export default function WorkflowEditPage() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { tenant } = useAuth();
  const tenantId = tenant?.id ?? null;
  
  const { data: workflow, isLoading } = useWorkflow(id ?? null);
  const { updateWorkflow, activateWorkflow } = useWorkflowMutations(tenantId);
  const { addNode, updateNode, deleteNode } = useWorkflowNodeMutations(id ?? null);
  
  const [addNodeOpen, setAddNodeOpen] = useState(false);
  const [selectedNodeType, setSelectedNodeType] = useState<WorkflowNodeType | "">("");
  const [editingNode, setEditingNode] = useState<WorkflowNode | null>(null);
  const [saving, setSaving] = useState(false);
  const [localName, setLocalName] = useState<string | null>(null);
  const [localDescription, setLocalDescription] = useState<string | null>(null);

  // Derive display values: use local state if user has edited, otherwise use server data
  const displayName = localName ?? workflow?.name ?? "";
  const displayDescription = localDescription ?? workflow?.description ?? "";

  const handleSave = async () => {
    if (!workflow) return;
    setSaving(true);
    try {
      await updateWorkflow.mutateAsync({
        id: workflow.id,
        name: displayName,
        description: displayDescription,
      });
      // Reset local overrides so we track server state again
      setLocalName(null);
      setLocalDescription(null);
    } finally {
      setSaving(false);
    }
  };

  const handleAddNode = async () => {
    if (!selectedNodeType) return;
    
    const meta = NODE_TYPE_METADATA[selectedNodeType];
    await addNode.mutateAsync({
      node_type: selectedNodeType,
      name: meta.label,
      config: {},
    });
    
    setAddNodeOpen(false);
    setSelectedNodeType("");
  };

  const handleDeleteNode = async (nodeId: string) => {
    if (confirm("Delete this step?")) {
      await deleteNode.mutateAsync(nodeId);
    }
  };

  const handleActivate = async () => {
    if (!workflow) return;
    await activateWorkflow.mutateAsync(workflow.id);
  };

  if (isLoading) {
    return (
      <div className="container py-6 space-y-6">
        <Skeleton className="h-8 w-48" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  if (!workflow) {
    return (
      <div className="container py-6">
        <p>Workflow not found</p>
      </div>
    );
  }

  const triggerMeta = TRIGGER_METADATA[workflow.trigger];
  const entityType = triggerMeta?.entityType || "order";
  const availableVariables = [
    ...(TEMPLATE_VARIABLES[entityType as keyof typeof TEMPLATE_VARIABLES] || []),
    ...TEMPLATE_VARIABLES.common,
  ];

  return (
    <div className="container py-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" asChild>
            <Link to="/app/workflows">
              <ArrowLeft className="h-5 w-5" />
            </Link>
          </Button>
          <div>
            <h1 className="text-2xl font-bold">{displayName}</h1>
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <span>{triggerMeta?.icon}</span>
              <span>{triggerMeta?.label || workflow.trigger}</span>
              <Badge variant={workflow.status === "active" ? "default" : "secondary"}>
                {workflow.status}
              </Badge>
            </div>
          </div>
        </div>
        
        <div className="flex items-center gap-2">
          <Button variant="outline" onClick={handleSave} disabled={saving}>
            <Save className="h-4 w-4 mr-2" />
            Save
          </Button>
          {workflow.status !== "active" && (
            <Button onClick={handleActivate}>
              <Play className="h-4 w-4 mr-2" />
              Activate
            </Button>
          )}
        </div>
      </div>

      {/* Workflow Details */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Workflow Settings</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <Label>Name</Label>
              <Input
                value={displayName}
                onChange={(e) => setLocalName(e.target.value)}
                placeholder="Workflow name"
              />
            </div>
            <div className="space-y-2">
              <Label>Description</Label>
              <Input
                value={displayDescription}
                onChange={(e) => setLocalDescription(e.target.value)}
                placeholder="Optional description"
              />
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Steps */}
      <Card>
        <CardHeader className="flex-row items-center justify-between">
          <div>
            <CardTitle className="text-lg">Steps</CardTitle>
            <CardDescription>Actions executed in order when the workflow runs</CardDescription>
          </div>
          <Dialog open={addNodeOpen} onOpenChange={setAddNodeOpen}>
            <Button variant="outline" onClick={() => setAddNodeOpen(true)}>
              <Plus className="h-4 w-4 mr-2" />
              Add Step
            </Button>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Add Step</DialogTitle>
                <DialogDescription>Choose an action to add to this workflow</DialogDescription>
              </DialogHeader>
              <div className="grid grid-cols-2 gap-3 py-4">
                {Object.entries(NODE_TYPE_METADATA).map(([type, meta]) => (
                  <button
                    key={type}
                    className={`p-4 rounded-lg border text-left transition-colors hover:bg-muted ${
                      selectedNodeType === type ? "border-primary bg-primary/5" : ""
                    }`}
                    onClick={() => setSelectedNodeType(type as WorkflowNodeType)}
                  >
                    <div className="text-2xl mb-2">{meta.icon}</div>
                    <div className="font-medium">{meta.label}</div>
                    <div className="text-xs text-muted-foreground">{meta.description}</div>
                  </button>
                ))}
              </div>
              <DialogFooter>
                <Button variant="outline" onClick={() => setAddNodeOpen(false)}>
                  Cancel
                </Button>
                <Button onClick={handleAddNode} disabled={!selectedNodeType}>
                  Add
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </CardHeader>
        <CardContent>
          {workflow.nodes.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground">
              <p>No steps yet. Add your first step to get started.</p>
            </div>
          ) : (
            <div className="space-y-3">
              {workflow.nodes.map((node, index) => {
                const meta = NODE_TYPE_METADATA[node.node_type];
                return (
                  <div
                    key={node.id}
                    className="flex items-center gap-3 p-4 rounded-lg border bg-card"
                  >
                    <div className="text-muted-foreground cursor-grab">
                      <GripVertical className="h-5 w-5" />
                    </div>
                    <div className="flex items-center justify-center w-8 h-8 rounded-full bg-muted text-sm font-medium">
                      {index + 1}
                    </div>
                    <div className="text-2xl">{meta?.icon}</div>
                    <div className="flex-1">
                      <div className="font-medium">{node.name}</div>
                      <div className="text-sm text-muted-foreground">
                        {formatNodeConfig(node)}
                      </div>
                    </div>
                    <Button
                      variant="ghost"
                      size="icon"
                      onClick={() => setEditingNode(node)}
                    >
                      <Settings className="h-4 w-4" />
                    </Button>
                    <Button
                      variant="ghost"
                      size="icon"
                      className="text-destructive hover:text-destructive"
                      onClick={() => handleDeleteNode(node.id)}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                );
              })}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Available Variables */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Available Variables</CardTitle>
          <CardDescription>
            Use these in your messages and templates: {"{{variable_name}}"}
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-2">
            {availableVariables.map((v) => (
              <Badge key={v} variant="outline" className="font-mono text-xs">
                {`{{${v}}}`}
              </Badge>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Node Config Editor */}
      {editingNode && (
        <NodeConfigEditor
          node={editingNode}
          open={!!editingNode}
          onClose={() => setEditingNode(null)}
          onSave={async (config) => {
            await updateNode.mutateAsync({
              id: editingNode.id,
              config,
            });
            setEditingNode(null);
          }}
          availableVariables={availableVariables}
        />
      )}
    </div>
  );
}

function formatNodeConfig(node: WorkflowNode): string {
  const config = node.config as Record<string, any>;
  
  switch (node.node_type) {
    case "notify_sms":
      return `To: ${config.to || "Not set"} · Message: ${(config.message || "").slice(0, 30)}...`;
    case "notify_email":
      return `To: ${config.to || "Not set"} · Subject: ${config.subject || "Not set"}`;
    case "delay":
      if (config.minutes) return `Wait ${config.minutes} minutes`;
      if (config.hours) return `Wait ${config.hours} hours`;
      return "Wait duration not set";
    case "webhook_push":
      return `${config.method || "POST"} ${config.url || "URL not set"}`;
    case "print_ticket":
      return `Format: ${config.format || "thermal"} · Copies: ${config.copies || 1}`;
    case "set_field":
      return `Set ${config.entity_field || "field"} = ${config.value || "value"}`;
    default:
      return "Configure this step";
  }
}

