export default function WorkflowsPage() {
  const { tenant, hasActiveSubscription } = useAuth();
  const { businessMode, enabledModules } = useTenantConfig();
  const tenantId = tenant?.id ?? null;
  
  const { data: workflows, isLoading } = useWorkflows(tenantId);
  const { data: stats } = useWorkflowStats(tenantId);
  const { createWorkflow, deleteWorkflow, activateWorkflow, pauseWorkflow } = useWorkflowMutations(tenantId);
  const navigate = useNavigate();
  
  const [createOpen, setCreateOpen] = useState(false);
  const [newName, setNewName] = useState("");
  const [newTrigger, setNewTrigger] = useState<WorkflowTrigger | "">("");
  const [viewMode, setViewMode] = useState<"simple" | "advanced" | "help">("simple");

  // Check if user has access to workflows
  const hasWorkflowAccess = useMemo(() => {
    const workflowModules = ["booking", "food_orders", "dispatch_queue", "ai_voice", "instant_text_back"];
    return workflowModules.some(mod => enabledModules.includes(mod));
  }, [enabledModules]);

  // Get mode-specific templates (strictly gated by business mode)
  const modeTemplates = useMemo(() => {
    const templates = WORKFLOW_TEMPLATES[businessMode] || WORKFLOW_TEMPLATES.general;
    return [...templates, ...UNIVERSAL_TEMPLATES];
  }, [businessMode]);

  // Get mode-appropriate triggers for the create dialog
  const availableTriggers = useMemo(() => {
    const modeTriggerMap: Record<BusinessMode, WorkflowTrigger[]> = {
      service: ["booking.created", "booking.confirmed", "booking.completed", "call.ended", "sms.received", "missed_call"],
      food: ["order.created", "order.confirmed", "order.ready", "order.completed", "reservation.created", "reservation.confirmed", "catering.created", "catering.quoted", "call.ended", "sms.received"],
      dispatch: ["dispatch.created", "dispatch.confirmed", "dispatch.completed", "call.ended", "sms.received", "missed_call"],
      medical: ["intake.created", "intake.scheduled", "booking.created", "booking.confirmed", "call.ended", "sms.received"],
      general: ["call.ended", "sms.received", "missed_call"],
      sales: ["booking.created", "booking.confirmed", "booking.completed", "call.ended", "sms.received", "missed_call"],
    };
    return modeTriggerMap[businessMode] || modeTriggerMap.general;
  }, [businessMode]);

  const activeWorkflows = workflows?.filter(w => w.status === "active") || [];
  const draftWorkflows = workflows?.filter(w => w.status === "draft") || [];
  const pausedWorkflows = workflows?.filter(w => w.status === "paused") || [];

  const handleCreate = async () => {
    if (!newName || !newTrigger) return;
    
    const workflow = await createWorkflow.mutateAsync({
      name: newName,
      trigger: newTrigger as WorkflowTrigger,
    });
    
    setCreateOpen(false);
    setNewName("");
    setNewTrigger("");
    navigate(`/app/workflows/${workflow.id}`);
  };

  const [creatingFromTemplate, setCreatingFromTemplate] = useState(false);
  
  const handleCreateFromTemplate = async (template: WorkflowTemplate) => {
    setCreatingFromTemplate(true);
    try {
      // Create the workflow first
      const workflow = await createWorkflow.mutateAsync({
        name: template.name,
        trigger: template.trigger,
      });
      
      // Add pre-configured nodes from the template
      if (template.nodes && template.nodes.length > 0) {
        for (const nodeConfig of template.nodes) {
          await supabase
            .from("workflow_nodes")
            .insert({
              workflow_id: workflow.id,
              node_type: nodeConfig.node_type,
              name: nodeConfig.name,
              config: nodeConfig.config as any,
              position: { x: 0, y: 0 },
            });
        }
      }
      
      navigate(`/app/workflows/${workflow.id}`);
    } catch (error) {
      console.error("Failed to create workflow from template:", error);
    } finally {
      setCreatingFromTemplate(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm("Are you sure you want to delete this workflow?")) {
      await deleteWorkflow.mutateAsync(id);
    }
  };

  // Access denied state
  if (!hasWorkflowAccess) {
    return (
      <div className="container py-6 flex items-center justify-center min-h-[60vh]">
        <Card className="max-w-md text-center shadow-soft-lg">
          <CardHeader className="pb-4">
            <div className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-muted mb-3">
              <Lock className="h-7 w-7 text-muted-foreground" />
            </div>
            <CardTitle className="text-xl">Workflows Not Available</CardTitle>
            <CardDescription className="text-base">
              Workflows require at least one of the following modules: Booking, Orders, Dispatch, Voice AI, or Text Back.
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-3 pt-2">
            <Button onClick={() => navigate("/app/settings")} className="w-full" size="lg">
              Manage Modules
            </Button>
            <Button 
              variant="outline" 
              onClick={() => navigate("/app/dashboard")}
              className="w-full"
            >
              Back to Dashboard
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="container py-6 space-y-6">
        <div className="flex items-center justify-between">
          <Skeleton className="h-8 w-48" />
          <Skeleton className="h-10 w-32" />
        </div>
        <div className="grid gap-4">
          {[1, 2, 3].map(i => (
            <Skeleton key={i} className="h-24 w-full" />
          ))}
        </div>
      </div>
    );
  }

  // Empty state with templates
  if (workflows?.length === 0) {
    return (
      <div className="container py-6 space-y-8">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold">Workflows</h1>
            <p className="text-muted-foreground">
              Automate what happens after calls, bookings, orders, and dispatches.
            </p>
          </div>
          
          <Dialog open={createOpen} onOpenChange={setCreateOpen}>
            <DialogTrigger asChild>
              <Button>
                <Plus className="h-4 w-4 mr-2" />
                Create Workflow
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Create Workflow</DialogTitle>
                <DialogDescription>
                  Choose a trigger event and give your workflow a name
                </DialogDescription>
              </DialogHeader>
              <div className="space-y-4 py-4">
                <div className="space-y-2">
                  <Label>Workflow Name</Label>
                  <Input
                    placeholder="e.g., New Order Notification"
                    value={newName}
                    onChange={(e) => setNewName(e.target.value)}
                  />
                </div>
                <div className="space-y-2">
                  <Label>Trigger Event</Label>
                  <Select value={newTrigger} onValueChange={(v) => setNewTrigger(v as WorkflowTrigger)}>
                    <SelectTrigger>
                      <SelectValue placeholder="Select when this workflow runs" />
                    </SelectTrigger>
                    <SelectContent>
                      {availableTriggers.map((key) => {
                        const meta = TRIGGER_METADATA[key];
                        return (
                          <SelectItem key={key} value={key}>
                            <span className="mr-2">{meta.icon}</span>
                            {meta.label}
                          </SelectItem>
                        );
                      })}
                    </SelectContent>
                  </Select>
                  <p className="text-xs text-muted-foreground">
                    Only triggers relevant to {businessMode} mode are shown
                  </p>
                </div>
              </div>
              <DialogFooter>
                <Button variant="outline" onClick={() => setCreateOpen(false)}>
                  Cancel
                </Button>
                <Button onClick={handleCreate} disabled={!newName || !newTrigger}>
                  Create
                </Button>
              </DialogFooter>
            </DialogContent>
          </Dialog>
        </div>

        {/* Empty State with Templates */}
        <div className="space-y-6">
          <div className="text-center py-8">
            <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10 mb-4">
              <GitBranch className="h-8 w-8 text-primary" />
            </div>
            <h2 className="text-xl font-semibold mb-2">Get Started with Workflows</h2>
            <p className="text-muted-foreground max-w-md mx-auto">
              Choose a template below to quickly set up automation, or create a custom workflow from scratch.
            </p>
          </div>

          {/* Template Cards */}
          <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
            {modeTemplates.map((template) => {
              const Icon = template.icon;
              return (
                <Card 
                  key={template.id} 
                  className="group cursor-pointer hover:border-primary/50 hover:shadow-md transition-all duration-200"
                  onClick={() => handleCreateFromTemplate(template)}
                >
                  <CardHeader className="pb-3">
                    <div className="flex items-center gap-3">
                      <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10 group-hover:bg-primary/20 transition-colors">
                        <Icon className="h-5 w-5 text-primary" />
                      </div>
                      <div>
                        <CardTitle className="text-base">{template.name}</CardTitle>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <p className="text-sm text-muted-foreground">{template.description}</p>
                    <div className="space-y-1.5">
                      {template.steps.map((step, idx) => (
                        <div key={idx} className="flex items-center gap-2 text-xs text-muted-foreground">
                          <div className="flex h-5 w-5 items-center justify-center rounded-full bg-muted text-[10px] font-medium">
                            {idx + 1}
                          </div>
                          {step}
                        </div>
                      ))}
                    </div>
                    <div className="pt-2">
                      <Button variant="ghost" size="sm" className="w-full group-hover:bg-primary group-hover:text-primary-foreground transition-colors">
                        Use Template
                        <ArrowRight className="h-4 w-4 ml-2" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              );
            })}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container py-6 space-y-6">
      {/* Header with View Mode Toggle */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold">Automations</h1>
          <p className="text-muted-foreground">
            Automate what happens after calls, bookings, orders, and dispatches.
          </p>
        </div>
        
        <div className="flex items-center gap-3">
          {/* Simple/Advanced/Help Toggle */}
          <Tabs value={viewMode} onValueChange={(v) => setViewMode(v as "simple" | "advanced" | "help")}>
            <TabsList className="h-9">
              <TabsTrigger value="simple" className="text-xs gap-1.5">
                <ToggleLeft className="h-3.5 w-3.5" />
                Simple
              </TabsTrigger>
              <TabsTrigger value="advanced" className="text-xs gap-1.5">
                <Sliders className="h-3.5 w-3.5" />
                Advanced
              </TabsTrigger>
              <TabsTrigger value="help" className="text-xs gap-1.5">
                <HelpCircle className="h-3.5 w-3.5" />
                Help
              </TabsTrigger>
            </TabsList>
          </Tabs>

          {viewMode === "advanced" && (
            <Dialog open={createOpen} onOpenChange={setCreateOpen}>
              <DialogTrigger asChild>
                <Button size="sm">
                  <Plus className="h-4 w-4 mr-2" />
                  Create Workflow
                </Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>Create Workflow</DialogTitle>
                  <DialogDescription>
                    Choose a trigger event and give your workflow a name
                  </DialogDescription>
                </DialogHeader>
                <div className="space-y-4 py-4">
                  <div className="space-y-2">
                    <Label>Workflow Name</Label>
                    <Input
                      placeholder="e.g., New Order Notification"
                      value={newName}
                      onChange={(e) => setNewName(e.target.value)}
                    />
                  </div>
                  <div className="space-y-2">
                    <Label>Trigger Event</Label>
                    <Select value={newTrigger} onValueChange={(v) => setNewTrigger(v as WorkflowTrigger)}>
                      <SelectTrigger>
                        <SelectValue placeholder="Select when this workflow runs" />
                      </SelectTrigger>
                      <SelectContent>
                        {availableTriggers.map((key) => {
                          const meta = TRIGGER_METADATA[key];
                          return (
                            <SelectItem key={key} value={key}>
                              <span className="mr-2">{meta.icon}</span>
                              {meta.label}
                            </SelectItem>
                          );
                        })}
                      </SelectContent>
                    </Select>
                    <p className="text-xs text-muted-foreground">
                      Only triggers relevant to {businessMode} mode are shown
                    </p>
                  </div>
                </div>
                <DialogFooter>
                  <Button variant="outline" onClick={() => setCreateOpen(false)}>
                    Cancel
                  </Button>
                  <Button onClick={handleCreate} disabled={!newName || !newTrigger}>
                    Create
                  </Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>
          )}
        </div>
      </div>

      {/* Simple Mode: Toggle-based automation panel */}
      {viewMode === "simple" && (
        <SimpleAutomationPanel onAdvancedClick={() => setViewMode("advanced")} />
      )}

      {/* Help Mode: Full documentation */}
      {viewMode === "help" && (
        <HelpGuideWorkflows mode={businessMode} />
      )}

      {/* Advanced Mode: Full workflow list */}
      {viewMode === "advanced" && (
        <>
          {stats && (
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <Card>
                <CardContent className="p-4 text-center">
                  <div className="text-2xl font-bold">{stats.total}</div>
                  <div className="text-sm text-muted-foreground">Runs Today</div>
                </CardContent>
              </Card>
              <Card>
                <CardContent className="p-4 text-center">
                  <div className="text-2xl font-bold text-primary">{stats.success}</div>
                  <div className="text-sm text-muted-foreground">Successful</div>
                </CardContent>
              </Card>
              <Card>
                <CardContent className="p-4 text-center">
                  <div className="text-2xl font-bold text-destructive">{stats.failed}</div>
                  <div className="text-sm text-muted-foreground">Failed</div>
                </CardContent>
              </Card>
              <Card>
                <CardContent className="p-4 text-center">
                  <div className="text-2xl font-bold text-muted-foreground">{stats.running}</div>
                  <div className="text-sm text-muted-foreground">Running</div>
                </CardContent>
              </Card>
            </div>
          )}

          {/* Empty state for advanced mode */}
          {workflows?.length === 0 && (
            <div className="text-center py-12">
              <div className="mx-auto flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10 mb-4">
                <GitBranch className="h-8 w-8 text-primary" />
              </div>
              <h2 className="text-xl font-semibold mb-2">No Custom Workflows Yet</h2>
              <p className="text-muted-foreground max-w-md mx-auto mb-6">
                Create custom workflows with conditional logic, delays, and multi-step automations.
              </p>
              <Button onClick={() => setCreateOpen(true)}>
                <Plus className="h-4 w-4 mr-2" />
                Create Your First Workflow
              </Button>
            </div>
          )}

          {/* Active Workflows */}
          {activeWorkflows.length > 0 && (
            <WorkflowSection
              title="Active"
              description="These workflows are running"
              workflows={activeWorkflows}
              tenantId={tenantId!}
              onPause={(id) => pauseWorkflow.mutateAsync(id)}
              onDelete={handleDelete}
            />
          )}

          {/* Draft Workflows */}
          {draftWorkflows.length > 0 && (
            <WorkflowSection
              title="Drafts"
              description="Work in progress"
              workflows={draftWorkflows}
              tenantId={tenantId!}
              onActivate={(id) => activateWorkflow.mutateAsync(id)}
              onDelete={handleDelete}
            />
          )}

          {/* Paused Workflows */}
          {pausedWorkflows.length > 0 && (
            <WorkflowSection
              title="Paused"
              description="Temporarily stopped"
              workflows={pausedWorkflows}
              tenantId={tenantId!}
              onActivate={(id) => activateWorkflow.mutateAsync(id)}
              onDelete={handleDelete}
            />
          )}

          {/* Recent Runs */}
          {tenantId && (
            <WorkflowRunLogCard tenantId={tenantId} limit={10} />
          )}
        </>
      )}
    </div>
  );
}

function WorkflowSection({
  title,
  description,
  workflows,
  tenantId,
  onActivate,
  onPause,
  onDelete,
}: {
  title: string;
  description: string;
  workflows: Workflow[];
  tenantId: string;
  onActivate?: (id: string) => void;
  onPause?: (id: string) => void;
  onDelete: (id: string) => void;
}) {
  return (
    <Card>
      <CardHeader className="pb-3">
        <CardTitle className="text-lg">{title}</CardTitle>
        <CardDescription>{description}</CardDescription>
      </CardHeader>
      <CardContent className="space-y-3">
        {workflows.map((workflow) => {
          const triggerMeta = TRIGGER_METADATA[workflow.trigger];
          
          return (
            <div
              key={workflow.id}
              className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-4 rounded-lg border bg-card hover:bg-muted/50 transition-colors"
            >
              <div className="flex items-center gap-4">
                <div className="text-2xl">{triggerMeta?.icon || "⚡"}</div>
                <div>
                  <div className="font-medium">{workflow.name}</div>
                  <div className="text-sm text-muted-foreground">
                    Trigger: {triggerMeta?.label || workflow.trigger}
                    {workflow.is_default && (
                      <Badge variant="outline" className="ml-2">Default</Badge>
                    )}
                  </div>
                </div>
              </div>
              
              <div className="flex items-center gap-2 flex-wrap">
                {/* Test Trigger Button */}
                <TestTriggerButton
                  tenantId={tenantId}
                  workflowId={workflow.id}
                  trigger={workflow.trigger}
                  disabled={workflow.status !== "active"}
                />
                
                {onActivate && workflow.status !== "active" && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => onActivate(workflow.id)}
                  >
                    <Play className="h-4 w-4 mr-1" />
                    Activate
                  </Button>
                )}
                {onPause && workflow.status === "active" && (
                  <Button
                    variant="ghost"
                    size="sm"
                    onClick={() => onPause(workflow.id)}
                  >
                    <Pause className="h-4 w-4 mr-1" />
                    Pause
                  </Button>
                )}
                <Button variant="ghost" size="sm" asChild>
                  <Link to={`/app/workflows/${workflow.id}`}>
                    <Settings className="h-4 w-4 mr-1" />
                    Edit
                  </Link>
                </Button>
                <Button variant="ghost" size="sm" asChild>
                  <Link to={`/app/workflows/${workflow.id}/runs`}>
                    <History className="h-4 w-4 mr-1" />
                    Runs
                  </Link>
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="text-destructive hover:text-destructive"
                  onClick={() => onDelete(workflow.id)}
                >
                  <Trash2 className="h-4 w-4" />
                </Button>
              </div>
            </div>
          );
        })}
      </CardContent>
    </Card>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useAIContextSnapshots, runGoldenPathTests, type GoldenPathTestResult } from "@/hooks/useAIContextSnapshots";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { supabase } from "@/integrations/supabase/client";
import { 
  RefreshCw, 
  Copy, 
  CheckCircle2, 
  XCircle, 
  AlertTriangle,
  Phone,
  MessageSquare,
  Monitor,
  Clock,
  ChevronDown,
  ChevronUp,
  Zap,
  List,
  TrendingUp,
} from "lucide-react";
import { toast } from "@/hooks/use-toast";
import { format } from "date-fns";

type ChannelFilter = "all" | "voice" | "sms" | "browser_test";

export default function AIContextInspectorPage() {
  const { tenant, isSuperAdmin } = useAuth();
  const tenantId = tenant?.id ?? null;
  const { snapshots, loading, refetch } = useAIContextSnapshots(tenantId);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [testResults, setTestResults] = useState<GoldenPathTestResult[] | null>(null);
  const [channelFilter, setChannelFilter] = useState<ChannelFilter>("all");
  const [generatingContext, setGeneratingContext] = useState(false);

  // Only accessible to admins/super-admins in dev
  if (!tenantId && !isSuperAdmin) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <p className="text-muted-foreground">No tenant context available</p>
      </div>
    );
  }

  // Filter snapshots by channel
  const filteredSnapshots = channelFilter === "all" 
    ? snapshots 
    : snapshots.filter(s => s.channel === channelFilter);

  // Calculate summary metrics
  const metrics = {
    total: snapshots.length,
    voice: snapshots.filter(s => s.channel === "voice").length,
    sms: snapshots.filter(s => s.channel === "sms").length,
    browserTest: snapshots.filter(s => s.channel === "browser_test").length,
    complete: snapshots.filter(s => !s.missing_sections || s.missing_sections.length === 0).length,
    withGaps: snapshots.filter(s => s.missing_sections && s.missing_sections.length > 0).length,
  };

  const getChannelIcon = (channel: string) => {
    switch (channel) {
      case "voice": return <Phone className="h-4 w-4" />;
      case "sms": return <MessageSquare className="h-4 w-4" />;
      case "browser_test": return <Monitor className="h-4 w-4" />;
      default: return <Clock className="h-4 w-4" />;
    }
  };

  const getChannelColor = (channel: string) => {
    switch (channel) {
      case "voice": return "bg-primary/10 text-primary";
      case "sms": return "bg-accent/50 text-accent-foreground";
      case "browser_test": return "bg-secondary text-secondary-foreground";
      default: return "bg-muted text-muted-foreground";
    }
  };

  const handleCopyContext = (context: Record<string, unknown>) => {
    navigator.clipboard.writeText(JSON.stringify(context, null, 2));
    toast({ title: "Copied to clipboard" });
  };

  const handleRunTests = (context: Record<string, unknown>) => {
    const results = runGoldenPathTests(context);
    setTestResults(results);
    
    const passCount = results.filter(r => r.passed).length;
    const failCount = results.filter(r => !r.passed).length;
    
    toast({
      title: `Golden Path: ${passCount}/${results.length} passed`,
      description: failCount > 0 ? `${failCount} tests need attention` : "All tests passed!",
      variant: failCount > 0 ? "destructive" : "default",
    });
  };

  const handleGenerateTestContext = async () => {
    if (!tenantId) {
      toast({ title: "No tenant selected", variant: "destructive" });
      return;
    }
    
    setGeneratingContext(true);
    try {
      // Call the get-business-context edge function directly to generate a test snapshot
      const { data, error } = await supabase.functions.invoke("get-business-context", {
        body: { tenantId },
      });
      
      if (error) {
        throw new Error(error.message);
      }
      
      toast({ 
        title: "Context generated successfully", 
        description: "Refresh to see the new snapshot" 
      });
      
      // Refetch snapshots to show the new one
      setTimeout(() => refetch(), 500);
    } catch (err) {
      console.error("Failed to generate test context:", err);
      toast({ 
        title: "Failed to generate context", 
        description: err instanceof Error ? err.message : "Unknown error",
        variant: "destructive" 
      });
    } finally {
      setGeneratingContext(false);
    }
  };

  return (
    <div className="min-h-screen bg-background p-4 md:p-8">
      <div className="max-w-6xl mx-auto space-y-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold">AI Context Inspector</h1>
            <p className="text-muted-foreground">Debug what the AI sees during calls and SMS</p>
          </div>
          <div className="flex gap-2">
            <Button 
              onClick={handleGenerateTestContext} 
              variant="outline" 
              size="sm" 
              disabled={generatingContext || !tenantId}
            >
              <Zap className={`h-4 w-4 mr-2 ${generatingContext ? "animate-pulse" : ""}`} />
              {generatingContext ? "Generating..." : "Generate Test Context"}
            </Button>
            <Button onClick={refetch} variant="outline" size="sm" disabled={loading}>
              <RefreshCw className={`h-4 w-4 mr-2 ${loading ? "animate-spin" : ""}`} />
              Refresh
            </Button>
          </div>
        </div>

        {/* Summary Metrics */}
        <div className="grid grid-cols-2 md:grid-cols-6 gap-3">
          <Card className="p-3">
            <div className="flex items-center gap-2">
              <List className="h-4 w-4 text-muted-foreground" />
              <div>
                <p className="text-2xl font-bold">{metrics.total}</p>
                <p className="text-xs text-muted-foreground">Total Snapshots</p>
              </div>
            </div>
          </Card>
          <Card className="p-3">
            <div className="flex items-center gap-2">
              <Phone className="h-4 w-4 text-primary" />
              <div>
                <p className="text-2xl font-bold">{metrics.voice}</p>
                <p className="text-xs text-muted-foreground">Voice Calls</p>
              </div>
            </div>
          </Card>
          <Card className="p-3">
            <div className="flex items-center gap-2">
              <MessageSquare className="h-4 w-4 text-accent-foreground" />
              <div>
                <p className="text-2xl font-bold">{metrics.sms}</p>
                <p className="text-xs text-muted-foreground">SMS</p>
              </div>
            </div>
          </Card>
          <Card className="p-3">
            <div className="flex items-center gap-2">
              <Monitor className="h-4 w-4 text-secondary-foreground" />
              <div>
                <p className="text-2xl font-bold">{metrics.browserTest}</p>
                <p className="text-xs text-muted-foreground">Browser Tests</p>
              </div>
            </div>
          </Card>
          <Card className="p-3">
            <div className="flex items-center gap-2">
              <CheckCircle2 className="h-4 w-4 text-primary" />
              <div>
                <p className="text-2xl font-bold">{metrics.complete}</p>
                <p className="text-xs text-muted-foreground">Complete</p>
              </div>
            </div>
          </Card>
          <Card className="p-3">
            <div className="flex items-center gap-2">
              <AlertTriangle className="h-4 w-4 text-destructive" />
              <div>
                <p className="text-2xl font-bold">{metrics.withGaps}</p>
                <p className="text-xs text-muted-foreground">With Gaps</p>
              </div>
            </div>
          </Card>
        </div>

        <Tabs defaultValue="snapshots">
          <TabsList>
            <TabsTrigger value="snapshots">Context Snapshots</TabsTrigger>
            <TabsTrigger value="tests">Golden Path Tests</TabsTrigger>
          </TabsList>

          <TabsContent value="snapshots" className="mt-4 space-y-4">
            {/* Channel Filter */}
            <div className="flex gap-2">
              <Button 
                variant={channelFilter === "all" ? "default" : "outline"} 
                size="sm"
                onClick={() => setChannelFilter("all")}
              >
                All ({metrics.total})
              </Button>
              <Button 
                variant={channelFilter === "voice" ? "default" : "outline"} 
                size="sm"
                onClick={() => setChannelFilter("voice")}
              >
                <Phone className="h-3 w-3 mr-1" />
                Voice ({metrics.voice})
              </Button>
              <Button 
                variant={channelFilter === "sms" ? "default" : "outline"} 
                size="sm"
                onClick={() => setChannelFilter("sms")}
              >
                <MessageSquare className="h-3 w-3 mr-1" />
                SMS ({metrics.sms})
              </Button>
              <Button 
                variant={channelFilter === "browser_test" ? "default" : "outline"} 
                size="sm"
                onClick={() => setChannelFilter("browser_test")}
              >
                <Monitor className="h-3 w-3 mr-1" />
                Browser ({metrics.browserTest})
              </Button>
            </div>

            {filteredSnapshots.length === 0 ? (
              <Card>
                <CardContent className="py-8 text-center text-muted-foreground">
                  {channelFilter === "all" 
                    ? "No context snapshots recorded yet. Make a test call or send an SMS to see data here."
                    : `No ${channelFilter.replace("_", " ")} snapshots found.`
                  }
                </CardContent>
              </Card>
            ) : (
              <div className="space-y-3">
                {filteredSnapshots.map((snapshot) => {
                  const isExpanded = expandedId === snapshot.id;
                  const missingSections = snapshot.missing_sections || [];
                  const contextJson = snapshot.context_json as Record<string, unknown>;
                  
                  // Extract key info from context for display
                  const contextTenant = contextJson?.tenant as Record<string, unknown> | undefined;
                  const contextOfferings = contextJson?.offerings as Record<string, unknown> | undefined;
                  const businessName = contextTenant?.business_name as string || "Unknown";
                  const businessMode = contextTenant?.business_mode as string || "general";
                  const servicesCount = Array.isArray(contextOfferings?.services) ? (contextOfferings.services as unknown[]).length : 0;
                  const menuCount = Array.isArray(contextOfferings?.menu) ? (contextOfferings.menu as unknown[]).length : 0;
                  
                  return (
                    <Card key={snapshot.id} className="overflow-hidden">
                      <div 
                        className="flex items-center justify-between p-4 cursor-pointer hover:bg-muted/50 transition-colors"
                        onClick={() => setExpandedId(isExpanded ? null : snapshot.id)}
                      >
                        <div className="flex items-center gap-4">
                          <Badge className={getChannelColor(snapshot.channel)}>
                            {getChannelIcon(snapshot.channel)}
                            <span className="ml-1.5 capitalize">{snapshot.channel.replace("_", " ")}</span>
                          </Badge>
                          
                          <div>
                            <p className="font-medium text-sm">
                              {businessName} <span className="text-muted-foreground">({businessMode})</span>
                            </p>
                            <p className="text-xs text-muted-foreground">
                              {format(new Date(snapshot.created_at), "MMM d, h:mm:ss a")}
                              {servicesCount > 0 && ` • ${servicesCount} services`}
                              {menuCount > 0 && ` • ${menuCount} menu items`}
                            </p>
                          </div>
                        </div>

                        <div className="flex items-center gap-3">
                          {missingSections.length > 0 ? (
                            <Badge variant="outline" className="border-destructive/50 text-destructive">
                              <AlertTriangle className="h-3 w-3 mr-1" />
                              {missingSections.length} gaps
                            </Badge>
                          ) : (
                            <Badge variant="outline" className="border-primary/50 text-primary">
                              <CheckCircle2 className="h-3 w-3 mr-1" />
                              Complete
                            </Badge>
                          )}
                          
                          {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
                        </div>
                      </div>

                      {isExpanded && (
                        <CardContent className="border-t pt-4 space-y-4">
                          {missingSections.length > 0 && (
                            <div className="flex flex-wrap gap-2">
                              <span className="text-sm text-muted-foreground">Missing:</span>
                              {missingSections.map((section) => (
                                <Badge key={section} variant="secondary">
                                  {section}
                                </Badge>
                              ))}
                            </div>
                          )}

                          {/* Quick Summary of What AI Can See */}
                          <div className="grid grid-cols-2 md:grid-cols-6 gap-2 text-sm">
                            <div className="p-2 rounded bg-muted/50">
                              <span className="text-muted-foreground">Services:</span>
                              <span className="ml-1 font-medium">{servicesCount}</span>
                            </div>
                            <div className="p-2 rounded bg-muted/50">
                              <span className="text-muted-foreground">Menu:</span>
                              <span className="ml-1 font-medium">{menuCount}</span>
                            </div>
                            <div className="p-2 rounded bg-muted/50">
                              <span className="text-muted-foreground">Menu Summary:</span>
                              <span className="ml-1 font-medium">
                                {typeof contextOfferings?.menu_summary === "string" 
                                  ? `${(contextOfferings.menu_summary as string).length} chars` 
                                  : "0 chars"}
                              </span>
                            </div>
                            <div className="p-2 rounded bg-muted/50">
                              <span className="text-muted-foreground">FAQs:</span>
                              <span className="ml-1 font-medium">
                                {Array.isArray((contextJson?.knowledge as Record<string, unknown>)?.faqs) 
                                  ? ((contextJson?.knowledge as Record<string, unknown>)?.faqs as unknown[]).length 
                                  : 0}
                              </span>
                            </div>
                            <div className="p-2 rounded bg-muted/50">
                              <span className="text-muted-foreground">Hours Today:</span>
                              <span className="ml-1 font-medium text-xs">
                                {String(contextTenant?.hours_today || "Not set").slice(0, 20)}
                              </span>
                            </div>
                            <div className="p-2 rounded bg-muted/50">
                              <span className="text-muted-foreground">Mode:</span>
                              <span className="ml-1 font-medium capitalize">{businessMode}</span>
                            </div>
                          </div>
                          
                          {/* Debug Flags (context_has_*) */}
                          <div className="flex flex-wrap gap-2">
                            <Badge variant={contextTenant?.hours_today ? "default" : "secondary"}>
                              {contextTenant?.hours_today ? <CheckCircle2 className="h-3 w-3 mr-1" /> : <XCircle className="h-3 w-3 mr-1" />}
                              context_has_hours: {contextTenant?.hours_today ? "true" : "false"}
                            </Badge>
                            <Badge variant={menuCount > 0 ? "default" : "secondary"}>
                              {menuCount > 0 ? <CheckCircle2 className="h-3 w-3 mr-1" /> : <XCircle className="h-3 w-3 mr-1" />}
                              context_has_menu: {menuCount > 0 ? "true" : "false"}
                            </Badge>
                            <Badge variant={servicesCount > 0 ? "default" : "secondary"}>
                              {servicesCount > 0 ? <CheckCircle2 className="h-3 w-3 mr-1" /> : <XCircle className="h-3 w-3 mr-1" />}
                              context_has_services: {servicesCount > 0 ? "true" : "false"}
                            </Badge>
                            {/* Show menu_summary length badge for food mode */}
                            {businessMode === "food" && (
                              <Badge variant={typeof contextOfferings?.menu_summary === "string" && (contextOfferings.menu_summary as string).length > 0 ? "default" : "destructive"}>
                                menu_summary: {typeof contextOfferings?.menu_summary === "string" ? `${(contextOfferings.menu_summary as string).length}/1500 chars` : "0 chars"}
                              </Badge>
                            )}
                          </div>
                          
                          {/* Missing Sections Warning */}
                          {missingSections.length > 0 && (
                            <div className="p-2 rounded border border-destructive/30 bg-destructive/5">
                              <span className="text-sm font-medium text-destructive">Missing Sections: </span>
                              <span className="text-sm">{missingSections.join(", ")}</span>
                            </div>
                          )}

                          {/* Dynamic Variables (what was sent to ElevenLabs) */}
                          {snapshot.dynamic_variables_json && Object.keys(snapshot.dynamic_variables_json).length > 0 && (
                            <div className="space-y-2">
                              <h4 className="text-sm font-medium flex items-center gap-2">
                                <Zap className="h-4 w-4 text-primary" />
                                Dynamic Variables Sent to AI
                              </h4>
                              <div className="grid grid-cols-1 md:grid-cols-2 gap-2 text-xs">
                                {Object.entries(snapshot.dynamic_variables_json).map(([key, value]) => {
                                  const isLong = typeof value === "string" && value.length > 100;
                                  const displayValue = isLong ? value.slice(0, 100) + "..." : value;
                                  const hasValue = value && value !== "" && value !== "false";
                                  
                                  return (
                                    <div 
                                      key={key} 
                                      className={`p-2 rounded border ${hasValue ? "bg-primary/5 border-primary/20" : "bg-muted/50 border-muted"}`}
                                    >
                                      <span className="font-mono text-muted-foreground">{key}:</span>
                                      <span className={`ml-1 ${hasValue ? "text-foreground" : "text-muted-foreground"}`}>
                                        {displayValue || "(empty)"}
                                      </span>
                                      {isLong && (
                                        <Badge variant="outline" className="ml-1 text-xs">
                                          {value.length} chars
                                        </Badge>
                                      )}
                                    </div>
                                  );
                                })}
                              </div>
                            </div>
                          )}

                          <div className="flex gap-2">
                            <Button 
                              size="sm" 
                              variant="outline"
                              onClick={(e) => {
                                e.stopPropagation();
                                handleCopyContext(snapshot.context_json);
                              }}
                            >
                              <Copy className="h-4 w-4 mr-2" />
                              Copy Context JSON
                            </Button>
                            {snapshot.dynamic_variables_json && (
                              <Button 
                                size="sm" 
                                variant="outline"
                                onClick={(e) => {
                                  e.stopPropagation();
                                  handleCopyContext(snapshot.dynamic_variables_json as Record<string, unknown>);
                                }}
                              >
                                <Copy className="h-4 w-4 mr-2" />
                                Copy Dynamic Vars
                              </Button>
                            )}
                            <Button 
                              size="sm" 
                              variant="outline"
                              onClick={(e) => {
                                e.stopPropagation();
                                handleRunTests(snapshot.context_json);
                              }}
                            >
                              <CheckCircle2 className="h-4 w-4 mr-2" />
                              Run Tests
                            </Button>
                          </div>

                          <Tabs defaultValue="context" className="w-full">
                            <TabsList className="grid w-full grid-cols-2">
                              <TabsTrigger value="context">context_json</TabsTrigger>
                              <TabsTrigger value="dynamic_vars">dynamic_variables_json</TabsTrigger>
                            </TabsList>
                            <TabsContent value="context">
                              <ScrollArea className="h-[400px] rounded-md border bg-muted/30 p-4">
                                <pre className="text-xs font-mono whitespace-pre-wrap">
                                  {JSON.stringify(snapshot.context_json, null, 2)}
                                </pre>
                              </ScrollArea>
                            </TabsContent>
                            <TabsContent value="dynamic_vars">
                              <ScrollArea className="h-[400px] rounded-md border bg-muted/30 p-4">
                                <pre className="text-xs font-mono whitespace-pre-wrap">
                                  {snapshot.dynamic_variables_json 
                                    ? JSON.stringify(snapshot.dynamic_variables_json, null, 2)
                                    : "(No dynamic variables recorded for this snapshot)"
                                  }
                                </pre>
                              </ScrollArea>
                            </TabsContent>
                          </Tabs>
                        </CardContent>
                      )}
                    </Card>
                  );
                })}
              </div>
            )}
          </TabsContent>

          <TabsContent value="tests" className="mt-4">
            <Card>
              <CardHeader>
                <CardTitle>Golden Path Validation</CardTitle>
                <CardDescription>
                  Run tests against the most recent context to validate data completeness
                </CardDescription>
              </CardHeader>
              <CardContent>
                {snapshots.length > 0 ? (
                  <div className="space-y-4">
                    <Button
                      onClick={() => handleRunTests(snapshots[0].context_json)}
                      className="w-full"
                    >
                      <CheckCircle2 className="h-4 w-4 mr-2" />
                      Run Golden Path Tests on Latest Context
                    </Button>

                    {testResults && (
                      <div className="space-y-3 mt-4">
                        <div className="flex gap-4 text-sm">
                          <span className="text-primary">
                            ✓ {testResults.filter(r => r.passed).length} passed
                          </span>
                          <span className="text-destructive">
                            ✗ {testResults.filter(r => !r.passed).length} failed
                          </span>
                        </div>

                        {testResults.map((result, idx) => (
                          <div 
                            key={idx}
                            className={`flex items-start gap-3 p-3 rounded-lg border ${
                              result.passed 
                                ? "bg-primary/5 border-primary/20" 
                                : "bg-destructive/5 border-destructive/20"
                            }`}
                          >
                            {result.passed ? (
                              <CheckCircle2 className="h-5 w-5 text-primary shrink-0 mt-0.5" />
                            ) : (
                              <XCircle className="h-5 w-5 text-destructive shrink-0 mt-0.5" />
                            )}
                            <div>
                              <p className="font-medium text-sm">
                                [{result.mode}] {result.testName}
                              </p>
                              <p className="text-xs text-muted-foreground mt-1">
                                {result.details}
                              </p>
                              {result.missingKeys.length > 0 && (
                                <div className="flex flex-wrap gap-1 mt-2">
                                  {result.missingKeys.map((key) => (
                                    <Badge key={key} variant="outline" className="text-xs">
                                      {key}
                                    </Badge>
                                  ))}
                                </div>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ) : (
                  <p className="text-muted-foreground text-center py-8">
                    No context snapshots available. Make a test call or send an SMS first.
                  </p>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  useCalendarConnections,
  useBusyBlocks,
  useAvailableSlots,
  usePlaceHold,
  useConfirmBooking,
} from "@/hooks/useCalendarConnections";
import { format, addDays } from "date-fns";
import {
  Calendar,
  Clock,
  CheckCircle2,
  XCircle,
  RefreshCw,
  Lock,
  CalendarCheck,
  Loader2,
} from "lucide-react";

export default function AvailabilityDebugPage() {
  const { tenant } = useAuth();
  const { connections, isLoading: connectionsLoading, refetch: refetchConnections } = useCalendarConnections();
  
  const [dateRange] = useState({
    start: new Date(),
    end: addDays(new Date(), 7),
  });
  
  const { blocks, isLoading: blocksLoading, refetch: refetchBlocks, createBlock, deleteBlock } = useBusyBlocks(dateRange);
  
  const businessHours = tenant?.hours_json as unknown as Record<string, { open: string; close: string; closed?: boolean }> | undefined;
  
  const { data: slots, isLoading: slotsLoading, refetch: refetchSlots } = useAvailableSlots({
    startDate: dateRange.start,
    endDate: dateRange.end,
    durationMinutes: 60,
    bufferMinutes: 15,
    businessHours,
  });

  const placeHold = usePlaceHold();
  const confirmBooking = useConfirmBooking();

  const [testSlot, setTestSlot] = useState<{ start: string; end: string } | null>(null);
  const [holdId, setHoldId] = useState<string | null>(null);

  // Manual block form
  const [manualBlockStart, setManualBlockStart] = useState("");
  const [manualBlockEnd, setManualBlockEnd] = useState("");

  const handlePlaceHold = async () => {
    if (!testSlot) return;
    try {
      const id = await placeHold.mutateAsync({
        start_at: testSlot.start,
        end_at: testSlot.end,
        hold_minutes: 5,
        session_id: `debug-${Date.now()}`,
      });
      setHoldId(id);
    } catch (error) {
      console.error("Hold failed:", error);
    }
  };

  const handleConfirmBooking = async () => {
    if (!holdId) return;
    try {
      await confirmBooking.mutateAsync({
        hold_id: holdId,
        notes: "Created from debug page",
      });
      setHoldId(null);
      setTestSlot(null);
      refetchBlocks();
      refetchSlots();
    } catch (error) {
      console.error("Confirm failed:", error);
    }
  };

  const handleCreateManualBlock = async () => {
    if (!manualBlockStart || !manualBlockEnd) return;
    await createBlock.mutateAsync({
      start_at: manualBlockStart,
      end_at: manualBlockEnd,
      block_type: "manual_busy",
    });
    setManualBlockStart("");
    setManualBlockEnd("");
    refetchSlots();
  };

  const handleRefreshAll = () => {
    refetchConnections();
    refetchBlocks();
    refetchSlots();
  };

  const getBlockTypeBadge = (type: string) => {
    switch (type) {
      case "external_busy":
        return <Badge variant="secondary">External</Badge>;
      case "manual_busy":
        return <Badge variant="outline">Manual</Badge>;
      case "hold":
        return <Badge variant="warning">Hold</Badge>;
      case "confirmed_booking":
        return <Badge variant="success">Booking</Badge>;
      default:
        return <Badge>{type}</Badge>;
    }
  };

  if (!tenant) {
    return (
      <div className="p-8 text-center text-muted-foreground">
        Please log in to view availability debug info.
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 lg:p-8 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold flex items-center gap-2">
            <Calendar className="h-6 w-6 text-primary" />
            Availability Debug
          </h1>
          <p className="text-muted-foreground">
            View busy blocks, available slots, and test booking flow
          </p>
        </div>
        <Button variant="outline" onClick={handleRefreshAll}>
          <RefreshCw className="h-4 w-4 mr-2" />
          Refresh All
        </Button>
      </div>

      {/* Calendar Connections */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg">Calendar Connections</CardTitle>
        </CardHeader>
        <CardContent>
          {connectionsLoading ? (
            <Skeleton className="h-20 w-full" />
          ) : connections.length === 0 ? (
            <p className="text-muted-foreground text-sm">
              No calendar connections configured. Go to Settings → Schedule to connect.
            </p>
          ) : (
            <div className="space-y-2">
              {connections.map((conn) => (
                <div
                  key={conn.id}
                  className="flex items-center justify-between p-3 rounded-lg border"
                >
                  <div className="flex items-center gap-3">
                    <span className="text-xl">
                      {conn.provider === "google" && "📅"}
                      {conn.provider === "microsoft" && "📧"}
                      {conn.provider === "ics" && "🔗"}
                      {conn.provider === "manual" && "✋"}
                    </span>
                    <div>
                      <p className="font-medium">{conn.display_name || conn.provider}</p>
                      <p className="text-xs text-muted-foreground">
                        Last sync: {conn.last_sync_at ? format(new Date(conn.last_sync_at), "PPp") : "Never"}
                      </p>
                    </div>
                  </div>
                  <Badge variant={conn.status === "connected" ? "success" : "secondary"}>
                    {conn.status}
                  </Badge>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      <div className="grid md:grid-cols-2 gap-6">
        {/* Busy Blocks */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center justify-between">
              <span>Busy Blocks</span>
              <Badge variant="outline">{blocks.length}</Badge>
            </CardTitle>
          </CardHeader>
          <CardContent>
            {/* Add Manual Block */}
            <div className="mb-4 p-3 rounded-lg bg-muted/50 space-y-3">
              <p className="text-sm font-medium">Add Manual Block</p>
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <Label className="text-xs">Start</Label>
                  <Input
                    type="datetime-local"
                    value={manualBlockStart}
                    onChange={(e) => setManualBlockStart(e.target.value)}
                    className="text-sm"
                  />
                </div>
                <div>
                  <Label className="text-xs">End</Label>
                  <Input
                    type="datetime-local"
                    value={manualBlockEnd}
                    onChange={(e) => setManualBlockEnd(e.target.value)}
                    className="text-sm"
                  />
                </div>
              </div>
              <Button
                size="sm"
                onClick={handleCreateManualBlock}
                disabled={!manualBlockStart || !manualBlockEnd || createBlock.isPending}
              >
                {createBlock.isPending && <Loader2 className="h-3 w-3 mr-1 animate-spin" />}
                Add Block
              </Button>
            </div>

            {blocksLoading ? (
              <Skeleton className="h-40 w-full" />
            ) : blocks.length === 0 ? (
              <p className="text-muted-foreground text-sm text-center py-4">
                No busy blocks in the selected range.
              </p>
            ) : (
              <div className="max-h-80 overflow-y-auto space-y-2">
                {blocks.map((block) => (
                  <div
                    key={block.id}
                    className="flex items-center justify-between p-2 rounded border text-sm"
                  >
                    <div>
                      <div className="flex items-center gap-2">
                        {getBlockTypeBadge(block.block_type)}
                        {block.expires_at && (
                          <span className="text-xs text-muted-foreground">
                            expires {format(new Date(block.expires_at), "HH:mm")}
                          </span>
                        )}
                      </div>
                      <p className="text-xs text-muted-foreground mt-1">
                        {format(new Date(block.start_at), "MMM d HH:mm")} - {format(new Date(block.end_at), "HH:mm")}
                      </p>
                    </div>
                    {block.block_type !== "confirmed_booking" && (
                      <Button
                        variant="ghost"
                        size="icon"
                        onClick={() => deleteBlock.mutate(block.id)}
                      >
                        <XCircle className="h-4 w-4 text-muted-foreground" />
                      </Button>
                    )}
                  </div>
                ))}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Available Slots */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center justify-between">
              <span>Available Slots</span>
              <Badge variant="outline">{slots?.length || 0}</Badge>
            </CardTitle>
          </CardHeader>
          <CardContent>
            {!businessHours ? (
              <p className="text-muted-foreground text-sm text-center py-4">
                Configure business hours in Settings to see available slots.
              </p>
            ) : slotsLoading ? (
              <Skeleton className="h-40 w-full" />
            ) : !slots || slots.length === 0 ? (
              <p className="text-muted-foreground text-sm text-center py-4">
                No available slots in the selected range.
              </p>
            ) : (
              <div className="max-h-80 overflow-y-auto space-y-1">
                {slots.slice(0, 20).map((slot, idx) => (
                  <div
                    key={idx}
                    className={`flex items-center justify-between p-2 rounded border text-sm cursor-pointer transition-colors ${
                      testSlot?.start === slot.slot_start
                        ? "border-primary bg-primary/5"
                        : "hover:bg-muted/50"
                    }`}
                    onClick={() => setTestSlot({ start: slot.slot_start, end: slot.slot_end })}
                  >
                    <div className="flex items-center gap-2">
                      <Clock className="h-3 w-3 text-muted-foreground" />
                      <span>
                        {format(new Date(slot.slot_start), "EEE, MMM d")} at{" "}
                        {format(new Date(slot.slot_start), "h:mm a")}
                      </span>
                    </div>
                    {testSlot?.start === slot.slot_start && (
                      <CheckCircle2 className="h-4 w-4 text-primary" />
                    )}
                  </div>
                ))}
                {slots.length > 20 && (
                  <p className="text-xs text-muted-foreground text-center py-2">
                    + {slots.length - 20} more slots
                  </p>
                )}
              </div>
            )}
          </CardContent>
        </Card>
      </div>

      {/* Test Booking Flow */}
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <CalendarCheck className="h-5 w-5" />
            Test Booking Flow
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap items-center gap-4">
            <div className="flex-1 min-w-[200px]">
              {testSlot ? (
                <p className="text-sm">
                  Selected: <strong>{format(new Date(testSlot.start), "PPp")}</strong>
                </p>
              ) : (
                <p className="text-sm text-muted-foreground">
                  Click a slot above to select it for testing
                </p>
              )}
            </div>

            <div className="flex gap-2">
              <Button
                variant="outline"
                onClick={handlePlaceHold}
                disabled={!testSlot || placeHold.isPending || !!holdId}
              >
                {placeHold.isPending ? (
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                ) : (
                  <Lock className="h-4 w-4 mr-2" />
                )}
                1. Place Hold
              </Button>

              <Button
                onClick={handleConfirmBooking}
                disabled={!holdId || confirmBooking.isPending}
              >
                {confirmBooking.isPending ? (
                  <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                ) : (
                  <CheckCircle2 className="h-4 w-4 mr-2" />
                )}
                2. Confirm Booking
              </Button>
            </div>
          </div>

          {holdId && (
            <div className="mt-4 p-3 rounded-lg bg-amber-500/10 border border-amber-500/20">
              <p className="text-sm">
                <strong>Hold placed!</strong> ID: <code className="text-xs">{holdId}</code>
                <br />
                <span className="text-muted-foreground">
                  This hold will expire in 5 minutes. Click "Confirm Booking" to convert it.
                </span>
              </p>
            </div>
          )}
        </CardContent>
      </Card>

      {/* Business Hours Preview */}
      {businessHours && (
        <Card>
          <CardHeader>
            <CardTitle className="text-lg">Business Hours (from settings)</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-2">
              {Object.entries(businessHours).map(([day, hours]) => (
                <div key={day} className="p-2 rounded border text-center">
                  <p className="text-xs font-medium capitalize">{day}</p>
                  {hours.closed ? (
                    <p className="text-xs text-muted-foreground">Closed</p>
                  ) : (
                    <p className="text-xs text-muted-foreground">
                      {hours.open} - {hours.close}
                    </p>
                  )}
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState } from "react";
import { useAuth } from "@/contexts/AuthContext";
import { useLatestContextSnapshot, useLatestDynamicVariables } from "@/hooks/useLatestContextSnapshot";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Separator } from "@/components/ui/separator";
import { supabase } from "@/integrations/supabase/client";
import { JsonViewer } from "@/components/debug/JsonViewer";
import { PreviewCard, PreviewSource } from "@/components/debug/PreviewCard";
import { ContextWarningsPanel } from "@/components/debug/ContextWarningsPanel";
import { ServiceAreaPreview } from "@/components/debug/ServiceAreaPreview";
import {
  RefreshCw,
  Zap,
  Database,
  Eye,
  AlertTriangle,
  Clock,
  MapPin,
  DollarSign,
  FileText,
  Timer,
} from "lucide-react";
import { toast } from "@/hooks/use-toast";
import { format } from "date-fns";

export default function ContextDebuggerPage() {
  const { tenant, isSuperAdmin } = useAuth();
  const tenantId = tenant?.id ?? null;

  const {
    data: snapshot,
    isLoading: snapshotLoading,
    refetch: refetchSnapshot,
  } = useLatestContextSnapshot(tenantId);

  const {
    data: dynamicVars,
    isLoading: varsLoading,
    refetch: refetchVars,
  } = useLatestDynamicVariables(tenantId);

  const [generating, setGenerating] = useState(false);

  // Auth guard
  if (!tenantId && !isSuperAdmin) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <Card className="w-96">
          <CardContent className="pt-6 text-center">
            <AlertTriangle className="h-12 w-12 text-destructive mx-auto mb-4" />
            <p className="text-lg font-medium">Access Denied</p>
            <p className="text-sm text-muted-foreground mt-2">
              You must be logged in as a business owner to access this page.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  const handleRefresh = () => {
    refetchSnapshot();
    refetchVars();
  };

  const handleGenerateSnapshot = async () => {
    if (!tenantId) return;
    setGenerating(true);
    try {
      const { error } = await supabase.functions.invoke("get-business-context", {
        body: { tenantId },
      });
      if (error) throw error;
      toast({ title: "Context snapshot generated" });
      setTimeout(handleRefresh, 500);
    } catch (err) {
      console.error("Failed to generate context:", err);
      toast({
        title: "Failed to generate context",
        description: err instanceof Error ? err.message : "Unknown error",
        variant: "destructive",
      });
    } finally {
      setGenerating(false);
    }
  };

  // Extract preview values - prioritize dynamic variables, then snapshot
  const getPreviewValue = (
    varKey: string,
    snapshotPath?: string[]
  ): { value: string | null; source: PreviewSource } => {
    // First check dynamic variables
    if (dynamicVars?.variables && dynamicVars.variables[varKey]) {
      return { value: dynamicVars.variables[varKey], source: "variables" };
    }

    // Fall back to snapshot context
    if (snapshot?.context_json && snapshotPath) {
      let val: unknown = snapshot.context_json;
      for (const key of snapshotPath) {
        if (val && typeof val === "object") {
          val = (val as Record<string, unknown>)[key];
        } else {
          val = undefined;
          break;
        }
      }
      if (typeof val === "string" && val.trim()) {
        return { value: val, source: "snapshot" };
      }
    }

    return { value: null, source: "missing" };
  };

  // Get preview values for the 5 key summaries
  const locationSummary = getPreviewValue("address", ["tenant", "address"]);
  const serviceAreaSummary = getPreviewValue("service_area_description", ["tenant", "service_area"]);
  const servicesPricing = getPreviewValue("services_pricing", ["offerings", "services_pricing"]);
  const policiesSummary = getPreviewValue("policies_summary", ["policies"]);
  const etaRulesSummary = getPreviewValue("eta_rules_summary");

  // Build warnings list
  const buildWarnings = () => {
    const tenant_ctx = snapshot?.context_json?.tenant as Record<string, unknown> | undefined;
    const vars = dynamicVars?.variables;

    return [
      {
        id: "business_name",
        label: "Business Name",
        isMissing: !(vars?.business_name || tenant_ctx?.business_name),
        deepLink: "/app/business-brain",
        deepLinkLabel: "Edit Profile",
      },
      {
        id: "address",
        label: "Business Address",
        isMissing: !(vars?.address || tenant_ctx?.address),
        deepLink: "/app/business-brain",
        deepLinkLabel: "Add Address",
      },
      {
        id: "service_area",
        label: "Service Area",
        isMissing: !(vars?.service_area_description || tenant_ctx?.service_area),
        deepLink: "/app/business-brain",
        deepLinkLabel: "Configure",
      },
      {
        id: "services_pricing",
        label: "Services & Pricing",
        isMissing: !(vars?.services_pricing),
        deepLink: "/app/business-brain",
        deepLinkLabel: "Add Services",
      },
      {
        id: "policies",
        label: "Business Policies",
        isMissing: !(vars?.policies_summary),
        deepLink: "/app/business-brain",
        deepLinkLabel: "Add Policies",
      },
      {
        id: "dynamic_vars",
        label: "Dynamic Variables Payload",
        isMissing: !dynamicVars,
        deepLink: "/app/simulator",
        deepLinkLabel: "Run Test Call",
      },
    ];
  };

  const isLoading = snapshotLoading || varsLoading;

  return (
    <div className="min-h-screen bg-background p-4 md:p-8">
      <div className="max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold">Context Debugger</h1>
            <p className="text-muted-foreground">
              See exactly what the AI sees and what gets sent to the voice agent.
            </p>
          </div>
          <div className="flex gap-2">
            <Button
              onClick={handleGenerateSnapshot}
              variant="outline"
              size="sm"
              disabled={generating || !tenantId}
            >
              <Zap className={`h-4 w-4 mr-2 ${generating ? "animate-pulse" : ""}`} />
              {generating ? "Generating..." : "Generate Snapshot"}
            </Button>
            <Button onClick={handleRefresh} variant="outline" size="sm" disabled={isLoading}>
              <RefreshCw className={`h-4 w-4 mr-2 ${isLoading ? "animate-spin" : ""}`} />
              Refresh
            </Button>
          </div>
        </div>

        {/* Main Content - Two column on desktop */}
        <div className="grid gap-6 lg:grid-cols-2">
          {/* Left Column: Raw Data */}
          <div className="space-y-6">
            {/* Section 1: Latest AI Context Snapshot */}
            <Card>
              <CardHeader>
                <CardTitle className="text-base flex items-center gap-2">
                  <Database className="h-5 w-5" />
                  Latest AI Context Snapshot
                </CardTitle>
                <CardDescription>
                  Full business context assembled for AI conversations
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                {snapshot ? (
                  <>
                    <div className="flex items-center gap-4 text-sm text-muted-foreground">
                      <div className="flex items-center gap-1.5">
                        <Clock className="h-4 w-4" />
                        {format(new Date(snapshot.created_at), "MMM d, h:mm:ss a")}
                      </div>
                      <Badge variant="outline">{snapshot.channel}</Badge>
                      {snapshot.missing_sections.length > 0 && (
                        <Badge variant="destructive" className="gap-1">
                          <AlertTriangle className="h-3 w-3" />
                          {snapshot.missing_sections.length} gaps
                        </Badge>
                      )}
                    </div>
                    <JsonViewer
                      data={snapshot.context_json}
                      title="context_json"
                      maxHeight="350px"
                      showDownload
                      downloadFilename={`context-${snapshot.id}.json`}
                    />
                  </>
                ) : (
                  <div className="text-center py-8 text-muted-foreground">
                    <Database className="h-10 w-10 mx-auto mb-3 opacity-50" />
                    <p>No snapshots yet.</p>
                    <Button
                      variant="link"
                      onClick={handleGenerateSnapshot}
                      disabled={generating}
                      className="mt-2"
                    >
                      Generate snapshot
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>

            {/* Section 2: Latest Variables Sent to ElevenLabs */}
            <Card>
              <CardHeader>
                <CardTitle className="text-base flex items-center gap-2">
                  <Zap className="h-5 w-5" />
                  Latest Variables Sent to ElevenLabs
                </CardTitle>
                <CardDescription>
                  The exact payload sent during voice sessions
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-4">
                {dynamicVars ? (
                  <>
                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                      <Clock className="h-4 w-4" />
                      {format(new Date(dynamicVars.timestamp), "MMM d, h:mm:ss a")}
                      <Badge variant="secondary" className="text-xs">
                        {Object.keys(dynamicVars.variables).length} variables
                      </Badge>
                    </div>
                    <JsonViewer
                      data={dynamicVars.variables}
                      title="dynamic_variables_json"
                      maxHeight="350px"
                      showDownload
                      downloadFilename="dynamic-variables.json"
                    />
                  </>
                ) : (
                  <div className="text-center py-8">
                    <AlertTriangle className="h-10 w-10 mx-auto mb-3 text-destructive" />
                    <p className="text-muted-foreground">
                      No recent variables payload found.
                    </p>
                    <p className="text-sm text-muted-foreground mt-1">
                      Run a Test Call to generate one.
                    </p>
                    <Button variant="link" asChild className="mt-2">
                      <a href="/app/simulator">Go to Simulator</a>
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>
          </div>

          {/* Right Column: Previews & Warnings */}
          <div className="space-y-6">
            {/* Section 3: AI Preview Blocks */}
            <Card>
              <CardHeader>
                <CardTitle className="text-base flex items-center gap-2">
                  <Eye className="h-5 w-5" />
                  AI Preview Blocks
                </CardTitle>
                <CardDescription>
                  Key summaries the AI uses to answer questions
                </CardDescription>
              </CardHeader>
              <CardContent>
                <Tabs defaultValue="summaries" className="w-full">
                  <TabsList className="grid w-full grid-cols-2">
                    <TabsTrigger value="summaries">Summaries</TabsTrigger>
                    <TabsTrigger value="service-area">Service Area</TabsTrigger>
                  </TabsList>

                  <TabsContent value="summaries" className="mt-4 space-y-4">
                    <PreviewCard
                      title="Location Summary"
                      value={locationSummary.value}
                      source={locationSummary.source}
                      icon={<MapPin className="h-4 w-4" />}
                    />

                    <PreviewCard
                      title="Service Area Summary"
                      value={serviceAreaSummary.value}
                      source={serviceAreaSummary.source}
                      icon={<MapPin className="h-4 w-4" />}
                    />

                    <PreviewCard
                      title="Services & Pricing"
                      value={servicesPricing.value}
                      source={servicesPricing.source}
                      icon={<DollarSign className="h-4 w-4" />}
                    />

                    <PreviewCard
                      title="Policies Summary"
                      value={policiesSummary.value}
                      source={policiesSummary.source}
                      icon={<FileText className="h-4 w-4" />}
                    />

                    <PreviewCard
                      title="ETA Rules Summary"
                      value={etaRulesSummary.value}
                      source={etaRulesSummary.source}
                      icon={<Timer className="h-4 w-4" />}
                    />
                  </TabsContent>

                  <TabsContent value="service-area" className="mt-4">
                    <ServiceAreaPreview />
                  </TabsContent>
                </Tabs>
              </CardContent>
            </Card>

            {/* Section 4: Warnings Panel */}
            <ContextWarningsPanel warnings={buildWarnings()} />
          </div>
        </div>
      </div>
    </div>
  );
}

import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { 
  Phone, 
  CheckCircle2, 
  XCircle, 
  AlertTriangle,
  Clock,
  FileJson,
  Loader2,
  ShoppingBag,
  Calendar,
