};

export default function ExtractionDebugPage() {
  const { tenant } = useAuth();
  const [selectedSession, setSelectedSession] = useState<string | null>(null);

  // Fetch last 20 call sessions with extracted data
  const { data: sessions, isLoading: sessionsLoading } = useQuery({
    queryKey: ["extraction-debug-sessions", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("ai_call_sessions")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("started_at", { ascending: false })
        .limit(20);

      if (error) throw error;
      return (data || []) as CallSession[];
    },
    enabled: !!tenant?.id,
    refetchInterval: 10000,
  });

  // Fetch event logs for selected session
  const { data: eventLogs, isLoading: logsLoading } = useQuery({
    queryKey: ["extraction-debug-logs", selectedSession],
    queryFn: async () => {
      if (!selectedSession) return [];
      const { data, error } = await supabase
        .from("ai_event_logs")
        .select("*")
        .eq("session_id", selectedSession)
        .order("created_at", { ascending: true });

      if (error) throw error;
      return (data || []) as EventLog[];
    },
    enabled: !!selectedSession,
  });

  // Fetch derived entities for selected session
  const { data: derivedEntities } = useQuery({
    queryKey: ["extraction-debug-entities", selectedSession],
    queryFn: async () => {
      if (!selectedSession) return [];
      const entities: DerivedEntity[] = [];

      const { data: orders } = await supabase
        .from("food_orders")
        .select("id, order_number, status, created_at")
        .eq("session_id", selectedSession);
      if (orders) {
        entities.push(...orders.map(o => ({
          type: "order" as const,
          id: o.id,
          status: o.status,
          created_at: o.created_at,
          display: o.order_number,
        })));
      }

      const { data: reservations } = await supabase
        .from("reservations")
        .select("id, party_size, reservation_date, status, created_at")
        .eq("session_id", selectedSession);
      if (reservations) {
        entities.push(...reservations.map(r => ({
          type: "reservation" as const,
          id: r.id,
          status: r.status,
          created_at: r.created_at,
          display: `${r.party_size} guests - ${r.reservation_date}`,
        })));
      }

      const { data: bookings } = await supabase
        .from("bookings")
        .select("id, start_at, status, created_at")
        .eq("session_id", selectedSession);
      if (bookings) {
        entities.push(...bookings.map(b => ({
          type: "booking" as const,
          id: b.id,
          status: b.status,
          created_at: b.created_at,
          display: format(new Date(b.start_at), "MMM d, h:mm a"),
        })));
      }

      const { data: jobs } = await supabase
        .from("dispatch_jobs")
        .select("id, job_number, status, created_at")
        .eq("session_id", selectedSession);
      if (jobs) {
        entities.push(...jobs.map(j => ({
          type: "dispatch" as const,
          id: j.id,
          status: j.status,
          created_at: j.created_at,
          display: j.job_number,
        })));
      }

      return entities;
    },
    enabled: !!selectedSession,
  });

  const selectedSessionData = sessions?.find(s => s.id === selectedSession);
  const extractedPayload = selectedSessionData?.extracted_payload as Record<string, unknown> | null;

  // Get raw data collection keys from _meta
  const rawDataCollectionKeys = (extractedPayload?._meta as Record<string, unknown>)?.raw_data_collection_keys as string[] || [];
  const extractionSource = String((extractedPayload?._meta as Record<string, unknown>)?.extraction_source || "unknown");
  const normalizedAt = (extractedPayload?._meta as Record<string, unknown>)?.normalized_at;
  const tenantTimezone = (extractedPayload?._meta as Record<string, unknown>)?.tenant_timezone;

  // Get specific logs for pipeline stages
  const getLogForStage = (stage: string) => eventLogs?.find(l => l.stage === stage);
  const canonicalizedLog = getLogForStage("extraction_canonicalized");
  const normalizedLog = getLogForStage("normalization_applied");
  const extractionNormalizedLog = getLogForStage("extraction_normalized");
  const entityCreatedLog = getLogForStage("derived_entity_created");
  const entitySkippedLog = getLogForStage("derived_entity_skipped");
  const entityFailedLog = getLogForStage("entity_insert_failed");

  // Get routing decision from extraction_normalized log
  const routingData = extractionNormalizedLog?.event_data as Record<string, unknown> | undefined;
  const routingTarget = routingData?.routing_target as string | undefined;
  const routingReason = routingData?.routing_reason as string | undefined;
  const enabledModules = routingData?.enabled_modules as string[] | undefined;

  if (sessionsLoading) {
    return (
      <div className="p-6 flex items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="p-4 md:p-6 lg:p-8 space-y-6">
      <div className="page-header">
        <h1 className="page-title">Extraction Debug</h1>
        <p className="page-subtitle">View call extraction pipeline: Raw → Canonical → Normalized → Entity</p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Sessions List */}
        <Card>
          <CardHeader>
            <CardTitle className="text-lg flex items-center gap-2">
              <Phone className="h-5 w-5" />
              Recent Calls (Last 20)
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <ScrollArea className="h-[600px]">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead>Time</TableHead>
                    <TableHead>Caller</TableHead>
                    <TableHead>Intent</TableHead>
                    <TableHead>Entity</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {sessions?.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={4} className="text-center py-8 text-muted-foreground">
                        No calls found
                      </TableCell>
                    </TableRow>
                  ) : (
                    sessions?.map((session) => {
                      const payload = session.extracted_payload as Record<string, unknown> | null;
                      const intent = payload?.intent as string || "unknown";
                      const hasExtraction = !!payload && Object.keys(payload).length > 0;
                      
                      return (
                        <TableRow 
                          key={session.id}
                          className={cn(
                            "cursor-pointer hover:bg-muted/50",
                            selectedSession === session.id && "bg-muted"
                          )}
                          onClick={() => setSelectedSession(session.id)}
                        >
                          <TableCell className="font-mono text-xs">
                            {format(new Date(session.started_at), "MMM d, HH:mm")}
                          </TableCell>
                          <TableCell className="text-sm">
                            {session.caller_phone || "Unknown"}
                          </TableCell>
                          <TableCell>
                            <Badge className={intentColors[intent] || "bg-muted"}>
                              {intent}
                            </Badge>
                          </TableCell>
                          <TableCell>
                            {hasExtraction ? (
                              <CheckCircle2 className="h-4 w-4 text-green-500" />
                            ) : (
                              <XCircle className="h-4 w-4 text-muted-foreground" />
                            )}
                          </TableCell>
                        </TableRow>
                      );
                    })
                  )}
                </TableBody>
              </Table>
            </ScrollArea>
          </CardContent>
        </Card>

        {/* Selected Session Details - 4-Panel View */}
        <div className="space-y-4">
          {selectedSession && selectedSessionData ? (
            <>
              {/* Quick Summary */}
              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="text-lg flex items-center gap-2">
                    <FileJson className="h-5 w-5" />
                    Call Details
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <div className="grid grid-cols-2 gap-4 text-sm">
                    <div>
                      <p className="text-muted-foreground">Session ID</p>
                      <p className="font-mono text-xs">{selectedSessionData.id.slice(0, 8)}...</p>
                    </div>
                    <div>
                      <p className="text-muted-foreground">Caller</p>
                      <p>{selectedSessionData.caller_phone || "Unknown"}</p>
                    </div>
                    <div>
                      <p className="text-muted-foreground">Intent</p>
                      <Badge className={intentColors[(extractedPayload?.intent as string) || "other"] || "bg-muted"}>
                        {(extractedPayload?.intent as string) || "Unknown"}
                      </Badge>
                    </div>
                    <div>
                      <p className="text-muted-foreground">Outcome</p>
                      <Badge className={outcomeColors[selectedSessionData.outcome || ""] || "bg-muted"}>
                        {selectedSessionData.outcome || "Unknown"}
                      </Badge>
                    </div>
                  </div>
                </CardContent>
              </Card>

              {/* 4-Panel Extraction Pipeline */}
              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="text-lg">Extraction Pipeline</CardTitle>
                </CardHeader>
                <CardContent>
                  <Tabs defaultValue="canonical" className="w-full">
                    <TabsList className="grid w-full grid-cols-4">
                      <TabsTrigger value="raw" className="text-xs">
                        <Database className="h-3 w-3 mr-1" />
                        Raw
                      </TabsTrigger>
                      <TabsTrigger value="canonical" className="text-xs">
                        <FileJson className="h-3 w-3 mr-1" />
                        Canonical
                      </TabsTrigger>
                      <TabsTrigger value="normalized" className="text-xs">
                        <Wand2 className="h-3 w-3 mr-1" />
                        Normalized
                      </TabsTrigger>
                      <TabsTrigger value="entity" className="text-xs">
                        <FileCheck className="h-3 w-3 mr-1" />
                        Entity
                      </TabsTrigger>
                    </TabsList>

                    {/* Raw Data Collection */}
                    <TabsContent value="raw" className="mt-4">
                      <div className="space-y-3">
                        <div className="flex items-center gap-2">
                          <Badge variant="outline" className="text-xs">
                            Source: {extractionSource}
                          </Badge>
                          <Badge variant="outline" className="text-xs">
                            {rawDataCollectionKeys.length} keys
                          </Badge>
                        </div>
                        {rawDataCollectionKeys.length > 0 ? (
                          <ScrollArea className="h-[200px]">
                            <div className="space-y-2">
                              {rawDataCollectionKeys.map((key) => (
                                <div key={key} className="flex items-center gap-2 p-2 bg-muted rounded text-sm">
                                  <span className="font-mono text-xs text-muted-foreground">{key}</span>
                                </div>
                              ))}
                            </div>
                          </ScrollArea>
                        ) : (
                          <div className="flex items-center gap-2 text-muted-foreground py-4">
                            <AlertTriangle className="h-4 w-4" />
                            <span>No raw data collection keys (server-side extraction used)</span>
                          </div>
                        )}
                      </div>
                    </TabsContent>

                    {/* Canonical Payload */}
                    <TabsContent value="canonical" className="mt-4">
                      <div className="space-y-3">
                        <div className="flex flex-wrap gap-2">
                          {extractedPayload?.intent && (
                            <Badge variant="outline" className="bg-primary/10">
                              Intent: {String(extractedPayload.intent)}
                            </Badge>
                          )}
                          {(extractedPayload?.customer as Record<string, unknown>)?.name && (
                            <Badge variant="outline" className="bg-green-500/10 text-green-700">
                              Customer: {String((extractedPayload.customer as Record<string, unknown>).name)}
                            </Badge>
                          )}
                        </div>
                        
                        {/* Show relevant section based on intent */}
                        <ScrollArea className="h-[200px]">
                          <pre className="text-xs bg-muted p-3 rounded overflow-auto">
                            {JSON.stringify(extractedPayload, null, 2)}
                          </pre>
                        </ScrollArea>
                      </div>
                    </TabsContent>

                    {/* Normalized Values */}
                    <TabsContent value="normalized" className="mt-4">
                      <div className="space-y-3">
                        <div className="flex flex-wrap gap-2">
                          {tenantTimezone && (
                            <Badge variant="outline" className="text-xs">
                              Timezone: {String(tenantTimezone)}
                            </Badge>
                          )}
                          {normalizedAt && (
                            <Badge variant="outline" className="text-xs">
                              Normalized: {format(new Date(String(normalizedAt)), "HH:mm:ss")}
                            </Badge>
                          )}
                        </div>

                        {/* Reservation normalization details */}
                        {(extractedPayload?.reservation as Record<string, unknown>) && (
                          <div className="space-y-2">
                            <p className="text-sm font-medium">Reservation Normalization</p>
                            <div className="grid grid-cols-2 gap-2 text-sm">
                              <div className="p-2 bg-muted rounded">
                                <p className="text-xs text-muted-foreground">Original Date</p>
                                <p className="font-mono">
                                  {String((extractedPayload.reservation as Record<string, unknown>).original_date_phrase || "(already ISO)")}
                                </p>
                                <ArrowRight className="h-3 w-3 my-1 text-muted-foreground" />
                                <p className="font-mono text-primary">
                                  {String((extractedPayload.reservation as Record<string, unknown>).date || "null")}
                                </p>
                              </div>
                              <div className="p-2 bg-muted rounded">
                                <p className="text-xs text-muted-foreground">Original Time</p>
                                <p className="font-mono">
                                  {String((extractedPayload.reservation as Record<string, unknown>).original_time_phrase || "(already 24h)")}
                                </p>
                                <ArrowRight className="h-3 w-3 my-1 text-muted-foreground" />
                                <p className="font-mono text-primary">
                                  {String((extractedPayload.reservation as Record<string, unknown>).time || "null")}
                                </p>
                              </div>
                              <div className="p-2 bg-muted rounded col-span-2">
                                <p className="text-xs text-muted-foreground">Party Size</p>
                                <p className="font-mono text-primary">
                                  {String((extractedPayload.reservation as Record<string, unknown>).party_size ?? "null")} 
                                  <span className="text-muted-foreground ml-2">
                                    (type: {typeof (extractedPayload.reservation as Record<string, unknown>).party_size})
                                  </span>
                                </p>
                              </div>
                            </div>
                          </div>
                        )}

                        {/* Show normalization event log data if available */}
                        {normalizedLog?.event_data && (
                          <div className="mt-4">
                            <p className="text-sm font-medium mb-2">Event Log Data</p>
                            <pre className="text-xs bg-muted p-2 rounded overflow-auto">
                              {JSON.stringify(normalizedLog.event_data, null, 2)}
                            </pre>
                          </div>
                        )}
                      </div>
                    </TabsContent>

                    {/* Derived Entity */}
                    <TabsContent value="entity" className="mt-4">
                      <div className="space-y-3">
                        {/* Routing Decision */}
                        {routingData && (
                          <div className="p-3 bg-muted rounded-lg space-y-2">
                            <p className="text-sm font-medium">Routing Decision</p>
                            <div className="grid grid-cols-2 gap-2 text-sm">
                              <div>
                                <p className="text-xs text-muted-foreground">Target Table</p>
                                <Badge className={
                                  routingTarget === "food_orders" ? "bg-blue-500/10 text-blue-700" :
                                  routingTarget === "reservations" ? "bg-purple-500/10 text-purple-700" :
                                  routingTarget === "bookings" ? "bg-green-500/10 text-green-700" :
                                  routingTarget === "dispatch_jobs" ? "bg-orange-500/10 text-orange-700" :
                                  "bg-muted"
                                }>
                                  {routingTarget || "none"}
                                </Badge>
                              </div>
                              <div>
                                <p className="text-xs text-muted-foreground">Intent</p>
                                <Badge className={intentColors[(extractedPayload?.intent as string) || "other"]}>
                                  {(extractedPayload?.intent as string) || "unknown"}
                                </Badge>
                              </div>
                            </div>
                            {routingReason && (
                              <div className="text-xs text-muted-foreground">
                                <p className="font-medium">Reason:</p>
                                <p>{routingReason}</p>
                              </div>
                            )}
                            {enabledModules && enabledModules.length > 0 && (
                              <div className="flex flex-wrap gap-1 mt-2">
                                <span className="text-xs text-muted-foreground">Enabled modules:</span>
                                {enabledModules.map(mod => (
                                  <Badge key={mod} variant="outline" className="text-xs">
                                    {mod}
                                  </Badge>
                                ))}
                              </div>
                            )}
                          </div>
                        )}

                        {derivedEntities && derivedEntities.length > 0 ? (
                          <div className="space-y-2">
                            {derivedEntities.map((entity) => (
                              <div 
                                key={entity.id}
                                className="flex items-center justify-between p-3 bg-green-500/10 rounded-lg border border-green-500/20"
                              >
                                <div className="flex items-center gap-3">
                                  <div className="h-8 w-8 rounded-lg bg-green-500/20 flex items-center justify-center">
                                    {entityIcons[entity.type]}
                                  </div>
                                  <div>
                                    <p className="font-medium capitalize flex items-center gap-2">
                                      {entity.type}
                                      <CheckCircle2 className="h-4 w-4 text-green-500" />
                                    </p>
                                    <p className="text-sm text-muted-foreground">{entity.display}</p>
                                    <p className="text-xs font-mono text-muted-foreground">{entity.id.slice(0, 8)}...</p>
                                  </div>
                                </div>
                                <Badge variant="outline">{entity.status}</Badge>
                              </div>
                            ))}
                          </div>
                        ) : entitySkippedLog ? (
                          <div className="flex items-center gap-2 p-4 bg-muted rounded-lg">
                            <AlertTriangle className="h-5 w-5 text-yellow-500" />
                            <div>
                              <p className="font-medium">Entity Skipped</p>
                              <p className="text-sm text-muted-foreground">
                                {String((entitySkippedLog.event_data as Record<string, unknown>)?.reason || routingReason || "No entity created for this intent")}
                              </p>
                            </div>
                          </div>
                        ) : entityFailedLog ? (
                          <div className="flex items-center gap-2 p-4 bg-destructive/10 rounded-lg">
                            <XCircle className="h-5 w-5 text-destructive" />
                            <div>
                              <p className="font-medium">Entity Insert Failed</p>
                              <p className="text-sm text-muted-foreground">
                                {entityFailedLog.error_message || "Unknown error during entity creation"}
                              </p>
                              <pre className="text-xs mt-2 overflow-auto">
                                {JSON.stringify(entityFailedLog.event_data, null, 2)}
                              </pre>
                            </div>
                          </div>
                        ) : (
                          <div className="flex items-center gap-2 text-muted-foreground py-4">
                            <XCircle className="h-4 w-4" />
                            <span>No derived entities created</span>
                          </div>
                        )}

                        {/* Entity creation log details */}
                        {entityCreatedLog?.event_data && (
                          <div className="mt-4 p-3 bg-muted rounded">
                            <p className="text-sm font-medium mb-2">Entity Creation Log</p>
                            <pre className="text-xs overflow-auto">
                              {JSON.stringify(entityCreatedLog.event_data, null, 2)}
                            </pre>
                          </div>
                        )}
                      </div>
                    </TabsContent>
                  </Tabs>
                </CardContent>
              </Card>

              {/* Event Logs Timeline */}
              <Card>
                <CardHeader className="pb-2">
                  <CardTitle className="text-lg flex items-center gap-2">
                    <Clock className="h-5 w-5" />
                    Event Log Timeline
                  </CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                  {logsLoading ? (
                    <div className="flex justify-center py-8">
                      <Loader2 className="h-6 w-6 animate-spin" />
                    </div>
                  ) : eventLogs && eventLogs.length > 0 ? (
                    <ScrollArea className="h-[200px]">
                      <Table>
                        <TableHeader>
                          <TableRow>
                            <TableHead>Time</TableHead>
                            <TableHead>Stage</TableHead>
                            <TableHead>Status</TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {eventLogs.map((log) => (
                            <TableRow key={log.id}>
                              <TableCell className="font-mono text-xs">
                                {format(new Date(log.created_at), "HH:mm:ss")}
                              </TableCell>
                              <TableCell className="text-sm">
                                <Badge variant="outline" className={
                                  log.stage.includes("canonical") ? "bg-blue-500/10" :
                                  log.stage.includes("normal") ? "bg-purple-500/10" :
                                  log.stage.includes("entity_created") ? "bg-green-500/10" :
                                  log.stage.includes("error") || log.stage.includes("failed") ? "bg-destructive/10" :
                                  ""
                                }>
                                  {log.stage.replace(/_/g, " ")}
                                </Badge>
                              </TableCell>
                              <TableCell>
                                {log.error_message ? (
                                  <Badge variant="destructive" className="text-xs">
                                    Error
                                  </Badge>
                                ) : (
                                  <CheckCircle2 className="h-4 w-4 text-green-500" />
                                )}
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </ScrollArea>
                  ) : (
                    <div className="flex items-center gap-2 text-muted-foreground py-4 px-4">
                      <AlertTriangle className="h-4 w-4" />
                      <span>No event logs found</span>
                    </div>
                  )}
                </CardContent>
              </Card>
            </>
          ) : (
            <Card>
              <CardContent className="py-12 text-center text-muted-foreground">
                <FileJson className="h-12 w-12 mx-auto mb-4 opacity-50" />
                <p>Select a call to view extraction pipeline details</p>
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { supabase } from "@/integrations/supabase/client";
import { useQuery } from "@tanstack/react-query";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { 
  Phone, 
  Webhook, 
  AlertTriangle, 
  CheckCircle, 
  XCircle, 
  RefreshCw,
  ArrowLeft,
  ExternalLink,
  Copy,
  Loader2
} from "lucide-react";
import { format } from "date-fns";
import { useToast } from "@/hooks/use-toast";

// Top 5 failure reasons and fixes
const TROUBLESHOOTING_GUIDE = [
  {
    issue: "No tenant found for number",
    cause: "Twilio 'To' number not in phone_numbers table",
    fix: "Add the Twilio number to phone_numbers table with correct tenant_id",
    severity: "critical",
  },
  {
    issue: "ElevenLabs register-call failed [401]",
    cause: "Missing or invalid ELEVENLABS_API_KEY",
    fix: "Verify ELEVENLABS_API_KEY and ELEVENLABS_AGENT_ID secrets are set correctly",
    severity: "critical",
  },
  {
    issue: "Missing Supabase configuration",
    cause: "Edge function missing SUPABASE_URL or SERVICE_ROLE_KEY",
    fix: "These are auto-injected by Cloud - redeploy the edge function",
    severity: "critical",
  },
  {
    issue: "Database error looking up phone number",
    cause: "Schema mismatch or RLS blocking service role",
    fix: "Check phone_numbers table exists and has location_id column",
    severity: "high",
  },
  {
    issue: "Voice AI disabled for tenant",
    cause: "voice_ai_enabled = false in assistant_settings",
    fix: "Enable Voice AI in Settings or via assistant_settings.voice_ai_enabled = true",
    severity: "medium",
  },
];

export default function TelephonyDebugPage() {
  const { tenant, user, isSuperAdmin, loading: authLoading } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();
  const [refreshing, setRefreshing] = useState(false);

  // Only allow super admins or dev mode
  const isDev = import.meta.env.DEV;
  const canAccess = isSuperAdmin || isDev;

  useEffect(() => {
    if (!authLoading && !canAccess) {
      navigate("/app/dashboard");
    }
  }, [authLoading, canAccess, navigate]);

  // Fetch tenant phone number config
  const { data: phoneConfig, isLoading: phoneLoading, refetch: refetchPhone } = useQuery({
    queryKey: ["debug-phone-config", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data, error } = await supabase
        .from("phone_numbers")
        .select("*")
        .eq("tenant_id", tenant.id);
      return data || [];
    },
    enabled: !!tenant?.id && canAccess,
  });

  // Fetch assistant settings
  const { data: assistantSettings, refetch: refetchSettings } = useQuery({
    queryKey: ["debug-assistant-settings", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return null;
      const { data } = await supabase
        .from("assistant_settings")
        .select("*")
        .eq("tenant_id", tenant.id)
        .maybeSingle();
      return data;
    },
    enabled: !!tenant?.id && canAccess,
  });

  // Fetch Twilio event logs
  const { data: twilioLogs, isLoading: logsLoading, refetch: refetchLogs } = useQuery({
    queryKey: ["debug-twilio-logs", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data, error } = await supabase
        .from("twilio_event_logs")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false })
        .limit(20);
      return data || [];
    },
    enabled: !!tenant?.id && canAccess,
  });

  // Fetch ai_call_sessions
  const { data: callSessions, isLoading: sessionsLoading, refetch: refetchSessions } = useQuery({
    queryKey: ["debug-call-sessions", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      const { data } = await supabase
        .from("ai_call_sessions")
        .select("*")
        .eq("tenant_id", tenant.id)
        .order("created_at", { ascending: false })
        .limit(20);
      return data || [];
    },
    enabled: !!tenant?.id && canAccess,
  });

  const handleRefresh = async () => {
    setRefreshing(true);
    await Promise.all([refetchPhone(), refetchSettings(), refetchLogs(), refetchSessions()]);
    setRefreshing(false);
    toast({ title: "Refreshed", description: "Debug data updated" });
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({ title: "Copied", description: "Value copied to clipboard" });
  };

  if (authLoading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!canAccess) {
    return null;
  }

  const webhookBaseUrl = import.meta.env.VITE_SUPABASE_URL || "https://zsqfzluyylzmmjtfxwgr.supabase.co";

  return (
    <div className="min-h-screen bg-background">
      {/* Header */}
      <header className="sticky top-0 z-50 border-b bg-background/95 backdrop-blur">
        <div className="flex h-14 items-center justify-between px-4 md:px-6">
          <div className="flex items-center gap-3">
            <Button variant="ghost" size="icon" onClick={() => navigate(-1)}>
              <ArrowLeft className="h-4 w-4" />
            </Button>
            <div>
              <h1 className="text-lg font-semibold">Telephony Debug Pack</h1>
              <p className="text-xs text-muted-foreground">Dev/Admin Only</p>
            </div>
          </div>
          <Button variant="outline" size="sm" onClick={handleRefresh} disabled={refreshing}>
            <RefreshCw className={`h-4 w-4 mr-2 ${refreshing ? "animate-spin" : ""}`} />
            Refresh
          </Button>
        </div>
      </header>

      <main className="container max-w-6xl py-6 space-y-6">
        {/* TENANT ISOLATION SELF-TEST */}
        <Card className="border-primary/50">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg">
              <CheckCircle className="h-5 w-5 text-primary" />
              Tenant Isolation Self-Test
            </CardTitle>
            <CardDescription>
              Verify this tenant's phone number is properly scoped
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {/* Current Tenant Info */}
              <div className="grid grid-cols-2 gap-4 text-sm">
                <div>
                  <p className="text-muted-foreground mb-1">Current Tenant ID</p>
                  <code className="text-xs bg-muted px-2 py-1 rounded font-mono break-all">
                    {tenant?.id || "N/A"}
                  </code>
                </div>
                <div>
                  <p className="text-muted-foreground mb-1">Tenant Name</p>
                  <p className="font-medium">{tenant?.name || "N/A"}</p>
                </div>
              </div>

              {/* Self-Test Results */}
              <div className="border rounded-lg p-4 space-y-3">
                <h4 className="font-medium text-sm">Isolation Checks</h4>
                
                {/* Check 1: phone_numbers record exists for this tenant */}
                <div className="flex items-center gap-2 text-sm">
                  {phoneConfig && phoneConfig.length > 0 ? (
                    <CheckCircle className="h-4 w-4 text-primary shrink-0" />
                  ) : (
                    <XCircle className="h-4 w-4 text-destructive shrink-0" />
                  )}
                  <span>phone_numbers row exists for this tenant</span>
                  {phoneConfig && phoneConfig.length > 0 && (
                    <code className="text-xs bg-muted px-1 rounded ml-auto">
                      {phoneConfig[0]?.phone_e164}
                    </code>
                  )}
                </div>

                {/* Check 2: assistant_settings.closeloop_number matches */}
                <div className="flex items-center gap-2 text-sm">
                  {(() => {
                    const phoneFromNumbers = phoneConfig?.[0]?.phone_e164;
                    const phoneFromSettings = assistantSettings?.closeloop_number;
                    const match = phoneFromNumbers === phoneFromSettings;
                    const bothNull = !phoneFromNumbers && !phoneFromSettings;
                    const isOk = match || bothNull;
                    return (
                      <>
                        {isOk ? (
                          <CheckCircle className="h-4 w-4 text-primary shrink-0" />
                        ) : (
                          <AlertTriangle className="h-4 w-4 text-destructive shrink-0" />
                        )}
                        <span>assistant_settings.closeloop_number matches phone_numbers</span>
                        {!isOk && (
                          <Badge variant="destructive" className="ml-auto text-xs">
                            MISMATCH: {phoneFromSettings || "null"} ≠ {phoneFromNumbers || "null"}
                          </Badge>
                        )}
                      </>
                    );
                  })()}
                </div>

                {/* Check 3: No duplicate numbers across tenants */}
                <div className="flex items-center gap-2 text-sm">
                  <CheckCircle className="h-4 w-4 text-primary shrink-0" />
                  <span>DB constraints prevent duplicate phone_e164 across tenants</span>
                  <Badge variant="outline" className="ml-auto text-xs">UNIQUE</Badge>
                </div>

                {/* Check 4: RLS policies are active */}
                <div className="flex items-center gap-2 text-sm">
                  <CheckCircle className="h-4 w-4 text-primary shrink-0" />
                  <span>RLS policies enforce tenant isolation on phone_numbers</span>
                  <Badge variant="outline" className="ml-auto text-xs">ENABLED</Badge>
                </div>
              </div>

              {/* Summary */}
              <Alert variant={phoneConfig && phoneConfig.length > 0 ? "default" : "destructive"}>
                {phoneConfig && phoneConfig.length > 0 ? (
                  <>
                    <CheckCircle className="h-4 w-4" />
                    <AlertTitle>Tenant Isolation OK</AlertTitle>
                    <AlertDescription>
                      This tenant has its own unique phone number: <strong>{phoneConfig[0]?.phone_e164}</strong>
                    </AlertDescription>
                  </>
                ) : (
                  <>
                    <XCircle className="h-4 w-4" />
                    <AlertTitle>No Phone Number Assigned</AlertTitle>
                    <AlertDescription>
                      This tenant does not have a phone_numbers record. If they have a voice subscription, provision one.
                    </AlertDescription>
                  </>
                )}
              </Alert>
            </div>
          </CardContent>
        </Card>

        {/* Troubleshooting Guide */}
        <Card className="border-warning/50">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-lg">
              <AlertTriangle className="h-5 w-5 text-warning" />
              Top 5 Failure Reasons & Fixes
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {TROUBLESHOOTING_GUIDE.map((item, i) => (
                <div key={i} className="border rounded-lg p-3">
                  <div className="flex items-start gap-2">
                    <Badge variant={item.severity === "critical" ? "destructive" : item.severity === "high" ? "default" : "secondary"} className="shrink-0">
                      {item.severity.toUpperCase()}
                    </Badge>
                    <div className="space-y-1">
                      <p className="font-medium text-sm">{item.issue}</p>
                      <p className="text-xs text-muted-foreground">Cause: {item.cause}</p>
                      <p className="text-xs text-primary">Fix: {item.fix}</p>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Phone & Webhook Status */}
        <div className="grid md:grid-cols-2 gap-4">
          {/* Twilio Number */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-base">
                <Phone className="h-4 w-4" />
                Assigned Twilio Number
              </CardTitle>
            </CardHeader>
            <CardContent>
              {phoneLoading ? (
                <Skeleton className="h-20 w-full" />
              ) : phoneConfig && phoneConfig.length > 0 ? (
                <div className="space-y-2">
                  {phoneConfig.map((phone: any) => (
                    <div key={phone.id} className="flex items-center justify-between p-2 bg-muted rounded">
                      <div>
                        <p className="font-mono font-medium">{phone.phone_e164}</p>
                        <p className="text-xs text-muted-foreground">
                          Status: <Badge variant={phone.status === "active" ? "default" : "secondary"}>{phone.status || "unknown"}</Badge>
                        </p>
                      </div>
                      <Button size="icon" variant="ghost" onClick={() => copyToClipboard(phone.phone_e164)}>
                        <Copy className="h-4 w-4" />
                      </Button>
                    </div>
                  ))}
                </div>
              ) : (
                <Alert>
                  <XCircle className="h-4 w-4" />
                  <AlertTitle>No Twilio number assigned</AlertTitle>
                  <AlertDescription>
                    Add a phone_numbers record with tenant_id = {tenant?.id}
                  </AlertDescription>
                </Alert>
              )}
            </CardContent>
          </Card>

          {/* Webhook URLs */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-base">
                <Webhook className="h-4 w-4" />
                Webhook URLs
              </CardTitle>
              <CardDescription>Configure these in Twilio console</CardDescription>
            </CardHeader>
            <CardContent className="space-y-3">
              <div>
                <p className="text-xs font-medium text-muted-foreground mb-1">Voice Webhook (POST)</p>
                <div className="flex items-center gap-2">
                  <code className="flex-1 text-xs bg-muted p-2 rounded font-mono break-all">
                    {webhookBaseUrl}/functions/v1/twilio-inbound
                  </code>
                  <Button size="icon" variant="ghost" onClick={() => copyToClipboard(`${webhookBaseUrl}/functions/v1/twilio-inbound`)}>
                    <Copy className="h-4 w-4" />
                  </Button>
                </div>
              </div>
              <div>
                <p className="text-xs font-medium text-muted-foreground mb-1">ElevenLabs Webhook</p>
                <div className="flex items-center gap-2">
                  <code className="flex-1 text-xs bg-muted p-2 rounded font-mono break-all">
                    {webhookBaseUrl}/functions/v1/elevenlabs-webhook
                  </code>
                  <Button size="icon" variant="ghost" onClick={() => copyToClipboard(`${webhookBaseUrl}/functions/v1/elevenlabs-webhook`)}>
                    <Copy className="h-4 w-4" />
                  </Button>
                </div>
              </div>
              <div className="pt-2">
                <p className="text-xs text-muted-foreground">
                  Voice AI: <Badge variant={assistantSettings?.voice_ai_enabled ? "default" : "secondary"}>{assistantSettings?.voice_ai_enabled ? "Enabled" : "Disabled"}</Badge>
                  {" • "}
                  Connect Status: <Badge variant="outline">{assistantSettings?.connect_status || "unknown"}</Badge>
                </p>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Logs Tabs */}
        <Tabs defaultValue="twilio-events" className="w-full">
          <TabsList className="grid w-full grid-cols-3">
            <TabsTrigger value="twilio-events">Twilio Events</TabsTrigger>
            <TabsTrigger value="elevenlabs">ElevenLabs Attempts</TabsTrigger>
            <TabsTrigger value="sessions">Call Sessions</TabsTrigger>
          </TabsList>

          {/* Twilio Event Logs */}
          <TabsContent value="twilio-events">
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Last 20 Twilio Inbound Events</CardTitle>
                <CardDescription>Logged from twilio-inbound edge function</CardDescription>
              </CardHeader>
              <CardContent>
                {logsLoading ? (
                  <div className="space-y-2">
                    {[1, 2, 3].map((i) => <Skeleton key={i} className="h-12 w-full" />)}
                  </div>
                ) : twilioLogs && twilioLogs.length > 0 ? (
                  <ScrollArea className="h-[400px]">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Time</TableHead>
                          <TableHead>Stage</TableHead>
                          <TableHead>From → To</TableHead>
                          <TableHead>Status</TableHead>
                          <TableHead>Error</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {twilioLogs.map((log: any) => (
                          <TableRow key={log.id}>
                            <TableCell className="text-xs whitespace-nowrap">
                              {format(new Date(log.created_at), "MMM d, HH:mm:ss")}
                            </TableCell>
                            <TableCell>
                              <Badge variant="outline">{log.stage}</Badge>
                            </TableCell>
                            <TableCell className="text-xs font-mono">
                              {log.from_number} → {log.to_number}
                            </TableCell>
                            <TableCell>
                              {log.http_status ? (
                                <Badge variant={log.http_status >= 200 && log.http_status < 300 ? "default" : "destructive"}>
                                  {log.http_status}
                                </Badge>
                              ) : "-"}
                            </TableCell>
                            <TableCell className="text-xs text-destructive max-w-[200px] truncate">
                              {log.error_message || "-"}
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </ScrollArea>
                ) : (
                  <p className="text-sm text-muted-foreground text-center py-8">
                    No Twilio events logged yet. Events will appear after inbound calls are processed.
                  </p>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* ElevenLabs Attempts (from twilio_event_logs where stage = elevenlabs_*) */}
          <TabsContent value="elevenlabs">
            <Card>
              <CardHeader>
                <CardTitle className="text-base">ElevenLabs Register-Call Attempts</CardTitle>
                <CardDescription>Results from calling ElevenLabs API</CardDescription>
              </CardHeader>
              <CardContent>
                {logsLoading ? (
                  <div className="space-y-2">
                    {[1, 2, 3].map((i) => <Skeleton key={i} className="h-12 w-full" />)}
                  </div>
                ) : (() => {
                  const elevenLabsLogs = twilioLogs?.filter((l: any) => l.stage?.includes("elevenlabs")) || [];
                  return elevenLabsLogs.length > 0 ? (
                    <ScrollArea className="h-[400px]">
                      <Table>
                        <TableHeader>
                          <TableRow>
                            <TableHead>Time</TableHead>
                            <TableHead>Call SID</TableHead>
                            <TableHead>Status</TableHead>
                            <TableHead>Error</TableHead>
                          </TableRow>
                        </TableHeader>
                        <TableBody>
                          {elevenLabsLogs.map((log: any) => (
                            <TableRow key={log.id}>
                              <TableCell className="text-xs whitespace-nowrap">
                                {format(new Date(log.created_at), "MMM d, HH:mm:ss")}
                              </TableCell>
                              <TableCell className="text-xs font-mono">{log.twilio_call_sid}</TableCell>
                              <TableCell>
                                <Badge variant={log.http_status >= 200 && log.http_status < 300 ? "default" : "destructive"}>
                                  {log.http_status}
                                </Badge>
                              </TableCell>
                              <TableCell className="text-xs text-destructive max-w-[300px] truncate">
                                {log.error_message || "Success"}
                              </TableCell>
                            </TableRow>
                          ))}
                        </TableBody>
                      </Table>
                    </ScrollArea>
                  ) : (
                    <p className="text-sm text-muted-foreground text-center py-8">
                      No ElevenLabs API calls logged yet.
                    </p>
                  );
                })()}
              </CardContent>
            </Card>
          </TabsContent>

          {/* Call Sessions */}
          <TabsContent value="sessions">
            <Card>
              <CardHeader>
                <CardTitle className="text-base">Last 20 AI Call Sessions</CardTitle>
                <CardDescription>From ai_call_sessions table</CardDescription>
              </CardHeader>
              <CardContent>
                {sessionsLoading ? (
                  <div className="space-y-2">
                    {[1, 2, 3].map((i) => <Skeleton key={i} className="h-12 w-full" />)}
                  </div>
                ) : callSessions && callSessions.length > 0 ? (
                  <ScrollArea className="h-[400px]">
                    <Table>
                      <TableHeader>
                        <TableRow>
                          <TableHead>Started</TableHead>
                          <TableHead>Direction</TableHead>
                          <TableHead>Caller</TableHead>
                          <TableHead>Outcome</TableHead>
                          <TableHead>EL Conv ID</TableHead>
                        </TableRow>
                      </TableHeader>
                      <TableBody>
                        {callSessions.map((session: any) => (
                          <TableRow key={session.id}>
                            <TableCell className="text-xs whitespace-nowrap">
                              {format(new Date(session.started_at), "MMM d, HH:mm")}
                            </TableCell>
                            <TableCell>
                              <Badge variant="outline">{session.call_direction}</Badge>
                            </TableCell>
                            <TableCell className="text-xs font-mono">{session.caller_phone || "-"}</TableCell>
                            <TableCell>
                              {session.outcome ? (
                                <Badge variant={session.outcome === "completed" ? "default" : "secondary"}>
                                  {session.outcome}
                                </Badge>
                              ) : (
                                <span className="text-muted-foreground">-</span>
                              )}
                            </TableCell>
                            <TableCell className="text-xs font-mono max-w-[100px] truncate">
                              {session.elevenlabs_conversation_id || "-"}
                            </TableCell>
                          </TableRow>
                        ))}
                      </TableBody>
                    </Table>
                  </ScrollArea>
                ) : (
                  <p className="text-sm text-muted-foreground text-center py-8">
                    No call sessions yet. Sessions are created when calls are received.
                  </p>
                )}
              </CardContent>
            </Card>
          </TabsContent>
        </Tabs>
      </main>
    </div>
  );
}

import { useDriverJobs, DriverJob } from "@/hooks/useDriverJobs";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { 
  Loader2, MapPin, Phone, Navigation, Clock, ChevronRight, 
  AlertTriangle, CheckCircle2, Truck, Play 
} from "lucide-react";
import { Link } from "react-router-dom";
import { formatDistanceToNow } from "date-fns";

function getStatusBadge(status: string) {
  switch (status) {
    case "assigned":
      return <Badge className="bg-blue-500/10 text-blue-600 border-blue-200">Assigned</Badge>;
    case "en_route":
      return <Badge className="bg-amber-500/10 text-amber-600 border-amber-200">En Route</Badge>;
    case "on_site":
      return <Badge className="bg-purple-500/10 text-purple-600 border-purple-200">On Site</Badge>;
    case "completed":
      return <Badge className="bg-green-500/10 text-green-600 border-green-200">Completed</Badge>;
    default:
      return <Badge variant="secondary">{status}</Badge>;
  }
}

function getPriorityBadge(priority: string) {
  if (priority === "urgent") {
    return <Badge variant="destructive" className="gap-1"><AlertTriangle className="h-3 w-3" />Urgent</Badge>;
  }
  return null;
}

function JobCard({ job }: { job: DriverJob }) {
  const timeAgo = job.dispatched_at 
    ? formatDistanceToNow(new Date(job.dispatched_at), { addSuffix: true })
    : formatDistanceToNow(new Date(job.created_at), { addSuffix: true });

  const handleDirections = () => {
    if (job.pickup_address) {
      const url = `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(job.pickup_address)}`;
      window.open(url, "_blank");
    }
  };

  const handleCall = () => {
    if (job.customer_phone) {
      window.open(`tel:${job.customer_phone}`);
    }
  };

  return (
    <Card className="hover:border-primary/50 transition-colors">
      <CardContent className="p-4">
        <div className="flex items-start justify-between mb-3">
          <div>
            <div className="flex items-center gap-2 mb-1">
              <span className="font-mono text-sm font-medium">
                #{job.job_number || job.id.slice(0, 8)}
              </span>
              {getStatusBadge(job.status)}
              {getPriorityBadge(job.priority)}
            </div>
            <p className="font-medium">{job.customer_name || "Unknown Customer"}</p>
          </div>
          <span className="text-xs text-muted-foreground">{timeAgo}</span>
        </div>

        {job.pickup_address && (
          <div className="flex items-start gap-2 text-sm text-muted-foreground mb-2">
            <MapPin className="h-4 w-4 shrink-0 mt-0.5" />
            <span className="line-clamp-2">{job.pickup_address}</span>
          </div>
        )}

        {job.job_type && (
          <div className="flex items-center gap-2 text-sm text-muted-foreground mb-3">
            <Truck className="h-4 w-4" />
            <span>{job.job_type}</span>
          </div>
        )}

        <div className="flex items-center gap-2">
          <Button size="sm" variant="outline" className="flex-1" onClick={handleDirections}>
            <Navigation className="h-4 w-4 mr-1" />
            Directions
          </Button>
          {job.customer_phone && (
            <Button size="sm" variant="outline" onClick={handleCall}>
              <Phone className="h-4 w-4" />
            </Button>
          )}
          <Button size="sm" asChild>
            <Link to={`/driver/jobs/${job.id}`}>
              Details
              <ChevronRight className="h-4 w-4 ml-1" />
            </Link>
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

export default function DriverDashboard() {
  const { activeJobs, completedJobs, isLoading, driverRecord } = useDriverJobs();

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!driverRecord) {
    return (
      <div className="p-6">
        <Card>
          <CardContent className="py-12 text-center">
            <AlertTriangle className="h-12 w-12 mx-auto mb-4 text-amber-500" />
            <h2 className="text-lg font-semibold mb-2">Account Not Linked</h2>
            <p className="text-muted-foreground max-w-sm mx-auto">
              Your account is not yet linked to a driver profile. 
              Please contact your dispatcher to complete the setup.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="p-4 space-y-6">
      {/* Welcome Header */}
      <div>
        <h1 className="text-xl font-semibold">
          Hey, {driverRecord.full_name.split(" ")[0]}!
        </h1>
        <p className="text-muted-foreground">
          {activeJobs.length === 0 
            ? "No active jobs right now"
            : `You have ${activeJobs.length} active job${activeJobs.length !== 1 ? "s" : ""}`
          }
        </p>
      </div>

      {/* Active Jobs */}
      {activeJobs.length > 0 ? (
        <div className="space-y-3">
          <h2 className="text-sm font-medium text-muted-foreground uppercase tracking-wide">
            Active Jobs
          </h2>
          {activeJobs.map((job) => (
            <JobCard key={job.id} job={job} />
          ))}
        </div>
      ) : (
        <Card>
          <CardContent className="py-12 text-center">
            <CheckCircle2 className="h-12 w-12 mx-auto mb-4 text-green-500 opacity-50" />
            <h2 className="text-lg font-medium mb-1">All Caught Up</h2>
            <p className="text-sm text-muted-foreground">
              No jobs assigned to you right now. Check back later!
            </p>
          </CardContent>
        </Card>
      )}

      {/* Recently Completed */}
      {completedJobs.length > 0 && (
        <div className="space-y-3">
          <h2 className="text-sm font-medium text-muted-foreground uppercase tracking-wide">
            Recently Completed
          </h2>
          {completedJobs.slice(0, 3).map((job) => (
            <Card key={job.id} className="opacity-60">
              <CardContent className="p-4">
                <div className="flex items-center justify-between">
                  <div>
                    <span className="font-mono text-sm">
                      #{job.job_number || job.id.slice(0, 8)}
                    </span>
                    <p className="text-sm text-muted-foreground">
                      {job.customer_name}
                    </p>
                  </div>
                  {getStatusBadge("completed")}
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { useDriverJobs } from "@/hooks/useDriverJobs";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { useToast } from "@/hooks/use-toast";
import { 
  ArrowLeft, MapPin, Phone, Navigation, User, Truck, 
  FileText, AlertTriangle, Play, CheckCircle, ArrowRight,
  Loader2, Camera, DollarSign
} from "lucide-react";
import { PhotoUploader } from "@/components/driver/PhotoUploader";

function getNextStatus(current: string): string | null {
  switch (current) {
    case "assigned":
      return "en_route";
    case "en_route":
      return "on_site";
    case "on_site":
      return "completed";
    default:
      return null;
  }
}

function getNextStatusLabel(current: string): string {
  switch (current) {
    case "assigned":
      return "Start Route";
    case "en_route":
      return "Arrived On Site";
    case "on_site":
      return "Complete Job";
    default:
      return "Update Status";
  }
}

function getStatusIcon(current: string) {
  switch (current) {
    case "assigned":
      return <Play className="h-5 w-5" />;
    case "en_route":
      return <ArrowRight className="h-5 w-5" />;
    case "on_site":
      return <CheckCircle className="h-5 w-5" />;
    default:
      return null;
  }
}

function getStatusColor(status: string): string {
  switch (status) {
    case "assigned":
      return "bg-blue-500/10 text-blue-600 border-blue-200";
    case "en_route":
      return "bg-amber-500/10 text-amber-600 border-amber-200";
    case "on_site":
      return "bg-purple-500/10 text-purple-600 border-purple-200";
    case "completed":
      return "bg-green-500/10 text-green-600 border-green-200";
    default:
      return "";
  }
}

export default function DriverJobDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { tenant } = useAuth();
  const { toast } = useToast();
  const { jobs, isLoading, updateJobStatus, refetch } = useDriverJobs();
  const [photos, setPhotos] = useState<string[]>([]);
  const [savingPhotos, setSavingPhotos] = useState(false);

  const job = jobs.find(j => j.id === id);

  const handleSavePhotos = async () => {
    if (!job || photos.length === 0) return;
    
    setSavingPhotos(true);
    try {
      // Get existing photos
      const existingPhotos = (job as any).photos || [];
      const allPhotos = [...existingPhotos, ...photos];
      
      const { error } = await supabase
        .from("dispatch_jobs")
        .update({ photos: allPhotos })
        .eq("id", job.id);

      if (error) throw error;
      
      toast({ title: "Photos saved" });
      setPhotos([]);
      refetch();
    } catch (error) {
      toast({
        variant: "destructive",
        title: "Error",
        description: error instanceof Error ? error.message : "Failed to save photos",
      });
    } finally {
      setSavingPhotos(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  if (!job) {
    return (
      <div className="p-6">
        <Card>
          <CardContent className="py-12 text-center">
            <AlertTriangle className="h-12 w-12 mx-auto mb-4 text-amber-500" />
            <h2 className="text-lg font-semibold mb-2">Job Not Found</h2>
            <p className="text-muted-foreground mb-4">
              This job may have been reassigned or doesn't exist.
            </p>
            <Button onClick={() => navigate("/driver")}>
              <ArrowLeft className="h-4 w-4 mr-2" />
              Back to Jobs
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  const handleDirections = (address: string) => {
    const url = `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(address)}`;
    window.open(url, "_blank");
  };

  const handleCall = () => {
    if (job.customer_phone) {
      window.open(`tel:${job.customer_phone}`);
    }
  };

  const handleStatusUpdate = () => {
    const nextStatus = getNextStatus(job.status);
    if (nextStatus) {
      updateJobStatus.mutate({ jobId: job.id, status: nextStatus });
    }
  };

  const nextStatus = getNextStatus(job.status);
  const isCompleted = job.status === "completed";
  const isOnSite = job.status === "on_site";
  const existingPhotos = ((job as any).photos as string[]) || [];

  const formatPrice = (cents: number | null) => {
    if (!cents) return null;
    return `$${(cents / 100).toFixed(2)}`;
  };

  return (
    <div className="p-4 space-y-4 pb-36">
      {/* Header */}
      <div className="flex items-center gap-3">
        <Button variant="ghost" size="icon" onClick={() => navigate("/driver")}>
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div className="flex-1">
          <h1 className="font-semibold text-lg">Job #{job.job_number || job.id.slice(0, 8)}</h1>
          <div className="flex items-center gap-2 mt-1">
            <Badge className={getStatusColor(job.status)}>
              {job.status.replace("_", " ").toUpperCase()}
            </Badge>
            {job.priority === "urgent" && (
              <Badge variant="destructive" className="gap-1">
                <AlertTriangle className="h-3 w-3" />
                Urgent
              </Badge>
            )}
          </div>
        </div>
      </div>

      {/* Customer Info - Click to Call */}
      <Card>
        <CardContent className="p-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="h-12 w-12 rounded-full bg-muted flex items-center justify-center">
                <User className="h-6 w-6 text-muted-foreground" />
              </div>
              <div>
                <p className="font-medium">{job.customer_name || "Unknown Customer"}</p>
                <p className="text-sm text-muted-foreground">{job.job_type || "Dispatch Job"}</p>
              </div>
            </div>
            {job.customer_phone && (
              <Button size="icon" variant="outline" className="h-12 w-12" onClick={handleCall}>
                <Phone className="h-5 w-5" />
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Pickup Location - Primary Action */}
      {job.pickup_address && (
        <Card className="border-primary/50">
          <CardHeader className="pb-2">
            <div className="flex items-center justify-between">
              <CardTitle className="text-sm font-medium text-muted-foreground">PICKUP</CardTitle>
              {job.estimated_arrival_at && job.status === "en_route" && (
                <Badge variant="outline" className="text-xs">
                  ETA: {new Date(job.estimated_arrival_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                </Badge>
              )}
            </div>
          </CardHeader>
          <CardContent className="space-y-3">
            <p className="text-base">{job.pickup_address}</p>
            <Button 
              className="w-full h-12"
              onClick={() => handleDirections(job.pickup_address!)}
            >
              <Navigation className="h-5 w-5 mr-2" />
              Navigate to Pickup
            </Button>
          </CardContent>
        </Card>
      )}

      {/* Drop-off Location */}
      {job.dropoff_address && (
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm font-medium text-muted-foreground">DROP-OFF</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <p className="text-base">{job.dropoff_address}</p>
            <Button 
              variant="outline"
              className="w-full h-12"
              onClick={() => handleDirections(job.dropoff_address!)}
            >
              <Navigation className="h-5 w-5 mr-2" />
              Navigate to Drop-off
            </Button>
          </CardContent>
        </Card>
      )}

      {/* Price Info */}
      {job.price_cents && (
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <DollarSign className="h-5 w-5 text-muted-foreground" />
                <span className="font-medium">Job Total</span>
              </div>
              <span className="text-xl font-bold">{formatPrice(job.price_cents)}</span>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Notes */}
      {(job.notes || job.description) && (
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-base flex items-center gap-2">
              <FileText className="h-4 w-4" />
              Notes
            </CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-sm whitespace-pre-wrap">
              {job.notes || job.description}
            </p>
          </CardContent>
        </Card>
      )}

      {/* Vehicle Info */}
      {job.assigned_vehicle && (
        <Card>
          <CardContent className="p-4">
            <div className="flex items-center gap-3">
              <Truck className="h-5 w-5 text-muted-foreground" />
              <span className="text-sm">{job.assigned_vehicle}</span>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Photo Upload Section - Show when on site or completed */}
      {(isOnSite || isCompleted) && tenant?.id && (
        <Card className="border-dashed">
          <CardHeader className="pb-2">
            <CardTitle className="text-base flex items-center gap-2">
              <Camera className="h-4 w-4" />
              Job Photos
            </CardTitle>
            <CardDescription>
              {isOnSite ? "Take photos before completing the job" : "View or add job photos"}
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-4">
            {/* Existing Photos */}
            {existingPhotos.length > 0 && (
              <div className="space-y-2">
                <p className="text-xs text-muted-foreground uppercase tracking-wide">
                  Saved Photos ({existingPhotos.length})
                </p>
                <div className="grid grid-cols-4 gap-2">
                  {existingPhotos.map((url, i) => (
                    <div key={i} className="aspect-square rounded-lg overflow-hidden bg-muted">
                      <img src={url} alt={`Photo ${i + 1}`} className="w-full h-full object-cover" />
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Photo Uploader */}
            <PhotoUploader
              tenantId={tenant.id}
              entityType="dispatch"
              entityId={job.id}
              onPhotosChange={setPhotos}
              maxPhotos={8}
            />

            {/* Save Photos Button */}
            {photos.length > 0 && (
              <Button 
                className="w-full"
                onClick={handleSavePhotos}
                disabled={savingPhotos}
              >
                {savingPhotos ? (
                  <>
                    <Loader2 className="h-4 w-4 animate-spin mr-2" />
                    Saving...
                  </>
                ) : (
                  `Save ${photos.length} Photo${photos.length !== 1 ? 's' : ''}`
                )}
              </Button>
            )}
          </CardContent>
        </Card>
      )}

      {/* Status Action Button */}
      {!isCompleted && nextStatus && (
        <div className="fixed bottom-20 left-4 right-4 z-10">
          <Button 
            size="lg" 
            className="w-full h-16 text-lg font-semibold shadow-lg"
            onClick={handleStatusUpdate}
            disabled={updateJobStatus.isPending}
          >
            {updateJobStatus.isPending ? (
              <Loader2 className="h-6 w-6 animate-spin mr-2" />
            ) : (
              getStatusIcon(job.status)
            )}
            <span className="ml-2">{getNextStatusLabel(job.status)}</span>
          </Button>
        </div>
      )}

      {isCompleted && (
        <div className="fixed bottom-20 left-4 right-4 z-10">
          <Card className="bg-green-50 border-green-200 dark:bg-green-900/20 dark:border-green-800">
            <CardContent className="py-4 text-center">
              <CheckCircle className="h-6 w-6 text-green-600 dark:text-green-400 mx-auto mb-2" />
              <p className="font-medium text-green-700 dark:text-green-300">Job Completed</p>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Truck, Loader2, Eye, EyeOff } from "lucide-react";
import { useToast } from "@/hooks/use-toast";

export default function DriverLoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const { signIn } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    try {
      await signIn(email, password);
      // Always navigate to driver portal - DriverLayout will handle auth check
      navigate("/driver");
    } catch (error: any) {
      toast({
        variant: "destructive",
        title: "Login failed",
        description: error.message || "Please check your credentials and try again.",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-gradient-to-b from-slate-900 to-slate-800">
      {/* Driver Header */}
      <header className="p-6 text-center">
        <div className="inline-flex items-center justify-center h-16 w-16 rounded-2xl bg-primary mb-3">
          <Truck className="h-8 w-8 text-primary-foreground" />
        </div>
        <h1 className="text-2xl font-bold text-white">Driver Portal</h1>
        <p className="text-slate-400 mt-1">Sign in to access your jobs</p>
      </header>

      {/* Login Form */}
      <main className="flex-1 flex items-start justify-center px-4 pb-8">
        <Card className="w-full max-w-sm shadow-2xl border-slate-700 bg-slate-800/50 backdrop-blur">
          <CardHeader className="pb-4">
            <CardTitle className="text-xl text-white">Welcome back</CardTitle>
            <CardDescription className="text-slate-400">
              Enter your credentials to continue
            </CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-5">
              <div className="space-y-2">
                <Label htmlFor="email" className="text-slate-200">Email</Label>
                <Input
                  id="email"
                  type="email"
                  placeholder="driver@company.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  autoComplete="email"
                  className="h-12 bg-slate-700/50 border-slate-600 text-white placeholder:text-slate-400"
                />
              </div>
              
              <div className="space-y-2">
                <Label htmlFor="password" className="text-slate-200">Password</Label>
                <div className="relative">
                  <Input
                    id="password"
                    type={showPassword ? "text" : "password"}
                    placeholder="••••••••"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    autoComplete="current-password"
                    className="h-12 bg-slate-700/50 border-slate-600 text-white placeholder:text-slate-400 pr-12"
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-white transition-colors"
                  >
                    {showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}
                  </button>
                </div>
              </div>

              <Button 
                type="submit" 
                className="w-full h-14 text-lg font-semibold"
                disabled={loading}
              >
                {loading ? (
                  <>
                    <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                    Signing in...
                  </>
                ) : (
                  <>
                    <Truck className="mr-2 h-5 w-5" />
                    Sign In
                  </>
                )}
              </Button>
            </form>

            <div className="mt-6 pt-6 border-t border-slate-700">
              <p className="text-center text-sm text-slate-400">
                Having trouble logging in?
              </p>
              <p className="text-center text-sm text-slate-500 mt-1">
                Contact your dispatcher for help
              </p>
            </div>
          </CardContent>
        </Card>
      </main>

      {/* Footer */}
      <footer className="p-4 text-center text-slate-500 text-xs">
        Powered by CloseLoop
      </footer>
    </div>
  );
}

import { useState } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/contexts/AuthContext";
import { useDriverJobs } from "@/hooks/useDriverJobs";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useToast } from "@/hooks/use-toast";
import { Loader2, Truck, Check, AlertTriangle } from "lucide-react";
import { cn } from "@/lib/utils";

interface FleetVehicle {
  id: string;
  name: string;
  vehicle_type: string | null;
  license_plate: string | null;
  year: number | null;
  make: string | null;
  model: string | null;
  status: string;
  current_driver_id: string | null;
}

export default function DriverVehicleSelect() {
  const { tenant } = useAuth();
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const { driverRecord } = useDriverJobs();
  const [selectedVehicleId, setSelectedVehicleId] = useState<string | null>(
    driverRecord?.default_vehicle_id || null
  );

  const { data: vehicles, isLoading } = useQuery({
    queryKey: ["driver-vehicles", tenant?.id],
    queryFn: async () => {
      if (!tenant?.id) return [];
      
      const { data, error } = await supabase
        .from("fleet_vehicles")
        .select("*")
        .eq("tenant_id", tenant.id)
        .neq("status", "retired")
        .order("name");

      if (error) throw error;
      return data as FleetVehicle[];
    },
    enabled: !!tenant?.id,
  });

  const selectVehicle = useMutation({
    mutationFn: async (vehicleId: string | null) => {
      if (!driverRecord?.id) throw new Error("Driver not found");

      // Update driver's default vehicle
      const { error: driverError } = await supabase
        .from("fleet_drivers")
        .update({ default_vehicle_id: vehicleId })
        .eq("id", driverRecord.id);

      if (driverError) throw driverError;

      // Clear previous vehicle assignment if any
      if (driverRecord.default_vehicle_id) {
        await supabase
          .from("fleet_vehicles")
          .update({ current_driver_id: null })
          .eq("id", driverRecord.default_vehicle_id);
      }

      // Set new vehicle assignment
      if (vehicleId) {
        const { error: vehicleError } = await supabase
          .from("fleet_vehicles")
          .update({ current_driver_id: driverRecord.id })
          .eq("id", vehicleId);

        if (vehicleError) throw vehicleError;
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["driver-vehicles"] });
      queryClient.invalidateQueries({ queryKey: ["fleet-driver-me"] });
      toast({ title: "Vehicle updated" });
    },
    onError: (error: Error) => {
      toast({ variant: "destructive", title: "Error", description: error.message });
    },
  });

  const handleSelectVehicle = (vehicleId: string) => {
    const newSelection = selectedVehicleId === vehicleId ? null : vehicleId;
    setSelectedVehicleId(newSelection);
    selectVehicle.mutate(newSelection);
  };

  if (!driverRecord) {
    return (
      <div className="p-6">
        <Card>
          <CardContent className="py-12 text-center">
            <AlertTriangle className="h-12 w-12 mx-auto mb-4 text-amber-500" />
            <h2 className="text-lg font-semibold mb-2">Account Not Linked</h2>
            <p className="text-muted-foreground">
              Your account is not yet linked to a driver profile.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (isLoading) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const getVehicleDescription = (v: FleetVehicle) => {
    const parts = [];
    if (v.year) parts.push(v.year);
    if (v.make) parts.push(v.make);
    if (v.model) parts.push(v.model);
    return parts.length > 0 ? parts.join(" ") : null;
  };

  const getStatusBadge = (status: string, currentDriverId: string | null) => {
    if (currentDriverId && currentDriverId !== driverRecord.id) {
      return <Badge variant="secondary">In Use</Badge>;
    }
    switch (status) {
      case "available":
        return <Badge className="bg-green-500/10 text-green-600 border-green-200">Available</Badge>;
      case "maintenance":
        return <Badge className="bg-amber-500/10 text-amber-600 border-amber-200">Maintenance</Badge>;
      default:
        return <Badge variant="secondary">{status}</Badge>;
    }
  };

  return (
    <div className="p-4 space-y-6">
      <div>
        <h1 className="text-xl font-semibold flex items-center gap-2">
          <Truck className="h-5 w-5" />
          My Vehicle
        </h1>
        <p className="text-sm text-muted-foreground">
          Select the vehicle you're driving today
        </p>
      </div>

      {vehicles && vehicles.length > 0 ? (
        <div className="space-y-3">
          {vehicles.map((vehicle) => {
            const isSelected = selectedVehicleId === vehicle.id;
            const isUnavailable = 
              vehicle.status === "maintenance" || 
              (vehicle.current_driver_id && vehicle.current_driver_id !== driverRecord.id);

            return (
              <Card 
                key={vehicle.id}
                className={cn(
                  "cursor-pointer transition-all",
                  isSelected && "ring-2 ring-primary border-primary",
                  isUnavailable && "opacity-50 cursor-not-allowed"
                )}
                onClick={() => !isUnavailable && handleSelectVehicle(vehicle.id)}
              >
                <CardContent className="p-4">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-4">
                      <div className={cn(
                        "h-12 w-12 rounded-lg flex items-center justify-center",
                        isSelected ? "bg-primary text-primary-foreground" : "bg-muted"
                      )}>
                        {isSelected ? (
                          <Check className="h-6 w-6" />
                        ) : (
                          <Truck className="h-6 w-6 text-muted-foreground" />
                        )}
                      </div>
                      <div>
                        <p className="font-medium">{vehicle.name}</p>
                        {getVehicleDescription(vehicle) && (
                          <p className="text-sm text-muted-foreground">
                            {getVehicleDescription(vehicle)}
                          </p>
                        )}
                        {vehicle.license_plate && (
                          <p className="text-xs font-mono mt-1 text-muted-foreground">
                            {vehicle.license_plate}
                          </p>
                        )}
                      </div>
                    </div>
                    {getStatusBadge(vehicle.status, vehicle.current_driver_id)}
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      ) : (
        <Card>
          <CardContent className="py-12 text-center">
            <Truck className="h-12 w-12 mx-auto mb-4 opacity-20" />
            <h2 className="text-lg font-medium mb-1">No Vehicles Available</h2>
            <p className="text-sm text-muted-foreground">
              No vehicles have been added to the fleet yet.
            </p>
          </CardContent>
        </Card>
      )}

      {selectedVehicleId && (
        <div className="pt-4">
          <Button 
            variant="outline" 
            className="w-full"
            onClick={() => handleSelectVehicle(selectedVehicleId)}
          >
            Clear Selection
          </Button>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent } from "@/components/ui/card";
import { AudioWaveform, Loader2, Building2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { supabase } from "@/integrations/supabase/client";
import { BRAND } from "@/config/brand";

interface AgencyInfo {
  agency_id: string;
  agency_name: string;
  branding_json: Record<string, unknown>;
}

export default function AgencyReferralSignupPage() {
  const { agencySlug } = useParams<{ agencySlug: string }>();
  const navigate = useNavigate();
  const { signUp } = useAuth();
  const { toast } = useToast();

  const [agencyInfo, setAgencyInfo] = useState<AgencyInfo | null>(null);
  const [resolving, setResolving] = useState(true);
  const [notFound, setNotFound] = useState(false);

  const [businessName, setBusinessName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState<{
    businessName?: string;
    email?: string;
    password?: string;
    general?: string;
  }>({});

  // Resolve the agency slug on mount
  useEffect(() => {
    if (!agencySlug) {
      setNotFound(true);
      setResolving(false);
      return;
    }

    (async () => {
      try {
        const { data, error } = await supabase.functions.invoke("resolve-agency-slug", {
          body: { slug: agencySlug },
        });

        if (error || !data?.agency_id) {
          setNotFound(true);
        } else {
          setAgencyInfo(data as AgencyInfo);
        }
      } catch {
        setNotFound(true);
      } finally {
        setResolving(false);
      }
    })();
  }, [agencySlug]);

  const validateForm = (): boolean => {
    const newErrors: typeof errors = {};
    if (!businessName.trim()) newErrors.businessName = "Please enter your business name.";
    if (!email.trim()) newErrors.email = "Please enter your email address.";
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) newErrors.email = "Please enter a valid email address.";
    if (!password) newErrors.password = "Please create a password.";
    else if (password.length < 8) newErrors.password = "Password must be at least 8 characters.";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!validateForm()) return;

    setLoading(true);
    setErrors({});

    try {
      await signUp(email, password, businessName.trim());

      // Store referral info for onboarding
      sessionStorage.setItem("businessName", businessName.trim());
      sessionStorage.setItem("referralAgencySlug", agencySlug || "");
      sessionStorage.setItem("selectedPlan", "base-200");

      toast({
        title: "Account created!",
        description: "Let's set up your business.",
      });
      navigate("/app/onboarding");
    } catch (err: any) {
      const message = err.message?.toLowerCase() || "";
      if (message.includes("already registered") || message.includes("already exists")) {
        setErrors({ email: "An account with this email already exists." });
      } else if (message.includes("email")) {
        setErrors({ email: "Please enter a valid email address." });
      } else if (message.includes("password")) {
        setErrors({ password: "Password is too weak. Try adding numbers or symbols." });
      } else {
        setErrors({ general: "Something went wrong. Please try again." });
      }
    } finally {
      setLoading(false);
    }
  };

  // Loading state
  if (resolving) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <Loader2 className="h-8 w-8 animate-spin text-primary" />
      </div>
    );
  }

  // Not found
  if (notFound) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background px-4">
        <Card className="max-w-sm w-full">
          <CardContent className="pt-8 pb-8 text-center space-y-4">
            <Building2 className="h-12 w-12 mx-auto text-muted-foreground" />
            <h2 className="text-xl font-semibold">Agency Not Found</h2>
            <p className="text-sm text-muted-foreground">
              The referral link you followed doesn't match any active agency partner. Please check the link and try again.
            </p>
            <Button asChild variant="outline">
              <Link to="/signup">Sign Up Directly</Link>
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-background px-4 py-12">
      <div className="w-full max-w-sm space-y-6">
        {/* Logo */}
        <div className="flex justify-center">
          <div className="flex items-center gap-2.5">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary">
              <AudioWaveform className="h-5 w-5 text-primary-foreground" />
            </div>
            <span className="text-xl font-bold">{BRAND.name}</span>
          </div>
        </div>

        {/* Agency Welcome */}
        <div className="text-center space-y-1">
          <p className="text-sm text-muted-foreground">Referred by</p>
          <h1 className="text-xl font-semibold">{agencyInfo?.agency_name}</h1>
          <p className="text-sm text-muted-foreground">
            Create your account to get started with AI-powered voice for your business.
          </p>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-5">
          <div className="space-y-2">
            <Label htmlFor="businessName">Business name</Label>
            <Input
              id="businessName"
              type="text"
              placeholder="Your Business Name"
              value={businessName}
              onChange={(e) => setBusinessName(e.target.value)}
              className="h-12 w-full"
              aria-invalid={!!errors.businessName}
            />
            {errors.businessName && (
              <p className="text-[13px] text-destructive">{errors.businessName}</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="email">Email</Label>
            <Input
              id="email"
              type="email"
              placeholder="you@yourbusiness.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="h-12 w-full"
              aria-invalid={!!errors.email}
            />
            {errors.email && (
              <p className="text-[13px] text-destructive">{errors.email}</p>
            )}
          </div>

          <div className="space-y-2">
            <Label htmlFor="password">Password</Label>
            <Input
              id="password"
              type="password"
              placeholder="At least 8 characters"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="h-12 w-full"
              aria-invalid={!!errors.password}
            />
            {errors.password && (
              <p className="text-[13px] text-destructive">{errors.password}</p>
            )}
          </div>

          {errors.general && (
            <p className="text-[13px] text-destructive">{errors.general}</p>
          )}

          <Button type="submit" className="w-full h-12 text-base font-medium" disabled={loading}>
            {loading ? (
              <>
                <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                Creating account...
              </>
            ) : (
              "Create Account"
            )}
          </Button>
        </form>

        <p className="text-center text-sm text-muted-foreground">
          Already have an account?{" "}
          <Link to="/login" className="text-primary font-medium hover:underline underline-offset-4">
            Sign in
          </Link>
        </p>
      </div>
    </div>
  );
}

import { useState, useEffect } from "react";
import { useParams, useSearchParams } from "react-router-dom";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Loader2,
  Calendar,
  FileText,
  FileCheck,
  Phone,
  Building2,
  AlertCircle,
  ShieldAlert,
  CalendarClock,
  X,
} from "lucide-react";
import { format, formatDistanceToNow } from "date-fns";
import { supabase } from "@/integrations/supabase/client";

interface TenantInfo {
  id: string;
  name: string;
  phone_public: string | null;
  address: string | null;
  website_url: string | null;
}

interface CustomerData {
  id: string;
  full_name: string | null;
  email: string | null;
  phone_e164: string | null;
}

interface Booking {
  id: string;
  start_at: string;
  status: string;
  notes: string | null;
  service_id: string | null;
}

interface Estimate {
  id: string;
  estimate_number: string;
  title: string | null;
  status: string;
  total_cents: number | null;
  created_at: string;
}

interface Agreement {
  id: string;
  agreement_number: string;
  plan_name: string;
  status: string;
  price_cents: number;
  billing_frequency: string;
  renewal_date: string | null;
}

function formatCurrency(cents: number | null): string {
  if (cents === null) return "—";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);
}

const statusColors: Record<string, string> = {
  confirmed: "bg-green-100 text-green-700",
  pending: "bg-yellow-100 text-yellow-700",
  completed: "bg-blue-100 text-blue-700",
  cancelled: "bg-red-100 text-red-700",
  draft: "bg-gray-100 text-gray-700",
  sent: "bg-blue-100 text-blue-700",
  accepted: "bg-green-100 text-green-700",
  declined: "bg-red-100 text-red-700",
  active: "bg-green-100 text-green-700",
  expired: "bg-red-100 text-red-700",
};

export default function CustomerPortalPage() {
  const { tenantId } = useParams<{ tenantId: string }>();
  const [searchParams] = useSearchParams();
  const customerToken = searchParams.get("token");

  const [isLoading, setIsLoading] = useState(true);
  const [tenant, setTenant] = useState<TenantInfo | null>(null);
  const [customer, setCustomer] = useState<CustomerData | null>(null);
  const [tokenError, setTokenError] = useState("");

  const [bookings, setBookings] = useState<Booking[]>([]);
  const [estimates, setEstimates] = useState<Estimate[]>([]);
  const [agreements, setAgreements] = useState<Agreement[]>([]);

  // Booking action dialogs
  const [cancelDialogOpen, setCancelDialogOpen] = useState(false);
  const [rescheduleDialogOpen, setRescheduleDialogOpen] = useState(false);
  const [selectedBooking, setSelectedBooking] = useState<Booking | null>(null);
  const [newDateTime, setNewDateTime] = useState("");
  const [actionLoading, setActionLoading] = useState(false);
  const [actionMessage, setActionMessage] = useState<{ type: "success" | "error"; text: string } | null>(null);

  // Load tenant info
  useEffect(() => {
    if (tenantId) {
      loadTenant();
    }
  }, [tenantId]);

  // If token provided, verify it via edge function
  useEffect(() => {
    if (customerToken && tenant) {
      verifyToken(customerToken);
    }
  }, [customerToken, tenant]);

  const loadTenant = async () => {
    try {
      const { data, error } = await supabase
        .from("tenants")
        .select("id, name, phone_public, address, website_url")
        .eq("id", tenantId)
        .single();

      if (error || !data) {
        console.error("Tenant not found:", error);
        setIsLoading(false);
        return;
      }

      setTenant(data);
    } catch (err) {
      console.error("Error loading tenant:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const verifyToken = async (token: string) => {
    try {
      const { data, error } = await supabase.functions.invoke("verify-portal-token", {
        body: { token, tenant_id: tenantId },
      });

      if (error) {
        setTokenError("Unable to verify your link. Please contact the business for a new one.");
        return;
      }

      if (data?.valid && data.customer) {
        setCustomer(data.customer);
        loadCustomerData(data.customer_id);
      } else {
        setTokenError(
          data?.error === "Token expired"
            ? "This link has expired. Please contact the business for a new one."
            : "Invalid portal link. Please contact the business for a new one."
        );
      }
    } catch (err) {
      console.error("Error verifying token:", err);
      setTokenError("Unable to verify your link. Please try again later.");
    }
  };

  const loadCustomerData = async (customerId: string) => {
    // Load bookings
    try {
      const { data: bookingsData } = await supabase
        .from("bookings")
        .select("id, start_at, status, notes, service_id")
        .eq("lead_id", customerId)
        .order("start_at", { ascending: false })
        .limit(20);

      if (bookingsData) setBookings(bookingsData as Booking[]);
    } catch (err) {
      console.error("Error loading bookings:", err);
    }

    // Load estimates
    try {
      const { data: estimatesData } = await supabase
        .from("estimates")
        .select("id, estimate_number, title, status, total_cents, created_at")
        .eq("customer_id", customerId)
        .order("created_at", { ascending: false })
        .limit(20);

      if (estimatesData) setEstimates(estimatesData);
    } catch (err) {
      console.error("Error loading estimates:", err);
    }

    // Load agreements
    try {
      const { data: agreementsData } = await supabase
        .from("service_agreements")
        .select("id, agreement_number, plan_name, status, price_cents, billing_frequency, renewal_date")
        .eq("customer_id", customerId)
        .order("created_at", { ascending: false })
        .limit(20);

      if (agreementsData) setAgreements(agreementsData);
    } catch (err) {
      console.error("Error loading agreements:", err);
    }
  };

  const handleBookingAction = async (action: "cancel" | "reschedule") => {
    if (!selectedBooking || !customerToken || !tenantId) return;
    setActionLoading(true);
    setActionMessage(null);

    try {
      const body: Record<string, string> = {
        token: customerToken,
        tenant_id: tenantId,
        booking_id: selectedBooking.id,
        action,
      };
      if (action === "reschedule" && newDateTime) {
        body.new_start_at = new Date(newDateTime).toISOString();
      }

      const { data, error } = await supabase.functions.invoke("portal-booking-action", { body });

      if (error || !data?.success) {
        setActionMessage({ type: "error", text: data?.error || "Something went wrong. Please try again." });
        return;
      }

      // Update local state
      setBookings((prev) =>
        prev.map((b) => {
          if (b.id !== selectedBooking.id) return b;
          if (action === "cancel") return { ...b, status: "cancelled" };
          return { ...b, start_at: newDateTime ? new Date(newDateTime).toISOString() : b.start_at, status: "pending" };
        }),
      );

      setActionMessage({
        type: "success",
        text: action === "cancel" ? "Booking cancelled successfully." : "Booking rescheduled. Awaiting confirmation.",
      });
      setCancelDialogOpen(false);
      setRescheduleDialogOpen(false);
      setSelectedBooking(null);
      setNewDateTime("");
    } catch (err) {
      console.error("Booking action error:", err);
      setActionMessage({ type: "error", text: "Unable to process your request. Please try again." });
    } finally {
      setActionLoading(false);
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
      </div>
    );
  }

  if (!tenant) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Card className="max-w-md w-full mx-4">
          <CardContent className="pt-6 text-center">
            <AlertCircle className="h-12 w-12 text-red-500 mx-auto mb-4" />
            <h2 className="text-xl font-bold mb-2">Portal Not Found</h2>
            <p className="text-muted-foreground">
              This customer portal doesn't exist or has been disabled.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-xl font-bold">{tenant.name}</h1>
              <p className="text-sm text-muted-foreground">Customer Portal</p>
            </div>
            {tenant.phone_public && (
              <a
                href={`tel:${tenant.phone_public}`}
                className="flex items-center gap-2 text-sm text-primary hover:underline"
              >
                <Phone className="h-4 w-4" />
                {tenant.phone_public}
              </a>
            )}
          </div>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 py-8">
        {/* Error state — invalid/expired token */}
        {tokenError ? (
          <Card className="max-w-md mx-auto">
            <CardContent className="pt-6 text-center space-y-4">
              <ShieldAlert className="h-12 w-12 text-amber-500 mx-auto" />
              <h2 className="text-lg font-bold">Portal Access Issue</h2>
              <p className="text-muted-foreground">{tokenError}</p>
              {tenant.phone_public && (
                <Button variant="outline" asChild>
                  <a href={`tel:${tenant.phone_public}`}>
                    <Phone className="h-4 w-4 mr-2" />
                    Call {tenant.name}
                  </a>
                </Button>
              )}
            </CardContent>
          </Card>
        ) : !customer && !customerToken ? (
          /* No token provided — show contact message */
          <Card className="max-w-md mx-auto">
            <CardHeader className="text-center">
              <Building2 className="h-12 w-12 text-primary mx-auto mb-2" />
              <CardTitle>Welcome to {tenant.name}</CardTitle>
              <CardDescription>
                Contact {tenant.name} to receive your personal portal link.
              </CardDescription>
            </CardHeader>
            <CardContent className="text-center space-y-4">
              {tenant.phone_public && (
                <Button variant="outline" asChild>
                  <a href={`tel:${tenant.phone_public}`}>
                    <Phone className="h-4 w-4 mr-2" />
                    Call {tenant.phone_public}
                  </a>
                </Button>
              )}
            </CardContent>
          </Card>
        ) : !customer ? (
          /* Token provided, still loading */
          <div className="flex items-center justify-center py-16">
            <Loader2 className="h-8 w-8 animate-spin text-gray-400" />
          </div>
        ) : (
          /* Customer Dashboard */
          <div className="space-y-6">
            {/* Welcome */}
            <Card>
              <CardContent className="pt-6">
                <div className="flex items-center justify-between">
                  <div>
                    <h2 className="text-2xl font-bold">
                      Welcome back, {customer.full_name?.split(" ")[0] || "there"}!
                    </h2>
                    <p className="text-muted-foreground">
                      Here's an overview of your account with {tenant.name}
                    </p>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Tabs */}
            <Tabs defaultValue="bookings">
              <TabsList className="grid w-full grid-cols-3">
                <TabsTrigger value="bookings" className="flex items-center gap-2">
                  <Calendar className="h-4 w-4" />
                  Bookings
                </TabsTrigger>
                <TabsTrigger value="estimates" className="flex items-center gap-2">
                  <FileText className="h-4 w-4" />
                  Estimates
                </TabsTrigger>
                <TabsTrigger value="agreements" className="flex items-center gap-2">
                  <FileCheck className="h-4 w-4" />
                  Agreements
                </TabsTrigger>
              </TabsList>

              {/* Bookings Tab */}
              <TabsContent value="bookings" className="mt-4">
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">Your Appointments</CardTitle>
                  </CardHeader>
                  <CardContent>
                    {bookings.length === 0 ? (
                      <p className="text-center text-muted-foreground py-8">
                        No appointments found.
                      </p>
                    ) : (
                      <div className="space-y-3">
                        {actionMessage && (
                          <div
                            className={`p-3 rounded-lg text-sm ${
                              actionMessage.type === "success"
                                ? "bg-green-50 text-green-700 border border-green-200"
                                : "bg-red-50 text-red-700 border border-red-200"
                            }`}
                          >
                            {actionMessage.text}
                          </div>
                        )}
                        {bookings.map((booking) => {
                          const canModify = ["pending", "confirmed"].includes(booking.status);
                          return (
                            <div
                              key={booking.id}
                              className="flex items-center justify-between p-4 border rounded-lg"
                            >
                              <div className="flex items-center gap-4">
                                <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
                                  <Calendar className="h-5 w-5 text-primary" />
                                </div>
                                <div>
                                  <p className="font-medium">Appointment</p>
                                  <p className="text-sm text-muted-foreground">
                                    {format(new Date(booking.start_at), "EEEE, MMMM d 'at' h:mm a")}
                                  </p>
                                </div>
                              </div>
                              <div className="flex items-center gap-2">
                                {canModify && (
                                  <>
                                    <Button
                                      variant="outline"
                                      size="sm"
                                      className="gap-1 text-xs"
                                      onClick={() => {
                                        setSelectedBooking(booking);
                                        setRescheduleDialogOpen(true);
                                        setActionMessage(null);
                                      }}
                                    >
                                      <CalendarClock className="h-3.5 w-3.5" />
                                      Reschedule
                                    </Button>
                                    <Button
                                      variant="outline"
                                      size="sm"
                                      className="gap-1 text-xs text-destructive hover:text-destructive"
                                      onClick={() => {
                                        setSelectedBooking(booking);
                                        setCancelDialogOpen(true);
                                        setActionMessage(null);
                                      }}
                                    >
                                      <X className="h-3.5 w-3.5" />
                                      Cancel
                                    </Button>
                                  </>
                                )}
                                <Badge className={statusColors[booking.status] || "bg-gray-100"}>
                                  {booking.status}
                                </Badge>
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </CardContent>
                </Card>
              </TabsContent>

              {/* Estimates Tab */}
              <TabsContent value="estimates" className="mt-4">
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">Your Estimates</CardTitle>
                  </CardHeader>
                  <CardContent>
                    {estimates.length === 0 ? (
                      <p className="text-center text-muted-foreground py-8">
                        No estimates found.
                      </p>
                    ) : (
                      <div className="space-y-3">
                        {estimates.map((estimate) => (
                          <div
                            key={estimate.id}
                            className="flex items-center justify-between p-4 border rounded-lg"
                          >
                            <div className="flex items-center gap-4">
                              <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
                                <FileText className="h-5 w-5 text-primary" />
                              </div>
                              <div>
                                <p className="font-medium">
                                  {estimate.title || estimate.estimate_number}
                                </p>
                                <p className="text-sm text-muted-foreground">
                                  {formatDistanceToNow(new Date(estimate.created_at), { addSuffix: true })}
                                </p>
                              </div>
                            </div>
                            <div className="text-right">
                              <p className="font-bold">{formatCurrency(estimate.total_cents)}</p>
                              <Badge className={statusColors[estimate.status] || "bg-gray-100"}>
                                {estimate.status}
                              </Badge>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </CardContent>
                </Card>
              </TabsContent>

              {/* Agreements Tab */}
              <TabsContent value="agreements" className="mt-4">
                <Card>
                  <CardHeader>
                    <CardTitle className="text-lg">Your Service Agreements</CardTitle>
                  </CardHeader>
                  <CardContent>
                    {agreements.length === 0 ? (
                      <p className="text-center text-muted-foreground py-8">
                        No service agreements found.
                      </p>
                    ) : (
                      <div className="space-y-3">
                        {agreements.map((agreement) => (
                          <div
                            key={agreement.id}
                            className="flex items-center justify-between p-4 border rounded-lg"
                          >
                            <div className="flex items-center gap-4">
                              <div className="h-10 w-10 rounded-full bg-primary/10 flex items-center justify-center">
                                <FileCheck className="h-5 w-5 text-primary" />
                              </div>
                              <div>
                                <p className="font-medium">{agreement.plan_name}</p>
                                <p className="text-sm text-muted-foreground">
                                  {agreement.renewal_date && (
                                    <>Renews {format(new Date(agreement.renewal_date), "MMM d, yyyy")}</>
                                  )}
                                </p>
                              </div>
                            </div>
                            <div className="text-right">
                              <p className="font-bold">
                                {formatCurrency(agreement.price_cents)}
                                <span className="text-sm font-normal text-muted-foreground">
                                  /{agreement.billing_frequency === "monthly" ? "mo" : agreement.billing_frequency === "quarterly" ? "qtr" : "yr"}
                                </span>
                              </p>
                              <Badge className={statusColors[agreement.status] || "bg-gray-100"}>
                                {agreement.status}
                              </Badge>
                            </div>
                          </div>
                        ))}
                      </div>
                    )}
                  </CardContent>
                </Card>
              </TabsContent>
            </Tabs>

            {/* Contact Card */}
            <Card>
              <CardContent className="pt-6">
                <div className="flex items-center justify-between">
                  <div>
                    <h3 className="font-medium">Need help?</h3>
                    <p className="text-sm text-muted-foreground">
                      Contact {tenant.name} directly
                    </p>
                  </div>
                  <div className="flex gap-2">
                    {tenant.phone_public && (
                      <Button variant="outline" size="sm" asChild>
                        <a href={`tel:${tenant.phone_public}`}>
                          <Phone className="h-4 w-4 mr-2" />
                          Call
                        </a>
                      </Button>
                    )}
                  </div>
                </div>
              </CardContent>
            </Card>
          </div>
        )}
      </main>

      {/* Cancel Booking Dialog */}
      <Dialog open={cancelDialogOpen} onOpenChange={setCancelDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Cancel Appointment</DialogTitle>
            <DialogDescription>
              Are you sure you want to cancel your appointment
              {selectedBooking
                ? ` on ${format(new Date(selectedBooking.start_at), "EEEE, MMMM d 'at' h:mm a")}`
                : ""}
              ?
            </DialogDescription>
          </DialogHeader>
          <DialogFooter className="gap-2 sm:gap-0">
            <Button
              variant="outline"
              onClick={() => setCancelDialogOpen(false)}
              disabled={actionLoading}
            >
              Keep Appointment
            </Button>
            <Button
              variant="destructive"
              onClick={() => handleBookingAction("cancel")}
              disabled={actionLoading}
            >
              {actionLoading ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : null}
              Cancel Appointment
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Reschedule Booking Dialog */}
      <Dialog open={rescheduleDialogOpen} onOpenChange={setRescheduleDialogOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Reschedule Appointment</DialogTitle>
            <DialogDescription>
              Choose a new date and time for your appointment.
              {selectedBooking && (
                <span className="block mt-1 text-foreground font-medium">
                  Current: {format(new Date(selectedBooking.start_at), "EEEE, MMMM d 'at' h:mm a")}
                </span>
              )}
            </DialogDescription>
          </DialogHeader>
          <div className="space-y-4 py-2">
            <div className="space-y-2">
              <Label htmlFor="new-datetime">New Date & Time</Label>
              <Input
                id="new-datetime"
                type="datetime-local"
                value={newDateTime}
                onChange={(e) => setNewDateTime(e.target.value)}
                min={format(new Date(), "yyyy-MM-dd'T'HH:mm")}
              />
            </div>
          </div>
          <DialogFooter className="gap-2 sm:gap-0">
            <Button
              variant="outline"
              onClick={() => {
                setRescheduleDialogOpen(false);
                setNewDateTime("");
              }}
              disabled={actionLoading}
            >
              Cancel
            </Button>
            <Button
              onClick={() => handleBookingAction("reschedule")}
              disabled={actionLoading || !newDateTime}
            >
              {actionLoading ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : null}
              Reschedule
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Footer */}
      <footer className="border-t mt-auto py-4 bg-white">
        <div className="max-w-4xl mx-auto px-4 text-center text-sm text-muted-foreground">
          Powered by CloseLoop
        </div>
      </footer>
    </div>
  );
}

import { useState, useEffect, useRef } from "react";
import { useParams } from "react-router-dom";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { supabase } from "@/integrations/supabase/client";
import {
  FileText,
  CheckCircle2,
  XCircle,
  Loader2,
  Building2,
  Calendar,
  DollarSign,
  Phone,
  Mail,
  AlertCircle,
} from "lucide-react";
import { format } from "date-fns";
import SignatureCanvas from "react-signature-canvas";

interface EstimateLineItem {
  id: string;
  name: string;
  description?: string;
  quantity: number;
  unit_price_cents: number;
  total_cents: number;
}

interface EstimateData {
  id: string;
  estimate_number: string;
  title: string | null;
  status: string;
  line_items: EstimateLineItem[];
  subtotal_cents: number | null;
  tax_rate_percent: number | null;
  tax_cents: number | null;
  discount_cents: number | null;
  total_cents: number | null;
  valid_until: string | null;
  customer_notes: string | null;
  terms_and_conditions: string | null;
  created_at: string;
  tenant: {
    business_name: string | null;
    phone: string | null;
    email: string | null;
  } | null;
  customer: {
    full_name: string | null;
    email: string | null;
    phone_e164: string | null;
  } | null;
}

function formatCurrency(cents: number | null): string {
  if (cents === null) return "$0.00";
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
  }).format(cents / 100);
}

export default function EstimateViewPage() {
  const { id } = useParams<{ id: string }>();
  const [estimate, setEstimate] = useState<EstimateData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [accepting, setAccepting] = useState(false);
  const [declining, setDeclining] = useState(false);
  const [showSignature, setShowSignature] = useState(false);
  const [signed, setSigned] = useState(false);
  const signatureRef = useRef<SignatureCanvas>(null);

  useEffect(() => {
    if (id) {
      fetchEstimate();
    }
  }, [id]);

  const fetchEstimate = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase.functions.invoke("estimate-public-view", {
        body: { estimate_id: id },
      });

      if (error) throw error;
      if (!data?.estimate) throw new Error("Estimate not found");

      setEstimate(data.estimate);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load estimate");
    } finally {
      setLoading(false);
    }
  };

  const handleAccept = async () => {
    if (!signatureRef.current || signatureRef.current.isEmpty()) {
      setShowSignature(true);
      return;
    }

    try {
      setAccepting(true);
      const signatureData = signatureRef.current.toDataURL();

      const { error } = await supabase.functions.invoke("estimate-public-action", {
        body: {
          estimate_id: id,
          action: "accept",
          signature_data: signatureData,
        },
      });

      if (error) throw error;

      setSigned(true);
      setEstimate((prev) => prev ? { ...prev, status: "accepted" } : null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to accept estimate");
    } finally {
      setAccepting(false);
    }
  };

  const handleDecline = async () => {
    try {
      setDeclining(true);

      const { error } = await supabase.functions.invoke("estimate-public-action", {
        body: {
          estimate_id: id,
          action: "decline",
        },
      });

      if (error) throw error;

      setEstimate((prev) => prev ? { ...prev, status: "declined" } : null);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to decline estimate");
    } finally {
      setDeclining(false);
    }
  };

  const clearSignature = () => {
    signatureRef.current?.clear();
  };

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center">
          <Loader2 className="h-8 w-8 animate-spin text-primary mx-auto mb-4" />
          <p className="text-muted-foreground">Loading estimate...</p>
        </div>
      </div>
    );
  }

  if (error || !estimate) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <Card className="max-w-md">
          <CardContent className="pt-6 text-center">
            <AlertCircle className="h-12 w-12 text-destructive mx-auto mb-4" />
            <h2 className="text-xl font-semibold mb-2">Estimate Not Found</h2>
            <p className="text-muted-foreground">{error || "This estimate may have expired or been removed."}</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  const isExpired = estimate.valid_until && new Date(estimate.valid_until) < new Date();
  const canRespond = estimate.status === "sent" || estimate.status === "viewed";
  const isAccepted = estimate.status === "accepted";
  const isDeclined = estimate.status === "declined";

  return (
    <div className="min-h-screen bg-gray-50 py-8 px-4">
      <div className="max-w-3xl mx-auto">
        {/* Header */}
        <div className="text-center mb-8">
          {estimate.tenant?.business_name && (
            <h1 className="text-2xl font-bold mb-2">{estimate.tenant.business_name}</h1>
          )}
          <p className="text-muted-foreground">Estimate #{estimate.estimate_number}</p>
        </div>

        {/* Status Banner */}
        {isAccepted && (
          <div className="bg-green-50 border border-green-200 rounded-lg p-4 mb-6 flex items-center gap-3">
            <CheckCircle2 className="h-6 w-6 text-green-600" />
            <div>
              <p className="font-medium text-green-800">Estimate Accepted</p>
              <p className="text-sm text-green-600">Thank you for your business!</p>
            </div>
          </div>
        )}

        {isDeclined && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6 flex items-center gap-3">
            <XCircle className="h-6 w-6 text-red-600" />
            <div>
              <p className="font-medium text-red-800">Estimate Declined</p>
              <p className="text-sm text-red-600">This estimate has been declined.</p>
            </div>
          </div>
        )}

        {isExpired && canRespond && (
          <div className="bg-orange-50 border border-orange-200 rounded-lg p-4 mb-6 flex items-center gap-3">
            <AlertCircle className="h-6 w-6 text-orange-600" />
            <div>
              <p className="font-medium text-orange-800">Estimate Expired</p>
              <p className="text-sm text-orange-600">This estimate has expired. Please contact us for an updated quote.</p>
            </div>
          </div>
        )}

        {/* Main Card */}
        <Card className="mb-6">
          <CardHeader>
            <div className="flex items-start justify-between">
              <div>
                <CardTitle className="flex items-center gap-2">
                  <FileText className="h-5 w-5" />
                  {estimate.title || "Service Estimate"}
                </CardTitle>
                <p className="text-sm text-muted-foreground mt-1">
                  Created {format(new Date(estimate.created_at), "MMMM d, yyyy")}
                </p>
              </div>
              <Badge variant={isAccepted ? "default" : isDeclined ? "destructive" : "secondary"}>
                {estimate.status.charAt(0).toUpperCase() + estimate.status.slice(1)}
              </Badge>
            </div>
          </CardHeader>
          <CardContent>
            {/* Customer Info */}
            {estimate.customer && (
              <div className="mb-6 p-4 bg-muted/50 rounded-lg">
                <p className="font-medium">{estimate.customer.full_name || "Customer"}</p>
                {estimate.customer.email && (
                  <p className="text-sm text-muted-foreground flex items-center gap-1">
                    <Mail className="h-3 w-3" /> {estimate.customer.email}
                  </p>
                )}
                {estimate.customer.phone_e164 && (
                  <p className="text-sm text-muted-foreground flex items-center gap-1">
                    <Phone className="h-3 w-3" /> {estimate.customer.phone_e164}
                  </p>
                )}
              </div>
            )}

            {/* Line Items */}
            <div className="mb-6">
              <h3 className="font-medium mb-3">Items & Services</h3>
              <div className="border rounded-lg overflow-hidden">
                <table className="w-full">
                  <thead className="bg-muted/50">
                    <tr className="text-sm">
                      <th className="text-left p-3">Description</th>
                      <th className="text-center p-3 w-20">Qty</th>
                      <th className="text-right p-3 w-28">Price</th>
                      <th className="text-right p-3 w-28">Total</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y">
                    {estimate.line_items.map((item) => (
                      <tr key={item.id}>
                        <td className="p-3">
                          <p className="font-medium">{item.name}</p>
                          {item.description && (
                            <p className="text-sm text-muted-foreground">{item.description}</p>
                          )}
                        </td>
                        <td className="p-3 text-center">{item.quantity}</td>
                        <td className="p-3 text-right">{formatCurrency(item.unit_price_cents)}</td>
                        <td className="p-3 text-right font-medium">{formatCurrency(item.total_cents)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>

            {/* Totals */}
            <div className="flex justify-end mb-6">
              <div className="w-64 space-y-2">
                <div className="flex justify-between text-sm">
                  <span>Subtotal</span>
                  <span>{formatCurrency(estimate.subtotal_cents)}</span>
                </div>
                {(estimate.discount_cents ?? 0) > 0 && (
                  <div className="flex justify-between text-sm text-green-600">
                    <span>Discount</span>
                    <span>-{formatCurrency(estimate.discount_cents)}</span>
                  </div>
                )}
                {(estimate.tax_cents ?? 0) > 0 && (
                  <div className="flex justify-between text-sm">
                    <span>Tax ({estimate.tax_rate_percent}%)</span>
                    <span>{formatCurrency(estimate.tax_cents)}</span>
                  </div>
                )}
                <Separator />
                <div className="flex justify-between font-bold text-lg">
                  <span>Total</span>
                  <span>{formatCurrency(estimate.total_cents)}</span>
                </div>
              </div>
            </div>

            {/* Valid Until */}
            {estimate.valid_until && (
              <div className="flex items-center gap-2 text-sm text-muted-foreground mb-6">
                <Calendar className="h-4 w-4" />
                <span>Valid until {format(new Date(estimate.valid_until), "MMMM d, yyyy")}</span>
              </div>
            )}

            {/* Customer Notes */}
            {estimate.customer_notes && (
              <div className="mb-6">
                <h3 className="font-medium mb-2">Notes</h3>
                <p className="text-sm text-muted-foreground whitespace-pre-wrap">{estimate.customer_notes}</p>
              </div>
            )}

            {/* Terms */}
            {estimate.terms_and_conditions && (
              <div className="mb-6">
                <h3 className="font-medium mb-2">Terms & Conditions</h3>
                <p className="text-xs text-muted-foreground whitespace-pre-wrap">{estimate.terms_and_conditions}</p>
              </div>
            )}
          </CardContent>
        </Card>

        {/* Signature Section */}
        {showSignature && canRespond && !isExpired && (
          <Card className="mb-6">
            <CardHeader>
              <CardTitle className="text-lg">Sign to Accept</CardTitle>
            </CardHeader>
            <CardContent>
              <p className="text-sm text-muted-foreground mb-4">
                Please sign below to accept this estimate. Your signature indicates agreement to the terms and pricing above.
              </p>
              <div className="border rounded-lg bg-white mb-4">
                <SignatureCanvas
                  ref={signatureRef}
                  canvasProps={{
                    className: "w-full h-40",
                    style: { width: "100%", height: "160px" },
                  }}
                  backgroundColor="white"
                />
              </div>
              <div className="flex gap-2">
                <Button variant="outline" size="sm" onClick={clearSignature}>
                  Clear
                </Button>
              </div>
            </CardContent>
          </Card>
        )}

        {/* Action Buttons */}
        {canRespond && !isExpired && (
          <div className="flex gap-4 justify-center">
            <Button
              size="lg"
              variant="outline"
              onClick={handleDecline}
              disabled={declining || accepting}
              className="min-w-32"
            >
              {declining ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : (
                <XCircle className="h-4 w-4 mr-2" />
              )}
              Decline
            </Button>
            <Button
              size="lg"
              onClick={handleAccept}
              disabled={accepting || declining}
              className="min-w-32"
            >
              {accepting ? (
                <Loader2 className="h-4 w-4 animate-spin mr-2" />
              ) : (
                <CheckCircle2 className="h-4 w-4 mr-2" />
              )}
              {showSignature ? "Submit Signature" : "Accept Estimate"}
            </Button>
          </div>
        )}

        {/* Contact Info */}
        {estimate.tenant && (estimate.tenant.phone || estimate.tenant.email) && (
          <div className="mt-8 text-center text-sm text-muted-foreground">
            <p>Questions? Contact us:</p>
            <div className="flex items-center justify-center gap-4 mt-2">
              {estimate.tenant.phone && (
                <a href={`tel:${estimate.tenant.phone}`} className="flex items-center gap-1 hover:text-primary">
                  <Phone className="h-4 w-4" /> {estimate.tenant.phone}
                </a>
              )}
              {estimate.tenant.email && (
                <a href={`mailto:${estimate.tenant.email}`} className="flex items-center gap-1 hover:text-primary">
                  <Mail className="h-4 w-4" /> {estimate.tenant.email}
                </a>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from "react";
import { Link } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { AudioWaveform, Loader2, ArrowLeft, CheckCircle2 } from "lucide-react";
import { BRAND } from "@/config/brand";

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email.trim()) return;

    setLoading(true);
    setError(null);

    try {
      const { error: resetError } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: window.location.origin + "/login",
      });
      if (resetError) throw resetError;
      setSent(true);
    } catch (err: any) {
      setError(err.message || "Something went wrong. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex">
      {/* Left Brand Panel -- hidden on mobile */}
      <div className="hidden md:flex md:w-[40%] flex-col justify-center items-center px-12 bg-gradient-to-br from-primary/90 to-primary/70 relative overflow-hidden">
        <div className="absolute inset-0 bg-[radial-gradient(circle_at_30%_50%,hsl(172_75%_50%/0.15),transparent_70%)]" />
        <div className="relative z-10 text-center space-y-6">
          <div className="inline-flex h-16 w-16 items-center justify-center rounded-2xl bg-white/15 backdrop-blur-sm border border-white/20">
            <AudioWaveform className="h-8 w-8 text-white" />
          </div>
          <h1 className="text-3xl font-bold text-white">{BRAND.name}</h1>
          <p className="text-white/80 text-lg max-w-xs">{BRAND.tagline}</p>
        </div>
      </div>

      {/* Right Form Panel */}
      <div className="flex-1 flex items-center justify-center px-6 bg-card">
        <div className="w-full max-w-sm">
          {/* Mobile logo */}
          <div className="flex justify-center mb-8 md:hidden">
            <div className="flex items-center gap-2.5">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary">
                <AudioWaveform className="h-5 w-5 text-primary-foreground" />
              </div>
              <span className="text-xl font-bold">{BRAND.name}</span>
            </div>
          </div>

          {sent ? (
            <div className="text-center space-y-4">
              <div className="flex justify-center">
                <div className="flex h-14 w-14 items-center justify-center rounded-full bg-primary/10">
                  <CheckCircle2 className="h-7 w-7 text-primary" />
                </div>
              </div>
              <h1 className="text-2xl font-semibold">Check your email</h1>
              <p className="text-muted-foreground">
                We sent a password reset link to <span className="font-medium text-foreground">{email}</span>.
                Check your inbox and follow the instructions.
              </p>
              <Link to="/login">
                <Button variant="outline" className="mt-4 gap-2">
                  <ArrowLeft className="h-4 w-4" />
                  Back to Sign In
                </Button>
              </Link>
            </div>
          ) : (
            <>
              <h1 className="text-2xl font-semibold text-center mb-2">
                Reset your password
              </h1>
              <p className="text-center text-muted-foreground mb-8">
                Enter your email and we'll send you a reset link.
              </p>

              <form onSubmit={handleSubmit} className="space-y-5">
                <div className="space-y-2">
                  <Label htmlFor="email">Email</Label>
                  <Input
                    id="email"
                    type="email"
                    placeholder="you@example.com"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    className="h-12 w-full"
                  />
                </div>

                {error && (
                  <p className="text-[13px] text-destructive">{error}</p>
                )}

                <Button
                  type="submit"
                  className="w-full h-12 text-base font-medium"
                  disabled={loading}
                >
                  {loading ? (
                    <>
                      <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                      Sending...
                    </>
                  ) : (
                    "Send Reset Link"
                  )}
                </Button>
              </form>

              <p className="mt-8 text-center text-sm text-muted-foreground">
                <Link
                  to="/login"
                  className="text-primary font-medium hover:underline underline-offset-4 inline-flex items-center gap-1"
                >
                  <ArrowLeft className="h-3 w-3" />
                  Back to Sign In
                </Link>
              </p>
            </>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "@/contexts/AuthContext";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { AudioWaveform, Loader2 } from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import { BRAND } from "@/config/brand";
import { supabase } from "@/integrations/supabase/client";

export default function LoginPage() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { signIn } = useAuth();
  const navigate = useNavigate();
  const { toast } = useToast();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      await signIn(email, password);

      // Check user type to redirect appropriately
      const { data: { user } } = await supabase.auth.getUser();
      if (user) {
        // 1. Check super_admin
        const { data: roleData } = await supabase
          .from("user_roles")
          .select("role")
          .eq("user_id", user.id)
          .eq("role", "super_admin")
          .maybeSingle();

        if (roleData?.role === "super_admin") {
          navigate("/admin/dashboard");
          return;
        }

        // 2. Check agency user
        const { data: agencyData } = await supabase
          .from("agency_accounts")
          .select("id")
          .eq("user_id", user.id)
          .limit(1);

        if (agencyData && agencyData.length > 0) {
          navigate("/app/agency");
          return;
        }

        // 3. Default: regular tenant user
        navigate("/app/dashboard");
      } else {
        navigate("/app/dashboard");
      }
    } catch (err: any) {
      const message = err.message?.toLowerCase() || "";
      if (message.includes("invalid") || message.includes("credentials")) {
        setError("Invalid email or password. Please try again.");
      } else if (message.includes("not found")) {
        setError("No account found with this email.");
      } else {
        setError("Something went wrong. Please try again.");
      }
      toast({
        variant: "destructive",
        title: "Sign in failed",
        description: "Please check your credentials and try again.",
      });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-[calc(100vh-4rem)] md:min-h-screen flex">
      {/* Left Brand Panel — hidden on mobile */}
      <div className="dark hidden md:flex md:w-[45%] flex-col justify-center items-center px-12 relative overflow-hidden bg-gradient-to-br from-[hsl(230,50%,12%)] via-[hsl(240,40%,10%)] to-[hsl(260,30%,8%)]">
        {/* Spotlight glow */}
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_60%_50%_at_50%_30%,hsl(230_70%_62%/0.2),transparent)] pointer-events-none" />
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_40%_40%_at_20%_80%,hsl(280_60%_55%/0.08),transparent)] pointer-events-none" />
        {/* Grid pattern */}
        <div className="absolute inset-0 bg-[linear-gradient(hsl(0_0%_100%/0.03)_1px,transparent_1px),linear-gradient(90deg,hsl(0_0%_100%/0.03)_1px,transparent_1px)] bg-[size:48px_48px] pointer-events-none" />

        <div className="relative z-10 text-center space-y-8 max-w-sm">
          <div className="inline-flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/15 backdrop-blur-md border border-primary/20 glow-primary-sm">
            <AudioWaveform className="h-8 w-8 text-primary" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-foreground mb-3">{BRAND.name}</h1>
            <p className="text-muted-foreground text-lg leading-relaxed">{BRAND.tagline}</p>
          </div>
          <div className="pt-4 flex flex-col gap-3.5">
            {["Answer calls 24/7", "Book appointments automatically", "Capture every lead"].map((text) => (
              <div key={text} className="flex items-center gap-3 text-muted-foreground/80 text-sm">
                <div className="h-5 w-5 rounded-full bg-primary/10 border border-primary/20 flex items-center justify-center shrink-0">
                  <div className="h-1.5 w-1.5 rounded-full bg-primary" />
                </div>
                {text}
              </div>
            ))}
          </div>
          <p className="text-muted-foreground/40 text-xs pt-6">Trusted by 500+ local businesses</p>
        </div>
      </div>

      {/* Right Form Panel */}
      <div className="flex-1 flex items-center justify-center px-6 bg-background">
        <div className="w-full max-w-[380px]">
          {/* Mobile logo */}
          <div className="flex justify-center mb-8 md:hidden">
            <div className="flex items-center gap-2.5">
              <div className="flex h-10 w-10 items-center justify-center rounded-xl bg-primary">
                <AudioWaveform className="h-5 w-5 text-primary-foreground" />
              </div>
              <span className="text-xl font-bold">{BRAND.name}</span>
            </div>
          </div>

          <div className="text-center mb-8">
            <h1 className="text-2xl font-semibold mb-1.5">
              Welcome back
            </h1>
            <p className="text-sm text-muted-foreground">Sign in to your account to continue</p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="space-y-2">
              <Label htmlFor="email">Email</Label>
              <Input
                id="email"
                type="email"
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                className="h-12 w-full"
              />
            </div>

            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label htmlFor="password">Password</Label>
                <Link
                  to="/forgot-password"
                  className="text-sm text-muted-foreground hover:text-primary transition-colors"
                >
                  Forgot?
                </Link>
              </div>
              <Input
                id="password"
                type="password"
                placeholder="••••••••"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                className="h-12 w-full"
              />
            </div>

            {error && (
              <p className="text-[13px] text-destructive">{error}</p>
            )}

            <Button
              type="submit"
              className="w-full h-12 text-base font-medium"
              disabled={loading}
            >
              {loading ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Signing in...
                </>
              ) : (
                "Sign In"
              )}
            </Button>
          </form>

          <p className="mt-8 text-center text-sm text-muted-foreground">
            Don't have an account?{" "}
            <Link
              to="/signup"
              className="text-primary font-medium hover:underline underline-offset-4"
            >
              Sign up
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
}

import { useState } from "react";
import { Link } from "react-router-dom";
import { Shield, CreditCard, Check, ArrowRight, Phone, MapPin, Plus, Minus, Mail, Zap } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import {
  TIERS,
  LADDER_STEPS,
  LOCATION_ADD_ONS,
  INCLUDED_IN_ALL_PLANS,
  formatPrice,
  calculateMonthlyTotal,
  type PlanSku,
} from "@/config/pricing";

export default function PricingPage() {
  const [selectedSku, setSelectedSku] = useState<PlanSku>("base-200");
  const [additionalLocations, setAdditionalLocations] = useState(0);

  const selectedStep = LADDER_STEPS.find((s) => s.sku === selectedSku);
  const tierInfo = TIERS[0];
  const monthlyTotal = calculateMonthlyTotal(selectedSku, additionalLocations);
  
  const selfServeSteps = LADDER_STEPS.filter((s) => !s.isEnterprise);
  const enterpriseStep = LADDER_STEPS.find((s) => s.isEnterprise);

  const handleLocationChange = (delta: number) => {
    setAdditionalLocations(Math.max(0, additionalLocations + delta));
  };

  return (
    <div className="py-20 md:py-28 relative overflow-hidden">
      {/* Background accents */}
      <div className="absolute inset-0 bg-[radial-gradient(ellipse_50%_50%_at_50%_0%,hsl(230_70%_62%/0.08),transparent)] pointer-events-none" />

      <div className="container relative">
        {/* Header */}
        <div className="text-center mb-16">
          <Badge variant="secondary" className="mb-5 gap-1.5 px-4 py-1.5 text-xs backdrop-blur-sm bg-primary/[0.06] border-primary/20">
            <Zap className="h-3 w-3" />
            Simple Pricing
          </Badge>
          <h1 className="text-4xl md:text-5xl lg:text-[3.5rem] font-extrabold tracking-tight mb-5 leading-[1.1]">
            One Platform,{" "}
            <span className="text-gradient-primary">Flexible Plans</span>
          </h1>
          <p className="text-lg text-muted-foreground/80 max-w-2xl mx-auto leading-relaxed">
            Start with the base plan and scale as you grow. All minutes are pooled across your locations.
          </p>
        </div>

        {/* Trust badges */}
        <div className="flex flex-wrap justify-center gap-4 sm:gap-6 mb-16">
          {[
            { icon: Shield, text: "Cancel anytime" },
            { icon: CreditCard, text: "Secure payment" },
            { icon: Phone, text: "Unlimited simultaneous calls" },
          ].map(({ icon: TrustIcon, text }) => (
            <div key={text} className="inline-flex items-center gap-2.5 px-4 py-2 rounded-full bg-card/40 backdrop-blur-sm border border-border/30 text-sm text-muted-foreground/80">
              <TrustIcon className="h-3.5 w-3.5 text-primary" />
              <span>{text}</span>
            </div>
          ))}
        </div>

        {/* Main Pricing Card */}
        <div className="max-w-2xl mx-auto mb-14">
          <div className="relative rounded-xl bg-card/70 backdrop-blur-sm border border-primary/40 shadow-[0_0_60px_-12px_hsl(230_70%_62%/0.2)] transition-all">
            <div className="absolute -top-3 left-1/2 -translate-x-1/2">
              <Badge className="bg-primary text-primary-foreground gap-1.5 px-4 py-1 shadow-[0_0_20px_-4px_hsl(230_70%_62%/0.4)]">
                <Phone className="h-3 w-3" />
                AI Voice Receptionist
              </Badge>
            </div>

            <div className="px-6 pb-4 pt-8">
              <div className="flex h-12 w-12 items-center justify-center rounded-xl mb-4 bg-primary text-primary-foreground glow-primary-sm">
                <Phone className="h-6 w-6" />
              </div>
              <h3 className="text-xl font-semibold">{tierInfo.displayName}</h3>
              <p className="text-sm text-muted-foreground">{tierInfo.shortDescription}</p>
            </div>

            <div className="px-6 pb-6 space-y-6">
              {/* Minute Bundle Selection */}
              <div className="space-y-3">
                <Label className="text-base font-medium">Choose your monthly minute bundle</Label>
                <RadioGroup
                  value={selectedSku}
                  onValueChange={(value) => setSelectedSku(value as PlanSku)}
                  className="space-y-2"
                >
                  {selfServeSteps.map((step) => (
                    <div
                      key={step.sku}
                      className={`flex items-center justify-between p-4 rounded-xl border cursor-pointer transition-all duration-150 ${
                        selectedSku === step.sku
                          ? "border-primary bg-primary/5 shadow-sm shadow-primary/5"
                          : "border-border/60 hover:border-primary/30"
                      }`}
                      onClick={() => setSelectedSku(step.sku)}
                    >
                      <div className="flex items-center gap-3">
                        <RadioGroupItem value={step.sku} id={step.sku} />
                        <Label htmlFor={step.sku} className="cursor-pointer font-normal">
                          <div className="font-medium">{step.name}</div>
                          <div className="text-sm text-muted-foreground">
                            {step.includedMinutes?.toLocaleString()} pooled minutes
                          </div>
                        </Label>
                      </div>
                      <div className="text-right">
                        <span className="font-bold text-lg">{formatPrice(step.price)}</span>
                        <span className="text-sm text-muted-foreground">/mo</span>
                      </div>
                    </div>
                  ))}
                </RadioGroup>
                {selectedStep && (
                  <p className="text-sm text-muted-foreground">
                    Overage rate: ${selectedStep.overageMinuteRate}/min over included
                  </p>
                )}
              </div>

              {/* Multi-location Add-on */}
              <div className="p-4 rounded-xl border border-border/50 bg-muted/30">
                <div className="flex items-center justify-between mb-2">
                  <div className="flex items-center gap-2">
                    <MapPin className="h-4 w-4 text-primary" />
                    <Label className="font-medium">Locations</Label>
                  </div>
                  <Badge variant="secondary">+${LOCATION_ADD_ONS.voice}/mo each</Badge>
                </div>
                <p className="text-sm text-muted-foreground mb-3">
                  Base plan includes 1 location with a dedicated number.
                </p>
                <div className="flex items-center gap-3">
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={() => handleLocationChange(-1)}
                    disabled={additionalLocations === 0}
                  >
                    <Minus className="h-4 w-4" />
                  </Button>
                  <span className="w-24 text-center font-medium">
                    {additionalLocations + 1} location{additionalLocations > 0 ? "s" : ""}
                  </span>
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={() => handleLocationChange(1)}
                  >
                    <Plus className="h-4 w-4" />
                  </Button>
                </div>
              </div>

              {/* Features */}
              <ul className="space-y-2">
                {tierInfo.features.slice(0, 5).map((feature, i) => (
                  <li key={i} className="flex items-start gap-2 text-sm">
                    <Check className="h-4 w-4 text-primary shrink-0 mt-0.5" />
                    <span>{feature}</span>
                  </li>
                ))}
              </ul>

              {/* Monthly Total */}
              <div className="p-4 rounded-xl bg-primary/10 border border-primary/20">
                <div className="flex items-center justify-between mb-1">
                  <span className="font-medium">Monthly Total</span>
                  <span className="text-2xl font-bold">{formatPrice(monthlyTotal)}</span>
                </div>
                <div className="text-sm text-muted-foreground">
                  {selectedStep?.includedMinutes?.toLocaleString()} minutes • {additionalLocations + 1} location{additionalLocations > 0 ? "s" : ""}
                </div>
              </div>

              {/* CTA */}
              <Link to={`/signup?sku=${selectedSku}&locations=${additionalLocations}`}>
                <Button
                  className="w-full gap-2 shadow-[0_0_20px_-6px_hsl(230_70%_62%/0.3)]"
                  variant="default"
                  size="lg"
                >
                  Get Started
                  <ArrowRight className="h-4 w-4" />
                </Button>
              </Link>
            </div>
          </div>
        </div>

        {/* Enterprise */}
        {enterpriseStep && (
          <div className="max-w-2xl mx-auto mb-14">
            <div className="rounded-xl border border-dashed border-border/40 bg-card/40 backdrop-blur-sm p-6">
              <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                <div>
                  <h3 className="font-semibold text-lg">{enterpriseStep.name}</h3>
                  <p className="text-muted-foreground">
                    {enterpriseStep.shortName} with custom pricing and dedicated support
                  </p>
                </div>
                <a href="mailto:sales@closeloop.com?subject=Enterprise%20Inquiry">
                  <Button variant="outline" className="gap-2">
                    <Mail className="h-4 w-4" />
                    Talk to Sales
                  </Button>
                </a>
              </div>
            </div>
          </div>
        )}

        {/* Included in all plans */}
        <div className="max-w-4xl mx-auto text-center mb-14 p-8 rounded-2xl bg-card/40 backdrop-blur-sm border border-border/30">
          <h3 className="font-semibold mb-5">Included in all plans</h3>
          <div className="flex flex-wrap justify-center gap-x-6 gap-y-3 text-sm">
            {INCLUDED_IN_ALL_PLANS.map((item, i) => (
              <div key={i} className="flex items-center gap-2 text-muted-foreground/80">
                <Check className="h-4 w-4 text-primary" />
                <span>{item}</span>
              </div>
            ))}
          </div>
        </div>

        {/* FAQ Section */}
        <div className="max-w-3xl mx-auto">
          <h2 className="text-2xl font-bold text-center mb-12 tracking-tight">Frequently asked questions</h2>
          <div className="space-y-6">
            {[
              {
                q: "What does 'pooled minutes' mean?",
                a: "Your included minutes are shared across all your locations. For example, if you have 2,000 minutes and 3 locations, any location can use from that shared pool.",
              },
              {
                q: "Can I change plans later?",
                a: "Absolutely. You can upgrade to a higher minute bundle at any time. Changes take effect on your next billing cycle.",
              },
              {
                q: "What if I go over my included limits?",
                a: "Your service continues uninterrupted. You'll be billed for overages at the rates shown. If you consistently exceed limits, upgrading often saves money.",
              },
              {
                q: "What does the AI Receptionist do?",
                a: "The AI answers your calls 24/7, qualifies leads, captures customer information, handles common objections, and can push callers to your booking system.",
              },
              {
                q: "Can I add more locations later?",
                a: "Yes! You can add additional locations anytime from your billing settings. Each location is $99/mo and includes a dedicated phone number.",
              },
            ].map((faq) => (
              <div key={faq.q} className="p-5 rounded-xl bg-card/40 backdrop-blur-sm border border-border/20">
                <h3 className="font-semibold mb-2">{faq.q}</h3>
                <p className="text-muted-foreground/80 text-sm leading-relaxed">{faq.a}</p>
              </div>
            ))}
          </div>
        </div>

        {/* Final CTA */}
        <div className="text-center mt-20">
          <Link to="/signup">
            <Button size="lg" className="gap-2.5 h-14 px-10 text-lg font-semibold shadow-[0_0_40px_-8px_hsl(230_70%_62%/0.4)] hover:shadow-[0_0_50px_-6px_hsl(230_70%_62%/0.5)] hover:scale-[1.02] transition-all duration-300">
              Get Started
              <ArrowRight className="h-5 w-5" />
            </Button>
          </Link>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Phone, Calendar, DollarSign, TrendingUp, Truck, ShoppingBag } from "lucide-react";

interface ROIData {
  tenant_name: string;
  business_mode: string;
  total_calls: number;
  bookings_created: number;
  dispatch_jobs_created: number;
  food_orders_created: number;
  total_revenue_cents: number;
  conversion_rate: number;
}

const modeTerms: Record<string, { entity: string; entityIcon: typeof Calendar }> = {
  service: { entity: "appointments", entityIcon: Calendar },
  dispatch: { entity: "jobs", entityIcon: Truck },
  food: { entity: "orders", entityIcon: ShoppingBag },
  medical: { entity: "appointments", entityIcon: Calendar },
  general: { entity: "conversions", entityIcon: TrendingUp },
};

export default function PublicROIReportPage() {
  const { tenantId, shareToken } = useParams<{ tenantId: string; shareToken: string }>();
  const [data, setData] = useState<ROIData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchROI() {
      if (!tenantId || !shareToken) {
        setError("Invalid share link");
        setLoading(false);
        return;
      }

      try {
        const response = await supabase.functions.invoke("public-roi-report", {
          body: { tenant_id: tenantId, share_token: shareToken },
        });

        if (response.error) {
          setError(response.error.message || "Failed to load report");
          return;
        }

        setData(response.data as ROIData);
      } catch (err: any) {
        setError(err.message || "Failed to load report");
      } finally {
        setLoading(false);
      }
    }

    fetchROI();
  }, [tenantId, shareToken]);

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900 flex items-center justify-center">
        <div className="animate-pulse text-muted-foreground">Loading report...</div>
      </div>
    );
  }

  if (error || !data) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900 flex items-center justify-center">
        <Card className="max-w-md w-full mx-4">
          <CardContent className="p-8 text-center">
            <p className="text-sm text-muted-foreground">{error || "Report not found"}</p>
          </CardContent>
        </Card>
      </div>
    );
  }

  const terms = modeTerms[data.business_mode] || modeTerms.general;
  const EntityIcon = terms.entityIcon;
  const totalEntities = data.bookings_created + data.dispatch_jobs_created + data.food_orders_created;
  const revenueDollars = data.total_revenue_cents / 100;
  const roiMultiplier = revenueDollars > 0 && data.total_calls > 0
    ? Math.round(revenueDollars / (data.total_calls * 2)) // Rough cost per call estimate
    : 0;

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-slate-100 dark:from-slate-950 dark:to-slate-900">
      <div className="container max-w-2xl py-12 px-4">
        {/* Header */}
        <div className="text-center space-y-3 mb-10">
          <Badge variant="secondary" className="text-xs">AI Performance Report</Badge>
          <h1 className="text-3xl font-bold tracking-tight">{data.tenant_name}</h1>
          <p className="text-muted-foreground">
            See how AI is handling calls and driving revenue
          </p>
        </div>

        {/* Hero Stat */}
        <Card className="mb-6 border-primary/20 bg-primary/5">
          <CardContent className="p-8 text-center">
            <p className="text-sm text-muted-foreground mb-2">Total Revenue from AI Calls</p>
            <p className="text-5xl font-bold text-primary">
              ${revenueDollars.toLocaleString()}
            </p>
            {roiMultiplier > 1 && (
              <p className="text-sm text-muted-foreground mt-2">
                {roiMultiplier}x return on investment
              </p>
            )}
          </CardContent>
        </Card>

        {/* Stats Grid */}
        <div className="grid grid-cols-2 gap-4 mb-8">
          <Card>
            <CardContent className="p-6 text-center">
              <Phone className="h-6 w-6 mx-auto text-blue-600 mb-2" />
              <p className="text-2xl font-bold">{data.total_calls.toLocaleString()}</p>
              <p className="text-xs text-muted-foreground">Calls Handled</p>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-6 text-center">
              <EntityIcon className="h-6 w-6 mx-auto text-emerald-600 mb-2" />
              <p className="text-2xl font-bold">{totalEntities.toLocaleString()}</p>
              <p className="text-xs text-muted-foreground capitalize">{terms.entity} Booked</p>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-6 text-center">
              <TrendingUp className="h-6 w-6 mx-auto text-purple-600 mb-2" />
              <p className="text-2xl font-bold">{Math.round(data.conversion_rate * 100)}%</p>
              <p className="text-xs text-muted-foreground">Conversion Rate</p>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-6 text-center">
              <DollarSign className="h-6 w-6 mx-auto text-amber-600 mb-2" />
              <p className="text-2xl font-bold">
                ${data.total_calls > 0 ? Math.round(revenueDollars / data.total_calls).toLocaleString() : 0}
              </p>
              <p className="text-xs text-muted-foreground">Revenue per Call</p>
            </CardContent>
          </Card>
        </div>

        {/* CTA */}
        <Card>
          <CardContent className="p-6 text-center space-y-3">
