/**
 * Distance tier interface matching frontend DispatchPricingConfig
 */
interface DistanceTier {
  min_miles: number;
  max_miles: number | null;
  base_price: number;
  per_mile_price?: number;
}

interface PackageTier {
  name: string;
  price: number;
  description?: string;
  is_popular?: boolean;
}

interface TripFee {
  enabled: boolean;
  amount: number;
  label: string;
  waived_with_service?: boolean;
}

interface PricingConfigJson {
  pricing_model: string;
  distance_basis?: string;
  distance_tiers?: DistanceTier[];
  // deno-lint-ignore no-explicit-any
  variables?: Array<{ key: string; label: string; modifiers: any[] }>;
  min_price?: number;
  max_price?: number;
  included_miles?: number;
  overage_per_mile?: number;
  trip_fee?: TripFee;
  unit_label?: string;
  per_unit_price?: number;
  min_units?: number;
  max_units?: number;
  packages?: PackageTier[];
  ai_quote_behavior?: string;
}

/**
 * Compute dispatch job price using the service's pricing_config_json (single source of truth).
 * Falls back to pricingResolution (pricing_rules_jsonb) for tenants not yet migrated.
 * Optionally calls compute-distance-eta for real distance if addresses provided.
 * Now applies price_modifiers from DB (previously bookings-only).
 */
export async function computeDispatchPrice(
  // deno-lint-ignore no-explicit-any
  supabase: any,
  supabaseUrl: string,
  supabaseKey: string,
  tenantId: string,
  pickupAddress: string | null,
  dropoffAddress: string | null,
  jobType: string | null,
  urgency: string,
  serviceId?: string | null
): Promise<DispatchPriceResult> {
  const defaultResult: DispatchPriceResult = {
    price_cents: null,
    price_breakdown: { method: "none", reason: "insufficient_data" },
    distance_miles: null,
    estimated_eta_minutes: null,
  };

  // Fetch services, distance settings, and price_modifiers in parallel
  const [servicesResult, distSettingsResult, modifiersResult] = await Promise.all([
    supabase
      .from("services")
      .select("id, name, price_amount, price_type, pricing_config_json, service_category")
      .eq("tenant_id", tenantId)
      .eq("is_active", true),
    supabase
      .from("tenant_distance_settings")
      .select("default_distance_basis")
      .eq("tenant_id", tenantId)
      .maybeSingle(),
    supabase
      .from("price_modifiers")
      .select("*")
      .eq("tenant_id", tenantId)
      .eq("is_active", true),
  ]);

  const allServices = servicesResult.data || [];

  // Find the matching service — by ID, by name match, or by category
  // deno-lint-ignore no-explicit-any
  let matchedService: any = null;
  if (serviceId) {
    // deno-lint-ignore no-explicit-any
    matchedService = allServices.find((s: any) => s.id === serviceId);
  }
  if (!matchedService && jobType) {
    // Try name match
    const normalizedJobType = jobType.toLowerCase();
    matchedService = allServices.find(
      // deno-lint-ignore no-explicit-any
      (s: any) => s.name.toLowerCase().includes(normalizedJobType)
    ) || allServices.find(
      // deno-lint-ignore no-explicit-any
      (s: any) => normalizedJobType.includes(s.name.toLowerCase())
    );
  }
  if (!matchedService) {
    // Fallback: first towing service
    matchedService = allServices.find(
      // deno-lint-ignore no-explicit-any
      (s: any) => s.service_category === "towing" || s.name.toLowerCase().includes("tow")
    ) || allServices[0];
  }

  const pricingConfig: PricingConfigJson | null =
    matchedService?.pricing_config_json &&
    typeof matchedService.pricing_config_json === "object"
      ? matchedService.pricing_config_json as PricingConfigJson
      : null;

  // Try to get distance if both addresses are provided
  let distanceMiles: number | null = null;
  let etaMinutes: number | null = null;

  if (pickupAddress && dropoffAddress) {
    try {
      const distanceResponse = await fetch(`${supabaseUrl}/functions/v1/compute-distance-eta`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${supabaseKey}`,
        },
        body: JSON.stringify({
          tenant_id: tenantId,
          pickup_address: pickupAddress,
          dropoff_address: dropoffAddress,
        }),
      });

      if (distanceResponse.ok) {
        const distanceData = await distanceResponse.json();
        distanceMiles = distanceData.distance_miles ?? distanceData.distanceMiles ?? null;
        etaMinutes = distanceData.eta_minutes ?? distanceData.etaMinutes ?? null;
      }
    } catch (e) {
      console.warn("[computeDispatchPrice] Distance API failed (non-blocking):", e);
    }
  }

  // ── PRIMARY PATH: Calculate from pricing_config_json (single source of truth) ──
  if (pricingConfig) {
    // Determine correct distance for pricing based on distance_basis
    const tenantDefaultBasis = distSettingsResult.data?.default_distance_basis || "tow_distance";
    const serviceBasis = pricingConfig.distance_basis || tenantDefaultBasis;
    // For webhook path, we only have pickup→dropoff distance — use it directly
    const pricingDistanceMiles = distanceMiles;

    let basePriceDollars: number | null = null;
    const breakdownParts: Record<string, unknown> = {
      method: "pricing_config_json",
      service_id: matchedService?.id,
      service_name: matchedService?.name,
      pricing_model: pricingConfig.pricing_model,
      distance_basis: serviceBasis,
      distance_miles: pricingDistanceMiles,
    };

    switch (pricingConfig.pricing_model) {
      case "flat": {
        basePriceDollars = pricingConfig.min_price || 0;
        if (pricingConfig.included_miles && pricingConfig.overage_per_mile && pricingDistanceMiles) {
          if (pricingDistanceMiles > pricingConfig.included_miles) {
            const overage = (pricingDistanceMiles - pricingConfig.included_miles) * pricingConfig.overage_per_mile;
            basePriceDollars += overage;
            breakdownParts.overage_miles = pricingDistanceMiles - pricingConfig.included_miles;
            breakdownParts.overage_charge = overage;
          }
        }
        break;
      }
      case "distance_tiered": {
        if (pricingConfig.distance_tiers && pricingDistanceMiles !== null) {
          for (const tier of pricingConfig.distance_tiers) {
            const tierMin = tier.min_miles;
            const tierMax = tier.max_miles ?? Infinity;
            if (pricingDistanceMiles >= tierMin && pricingDistanceMiles <= tierMax) {
              basePriceDollars = tier.base_price;
              if (tier.per_mile_price && pricingDistanceMiles > tierMin) {
                basePriceDollars += (pricingDistanceMiles - tierMin) * tier.per_mile_price;
              }
              breakdownParts.tier_used = { min: tierMin, max: tierMax, base: tier.base_price, per_mile: tier.per_mile_price };
              break;
            }
          }
        }
        if (basePriceDollars === null) {
          basePriceDollars = pricingConfig.min_price || null;
        }
        break;
      }
      case "per_unit": {
        if (pricingConfig.per_unit_price) {
          const units = pricingConfig.min_units || 1;
          basePriceDollars = pricingConfig.per_unit_price * units;
          if (pricingConfig.min_price && basePriceDollars < pricingConfig.min_price) {
            basePriceDollars = pricingConfig.min_price;
          }
          breakdownParts.unit_label = pricingConfig.unit_label;
          breakdownParts.per_unit_price = pricingConfig.per_unit_price;
          breakdownParts.units = units;
        }
        break;
      }
      case "package": {
        if (pricingConfig.packages?.length) {
          // Default to the "popular" package or first one for entity creation
          const defaultPkg = pricingConfig.packages.find(p => p.is_popular) || pricingConfig.packages[0];
          basePriceDollars = defaultPkg.price;
          breakdownParts.package_name = defaultPkg.name;
        }
        break;
      }
      case "variable": {
        // Variable = quote required, use min_price as estimate
        if (pricingConfig.min_price) {
          basePriceDollars = pricingConfig.min_price;
          breakdownParts.price_type = "estimate";
        }
        break;
      }
    }

    // Apply trip fee
    let tripFeeDollars = 0;
    if (pricingConfig.trip_fee?.enabled) {
      tripFeeDollars = pricingConfig.trip_fee.amount;
      breakdownParts.trip_fee = tripFeeDollars;
      breakdownParts.trip_fee_label = pricingConfig.trip_fee.label;
    }

    // Apply vehicle modifiers from pricing_config_json
    let modifierTotal = 0;
    if (jobType && pricingConfig.variables && basePriceDollars !== null) {
      for (const variable of pricingConfig.variables) {
        if (variable.key === "vehicle_type" && Array.isArray(variable.modifiers)) {
          const modifier = variable.modifiers.find(
            // deno-lint-ignore no-explicit-any
            (m: any) => m.value?.toLowerCase() === jobType.toLowerCase()
          );
          if (modifier) {
            const adj = modifier.adjustment_type === "percent"
              ? basePriceDollars * (modifier.price_adjustment / 100)
              : modifier.price_adjustment;
            modifierTotal += adj;
            breakdownParts.vehicle_modifier = { type: jobType, adjustment: adj };
          }
        }
      }
    }

    // Apply price_modifiers from DB (after-hours, weekend surcharges — previously bookings-only)
    const appliedDbModifiers: Array<{ name: string; type: string; adjustment: number }> = [];
    const modifiers = modifiersResult.data || [];
    if (modifiers.length > 0 && basePriceDollars !== null) {
      const now = new Date();
      const dayOfWeek = now.toLocaleDateString("en-US", { weekday: "long" }).toLowerCase();
      const subtotalCents = Math.round((basePriceDollars + modifierTotal) * 100);

      for (const mod of modifiers) {
        // Check applies_to_services
        if (mod.applies_to_services?.length && matchedService?.id) {
          if (!mod.applies_to_services.includes(matchedService.id)) continue;
        }
        // Check active_days
        if (mod.active_days?.length) {
          if (!mod.active_days.includes(dayOfWeek)) continue;
        }

        let adjustment = 0;
        switch (mod.adjustment_type) {
          case "fixed":
            adjustment = Math.round(mod.adjustment_value * 100);
            break;
          case "percentage":
            adjustment = Math.round(subtotalCents * (mod.adjustment_value / 100));
            break;
          case "multiplier":
            adjustment = Math.round(subtotalCents * mod.adjustment_value) - subtotalCents;
            break;
        }
        if (adjustment !== 0) {
          appliedDbModifiers.push({
            name: mod.modifier_type || mod.name || "modifier",
            type: mod.adjustment_type,
            adjustment,
          });
        }
      }
    }

    const dbModifierCents = appliedDbModifiers.reduce((sum, m) => sum + m.adjustment, 0);

    if (basePriceDollars !== null) {
      const totalDollars = basePriceDollars + modifierTotal + tripFeeDollars;
      const totalCents = Math.round(totalDollars * 100) + dbModifierCents;
      const minCents = pricingConfig.min_price ? Math.round(pricingConfig.min_price * 100) : 0;
      const finalCents = Math.max(totalCents, minCents);

      breakdownParts.base_price_dollars = basePriceDollars;
      breakdownParts.modifier_total = modifierTotal;
      breakdownParts.db_modifiers = appliedDbModifiers;
      breakdownParts.final_price_cents = finalCents;

      return {
        price_cents: finalCents,
        price_breakdown: breakdownParts,
        distance_miles: distanceMiles,
        estimated_eta_minutes: etaMinutes,
      };
    }

    // pricing_config_json present but couldn't calculate — return with context
    breakdownParts.reason = "could_not_calculate";
    return {
      price_cents: null,
      price_breakdown: breakdownParts,
      distance_miles: distanceMiles,
      estimated_eta_minutes: etaMinutes,
    };
  }

  // ── FALLBACK: Use pricingResolution (pricing_rules_jsonb) for unmigrated tenants ──
  const { data: tenant } = await supabase
    .from("tenants")
    .select("pricing_rules_jsonb")
    .eq("id", tenantId)
    .single();

  const pricingRulesRaw = tenant?.pricing_rules_jsonb || [];
  const pricingRules = Array.isArray(pricingRulesRaw) ? pricingRulesRaw : [];

  const services = allServices.map(
    // deno-lint-ignore no-explicit-any
    (s: any) => ({
      id: s.id,
      name: s.name,
      price: s.price_amount,
      pricing_type: s.price_type,
    })
  );

  const extractedData: Record<string, unknown> = {
    miles: distanceMiles,
    estimated_miles: distanceMiles,
    urgency,
    vehicle_type: jobType,
  };

  const pricingResult: PricingResolutionResult = resolvePricing(
    jobType || "tow",
    extractedData,
    pricingRules,
    services,
    tenantId
  );

  let priceCents: number | null = null;

  if (pricingResult.success) {
    if (pricingResult.priceType === "exact" && pricingResult.price != null) {
      priceCents = Math.round(pricingResult.price * 100);
    } else if (pricingResult.priceType === "range" && pricingResult.priceRange) {
      priceCents = Math.round(((pricingResult.priceRange.min + pricingResult.priceRange.max) / 2) * 100);
    }
  }

  return {
    price_cents: priceCents,
    price_breakdown: {
      method: pricingResult.success ? "pricing_rules_fallback" : "none",
      price_type: pricingResult.priceType,
      reason: pricingResult.reason,
      distance_miles: distanceMiles,
      log_data: pricingResult.logData,
    },
    distance_miles: distanceMiles,
    estimated_eta_minutes: etaMinutes,
  };
}

/**
 * PURE PRICING + ETA DECISION ENGINE
 *
 * Zero runtime dependencies. Deterministic. Unit-testable.
 * Used by AI to decide: EXACT vs ESTIMATE vs UNKNOWN pricing/ETA.
 */

// ============= TYPES =============

export type QuoteType = "EXACT" | "ESTIMATE" | "UNKNOWN";

export interface RequiredInput {
  field: string;
  label: string;
  type: "number" | "text" | "select";
  options?: string[];
  reason: string;
}

export interface QuoteResult {
  type: QuoteType;
  value?: number; // in cents for price, in minutes for ETA
  rangeMin?: number;
  rangeMax?: number;
  confidence: number; // 0.0 - 1.0
  explanation: string;
  missingInputs: RequiredInput[];
  drivers?: string[]; // factors affecting the estimate
}

export interface PricingRule {
  id: string;
  name: string;
  ruleType: "fixed" | "range" | "formula" | "conditional";
  conditions?: Record<string, any>; // e.g., { serviceType: "drain_cleaning", urgency: "normal" }
  requiredInputs?: string[]; // fields needed to apply this rule
  fixedPrice?: number; // cents
  rangeMin?: number; // cents
  rangeMax?: number; // cents
  formula?: string; // for formula rules (not implemented in v1)
  priority: number; // higher = more specific, lower = fallback
}

export interface BusynessRule {
  busynessLevel: "low" | "medium" | "high";
  etaMultiplier?: number; // 1.0 = normal, 1.5 = 50% longer
  surchargePercent?: number; // 0-100
}

export interface OfferingContext {
  serviceId?: string;
  serviceName?: string;
  name?: string;
  type?: string;
  duration?: number; // minutes
  basePrice?: number; // cents
  priceType?: "fixed" | "starting_at" | "quote_only";
}

export interface QueueMetrics {
  busynessLevel: "low" | "medium" | "high";
  queueLength?: number;
  current_queue_length?: number;
  avgCompletionMinutes?: number;
  avg_service_time_minutes?: number;
}

// ============= PRICING QUOTE COMPUTATION =============

/**
 * Compute a price quote based on rules, business mode, offering, and inputs.
 *
 * Decision tree:
 * 1. No matching rule => UNKNOWN (confidence 0.3)
 * 2. Missing required inputs => ask for inputs; if rule has range => ESTIMATE else UNKNOWN
 * 3. Deterministic rule (fixed) => EXACT (confidence 0.9)
 * 4. Range rule => ESTIMATE (confidence 0.6)
 */
export function computePriceQuote(params: {
  rules: PricingRule[];
  businessMode: string;
  offering: OfferingContext;
  inputs: Record<string, any>;
}): QuoteResult {
  const { rules, businessMode, offering, inputs } = params;

  // If offering has fixed base price and no rules, return EXACT
  if (offering.priceType === "fixed" && offering.basePrice && rules.length === 0) {
    return {
      type: "EXACT",
      value: offering.basePrice,
      confidence: 0.95,
      explanation: `Fixed price: $${(offering.basePrice / 100).toFixed(2)}`,
      missingInputs: [],
    };
  }

  // If offering requires quote and no rules, return UNKNOWN
  if (offering.priceType === "quote_only" && rules.length === 0) {
    return {
      type: "UNKNOWN",
      confidence: 0.3,
      explanation: "This service requires a custom quote. Please provide project details for an accurate estimate.",
      missingInputs: [],
    };
  }

  // Sort rules by priority (highest first)
  const sortedRules = [...rules].sort((a, b) => b.priority - a.priority);

  // Find first matching rule
  for (const rule of sortedRules) {
    // Skip malformed rules entirely
    if (!rule || typeof rule !== "object") continue;

    let matches: boolean;
    try {
      matches = checkRuleConditions(rule, inputs, offering);
    } catch {
      // Malformed rule — skip it rather than crashing the entire quote
      continue;
    }
    if (!matches) continue;

    // Check for missing required inputs
    const missing = getMissingInputs(rule, inputs);
    if (missing.length > 0) {
      // Has range? Return ESTIMATE with missing inputs
      if (rule.rangeMin !== undefined && rule.rangeMax !== undefined) {
        return {
          type: "ESTIMATE",
          rangeMin: rule.rangeMin,
          rangeMax: rule.rangeMax,
          confidence: 0.5,
          explanation: `Estimated range: $${(rule.rangeMin / 100).toFixed(2)} - $${(rule.rangeMax / 100).toFixed(2)}. Provide additional details for exact quote.`,
          missingInputs: missing,
          drivers: ["Missing details reduce accuracy"],
        };
      }

      // No range, return UNKNOWN
      return {
        type: "UNKNOWN",
        confidence: 0.4,
        explanation: "Additional information needed to provide an accurate quote.",
        missingInputs: missing,
      };
    }

    // All inputs provided, apply rule
    switch (rule.ruleType) {
      case "fixed":
        if (rule.fixedPrice !== undefined) {
          return {
            type: "EXACT",
            value: rule.fixedPrice,
            confidence: 0.9,
            explanation: `${rule.name}: $${(rule.fixedPrice / 100).toFixed(2)}`,
            missingInputs: [],
          };
        }
        break;

      case "range":
        if (rule.rangeMin !== undefined && rule.rangeMax !== undefined) {
          return {
            type: "ESTIMATE",
            rangeMin: rule.rangeMin,
            rangeMax: rule.rangeMax,
            confidence: 0.6,
            explanation: `${rule.name}: $${(rule.rangeMin / 100).toFixed(2)} - $${(rule.rangeMax / 100).toFixed(2)}`,
            missingInputs: [],
            drivers: ["Price varies based on project scope"],
          };
        }
        break;

      case "formula":
        // Not implemented in v1 - return UNKNOWN
        return {
          type: "UNKNOWN",
          confidence: 0.3,
          explanation: "Complex pricing formula requires manual quote.",
          missingInputs: [],
        };

      case "conditional":
        // Check conditions and return appropriate result
        if (rule.fixedPrice !== undefined) {
          return {
            type: "EXACT",
            value: rule.fixedPrice,
            confidence: 0.85,
            explanation: `${rule.name}: $${(rule.fixedPrice / 100).toFixed(2)}`,
            missingInputs: [],
          };
        }
        break;
    }
  }

  // No matching rules found
  // If offering has starting_at price, use it as ESTIMATE
  if (offering.priceType === "starting_at" && offering.basePrice) {
    return {
      type: "ESTIMATE",
      rangeMin: offering.basePrice,
      rangeMax: offering.basePrice * 2, // Assume up to 2x base
      confidence: 0.5,
      explanation: `Starting at $${(offering.basePrice / 100).toFixed(2)}. Final price depends on specific requirements.`,
      missingInputs: [],
      drivers: ["Base estimate without detailed scope"],
    };
  }

  // Default: UNKNOWN
  return {
    type: "UNKNOWN",
    confidence: 0.3,
    explanation: "Unable to determine pricing without additional context. Custom quote required.",
    missingInputs: [],
  };
}

// ============= ETA QUOTE COMPUTATION =============

/**
 * Compute an ETA quote based on busyness rules, mode, queue metrics, and inputs.
 *
 * Decision tree:
 * 1. No queue metrics => UNKNOWN
 * 2. Has duration + busyness => ESTIMATE with multiplier
 * 3. Missing duration => ask for it
 * 4. Deterministic (low busyness, known duration) => EXACT
 */
export function computeEtaQuote(params: {
  busynessRules: Record<string, BusynessRule>;
  mode: string;
  queueMetrics: QueueMetrics;
  inputs: Record<string, any>;
}): QuoteResult {
  const { busynessRules, mode, queueMetrics, inputs } = params;

  const baseDuration = inputs.duration || inputs.estimatedDuration;

  // No base duration provided
  if (!baseDuration) {
    return {
      type: "UNKNOWN",
      confidence: 0.3,
      explanation: "Service duration not specified. Unable to estimate completion time.",
      missingInputs: [
        {
          field: "duration",
          label: "Estimated Duration",
          type: "number",
          reason: "Required to calculate ETA",
        },
      ],
    };
  }

  // Get busyness rule
  const busynessRule = busynessRules[queueMetrics.busynessLevel];
  const multiplier = busynessRule?.etaMultiplier || 1.0;

  // Calculate ETA
  const queueLength = queueMetrics.queueLength ?? queueMetrics.current_queue_length ?? 0;
  const avgCompletionMinutes = queueMetrics.avgCompletionMinutes ?? queueMetrics.avg_service_time_minutes ?? 30;
  const queueDelay = queueLength * avgCompletionMinutes;
  const adjustedDuration = baseDuration * multiplier;
  const totalEta = queueDelay + adjustedDuration;

  // Determine confidence based on busyness
  let confidence = 0.7;
  let type: QuoteType = "ESTIMATE";
  const drivers: string[] = [];

  if (queueMetrics.busynessLevel === "low" && queueLength === 0) {
    confidence = 0.85;
    type = "EXACT";
  } else if (queueMetrics.busynessLevel === "high") {
    confidence = 0.5;
    drivers.push("High demand may extend wait time");
  }

  if (queueLength > 0) {
    drivers.push(`${queueLength} customer(s) ahead in queue`);
  }

  if (multiplier > 1.0) {
    drivers.push(`${Math.round((multiplier - 1) * 100)}% longer due to ${queueMetrics.busynessLevel} demand`);
  }

  // Build explanation
  let explanation = "";
  if (type === "EXACT") {
    explanation = `Your service will be ready in approximately ${totalEta} minutes.`;
  } else {
    const rangeMin = Math.floor(totalEta * 0.9);
    const rangeMax = Math.ceil(totalEta * 1.1);
    explanation = `Estimated ${rangeMin}-${rangeMax} minutes based on current demand.`;
    return {
      type,
      rangeMin,
      rangeMax,
      confidence,
      explanation,
      missingInputs: [],
      drivers,
    };
  }

  return {
    type,
    value: totalEta,
    confidence,
    explanation,
    missingInputs: [],
    drivers: drivers.length > 0 ? drivers : undefined,
  };
}

// ============= HELPER FUNCTIONS =============

/**
 * Check if a rule's conditions match the current inputs and offering
 */
function checkRuleConditions(
  rule: PricingRule,
  inputs: Record<string, any>,
  offering: OfferingContext
): boolean {
  // No conditions or malformed conditions = always matches
  if (!rule.conditions || typeof rule.conditions !== "object") return true;

  let entries: [string, any][];
  try {
    entries = Object.entries(rule.conditions);
  } catch {
    // Malformed conditions — treat as no conditions (match everything)
    return true;
  }

  for (const [key, value] of entries) {
    // Check inputs first
    if (inputs[key] !== undefined) {
      if (inputs[key] !== value) return false;
    }
    // Check offering context
    else if (key === "serviceId" && offering.serviceId !== value) {
      return false;
    } else if (key === "serviceName" && offering.serviceName !== value) {
      return false;
    } else if (key === "priceType" && offering.priceType !== value) {
      return false;
    }
  }

  return true;
}

/**
 * Get list of missing required inputs for a rule
 */
function getMissingInputs(
  rule: PricingRule,
  inputs: Record<string, any>
): RequiredInput[] {
  if (!rule.requiredInputs || rule.requiredInputs.length === 0) return [];

  const missing: RequiredInput[] = [];

  for (const field of rule.requiredInputs) {
    if (inputs[field] === undefined || inputs[field] === null || inputs[field] === "") {
      missing.push({
        field,
        label: formatFieldLabel(field),
        type: inferFieldType(field),
        reason: `Required to apply ${rule.name}`,
      });
    }
  }

  return missing;
}

/**
 * Format field name into human-readable label
 */
function formatFieldLabel(field: string): string {
  return field
    .replace(/_/g, " ")
    .replace(/\b\w/g, (l) => l.toUpperCase());
}

/**
 * Infer field type from field name (heuristic)
 */
function inferFieldType(field: string): "number" | "text" | "select" {
  const lowerField = field.toLowerCase();
  if (lowerField.includes("count") || lowerField.includes("quantity") || lowerField.includes("size")) {
    return "number";
  }
  if (lowerField.includes("type") || lowerField.includes("urgency") || lowerField.includes("level")) {
    return "select";
  }
  return "text";
}

/**
 * Distance-aware ETA Computation
 *
 * Computes driving distance/time between tenant's base address and a destination.
 * Supports multiple providers: Mapbox (preferred), Google, OSRM.
 *
 * Configuration sources (in priority order):
 * 1. tenants table columns (distance_provider_enabled, distance_provider, etc.)
 * 2. tenant_distance_settings table (legacy, for Google provider)
 *
 * Provider keys are NEVER stored in DB - they are platform env vars:
 * - MAPBOX_ACCESS_TOKEN
 * - GOOGLE_DISTANCE_MATRIX_API_KEY
 */

import { SupabaseClient } from "https://esm.sh/@supabase/supabase-js@2";

// ============= TYPES =============

export interface DistanceEtaInput {
  supabase: SupabaseClient;
  tenantId: string;
  destinationAddress: string;
  /** Optional: pre-geocoded destination coordinates */
  destinationLat?: number;
  destinationLng?: number;
}

export interface DistanceEtaResult {
  ok: boolean;
  distance_miles: number | null;
  drive_minutes: number | null;
  rounded_travel_minutes: number | null;
  provider_used: "google" | "mapbox" | "osrm" | "fallback_per_mile" | "none";
  max_distance_exceeded: boolean;
  error: string | null;
}

/** Tenant columns for distance configuration */
interface TenantDistanceConfig {
  address: string | null;
  base_lat: number | null;
  base_lng: number | null;
  distance_provider: string;
  distance_provider_enabled: boolean;
  mapbox_route_profile: string;
  eta_base_minutes: number;
  eta_per_mile_minutes: number;
  eta_min_minutes: number | null;
  eta_max_minutes: number | null;
}

/** tenant_distance_settings table (Business Brain) */
interface DistanceSettings {
  tenant_id: string;
  distance_provider_enabled: boolean;
  provider: string;
  base_lat: number | null;
  base_lng: number | null;
  base_place_name: string | null;
  mapbox_route_profile: string;
  eta_base_minutes: number;
  eta_per_mile_minutes: number | null;
  eta_min_minutes: number | null;
  eta_max_minutes: number | null;
  eta_rounding_minutes: number;
}

interface GoogleDistanceMatrixResponse {
  status: string;
  rows?: Array<{
    elements?: Array<{
      status: string;
      distance?: { value: number; text: string };
      duration?: { value: number; text: string };
    }>;
  }>;
  error_message?: string;
}

interface MapboxDirectionsResponse {
  code: string;
  routes?: Array<{
    distance: number; // meters
    duration: number; // seconds
  }>;
  message?: string;
}

interface MapboxGeocodingResponse {
  features?: Array<{
    geometry: {
      coordinates: [number, number]; // [lng, lat]
    };
    relevance: number;
  }>;
}

// ============= CONSTANTS =============

const METERS_PER_MILE = 1609.344;
const SECONDS_PER_MINUTE = 60;

// ============= MAIN FUNCTION =============

/**
 * Compute distance-aware travel time for ETA.
 *
 * Priority:
 * 1. If tenant has distance_provider_enabled=true, use tenants table config (Mapbox/etc)
 * 2. Otherwise fall back to tenant_distance_settings table (legacy Google)
 *
 * @param input - tenantId (trusted), supabase client, destination address
 * @returns Structured result with distance, time, and provider info
 */
export async function computeDistanceEta(
  input: DistanceEtaInput
): Promise<DistanceEtaResult> {
  const { supabase, tenantId, destinationAddress, destinationLat, destinationLng } = input;

  // Default "disabled" result (Golden Path safe - no nulls that break ElevenLabs)
  const disabledResult: DistanceEtaResult = {
    ok: true,
    distance_miles: null,
    drive_minutes: null,
    rounded_travel_minutes: null,
    provider_used: "none",
    max_distance_exceeded: false,
    error: null,
  };

  try {
    // Validate destination (need either address or coordinates)
    const hasAddress = destinationAddress && destinationAddress.trim().length >= 5;
    const hasCoords = destinationLat !== undefined && destinationLng !== undefined;

    if (!hasAddress && !hasCoords) {
      return {
        ...disabledResult,
        ok: false,
        error: "Invalid or missing destination address/coordinates",
      };
    }

    // ===== 1. Fetch tenant config (includes new distance columns) =====
    const { data: tenant, error: tenantError } = await supabase
      .from("tenants")
      .select(`
        address,
        base_lat,
        base_lng,
        distance_provider,
        distance_provider_enabled,
        mapbox_route_profile,
        eta_base_minutes,
        eta_per_mile_minutes,
        eta_min_minutes,
        eta_max_minutes
      `)
      .eq("id", tenantId)
      .single();

    if (tenantError || !tenant) {
      console.error("[distance_eta] Tenant fetch error:", tenantError?.message);
      return {
        ...disabledResult,
        ok: false,
        error: "Failed to fetch tenant data",
      };
    }

    // Type-safe config with null-safe defaults
    const tenantConfig: TenantDistanceConfig = {
      address: tenant.address ?? null,
      base_lat: tenant.base_lat ?? null,
      base_lng: tenant.base_lng ?? null,
      distance_provider: tenant.distance_provider ?? "mapbox",
      distance_provider_enabled: tenant.distance_provider_enabled ?? false,
      mapbox_route_profile: tenant.mapbox_route_profile ?? "mapbox/driving-traffic",
      eta_base_minutes: tenant.eta_base_minutes ?? 0,
      eta_per_mile_minutes: tenant.eta_per_mile_minutes ?? 0,
      eta_min_minutes: tenant.eta_min_minutes ?? null,
      eta_max_minutes: tenant.eta_max_minutes ?? null,
    };

    // ===== 2. Check if new distance system is enabled =====
    if (tenantConfig.distance_provider_enabled) {
      return await computeDistanceEtaV2(supabase, tenantId, tenantConfig, {
        address: destinationAddress,
        lat: destinationLat,
        lng: destinationLng,
      });
    }

    // ===== 3. Fall back to legacy tenant_distance_settings =====
    let { data: settings, error: settingsError } = await supabase
      .from("tenant_distance_settings")
      .select("*")
      .eq("tenant_id", tenantId)
      .maybeSingle();

    if (settingsError) {
      console.error("[distance_eta] Settings fetch error:", settingsError.message);
      return {
        ...disabledResult,
        ok: false,
        error: "Failed to fetch distance settings",
      };
    }

    // ===== 3a. Upsert default row if none exists =====
    // Ensures every tenant has a settings row (disabled by default)
    if (!settings) {
      console.log(`[distance_eta] No settings row for tenant ${tenantId.substring(0, 8)}..., creating default`);
      const defaultSettings = {
        tenant_id: tenantId,
        distance_provider_enabled: false,
        provider: "mapbox",
        base_lat: null,
        base_lng: null,
        base_place_name: null,
        mapbox_route_profile: "mapbox/driving-traffic",
        eta_base_minutes: 0,
        eta_per_mile_minutes: null,
        eta_min_minutes: null,
        eta_max_minutes: null,
        eta_rounding_minutes: 5,
      };

      const { data: upsertedSettings, error: upsertError } = await supabase
        .from("tenant_distance_settings")
        .upsert(defaultSettings, { onConflict: "tenant_id" })
        .select()
        .single();

      if (upsertError) {
        // Non-blocking: log but don't fail - just means no row created
        console.warn(`[distance_eta] Failed to upsert default settings:`, upsertError.message);
        // Return disabled result since settings don't exist
        logDistanceEta(tenantId, "none", true, false, "no_settings_upsert_failed");
        return disabledResult;
      }

      settings = upsertedSettings;
    }

    // If disabled, return early
    if (!settings.distance_provider_enabled) {
      logDistanceEta(tenantId, "none", true, false, "disabled_or_no_config");
      return disabledResult;
    }

    const distanceSettings = settings as DistanceSettings;

    // Get origin coordinates (prefer base_lat/lng from settings, fallback to tenant address)
    const originLat = distanceSettings.base_lat;
    const originLng = distanceSettings.base_lng;
    const originAddress = tenantConfig.address;

    if ((originLat === null || originLng === null) && (!originAddress || originAddress.trim().length < 5)) {
      logDistanceEta(tenantId, "none", false, false, "missing_origin_coords_and_address");
      return {
        ...disabledResult,
        ok: false,
        error: "Tenant base location not configured (no coordinates or address)",
      };
    }

    // ===== 4. Call distance provider =====
    let providerResult: {
      ok: boolean;
      distance_meters: number | null;
      duration_seconds: number | null;
      error: string | null;
    } = { ok: false, distance_meters: null, duration_seconds: null, error: null };

    const provider = distanceSettings.provider;
    const routeProfile = distanceSettings.mapbox_route_profile || "mapbox/driving-traffic";

    if (provider === "google") {
      // Google needs address strings
      const originStr = originAddress || `${originLat},${originLng}`;
      providerResult = await callGoogleDistanceMatrix(originStr, destinationAddress);
    } else if (provider === "mapbox") {
      // Mapbox can use coordinates or addresses
      if (originLat !== null && originLng !== null) {
        providerResult = await callMapboxDirections(
          { lat: originLat, lng: originLng },
          { address: destinationAddress },
          routeProfile
        );
      } else if (originAddress) {
        providerResult = await callMapboxDirections(
          { address: originAddress },
          { address: destinationAddress },
          routeProfile
        );
      }
    } else if (provider === "osrm") {
      providerResult = { ok: false, distance_meters: null, duration_seconds: null, error: "OSRM provider not yet implemented" };
    } else if (provider === "none") {
      logDistanceEta(tenantId, "none", true, false, "provider_disabled");
      return disabledResult;
    } else {
      providerResult = { ok: false, distance_meters: null, duration_seconds: null, error: `Unknown provider: ${provider}` };
    }

    // ===== 5. Handle provider result or fallback =====
    let distance_miles: number | null = null;
    let drive_minutes: number | null = null;
    let provider_used: DistanceEtaResult["provider_used"] = "none";

    if (providerResult.ok && providerResult.distance_meters !== null && providerResult.duration_seconds !== null) {
      distance_miles = providerResult.distance_meters / METERS_PER_MILE;
      drive_minutes = providerResult.duration_seconds / SECONDS_PER_MINUTE;
      provider_used = provider as DistanceEtaResult["provider_used"];
    } else {
      // Use eta_per_mile_minutes as fallback if configured
      const etaPerMile = distanceSettings.eta_per_mile_minutes;
      if (etaPerMile !== null && etaPerMile > 0 && providerResult.distance_meters !== null) {
        distance_miles = providerResult.distance_meters / METERS_PER_MILE;
        drive_minutes = distanceSettings.eta_base_minutes + distance_miles * etaPerMile;
        provider_used = "fallback_per_mile";
        console.log(`[distance_eta] Using fallback: ${distanceSettings.eta_base_minutes} base + ${distance_miles.toFixed(2)} mi * ${etaPerMile} = ${drive_minutes.toFixed(1)} min`);
      } else {
        logDistanceEta(tenantId, "none", false, false, providerResult.error || "provider_failed");
        return {
          ...disabledResult,
          ok: false,
          error: providerResult.error || "Distance provider failed and no fallback configured",
        };
      }
    }

    // Add base prep time
    drive_minutes += distanceSettings.eta_base_minutes;

    // Apply min/max clamps
    if (distanceSettings.eta_min_minutes !== null && drive_minutes < distanceSettings.eta_min_minutes) {
      drive_minutes = distanceSettings.eta_min_minutes;
    }
    if (distanceSettings.eta_max_minutes !== null && drive_minutes > distanceSettings.eta_max_minutes) {
      drive_minutes = distanceSettings.eta_max_minutes;
    }

    // ===== 6. Apply rounding =====
    const roundingMinutes = distanceSettings.eta_rounding_minutes || 5;
    const rounded_travel_minutes = Math.ceil(drive_minutes / roundingMinutes) * roundingMinutes;

    // ===== 7. Check max distance cutoff (use eta_max_minutes as proxy) =====
    const max_distance_exceeded = false; // Removed - use eta_max_minutes clamping instead

    logDistanceEta(tenantId, provider_used, true, max_distance_exceeded, null);

    return {
      ok: true,
      distance_miles: Math.round(distance_miles * 100) / 100,
      drive_minutes: Math.round(drive_minutes * 10) / 10,
      rounded_travel_minutes,
      provider_used,
      max_distance_exceeded,
      error: null,
    };
  } catch (error) {
    console.error("[distance_eta] Unexpected error:", error);
    return {
      ...disabledResult,
      ok: false,
      error: error instanceof Error ? error.message : "Unexpected error computing distance",
    };
  }
}

// ============= V2: NEW DISTANCE SYSTEM (tenants table columns) =============

/**
 * New distance computation using tenants table columns.
 * Supports Mapbox with geocoding and route caching.
 */
async function computeDistanceEtaV2(
  supabase: SupabaseClient,
  tenantId: string,
  config: TenantDistanceConfig,
  destination: { address?: string; lat?: number; lng?: number }
): Promise<DistanceEtaResult> {
  const disabledResult: DistanceEtaResult = {
    ok: true,
    distance_miles: null,
    drive_minutes: null,
    rounded_travel_minutes: null,
    provider_used: "none",
    max_distance_exceeded: false,
    error: null,
  };

  // Get origin coordinates (from tenant's base_lat/base_lng or geocode address)
  let originLat = config.base_lat;
  let originLng = config.base_lng;

  if (originLat === null || originLng === null) {
    if (!config.address || config.address.trim().length < 5) {
      logDistanceEta(tenantId, "none", false, false, "missing_origin_coords_and_address");
      return {
        ...disabledResult,
        ok: false,
        error: "Tenant base location not configured (no coordinates or address)",
      };
    }

    // Geocode the tenant's address
    const geocoded = await geocodeAddress(supabase, tenantId, config.address);
    if (!geocoded.ok || geocoded.lat === null || geocoded.lng === null) {
      logDistanceEta(tenantId, "none", false, false, "geocode_origin_failed");
      return {
        ...disabledResult,
        ok: false,
        error: geocoded.error || "Failed to geocode tenant base address",
      };
    }
    originLat = geocoded.lat;
    originLng = geocoded.lng;
  }

  // Get destination coordinates
  let destLat = destination.lat;
  let destLng = destination.lng;

  if (destLat === undefined || destLng === undefined) {
    if (!destination.address || destination.address.trim().length < 5) {
      return {
        ...disabledResult,
        ok: false,
        error: "Invalid destination (no coordinates or address)",
      };
    }

    // Geocode the destination address
    const geocoded = await geocodeAddress(supabase, tenantId, destination.address);
    if (!geocoded.ok || geocoded.lat === null || geocoded.lng === null) {
      return {
        ...disabledResult,
        ok: false,
        error: geocoded.error || "Failed to geocode destination address",
      };
    }
    destLat = geocoded.lat;
    destLng = geocoded.lng;
  }

  // Call routing provider
  const provider = config.distance_provider;
  let providerResult: {
    ok: boolean;
    distance_meters: number | null;
    duration_seconds: number | null;
    error: string | null;
  };

  if (provider === "mapbox") {
    providerResult = await callMapboxDirections(
      { lat: originLat, lng: originLng },
      { lat: destLat, lng: destLng },
      config.mapbox_route_profile
    );
  } else if (provider === "google") {
    // For Google, we need addresses not coords (or use a different API)
    const originAddr = config.address || `${originLat},${originLng}`;
    const destAddr = destination.address || `${destLat},${destLng}`;
    providerResult = await callGoogleDistanceMatrix(originAddr, destAddr);
  } else if (provider === "none") {
    // Use simple linear estimation
    const straightLineMiles = haversineDistanceMiles(originLat, originLng, destLat, destLng);
    const estimatedDriveMiles = straightLineMiles * 1.3; // ~30% more than straight line
    providerResult = {
      ok: true,
      distance_meters: estimatedDriveMiles * METERS_PER_MILE,
      duration_seconds: (config.eta_base_minutes + estimatedDriveMiles * config.eta_per_mile_minutes) * 60,
      error: null,
    };
  } else {
    providerResult = { ok: false, distance_meters: null, duration_seconds: null, error: `Unknown provider: ${provider}` };
  }

  if (!providerResult.ok || providerResult.distance_meters === null || providerResult.duration_seconds === null) {
    // Use eta_per_mile_minutes as fallback if configured
    if (config.eta_per_mile_minutes > 0) {
      const straightLineMiles = haversineDistanceMiles(originLat, originLng, destLat, destLng);
      const estimatedDriveMiles = straightLineMiles * 1.3;
      const drive_minutes = config.eta_base_minutes + estimatedDriveMiles * config.eta_per_mile_minutes;

      logDistanceEta(tenantId, "fallback_per_mile", true, false, "provider_failed_using_eta_per_mile");

      return {
        ok: true,
        distance_miles: Math.round(estimatedDriveMiles * 100) / 100,
        drive_minutes: Math.round(drive_minutes * 10) / 10,
        rounded_travel_minutes: Math.ceil(drive_minutes / 5) * 5,
        provider_used: "fallback_per_mile",
        max_distance_exceeded: false,
        error: null,
      };
    }

    logDistanceEta(tenantId, "none", false, false, providerResult.error || "provider_failed");
    return {
      ...disabledResult,
      ok: false,
      error: providerResult.error || "Distance provider failed",
    };
  }

  // Calculate final values
  const distance_miles = providerResult.distance_meters / METERS_PER_MILE;
  let drive_minutes = providerResult.duration_seconds / SECONDS_PER_MINUTE;

  // Add base prep time
  drive_minutes += config.eta_base_minutes;

  // Apply min/max constraints
  if (config.eta_min_minutes !== null && drive_minutes < config.eta_min_minutes) {
    drive_minutes = config.eta_min_minutes;
  }
  if (config.eta_max_minutes !== null && drive_minutes > config.eta_max_minutes) {
    drive_minutes = config.eta_max_minutes;
  }

  // Round to nearest 5 minutes
  const rounded_travel_minutes = Math.ceil(drive_minutes / 5) * 5;

  const provider_used = provider === "none" ? "fallback_per_mile" : provider as DistanceEtaResult["provider_used"];
  logDistanceEta(tenantId, provider_used, true, false, null);

  return {
    ok: true,
    distance_miles: Math.round(distance_miles * 100) / 100,
    drive_minutes: Math.round(drive_minutes * 10) / 10,
    rounded_travel_minutes,
    provider_used,
    max_distance_exceeded: false,
    error: null,
  };
}

// ============= GOOGLE DISTANCE MATRIX =============

async function callGoogleDistanceMatrix(
  origin: string,
  destination: string
): Promise<{
  ok: boolean;
  distance_meters: number | null;
  duration_seconds: number | null;
  error: string | null;
}> {
  const apiKey = Deno.env.get("GOOGLE_DISTANCE_MATRIX_API_KEY");

  if (!apiKey) {
    console.error("[distance_eta] GOOGLE_DISTANCE_MATRIX_API_KEY not configured");
    return {
      ok: false,
      distance_meters: null,
      duration_seconds: null,
      error: "Google Distance Matrix API key not configured",
    };
  }

  try {
    const url = new URL("https://maps.googleapis.com/maps/api/distancematrix/json");
    url.searchParams.set("origins", origin);
    url.searchParams.set("destinations", destination);
    url.searchParams.set("mode", "driving");
    url.searchParams.set("units", "imperial");
    url.searchParams.set("key", apiKey);

    const response = await fetch(url.toString(), {
      method: "GET",
      headers: { "Accept": "application/json" },
    });

    if (!response.ok) {
      console.error("[distance_eta] Google API HTTP error:", response.status);
      return {
        ok: false,
        distance_meters: null,
        duration_seconds: null,
        error: `Google API returned HTTP ${response.status}`,
      };
    }

    const data: GoogleDistanceMatrixResponse = await response.json();

    if (data.status !== "OK") {
      console.error("[distance_eta] Google API status:", data.status, data.error_message);
      return {
        ok: false,
        distance_meters: null,
        duration_seconds: null,
        error: data.error_message || `Google API status: ${data.status}`,
      };
    }

    const element = data.rows?.[0]?.elements?.[0];
    if (!element || element.status !== "OK") {
      const elementStatus = element?.status || "NO_ELEMENT";
      console.error("[distance_eta] Google element status:", elementStatus);
      return {
        ok: false,
        distance_meters: null,
        duration_seconds: null,
        error: `Route not found: ${elementStatus}`,
      };
    }

    const distance_meters = element.distance?.value ?? null;
    const duration_seconds = element.duration?.value ?? null;

    if (distance_meters === null || duration_seconds === null) {
      return {
        ok: false,
        distance_meters,
        duration_seconds,
        error: "Missing distance or duration in response",
      };
    }

    console.log(`[distance_eta] Google result: ${element.distance?.text}, ${element.duration?.text}`);

    return {
      ok: true,
      distance_meters,
      duration_seconds,
      error: null,
    };
  } catch (error) {
    console.error("[distance_eta] Google API call failed:", error);
    return {
      ok: false,
      distance_meters: null,
      duration_seconds: null,
      error: error instanceof Error ? error.message : "Google API call failed",
    };
  }
}

// ============= MAPBOX DIRECTIONS =============

/**
 * Call Mapbox Directions API for routing.
 * Supports both coordinates and addresses (addresses will be geocoded first).
 */
async function callMapboxDirections(
  origin: { lat?: number; lng?: number; address?: string },
  destination: { lat?: number; lng?: number; address?: string },
  routeProfile: string = "mapbox/driving-traffic"
): Promise<{
  ok: boolean;
  distance_meters: number | null;
  duration_seconds: number | null;
  error: string | null;
}> {
  const accessToken = Deno.env.get("MAPBOX_ACCESS_TOKEN");

  if (!accessToken) {
    console.error("[distance_eta] MAPBOX_ACCESS_TOKEN not configured");
    return {
      ok: false,
      distance_meters: null,
      duration_seconds: null,
      error: "Mapbox API token not configured",
    };
  }

  try {
    // Get coordinates (geocode if needed)
    let originLng: number, originLat: number;
    let destLng: number, destLat: number;

    if (origin.lat !== undefined && origin.lng !== undefined) {
      originLat = origin.lat;
      originLng = origin.lng;
    } else if (origin.address) {
      const geocoded = await geocodeWithMapbox(origin.address, accessToken);
      if (!geocoded.ok) {
        return { ok: false, distance_meters: null, duration_seconds: null, error: geocoded.error || "Failed to geocode origin" };
      }
      originLat = geocoded.lat!;
      originLng = geocoded.lng!;
    } else {
      return { ok: false, distance_meters: null, duration_seconds: null, error: "Origin missing coordinates and address" };
    }

    if (destination.lat !== undefined && destination.lng !== undefined) {
      destLat = destination.lat;
      destLng = destination.lng;
    } else if (destination.address) {
      const geocoded = await geocodeWithMapbox(destination.address, accessToken);
      if (!geocoded.ok) {
        return { ok: false, distance_meters: null, duration_seconds: null, error: geocoded.error || "Failed to geocode destination" };
      }
      destLat = geocoded.lat!;
      destLng = geocoded.lng!;
    } else {
      return { ok: false, distance_meters: null, duration_seconds: null, error: "Destination missing coordinates and address" };
    }

    // Extract profile from "mapbox/driving-traffic" -> "driving-traffic"
    const profile = routeProfile.replace("mapbox/", "");

    // Call Mapbox Directions API
    const url = `https://api.mapbox.com/directions/v5/mapbox/${profile}/${originLng},${originLat};${destLng},${destLat}?access_token=${accessToken}&overview=false`;

    const response = await fetch(url, {
      method: "GET",
      headers: { "Accept": "application/json" },
    });

    if (!response.ok) {
      console.error("[distance_eta] Mapbox API HTTP error:", response.status);
      return {
        ok: false,
        distance_meters: null,
        duration_seconds: null,
        error: `Mapbox API returned HTTP ${response.status}`,
      };
    }

    const data: MapboxDirectionsResponse = await response.json();

    if (data.code !== "Ok" || !data.routes || data.routes.length === 0) {
      console.error("[distance_eta] Mapbox API error:", data.code, data.message);
      return {
        ok: false,
        distance_meters: null,
        duration_seconds: null,
        error: data.message || `Mapbox error: ${data.code}`,
      };
    }

    const route = data.routes[0];
    console.log(`[distance_eta] Mapbox result: ${(route.distance / METERS_PER_MILE).toFixed(2)} mi, ${(route.duration / 60).toFixed(1)} min`);

    return {
      ok: true,
      distance_meters: route.distance,
      duration_seconds: route.duration,
      error: null,
    };
  } catch (error) {
    console.error("[distance_eta] Mapbox API call failed:", error);
    return {
      ok: false,
      distance_meters: null,
      duration_seconds: null,
      error: error instanceof Error ? error.message : "Mapbox API call failed",
    };
  }
}

/**
 * Geocode an address using Mapbox Geocoding API (direct call, no caching).
 */
async function geocodeWithMapbox(
  address: string,
  accessToken: string
): Promise<{ ok: boolean; lat: number | null; lng: number | null; error: string | null }> {
  try {
    const encodedAddress = encodeURIComponent(address);
    const url = `https://api.mapbox.com/geocoding/v5/mapbox.places/${encodedAddress}.json?access_token=${accessToken}&limit=1`;

    const response = await fetch(url, {
      method: "GET",
      headers: { "Accept": "application/json" },
    });

    if (!response.ok) {
      return { ok: false, lat: null, lng: null, error: `Mapbox Geocoding HTTP ${response.status}` };
    }

    const data: MapboxGeocodingResponse = await response.json();

    if (!data.features || data.features.length === 0) {
      return { ok: false, lat: null, lng: null, error: "Address not found" };
    }

    const [lng, lat] = data.features[0].geometry.coordinates;
    return { ok: true, lat, lng, error: null };
  } catch (error) {
    return {
      ok: false,
      lat: null,
      lng: null,
      error: error instanceof Error ? error.message : "Geocoding failed",
    };
  }
}

// ============= GEOCODING WITH CACHE =============

/**
 * Geocode an address with caching (tenant-scoped).
 * Checks geocode_cache first, then calls Mapbox if not found.
 */
async function geocodeAddress(
  supabase: SupabaseClient,
  tenantId: string,
  address: string
): Promise<{ ok: boolean; lat: number | null; lng: number | null; error: string | null }> {
  const accessToken = Deno.env.get("MAPBOX_ACCESS_TOKEN");
  if (!accessToken) {
    return { ok: false, lat: null, lng: null, error: "MAPBOX_ACCESS_TOKEN not configured" };
  }

  // Normalize and hash address for cache lookup
  const normalizedAddress = address.trim().toLowerCase().replace(/\s+/g, " ");
  const addressHash = await hashString(normalizedAddress);

  // Check cache first
  const { data: cached } = await supabase
    .from("geocode_cache")
    .select("lat, lng")
    .eq("tenant_id", tenantId)
    .eq("address_hash", addressHash)
    .eq("provider", "mapbox")
    .gt("expires_at", new Date().toISOString())
    .maybeSingle();

  if (cached) {
    console.log(`[distance_eta] Geocode cache hit for hash ${addressHash.substring(0, 8)}...`);
    return { ok: true, lat: cached.lat, lng: cached.lng, error: null };
  }

  // Call Mapbox Geocoding
  const result = await geocodeWithMapbox(address, accessToken);

  if (result.ok && result.lat !== null && result.lng !== null) {
    // Store in cache (fire-and-forget, don't block on insert)
    (async () => {
      try {
        await supabase
          .from("geocode_cache")
          .upsert({
            tenant_id: tenantId,
            address_hash: addressHash,
            lat: result.lat,
            lng: result.lng,
            confidence: "high",
            provider: "mapbox",
            fetched_at: new Date().toISOString(),
            expires_at: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(), // 30 days
          }, { onConflict: "tenant_id,address_hash,provider" });
        console.log(`[distance_eta] Geocode cached for hash ${addressHash.substring(0, 8)}...`);
      } catch (err: unknown) {
        const message = err instanceof Error ? err.message : "Unknown error";
        console.warn(`[distance_eta] Failed to cache geocode:`, message);
      }
    })();
  }

  return result;
}

/**
 * Hash a string using SHA-256 (Web Crypto API).
 */
async function hashString(str: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(str);
  const hashBuffer = await crypto.subtle.digest("SHA-256", data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map((b) => b.toString(16).padStart(2, "0")).join("");
}

