// ============= MAIN FETCHER =============

export interface GetSnapshotOptions {
  tenantId: string;
  locationId?: string | null;
}

/**
 * Fetches complete Business Brain snapshot from database.
 * All data is tenant-scoped. Returns stable shape with safe defaults.
 */
export async function getBusinessBrainSnapshot(
  supabase: SupabaseClient,
  options: GetSnapshotOptions
): Promise<BusinessBrainSnapshot> {
  const { tenantId, locationId } = options;

  // STEP 1: Fetch tenant first to get business_mode
  const { data: tenantData, error: tenantError } = await supabase
    .from("tenants")
    .select(`
      id, name, tagline, business_mode, industry, timezone,
      phone_public, website_url, address, years_in_business,
      hours_json, service_area_json,
      cancellation_policy, deposit_policy, refund_policy, payment_methods,
      ai_never_promise, ai_policies_json, enabled_modules, hipaa_mode,
      pricing_rules_jsonb, busyness_rules_jsonb, context_fields_json,
      capabilities_json
    `)
    .eq("id", tenantId)
    .single();

  if (tenantError || !tenantData) {
    console.error(`[getBusinessBrainSnapshot] Tenant not found: ${tenantId}`, tenantError);
    throw new Error(`Tenant not found: ${tenantId}`);
  }

  const businessMode = safeString(tenantData.business_mode) || "general";
  const caps = resolveCapabilities(
    tenantData.business_mode,
    tenantData.enabled_modules,
    tenantData.capabilities_json,
  );
  const isFoodMode = caps.isFoodBusiness;

  // STEP 2: Fetch all Business Brain data in parallel (typed separately to avoid inference issues)
  const servicesQuery = supabase
    .from("services")
    .select("id, name, description, price_type, price_amount, duration_minutes, deposit_required, deposit_amount, preparation_instructions, upsell_suggestions, is_active, service_category, service_type, pricing_config_json, booking_type, prerequisite_note, duration_min_minutes, duration_max_minutes")
    .eq("tenant_id", tenantId)
    .eq("is_active", true)
    .order("display_order", { ascending: true })
    .limit(100);

  const faqsQuery = supabase
    .from("business_faqs")
    .select("id, question, answer, priority_weight")
    .eq("tenant_id", tenantId)
    .order("priority_weight", { ascending: false })
    .limit(30);

  const objectionsQuery = supabase
    .from("objection_responses")
    .select("id, objection, response, priority_weight")
    .eq("tenant_id", tenantId)
    .order("priority_weight", { ascending: false })
    .limit(20);

  const knowledgeQuery = supabase
    .from("ai_knowledge_base")
    .select("id, type, title, content, priority_weight")
    .eq("tenant_id", tenantId)
    .order("priority_weight", { ascending: false })
    .limit(30);

  const assistantSettingsQuery = supabase
    .from("assistant_settings")
    .select("voice_ai_enabled, instant_text_enabled, go_live_enabled, missed_call_behavior, ai_booking_mode, booking_url, calendar_provider, busy_toggle, overflow_rings, sms_first_delay_seconds, owner_forward_number, owner_forward_verified, settings_json, unknown_question_behavior")
    .eq("tenant_id", tenantId)
    .maybeSingle();

  const intelligenceSettingsQuery = supabase
    .from("tenant_intelligence_settings")
    .select("memory_enabled, min_confidence_threshold, min_observation_threshold, share_memory_across_locations")
    .eq("tenant_id", tenantId)
    .maybeSingle();

  const intentRulesQuery = supabase
    .from("business_intent_rules")
    .select("id, name, rule_type, description, condition_json, action_json, priority, is_enabled")
    .eq("tenant_id", tenantId)
    .eq("is_enabled", true)
    .order("priority", { ascending: false })
    .limit(30);

  const availabilitySlotsQuery = supabase
    .from("availability_slots")
    .select("id, day_of_week, start_time, end_time, is_available")
    .eq("tenant_id", tenantId)
    .order("day_of_week")
    .order("start_time");

  // Mode-specific knowledge queries
  const menuKnowledgeQuery = supabase
    .from("menu_knowledge")
    .select("item_name, detailed_description, ingredients, allergens, dietary_tags, pairing_suggestions, chef_notes, spice_level, is_signature")
    .eq("tenant_id", tenantId)
    .order("is_signature", { ascending: false })
    .limit(50);

  const cateringKnowledgeQuery = supabase
    .from("catering_knowledge")
    .select("event_type, min_guests, max_guests, lead_time_days, deposit_percentage, ai_script")
    .eq("tenant_id", tenantId)
    .limit(20);

  const vehicleKnowledgeQuery = supabase
    .from("vehicle_knowledge")
    .select("vehicle_category, equipment_required, weight_class, special_instructions, additional_fees_apply, fee_notes")
    .eq("tenant_id", tenantId)
    .limit(30);

  const roadsideKnowledgeQuery = supabase
    .from("roadside_knowledge")
    .select("situation_type, safety_instructions, estimated_service_time_minutes, escalation_triggers, priority_level, ai_script")
    .eq("tenant_id", tenantId)
    .order("priority_level", { ascending: false })
    .limit(20);

  const symptomTriageQuery = supabase
    .from("symptom_triage")
    .select("symptom_category, symptom_name, severity_indicators, escalation_action, can_be_telehealth, hipaa_safe_response")
    .eq("tenant_id", tenantId)
    .limit(50);

  const insuranceKnowledgeQuery = supabase
    .from("insurance_knowledge")
    .select("carrier_name, plan_types, is_accepted, copay_typical_range, patient_script")
    .eq("tenant_id", tenantId)
    .limit(30);

  const productKnowledgeQuery = supabase
    .from("product_knowledge")
    .select("product_name, brand, benefits, is_premium, upsell_script")
    .eq("tenant_id", tenantId)
    .order("is_premium", { ascending: false })
    .limit(30);

  const aftercareQuery = supabase
    .from("aftercare_instructions")
    .select("service_name, immediate_care, things_to_avoid, warning_signs, follow_up_timeframe")
    .eq("tenant_id", tenantId)
    .limit(30);

  const competitorQuery = supabase
    .from("competitor_knowledge")
    .select("competitor_name, our_advantage, response_script")
    .eq("tenant_id", tenantId)
    .limit(20);

  const seasonalQuery = supabase
    .from("seasonal_knowledge")
    .select("event_name, special_hours, special_pricing_notes, ai_announcement")
    .eq("tenant_id", tenantId)
    .limit(20);

  // Workflow config queries
  const dispatchWorkflowQuery = supabase
    .from("dispatch_workflow_config")
    .select("*")
    .eq("tenant_id", tenantId)
    .maybeSingle();

  const serviceWorkflowQuery = supabase
    .from("service_workflow_config")
    .select("*")
    .eq("tenant_id", tenantId)
    .maybeSingle();

  const foodWorkflowQuery = supabase
    .from("food_workflow_config")
    .select("*")
    .eq("tenant_id", tenantId)
    .maybeSingle();

  const medicalWorkflowQuery = supabase
    .from("medical_workflow_config")
    .select("*")
    .eq("tenant_id", tenantId)
    .maybeSingle();

  const generalWorkflowQuery = supabase
    .from("general_workflow_config")
    .select("*")
    .eq("tenant_id", tenantId)
    .maybeSingle();

  // Impound lot queries (for dispatch businesses with impound capability)
  const impoundLotQuery = supabase
    .from("impound_lots")
    .select("*")
    .eq("tenant_id", tenantId)
    .eq("is_active", true)
    .order("is_default", { ascending: false })
    .limit(1)
    .maybeSingle();

  const impoundSettingsQuery = supabase
    .from("impound_settings")
    .select("*")
    .eq("tenant_id", tenantId)
    .maybeSingle();

  // Execute core queries in parallel
  const [
    servicesResult,
    faqsResult,
    objectionsResult,
    knowledgeResult,
    assistantSettingsResult,
    intelligenceSettingsResult,
    intentRulesResult,
    availabilitySlotsResult,
    // Mode-specific knowledge
    menuKnowledgeResult,
    cateringKnowledgeResult,
    vehicleKnowledgeResult,
    roadsideKnowledgeResult,
    symptomTriageResult,
    insuranceKnowledgeResult,
    productKnowledgeResult,
    aftercareResult,
    competitorResult,
    seasonalResult,
    // Workflow configs
    dispatchWorkflowResult,
    serviceWorkflowResult,
    foodWorkflowResult,
    medicalWorkflowResult,
    generalWorkflowResult,
    // Impound lot data
    impoundLotResult,
    impoundSettingsResult,
  ] = await Promise.all([
    servicesQuery,
    faqsQuery,
    objectionsQuery,
    knowledgeQuery,
    assistantSettingsQuery,
    intelligenceSettingsQuery,
    intentRulesQuery,
    availabilitySlotsQuery,
    // Mode-specific knowledge
    menuKnowledgeQuery,
    cateringKnowledgeQuery,
    vehicleKnowledgeQuery,
    roadsideKnowledgeQuery,
    symptomTriageQuery,
    insuranceKnowledgeQuery,
    productKnowledgeQuery,
    aftercareQuery,
    competitorQuery,
    seasonalQuery,
    // Workflow configs
    dispatchWorkflowQuery,
    serviceWorkflowQuery,
    foodWorkflowQuery,
    medicalWorkflowQuery,
    generalWorkflowQuery,
    // Impound lot data
    impoundLotQuery,
    impoundSettingsQuery,
  ]);

  // Conditionally fetch food-specific data
  let menuItemsResult: { data: any[] | null } = { data: null };
  let foodSettingsResult: { data: any | null } = { data: null };

  if (isFoodMode) {
    const [menuResult, foodResult] = await Promise.all([
      supabase
        .from("menu_items")
        .select("id, name, description, category, price_cents, modifiers, dietary_tags, is_available, prep_time_minutes")
        .eq("tenant_id", tenantId)
        .eq("is_available", true)
        .limit(100),
      supabase
        .from("food_order_settings")
        .select("estimated_prep_minutes, accepts_pickup, accepts_delivery, accepts_dine_in, delivery_radius_miles, delivery_minimum_cents, accepts_catering, catering_min_guests, catering_lead_days, order_confirmation_mode")
        .eq("tenant_id", tenantId)
        .maybeSingle(),
    ]);
    menuItemsResult = menuResult;
    foodSettingsResult = foodResult;
  }

  // STEP 3: Transform data with safe defaults

  const tenant: TenantSnapshot = {
    id: safeString(tenantData.id),
    name: safeString(tenantData.name),
    tagline: safeString(tenantData.tagline),
    business_mode: businessMode,
    industry: safeString(tenantData.industry),
    timezone: safeString(tenantData.timezone) || "America/New_York",
    phone_public: safeString(tenantData.phone_public),
    website_url: safeString(tenantData.website_url),
    address: safeString(tenantData.address),
    years_in_business: tenantData.years_in_business,
    hours_json: safeObject(tenantData.hours_json),
    service_area_json: tenantData.service_area_json || null,
    // Not present in tenants table; kept for backwards compatibility
    out_of_area_message: "",
    cancellation_policy: safeString(tenantData.cancellation_policy),
    deposit_policy: safeString(tenantData.deposit_policy),
    refund_policy: safeString(tenantData.refund_policy),
    payment_methods: safeArray(tenantData.payment_methods),
    ai_never_promise: safeArray(tenantData.ai_never_promise),
    ai_policies_json: tenantData.ai_policies_json || null,
    enabled_modules: safeArray(tenantData.enabled_modules),
    hipaa_mode: safeBoolean(tenantData.hipaa_mode),
    pricing_rules_jsonb: tenantData.pricing_rules_jsonb || null,
    busyness_rules_jsonb: tenantData.busyness_rules_jsonb || null,
    // Legacy field; tenant_distance_settings is now canonical for ETA
    eta_policy_jsonb: null,
    context_fields_json: safeArray(tenantData.context_fields_json),
  };

  const services: ServiceSnapshot[] = safeArray(servicesResult.data).map((s: any) => ({
    id: safeString(s.id),
    name: safeString(s.name),
    description: safeString(s.description),
    price_type: safeString(s.price_type) || "quote_only",
    price_amount: s.price_amount,
    duration_minutes: safeNumber(s.duration_minutes, 60),
    deposit_required: safeBoolean(s.deposit_required),
    deposit_amount: s.deposit_amount,
    preparation_instructions: safeString(s.preparation_instructions),
    upsell_suggestions: safeArray(s.upsell_suggestions),
    is_active: safeBoolean(s.is_active, true),
    service_category: safeString(s.service_category),
    service_type: safeString(s.service_type) || "primary",
    pricing_config_json: s.pricing_config_json || null,
    booking_type: safeString(s.booking_type) || "direct_book",
    prerequisite_note: safeString(s.prerequisite_note),
    duration_min_minutes: s.duration_min_minutes ?? null,
    duration_max_minutes: s.duration_max_minutes ?? null,
  }));

  const faqs: FAQSnapshot[] = safeArray(faqsResult.data).map((f: any) => ({
    id: safeString(f.id),
    question: safeString(f.question),
    answer: safeString(f.answer),
    priority_weight: safeNumber(f.priority_weight),
  }));

  const objections: ObjectionSnapshot[] = safeArray(objectionsResult.data).map((o: any) => ({
    id: safeString(o.id),
    objection: safeString(o.objection),
    response: safeString(o.response),
    priority_weight: safeNumber(o.priority_weight),
  }));

  const knowledge: KnowledgeSnapshot[] = safeArray(knowledgeResult.data).map((k: any) => ({
    id: safeString(k.id),
    type: safeString(k.type),
    title: safeString(k.title),
    content: safeString(k.content),
    priority_weight: safeNumber(k.priority_weight),
  }));

  const assistantSettingsRaw = assistantSettingsResult?.data;
  const settingsJsonRaw = (assistantSettingsRaw as any)?.settings_json as Record<string, string> | null;
  const assistant_settings: AssistantSettingsSnapshot = assistantSettingsRaw
    ? {
        voice_ai_enabled: safeBoolean(assistantSettingsRaw.voice_ai_enabled),
        instant_text_enabled: safeBoolean(assistantSettingsRaw.instant_text_enabled),
        go_live_enabled: safeBoolean(assistantSettingsRaw.go_live_enabled),
        missed_call_behavior: safeString(assistantSettingsRaw.missed_call_behavior) || "text_only",
        ai_booking_mode: safeString(assistantSettingsRaw.ai_booking_mode) || "pending_approval",
        booking_url: safeString(assistantSettingsRaw.booking_url),
        calendar_provider: safeString(assistantSettingsRaw.calendar_provider),
        busy_toggle: safeBoolean(assistantSettingsRaw.busy_toggle),
        overflow_rings: safeNumber(assistantSettingsRaw.overflow_rings, 3),
        sms_first_delay_seconds: safeNumber(assistantSettingsRaw.sms_first_delay_seconds, 5),
        owner_forward_number: safeString(assistantSettingsRaw.owner_forward_number),
        owner_forward_verified: safeBoolean(assistantSettingsRaw.owner_forward_verified),
        ai_tone: safeString(settingsJsonRaw?.ai_tone),
        followup_cadence: safeString(settingsJsonRaw?.followup_cadence) || "moderate",
        unknown_question_behavior: safeString((assistantSettingsRaw as any)?.unknown_question_behavior || settingsJsonRaw?.unknown_question_behavior) || "try_help",
        ai_guardrails: safeString((settingsJsonRaw as any)?.ai_guardrails),
        required_intake_fields: Array.isArray((settingsJsonRaw as any)?.required_intake_fields) ? (settingsJsonRaw as any).required_intake_fields : ["customer_name", "customer_phone"],
        escalation_rules: {
          transferOnRequest: (settingsJsonRaw as any)?.escalation_rules?.transferOnRequest ?? true,
          transferOnAnger: (settingsJsonRaw as any)?.escalation_rules?.transferOnAnger ?? true,
          transferOnPriceObjection: (settingsJsonRaw as any)?.escalation_rules?.transferOnPriceObjection ?? false,
          transferOnComplexQuestion: (settingsJsonRaw as any)?.escalation_rules?.transferOnComplexQuestion ?? true,
          transferOnComplaint: (settingsJsonRaw as any)?.escalation_rules?.transferOnComplaint ?? true,
          fallbackAction: safeString((settingsJsonRaw as any)?.escalation_rules?.fallbackAction) || "callback",
        },
      }
    : getDefaultAssistantSettings();

  const intelligenceSettingsRaw = intelligenceSettingsResult?.data;
  const tenant_intelligence_settings: IntelligenceSettingsSnapshot = intelligenceSettingsRaw
    ? {
        memory_enabled: safeBoolean(intelligenceSettingsRaw.memory_enabled),
        min_confidence_threshold: safeNumber(intelligenceSettingsRaw.min_confidence_threshold, 0.65),
        min_observation_threshold: safeNumber(intelligenceSettingsRaw.min_observation_threshold, 3),
        share_memory_across_locations: safeBoolean(intelligenceSettingsRaw.share_memory_across_locations),
      }
    : getDefaultIntelligenceSettings();

  const intent_rules: IntentRuleSnapshot[] = safeArray(intentRulesResult.data).map((r: any) => ({
    id: safeString(r.id),
    name: safeString(r.name),
    rule_type: safeString(r.rule_type),
    description: safeString(r.description),
    condition_json: safeObject(r.condition_json),
    action_json: safeObject(r.action_json),
    priority: safeNumber(r.priority),
    is_enabled: safeBoolean(r.is_enabled, true),
  }));

  // Extract required questions from intent rules
  const required_questions: RequiredQuestionSnapshot[] = intent_rules
    .filter((r) => r.rule_type === "required_inputs" && r.action_json)
    .map((r) => {
      const action = r.action_json as any;
      return {
        intent: safeString(action.intent),
        required_inputs: safeArray(action.required_inputs).map((input: any) => ({
          key: safeString(input.key),
          label: safeString(input.label),
          ask_prompt: safeString(input.ask_prompt),
          why_needed: safeString(input.why_needed),
        })),
        optional_inputs: safeArray(action.optional_inputs).map((input: any) => ({
          key: safeString(input.key),
          label: safeString(input.label),
          ask_prompt: safeString(input.ask_prompt),
          why_needed: safeString(input.why_needed),
        })),
      };
    })
    .filter((q) => q.intent);

  const availability_slots: AvailabilitySlotSnapshot[] = safeArray(availabilitySlotsResult.data).map((s: any) => ({
    id: safeString(s.id),
    day_of_week: safeNumber(s.day_of_week),
    start_time: safeString(s.start_time),
    end_time: safeString(s.end_time),
    is_available: safeBoolean(s.is_available, true),
  }));

  // Extract pricing rules from tenant JSON
  const pricingRulesRaw = tenant.pricing_rules_jsonb?.rules || tenant.pricing_rules_jsonb || [];
  const pricing_rules: PricingRuleSnapshot[] = safeArray(pricingRulesRaw).map((r: any) => ({
    type: safeString(r.type) || "quote_only",
    service_name: safeString(r.service_name),
    base_price: r.base_price,
    per_unit_price: r.per_unit_price,
    unit_label: safeString(r.unit_label),
    required_inputs: safeArray(r.required_inputs),
    min_price: r.min_price,
    max_price: r.max_price,
  }));

  // Food-specific data (empty if not food mode)
  let menu_items: MenuItemSnapshot[] = [];
  let food_order_settings: FoodOrderSettingsSnapshot = getDefaultFoodOrderSettings();

  if (isFoodMode) {
    menu_items = safeArray(menuItemsResult.data).map((m: any) => ({
      id: safeString(m.id),
      name: safeString(m.name),
      description: safeString(m.description),
      category: safeString(m.category) || "Menu",
      price_cents: m.price_cents,
      modifiers: safeArray(m.modifiers),
      dietary_tags: safeArray(m.dietary_tags),
      is_available: safeBoolean(m.is_available, true),
      prep_time_minutes: m.prep_time_minutes,
    }));

    const foodSettingsRaw = foodSettingsResult?.data;
    if (foodSettingsRaw) {
      food_order_settings = {
        estimated_prep_minutes: safeNumber(foodSettingsRaw.estimated_prep_minutes, 15),
        accepts_pickup: safeBoolean(foodSettingsRaw.accepts_pickup, true),
        accepts_delivery: safeBoolean(foodSettingsRaw.accepts_delivery),
        accepts_dine_in: safeBoolean(foodSettingsRaw.accepts_dine_in, true),
        delivery_radius_miles: foodSettingsRaw.delivery_radius_miles,
        delivery_minimum_cents: foodSettingsRaw.delivery_minimum_cents,
        accepts_catering: safeBoolean(foodSettingsRaw.accepts_catering),
        catering_min_guests: foodSettingsRaw.catering_min_guests,
        catering_lead_days: foodSettingsRaw.catering_lead_days,
        order_confirmation_mode: safeString(foodSettingsRaw.order_confirmation_mode) || "auto_confirm",
      };
    }
  }

  // Transform mode-specific knowledge with safe defaults
  const menu_knowledge: MenuKnowledgeSnapshot[] = safeArray(menuKnowledgeResult.data).map((m: any) => ({
    item_name: safeString(m.item_name),
    description: safeString(m.detailed_description),
    ingredients: safeArray(m.ingredients),
    allergens: safeArray(m.allergens),
    dietary_tags: safeArray(m.dietary_tags),
    pairing_suggestions: safeString(m.pairing_suggestions),
    chef_notes: safeString(m.chef_notes),
    spice_level: safeNumber(m.spice_level),
    is_signature: safeBoolean(m.is_signature),
  }));

  const catering_knowledge: CateringKnowledgeSnapshot[] = safeArray(cateringKnowledgeResult.data).map((c: any) => ({
    event_type: safeString(c.event_type),
    min_guests: c.min_guests,
    max_guests: c.max_guests,
    lead_time_days: c.lead_time_days,
    deposit_percentage: c.deposit_percentage,
    ai_script: safeString(c.ai_script),
  }));

  const vehicle_knowledge: VehicleKnowledgeSnapshot[] = safeArray(vehicleKnowledgeResult.data).map((v: any) => ({
    vehicle_category: safeString(v.vehicle_category),
    equipment_required: safeArray(v.equipment_required),
    weight_class: safeString(v.weight_class),
    special_instructions: safeString(v.special_instructions),
    additional_fees_apply: safeBoolean(v.additional_fees_apply),
    fee_notes: safeString(v.fee_notes),
  }));

  const roadside_knowledge: RoadsideKnowledgeSnapshot[] = safeArray(roadsideKnowledgeResult.data).map((r: any) => ({
    situation_type: safeString(r.situation_type),
    safety_instructions: safeString(r.safety_instructions),
    estimated_service_time_minutes: r.estimated_service_time_minutes,
    escalation_triggers: safeArray(r.escalation_triggers),
    priority_level: safeString(r.priority_level),
    ai_script: safeString(r.ai_script),
  }));

  const symptom_triage: SymptomTriageSnapshot[] = safeArray(symptomTriageResult.data).map((s: any) => ({
    symptom_category: safeString(s.symptom_category),
    symptom_name: safeString(s.symptom_name),
    severity_indicators: safeArray(s.severity_indicators),
    escalation_action: safeString(s.escalation_action),
    can_be_telehealth: safeBoolean(s.can_be_telehealth, true),
    hipaa_safe_response: safeString(s.hipaa_safe_response),
  }));

  const insurance_knowledge: InsuranceKnowledgeSnapshot[] = safeArray(insuranceKnowledgeResult.data).map((i: any) => ({
    carrier_name: safeString(i.carrier_name),
    plan_types: safeArray(i.plan_types),
    is_accepted: safeBoolean(i.is_accepted, true),
    copay_typical_range: safeString(i.copay_typical_range),
    patient_script: safeString(i.patient_script),
  }));

  const product_knowledge: ProductKnowledgeSnapshot[] = safeArray(productKnowledgeResult.data).map((p: any) => ({
    product_name: safeString(p.product_name),
    brand: safeString(p.brand),
    benefits: safeArray(p.benefits),
    is_premium: safeBoolean(p.is_premium),
    upsell_script: safeString(p.upsell_script),
  }));

  const aftercare: AftercareSnapshot[] = safeArray(aftercareResult.data).map((a: any) => ({
    service_name: safeString(a.service_name),
    immediate_care: safeArray(a.immediate_care),
    things_to_avoid: safeArray(a.things_to_avoid),
    warning_signs: safeArray(a.warning_signs),
    follow_up_timeframe: safeString(a.follow_up_timeframe),
  }));

  const competitors: CompetitorKnowledgeSnapshot[] = safeArray(competitorResult.data).map((c: any) => ({
    competitor_name: safeString(c.competitor_name),
    our_advantage: safeArray(c.our_advantage),
    response_script: safeString(c.response_script),
  }));

  const seasonal: SeasonalKnowledgeSnapshot[] = safeArray(seasonalResult.data).map((s: any) => ({
    event_name: safeString(s.event_name),
    special_hours: safeString(s.special_hours),
    special_pricing_notes: safeString(s.special_pricing_notes),
    ai_announcement: safeString(s.ai_announcement),
  }));

  // Transform workflow configs with safe defaults
  const dispatchWorkflowRaw = dispatchWorkflowResult?.data;
  const dispatch_workflow: DispatchWorkflowConfigSnapshot | null = dispatchWorkflowRaw
    ? {
        vehicle_info_timing: safeString(dispatchWorkflowRaw.vehicle_info_timing) || "before_pricing",
        vehicle_affects_pricing: safeBoolean(dispatchWorkflowRaw.vehicle_affects_pricing, true),
        required_vehicle_fields: safeArray(dispatchWorkflowRaw.required_vehicle_fields),
        luxury_flatbed_recommendation: safeBoolean(dispatchWorkflowRaw.luxury_flatbed_recommendation),
        luxury_brands: safeArray(dispatchWorkflowRaw.luxury_brands),
        awd_detection_enabled: safeBoolean(dispatchWorkflowRaw.awd_detection_enabled),
        motorcycle_special_handling: safeBoolean(dispatchWorkflowRaw.motorcycle_special_handling),
        ask_payment_method: safeBoolean(dispatchWorkflowRaw.ask_payment_method, true),
        payment_timing: safeString(dispatchWorkflowRaw.payment_timing) || "on_arrival",
        require_payment_confirmation: safeBoolean(dispatchWorkflowRaw.require_payment_confirmation),
        accepted_methods: safeArray(dispatchWorkflowRaw.accepted_methods),
        payment_due_message: safeString(dispatchWorkflowRaw.payment_due_message),
        confirm_geocoded_address: safeBoolean(dispatchWorkflowRaw.confirm_geocoded_address, true),
        require_zip_code: safeBoolean(dispatchWorkflowRaw.require_zip_code),
        address_confirmation_script: safeString(dispatchWorkflowRaw.address_confirmation_script),
        driver_callback_script: safeString(dispatchWorkflowRaw.driver_callback_script),
        include_direct_contact_info: safeBoolean(dispatchWorkflowRaw.include_direct_contact_info),
        escalation_number: safeString(dispatchWorkflowRaw.escalation_number),
        service_dropoff_rules: safeObject(dispatchWorkflowRaw.service_dropoff_rules),
      }
    : null;

  const serviceWorkflowRaw = serviceWorkflowResult?.data;
  const service_workflow: ServiceWorkflowConfigSnapshot | null = serviceWorkflowRaw
    ? {
        collect_service_duration: safeBoolean(serviceWorkflowRaw.collect_service_duration, true),
        collect_deposit_upfront: safeBoolean(serviceWorkflowRaw.collect_deposit_upfront),
        deposit_timing: safeString(serviceWorkflowRaw.deposit_timing) || "at_confirmation",
        deposit_amount_behavior: safeString(serviceWorkflowRaw.deposit_amount_behavior) || "percentage",
        default_deposit_percentage: safeNumber(serviceWorkflowRaw.default_deposit_percentage, 50),
        required_intake_questions: safeArray(serviceWorkflowRaw.required_intake_questions),
        suggest_alternatives_when_unavailable: safeBoolean(serviceWorkflowRaw.suggest_alternatives_when_unavailable, true),
        max_alternatives_to_suggest: safeNumber(serviceWorkflowRaw.max_alternatives_to_suggest, 3),
        alternative_suggestion_window_days: safeNumber(serviceWorkflowRaw.alternative_suggestion_window_days, 7),
        booking_confirmation_script: safeString(serviceWorkflowRaw.booking_confirmation_script),
        send_sms_confirmation: safeBoolean(serviceWorkflowRaw.send_sms_confirmation, true),
        ask_for_email_confirmation: safeBoolean(serviceWorkflowRaw.ask_for_email_confirmation),
        allow_ai_rescheduling: safeBoolean(serviceWorkflowRaw.allow_ai_rescheduling, true),
        allow_ai_cancellation: safeBoolean(serviceWorkflowRaw.allow_ai_cancellation),
        cancellation_requires_manager: safeBoolean(serviceWorkflowRaw.cancellation_requires_manager),
      }
    : null;

  const foodWorkflowRaw = foodWorkflowResult?.data;
  const food_workflow: FoodWorkflowConfigSnapshot | null = foodWorkflowRaw
    ? {
        ask_pickup_vs_delivery: safeString(foodWorkflowRaw.ask_pickup_vs_delivery) || "if_both_enabled",
        default_order_type: safeString(foodWorkflowRaw.default_order_type) || "ask",
        allow_menu_customizations: safeBoolean(foodWorkflowRaw.allow_menu_customizations, true),
        require_allergy_check: safeBoolean(foodWorkflowRaw.require_allergy_check),
        ask_special_instructions: safeBoolean(foodWorkflowRaw.ask_special_instructions, true),
        ask_asap_vs_scheduled: safeBoolean(foodWorkflowRaw.ask_asap_vs_scheduled, true),
        min_advance_order_minutes: safeNumber(foodWorkflowRaw.min_advance_order_minutes, 30),
        default_prep_time_minutes: safeNumber(foodWorkflowRaw.default_prep_time_minutes, 20),
        collect_delivery_instructions: safeBoolean(foodWorkflowRaw.collect_delivery_instructions, true),
        require_buzzer_code: safeBoolean(foodWorkflowRaw.require_buzzer_code),
        order_confirmation_script: safeString(foodWorkflowRaw.order_confirmation_script),
        repeat_order_back: safeBoolean(foodWorkflowRaw.repeat_order_back, true),
        confirm_total_before_submit: safeBoolean(foodWorkflowRaw.confirm_total_before_submit, true),
      }
    : null;

  const medicalWorkflowRaw = medicalWorkflowResult?.data;
  const medical_workflow: MedicalWorkflowConfigSnapshot | null = medicalWorkflowRaw
    ? {
        consent_timing: safeString(medicalWorkflowRaw.consent_timing) || "before_intake",
        consent_script: safeString(medicalWorkflowRaw.consent_script),
        require_explicit_consent: safeBoolean(medicalWorkflowRaw.require_explicit_consent, true),
        collect_symptom_details: safeBoolean(medicalWorkflowRaw.collect_symptom_details, true),
        symptom_severity_scale: safeBoolean(medicalWorkflowRaw.symptom_severity_scale, true),
        ask_duration_of_symptoms: safeBoolean(medicalWorkflowRaw.ask_duration_of_symptoms, true),
        required_intake_questions: safeArray(medicalWorkflowRaw.required_intake_questions),
        detect_emergency_keywords: safeBoolean(medicalWorkflowRaw.detect_emergency_keywords, true),
        emergency_escalation_script: safeString(medicalWorkflowRaw.emergency_escalation_script),
      }
    : null;

  const generalWorkflowRaw = generalWorkflowResult?.data;
  const general_workflow: GeneralWorkflowConfigSnapshot | null = generalWorkflowRaw
    ? {
        qualification_questions: safeArray(generalWorkflowRaw.qualification_questions),
        callback_confirmation_script: safeString(generalWorkflowRaw.callback_confirmation_script),
        ask_best_time_to_call: safeBoolean(generalWorkflowRaw.ask_best_time_to_call, true),
        ask_callback_reason: safeBoolean(generalWorkflowRaw.ask_callback_reason, true),
        escalate_unknown_questions: safeBoolean(generalWorkflowRaw.escalate_unknown_questions, true),
        unknown_question_script: safeString(generalWorkflowRaw.unknown_question_script),
      }
    : null;

  // Transform impound data (for dispatch businesses with impound capability)
  const impoundLotRaw = impoundLotResult?.data;
  const impoundSettingsRaw = impoundSettingsResult?.data;

  // Helper to format hours for today
  const formatTodayHours = (hoursJson: any): string => {
    if (!hoursJson) return "";
    const today = new Date().toLocaleDateString("en-US", { weekday: "lowercase" as any, timeZone: timezone });
    const todayHours = hoursJson[today];
    if (!todayHours?.open || !todayHours?.close) return "Closed";
    return `${todayHours.open} to ${todayHours.close}`;
  };

  // Helper to format hours summary for speech
  const formatHoursSummary = (hoursJson: any): string => {
    if (!hoursJson) return "";
    const days = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"];
    const parts: string[] = [];
    for (const day of days) {
      const hours = hoursJson[day];
      if (hours?.open && hours?.close) {
        parts.push(`${day}: ${hours.open}-${hours.close}`);
      }
    }
    return parts.join(", ");
  };

  // Helper to format fee summary
  const formatFeeSummary = (settings: any): string => {
    if (!settings) return "";
    const baseTow = (settings.base_tow_fee_cents || 0) / 100;
    const storage = (settings.daily_storage_cents || 0) / 100;
    const admin = (settings.admin_fee_cents || 0) / 100;
    const gate = (settings.gate_fee_cents || 0) / 100;
    return `Base tow $${baseTow}, $${storage} per day storage, $${admin} admin fee, $${gate} gate fee`;
  };

  // Helper to format release requirements summary
  const formatRequirementsSummary = (requirements: string[]): string => {
    if (!requirements || requirements.length === 0) return "";
    const labels: Record<string, string> = {
      valid_id: "valid ID",
      registration: "vehicle registration",
      insurance: "proof of insurance",
      lien_release: "lien release",
      police_release: "police release",
      payment: "payment in full",
    };
    return requirements.map(r => labels[r] || r).join(", ");
  };

  // Helper to format payment methods summary
  const formatPaymentSummary = (methods: string[]): string => {
    if (!methods || methods.length === 0) return "";
    const labels: Record<string, string> = {
      cash: "Cash",
      credit_card: "Credit Card",
      debit_card: "Debit Card",
      check: "Check",
      money_order: "Money Order",
    };
    return methods.map(m => labels[m] || m).join(" or ");
  };

  const impound: ImpoundSnapshot | null = impoundLotRaw && impoundSettingsRaw
    ? {
        lot_id: safeString(impoundLotRaw.id),
        lot_name: safeString(impoundLotRaw.name),
        lot_address: [
          safeString(impoundLotRaw.address),
          safeString(impoundLotRaw.city),
          safeString(impoundLotRaw.state),
          safeString(impoundLotRaw.zip),
        ].filter(Boolean).join(", "),
        lot_phone: safeString(impoundLotRaw.phone),
        lot_hours_json: impoundLotRaw.hours_json || {},
        lot_hours_today: formatTodayHours(impoundLotRaw.hours_json),
        lot_hours_summary: formatHoursSummary(impoundLotRaw.hours_json),
        is_open_now: false, // TODO: Calculate based on current time and hours
        next_open: "", // TODO: Calculate next open time
        base_tow_fee_cents: impoundSettingsRaw.base_tow_fee_cents || 15000,
        daily_storage_cents: impoundSettingsRaw.daily_storage_cents || 3500,
        admin_fee_cents: impoundSettingsRaw.admin_fee_cents || 2500,
        gate_fee_cents: impoundSettingsRaw.gate_fee_cents || 5000,
        fee_summary: formatFeeSummary(impoundSettingsRaw),
        release_requirements: safeArray(impoundSettingsRaw.default_release_requirements),
        release_requirements_summary: formatRequirementsSummary(safeArray(impoundSettingsRaw.default_release_requirements)),
        accepted_payment_summary: formatPaymentSummary(safeArray(impoundSettingsRaw.accepted_payment)),
      }
    : null;

  // Count total mode-specific knowledge items
  const modeKnowledgeCount = menu_knowledge.length + catering_knowledge.length +
    vehicle_knowledge.length + roadside_knowledge.length +
    symptom_triage.length + insurance_knowledge.length +
    product_knowledge.length + aftercare.length +
    competitors.length + seasonal.length;

  // Build section counts for logging
  const section_counts = {
    services: services.length,
    faqs: faqs.length,
    objections: objections.length,
    knowledge: knowledge.length,
    intent_rules: intent_rules.length,
    required_questions: required_questions.length,
    availability_slots: availability_slots.length,
    pricing_rules: pricing_rules.length,
    menu_items: menu_items.length,
    mode_knowledge: modeKnowledgeCount,
  };

  // STEP 4: Return complete snapshot
  return {
    tenant,
    services,
    faqs,
    objections,
    knowledge,
    assistant_settings,
    tenant_intelligence_settings,
    intent_rules,
    required_questions,
    availability_slots,
    pricing_rules,
    food: {
      menu_categories: [], // menu_categories table doesn't exist - derived from menu_items
      menu_items,
      food_order_settings,
    },
    mode_knowledge: {
      menu_knowledge,
      catering_knowledge,
      vehicle_knowledge,
      roadside_knowledge,
      symptom_triage,
      insurance_knowledge,
      product_knowledge,
      aftercare,
      competitors,
      seasonal,
    },
    workflow_config: {
      dispatch: dispatch_workflow,
      service: service_workflow,
      food: food_workflow,
      medical: medical_workflow,
      general: general_workflow,
    },
    impound,
    _meta: {
      fetched_at: new Date().toISOString(),
      tenant_id: tenantId,
      business_mode: businessMode,
      section_counts,
    },
  };
}

// ============= SUMMARY BUILDER =============

/**
 * Build a compact AI-facing summary string from Business Brain snapshot.
 * This summary enumerates key facts for the voice AI.
 */
export function buildBusinessBrainSummary(snapshot: BusinessBrainSnapshot): string {
  const parts: string[] = [];
  const t = snapshot.tenant;

  // Business identity
  parts.push(`Business: ${t.name || "Unknown"}`);
  if (t.address) parts.push(`Location: ${t.address}`);

  // Service area
  if (t.service_area_json) {
    const sa = t.service_area_json;
    if (sa.radius_miles || sa.miles) {
      parts.push(`Service area: ${sa.radius_miles || sa.miles}-mile radius`);
    } else if (sa.zip_codes?.length) {
      parts.push(`Service area: ${sa.zip_codes.length} ZIP codes`);
    }
  }

  // Hours
  if (Object.keys(t.hours_json).length > 0) {
    parts.push(`Hours: configured`);
  }

  // Mode and modules
  parts.push(`Mode: ${t.business_mode}`);
  if (t.enabled_modules.length > 0) {
    parts.push(`Modules: ${t.enabled_modules.join(", ")}`);
  }

  // Policies
  const policiesCount = [t.cancellation_policy, t.deposit_policy, t.refund_policy].filter(Boolean).length;
  if (policiesCount > 0) {
    parts.push(`Policies: ${policiesCount} configured`);
  }

  // Booking mode
  if (snapshot.assistant_settings.ai_booking_mode) {
    parts.push(`Booking: ${snapshot.assistant_settings.ai_booking_mode}`);
  }

  // Section counts
  const counts = snapshot._meta.section_counts;
  const countParts: string[] = [];
  if (counts.services > 0) countParts.push(`${counts.services} services`);
  if (counts.menu_items > 0) countParts.push(`${counts.menu_items} menu items`);
  if (counts.faqs > 0) countParts.push(`${counts.faqs} FAQs`);
  if (counts.objections > 0) countParts.push(`${counts.objections} objection responses`);
  if (counts.intent_rules > 0) countParts.push(`${counts.intent_rules} intent rules`);
  if (counts.required_questions > 0) countParts.push(`${counts.required_questions} required question configs`);
  if (counts.pricing_rules > 0) countParts.push(`${counts.pricing_rules} pricing rules`);

  if (countParts.length > 0) {
    parts.push(`Knowledge: ${countParts.join(", ")}`);
  }

  return parts.join(". ") + ".";
}

/**
 * Serialize Business Brain snapshot to JSON with size awareness.
 * Returns truncated version if exceeds safe limit.
 */
export function serializeBusinessBrainSnapshot(
  snapshot: BusinessBrainSnapshot,
  maxSize: number = 20000
): { json: string; truncated: boolean } {
  // First try full serialization
  const fullJson = JSON.stringify(snapshot);

  if (fullJson.length <= maxSize) {
    return { json: fullJson, truncated: false };
  }

  // Reduce to essential fields only
  const reduced = {
    tenant: {
      id: snapshot.tenant.id,
      name: snapshot.tenant.name,
      business_mode: snapshot.tenant.business_mode,
      timezone: snapshot.tenant.timezone,
      address: snapshot.tenant.address,
      hours_json: snapshot.tenant.hours_json,
      enabled_modules: snapshot.tenant.enabled_modules,
    },
    services: snapshot.services.slice(0, 15).map((s) => ({
      name: s.name,
      price_type: s.price_type,
      price_amount: s.price_amount,
      duration_minutes: s.duration_minutes,
    })),
    assistant_settings: snapshot.assistant_settings,
    required_questions: snapshot.required_questions.slice(0, 5),
    intent_rules: snapshot.intent_rules.slice(0, 10).map((r) => ({
      name: r.name,
      rule_type: r.rule_type,
      action_json: r.action_json,
    })),
    _meta: snapshot._meta,
  };

  const reducedJson = JSON.stringify(reduced);

  // Final safety truncation
  if (reducedJson.length > maxSize) {
    return {
      json: reducedJson.substring(0, maxSize - 20) + '..."truncated"}',
      truncated: true,
    };
  }

  return { json: reducedJson, truncated: true };
}

/**
 * HERE Geocoding API integration
 *
 * HERE provides superior geocoding for:
 * - Cross streets (e.g., "Main St and Oak Ave")
 * - Highway routes with mile markers (e.g., "Route 539, mile marker 15")
 * - Intersections and landmarks
 * - Dispatch/towing use cases
 *
 * Requires HERE_API_KEY environment variable.
 */

export interface HereGeocodeResult {
  ok: boolean;
  lat: number | null;
  lng: number | null;
  place_name: string | null;
  relevance: number;
  match_level: string | null;
  error: string | null;
  // For debugging
  raw_result_type: string | null;
}

interface HereGeocodeResponse {
  items?: Array<{
    title: string;
    position: {
      lat: number;
      lng: number;
    };
    scoring?: {
      queryScore: number;
      fieldScore?: {
        streets?: number[];
        houseNumber?: number;
      };
    };
    resultType?: string;
    address?: {
      label?: string;
      countryCode?: string;
      countryName?: string;
      state?: string;
      county?: string;
      city?: string;
      district?: string;
      street?: string;
      postalCode?: string;
      houseNumber?: string;
    };
  }>;
  error?: string;
  error_description?: string;
}

/**
 * Geocode an address using HERE Geocoding & Search API
 *
 * @param address - The address to geocode
 * @param options - Optional parameters
 * @returns Geocoding result with coordinates and confidence
 */
export async function geocodeWithHere(
  address: string,
  options?: {
    /** State hint to improve accuracy (e.g., "NJ", "New Jersey") */
    stateHint?: string;
    /** Country code for regional bias (default: "USA") */
    countryCode?: string;
    /** Optional lat/lng to bias results toward */
    proximityLat?: number;
    proximityLng?: number;
    /** Radius for proximity bias in meters (default: 50000 = 50km) */
    proximityRadius?: number;
  }
): Promise<HereGeocodeResult> {
  const apiKey = Deno.env.get("HERE_API_KEY");

  if (!apiKey) {
    console.error("[here_geocode] HERE_API_KEY not configured");
    return {
      ok: false,
      lat: null,
      lng: null,
      place_name: null,
      relevance: 0,
      match_level: null,
      error: "HERE API key not configured",
      raw_result_type: null,
    };
  }

  try {
    // Build the query with optional state hint
    let queryAddress = address.trim();
    const stateHint = options?.stateHint;

    // Check if address already has a state
    const hasState =
      /,\s*[A-Z]{2}\b/.test(queryAddress) ||
      /\b(Alabama|Alaska|Arizona|Arkansas|California|Colorado|Connecticut|Delaware|Florida|Georgia|Hawaii|Idaho|Illinois|Indiana|Iowa|Kansas|Kentucky|Louisiana|Maine|Maryland|Massachusetts|Michigan|Minnesota|Mississippi|Missouri|Montana|Nebraska|Nevada|New Hampshire|New Jersey|New Mexico|New York|North Carolina|North Dakota|Ohio|Oklahoma|Oregon|Pennsylvania|Rhode Island|South Carolina|South Dakota|Tennessee|Texas|Utah|Vermont|Virginia|Washington|West Virginia|Wisconsin|Wyoming)\b/i.test(
        queryAddress
      );

    if (!hasState && stateHint) {
      queryAddress = `${queryAddress}, ${stateHint}`;
    }

    // Build URL with parameters
    const url = new URL("https://geocode.search.hereapi.com/v1/geocode");
    url.searchParams.set("q", queryAddress);
    url.searchParams.set("apiKey", apiKey);
    url.searchParams.set("limit", "1");

    // Country filter
    if (options?.countryCode) {
      url.searchParams.set("in", `countryCode:${options.countryCode}`);
    } else {
      url.searchParams.set("in", "countryCode:USA");
    }

    // Proximity bias - helps with vague addresses near business location
    if (options?.proximityLat !== undefined && options?.proximityLng !== undefined) {
      const radius = options?.proximityRadius || 50000;
      url.searchParams.set("at", `${options.proximityLat},${options.proximityLng}`);
    }

    console.log(`[here_geocode] Geocoding: "${queryAddress.substring(0, 50)}..."`);

    const response = await fetch(url.toString(), {
      method: "GET",
      headers: { Accept: "application/json" },
    });

    if (!response.ok) {
      console.error(`[here_geocode] HTTP error: ${response.status}`);
      return {
        ok: false,
        lat: null,
        lng: null,
        place_name: null,
        relevance: 0,
        match_level: null,
        error: `HERE API returned HTTP ${response.status}`,
        raw_result_type: null,
      };
    }

    const data: HereGeocodeResponse = await response.json();

    if (data.error) {
      console.error(`[here_geocode] API error: ${data.error_description || data.error}`);
      return {
        ok: false,
        lat: null,
        lng: null,
        place_name: null,
        relevance: 0,
        match_level: null,
        error: data.error_description || data.error,
        raw_result_type: null,
      };
    }

    if (!data.items || data.items.length === 0) {
      console.log(`[here_geocode] No results found for: "${queryAddress.substring(0, 50)}..."`);
      return {
        ok: false,
        lat: null,
        lng: null,
        place_name: null,
        relevance: 0,
        match_level: null,
        error: "Address not found",
        raw_result_type: null,
      };
    }

    const item = data.items[0];
    const { lat, lng } = item.position;
    const placeName = item.address?.label || item.title;
    const relevance = item.scoring?.queryScore || 0.5;
    const matchLevel = item.resultType || null;

    console.log(
      `[here_geocode] Result: lat=${lat.toFixed(5)}, lng=${lng.toFixed(5)}, relevance=${relevance.toFixed(2)}, type=${matchLevel}`
    );

    return {
      ok: true,
      lat,
      lng,
      place_name: placeName,
      relevance,
      match_level: matchLevel,
      error: null,
      raw_result_type: matchLevel,
    };
  } catch (error) {
    console.error("[here_geocode] Error:", error);
    return {
      ok: false,
      lat: null,
      lng: null,
      place_name: null,
      relevance: 0,
      match_level: null,
      error: error instanceof Error ? error.message : "HERE geocoding failed",
      raw_result_type: null,
    };
  }
}

/**
 * Special handling for cross-street queries
 * HERE is better at parsing "Main St and Oak Ave" or "Route 9 at Mile Marker 15"
 */
export function isCrossStreetOrRouteQuery(address: string): boolean {
  const lowerAddr = address.toLowerCase();

  // Cross street patterns
  const crossStreetPatterns = [
    / and /,
    / & /,
    / at /,
    /\//, // "Main St / Oak Ave"
    / corner of /,
    / intersection of /,
    / near /,
  ];

  // Route/highway patterns
  const routePatterns = [
    /\broute\s+\d+/i,
    /\brt\.?\s*\d+/i,
    /\bhwy\.?\s*\d+/i,
    /\bhighway\s+\d+/i,
    /\bi-\d+/i, // Interstate
    /\bus-\d+/i, // US route
    /\bmile\s*marker/i,
    /\bmm\s*\d+/i,
    /\bexit\s+\d+/i,
  ];

  const hasCrossStreet = crossStreetPatterns.some((p) => p.test(lowerAddr));
  const hasRoute = routePatterns.some((p) => p.test(lowerAddr));

  return hasCrossStreet || hasRoute;
}

/**
 * Input Validators for Required Questions
 *
 * These validators enforce data quality beyond just "non-empty".
 * Each validator returns { valid: boolean, reason?: string }
 */

export interface ValidationResult {
  valid: boolean;
  reason?: string;
}

/**
 * Address Validator - For dispatch pickup/dropoff
 *
 * Requirements:
 * - Must include street number OR cross streets (indicated by "&", "and", "corner of", "x")
 * - Must include city OR ZIP code
 *
 * Valid examples:
 * - "123 Main Street, Chicago"
 * - "123 Main St, 60601"
 * - "Corner of Main and Oak, Springfield"
 * - "Main & 5th, 62701"
 * - "Exit 42 on I-94, Detroit"
 *
 * Invalid examples:
 * - "downtown" (no specificity)
 * - "Main Street" (no number or cross street)
 * - "123 Main" (no city or ZIP)
 */
export function validateAddress(value: string): ValidationResult {
  if (!value || value.trim().length === 0) {
    return { valid: false, reason: "Address cannot be empty" };
  }

  const normalized = value.toLowerCase().trim();

  // Check for cross streets indicators
  const hasCrossStreets = /(&|and|corner of|\sx\s|intersection)/i.test(normalized);

  // Check for street number (1-5 digits at start or after common prefixes)
  const hasStreetNumber = /^\d{1,5}\s|^#\d{1,5}|\s\d{1,5}\s/.test(value);

  // Check for exit/mile marker (common on highways)
  const hasExitOrMarker = /exit\s+\d+|mile\s+marker\s+\d+|mm\s+\d+/i.test(normalized);

  // Must have street number, cross streets, or exit/marker
  if (!hasStreetNumber && !hasCrossStreets && !hasExitOrMarker) {
    return {
      valid: false,
      reason: "Address must include a street number (e.g., '123 Main St') OR cross streets (e.g., 'Main & Oak') OR exit number (e.g., 'Exit 42 on I-94')"
    };
  }

  // Check for city name (2+ letters, common city patterns)
  const hasCity = /,\s*[a-z]{2,}(?:\s+[a-z]+)*(?:\s*,|\s*$)/i.test(value) ||
                  /\s(?:in|near)\s+[a-z]{2,}/i.test(normalized);

  // Check for ZIP code (5 digits or 5+4 format)
  const hasZip = /\b\d{5}(?:-\d{4})?\b/.test(value);

  // Must have city or ZIP
  if (!hasCity && !hasZip) {
    return {
      valid: false,
      reason: "Address must include a city (e.g., 'Chicago', 'in Springfield') OR ZIP code (e.g., '60601')"
    };
  }

  return { valid: true };
}

/**
 * Date Validator
 *
 * Accepts various date formats:
 * - "tomorrow", "today", "next Monday"
 * - "12/25", "12/25/2024", "Dec 25", "December 25th"
 * - ISO format "2024-12-25"
 *
 * Invalid:
 * - "soon", "later", "sometime" (too vague)
 */
export function validateDate(value: string): ValidationResult {
  if (!value || value.trim().length === 0) {
    return { valid: false, reason: "Date cannot be empty" };
  }

  const normalized = value.toLowerCase().trim();

  // Relative dates (acceptable)
  const relativePatterns = /^(today|tomorrow|next\s+\w+|this\s+\w+|in\s+\d+\s+days?)$/i;
  if (relativePatterns.test(normalized)) {
    return { valid: true };
  }

  // Too vague
  const vaguePatterns = /^(soon|later|sometime|eventually|whenever)$/i;
  if (vaguePatterns.test(normalized)) {
    return {
      valid: false,
      reason: "Please provide a specific date like 'tomorrow', 'December 25th', or '12/25'"
    };
  }

  // Numeric date formats
  const numericDate = /\d{1,2}[\/\-]\d{1,2}(?:[\/\-]\d{2,4})?/;
  if (numericDate.test(value)) {
    return { valid: true };
  }

  // Month name formats
  const monthNameDate = /(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+\d{1,2}(?:st|nd|rd|th)?/i;
  if (monthNameDate.test(normalized)) {
    return { valid: true };
  }

  // ISO format
  const isoDate = /\d{4}-\d{2}-\d{2}/;
  if (isoDate.test(value)) {
    return { valid: true };
  }

  return {
    valid: false,
    reason: "Please provide a specific date like 'tomorrow', 'December 25th', or '12/25'"
  };
}

/**
 * Time Validator
 *
 * Accepts:
 * - "2pm", "2:30pm", "14:30"
 * - "morning", "afternoon", "evening" (general)
 * - "around 2pm", "before 3pm"
 *
 * Invalid:
 * - "later", "sometime" (too vague)
 */
export function validateTime(value: string): ValidationResult {
  if (!value || value.trim().length === 0) {
    return { valid: false, reason: "Time cannot be empty" };
  }

  const normalized = value.toLowerCase().trim();

  // Too vague
  const vaguePatterns = /^(later|sometime|eventually|whenever|asap)$/i;
  if (vaguePatterns.test(normalized)) {
    return {
      valid: false,
      reason: "Please provide a specific time like '2pm', 'morning', or 'around 3:00'"
    };
  }

  // Specific times (12/24 hour)
  const specificTime = /\d{1,2}(?::\d{2})?\s*(?:am|pm)?|(?:around|before|after|by)\s+\d{1,2}/i;
  if (specificTime.test(normalized)) {
    return { valid: true };
  }

  // General time of day (acceptable for initial booking)
  const generalTime = /^(morning|afternoon|evening|night|midday|noon)$/i;
  if (generalTime.test(normalized)) {
    return { valid: true };
  }

  return {
    valid: false,
    reason: "Please provide a time like '2pm', 'morning', or 'around 3:00'"
  };
}

/**
 * Miles/Distance Validator
 *
 * Accepts:
 * - "5", "5 miles", "about 10 miles"
 * - "5-10 miles" (range)
 *
 * Invalid:
 * - "not far", "close by" (no number)
 * - "1000 miles" (unreasonable for dispatch)
 */
export function validateMiles(value: string): ValidationResult {
  if (!value || value.trim().length === 0) {
    return { valid: false, reason: "Distance cannot be empty" };
  }

  const normalized = value.toLowerCase().trim();

  // Too vague
  if (/^(close|nearby|not far|short|long)$/i.test(normalized)) {
    return {
      valid: false,
      reason: "Please provide an estimated distance in miles, like '5 miles' or 'about 10'"
    };
  }

  // Extract number(s)
  const numbers = value.match(/\d+(?:\.\d+)?/g);
  if (!numbers || numbers.length === 0) {
    return {
      valid: false,
      reason: "Please provide a number of miles, like '5 miles' or 'about 10'"
    };
  }

  // Check if reasonable (1-500 miles)
  const miles = parseFloat(numbers[0]);
  if (miles < 1) {
    return {
      valid: false,
      reason: "Distance must be at least 1 mile"
    };
  }

  if (miles > 500) {
    return {
      valid: false,
      reason: "Distance seems unusually high. Please confirm the distance in miles."
    };
  }

  return { valid: true };
}

/**
 * Email Validator
 *
 * Basic email format validation
 */
export function validateEmail(value: string): ValidationResult {
  if (!value || value.trim().length === 0) {
    return { valid: false, reason: "Email cannot be empty" };
  }

  const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailPattern.test(value.trim())) {
    return {
      valid: false,
      reason: "Please provide a valid email address like 'john@example.com'"
    };
  }

  return { valid: true };
}

/**
 * Phone Validator
 *
 * Accepts various phone formats:
 * - "555-1234", "(555) 123-4567", "555.123.4567"
 * - "+1 555 123 4567"
 */
export function validatePhone(value: string): ValidationResult {
  if (!value || value.trim().length === 0) {
    return { valid: false, reason: "Phone number cannot be empty" };
  }

  // Remove common formatting characters
  const cleaned = value.replace(/[\s\-\.\(\)]/g, '');

  // Check if it contains enough digits (at least 7 for local, typically 10+ for full)
  const digits = cleaned.match(/\d/g);
  if (!digits || digits.length < 7) {
    return {
      valid: false,
      reason: "Please provide a complete phone number like '555-123-4567'"
    };
  }

  return { valid: true };
}

/**
 * Party Size Validator
 *
 * Accepts:
 * - Numbers 1-100
 * - "2", "2 people", "party of 4"
 *
 * Invalid:
 * - "a few", "some" (not specific)
 * - 0 or negative
 * - > 100 (likely error)
 */
export function validatePartySize(value: string): ValidationResult {
  if (!value || value.trim().length === 0) {
    return { valid: false, reason: "Party size cannot be empty" };
  }

  const normalized = value.toLowerCase().trim();

  // Too vague
  if (/^(few|some|several|many|couple)$/i.test(normalized)) {
    return {
      valid: false,
      reason: "Please provide a specific number like '2', '4 people', or 'party of 6'"
    };
  }

  // Extract number
  const match = value.match(/\d+/);
  if (!match) {
    return {
      valid: false,
      reason: "Please provide a number like '2' or 'party of 4'"
    };
  }

  const size = parseInt(match[0], 10);

  if (size < 1) {
    return {
      valid: false,
      reason: "Party size must be at least 1"
    };
  }

  if (size > 100) {
    return {
      valid: false,
      reason: "Party size seems unusually large. Please confirm the number of people."
    };
  }

  return { valid: true };
}

/**
 * Numeric Validator (generic)
 *
 * Ensures value contains a number
 */
export function validateNumeric(value: string): ValidationResult {
  if (!value || value.trim().length === 0) {
    return { valid: false, reason: "Value cannot be empty" };
  }

  const hasNumber = /\d+(?:\.\d+)?/.test(value);
  if (!hasNumber) {
    return {
      valid: false,
      reason: "Please provide a number"
    };
  }

  return { valid: true };
}

/**
 * Non-Empty Validator (default)
 *
 * Just checks that value is not empty
 */
export function validateNonEmpty(value: string): ValidationResult {
  if (!value || value.trim().length === 0) {
    return { valid: false, reason: "This field is required" };
  }

  return { valid: true };
}

/**
 * Validate a field based on its key and value
 *
 * This function maps field keys to appropriate validators
 */
export function validateRequiredInput(fieldKey: string, value: string): ValidationResult {
  // Address fields
  if (fieldKey.includes('address') && !fieldKey.includes('email')) {
    return validateAddress(value);
  }

  // Date fields
  if (fieldKey.includes('date')) {
    return validateDate(value);
  }

  // Time fields
  if (fieldKey.includes('time') && !fieldKey.includes('estimated')) {
    return validateTime(value);
  }

  // Miles/distance fields
  if (fieldKey.includes('miles') || fieldKey === 'estimated_miles') {
    return validateMiles(value);
  }

  // Email fields
  if (fieldKey.includes('email')) {
    return validateEmail(value);
  }

  // Phone fields
  if (fieldKey.includes('phone')) {
    return validatePhone(value);
  }

  // Party size
  if (fieldKey === 'party_size') {
    return validatePartySize(value);
  }

  // Numeric fields
  if (fieldKey.includes('quantity') || fieldKey.includes('count') || fieldKey.includes('number')) {
    return validateNumeric(value);
  }

  // Default: just check non-empty
  return validateNonEmpty(value);
}

/**
 * Check if all required inputs are valid
 *
 * Returns array of missing/invalid fields with reasons
 */
export interface MissingInput {
  key: string;
  label: string;
  reason: string;
  ask_prompt: string;
}

export function checkRequiredInputs(
  requiredFields: Array<{ key: string; label: string; ask_prompt: string }>,
  extractedData: Record<string, any>
): MissingInput[] {
  const missing: MissingInput[] = [];

  for (const field of requiredFields) {
    const value = extractedData[field.key];

    // Check if field exists and has a value
    if (value === undefined || value === null || value === '') {
      missing.push({
        key: field.key,
        label: field.label,
        reason: "Not provided",
        ask_prompt: field.ask_prompt
      });
      continue;
    }

    // Validate the value
    const validation = validateRequiredInput(field.key, String(value));
    if (!validation.valid) {
      missing.push({
        key: field.key,
        label: field.label,
        reason: validation.reason || "Invalid format",
        ask_prompt: field.ask_prompt
      });
    }
  }

  return missing;
}

