    description: description || null,
    metadata: metadata || {},
  });
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const contentType = req.headers.get("content-type") || "";
    let from: string | null = null;
    let body: string | null = null;
    let channel: "sms" | "email" = "sms";

    // Handle Twilio SMS webhook (form-encoded)
    if (contentType.includes("application/x-www-form-urlencoded")) {
      const formData = await req.formData();
      from = formData.get("From") as string;
      body = formData.get("Body") as string;
      channel = "sms";
    } else {
      // Handle JSON (email webhook from Resend or manual)
      const json = await req.json();
      from = json.from_email || json.from || json.From;
      body = json.body || json.text || json.Body;
      channel = json.channel || "email";
    }

    if (!from || !body) {
      return errorResponse("Missing from or body", 400);
    }

    console.log(`[outreach-response] ${channel} reply from ${from}: ${body.substring(0, 100)}`);

    // Find matching enrollment by phone or email
    const field = channel === "sms" ? "lead_phone" : "lead_email";
    const { data: enrollment } = await supabase
      .from("admin_outreach_enrollments")
      .select("*")
      .eq(field, from)
      .in("status", ["active", "paused"])
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (!enrollment) {
      console.log(`[outreach-response] No active enrollment found for ${from}`);
      return jsonResponse({ success: false, reason: "no_enrollment_found" });
    }

    // Analyze sentiment with AI
    let sentiment = "neutral";
    try {
      sentiment = await analyzeSentiment(body);
    } catch (e) {
      console.error("[outreach-response] Sentiment analysis failed:", e);
    }

    // Update enrollment
    await supabase
      .from("admin_outreach_enrollments")
      .update({
        status: "responded",
        response_text: body,
        response_sentiment: sentiment,
        updated_at: new Date().toISOString(),
      })
      .eq("id", enrollment.id);

    // Atomically increment campaign response count
    await supabase.rpc("admin_increment_campaign_responded", {
      p_campaign_id: enrollment.campaign_id,
    }).catch((err: any) => {
      console.error("[outreach-response] Failed to increment campaign responded:", err);
    });

    // Track sequence-level response rate
    if (enrollment.current_step > 0) {
      const { data: camp } = await supabase
        .from("admin_outreach_campaigns")
        .select("sequence_id")
        .eq("id", enrollment.campaign_id)
        .maybeSingle();

      if (camp?.sequence_id) {
        await supabase.rpc("admin_increment_sequence_responded", {
          p_sequence_id: camp.sequence_id,
        }).catch(() => {});

        // Track which step triggered the response
        await supabase.rpc("admin_increment_step_responded", {
          p_sequence_id: camp.sequence_id,
          p_step_order: enrollment.current_step,
        }).catch(() => {});
      }
    }

    // Log activity
    await supabase.from("admin_growth_activity_log").insert({
      activity_type: "outreach_response",
      title: `${enrollment.lead_name} replied (${sentiment})`,
      description: body.substring(0, 200),
      metadata: {
        enrollment_id: enrollment.id,
        campaign_id: enrollment.campaign_id,
        channel,
        sentiment,
        from,
      },
    });

    // Send notification to admin
    const { data: settings } = await supabase
      .from("admin_growth_settings")
      .select("notification_email, notify_on_response")
      .limit(1)
      .maybeSingle();

    if (settings?.notify_on_response && settings?.notification_email) {
      const { sendEmail } = await import("../_shared/sendEmail.ts");
      await sendEmail({
        to: settings.notification_email,
        subject: `Outreach Response: ${enrollment.lead_name} (${sentiment})`,
        html: `
          <h3>${enrollment.lead_name} replied to outreach</h3>
          <p><strong>Channel:</strong> ${channel}</p>
          <p><strong>Sentiment:</strong> ${sentiment}</p>
          <p><strong>Message:</strong></p>
          <blockquote style="border-left: 3px solid #ccc; padding-left: 12px; color: #555;">${body}</blockquote>
        `,
      });
    }

    console.log(`[outreach-response] Processed ${channel} response from ${enrollment.lead_name} (${sentiment})`);

    return jsonResponse({ success: true, enrollment_id: enrollment.id, sentiment });
  } catch (error) {
    console.error("[outreach-response] Error:", error);
    return errorResponse(String(error), 500);
  }
});

async function analyzeSentiment(text: string): Promise<string> {
  const apiKey = Deno.env.get("AI_GATEWAY_API_KEY");
  if (!apiKey) return "neutral";

  const res = await fetch("https://ai.gateway.lovable.dev/chat/completions", {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: "gpt-4o-mini",
      messages: [
        {
          role: "system",
          content: 'Classify the sentiment of this reply to a business outreach message. Reply with ONLY one word: "positive", "neutral", or "negative".',
        },
        { role: "user", content: text },
      ],
      temperature: 0,
      max_tokens: 10,
    }),
  });

  if (!res.ok) return "neutral";
  const data = await res.json();
  const result = (data.choices?.[0]?.message?.content || "neutral").toLowerCase().trim();
  if (["positive", "neutral", "negative"].includes(result)) return result;
  return "neutral";
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsResponse, jsonResponse } from "../_shared/cors.ts";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const now = new Date();
    console.log(`[outreach-scheduler] Starting run at ${now.toISOString()}`);

    // Load settings
    const { data: settings } = await supabase
      .from("admin_growth_settings")
      .select("*")
      .limit(1)
      .maybeSingle();

    if (!settings?.auto_outreach_enabled) {
      console.log("[outreach-scheduler] Auto outreach disabled");
      return jsonResponse({ success: true, reason: "disabled", processed: 0 });
    }

    // Check quiet hours
    if (isQuietTime(now, settings)) {
      console.log("[outreach-scheduler] Currently in quiet hours");
      return jsonResponse({ success: true, reason: "quiet_hours", processed: 0 });
    }

    // Check daily send limits
    const todayStart = new Date(now);
    todayStart.setHours(0, 0, 0, 0);

    const { count: emailsSentToday } = await supabase
      .from("admin_outreach_actions")
      .select("id", { count: "exact", head: true })
      .eq("action_type", "email")
      .eq("delivery_status", "sent")
      .gte("executed_at", todayStart.toISOString());

    const { count: smsSentToday } = await supabase
      .from("admin_outreach_actions")
      .select("id", { count: "exact", head: true })
      .eq("action_type", "sms")
      .eq("delivery_status", "sent")
      .gte("executed_at", todayStart.toISOString());

    const emailLimit = settings.outreach_daily_email_limit || 50;
    const smsLimit = settings.outreach_daily_sms_limit || 20;
    const emailsRemaining = Math.max(0, emailLimit - (emailsSentToday ?? 0));
    const smsRemaining = Math.max(0, smsLimit - (smsSentToday ?? 0));

    if (emailsRemaining === 0 && smsRemaining === 0) {
      console.log("[outreach-scheduler] Daily limits reached");
      return jsonResponse({ success: true, reason: "daily_limit_reached", processed: 0 });
    }

    // Find due enrollments
    const { data: dueEnrollments, error: queryErr } = await supabase
      .from("admin_outreach_enrollments")
      .select("id")
      .eq("status", "active")
      .not("next_action_at", "is", null)
      .lte("next_action_at", now.toISOString())
      .order("next_action_at", { ascending: true })
      .limit(50);

    if (queryErr) {
      console.error("[outreach-scheduler] Query error:", queryErr);
      return jsonResponse({ success: false, error: queryErr.message }, 500);
    }

    console.log(`[outreach-scheduler] Found ${dueEnrollments?.length ?? 0} due enrollments`);

    let processed = 0;
    let succeeded = 0;
    let failed = 0;
    const errors: string[] = [];

    for (const enrollment of dueEnrollments ?? []) {
      processed++;
      try {
        const { data: result, error: execErr } = await supabase.functions.invoke(
          "admin-outreach-execute",
          { body: { enrollment_id: enrollment.id } }
        );

        if (execErr) {
          console.error(`[outreach-scheduler] Error for ${enrollment.id}:`, execErr);
          failed++;
          errors.push(`${enrollment.id}: ${execErr.message}`);
        } else if (result?.success) {
          succeeded++;
        } else {
          failed++;
          errors.push(`${enrollment.id}: ${result?.reason || "unknown"}`);
        }
      } catch (err) {
        failed++;
        errors.push(`${enrollment.id}: ${String(err)}`);
      }
    }

    console.log(`[outreach-scheduler] Complete: ${processed} processed, ${succeeded} succeeded, ${failed} failed`);

    return jsonResponse({ success: true, processed, succeeded, failed, errors: errors.slice(0, 10) });
  } catch (error) {
    console.error("[outreach-scheduler] Fatal error:", error);
    return jsonResponse({ success: false, error: String(error) }, 500);
  }
});

function isQuietTime(now: Date, settings: any): boolean {
  const dayNames = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
  const dayName = dayNames[now.getDay()];

  if ((settings.outreach_quiet_days || []).includes(dayName)) return true;

  const currentTime = `${now.getHours().toString().padStart(2, "0")}:${now.getMinutes().toString().padStart(2, "0")}`;
  const quietStart = settings.outreach_quiet_hours_start || "21:00";
  const quietEnd = settings.outreach_quiet_hours_end || "08:00";

  if (quietStart > quietEnd) {
    return currentTime >= quietStart || currentTime < quietEnd;
  }
  return currentTime >= quietStart && currentTime < quietEnd;
}

