    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Unknown error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { requireAuthedTenant, serviceClient } from "../_shared/tenant.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

type Intent = 'booking' | 'quote' | 'service_info' | 'pricing' | 'hours' | 'location' | 
              'cancel' | 'reschedule' | 'objection' | 'urgent' | 'greeting' | 'other';

interface ResponsePlan {
  intent: Intent;
  confidence: string;
  required_info_to_collect: string[];
  facts_to_use: Array<{ source: string; content: string }>;
  policy_constraints: string[];
  guardrails_applied: string[];
  next_action: 'offer_slots' | 'provide_info' | 'request_details' | 'escalate' | 'book' | 'callback';
  draft_reply: string;
  sources_used: Array<{ type: string; id: string }>;
  knowledge_gap_detected: boolean;
  gap_description?: string;
}

// Detect intent from message
function detectIntent(message: string): Intent {
  const lower = message.toLowerCase();
  
  if (/\b(book|schedule|appointment|reserve|slot)\b/.test(lower)) return 'booking';
  if (/\b(price|cost|how much|quote|estimate|pricing)\b/.test(lower)) return 'quote';
  if (/\b(cancel|cancellation)\b/.test(lower)) return 'cancel';
  if (/\b(reschedule|change.*time|move.*appointment)\b/.test(lower)) return 'reschedule';
  if (/\b(hours|open|close|when.*open)\b/.test(lower)) return 'hours';
  if (/\b(where|location|address|directions)\b/.test(lower)) return 'location';
  if (/\b(urgent|emergency|asap|right now)\b/.test(lower)) return 'urgent';
  if (/\b(hi|hello|hey|good morning|good afternoon)\b/.test(lower) && lower.length < 30) return 'greeting';
  if (/\b(what.*service|do you|can you|offer)\b/.test(lower)) return 'service_info';
  if (/\b(too expensive|too much|competitor|elsewhere|think about it)\b/.test(lower)) return 'objection';
  
  return 'other';
}

// Generate draft reply using AI
async function generateReply(
  brain: any,
  snippets: any[],
  userMessage: string,
  intent: Intent,
  channel: string,
  lovableApiKey: string
): Promise<{ reply: string; next_action: string }> {
  
  // Build system prompt from brain
  let systemPrompt = `You are an AI assistant for ${brain.business.name}`;
  if (brain.business.tagline) systemPrompt += ` - ${brain.business.tagline}`;
  systemPrompt += `.

COMMUNICATION STYLE: Be ${brain.ai_settings?.tone || 'friendly'} in your responses.
CHANNEL: ${channel === 'sms' ? 'SMS (keep responses under 300 characters)' : 'Phone call (be conversational)'}

BUSINESS INFORMATION:
- Industry: ${brain.business.industry}
- Phone: ${brain.business.phone || 'Not provided'}
- Address: ${brain.business.address || 'Not provided'}

`;

  // Add services summary
  if (brain.services.length > 0) {
    systemPrompt += `SERVICES:\n`;
    for (const s of brain.services.slice(0, 5)) {
      systemPrompt += `- ${s.name}`;
      if (s.price_type === 'fixed' && s.price_amount) systemPrompt += ` - $${s.price_amount}`;
      else if (s.price_type === 'starting_at' && s.price_amount) systemPrompt += ` - starting at $${s.price_amount}`;
      else systemPrompt += ` - quote required`;
      systemPrompt += ` (${s.duration_minutes} min)\n`;
    }
    systemPrompt += '\n';
  }

  // Add relevant knowledge snippets
  if (snippets.length > 0) {
    systemPrompt += `RELEVANT KNOWLEDGE FOR THIS QUERY:\n`;
    for (const s of snippets.slice(0, 5)) {
      systemPrompt += `[${s.source_type.toUpperCase()}] ${s.title}: ${s.content}\n\n`;
    }
  }

  // Add policies
  systemPrompt += `POLICIES:\n`;
  if (brain.policies.cancellation) systemPrompt += `- Cancellation: ${brain.policies.cancellation}\n`;
  if (brain.policies.deposit) systemPrompt += `- Deposit: ${brain.policies.deposit}\n`;
  if (brain.policies.refund) systemPrompt += `- Refund: ${brain.policies.refund}\n`;
  systemPrompt += '\n';

  // Add guardrails
  if (brain.guardrails.never_promise.length > 0) {
    systemPrompt += `NEVER PROMISE OR SAY:\n`;
    for (const np of brain.guardrails.never_promise) {
      systemPrompt += `- ${np}\n`;
    }
    systemPrompt += '\n';
  }

  // Add booking rules
  systemPrompt += `BOOKING RULES:\n`;
  systemPrompt += `- Minimum lead time: ${brain.booking_rules.min_lead_hours || 24} hours\n`;
  systemPrompt += `- Maximum advance booking: ${brain.booking_rules.max_advance_days || 30} days\n`;
  systemPrompt += `- Booking mode: ${brain.booking_rules.booking_mode === 'auto_book' ? 'Can confirm immediately' : 'Pending owner approval'}\n\n`;

  // Greeting and fallback
  if (brain.ai_settings?.greeting) {
    systemPrompt += `GREETING SCRIPT: "${brain.ai_settings.greeting}"\n`;
  }
  if (brain.ai_settings?.fallback) {
    systemPrompt += `FALLBACK (when unsure): "${brain.ai_settings.fallback}"\n`;
  }

  systemPrompt += `
CRITICAL RULES:
1. ONLY use information provided above. NEVER invent prices, services, or policies.
2. If you don't have the answer, say you'll have someone get back to them.
3. Be action-oriented: try to book, collect contact info, or provide clear next steps.
4. Keep responses concise and natural.
5. If the customer seems hesitant, address their concern directly.
`;

  // User prompt based on intent
  const userPrompt = `Customer message: "${userMessage}"
Intent detected: ${intent}

Generate a helpful, accurate response. ${channel === 'sms' ? 'Keep it under 300 characters.' : 'Be conversational.'}`;

  try {
    const aiResponse = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${lovableApiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "google/gemini-3-flash-preview",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: userPrompt },
        ],
        max_tokens: channel === 'sms' ? 150 : 300,
        temperature: 0.7,
      }),
    });

    if (!aiResponse.ok) {
      throw new Error(`AI API error: ${aiResponse.status}`);
    }

    const data = await aiResponse.json();
    const reply = data.choices?.[0]?.message?.content?.trim() || '';

    // Determine next action based on intent and reply
    let next_action = 'provide_info';
    if (intent === 'booking' && reply.toLowerCase().includes('time')) next_action = 'offer_slots';
    else if (intent === 'booking') next_action = 'request_details';
    else if (intent === 'urgent') next_action = 'callback';
    else if (reply.toLowerCase().includes('call you back') || reply.toLowerCase().includes('get back to you')) next_action = 'escalate';

    return { reply, next_action };
  } catch (error) {
    console.error("AI generation error:", error);
    return {
      reply: brain.ai_settings?.fallback || "I'd be happy to help! Let me have someone get back to you shortly.",
      next_action: 'escalate',
    };
  }
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    // Parse body early to extract tenantId for validation
    const body = await req.json().catch(() => ({}));
    const { userMessage, channel = 'call', customerId } = body;
    const requestedTenantId = body.tenant_id ?? body.tenantId ?? null;

    if (!userMessage) {
      return new Response(
        JSON.stringify({ error: "User message is required" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // SECURITY: Validate user has access to the requested tenant
    const { tenantId } = await requireAuthedTenant(req, requestedTenantId);

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const lovableApiKey = Deno.env.get("LOVABLE_API_KEY")!;
    const supabase = serviceClient();

    // Get the authorization header to pass to sub-functions
    const authHeader = req.headers.get("authorization") || "";

    // Detect intent
    const intent = detectIntent(userMessage);

    // Fetch business brain (pass user's auth header for tenant validation)
    const brainResponse = await fetch(`${supabaseUrl}/functions/v1/build-business-brain`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": authHeader,
      },
      body: JSON.stringify({ tenantId }),
    });

    if (!brainResponse.ok) {
      throw new Error("Failed to fetch business brain");
    }

    const { brain } = await brainResponse.json();

    // Retrieve relevant knowledge (pass user's auth header for tenant validation)
    const knowledgeResponse = await fetch(`${supabaseUrl}/functions/v1/retrieve-knowledge`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": authHeader,
      },
      body: JSON.stringify({ tenantId, queryText: userMessage, intent, topK: 8 }),
    });

    if (!knowledgeResponse.ok) {
      throw new Error("Failed to retrieve knowledge");
    }

    const { snippets, confidence } = await knowledgeResponse.json();

    // Build response plan
    const factsToUse = snippets.slice(0, 5).map((s: any) => ({
      source: s.source_type,
      content: s.content,
    }));

    const policyConstraints: string[] = [];
    if (brain.policies.cancellation) policyConstraints.push(`Cancellation: ${brain.policies.cancellation}`);
    if (brain.policies.deposit) policyConstraints.push(`Deposit: ${brain.policies.deposit}`);

    const guardrailsApplied = brain.guardrails.never_promise.slice(0, 3);

    // Determine what info to collect based on intent
    const requiredInfo: string[] = [];
    if (intent === 'booking') {
      requiredInfo.push('Preferred date/time', 'Service needed');
      if (brain.intake_fields.length > 0) {
        const required = brain.intake_fields.filter((f: any) => f.required);
        requiredInfo.push(...required.map((f: any) => f.label));
      }
    } else if (intent === 'quote') {
      requiredInfo.push('Service details', 'Any specific requirements');
    } else if (intent === 'cancel' || intent === 'reschedule') {
      requiredInfo.push('Booking reference or date');
    }

    // Generate the reply
    const { reply, next_action } = await generateReply(
      brain,
      snippets,
      userMessage,
      intent,
      channel,
      lovableApiKey
    );

    // Check for knowledge gap
    const knowledgeGapDetected = confidence === 'low' && intent !== 'greeting';
    let gapDescription: string | undefined;

    if (knowledgeGapDetected) {
      gapDescription = `No confident answer for: "${userMessage}" (intent: ${intent})`;
      
      // Log the knowledge gap
      await supabase.from('knowledge_gaps').upsert({
        tenant_id: tenantId,
        gap_type: intent === 'quote' ? 'missing_pricing' : 
                  intent === 'service_info' ? 'missing_faq' : 'unanswered_question',
        description: gapDescription,
        customer_question: userMessage,
        priority: intent === 'urgent' ? 3 : 2,
      }, {
        onConflict: 'id', // Will create new if no match
      });
    }

    const plan: ResponsePlan = {
      intent,
      confidence,
      required_info_to_collect: requiredInfo,
      facts_to_use: factsToUse,
      policy_constraints: policyConstraints,
      guardrails_applied: guardrailsApplied,
      next_action: next_action as any,
      draft_reply: reply,
      sources_used: snippets.slice(0, 5).map((s: any) => ({ type: s.source_type, id: s.id })),
      knowledge_gap_detected: knowledgeGapDetected,
      gap_description: gapDescription,
    };

    return new Response(
      JSON.stringify({ 
        plan,
        brain_summary: {
          business_name: brain.business.name,
          services_count: brain.services.length,
          faqs_count: brain.faqs.length,
          has_booking_rules: !!brain.booking_rules.min_lead_hours,
        },
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("Error in ai-plan-response:", error);
    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Unknown error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

/**
 * approve-agency-application
 *
 * Approves a pending agency application:
 * 1. Creates an agency_accounts row for the applicant
 * 2. Updates the application status to "approved"
 *
 * Auth: requires super_admin role.
 */

import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { serviceClient } from "../_shared/tenant.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

function slugify(text: string): string {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^\w\s-]/g, "")
    .replace(/[\s_]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();
  if (req.method !== "POST") return errorResponse("Method not allowed", 405);

  try {
    // Auth: verify caller is super_admin
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) return errorResponse("Unauthorized", 401);

    const anonClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } }, auth: { persistSession: false } }
    );
    const { data: userRes, error: userErr } = await anonClient.auth.getUser();
    if (userErr || !userRes?.user?.id) return errorResponse("Unauthorized", 401);

    const adminUserId = userRes.user.id;

    const svc = serviceClient();

    // Check super_admin role
    const { data: roleRow } = await svc
      .from("user_roles")
      .select("role")
      .eq("user_id", adminUserId)
      .eq("role", "super_admin")
      .maybeSingle();

    if (!roleRow) return errorResponse("Forbidden: super_admin required", 403);

    // Parse body
    const body = await req.json();
    const { application_id, admin_notes } = body;

    if (!application_id) return errorResponse("application_id is required", 400);

    // Fetch the application
    const { data: app, error: appErr } = await svc
      .from("agency_applications")
      .select("*")
      .eq("id", application_id)
      .single();

    if (appErr || !app) return errorResponse("Application not found", 404);

    if (app.status !== "new" && app.status !== "reviewing") {
      return errorResponse(`Application is already ${app.status}`, 409);
    }

    if (!app.user_id) {
      return errorResponse("Application has no linked user account. Cannot approve.", 400);
    }

    // Create agency_accounts row
    const agencySlug = slugify(app.company_name) + "-" + Date.now().toString(36).slice(-4);

    const { data: agencyRow, error: agencyErr } = await svc
      .from("agency_accounts")
      .insert({
        user_id: app.user_id,
        agency_name: app.company_name,
        agency_slug: agencySlug,
        billing_config_json: { commission_rate: 0.20 },
      })
      .select("id")
      .single();

    if (agencyErr) {
      console.error("[approve-agency-application] agency insert error:", agencyErr);
      return errorResponse(`Failed to create agency account: ${agencyErr.message}`, 500);
    }

    // Update the application
    const updateFields: Record<string, unknown> = {
      status: "approved",
      approved_agency_id: agencyRow.id,
      reviewed_by: adminUserId,
      reviewed_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    };
    if (admin_notes !== undefined) updateFields.admin_notes = admin_notes;

    const { error: updateErr } = await svc
      .from("agency_applications")
      .update(updateFields)
      .eq("id", application_id);

    if (updateErr) {
      console.error("[approve-agency-application] update error:", updateErr);
      return errorResponse(`Failed to update application: ${updateErr.message}`, 500);
    }

    console.log(`[approve-agency-application] Approved: app=${application_id} agency=${agencyRow.id}`);

    return jsonResponse({ success: true, agency_id: agencyRow.id });
  } catch (err) {
    console.error("[approve-agency-application] Error:", err);
    return errorResponse(err instanceof Error ? err.message : "Internal server error", 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { requireAuthedTenant, serviceClient } from "../_shared/tenant.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

interface SuggestRequest {
  tenant_id?: string;
  tenantId?: string;
  date: string; // YYYY-MM-DD in tenant's local timezone
  duration_minutes?: number;
  service_id?: string;
  preference?: "earliest" | "earlier_than" | "later_than";
  reference_time?: string; // HH:MM in 24h format
  max_results?: number;
}

interface SlotResult {
  start: string; // ISO timestamp
  end: string;
  display: string; // Human-readable like "9:00 AM"
  local_date: string;
}

/**
 * availability-suggest: Returns deterministic slot suggestions for AI agent
 *
 * This is the canonical endpoint the voice agent uses when asking about availability.
 * It enforces timezone-correct, duration-aware slot computation.
 */
serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const startTime = Date.now();

  try {
    const body: SuggestRequest = await req.json();
    const {
      date,
      duration_minutes,
      service_id,
      preference = "earliest",
      reference_time,
      max_results = 5,
    } = body;

    const requestedTenantId = body.tenant_id ?? body.tenantId ?? null;

    if (!date) {
      return new Response(
        JSON.stringify({ error: "date is required" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // SECURITY: Validate user has access to the requested tenant
    const { tenantId } = await requireAuthedTenant(req, requestedTenantId);

    const supabase = serviceClient();

    // Get tenant settings - scoped to validated tenantId
    const { data: tenant, error: tenantError } = await supabase
      .from("tenants")
      .select("timezone, hours_json, appointment_buffer_minutes, min_lead_hours, max_advance_days")
      .eq("id", tenantId)
      .single();

    if (tenantError || !tenant) {
      return new Response(
        JSON.stringify({ error: "Tenant not found" }),
        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const timezone = tenant.timezone || "America/New_York";
    const bufferMinutes = tenant.appointment_buffer_minutes || 15;

    // Determine duration from service if provided
    let finalDuration = duration_minutes || 60;
    let serviceName: string | null = null;

    if (service_id) {
      // SECURITY: Service must belong to the validated tenant
      const { data: service } = await supabase
        .from("services")
        .select("duration_minutes, name")
        .eq("id", service_id)
        .eq("tenant_id", tenantId)
        .single();

      if (service) {
        finalDuration = service.duration_minutes;
        serviceName = service.name;
      }
    }

    console.log(`[availability-suggest] Tenant: ${tenantId}, Date: ${date}, Duration: ${finalDuration}min, Preference: ${preference}`);

    // Get tenant capacity
    const { data: tenantCapData } = await supabase
      .from("tenants")
      .select("default_capacity")
      .eq("id", tenantId)
      .single();
    const capacity = (tenantCapData as any)?.default_capacity || 1;

    // Call the timezone-aware database function
    const { data: slots, error: slotsError } = await supabase.rpc(
      "fn_compute_available_slots",
      {
        _tenant_id: tenantId,
        _start_date: date,
        _end_date: date,
        _duration_minutes: finalDuration,
        _buffer_minutes: bufferMinutes,
        _business_hours: tenant.hours_json,
        _capacity: capacity,
      }
    );

    if (slotsError) {
      console.error("Slots computation error:", slotsError);
      return new Response(
        JSON.stringify({ error: "Failed to compute availability", details: slotsError.message }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Transform and filter slots based on preference
    let filteredSlots = (slots || []) as Array<{
      slot_start: string;
      slot_end: string;
      slot_date: string;
      slot_time_local: string;
    }>;

    // Apply preference filter
    if (preference === "earlier_than" && reference_time) {
      // Filter slots that start before the reference time
      filteredSlots = filteredSlots.filter((slot) => {
        const slotTime = new Date(slot.slot_start);
        const refParts = reference_time.split(":");
        const refHour = parseInt(refParts[0], 10);
        const refMin = parseInt(refParts[1] || "0", 10);

        // Compare in local timezone context
        const slotLocal = new Date(slotTime.toLocaleString("en-US", { timeZone: timezone }));
        const slotHour = slotLocal.getHours();
        const slotMin = slotLocal.getMinutes();

        return (slotHour < refHour) || (slotHour === refHour && slotMin < refMin);
      });
    } else if (preference === "later_than" && reference_time) {
      // Filter slots that start after the reference time
      filteredSlots = filteredSlots.filter((slot) => {
        const slotTime = new Date(slot.slot_start);
        const refParts = reference_time.split(":");
        const refHour = parseInt(refParts[0], 10);
        const refMin = parseInt(refParts[1] || "0", 10);

        const slotLocal = new Date(slotTime.toLocaleString("en-US", { timeZone: timezone }));
        const slotHour = slotLocal.getHours();
        const slotMin = slotLocal.getMinutes();

        return (slotHour > refHour) || (slotHour === refHour && slotMin > refMin);
      });
    }

    // Limit results
    const limitedSlots = filteredSlots.slice(0, max_results);

    // Format slots for response
    const formattedSlots: SlotResult[] = limitedSlots.map((slot) => ({
      start: slot.slot_start,
      end: slot.slot_end,
      display: slot.slot_time_local,
      local_date: slot.slot_date,
    }));

    const elapsedMs = Date.now() - startTime;

    // Build explanation if no slots found
    let explanation: string | null = null;
    if (formattedSlots.length === 0) {
      if (preference === "earlier_than" && reference_time) {
        explanation = `No earlier openings available for a ${finalDuration}-minute ${serviceName || "appointment"} before ${reference_time}. The earliest available time has already been suggested.`;
      } else if (filteredSlots.length === 0 && slots && slots.length === 0) {
        explanation = `No availability on ${date} for a ${finalDuration}-minute ${serviceName || "appointment"}. The day may be fully booked or outside business hours.`;
      } else {
        explanation = `No slots match the requested criteria.`;
      }
    }

    console.log(`[availability-suggest] Found ${formattedSlots.length} slots in ${elapsedMs}ms`);

    return new Response(
      JSON.stringify({
        slots: formattedSlots,
        count: formattedSlots.length,
        total_available: slots?.length || 0,
        date,
        duration_minutes: finalDuration,
        service_name: serviceName,
        timezone,
        preference,
        explanation,
        computed_in_ms: elapsedMs,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    console.error("Error in availability-suggest:", error);
    const message = error instanceof Error ? error.message : "Unknown error";
    return new Response(
      JSON.stringify({ error: message }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { requireAuthedTenant, requireInternalSecret, serviceClient } from "../_shared/tenant.ts";
import { captureException } from "../_shared/sentry.ts";
import { sendEmail } from "../_shared/sendEmail.ts";
import { sendTenantSms } from "../_shared/sms-sender.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-closeloop-secret",
};

interface BookingHandoffRequest {
  booking_id?: string;
  tenant_id?: string;
  tenantId?: string;
  test?: boolean;
  method?: string;
  webhook_url?: string;
  webhook_secret?: string;
  notify_email?: string;
  notify_phone?: string;
}

async function createHmacSignature(payload: string, secret: string): Promise<string> {
  const encoder = new TextEncoder();
  const keyData = encoder.encode(secret);
  const messageData = encoder.encode(payload);

  const cryptoKey = await crypto.subtle.importKey(
    "raw",
    keyData,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );

  const signature = await crypto.subtle.sign("HMAC", cryptoKey, messageData);
  const hashArray = Array.from(new Uint8Array(signature));
  const hashHex = hashArray.map(b => b.toString(16).padStart(2, "0")).join("");
  return `sha256=${hashHex}`;
}

/**
 * Validate access - supports both user JWT and internal secret
 */
async function validateAccess(
  req: Request,
  requestedTenantId: string | null
): Promise<{ tenantId: string; isInternalCall: boolean }> {
  const hasAuthHeader = req.headers.get("authorization")?.startsWith("Bearer ");
  const hasInternalSecret = req.headers.get("x-closeloop-secret");

  // Try user JWT first
  if (hasAuthHeader) {
    const { tenantId } = await requireAuthedTenant(req, requestedTenantId);
    return { tenantId, isInternalCall: false };
  }

  // Fall back to internal secret for system triggers
  if (hasInternalSecret) {
    requireInternalSecret(req);
    if (!requestedTenantId) {
      throw new Error("tenant_id required for internal calls");
    }
    return { tenantId: requestedTenantId, isInternalCall: true };
  }

  throw new Error("Missing Authorization header or x-closeloop-secret");
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const body: BookingHandoffRequest = await req.json();
    const { booking_id, test, method, webhook_url, webhook_secret, notify_email, notify_phone } = body;
    const requestedTenantId = body.tenant_id ?? body.tenantId ?? null;

    // SECURITY: Validate access (user JWT or internal secret)
    const { tenantId, isInternalCall } = await validateAccess(req, requestedTenantId);

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabase = serviceClient();

    // Handle test requests (requires user JWT, not internal)
    if (test) {
      if (isInternalCall) {
        throw new Error("Test mode requires user authentication, not internal secret");
      }

      const testPayload = {
        type: "booking",
        event: "test",
        tenant_id: tenantId,
        booking_id: "test-booking-123",
        customer: {
          name: "Test Customer",
          phone: "+15551234567",
          email: "test@example.com",
        },
        service: {
          name: "Test Service",
          duration_minutes: 60,
        },
        scheduled_start: new Date().toISOString(),
        scheduled_end: new Date(Date.now() + 60 * 60 * 1000).toISOString(),
        notes: "This is a test booking",
        created_at: new Date().toISOString(),
      };

      if (method === "webhook" && webhook_url) {
        const payloadString = JSON.stringify(testPayload);
        const headers: Record<string, string> = {
          "Content-Type": "application/json",
        };

        if (webhook_secret) {
          headers["X-CloseLoop-Signature"] = await createHmacSignature(payloadString, webhook_secret);
        }

        const response = await fetch(webhook_url, {
          method: "POST",
          headers,
          body: payloadString,
        });

        if (!response.ok) {
          throw new Error(`Webhook returned ${response.status}: ${await response.text()}`);
        }

        return new Response(JSON.stringify({ success: true, method: "webhook" }), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      if (method === "email" && notify_email) {
        console.log(`[TEST] Would send email to ${notify_email}:`, testPayload);
        return new Response(JSON.stringify({ success: true, method: "email", message: "Email test logged" }), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      if (method === "sms" && notify_phone) {
        const smsResult = await sendTenantSms({
          tenantId,
          to: notify_phone,
          body: `[TEST] New booking: Test Customer for Test Service. This is a test.`,
        });

        if (!smsResult.success && !smsResult.skipped) {
          throw new Error(`SMS failed: ${smsResult.error}`);
        }

        return new Response(JSON.stringify({ success: true, method: "sms", skipped: smsResult.skipped }), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      return new Response(JSON.stringify({ success: true, message: "Test completed" }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Real booking handoff
    if (!booking_id) {
      throw new Error("booking_id is required for non-test requests");
    }

    // SECURITY: Fetch booking AND verify it belongs to the validated tenant
    const { data: booking, error: bookingError } = await supabase
      .from("bookings")
      .select(`
        *,
        lead:leads(*),
        service:services(*)
      `)
      .eq("id", booking_id)
      .eq("tenant_id", tenantId)
      .single();

    if (bookingError || !booking) {
      throw new Error(`Booking not found or access denied`);
    }

    // SECURITY: Fetch delivery settings scoped to tenant
    const { data: settings } = await supabase
      .from("booking_delivery_settings")
      .select("*")
      .eq("tenant_id", tenantId)
      .single();

    if (!settings?.enabled) {
      return new Response(JSON.stringify({ success: true, message: "Handoff disabled" }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Fetch tenant info
    const { data: tenantData } = await supabase
      .from("tenants")
      .select("name")
      .eq("id", tenantId)
      .single();

    const methods = Array.isArray(settings.handoff_methods) ? settings.handoff_methods : ["internal"];
    const results: Record<string, { success: boolean; error?: string }> = {};

    // Build payload
    const payload = {
      type: "booking",
      event: "booking.created",
      tenant_id: tenantId,
      tenant_name: tenantData?.name,
      booking_id: booking.id,
      customer: {
        name: booking.lead?.full_name || "Unknown",
        phone: booking.lead?.phone || null,
        email: booking.lead?.email || null,
      },
      service: booking.service ? {
        name: booking.service.name,
        duration_minutes: booking.service.duration_minutes,
        price_amount: booking.service.price_amount,
      } : null,
      scheduled_start: booking.start_at,
      scheduled_end: booking.end_at,
      status: booking.status,
      deposit_required: booking.deposit_required,
      deposit_paid: booking.deposit_paid,
      notes: booking.notes,
      created_at: booking.created_at,
    };

    // Record audit event for booking created (internal call, use service key)
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    try {
      await fetch(`${supabaseUrl}/functions/v1/record-audit-event`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-closeloop-secret": Deno.env.get("CLOSELOOP_INTERNAL_SECRET") || supabaseServiceKey,
        },
        body: JSON.stringify({
          tenant_id: tenantId,
          event_type: booking.status === "confirmed" ? "booking.confirmed" : "booking.created",
          entity_type: "booking",
          entity_id: booking_id,
          actor_type: "system",
          payload: {
            service_name: booking.service?.name,
            customer_name: booking.lead?.full_name,
            scheduled_start: booking.start_at,
          },
          confirmation_summary: booking.status === "confirmed"
            ? `Booking confirmed: ${booking.service?.name || "Service"} for ${booking.lead?.full_name || "Customer"} at ${new Date(booking.start_at).toLocaleString()}`
            : undefined,
          confirmed_by: "staff",
        }),
      });
    } catch (e) {
      console.error("Failed to record booking audit event:", e);
    }

    // Record observation for booking pattern
    if (booking.service?.name) {
      try {
        await fetch(`${supabaseUrl}/functions/v1/record-observation`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "x-closeloop-secret": Deno.env.get("CLOSELOOP_INTERNAL_SECRET") || supabaseServiceKey,
          },
          body: JSON.stringify({
            tenantId: tenantId,
            observationType: "service_pattern",
            subjectKey: `service_${booking.service.id}`,
            observation: `${booking.service.name} booked at ${new Date(booking.start_at).toLocaleTimeString()}`,
          }),
        });
      } catch (e) {
        console.error("Failed to record booking observation:", e);
      }
    }

    // Execute each enabled method
    for (const handoffMethod of methods) {
      if (handoffMethod === "internal") continue;

      try {
        if (handoffMethod === "webhook" && settings.webhook_url) {
          const payloadString = JSON.stringify(payload);
          const headers: Record<string, string> = {
            "Content-Type": "application/json",
          };

          if (settings.webhook_secret) {
            headers["X-CloseLoop-Signature"] = await createHmacSignature(payloadString, settings.webhook_secret);
          }

          const response = await fetch(settings.webhook_url, {
            method: "POST",
            headers,
            body: payloadString,
          });

          if (!response.ok) {
            throw new Error(`Webhook returned ${response.status}`);
          }

          results.webhook = { success: true };

          await supabase.from("handoff_attempts").insert({
            tenant_id: tenantId,
            entity_type: "booking",
            entity_id: booking_id,
            method: "webhook",
            status: "success",
          });
        }

        if (handoffMethod === "email" && settings.notify_email) {
          const customerName = payload.customer.name;
          const serviceName = payload.service?.name || "Service";
          const startTime = new Date(payload.scheduled_start).toLocaleString();
          const businessName = payload.tenant_name || "Your Business";

          const emailResult = await sendEmail({
            to: settings.notify_email,
            subject: `New Booking: ${customerName} — ${serviceName}`,
            businessName,
            html: `
              <h2>New Booking Received</h2>
              <p><strong>Customer:</strong> ${customerName}</p>
              ${payload.customer.phone ? `<p><strong>Phone:</strong> ${payload.customer.phone}</p>` : ""}
              <p><strong>Service:</strong> ${serviceName}</p>
              <p><strong>Scheduled:</strong> ${startTime}</p>
              ${payload.notes ? `<p><strong>Notes:</strong> ${payload.notes}</p>` : ""}
              ${payload.deposit_required && !payload.deposit_paid ? `<p><em>Deposit required — not yet paid</em></p>` : ""}
            `.trim(),
          });

          results.email = { success: emailResult.success, error: emailResult.error };

          await supabase.from("handoff_attempts").insert({
            tenant_id: tenantId,
            entity_type: "booking",
            entity_id: booking_id,
            method: "email",
            status: emailResult.success ? "success" : "failed",
            error_message: emailResult.error || null,
          });
        }

        if (handoffMethod === "sms" && settings.notify_phone) {
          const customerName = booking.lead?.full_name || "Customer";
          const serviceName = booking.service?.name || "Service";
          const startTime = new Date(booking.start_at).toLocaleString();
          const smsBody = `New booking: ${customerName} for ${serviceName} at ${startTime}`;

          const smsResult = await sendTenantSms({
            tenantId,
            to: settings.notify_phone,
            body: smsBody,
          });

          if (smsResult.success) {
            results.sms = { success: true };
            await supabase.from("handoff_attempts").insert({
              tenant_id: tenantId,
              entity_type: "booking",
              entity_id: booking_id,
              method: "sms",
              status: "success",
            });
          } else if (!smsResult.skipped) {
            throw new Error(`SMS failed: ${smsResult.error}`);
          }
        }
      } catch (error) {
        const errorMessage = error instanceof Error ? error.message : "Unknown error";
        results[handoffMethod] = { success: false, error: errorMessage };

        await supabase.from("handoff_attempts").insert({
          tenant_id: tenantId,
          entity_type: "booking",
          entity_id: booking_id,
          method: handoffMethod,
          status: "failed",
          error_message: errorMessage,
        });
      }
    }

    // Trigger workflow if any active workflow matches this event
    const eventType = booking.status === "confirmed" ? "booking.confirmed" : "booking.created";
    try {
      await fetch(`${supabaseUrl}/functions/v1/trigger-workflow`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-closeloop-secret": Deno.env.get("CLOSELOOP_INTERNAL_SECRET") || supabaseServiceKey,
        },
        body: JSON.stringify({
          tenant_id: tenantId,
          trigger: eventType,
          entity_type: "booking",
          entity_id: booking_id,
        }),
      });
      console.log(`Triggered workflow for ${eventType}:`, booking_id);
    } catch (e) {
      console.error("Failed to trigger workflow:", e);
    }

    // Push bookings to Google Calendar (confirmed or pending_deposit without deposit required)
    const shouldSyncCalendar = !booking.external_event_id && (
      booking.status === "confirmed" ||
      (booking.status === "pending_deposit" && !booking.deposit_required)
    );
    if (shouldSyncCalendar) {
      try {
        const calendarResponse = await fetch(`${supabaseUrl}/functions/v1/create-calendar-event`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "x-closeloop-secret": Deno.env.get("CLOSELOOP_INTERNAL_SECRET") || supabaseServiceKey,
          },
          body: JSON.stringify({
            booking_id,
            tenant_id: tenantId,
          }),
        });

        const calendarResult = await calendarResponse.json();
        if (calendarResult.success) {
          console.log(`Created Google Calendar event for booking ${booking_id}:`, calendarResult.event_id);
          results.google_calendar = { success: true };
        } else if (calendarResult.skipped) {
          console.log(`Skipped Google Calendar for booking ${booking_id}:`, calendarResult.message);
        } else {
          console.error(`Failed to create calendar event:`, calendarResult.error);
          results.google_calendar = { success: false, error: calendarResult.error };
        }
      } catch (e) {
        console.error("Failed to create Google Calendar event:", e);
        results.google_calendar = { success: false, error: String(e) };
      }
    }

    // ─── CUSTOMER CONFIRMATION SMS ───────────────────────────────────
    // Send confirmation SMS to the CUSTOMER (not the owner) if enabled
    try {
      const customerPhone = booking.lead?.phone;
      if (customerPhone) {
        const { data: assistSettings } = await supabase
          .from("assistant_settings")
          .select("settings_json")
          .eq("tenant_id", tenantId)
          .maybeSingle();

        const smsTemplates = (assistSettings?.settings_json as any)?.sms_templates;
        const confirmationConfig = smsTemplates?.appointment_confirmation;

        if (confirmationConfig?.enabled) {
          const startTime = new Date(booking.start_at).toLocaleTimeString("en-US", {
            hour: "numeric",
            minute: "2-digit",
          });
          const startDate = new Date(booking.start_at).toLocaleDateString("en-US", {
            weekday: "long",
            month: "long",
            day: "numeric",
          });

          const template = confirmationConfig.message ||
            "Hi {{customer_name}}! Your appointment with {{business_name}} is confirmed for {{appointment_date}} at {{appointment_time}}. Reply STOP to opt out.";

          const message = template
            .replace(/\{\{customer_name\}\}/g, booking.lead?.full_name || "there")
            .replace(/\{\{business_name\}\}/g, tenantData?.name || "")
            .replace(/\{\{service_name\}\}/g, booking.service?.name || "your appointment")
            .replace(/\{\{appointment_time\}\}/g, startTime)
            .replace(/\{\{appointment_date\}\}/g, startDate);

          const smsResult = await sendTenantSms({
            tenantId,
            to: customerPhone,
            body: message,
          });

          if (smsResult.success) {
            await supabase
              .from("bookings")
              .update({ confirmation_sent: true })
              .eq("id", booking_id);
            results.customer_confirmation = { success: true };
            console.log(`[booking-handoff] Confirmation SMS sent via ${smsResult.channel} for ${booking_id}`);
          } else if (smsResult.skipped) {
            console.log(`[booking-handoff] Skipping customer SMS: no verified channel for ${tenantId}`);
          } else {
            console.error(`[booking-handoff] Customer confirmation SMS failed:`, smsResult.error);
            results.customer_confirmation = { success: false, error: smsResult.error };
          }
        }
      }
    } catch (e) {
      console.error("[booking-handoff] Customer confirmation SMS error:", e);
      results.customer_confirmation = { success: false, error: String(e) };
    }

    return new Response(JSON.stringify({ success: true, results }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });

  } catch (error) {
    console.error("Booking handoff error:", error);

    // Capture to Sentry for monitoring
    await captureException(error, {
      tags: { function: "booking-handoff" },
    });

    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Unknown error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

