      ...((tenant.business_mode === "service" || tenant.business_mode === "general") && {
        product_knowledge: productKnowledge.map((p: any) => ({
          name: p.product_name,
          brand: p.brand,
          category: p.category,
          benefits: p.benefits || [],
          is_premium: p.is_premium,
