const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

// OAuth configuration
const GOOGLE_CLIENT_ID = Deno.env.get("GOOGLE_CALENDAR_CLIENT_ID");
const GOOGLE_CLIENT_SECRET = Deno.env.get("GOOGLE_CALENDAR_CLIENT_SECRET");
const GOOGLE_REDIRECT_URI = Deno.env.get("GOOGLE_CALENDAR_REDIRECT_URI");

const MS_CLIENT_ID = Deno.env.get("MS_CALENDAR_CLIENT_ID");
const MS_CLIENT_SECRET = Deno.env.get("MS_CALENDAR_CLIENT_SECRET");
const MS_REDIRECT_URI = Deno.env.get("MS_CALENDAR_REDIRECT_URI");

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const JWT_SECRET = Deno.env.get("SUPABASE_JWT_SECRET") || Deno.env.get("CLOSELOOP_OAUTH_STATE_SECRET") || "closeloop-state-secret";

// Verify signed state
async function verifyState(state: string): Promise<Record<string, string> | null> {
  try {
    const [payloadB64, signatureB64] = state.split(".");
    const payload = atob(payloadB64);
    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey(
      "raw",
      encoder.encode(JWT_SECRET),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["verify"]
    );
    const signature = Uint8Array.from(atob(signatureB64), c => c.charCodeAt(0));
    const valid = await crypto.subtle.verify("HMAC", key, signature, encoder.encode(payload));
    if (!valid) return null;
    return JSON.parse(payload);
  } catch {
    return null;
  }
}

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const url = new URL(req.url);
    const code = url.searchParams.get("code");
    const state = url.searchParams.get("state");
    const error = url.searchParams.get("error");

    if (error) {
      return new Response(renderHTML("error", `OAuth error: ${error}`), {
        headers: { "Content-Type": "text/html" },
      });
    }

    if (!code || !state) {
      return new Response(renderHTML("error", "Missing code or state"), {
        headers: { "Content-Type": "text/html" },
      });
    }

    // Verify state
    const stateData = await verifyState(state);
    if (!stateData || !stateData.tenant_id || !stateData.provider) {
      return new Response(renderHTML("error", "Invalid state"), {
        headers: { "Content-Type": "text/html" },
      });
    }

    const { tenant_id, provider } = stateData;

    // Exchange code for tokens
    let tokens: {
      access_token: string;
      refresh_token?: string;
      expires_in?: number;
      token_type?: string;
      scope?: string;
    };
    let calendars: { id: string; name: string; primary?: boolean }[] = [];

    if (provider === "google") {
      if (!GOOGLE_CLIENT_ID || !GOOGLE_CLIENT_SECRET || !GOOGLE_REDIRECT_URI) {
        return new Response(renderHTML("error", "Google not configured"), {
          headers: { "Content-Type": "text/html" },
        });
      }

      // Exchange code for tokens
      const tokenResponse = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          code,
          client_id: GOOGLE_CLIENT_ID,
          client_secret: GOOGLE_CLIENT_SECRET,
          redirect_uri: GOOGLE_REDIRECT_URI,
          grant_type: "authorization_code",
        }),
      });

      if (!tokenResponse.ok) {
        const errorText = await tokenResponse.text();
        console.error("Google token error:", errorText);
        return new Response(renderHTML("error", "Failed to exchange code for tokens"), {
          headers: { "Content-Type": "text/html" },
        });
      }

      tokens = await tokenResponse.json();

      // Fetch calendar list
      const calendarResponse = await fetch(
        "https://www.googleapis.com/calendar/v3/users/me/calendarList",
        {
          headers: { Authorization: `Bearer ${tokens.access_token}` },
        }
      );

      if (calendarResponse.ok) {
        const calendarData = await calendarResponse.json();
        calendars = (calendarData.items || []).map((cal: any) => ({
          id: cal.id,
          name: cal.summary || cal.id,
          primary: cal.primary || false,
        }));
      }
    } else if (provider === "microsoft") {
      if (!MS_CLIENT_ID || !MS_CLIENT_SECRET || !MS_REDIRECT_URI) {
        return new Response(renderHTML("error", "Microsoft not configured"), {
          headers: { "Content-Type": "text/html" },
        });
      }

      // Exchange code for tokens
      const tokenResponse = await fetch(
        "https://login.microsoftonline.com/common/oauth2/v2.0/token",
        {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: new URLSearchParams({
            code,
            client_id: MS_CLIENT_ID,
            client_secret: MS_CLIENT_SECRET,
            redirect_uri: MS_REDIRECT_URI,
            grant_type: "authorization_code",
          }),
        }
      );

      if (!tokenResponse.ok) {
        const errorText = await tokenResponse.text();
        console.error("Microsoft token error:", errorText);
        return new Response(renderHTML("error", "Failed to exchange code for tokens"), {
          headers: { "Content-Type": "text/html" },
        });
      }

      tokens = await tokenResponse.json();

      // Fetch calendar list
      const calendarResponse = await fetch(
        "https://graph.microsoft.com/v1.0/me/calendars",
        {
          headers: { Authorization: `Bearer ${tokens.access_token}` },
        }
      );

      if (calendarResponse.ok) {
        const calendarData = await calendarResponse.json();
        calendars = (calendarData.value || []).map((cal: any) => ({
          id: cal.id,
          name: cal.name || cal.id,
          primary: cal.isDefaultCalendar || false,
        }));
      }
    } else {
      return new Response(renderHTML("error", "Unknown provider"), {
        headers: { "Content-Type": "text/html" },
      });
    }

    // Store tokens securely using service role
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    const expiresAt = tokens.expires_in
      ? new Date(Date.now() + tokens.expires_in * 1000).toISOString()
      : null;

    // Upsert token
    const { error: tokenError } = await supabase
      .from("calendar_tokens")
      .upsert({
        tenant_id,
        provider,
        access_token: tokens.access_token,
        refresh_token: tokens.refresh_token || null,
        token_type: tokens.token_type || "Bearer",
        scope: tokens.scope || null,
        expires_at: expiresAt,
      }, {
        onConflict: "tenant_id,provider",
      });

    if (tokenError) {
      console.error("Token storage error:", tokenError);
      return new Response(renderHTML("error", "Failed to store tokens"), {
        headers: { "Content-Type": "text/html" },
      });
    }

    // Create or update calendar connection
    const { data: existingConn } = await supabase
      .from("calendar_connections")
      .select("id")
      .eq("tenant_id", tenant_id)
      .eq("provider", provider)
      .single();

    if (existingConn) {
      await supabase
        .from("calendar_connections")
        .update({
          status: "connected",
          config_json: {
            available_calendars: calendars,
            selected_calendar_ids: calendars.filter(c => c.primary).map(c => c.id),
          },
          scopes_json: tokens.scope ? tokens.scope.split(" ") : [],
        })
        .eq("id", existingConn.id);
    } else {
      await supabase.from("calendar_connections").insert({
        tenant_id,
        provider,
        status: "connected",
        auth_type: "oauth",
        display_name: provider === "google" ? "Google Calendar" : "Microsoft Outlook",
        config_json: {
          available_calendars: calendars,
          selected_calendar_ids: calendars.filter(c => c.primary).map(c => c.id),
        },
        scopes_json: tokens.scope ? tokens.scope.split(" ") : [],
      });
    }

    // Return success page that closes popup
    return new Response(renderHTML("success", null, calendars), {
      headers: { "Content-Type": "text/html" },
    });
  } catch (error: unknown) {
    console.error("Error in calendar-oauth-callback:", error);
    const message = error instanceof Error ? error.message : "Unknown error";
    return new Response(renderHTML("error", message), {
      headers: { "Content-Type": "text/html" },
    });
  }
});

function renderHTML(
  status: "success" | "error",
  errorMessage?: string | null,
  calendars?: { id: string; name: string; primary?: boolean }[]
): string {
  if (status === "error") {
    return `<!DOCTYPE html>
<html>
<head>
  <title>Calendar Connection Failed</title>
  <style>
    body { font-family: system-ui, sans-serif; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; background: #fef2f2; }
    .card { background: white; padding: 2rem; border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); text-align: center; max-width: 400px; }
    .icon { font-size: 48px; margin-bottom: 1rem; }
    h1 { color: #dc2626; margin: 0 0 0.5rem; font-size: 1.25rem; }
    p { color: #6b7280; margin: 0; }
  </style>
</head>
<body>
  <div class="card">
    <div class="icon">❌</div>
    <h1>Connection Failed</h1>
    <p>${errorMessage || "Something went wrong"}</p>
    <p style="margin-top: 1rem;"><a href="#" onclick="window.close()">Close this window</a></p>
  </div>
  <script>
    setTimeout(() => { window.opener?.postMessage({ type: 'calendar-oauth-error', error: '${errorMessage}' }, '*'); }, 500);
  </script>
</body>
</html>`;
  }

  return `<!DOCTYPE html>
<html>
<head>
  <title>Calendar Connected!</title>
  <style>
    body { font-family: system-ui, sans-serif; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; background: #f0fdf4; }
    .card { background: white; padding: 2rem; border-radius: 12px; box-shadow: 0 4px 6px rgba(0,0,0,0.1); text-align: center; max-width: 400px; }
    .icon { font-size: 48px; margin-bottom: 1rem; }
    h1 { color: #16a34a; margin: 0 0 0.5rem; font-size: 1.25rem; }
    p { color: #6b7280; margin: 0; }
  </style>
</head>
<body>
  <div class="card">
    <div class="icon">✅</div>
    <h1>Connected successfully!</h1>
    <p>This window will close automatically.</p>
  </div>
  <script>
    (function() {
      var cals = ${JSON.stringify(calendars || [])};
      try {
        if (window.opener) {
          window.opener.postMessage({ type: 'calendar-oauth-success', calendars: cals }, '*');
        }
      } catch (e) {
        console.error('postMessage failed:', e);
      }
      setTimeout(function() { window.close(); }, 1500);
    })();
  </script>
</body>
</html>`;
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { requireAuthedTenant, requireInternalSecret, serviceClient } from "../_shared/tenant.ts";
import { computeDistanceEta, DistanceEtaResult } from "../_shared/distance_eta.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-closeloop-secret",
};

// Timezone offset map for common US timezones (simplified)
const TIMEZONE_OFFSETS: Record<string, string> = {
  "America/New_York": "-05:00",
  "America/Chicago": "-06:00",
  "America/Denver": "-07:00",
  "America/Los_Angeles": "-08:00",
  "America/Phoenix": "-07:00",
  "America/Anchorage": "-09:00",
  "America/Honolulu": "-10:00",
  "UTC": "+00:00",
};

function getTimezoneOffset(tz: string): string {
  return TIMEZONE_OFFSETS[tz] || "-05:00"; // Default to EST
}

/**
 * Normalize hours_json day config to { open, close } format.
 * Handles both legacy flat format and windows array format.
 */
function normalizeHours(dayConfig: any): { open: string; close: string } | null {
  if (!dayConfig || dayConfig.closed === true) return null;
  // Windows array format: { closed: false, windows: [{ open, close }] }
  if (dayConfig.windows?.length) {
    return { open: dayConfig.windows[0].open, close: dayConfig.windows[0].close };
  }
  // Legacy flat format: { open, close }
  if (dayConfig.open && dayConfig.close) {
    return { open: dayConfig.open, close: dayConfig.close };
  }
  return null;
}

/**
 * Validate access - supports both user JWT and internal secret (for AI agent)
 */
async function validateAccess(
  req: Request,
  requestedTenantId: string | null
): Promise<{ tenantId: string; isInternalCall: boolean }> {
  const hasAuthHeader = req.headers.get("authorization")?.startsWith("Bearer ");
  const hasInternalSecret = req.headers.get("x-closeloop-secret");

  // Try user JWT first
  if (hasAuthHeader) {
    const { tenantId } = await requireAuthedTenant(req, requestedTenantId);
    return { tenantId, isInternalCall: false };
  }

  // Fall back to internal secret for AI agent/system triggers
  if (hasInternalSecret) {
    requireInternalSecret(req);
    if (!requestedTenantId) {
      throw new Error("tenant_id required for internal calls");
    }
    return { tenantId: requestedTenantId, isInternalCall: true };
  }

  throw new Error("Missing Authorization header or x-closeloop-secret");
}

/**
 * check-availability: Real-time slot availability check for AI voice agent
 *
 * Called during conversations when the AI needs to verify if a specific time is available
 * before confirming a booking.
 *
 * Request body:
 * - tenant_id: UUID of the tenant
 * - requested_date: Date in YYYY-MM-DD format
 * - requested_time: Time in HH:MM format (24h)
 * - duration_minutes: How long the appointment needs (default: 60)
 * - destination_address: (optional) Customer address for distance-based ETA
 *
 * Returns:
 * - available: boolean - whether the slot is free
 * - conflict_reason: string | null - why it's not available
 * - alternative_slots: array of available times nearby
 * - travel_eta: (if destination_address provided) distance/time info
 * - not_serviceable: boolean - true if destination exceeds max service distance
 */
serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const body = await req.json();
    const {
      requested_date,
      requested_time,
      duration_minutes = 60,
      destination_address,
    } = body;
    const requestedTenantId = body.tenant_id ?? body.tenantId ?? null;

    if (!requested_date || !requested_time) {
      return new Response(
        JSON.stringify({
          error: "Missing required fields: requested_date, requested_time"
        }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // SECURITY: Validate access (user JWT or internal secret)
    const { tenantId } = await validateAccess(req, requestedTenantId);

    const supabase = serviceClient();

    // SECURITY: Get tenant settings scoped to validated tenantId
    const { data: tenant, error: tenantError } = await supabase
      .from("tenants")
      .select("timezone, hours_json, min_lead_hours, max_advance_days, appointment_buffer_minutes")
      .eq("id", tenantId)
      .single();

    if (tenantError || !tenant) {
      return new Response(
        JSON.stringify({ error: "Tenant not found" }),
        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const timezone = tenant.timezone || "America/New_York";
    const bufferMinutes = tenant.appointment_buffer_minutes || 15;
    const minLeadHours = tenant.min_lead_hours ?? 2;

    // Parse the requested date/time in the tenant's timezone
    // The requested_time is in tenant local time, so we build an ISO string with offset
    const tzOffset = getTimezoneOffset(timezone);
    const localDateTimeStr = `${requested_date}T${requested_time}:00${tzOffset}`;
    
    const requestedStart = new Date(localDateTimeStr);
    // Total blocked time includes duration + buffer for following appointments
    const requestedEnd = new Date(requestedStart.getTime() + (duration_minutes + bufferMinutes) * 60 * 1000);

    console.log("=== CHECK AVAILABILITY ===");
    console.log("Tenant:", tenantId, "Timezone:", timezone);
    console.log("Requested:", requestedStart.toISOString(), "to", requestedEnd.toISOString());

    // Check minimum lead time
    const now = new Date();
    const minBookingTime = new Date(now.getTime() + minLeadHours * 60 * 60 * 1000);
    if (requestedStart < minBookingTime) {
      return new Response(
        JSON.stringify({
          available: false,
          conflict_reason: `Appointments require at least ${minLeadHours} hours notice`,
          alternative_slots: await getAlternativeSlots(supabase, tenantId, requested_date, duration_minutes, bufferMinutes, tenant.hours_json),
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Check business hours for the day
    const dayNames = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
    const dayOfWeek = dayNames[requestedStart.getDay()];
    const rawDayHours = tenant.hours_json?.[dayOfWeek];
    const normalizedDay = normalizeHours(rawDayHours);

    if (!normalizedDay) {
      return new Response(
        JSON.stringify({
          available: false,
          conflict_reason: `We are closed on ${dayOfWeek.charAt(0).toUpperCase() + dayOfWeek.slice(1)}`,
          alternative_slots: await getAlternativeSlots(supabase, tenantId, requested_date, duration_minutes, bufferMinutes, tenant.hours_json),
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Check if requested time is within business hours
    const openTime = normalizedDay.open;
    const closeTime = normalizedDay.close;
    const requestedTimeStr = requested_time;
    const requestedEndTimeStr = `${String(requestedEnd.getHours()).padStart(2, "0")}:${String(requestedEnd.getMinutes()).padStart(2, "0")}`;

    if (requestedTimeStr < openTime || requestedEndTimeStr > closeTime) {
      return new Response(
        JSON.stringify({
          available: false,
          conflict_reason: `That time is outside our business hours (${openTime} - ${closeTime})`,
          alternative_slots: await getAlternativeSlots(supabase, tenantId, requested_date, duration_minutes, bufferMinutes, tenant.hours_json),
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // SECURITY: Check for conflicts scoped to validated tenantId
    const { data: conflicts, error: conflictsError } = await supabase
      .from("busy_blocks")
      .select("id, block_type, start_at, end_at, metadata_json")
      .eq("tenant_id", tenantId)
      .eq("is_active", true)
      .lt("start_at", requestedEnd.toISOString())
      .gt("end_at", requestedStart.toISOString());

    if (conflictsError) {
      console.error("Error checking conflicts:", conflictsError);
      return new Response(
        JSON.stringify({ error: "Failed to check availability" }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    console.log("Conflicts found:", conflicts?.length || 0);

    if (conflicts && conflicts.length > 0) {
      const conflict = conflicts[0];
      const conflictStart = new Date(conflict.start_at);
      const conflictEnd = new Date(conflict.end_at);
      
      let reason = "That time is already booked";
      if (conflict.block_type === "external_busy") {
        reason = "We already have an appointment at that time";
      } else if (conflict.block_type === "hold") {
        reason = "That slot is currently on hold";
      }

      console.log("Conflict:", reason, "from", conflictStart.toISOString(), "to", conflictEnd.toISOString());

      return new Response(
        JSON.stringify({
          available: false,
          conflict_reason: reason,
          alternative_slots: await getAlternativeSlots(supabase, tenantId, requested_date, duration_minutes, bufferMinutes, tenant.hours_json),
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // No conflicts - slot is available!
    console.log("Slot is AVAILABLE");

    // ===== Distance-aware ETA (if destination provided) =====
    let travelEta: DistanceEtaResult | null = null;
    let notServiceable = false;

    if (destination_address && typeof destination_address === "string" && destination_address.trim()) {
      travelEta = await computeDistanceEta({
        supabase,
        tenantId,
        destinationAddress: destination_address.trim(),
      });

      // If max distance exceeded, mark as not serviceable
      if (travelEta.max_distance_exceeded) {
        notServiceable = true;
        console.log(`[check-availability] Destination exceeds max service distance`);
      }
    }

    // Build response
    const response: Record<string, unknown> = {
      available: !notServiceable, // Not available if not serviceable
      conflict_reason: notServiceable
        ? "That location is outside our service area"
        : null,
      slot: {
        start: requestedStart.toISOString(),
        end: requestedEnd.toISOString(),
      },
      not_serviceable: notServiceable,
    };

    // Include travel ETA if computed
    if (travelEta && travelEta.ok) {
      response.travel_eta = {
        distance_miles: travelEta.distance_miles,
        drive_minutes: travelEta.drive_minutes,
        rounded_travel_minutes: travelEta.rounded_travel_minutes,
        provider_used: travelEta.provider_used,
      };

      // Add total ETA including travel (arrival time estimate)
      if (travelEta.rounded_travel_minutes !== null) {
        const arrivalTime = new Date(requestedStart.getTime() - travelEta.rounded_travel_minutes * 60 * 1000);
        response.suggested_departure_time = arrivalTime.toISOString();
        response.total_eta_minutes = travelEta.rounded_travel_minutes;
      }
    } else if (travelEta && !travelEta.ok) {
      // Include error info (but don't fail the whole request)
      response.travel_eta = {
        error: travelEta.error,
        provider_used: travelEta.provider_used,
      };
    }

    return new Response(
      JSON.stringify(response),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error: unknown) {
    console.error("Error in check-availability:", error);
    const message = error instanceof Error ? error.message : "Unknown error";
    return new Response(
      JSON.stringify({ error: message }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

// Helper to get alternative available slots for the same day
// deno-lint-ignore no-explicit-any
async function getAlternativeSlots(
  supabase: any,
  tenantId: string,
  dateStr: string,
  durationMinutes: number,
  bufferMinutes: number,
  hoursJson: Record<string, unknown> | null
): Promise<Array<{ start: string; end: string; display: string }>> {
  try {
    const { data: slots, error } = await supabase.rpc("fn_compute_available_slots", {
      _tenant_id: tenantId,
      _start_date: dateStr,
      _end_date: dateStr,
      _duration_minutes: durationMinutes,
      _buffer_minutes: bufferMinutes,
      _business_hours: hoursJson,
    });

    if (error || !slots) {
      console.error("Error fetching alternatives:", error);
      return [];
    }

    // Return up to 3 alternatives with formatted display times
    return (slots as Array<{ slot_start: string; slot_end: string }>).slice(0, 3).map((slot) => {
      const start = new Date(slot.slot_start);
      const hours = start.getHours();
      const minutes = start.getMinutes();
      const ampm = hours >= 12 ? "PM" : "AM";
      const displayHours = hours % 12 || 12;
      const displayMinutes = minutes === 0 ? "" : `:${String(minutes).padStart(2, "0")}`;
      
      return {
        start: slot.slot_start,
        end: slot.slot_end,
        display: `${displayHours}${displayMinutes} ${ampm}`,
      };
    });
  } catch (error) {
    console.error("Error in getAlternativeSlots:", error);
    return [];
  }
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { captureException, captureMessage } from "../_shared/sentry.ts";

/**
 * Check Handoff Failures
 *
 * This function should be run on a schedule (e.g., every 15 minutes) to:
 * 1. Check for failed handoff deliveries
 * 2. Send alerts to tenant owners via email/SMS
 * 3. Send alerts to the CloseLoop ops team for critical failures
 *
 * Alert thresholds:
 * - Single failure: Log only (will be retried)
 * - 2+ failures for same tenant in 1 hour: Notify tenant owner
 * - 5+ failures globally in 1 hour: Notify ops team (Slack/email)
 */

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

// Thresholds
const TENANT_ALERT_THRESHOLD = 2; // Failures per tenant before alerting
const GLOBAL_ALERT_THRESHOLD = 5; // Global failures before ops alert
const LOOKBACK_MINUTES = 60; // Check failures in the last hour

interface FailureSummary {
  tenant_id: string;
  tenant_name: string;
  owner_email: string | null;
  failure_count: number;
  entity_types: string[];
  latest_error: string | null;
  first_failure_at: string;
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  const OPS_ALERT_EMAIL = Deno.env.get("OPS_ALERT_EMAIL") || "ops@closeloop.ai";
  const SLACK_WEBHOOK_URL = Deno.env.get("SLACK_OPS_WEBHOOK_URL");

  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    console.error("Missing Supabase configuration");
    return new Response(
      JSON.stringify({ error: "Server configuration error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }

  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  try {
    console.log("Starting handoff failure check...");

    const lookbackTime = new Date();
    lookbackTime.setMinutes(lookbackTime.getMinutes() - LOOKBACK_MINUTES);
    const lookbackIso = lookbackTime.toISOString();

    // Count failures by tenant in the lookback window — check BOTH tables
    const [deliveryResult, handoffResult] = await Promise.all([
      supabase
        .from("delivery_attempts")
        .select(`
          tenant_id,
          entity_type,
          error_message,
          created_at,
          tenants!inner(business_name, owner_email)
        `)
        .eq("status", "failed")
        .gte("created_at", lookbackIso)
        .order("created_at", { ascending: false }),
      supabase
        .from("handoff_attempts")
        .select(`
          tenant_id,
          entity_type,
          error_message,
          created_at,
          tenants!inner(business_name, owner_email)
        `)
        .eq("status", "failed")
        .gte("created_at", lookbackIso)
        .order("created_at", { ascending: false }),
    ]);

    if (deliveryResult.error) {
      console.error("Failed to fetch delivery_attempts failures:", deliveryResult.error);
    }
    if (handoffResult.error) {
      console.error("Failed to fetch handoff_attempts failures:", handoffResult.error);
    }

    // Merge results from both tables, tagging the source
    const deliveryFailures = (deliveryResult.data || []).map((f: Record<string, unknown>) => ({ ...f, _source: "delivery_attempts" }));
    const handoffFailures = (handoffResult.data || []).map((f: Record<string, unknown>) => ({ ...f, _source: "handoff_attempts" }));
    const failureData = [...deliveryFailures, ...handoffFailures];

    if (failureData.length === 0) {
      console.log("No failures found in lookback window");
      return new Response(
        JSON.stringify({
          status: "success",
          message: "No failures to report",
          lookback_minutes: LOOKBACK_MINUTES,
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Aggregate failures by tenant
    const failuresByTenant: Map<string, FailureSummary> = new Map();

    for (const failure of failureData) {
      const tenantId = failure.tenant_id;
      const existing = failuresByTenant.get(tenantId);

      if (existing) {
        existing.failure_count++;
        if (!existing.entity_types.includes(failure.entity_type)) {
          existing.entity_types.push(failure.entity_type);
        }
        // Keep the most recent error
        if (!existing.latest_error && failure.error_message) {
          existing.latest_error = failure.error_message;
        }
       } else {
         const tenantData = failure.tenants as unknown as { business_name: string; owner_email: string | null };
         failuresByTenant.set(tenantId, {
           tenant_id: tenantId,
           tenant_name: tenantData?.business_name || "Unknown",
           owner_email: tenantData?.owner_email || null,
          failure_count: 1,
          entity_types: [failure.entity_type],
          latest_error: failure.error_message || null,
          first_failure_at: failure.created_at,
        });
      }
    }

    const totalFailures = failureData.length;
    const alertResults: { tenant_id: string; alerted: boolean; method?: string }[] = [];

    console.log(`Found ${totalFailures} failures across ${failuresByTenant.size} tenants`);

    // Check if we need global ops alert
    if (totalFailures >= GLOBAL_ALERT_THRESHOLD) {
      console.log(`Global alert threshold reached: ${totalFailures} failures`);
      await sendOpsAlert(
        supabase,
        SUPABASE_URL,
        SUPABASE_SERVICE_ROLE_KEY,
        SLACK_WEBHOOK_URL,
        OPS_ALERT_EMAIL,
        totalFailures,
        failuresByTenant
      );
    }

    // Check per-tenant thresholds and send alerts
    for (const [tenantId, summary] of failuresByTenant) {
      if (summary.failure_count >= TENANT_ALERT_THRESHOLD) {
        console.log(
          `Tenant ${tenantId} (${summary.tenant_name}) has ${summary.failure_count} failures - alerting`
        );

        // Check if we've already alerted this tenant recently
        const { data: recentAlert } = await supabase
          .from("audit_events")
          .select("id")
          .eq("tenant_id", tenantId)
          .eq("event_type", "handoff.alert_sent")
          .gte("occurred_at", lookbackIso)
          .limit(1)
          .single();

        if (recentAlert) {
          console.log(`Already alerted tenant ${tenantId} recently, skipping`);
          alertResults.push({ tenant_id: tenantId, alerted: false, method: "already_alerted" });
          continue;
        }

        // Send alert to tenant owner
        const alertSent = await sendTenantAlert(
          supabase,
          SUPABASE_URL,
          SUPABASE_SERVICE_ROLE_KEY,
          summary
        );

        alertResults.push({
          tenant_id: tenantId,
          alerted: alertSent,
          method: summary.owner_email ? "email" : "dashboard_only",
        });
      }
    }

    // Log summary to Sentry
    if (totalFailures > 0) {
      await captureMessage(
        `Handoff failures detected: ${totalFailures} in last ${LOOKBACK_MINUTES} minutes`,
        totalFailures >= GLOBAL_ALERT_THRESHOLD ? "error" : "warning",
        {
          tags: { function: "check-handoff-failures" },
          extra: {
            total_failures: totalFailures,
            affected_tenants: failuresByTenant.size,
            alerts_sent: alertResults.filter((r) => r.alerted).length,
          },
        }
      );
    }

    return new Response(
      JSON.stringify({
        status: "success",
        total_failures: totalFailures,
        affected_tenants: failuresByTenant.size,
        alerts: alertResults,
        lookback_minutes: LOOKBACK_MINUTES,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("Failure check error:", error);

    await captureException(error, {
      tags: { function: "check-handoff-failures" },
    });

    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Unknown error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

// Send alert to ops team
 async function sendOpsAlert(
   supabase: any,
  supabaseUrl: string,
  supabaseKey: string,
  slackWebhookUrl: string | undefined,
  opsEmail: string,
  totalFailures: number,
  failuresByTenant: Map<string, FailureSummary>
): Promise<void> {
  const tenantSummaries = Array.from(failuresByTenant.values())
    .sort((a, b) => b.failure_count - a.failure_count)
    .slice(0, 5)
    .map((s) => `${s.tenant_name}: ${s.failure_count} failures (${s.entity_types.join(", ")})`)
    .join("\n");

  const message = `
CloseLoop Handoff Alert

${totalFailures} handoff failures detected in the last hour.

Top affected tenants:
${tenantSummaries}

Please check the dashboard for details.
  `.trim();

  // Send to Slack if configured
  if (slackWebhookUrl) {
    try {
      await fetch(slackWebhookUrl, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          text: message,
          attachments: [
            {
              color: "danger",
              title: "Handoff Failure Alert",
              fields: [
                { title: "Total Failures", value: String(totalFailures), short: true },
                { title: "Affected Tenants", value: String(failuresByTenant.size), short: true },
              ],
            },
          ],
        }),
      });
      console.log("Sent Slack alert to ops channel");
    } catch (e) {
      console.error("Failed to send Slack alert:", e);
    }
  }

   // Log the ops alert
   try {
     await supabase.from("audit_events").insert({
       tenant_id: null,
       event_type: "system.ops_alert_sent",
       actor_type: "system",
       payload: {
         alert_type: "handoff_failures",
         total_failures: totalFailures,
         affected_tenants: failuresByTenant.size,
         message,
       },
     });
   } catch (e) {
     console.error("Failed to log ops alert:", e);
   }
 }

 // Send alert to tenant owner
 async function sendTenantAlert(
   supabase: any,
  supabaseUrl: string,
  supabaseKey: string,
  summary: FailureSummary
): Promise<boolean> {
  const { tenant_id, tenant_name, owner_email, failure_count, entity_types, latest_error } = summary;

   // Log the alert to audit_events
   try {
     await supabase.from("audit_events").insert({
       tenant_id,
       event_type: "handoff.alert_sent",
       actor_type: "system",
       payload: {
         failure_count,
         entity_types,
         latest_error,
         owner_email,
       },
     });
   } catch (e) {
     console.error("Failed to log tenant alert:", e);
   }
 
   // Create a dashboard notification
   try {
     await supabase.from("notifications").insert({
       tenant_id,
       type: "handoff_failure",
       title: "Handoff Delivery Issues",
       message: `${failure_count} handoff deliveries have failed in the last hour. Please check your integration settings.`,
       severity: "warning",
       read: false,
     });
   } catch {
     // notifications table might not exist, ignore
   }

  // Trigger notification workflow if email is available
  if (owner_email) {
    try {
      await fetch(`${supabaseUrl}/functions/v1/trigger-workflow`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${supabaseKey}`,
        },
        body: JSON.stringify({
          tenant_id,
          trigger: "handoff.failure_alert",
          is_critical: failure_count >= 5,
          details: {
            failure_count,
            entity_types,
            latest_error,
            owner_email,
            business_name: tenant_name,
          },
        }),
      });
      return true;
    } catch (e) {
      console.error(`Failed to trigger alert workflow for tenant ${tenant_id}:`, e);
      return false;
    }
  }

  return false;
}

// v2.0.0 - Lightweight fetch-based implementation to avoid cold-start timeouts

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

interface CheckImpoundRequest {
  tenant_id: string;
  license_plate?: string;
  license_plate_state?: string;
  vin?: string;
  vehicle_description?: string;
  towed_date?: string;
}

interface VehicleResult {
  id: string;
  license_plate: string | null;
  license_plate_state: string | null;
  vehicle_year: string | null;
  vehicle_make: string | null;
  vehicle_model: string | null;
  vehicle_color: string | null;
  towed_from: string | null;
  towed_at: string;
  days_in_lot: number;
  status: string;
}

interface LotResult {
  name: string;
  address: string;
  phone: string | null;
}

// Inline Supabase query helper (avoids esm.sh cold-start)
async function querySupabase(
  url: string,
  key: string,
  table: string,
  query: Record<string, string>,
  extraParams?: string
): Promise<any[]> {
  const params = new URLSearchParams();
  for (const [k, v] of Object.entries(query)) {
    params.append(k, `eq.${v}`);
  }
  if (extraParams) {
    params.append("select", extraParams);
  }

  const response = await fetch(`${url}/rest/v1/${table}?${params.toString()}`, {
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
    },
  });

  if (!response.ok) {
    console.error(`[querySupabase] ${table} query failed:`, response.status);
    return [];
  }

  return await response.json();
}

// Lookup tenant by name using ilike
async function resolveTenantByName(url: string, key: string, name: string): Promise<string | null> {
  const response = await fetch(
    `${url}/rest/v1/tenants?name=ilike.*${encodeURIComponent(name)}*&select=id&limit=1`,
    {
      headers: {
        apikey: key,
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
    }
  );

  if (!response.ok) return null;
  const data = await response.json();
  return data?.[0]?.id || null;
}

// Fetch impound vehicles with embedded lot info
async function fetchImpoundVehicles(
  url: string,
  key: string,
  tenantId: string,
  towedDate?: string
): Promise<any[]> {
  let queryUrl = `${url}/rest/v1/impound_vehicles?tenant_id=eq.${tenantId}&status=in.(in_lot,pending_release)&select=*,impound_lots(id,name,address,city,state,zip,phone)`;

  if (towedDate) {
    queryUrl += `&towed_at=gte.${towedDate}T00:00:00Z&towed_at=lte.${towedDate}T23:59:59Z`;
  }

  const response = await fetch(queryUrl, {
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
    },
  });

  if (!response.ok) {
    console.error(`[fetchImpoundVehicles] query failed:`, response.status);
    return [];
  }

  return await response.json();
}

// Normalize license plate: remove spaces, dashes, convert to uppercase
function normalizePlate(plate: string): string {
  return plate.replace(/[\s\-\.]/g, "").toUpperCase();
}

// Format date for speaking
function formatDateForSpeech(dateStr: string): string {
  const date = new Date(dateStr);
  const options: Intl.DateTimeFormatOptions = {
    month: "long",
    day: "numeric",
    hour: "numeric",
    minute: "2-digit",
  };
  return date.toLocaleDateString("en-US", options);
}

// Calculate days between two dates
function daysBetween(date1: Date, date2: Date): number {
  const oneDay = 24 * 60 * 60 * 1000;
  return Math.floor(Math.abs((date2.getTime() - date1.getTime()) / oneDay));
}

// Parse vehicle description for fuzzy matching
function parseVehicleDescription(desc: string): {
  color?: string;
  make?: string;
  model?: string;
  year?: string;
} {
  const words = desc.toLowerCase().split(/\s+/);
  const colors = [
    "red", "blue", "green", "black", "white", "silver", "gray", "grey",
    "gold", "brown", "tan", "beige", "orange", "yellow", "purple", "maroon",
  ];
  const makes = [
    "honda", "toyota", "ford", "chevrolet", "chevy", "nissan", "bmw",
    "mercedes", "audi", "volkswagen", "vw", "hyundai", "kia", "mazda",
    "subaru", "lexus", "acura", "infiniti", "jeep", "dodge", "ram",
    "chrysler", "buick", "cadillac", "gmc", "lincoln", "tesla", "volvo",
  ];

  const result: { color?: string; make?: string; model?: string; year?: string } = {};

  for (const word of words) {
    if (colors.includes(word)) {
      result.color = word;
    } else if (makes.includes(word)) {
      result.make = word;
    } else if (/^\d{4}$/.test(word)) {
      result.year = word;
    }
  }

  // Model could be remaining words after color and make are extracted
  const remainingWords = words.filter(
    (w) => w !== result.color && w !== result.make && w !== result.year
  );
  if (remainingWords.length > 0) {
    result.model = remainingWords.join(" ");
  }

  return result;
}

Deno.serve(async (req) => {
  // Handle CORS preflight
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  // Auth: require Authorization header (service key or JWT from ElevenLabs tools)
  const authHeader = req.headers.get("authorization");
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return new Response(
      JSON.stringify({ found: false, error: "Unauthorized", message: "I'm having trouble accessing the system." }),
      { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

  try {
    const body: CheckImpoundRequest = await req.json();
    const { tenant_id, license_plate, license_plate_state, vin, vehicle_description, towed_date } = body;

    // Validate required tenant_id
    if (!tenant_id) {
      return new Response(
        JSON.stringify({
          found: false,
          error: "tenant_id is required",
          message: "I'm having trouble looking that up right now. Let me get someone to help you.",
        }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Validate at least one search param
    if (!license_plate && !vin && !vehicle_description) {
      return new Response(
        JSON.stringify({
          found: false,
          error: "At least one of license_plate, vin, or vehicle_description is required",
          message: "To look up your vehicle, I'll need either the license plate number, VIN, or a description of your car. Which would you like to provide?",
        }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Resolve tenant_id - it could be a UUID or a business name
    let resolvedTenantId = tenant_id;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    
    if (!uuidRegex.test(tenant_id)) {
      console.log(`[check-impound] tenant_id "${tenant_id}" is not UUID, looking up by name`);
      const resolved = await resolveTenantByName(SUPABASE_URL, SUPABASE_KEY, tenant_id);
      
      if (!resolved) {
        console.error("[check-impound] Could not resolve tenant by name");
        return new Response(
          JSON.stringify({
            found: false,
            error: "Could not identify business",
            message: "I'm having trouble accessing our system. Let me connect you with someone who can help.",
          }),
          { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
      
      resolvedTenantId = resolved;
      console.log(`[check-impound] Resolved "${tenant_id}" to tenant ${resolvedTenantId}`);
    }

    // Fetch vehicles
    const vehicles = await fetchImpoundVehicles(SUPABASE_URL, SUPABASE_KEY, resolvedTenantId, towed_date);

    if (!vehicles || vehicles.length === 0) {
      return new Response(
        JSON.stringify({
          found: false,
          message: "I couldn't find any vehicles matching that description in our system. It's possible it was towed by a different company, or the information might be different than what we have on file. Would you like me to try a different search, or would you prefer to speak with someone directly?",
          suggestions: [
            "Try searching by VIN number",
            "Check with local police for tow company info",
            "Verify the license plate number",
          ],
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Filter and score results based on search criteria
    const scoredResults: { vehicle: any; score: number }[] = [];
    const normalizedSearchPlate = license_plate ? normalizePlate(license_plate) : null;
    const normalizedVin = vin ? vin.toUpperCase().replace(/\s/g, "") : null;
    const parsedDesc = vehicle_description ? parseVehicleDescription(vehicle_description) : null;

    for (const v of vehicles) {
      let score = 0;

      // Priority 1: Exact license plate match
      if (normalizedSearchPlate && v.license_plate) {
        const vehiclePlate = normalizePlate(v.license_plate);
        if (vehiclePlate === normalizedSearchPlate) {
          score += 100;
          // Bonus for matching state
          if (license_plate_state && v.license_plate_state) {
            if (v.license_plate_state.toUpperCase() === license_plate_state.toUpperCase()) {
              score += 20;
            }
          }
        } else if (vehiclePlate.includes(normalizedSearchPlate) || normalizedSearchPlate.includes(vehiclePlate)) {
          // Partial plate match
          score += 30;
        }
      }

      // Priority 2: VIN match
      if (normalizedVin && v.vin) {
        const vehicleVin = v.vin.toUpperCase().replace(/\s/g, "");
        if (vehicleVin === normalizedVin) {
          score += 90;
        } else if (vehicleVin.includes(normalizedVin) || normalizedVin.includes(vehicleVin)) {
          score += 25;
        }
      }

      // Priority 3: Description match (fuzzy)
      if (parsedDesc) {
        if (parsedDesc.color && v.vehicle_color) {
          if (v.vehicle_color.toLowerCase().includes(parsedDesc.color)) {
            score += 15;
          }
        }
        if (parsedDesc.make && v.vehicle_make) {
          const vehicleMake = v.vehicle_make.toLowerCase();
          if (vehicleMake.includes(parsedDesc.make) || parsedDesc.make.includes(vehicleMake)) {
            score += 20;
          }
        }
        if (parsedDesc.model && v.vehicle_model) {
          const vehicleModel = v.vehicle_model.toLowerCase();
          if (vehicleModel.includes(parsedDesc.model) || parsedDesc.model.includes(vehicleModel)) {
            score += 15;
          }
        }
        if (parsedDesc.year && v.vehicle_year) {
          if (v.vehicle_year === parsedDesc.year) {
            score += 10;
          }
        }
      }

      if (score > 0) {
        scoredResults.push({ vehicle: v, score });
      }
    }

    // Sort by score descending
    scoredResults.sort((a, b) => b.score - a.score);

    // No matches found
    if (scoredResults.length === 0) {
      return new Response(
        JSON.stringify({
          found: false,
          message: "I couldn't find a vehicle matching that information in our impound lot. It's possible it was towed by a different company, or the plate number might be different. Would you like me to try searching by VIN instead?",
          suggestions: [
            "Try searching by VIN number",
            "Check with local police for tow company info",
            "Verify the license plate number",
          ],
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Format results
    const formatVehicle = (v: any): VehicleResult => {
      const towedAt = new Date(v.towed_at);
      const now = new Date();
      return {
        id: v.id,
        license_plate: v.license_plate,
        license_plate_state: v.license_plate_state,
        vehicle_year: v.vehicle_year,
        vehicle_make: v.vehicle_make,
        vehicle_model: v.vehicle_model,
        vehicle_color: v.vehicle_color,
        towed_from: v.towed_from_address,
        towed_at: v.towed_at,
        days_in_lot: daysBetween(towedAt, now),
        status: v.status,
      };
    };

    const formatLot = (lot: any): LotResult | null => {
      if (!lot) return null;
      const addressParts = [lot.address, lot.city, lot.state, lot.zip].filter(Boolean);
      return {
        name: lot.name,
        address: addressParts.join(", "),
        phone: lot.phone,
      };
    };

    const buildVehicleDescription = (v: VehicleResult): string => {
      const parts = [v.vehicle_year, v.vehicle_color, v.vehicle_make, v.vehicle_model].filter(Boolean);
      return parts.join(" ") || "your vehicle";
    };

    // Single match with high confidence
    if (scoredResults.length === 1 || scoredResults[0].score >= 90) {
      const topMatch = scoredResults[0].vehicle;
      const vehicle = formatVehicle(topMatch);
      const lot = formatLot(topMatch.impound_lots);
      const vehicleDesc = buildVehicleDescription(vehicle);
      const towedDate = formatDateForSpeech(vehicle.towed_at);

      let message = `Found your ${vehicleDesc}.`;
      if (vehicle.towed_from) {
        message += ` It was towed from ${vehicle.towed_from} on ${towedDate}`;
      } else {
        message += ` It was towed on ${towedDate}`;
      }
      if (lot) {
        message += ` and is currently at our ${lot.name} location.`;
        if (lot.phone) {
          message += ` You can reach us at ${lot.phone} to arrange pickup.`;
        }
      } else {
        message += ` and is currently in our impound lot.`;
      }

      if (vehicle.days_in_lot > 0) {
        message += ` It has been here for ${vehicle.days_in_lot} day${vehicle.days_in_lot > 1 ? "s" : ""}.`;
      }

      return new Response(
        JSON.stringify({
          found: true,
          vehicle,
          lot,
          message,
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Multiple matches - need clarification
    const topResults = scoredResults.slice(0, 5).map((r) => ({
      vehicle: formatVehicle(r.vehicle),
      lot: formatLot(r.vehicle.impound_lots),
    }));

    // Build clarification message
    const uniqueColors = [...new Set(topResults.map((r) => r.vehicle.vehicle_color).filter(Boolean))];

    let message = `I found ${scoredResults.length} vehicle${scoredResults.length > 1 ? "s" : ""} that could be yours.`;
    if (uniqueColors.length > 1) {
      message += " Can you tell me what color your car is to help narrow it down?";
    } else {
      message += " Can you give me more details like the year or color to help identify your vehicle?";
    }

    return new Response(
      JSON.stringify({
        found: true,
        multiple: true,
        count: scoredResults.length,
        vehicles: topResults,
        message,
      }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("[check-impound] Error:", error);
    return new Response(
      JSON.stringify({
        found: false,
        error: error instanceof Error ? error.message : String(error),
        message: "I'm having trouble with our system right now. Let me connect you with someone who can help look that up.",
      }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";
import { normalizePhoneE164 } from "../_shared/phoneNormalize.ts";

/**
 * Check Recovery Context
 * 
 * Called at the start of an inbound call to check if the caller
 * has an active recovery campaign and inject context for the AI.
 * 
 * Input:
 * - tenant_id: string
 * - customer_id: string (optional)
 * - customer_phone: string (optional)
 * - call_session_id: string (the new call session)
 * 
 * Output:
 * - has_recovery_campaign: boolean
 * - campaign_id: string | null
 * - recovery_context: object with original intent, service, objection
 * - ai_context_addition: string to add to AI prompt
 */
Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const { tenant_id, customer_id, customer_phone, call_session_id } = await req.json();

    if (!tenant_id) {
      return jsonResponse({ has_recovery_campaign: false, reason: "missing_tenant_id" });
    }

    // Find customer if not provided
    let finalCustomerId = customer_id;
    
    if (!finalCustomerId && customer_phone) {
      const normalizedPhone = normalizePhoneNumber(customer_phone);
      const { data: customer } = await supabase
        .from("customers")
        .select("id")
        .eq("tenant_id", tenant_id)
        .eq("phone_e164", normalizedPhone)
        .maybeSingle();

      if (customer) {
        finalCustomerId = customer.id;
      }
    }

    if (!finalCustomerId) {
      return jsonResponse({ has_recovery_campaign: false, reason: "customer_not_found" });
    }

    // Check for active recovery campaign
    const { data: activeCampaign } = await supabase
      .from("lead_recovery_campaigns")
      .select(`
        id,
        original_intent,
        original_service_interest,
        original_objection,
        original_call_outcome,
        total_attempts,
        sequence:lead_recovery_sequences(name)
      `)
      .eq("tenant_id", tenant_id)
      .eq("customer_id", finalCustomerId)
      .in("status", ["active", "paused"])
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (!activeCampaign) {
      return jsonResponse({ has_recovery_campaign: false });
    }

    // This is a recovery callback!
    console.log(`[Check Recovery] Found active campaign ${activeCampaign.id} for customer ${finalCustomerId}`);

    // Process as recovery response
    if (call_session_id) {
      try {
        await supabase.functions.invoke("process-recovery-response", {
          body: {
            tenant_id,
            customer_id: finalCustomerId,
            response_type: "inbound_call",
            response_content: "Customer called back",
            call_session_id,
          },
        });
      } catch (error) {
        console.error("[Check Recovery] Error processing response:", error);
      }

      // Update the call session with recovery context
      await supabase
        .from("ai_call_sessions")
        .update({
          is_recovery_call: true,
          recovery_campaign_id: activeCampaign.id,
          recovery_context: {
            campaign_id: activeCampaign.id,
            original_intent: activeCampaign.original_intent,
            original_service: activeCampaign.original_service_interest,
            original_objection: activeCampaign.original_objection,
          },
        })
        .eq("id", call_session_id);
    }

    // Build AI context addition for the agent prompt
    const aiContextAddition = buildAiContextAddition(activeCampaign);

    // Handle the sequence join which returns an array
    const sequenceData = activeCampaign.sequence as unknown;
    const sequenceName = Array.isArray(sequenceData) && sequenceData.length > 0
      ? (sequenceData[0] as { name?: string })?.name
      : typeof sequenceData === 'object' && sequenceData !== null
        ? (sequenceData as { name?: string })?.name
        : undefined;

    return jsonResponse({
      has_recovery_campaign: true,
      campaign_id: activeCampaign.id,
      recovery_context: {
        original_intent: activeCampaign.original_intent,
        original_service_interest: activeCampaign.original_service_interest,
        original_objection: activeCampaign.original_objection,
        original_call_outcome: activeCampaign.original_call_outcome,
        sequence_name: sequenceName,
        total_attempts: activeCampaign.total_attempts,
      },
      ai_context_addition: aiContextAddition,
    });

  } catch (error) {
    console.error("[Check Recovery] Error:", error);
    return jsonResponse({ has_recovery_campaign: false, error: String(error) });
  }
});

/**
 * Build context string to inject into AI agent prompt
 */
function buildAiContextAddition(campaign: any): string {
  const parts: string[] = [];

  parts.push("[RETURNING CUSTOMER CONTEXT]");
  parts.push("This customer called before and is calling back.");

  if (campaign.original_service_interest) {
    parts.push(`They previously asked about: ${campaign.original_service_interest}.`);
  } else if (campaign.original_intent) {
    parts.push(`Their previous inquiry was about: ${campaign.original_intent}.`);
  }

  if (campaign.original_objection) {
    parts.push(`They mentioned: "${campaign.original_objection}" as a concern.`);
  }

  parts.push("Greet them warmly like you remember them, and help them complete their booking.");
  parts.push("[END CONTEXT]");

  return parts.join(" ");
}

