import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";

interface CompleteRecoveryRequest {
  campaign_id: string;
  outcome: "converted" | "declined" | "stopped";
  recovered_value_cents?: number;
  booking_id?: string;
  dispatch_job_id?: string;
  food_order_id?: string;
  stop_reason?: string;
}

interface CompleteRecoveryResult {
  success: boolean;
  reason?: string;
  campaign_id?: string;
  status?: string;
  recovered_value_cents?: number;
  revenue_attribution_id?: string;
  audit_event_id?: string;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const body: CompleteRecoveryRequest = await req.json();
    const {
      campaign_id,
      outcome,
      recovered_value_cents,
      booking_id,
      dispatch_job_id,
      food_order_id,
      stop_reason,
    } = body;

    if (!campaign_id) {
      return jsonResponse({ success: false, reason: "missing_campaign_id" }, 400);
    }

    if (!outcome || !["converted", "declined", "stopped"].includes(outcome)) {
      return jsonResponse({ success: false, reason: "invalid_outcome" }, 400);
    }

    // Load campaign
    const { data: campaign, error: campaignError } = await supabase
      .from("lead_recovery_campaigns")
      .select("*")
      .eq("id", campaign_id)
      .maybeSingle();

    if (campaignError || !campaign) {
      console.error("Campaign not found:", campaignError);
      return jsonResponse({ success: false, reason: "campaign_not_found" }, 404);
    }

    if (campaign.status === "converted") {
      return jsonResponse({ success: false, reason: "already_converted" });
    }

    const now = new Date().toISOString();
    const result: CompleteRecoveryResult = {
      success: true,
      campaign_id,
      status: outcome,
    };

    if (outcome === "converted") {
      // Update campaign as converted
      await supabase
        .from("lead_recovery_campaigns")
        .update({
          status: "converted",
          converted_at: now,
          converted_booking_id: booking_id || null,
          converted_dispatch_job_id: dispatch_job_id || null,
          converted_food_order_id: food_order_id || null,
          recovered_value_cents: recovered_value_cents || null,
          next_action_at: null,
          updated_at: now,
        })
        .eq("id", campaign_id);

      // Update lead status
      if (campaign.lead_id) {
        await supabase
          .from("leads")
          .update({ 
            recovery_status: "recovered",
            status: "won"
          })
          .eq("id", campaign.lead_id);
      }

      result.recovered_value_cents = recovered_value_cents;

      // Create revenue attribution for ROI tracking
      if (recovered_value_cents && recovered_value_cents > 0) {
        const entityType = booking_id
          ? "booking"
          : dispatch_job_id
          ? "dispatch_job"
          : food_order_id
          ? "food_order"
          : "lead_recovery";
        const entityId = booking_id || dispatch_job_id || food_order_id || campaign_id;

        const { data: attribution } = await supabase
          .from("revenue_attributions")
          .insert({
            tenant_id: campaign.tenant_id,
            session_id: campaign.original_session_id || null,
            entity_type: entityType,
            entity_id: entityId,
            customer_id: campaign.customer_id,
            revenue_cents: recovered_value_cents,
            source_type: "lead_recovery",
            status: "pending",
            attributed_at: now,
          })
          .select("id")
          .single();

        if (attribution) {
          result.revenue_attribution_id = attribution.id;
        }
      }

      // Log audit event
      const { data: auditEvent } = await supabase
        .from("audit_events")
        .insert({
          tenant_id: campaign.tenant_id,
          event_type: "lead.recovered",
          entity_type: "lead_recovery_campaign",
          entity_id: campaign_id,
          actor_type: "system",
          payload: {
            campaign_id,
            customer_id: campaign.customer_id,
            lead_id: campaign.lead_id,
            recovered_value_cents,
            booking_id,
            dispatch_job_id,
            food_order_id,
            total_attempts: campaign.total_attempts,
          },
        })
        .select("id")
        .single();

      if (auditEvent) {
        result.audit_event_id = auditEvent.id;
      }

      console.log(`Campaign ${campaign_id} converted with value ${recovered_value_cents}`);

    } else {
      // Declined or stopped
      await supabase
        .from("lead_recovery_campaigns")
        .update({
          status: outcome,
          stopped_at: now,
          stopped_reason: stop_reason || (outcome === "declined" ? "Customer declined" : "Manually stopped"),
          next_action_at: null,
          updated_at: now,
        })
        .eq("id", campaign_id);

      // Update lead status
      if (campaign.lead_id) {
        await supabase
          .from("leads")
          .update({
            recovery_status: outcome === "declined" ? "declined" : "dormant",
            status: "lost"
          })
          .eq("id", campaign.lead_id);
      }

      console.log(`Campaign ${campaign_id} ${outcome}: ${stop_reason}`);
    }

    return jsonResponse(result);

  } catch (error) {
    console.error("Error in complete-lead-recovery:", error);
    return jsonResponse(
      { success: false, reason: "internal_error", message: String(error) },
      500
    );
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";
import { requireAuthedTenant, serviceClient } from "../_shared/tenant.ts";

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    const { tenantId } = await requireAuthedTenant(req);
    const supabase = serviceClient();

    const {
      start_date,
      end_date,
      duration_minutes = 60,
      buffer_minutes = 0,
      session_id, // Optional: if provided, locks slots for this session
      lock_slots = false, // Whether to lock returned slots for the session
      lock_ttl_minutes = 10, // How long to hold the locks
    } = await req.json();

    // Get tenant settings for business hours and capacity
    const { data: tenant } = await supabase
      .from("tenants")
      .select("hours_json, timezone, min_lead_hours, max_advance_days, default_capacity")
      .eq("id", tenantId)
      .single();

    const businessHours = tenant?.hours_json || null;
    const capacity = (tenant as any)?.default_capacity || 1;

    let slots;
    let slotsError;

    // Use session-aware slot computation if session_id provided
    if (session_id) {
      const result = await supabase.rpc("fn_refresh_session_slots", {
        _tenant_id: tenantId,
        _session_id: session_id,
        _start_date: start_date,
        _end_date: end_date,
        _duration_minutes: duration_minutes,
        _buffer_minutes: buffer_minutes,
        _business_hours: businessHours,
      });
      slots = result.data;
      slotsError = result.error;
    } else {
      // Standard computation without session awareness
      const result = await supabase.rpc("fn_compute_available_slots", {
        _tenant_id: tenantId,
        _start_date: start_date,
        _end_date: end_date,
        _duration_minutes: duration_minutes,
        _buffer_minutes: buffer_minutes,
        _business_hours: businessHours,
        _capacity: capacity,
      });
      slots = result.data;
      slotsError = result.error;
    }

    if (slotsError) {
      console.error("Slots error:", slotsError);
      return errorResponse(slotsError.message, 500);
    }

    // Lock the offered slots if requested
    let lockResult = null;
    if (lock_slots && session_id && slots && slots.length > 0) {
      const slotsToLock = slots.map((s: { slot_start: string; slot_end: string }) => ({
        start_at: s.slot_start,
        end_at: s.slot_end,
      }));

      const { data: lockData, error: lockError } = await supabase.rpc(
        "fn_lock_offered_slots",
        {
          _tenant_id: tenantId,
          _session_id: session_id,
          _slots: slotsToLock,
          _ttl_minutes: lock_ttl_minutes,
        }
      );

      if (lockError) {
        console.warn("Failed to lock slots:", lockError);
      } else if (lockData && lockData.length > 0) {
        lockResult = {
          locked_count: lockData[0].locked_count,
          failed_slots: lockData[0].failed_slots,
        };
      }
    }

    return jsonResponse({
      slots: slots || [],
      count: slots?.length || 0,
      date_range: { start_date, end_date },
      settings: {
        duration_minutes,
        buffer_minutes,
        min_lead_hours: tenant?.min_lead_hours,
        max_advance_days: tenant?.max_advance_days,
      },
      session_id: session_id || null,
      lock_result: lockResult,
    });
  } catch (error: unknown) {
    console.error("Error in compute-available-slots:", error);
    const message = error instanceof Error ? error.message : "Unknown error";
    return errorResponse(message, 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";
import { requireAuthedTenant, serviceClient } from "../_shared/tenant.ts";

interface NavigationItem {
  path: string;
  label: string;
  enabled: boolean;
}

interface CopilotContext {
  tenant: {
    id: string;
    business_name: string;
    industry: string;
    business_mode: string;
    timezone: string;
  };
  enabled_modules: string[];
  setup: {
    readiness_score: number;
    missing_critical_fields: string[];
  };
  phone: {
    assigned_number: string;
    connect_status: string;
    forwarding_phone: string;
    last_test_call_at: string;
    is_connected: boolean;
  };
  handoff: {
    booking: {
      enabled: boolean;
      methods: string[];
      has_email: boolean;
      has_sms: boolean;
      has_webhook: boolean;
    };
    orders: {
      enabled: boolean;
      methods: string[];
      has_email: boolean;
      has_sms: boolean;
      has_webhook: boolean;
      auto_print: boolean;
    };
    dispatch: {
      enabled: boolean;
      methods: string[];
      has_email: boolean;
      has_sms: boolean;
      has_webhook: boolean;
      has_urgent_sms: boolean;
    };
  };
  knowledge_status: {
    pending_suggestions_count: number;
    unresolved_conflicts_count: number;
    processing_uploads_count: number;
    last_upload_status: string | null;
  };
  navigation_map: NavigationItem[];
  recent_activity: {
    calls: Array<{ id: string; started_at: string; outcome: string; summary: string }>;
    bookings: Array<{ id: string; start_at: string; status: string; service_name: string }>;
    orders: Array<{ id: string; created_at: string; status: string; order_number: string }>;
    dispatch_jobs: Array<{ id: string; created_at: string; status: string; job_number: string; priority: string }>;
  };
  hipaa_mode: boolean;
}

function computeReadinessScore(
  businessMode: string,
  tenant: any,
  services: any[],
  menuItems: any[],
  assistantSettings: any,
  medicalSettings: any,
  faqs: any[],
  hours: any
): { score: number; missing: string[] } {
  const missing: string[] = [];
  let score = 0;
  const maxScore = 100;

  // Common fields (30 points)
  if (tenant.name) score += 10; else missing.push("Business name");
  if (tenant.phone_public) score += 5; else missing.push("Public phone number");
  if (hours && Object.keys(hours).length > 0) score += 10; else missing.push("Business hours");
  if (tenant.timezone) score += 5; else missing.push("Timezone");

  // Mode-specific fields
  switch (businessMode) {
    case "service":
      // Services (25 points)
      if (services.length >= 1) score += 15; else missing.push("At least 1 service");
      if (services.length >= 3) score += 10;
      // Booking settings (15 points)
      if (assistantSettings?.booking_url) score += 10; else missing.push("Booking URL");
      if (assistantSettings?.ai_booking_mode) score += 5;
      // Policies (15 points)
      if (tenant.cancellation_policy) score += 5; else missing.push("Cancellation policy");
      if (tenant.deposit_policy) score += 5; else missing.push("Deposit policy");
      if (tenant.payment_methods?.length > 0) score += 5; else missing.push("Payment methods");
      // Intake (10 points)
      if (tenant.context_fields_json?.length > 0) score += 10; else missing.push("Intake questions");
      // FAQs (5 points)
      if (faqs.length >= 3) score += 5; else missing.push("At least 3 FAQs");
      break;

    case "dispatch":
      // Services/job types (20 points)
      if (services.length >= 1) score += 15; else missing.push("At least 1 service/job type");
      if (services.length >= 3) score += 5;
      // Dispatch settings (20 points)
      if (tenant.service_area_json) score += 10; else missing.push("Service area");
      // Intake (15 points)
      if (tenant.context_fields_json?.length > 0) score += 15; else missing.push("Intake questions (location, situation)");
      // Escalation (15 points)
      if (tenant.ai_never_promise?.length > 0) score += 15; else missing.push("AI guardrails/escalation rules");
      break;

    case "food":
      // Menu (35 points)
      if (menuItems.length >= 1) score += 20; else missing.push("Menu items");
      if (menuItems.length >= 10) score += 15;
      // Order delivery (15 points)
      // (checked via handoff settings externally)
      score += 15; // Assume delivery configured if they're using food mode
      // Policies (10 points)
      if (tenant.cancellation_policy) score += 5;
      if (tenant.payment_methods?.length > 0) score += 5; else missing.push("Payment methods");
      // Hours already counted (10 points)
      break;

    case "medical":
      // Intake fields (25 points)
      if (medicalSettings?.intake_fields_json?.length > 0) score += 25; else missing.push("Medical intake fields");
      // Scheduling rules (15 points)
      if (medicalSettings?.scheduling_rules_json) score += 15; else missing.push("Scheduling rules");
      // HIPAA settings (15 points)
      if (medicalSettings?.id) score += 15; else missing.push("HIPAA settings configured");
      // Services (10 points)
      if (services.length >= 1) score += 10; else missing.push("Appointment types");
      break;

    default: // general
      if (services.length >= 1) score += 20;
      if (faqs.length >= 3) score += 15;
      if (tenant.cancellation_policy) score += 10;
      break;
  }

  return { score: Math.min(score, maxScore), missing };
}

function buildNavigationMap(businessMode: string, enabledModules: string[]): NavigationItem[] {
  const baseNav: NavigationItem[] = [
    { path: "/app", label: "Dashboard", enabled: true },
    { path: "/app/inbox", label: "Inbox", enabled: true },
    { path: "/app/calls", label: "Calls", enabled: true },
    { path: "/app/leads", label: "Leads", enabled: true },
    { path: "/app/brain", label: "Business Brain", enabled: true },
    { path: "/app/simulator", label: "Simulator", enabled: true },
    { path: "/app/settings", label: "Settings", enabled: true },
    { path: "/app/usage", label: "Usage", enabled: true },
  ];

  // Mode-specific and module-specific navigation
  const conditionalNav: NavigationItem[] = [
    { 
      path: "/app/bookings", 
      label: "Bookings", 
      enabled: enabledModules.includes("booking") || businessMode === "service" || businessMode === "medical"
    },
    { 
      path: "/app/services", 
      label: "Services", 
      enabled: businessMode === "service" || businessMode === "dispatch" || businessMode === "medical" || businessMode === "general"
    },
    { 
      path: "/app/orders", 
      label: "Orders", 
      enabled: enabledModules.includes("food_orders") || businessMode === "food"
    },
    { 
      path: "/app/menu", 
      label: "Menu Center", 
      enabled: enabledModules.includes("menu_knowledge") || businessMode === "food"
    },
    { 
      path: "/app/reservations", 
      label: "Reservations", 
      enabled: enabledModules.includes("reservations") || businessMode === "food"
    },
    { 
      path: "/app/catering", 
      label: "Catering", 
      enabled: enabledModules.includes("catering") || businessMode === "food"
    },
    { 
      path: "/app/dispatch", 
      label: "Dispatch", 
      enabled: enabledModules.includes("dispatch_queue") || businessMode === "dispatch"
    },
    { 
      path: "/app/medical-intake", 
      label: "Medical Intake", 
      enabled: enabledModules.includes("medical_intake") || businessMode === "medical"
    },
  ];

  return [...baseNav, ...conditionalNav.filter(n => n.enabled)];
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    const { tenantId } = await requireAuthedTenant(req);
    const supabase = serviceClient();

    // Fetch all needed data in parallel
    const [
      tenantResult,
      assistantResult,
      servicesResult,
      menuItemsResult,
      faqsResult,
      bookingDeliveryResult,
      orderDeliveryResult,
      dispatchDeliveryResult,
      medicalSettingsResult,
      phoneNumbersResult,
      recentCallsResult,
      recentBookingsResult,
      recentOrdersResult,
      recentDispatchResult,
      knowledgeSourcesResult,
      suggestionsResult,
      conflictsResult,
    ] = await Promise.all([
      supabase.from("tenants").select("*").eq("id", tenantId).single(),
      supabase.from("assistant_settings").select("*").eq("tenant_id", tenantId).single(),
      supabase.from("services").select("*").eq("tenant_id", tenantId).eq("is_active", true),
      supabase.from("menu_items").select("*").eq("tenant_id", tenantId).eq("is_available", true),
      supabase.from("business_faqs").select("*").eq("tenant_id", tenantId),
      supabase.from("booking_delivery_settings").select("*").eq("tenant_id", tenantId).single(),
      supabase.from("order_delivery_settings").select("*").eq("tenant_id", tenantId).single(),
      supabase.from("dispatch_delivery_settings").select("*").eq("tenant_id", tenantId).single(),
      supabase.from("medical_settings").select("*").eq("tenant_id", tenantId).single(),
      supabase.from("phone_numbers").select("*").eq("tenant_id", tenantId).eq("purpose", "forwarding").single(),
      supabase.from("ai_call_sessions").select("id, started_at, outcome, summary").eq("tenant_id", tenantId).order("started_at", { ascending: false }).limit(10),
      supabase.from("bookings").select("id, start_at, status, service_id, services(name)").eq("tenant_id", tenantId).order("start_at", { ascending: false }).limit(10),
      supabase.from("food_orders").select("id, created_at, status, order_number").eq("tenant_id", tenantId).order("created_at", { ascending: false }).limit(10),
      supabase.from("dispatch_jobs").select("id, created_at, status, job_number, priority").eq("tenant_id", tenantId).order("created_at", { ascending: false }).limit(10),
      supabase.from("knowledge_sources").select("id, status").eq("tenant_id", tenantId).order("created_at", { ascending: false }).limit(1),
      supabase.from("extracted_knowledge_suggestions").select("id", { count: "exact", head: true }).eq("tenant_id", tenantId).eq("status", "pending_review"),
      supabase.from("knowledge_conflicts").select("id", { count: "exact", head: true }).eq("tenant_id", tenantId).eq("status", "unresolved"),
    ]);

    const tenant = tenantResult.data;
    const assistantSettings = assistantResult.data;
    const services = servicesResult.data || [];
    const menuItems = menuItemsResult.data || [];
    const faqs = faqsResult.data || [];
    const bookingDelivery = bookingDeliveryResult.data;
    const orderDelivery = orderDeliveryResult.data;
    const dispatchDelivery = dispatchDeliveryResult.data;
    const medicalSettings = medicalSettingsResult.data;
    const phoneNumber = phoneNumbersResult.data;

    if (!tenant) {
      return errorResponse("Tenant not found", 404);
    }

    const businessMode = tenant.business_mode || "service";
    const enabledModules = tenant.enabled_modules || [];
    const hipaaMode = businessMode === "medical" || tenant.hipaa_mode === true;

    // Compute readiness
    const { score: readinessScore, missing: missingFields } = computeReadinessScore(
      businessMode,
      tenant,
      services,
      menuItems,
      assistantSettings,
      medicalSettings,
      faqs,
      tenant.hours_json
    );

    // Build navigation map
    const navigationMap = buildNavigationMap(businessMode, enabledModules);

    // Parse handoff methods safely
    const parseHandoffMethods = (methods: any): string[] => {
      if (!methods) return [];
      if (Array.isArray(methods)) return methods;
      if (typeof methods === "object") return Object.keys(methods).filter(k => methods[k]);
      return [];
    };

    // Build recent activity (PHI-minimized for medical)
    const recentCalls = (recentCallsResult.data || []).map((c: any) => ({
      id: c.id,
      started_at: c.started_at || "",
      outcome: c.outcome || "unknown",
      summary: hipaaMode ? (c.summary ? "Summary available" : "") : (c.summary || ""),
    }));

    const recentBookings = (recentBookingsResult.data || []).map((b: any) => ({
      id: b.id,
      start_at: b.start_at || "",
      status: b.status || "pending",
      service_name: b.services?.name || "Service",
    }));

    const recentOrders = (recentOrdersResult.data || []).map((o: any) => ({
      id: o.id,
      created_at: o.created_at || "",
      status: o.status || "pending",
      order_number: o.order_number || "",
    }));

    const recentDispatch = (recentDispatchResult.data || []).map((d: any) => ({
      id: d.id,
      created_at: d.created_at || "",
      status: d.status || "pending",
      job_number: d.job_number || "",
      priority: d.priority || "normal",
    }));

    // Build context object
    const copilotContext: CopilotContext = {
      tenant: {
        id: tenant.id,
        business_name: tenant.name || "",
        industry: tenant.industry || "",
        business_mode: businessMode,
        timezone: tenant.timezone || "America/New_York",
      },
      enabled_modules: enabledModules,
      setup: {
        readiness_score: readinessScore,
        missing_critical_fields: missingFields,
      },
      phone: {
        assigned_number: phoneNumber?.phone_e164 || assistantSettings?.closeloop_number || "",
        connect_status: assistantSettings?.connect_status || "not_connected",
        forwarding_phone: assistantSettings?.forwarding_phone_e164 || "",
        last_test_call_at: recentCalls.length > 0 ? recentCalls[0].started_at : "",
        is_connected: assistantSettings?.phone_connected === true,
      },
      handoff: {
        booking: {
          enabled: bookingDelivery?.enabled === true,
          methods: parseHandoffMethods(bookingDelivery?.handoff_methods),
          has_email: !!bookingDelivery?.notify_email,
          has_sms: !!bookingDelivery?.notify_phone,
          has_webhook: !!bookingDelivery?.webhook_url,
        },
        orders: {
          enabled: orderDelivery?.enabled === true,
          methods: parseHandoffMethods(orderDelivery?.handoff_methods),
          has_email: !!orderDelivery?.notify_email,
          has_sms: !!orderDelivery?.notify_phone,
          has_webhook: !!orderDelivery?.webhook_url,
          auto_print: orderDelivery?.auto_print === true,
        },
        dispatch: {
          enabled: dispatchDelivery?.enabled === true,
          methods: parseHandoffMethods(dispatchDelivery?.handoff_methods),
          has_email: !!dispatchDelivery?.notify_email,
          has_sms: !!dispatchDelivery?.notify_phone,
          has_webhook: !!dispatchDelivery?.webhook_url,
          has_urgent_sms: !!dispatchDelivery?.urgent_sms_phone,
        },
      },
      knowledge_status: {
        pending_suggestions_count: suggestionsResult.count || 0,
        unresolved_conflicts_count: conflictsResult.count || 0,
        processing_uploads_count: (knowledgeSourcesResult.data || []).filter((s: any) => s.status === 'processing' || s.status === 'uploading').length,
        last_upload_status: knowledgeSourcesResult.data?.[0]?.status || null,
      },
      navigation_map: navigationMap,
      recent_activity: {
        calls: recentCalls,
        bookings: recentBookings,
        orders: recentOrders,
        dispatch_jobs: recentDispatch,
      },
      hipaa_mode: hipaaMode,
    };

    return jsonResponse({ copilot_context: copilotContext });
  } catch (error) {
    console.error("Error in copilot-context:", error);
    const message = error instanceof Error ? error.message : "Unknown error";
    return errorResponse(message, 500);
  }
});

/**
 * @deprecated Use elevenlabs-create-dispatch-job instead.
 * This function is the older dispatch creation endpoint that lacks:
 * - Distance/pricing calculation via check-service-area
 * - price_cents storage for revenue attribution
 * - Geocoded coordinate storage
 * - Module gating check (dispatch_queue)
 *
 * Kept for backward compatibility until confirmed no active tool configs reference it.
 * Plan for removal in next major cleanup.
 *
 * create-dispatch-request: ElevenLabs tool endpoint for creating dispatch jobs
 * during voice calls.
 *
 * Called by ElevenLabs agent when it has collected enough dispatch intake info:
 * - customer_name, customer_phone
 * - pickup_address, dropoff_address (optional)
 * - vehicle_type, drivable, urgency
 * - notes
 */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsResponse, jsonResponse } from "../_shared/cors.ts";
import { sanitizeCustomerName, isPlaceholderName, shouldUpdateCustomerName } from "../_shared/sanitizeName.ts";
import { normalizePhoneE164 } from "../_shared/phoneNormalize.ts";

interface CreateDispatchRequest {
  // Customer info (name is optional; phone is required to link/create a customer)
  customer_name?: string;
  customer_phone?: string;

  // Dispatch info
  pickup_address: string;
  dropoff_address?: string;
  vehicle_type?: string;
  drivable?: boolean;
  urgency?: "emergency" | "same_day" | "scheduled";
  notes?: string;

  // ElevenLabs context
  conversation_id?: string;
  agent_id?: string;
}

interface CreateDispatchResponse {
  success: boolean;
  job_number?: string;
  dispatch_id?: string;
  message: string;
  error?: string;
}

// Use shared phone normalization
const normalizePhone = normalizePhoneE164;

// Generate job number
function generateJobNumber(): string {
  const now = new Date();
  const dateStr = now.toISOString().slice(2, 10).replace(/-/g, "");
  const random = Math.random().toString(36).substring(2, 6).toUpperCase();
  return `DSP-${dateStr}-${random}`;
}

// Map urgency to priority
function urgencyToPriority(urgency?: string): "low" | "normal" | "high" | "urgent" {
  switch (urgency) {
    case "emergency": return "urgent";
    case "same_day": return "normal";
    case "scheduled": return "low";
    default: return "normal";
  }
}

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    const body: CreateDispatchRequest = await req.json();
    const { 
      customer_name, 
      customer_phone, 
      pickup_address, 
      dropoff_address,
      vehicle_type,
      drivable,
      urgency,
      notes,
      conversation_id 
    } = body;

    const pickupAddress = (pickup_address || "").trim();

    // Validate required fields
    if (!pickupAddress) {
      return jsonResponse({
        success: false,
        message: "Missing required information",
        error: "pickup_address is required"
      } as CreateDispatchResponse);
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, serviceKey);

    // Get tenant_id from active conversation
    let tenantId: string | null = null;
    let sessionId: string | null = null;
    let sessionCallerPhone: string | null = null;
    
    // Strategy 1: Find by conversation_id
    if (conversation_id) {
      const { data: session } = await supabase
        .from("ai_call_sessions")
        .select("tenant_id, id, caller_phone")
        .eq("elevenlabs_conversation_id", conversation_id)
        .maybeSingle();
      
      tenantId = session?.tenant_id || null;
      sessionId = session?.id || null;
      sessionCallerPhone = session?.caller_phone || null;
      if (tenantId) {
        console.log(`[create-dispatch] Found session by conversation_id: ${conversation_id}`);
      }
    }

    // P0-2: Removed cross-tenant fallback (Strategy 2) that queried most
    // recent session across ALL tenants. This was a tenant isolation risk.
    
    // Strategy 3: Find by caller phone from body (recent session in last 5 min)
    if (!tenantId && customer_phone) {
      const phoneE164 = normalizePhone(customer_phone);
      const fiveMinAgo = new Date(Date.now() - 5 * 60 * 1000).toISOString();
      
      const { data: phoneSession } = await supabase
        .from("ai_call_sessions")
        .select("tenant_id, id, caller_phone")
        .eq("caller_phone", phoneE164)
        .gte("created_at", fiveMinAgo)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      
      tenantId = phoneSession?.tenant_id || null;
      sessionId = phoneSession?.id || null;
      sessionCallerPhone = phoneSession?.caller_phone || phoneE164 || null;
      if (tenantId) {
        console.log(`[create-dispatch] Found session by phone ${phoneE164}: ${sessionId}`);
      }
    }

    if (!tenantId) {
      console.error(`[create-dispatch] No session found. conv_id=${conversation_id}, phone=${customer_phone}`);
      return jsonResponse({
        success: false,
        message: "Unable to identify business",
        error: "No active voice session found"
      } as CreateDispatchResponse);
    }
    
    console.log(`[create-dispatch] Processing for tenant ${tenantId}, session ${sessionId}`);

    const rawCustomerName = (customer_name || "").trim();
    const effectivePhoneRaw = (customer_phone || sessionCallerPhone || "").trim();
    const phoneE164 = normalizePhone(effectivePhoneRaw);

    // Log if placeholder name was detected
    if (isPlaceholderName(rawCustomerName)) {
      console.log(`[create-dispatch] Placeholder name detected: "${rawCustomerName}" - will store as "Unknown"`);
      // Log to ai_event_logs for tracking
      try {
        await supabase.from("ai_event_logs").insert({
          tenant_id: tenantId,
          session_id: sessionId,
          stage: "dispatch_identity_missing",
          event_data: {
            tool: "create-dispatch-request",
            placeholder_detected: rawCustomerName || null,
            has_caller_phone: !!phoneE164,
          },
        });
      } catch (e) {
        // Don't block on logging errors
      }
    }

    // Sanitize customer name (converts placeholders to "Unknown")
    const sanitizedName = sanitizeCustomerName(rawCustomerName);

    if (!phoneE164) {
      return jsonResponse({
        success: false,
        message: "Missing phone number",
        error: "customer_phone is required to create a dispatch job"
      } as CreateDispatchResponse);
    }

    // Find or create customer (dispatch_jobs.customer_id is NOT NULL)
    let customerId: string | null = null;

    const { data: existingCustomer, error: existingCustomerError } = await supabase
      .from("customers")
      .select("id, full_name")
      .eq("tenant_id", tenantId)
      .eq("phone_e164", phoneE164)
      .maybeSingle();

    if (existingCustomerError) {
      console.error("[create-dispatch-request] Customer lookup error:", existingCustomerError);
    }

    if (existingCustomer) {
      customerId = existingCustomer.id;

      // Only update name if new name is better than existing
      if (shouldUpdateCustomerName(existingCustomer.full_name, rawCustomerName)) {
        await supabase
          .from("customers")
          .update({ full_name: sanitizedName, updated_at: new Date().toISOString() })
          .eq("id", customerId);
      } else {
        await supabase
          .from("customers")
          .update({ updated_at: new Date().toISOString() })
          .eq("id", customerId);
      }
    } else {
      const { data: newCustomer, error: customerError } = await supabase
        .from("customers")
        .insert({
          tenant_id: tenantId,
          full_name: sanitizedName,
          phone_e164: phoneE164,
          phone_raw: effectivePhoneRaw || null,
          source: "voice_ai",
        })
        .select("id")
        .single();

      if (customerError) {
        console.error("[create-dispatch-request] Failed to create customer:", customerError);
      } else {
        customerId = newCustomer?.id || null;
      }
    }

    if (!customerId) {
      return jsonResponse({
        success: false,
        message: "Unable to create dispatch request",
        error: "Could not resolve or create customer"
      } as CreateDispatchResponse);
    }

    // Use sanitized name for dispatch job
    const dispatchCustomerName = sanitizedName;

    // Generate job number
    const jobNumber = generateJobNumber();

    // Build description
    const descriptionParts: string[] = [];
    if (vehicle_type) descriptionParts.push(`Vehicle: ${vehicle_type}`);
    if (typeof drivable === "boolean") descriptionParts.push(`Drivable: ${drivable ? "Yes" : "No"}`);
    const description = descriptionParts.join(". ") || null;

    // Create dispatch job
    const { data: dispatch, error: dispatchError } = await supabase
      .from("dispatch_jobs")
      .insert({
        tenant_id: tenantId,
        job_number: jobNumber,
        customer_id: customerId,
        customer_name: dispatchCustomerName,
        customer_phone: phoneE164,
        pickup_address: pickupAddress,
        dropoff_address: dropoff_address || null,
        job_type: vehicle_type ? "Tow" : "Dispatch",
        priority: urgencyToPriority(urgency),
        status: "pending",
        description: description,
        notes: notes || null,
        session_id: sessionId,
        requested_at: new Date().toISOString(),
      })
      .select("id, job_number")
      .single();

    if (dispatchError) {
      console.error("[create-dispatch-request] Error creating dispatch:", dispatchError);
      return jsonResponse({
        success: false,
        message: "Failed to create dispatch request",
        error: dispatchError.message
      } as CreateDispatchResponse);
    }

    // Trigger dispatch handoff to notify the business
    try {
      await fetch(`${supabaseUrl}/functions/v1/dispatch-handoff`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${serviceKey}`,
        },
        body: JSON.stringify({
          dispatch_id: dispatch.id,
          tenant_id: tenantId,
        }),
      });
    } catch (e) {
      console.error("[create-dispatch-request] Failed to trigger handoff:", e);
      // Don't fail the whole request if handoff fails
    }

    // Update session with dispatch outcome
    if (sessionId) {
      await supabase
        .from("ai_call_sessions")
        .update({
          outcome: "dispatch",
          extracted_payload: {
            dispatch_id: dispatch.id,
            job_number: dispatch.job_number,
            customer_name: sanitizedName || null,
            customer_phone: phoneE164,
            pickup_address: pickupAddress,
            dropoff_address: dropoff_address || null,
            vehicle_type,
            drivable,
            urgency,
            notes,
          }
        })
        .eq("id", sessionId);
    }

    console.log(`[create-dispatch-request] Created dispatch ${dispatch.job_number} for tenant ${tenantId.substring(0, 8)}...`);

    const response: CreateDispatchResponse = {
      success: true,
      job_number: dispatch.job_number,
      dispatch_id: dispatch.id,
      message: `Dispatch ${dispatch.job_number} created successfully`
    };

    return jsonResponse(response);

  } catch (error) {
    console.error("[create-dispatch-request] Error:", error);
    return jsonResponse({
      success: false,
      message: "Unable to submit dispatch request",
      error: error instanceof Error ? error.message : "Unknown error"
    } as CreateDispatchResponse);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, jsonResponse, errorResponse, corsResponse } from "../_shared/cors.ts";
import { serviceClient } from "../_shared/tenant.ts";

/**
 * cron-a2p-status-check
 * 
 * Runs on a schedule (every 30 minutes) to poll Twilio for A2P brand
 * and campaign approval status. Updates a2p_registrations accordingly.
 * 
 * When a campaign is approved, SMS capabilities become available for that tenant.
 */

serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();

  const TWILIO_ACCOUNT_SID = Deno.env.get("TWILIO_ACCOUNT_SID");
  const TWILIO_AUTH_TOKEN = Deno.env.get("TWILIO_AUTH_TOKEN");

  if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN) {
    return errorResponse("Twilio credentials not configured", 500);
  }

  const supabase = serviceClient();
  const twilioAuth = btoa(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`);

  try {
    // ========== TOLL-FREE VERIFICATION CHECK ==========
    const { data: pendingTF } = await supabase
      .from("a2p_registrations")
      .select("id, tenant_id, toll_free_verification_sid")
      .eq("toll_free_verified", false)
      .not("toll_free_verification_sid", "is", null);

    let tfUpdated = 0;
    if (pendingTF?.length) {
      console.log(`[cron-a2p] Checking ${pendingTF.length} pending toll-free verifications`);
      for (const reg of pendingTF) {
        try {
          const tfRes = await fetch(
            `https://messaging.twilio.com/v1/Tollfree/Verifications/${reg.toll_free_verification_sid}`,
            { headers: { Authorization: `Basic ${twilioAuth}` } }
          );
          if (tfRes.ok) {
            const tfData = await tfRes.json();
            console.log(`[cron-a2p] TF verification ${reg.toll_free_verification_sid} status: ${tfData.status}`);
            if (tfData.status === "TWILIO_APPROVED" || tfData.status === "APPROVED") {
              await supabase
                .from("a2p_registrations")
                .update({ toll_free_verified: true })
                .eq("id", reg.id);
              console.log(`[cron-a2p] ✅ Toll-free verified for tenant ${reg.tenant_id}`);
              tfUpdated++;
            }
          }
        } catch (e) {
          console.error(`[cron-a2p] Error checking TF verification ${reg.id}:`, e);
        }
      }
    }

    // ========== 10DLC STATUS CHECK (existing logic) ==========
    const { data: pendingRegs, error: fetchError } = await supabase
      .from("a2p_registrations")
      .select("*")
      .in("status", ["pending_profile", "pending_brand", "pending_campaign"]);

    if (fetchError) {
      console.error("[cron-a2p] Failed to fetch pending registrations:", fetchError);
      return errorResponse("Failed to fetch pending registrations", 500);
    }

    if (!pendingRegs || pendingRegs.length === 0) {
      console.log("[cron-a2p] No pending A2P registrations to check");
      return jsonResponse({ checked: 0, tf_updated: tfUpdated });
    }

    console.log(`[cron-a2p] Checking ${pendingRegs.length} pending A2P registrations`);

    let updated = 0;

    for (const reg of pendingRegs) {
      try {
        // Check Brand Registration status
        if (reg.status === "pending_brand" && reg.brand_sid) {
          const brandRes = await fetch(
            `https://messaging.twilio.com/v1/a2p/BrandRegistrations/${reg.brand_sid}`,
            { headers: { Authorization: `Basic ${twilioAuth}` } }
          );

          if (brandRes.ok) {
            const brandData = await brandRes.json();
            console.log(`[cron-a2p] Brand ${reg.brand_sid} status: ${brandData.status}, score: ${brandData.brand_score}`);

            if (brandData.status === "APPROVED") {
              await supabase.from("a2p_registrations").update({
                brand_score: brandData.brand_score,
                status: reg.campaign_sid ? "pending_campaign" : "pending_brand",
              }).eq("id", reg.id);

              if (!reg.messaging_service_sid || !reg.campaign_sid) {
                console.log(`[cron-a2p] Brand approved for tenant ${reg.tenant_id}, triggering next registration steps`);
                const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
                await fetch(`${SUPABASE_URL}/functions/v1/register-a2p-10dlc`, {
                  method: "POST",
                  headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")}`,
                  },
                  body: JSON.stringify({ tenant_id: reg.tenant_id }),
                });
              }
              updated++;
            } else if (brandData.status === "FAILED") {
              await supabase.from("a2p_registrations").update({
                status: "failed",
                failure_reason: `Brand registration failed: ${brandData.failure_reason || "Unknown reason"}`,
                brand_score: brandData.brand_score,
              }).eq("id", reg.id);
              updated++;
            }
          }
        }

        // Check Campaign status
        if (reg.status === "pending_campaign" && reg.campaign_sid && reg.messaging_service_sid) {
          const campaignRes = await fetch(
            `https://messaging.twilio.com/v1/Services/${reg.messaging_service_sid}/UsAppToPerson/${reg.campaign_sid}`,
            { headers: { Authorization: `Basic ${twilioAuth}` } }
          );

          if (campaignRes.ok) {
            const campaignData = await campaignRes.json();
            console.log(`[cron-a2p] Campaign ${reg.campaign_sid} status: ${campaignData.campaign_status}`);

            if (campaignData.campaign_status === "VERIFIED") {
              console.log(`[cron-a2p] 🎉 Campaign APPROVED for tenant ${reg.tenant_id}! SMS is now active.`);
              await supabase.from("a2p_registrations").update({
                status: "approved",
                failure_reason: null,
              }).eq("id", reg.id);
              updated++;
            } else if (campaignData.campaign_status === "FAILED") {
              await supabase.from("a2p_registrations").update({
                status: "failed",
                failure_reason: `Campaign failed: ${campaignData.failure_reason || "Rejected by carrier"}`,
              }).eq("id", reg.id);
              updated++;
            }
          }
        }

        // Check Customer Profile status (for pending_profile)
        if (reg.status === "pending_profile" && reg.customer_profile_sid) {
          const profileRes = await fetch(
            `https://trusthub.twilio.com/v1/CustomerProfiles/${reg.customer_profile_sid}`,
            { headers: { Authorization: `Basic ${twilioAuth}` } }
          );

          if (profileRes.ok) {
            const profileData = await profileRes.json();
            console.log(`[cron-a2p] Profile ${reg.customer_profile_sid} status: ${profileData.status}`);

            if (profileData.status === "twilio-approved") {
              const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
              await fetch(`${SUPABASE_URL}/functions/v1/register-a2p-10dlc`, {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                  Authorization: `Bearer ${Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")}`,
                },
                body: JSON.stringify({ tenant_id: reg.tenant_id }),
              });
              updated++;
            } else if (profileData.status === "twilio-rejected") {
              await supabase.from("a2p_registrations").update({
                status: "failed",
                failure_reason: `Customer Profile rejected: ${profileData.failure_reason || "Review failed"}`,
              }).eq("id", reg.id);
              updated++;
            }
          }
        }
      } catch (regErr) {
        console.error(`[cron-a2p] Error checking registration ${reg.id}:`, regErr);
      }
    }

    console.log(`[cron-a2p] Checked ${pendingRegs.length} registrations, updated ${updated}, TF updated ${tfUpdated}`);
    return jsonResponse({ checked: pendingRegs.length, updated, tf_updated: tfUpdated });
  } catch (error) {
    console.error("[cron-a2p] Error:", error);
    return errorResponse(error instanceof Error ? error.message : "Unknown error", 500);
  }
});

/**
 * cron-appointment-reminders: Send SMS reminders for upcoming appointments.
 *
 * Called by pg_cron every 15 minutes. Sends reminders based on tenant's
 * configured timing in assistant_settings.settings_json.sms_templates.
 *
 * Uses shared sms-sender for intelligent 10DLC/toll-free routing.
 */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { sendTenantSms } from "../_shared/sms-sender.ts";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

const DEFAULT_REMINDER_TEMPLATE =
  "Hi {{customer_name}}, this is a reminder that your {{service_name}} appointment with {{business_name}} is coming up at {{appointment_time}}. We look forward to seeing you!";

function resolveTemplate(
  template: string,
  vars: Record<string, string>,
): string {
  return template.replace(/\{\{(\w+)\}\}/g, (_, key) => vars[key] || "");
}

serve(async (_req: Request) => {
  try {
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
    const now = new Date();
    const results = { checked: 0, sent_reminders: 0, errors: 0, skipped_sms: 0 };

    // Get all tenants with SMS templates configured
    const { data: allSettings, error: settingsErr } = await supabase
      .from("assistant_settings")
      .select("tenant_id, settings_json");

    if (settingsErr) {
      console.error("[cron-appointment-reminders] Error fetching settings:", settingsErr);
      return new Response(JSON.stringify({ error: settingsErr.message }), { status: 500 });
    }

    const enabledTenants = (allSettings || []).filter((s: any) => {
      const json = s.settings_json as Record<string, any> | null;
      return json?.sms_templates?.appointment_reminder?.enabled === true;
    });

    if (enabledTenants.length === 0) {
      return new Response(JSON.stringify({ message: "No tenants with reminders enabled", ...results }));
    }

    const tenantIds = enabledTenants.map((s: any) => s.tenant_id);

    // Build tenant settings map
    const settingsMap = new Map<string, any>();
    for (const s of enabledTenants) {
      settingsMap.set(s.tenant_id, s.settings_json || {});
    }

    // Get tenant business names
    const { data: tenants } = await supabase
      .from("tenants")
      .select("id, name")
      .in("id", tenantIds);
    const tenantNameMap = new Map((tenants || []).map((t: any) => [t.id, t.name]));

    // Process each tenant
    for (const tenantId of tenantIds) {
      const tenantSettings = settingsMap.get(tenantId) || {};
      const smsTemplates = tenantSettings.sms_templates || {};
      const reminderConfig = smsTemplates.appointment_reminder || {};
      const delayMinutes = reminderConfig.delayMinutes || 1440;
      const template = reminderConfig.message || DEFAULT_REMINDER_TEMPLATE;

      // Window: target time ± 15 min (cron frequency)
      const targetMs = delayMinutes * 60 * 1000;
      const windowStart = new Date(now.getTime() + targetMs - 15 * 60 * 1000).toISOString();
      const windowEnd = new Date(now.getTime() + targetMs + 15 * 60 * 1000).toISOString();

      const isShortReminder = delayMinutes <= 120;
      const flagColumn = isShortReminder ? "reminder_sent_1h" : "reminder_sent_24h";

      const { data: bookings } = await supabase
        .from("bookings")
        .select("id, tenant_id, start_at, lead_id, service_id, leads(full_name, phone), services(name)")
        .eq("tenant_id", tenantId)
        .in("status", ["confirmed", "pending"])
        .gte("start_at", windowStart)
        .lte("start_at", windowEnd)
        .eq(flagColumn, false);

      if (!bookings?.length) continue;
      results.checked += bookings.length;

      const businessName = tenantNameMap.get(tenantId) || "";

      for (const booking of bookings) {
        try {
          const lead = booking.leads as any;
          const phone = lead?.phone;
          if (!phone) continue;

          const startTime = new Date(booking.start_at).toLocaleTimeString("en-US", {
            hour: "numeric",
            minute: "2-digit",
          });
          const startDate = new Date(booking.start_at).toLocaleDateString("en-US", {
            weekday: "long",
            month: "long",
            day: "numeric",
          });

          const message = resolveTemplate(template, {
            customer_name: lead?.full_name || "there",
            service_name: (booking.services as any)?.name || "your appointment",
            business_name: businessName,
            appointment_time: startTime,
            appointment_date: startDate,
          });

          const smsResult = await sendTenantSms({
            tenantId,
            to: phone,
            body: message,
          });

          if (smsResult.success) {
            await supabase
              .from("bookings")
              .update({ [flagColumn]: true })
              .eq("id", booking.id);
            results.sent_reminders++;

            // 3.2: Also queue an outbound AI voice reminder call
            try {
              await supabase.from("outbound_call_queue").insert({
                tenant_id: tenantId,
                customer_phone: phone,
                call_purpose: "reminder",
                scheduled_at: new Date(new Date(booking.start_at).getTime() - 2 * 60 * 60 * 1000).toISOString(), // 2 hours before appointment
                context_json: {
                  customer_name: lead?.full_name || "",
                  service_name: (booking.services as any)?.name || "your appointment",
                  appointment_time: startTime,
                  appointment_date: startDate,
                  booking_id: booking.id,
                },
                max_attempts: 2,
              });
            } catch (queueErr) {
              console.warn(`[cron-appointment-reminders] Failed to queue voice reminder:`, queueErr);
            }
          } else if (smsResult.skipped) {
            results.skipped_sms++;
          } else {
            console.error(`[cron-appointment-reminders] SMS failed for ${booking.id}:`, smsResult.error);
            results.errors++;
          }
        } catch (err) {
          console.error(`[cron-appointment-reminders] Error for ${booking.id}:`, err);
          results.errors++;
        }
      }
    }

    console.log(`[cron-appointment-reminders] Done:`, results);
    return new Response(JSON.stringify(results));
  } catch (error) {
    console.error("[cron-appointment-reminders] Fatal error:", error);
    return new Response(JSON.stringify({ error: String(error) }), { status: 500 });
  }
});

/**
 * cron-calendar-sync: Periodic sync of all active calendar connections
 * 
 * Called by pg_cron every 5 minutes to ensure calendar data stays fresh
 * and prevents double-booking.
 */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

serve(async (req: Request) => {
  // This function is called by pg_cron, no CORS needed
  try {
    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

    // Get all active calendar connections that need syncing
    const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000).toISOString();
    
    const { data: connections, error: connError } = await supabase
      .from("calendar_connections")
      .select("id, tenant_id, provider, last_sync_at")
      .eq("status", "connected")
      .or(`last_sync_at.is.null,last_sync_at.lt.${fiveMinutesAgo}`);

    if (connError) {
      console.error("[cron-calendar-sync] Error fetching connections:", connError);
      return new Response(JSON.stringify({ error: connError.message }), { status: 500 });
    }

    console.log(`[cron-calendar-sync] Found ${connections?.length || 0} connections to sync`);

    if (!connections || connections.length === 0) {
      return new Response(JSON.stringify({ message: "No connections need syncing", synced: 0 }));
    }

    // Sync each connection
    const results: { connection_id: string; success: boolean; error?: string }[] = [];

    for (const conn of connections) {
      try {
        // Call sync-availability for each connection
        const syncResponse = await fetch(`${SUPABASE_URL}/functions/v1/sync-availability`, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`,
          },
          body: JSON.stringify({
            connection_id: conn.id,
            days: 30,
            // Pass tenant context for the sync function
            _cron_tenant_id: conn.tenant_id,
          }),
        });

        if (syncResponse.ok) {
          const syncData = await syncResponse.json();
          console.log(`[cron-calendar-sync] Synced ${conn.id}: ${syncData.synced_count || 0} events`);
          results.push({ connection_id: conn.id, success: true });
        } else {
          const errorText = await syncResponse.text();
          console.error(`[cron-calendar-sync] Failed to sync ${conn.id}:`, errorText);
          results.push({ connection_id: conn.id, success: false, error: errorText });
        }
      } catch (error) {
        console.error(`[cron-calendar-sync] Error syncing ${conn.id}:`, error);
        results.push({ 
          connection_id: conn.id, 
          success: false, 
          error: error instanceof Error ? error.message : "Unknown error" 
        });
      }
    }

    const successCount = results.filter(r => r.success).length;
    console.log(`[cron-calendar-sync] Complete: ${successCount}/${results.length} successful`);

    return new Response(
      JSON.stringify({
        message: `Synced ${successCount}/${results.length} connections`,
        results,
      }),
      { headers: { "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("[cron-calendar-sync] Error:", error);
    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Unknown error" }),
      { status: 500 }
    );
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { serviceClient } from "../_shared/tenant.ts";

const corsHeaders = {
