    let tenantValidated = false;
    if (SUPABASE_URL && SUPABASE_SERVICE_ROLE_KEY) {
      const supabaseForValidation = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

      try {
        const { data: tenant, error } = await supabaseForValidation
          .from("tenants")
          .select("id, name")
          .eq("id", tenantId)
          .maybeSingle();

        if (error || !tenant) {
          console.error(`[elevenlabs-token] Invalid tenantId: ${tenantId}`);
          return new Response(
            JSON.stringify({
              error: "Invalid tenant_id - tenant not found",
              _debug: {
                endpoint: "elevenlabs-conversation-token",
                tenant_id: tenantId,
              },
            }),
            { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
          );
        }

        tenantValidated = true;
        console.log(`[elevenlabs-token] Validated tenant: ${tenant.name} (${tenantId})`);

        // Log tenant resolution for browser tests (HIPAA-safe)
        await supabaseForValidation.from("ai_event_logs").insert({
          tenant_id: tenantId,
          stage: "voice_tenant_resolved",
          event_data: {
            tenant_id: tenantId,
            tenant_name: tenant.name,
            source: resolutionSource,
            has_location_id: !!locationId,
            channel: "browser_test",
            connection_type: connectionType,
          },
        });
      } catch (validationError) {
        console.error("[elevenlabs-token] Tenant validation failed:", validationError);
        return new Response(
          JSON.stringify({
            error: "Tenant validation failed",
            _debug: { endpoint: "elevenlabs-conversation-token" },
          }),
          { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
    }

    // Initialize dynamic variables with safe defaults (all strings for ElevenLabs)
    let dynamicVariables: Record<string, string | number | boolean> = {
      business_name: "our business",
      businessname: "our business", // Alias for ElevenLabs compatibility
      business_mode: "general",
      enabled_modules: "",
      hipaa_mode: "false",
      timezone: "America/New_York",
      caller_phone: "browser_test",
      customer_id: "",
      hours_today: "Hours not available",
      calendar_connected: "false",
      booking_link: "",
      service_summary: "",
      services_pricing: "No services configured yet.",
      menu_summary: "",
      policies_summary: "",
      faqs_summary: "",
      greeting_script: "",
      fallback_script: "",
      tone: "friendly",
      intent_rules_summary: "",
      memory_hints_summary: "",
      memory_enabled: "false",
      tenant_id: "",
      location_id: "",
      // Speech-ready summaries (empty when not available - never invent)
      location_summary: "",
      service_area_summary: "",
      out_of_area_message: "",
      business_address: "",
      // Debug routing vars (spoken only when caller says "debug routing")
      debug_tenant_id: tenantId || "",
      debug_tenant_source: resolutionSource,
      debug_tenant_endpoint: "elevenlabs-conversation-token",
      debug_tenant_field: tenantId ? "tenantId" : "none",
      // Contract meta fields (for deploy verification)
      business_brain_json_compact: "",
      business_brain_json_hash: "",
      business_brain_json_truncated: "false",
      context_contract_version: "v1",
      dynamic_variables_keys: getAllVariableKeys().join(","),
    };

    // If tenantId provided, build FULL business context using canonical builder
    let systemPrompt = "";
    let precomputedSlots: string[] = [];
    
    if (tenantId && SUPABASE_URL && SUPABASE_SERVICE_ROLE_KEY) {
      try {
        const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
        const sessionId = `browser_test_${Date.now()}`;

        console.log(`Building full business context for browser test: tenant=${tenantId}, location=${locationId}`);

        // Use the SAME canonical builder that twilio-inbound uses
        const { context, systemPrompt: prompt } = await buildBusinessContext(supabase, {
          tenantId,
          locationId,
          customerId: null,
          channel: "browser_test",
          sessionId,
          callerPhone: null,
          includeIntelligence: true,
        });

        systemPrompt = prompt;

        // Store snapshot for debugging (viewable at /debug/ai-context)
        await storeContextSnapshot(supabase, context);

        // Build flattened dynamic variables using shared helper
        dynamicVariables = buildDynamicVariables(context, "browser_test", null);

        // Re-add debug routing vars after buildDynamicVariables overwrites
        dynamicVariables.debug_tenant_id = tenantId || "";
        dynamicVariables.debug_tenant_source = resolutionSource;
        dynamicVariables.debug_tenant_endpoint = "elevenlabs-conversation-token";
        dynamicVariables.debug_tenant_field = "tenantId";

        // Precompute tomorrow's slots for strict enforcement
        const tomorrow = new Date();
        tomorrow.setDate(tomorrow.getDate() + 1);
        const tomorrowStr = tomorrow.toISOString().split("T")[0];
        
        const { data: tenantHours } = await supabase
          .from("tenants")
          .select("hours_json")
          .eq("id", tenantId)
          .single();
        
        const { data: slots } = await supabase.rpc("fn_compute_available_slots", {
          _tenant_id: tenantId,
          _start_date: tomorrowStr,
          _end_date: tomorrowStr,
          _duration_minutes: 60,
          _buffer_minutes: 15,
          _business_hours: tenantHours?.hours_json || null,
        });
        
        if (slots && Array.isArray(slots)) {
          precomputedSlots = slots.slice(0, 6).map((s: { slot_time_local: string }) => s.slot_time_local);
        }
        
        // Create ai_call_sessions record for browser test calls
        // The webhook's fallback (match by tenant_id + caller_phone where elevenlabs_conversation_id IS NULL)
        // will find this record and link it when the call completes.
        try {
          const { error: sessionError } = await supabase
            .from("ai_call_sessions")
            .insert({
              tenant_id: tenantId,
              caller_phone: "browser_test",
              call_direction: "inbound",
              started_at: new Date().toISOString(),
              context_json: {
                channel: "browser_test",
                session_id: sessionId,
                business_mode: context.tenant.business_mode,
              },
            });
          if (sessionError) {
            console.warn("[elevenlabs-token] Failed to create browser test session (non-fatal):", sessionError.message);
          } else {
            console.log("[elevenlabs-token] Created ai_call_session for browser test");
          }
        } catch (sessionInsertError) {
          console.warn("[elevenlabs-token] Session insert error (non-fatal):", sessionInsertError);
        }

        // Log comprehensive context summary for debugging
        console.log("Browser test context built successfully:", {
          tenant_id: tenantId,
          business_name: context.tenant.business_name,
          business_mode: context.tenant.business_mode,
          hours_today: context.tenant.hours_today,
          services_count: context.offerings.services.length,
          precomputed_slots: precomputedSlots.length,
          missing_sections: context._meta.missing_sections,
        });
      } catch (dbError) {
        console.error("Error building business context for browser test:", dbError);
        // Continue with defaults if context build fails
      }
    } else {
      console.log("No tenantId provided for browser test - using minimal defaults");
    }

    // ===== RESOLVE MODE-SPECIFIC AGENT ID =====
    const businessMode = String(dynamicVariables.business_mode || "general");
    const { agentId, source: agentSource } = getAgentIdForMode(businessMode);
    
    if (!agentId) {
      console.error(`No ElevenLabs agent configured for mode: ${businessMode}`);
      return new Response(
        JSON.stringify({ 
          error: `No agent configured for business mode: ${businessMode}`,
          _debug: { business_mode: businessMode, source: agentSource }
        }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    console.log(`Using ElevenLabs agent: ${agentId.slice(0, 12)}... (source: ${agentSource}, mode: ${businessMode})`);

    const DEPLOYED_VERSION = "2026-02-03T12:00:00Z";

    // Log deployment version for verification
    console.log(`✅ ELEV_TOKEN_VERSION=${DEPLOYED_VERSION} | MODE=${connectionType} | VARS=${Object.keys(dynamicVariables).length} | AGENT_SOURCE=${agentSource}`);

    // DUAL PATH: WebRTC (default) or WebSocket
    if (connectionType === "webrtc") {
      // WebRTC PATH: fetch a short-lived conversation token.
      // IMPORTANT: Do NOT POST to the WebSocket conversation endpoint.
      console.log("Getting WebRTC conversation token for agent:", {
        agent_id: agentId.slice(0, 12) + "...",
        tenantId,
        businessMode,
        agentSource,
        flow: "webrtc-token",
      });

      const tokenResponse = await fetch(
        `https://api.elevenlabs.io/v1/convai/conversation/token?agent_id=${agentId}`,
        {
          method: "GET",
          headers: {
            "xi-api-key": ELEVENLABS_API_KEY,
          },
        }
      );

      if (!tokenResponse.ok) {
        const errorText = await tokenResponse.text();
        console.error("ElevenLabs conversation token error:", tokenResponse.status, errorText);
        return new Response(
          JSON.stringify({ error: "Failed to get conversation token", details: errorText }),
          { status: tokenResponse.status, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      const tokenData = await tokenResponse.json().catch(() => ({} as any));
      const token = (tokenData as any)?.token as string | undefined;

      if (!token) {
        console.error("ElevenLabs conversation token missing in response", tokenData);
        return new Response(
          JSON.stringify({ error: "Conversation token missing from ElevenLabs response" }),
          { status: 502, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      console.log("WebRTC token received:", { tokenPrefix: token.slice(0, 12) });

      // Convert all values to strings for ElevenLabs compatibility
      const stringOnlyVars = toStringOnlyVars(dynamicVariables);

      return new Response(
        JSON.stringify({
          token,
          dynamicVariables: stringOnlyVars,
          precomputedSlots: precomputedSlots,
          deployedVersion: DEPLOYED_VERSION,
          connectionType: "webrtc",
          _debug: {
            deployedVersion: DEPLOYED_VERSION,
            flow: "webrtc-token",
            agentId: agentId.slice(0, 12) + "...",
            agentSource,
            businessMode,
            tokenPrefix: token.slice(0, 12),
            denoStdVersion: "0.191.0",
            dynamicVarsCount: Object.keys(stringOnlyVars).length,
            hasContractFields: Boolean(stringOnlyVars.dynamic_variables_keys && stringOnlyVars.business_brain_json_hash),
          },
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    } else {
      // WEBSOCKET PATH: Get signed URL directly (original flow)
      console.log("Getting WebSocket signed URL directly for agent:", {
        agent_id: agentId.slice(0, 12) + "...",
        tenantId,
        businessMode,
        agentSource,
        flow: "websocket-signed-url",
      });

      const signedUrlResponse = await fetch(
        `https://api.elevenlabs.io/v1/convai/conversation/get-signed-url?agent_id=${agentId}`,
        {
          method: "GET",
          headers: {
            "xi-api-key": ELEVENLABS_API_KEY,
          },
        }
      );

      if (!signedUrlResponse.ok) {
        const errorText = await signedUrlResponse.text();
        console.error("ElevenLabs signed URL error:", signedUrlResponse.status, errorText);
        return new Response(
          JSON.stringify({ error: "Failed to get signed URL", details: errorText }),
          { status: signedUrlResponse.status, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      const signedUrlData = await signedUrlResponse.json();

      // Convert all values to strings for ElevenLabs compatibility
      const stringOnlyVarsWs = toStringOnlyVars(dynamicVariables);

      return new Response(
        JSON.stringify({
          signedUrl: signedUrlData.signed_url,
          dynamicVariables: stringOnlyVarsWs,
          precomputedSlots: precomputedSlots,
          deployedVersion: DEPLOYED_VERSION,
          connectionType: "websocket",
          _debug: {
            deployedVersion: DEPLOYED_VERSION,
            flow: "websocket-signed-url",
            agentId: agentId.slice(0, 12) + "...",
            agentSource,
            businessMode,
            denoStdVersion: "0.191.0",
            dynamicVarsCount: Object.keys(stringOnlyVarsWs).length,
            hasContractFields: Boolean(stringOnlyVarsWs.dynamic_variables_keys && stringOnlyVarsWs.business_brain_json_hash),
          },
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }
  } catch (error) {
    console.error("Error in elevenlabs-conversation-token:", error);
    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Unknown error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

/**
 * elevenlabs-create-dispatch-job: ElevenLabs tool endpoint for creating dispatch jobs
 * during voice calls.
 * 
 * Called by ElevenLabs agent when it has collected enough dispatch intake info:
 * - customer_name, customer_phone
 * - pickup_address, dropoff_address (optional)
 * - vehicle_info, service_type, urgency
 * - notes
 * 
 * ENHANCED: Now calculates and stores distance & pricing data by calling check_service_area
 */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { sanitizeCustomerName, isPlaceholderName, shouldUpdateCustomerName } from "../_shared/sanitizeName.ts";
import { normalizePhoneE164 } from "../_shared/phoneNormalize.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface CreateDispatchJobRequest {
  // Required
  pickup_address: string;
  service_type: string;
  // Dispatch mode specific
  vehicle_info?: string;
  dropoff_address?: string;
  drivable?: boolean | string;
  // Common
  customer_name?: string;
  customer_phone?: string;
  urgency?: "emergency" | "urgent" | "standard" | "same_day" | "scheduled";
  notes?: string;
  // ElevenLabs context
  tenant_id?: string;
  conversation_id?: string;
}

interface CreateDispatchJobResponse {
  success: boolean;
  job_number?: string;
  dispatch_id?: string;
  message: string;
  error?: string;
}

interface ServiceAreaResponse {
  in_area: boolean;
  distance_miles: number | null;
  tow_distance_miles: number | null;
  eta_minutes: number | null;
  eta_range: string;
  service_tier: string;
  pricing_note: string;
  distance_basis_used: string;
  pickup_lat?: number | null;
  pickup_lng?: number | null;
  dropoff_lat?: number | null;
  dropoff_lng?: number | null;
  price_breakdown: {
    base_price?: number;
    per_mile_rate?: number;
    distance_charge?: number;
    vehicle_modifier?: number;
    urgency_modifier?: number;
    total_estimate?: number;
    total?: number;
    description?: string;
  } | null;
}

// Use shared phone normalization
const normalizePhone = normalizePhoneE164;

// Generate job number
function generateJobNumber(): string {
  const now = new Date();
  const dateStr = now.toISOString().slice(2, 10).replace(/-/g, "");
  const random = Math.random().toString(36).substring(2, 6).toUpperCase();
  return `DSP-${dateStr}-${random}`;
}

// Map urgency to priority
function urgencyToPriority(urgency?: string): "low" | "normal" | "high" | "urgent" {
  switch (urgency) {
    case "emergency": return "urgent";
    case "urgent": return "high";
    case "same_day": 
    case "standard": return "normal";
    case "scheduled": return "low";
    default: return "normal";
  }
}

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
  const supabase = createClient(supabaseUrl, serviceKey);

  try {
    const body: CreateDispatchJobRequest = await req.json();
    console.log("[elevenlabs-create-dispatch-job] Request:", JSON.stringify({
      ...body,
      customer_phone: body.customer_phone ? "[REDACTED]" : undefined,
    }));

    const {
      pickup_address,
      service_type,
      vehicle_info,
      dropoff_address,
      drivable,
      customer_name,
      customer_phone,
      urgency,
      notes,
      tenant_id,
      conversation_id
    } = body;

    // Validate required fields
    if (!pickup_address) {
      console.error("[elevenlabs-create-dispatch-job] Missing pickup_address");
      return new Response(
        JSON.stringify({
          success: false,
          message: "I need your pickup location to send help. What's the address or cross streets where you need us?",
          error: "pickup_address is required"
        } as CreateDispatchJobResponse),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    if (!service_type) {
      console.error("[elevenlabs-create-dispatch-job] Missing service_type");
      return new Response(
        JSON.stringify({
          success: false,
          message: "What type of service do you need? Tow, jumpstart, lockout, tire change, or something else?",
          error: "service_type is required"
        } as CreateDispatchJobResponse),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Resolve tenant_id
    let resolvedTenantId: string | null = tenant_id || null;
    let sessionId: string | null = null;
    let sessionCallerPhone: string | null = null;
    
    // Try to get tenant from conversation_id if not provided
    if (!resolvedTenantId && conversation_id) {
      const { data: session } = await supabase
        .from("ai_call_sessions")
        .select("tenant_id, id, caller_phone")
        .eq("elevenlabs_conversation_id", conversation_id)
        .maybeSingle();
      
      resolvedTenantId = session?.tenant_id || null;
      sessionId = session?.id || null;
      sessionCallerPhone = session?.caller_phone || null;
      console.log(`[elevenlabs-create-dispatch-job] Resolved tenant from conversation: ${resolvedTenantId?.substring(0, 8)}...`);
    }

    // Get session ID if we have tenant but not session
    if (resolvedTenantId && !sessionId && conversation_id) {
      const { data: session } = await supabase
        .from("ai_call_sessions")
        .select("id")
        .eq("tenant_id", resolvedTenantId)
        .eq("elevenlabs_conversation_id", conversation_id)
        .maybeSingle();
      sessionId = session?.id || null;
    }

    // Fallback: try to get from most recent active session for this tenant
    if (resolvedTenantId && !sessionId) {
      const { data: recentSession } = await supabase
        .from("ai_call_sessions")
        .select("id")
        .eq("tenant_id", resolvedTenantId)
        .is("ended_at", null)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      
      sessionId = recentSession?.id || null;
    }

    // P0-2: Removed cross-tenant fallback that queried most recent session
    // across ALL tenants. This was a tenant isolation risk.

    if (!resolvedTenantId) {
      console.error("[elevenlabs-create-dispatch-job] Could not resolve tenant_id");
      return new Response(
        JSON.stringify({
          success: false,
          message: "I'm having trouble connecting to the dispatch system. Let me take your information and have someone call you right back.",
          error: "No active voice session found - could not determine tenant"
        } as CreateDispatchJobResponse),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Module gating: never create entities for disabled modules
    const { data: tenantRow } = await supabase
      .from("tenants")
      .select("enabled_modules")
      .eq("id", resolvedTenantId)
      .maybeSingle();

    const enabledModules: string[] = tenantRow?.enabled_modules || [];
    if (!enabledModules.includes("dispatch_queue")) {
      console.warn(`[elevenlabs-create-dispatch-job] dispatch_queue not enabled for tenant ${resolvedTenantId.substring(0, 8)}...`);
      return new Response(
        JSON.stringify({
          success: false,
          message: "I'm sorry, dispatch isn't available right now. Let me take your info and have someone call you back to help.",
          error: "dispatch_queue module not enabled for this tenant"
        } as CreateDispatchJobResponse),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Normalize phone (prefer caller_id from the active session if the tool didn't send customer_phone)
    const effectivePhoneRaw = (customer_phone || sessionCallerPhone || "").trim();
    const phoneE164 = normalizePhone(effectivePhoneRaw);

    // Sanitize customer name - detect and normalize placeholders
    const rawCustomerName = (customer_name || "").trim();
    const sanitizedName = sanitizeCustomerName(rawCustomerName);

    // Log if placeholder name was detected
    if (isPlaceholderName(rawCustomerName)) {
      console.log(`[elevenlabs-create-dispatch-job] Placeholder name detected: "${rawCustomerName}" - storing as "Unknown"`);
      // Log to ai_event_logs for tracking
      try {
        await supabase.from("ai_event_logs").insert({
          tenant_id: resolvedTenantId,
          session_id: sessionId,
          stage: "dispatch_identity_missing",
          event_data: {
            tool: "elevenlabs-create-dispatch-job",
            placeholder_detected: rawCustomerName || null,
            has_caller_phone: !!phoneE164,
          },
        });
      } catch (e) {
        // Don't block on logging errors
      }
    }

    // Find or create customer
    let customerId: string | null = null;
    if (phoneE164) {
      try {
        const { data: existingCustomer } = await supabase
          .from("customers")
          .select("id, full_name")
          .eq("tenant_id", resolvedTenantId)
          .eq("phone_e164", phoneE164)
          .maybeSingle();

        if (existingCustomer) {
          customerId = existingCustomer.id;
          // Only update name if new name is better than existing
          if (shouldUpdateCustomerName(existingCustomer.full_name, rawCustomerName)) {
            await supabase
              .from("customers")
              .update({ full_name: sanitizedName, updated_at: new Date().toISOString() })
              .eq("id", customerId);
          }
        } else {
          // Create new customer (name is sanitized)
          const { data: newCustomer, error: newCustomerError } = await supabase
            .from("customers")
            .insert({
              tenant_id: resolvedTenantId,
              full_name: sanitizedName,
              phone_e164: phoneE164,
              phone_raw: customer_phone || null,
              source: "voice_ai"
            })
            .select("id")
            .single();

          if (newCustomerError) {
            console.error("[elevenlabs-create-dispatch-job] Failed to create customer:", newCustomerError);
          } else if (newCustomer) {
            customerId = newCustomer.id;
          }
        }
      } catch (e) {
        console.error("[elevenlabs-create-dispatch-job] Customer lookup/create error:", e);
        // Continue without customer record
      }
    }

    if (!customerId) {
      console.error("[elevenlabs-create-dispatch-job] Missing customerId (cannot create dispatch job)");
      return new Response(
        JSON.stringify({
          success: false,
          message: "I can still get this dispatched — what's the best callback number for you?",
          error: "Unable to resolve or create customer"
        } as CreateDispatchJobResponse),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Generate job number
    const jobNumber = generateJobNumber();

    // Build description from vehicle_info, service_type, and drivable status
    const descriptionParts: string[] = [];
    if (service_type) descriptionParts.push(`Service: ${service_type}`);
    if (vehicle_info) descriptionParts.push(`Vehicle: ${vehicle_info}`);
    if (drivable !== undefined && drivable !== null) {
      const isDrivable = drivable === true || drivable === "true" || drivable === "yes";
      descriptionParts.push(`Drivable: ${isDrivable ? "Yes" : "No"}`);
    }
    const description = descriptionParts.join(". ") || null;

    // === NEW: Calculate distance & pricing by calling check_service_area ===
    let dispatchDistanceMiles: number | null = null;
    let towDistanceMiles: number | null = null;
    let totalDistanceMiles: number | null = null;
    let serviceTier: string | null = null;
    let pricingNote: string | null = null;
    let priceBreakdown: Record<string, unknown> | null = null;
    let etaRange: string | null = null;
    let priceCents: number | null = null;
    let pickupLat: number | null = null;
    let pickupLng: number | null = null;
    let dropoffLat: number | null = null;
    let dropoffLng: number | null = null;

    try {
      const checkServiceAreaUrl = `${supabaseUrl}/functions/v1/elevenlabs-check-service-area`;
      const checkResponse = await fetch(checkServiceAreaUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${serviceKey}`,
        },
        body: JSON.stringify({
          tenant_id: resolvedTenantId,
          address: pickup_address,
          dropoff_address: dropoff_address || "",
          vehicle_type: vehicle_info || "",
        }),
      });

      if (checkResponse.ok) {
        const areaData: ServiceAreaResponse = await checkResponse.json();

        dispatchDistanceMiles = areaData.distance_miles;
        towDistanceMiles = areaData.tow_distance_miles;
        totalDistanceMiles = (dispatchDistanceMiles || 0) + (towDistanceMiles || 0);
        serviceTier = areaData.service_tier || null;
        pricingNote = areaData.pricing_note || null;
        etaRange = areaData.eta_range || null;

        // Extract coordinates if available
        pickupLat = areaData.pickup_lat ?? null;
        pickupLng = areaData.pickup_lng ?? null;
        dropoffLat = areaData.dropoff_lat ?? null;
        dropoffLng = areaData.dropoff_lng ?? null;

        // Format price_breakdown for storage and extract price_cents
        if (areaData.price_breakdown) {
          const pb = areaData.price_breakdown;
          const totalEstimate = pb.total_estimate || pb.total || null;
          priceBreakdown = {
            base_price: pb.base_price || null,
            per_mile_rate: pb.per_mile_rate || null,
            distance_charge: pb.distance_charge || null,
            vehicle_modifier: pb.vehicle_modifier || null,
            urgency_modifier: pb.urgency_modifier || null,
            total: totalEstimate,
            description: pb.description || null,
          };
          // Convert dollars to cents for price_cents column (revenue attribution reads this)
          if (totalEstimate && typeof totalEstimate === "number" && totalEstimate > 0) {
            priceCents = Math.round(totalEstimate * 100);
          }
        }

        console.log(`[elevenlabs-create-dispatch-job] Distance/pricing: dispatch=${dispatchDistanceMiles?.toFixed(1) || 'null'}mi, tow=${towDistanceMiles?.toFixed(1) || 'null'}mi, tier=${serviceTier}, price_cents=${priceCents || 'null'}, pricing="${pricingNote?.substring(0, 50) || 'null'}..."`);
      } else {
        console.warn("[elevenlabs-create-dispatch-job] check_service_area returned non-OK status:", checkResponse.status);
      }
    } catch (e) {
      console.warn("[elevenlabs-create-dispatch-job] Failed to get distance/pricing data:", e);
      // Continue without distance data - job can still be created
    }

    // Create dispatch job with distance & pricing data
    const { data: dispatch, error: dispatchError } = await supabase
      .from("dispatch_jobs")
      .insert({
        tenant_id: resolvedTenantId,
        job_number: jobNumber,
        customer_id: customerId,
        customer_name: sanitizedName,
        customer_phone: phoneE164 || customer_phone || null,
        pickup_address: pickup_address,
        pickup_lat: pickupLat,
        pickup_lng: pickupLng,
        dropoff_address: dropoff_address || null,
        dropoff_lat: dropoffLat,
        dropoff_lng: dropoffLng,
        job_type: service_type || "Tow",
        priority: urgencyToPriority(urgency),
        status: "pending",
        description: description,
        notes: notes || null,
        session_id: sessionId,
        requested_at: new Date().toISOString(),
        // Revenue attribution reads price_cents
        price_cents: priceCents,
        // Distance & pricing fields
        dispatch_distance_miles: dispatchDistanceMiles,
        tow_distance_miles: towDistanceMiles,
        total_distance_miles: totalDistanceMiles,
        service_tier: serviceTier,
        pricing_note: pricingNote,
        price_breakdown: priceBreakdown,
      })
      .select("id, job_number")
      .single();

    if (dispatchError) {
      console.error("[elevenlabs-create-dispatch-job] Error creating dispatch:", dispatchError);
      return new Response(
        JSON.stringify({
          success: false,
          message: "I'm having trouble submitting the dispatch. Let me take your information and have our dispatcher call you right back to confirm.",
          error: dispatchError.message
        } as CreateDispatchJobResponse),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Trigger dispatch handoff to notify the business
    try {
      await fetch(`${supabaseUrl}/functions/v1/dispatch-handoff`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${serviceKey}`,
        },
        body: JSON.stringify({
          dispatch_id: dispatch.id,
          tenant_id: resolvedTenantId,
        }),
      });
    } catch (e) {
      console.error("[elevenlabs-create-dispatch-job] Failed to trigger handoff:", e);
      // Don't fail the whole request if handoff fails
    }

    // Update session with dispatch outcome
    if (sessionId) {
      try {
        await supabase
          .from("ai_call_sessions")
          .update({
            outcome: "dispatch",
            extracted_payload: {
              dispatch_id: dispatch.id,
              job_number: dispatch.job_number,
              customer_name,
              customer_phone: phoneE164,
              pickup_address,
              dropoff_address,
              vehicle_info,
              service_type,
              urgency,
              notes,
              // Include pricing data in payload
              dispatch_distance_miles: dispatchDistanceMiles,
              tow_distance_miles: towDistanceMiles,
              service_tier: serviceTier,
              pricing_note: pricingNote,
            }
          })
          .eq("id", sessionId);
      } catch (e) {
        console.error("[elevenlabs-create-dispatch-job] Failed to update session:", e);
      }
    }

    console.log(`[elevenlabs-create-dispatch-job] Created dispatch ${dispatch.job_number} for tenant ${resolvedTenantId.substring(0, 8)}... with pricing: ${pricingNote?.substring(0, 50) || 'none'}`);

    // Build realistic confirmation message - NOT "driver is on the way"
    // The job is PENDING assignment by a dispatcher
    const etaMessage = etaRange ? ` We'll have someone there in about ${etaRange}.` : "";
    
    const response: CreateDispatchJobResponse = {
      success: true,
      job_number: dispatch.job_number,
      dispatch_id: dispatch.id,
      message: `Got it — we've got you in the system and our dispatch team is assigning a driver now.${etaMessage} You'll get a call or text when they're on the way.`
    };

    return new Response(JSON.stringify(response), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" }
    });

  } catch (error) {
    console.error("[elevenlabs-create-dispatch-job] Error:", error);
    return new Response(
      JSON.stringify({
        success: false,
        message: "I apologize, I'm having some technical difficulties. Let me take your number and have dispatch call you right back.",
        error: error instanceof Error ? error.message : "Unknown error"
      } as CreateDispatchJobResponse),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

/**
 * elevenlabs-initiate-referral-transfer: Execute a referral transfer.
 *
 * Transfers the live Twilio call from Business A's AI agent to Business B's AI agent.
 * This is the direct agent-switch approach:
 *  1. Registers a NEW ElevenLabs conversation with the target tenant's agent
 *  2. Injects referral context into the target agent's dynamic variables
 *  3. Switches the live Twilio call to the new ElevenLabs stream via REST API
 *
 * Same proven pattern as elevenlabs-transfer-call but targeting another AI agent
 * instead of a human phone number.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { getAgentIdForMode } from "../_shared/agentResolver.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface TransferRequest {
  target_tenant_id?: string;
  transfer_id?: string;
  service_needed?: string;
  caller_name?: string;
  caller_phone?: string;
  caller_location?: string;
  urgency?: string;
  referral_reason?: string;
  notes?: string;
  tenant_id?: string;
  twilio_call_sid?: string;
  conversation_id?: string;
  params?: {
    target_tenant_id?: string;
    transfer_id?: string;
    service_needed?: string;
    caller_name?: string;
    caller_phone?: string;
    caller_location?: string;
    urgency?: string;
    referral_reason?: string;
    notes?: string;
    tenant_id?: string;
    twilio_call_sid?: string;
    conversation_id?: string;
  };
}

const FALLBACK_MSG =
  "I wasn't able to connect you right now. Can I take your info and have someone call you back?";

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const body: TransferRequest = await req.json();
    console.log("[referral-transfer] Request:", JSON.stringify(body));

    // Handle nested params
    const targetTenantId = body.target_tenant_id || body.params?.target_tenant_id || "";
    const transferId = body.transfer_id || body.params?.transfer_id || "";
    const serviceNeeded = body.service_needed || body.params?.service_needed || "";
    const callerName = body.caller_name || body.params?.caller_name || "";
    const callerPhone = body.caller_phone || body.params?.caller_phone || "";
    const callerLocation = body.caller_location || body.params?.caller_location || "";
    const urgency = body.urgency || body.params?.urgency || "normal";
    const referralReason = body.referral_reason || body.params?.referral_reason || "";
    const notes = body.notes || body.params?.notes || "";
    const sourceTenantId = body.tenant_id || body.params?.tenant_id || "";
    const directCallSid = body.twilio_call_sid || body.params?.twilio_call_sid || "";
    const conversationId = body.conversation_id || body.params?.conversation_id || "";

    if (!targetTenantId) {
      return respond(false, FALLBACK_MSG);
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const twilioAccountSid = Deno.env.get("TWILIO_ACCOUNT_SID");
    const twilioAuthToken = Deno.env.get("TWILIO_AUTH_TOKEN");
    const elevenLabsApiKey = Deno.env.get("ELEVENLABS_API_KEY");
    const supabase = createClient(supabaseUrl, serviceKey);

    if (!twilioAccountSid || !twilioAuthToken || !elevenLabsApiKey) {
      console.error("[referral-transfer] Missing Twilio or ElevenLabs credentials");
      return respond(false, FALLBACK_MSG);
    }

    // ── Resolve twilio_call_sid from session ──
    let callSid = directCallSid;
    let sourceSessionId: string | null = null;

    if (!callSid && conversationId) {
      const { data: session } = await supabase
        .from("ai_call_sessions")
        .select("id, twilio_call_sid")
        .eq("elevenlabs_conversation_id", conversationId)
        .maybeSingle();

      if (session?.twilio_call_sid) {
        callSid = session.twilio_call_sid;
        sourceSessionId = session.id;
      }
    }

    if (callSid && !sourceSessionId) {
      const { data: session } = await supabase
        .from("ai_call_sessions")
        .select("id")
        .eq("twilio_call_sid", callSid)
        .maybeSingle();
      sourceSessionId = session?.id || null;
    }

    if (!callSid || callSid.startsWith("missing_")) {
      console.error(`[referral-transfer] No valid twilio_call_sid (got: ${callSid})`);
      return respond(false, FALLBACK_MSG);
    }

    // ── Chain prevention: check referral_depth ──
    if (transferId) {
      const { data: existingTransfer } = await supabase
        .from("referral_transfers")
        .select("referral_depth")
        .eq("id", transferId)
        .maybeSingle();

      if (existingTransfer && (existingTransfer.referral_depth || 1) >= 2) {
        console.warn("[referral-transfer] Chain prevention: max depth reached");
        return respond(
          false,
          "I'm not able to transfer further. Can I take your info and have someone call you back?"
        );
      }
    }

    // Also check if this call already has a referral transfer (by session)
    if (sourceSessionId) {
      const { data: existingRef } = await supabase
        .from("ai_call_sessions")
        .select("is_referral_receiving")
        .eq("id", sourceSessionId)
        .maybeSingle();

      if (existingRef?.is_referral_receiving) {
        console.warn("[referral-transfer] Chain prevention: session is already a referral");
        return respond(
          false,
          "I'm not able to transfer further. Can I take your info and have someone call you back?"
        );
      }
    }

    // ── Fetch target tenant config ──
    const { data: targetTenant, error: targetErr } = await supabase
      .from("tenants")
      .select("id, business_name, business_mode, enabled_modules, capabilities_json, industry")
      .eq("id", targetTenantId)
      .single();

    if (targetErr || !targetTenant) {
      console.error("[referral-transfer] Target tenant not found:", targetTenantId);
      return respond(false, FALLBACK_MSG);
    }

    // ── Resolve target agent ID ──
    const internalSecret = Deno.env.get("CLOSELOOP_INTERNAL_SECRET");

    // Build target business context via internal call
    const contextRes = await fetch(`${supabaseUrl}/functions/v1/copilot-context`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-closeloop-secret": internalSecret || "",
      },
      body: JSON.stringify({
        tenant_id: targetTenantId,
        channel: "voice",
        caller_phone: callerPhone,
      }),
    });

    let dynamicVariables: Record<string, string | number | boolean> = {};
    let targetAgentId = "";

    if (contextRes.ok) {
      const contextData = await contextRes.json();
      dynamicVariables = contextData.dynamic_variables || {};
      targetAgentId = contextData.agent_id || "";
    }

    // Fallback: use mode-based env var resolution (same path as twilio-inbound)
    if (!targetAgentId) {
      const resolution = getAgentIdForMode(targetTenant.business_mode);
      targetAgentId = resolution.agentId || "";
    }

    if (!targetAgentId) {
      console.error("[referral-transfer] No agent_id for target tenant");
      return respond(false, FALLBACK_MSG);
    }

    // ── Inject referral context into dynamic variables ──
    // Look up source business name
    let sourceName = "another business";
    if (sourceTenantId) {
      const { data: srcTenant } = await supabase
        .from("tenants")
        .select("business_name")
        .eq("id", sourceTenantId)
        .single();
      sourceName = srcTenant?.business_name || "another business";
    }

    dynamicVariables.is_referral_transfer = "true";
    dynamicVariables.referral_caller_name = callerName || "";
    dynamicVariables.referral_caller_need = serviceNeeded || "";
    dynamicVariables.referral_caller_phone = callerPhone || "";
    dynamicVariables.referral_source_business = sourceName;
    dynamicVariables.referral_context =
      `Caller was speaking with ${sourceName}` +
      (serviceNeeded ? ` and needs ${serviceNeeded}` : "") +
      (callerLocation ? ` in ${callerLocation}` : "") +
      (callerName ? `. Their name is ${callerName}` : "") +
      ".";

    // ── Register new ElevenLabs conversation ──
    console.log(
      `[referral-transfer] Registering agent=${targetAgentId.slice(0, 8)}... ` +
        `for tenant=${targetTenantId.slice(0, 8)}...`
    );

    const registerRes = await fetch(
      "https://api.elevenlabs.io/v1/convai/twilio/register-call",
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "xi-api-key": elevenLabsApiKey,
        },
        body: JSON.stringify({
          agent_id: targetAgentId,
          dynamic_variables: dynamicVariables,
        }),
      }
    );

    if (!registerRes.ok) {
      const errText = await registerRes.text();
      console.error(
        `[referral-transfer] ElevenLabs register-call failed [${registerRes.status}]: ${errText}`
      );
      return respond(false, FALLBACK_MSG);
    }

    const registerData = await registerRes.json();
    // ElevenLabs returns TwiML with a <Stream> WebSocket URL
    // The response format has the conversation_id embedded in the stream URL
    const twiml = registerData.twiml || "";

    // Extract conversation_id from stream URL
    const convIdMatch = twiml.match(/conversation_id=([a-zA-Z0-9_-]+)/);
    const targetConversationId = convIdMatch?.[1] || "";

    console.log(
      `[referral-transfer] Got TwiML (${twiml.length} chars), ` +
        `conv_id=${targetConversationId || "unknown"}`
    );

    // ── Create target session ──
    const { data: targetSession } = await supabase
      .from("ai_call_sessions")
      .insert({
        tenant_id: targetTenantId,
        twilio_call_sid: callSid,
        elevenlabs_conversation_id: targetConversationId || null,
        started_at: new Date().toISOString(),
        is_referral_receiving: true,
        referral_transfer_id: transferId || null,
      })
      .select("id")
      .single();

    // ── Update source session ──
    if (sourceSessionId) {
      await supabase
        .from("ai_call_sessions")
        .update({
          outcome: "referral_transfer",
          referral_transfer_id: transferId || null,
        })
        .eq("id", sourceSessionId);
    }

    // ── Update referral_transfers record ──
    if (transferId) {
      await supabase
        .from("referral_transfers")
        .update({
          status: "transferring",
          target_session_id: targetSession?.id || null,
        })
        .eq("id", transferId);
    }

    // ── Switch the live Twilio call to the new agent ──
    // Prepend a brief pause to let the AI finish its farewell
    const switchTwiml = twiml.replace("<Response>", "<Response><Pause length=\"2\"/>");

    const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${twilioAccountSid}/Calls/${callSid}.json`;
    const authHeader = "Basic " + btoa(`${twilioAccountSid}:${twilioAuthToken}`);

    const updateParams = new URLSearchParams();
    updateParams.set("Twiml", switchTwiml);

    console.log(`[referral-transfer] Updating Twilio call ${callSid}`);

    const twilioRes = await fetch(twilioUrl, {
      method: "POST",
      headers: {
        Authorization: authHeader,
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: updateParams.toString(),
    });

    if (!twilioRes.ok) {
      const errText = await twilioRes.text();
      console.error(
        `[referral-transfer] Twilio update failed [${twilioRes.status}]: ${errText}`
      );

      // Update transfer status to failed
      if (transferId) {
        await supabase
          .from("referral_transfers")
          .update({
            status: "failed",
            failure_reason: `Twilio ${twilioRes.status}: ${errText.substring(0, 200)}`,
          })
          .eq("id", transferId);
      }

      return respond(false, FALLBACK_MSG);
    }

    // ── Success: update transfer status ──
    if (transferId) {
      await supabase
        .from("referral_transfers")
        .update({
          status: "completed",
          completed_at: new Date().toISOString(),
        })
        .eq("id", transferId);

      // Increment referrals_today for target
      await supabase.rpc("increment_referrals_today", {
        p_tenant_id: targetTenantId,
      }).catch((err: unknown) => {
        console.error("[referral-transfer] increment_referrals_today RPC failed:", err);
      });
    }

    console.log(
      `[referral-transfer] Successfully transferred call ${callSid} ` +
        `to ${targetTenant.business_name}`
    );

    return respond(
      true,
      `Connecting you to ${targetTenant.business_name} now. One moment please.`
    );
  } catch (error) {
    console.error("[referral-transfer] Error:", error);
    return respond(false, FALLBACK_MSG);
  }
});

function respond(success: boolean, message: string) {
  return new Response(
    JSON.stringify({ success, message }),
    { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
  );
}

/**
 * ElevenLabs Tool: Lookup Active Job
 *
 * Allows the voice AI to look up a customer's active job/vehicle status
 * during a call. Matches by phone (primary), name (fuzzy), job number (exact),
 * or vehicle description (title match).
 *
 * Returns a speech-ready status message the AI can read directly.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface LookupRequest {
  tenant_id: string;
  customer_phone?: string;
  customer_name?: string;
  job_number?: string;
  vehicle_description?: string;
  conversation_id?: string;
  params?: {
    tenant_id?: string;
    customer_phone?: string;
    customer_name?: string;
    job_number?: string;
    vehicle_description?: string;
  };
}

interface JobStatusResponse {
  found: boolean;
  job_id?: string;
  job_number?: string;
  status?: string;
  status_message: string;
  title?: string;
  services_total?: number;
  services_completed?: number;
  estimated_completion?: string;
  multiple_jobs?: boolean;
  job_count?: number;
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const startTime = Date.now();

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    const body: LookupRequest = await req.json();

    // Handle nested params from ElevenLabs
    const tenantId = body.tenant_id || body.params?.tenant_id || "";
    const customerPhone = body.customer_phone || body.params?.customer_phone || "";
    const customerName = body.customer_name || body.params?.customer_name || "";
    const jobNumber = body.job_number || body.params?.job_number || "";
    const vehicleDescription = body.vehicle_description || body.params?.vehicle_description || "";
    const conversationId = body.conversation_id || "";

    if (!tenantId) {
      return new Response(
        JSON.stringify({
          found: false,
          status_message: "I'm having trouble looking that up. Can I take your info and have someone call you back with an update?",
        }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Resolve caller phone from session if not provided directly
    let resolvedPhone = customerPhone;
    if (!resolvedPhone && conversationId) {
      const { data: session } = await supabase
        .from("ai_call_sessions")
        .select("caller_phone")
        .eq("elevenlabs_conversation_id", conversationId)
        .maybeSingle();
      if (session?.caller_phone) {
        resolvedPhone = session.caller_phone;
      }
    }

    console.log(`[lookup-active-job] Searching: tenant=${tenantId.slice(0, 8)}, phone=${resolvedPhone}, name=${customerName}, job#=${jobNumber}, vehicle=${vehicleDescription}`);

    // Strategy 1: Direct job number lookup (most precise)
    if (jobNumber) {
      const { data: job, error } = await supabase
        .from("active_jobs")
        .select("id, job_number, title, status, priority, notes, estimated_completion, actual_completion, is_active, job_service_items(id, title, status, sort_order)")
        .eq("tenant_id", tenantId)
        .eq("job_number", jobNumber)
        .maybeSingle();

      if (error) {
        console.error("[lookup-active-job] Job number query error:", error);
        throw error;
      }

      if (job) {
        const response = buildJobResponse(job);
        console.log(`[lookup-active-job] Found by job_number ${jobNumber} in ${Date.now() - startTime}ms`);
        return new Response(JSON.stringify(response), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      // Job number provided but not found
      return new Response(
        JSON.stringify({
          found: false,
          status_message: "I don't see a job with that number. Could you double-check it? Or I can look it up by your phone number or name.",
        } as JobStatusResponse),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Strategy 2: Phone-based lookup (primary for callers)
    if (resolvedPhone) {
      const normalizedPhone = resolvedPhone.replace(/\D/g, "").slice(-10);

      const { data: jobs, error } = await supabase
        .from("active_jobs")
        .select("id, job_number, title, status, priority, notes, estimated_completion, actual_completion, is_active, customer_name, customer_phone, job_service_items(id, title, status, sort_order)")
        .eq("tenant_id", tenantId)
        .ilike("customer_phone", `%${normalizedPhone}%`)
        .eq("is_active", true)
        .in("status", ["intake", "in_progress", "on_hold"])
        .order("created_at", { ascending: false })
        .limit(5);

      if (error) {
        console.error("[lookup-active-job] Phone query error:", error);
        throw error;
      }

      if (jobs && jobs.length > 0) {
        const response = buildJobResponse(jobs[0], jobs.length > 1 ? jobs.length : undefined);
        console.log(`[lookup-active-job] Found ${jobs.length} job(s) by phone in ${Date.now() - startTime}ms`);
        return new Response(JSON.stringify(response), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      // Also check recently completed jobs (last 48 hours)
      const { data: completedJobs } = await supabase
        .from("active_jobs")
        .select("id, job_number, title, status, actual_completion, customer_phone, job_service_items(id, title, status, sort_order)")
        .eq("tenant_id", tenantId)
        .ilike("customer_phone", `%${normalizedPhone}%`)
        .eq("status", "completed")
        .order("actual_completion", { ascending: false })
        .limit(1);

      if (completedJobs && completedJobs.length > 0) {
        const job = completedJobs[0];
        return new Response(
          JSON.stringify({
            found: true,
            job_id: job.id,
            job_number: job.job_number,
            status: "completed",
            title: job.title,
            status_message: `Great news! Your ${job.title} is all done and ready for pickup.`,
          } as JobStatusResponse),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
    }

    // Strategy 3: Name-based fuzzy lookup (fallback)
    if (customerName) {
      const firstName = customerName.toLowerCase().split(" ")[0];
      if (firstName.length >= 2) {
        const { data: jobs } = await supabase
          .from("active_jobs")
          .select("id, job_number, title, status, priority, notes, estimated_completion, actual_completion, is_active, customer_name, job_service_items(id, title, status, sort_order)")
          .eq("tenant_id", tenantId)
          .ilike("customer_name", `%${firstName}%`)
          .eq("is_active", true)
          .in("status", ["intake", "in_progress", "on_hold"])
          .order("created_at", { ascending: false })
          .limit(5);

        if (jobs && jobs.length > 0) {
          const response = buildJobResponse(jobs[0], jobs.length > 1 ? jobs.length : undefined);
          console.log(`[lookup-active-job] Found ${jobs.length} job(s) by name in ${Date.now() - startTime}ms`);
          return new Response(JSON.stringify(response), {
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          });
        }
      }
    }

    // Strategy 4: Vehicle description match against job title
    if (vehicleDescription) {
      const searchTerms = vehicleDescription.toLowerCase().split(/\s+/).filter(w => w.length >= 3);
      if (searchTerms.length > 0) {
        // Search by first meaningful term in the vehicle description
        const { data: jobs } = await supabase
          .from("active_jobs")
          .select("id, job_number, title, status, priority, notes, estimated_completion, actual_completion, is_active, job_service_items(id, title, status, sort_order)")
          .eq("tenant_id", tenantId)
          .ilike("title", `%${searchTerms[0]}%`)
          .eq("is_active", true)
          .in("status", ["intake", "in_progress", "on_hold"])
          .order("created_at", { ascending: false })
          .limit(5);

        if (jobs && jobs.length > 0) {
          // Score by how many search terms match
          const scored = jobs.map((job: any) => {
            const titleLower = (job.title || "").toLowerCase();
            const matchCount = searchTerms.filter(t => titleLower.includes(t)).length;
            return { ...job, matchScore: matchCount };
          }).filter(j => j.matchScore > 0)
            .sort((a, b) => b.matchScore - a.matchScore);

          if (scored.length > 0) {
            const response = buildJobResponse(scored[0], scored.length > 1 ? scored.length : undefined);
            console.log(`[lookup-active-job] Found ${scored.length} job(s) by vehicle in ${Date.now() - startTime}ms`);
            return new Response(JSON.stringify(response), {
              headers: { ...corsHeaders, "Content-Type": "application/json" },
            });
          }
        }
      }
    }

    // Nothing found
    console.log(`[lookup-active-job] No jobs found in ${Date.now() - startTime}ms`);
    return new Response(
      JSON.stringify({
        found: false,
        status_message: "I don't see any active work orders on file for you. Do you have a job number, or know what name it might be under?",
      } as JobStatusResponse),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );

  } catch (error) {
    console.error("[lookup-active-job] Error:", error);
    return new Response(
      JSON.stringify({
        found: false,
        status_message: "I'm having trouble looking that up right now. Can I take your info and have someone call you back with an update?",
        error: error instanceof Error ? error.message : "Unknown error",
      }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

/**
 * Build a speech-ready response from an active_jobs row with its service items.
 */
function buildJobResponse(job: any, totalJobCount?: number): JobStatusResponse {
  const items = (job.job_service_items || []).sort(
    (a: { sort_order: number }, b: { sort_order: number }) => a.sort_order - b.sort_order
  );
  const completed = items.filter((i: { status: string }) => i.status === "completed");
  const inProgress = items.filter((i: { status: string }) => i.status === "in_progress");
  const remaining = items.filter((i: { status: string }) => i.status !== "completed" && i.status !== "skipped");

  let statusMessage = "";

  // Handle completed jobs
  if (job.status === "completed" || job.actual_completion) {
    statusMessage = `Great news! Your ${job.title} is all done and ready for pickup.`;
    return {
      found: true,
      job_id: job.id,
      job_number: job.job_number,
      status: "completed",
      title: job.title,
      status_message: statusMessage,
      services_total: items.length,
      services_completed: completed.length,
    };
  }

  // Handle on_hold
  if (job.status === "on_hold") {
    statusMessage = `Your ${job.title} is currently on hold.`;
    if (job.notes) {
      statusMessage += ` The note says: ${job.notes}`;
    }
    statusMessage += " Want me to have someone call you with more details?";
    return {
      found: true,
      job_id: job.id,
      job_number: job.job_number,
      status: job.status,
      title: job.title,
      status_message: statusMessage,
      services_total: items.length,
      services_completed: completed.length,
    };
  }

  // Active job — build progress summary
  if (items.length === 0) {
    statusMessage = `Your ${job.title} is in the shop and being worked on.`;
  } else if (completed.length === items.length) {
    statusMessage = `Your ${job.title} is all done! Everything's been completed.`;
  } else if (completed.length === 0) {
    if (inProgress.length > 0) {
      statusMessage = `Your ${job.title} is in the shop. We're currently working on the ${inProgress[0].title}.`;
    } else {
      statusMessage = `Your ${job.title} is in the queue. We haven't started on it yet but it's coming up.`;
    }
  } else {
    // Partial progress
    const completedNames = completed.map((i: { title: string }) => i.title).join(", ");
    if (inProgress.length > 0) {
      statusMessage = `Your ${job.title} is coming along. We've finished the ${completedNames}, and we're currently working on the ${inProgress[0].title}.`;
    } else {
      const remainingNames = remaining.map((i: { title: string }) => i.title).join(", ");
      statusMessage = `Your ${job.title} is coming along. We've finished the ${completedNames}. Still need to do the ${remainingNames}.`;
    }
  }

  // Add ETA if available
  if (job.estimated_completion) {
    const est = new Date(job.estimated_completion);
    const now = new Date();
    const diffHours = Math.round((est.getTime() - now.getTime()) / (1000 * 60 * 60));
    if (diffHours > 0 && diffHours <= 4) {
      statusMessage += ` Should be ready in about ${diffHours} ${diffHours === 1 ? "hour" : "hours"}.`;
    } else if (diffHours > 4 && diffHours <= 24) {
      statusMessage += " Should be ready later today.";
    } else if (diffHours > 24 && diffHours <= 48) {
      statusMessage += " Looking like it'll be ready tomorrow.";
    }
  }

  // Multiple jobs note
  if (totalJobCount && totalJobCount > 1) {
    statusMessage = `I see you have ${totalJobCount} jobs with us. For the most recent one: ${statusMessage}`;
  }

  return {
    found: true,
    job_id: job.id,
    job_number: job.job_number,
    status: job.status,
    title: job.title,
    status_message: statusMessage,
    services_total: items.length,
    services_completed: completed.length,
    estimated_completion: job.estimated_completion || undefined,
    multiple_jobs: totalJobCount ? totalJobCount > 1 : false,
    job_count: totalJobCount || 1,
  };
}

/**
 * ElevenLabs Tool: Lookup Dispatch Status
 * 
 * Allows the voice AI to look up a caller's dispatch job status
 * by matching at least 2 of 3 identifiers: name, phone, pickup address.
 * 
 * Returns job status with appropriate ETA information.
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface LookupRequest {
  tenant_id: string;
  customer_name?: string;
  customer_phone?: string;
  pickup_address?: string;
}

interface JobStatusResponse {
  found: boolean;
  job_id?: string;
  job_number?: string;
  status?: string;
  status_message?: string;
  driver_assigned?: boolean;
  en_route_since_minutes?: number;
  estimated_arrival_minutes?: number;
  pickup_address?: string;
  multiple_jobs?: boolean;
  job_count?: number;
}

/**
 * Escape special characters for PostgREST ilike filters
 * Commas, parentheses, and percent signs need special handling
 */
function escapeForPostgREST(value: string): string {
  // Replace special PostgREST characters that break or() parsing
  // The main issue is commas in addresses like "2968 Mercerville, Quaker"
  return value
    .replace(/,/g, " ")  // Replace commas with spaces (safer for address matching)
    .replace(/\(/g, " ")
    .replace(/\)/g, " ")
    .replace(/\s+/g, " ") // Collapse multiple spaces
    .trim();
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const startTime = Date.now();

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    const body: LookupRequest = await req.json();
    const { tenant_id, customer_name, customer_phone, pickup_address } = body;

    if (!tenant_id) {
      return new Response(
        JSON.stringify({ error: "tenant_id is required" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Count how many identifiers were provided
    const identifiers = [customer_name, customer_phone, pickup_address].filter(Boolean);
    if (identifiers.length < 2) {
      return new Response(
        JSON.stringify({
          found: false,
          status_message: "I need at least two pieces of information to look up your job - your name, phone number, or pickup address. Could you provide another detail?",
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Build individual filter conditions
    // We'll use separate ilike calls instead of combining with commas
    const filterConditions: string[] = [];
    
    if (customer_phone) {
      // Normalize phone for matching - just use last 10 digits
      const normalizedPhone = customer_phone.replace(/\D/g, "").slice(-10);
      if (normalizedPhone.length >= 7) {
        filterConditions.push(`customer_phone.ilike.*${normalizedPhone}*`);
      }
    }
    
    if (customer_name) {
      // Fuzzy match on first name only (safer)
      const firstName = escapeForPostgREST(customer_name.toLowerCase().split(" ")[0]);
      if (firstName.length >= 2) {
        filterConditions.push(`customer_name.ilike.*${firstName}*`);
      }
    }
    
    if (pickup_address) {
      // Extract just the street number and first word of street name for matching
      // This avoids issues with commas in city names like "2968 Mercerville, Quaker Bridge Rd"
      const cleanAddress = escapeForPostgREST(pickup_address.toLowerCase());
      const addressWords = cleanAddress.split(" ").filter(w => w.length >= 2);
      // Use first 2 significant words (usually street number + name)
      const searchPattern = addressWords.slice(0, 2).join("*");
      if (searchPattern.length >= 3) {
        filterConditions.push(`pickup_address.ilike.*${searchPattern}*`);
      }
    }

    console.log(`[lookup-dispatch-status] Searching with ${filterConditions.length} conditions:`, filterConditions);

    // Build query for active jobs
    let query = supabase
      .from("dispatch_jobs")
      .select(`
        id,
        job_number,
        status,
        customer_name,
        customer_phone,
        pickup_address,
        driver_id,
        en_route_at,
        on_site_at,
        estimated_arrival_at,
        created_at,
        fleet_drivers:driver_id (
          full_name,
          location_enabled,
          last_known_lat,
          last_known_lng,
          location_updated_at
        )
      `)
      .eq("tenant_id", tenant_id)
      .not("status", "in", '("completed","cancelled")')
      .order("created_at", { ascending: false });

    // Apply OR filters safely by joining with comma but using escaped values
    if (filterConditions.length > 0) {
      query = query.or(filterConditions.join(","));
    }

    const { data: jobs, error } = await query.limit(5);

    if (error) {
      console.error("Query error:", error);
      throw error;
    }

    console.log(`[lookup-dispatch-status] Found ${jobs?.length || 0} candidate jobs`);

    // Score jobs by how many identifiers match
    const scoredJobs = (jobs || []).map((job: any) => {
      let score = 0;
      
      if (customer_phone) {
        const normalizedInput = customer_phone.replace(/\D/g, "").slice(-10);
        const normalizedJob = (job.customer_phone || "").replace(/\D/g, "").slice(-10);
        if (normalizedInput === normalizedJob) score += 1;
      }
      
      if (customer_name) {
        const inputName = customer_name.toLowerCase();
        const jobName = (job.customer_name || "").toLowerCase();
        if (jobName.includes(inputName) || inputName.includes(jobName.split(" ")[0])) score += 1;
      }
      
      if (pickup_address) {
        const inputAddr = pickup_address.toLowerCase().replace(/[^a-z0-9]/g, "");
        const jobAddr = (job.pickup_address || "").toLowerCase().replace(/[^a-z0-9]/g, "");
        // Check if significant overlap
        if (inputAddr.includes(jobAddr.slice(0, 10)) || jobAddr.includes(inputAddr.slice(0, 10))) score += 1;
      }
      
      return { ...job, matchScore: score };
    }).filter((job: any) => job.matchScore >= 2);

    if (scoredJobs.length === 0) {
      return new Response(
        JSON.stringify({
          found: false,
          status_message: "I couldn't find an active job matching that information. Could you double-check the details, or let me know if this is a new request?",
        }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // If multiple jobs, note it but use the most recent
    const multipleJobs = scoredJobs.length > 1;
    const job = scoredJobs[0];

    // Calculate ETA information
    let enRouteSinceMinutes: number | undefined;
    let estimatedArrivalMinutes: number | undefined;

    if (job.status === "en_route" && job.en_route_at) {
      const enRouteTime = new Date(job.en_route_at).getTime();
      const now = Date.now();
      enRouteSinceMinutes = Math.round((now - enRouteTime) / 60000);

      // If we have a calculated ETA, use it
      if (job.estimated_arrival_at) {
        const etaTime = new Date(job.estimated_arrival_at).getTime();
        estimatedArrivalMinutes = Math.max(0, Math.round((etaTime - now) / 60000));
      }
    }

    // Build status message
    let statusMessage = "";
    const driverAssigned = !!job.driver_id;

    switch (job.status) {
      case "pending":
        statusMessage = "We have your request logged. A driver hasn't been assigned yet, but we're working on getting someone to you as soon as possible.";
        break;
      case "assigned":
        statusMessage = "Good news! A driver has been assigned to your job and should be heading your way shortly.";
        break;
      case "en_route":
        if (enRouteSinceMinutes !== undefined && estimatedArrivalMinutes !== undefined) {
          if (estimatedArrivalMinutes <= 5) {
            statusMessage = `Your driver left about ${enRouteSinceMinutes} minutes ago and should be arriving any moment now.`;
          } else {
            statusMessage = `Your driver left about ${enRouteSinceMinutes} minutes ago and should arrive in roughly ${estimatedArrivalMinutes} minutes, give or take.`;
          }
        } else if (enRouteSinceMinutes !== undefined) {
          statusMessage = `Your driver has been on the way for about ${enRouteSinceMinutes} minutes. They should be there soon.`;
        } else {
          statusMessage = "Your driver is currently on the way to you.";
        }
        break;
      case "on_site":
        statusMessage = "Our driver is at the pickup location right now. They should be with you!";
        break;
      default:
        statusMessage = `Your job status is: ${job.status}. Is there something specific I can help with?`;
    }

    // Add note about multiple jobs if applicable
    if (multipleJobs) {
      statusMessage = `I found ${scoredJobs.length} active jobs for you. For the most recent one: ${statusMessage}`;
    }

    const response: JobStatusResponse = {
      found: true,
      job_id: job.id,
      job_number: job.job_number,
      status: job.status,
      status_message: statusMessage,
      driver_assigned: driverAssigned,
      en_route_since_minutes: enRouteSinceMinutes,
      estimated_arrival_minutes: estimatedArrivalMinutes,
      pickup_address: job.pickup_address,
      multiple_jobs: multipleJobs,
      job_count: multipleJobs ? scoredJobs.length : 1,
    };

    console.log(`[lookup-dispatch-status] Found job ${job.job_number} in ${Date.now() - startTime}ms`);

    return new Response(
      JSON.stringify(response),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );

  } catch (error) {
    console.error("[lookup-dispatch-status] Error:", error);
    return new Response(
      JSON.stringify({
        found: false,
        status_message: "I'm having trouble looking up your job right now. Can I take a message and have someone call you back with an update?",
        error: error instanceof Error ? error.message : "Unknown error",
      }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.39.3";

const CORS_HEADERS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
  "Access-Control-Allow-Headers": "Content-Type, Authorization, x-cl-secret",
};

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { status: 204, headers: CORS_HEADERS });
  }

  try {
    const body = await req.json();

    // Dual-level param extraction (ElevenLabs sends nested or flat)
    const params = body.body ?? body;

    const tenantId = params.tenant_id || null;
    const conversationId = params.conversation_id || null;
    const query = params.query || "";
    const make = params.make || "";
    const model = params.model || "";
    const yearMin = params.year_min ? parseInt(params.year_min) : null;
    const yearMax = params.year_max ? parseInt(params.year_max) : null;
    const priceMin = params.price_min ? Math.round(parseFloat(params.price_min) * 100) : null;
    const priceMax = params.price_max ? Math.round(parseFloat(params.price_max) * 100) : null;
    const condition = params.condition || "";
    const bodyStyle = params.body_style || "";
    const color = params.color || "";
    const maxResults = Math.min(parseInt(params.max_results || "5"), 10);

    // Resolve tenant
    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!,
    );

    let resolvedTenantId = tenantId;
    if (!resolvedTenantId && conversationId) {
      const { data: session } = await supabase
        .from("ai_call_sessions")
        .select("tenant_id")
        .eq("elevenlabs_conversation_id", conversationId)
        .maybeSingle();
      resolvedTenantId = session?.tenant_id || null;
    }

    if (!resolvedTenantId) {
      return new Response(
        JSON.stringify({
          success: false,
          message: "I'm not able to search inventory right now. Want me to have someone call you back with that info?",
        }),
        { status: 200, headers: { ...CORS_HEADERS, "Content-Type": "application/json" } },
      );
    }

    // Build dynamic query
    let dbQuery = supabase
      .from("sales_inventory")
      .select("id, year, make, model, trim, body_style, condition, exterior_color, mileage, msrp_cents, asking_price_cents, internet_price_cents, features, stock_number, description")
      .eq("tenant_id", resolvedTenantId)
      .eq("status", "available");

    // Apply structured filters
    if (make) {
      dbQuery = dbQuery.ilike("make", `%${make}%`);
    }
    if (model) {
      dbQuery = dbQuery.ilike("model", `%${model}%`);
    }
    if (yearMin) {
      dbQuery = dbQuery.gte("year", yearMin);
    }
    if (yearMax) {
      dbQuery = dbQuery.lte("year", yearMax);
    }
    if (priceMin) {
      dbQuery = dbQuery.gte("asking_price_cents", priceMin);
    }
    if (priceMax) {
      dbQuery = dbQuery.lte("asking_price_cents", priceMax);
    }
    if (condition) {
      dbQuery = dbQuery.ilike("condition", condition);
    }
    if (bodyStyle) {
      dbQuery = dbQuery.ilike("body_style", `%${bodyStyle}%`);
    }
    if (color) {
      dbQuery = dbQuery.ilike("exterior_color", `%${color}%`);
    }

    // If free-text query provided but no structured filters, try keyword parsing
    if (query && !make && !model && !bodyStyle && !color && !priceMin && !priceMax && !condition) {
      // Parse common keywords from free-text
      const q = query.toLowerCase();

      // Body style keywords
      const bodyStyles = ["suv", "sedan", "truck", "coupe", "convertible", "van", "minivan", "wagon", "hatchback", "crossover"];
      const matchedBody = bodyStyles.find(b => q.includes(b));
      if (matchedBody) {
        dbQuery = dbQuery.ilike("body_style", `%${matchedBody}%`);
      }

      // Condition keywords
      if (q.includes("new")) {
        dbQuery = dbQuery.eq("condition", "new");
      } else if (q.includes("used") || q.includes("pre-owned") || q.includes("preowned")) {
        dbQuery = dbQuery.eq("condition", "used");
      } else if (q.includes("certified") || q.includes("cpo")) {
        dbQuery = dbQuery.eq("condition", "certified");
      }

      // Price hints (e.g., "under 20k", "below 15000")
      const priceMatch = q.match(/(?:under|below|less than|max|up to)\s*\$?\s*(\d+)\s*k?/i);
      if (priceMatch) {
        let priceVal = parseInt(priceMatch[1]);
        if (priceVal < 1000) priceVal *= 1000; // "20k" -> 20000
        dbQuery = dbQuery.lte("asking_price_cents", priceVal * 100);
      }

      // Color keywords
      const colors = ["red", "blue", "black", "white", "silver", "gray", "grey", "green", "yellow", "orange", "brown", "gold", "beige", "tan"];
      const matchedColor = colors.find(c => q.includes(c));
      if (matchedColor) {
        dbQuery = dbQuery.ilike("exterior_color", `%${matchedColor}%`);
      }

      // Make/model - check if any word matches common makes
      const commonMakes = ["toyota", "honda", "ford", "chevrolet", "chevy", "nissan", "bmw", "mercedes", "audi", "hyundai", "kia", "subaru", "mazda", "volkswagen", "vw", "jeep", "dodge", "ram", "gmc", "buick", "cadillac", "lincoln", "lexus", "acura", "infiniti", "volvo", "porsche", "tesla", "rivian", "lucid"];
      const words = q.split(/\s+/);
      for (const word of words) {
        const matchedMake = commonMakes.find(m => word === m || (word === "chevy" && m === "chevrolet") || (word === "vw" && m === "volkswagen"));
        if (matchedMake) {
          const dbMake = matchedMake === "chevy" ? "chevrolet" : matchedMake === "vw" ? "volkswagen" : matchedMake;
          dbQuery = dbQuery.ilike("make", `%${dbMake}%`);
          break;
        }
      }
    }

    // Order by price and limit
    dbQuery = dbQuery.order("asking_price_cents", { ascending: true }).limit(maxResults);

    const { data: results, error } = await dbQuery;

    if (error) {
      console.error("[search-inventory] DB error:", error.message);
      return new Response(
        JSON.stringify({
          success: false,
          message: "I'm having trouble pulling up inventory right now. Want me to have someone call you back with what we have?",
        }),
        { status: 200, headers: { ...CORS_HEADERS, "Content-Type": "application/json" } },
      );
    }

    // Get total available count for context
    const { count: totalAvailable } = await supabase
      .from("sales_inventory")
      .select("id", { count: "exact", head: true })
      .eq("tenant_id", resolvedTenantId)
      .eq("status", "available");

    if (!results || results.length === 0) {
      return new Response(
        JSON.stringify({
          success: true,
          message: "I don't see anything matching that right now. Our inventory changes frequently though — want me to set up a time for you to come browse in person, or have someone call you when something comes in?",
          results: [],
          total_available: totalAvailable || 0,
        }),
        { status: 200, headers: { ...CORS_HEADERS, "Content-Type": "application/json" } },
      );
    }

    // Format results into conversational message
    const formatPrice = (cents: number | null): string => {
      if (!cents) return "call for pricing";
      const dollars = Math.round(cents / 100);
      if (dollars >= 1000) {
        const thousands = (dollars / 1000).toFixed(dollars % 1000 === 0 ? 0 : 1);
        return `$${thousands.replace(/\.0$/, "")}k`;
      }
      return `$${dollars.toLocaleString()}`;
    };

    const formatMileage = (miles: number | null): string => {
      if (!miles) return "";
      if (miles >= 1000) {
        return `${Math.round(miles / 1000)}k miles`;
      }
      return `${miles} miles`;
    };

    const vehicleSummaries = results.map((v: any, i: number) => {
      const price = v.internet_price_cents || v.asking_price_cents;
      const parts = [
        `${v.year} ${v.make} ${v.model}${v.trim ? ` ${v.trim}` : ""}`,
      ];
      if (v.body_style) parts[0] += ` (${v.body_style})`;
      if (v.exterior_color) parts.push(v.exterior_color);
      if (v.mileage) parts.push(formatMileage(v.mileage));
      parts.push(formatPrice(price));
      if (v.condition === "certified") parts.push("Certified Pre-Owned");

      // Add top features if available
      const features = Array.isArray(v.features) ? v.features : [];
      if (features.length > 0) {
        parts.push(features.slice(0, 3).join(", "));
      }

      return parts.join(" — ");
    });

    let message = `I found ${results.length} option${results.length > 1 ? "s" : ""} that match${results.length === 1 ? "es" : ""}. `;
    message += vehicleSummaries.join(". ");
    message += ". Would you like to come in and check any of these out? I can set up a time for you.";

    return new Response(
      JSON.stringify({
        success: true,
        message,
        results: results.map((v: any) => ({
          id: v.id,
          year: v.year,
          make: v.make,
          model: v.model,
          trim: v.trim,
          body_style: v.body_style,
          condition: v.condition,
          color: v.exterior_color,
          mileage: v.mileage,
          price_cents: v.internet_price_cents || v.asking_price_cents,
          stock_number: v.stock_number,
        })),
        total_available: totalAvailable || 0,
      }),
      { status: 200, headers: { ...CORS_HEADERS, "Content-Type": "application/json" } },
    );
  } catch (err) {
    console.error("[search-inventory] Error:", err);
    return new Response(
      JSON.stringify({
        success: false,
        message: "I'm having a little trouble pulling that up. Want me to have someone from the team call you with inventory details?",
      }),
      { status: 200, headers: { ...CORS_HEADERS, "Content-Type": "application/json" } },
    );
  }
});

/**
 * elevenlabs-suggest-availability: ElevenLabs tool endpoint for suggesting
 * available appointment slots during voice calls.
 * 
 * Called by ElevenLabs agent when it needs to offer appointment times:
 * - Returns next available slots for a given date
 * - Respects service duration, business hours, and existing bookings
 * - Provides human-readable slot displays for voice output
 */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface ElevenLabsToolRequest {
  // Date for availability (YYYY-MM-DD or natural language like "tomorrow")
  date?: string;
  // Service name or ID to determine duration
  service_name?: string;
  service_id?: string;
  // Duration override in minutes
  duration_minutes?: number;
  // Preference: earliest, morning, afternoon, evening
  preference?: string;
  // Max slots to return
  max_results?: number;
  // Tenant identification
  tenant_id?: string;
  tenantId?: string;
  // ElevenLabs context
  conversation_id?: string;
  call_id?: string;
  // Nested params (ElevenLabs format)
  params?: {
    date?: string;
    service_name?: string;
    service_id?: string;
    duration_minutes?: number;
    preference?: string;
    tenant_id?: string;
  };
}

interface SuggestAvailabilityResponse {
  success: boolean;
  slots: Array<{
    start: string;
    end: string;
    display: string;
    local_date: string;
  }>;
  count: number;
  date: string;
  service_name: string | null;
  duration_minutes: number;
  message: string;
  no_availability_reason?: string;
  waitlist_available?: boolean;
  callback_available?: boolean;
  next_available_date?: string | null;
  next_available_slots?: Array<{ start: string; end: string; display: string; local_date: string }>;
}

// Parse natural language date to YYYY-MM-DD
function parseDate(input: string, timezone: string): string {
  const now = new Date();
  const lower = input.toLowerCase().trim();
  
  // Handle relative dates
  if (lower === "today" || lower === "now") {
    return formatDateLocal(now, timezone);
  }
  if (lower === "tomorrow") {
    const tomorrow = new Date(now);
    tomorrow.setDate(tomorrow.getDate() + 1);
    return formatDateLocal(tomorrow, timezone);
  }
  if (lower.includes("next")) {
    const days = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
    for (let i = 0; i < days.length; i++) {
      if (lower.includes(days[i])) {
        const target = new Date(now);
        const currentDay = now.getDay();
        let daysToAdd = i - currentDay;
        if (daysToAdd <= 0) daysToAdd += 7;
        target.setDate(target.getDate() + daysToAdd);
        return formatDateLocal(target, timezone);
      }
    }
  }
  
  // Try parsing as YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(input)) {
    return input;
  }
  
  // Try parsing as MM/DD or MM-DD
  const mdMatch = input.match(/^(\d{1,2})[\/\-](\d{1,2})$/);
  if (mdMatch) {
    const month = mdMatch[1].padStart(2, "0");
    const day = mdMatch[2].padStart(2, "0");
    const year = now.getFullYear();
    return `${year}-${month}-${day}`;
  }
  
  // Default to today
  return formatDateLocal(now, timezone);
}

function formatDateLocal(date: Date, timezone: string): string {
  try {
    const formatter = new Intl.DateTimeFormat("en-CA", {
      timeZone: timezone,
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
    });
    return formatter.format(date);
  } catch {
    return date.toISOString().slice(0, 10);
  }
}

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const body: ElevenLabsToolRequest = await req.json();
    
    console.log(`[suggest-availability] Full request:`, JSON.stringify(body));
    
    // Parse request params (handle ElevenLabs nested format)
    const rawDate = body.date || body.params?.date || "";
    const serviceName = body.service_name || body.params?.service_name || "";
    const serviceId = body.service_id || body.params?.service_id || "";
    const durationOverride = body.duration_minutes || body.params?.duration_minutes;
    const preference = body.preference || body.params?.preference || "earliest";
    const maxResults = body.max_results || 5;
    const directTenantId = body.tenant_id || body.tenantId || body.params?.tenant_id || "";
    const conversationId = body.conversation_id || body.call_id || "";

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, serviceKey);

    // Resolve tenant_id
    let tenantId: string | null = directTenantId || null;
    
    if (!tenantId && conversationId) {
      const { data: session } = await supabase
        .from("ai_call_sessions")
        .select("tenant_id")
        .eq("elevenlabs_conversation_id", conversationId)
        .maybeSingle();
      tenantId = session?.tenant_id || null;
    }

    // P0-2: Removed cross-tenant fallback that queried most recent session
    // across ALL tenants. This was a tenant isolation risk.

    if (!tenantId) {
      return new Response(
        JSON.stringify({
          success: false,
          slots: [],
          count: 0,
          date: rawDate,
          service_name: null,
          duration_minutes: 60,
          message: "Unable to check availability - no active session found",
        } as SuggestAvailabilityResponse),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Get tenant settings + assistant_settings (same_day_enabled, waitlist_enabled)
    const [tenantResult, assistantSettingsResult] = await Promise.all([
      supabase.from("tenants").select("timezone, hours_json, appointment_buffer_minutes").eq("id", tenantId).single(),
      supabase.from("assistant_settings").select("same_day_enabled, waitlist_enabled").eq("tenant_id", tenantId).maybeSingle(),
    ]);

    const tenant = tenantResult.data;
    const assistantSettings = assistantSettingsResult.data;
    const timezone = tenant?.timezone || "America/New_York";
    const bufferMinutes = tenant?.appointment_buffer_minutes || 15;
    const sameDayEnabled = assistantSettings?.same_day_enabled ?? true;
    const waitlistEnabled = assistantSettings?.waitlist_enabled ?? false;

    // Parse the date
    let targetDate = parseDate(rawDate || "today", timezone);

    // same_day_enabled check: if disabled and target is today, skip to tomorrow
    const todayStr = new Date().toLocaleDateString("en-CA", { timeZone: timezone });
    if (!sameDayEnabled && targetDate === todayStr) {
      const tomorrow = new Date();
      tomorrow.setDate(tomorrow.getDate() + 1);
      targetDate = tomorrow.toLocaleDateString("en-CA", { timeZone: timezone });
      console.log(`[suggest-availability] same_day_enabled=false, advancing to ${targetDate}`);
    }
    
    console.log(`[suggest-availability] Tenant: ${tenantId.substring(0, 8)}..., Date: ${targetDate}, Service: ${serviceName || serviceId}`);

    // Resolve service for duration
    let finalDuration = durationOverride || 60;
    let resolvedServiceName: string | null = null;

    if (serviceId) {
      const { data: service } = await supabase
        .from("services")
        .select("name, duration_minutes")
        .eq("id", serviceId)
        .eq("tenant_id", tenantId)
        .single();
      if (service) {
        finalDuration = service.duration_minutes || finalDuration;
        resolvedServiceName = service.name;
      }
    } else if (serviceName) {
      const { data: service } = await supabase
        .from("services")
        .select("name, duration_minutes")
        .eq("tenant_id", tenantId)
        .ilike("name", `%${serviceName}%`)
        .limit(1)
        .maybeSingle();
      if (service) {
        finalDuration = service.duration_minutes || finalDuration;
        resolvedServiceName = service.name;
      }
    }

    // Call the database function for slot computation
    // Fetch tenant capacity for multi-technician support
    const { data: tenantCapacity } = await supabase
      .from("tenants")
      .select("default_capacity")
      .eq("id", tenantId)
      .single();
    const capacity = (tenantCapacity as any)?.default_capacity || 1;

    const { data: slots, error: slotsError } = await supabase.rpc(
      "fn_compute_available_slots",
      {
        _tenant_id: tenantId,
        _start_date: targetDate,
        _end_date: targetDate,
        _duration_minutes: finalDuration,
        _buffer_minutes: bufferMinutes,
        _business_hours: tenant?.hours_json,
        _capacity: capacity,
      }
    );

    if (slotsError) {
      console.error("[suggest-availability] Slots error:", slotsError);
      return new Response(
        JSON.stringify({
          success: false,
          slots: [],
          count: 0,
          date: targetDate,
          service_name: resolvedServiceName,
          duration_minutes: finalDuration,
          message: "Unable to check availability at this time",
        } as SuggestAvailabilityResponse),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Apply preference filter
    let filteredSlots = (slots || []) as Array<{
      slot_start: string;
      slot_end: string;
      slot_date: string;
      slot_time_local: string;
    }>;

    if (preference === "morning") {
      filteredSlots = filteredSlots.filter(slot => {
        const hour = parseInt(slot.slot_time_local.split(":")[0], 10);
        return hour < 12;
      });
    } else if (preference === "afternoon") {
      filteredSlots = filteredSlots.filter(slot => {
        const hour = parseInt(slot.slot_time_local.split(":")[0], 10);
        return hour >= 12 && hour < 17;
      });
    } else if (preference === "evening") {
      filteredSlots = filteredSlots.filter(slot => {
        const hour = parseInt(slot.slot_time_local.split(":")[0], 10);
        return hour >= 17;
      });
    }

    // Limit and format results
    const limitedSlots = filteredSlots.slice(0, maxResults);
    
    const formattedSlots = limitedSlots.map(slot => ({
      start: slot.slot_start,
      end: slot.slot_end,
      display: slot.slot_time_local,
      local_date: slot.slot_date,
    }));

    // Build response message
    let message: string;
    let noAvailabilityReason: string | undefined;
    let waitlistAvailable: boolean | undefined;
    let callbackAvailable: boolean | undefined;
    let nextAvailableDate: string | null = null;
    let nextAvailableSlots: Array<{ start: string; end: string; display: string; local_date: string }> | undefined;

    if (formattedSlots.length === 0) {
      if (filteredSlots.length === 0 && (slots?.length || 0) > 0) {
        noAvailabilityReason = `No ${preference} slots available. Other times may be available.`;
        message = noAvailabilityReason;
      } else {
        // No slots on requested date — scan up to 5 additional business days
        let foundFutureSlots = false;
        for (let dayOffset = 1; dayOffset <= 5; dayOffset++) {
          const futureDate = new Date(targetDate + "T12:00:00");
          futureDate.setDate(futureDate.getDate() + dayOffset);
          const futureDateStr = futureDate.toISOString().split("T")[0];

          const { data: futureSlots } = await supabase.rpc("fn_compute_available_slots", {
            _tenant_id: tenantId,
            _start_date: futureDateStr,
            _end_date: futureDateStr,
            _duration_minutes: finalDuration,
            _buffer_minutes: bufferMinutes,
            _business_hours: tenant?.hours_json,
            _capacity: capacity,
          });

          if (futureSlots && futureSlots.length > 0) {
            nextAvailableDate = futureDateStr;
            nextAvailableSlots = futureSlots.slice(0, 3).map((s: Record<string, string>) => ({
              start: s.slot_start,
              end: s.slot_end,
              display: s.slot_time_local,
              local_date: s.slot_date,
            }));
            const nextTimes = nextAvailableSlots.map(s => s.display).join(", ");
            message = `Nothing available on ${targetDate}, but I have openings on ${futureDateStr} at ${nextTimes}. Would any of those work?`;
            noAvailabilityReason = "requested_date_full";
            foundFutureSlots = true;
            break;
          }
        }

        if (!foundFutureSlots) {
          // All scanned days are full — offer waitlist or callback
          if (waitlistEnabled) {
            waitlistAvailable = true;
            noAvailabilityReason = "fully_booked_waitlist_available";
            message = "We're fully booked for the next several days. Would you like me to add you to our waitlist? We'll call you as soon as something opens up.";
          } else {
            callbackAvailable = true;
            noAvailabilityReason = "fully_booked_no_waitlist";
            message = "We're fully booked right now. Would you like us to call you back when something opens up?";
          }
        }
      }
    } else if (formattedSlots.length === 1) {
      message = `I have ${formattedSlots[0].display} available.`;
    } else {
      const displayTimes = formattedSlots.slice(0, 3).map(s => s.display).join(", ");
      message = `Available times include ${displayTimes}.`;
    }

    const response: SuggestAvailabilityResponse = {
      success: formattedSlots.length > 0,
      slots: formattedSlots,
      count: formattedSlots.length,
      date: targetDate,
      service_name: resolvedServiceName,
      duration_minutes: finalDuration,
      message,
      no_availability_reason: noAvailabilityReason,
      waitlist_available: waitlistAvailable,
      callback_available: callbackAvailable,
      next_available_date: nextAvailableDate,
      next_available_slots: nextAvailableSlots,
    };

    console.log(`[suggest-availability] Returning ${formattedSlots.length} slots`);

    return new Response(JSON.stringify(response), {
      status: 200,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });

  } catch (error) {
    console.error("[suggest-availability] Error:", error);
    return new Response(
      JSON.stringify({
        success: false,
        slots: [],
        count: 0,
        date: "",
        service_name: null,
        duration_minutes: 60,
        message: "Unable to check availability at this time",
      } as SuggestAvailabilityResponse),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

