    return {
      success: result.success,
      delivery_status: result.success ? "sent" : "failed",
      messageSent: message,
      error: result.error,
    };
  } catch (error) {
    console.error("Email action error:", error);
    return { success: false, delivery_status: "failed", error: String(error) };
  }
}

async function executeAiCallAction(
  supabase: any,
  campaign: any,
  step: any,
  customer: any,
  assistantSettings: any,
  recoverySettings: any
): Promise<ActionResult> {
  try {
    // Check if AI calls are enabled
    if (!recoverySettings?.ai_calls_enabled) {
      // Fall back to internal task
      return await executeInternalTaskAction(
        supabase,
        campaign,
        { ...step, task_description: `Call ${customer.full_name} about ${campaign.original_intent || "their inquiry"}` },
        customer,
        assistantSettings,
        recoverySettings
      );
    }

    // Check AI call hours
    const now = new Date();
    if (recoverySettings.ai_call_hours_start && recoverySettings.ai_call_hours_end) {
      const currentTime = `${now.getHours().toString().padStart(2, "0")}:${now.getMinutes().toString().padStart(2, "0")}`;
      if (currentTime < recoverySettings.ai_call_hours_start || currentTime > recoverySettings.ai_call_hours_end) {
        return { success: false, delivery_status: "rescheduled", error: "outside_ai_call_hours" };
      }
    }

    if (!customer.phone_e164) {
      return { success: false, delivery_status: "failed", error: "no_phone_number" };
    }

    // Build recovery context for the AI
    const recoveryContext = {
      is_recovery_call: true,
      original_call_id: campaign.original_call_id,
      original_intent: campaign.original_intent,
      original_service_interest: campaign.original_service_interest,
      original_objection: campaign.original_objection,
      call_purpose: step.ai_call_purpose,
      script_hints: step.ai_call_script_hints,
      campaign_id: campaign.id,
    };

    // Trigger outbound call via the initiate-outbound-call function
    const { data: callResult, error: callError } = await supabase.functions.invoke("initiate-outbound-call", {
      body: {
        tenant_id: campaign.tenant_id,
        customer_id: customer.id,
        to_phone: customer.phone_e164,
        recovery_context: recoveryContext,
        max_duration_seconds: step.ai_call_max_duration_seconds || 120,
      },
    });

    if (callError) {
      console.error("AI call error:", callError);
      // Fall back to internal task
      return await executeInternalTaskAction(
        supabase,
        campaign,
        { ...step, task_description: `AI call failed - manually call ${customer.full_name} about ${campaign.original_intent || "their inquiry"}` },
        customer,
        assistantSettings,
        recoverySettings
      );
    }

    return {
      success: true,
      delivery_status: "sent",
      callSessionId: callResult?.session_id,
    };
  } catch (error) {
    console.error("AI call action error:", error);
    return { success: false, delivery_status: "failed", error: String(error) };
  }
}

async function executeInternalTaskAction(
  supabase: any,
  campaign: any,
  step: any,
  customer: any,
  assistantSettings: any,
  recoverySettings: any
): Promise<ActionResult> {
  try {
    const description = resolveTemplateTokens(
      step.task_description || `Follow up with ${customer.full_name}`,
      campaign,
      customer,
      assistantSettings,
      recoverySettings
    );

    // Create an in-app notification (using audit_events or a notifications table if available)
    await supabase.from("audit_events").insert({
      tenant_id: campaign.tenant_id,
      event_type: "lead.recovery_task",
      entity_type: "lead_recovery_campaign",
      entity_id: campaign.id,
      actor_type: "system",
      payload: {
        task_description: description,
        task_priority: step.task_priority || "normal",
        customer_id: customer.id,
        customer_name: customer.full_name,
        customer_phone: customer.phone_e164,
        campaign_id: campaign.id,
        action_url: `/app/leads/recovery/${campaign.id}`,
      },
    });

    // Send email notification if configured
    if (recoverySettings?.notification_email) {
      console.log(`Would send task notification email to ${recoverySettings.notification_email}`);
      // TODO: Integrate with email service
    }

    // Send SMS notification if configured
    if (recoverySettings?.notification_sms && assistantSettings?.closeloop_number) {
      const notificationMessage = `[CloseLoop Task] ${description}. Customer: ${customer.phone_e164}`;
      
      await supabase.functions.invoke("send-sms", {
        body: {
          to: recoverySettings.notification_sms,
          from: assistantSettings.closeloop_number,
          body: notificationMessage,
          tenant_id: campaign.tenant_id,
        },
      });
    }

    return {
      success: true,
      delivery_status: "sent",
      messageSent: description,
    };
  } catch (error) {
    console.error("Internal task action error:", error);
    return { success: false, delivery_status: "failed", error: String(error) };
  }
}

// ============== Helper Functions ==============

function resolveTemplateTokens(
  template: string,
  campaign: any,
  customer: any,
  assistantSettings: any,
  recoverySettings: any
): string {
  const firstName = customer.full_name?.split(" ")[0] || customer.full_name || "there";
  
  const replacements: Record<string, string> = {
    "{{customer_name}}": customer.full_name || "Valued Customer",
    "{{customer_first_name}}": firstName,
    "{{business_name}}": assistantSettings?.business_name || campaign.tenant?.business_name || "our team",
    "{{business_phone}}": assistantSettings?.business_phone_number || assistantSettings?.closeloop_number || "",
    "{{service_interest}}": campaign.original_service_interest || campaign.original_intent || "your inquiry",
    "{{original_objection}}": campaign.original_objection || "",
    "{{offer_code}}": recoverySettings?.default_offer_code || "",
    "{{offer_description}}": recoverySettings?.default_offer_description || "a special offer",
    "{{booking_link}}": assistantSettings?.booking_url || "",
  };

  let result = template;
  for (const [token, value] of Object.entries(replacements)) {
    result = result.replace(new RegExp(token.replace(/[{}]/g, "\\$&"), "g"), value);
  }

  return result;
}

function isWithinBusinessHours(date: Date, settings: any): boolean {
  const dayNames = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
  const dayName = dayNames[date.getDay()];
  
  // Check quiet days
  if (settings.quiet_days?.includes(dayName)) {
    return false;
  }

  const currentTime = `${date.getHours().toString().padStart(2, "0")}:${date.getMinutes().toString().padStart(2, "0")}`;
  const quietStart = settings.quiet_hours_start || "21:00";
  const quietEnd = settings.quiet_hours_end || "08:00";

  // Handle overnight quiet period
  if (quietStart > quietEnd) {
    // Quiet from 21:00 to 08:00 means active from 08:00 to 21:00
    return currentTime >= quietEnd && currentTime < quietStart;
  } else {
    return currentTime < quietStart || currentTime >= quietEnd;
  }
}

function getNextBusinessHour(date: Date, settings: any): Date {
  const result = new Date(date);
  const dayNames = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
  const quietEnd = settings.quiet_hours_end || "08:00";
  const [quietEndHour, quietEndMin] = quietEnd.split(":").map(Number);

  let iterations = 0;
  while (iterations < 14) {
    const dayName = dayNames[result.getDay()];
    
    if (!settings.quiet_days?.includes(dayName)) {
      // Set to quiet end time
      result.setHours(quietEndHour, quietEndMin, 0, 0);
      
      if (result > date && isWithinBusinessHours(result, settings)) {
        return result;
      }
    }
    
    // Move to next day
    result.setDate(result.getDate() + 1);
    result.setHours(quietEndHour, quietEndMin, 0, 0);
    iterations++;
  }

  return result;
}

async function advanceToNextStep(
  supabase: any,
  campaign: any,
  currentStep: any,
  recoverySettings: any,
  skipReason: string | null,
  actionId?: string,
  actionResult?: ActionResult
): Promise<Response> {
  const newStepNumber = (campaign.current_step || 0) + 1;
  
  // Get next step
  const { data: nextStep } = await supabase
    .from("lead_recovery_sequence_steps")
    .select("*")
    .eq("sequence_id", campaign.sequence_id)
    .eq("step_order", newStepNumber + 1)
    .maybeSingle();

  let nextActionAt: Date | null = null;
  let newStatus = "active";
  let hasMoreSteps = true;

  if (nextStep) {
    nextActionAt = new Date();
    nextActionAt.setMinutes(nextActionAt.getMinutes() + (nextStep.delay_minutes || 60));
    
    // Adjust for business hours if needed
    if (nextStep.respect_business_hours && recoverySettings?.respect_business_hours) {
      nextActionAt = getNextBusinessHour(nextActionAt, recoverySettings);
    }
  } else {
    // No more steps - complete the campaign
    newStatus = "completed";
    hasMoreSteps = false;
  }

  // Update campaign
  await supabase
    .from("lead_recovery_campaigns")
    .update({
      current_step: newStepNumber,
      next_action_at: nextActionAt?.toISOString() || null,
      total_attempts: campaign.total_attempts + (skipReason ? 0 : 1),
      last_attempt_at: skipReason ? campaign.last_attempt_at : new Date().toISOString(),
      status: newStatus,
      updated_at: new Date().toISOString(),
    })
    .eq("id", campaign.id);

  // Update lead status if completed
  if (newStatus === "completed" && campaign.lead_id) {
    await supabase
      .from("leads")
      .update({ recovery_status: "dormant" })
      .eq("id", campaign.lead_id);
  }

  return jsonResponse({
    success: true,
    action_type: skipReason ? "skipped" : currentStep.action_type,
    action_id: actionId,
    delivery_status: actionResult?.delivery_status || (skipReason ? "skipped" : "unknown"),
    skip_reason: skipReason,
    has_more_steps: hasMoreSteps,
    next_action_at: nextActionAt?.toISOString() || null,
  });
}

async function completeCampaign(supabase: any, campaign: any): Promise<void> {
  await supabase
    .from("lead_recovery_campaigns")
    .update({
      status: "completed",
      next_action_at: null,
      updated_at: new Date().toISOString(),
    })
    .eq("id", campaign.id);

  if (campaign.lead_id) {
    await supabase
      .from("leads")
      .update({ recovery_status: "dormant" })
      .eq("id", campaign.lead_id);
  }
}

async function convertCampaign(
  supabase: any,
  campaign: any,
  bookingId: string | null,
  dispatchJobId: string | null,
  foodOrderId: string | null,
  recoveredValueCents?: number | null
): Promise<void> {
  const now = new Date().toISOString();
  
  // Update campaign status
  await supabase
    .from("lead_recovery_campaigns")
    .update({
      status: "converted",
      converted_at: now,
      converted_booking_id: bookingId,
      converted_dispatch_job_id: dispatchJobId,
      converted_food_order_id: foodOrderId,
      recovered_value_cents: recoveredValueCents || null,
      next_action_at: null,
      updated_at: now,
    })
    .eq("id", campaign.id);

  // Update lead status
  if (campaign.lead_id) {
    await supabase
      .from("leads")
      .update({ recovery_status: "recovered" })
      .eq("id", campaign.lead_id);
  }

  // Create revenue attribution for ROI tracking
  if (recoveredValueCents && recoveredValueCents > 0) {
    const entityType = bookingId ? "booking" : dispatchJobId ? "dispatch_job" : foodOrderId ? "food_order" : "lead_recovery";
    const entityId = bookingId || dispatchJobId || foodOrderId || campaign.id;

    await supabase.from("revenue_attributions").insert({
      tenant_id: campaign.tenant_id,
      session_id: campaign.original_session_id || null,
      entity_type: entityType,
      entity_id: entityId,
      customer_id: campaign.customer_id,
      revenue_cents: recoveredValueCents,
      source_type: "lead_recovery", // New source type for recovery attribution
      status: "pending",
      attributed_at: now,
    });
  }

  // Log the conversion event
  await supabase.from("audit_events").insert({
    tenant_id: campaign.tenant_id,
    event_type: "lead.recovered",
    entity_type: "lead_recovery_campaign",
    entity_id: campaign.id,
    actor_type: "system",
    payload: {
      campaign_id: campaign.id,
      customer_id: campaign.customer_id,
      lead_id: campaign.lead_id,
      recovered_value_cents: recoveredValueCents,
      booking_id: bookingId,
      dispatch_job_id: dispatchJobId,
      food_order_id: foodOrderId,
      total_attempts: campaign.total_attempts,
    },
  });
}

import { corsHeaders } from "../_shared/cors.ts";

const jsonResponse = (body: Record<string, unknown>, status = 200) =>
  new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const { createClient } = await import("https://esm.sh/@supabase/supabase-js@2");
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const body = await req.json();
    const { action, tenant_id, api_key, base_url, is_active } = body;

    if (!tenant_id) return jsonResponse({ error: "Missing tenant_id" }, 400);

    // Verify auth
    const authHeader = req.headers.get("Authorization") || "";
    const token = authHeader.replace("Bearer ", "");
    const { data: { user }, error: authError } = await supabase.auth.getUser(token);
    if (authError || !user) return jsonResponse({ error: "Unauthorized" }, 401);

    if (action === "connect") {
      if (!api_key) return jsonResponse({ error: "Missing api_key" }, 400);

      // Validate the API key by making a test request to FieldEdge
      // NOTE: FieldEdge API endpoints are partner-specific. 
      // Update this URL once you have the actual FieldEdge API docs.
      const fieldedgeBaseUrl = base_url || "https://api.fieldedge.com/v1";
      
      try {
        const testResp = await fetch(`${fieldedgeBaseUrl}/company`, {
          headers: {
            "Authorization": `Bearer ${api_key}`,
            "Content-Type": "application/json",
          },
        });

        // If FieldEdge API isn't accessible yet (partner-only), we store credentials
        // and let the tenant test when their access is approved.
        let companyName = "FieldEdge Account";
        if (testResp.ok) {
          try {
            const companyData = await testResp.json();
            companyName = companyData?.name || companyData?.company_name || companyName;
          } catch {
            // Non-JSON response is fine
          }
        }

        // Upsert integration record
        const { error: upsertError } = await supabase
          .from("tenant_integrations")
          .upsert(
            {
              tenant_id,
              provider: "fieldedge",
              is_active: true,
              credentials_json: { api_key, base_url: fieldedgeBaseUrl },
              config_json: { base_url: fieldedgeBaseUrl, company_name: companyName },
            },
            { onConflict: "tenant_id,provider" }
          );

        if (upsertError) throw upsertError;

        return jsonResponse({ success: true, company_name: companyName });
      } catch (fetchErr) {
        // Even if the test call fails, store the credentials for later use
        const { error: upsertError } = await supabase
          .from("tenant_integrations")
          .upsert(
            {
              tenant_id,
              provider: "fieldedge",
              is_active: true,
              credentials_json: { api_key, base_url: base_url || "https://api.fieldedge.com/v1" },
              config_json: { base_url: base_url || "https://api.fieldedge.com/v1", company_name: "FieldEdge Account" },
            },
            { onConflict: "tenant_id,provider" }
          );

        if (upsertError) throw upsertError;

        return jsonResponse({
          success: true,
          warning: "Could not verify credentials with FieldEdge API. Credentials saved — sync will activate when FieldEdge API access is confirmed.",
        });
      }
    }

    if (action === "toggle") {
      const { error } = await supabase
        .from("tenant_integrations")
        .update({ is_active })
        .eq("tenant_id", tenant_id)
        .eq("provider", "fieldedge");

      if (error) throw error;
      return jsonResponse({ success: true });
    }

    if (action === "disconnect") {
      const { error } = await supabase
        .from("tenant_integrations")
        .delete()
        .eq("tenant_id", tenant_id)
        .eq("provider", "fieldedge");

      if (error) throw error;
      return jsonResponse({ success: true });
    }

    return jsonResponse({ error: "Unknown action" }, 400);
  } catch (err) {
    console.error("[fieldedge-auth] Error:", err);
    return jsonResponse({ error: err.message || "Internal error" }, 500);
  }
});

import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { requireAuthedTenant, serviceClient } from "../_shared/tenant.ts";

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    const { tenantId } = await requireAuthedTenant(req);
    const { customer_id } = await req.json();

    if (!customer_id) {
      return errorResponse("customer_id is required");
    }

    const svc = serviceClient();

    // Verify customer belongs to this tenant
    const { data: customer, error: custErr } = await svc
      .from("customers")
      .select("id, full_name")
      .eq("id", customer_id)
      .eq("tenant_id", tenantId)
      .single();

    if (custErr || !customer) {
      return errorResponse("Customer not found", 404);
    }

    // Build token payload
    const iat = Math.floor(Date.now() / 1000);
    const exp = iat + 24 * 60 * 60; // 24 hours
    const payload = { customer_id, tenant_id: tenantId, iat, exp };
    const payloadB64 = btoa(JSON.stringify(payload));

    // Sign with HMAC-SHA256
    const secret = Deno.env.get("PORTAL_TOKEN_SECRET");
    if (!secret) {
      return errorResponse("PORTAL_TOKEN_SECRET not configured", 500);
    }

    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey(
      "raw",
      encoder.encode(secret),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"],
    );

    const signatureBuffer = await crypto.subtle.sign("HMAC", key, encoder.encode(payloadB64));
    const signatureArray = Array.from(new Uint8Array(signatureBuffer));
    const signatureB64 = btoa(String.fromCharCode(...signatureArray));

    const token = `${payloadB64}.${signatureB64}`;

    const SUPABASE_URL = Deno.env.get("SUPABASE_URL") || "";
    // Construct portal URL — assumes the frontend is hosted at the Supabase project URL or custom domain
    const portalUrl = `${SUPABASE_URL.replace(".supabase.co", "")}/portal/${tenantId}?token=${encodeURIComponent(token)}`;

    return jsonResponse({
      token,
      expires_at: new Date(exp * 1000).toISOString(),
      portal_url: portalUrl,
    });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : "Internal error";
    const status = message.includes("Unauthorized") || message.includes("Forbidden") ? 403 : 500;
    return errorResponse(message, status);
  }
});

/**
 * get-agency-metrics
 *
 * Returns aggregated metrics across all agency-managed tenants.
 * Auth: JWT via requireAuthedTenant, then agency_accounts lookup.
 * Uses serviceClient for cross-tenant queries (bypasses RLS).
 */

import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { serviceClient } from "../_shared/tenant.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    // Auth: only need user identity, not tenant membership
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) return errorResponse("Unauthorized", 401);

    const anonClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } }, auth: { persistSession: false } }
    );
    const { data: userRes, error: userErr } = await anonClient.auth.getUser();
    if (userErr || !userRes?.user?.id) return errorResponse("Unauthorized", 401);

    const userId = userRes.user.id;

    const svc = serviceClient();

    // Look up agency_accounts where user_id matches the authed user
    const { data: agency, error: agencyErr } = await svc
      .from("agency_accounts")
      .select("id, agency_name")
      .eq("user_id", userId)
      .maybeSingle();

    if (agencyErr) {
      console.error("[get-agency-metrics] agency lookup error:", agencyErr);
      return errorResponse("Failed to look up agency account", 500);
    }

    if (!agency) {
      return errorResponse("No agency account found", 403);
    }

    // Fetch all agency_tenants for this agency
    const { data: agencyTenants, error: tenantsErr } = await svc
      .from("agency_tenants")
      .select("tenant_id, status, provisioned_at, notes")
      .eq("agency_id", agency.id);

    if (tenantsErr) {
      console.error("[get-agency-metrics] agency_tenants lookup error:", tenantsErr);
      return errorResponse("Failed to fetch managed tenants", 500);
    }

    const managedTenants = agencyTenants ?? [];
    const activeTenants = managedTenants.filter((t) => t.status === "active");
    const tenantIds = activeTenants.map((t) => t.tenant_id);

    if (tenantIds.length === 0) {
      return jsonResponse({
        agency_id: agency.id,
        agency_name: agency.agency_name,
        total_clients: 0,
        total_calls_30d: 0,
        total_revenue_30d_cents: 0,
        conversion_rate: 0,
        per_tenant: [],
      });
    }

    // Calculate 30-day window
    const now = new Date();
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString();

    // Fetch tenant names
    const { data: tenants } = await svc
      .from("tenants")
      .select("id, name")
      .in("id", tenantIds);

    const tenantNameMap: Record<string, string> = {};
    for (const t of tenants ?? []) {
      tenantNameMap[t.id] = t.name ?? "Unknown";
    }

    // Fetch call sessions (last 30d) for all managed tenants
    const { data: sessions30d } = await svc
      .from("ai_call_sessions")
      .select("id, tenant_id, outcome")
      .in("tenant_id", tenantIds)
      .gte("started_at", thirtyDaysAgo);

    const sessionsList = sessions30d ?? [];

    // Fetch revenue attributions (last 30d) for all managed tenants
    const { data: revenues30d } = await svc
      .from("revenue_attributions")
      .select("tenant_id, revenue_cents")
      .in("tenant_id", tenantIds)
      .gte("created_at", thirtyDaysAgo);

    const revenuesList = revenues30d ?? [];

    // Aggregate per-tenant
    const perTenant: Array<{
      tenant_id: string;
      tenant_name: string;
      calls_30d: number;
      revenue_30d_cents: number;
      conversion_rate: number;
      status: string;
    }> = [];

    let totalCalls30d = 0;
    let totalRevenue30dCents = 0;
    let totalBooked30d = 0;

    for (const at of activeTenants) {
      const tid = at.tenant_id;

      const tenantSessions = sessionsList.filter((s) => s.tenant_id === tid);
      const tenantRevenues = revenuesList.filter((r) => r.tenant_id === tid);

      const calls30d = tenantSessions.length;
      const booked30d = tenantSessions.filter((s) => s.outcome === "booked").length;
      const revenue30dCents = tenantRevenues.reduce(
        (sum, r) => sum + (r.revenue_cents ?? 0),
        0
      );

      totalCalls30d += calls30d;
      totalRevenue30dCents += revenue30dCents;
      totalBooked30d += booked30d;

      perTenant.push({
        tenant_id: tid,
        tenant_name: tenantNameMap[tid] ?? "Unknown",
        calls_30d: calls30d,
        revenue_30d_cents: revenue30dCents,
        conversion_rate: calls30d > 0 ? Math.round((booked30d / calls30d) * 10000) / 10000 : 0,
        status: at.status,
      });
    }

    return jsonResponse({
      agency_id: agency.id,
      agency_name: agency.agency_name,
      total_clients: activeTenants.length,
      total_calls_30d: totalCalls30d,
      total_revenue_30d_cents: totalRevenue30dCents,
      conversion_rate:
        totalCalls30d > 0
          ? Math.round((totalBooked30d / totalCalls30d) * 10000) / 10000
          : 0,
      per_tenant: perTenant,
    });
  } catch (err) {
    console.error("[get-agency-metrics] Error:", err);
    const message = err instanceof Error ? err.message : "Internal server error";
    const status = message.includes("Unauthorized") || message.includes("bearer") ? 401 : 500;
    return errorResponse(message, status);
  }
});

/**
 * get-agency-readiness-batch
 *
 * Returns onboarding readiness status for a batch of tenant IDs.
 * Auth: JWT + verify caller has membership on each requested tenant (via agency).
 *
 * Input: { tenant_ids: string[] }
 * Returns: { readiness: Record<string, { has_brain_content, subscription_status, has_stripe_customer, onboarding_step }> }
 */

import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";
import { requireAuthedTenant, serviceClient } from "../_shared/tenant.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    const { tenant_ids } = await req.json();

    if (!Array.isArray(tenant_ids) || tenant_ids.length === 0) {
      return errorResponse("Missing or empty tenant_ids array");
    }

    // Limit batch size
    if (tenant_ids.length > 50) {
      return errorResponse("Too many tenant_ids (max 50)");
    }

    // Auth: verify JWT
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) return errorResponse("Unauthorized", 401);

    const anonClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } }, auth: { persistSession: false } }
    );
    const { data: userRes, error: userErr } = await anonClient.auth.getUser();
    if (userErr || !userRes?.user?.id) return errorResponse("Unauthorized", 401);

    const userId = userRes.user.id;
    const svc = serviceClient();

    // Verify user is an agency owner that manages these tenants
    const { data: agencyAccount } = await svc
      .from("agency_accounts")
      .select("id")
      .eq("user_id", userId)
      .maybeSingle();

    if (!agencyAccount) return errorResponse("Not an agency user", 403);

    const { data: agencyTenants } = await svc
      .from("agency_tenants")
      .select("tenant_id")
      .eq("agency_id", agencyAccount.id)
      .in("tenant_id", tenant_ids);

    const allowedIds = new Set((agencyTenants || []).map((t: any) => t.tenant_id));

    // Fetch data for all allowed tenants
    const allowedList = tenant_ids.filter((id: string) => allowedIds.has(id));

    if (allowedList.length === 0) {
      return jsonResponse({ readiness: {} });
    }

    // Fetch assistant_settings (brain content proxy)
    const { data: settings } = await svc
      .from("assistant_settings")
      .select("tenant_id, voice_ai_enabled, greeting_script")
      .in("tenant_id", allowedList);

    // Fetch subscriptions
    const { data: subscriptions } = await svc
      .from("subscriptions")
      .select("tenant_id, status, stripe_customer_id")
      .in("tenant_id", allowedList);

    // Fetch FAQs count (brain content indicator)
    const { data: faqCounts } = await svc
      .from("business_faqs")
      .select("tenant_id")
      .in("tenant_id", allowedList);

    // Fetch services count (brain content indicator)
    const { data: serviceCounts } = await svc
      .from("services")
      .select("tenant_id")
      .in("tenant_id", allowedList);

    const settingsMap = new Map((settings || []).map((s: any) => [s.tenant_id, s]));
    const subMap = new Map((subscriptions || []).map((s: any) => [s.tenant_id, s]));

    // Count FAQs and services per tenant
    const faqCountMap = new Map<string, number>();
    for (const f of faqCounts || []) {
      faqCountMap.set((f as any).tenant_id, (faqCountMap.get((f as any).tenant_id) || 0) + 1);
    }
    const svcCountMap = new Map<string, number>();
    for (const s of serviceCounts || []) {
      svcCountMap.set((s as any).tenant_id, (svcCountMap.get((s as any).tenant_id) || 0) + 1);
    }

    const readiness: Record<string, unknown> = {};

    for (const tenantId of allowedList) {
      const s = settingsMap.get(tenantId);
      const sub = subMap.get(tenantId);
      const faqCount = faqCountMap.get(tenantId) || 0;
      const svcCount = svcCountMap.get(tenantId) || 0;

      const hasBrainContent = faqCount > 0 || svcCount > 0 || !!(s?.greeting_script);
      const subscriptionStatus = sub?.status || null;
      const hasStripeCustomer = !!sub?.stripe_customer_id;

      // Compute step
      let onboardingStep: string;
      if (subscriptionStatus === "active") {
        onboardingStep = "live";
      } else if (hasStripeCustomer || subscriptionStatus === "trialing") {
        onboardingStep = "plan_selected";
      } else if (hasBrainContent) {
        onboardingStep = "ai_ready";
      } else if (s) {
        onboardingStep = "brain_setup";
      } else {
        onboardingStep = "provisioned";
      }

      readiness[tenantId] = {
        has_brain_content: hasBrainContent,
        subscription_status: subscriptionStatus,
        has_stripe_customer: hasStripeCustomer,
        onboarding_step: onboardingStep,
      };
    }

    return jsonResponse({ readiness });
  } catch (err) {
    console.error("get-agency-readiness-batch error:", err);
    if (err instanceof Error && (err.message === "Unauthorized" || err.message.includes("Forbidden"))) {
      return errorResponse(err.message, 401);
    }
    return errorResponse("Internal error", 500);
  }
});

/**
 * get-agent-tools-config: Returns the ElevenLabs agent tools configuration
 * for a given business mode.
 *
 * Used by:
 * - Dashboard to display available tools per mode
 * - External systems to configure ElevenLabs agents
 * - Documentation generation
 *
 * Query parameters:
 * - mode: business mode (service, dispatch, food, medical, general)
 * - format: output format (default, elevenlabs)
 * - summary: if "true", return summary of all modes
 */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import {
  getAgentToolsConfig,
  getElevenLabsToolsForMode,
  getAgentsSummary,
  AGENT_TOOLS_REGISTRY,
  type BusinessMode,
} from "../_shared/agentToolsConfig.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const VALID_MODES: BusinessMode[] = ["service", "dispatch", "food", "medical", "general", "sales"];

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const url = new URL(req.url);
    const mode = url.searchParams.get("mode") as BusinessMode | null;
    const format = url.searchParams.get("format") || "default";
    const summaryOnly = url.searchParams.get("summary") === "true";

    // Return summary of all modes
    if (summaryOnly) {
      const summary = getAgentsSummary();
      return new Response(
        JSON.stringify({
          success: true,
          agents: summary,
          available_modes: VALID_MODES,
        }),
        {
          status: 200,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // Validate mode
    if (!mode || !VALID_MODES.includes(mode)) {
      return new Response(
        JSON.stringify({
          success: false,
          error: `Invalid or missing mode. Must be one of: ${VALID_MODES.join(", ")}`,
          available_modes: VALID_MODES,
        }),
        {
          status: 400,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // Get configuration for mode
    const config = getAgentToolsConfig(mode);

    // Return in requested format
    if (format === "elevenlabs") {
      // Return tools in ElevenLabs API format
      const tools = getElevenLabsToolsForMode(mode);
      return new Response(
        JSON.stringify({
          success: true,
          mode,
          agent_name: config.agentName,
          industries: config.industries,
          tool_count: config.toolCount,
          tools,
        }),
        {
          status: 200,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        }
      );
    }

    // Default format - return full configuration
    return new Response(
      JSON.stringify({
        success: true,
        config,
      }),
      {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  } catch (error) {
    console.error("[get-agent-tools-config] Error:", error);
    return new Response(
      JSON.stringify({
        success: false,
        error: error instanceof Error ? error.message : "Unknown error",
      }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      }
    );
  }
});

