// v2.0.0 - Lightweight fetch-based implementation to avoid cold-start timeouts

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

interface LotInfoRequest {
  tenant_id: string;
  lot_id?: string;
  tenant_timezone?: string;
}

interface HoursEntry {
  open: string | null;
  close: string | null;
}

type DayOfWeek = "sunday" | "monday" | "tuesday" | "wednesday" | "thursday" | "friday" | "saturday";

const DAY_ORDER: DayOfWeek[] = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"];
const DAY_LABELS: Record<DayOfWeek, string> = {
  monday: "Monday",
  tuesday: "Tuesday",
  wednesday: "Wednesday",
  thursday: "Thursday",
  friday: "Friday",
  saturday: "Saturday",
  sunday: "Sunday",
};

// Lookup tenant by name using ilike
async function resolveTenantByName(url: string, key: string, name: string): Promise<string | null> {
  const response = await fetch(
    `${url}/rest/v1/tenants?name=ilike.*${encodeURIComponent(name)}*&select=id&limit=1`,
    {
      headers: {
        apikey: key,
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
    }
  );

  if (!response.ok) return null;
  const data = await response.json();
  return data?.[0]?.id || null;
}

// Fetch impound lot(s)
async function fetchImpoundLots(
  url: string,
  key: string,
  tenantId: string,
  lotId?: string
): Promise<any[]> {
  let queryUrl = `${url}/rest/v1/impound_lots?tenant_id=eq.${tenantId}&is_active=eq.true&select=*`;

  if (lotId) {
    queryUrl += `&id=eq.${lotId}`;
  } else {
    queryUrl += "&order=is_default.desc&limit=1";
  }

  const response = await fetch(queryUrl, {
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
    },
  });

  if (!response.ok) return [];
  return await response.json();
}

// Format time from 24h to 12h AM/PM
function formatTime(time24: string): string {
  const [hours, minutes] = time24.split(":").map(Number);
  const period = hours >= 12 ? "PM" : "AM";
  const hours12 = hours % 12 || 12;
  if (minutes === 0) {
    return `${hours12} ${period}`;
  }
  return `${hours12}:${minutes.toString().padStart(2, "0")} ${period}`;
}

// Format time for speech (simpler)
function formatTimeForSpeech(time24: string): string {
  const [hours, minutes] = time24.split(":").map(Number);
  const hours12 = hours % 12 || 12;
  if (minutes === 0) {
    return `${hours12}`;
  }
  return `${hours12}:${minutes.toString().padStart(2, "0")}`;
}

// Get current time parts in a specific timezone
function getNowInTimezone(tz: string): { dayIndex: number; hours: number; minutes: number } {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: tz,
    hour12: false,
    weekday: "short",
    hour: "numeric",
    minute: "numeric",
  });
  const parts = fmt.formatToParts(new Date());
  const weekday = parts.find((p) => p.type === "weekday")?.value || "";
  const hour = Number(parts.find((p) => p.type === "hour")?.value || 0);
  const minute = Number(parts.find((p) => p.type === "minute")?.value || 0);
  const dayMap: Record<string, number> = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return { dayIndex: dayMap[weekday] ?? new Date().getDay(), hours: hour === 24 ? 0 : hour, minutes: minute };
}

// Get current day name
function getCurrentDayName(tz?: string): DayOfWeek {
  const days: DayOfWeek[] = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
  if (tz) {
    const { dayIndex } = getNowInTimezone(tz);
    return days[dayIndex];
  }
  return days[new Date().getDay()];
}

// Check if current time is within hours
function isOpenNow(hours: HoursEntry | null, tz?: string): boolean {
  if (!hours || !hours.open || !hours.close) return false;

  const { hours: nowH, minutes: nowM } = tz ? getNowInTimezone(tz) : { hours: new Date().getHours(), minutes: new Date().getMinutes() };
  const [openHour, openMin] = hours.open.split(":").map(Number);
  const [closeHour, closeMin] = hours.close.split(":").map(Number);

  const currentMinutes = nowH * 60 + nowM;
  const openMinutes = openHour * 60 + openMin;
  const closeMinutes = closeHour * 60 + closeMin;

  return currentMinutes >= openMinutes && currentMinutes < closeMinutes;
}

// Get current status message
function getCurrentStatus(hoursJson: Record<string, HoursEntry>, tz?: string): string {
  const todayName = getCurrentDayName(tz);
  const todayHours = hoursJson[todayName];

  if (!todayHours?.open || !todayHours?.close) {
    return "Closed today";
  }

  const { hours: nowH, minutes: nowM } = tz ? getNowInTimezone(tz) : { hours: new Date().getHours(), minutes: new Date().getMinutes() };
  const [openHour, openMin] = todayHours.open.split(":").map(Number);
  const [closeHour, closeMin] = todayHours.close.split(":").map(Number);

  const currentMinutes = nowH * 60 + nowM;
  const openMinutes = openHour * 60 + openMin;
  const closeMinutes = closeHour * 60 + closeMin;

  if (currentMinutes < openMinutes) {
    return `Opens at ${formatTime(todayHours.open)}`;
  } else if (currentMinutes < closeMinutes) {
    return `Open until ${formatTime(todayHours.close)}`;
  } else {
    return "Closed for today";
  }
}

// Format hours for display
function formatHoursForDisplay(hoursJson: Record<string, HoursEntry>): Record<string, string> {
  const result: Record<string, string> = {};

  for (const day of DAY_ORDER) {
    const hours = hoursJson[day];
    if (!hours?.open || !hours?.close) {
      result[day] = "Closed";
    } else {
      result[day] = `${formatTime(hours.open)} - ${formatTime(hours.close)}`;
    }
  }

  return result;
}

// Build speakable hours summary
function buildHoursSummary(hoursJson: Record<string, HoursEntry>): string {
  const parts: string[] = [];

  const weekdays = ["monday", "tuesday", "wednesday", "thursday", "friday"] as DayOfWeek[];
  const weekdayHours = weekdays.map((d) => hoursJson[d]);
  const allWeekdaysSame = weekdayHours.every(
    (h) =>
      h?.open === weekdayHours[0]?.open && h?.close === weekdayHours[0]?.close
  );

  if (allWeekdaysSame && weekdayHours[0]?.open && weekdayHours[0]?.close) {
    parts.push(
      `Monday through Friday we're open ${formatTimeForSpeech(weekdayHours[0].open)} to ${formatTimeForSpeech(weekdayHours[0].close)}`
    );
  } else {
    for (const day of weekdays) {
      const h = hoursJson[day];
      if (h?.open && h?.close) {
        parts.push(`${DAY_LABELS[day]} ${formatTimeForSpeech(h.open)} to ${formatTimeForSpeech(h.close)}`);
      }
    }
  }

  const satHours = hoursJson["saturday"];
  if (satHours?.open && satHours?.close) {
    parts.push(`Saturdays ${formatTimeForSpeech(satHours.open)} to ${formatTimeForSpeech(satHours.close)}`);
  } else {
    parts.push("Saturdays we're closed");
  }

  const sunHours = hoursJson["sunday"];
  if (sunHours?.open && sunHours?.close) {
    parts.push(`Sundays ${formatTimeForSpeech(sunHours.open)} to ${formatTimeForSpeech(sunHours.close)}`);
  } else {
    parts.push("we're closed Sundays");
  }

  return parts.join(", ");
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  // Auth: require Authorization header (service key or JWT from ElevenLabs tools)
  const authHeader = req.headers.get("authorization");
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return new Response(
      JSON.stringify({ error: "Unauthorized", message: "I'm having trouble accessing the system." }),
      { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

  try {
    const body: LotInfoRequest = await req.json();
    const { tenant_id, lot_id, tenant_timezone } = body;

    if (!tenant_id) {
      return new Response(
        JSON.stringify({
          error: "tenant_id is required",
          message: "I'm having trouble looking that up. Let me connect you with someone who can help.",
        }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Resolve tenant_id
    let resolvedTenantId = tenant_id;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (!uuidRegex.test(tenant_id)) {
      console.log(`[get-impound-lot-info] tenant_id "${tenant_id}" is not UUID, looking up by name`);
      const resolved = await resolveTenantByName(SUPABASE_URL, SUPABASE_KEY, tenant_id);
      
      if (!resolved) {
        console.error("[get-impound-lot-info] Could not resolve tenant by name");
        return new Response(
          JSON.stringify({
            error: "Could not identify business",
            message: "I'm having trouble accessing our system. Let me connect you with someone who can help.",
          }),
          { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
      
      resolvedTenantId = resolved;
      console.log(`[get-impound-lot-info] Resolved "${tenant_id}" to tenant ${resolvedTenantId}`);
    }

    // Resolve timezone from param or tenant record
    let tz = tenant_timezone || "";
    if (!tz) {
      try {
        const tzResp = await fetch(
          `${SUPABASE_URL}/rest/v1/tenants?id=eq.${resolvedTenantId}&select=timezone`,
          { headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${SUPABASE_KEY}`, "Content-Type": "application/json" } }
        );
        if (tzResp.ok) {
          const tzData = await tzResp.json();
          tz = tzData?.[0]?.timezone || "";
        }
      } catch { /* continue without timezone */ }
    }
    const effectiveTz = tz || undefined;

    // Fetch lot(s)
    const lots = await fetchImpoundLots(SUPABASE_URL, SUPABASE_KEY, resolvedTenantId, lot_id);

    if (!lots || lots.length === 0) {
      return new Response(
        JSON.stringify({
          error: "No impound lot found",
          message: "I don't have lot information available. Let me connect you with someone who can help.",
        }),
        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const lot = lots[0];
    const hoursJson: Record<string, HoursEntry> = lot.hours_json || {};

    // Format address
    const addressParts = [lot.address, lot.city, lot.state, lot.zip].filter(Boolean);
    const fullAddress = addressParts.join(", ");

    // Get current status
    const todayName = getCurrentDayName(effectiveTz);
    const todayHours = hoursJson[todayName];
    const isOpen = isOpenNow(todayHours, effectiveTz);
    const currentStatus = getCurrentStatus(hoursJson, effectiveTz);

    // Format hours
    const formattedHours = formatHoursForDisplay(hoursJson);
    const hoursSummary = buildHoursSummary(hoursJson);

    // Build message
    const messageParts: string[] = [];

    if (fullAddress) {
      messageParts.push(`Our impound lot is at ${fullAddress}.`);
    } else if (lot.name) {
      messageParts.push(`Our lot is called ${lot.name}.`);
    }

    if (isOpen && todayHours?.close) {
      messageParts.push(`We're open today until ${formatTime(todayHours.close)}.`);
    } else if (!isOpen && todayHours?.open) {
      const { hours: nowH } = effectiveTz ? getNowInTimezone(effectiveTz) : { hours: new Date().getHours() };
      const [openHour] = todayHours.open.split(":").map(Number);
      if (nowH < openHour) {
        messageParts.push(`We open today at ${formatTime(todayHours.open)}.`);
      } else {
        messageParts.push(`We're closed for today.`);
      }
    } else {
      messageParts.push(`We're closed today.`);
    }

    messageParts.push(hoursSummary + ".");

    if (lot.phone) {
      messageParts.push(`You can also reach us at ${lot.phone}.`);
    }

    const message = messageParts.join(" ");

    return new Response(
      JSON.stringify({
        lot: {
          id: lot.id,
          name: lot.name,
          address: fullAddress,
          phone: lot.phone,
          is_open_now: isOpen,
          current_status: currentStatus,
        },
        hours: formattedHours,
        message,
      }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("[get-impound-lot-info] Error:", error);
    return new Response(
      JSON.stringify({
        error: error instanceof Error ? error.message : String(error),
        message: "I'm having trouble getting that information right now. Let me connect you with someone who can help.",
      }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

// v2.0.0 - Lightweight fetch-based implementation to avoid cold-start timeouts

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

interface ReleaseInfoRequest {
  tenant_id: string;
  vehicle_id: string;
  tenant_timezone?: string;
}

interface HoursEntry {
  open: string | null;
  close: string | null;
}

type DayOfWeek = "sunday" | "monday" | "tuesday" | "wednesday" | "thursday" | "friday" | "saturday";

const REQUIREMENT_DESCRIPTIONS: Record<string, string> = {
  valid_id: "Valid government-issued photo ID",
  registration: "Vehicle registration or title",
  insurance: "Proof of insurance",
  lien_release: "Lien release from lienholder",
  police_release: "Police release authorization",
  payment: "Payment in full",
};

const PAYMENT_METHOD_LABELS: Record<string, string> = {
  cash: "Cash",
  credit_card: "Credit Card",
  debit_card: "Debit Card",
  check: "Check",
  money_order: "Money Order",
};

// Lookup tenant by name using ilike
async function resolveTenantByName(url: string, key: string, name: string): Promise<string | null> {
  const response = await fetch(
    `${url}/rest/v1/tenants?name=ilike.*${encodeURIComponent(name)}*&select=id&limit=1`,
    {
      headers: {
        apikey: key,
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
    }
  );

  if (!response.ok) return null;
  const data = await response.json();
  return data?.[0]?.id || null;
}

// Fetch vehicle with lot info
async function fetchVehicleWithLot(url: string, key: string, vehicleId: string, tenantId: string): Promise<any | null> {
  const response = await fetch(
    `${url}/rest/v1/impound_vehicles?id=eq.${vehicleId}&tenant_id=eq.${tenantId}&select=*,impound_lots(id,name,address,city,state,zip,phone,hours_json)`,
    {
      headers: {
        apikey: key,
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
    }
  );

  if (!response.ok) return null;
  const data = await response.json();
  return data?.[0] || null;
}

// Fetch impound settings
async function fetchImpoundSettings(url: string, key: string, tenantId: string): Promise<any | null> {
  const response = await fetch(
    `${url}/rest/v1/impound_settings?tenant_id=eq.${tenantId}&select=*`,
    {
      headers: {
        apikey: key,
        Authorization: `Bearer ${key}`,
        "Content-Type": "application/json",
      },
    }
  );

  if (!response.ok) return null;
  const data = await response.json();
  return data?.[0] || null;
}

// Update vehicle fees
async function updateVehicleFees(
  url: string,
  key: string,
  vehicleId: string,
  updates: Record<string, any>
): Promise<void> {
  await fetch(`${url}/rest/v1/impound_vehicles?id=eq.${vehicleId}`, {
    method: "PATCH",
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      "Content-Type": "application/json",
      Prefer: "return=minimal",
    },
    body: JSON.stringify(updates),
  });
}

// Format cents to dollars string
function formatCurrency(cents: number): string {
  return `$${(cents / 100).toFixed(2)}`;
}

// Format cents to speakable dollars
function formatCurrencyForSpeech(cents: number): string {
  const dollars = cents / 100;
  if (dollars === Math.floor(dollars)) {
    return `$${Math.floor(dollars)}`;
  }
  return `$${dollars.toFixed(2)}`;
}

// Calculate days between two dates
function daysBetween(date1: Date, date2: Date): number {
  const oneDay = 24 * 60 * 60 * 1000;
  return Math.max(0, Math.floor((date2.getTime() - date1.getTime()) / oneDay));
}

// Get current time parts in a specific timezone
function getNowInTimezone(tz: string): { dayIndex: number; hours: number; minutes: number } {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: tz,
    hour12: false,
    weekday: "short",
    hour: "numeric",
    minute: "numeric",
  });
  const parts = fmt.formatToParts(new Date());
  const weekday = parts.find((p) => p.type === "weekday")?.value || "";
  const hour = Number(parts.find((p) => p.type === "hour")?.value || 0);
  const minute = Number(parts.find((p) => p.type === "minute")?.value || 0);
  const dayMap: Record<string, number> = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  return { dayIndex: dayMap[weekday] ?? new Date().getDay(), hours: hour === 24 ? 0 : hour, minutes: minute };
}

// Get current day name
function getCurrentDayName(tz?: string): DayOfWeek {
  const days: DayOfWeek[] = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
  if (tz) {
    const { dayIndex } = getNowInTimezone(tz);
    return days[dayIndex];
  }
  return days[new Date().getDay()];
}

// Format time from 24h to 12h AM/PM
function formatTime(time24: string): string {
  const [hours, minutes] = time24.split(":").map(Number);
  const period = hours >= 12 ? "PM" : "AM";
  const hours12 = hours % 12 || 12;
  if (minutes === 0) {
    return `${hours12} ${period}`;
  }
  return `${hours12}:${minutes.toString().padStart(2, "0")} ${period}`;
}

// Check if current time is within hours
function isOpenNow(hours: HoursEntry | null, tz?: string): boolean {
  if (!hours || !hours.open || !hours.close) return false;

  const { hours: nowH, minutes: nowM } = tz ? getNowInTimezone(tz) : { hours: new Date().getHours(), minutes: new Date().getMinutes() };
  const [openHour, openMin] = hours.open.split(":").map(Number);
  const [closeHour, closeMin] = hours.close.split(":").map(Number);

  const currentMinutes = nowH * 60 + nowM;
  const openMinutes = openHour * 60 + openMin;
  const closeMinutes = closeHour * 60 + closeMin;

  return currentMinutes >= openMinutes && currentMinutes < closeMinutes;
}

// Find next open time
function findNextOpen(hoursJson: Record<string, HoursEntry>, tz?: string): string | null {
  const days: DayOfWeek[] = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
  const dayLabels = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
  const today = tz ? getNowInTimezone(tz).dayIndex : new Date().getDay();

  const todayName = days[today];
  const todayHours = hoursJson[todayName];
  if (todayHours?.open && todayHours?.close) {
    const { hours: nowH, minutes: nowM } = tz ? getNowInTimezone(tz) : { hours: new Date().getHours(), minutes: new Date().getMinutes() };
    const [openHour, openMin] = todayHours.open.split(":").map(Number);
    const openMinutes = openHour * 60 + openMin;
    const currentMinutes = nowH * 60 + nowM;
    if (currentMinutes < openMinutes) {
      return `Today at ${formatTime(todayHours.open)}`;
    }
  }

  for (let i = 1; i <= 7; i++) {
    const checkDay = (today + i) % 7;
    const dayName = days[checkDay];
    const dayHours = hoursJson[dayName];

    if (dayHours?.open) {
      const dayLabel = i === 1 ? "Tomorrow" : dayLabels[checkDay];
      return `${dayLabel} at ${formatTime(dayHours.open)}`;
    }
  }

  return null;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  // Auth: require Authorization header (service key or JWT from ElevenLabs tools)
  const authHeader = req.headers.get("authorization");
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    return new Response(
      JSON.stringify({ error: "Unauthorized", message: "I'm having trouble accessing the system." }),
      { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
  const SUPABASE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

  try {
    const body: ReleaseInfoRequest = await req.json();
    const { tenant_id, vehicle_id, tenant_timezone } = body;

    if (!tenant_id || !vehicle_id) {
      return new Response(
        JSON.stringify({
          error: "tenant_id and vehicle_id are required",
          message: "I need more information to look up those details. Can you give me the vehicle information again?",
        }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Resolve tenant_id
    let resolvedTenantId = tenant_id;
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    if (!uuidRegex.test(tenant_id)) {
      console.log(`[get-impound-release-info] tenant_id "${tenant_id}" is not UUID, looking up by name`);
      const resolved = await resolveTenantByName(SUPABASE_URL, SUPABASE_KEY, tenant_id);
      
      if (!resolved) {
        console.error("[get-impound-release-info] Could not resolve tenant by name");
        return new Response(
          JSON.stringify({
            error: "Could not identify business",
            message: "I'm having trouble accessing our system. Let me connect you with someone who can help.",
          }),
          { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
      
      resolvedTenantId = resolved;
      console.log(`[get-impound-release-info] Resolved "${tenant_id}" to tenant ${resolvedTenantId}`);
    }

    // Resolve timezone from param or tenant record
    let tz = tenant_timezone || "";
    if (!tz) {
      try {
        const tzResp = await fetch(
          `${SUPABASE_URL}/rest/v1/tenants?id=eq.${resolvedTenantId}&select=timezone`,
          { headers: { apikey: SUPABASE_KEY, Authorization: `Bearer ${SUPABASE_KEY}`, "Content-Type": "application/json" } }
        );
        if (tzResp.ok) {
          const tzData = await tzResp.json();
          tz = tzData?.[0]?.timezone || "";
        }
      } catch { /* continue without timezone */ }
    }
    const effectiveTz = tz || undefined;

    // Load vehicle with lot info
    const vehicle = await fetchVehicleWithLot(SUPABASE_URL, SUPABASE_KEY, vehicle_id, resolvedTenantId);

    if (!vehicle) {
      console.error("[get-impound-release-info] Vehicle not found");
      return new Response(
        JSON.stringify({
          error: "Vehicle not found",
          message: "I couldn't find that vehicle in our system. Let me search for it again. What's the license plate number?",
        }),
        { status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Load tenant settings
    const settings = await fetchImpoundSettings(SUPABASE_URL, SUPABASE_KEY, resolvedTenantId);

    // Use defaults if no settings
    const effectiveSettings = settings || {
      base_tow_fee_cents: 15000,
      daily_storage_cents: 3500,
      gate_fee_cents: 5000,
      admin_fee_cents: 2500,
      accepted_payment: ["cash", "credit_card", "debit_card"],
      default_release_requirements: ["valid_id", "registration", "payment"],
      release_hours_json: null,
    };

    // Calculate fees
    const towedAt = new Date(vehicle.towed_at);
    const now = new Date();
    const daysStored = Math.max(1, daysBetween(towedAt, now));

    const baseTow = vehicle.base_tow_fee_cents || effectiveSettings.base_tow_fee_cents;
    const storagePerDay = vehicle.storage_fee_daily_cents || effectiveSettings.daily_storage_cents;
    const storageTotal = daysStored * storagePerDay;
    const adminFee = vehicle.admin_fee_cents || effectiveSettings.admin_fee_cents;
    const gateFee = vehicle.gate_fee_cents || effectiveSettings.gate_fee_cents;
    const additionalFees = vehicle.additional_fees_cents || 0;
    const totalCents = baseTow + storageTotal + adminFee + gateFee + additionalFees;

    // Update vehicle record if fees changed
    if (
      vehicle.days_stored !== daysStored ||
      vehicle.total_storage_cents !== storageTotal ||
      vehicle.total_fees_cents !== totalCents
    ) {
      await updateVehicleFees(SUPABASE_URL, SUPABASE_KEY, vehicle_id, {
        days_stored: daysStored,
        total_storage_cents: storageTotal,
        total_fees_cents: totalCents,
        updated_at: new Date().toISOString(),
      });
    }

    // Get release requirements
    const requirements = (vehicle.release_requirements || effectiveSettings.default_release_requirements || []).map(
      (item: string) => ({
        item,
        description: REQUIREMENT_DESCRIPTIONS[item] || item,
      })
    );

    // Get payment methods
    const paymentMethods = effectiveSettings.accepted_payment || ["cash", "credit_card", "debit_card"];

    // Get lot info and hours
    const lot = vehicle.impound_lots;
    const releaseHours = effectiveSettings.release_hours_json || lot?.hours_json;
    const todayName = getCurrentDayName(effectiveTz);
    const todayHours: HoursEntry | null = releaseHours?.[todayName] || null;
    const isOpen = isOpenNow(todayHours, effectiveTz);

    // Format hours for today
    let hoursToday = "Closed";
    if (todayHours?.open && todayHours?.close) {
      hoursToday = `${formatTime(todayHours.open)} - ${formatTime(todayHours.close)}`;
    }

    // Find next open if currently closed
    let nextOpen: string | null = null;
    if (!isOpen && releaseHours) {
      nextOpen = findNextOpen(releaseHours, effectiveTz);
    }

    // Format lot address
    const lotAddressParts = lot
      ? [lot.address, lot.city, lot.state, lot.zip].filter(Boolean)
      : [];
    const lotAddress = lotAddressParts.join(", ");

    // Build speakable message
    const messageParts: string[] = [];

    messageParts.push(`The total to release your vehicle is ${formatCurrencyForSpeech(totalCents)}.`);

    const breakdownParts: string[] = [];
    breakdownParts.push(`the ${formatCurrencyForSpeech(baseTow)} tow fee`);
    if (daysStored > 0) {
      breakdownParts.push(`${formatCurrencyForSpeech(storageTotal)} for ${daysStored} day${daysStored > 1 ? "s" : ""} of storage`);
    }
    if (adminFee > 0 || gateFee > 0) {
      breakdownParts.push("fees");
    }
    messageParts.push(`That includes ${breakdownParts.join(" plus ")}.`);

    const reqDescriptions = requirements
      .filter((r: { item: string }) => r.item !== "payment")
      .map((r: { description: string }) => r.description.toLowerCase().replace("valid ", ""));
    if (reqDescriptions.length > 0) {
      messageParts.push(`You'll need to bring ${reqDescriptions.join(" and ")}.`);
    }

    const paymentLabels = paymentMethods.map((m: string) => PAYMENT_METHOD_LABELS[m] || m).join(" or ");
    messageParts.push(`We accept ${paymentLabels.toLowerCase()}.`);

    if (isOpen) {
      const closeTime = todayHours?.close ? formatTime(todayHours.close) : "close";
      messageParts.push(`The lot is open today until ${closeTime}`);
      if (lotAddress) {
        messageParts.push(`and is located at ${lotAddress}.`);
      }
    } else {
      if (nextOpen) {
        messageParts.push(`The lot is currently closed but opens ${nextOpen.toLowerCase()}.`);
      } else {
        messageParts.push(`The lot is currently closed.`);
      }
      if (lotAddress) {
        messageParts.push(`Would you like the address so you know where to go? It's at ${lotAddress}.`);
      }
    }

    const message = messageParts.join(" ");

    return new Response(
      JSON.stringify({
        vehicle_id,
        fees: {
          base_tow: baseTow,
          storage_days: daysStored,
          storage_per_day: storagePerDay,
          storage_total: storageTotal,
          admin_fee: adminFee,
          gate_fee: gateFee,
          additional_fees: additionalFees,
          total_cents: totalCents,
          total_formatted: formatCurrency(totalCents),
        },
        requirements,
        payment_methods: paymentMethods,
        lot: lot
          ? {
              name: lot.name,
              address: lotAddress,
              phone: lot.phone,
              is_open_now: isOpen,
              hours_today: hoursToday,
              next_open: nextOpen,
            }
          : null,
        message,
      }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("[get-impound-release-info] Error:", error);
    return new Response(
      JSON.stringify({
        error: error instanceof Error ? error.message : String(error),
        message: "I'm having trouble getting that information. Let me connect you with someone who can help.",
      }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

/**
 * get-intelligence-dashboard
 * 
 * API endpoint that returns aggregated intelligence data for the UI.
 * Includes metrics, active insights, top patterns, and AI health score.
 */

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseAnonKey = Deno.env.get("SUPABASE_ANON_KEY")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    // Verify user auth
    const userClient = createClient(supabaseUrl, supabaseAnonKey, {
      global: { headers: { Authorization: authHeader } },
    });
    const { data: { user }, error: authError } = await userClient.auth.getUser();
    if (authError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Get tenant ID from request body or query
    const url = new URL(req.url);
    let tenantId = url.searchParams.get("tenant_id");
    
    if (!tenantId && req.method === "POST") {
      const body = await req.json().catch(() => ({}));
      tenantId = body.tenantId;
    }

    if (!tenantId) {
      // Get user's primary tenant
      const { data: tenantUser } = await userClient
        .from("tenant_users")
        .select("tenant_id")
        .eq("user_id", user.id)
        .limit(1)
        .maybeSingle();
      
      tenantId = tenantUser?.tenant_id;
    }

    if (!tenantId) {
      return new Response(JSON.stringify({ error: "No tenant found" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // Calculate time ranges
    const now = new Date();
    const last7Days = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString();
    const last30Days = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString();

    // Get call outcomes for metrics
    const { data: outcomes } = await supabase
      .from("call_outcomes")
      .select("*")
      .eq("tenant_id", tenantId)
      .gte("created_at", last7Days);

    const outcomesList = outcomes || [];
    const totalCalls = outcomesList.length;
    const aiHandledCalls = outcomesList.filter(o => o.ai_handled_fully).length;
    const conversions = outcomesList.filter(o => 
      ["booked", "order_placed", "dispatch_created"].includes(o.outcome_type)
    ).length;

    // AI Health Score (0-100)
    const aiHealthScore = totalCalls > 0 
      ? Math.round((aiHandledCalls / totalCalls) * 100)
      : 100; // Default to 100 if no calls

    // Get active insights
    const { data: insights } = await supabase
      .from("intelligence_insights")
      .select("*")
      .eq("tenant_id", tenantId)
      .eq("is_actioned", false)
      .order("severity", { ascending: false })
      .order("created_at", { ascending: false })
      .limit(10);

    const unreadCount = (insights || []).filter(i => !i.is_read).length;

    // Get top patterns
    const { data: patterns } = await supabase
      .from("business_patterns")
      .select("*")
      .eq("tenant_id", tenantId)
      .eq("is_dismissed", false)
      .gte("confidence_score", 0.6)
      .order("confidence_score", { ascending: false })
      .limit(5);

    // Get recent knowledge gaps
    const { data: gaps } = await supabase
      .from("knowledge_gaps")
      .select("*")
      .eq("tenant_id", tenantId)
      .eq("is_resolved", false)
      .order("occurrence_count", { ascending: false })
      .limit(5);

    // Get latest digest
    const { data: digest } = await supabase
      .from("intelligence_digest")
      .select("*")
      .eq("tenant_id", tenantId)
      .eq("digest_type", "weekly")
      .order("period_end", { ascending: false })
      .limit(1)
      .maybeSingle();

    // Build response
    const response = {
      metrics: {
        period: "last_7_days",
        totalCalls,
        aiHandledCalls,
        aiHealthScore,
        conversions,
        conversionRate: totalCalls > 0 ? (conversions / totalCalls) : 0,
      },
      insights: {
        items: insights || [],
        unreadCount,
        totalActive: (insights || []).length,
      },
      patterns: patterns || [],
      gaps: gaps || [],
      latestDigest: digest,
    };

    return new Response(JSON.stringify(response), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });

  } catch (error) {
    console.error("[get-intelligence-dashboard] Error:", error);
    return new Response(JSON.stringify({ error: (error as Error).message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { requireAuthedTenant, requireAuthedUser } from "../_shared/tenant.ts";

/**
 * import-business-website
 *
 * Accepts a URL, fetches the page, extracts text, sends it to Claude for
 * structured business-data extraction, and returns a preview payload for
 * the user to confirm before anything is written to the database.
 *
 * POST { url: string, tenant_id: string }
 * Auth: JWT via requireAuthedTenant
 */

interface ExtractedService {
  name: string;
  description: string;
  price_amount: number | null;
  duration_minutes: number | null;
}

interface ExtractedFAQ {
  question: string;
  answer: string;
}

interface DayHours {
  open: string;
  close: string;
  is_open: boolean;
}

interface ExtractedHours {
  monday: DayHours;
  tuesday: DayHours;
  wednesday: DayHours;
  thursday: DayHours;
  friday: DayHours;
  saturday: DayHours;
  sunday: DayHours;
}

interface ExtractionResult {
  business_name: string;
  phone: string | null;
  address: string | null;
  hours: ExtractedHours | null;
  services: ExtractedService[];
  faqs: ExtractedFAQ[];
  description: string;
  suggested_industry: string;
  suggested_business_mode: string;
}

/** Basic URL validation — must start with http(s):// and have a domain. */
function isValidUrl(raw: string): boolean {
  try {
    const parsed = new URL(raw);
    return parsed.protocol === "http:" || parsed.protocol === "https:";
  } catch {
    return false;
  }
}

/** Strip HTML tags, collapse whitespace, decode common entities. */
function htmlToPlainText(html: string): string {
  // Remove script and style blocks entirely
  let text = html.replace(/<script[\s\S]*?<\/script>/gi, " ");
  text = text.replace(/<style[\s\S]*?<\/style>/gi, " ");
  // Remove HTML comments
  text = text.replace(/<!--[\s\S]*?-->/g, " ");
  // Replace block-level tags with newlines for readability
  text = text.replace(/<\/(p|div|h[1-6]|li|tr|br|hr)[^>]*>/gi, "\n");
  text = text.replace(/<br\s*\/?>/gi, "\n");
  // Strip remaining tags
  text = text.replace(/<[^>]+>/g, " ");
  // Decode common HTML entities
  text = text.replace(/&amp;/g, "&");
  text = text.replace(/&lt;/g, "<");
  text = text.replace(/&gt;/g, ">");
  text = text.replace(/&quot;/g, '"');
  text = text.replace(/&#39;/g, "'");
  text = text.replace(/&nbsp;/g, " ");
  text = text.replace(/&#\d+;/g, " ");
  // Collapse whitespace
  text = text.replace(/[ \t]+/g, " ");
  text = text.replace(/\n{3,}/g, "\n\n");
  return text.trim();
}

const EXTRACTION_PROMPT = `You are a business information extraction assistant. Analyze the following website text and extract structured business information.

Return a single JSON object with these fields:
{
  "business_name": "string — the business name",
  "phone": "string or null — primary phone number if found",
  "address": "string or null — full street address if found",
  "hours": {
    "monday":    { "open": "09:00", "close": "17:00", "is_open": true },
    "tuesday":   { "open": "09:00", "close": "17:00", "is_open": true },
    "wednesday": { "open": "09:00", "close": "17:00", "is_open": true },
    "thursday":  { "open": "09:00", "close": "17:00", "is_open": true },
    "friday":    { "open": "09:00", "close": "17:00", "is_open": true },
    "saturday":  { "open": "10:00", "close": "14:00", "is_open": true },
    "sunday":    { "open": "00:00", "close": "00:00", "is_open": false }
  },
  "services": [
    {
      "name": "string — service name",
      "description": "string — brief description",
      "price_amount": null,
      "duration_minutes": null
    }
  ],
  "faqs": [
    { "question": "string", "answer": "string" }
  ],
  "description": "string — a 1-3 sentence summary of what this business does",
  "suggested_industry": "string — closest slug from: plumbing, hvac, electrical, roofing, painting, flooring, cleaning, landscaping, pest_control, pool_service, auto_detailing, tire_shop, auto_repair, towing, salon, barbershop, spa, massage, medspa, dental, chiropractor, optometry, physical_therapy, restaurant, pizza, bakery, coffee_shop, catering, personal_training, photography, accounting, law_firm, real_estate, veterinary, pet_grooming, car_wash, locksmith, moving, gym, yoga_studio, martial_arts, tattoo, other",
  "suggested_business_mode": "string — one of: service, dispatch, food, medical, general"
}

Rules:
- Use 24-hour time format for hours (e.g. "09:00", "17:00").
- If hours are not found on the page, set "hours" to null.
- If a specific day's hours are unknown, set is_open to true with reasonable defaults (09:00-17:00).
- For services, extract every distinct service or offering you can identify. Set price_amount to a number (dollars, not cents) if listed, otherwise null. Set duration_minutes if listed, otherwise null.
- For FAQs, generate useful Q&A pairs from the website content — things a caller might ask. Include at least 3 if there is enough information.
- For phone and address, extract if clearly present; otherwise null.
- For "suggested_industry", pick the closest slug from the list. Use "other" if nothing fits.
- For "suggested_business_mode": "service" for appointment/booking businesses, "dispatch" for delivery/towing/logistics, "food" for restaurants/cafes/bakeries, "medical" for healthcare, "general" otherwise.
- Return ONLY the JSON object, no markdown fences, no extra text.`;

serve(async (req) => {
  // Handle CORS preflight
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    // Parse and validate body
    const body = await req.json();
    const { url, tenant_id } = body as { url?: string; tenant_id?: string };

    if (!url || typeof url !== "string") {
      return errorResponse("Missing required field: url");
    }
    if (!isValidUrl(url)) {
      return errorResponse("Invalid URL — must start with http:// or https://");
    }

    // Authenticate caller — tenant_id optional (onboarding flow has no tenant yet)
    if (tenant_id) {
      await requireAuthedTenant(req, tenant_id);
    } else {
      await requireAuthedUser(req);
    }

    // ---- Step 1: Fetch the website ----
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 10_000);

    let htmlContent: string;
    try {
      const siteResponse = await fetch(url, {
        headers: {
          "User-Agent":
            "Mozilla/5.0 (compatible; CloseLoopBot/1.0; +https://closeloop.ai)",
          Accept: "text/html,application/xhtml+xml,*/*",
        },
        signal: controller.signal,
        redirect: "follow",
      });
      clearTimeout(timeout);

      if (!siteResponse.ok) {
        return errorResponse(
          `Failed to fetch URL (HTTP ${siteResponse.status}): ${siteResponse.statusText}`,
          422,
        );
      }

      htmlContent = await siteResponse.text();
    } catch (fetchErr: unknown) {
      clearTimeout(timeout);
      const msg =
        fetchErr instanceof DOMException && fetchErr.name === "AbortError"
          ? "Request timed out after 10 seconds"
          : fetchErr instanceof Error
            ? fetchErr.message
            : "Unknown fetch error";
      return errorResponse(`Could not fetch URL: ${msg}`, 422);
    }

    // ---- Step 2: Convert HTML to plain text and truncate ----
    let plainText = htmlToPlainText(htmlContent);
    if (plainText.length > 15_000) {
      plainText = plainText.substring(0, 15_000) + "\n[...truncated]";
    }

    if (plainText.length < 50) {
      return errorResponse(
        "The page returned very little readable text. It may be a single-page app that requires JavaScript rendering.",
        422,
      );
    }

    // ---- Step 3: Call Anthropic Claude for extraction ----
    const anthropicApiKey = Deno.env.get("ANTHROPIC_API_KEY");
    if (!anthropicApiKey) {
      return errorResponse("ANTHROPIC_API_KEY is not configured", 500);
    }

    const claudeResponse = await fetch(
      "https://api.anthropic.com/v1/messages",
      {
        method: "POST",
        headers: {
          "x-api-key": anthropicApiKey,
          "anthropic-version": "2023-06-01",
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: "claude-sonnet-4-5-20250929",
          max_tokens: 4096,
          messages: [
            {
              role: "user",
              content: `${EXTRACTION_PROMPT}\n\n--- WEBSITE TEXT ---\n${plainText}`,
            },
          ],
        }),
      },
    );

    if (!claudeResponse.ok) {
      const errBody = await claudeResponse.text();
      console.error(
        "Anthropic API error:",
        claudeResponse.status,
        errBody,
      );
      return errorResponse(
        `AI extraction failed (HTTP ${claudeResponse.status})`,
        502,
      );
    }

    const claudeData = await claudeResponse.json();
    const assistantText: string =
      claudeData?.content?.[0]?.text ?? "";

    if (!assistantText) {
      return errorResponse("AI returned an empty response", 502);
    }

    // ---- Step 4: Parse the JSON from Claude's response ----
    let extracted: ExtractionResult;
    try {
      // Strip possible markdown fences just in case
      const jsonString = assistantText
        .replace(/^```json\s*/i, "")
        .replace(/^```\s*/i, "")
        .replace(/\s*```$/i, "")
        .trim();
      extracted = JSON.parse(jsonString);
    } catch {
      console.error("Failed to parse Claude response as JSON:", assistantText.substring(0, 500));
      return errorResponse(
        "AI returned data that could not be parsed. Please try a different URL.",
        422,
      );
    }

    // Ensure required fields have sane defaults
    const result: ExtractionResult = {
      business_name: extracted.business_name || "Unknown Business",
      phone: extracted.phone || null,
      address: extracted.address || null,
      hours: extracted.hours || null,
      services: Array.isArray(extracted.services) ? extracted.services : [],
      faqs: Array.isArray(extracted.faqs) ? extracted.faqs : [],
      description: extracted.description || "",
      suggested_industry: extracted.suggested_industry || "other",
      suggested_business_mode: extracted.suggested_business_mode || "service",
    };

    return jsonResponse({
      success: true,
      source_url: url,
      extracted: result,
    });
  } catch (err: unknown) {
    console.error("import-business-website error:", err);
    const message =
      err instanceof Error ? err.message : "Internal server error";

    // Auth errors → 401
    if (
      message.includes("Unauthorized") ||
      message.includes("Missing Authorization")
    ) {
      return errorResponse(message, 401);
    }
    if (message.includes("Forbidden")) {
      return errorResponse(message, 403);
    }

    return errorResponse(message, 500);
  }
});

