    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    const anonClient = createClient(
      supabaseUrl,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } } }
    );
    const { data: { user }, error: userError } = await anonClient.auth.getUser();
    if (userError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Verify super_admin role
    const { data: roleData } = await supabase
      .from("user_roles")
      .select("role")
      .eq("user_id", user.id)
      .eq("role", "super_admin")
      .maybeSingle();

    if (!roleData) {
      return new Response(JSON.stringify({ error: "Forbidden — super_admin only" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { messages, category = "general" } = await req.json();

    if (!messages || !Array.isArray(messages) || messages.length === 0) {
      return new Response(JSON.stringify({ error: "messages array is required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Get current platform stats
    let platformStats = "";
    try {
      const [tenantsRes, usersRes, agenciesRes] = await Promise.all([
        supabase.from("tenants").select("id", { count: "exact", head: true }),
        supabase.from("tenant_users").select("user_id", { count: "exact", head: true }),
        supabase.from("agency_accounts").select("id", { count: "exact", head: true }),
      ]);
      platformStats = `
Current Platform Stats:
- Total tenants: ${tenantsRes.count ?? 0}
- Total users: ${usersRes.count ?? 0}
- Total agencies: ${agenciesRes.count ?? 0}
`;
    } catch {
      // Stats are nice to have, not critical
    }

    const categoryPrompt = CATEGORY_SYSTEM_PROMPTS[category] || CATEGORY_SYSTEM_PROMPTS.general;
    const systemPrompt = `${categoryPrompt}

${PRODUCT_CONTEXT}

${platformStats}

Important guidelines:
- Always ground your advice in CloseLoop's specific product, market, and competitive position
- Be specific and actionable — provide actual copy, numbers, and timelines when possible
- Format your responses clearly with headers, bullet points, and sections
- When suggesting metrics, provide realistic benchmarks for B2B SaaS targeting SMBs
- Tailor advice to the current scale of the platform (use the stats above)`;

    const apiMessages = [
      { role: "system", content: systemPrompt },
      ...messages.map((m: any) => ({ role: m.role, content: m.content })),
    ];

    // Use the AI gateway
    const res = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: "gpt-4o-mini",
        messages: apiMessages,
        temperature: 0.7,
        max_tokens: 4096,
      }),
    });

    if (!res.ok) {
      const errorText = await res.text();
      console.error(`[marketing-chat] AI gateway error ${res.status}:`, errorText);
      throw new Error(`AI gateway returned ${res.status}`);
    }

    const data = await res.json();
    const content = data.choices?.[0]?.message?.content || "";

    return new Response(
      JSON.stringify({ content }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("[marketing-chat] Error:", error);
    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Unknown error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsHeaders, jsonResponse, errorResponse, corsResponse } from "../_shared/cors.ts";

interface NotifyJobUpdateRequest {
  job_id: string;
  event_type: "step_complete" | "all_complete" | "status_change";
  message?: string;
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const { job_id, event_type, message } = (await req.json()) as NotifyJobUpdateRequest;

    if (!job_id || !event_type) {
      return errorResponse("Missing required fields: job_id, event_type");
    }

    // Fetch the job
    const { data: job, error: jobError } = await supabase
      .from("active_jobs")
      .select("*")
      .eq("id", job_id)
      .single();

    if (jobError || !job) {
      return errorResponse("Job not found", 404);
    }

    // Check per-job notification toggles
    const shouldNotify =
      (event_type === "step_complete" && job.notify_on_step_complete) ||
      (event_type === "all_complete" && job.notify_on_all_complete) ||
      event_type === "status_change";

    if (!shouldNotify) {
      return jsonResponse({ notified: false, reason: "notification_disabled" });
    }

    // Check tenant-level notification preferences
    const { data: prefs } = await supabase
      .from("notification_preferences")
      .select("*")
      .eq("tenant_id", job.tenant_id)
      .maybeSingle();

    // Build notification message
    let notificationMessage = message || "";
    if (!notificationMessage) {
      const { data: tenant } = await supabase
        .from("tenants")
        .select("business_name")
        .eq("id", job.tenant_id)
        .single();

      const bizName = tenant?.business_name || "Our shop";

      switch (event_type) {
        case "step_complete":
          notificationMessage = `${bizName}: A service step has been completed on your ${job.title}. We'll keep you updated!`;
          break;
        case "all_complete":
          notificationMessage = `${bizName}: Great news! All work on your ${job.title} is complete. It's ready for pickup!`;
          break;
        case "status_change":
          notificationMessage = `${bizName}: Your ${job.title} status has been updated to ${job.status.replace("_", " ")}.`;
          break;
      }
    }

    // Log the update
    await supabase.from("job_status_updates").insert({
      job_id: job.id,
      tenant_id: job.tenant_id,
      previous_status: job.status,
      new_status: job.status,
      message: notificationMessage,
      triggered_notification: true,
    });

    // Route through universal-delivery if customer phone is available
    if (job.customer_phone) {
      try {
        const deliveryPayload = {
          tenant_id: job.tenant_id,
          entity_type: "job_update",
          entity_id: job.id,
          notification_message: notificationMessage,
          customer_phone: job.customer_phone,
          customer_name: job.customer_name || "Customer",
          event_type,
        };

        // Call universal-delivery
        const deliveryUrl = `${supabaseUrl}/functions/v1/universal-delivery`;
        await fetch(deliveryUrl, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${supabaseServiceKey}`,
          },
          body: JSON.stringify({
            tenant_id: job.tenant_id,
            entity_type: "job_update",
            entity_id: job.id,
          }),
        });
      } catch (deliveryError) {
        console.error("[notify-job-update] Delivery failed:", deliveryError);
        // Non-fatal — notification was still logged
      }
    }

    return jsonResponse({
      notified: true,
      event_type,
      job_id: job.id,
      customer_phone: job.customer_phone,
    });
  } catch (err) {
    console.error("[notify-job-update] Error:", err);
    return errorResponse("Internal server error", 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface JobLocation {
  id: string;
  name?: string;
  latitude: number;
  longitude: number;
  duration_minutes?: number; // Estimated time at stop
  time_window?: {
    start: string; // ISO timestamp
    end: string;
  };
}

interface OptimizeRouteRequest {
  technician_id: string;
  start_location?: {
    latitude: number;
    longitude: number;
  };
  end_location?: {
    latitude: number;
    longitude: number;
  };
  jobs: JobLocation[];
  profile?: "driving" | "driving-traffic" | "walking" | "cycling";
  roundtrip?: boolean;
}

interface OptimizedStop {
  job_id: string;
  name?: string;
  latitude: number;
  longitude: number;
  sequence: number;
  arrival_time?: string;
  departure_time?: string;
  distance_meters: number;
  duration_seconds: number;
}

interface OptimizeRouteResponse {
  success: boolean;
  optimized_route: OptimizedStop[];
  total_distance_meters: number;
  total_duration_seconds: number;
  waypoints_order: string[];
  geometry?: string; // Encoded polyline
}

serve(async (req) => {
  // Handle CORS preflight
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    // Auth: require Authorization header (service key or JWT)
    const authHeader = req.headers.get("authorization");
    if (!authHeader || !authHeader.startsWith("Bearer ")) {
      return new Response(
        JSON.stringify({ error: "Unauthorized: missing authorization header" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const payload: OptimizeRouteRequest = await req.json();
    const { jobs, start_location, end_location, profile = "driving", roundtrip = false } = payload;

    if (!jobs || jobs.length === 0) {
      return new Response(
        JSON.stringify({ error: "No jobs provided for optimization" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const mapboxToken = Deno.env.get("MAPBOX_ACCESS_TOKEN");
    if (!mapboxToken) {
      return new Response(
        JSON.stringify({ error: "Mapbox access token not configured" }),
        { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Build coordinates string for Mapbox API
    // Format: lon1,lat1;lon2,lat2;...
    const coordinates: string[] = [];
    const distributionIndices: number[] = [];

    // Add start location (depot)
    if (start_location) {
      coordinates.push(`${start_location.longitude},${start_location.latitude}`);
    } else if (jobs.length > 0) {
      // Use first job as start if no start specified
      coordinates.push(`${jobs[0].longitude},${jobs[0].latitude}`);
    }

    // Add job locations
    for (let i = 0; i < jobs.length; i++) {
      const job = jobs[i];
      coordinates.push(`${job.longitude},${job.latitude}`);
      distributionIndices.push(coordinates.length - 1);
    }

    // Add end location if different from start and roundtrip is false
    if (end_location && !roundtrip) {
      coordinates.push(`${end_location.longitude},${end_location.latitude}`);
    }

    // If only 1-2 jobs, no optimization needed
    if (jobs.length <= 2) {
      const optimizedRoute: OptimizedStop[] = jobs.map((job, index) => ({
        job_id: job.id,
        name: job.name,
        latitude: job.latitude,
        longitude: job.longitude,
        sequence: index + 1,
        distance_meters: 0,
        duration_seconds: 0,
      }));

      return new Response(
        JSON.stringify({
          success: true,
          optimized_route: optimizedRoute,
          total_distance_meters: 0,
          total_duration_seconds: 0,
          waypoints_order: jobs.map((j) => j.id),
          message: "Route has 2 or fewer stops, no optimization needed",
        } as OptimizeRouteResponse),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Call Mapbox Optimization API
    const mapboxProfile = profile === "driving-traffic" ? "mapbox/driving-traffic" : `mapbox/${profile}`;
    const coordinatesStr = coordinates.join(";");

    // Build distributions parameter (which jobs to visit)
    // Format: pickup_index,delivery_index;... but for simple stops: 0,1;0,2;0,3 (depot to each stop)
    const distributions = distributionIndices.map((idx) => `0,${idx}`).join(";");

    // Use the Optimization API v1
    const optimizationUrl = `https://api.mapbox.com/optimized-trips/v1/${mapboxProfile}/${coordinatesStr}?` +
      new URLSearchParams({
        access_token: mapboxToken,
        roundtrip: roundtrip.toString(),
        source: "first",
        destination: roundtrip ? "last" : (end_location ? "last" : "any"),
        geometries: "polyline",
        overview: "full",
      });

    console.log("Calling Mapbox Optimization API...");

    const response = await fetch(optimizationUrl);
    const data = await response.json();

    if (data.code !== "Ok") {
      console.error("Mapbox API error:", data);
      return new Response(
        JSON.stringify({
          error: "Route optimization failed",
          details: data.message || data.code
        }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Extract the optimized trip
    const trip = data.trips?.[0];
    if (!trip) {
      return new Response(
        JSON.stringify({ error: "No optimized trip returned" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Map waypoints back to jobs
    const waypoints = data.waypoints || [];
    const optimizedRoute: OptimizedStop[] = [];
    const waypointsOrder: string[] = [];

    // The waypoints are returned in input order, but with waypoint_index showing optimized order
    const sortedWaypoints = [...waypoints]
      .filter((wp: any) => wp.waypoint_index !== undefined)
      .sort((a: any, b: any) => a.waypoint_index - b.waypoint_index);

    let cumulativeDistance = 0;
    let cumulativeDuration = 0;

    for (const wp of sortedWaypoints) {
      // Skip start/end depot
      const originalIndex = waypoints.indexOf(wp);
      if (start_location && originalIndex === 0) continue;
      if (end_location && !roundtrip && originalIndex === waypoints.length - 1) continue;

      // Find corresponding job
      const jobIndex = start_location ? originalIndex - 1 : originalIndex;
      if (jobIndex < 0 || jobIndex >= jobs.length) continue;

      const job = jobs[jobIndex];

      // Get leg info if available
      const legIndex = wp.waypoint_index > 0 ? wp.waypoint_index - 1 : 0;
      const leg = trip.legs?.[legIndex];

      if (leg) {
        cumulativeDistance += leg.distance || 0;
        cumulativeDuration += leg.duration || 0;
      }

      optimizedRoute.push({
        job_id: job.id,
        name: job.name,
        latitude: job.latitude,
        longitude: job.longitude,
        sequence: optimizedRoute.length + 1,
        distance_meters: Math.round(cumulativeDistance),
        duration_seconds: Math.round(cumulativeDuration),
      });

      waypointsOrder.push(job.id);
    }

    // If optimized route is empty, fall back to original order
    if (optimizedRoute.length === 0) {
      for (let i = 0; i < jobs.length; i++) {
        const job = jobs[i];
        optimizedRoute.push({
          job_id: job.id,
          name: job.name,
          latitude: job.latitude,
          longitude: job.longitude,
          sequence: i + 1,
          distance_meters: 0,
          duration_seconds: 0,
        });
        waypointsOrder.push(job.id);
      }
    }

    const result: OptimizeRouteResponse = {
      success: true,
      optimized_route: optimizedRoute,
      total_distance_meters: Math.round(trip.distance || 0),
      total_duration_seconds: Math.round(trip.duration || 0),
      waypoints_order: waypointsOrder,
      geometry: trip.geometry,
    };

    return new Response(
      JSON.stringify(result),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("Error optimizing route:", error);
    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Internal server error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { requireAuthedTenant, requireInternalSecret } from "../_shared/tenant.ts";
import { captureException } from "../_shared/sentry.ts";
import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";
import { sendEmail } from "../_shared/sendEmail.ts";
import { sendTenantSms } from "../_shared/sms-sender.ts";

interface OrderItem {
  name: string;
  qty: number;
  base_price?: number;
  modifiers?: string[];
  item_notes?: string;
}

interface Order {
  id: string;
  tenant_id: string;
  order_number: string;
  order_type: string;
  status: string;
  customer_name: string | null;
  customer_phone: string | null;
  delivery_address: string | null;
  address_json: unknown;
  items_json: OrderItem[];
  special_instructions: string | null;
  requested_time: string | null;
  total_cents: number | null;
  created_at: string;
}

interface DeliverySettings {
  enabled: boolean;
  handoff_methods: string[];
  webhook_url: string | null;
  webhook_secret: string | null;
  notify_email: string | null;
  notify_phone: string | null;
}

/**
 * Validate access - supports both user JWT and internal secret
 */
async function validateAccess(
  req: Request,
  requestedTenantId: string | null
): Promise<{ tenantId: string; isInternalCall: boolean }> {
  const hasAuthHeader = req.headers.get("authorization")?.startsWith("Bearer ");
  const hasInternalSecret = req.headers.get("x-closeloop-secret");

  // Try user JWT first
  if (hasAuthHeader) {
    const { tenantId } = await requireAuthedTenant(req, requestedTenantId);
    return { tenantId, isInternalCall: false };
  }

  // Fall back to internal secret for system triggers
  if (hasInternalSecret) {
    requireInternalSecret(req);
    if (!requestedTenantId) {
      throw new Error("tenant_id required for internal calls");
    }
    return { tenantId: requestedTenantId, isInternalCall: true };
  }

  throw new Error("Missing Authorization header or x-closeloop-secret");
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    const body = await req.json();
    const { order_id, methods, test, method, webhook_url, webhook_secret, notify_email, notify_phone } = body;
    const requestedTenantId = body.tenant_id ?? body.tenantId ?? null;

    // SECURITY: Validate access (user JWT or internal secret)
    const { tenantId: tenant_id } = await validateAccess(req, requestedTenantId);

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    // Handle test mode
    if (test && method) {
      const testResult = await runTestHandoff(method, {
        webhook_url,
        webhook_secret,
        notify_email,
        notify_phone,
        tenant_id,
      }, supabase);
      return jsonResponse(testResult);
    }

    if (!order_id || !tenant_id) {
      throw new Error("order_id and tenant_id are required");
    }

    // Fetch order
    const { data: order, error: orderError } = await supabase
      .from("food_orders")
      .select("*")
      .eq("id", order_id)
      .eq("tenant_id", tenant_id)
      .single();

    if (orderError || !order) {
      throw new Error(`Order not found: ${orderError?.message}`);
    }

    // Fetch delivery settings
    const { data: settings } = await supabase
      .from("order_delivery_settings")
      .select("*")
      .eq("tenant_id", tenant_id)
      .single();

    if (!settings?.enabled) {
      console.log("Order handoff disabled for tenant");
      return jsonResponse({ status: "skipped", reason: "handoff disabled" });
    }

    // Determine which methods to run
    const methodsToRun = methods || settings.handoff_methods || ["internal"];
    const results: Record<string, { success: boolean; error?: string }> = {};

    // Fetch tenant name for display
    const { data: tenant } = await supabase
      .from("tenants")
      .select("name")
      .eq("id", tenant_id)
      .single();

    const businessName = tenant?.name || "Restaurant";

    // Record observation for order pattern
    try {
      const orderHour = new Date(order.created_at).getHours();
      await fetch(`${supabaseUrl}/functions/v1/record-observation`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${supabaseKey}`,
        },
        body: JSON.stringify({
          tenantId: tenant_id,
          observationType: "time_pattern",
          subjectKey: `order_hour_${orderHour}`,
          observation: `${order.order_type} order placed at ${orderHour}:00`,
        }),
      });
    } catch (e) {
      console.error("Failed to record order time observation:", e);
    }

    // Run each enabled method
    for (const handoffMethod of methodsToRun) {
      if (handoffMethod === "internal") {
        // Internal queue is just the database - always succeeds
        results.internal = { success: true };
        await logHandoffAttempt(supabase, tenant_id, order_id, "internal", "success");
        continue;
      }

      if (handoffMethod === "webhook" && settings.webhook_url) {
        try {
          await sendWebhook(order as Order, settings, businessName);
          results.webhook = { success: true };
          await logHandoffAttempt(supabase, tenant_id, order_id, "webhook", "success");
        } catch (e) {
          const error = e instanceof Error ? e.message : "Unknown error";
          results.webhook = { success: false, error };
          await logHandoffAttempt(supabase, tenant_id, order_id, "webhook", "failed", error);
        }
      }

      if (handoffMethod === "email" && settings.notify_email) {
        try {
          const items = Array.isArray(order.items_json)
            ? order.items_json.map((i: OrderItem) => `${i.qty}x ${i.name}`).join(", ")
            : "items";
          const totalStr = order.total_cents ? `$${(order.total_cents / 100).toFixed(2)}` : "N/A";

          const orderType = (order.order_type || "pickup").toUpperCase();
          const emailResult = await sendEmail({
            to: settings.notify_email,
            subject: `New Order #${order.order_number} — ${orderType}`,
            businessName,
            html: `
              <h2>New Order #${order.order_number}</h2>
              <p><strong>Type:</strong> ${orderType}</p>
              <p><strong>Customer:</strong> ${order.customer_name || "Unknown"}</p>
              ${order.customer_phone ? `<p><strong>Phone:</strong> ${order.customer_phone}</p>` : ""}
              <p><strong>Items:</strong> ${items}</p>
              <p><strong>Total:</strong> ${totalStr}</p>
              ${order.special_instructions ? `<p><strong>Special Instructions:</strong> ${order.special_instructions}</p>` : ""}
              ${order.delivery_address ? `<p><strong>Delivery Address:</strong> ${order.delivery_address}</p>` : ""}
              ${order.requested_time ? `<p><strong>Requested Time:</strong> ${order.requested_time}</p>` : ""}
            `.trim(),
          });

          results.email = { success: emailResult.success, error: emailResult.error };
          await logHandoffAttempt(supabase, tenant_id, order_id, "email", emailResult.success ? "success" : "failed", emailResult.error);
        } catch (e) {
          const error = e instanceof Error ? e.message : "Unknown error";
          results.email = { success: false, error };
          await logHandoffAttempt(supabase, tenant_id, order_id, "email", "failed", error);
        }
      }

      if (handoffMethod === "sms" && settings.notify_phone) {
        try {
          const items = Array.isArray(order.items_json)
            ? (order.items_json as OrderItem[]).map((i) => `${i.qty}x ${i.name}`).join(", ")
            : "items";

          let message = `NEW ORDER #${order.order_number}\n`;
          message += `Type: ${(order.order_type || "pickup").toUpperCase()}\n`;
          message += `Customer: ${order.customer_name || "Unknown"}\n`;
          message += `Items: ${items.substring(0, 100)}${items.length > 100 ? "..." : ""}\n`;
          if (order.total_cents) {
            message += `Total: $${(order.total_cents / 100).toFixed(2)}\n`;
          }
          if (order.special_instructions) {
            const truncated = order.special_instructions.substring(0, 50);
            message += `NOTE: ${truncated}${order.special_instructions.length > 50 ? "..." : ""}\n`;
          }

          const smsResult = await sendTenantSms({
            tenantId: tenant_id,
            to: settings.notify_phone,
            body: message,
          });

          if (smsResult.success) {
            results.sms = { success: true };
            await logHandoffAttempt(supabase, tenant_id, order_id, "sms", "success");
          } else if (smsResult.skipped) {
            console.log(`[order-handoff] No verified SMS channel for tenant ${tenant_id}`);
            results.sms = { success: false, error: "No verified SMS channel" };
            await logHandoffAttempt(supabase, tenant_id, order_id, "sms", "skipped", "No verified SMS channel");
          } else {
            throw new Error(`SMS failed: ${smsResult.error}`);
          }
        } catch (e) {
          const error = e instanceof Error ? e.message : "Unknown error";
          results.sms = { success: false, error };
          await logHandoffAttempt(supabase, tenant_id, order_id, "sms", "failed", error);
        }
      }

      if (handoffMethod === "print") {
        // Print is handled client-side - just mark as pending
        results.print = { success: true };
        await logHandoffAttempt(supabase, tenant_id, order_id, "print", "pending");
      }
    }

    // Update order handoff_state
    await supabase
      .from("food_orders")
      .update({
        handoff_state: {
          last_run: new Date().toISOString(),
          results,
        },
      })
      .eq("id", order_id);

    // Trigger workflow if any active workflow matches this event
    const eventType = order.status === "confirmed" ? "order.confirmed" : "order.created";
    try {
      await fetch(`${supabaseUrl}/functions/v1/trigger-workflow`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${supabaseKey}`,
        },
        body: JSON.stringify({
          tenant_id,
          trigger: eventType,
          entity_type: "order",
          entity_id: order_id,
        }),
      });
      console.log(`Triggered workflow for ${eventType}:`, order_id);
    } catch (e) {
      console.error("Failed to trigger workflow:", e);
    }

    return jsonResponse({ status: "success", results });
  } catch (error) {
    console.error("Order handoff error:", error);

    // Capture to Sentry for monitoring
    await captureException(error, {
      tags: { function: "order-handoff" },
    });

    return errorResponse(error instanceof Error ? error.message : "Unknown error", 500);
  }
});

async function sendWebhook(order: Order, settings: DeliverySettings, businessName: string) {
  if (!settings.webhook_url) throw new Error("No webhook URL configured");

  const payload = JSON.stringify({
    event: "order.created",
    order_id: order.id,
    order_number: order.order_number,
    order_type: order.order_type,
    status: order.status,
    customer: {
      name: order.customer_name,
      phone: order.customer_phone,
    },
    items: order.items_json,
    special_instructions: order.special_instructions,
    requested_time: order.requested_time,
    total_cents: order.total_cents,
    created_at: order.created_at,
    business_name: businessName,
  });

  const headers: Record<string, string> = {
    "Content-Type": "application/json",
  };

  // Add HMAC signature if secret is configured
  if (settings.webhook_secret) {
    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey(
      "raw",
      encoder.encode(settings.webhook_secret),
      { name: "HMAC", hash: "SHA-256" },
      false,
      ["sign"]
    );
    const signature = await crypto.subtle.sign("HMAC", key, encoder.encode(payload));
    const signatureHex = Array.from(new Uint8Array(signature))
      .map(b => b.toString(16).padStart(2, "0"))
      .join("");
    headers["X-CloseLoop-Signature"] = `sha256=${signatureHex}`;
  }

  const response = await fetch(settings.webhook_url, {
    method: "POST",
    headers,
    body: payload,
  });

  if (!response.ok) {
    throw new Error(`Webhook failed: ${response.status} ${response.statusText}`);
  }
}

async function sendOrderEmail(order: Order, email: string, bName: string) {
  const items = Array.isArray(order.items_json)
    ? order.items_json.map((i: OrderItem) => `${i.qty}x ${i.name}`).join(", ")
    : "items";
  const totalStr = order.total_cents ? `$${(order.total_cents / 100).toFixed(2)}` : "N/A";

  const orderType = (order.order_type || "pickup").toUpperCase();
  const result = await sendEmail({
    to: email,
    subject: `New Order #${order.order_number} — ${orderType}`,
    businessName: bName,
    html: `
      <h2>New Order #${order.order_number}</h2>
      <p><strong>Type:</strong> ${orderType}</p>
      <p><strong>Customer:</strong> ${order.customer_name || "Unknown"}</p>
      <p><strong>Items:</strong> ${items}</p>
      <p><strong>Total:</strong> ${totalStr}</p>
    `.trim(),
  });

  if (!result.success) {
    throw new Error(result.error || "Email send failed");
  }
}

