/**
 * outbound-call
 *
 * Initiates an outbound AI phone call via Twilio + ElevenLabs.
 * Used for appointment reminders, warm lead follow-ups, review requests, and no-show recovery.
 *
 * Called by: cron-process-outbound-queue
 *
 * Payload:
 *   tenant_id       - Required
 *   customer_phone  - Required (E.164)
 *   call_purpose    - Required: reminder | followup | recovery | review | no_show_recovery
 *   context         - Optional: entity details, history, etc.
 *   queue_item_id   - Optional: outbound_call_queue record ID
 */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsHeaders, corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";
import { buildBusinessContext, buildDynamicVariables } from "../_shared/buildBusinessContext.ts";
import { getAgentIdForMode } from "../_shared/agentResolver.ts";

interface OutboundCallPayload {
  tenant_id: string;
  customer_phone: string;
  call_purpose: "reminder" | "followup" | "recovery" | "review" | "no_show_recovery";
  context?: Record<string, unknown>;
  queue_item_id?: string;
}

// Purpose-specific opening prompts
const PURPOSE_PROMPTS: Record<string, string> = {
  reminder: "Hi {{customer_name}}, this is {{business_name}}'s assistant calling to confirm your {{service_name}} appointment {{appointment_time}}. Would you like to confirm, reschedule, or cancel?",
  followup: "Hi {{customer_name}}, this is {{business_name}} following up on your call earlier about {{service_requested}}. I wanted to check if you had any other questions or if you'd like to go ahead and schedule?",
  recovery: "Hi {{customer_name}}, this is {{business_name}}. We noticed you were interested in {{service_requested}} — we'd love to help you get that scheduled. Do you have a moment?",
  review: "Hi {{customer_name}}, this is {{business_name}}. We wanted to check in — how was your recent {{service_name}} with us? We'd love to hear your feedback.",
  no_show_recovery: "Hi {{customer_name}}, this is {{business_name}}. We noticed you missed your appointment today. No worries at all — would you like to reschedule? I can check what's available.",
};

serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    const payload: OutboundCallPayload = await req.json();

    if (!payload.tenant_id || !payload.customer_phone || !payload.call_purpose) {
      return errorResponse("Missing required fields: tenant_id, customer_phone, call_purpose");
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const twilioAccountSid = Deno.env.get("TWILIO_ACCOUNT_SID");
    const twilioAuthToken = Deno.env.get("TWILIO_AUTH_TOKEN");
    const elevenLabsApiKey = Deno.env.get("ELEVENLABS_API_KEY");
    const supabase = createClient(supabaseUrl, supabaseKey);

    if (!twilioAccountSid || !twilioAuthToken || !elevenLabsApiKey) {
      return errorResponse("Missing Twilio or ElevenLabs credentials", 500);
    }

    // Check opt-out list
    const { data: optOut } = await supabase
      .from("outbound_opt_outs")
      .select("id")
      .eq("tenant_id", payload.tenant_id)
      .eq("customer_phone", payload.customer_phone)
      .maybeSingle();

    if (optOut) {
      console.log(`[outbound-call] Skipping opted-out customer ${payload.customer_phone.slice(-4)}`);
      if (payload.queue_item_id) {
        await supabase.from("outbound_call_queue").update({ status: "skipped", error_message: "Customer opted out" }).eq("id", payload.queue_item_id);
      }
      return jsonResponse({ success: false, reason: "opted_out" });
    }

    // Get tenant info
    const { data: tenant } = await supabase
      .from("tenants")
      .select("id, business_name, business_mode, enabled_modules, timezone, hours_json")
      .eq("id", payload.tenant_id)
      .single();

    if (!tenant) {
      return errorResponse("Tenant not found", 404);
    }

    // Check business hours
    const now = new Date();
    const tenantTz = tenant.timezone || "America/New_York";
    const localHour = parseInt(now.toLocaleString("en-US", { timeZone: tenantTz, hour: "numeric", hour12: false }));
    if (localHour < 9 || localHour >= 20) {
      console.log(`[outbound-call] Outside business hours (${localHour}h in ${tenantTz})`);
      if (payload.queue_item_id) {
        // Reschedule for next business hour
        const nextDay = new Date(now.getTime() + 24 * 60 * 60 * 1000);
        nextDay.setHours(10, 0, 0, 0);
        await supabase.from("outbound_call_queue").update({
          scheduled_at: nextDay.toISOString(),
          status: "queued",
        }).eq("id", payload.queue_item_id);
      }
      return jsonResponse({ success: false, reason: "outside_hours" });
    }

    // Get a phone number to call from
    const { data: phoneNumbers } = await supabase
      .from("phone_numbers")
      .select("phone_e164")
      .eq("tenant_id", payload.tenant_id)
      .eq("is_active", true)
      .limit(1);

    const fromNumber = phoneNumbers?.[0]?.phone_e164;
    if (!fromNumber) {
      return errorResponse("No active phone number for tenant", 400);
    }

    // Resolve agent
    const agentResolution = await getAgentIdForMode(
      supabase,
      payload.tenant_id,
      tenant.business_mode,
      null
    );
    const agentId = agentResolution.agentId;

    if (!agentId) {
      return errorResponse("No ElevenLabs agent configured", 400);
    }

    // Build business context
    let dynamicVars: Record<string, string> = {};
    try {
      const contextClient = createClient(supabaseUrl, supabaseKey, { auth: { persistSession: false } });
      const { context } = await buildBusinessContext(contextClient, {
        tenantId: payload.tenant_id,
        locationId: null,
        customerId: null,
        channel: "voice",
        sessionId: null,
        callerPhone: payload.customer_phone,
        includeIntelligence: true,
      });
      dynamicVars = buildDynamicVariables(context, payload.customer_phone, null);
    } catch (e) {
      console.warn("[outbound-call] Context build failed, using minimal vars:", e);
    }

    // Build purpose-specific greeting
    const contextData = payload.context || {};
    let purposeGreeting = PURPOSE_PROMPTS[payload.call_purpose] || PURPOSE_PROMPTS.followup;
    purposeGreeting = purposeGreeting
      .replace("{{customer_name}}", (contextData.customer_name as string) || "there")
      .replace("{{business_name}}", tenant.business_name || "our business")
      .replace("{{service_name}}", (contextData.service_name as string) || "service")
      .replace("{{service_requested}}", (contextData.service_requested as string) || "our services")
      .replace("{{appointment_time}}", (contextData.appointment_time as string) || "tomorrow");

    // Override greeting for outbound purpose
    dynamicVars.greeting_script = purposeGreeting;
    dynamicVars.call_direction = "outbound";
    dynamicVars.call_purpose = payload.call_purpose;

    // Register call with ElevenLabs
    const registerResponse = await fetch(
      "https://api.elevenlabs.io/v1/convai/twilio/register-call",
      {
        method: "POST",
        headers: {
          "xi-api-key": elevenLabsApiKey,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          agent_id: agentId,
          from_number: fromNumber,
          to_number: payload.customer_phone,
          conversation_initiation_client_data: {
            dynamic_variables: dynamicVars,
          },
        }),
      }
    );

    if (!registerResponse.ok) {
      const errText = await registerResponse.text();
      console.error(`[outbound-call] ElevenLabs register failed: ${errText}`);
      return errorResponse(`ElevenLabs register failed: ${registerResponse.status}`, 500);
    }

    const registerData = await registerResponse.json();

    // Initiate outbound call via Twilio
    const twilioUrl = `https://api.twilio.com/2010-04-01/Accounts/${twilioAccountSid}/Calls.json`;
    const twiml = registerData.twiml || `<Response><Connect><Stream url="${registerData.stream_url || ""}" /></Connect></Response>`;

    const twilioBody = new URLSearchParams({
      To: payload.customer_phone,
      From: fromNumber,
      Twiml: twiml,
      StatusCallback: `${supabaseUrl}/functions/v1/twilio-inbound`,
      StatusCallbackEvent: "completed",
      MachineDetection: "Enable",
      MachineDetectionTimeout: "5",
    });

    const twilioResponse = await fetch(twilioUrl, {
      method: "POST",
      headers: {
        Authorization: `Basic ${btoa(`${twilioAccountSid}:${twilioAuthToken}`)}`,
        "Content-Type": "application/x-www-form-urlencoded",
      },
      body: twilioBody.toString(),
    });

    if (!twilioResponse.ok) {
      const errText = await twilioResponse.text();
      console.error(`[outbound-call] Twilio call failed: ${errText}`);
      if (payload.queue_item_id) {
        await supabase.from("outbound_call_queue").update({
          status: "failed",
          error_message: `Twilio error: ${twilioResponse.status}`,
          last_attempt_at: new Date().toISOString(),
        }).eq("id", payload.queue_item_id);
      }
      return errorResponse(`Twilio call failed: ${twilioResponse.status}`, 500);
    }

    const twilioData = await twilioResponse.json();
    const callSid = twilioData.sid;

    // Create session record
    const { data: session } = await supabase
      .from("ai_call_sessions")
      .insert({
        tenant_id: payload.tenant_id,
        twilio_call_sid: callSid,
        caller_phone: payload.customer_phone,
        direction: "outbound",
        call_purpose: payload.call_purpose,
        started_at: new Date().toISOString(),
        context_json: { ...contextData, call_purpose: payload.call_purpose },
      })
      .select("id")
      .single();

    // Update queue item
    if (payload.queue_item_id) {
      await supabase.from("outbound_call_queue").update({
        status: "calling",
        last_attempt_at: new Date().toISOString(),
        result_session_id: session?.id || null,
      }).eq("id", payload.queue_item_id);
    }

    console.log(`[outbound-call] Initiated ${payload.call_purpose} call to ${payload.customer_phone.slice(-4)} (sid: ${callSid})`);

    return jsonResponse({
      success: true,
      call_sid: callSid,
      session_id: session?.id,
      purpose: payload.call_purpose,
    });

  } catch (error) {
    console.error("[outbound-call] Error:", error);
    return errorResponse(`Internal error: ${(error as Error).message}`, 500);
  }
});

import "jsr:@supabase/functions-js/edge-runtime.d.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

function jsonResponse(data: unknown, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const { text } = await req.json();

    if (!text || typeof text !== "string" || text.trim().length === 0) {
      return jsonResponse({ error: "Text is required" }, 400);
    }

    if (text.length > 50000) {
      return jsonResponse({ error: "Text is too long (max 50,000 characters)" }, 400);
    }

    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
    if (!LOVABLE_API_KEY) {
      return jsonResponse({ error: "AI service not configured" }, 500);
    }

    const systemPrompt = `You are a service/menu parser for businesses. Extract individual services from the provided text.

For each service, extract:
- name: The service name (required)
- description: A brief description if available
- duration_minutes: Estimated duration in minutes. Use context clues. Default to 60 if unknown.
- price_amount: The numeric price (no $ sign). If "starting at $X" or "from $X", use X.
- price_type: One of "fixed", "starting_at", or "quote_only"

Price type rules:
- "starting_at" if text says: "starting at", "from", "starts at", "and up", "+", "beginning at", "as low as"
- "quote_only" if text says: "quote", "call for pricing", "varies", "TBD", "custom", "contact us", or no price at all and the service sounds variable
- "fixed" for all other explicit prices

Return a JSON object with a "services" array. Each element has: name, description, duration_minutes, price_amount (number or null), price_type.

IMPORTANT: Return ONLY valid JSON, no markdown, no explanation.`;

    const response = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${LOVABLE_API_KEY}`,
      },
      body: JSON.stringify({
        model: "google/gemini-2.5-flash",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: text },
        ],
        temperature: 0.1,
        response_format: { type: "json_object" },
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.error("[parse-services-text] AI error:", response.status, errorText);

      if (response.status === 429) {
        return jsonResponse({ error: "Rate limited — please try again in a moment" }, 429);
      }
      if (response.status === 402) {
        return jsonResponse({ error: "AI credits exhausted" }, 402);
      }

      return jsonResponse({ error: "AI parsing failed" }, 500);
    }

    const aiResult = await response.json();
    const content = aiResult.choices?.[0]?.message?.content;

    if (!content) {
      return jsonResponse({ error: "No response from AI" }, 500);
    }

    let parsed;
    try {
      parsed = JSON.parse(content);
    } catch {
      // Try to extract JSON from markdown code blocks
      const match = content.match(/```(?:json)?\s*([\s\S]*?)```/);
      if (match) {
        parsed = JSON.parse(match[1].trim());
      } else {
        console.error("[parse-services-text] Failed to parse AI response:", content);
        return jsonResponse({ error: "Could not parse AI response" }, 500);
      }
    }

    const services = (parsed.services || []).map((s: any) => ({
      name: String(s.name || "").trim(),
      description: String(s.description || "").trim(),
      duration_minutes: typeof s.duration_minutes === "number" ? s.duration_minutes : 60,
      price_amount: typeof s.price_amount === "number" ? s.price_amount : null,
      price_type: ["fixed", "starting_at", "quote_only"].includes(s.price_type) ? s.price_type : "fixed",
    })).filter((s: any) => s.name.length > 0);

    console.log(`[parse-services-text] Extracted ${services.length} services`);

    return jsonResponse({ services });
  } catch (error) {
    console.error("[parse-services-text] Error:", error);
    return jsonResponse({ error: "Internal server error" }, 500);
  }
});

/**
 * Partner Analysis Edge Function
 *
 * Generates AI-powered business analysis for the Business Partner page.
 * Uses Claude Sonnet 4.5 to analyze the tenant's actual business data
 * and produce personalized, contextual advice.
 *
 * - Caches analysis for 24 hours per tenant
 * - Manual refresh limited to 3 per day
 * - Auto-generates only when user visits and cache is expired
 *
 * Auth: JWT-based via requireAuthedTenant
 */

import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { requireAuthedTenant, serviceClient } from "../_shared/tenant.ts";
import { getBusinessBrainSnapshot } from "../_shared/getBusinessBrainSnapshot.ts";
import { getIndustryKnowledge } from "../_shared/industryKnowledge.ts";

const MAX_REFRESHES_PER_DAY = 3;

interface RequestBody {
  tenant_id: string;
  force_refresh?: boolean;
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    const body: RequestBody = await req.json();
    const { tenantId } = await requireAuthedTenant(req, body.tenant_id);
    const forceRefresh = body.force_refresh === true;

    const supabase = serviceClient();

    // ─── Cache Check ────────────────────────────────────────────────
    const { data: cached } = await supabase
      .from("partner_analyses")
      .select("*")
      .eq("tenant_id", tenantId)
      .maybeSingle();

    const now = new Date();
    const today = now.toISOString().split("T")[0];

    if (cached && !forceRefresh) {
      const expiresAt = new Date(cached.expires_at);
      if (expiresAt > now) {
        // Reset refresh count if new day
        const refreshCount = cached.refresh_date === today
          ? cached.refresh_count_today
          : 0;

        return jsonResponse({
          analysis: cached.analysis_json,
          generated_at: cached.generated_at,
          expires_at: cached.expires_at,
          is_cached: true,
          refresh_count_today: refreshCount,
          max_refreshes_per_day: MAX_REFRESHES_PER_DAY,
        });
      }
    }

    // ─── Rate Limit (force refresh only) ────────────────────────────
    if (forceRefresh && cached) {
      const refreshCount = cached.refresh_date === today
        ? cached.refresh_count_today
        : 0;

      if (refreshCount >= MAX_REFRESHES_PER_DAY) {
        return errorResponse(
          `Daily refresh limit reached (${MAX_REFRESHES_PER_DAY}/${MAX_REFRESHES_PER_DAY}). Analysis will auto-refresh tomorrow.`,
          429
        );
      }
    }

    // ─── Assemble Context (parallel) ────────────────────────────────
    const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString();

    const [
      brainSnapshot,
      callOutcomesResult,
      patternsResult,
      knowledgeGapsResult,
      insightsResult,
      digestResult,
      revenueResult,
      staffCountResult,
      calendarResult,
    ] = await Promise.all([
      getBusinessBrainSnapshot(supabase, { tenantId }),
      supabase
        .from("call_outcomes")
        .select("outcome_type, intent, conversion_value_cents, ai_handled_fully, created_at")
        .eq("tenant_id", tenantId)
        .gte("created_at", thirtyDaysAgo)
        .order("created_at", { ascending: false })
        .limit(200),
      supabase
        .from("business_patterns")
        .select("pattern_type, pattern_key, confidence_score, observation_count, is_actionable, pattern_data")
        .eq("tenant_id", tenantId)
        .order("observation_count", { ascending: false })
        .limit(10),
      supabase
        .from("knowledge_gaps")
        .select("gap_type, description, customer_question, occurrence_count")
        .eq("tenant_id", tenantId)
        .eq("resolved", false)
        .order("occurrence_count", { ascending: false })
        .limit(10),
      supabase
        .from("intelligence_insights")
        .select("insight_type, severity, title, description, recommended_action, is_actioned")
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(10),
      supabase
        .from("intelligence_digest")
        .select("digest_json, period_start, period_end")
        .eq("tenant_id", tenantId)
        .order("created_at", { ascending: false })
        .limit(1)
        .maybeSingle(),
      supabase
        .from("revenue_attributions")
        .select("entity_type, revenue_cents, created_at")
        .eq("tenant_id", tenantId)
        .gte("created_at", thirtyDaysAgo),
      supabase
        .from("tenant_users")
        .select("id", { count: "exact", head: true })
        .eq("tenant_id", tenantId),
      supabase
        .from("calendar_connections")
        .select("id, status")
        .eq("tenant_id", tenantId)
        .eq("status", "connected"),
    ]);

    // ─── Compute Metrics ────────────────────────────────────────────
    const callOutcomes = callOutcomesResult.data ?? [];
    const patterns = patternsResult.data ?? [];
    const knowledgeGaps = knowledgeGapsResult.data ?? [];
    const insights = insightsResult.data ?? [];
    const digest = digestResult.data;
    const revenueRows = revenueResult.data ?? [];
    const staffCount = staffCountResult.count ?? 0;
    const hasCalendarConnected = (calendarResult.data?.length ?? 0) > 0;

    const totalCalls = callOutcomes.length;
    const bookedCalls = callOutcomes.filter((c: any) => c.outcome_type === "booked").length;
    const conversionRate = totalCalls > 0 ? Math.round((bookedCalls / totalCalls) * 100) : 0;
    const hangupCalls = callOutcomes.filter((c: any) => c.outcome_type === "hangup" || c.outcome_type === "lost").length;
    const hangupRate = totalCalls > 0 ? Math.round((hangupCalls / totalCalls) * 100) : 0;
    const aiHandledFully = callOutcomes.filter((c: any) => c.ai_handled_fully).length;
    const aiHandledRate = totalCalls > 0 ? Math.round((aiHandledFully / totalCalls) * 100) : 0;
    const totalRevenueCents = revenueRows.reduce((sum: number, r: any) => sum + (r.revenue_cents || 0), 0);

    // Industry knowledge
    const industrySlug = brainSnapshot.tenant.industry || "";
    const industryEntry = getIndustryKnowledge(industrySlug);

    // Stage detection (same logic as frontend)
    const brainEssentialPct = computeBrainEssentialPct(brainSnapshot);
    const stage = detectStage(totalCalls, conversionRate, totalRevenueCents, brainEssentialPct);

    // ─── Build Context Document ─────────────────────────────────────
    const contextDoc = buildContextDocument({
      brainSnapshot,
      callOutcomes,
      patterns,
      knowledgeGaps,
      insights,
      digest,
      totalCalls,
      conversionRate,
      hangupRate,
      aiHandledRate,
      totalRevenueCents,
      stage,
      industryEntry,
      staffCount,
      hasCalendarConnected,
    });

    // ─── Call AI via Lovable AI Gateway ────────────────────────────
    const LOVABLE_API_KEY = Deno.env.get("LOVABLE_API_KEY");
    if (!LOVABLE_API_KEY) {
      return errorResponse("LOVABLE_API_KEY not configured", 500);
    }

    const systemPrompt = buildSystemPrompt();

    const aiResponse = await fetch("https://ai.gateway.lovable.dev/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${LOVABLE_API_KEY}`,
      },
      body: JSON.stringify({
        model: "google/gemini-3-flash-preview",
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: contextDoc },
        ],
        max_tokens: 4096,
        temperature: 0.3,
      }),
    });

    if (!aiResponse.ok) {
      const errText = await aiResponse.text();
      console.error("[partner-analysis] AI Gateway error:", aiResponse.status, errText);
      if (aiResponse.status === 429) {
        return errorResponse("Rate limit exceeded. Please try again later.", 429);
      }
      if (aiResponse.status === 402) {
        return errorResponse("AI credits exhausted. Please add more credits.", 402);
      }
      return errorResponse(`AI service error: ${aiResponse.status}`, 502);
    }

    const aiData = await aiResponse.json();
    const rawText = aiData.choices?.[0]?.message?.content ?? "";
    const promptTokens = aiData.usage?.prompt_tokens ?? null;
    const completionTokens = aiData.usage?.completion_tokens ?? null;

    // Parse JSON from response (strip markdown fences if present)
    let analysis;
    try {
      const jsonStr = rawText
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/\s*```\s*$/, "")
        .trim();
      analysis = JSON.parse(jsonStr);
    } catch (parseErr) {
      console.error("[partner-analysis] Failed to parse AI response:", parseErr, rawText.substring(0, 500));
      return errorResponse("Failed to parse AI analysis response", 502);
    }

    // ─── Upsert Cache ──────────────────────────────────────────────
    const expiresAt = new Date(now.getTime() + 24 * 60 * 60 * 1000).toISOString();
    const refreshCountToday = (cached && cached.refresh_date === today)
      ? cached.refresh_count_today + 1
      : 1;

    await supabase
      .from("partner_analyses")
      .upsert(
        {
          tenant_id: tenantId,
          analysis_json: analysis,
          model_used: "google/gemini-3-flash-preview",
          prompt_tokens: promptTokens,
          completion_tokens: completionTokens,
          generated_at: now.toISOString(),
          expires_at: expiresAt,
          refresh_count_today: refreshCountToday,
          refresh_date: today,
        },
        { onConflict: "tenant_id" }
      );

    return jsonResponse({
      analysis,
      generated_at: now.toISOString(),
      expires_at: expiresAt,
      is_cached: false,
      refresh_count_today: refreshCountToday,
      max_refreshes_per_day: MAX_REFRESHES_PER_DAY,
    });
  } catch (err: any) {
    console.error("[partner-analysis] Error:", err);

    if (err.message?.includes("Unauthorized") || err.message?.includes("Forbidden")) {
      return errorResponse(err.message, 401);
    }

    return errorResponse(err.message || "Internal error", 500);
  }
});

// ─── Helpers ──────────────────────────────────────────────────────────────

function detectStage(
  totalCalls: number,
  conversionRate: number,
  revenueCents: number,
  brainEssentialPct: number,
): string {
  if (totalCalls >= 200 && conversionRate > 40 && revenueCents > 500_000 && brainEssentialPct > 90)
    return "established";
  if (totalCalls >= 200 && conversionRate > 25 && revenueCents > 200_000)
    return "scaling";
  if (totalCalls >= 50 && brainEssentialPct > 80 && conversionRate > 15)
    return "growing";
  if (totalCalls >= 10 && brainEssentialPct > 50)
    return "building";
  return "getting_started";
}

function computeBrainEssentialPct(snapshot: any): number {
  let total = 0;
  let filled = 0;

  // Core fields
  const checks = [
    !!snapshot.tenant.name,
    Object.keys(snapshot.tenant.hours_json || {}).length > 0,
    snapshot._meta.section_counts.services > 0,
    !!snapshot.assistant_settings.ai_tone,
  ];
  total = checks.length;
  filled = checks.filter(Boolean).length;

  return total > 0 ? Math.round((filled / total) * 100) : 0;
}

