/**
 * portal-booking-action: Allow customers to reschedule or cancel bookings
 * via their portal link.
 *
 * Accepts:
 *   { token, tenant_id, booking_id, action: "cancel" | "reschedule", new_start_at? }
 *
 * Auth: Portal token (HMAC-SHA256, same as verify-portal-token)
 */
import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { serviceClient } from "../_shared/tenant.ts";

async function verifyPortalToken(
  token: string,
  tenantId: string,
): Promise<{ valid: boolean; customerId?: string; error?: string }> {
  const secret = Deno.env.get("PORTAL_TOKEN_SECRET");
  if (!secret) return { valid: false, error: "PORTAL_TOKEN_SECRET not configured" };

  const parts = token.split(".");
  if (parts.length !== 2) return { valid: false, error: "Invalid token format" };

  const [payloadB64, signatureB64] = parts;
  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"],
  );

  const expectedSigBuffer = await crypto.subtle.sign("HMAC", key, encoder.encode(payloadB64));
  const expectedSigArray = Array.from(new Uint8Array(expectedSigBuffer));
  const expectedSigB64 = btoa(String.fromCharCode(...expectedSigArray));

  if (signatureB64.length !== expectedSigB64.length) return { valid: false, error: "Invalid token" };
  let mismatch = 0;
  for (let i = 0; i < signatureB64.length; i++) {
    mismatch |= signatureB64.charCodeAt(i) ^ expectedSigB64.charCodeAt(i);
  }
  if (mismatch !== 0) return { valid: false, error: "Invalid token" };

  let payload: { customer_id: string; tenant_id: string; iat: number; exp: number };
  try {
    payload = JSON.parse(atob(payloadB64));
  } catch {
    return { valid: false, error: "Malformed token" };
  }

  if (payload.exp < Math.floor(Date.now() / 1000)) return { valid: false, error: "Token expired" };
  if (payload.tenant_id !== tenantId) return { valid: false, error: "Tenant mismatch" };

  return { valid: true, customerId: payload.customer_id };
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    const { token, tenant_id, booking_id, action, new_start_at } = await req.json();

    if (!token || !tenant_id || !booking_id || !action) {
      return errorResponse("Missing required fields: token, tenant_id, booking_id, action", 400);
    }

    if (!["cancel", "reschedule"].includes(action)) {
      return errorResponse("Invalid action. Must be 'cancel' or 'reschedule'", 400);
    }

    // Verify portal token
    const tokenResult = await verifyPortalToken(token, tenant_id);
    if (!tokenResult.valid) {
      return jsonResponse({ success: false, error: tokenResult.error }, 401);
    }

    const supabase = serviceClient();

    // Fetch the booking and verify it belongs to this customer
    const { data: booking, error: bookingErr } = await supabase
      .from("bookings")
      .select("id, tenant_id, lead_id, status, start_at, leads(customer_id)")
      .eq("id", booking_id)
      .eq("tenant_id", tenant_id)
      .single();

    if (bookingErr || !booking) {
      return errorResponse("Booking not found", 404);
    }

    // Verify the booking belongs to this customer (via lead → customer)
    const leadCustomerId = (booking.leads as any)?.customer_id;
    if (leadCustomerId !== tokenResult.customerId) {
      return errorResponse("Booking does not belong to this customer", 403);
    }

    // Only allow actions on modifiable statuses
    const modifiableStatuses = ["pending", "confirmed"];
    if (!modifiableStatuses.includes(booking.status)) {
      return errorResponse(`Cannot ${action} a booking with status '${booking.status}'`, 422);
    }

    if (action === "cancel") {
      const { error: updateErr } = await supabase
        .from("bookings")
        .update({
          status: "canceled",
          notes: `${booking.notes ? booking.notes + "\n" : ""}[Customer cancelled via portal on ${new Date().toISOString()}]`,
        } as any)
        .eq("id", booking_id);

      if (updateErr) {
        console.error("[portal-booking-action] Cancel error:", updateErr);
        return errorResponse("Failed to cancel booking", 500);
      }

      return jsonResponse({ success: true, action: "cancel", booking_id });
    }

    if (action === "reschedule") {
      if (!new_start_at) {
        return errorResponse("new_start_at is required for reschedule", 400);
      }

      // Validate the new time is in the future
      const newDate = new Date(new_start_at);
      if (isNaN(newDate.getTime()) || newDate <= new Date()) {
        return errorResponse("new_start_at must be a valid future date", 422);
      }

      const { error: updateErr } = await supabase
        .from("bookings")
        .update({
          start_at: new_start_at,
          status: "pending", // Reset to pending for owner re-approval
          notes: `${booking.notes ? booking.notes + "\n" : ""}[Customer rescheduled via portal on ${new Date().toISOString()}. Previous time: ${booking.start_at}]`,
        } as any)
        .eq("id", booking_id);

      if (updateErr) {
        console.error("[portal-booking-action] Reschedule error:", updateErr);
        return errorResponse("Failed to reschedule booking", 500);
      }

      return jsonResponse({ success: true, action: "reschedule", booking_id, new_start_at });
    }

    return errorResponse("Unknown action", 400);
  } catch (err: unknown) {
    console.error("[portal-booking-action] Error:", err);
    const message = err instanceof Error ? err.message : "Internal error";
    return errorResponse(message, 500);
  }
});

/**
 * process-call-outcome
 *
 * Called after elevenlabs-webhook finishes processing a call.
 * Extracts a structured call_outcome record for conversion tracking
 * and fires pattern detection if enough data has accumulated.
 *
 * Payload:
 *   tenant_id, session_id, outcome, intent, service_requested,
 *   duration_seconds, customer_id, business_mode
 */
import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsHeaders, jsonHeaders, corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";
import { requireInternalSecret } from "../_shared/tenant.ts";

interface CallOutcomePayload {
  tenant_id: string;
  session_id: string;
  outcome: string;
  intent?: string;
  service_requested?: string;
  duration_seconds?: number;
  customer_id?: string;
  business_mode?: string;
  escalation_reason?: string;
}

/** Map ai_call_outcome enum values to call_outcomes.outcome_type */
function mapOutcomeType(outcome: string, intent?: string): string {
  switch (outcome) {
    case "booked": return "booked";
    case "order": return "order_placed";
    case "dispatch": return "dispatch_created";
    case "escalated": return "transferred";
    case "followup": return "callback_scheduled";
    case "message": return "voicemail";
    case "lead_captured": return "callback_scheduled";
    case "lost": {
      // Distinguish between hangup and FAQ-only calls
      if (intent === "faq" || intent === "hours_inquiry" || intent === "general_inquiry") {
        return "faq_answered";
      }
      return "hangup";
    }
    default: return "other";
  }
}

/** Estimate conversion value based on outcome and mode */
function estimateConversionValue(outcomeType: string, businessMode: string): number | null {
  if (outcomeType === "hangup" || outcomeType === "voicemail") return null;
  // Conservative estimates in cents - real values come from actual bookings
  switch (outcomeType) {
    case "booked":
      switch (businessMode) {
        case "service": return 15000; // $150
        case "dispatch": return 12500; // $125
        case "medical": return 20000; // $200
        case "food": return 3500; // $35
        default: return 10000; // $100
      }
    case "order_placed":
      return 3500; // $35
    case "dispatch_created":
      return 12500; // $125
    case "callback_scheduled":
      return 5000; // $50 potential
    case "faq_answered":
      return 500; // $5 retention value
    default:
      return null;
  }
}

serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    // Require internal secret — only called from elevenlabs-webhook, not from browsers
    const secret = req.headers.get("x-closeloop-secret") || req.headers.get("authorization")?.replace("Bearer ", "");
    const expectedSecret = Deno.env.get("CLOSELOOP_INTERNAL_SECRET") || Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
    if (!secret || secret !== expectedSecret) {
      return errorResponse("Unauthorized", 401);
    }

    const payload: CallOutcomePayload = await req.json();

    if (!payload.tenant_id || !payload.session_id || !payload.outcome) {
      return errorResponse("Missing required fields: tenant_id, session_id, outcome");
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    const outcomeType = mapOutcomeType(payload.outcome, payload.intent);
    const conversionValue = estimateConversionValue(outcomeType, payload.business_mode || "general");

    // Determine if AI handled fully (no escalation)
    const aiHandledFully = !["transferred", "voicemail"].includes(outcomeType);

    // Insert call outcome
    const { error: insertError } = await supabase
      .from("call_outcomes")
      .insert({
        tenant_id: payload.tenant_id,
        session_id: payload.session_id,
        outcome_type: outcomeType,
        intent: payload.intent || null,
        service_requested: payload.service_requested || null,
        conversion_value_cents: conversionValue,
        duration_seconds: payload.duration_seconds || null,
        ai_handled_fully: aiHandledFully,
        escalation_reason: payload.escalation_reason || null,
      });

    if (insertError) {
      console.error("[process-call-outcome] Insert error:", insertError);
      return errorResponse(`Failed to insert call outcome: ${insertError.message}`, 500);
    }

    // Check if we should trigger pattern detection
    // Only trigger every 10 calls to avoid excessive processing
    const { count } = await supabase
      .from("call_outcomes")
      .select("id", { count: "exact", head: true })
      .eq("tenant_id", payload.tenant_id)
      .gte("created_at", new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString());

    const shouldDetectPatterns = (count || 0) % 10 === 0 && (count || 0) > 0;

    if (shouldDetectPatterns) {
      // Fire-and-forget pattern detection
      try {
        await fetch(`${supabaseUrl}/functions/v1/detect-patterns`, {
          method: "POST",
          headers: { "Content-Type": "application/json", "Authorization": `Bearer ${supabaseKey}` },
          body: JSON.stringify({ tenant_id: payload.tenant_id }),
        });
      } catch (e) {
        console.warn("[process-call-outcome] Failed to trigger pattern detection:", e);
      }
    }

    console.log(`[process-call-outcome] Recorded ${outcomeType} for tenant ${payload.tenant_id.substring(0, 8)}... session ${payload.session_id.substring(0, 8)}...`);

    return jsonResponse({
      success: true,
      outcome_type: outcomeType,
      pattern_detection_triggered: shouldDetectPatterns,
    });
  } catch (err) {
    console.error("[process-call-outcome] Error:", err);
    return errorResponse(`Internal error: ${err instanceof Error ? err.message : "Unknown error"}`, 500);
  }
});

/**
 * process-commission-payout
 *
 * Marks pending commissions as paid. Admin-only (super_admin JWT).
 *
 * Input: { commission_ids: string[], payout_method: string, payout_reference?: string, notes?: string }
 */

import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";
import { serviceClient } from "../_shared/tenant.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();
  if (req.method !== "POST") return errorResponse("Method not allowed", 405);

  try {
    // Auth: verify caller is super_admin
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) return errorResponse("Unauthorized", 401);

    const anonClient = createClient(
      Deno.env.get("SUPABASE_URL")!,
      Deno.env.get("SUPABASE_ANON_KEY")!,
      { global: { headers: { Authorization: authHeader } }, auth: { persistSession: false } }
    );
    const { data: userRes, error: userErr } = await anonClient.auth.getUser();
    if (userErr || !userRes?.user?.id) return errorResponse("Unauthorized", 401);

    const adminUserId = userRes.user.id;
    const svc = serviceClient();

    // Check super_admin role
    const { data: roleRow } = await svc
      .from("user_roles")
      .select("role")
      .eq("user_id", adminUserId)
      .eq("role", "super_admin")
      .maybeSingle();

    if (!roleRow) return errorResponse("Forbidden: super_admin required", 403);

    // Parse input
    const { commission_ids, payout_method, payout_reference, notes } = await req.json();

    if (!Array.isArray(commission_ids) || commission_ids.length === 0) {
      return errorResponse("Missing or empty commission_ids array");
    }
    if (!payout_method || typeof payout_method !== "string") {
      return errorResponse("Missing payout_method");
    }

    // Verify all commissions are pending and belong to the same agency
    const { data: commissions, error: fetchErr } = await svc
      .from("agency_commissions")
      .select("id, agency_id, status")
      .in("id", commission_ids);

    if (fetchErr) return errorResponse("Failed to fetch commissions", 500);
    if (!commissions || commissions.length !== commission_ids.length) {
      return errorResponse("Some commission IDs not found");
    }

    const nonPending = commissions.filter((c: any) => c.status !== "pending");
    if (nonPending.length > 0) {
      return errorResponse(`${nonPending.length} commission(s) are not in 'pending' status`);
    }

    const agencyIds = [...new Set(commissions.map((c: any) => c.agency_id))];
    if (agencyIds.length > 1) {
      return errorResponse("All commissions must belong to the same agency");
    }

    // Update commissions
    const now = new Date().toISOString();
    const { error: updateErr } = await svc
      .from("agency_commissions")
      .update({
        status: "paid",
        paid_at: now,
        payout_method,
        payout_reference: payout_reference || null,
        payout_notes: notes || null,
        approved_by: adminUserId,
      })
      .in("id", commission_ids);

    if (updateErr) {
      console.error("Commission update error:", updateErr);
      return errorResponse("Failed to update commissions", 500);
    }

    // Record audit event
    try {
      await svc.from("audit_events").insert({
        event_type: "commission_paid",
        actor_id: adminUserId,
        metadata: {
          commission_ids,
          agency_id: agencyIds[0],
          payout_method,
          payout_reference: payout_reference || null,
          total_commissions: commissions.length,
        },
      });
    } catch (auditErr) {
      console.error("Audit event error:", auditErr);
    }

    return jsonResponse({
      success: true,
      paid_count: commission_ids.length,
      agency_id: agencyIds[0],
    });
  } catch (err) {
    console.error("process-commission-payout error:", err);
    return errorResponse("Internal error", 500);
  }
});

