async function processFAQs(
  supabase: any,
  tenantId: string,
  sourceId: string,
  faqs: FAQItem[]
): Promise<{ suggestions: number; conflicts: number; matched: number }> {
  let suggestions = 0;
  let conflicts = 0;
  let matched = 0;

  const { data: existingFAQs } = await supabase
    .from("business_faqs")
    .select("id, question, answer")
    .eq("tenant_id", tenantId);

  for (const faq of faqs) {
    const normalizedQuestion = faq.question.toLowerCase().trim();
    
    // Find similar questions
    const existing = existingFAQs?.find((e: any) => {
      const existingNormalized = e.question.toLowerCase().trim();
      return similarity(existingNormalized, normalizedQuestion) > 0.8;
    });

    if (existing) {
      // Check if answer differs significantly
      if (similarity(existing.answer.toLowerCase(), faq.answer.toLowerCase()) < 0.8) {
        await supabase.from("knowledge_conflicts").insert({
          tenant_id: tenantId,
          source_id: sourceId,
          entity_type: "faq",
          existing_entity_id: existing.id,
          existing_data: existing,
          proposed_data: faq,
          differing_fields: ["answer"],
          conflict_type: "field_mismatch"
        });
        conflicts++;
      } else {
        matched++;
      }
    } else {
      await supabase.from("extracted_knowledge_suggestions").insert({
        tenant_id: tenantId,
        source_id: sourceId,
        suggestion_type: "faq",
        extracted_data: faq,
        status: "pending_review"
      });
      suggestions++;
    }
  }

  return { suggestions, conflicts, matched };
}

async function processHours(
  supabase: any,
  tenantId: string,
  sourceId: string,
  hours: HoursItem[]
): Promise<{ suggestions: number; conflicts: number }> {
  let suggestions = 0;
  let conflicts = 0;

  // Get existing availability slots
  const { data: existingSlots } = await supabase
    .from("availability_slots")
    .select("*")
    .eq("tenant_id", tenantId);

  const dayToNumber: Record<string, number> = {
    sunday: 0,
    monday: 1,
    tuesday: 2,
    wednesday: 3,
    thursday: 4,
    friday: 5,
    saturday: 6
  };

  for (const hour of hours) {
    const dayNum = dayToNumber[hour.day.toLowerCase()];
    if (dayNum === undefined) continue;

    const existing = existingSlots?.find((e: any) => e.day_of_week === dayNum);

    if (existing) {
      // Check for conflicts
      const differingFields: string[] = [];
      const proposedOpen = hour.open || (hour.closed ? null : undefined);
      const proposedClose = hour.close || (hour.closed ? null : undefined);
      
      if (proposedOpen && existing.start_time !== proposedOpen) {
        differingFields.push("start_time");
      }
      if (proposedClose && existing.end_time !== proposedClose) {
        differingFields.push("end_time");
      }
      if (hour.closed !== undefined && existing.is_available === hour.closed) {
        differingFields.push("is_available");
      }

      if (differingFields.length > 0) {
        await supabase.from("knowledge_conflicts").insert({
          tenant_id: tenantId,
          source_id: sourceId,
          entity_type: "hours",
          existing_entity_id: existing.id,
          existing_data: {
            day: hour.day,
            start_time: existing.start_time,
            end_time: existing.end_time,
            is_available: existing.is_available
          },
          proposed_data: {
            day: hour.day,
            start_time: hour.open,
            end_time: hour.close,
            is_available: !hour.closed
          },
          differing_fields: differingFields,
          conflict_type: "field_mismatch"
        });
        conflicts++;
      }
    } else {
      // Create suggestion for new hours
      await supabase.from("extracted_knowledge_suggestions").insert({
        tenant_id: tenantId,
        source_id: sourceId,
        suggestion_type: "hours" as any,
        extracted_data: {
          day_of_week: dayNum,
          day_name: hour.day,
          start_time: hour.open,
          end_time: hour.close,
          is_available: !hour.closed
        },
        status: "pending_review"
      });
      suggestions++;
    }
  }

  return { suggestions, conflicts };
}

async function processPolicies(
  supabase: any,
  tenantId: string,
  sourceId: string,
  policies: PolicyData
): Promise<void> {
  // Get current tenant policies
  const { data: tenant } = await supabase
    .from("tenants")
    .select("cancellation_policy, refund_policy, deposit_policy")
    .eq("id", tenantId)
    .single();

  // Check for conflicts with existing policies
  const differingFields: string[] = [];
  const existingData: any = {};
  const proposedData: any = {};

  if (policies.cancellation && tenant?.cancellation_policy && 
      tenant.cancellation_policy !== policies.cancellation) {
    differingFields.push("cancellation_policy");
    existingData.cancellation_policy = tenant.cancellation_policy;
    proposedData.cancellation_policy = policies.cancellation;
  }

  if (policies.refund && tenant?.refund_policy && 
      tenant.refund_policy !== policies.refund) {
    differingFields.push("refund_policy");
    existingData.refund_policy = tenant.refund_policy;
    proposedData.refund_policy = policies.refund;
  }

  if (policies.deposit && tenant?.deposit_policy && 
      tenant.deposit_policy !== policies.deposit) {
    differingFields.push("deposit_policy");
    existingData.deposit_policy = tenant.deposit_policy;
    proposedData.deposit_policy = policies.deposit;
  }

  if (differingFields.length > 0) {
    await supabase.from("knowledge_conflicts").insert({
      tenant_id: tenantId,
      source_id: sourceId,
      entity_type: "policy",
      existing_data: existingData,
      proposed_data: proposedData,
      differing_fields: differingFields,
      conflict_type: "field_mismatch"
    });
  } else if (Object.keys(policies).some(k => policies[k as keyof PolicyData])) {
    // No conflicts, create suggestion for new policies
    await supabase.from("extracted_knowledge_suggestions").insert({
      tenant_id: tenantId,
      source_id: sourceId,
      suggestion_type: "policy",
      extracted_data: policies,
      status: "pending_review"
    });
  }
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";

interface ProcessResponseRequest {
  tenant_id: string;
  customer_id?: string;
  customer_phone?: string;
  response_type: "sms_reply" | "inbound_call" | "manual";
  response_content: string;
  call_session_id?: string;
}

interface ResponseAnalysis {
  sentiment: "positive" | "neutral" | "negative";
  outcome: "interested" | "question" | "not_now" | "declined";
}

interface ProcessResponseResult {
  success: boolean;
  reason?: string;
  campaign_id?: string;
  response_outcome?: string;
  campaign_status?: string;
  notification_sent?: boolean;
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const body: ProcessResponseRequest = await req.json();
    const {
      tenant_id,
      customer_id,
      customer_phone,
      response_type,
      response_content,
      call_session_id,
    } = body;

    if (!tenant_id) {
      return jsonResponse({ success: false, reason: "missing_tenant_id" }, 400);
    }

    if (!customer_id && !customer_phone) {
      return jsonResponse({ success: false, reason: "missing_customer_identifier" }, 400);
    }

    // Step 1: Find the active campaign
    let finalCustomerId = customer_id;
    
    // If no customer_id, look up by phone
    if (!finalCustomerId && customer_phone) {
      const { data: customer } = await supabase
        .from("customers")
        .select("id")
        .eq("tenant_id", tenant_id)
        .eq("phone_e164", customer_phone)
        .maybeSingle();

      if (customer) {
        finalCustomerId = customer.id;
      }
    }

    if (!finalCustomerId) {
      return jsonResponse({ success: false, reason: "customer_not_found" });
    }

    // Find active campaign
    const { data: campaign, error: campaignError } = await supabase
      .from("lead_recovery_campaigns")
      .select(`
        *,
        customer:customers(*),
        lead:leads!lead_recovery_campaigns_lead_id_fkey(*)
      `)
      .eq("tenant_id", tenant_id)
      .eq("customer_id", finalCustomerId)
      .in("status", ["active", "paused"])
      .order("created_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (campaignError || !campaign) {
      console.log("No active campaign found for customer:", finalCustomerId);
      return jsonResponse({ success: false, reason: "no_active_campaign" });
    }

    // Get recovery settings
    const { data: settings } = await supabase
      .from("lead_recovery_settings")
      .select("*")
      .eq("tenant_id", tenant_id)
      .maybeSingle();

    // Get assistant settings for notifications
    const { data: assistantSettings } = await supabase
      .from("assistant_settings")
      .select("closeloop_number, business_name")
      .eq("tenant_id", tenant_id)
      .maybeSingle();

    // Step 2: Analyze the response
    const analysis = analyzeResponse(response_content, response_type);
    console.log(`Response analysis for campaign ${campaign.id}:`, analysis);

    // Step 3: Log the response - update most recent action
    const { data: recentAction } = await supabase
      .from("lead_recovery_actions")
      .select("id")
      .eq("campaign_id", campaign.id)
      .eq("response_received", false)
      .order("executed_at", { ascending: false })
      .limit(1)
      .maybeSingle();

    if (recentAction) {
      await supabase
        .from("lead_recovery_actions")
        .update({
          response_received: true,
          response_at: new Date().toISOString(),
          response_content: response_content,
          response_sentiment: analysis.sentiment,
          response_outcome: analysis.outcome,
        })
        .eq("id", recentAction.id);
    } else {
      // Create a new action record for this response
      await supabase.from("lead_recovery_actions").insert({
        campaign_id: campaign.id,
        step_id: null,
        action_type: response_type === "inbound_call" ? "inbound_call" : "sms_response",
        executed_at: new Date().toISOString(),
        message_sent: null,
        call_session_id: call_session_id || null,
        delivery_status: "received",
        response_received: true,
        response_at: new Date().toISOString(),
        response_content: response_content,
        response_sentiment: analysis.sentiment,
        response_outcome: analysis.outcome,
      });
    }

    // Step 4: Update campaign based on outcome
    let newCampaignStatus = campaign.status;
    let notificationSent = false;

    if (analysis.outcome === "declined") {
      // Customer declined
      newCampaignStatus = "declined";
      
      await supabase
        .from("lead_recovery_campaigns")
        .update({
          status: "declined",
          stopped_at: new Date().toISOString(),
          stopped_reason: `Customer responded: "${response_content.substring(0, 100)}"`,
          total_responses: campaign.total_responses + 1,
          last_response_at: new Date().toISOString(),
        })
        .eq("id", campaign.id);

      // Update lead
      if (campaign.lead_id) {
        await supabase
          .from("leads")
          .update({ recovery_status: "declined" })
          .eq("id", campaign.lead_id);
      }

      // Check for opt-out keywords
      const lowerContent = response_content.toLowerCase();
      if (lowerContent.includes("stop") || lowerContent.includes("unsubscribe") || lowerContent.includes("remove")) {
        await supabase
          .from("customers")
          .update({ do_not_contact: true })
          .eq("id", finalCustomerId);
        
        console.log(`Customer ${finalCustomerId} opted out of all contact`);
      }

    } else if (analysis.outcome === "interested" || analysis.outcome === "question") {
      // Customer is interested or has questions - pause and notify
      newCampaignStatus = "paused";
      
      await supabase
        .from("lead_recovery_campaigns")
        .update({
          status: "paused",
          total_responses: campaign.total_responses + 1,
          last_response_at: new Date().toISOString(),
          notes: `${campaign.notes || ""}\n[${new Date().toISOString()}] Customer responded (${analysis.outcome}): "${response_content}"`.trim(),
        })
        .eq("id", campaign.id);

      // Step 5: Notify business owner
      if (settings?.notify_on_response) {
        notificationSent = await sendOwnerNotification(
          supabase,
          tenant_id,
          campaign,
          response_content,
          analysis,
          settings,
          assistantSettings
        );
      }

    } else {
      // Neutral response (not_now) - keep sequence going but log it
      await supabase
        .from("lead_recovery_campaigns")
        .update({
          total_responses: campaign.total_responses + 1,
          last_response_at: new Date().toISOString(),
        })
        .eq("id", campaign.id);
    }

    // If this was an inbound call, link the call session
    if (call_session_id) {
      await supabase
        .from("ai_call_sessions")
        .update({
          is_recovery_call: true,
          recovery_campaign_id: campaign.id,
          recovery_context: {
            campaign_id: campaign.id,
            original_intent: campaign.original_intent,
            original_service: campaign.original_service_interest,
            response_type: response_type,
          },
        })
        .eq("id", call_session_id);
    }

    console.log(`Processed recovery response for campaign ${campaign.id}: ${analysis.outcome}`);

    return jsonResponse({
      success: true,
      campaign_id: campaign.id,
      response_outcome: analysis.outcome,
      campaign_status: newCampaignStatus,
      notification_sent: notificationSent,
    });

  } catch (error) {
    console.error("Error in process-recovery-response:", error);
    return jsonResponse(
      { success: false, reason: "internal_error", message: String(error) },
      500
    );
  }
});

/**
 * Analyze customer response to determine sentiment and outcome
 */
function analyzeResponse(text: string, responseType: string): ResponseAnalysis {
  // Inbound calls are always positive signals
  if (responseType === "inbound_call") {
    return { sentiment: "positive", outcome: "interested" };
  }

  if (!text || text.trim().length === 0) {
    return { sentiment: "neutral", outcome: "not_now" };
  }

  const lowerText = text.toLowerCase().trim();

  // Positive signals
  const positiveKeywords = [
    "yes", "yeah", "yep", "yup", "ok", "okay", "sure", "absolutely",
    "schedule", "book", "appointment", "interested", "call me", "ready",
    "sounds good", "let's do it", "i'm in", "sign me up", "available",
    "perfect", "great", "awesome", "please", "when can", "what time"
  ];
  const isPositive = positiveKeywords.some(k => lowerText.includes(k));

  // Strong negative signals (opt-out)
  const optOutKeywords = ["stop", "unsubscribe", "remove", "opt out", "opt-out"];
  const isOptOut = optOutKeywords.some(k => lowerText.includes(k));

  // Negative signals
  const negativeKeywords = [
    "no", "nope", "not interested", "don't", "dont", "cant", "can't",
    "won't", "wont", "never", "go away", "leave me alone", "wrong number",
    "already", "found someone", "went with", "not now", "busy"
  ];
  const isNegative = negativeKeywords.some(k => lowerText.includes(k)) || isOptOut;

  // Questions
  const questionIndicators = ["?", "how much", "what is", "when", "where", "who", "which", "cost", "price", "available"];
  const isQuestion = questionIndicators.some(q => lowerText.includes(q));

  // Determine outcome
  if (isOptOut) {
    return { sentiment: "negative", outcome: "declined" };
  }
  
  if (isNegative && !isPositive) {
    return { sentiment: "negative", outcome: "declined" };
  }
  
  if (isPositive) {
    return { sentiment: "positive", outcome: "interested" };
  }
  
  if (isQuestion) {
    return { sentiment: "neutral", outcome: "question" };
  }

  return { sentiment: "neutral", outcome: "not_now" };
}

/**
 * Send notification to business owner about customer response
 */
async function sendOwnerNotification(
  supabase: any,
  tenantId: string,
  campaign: any,
  responseContent: string,
  analysis: ResponseAnalysis,
  settings: any,
  assistantSettings: any
): Promise<boolean> {
  try {
    const customer = campaign.customer;
    const customerName = customer?.full_name || "A customer";
    const customerPhone = customer?.phone_e164 || "";

    // Create in-app notification via audit_events
    await supabase.from("audit_events").insert({
      tenant_id: tenantId,
      event_type: "lead.recovery_response",
      entity_type: "lead_recovery_campaign",
      entity_id: campaign.id,
      actor_type: "customer",
      actor_id: customer?.id,
      payload: {
        customer_name: customerName,
        customer_phone: customerPhone,
        response_content: responseContent,
        response_outcome: analysis.outcome,
        response_sentiment: analysis.sentiment,
        campaign_id: campaign.id,
        action_url: `/app/leads/recovery/${campaign.id}`,
        priority: "high",
      },
    });

    // Build notification message
    const outcomeEmoji = analysis.outcome === "interested" ? "🎉" : "❓";
    const message = `${outcomeEmoji} ${customerName} responded to follow-up!\n\n"${responseContent}"\n\nCall them: ${customerPhone}`;

    // Send SMS notification if configured
    if (settings.notification_sms && assistantSettings?.closeloop_number) {
      try {
        await supabase.functions.invoke("send-sms", {
          body: {
            to: settings.notification_sms,
            from: assistantSettings.closeloop_number,
            body: message,
            tenant_id: tenantId,
          },
        });
      } catch (smsError) {
        console.error("Failed to send SMS notification:", smsError);
      }
    }

    // Send email notification if configured
    if (settings.notification_email) {
      console.log(`Would send email notification to ${settings.notification_email}`);
      // TODO: Integrate with email service
    }

    return true;
  } catch (error) {
    console.error("Error sending owner notification:", error);
    return false;
  }
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const url = new URL(req.url);
    const imageUrl = url.searchParams.get("url");

    if (!imageUrl) {
      return new Response("Missing url param", { status: 400, headers: corsHeaders });
    }

    // Only allow proxying from known CDN domains
    const allowed = ["cdn05.carsforsale.com", "cdn04.carsforsale.com", "cdn03.carsforsale.com", "cdn02.carsforsale.com", "cdn01.carsforsale.com"];
    const parsed = new URL(imageUrl);
    if (!allowed.some(d => parsed.hostname === d)) {
      return new Response("Domain not allowed", { status: 403, headers: corsHeaders });
    }

    const response = await fetch(imageUrl, {
      headers: {
        "Referer": "https://www.carsforsale.com/",
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
      },
    });

    if (!response.ok) {
      return new Response("Image fetch failed", { status: response.status, headers: corsHeaders });
    }

    const body = await response.arrayBuffer();
    const contentType = response.headers.get("content-type") || "image/jpeg";

    return new Response(body, {
      headers: {
        ...corsHeaders,
        "Content-Type": contentType,
        "Cache-Control": "public, max-age=86400",
      },
    });
  } catch (e) {
    return new Response("Error", { status: 500, headers: corsHeaders });
  }
});

/**
 * public-roi-report
 *
 * Returns sanitized ROI data for a public shareable report.
 * No auth required -- access gated by share_token validated against tenant_revenue_settings.
 * Uses serviceClient for all queries (no user JWT).
 * NO PII is returned (no customer names, phones, emails).
 */

import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { serviceClient } from "../_shared/tenant.ts";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    // Accept params from GET query string or POST body
    let tenantId: string | null = null;
    let shareToken: string | null = null;

    if (req.method === "GET") {
      const url = new URL(req.url);
      tenantId = url.searchParams.get("tenant_id");
      shareToken = url.searchParams.get("share_token");
    } else {
      const body = await req.json().catch(() => ({}));
      tenantId = body.tenant_id ?? null;
      shareToken = body.share_token ?? null;
    }

    if (!tenantId || !shareToken) {
      return errorResponse("Missing tenant_id or share_token", 400);
    }

    const svc = serviceClient();

    // Validate share_token against tenant_revenue_settings
    const { data: revSettings, error: revErr } = await svc
      .from("tenant_revenue_settings")
      .select("id, share_token")
      .eq("tenant_id", tenantId)
      .maybeSingle();

    if (revErr) {
      console.error("[public-roi-report] revenue settings lookup error:", revErr);
      return errorResponse("Failed to validate share link", 500);
    }

    if (!revSettings || revSettings.share_token !== shareToken) {
      return errorResponse("Invalid or expired share link", 403);
    }

    // Fetch tenant name and business_mode (no sensitive data)
    const { data: tenant, error: tenantErr } = await svc
      .from("tenants")
      .select("id, business_name, business_mode")
      .eq("id", tenantId)
      .maybeSingle();

    if (tenantErr || !tenant) {
      console.error("[public-roi-report] tenant lookup error:", tenantErr);
      return errorResponse("Tenant not found", 404);
    }

    // Aggregate ROI data -- NO PII

    // Total calls handled
    const { count: totalCalls } = await svc
      .from("ai_call_sessions")
      .select("id", { count: "exact", head: true })
      .eq("tenant_id", tenantId);

    // Bookings created
    const { count: totalBookings } = await svc
      .from("bookings")
      .select("id", { count: "exact", head: true })
      .eq("tenant_id", tenantId);

    // Dispatch jobs created
    const { count: totalDispatchJobs } = await svc
      .from("dispatch_jobs")
      .select("id", { count: "exact", head: true })
      .eq("tenant_id", tenantId);

    // Food orders created
    const { count: totalFoodOrders } = await svc
      .from("food_orders")
      .select("id", { count: "exact", head: true })
      .eq("tenant_id", tenantId);

    // Revenue attributed (sum)
    const { data: revenueRows } = await svc
      .from("revenue_attributions")
      .select("revenue_cents")
      .eq("tenant_id", tenantId);

    const totalRevenueCents = (revenueRows ?? []).reduce(
      (sum, r) => sum + (r.revenue_cents ?? 0),
      0
    );

    // Conversion rate: sessions with outcome='booked' / total sessions
    const { count: bookedCount } = await svc
      .from("ai_call_sessions")
      .select("id", { count: "exact", head: true })
      .eq("tenant_id", tenantId)
      .eq("outcome", "booked");

    const totalCallsNum = totalCalls ?? 0;
    const bookedNum = bookedCount ?? 0;
    const conversionRate =
      totalCallsNum > 0
        ? Math.round((bookedNum / totalCallsNum) * 10000) / 10000
        : 0;

    const totalEntitiesCreated =
      (totalBookings ?? 0) + (totalDispatchJobs ?? 0) + (totalFoodOrders ?? 0);

    return jsonResponse({
      tenant_name: tenant.business_name,
      business_mode: tenant.business_mode,
      total_calls_handled: totalCallsNum,
      entities_created: {
        bookings: totalBookings ?? 0,
        dispatch_jobs: totalDispatchJobs ?? 0,
        food_orders: totalFoodOrders ?? 0,
        total: totalEntitiesCreated,
      },
      total_revenue_attributed_cents: totalRevenueCents,
      conversion_rate: conversionRate,
    });
  } catch (err) {
    console.error("[public-roi-report] Error:", err);
    const message = err instanceof Error ? err.message : "Internal server error";
    return errorResponse(message, 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsHeaders, jsonResponse, errorResponse, corsResponse } from "../_shared/cors.ts";
import { serviceClient } from "../_shared/tenant.ts";

/**
 * register-a2p-10dlc
 * 
 * Orchestrates the full Twilio A2P 10DLC registration pipeline for a tenant.
 * Called automatically after number provisioning succeeds.
 * 
 * Steps:
 * 1. Create Secondary Customer Profile (TrustHub)
 * 2. Create Brand Registration
 * 3. Create Messaging Service + link phone number
 * 4. Create Campaign (UsAppToPerson)
 * 
 * Each step updates the a2p_registrations table with SIDs and status.
 */

interface A2PRequest {
  tenant_id: string;
  phone_number_sid?: string; // Twilio phone number SID to add to messaging service
  phone_e164?: string; // The actual phone number
}

// Map our entity types to Twilio's expected values
const ENTITY_TYPE_MAP: Record<string, string> = {
  sole_proprietorship: "Sole Proprietorship",
  llc: "Limited Liability Corporation",
  corporation: "Corporation",
  partnership: "Partnership",
  non_profit: "Non-profit Corporation",
};

// Map industry to Twilio vertical
function mapIndustryToVertical(industrySlug: string): string {
  const verticalMap: Record<string, string> = {
    // Service
    "plumber": "PROFESSIONAL",
    "electrician": "PROFESSIONAL",
    "hvac": "PROFESSIONAL",
    "landscaping": "PROFESSIONAL",
    "cleaning": "PROFESSIONAL",
    "auto-repair": "AUTOMOTIVE",
    "auto-detailing": "AUTOMOTIVE",
    // Medical
    "dental": "HEALTHCARE",
    "medical-clinic": "HEALTHCARE",
    "veterinary": "HEALTHCARE",
    "chiropractor": "HEALTHCARE",
    // Food
    "restaurant": "FOOD_AND_BEVERAGE",
    "pizza": "FOOD_AND_BEVERAGE",
    "catering": "FOOD_AND_BEVERAGE",
    // Dispatch
    "towing": "TRANSPORTATION",
    "moving": "TRANSPORTATION",
    "courier": "TRANSPORTATION",
  };
  return verticalMap[industrySlug] || "PROFESSIONAL";
}

serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();

  const TWILIO_ACCOUNT_SID = Deno.env.get("TWILIO_ACCOUNT_SID");
  const TWILIO_AUTH_TOKEN = Deno.env.get("TWILIO_AUTH_TOKEN");
  const TWILIO_ISV_PROFILE_SID = Deno.env.get("TWILIO_ISV_PROFILE_SID"); // Primary ISV Business Profile SID
  const TWILIO_A2P_POLICY_SID = Deno.env.get("TWILIO_A2P_POLICY_SID"); // A2P TrustHub policy SID
  const SUPABASE_URL = Deno.env.get("SUPABASE_URL");

  if (!TWILIO_ACCOUNT_SID || !TWILIO_AUTH_TOKEN) {
    return errorResponse("Twilio credentials not configured", 500);
  }

  const supabase = serviceClient();
  const twilioAuth = btoa(`${TWILIO_ACCOUNT_SID}:${TWILIO_AUTH_TOKEN}`);

  try {
    const { tenant_id, phone_number_sid, phone_e164 }: A2PRequest = await req.json();
    if (!tenant_id) return errorResponse("tenant_id is required");

    console.log(`[register-a2p] Starting A2P registration for tenant ${tenant_id}`);

    // Fetch A2P registration data
    const { data: a2p, error: a2pError } = await supabase
      .from("a2p_registrations")
      .select("*")
      .eq("tenant_id", tenant_id)
      .maybeSingle();

    if (a2pError || !a2p) {
      console.error("[register-a2p] No A2P registration found:", a2pError);
      return errorResponse("No A2P registration data found for tenant");
    }

    // Fetch tenant for industry info
    const { data: tenant } = await supabase
      .from("tenants")
      .select("industry, business_name")
      .eq("id", tenant_id)
      .single();

    // ========== STEP 1: Create Secondary Customer Profile ==========
    if (!a2p.customer_profile_sid) {
      console.log("[register-a2p] Step 1: Creating Customer Profile...");

      await updateStatus(supabase, tenant_id, "pending_profile");

      // 1a. Create the Customer Profile
      const profileRes = await twilioPost(
        `https://trusthub.twilio.com/v1/CustomerProfiles`,
        {
          FriendlyName: `${a2p.legal_business_name || tenant?.business_name} - A2P`,
          Email: a2p.contact_email || "",
          PolicySid: TWILIO_A2P_POLICY_SID || "RNdfbf3fae0e1107f8aded0e7cead80bf5", // Default A2P Messaging policy
          StatusCallback: `${SUPABASE_URL}/functions/v1/a2p-status-webhook`,
        },
        twilioAuth
      );

      if (!profileRes.ok) {
        const err = await profileRes.text();
        console.error("[register-a2p] Customer Profile creation failed:", err);
        await updateStatus(supabase, tenant_id, "failed", `Customer Profile failed: ${err}`);
        return errorResponse(`Customer Profile creation failed: ${err}`, 500);
      }

      const profileData = await profileRes.json();
      const customerProfileSid = profileData.sid;
      console.log(`[register-a2p] Customer Profile created: ${customerProfileSid}`);

      // 1b. Create EndUser resource with business info
      const endUserRes = await twilioPost(
        `https://trusthub.twilio.com/v1/EndUsers`,
        {
          FriendlyName: a2p.legal_business_name || tenant?.business_name || "",
          Type: "customer_profile_business_information",
          "Attributes": JSON.stringify({
            business_name: a2p.legal_business_name || tenant?.business_name,
            business_identity: ENTITY_TYPE_MAP[a2p.entity_type || "llc"] || "Limited Liability Corporation",
            business_type: mapIndustryToVertical(tenant?.industry || ""),
            business_registration_identifier: (a2p.ein || "").replace(/-/g, ""),
            business_registration_number: (a2p.ein || "").replace(/-/g, ""),
            business_regions_of_operation: "US",
            website_url: a2p.website_url || "",
            social_media_profile_urls: "",
            business_industry: mapIndustryToVertical(tenant?.industry || ""),
          }),
        },
        twilioAuth
      );

      if (endUserRes.ok) {
        const endUserData = await endUserRes.json();
        // 1c. Attach EndUser to Customer Profile
        await twilioPost(
          `https://trusthub.twilio.com/v1/CustomerProfiles/${customerProfileSid}/EntityAssignments`,
          { ObjectSid: endUserData.sid },
          twilioAuth
        );
      }

      // 1d. Create address and attach
      const addressRes = await twilioPost(
        `https://api.twilio.com/2010-04-01/Accounts/${TWILIO_ACCOUNT_SID}/Addresses.json`,
        {
          FriendlyName: a2p.legal_business_name || "",
          CustomerName: a2p.legal_business_name || "",
          Street: a2p.street_address || "",
          City: a2p.city || "",
          Region: a2p.state || "",
          PostalCode: a2p.zip_code || "",
          IsoCountry: "US",
        },
        twilioAuth
      );

      if (addressRes.ok) {
        const addressData = await addressRes.json();
        // Create supporting doc for address
        const docRes = await twilioPost(
          `https://trusthub.twilio.com/v1/SupportingDocuments`,
          {
            FriendlyName: "Business Address",
            Type: "customer_profile_address",
            "Attributes": JSON.stringify({
              address_sids: addressData.sid,
            }),
          },
          twilioAuth
        );
        if (docRes.ok) {
          const docData = await docRes.json();
          await twilioPost(
            `https://trusthub.twilio.com/v1/CustomerProfiles/${customerProfileSid}/EntityAssignments`,
            { ObjectSid: docData.sid },
            twilioAuth
          );
        }
      }

      // 1e. Create authorized representative
      const repRes = await twilioPost(
        `https://trusthub.twilio.com/v1/EndUsers`,
        {
          FriendlyName: `${a2p.contact_first_name || ""} ${a2p.contact_last_name || ""}`.trim(),
          Type: "authorized_representative_1",
          "Attributes": JSON.stringify({
            first_name: a2p.contact_first_name || "",
            last_name: a2p.contact_last_name || "",
            email: a2p.contact_email || "",
            phone_number: a2p.contact_phone || "",
            business_title: "Owner",
            job_position: "Owner",
          }),
        },
        twilioAuth
      );

      if (repRes.ok) {
        const repData = await repRes.json();
        await twilioPost(
          `https://trusthub.twilio.com/v1/CustomerProfiles/${customerProfileSid}/EntityAssignments`,
          { ObjectSid: repData.sid },
          twilioAuth
        );
      }

      // 1f. Submit Customer Profile for evaluation
      await twilioPost(
        `https://trusthub.twilio.com/v1/CustomerProfiles/${customerProfileSid}/Evaluations`,
        { PolicySid: TWILIO_A2P_POLICY_SID || "RNdfbf3fae0e1107f8aded0e7cead80bf5" },
        twilioAuth
      );

      // Save profile SID
      await supabase
        .from("a2p_registrations")
        .update({ customer_profile_sid: customerProfileSid })
        .eq("tenant_id", tenant_id);
    }

    // ========== STEP 2: Create Brand Registration ==========
    const { data: refreshedA2p } = await supabase
      .from("a2p_registrations")
      .select("*")
      .eq("tenant_id", tenant_id)
      .single();

    if (refreshedA2p?.customer_profile_sid && !refreshedA2p.brand_sid) {
      console.log("[register-a2p] Step 2: Creating Brand Registration...");
      await updateStatus(supabase, tenant_id, "pending_brand");

      const brandRes = await twilioPost(
        `https://messaging.twilio.com/v1/a2p/BrandRegistrations`,
        {
          CustomerProfileBundleSid: refreshedA2p.customer_profile_sid,
          A2PProfileBundleSid: TWILIO_ISV_PROFILE_SID || refreshedA2p.customer_profile_sid,
        },
        twilioAuth
      );

      if (!brandRes.ok) {
        const err = await brandRes.text();
        console.error("[register-a2p] Brand Registration failed:", err);
        await updateStatus(supabase, tenant_id, "failed", `Brand Registration failed: ${err}`);
        return errorResponse(`Brand Registration failed: ${err}`, 500);
      }

      const brandData = await brandRes.json();
      console.log(`[register-a2p] Brand Registration created: ${brandData.sid}, status: ${brandData.status}`);

      await supabase
        .from("a2p_registrations")
        .update({
          brand_sid: brandData.sid,
          brand_score: brandData.brand_score || null,
        })
        .eq("tenant_id", tenant_id);
    }

    // ========== STEP 3: Create Messaging Service ==========
    const { data: a2pStep3 } = await supabase
      .from("a2p_registrations")
      .select("*")
      .eq("tenant_id", tenant_id)
      .single();

    if (a2pStep3?.brand_sid && !a2pStep3.messaging_service_sid) {
      console.log("[register-a2p] Step 3: Creating Messaging Service...");

      const msgSvcRes = await twilioPost(
        `https://messaging.twilio.com/v1/Services`,
