          InboundRequestUrl: `${SUPABASE_URL}/functions/v1/twilio-sms-webhook`,
          InboundMethod: "POST",
          UseInboundWebhookOnNumber: "false",
          FallbackToLongCode: "true",
          StickySender: "true",
        },
