interface KnowledgeSnippet {
  source_type: 'faq' | 'objection' | 'policy' | 'service' | 'upsell' | 'intake';
  id: string;
  title: string;
  content: string;
  relevance_score: number;
  metadata?: Record<string, unknown>;
}

// Simple keyword-based relevance scoring
function calculateRelevance(query: string, text: string): number {
  const queryWords = query.toLowerCase().split(/\s+/).filter(w => w.length > 2);
  const textLower = text.toLowerCase();
  
  let score = 0;
  let exactMatches = 0;
  
  for (const word of queryWords) {
    if (textLower.includes(word)) {
      score += 1;
      // Bonus for exact word match (not just substring)
      if (new RegExp(`\\b${word}\\b`).test(textLower)) {
        exactMatches += 1;
      }
    }
  }
  
  // Normalize by query length and add bonus for exact matches
  const baseScore = queryWords.length > 0 ? score / queryWords.length : 0;
  const exactBonus = exactMatches * 0.1;
  
  return Math.min(baseScore + exactBonus, 1);
}

// Intent-based boosting
function getIntentBoost(intent: string, sourceType: string): number {
  const boosts: Record<string, Record<string, number>> = {
    booking: { service: 0.3, intake: 0.2 },
    quote: { service: 0.4, policy: 0.1 },
    service_info: { service: 0.4, faq: 0.2 },
    pricing: { service: 0.5 },
    cancel: { policy: 0.5 },
    reschedule: { policy: 0.3, service: 0.2 },
    hours: { faq: 0.3 },
    location: { faq: 0.3 },
    objection: { objection: 0.5 },
    urgent: { policy: 0.3 },
  };
  
  return boosts[intent]?.[sourceType] || 0;
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const { tenantId, queryText, intent, topK = 8 } = await req.json();

    if (!tenantId || !queryText) {
      return new Response(
        JSON.stringify({ error: "Tenant ID and query text are required" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseKey);

    // Fetch all knowledge sources in parallel
    const [
      faqsResult,
      objectionsResult,
      servicesResult,
      knowledgeBaseResult,
      tenantResult,
    ] = await Promise.all([
      supabase.from("business_faqs").select("*").eq("tenant_id", tenantId),
      supabase.from("objection_responses").select("*").eq("tenant_id", tenantId),
      supabase.from("services").select("*").eq("tenant_id", tenantId).eq("is_active", true),
      supabase.from("ai_knowledge_base").select("*").eq("tenant_id", tenantId),
      supabase.from("tenants").select("context_fields_json, cancellation_policy, deposit_policy, refund_policy").eq("id", tenantId).single(),
    ]);

    const snippets: KnowledgeSnippet[] = [];
    const detectedIntent = intent || 'general';

    // Process FAQs
    for (const faq of faqsResult.data || []) {
      const searchText = `${faq.question} ${faq.answer}`;
      const baseScore = calculateRelevance(queryText, searchText);
      const intentBoost = getIntentBoost(detectedIntent, 'faq');
      const priorityBoost = (faq.priority_weight || 0) * 0.05;
      
      snippets.push({
        source_type: 'faq',
        id: faq.id,
        title: faq.question,
        content: faq.answer,
        relevance_score: baseScore + intentBoost + priorityBoost,
      });
    }

    // Process objection responses
    for (const obj of objectionsResult.data || []) {
      const searchText = `${obj.objection} ${obj.response}`;
      const baseScore = calculateRelevance(queryText, searchText);
      const intentBoost = getIntentBoost(detectedIntent, 'objection');
      const priorityBoost = (obj.priority_weight || 0) * 0.05;
      
      snippets.push({
        source_type: 'objection',
        id: obj.id,
        title: obj.objection,
        content: obj.response,
        relevance_score: baseScore + intentBoost + priorityBoost,
      });
    }

    // Process services
    for (const svc of servicesResult.data || []) {
      const searchText = `${svc.name} ${svc.description || ''} ${svc.preparation_instructions || ''}`;
      const baseScore = calculateRelevance(queryText, searchText);
      const intentBoost = getIntentBoost(detectedIntent, 'service');
      
      let content = `${svc.description || 'No description available'}`;
      if (svc.price_type === 'fixed' && svc.price_amount) {
        content += ` Price: $${svc.price_amount}.`;
      } else if (svc.price_type === 'starting_at' && svc.price_amount) {
        content += ` Starting at $${svc.price_amount}.`;
      } else {
        content += ` Price: Quote required.`;
      }
      content += ` Duration: ${svc.duration_minutes} minutes.`;
      if (svc.deposit_required && svc.deposit_amount) {
        content += ` Deposit: $${svc.deposit_amount} required.`;
      }
      
      snippets.push({
        source_type: 'service',
        id: svc.id,
        title: svc.name,
        content,
        relevance_score: baseScore + intentBoost,
        metadata: {
          price_type: svc.price_type,
          price_amount: svc.price_amount,
          duration_minutes: svc.duration_minutes,
          deposit_required: svc.deposit_required,
          deposit_amount: svc.deposit_amount,
          upsells: svc.upsell_suggestions,
        },
      });

      // Add preparation instructions as separate snippet if exists
      if (svc.preparation_instructions) {
        const prepScore = calculateRelevance(queryText, svc.preparation_instructions);
        snippets.push({
          source_type: 'service',
          id: `${svc.id}-prep`,
          title: `${svc.name} - Preparation`,
          content: svc.preparation_instructions,
          relevance_score: prepScore + 0.1,
        });
      }
    }

    // Process knowledge base items
    for (const kb of knowledgeBaseResult.data || []) {
      const searchText = `${kb.title} ${kb.content}`;
      const baseScore = calculateRelevance(queryText, searchText);
      const intentBoost = getIntentBoost(detectedIntent, kb.type);
      const priorityBoost = (kb.priority_weight || 0) * 0.05;
      
      snippets.push({
        source_type: kb.type as any,
        id: kb.id,
        title: kb.title,
        content: kb.content,
        relevance_score: baseScore + intentBoost + priorityBoost,
      });
    }

    // Add tenant policies as snippets
    const tenant = tenantResult.data;
    if (tenant) {
      if (tenant.cancellation_policy) {
        const score = calculateRelevance(queryText, `cancel cancellation policy ${tenant.cancellation_policy}`);
        snippets.push({
          source_type: 'policy',
          id: 'cancellation_policy',
          title: 'Cancellation Policy',
          content: tenant.cancellation_policy,
          relevance_score: score + getIntentBoost(detectedIntent, 'policy'),
        });
      }
      if (tenant.deposit_policy) {
        const score = calculateRelevance(queryText, `deposit payment policy ${tenant.deposit_policy}`);
        snippets.push({
          source_type: 'policy',
          id: 'deposit_policy',
          title: 'Deposit Policy',
          content: tenant.deposit_policy,
          relevance_score: score + getIntentBoost(detectedIntent, 'policy'),
        });
      }
      if (tenant.refund_policy) {
        const score = calculateRelevance(queryText, `refund money back policy ${tenant.refund_policy}`);
        snippets.push({
          source_type: 'policy',
          id: 'refund_policy',
          title: 'Refund Policy',
          content: tenant.refund_policy,
          relevance_score: score + getIntentBoost(detectedIntent, 'policy'),
        });
      }

      // Add intake fields
      const intakeFields = tenant.context_fields_json;
      if (Array.isArray(intakeFields) && intakeFields.length > 0) {
        const intakeContent = intakeFields.map((f: any) => 
          `${f.label}${f.required ? ' (required)' : ''}: ${f.type}${f.options ? ` - Options: ${f.options.join(', ')}` : ''}`
        ).join('\n');
        
        snippets.push({
          source_type: 'intake',
          id: 'intake_fields',
          title: 'Customer Intake Requirements',
          content: intakeContent,
          relevance_score: calculateRelevance(queryText, 'information needed details customer') + getIntentBoost(detectedIntent, 'intake'),
          metadata: { fields: intakeFields },
        });
      }
    }

    // Sort by relevance and take top K
    const rankedSnippets = snippets
      .filter(s => s.relevance_score > 0.1) // Filter low relevance
      .sort((a, b) => b.relevance_score - a.relevance_score)
      .slice(0, topK);

    // Determine confidence based on top result score
    const topScore = rankedSnippets[0]?.relevance_score || 0;
    const confidence = topScore > 0.6 ? 'high' : topScore > 0.3 ? 'medium' : 'low';

    return new Response(
      JSON.stringify({ 
        snippets: rankedSnippets,
        confidence,
        query: queryText,
        intent: detectedIntent,
        total_sources_searched: snippets.length,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("Error in retrieve-knowledge:", error);
    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Unknown error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { captureException, captureMessage } from "../_shared/sentry.ts";

/**
 * Retry Failed Deliveries
 *
 * This function should be called on a schedule (e.g., every 5 minutes) to retry
 * failed handoff deliveries with exponential backoff.
 *
 * Configuration:
 * - MAX_RETRIES: Maximum number of retry attempts (default: 3)
 * - BASE_DELAY_MINUTES: Initial delay before first retry (default: 5)
 * - BACKOFF_MULTIPLIER: How much to multiply delay for each retry (default: 2)
 *
 * Retry schedule with defaults:
 * - 1st retry: 5 minutes after failure
 * - 2nd retry: 10 minutes after 1st retry
 * - 3rd retry: 20 minutes after 2nd retry
 * - After 3rd failure: Marked as permanently failed, alert triggered
 */

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const MAX_RETRIES = 3;
const BASE_DELAY_MINUTES = 5;
const BACKOFF_MULTIPLIER = 2;

interface FailedDelivery {
  id: string;
  tenant_id: string;
  entity_type: string;
  entity_id: string;
  method: string;
  error_message: string | null;
  created_at: string;
  retry_count: number;
  last_retry_at: string | null;
  next_retry_at: string | null;
}

// Calculate next retry time based on retry count
function calculateNextRetryTime(retryCount: number): Date {
  const delayMinutes = BASE_DELAY_MINUTES * Math.pow(BACKOFF_MULTIPLIER, retryCount);
  const nextRetry = new Date();
  nextRetry.setMinutes(nextRetry.getMinutes() + delayMinutes);
  return nextRetry;
}

// Check if a delivery is ready for retry
function isReadyForRetry(delivery: FailedDelivery): boolean {
  if (delivery.retry_count >= MAX_RETRIES) {
    return false; // Already exhausted retries
  }

  if (!delivery.next_retry_at) {
    return true; // No next retry time set, ready for first retry
  }

  const nextRetryTime = new Date(delivery.next_retry_at);
  return new Date() >= nextRetryTime;
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  const SUPABASE_URL = Deno.env.get("SUPABASE_URL");
  const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

  if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    console.error("Missing Supabase configuration");
    return new Response(
      JSON.stringify({ error: "Server configuration error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }

  const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

  try {
    console.log("Starting failed delivery retry job...");

    // Fetch failed deliveries from BOTH tables that are ready for retry
    const nowIso = new Date().toISOString();
    const [deliveryResult, handoffResult] = await Promise.all([
      supabase
        .from("delivery_attempts")
        .select("*")
        .eq("status", "failed")
        .lt("retry_count", MAX_RETRIES)
        .or(`next_retry_at.is.null,next_retry_at.lte.${nowIso}`)
        .order("created_at", { ascending: true })
        .limit(50),
      supabase
        .from("handoff_attempts")
        .select("*")
        .eq("status", "failed")
        .lt("retry_count", MAX_RETRIES)
        .or(`next_retry_at.is.null,next_retry_at.lte.${nowIso}`)
        .order("created_at", { ascending: true })
        .limit(25),
    ]);

    if (deliveryResult.error) {
      console.error("Failed to fetch delivery_attempts:", deliveryResult.error);
    }
    if (handoffResult.error) {
      console.error("Failed to fetch handoff_attempts:", handoffResult.error);
    }

    // Tag each with source table for correct update path
    const deliveryItems = (deliveryResult.data || []).map((d: FailedDelivery) => ({ ...d, _table: "delivery_attempts" as const }));
    const handoffItems = (handoffResult.data || []).map((h: Record<string, unknown>) => ({
      id: h.id as string,
      tenant_id: h.tenant_id as string,
      entity_type: (h.entity_type as string) || "order",
      entity_id: (h.entity_id as string) || (h.order_id as string) || "",
      method: h.method as string,
      error_message: h.error_message as string | null,
      created_at: h.created_at as string,
      retry_count: (h.retry_count as number) || 0,
      last_retry_at: h.last_retry_at as string | null,
      next_retry_at: h.next_retry_at as string | null,
      _table: "handoff_attempts" as const,
    }));

    const failedDeliveries = [...deliveryItems, ...handoffItems];

    if (failedDeliveries.length === 0) {
      console.log("No failed deliveries ready for retry");
      return new Response(
        JSON.stringify({ status: "success", retried: 0, message: "No deliveries to retry" }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    console.log(`Found ${failedDeliveries.length} failed deliveries to retry (${deliveryItems.length} from delivery_attempts, ${handoffItems.length} from handoff_attempts)`);

    const results: { id: string; success: boolean; error?: string }[] = [];

    for (const delivery of failedDeliveries) {
      const { id, tenant_id, entity_type, entity_id, retry_count, _table } = delivery;
      console.log(`Retrying ${_table}/${id}: ${entity_type}/${entity_id} (attempt ${retry_count + 1})`);

      // Determine retry endpoint: handoff_attempts uses entity-specific functions,
      // delivery_attempts uses universal-delivery
      let retryEndpoint: string;
      let retryBody: Record<string, unknown>;

      if (_table === "handoff_attempts") {
        // Route to correct handoff function
        const handoffMap: Record<string, string> = {
          booking: "booking-handoff",
          dispatch: "dispatch-handoff",
          order: "order-handoff",
        };
        const handoffFn = handoffMap[entity_type] || "universal-delivery";
        retryEndpoint = `${SUPABASE_URL}/functions/v1/${handoffFn}`;

        if (entity_type === "booking") {
          retryBody = { booking_id: entity_id, tenant_id };
        } else if (entity_type === "dispatch") {
          retryBody = { dispatch_id: entity_id, tenant_id };
        } else if (entity_type === "order") {
          retryBody = { order_id: entity_id, tenant_id };
        } else {
          retryBody = { tenant_id, entity_type, entity_id, retry_attempt: retry_count + 1 };
        }
      } else {
        retryEndpoint = `${SUPABASE_URL}/functions/v1/universal-delivery`;
        retryBody = { tenant_id, entity_type, entity_id, retry_attempt: retry_count + 1 };
      }

      try {
        const response = await fetch(retryEndpoint, {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "Authorization": `Bearer ${SUPABASE_SERVICE_ROLE_KEY}`,
          },
          body: JSON.stringify(retryBody),
        });

        const result = await response.json();

        if (response.ok && result.success) {
          await supabase
            .from(_table)
            .update({
              status: "success",
              retry_count: retry_count + 1,
              last_retry_at: new Date().toISOString(),
              error_message: null,
            })
            .eq("id", id);

          results.push({ id, success: true });
          console.log(`Retry successful for ${_table}/${id}`);
        } else {
          const newRetryCount = retry_count + 1;
          const nextRetryAt = newRetryCount < MAX_RETRIES
            ? calculateNextRetryTime(newRetryCount)
            : null;

          await supabase
            .from(_table)
            .update({
              retry_count: newRetryCount,
              last_retry_at: new Date().toISOString(),
              next_retry_at: nextRetryAt?.toISOString() || null,
              error_message: result.error || "Retry failed",
            })
            .eq("id", id);

          results.push({ id, success: false, error: result.error });
          console.log(`Retry failed for ${_table}/${id}: ${result.error}`);

          if (newRetryCount >= MAX_RETRIES) {
            console.log(`Max retries exhausted for ${_table}/${id}, triggering alert`);
            await triggerDeliveryFailureAlert(supabase, SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, delivery);
          }
        }
      } catch (error) {
        console.error(`Error retrying ${_table}/${id}:`, error);

        const newRetryCount = retry_count + 1;
        const nextRetryAt = newRetryCount < MAX_RETRIES
          ? calculateNextRetryTime(newRetryCount)
          : null;

        await supabase
          .from(_table)
          .update({
            retry_count: newRetryCount,
            last_retry_at: new Date().toISOString(),
            next_retry_at: nextRetryAt?.toISOString() || null,
            error_message: error instanceof Error ? error.message : "Unknown error",
          })
          .eq("id", id);

        results.push({
          id,
          success: false,
          error: error instanceof Error ? error.message : "Unknown error",
        });

        await captureException(error, {
          tags: { function: "retry-failed-deliveries", delivery_id: id },
          extra: { entity_type, entity_id, tenant_id },
        });
      }
    }

    const successful = results.filter((r) => r.success).length;
    const failed = results.filter((r) => !r.success).length;

    console.log(`Retry job complete: ${successful} successful, ${failed} failed`);

    return new Response(
      JSON.stringify({
        status: "success",
        retried: failedDeliveries.length,
        successful,
        failed,
        results,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("Retry job error:", error);

    await captureException(error, {
      tags: { function: "retry-failed-deliveries" },
    });

    return new Response(
      JSON.stringify({ error: error instanceof Error ? error.message : "Unknown error" }),
      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  }
});

// Trigger an alert when max retries are exhausted
 async function triggerDeliveryFailureAlert(
   supabase: any,
  supabaseUrl: string,
  supabaseKey: string,
  delivery: FailedDelivery
): Promise<void> {
  const { tenant_id, entity_type, entity_id, error_message } = delivery;

   // Log to audit_events
   try {
     await supabase.from("audit_events").insert({
       tenant_id,
       event_type: "handoff.failed",
       entity_type,
       entity_id,
       actor_type: "system",
       payload: {
         error: error_message,
         retry_count: MAX_RETRIES,
         permanently_failed: true,
       },
     });
   } catch (e) {
     console.error("Failed to log audit event:", e);
   }

  // Send to Sentry for monitoring
  await captureMessage(
    `Handoff permanently failed: ${entity_type}/${entity_id}`,
    "error",
    {
      tags: {
        function: "retry-failed-deliveries",
        tenant_id,
        entity_type,
      },
      extra: { delivery },
    }
  );

  // Get tenant details for notification
  const { data: tenant } = await supabase
    .from("tenants")
    .select("business_name, owner_email")
    .eq("id", tenant_id)
    .single();
   
   const tenantData = tenant as { business_name: string; owner_email: string | null } | null;

  // Trigger notification workflow
  try {
    await fetch(`${supabaseUrl}/functions/v1/trigger-workflow`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Authorization": `Bearer ${supabaseKey}`,
      },
      body: JSON.stringify({
        tenant_id,
        trigger: "handoff.permanently_failed",
        entity_type,
        entity_id,
        is_critical: true,
        details: {
          error: error_message,
          retry_count: MAX_RETRIES,
           business_name: tenantData?.business_name,
           owner_email: tenantData?.owner_email,
        },
      }),
    });
  } catch (e) {
    console.error("Failed to trigger failure notification workflow:", e);
  }
}

