Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeadersWithAdmin });
  }

  try {
    // Auth: accept either x-admin-secret header OR JWT from a super_admin user
    const adminSecret = req.headers.get("x-admin-secret");
    if (adminSecret) {
      requireAdminSecret(req);
    } else {
      // JWT auth — verify user is super_admin
      const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
      const ANON_KEY = Deno.env.get("SUPABASE_ANON_KEY")!;
      const auth = req.headers.get("authorization") || "";
      const token = auth.replace(/^Bearer\s+/i, "");
      if (!token) throw new Error("Forbidden: no credentials provided");

      const anon = createClient(SUPABASE_URL, ANON_KEY, {
        global: { headers: { Authorization: `Bearer ${token}` } },
        auth: { persistSession: false },
      });
      const { data: userData, error: userErr } = await anon.auth.getUser();
      if (userErr || !userData?.user?.id) throw new Error("Forbidden: invalid token");

      const svc = serviceClient();
      const { data: roleData } = await svc
        .from("user_roles")
        .select("role")
        .eq("user_id", userData.user.id)
        .eq("role", "super_admin")
        .maybeSingle();

      if (!roleData) throw new Error("Forbidden: super_admin role required");
    }

    const STRIPE_SECRET_KEY = Deno.env.get("STRIPE_SECRET_KEY");
    if (!STRIPE_SECRET_KEY) {
      return errorResponse("STRIPE_SECRET_KEY not configured", 500);
    }

    // Step 1: Find or create product
    const productSearchRes = await stripeGet(
      `/products/search?query=metadata['product_key']:'${PRODUCT_KEY}'`,
      STRIPE_SECRET_KEY,
    );

    let productId: string;

    if (productSearchRes.ok) {
      const productData = await productSearchRes.json();
      if (productData.data?.length > 0) {
        productId = productData.data[0].id;
        console.log(`Product already exists: ${productId}`);
      } else {
        // Create product
        const createRes = await stripePost(
          "/products",
          STRIPE_SECRET_KEY,
          new URLSearchParams({
            name: PRODUCT_NAME,
            "metadata[product_key]": PRODUCT_KEY,
          }),
        );
        if (!createRes.ok) {
          const err = await createRes.text();
          console.error("Product creation failed:", err);
          return errorResponse(`Failed to create Stripe product: ${err}`, 500);
        }
        const product = await createRes.json();
        productId = product.id;
        console.log(`Product created: ${productId}`);
      }
    } else {
      const err = await productSearchRes.text();
      console.error("Product search failed:", err);
      return errorResponse(`Stripe product search failed: ${err}`, 500);
    }

    // Step 2: For each SKU, find or create price
    const results: { sku: string; status: string; price_id: string }[] = [];

    for (const priceDef of PRICES) {
      // Search for existing price with this plan_code
      const searchRes = await stripeGet(
        `/prices/search?query=metadata['plan_code']:'${priceDef.sku}' AND active:'true'`,
        STRIPE_SECRET_KEY,
      );

      if (searchRes.ok) {
        const searchData = await searchRes.json();
        if (searchData.data?.length > 0) {
          results.push({
            sku: priceDef.sku,
            status: "exists",
            price_id: searchData.data[0].id,
          });
          console.log(`Price already exists for ${priceDef.sku}: ${searchData.data[0].id}`);
          continue;
        }
      }

      // Create price
      const createRes = await stripePost(
        "/prices",
        STRIPE_SECRET_KEY,
        new URLSearchParams({
          product: productId,
          unit_amount: String(priceDef.unit_amount),
          currency: "usd",
          "recurring[interval]": "month",
          nickname: priceDef.nickname,
          "metadata[plan_code]": priceDef.sku,
          "metadata[included_minutes]": priceDef.included_minutes,
          "metadata[overage_rate_cents]": priceDef.overage_rate_cents,
          "metadata[product_key]": PRODUCT_KEY,
        }),
      );

      if (!createRes.ok) {
        const err = await createRes.text();
        console.error(`Price creation failed for ${priceDef.sku}:`, err);
        results.push({
          sku: priceDef.sku,
          status: `error: ${err}`,
          price_id: "",
        });
        continue;
      }

      const price = await createRes.json();
      results.push({
        sku: priceDef.sku,
        status: "created",
        price_id: price.id,
      });
      console.log(`Price created for ${priceDef.sku}: ${price.id}`);
    }

    return jsonResponse({
      product_id: productId,
      results,
    });
  } catch (err) {
    console.error("seed-stripe-prices error:", err);
    if (err instanceof Error && err.message.includes("Forbidden")) {
      return errorResponse(err.message, 403);
    }
    return errorResponse("Internal error", 500);
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

interface SeedRequest {
  action: "create_and_seed" | "reseed" | "delete";
  config: {
    slug: string;
    name: string;
    address: string;
    timezone: string;
    business_mode: string;
    industry: string;
    enabled_modules: string[];
    capabilities_json: Record<string, boolean>;
    hipaa_mode: boolean;
    // Optional business details
    hours_json?: Record<string, unknown>;
    phone_public?: string;
    website_url?: string;
    tagline?: string;
    cancellation_policy?: string;
    service_area_json?: Record<string, unknown>;
    // Optional standalone login credentials
    owner_email?: string;
    owner_password?: string;
    communicationPrefs: {
      aiBookingMode: string;
      missedCallBehavior: string;
      unknownQuestionBehavior: string;
    };
    seedData: {
      callCount: number;
      faqCount: number;
      serviceCount: number;
      bookingCount?: number;
      orderCount?: number;
      dispatchJobCount?: number;
      intakeCount?: number;
      customServices?: {
        name: string;
        description?: string;
        duration_minutes: number;
        price_amount: number;
        price_type?: string;
        service_category?: string;
        display_order?: number;
      }[];
      customFaqs?: {
        question: string;
        answer: string;
        priority_weight?: number;
      }[];
      customObjections?: {
        objection: string;
        response: string;
        priority_weight?: number;
      }[];
    };
  };
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    // Verify auth
    const authHeader = req.headers.get("Authorization");
    if (!authHeader) {
      return new Response(JSON.stringify({ error: "Missing authorization" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabaseAnonKey = Deno.env.get("SUPABASE_ANON_KEY")!;

    // Verify the user is a super_admin
    const userClient = createClient(supabaseUrl, supabaseAnonKey, {
      global: { headers: { Authorization: authHeader } },
    });

    const { data: { user }, error: authError } = await userClient.auth.getUser();
    if (authError || !user) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Check super_admin role
    const serviceClient = createClient(supabaseUrl, supabaseServiceKey);

    const { data: roleRow } = await serviceClient
      .from("user_roles")
      .select("role")
      .eq("user_id", user.id)
      .eq("role", "super_admin")
      .maybeSingle();

    if (!roleRow) {
      return new Response(JSON.stringify({ error: "Forbidden: super_admin required" }), {
        status: 403,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const body: SeedRequest = await req.json();
    const { action, config } = body;

    if (!action || !config) {
      return new Response(JSON.stringify({ error: "Missing action or config" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Check if tenant already exists
    const { data: existingTenant } = await serviceClient
      .from("tenants")
      .select("id")
      .eq("name", config.name)
      .maybeSingle();

    // Handle DELETE action
    if (action === "delete") {
      if (!existingTenant) {
        return new Response(JSON.stringify({ status: "skipped", message: "Tenant not found" }), {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }

      const tenantId = existingTenant.id;

      // Delete in order (respecting FK constraints)
      await serviceClient.from("ai_call_sessions").delete().eq("tenant_id", tenantId);
      await serviceClient.from("bookings").delete().eq("tenant_id", tenantId);
      await serviceClient.from("dispatch_jobs").delete().eq("tenant_id", tenantId);
      await serviceClient.from("food_orders").delete().eq("tenant_id", tenantId);
      await serviceClient.from("medical_intakes").delete().eq("tenant_id", tenantId);
      await serviceClient.from("services").delete().eq("tenant_id", tenantId);
      await serviceClient.from("business_faqs").delete().eq("tenant_id", tenantId);
      await serviceClient.from("objection_responses").delete().eq("tenant_id", tenantId);
      await serviceClient.from("automations").delete().eq("tenant_id", tenantId);
      await serviceClient.from("assistant_settings").delete().eq("tenant_id", tenantId);
      await serviceClient.from("subscriptions").delete().eq("tenant_id", tenantId);
      await serviceClient.from("food_order_settings").delete().eq("tenant_id", tenantId);
      await serviceClient.from("customers").delete().eq("tenant_id", tenantId);
      await serviceClient.from("tenant_users").delete().eq("tenant_id", tenantId);
      await serviceClient.from("tenants").delete().eq("id", tenantId);

      return new Response(JSON.stringify({ tenant_id: tenantId, status: "deleted" }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Handle RESEED action
    if (action === "reseed" && existingTenant) {
      const tenantId = existingTenant.id;

      // Clear seed-able data
      await serviceClient.from("ai_call_sessions").delete().eq("tenant_id", tenantId);
      await serviceClient.from("bookings").delete().eq("tenant_id", tenantId);
      await serviceClient.from("dispatch_jobs").delete().eq("tenant_id", tenantId);
      await serviceClient.from("food_orders").delete().eq("tenant_id", tenantId);
      await serviceClient.from("medical_intakes").delete().eq("tenant_id", tenantId);
      await serviceClient.from("services").delete().eq("tenant_id", tenantId);
      await serviceClient.from("business_faqs").delete().eq("tenant_id", tenantId);
      await serviceClient.from("objection_responses").delete().eq("tenant_id", tenantId);

      // Ensure standalone owner login exists if credentials provided
      if (config.owner_email && config.owner_password) {
        let ownerId: string | null = null;

        const { data: newUser, error: createErr } =
          await serviceClient.auth.admin.createUser({
            email: config.owner_email,
            password: config.owner_password,
            email_confirm: true,
          });

        if (newUser?.user) {
          ownerId = newUser.user.id;
        } else if (
          createErr &&
          (createErr.message?.includes("already been registered") ||
            createErr.message?.includes("already exists"))
        ) {
          const { data: listData } =
            await serviceClient.auth.admin.listUsers();
          const existing = listData?.users?.find(
            (u: { email?: string }) => u.email === config.owner_email
          );
          if (existing) ownerId = existing.id;
        } else if (createErr) {
          console.error("Failed to create owner auth user:", createErr.message);
        }

        if (ownerId) {
          await serviceClient
            .from("profiles")
            .upsert({ id: ownerId, role: "user" }, { onConflict: "id" });

          await serviceClient.from("tenant_users").upsert(
            { tenant_id: tenantId, user_id: ownerId, role: "owner" },
            { onConflict: "tenant_id,user_id" }
          );
        }
      }

      // Re-seed
      await seedTenantData(serviceClient, tenantId, config);

      return new Response(JSON.stringify({ tenant_id: tenantId, status: "reseeded" }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Handle CREATE_AND_SEED action
    if (action === "create_and_seed") {
      if (existingTenant) {
        return new Response(
          JSON.stringify({ tenant_id: existingTenant.id, status: "skipped", message: "Already exists" }),
          { headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }

      // Create tenant
      const defaultHours = {
        monday: { closed: false, windows: [{ open: "09:00", close: "17:00" }] },
        tuesday: { closed: false, windows: [{ open: "09:00", close: "17:00" }] },
        wednesday: { closed: false, windows: [{ open: "09:00", close: "17:00" }] },
        thursday: { closed: false, windows: [{ open: "09:00", close: "17:00" }] },
        friday: { closed: false, windows: [{ open: "09:00", close: "17:00" }] },
        saturday: { closed: false, windows: [{ open: "10:00", close: "15:00" }] },
        sunday: { closed: true, windows: [] },
      };

      const tenantInsert: Record<string, unknown> = {
        name: config.name,
        address: config.address,
        timezone: config.timezone,
        business_mode: config.business_mode,
        industry: config.industry,
        enabled_modules: config.enabled_modules,
        capabilities_json: config.capabilities_json,
        hipaa_mode: config.hipaa_mode,
        hours_json: config.hours_json ?? defaultHours,
        onboarding_completed_at: new Date().toISOString(),
      };

      if (config.phone_public) tenantInsert.phone_public = config.phone_public;
      if (config.website_url) tenantInsert.website_url = config.website_url;
      if (config.tagline) tenantInsert.tagline = config.tagline;
      if (config.cancellation_policy) tenantInsert.cancellation_policy = config.cancellation_policy;
      if (config.service_area_json) tenantInsert.service_area_json = config.service_area_json;

      const { data: newTenant, error: tenantError } = await serviceClient
        .from("tenants")
        .insert(tenantInsert)
        .select("id")
        .single();

      if (tenantError || !newTenant) {
        throw new Error(`Tenant creation failed: ${tenantError?.message}`);
      }

      const tenantId = newTenant.id;

      // Create membership for the admin user (so they can Switch to this tenant)
      await serviceClient.from("tenant_users").insert({
        tenant_id: tenantId,
        user_id: user.id,
        role: "owner",
      });

      // Create standalone owner login if credentials provided
      if (config.owner_email && config.owner_password) {
        let ownerId: string | null = null;

        // Try to create the auth user
        const { data: newUser, error: createErr } =
          await serviceClient.auth.admin.createUser({
            email: config.owner_email,
            password: config.owner_password,
            email_confirm: true,
          });

        if (newUser?.user) {
          ownerId = newUser.user.id;
        } else if (
          createErr &&
          (createErr.message?.includes("already been registered") ||
            createErr.message?.includes("already exists"))
        ) {
          // User already exists (re-seed scenario) — look them up
          const { data: listData } =
            await serviceClient.auth.admin.listUsers();
          const existing = listData?.users?.find(
            (u: { email?: string }) => u.email === config.owner_email
          );
          if (existing) ownerId = existing.id;
        } else if (createErr) {
          console.error("Failed to create owner auth user:", createErr.message);
        }

        if (ownerId) {
          // Ensure a profile row exists so role checks work
          await serviceClient
            .from("profiles")
            .upsert({ id: ownerId, role: "user" }, { onConflict: "id" });

          // Add owner membership (ignore conflict if already exists)
          await serviceClient.from("tenant_users").upsert(
            { tenant_id: tenantId, user_id: ownerId, role: "owner" },
            { onConflict: "tenant_id,user_id" }
          );
        }
      }

      // Create subscription
      await serviceClient.from("subscriptions").insert({
        tenant_id: tenantId,
        plan_code: "voice",
        status: "trialing",
        current_period_end: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
      });

      // Create assistant settings
      await serviceClient.from("assistant_settings").insert({
        tenant_id: tenantId,
        voice_ai_enabled: true,
        instant_text_enabled: true,
        ai_booking_mode: config.communicationPrefs.aiBookingMode,
        missed_call_behavior: config.communicationPrefs.missedCallBehavior,
        unknown_question_behavior: config.communicationPrefs.unknownQuestionBehavior,
      });

      // Create food order settings for food mode
      if (config.business_mode === "food") {
        await serviceClient.from("food_order_settings").insert({
          tenant_id: tenantId,
          accepts_pickup: true,
          accepts_delivery: config.capabilities_json.offersDelivery ?? false,
          accepts_dine_in: true,
          accepts_catering: config.capabilities_json.offersCatering ?? false,
          order_confirmation_mode: "auto_confirm",
        });
      }

      // Seed data
      await seedTenantData(serviceClient, tenantId, config);

      // Save scenario flags
      await serviceClient
        .from("tenants")
        .update({
          context_fields_json: { capabilities: config.capabilities_json },
        })
        .eq("id", tenantId);

      return new Response(JSON.stringify({ tenant_id: tenantId, status: "created" }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    return new Response(JSON.stringify({ error: "Invalid action" }), {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (error) {
    console.error("seed-test-tenants error:", error);
    return new Response(JSON.stringify({ error: (error as Error).message }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

// Helper: seed services, FAQs, objections, and sample data
// deno-lint-ignore no-explicit-any
async function seedTenantData(
  client: any,
  tenantId: string,
  config: SeedRequest["config"]
) {
  const { seedData } = config;

  // Seed services — use custom if provided, otherwise generate generic
  if (seedData.customServices && seedData.customServices.length > 0) {
    const services = seedData.customServices.map((s) => ({
      tenant_id: tenantId,
      name: s.name,
      description: s.description ?? "",
      duration_minutes: s.duration_minutes,
      price_amount: s.price_amount,
      price_type: s.price_type ?? "fixed",
      service_category: s.service_category ?? null,
      display_order: s.display_order ?? 0,
      is_active: true,
    }));
    await client.from("services").insert(services);
  } else {
    const services = Array.from({ length: seedData.serviceCount }, (_, i) => ({
      tenant_id: tenantId,
      name: `${config.name} Service ${i + 1}`,
      description: `Sample service #${i + 1}`,
      duration_minutes: [30, 45, 60, 90][i % 4],
      price_amount: [50, 75, 100, 150, 200][i % 5],
      price_type: "fixed" as const,
      is_active: true,
    }));
    if (services.length > 0) {
      await client.from("services").insert(services);
    }
  }

  // Seed FAQs — use custom if provided, otherwise generate generic
  if (seedData.customFaqs && seedData.customFaqs.length > 0) {
    const faqs = seedData.customFaqs.map((f, i) => ({
      tenant_id: tenantId,
      question: f.question,
      answer: f.answer,
      priority_weight: f.priority_weight ?? i,
    }));
    await client.from("business_faqs").insert(faqs);
  } else {
    const faqs = Array.from({ length: seedData.faqCount }, (_, i) => ({
      tenant_id: tenantId,
      question: `Sample question ${i + 1} for ${config.name}?`,
      answer: `This is the answer to sample question ${i + 1}.`,
      priority_weight: i,
    }));
    if (faqs.length > 0) {
      await client.from("business_faqs").insert(faqs);
    }
  }

  // Seed objection responses — only if custom data provided
  if (seedData.customObjections && seedData.customObjections.length > 0) {
    const objections = seedData.customObjections.map((o, i) => ({
      tenant_id: tenantId,
      objection: o.objection,
      response: o.response,
      priority_weight: o.priority_weight ?? i,
    }));
    await client.from("objection_responses").insert(objections);
  }

  // Seed sample call sessions
  const calls = Array.from({ length: seedData.callCount }, (_, i) => {
    const hoursAgo = i * 2 + 1;
    const startedAt = new Date(Date.now() - hoursAgo * 60 * 60 * 1000);
    return {
      tenant_id: tenantId,
      started_at: startedAt.toISOString(),
      ended_at: new Date(startedAt.getTime() + (60 + i * 30) * 1000).toISOString(),
      status: ["completed", "completed", "missed", "completed", "voicemail"][i % 5],
      caller_phone: `+1555000${String(i).padStart(4, "0")}`,
      duration_seconds: 60 + i * 30,
    };
  });

  if (calls.length > 0) {
    await client.from("ai_call_sessions").insert(calls);
  }
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { requireAuthedTenant, serviceClient } from "../_shared/tenant.ts";
import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { captureException } from "../_shared/sentry.ts";
import { sendTenantSms } from "../_shared/sms-sender.ts";

serve(async (req: Request) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    const { to, body, tenant_id, conversation_id, customer_id } = await req.json();

    if (!to || !body) {
      return errorResponse("Missing required fields: to, body");
    }

    // Auth: require JWT + tenant membership
    const { tenantId } = await requireAuthedTenant(req, tenant_id);

    // Send via shared helper (auto-routes 10DLC → toll-free → skip)
    const result = await sendTenantSms({ tenantId, to, body });

    if (result.skipped) {
      return errorResponse("SMS not available: registration pending. Messages will be sent once your number is verified.", 422);
    }

    if (!result.success) {
      return errorResponse(`SMS delivery failed: ${result.error}`, 502);
    }

    // Log to messages table if we have a conversation_id
    const supabase = serviceClient();

    if (conversation_id) {
      await supabase.from("messages").insert({
        tenant_id: tenantId,
        conversation_id,
        direction: "outbound",
        body,
        status: "sent",
        meta_json: { twilio_sid: result.twilioSid, channel: result.channel },
      });
    } else if (customer_id) {
      const { data: existingConvo } = await supabase
        .from("conversations")
        .select("id")
        .eq("tenant_id", tenantId)
        .eq("customer_id", customer_id)
        .eq("channel", "sms")
        .order("created_at", { ascending: false })
        .limit(1)
        .single();

      if (existingConvo?.id) {
        await supabase.from("messages").insert({
          tenant_id: tenantId,
          conversation_id: existingConvo.id,
          direction: "outbound",
          body,
          status: "sent",
          meta_json: { twilio_sid: result.twilioSid, channel: result.channel },
        });
      }
    }

    return jsonResponse({
      success: true,
      twilio_sid: result.twilioSid,
      channel: result.channel,
    });
  } catch (error) {
    console.error("send-sms error:", error);
    await captureException(error, { tags: { function: "send-sms" } });
    return errorResponse(
      error instanceof Error ? error.message : "Unknown error",
      500,
    );
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";

interface StartRecoveryRequest {
  tenant_id: string;
  customer_id: string;
  lead_id?: string;
  call_session_id?: string;
  original_intent?: string;
  original_service_interest?: string;
  original_objection?: string;
  original_call_outcome?: string;
  force_start?: boolean;
}

interface RecoveryResult {
  success: boolean;
  reason?: string;
  campaign_id?: string;
  next_action_at?: string;
  sequence_name?: string;
  total_steps?: number;
}

Deno.serve(async (req) => {
  // Handle CORS preflight
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const body: StartRecoveryRequest = await req.json();
    const {
      tenant_id,
      customer_id,
      lead_id,
      call_session_id,
      original_intent,
      original_service_interest,
      original_objection,
      original_call_outcome = "followup",
      force_start = false,
    } = body;

    // Validate required fields
    if (!tenant_id || !customer_id) {
      return jsonResponse({ success: false, reason: "missing_required_fields" }, 400);
    }

    // Step 1: Check if recovery is enabled for tenant
    const { data: settings, error: settingsError } = await supabase
      .from("lead_recovery_settings")
      .select("*")
      .eq("tenant_id", tenant_id)
      .maybeSingle();

    if (settingsError) {
      console.error("Error fetching settings:", settingsError);
      return jsonResponse({ success: false, reason: "settings_error" }, 500);
    }

    if (!settings || !settings.recovery_enabled) {
      return jsonResponse({ success: false, reason: "recovery_disabled" });
    }

    // Step 2: Get customer details and check preferences
    const { data: customer, error: customerError } = await supabase
      .from("customers")
      .select("*")
      .eq("id", customer_id)
      .eq("tenant_id", tenant_id)
      .maybeSingle();

    if (customerError || !customer) {
      console.error("Error fetching customer:", customerError);
      return jsonResponse({ success: false, reason: "customer_not_found" }, 404);
    }

    // Check do_not_contact
    if (customer.do_not_contact) {
      return jsonResponse({ success: false, reason: "do_not_contact" });
    }

    // Check contact method availability
    const hasPhone = !!customer.phone_e164;
    const hasEmail = !!customer.email;
    if (!hasPhone && !hasEmail) {
      return jsonResponse({ success: false, reason: "no_contact_method" });
    }

    // Step 3: Check for existing active campaign
    if (!force_start) {
      const { data: existingCampaign } = await supabase
        .from("lead_recovery_campaigns")
        .select("id, status")
        .eq("customer_id", customer_id)
        .eq("tenant_id", tenant_id)
        .in("status", ["active", "paused"])
        .maybeSingle();

      if (existingCampaign) {
        return jsonResponse({
          success: false,
          reason: "campaign_exists",
          campaign_id: existingCampaign.id,
        });
      }

      // Step 4: Check cooldown period
      const cooldownDays = settings.cooldown_days || 30;
      const cooldownDate = new Date();
      cooldownDate.setDate(cooldownDate.getDate() - cooldownDays);

      const { data: recentCampaign } = await supabase
        .from("lead_recovery_campaigns")
        .select("id, stopped_at, updated_at")
        .eq("customer_id", customer_id)
        .eq("tenant_id", tenant_id)
        .in("status", ["completed", "stopped", "declined", "converted"])
        .order("updated_at", { ascending: false })
        .limit(1)
        .maybeSingle();

      if (recentCampaign) {
        const lastCampaignDate = new Date(recentCampaign.stopped_at || recentCampaign.updated_at);
        if (lastCampaignDate > cooldownDate) {
          return jsonResponse({ success: false, reason: "cooldown_active" });
        }
      }

      // Step 5: Check daily rate limit
      const todayStart = new Date();
      todayStart.setHours(0, 0, 0, 0);

      const { count: todayCampaigns } = await supabase
        .from("lead_recovery_campaigns")
        .select("*", { count: "exact", head: true })
        .eq("tenant_id", tenant_id)
        .gte("created_at", todayStart.toISOString());

      const maxPerDay = settings.max_campaigns_per_day || 50;
      if ((todayCampaigns || 0) >= maxPerDay) {
        return jsonResponse({ success: false, reason: "rate_limited" });
      }
    }

    // Step 6: Check if customer already has a scheduled booking
    const { data: existingBooking } = await supabase
      .from("bookings")
      .select("id")
      .eq("tenant_id", tenant_id)
      .eq("status", "scheduled")
      .gte("start_at", new Date().toISOString())
      .limit(1)
      .maybeSingle();

    // We need to check if the booking is linked to this customer via lead
    // For now, skip this check if no lead_id provided
    if (existingBooking && lead_id) {
      const { data: linkedBooking } = await supabase
        .from("bookings")
        .select("id")
        .eq("tenant_id", tenant_id)
        .eq("lead_id", lead_id)
        .eq("status", "scheduled")
        .gte("start_at", new Date().toISOString())
        .maybeSingle();

      if (linkedBooking) {
        return jsonResponse({ success: false, reason: "already_booked" });
      }
    }

    // Step 7: Get or create lead record
    let finalLeadId = lead_id;
    if (!finalLeadId) {
      // Create a new lead from customer info
      const { data: newLead, error: leadError } = await supabase
        .from("leads")
        .insert({
          tenant_id,
          full_name: customer.full_name,
          phone: customer.phone_e164,
          email: customer.email,
          source: "missed_call", // Valid enum value
          status: "new",
          vehicle_or_context: original_intent ? `Original inquiry: ${original_intent}` : null,
        })
        .select("id")
        .single();

      if (leadError) {
        console.error("Error creating lead:", leadError);
        return jsonResponse({ success: false, reason: "lead_creation_failed" }, 500);
      }

      finalLeadId = newLead.id;
    }

    // Step 8: Get the appropriate sequence
    let { data: sequence } = await supabase
      .from("lead_recovery_sequences")
      .select("id, name, trigger_on_outcomes")
      .eq("tenant_id", tenant_id)
      .eq("is_default", true)
      .eq("is_active", true)
      .maybeSingle();

    // If no default sequence, create one
    if (!sequence) {
      const { data: ensureResult, error: ensureError } = await supabase
        .rpc("ensure_tenant_has_default_sequence", { p_tenant_id: tenant_id });

      if (ensureError) {
        console.error("Error ensuring default sequence:", ensureError);
        return jsonResponse({ success: false, reason: "sequence_creation_failed" }, 500);
      }

      // Fetch the newly created sequence
      const { data: newSequence } = await supabase
        .from("lead_recovery_sequences")
        .select("id, name, trigger_on_outcomes")
        .eq("id", ensureResult)
        .single();

      sequence = newSequence;
    }

    if (!sequence) {
      return jsonResponse({ success: false, reason: "no_sequence_available" }, 500);
    }

    // Step 9: Check trigger conditions
    const triggerOutcomes = sequence.trigger_on_outcomes || [];
    if (!triggerOutcomes.includes(original_call_outcome)) {
      return jsonResponse({ success: false, reason: "outcome_not_triggered" });
    }

    // Step 10: Get sequence steps
    const { data: steps, error: stepsError } = await supabase
      .from("lead_recovery_sequence_steps")
      .select("*")
      .eq("sequence_id", sequence.id)
      .order("step_order", { ascending: true });

    if (stepsError || !steps || steps.length === 0) {
      return jsonResponse({ success: false, reason: "empty_sequence" });
    }

    // Step 11: Calculate next_action_at
    const firstStep = steps[0];
    let nextActionAt = new Date();
    nextActionAt.setMinutes(nextActionAt.getMinutes() + (firstStep.delay_minutes || 60));

    // Consider business hours if needed
    if (firstStep.respect_business_hours && settings.respect_business_hours) {
      nextActionAt = adjustForBusinessHours(
        nextActionAt,
        settings.quiet_hours_start,
        settings.quiet_hours_end,
        settings.quiet_days || []
      );
    }

    // Step 12: Create the campaign
    const { data: campaign, error: campaignError } = await supabase
      .from("lead_recovery_campaigns")
      .insert({
        tenant_id,
        customer_id,
        lead_id: finalLeadId,
        original_call_id: call_session_id || null,
        sequence_id: sequence.id,
        status: "active",
        current_step: 0,
        next_action_at: nextActionAt.toISOString(),
        original_intent: original_intent || null,
        original_service_interest: original_service_interest || null,
        original_objection: original_objection || null,
        original_call_outcome: original_call_outcome,
      })
      .select("id")
      .single();

    if (campaignError) {
      console.error("Error creating campaign:", campaignError);
      return jsonResponse({ success: false, reason: "campaign_creation_failed" }, 500);
    }

    // Step 13: Update related records
    // Update lead
    await supabase
      .from("leads")
      .update({
        recovery_status: "in_recovery",
        recovery_campaign_id: campaign.id,
        last_recovery_at: new Date().toISOString(),
      })
      .eq("id", finalLeadId);

    // Update call session if provided
    if (call_session_id) {
      await supabase
        .from("ai_call_sessions")
        .update({
          triggered_recovery: true,
          recovery_campaign_id: campaign.id,
        })
        .eq("id", call_session_id);
    }

    // Return success
    const result: RecoveryResult = {
      success: true,
      campaign_id: campaign.id,
      next_action_at: nextActionAt.toISOString(),
      sequence_name: sequence.name,
      total_steps: steps.length,
    };

    console.log(`Started recovery campaign ${campaign.id} for customer ${customer_id}`);

    return jsonResponse(result);

  } catch (error) {
    console.error("Error in start-lead-recovery:", error);
    return jsonResponse(
      { success: false, reason: "internal_error", message: String(error) },
      500
    );
  }
});

/**
 * Adjust a date to fall within business hours
 */
function adjustForBusinessHours(
  date: Date,
  quietStart: string | null,
  quietEnd: string | null,
  quietDays: string[]
): Date {
  const result = new Date(date);
  
  // Default quiet hours: 9 PM to 8 AM
  const quietStartTime = quietStart || "21:00";
  const quietEndTime = quietEnd || "08:00";
  
  const [quietStartHour, quietStartMin] = quietStartTime.split(":").map(Number);
  const [quietEndHour, quietEndMin] = quietEndTime.split(":").map(Number);
  
  // Get day name (lowercase)
  const dayNames = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"];
  
  // Keep adjusting until we find a valid time
  let iterations = 0;
  const maxIterations = 14; // Max 2 weeks of adjustment
  
  while (iterations < maxIterations) {
    const dayName = dayNames[result.getDay()];
    const hour = result.getHours();
    const minute = result.getMinutes();
    const currentMinutes = hour * 60 + minute;
    
    const quietStartMinutes = quietStartHour * 60 + quietStartMin;
    const quietEndMinutes = quietEndHour * 60 + quietEndMin;
    
    // Check if it's a quiet day
    if (quietDays.includes(dayName)) {
      // Move to next day at quiet end time
      result.setDate(result.getDate() + 1);
      result.setHours(quietEndHour, quietEndMin, 0, 0);
      iterations++;
      continue;
    }
    
    // Check if we're in quiet hours (handle overnight quiet period)
    let inQuietHours = false;
    
    if (quietStartMinutes > quietEndMinutes) {
      // Overnight quiet period (e.g., 21:00 - 08:00)
      inQuietHours = currentMinutes >= quietStartMinutes || currentMinutes < quietEndMinutes;
    } else {
      // Same-day quiet period
      inQuietHours = currentMinutes >= quietStartMinutes && currentMinutes < quietEndMinutes;
    }
    
    if (inQuietHours) {
      if (currentMinutes >= quietStartMinutes) {
        // Move to next day at quiet end time
        result.setDate(result.getDate() + 1);
        result.setHours(quietEndHour, quietEndMin, 0, 0);
      } else {
        // Move to quiet end time today
        result.setHours(quietEndHour, quietEndMin, 0, 0);
      }
      iterations++;
      continue;
    }
    
    // We're in valid business hours
    break;
  }
  
  return result;
}

import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { serviceClient } from "../_shared/tenant.ts";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();

  if (req.method !== "POST") {
    return errorResponse("Method not allowed", 405);
  }

  try {
    const body = await req.json();
    const { full_name, email, company_name, expected_clients, phone, company_website, current_client_count, services_offered, referral_source, message, user_id } = body;

    // Validate required fields
    if (!full_name?.trim()) return errorResponse("Full name is required");
    if (!email?.trim()) return errorResponse("Email is required");
    if (!company_name?.trim()) return errorResponse("Company name is required");
    if (!expected_clients) return errorResponse("Expected clients is required");

    // Validate email format
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email.trim())) return errorResponse("Invalid email format");

    const db = serviceClient();

    // Check for duplicate pending application
    const { data: existing } = await db
      .from("agency_applications")
      .select("id")
      .eq("email", email.trim().toLowerCase())
      .in("status", ["new", "reviewing"])
      .limit(1);

    if (existing && existing.length > 0) {
      return errorResponse("An application with this email is already under review", 409);
    }

    // Insert application
    const { error: insertErr } = await db
      .from("agency_applications")
      .insert({
        full_name: full_name.trim(),
        email: email.trim().toLowerCase(),
        phone: phone?.trim() || null,
