      });

    if (insertErr) {
      console.error("Insert error:", insertErr);
      return errorResponse("Failed to submit application", 500);
    }

    return jsonResponse({ success: true });
  } catch (err) {
    console.error("submit-agency-application error:", err);
    return errorResponse("Internal server error", 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";
import { requireAuthedTenant, serviceClient } from "../_shared/tenant.ts";

// OAuth credentials for token refresh
const GOOGLE_CLIENT_ID = Deno.env.get("GOOGLE_CALENDAR_CLIENT_ID");
const GOOGLE_CLIENT_SECRET = Deno.env.get("GOOGLE_CALENDAR_CLIENT_SECRET");
const MS_CLIENT_ID = Deno.env.get("MS_CALENDAR_CLIENT_ID");
const MS_CLIENT_SECRET = Deno.env.get("MS_CALENDAR_CLIENT_SECRET");

serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return corsResponse();
  }

  try {
    // Parse body first to check for cron mode
    const body = await req.json();
    const { connection_id, days = 30, _cron_tenant_id } = body;

    let tenantId: string;

    // Check if this is a cron call (service role with explicit tenant_id)
    const authHeader = req.headers.get("Authorization") || "";
    const token = authHeader.replace("Bearer ", "");
    const isServiceRole = token === Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

    if (isServiceRole && _cron_tenant_id) {
      // Cron mode: trust the tenant_id from the cron job
      tenantId = _cron_tenant_id;
      console.log("[sync-availability] Cron mode for tenant:", tenantId);
    } else {
      // User mode: verify user and get tenant
      const result = await requireAuthedTenant(req, body.tenant_id);
      tenantId = result.tenantId;
    }

    // Use service role for token access
    const supabase = serviceClient();

    // Get connection
    const { data: connection, error: connError } = await supabase
      .from("calendar_connections")
      .select("*")
      .eq("id", connection_id)
      .eq("tenant_id", tenantId)
      .single();

    if (connError || !connection) {
      return errorResponse("Connection not found", 404);
    }

    // Get tokens
    const { data: tokens, error: tokenError } = await supabase
      .from("calendar_tokens")
      .select("*")
      .eq("tenant_id", tenantId)
      .eq("provider", connection.provider)
      .single();

    if (tokenError || !tokens) {
      // Mark connection as error
      await supabase
        .from("calendar_connections")
        .update({ status: "error", sync_error: "No tokens found" })
        .eq("id", connection_id);

      return errorResponse("No tokens found", 400);
    }

    let accessToken = tokens.access_token;

    // Check if token is expired and refresh if needed
    if (tokens.expires_at && new Date(tokens.expires_at) < new Date()) {
      accessToken = await refreshToken(supabase, tokens);
      if (!accessToken) {
        await supabase
          .from("calendar_connections")
          .update({ status: "error", sync_error: "Token refresh failed" })
          .eq("id", connection_id);

        return errorResponse("Token refresh failed", 401);
      }
    }

    // Calculate date range
    const startDate = new Date();
    const endDate = new Date();
    endDate.setDate(endDate.getDate() + days);

    // Fetch busy times based on provider
    let events: { start_at: string; end_at: string; external_event_id: string; summary?: string }[] = [];
    const configJson = connection.config_json as { selected_calendar_ids?: string[] } | null;
    const selectedCalendarIds = configJson?.selected_calendar_ids || [];

    console.log("=== SYNC-AVAILABILITY DEBUG ===");
    console.log("Tenant ID:", tenantId);
    console.log("Connection ID:", connection_id);
    console.log("Provider:", connection.provider);
    console.log("Selected Calendar IDs:", JSON.stringify(selectedCalendarIds));
    console.log("Date Range:", startDate.toISOString(), "to", endDate.toISOString());

    if (connection.provider === "google") {
      events = await fetchGoogleBusyTimes(accessToken, selectedCalendarIds, startDate, endDate);
    } else if (connection.provider === "microsoft") {
      events = await fetchMicrosoftBusyTimes(accessToken, selectedCalendarIds, startDate, endDate);
    }

    console.log("=== EVENTS FETCHED FROM API ===");
    console.log("Total events found:", events.length);
    for (const evt of events) {
      console.log(`  Event: ${evt.start_at} -> ${evt.end_at} (ID: ${evt.external_event_id})`);
    }

    // Update last_sync_at on the connection
    await supabase
      .from("calendar_connections")
      .update({ 
        last_sync_at: new Date().toISOString(),
        sync_error: null,
        status: "connected"
      })
      .eq("id", connection_id);

    // Sync to busy_blocks
    const { data: syncResult, error: syncError } = await supabase.rpc("fn_sync_busy_blocks", {
      _tenant_id: tenantId,
      _connection_id: connection_id,
      _events: events,
    });

    if (syncError) {
      console.error("Sync error:", syncError);
      
      // Update connection with error
      await supabase
        .from("calendar_connections")
        .update({ sync_error: syncError.message })
        .eq("id", connection_id);
        
      return errorResponse(syncError.message, 500);
    }

    console.log("=== SYNC COMPLETE ===");
    console.log("Events synced to busy_blocks:", syncResult);

    return jsonResponse({
      success: true,
      synced_count: syncResult,
      events_found: events.length,
      date_range: {
        start: startDate.toISOString(),
        end: endDate.toISOString(),
      },
      calendar_ids: selectedCalendarIds,
    });
  } catch (error: unknown) {
    console.error("Error in sync-availability:", error);
    const message = error instanceof Error ? error.message : "Unknown error";
    return errorResponse(message, 500);
  }
});

function timeZoneOffsetForDate(timeZone: string, yyyyMmDd: string): string {
  // Use noon UTC to avoid DST edge cases that can occur around midnight.
  const [y, m, d] = yyyyMmDd.split("-").map((n) => Number(n));
  const probe = new Date(Date.UTC(y, (m || 1) - 1, d || 1, 12, 0, 0));

  try {
    const parts = new Intl.DateTimeFormat("en-US", {
      timeZone,
      timeZoneName: "shortOffset",
    }).formatToParts(probe);

    const tz = parts.find((p) => p.type === "timeZoneName")?.value || "GMT";
    // e.g. "GMT-5" or "GMT+5:30"
    const match = tz.match(/GMT([+-]\d{1,2})(?::(\d{2}))?/);
    if (!match) return "+00:00";

    const minutes = match[2] || "00";

    // match[1] already includes sign.
    const sign = match[1].startsWith("-") ? "-" : "+";
    const absHours = String(Math.abs(Number(match[1]))).padStart(2, "0");

    return `${sign}${absHours}:${minutes}`;
  } catch {
    return "+00:00";
  }
}

async function refreshToken(supabase: any, tokens: any): Promise<string | null> {
  if (!tokens.refresh_token) return null;

  try {
    let response;

    if (tokens.provider === "google") {
      if (!GOOGLE_CLIENT_ID || !GOOGLE_CLIENT_SECRET) return null;

      response = await fetch("https://oauth2.googleapis.com/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          client_id: GOOGLE_CLIENT_ID,
          client_secret: GOOGLE_CLIENT_SECRET,
          refresh_token: tokens.refresh_token,
          grant_type: "refresh_token",
        }),
      });
    } else if (tokens.provider === "microsoft") {
      if (!MS_CLIENT_ID || !MS_CLIENT_SECRET) return null;

      response = await fetch("https://login.microsoftonline.com/common/oauth2/v2.0/token", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          client_id: MS_CLIENT_ID,
          client_secret: MS_CLIENT_SECRET,
          refresh_token: tokens.refresh_token,
          grant_type: "refresh_token",
        }),
      });
    } else {
      return null;
    }

    if (!response.ok) return null;

    const newTokens = await response.json();
    const expiresAt = newTokens.expires_in
      ? new Date(Date.now() + newTokens.expires_in * 1000).toISOString()
      : null;

    // Update stored tokens
    await supabase
      .from("calendar_tokens")
      .update({
        access_token: newTokens.access_token,
        refresh_token: newTokens.refresh_token || tokens.refresh_token,
        expires_at: expiresAt,
      })
      .eq("tenant_id", tokens.tenant_id)
      .eq("provider", tokens.provider);

    return newTokens.access_token;
  } catch (error) {
    console.error("Token refresh error:", error);
    return null;
  }
}

async function fetchGoogleBusyTimes(
  accessToken: string,
  calendarIds: string[],
  startDate: Date,
  endDate: Date
): Promise<{ start_at: string; end_at: string; external_event_id: string; summary?: string; location?: string; description?: string }[]> {
  const events: { start_at: string; end_at: string; external_event_id: string; summary?: string; location?: string; description?: string }[] = [];

  if (calendarIds.length === 0) {
    calendarIds = ["primary"];
  }

  console.log("=== GOOGLE CALENDAR EVENTS REQUEST ===");
  console.log("Calendar IDs requested:", JSON.stringify(calendarIds));
  console.log("Time range:", startDate.toISOString(), "to", endDate.toISOString());

  // Use Events API to get full event details (title, location, description)
  for (const calendarId of calendarIds) {
    try {
      const eventsUrl = new URL(`https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(calendarId)}/events`);
      eventsUrl.searchParams.set("timeMin", startDate.toISOString());
      eventsUrl.searchParams.set("timeMax", endDate.toISOString());
      eventsUrl.searchParams.set("singleEvents", "true");
      eventsUrl.searchParams.set("orderBy", "startTime");
      eventsUrl.searchParams.set("maxResults", "250");

      const eventsResponse = await fetch(eventsUrl.toString(), {
        headers: {
          Authorization: `Bearer ${accessToken}`,
        },
      });

      if (!eventsResponse.ok) {
        const errorText = await eventsResponse.text();
        console.error(`Google Events API error for ${calendarId}:`, errorText);
        continue;
      }

      const eventsData = await eventsResponse.json();
      console.log(`=== GOOGLE EVENTS for ${calendarId} ===`);
      console.log(`Found ${eventsData.items?.length || 0} events`);

      for (const event of eventsData.items || []) {
        // Skip cancelled events
        if (event.status === "cancelled") continue;

        // Respect transparency ("transparent" means it shouldn't block availability)
        if (event.transparency === "transparent") {
          console.log(`  -> Skipping transparent event: "${event.summary}"`);
          continue;
        }

        const calendarTimeZone = eventsData.timeZone || event.start?.timeZone || "UTC";

        // Get start/end times
        let startAt: string | undefined = event.start?.dateTime || event.start?.date;
        let endAt: string | undefined = event.end?.dateTime || event.end?.date;

        console.log(
          `  Raw event: "${event.summary}" | start=${JSON.stringify(event.start)} | end=${JSON.stringify(event.end)}`
        );

        if (!startAt || !endAt) {
          console.log(`  -> Skipping: missing start or end time`);
          continue;
        }

        // All-day events: Google returns date-only (end is exclusive). Convert to a block.
        const isAllDay = !event.start?.dateTime && !!event.start?.date;
        if (isAllDay) {
          const startOffset = timeZoneOffsetForDate(calendarTimeZone, startAt);
          const endOffset = timeZoneOffsetForDate(calendarTimeZone, endAt);

          startAt = `${startAt}T00:00:00${startOffset}`;
          endAt = `${endAt}T00:00:00${endOffset}`;

          console.log(`  All-day event normalized (${calendarTimeZone}): ${startAt} -> ${endAt}`);
        }

        // Zero-duration events: treat as a small busy block to prevent double-booking
        if (startAt === endAt) {
          const DEFAULT_ZERO_DURATION_MINUTES = 15;
          const startMs = new Date(startAt).getTime();
          const endMs = startMs + DEFAULT_ZERO_DURATION_MINUTES * 60 * 1000;
          const normalizedEnd = new Date(endMs).toISOString();

          console.log(
            `  -> Zero-duration event normalized to ${DEFAULT_ZERO_DURATION_MINUTES}m: startAt=${startAt}, endAt=${normalizedEnd}`
          );

          endAt = normalizedEnd;
        }

        // Guard against invalid ranges after normalization
        if (new Date(endAt).getTime() <= new Date(startAt).getTime()) {
          console.log(`  -> Skipping: end <= start after normalization`);
          continue;
        }

        console.log(`  Event: "${event.summary}" | ${startAt} -> ${endAt}`);

        events.push({
          start_at: startAt,
          end_at: endAt,
          external_event_id: event.id || `google_${calendarId}_${startAt}`,
          summary: event.summary || "Busy",
          location: event.location || undefined,
          description: event.description ? event.description.substring(0, 500) : undefined,
        });
      }
    } catch (error) {
      console.error(`Error fetching events for calendar ${calendarId}:`, error);
    }
  }

  console.log(`=== TOTAL EVENTS FETCHED: ${events.length} ===`);
  return events;
}

async function fetchMicrosoftBusyTimes(
  accessToken: string,
  calendarIds: string[],
  startDate: Date,
  endDate: Date
): Promise<{ start_at: string; end_at: string; external_event_id: string; summary?: string }[]> {
  const events: { start_at: string; end_at: string; external_event_id: string; summary?: string }[] = [];

  try {
    // Get user email for schedule request
    const meResponse = await fetch("https://graph.microsoft.com/v1.0/me", {
      headers: { Authorization: `Bearer ${accessToken}` },
    });

    if (!meResponse.ok) {
      console.error("Microsoft me error:", await meResponse.text());
      return events;
    }

    const meData = await meResponse.json();
    const userEmail = meData.mail || meData.userPrincipalName;

    // Use getSchedule API
    const scheduleResponse = await fetch(
      "https://graph.microsoft.com/v1.0/me/calendar/getSchedule",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${accessToken}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          schedules: [userEmail],
          startTime: {
            dateTime: startDate.toISOString(),
            timeZone: "UTC",
          },
          endTime: {
            dateTime: endDate.toISOString(),
            timeZone: "UTC",
          },
          availabilityViewInterval: 30,
        }),
      }
    );

    if (!scheduleResponse.ok) {
      // Fallback to calendarView
      const viewResponse = await fetch(
        `https://graph.microsoft.com/v1.0/me/calendarview?startDateTime=${startDate.toISOString()}&endDateTime=${endDate.toISOString()}&$select=id,subject,start,end,showAs`,
        {
          headers: { Authorization: `Bearer ${accessToken}` },
        }
      );

      if (viewResponse.ok) {
        const viewData = await viewResponse.json();
        for (const event of viewData.value || []) {
          if (event.showAs === "busy" || event.showAs === "tentative" || event.showAs === "oof") {
            const startAt = event.start?.dateTime + "Z";
            const endAt = event.end?.dateTime + "Z";
            // Skip zero-duration events
            if (startAt === endAt) continue;
            events.push({
              start_at: startAt,
              end_at: endAt,
              external_event_id: event.id,
              summary: "Busy",
            });
          }
        }
      }
      return events;
    }

    const scheduleData = await scheduleResponse.json();
    for (const schedule of scheduleData.value || []) {
      for (const item of schedule.scheduleItems || []) {
        if (item.status !== "free") {
          const startAt = item.start?.dateTime + "Z";
          const endAt = item.end?.dateTime + "Z";
          // Skip zero-duration events
          if (startAt === endAt) continue;
          events.push({
            start_at: startAt,
            end_at: endAt,
            external_event_id: `ms_${schedule.scheduleId}_${item.start?.dateTime}`,
            summary: "Busy",
          });
        }
      }
    }
  } catch (error) {
    console.error("Error fetching Microsoft busy times:", error);
  }

  return events;
}

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { requireInternalSecret, serviceClient } from "../_shared/tenant.ts";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-closeloop-secret",
};

interface InventoryItem {
  stock_number?: string;
  vin?: string;
  year?: string;
  make?: string;
  model?: string;
  trim?: string;
  body_style?: string;
  color_exterior?: string;
  color_interior?: string;
  msrp_cents?: number;
  asking_price_cents?: number;
  internet_price_cents?: number;
  condition?: string;
  mileage?: number;
  status?: string;
  features?: string[];
  description?: string;
  photo_urls?: string[];
  lot_location?: string;
  days_on_lot?: number;
  external_id?: string;
}

interface SyncRequest {
  tenant_id: string;
  source: "dealersocket" | "vauto" | "cdk" | "manual";
  items: InventoryItem[];
  full_sync?: boolean; // If true, mark items not in payload as "sold"
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    requireInternalSecret(req);
    const body: SyncRequest = await req.json();
    const { tenant_id, source, items, full_sync } = body;

    if (!tenant_id || !source || !Array.isArray(items)) {
      throw new Error("tenant_id, source, and items[] are required");
    }

    const supabase = serviceClient();

    let upserted = 0;
    let skipped = 0;
    let errors = 0;

    for (const item of items) {
      try {
        // Must have at least stock_number or vin for upsert
        if (!item.stock_number && !item.vin) {
          skipped++;
          continue;
        }

        const record = {
          tenant_id,
          stock_number: item.stock_number || null,
          vin: item.vin || null,
          year: item.year || null,
          make: item.make || null,
          model: item.model || null,
          trim: item.trim || null,
          body_style: item.body_style || null,
          color_exterior: item.color_exterior || null,
          color_interior: item.color_interior || null,
          msrp_cents: item.msrp_cents ?? null,
          asking_price_cents: item.asking_price_cents ?? null,
          internet_price_cents: item.internet_price_cents ?? null,
          condition: item.condition || null,
          mileage: item.mileage ?? null,
          status: item.status || "available",
          features: item.features || null,
          description: item.description || null,
          photo_urls: item.photo_urls || null,
          lot_location: item.lot_location || null,
          days_on_lot: item.days_on_lot ?? null,
          external_id: item.external_id || null,
          external_source: source,
          last_synced_at: new Date().toISOString(),
        };

        // Try upsert by VIN first, then stock_number
        if (item.vin) {
          const { error } = await supabase
            .from("sales_inventory")
            .upsert(record, { onConflict: "tenant_id,vin", ignoreDuplicates: false });

          if (error) {
            console.error(`[sync-sales-inventory] VIN upsert error for ${item.vin}:`, error.message);
            errors++;
            continue;
          }
        } else if (item.stock_number) {
          const { error } = await supabase
            .from("sales_inventory")
            .upsert(record, { onConflict: "tenant_id,stock_number", ignoreDuplicates: false });

          if (error) {
            console.error(`[sync-sales-inventory] Stock upsert error for ${item.stock_number}:`, error.message);
            errors++;
            continue;
          }
        }

        upserted++;
      } catch (e) {
        console.error(`[sync-sales-inventory] Item error:`, e);
        errors++;
      }
    }

    // Full sync: mark items not present in this batch as "sold"
    if (full_sync && items.length > 0) {
      const syncedVins = items.map(i => i.vin).filter(Boolean) as string[];
      const syncedStocks = items.map(i => i.stock_number).filter(Boolean) as string[];

      if (syncedVins.length > 0) {
        await supabase
          .from("sales_inventory")
          .update({ status: "sold" })
          .eq("tenant_id", tenant_id)
          .eq("external_source", source)
          .eq("status", "available")
          .not("vin", "in", `(${syncedVins.join(",")})`);
      }
    }

    return new Response(JSON.stringify({
      success: true,
      summary: { upserted, skipped, errors, total: items.length },
    }), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (e) {
    const errorMessage = e instanceof Error ? e.message : String(e);
    console.error("[sync-sales-inventory] Error:", errorMessage);
    return new Response(JSON.stringify({ error: errorMessage }), {
      status: 400,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { serviceClient } from "../_shared/tenant.ts";
import { normalizePhoneE164 } from "../_shared/phoneNormalize.ts";

const TEKMETRIC_BASE_URL = "https://shop.tekmetric.com";

const STATUS_MAP: Record<string, string> = {
  Estimate: "intake",
  "Work In Progress": "in_progress",
  Complete: "completed",
  "Saved for Later": "on_hold",
  Posted: "picked_up",
  Deleted: "cancelled",
};

function mapStatus(tekStatus: string): string {
  return STATUS_MAP[tekStatus] || "intake";
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    const body = await req.json().catch(() => ({}));
    const targetTenantId = body.tenant_id;

    const svc = serviceClient();

    // If a specific tenant is provided, sync just that one
    // Otherwise this is called from the cron to sync all active tenants
    let integrations: Array<Record<string, unknown>> = [];

    if (targetTenantId) {
      const { data, error } = await svc
        .from("tenant_integrations")
        .select("*")
        .eq("tenant_id", targetTenantId)
        .eq("provider", "tekmetric")
        .eq("is_active", true)
        .single();

      if (error || !data) return errorResponse("No active Tekmetric integration for this tenant");
      integrations = [data];
    } else {
      const { data, error } = await svc
        .from("tenant_integrations")
        .select("*")
        .eq("provider", "tekmetric")
        .eq("is_active", true);

      if (error) return errorResponse("Failed to fetch integrations");
      integrations = data || [];
    }

    const results: Array<Record<string, unknown>> = [];

    for (const integration of integrations) {
      const tenantId = integration.tenant_id as string;
      const creds = integration.credentials_json as Record<string, string>;
      const config = integration.config_json as Record<string, unknown>;
      const accessToken = creds?.access_token;
      const shopId = config?.selected_shop_id;

      if (!accessToken || !shopId) {
        results.push({ tenant_id: tenantId, error: "Missing credentials or shop_id" });
        continue;
      }

      try {
        const syncResult = await syncTenantRepairOrders(
          svc,
          tenantId,
          accessToken,
          String(shopId),
          integration.sync_cursor as string | null,
          integration.id as string
        );
        results.push({ tenant_id: tenantId, ...syncResult });
      } catch (err) {
        console.error(`[sync-tekmetric] Error syncing tenant ${tenantId}:`, err);
        results.push({ tenant_id: tenantId, error: err.message });
      }
    }

    return jsonResponse({ synced: results.length, results });
  } catch (err) {
    console.error("[sync-tekmetric] Error:", err);
    return errorResponse(err.message || "Internal error", 500);
  }
});

async function syncTenantRepairOrders(
  svc: ReturnType<typeof serviceClient>,
  tenantId: string,
  accessToken: string,
  shopId: string,
  syncCursor: string | null,
  integrationId: string
) {
  // Build query params
  const params = new URLSearchParams({ shop: shopId, size: "100" });
  if (syncCursor) {
    params.set("updatedDateStart", syncCursor);
  }

  const url = `${TEKMETRIC_BASE_URL}/api/v1/repair-orders?${params}`;
  console.log(`[sync-tekmetric] Fetching: ${url}`);

  const res = await fetch(url, {
    headers: { Authorization: `Bearer ${accessToken}` },
  });

  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Tekmetric API error ${res.status}: ${errText.substring(0, 200)}`);
  }

  const data = await res.json();
  const repairOrders = data.content || data.data || [];

  let created = 0;
  let updated = 0;
  let skipped = 0;
  let latestUpdatedDate = syncCursor || "";

  for (const ro of repairOrders) {
    try {
      const externalId = `tekmetric:${ro.id}`;
      const roNumber = String(ro.repairOrderNumber || ro.roNumber || ro.id);
      const tekStatus = ro.repairOrderStatus?.name || ro.status || "Estimate";
      const clStatus = mapStatus(tekStatus);

      // Track latest updated date for cursor
      const roUpdated = ro.updatedDate || ro.updatedAt || "";
      if (roUpdated > latestUpdatedDate) latestUpdatedDate = roUpdated;

      // Resolve customer
      let customerId: string | null = null;
      let customerName: string | null = null;
      let customerPhone: string | null = null;

      const customer = ro.customer;
      if (customer) {
        customerName = [customer.firstName, customer.lastName].filter(Boolean).join(" ") || null;
        const rawPhone = customer.phone?.[0]?.number || customer.phone || customer.phoneNumber || "";
        customerPhone = normalizePhoneE164(typeof rawPhone === "string" ? rawPhone : String(rawPhone));

        if (customerPhone) {
          // Try to find existing customer
          const { data: existing } = await svc
            .from("customers")
            .select("id")
            .eq("tenant_id", tenantId)
            .eq("phone_e164", customerPhone)
            .maybeSingle();

          if (existing) {
            customerId = existing.id;
          } else {
            // Create new customer
            const { data: newCust } = await svc
              .from("customers")
              .insert({
                tenant_id: tenantId,
                phone_e164: customerPhone,
                phone_raw: typeof rawPhone === "string" ? rawPhone : String(rawPhone),
                full_name: customerName || "Unknown",
                source: "tekmetric",
              })
              .select("id")
              .single();
            customerId = newCust?.id || null;
          }
        }
      }

      // Resolve vehicle
      let vehicleId: string | null = null;
      const vehicle = ro.vehicle;
      if (vehicle) {
        const vin = vehicle.vin || null;
        const year = vehicle.year ? String(vehicle.year) : null;
        const make = vehicle.make || null;
        const model = vehicle.model || null;

        if (vin) {
          const { data: existingV } = await svc
            .from("customer_vehicles")
            .select("id")
            .eq("tenant_id", tenantId)
            .eq("vin", vin)
            .maybeSingle();

          if (existingV) {
            vehicleId = existingV.id;
          } else {
            const { data: newV } = await svc
              .from("customer_vehicles")
              .insert({
                tenant_id: tenantId,
                customer_id: customerId,
                vin,
                year: year ? parseInt(year) : null,
                make,
                model,
              })
              .select("id")
              .single();
            vehicleId = newV?.id || null;
          }
        } else if (year && make && model && customerId) {
          // Match by YMM + customer
          const { data: existingV } = await svc
            .from("customer_vehicles")
            .select("id")
            .eq("tenant_id", tenantId)
            .eq("customer_id", customerId)
            .eq("year", parseInt(year))
            .eq("make", make)
            .eq("model", model)
            .maybeSingle();

          if (existingV) {
            vehicleId = existingV.id;
          } else {
            const { data: newV } = await svc
              .from("customer_vehicles")
              .insert({
                tenant_id: tenantId,
                customer_id: customerId,
                year: parseInt(year),
                make,
                model,
              })
              .select("id")
              .single();
            vehicleId = newV?.id || null;
          }
        }
      }

      // Build job title
      const vehicleLabel = vehicle
        ? [vehicle.year, vehicle.make, vehicle.model].filter(Boolean).join(" ")
        : "";
      const title = vehicleLabel || `RO #${roNumber}`;

      // Upsert active_job
      const { data: existingJob } = await svc
        .from("active_jobs")
        .select("id, status")
        .eq("tenant_id", tenantId)
        .eq("external_id", externalId)
        .maybeSingle();

      if (existingJob) {
        // Update existing
        await svc
          .from("active_jobs")
          .update({
            status: clStatus,
            title,
            customer_id: customerId,
            customer_name: customerName,
            customer_phone: customerPhone,
            vehicle_id: vehicleId,
            is_active: clStatus !== "cancelled" && clStatus !== "picked_up",
            actual_completion: clStatus === "completed" ? new Date().toISOString() : undefined,
          })
          .eq("id", existingJob.id);
        updated++;
      } else {
        // Create new
        const { data: newJob, error: jobErr } = await svc
          .from("active_jobs")
          .insert({
            tenant_id: tenantId,
            external_id: externalId,
            job_number: `RO-${roNumber}`,
            title,
            status: clStatus,
            priority: "normal",
            intake_method: "tekmetric",
            customer_id: customerId,
            customer_name: customerName,
            customer_phone: customerPhone,
            vehicle_id: vehicleId,
            is_active: clStatus !== "cancelled" && clStatus !== "picked_up",
            metadata_json: {
              tekmetric_ro_id: ro.id,
              tekmetric_status: tekStatus,
            },
          })
          .select("id")
          .single();

        if (jobErr) {
          console.error("[sync-tekmetric] Job insert error:", jobErr);
          skipped++;
          continue;
        }

        // Create service items from Tekmetric "jobs"
        const tekJobs = ro.jobs || [];
        if (newJob && tekJobs.length > 0) {
          const items = tekJobs.map((j: Record<string, unknown>, i: number) => ({
            job_id: newJob.id,
            tenant_id: tenantId,
            title: (j.name || j.description || `Service ${i + 1}`) as string,
            status: j.completed ? "completed" : "pending",
            sort_order: i,
          }));

          await svc.from("job_service_items").insert(items);
        }

        created++;
      }
    } catch (roErr) {
      console.error("[sync-tekmetric] RO processing error:", roErr);
      skipped++;
    }
  }

  // Update sync cursor
  await svc
    .from("tenant_integrations")
    .update({
      last_synced_at: new Date().toISOString(),
      sync_cursor: latestUpdatedDate || null,
    })
    .eq("id", integrationId);

  console.log(`[sync-tekmetric] Tenant ${tenantId}: created=${created}, updated=${updated}, skipped=${skipped}`);
  return { created, updated, skipped, total: repairOrders.length };
}

import { corsHeaders, corsResponse, jsonResponse, errorResponse } from "../_shared/cors.ts";
import { requireAuthedTenant, serviceClient } from "../_shared/tenant.ts";

const TEKMETRIC_BASE_URL = "https://shop.tekmetric.com";

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") return corsResponse();

  try {
    const { tenantId } = await requireAuthedTenant(req);
    const body = await req.json();
    const { action } = body;

    const svc = serviceClient();

    if (action === "exchange-token") {
      // Step 1: Exchange client credentials for access token
      const { client_id, client_secret } = body;
      if (!client_id || !client_secret) {
        return errorResponse("client_id and client_secret are required");
      }

      const tokenRes = await fetch(`${TEKMETRIC_BASE_URL}/api/v1/oauth/token`, {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          grant_type: "client_credentials",
          client_id,
          client_secret,
        }),
      });

      if (!tokenRes.ok) {
        const errText = await tokenRes.text();
        console.error("[tekmetric-auth] Token exchange failed:", tokenRes.status, errText);
        return errorResponse("Failed to authenticate with Tekmetric. Check your Client ID and Secret.", 401);
      }

      const tokenData = await tokenRes.json();
      const accessToken = tokenData.access_token;
      if (!accessToken) {
        return errorResponse("No access token received from Tekmetric");
      }

      // Fetch available shops
      const shopsRes = await fetch(`${TEKMETRIC_BASE_URL}/api/v1/shops`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });

      if (!shopsRes.ok) {
        return errorResponse("Authenticated but failed to fetch shops");
      }

      const shopsData = await shopsRes.json();
      const shops = (shopsData.content || shopsData.data || shopsData || []).map(
        (s: Record<string, unknown>) => ({
          id: s.id,
          name: s.name || s.shopName || `Shop ${s.id}`,
          phone: s.phone || "",
          address: s.address || "",
        })
      );

      // Store credentials temporarily (user still needs to pick a shop)
      await svc.from("tenant_integrations").upsert(
        {
          tenant_id: tenantId,
          provider: "tekmetric",
          credentials_json: { access_token: accessToken, client_id },
          config_json: { shops, selected_shop_id: null },
          is_active: false,
        },
        { onConflict: "tenant_id,provider" }
      );

      return jsonResponse({ shops });
    }

    if (action === "select-shop") {
      // Step 2: User picked a shop — activate sync
      const { shop_id } = body;
      if (!shop_id) return errorResponse("shop_id is required");

      const { data: existing, error: fetchErr } = await svc
        .from("tenant_integrations")
        .select("config_json")
        .eq("tenant_id", tenantId)
        .eq("provider", "tekmetric")
        .single();

      if (fetchErr || !existing) {
        return errorResponse("No Tekmetric credentials found. Authenticate first.");
      }

      const config = existing.config_json as Record<string, unknown>;
      const shops = (config.shops || []) as Array<Record<string, unknown>>;
      const selectedShop = shops.find((s) => String(s.id) === String(shop_id));

      const { error: updateErr } = await svc
        .from("tenant_integrations")
        .update({
          config_json: {
            ...config,
            selected_shop_id: shop_id,
            selected_shop_name: selectedShop?.name || `Shop ${shop_id}`,
          },
          is_active: true,
        })
        .eq("tenant_id", tenantId)
        .eq("provider", "tekmetric");

      if (updateErr) {
        console.error("[tekmetric-auth] Failed to activate:", updateErr);
        return errorResponse("Failed to save shop selection");
      }

      return jsonResponse({ success: true, shop_name: selectedShop?.name });
    }

    if (action === "disconnect") {
      await svc
        .from("tenant_integrations")
        .update({ is_active: false })
        .eq("tenant_id", tenantId)
        .eq("provider", "tekmetric");

      return jsonResponse({ success: true });
    }

    if (action === "toggle") {
      const { is_active } = body;
      await svc
        .from("tenant_integrations")
        .update({ is_active: !!is_active })
        .eq("tenant_id", tenantId)
        .eq("provider", "tekmetric");

      return jsonResponse({ success: true });
    }

    return errorResponse("Unknown action");
  } catch (err) {
    console.error("[tekmetric-auth] Error:", err);
    return errorResponse(err.message || "Internal error", 500);
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { corsResponse, errorResponse, jsonResponse } from "../_shared/cors.ts";
import { sendEmail } from "../_shared/sendEmail.ts";

interface TriggerWorkflowRequest {
  tenant_id: string;
  trigger: string;
  entity_type: string;
  entity_id: string;
  location_id?: string;
  session_id?: string; // AI call session that triggered this workflow
  details?: Record<string, any>;
  customer?: Record<string, any>;
  summary?: string;
  dry_run?: boolean; // If true, simulate without sending webhooks/SMS
  retry_run_id?: string; // If set, this is a retry of a previous run
}


function nowIso() {
  return new Date().toISOString();
}

// Resolve nested path like "details.priority" from context
function resolvePath(path: string, ctx: Record<string, any>): any {
  return path.split(".").reduce((acc: any, k: string) => (acc ? acc[k] : undefined), ctx);
}

// Evaluate edge conditions - supports multiple formats
function evalCondition(condition: any, ctx: Record<string, any>): boolean {
  if (!condition || Object.keys(condition).length === 0) return true;

  // New format: { "equals": ["order_type", "delivery"] }
  if (condition.equals?.length === 2) {
    const [path, value] = condition.equals;
    const got = resolvePath(path, ctx);
    return String(got) === String(value);
  }

  // New format: { "exists": ["customer_email"] }
  if (condition.exists?.length === 1) {
    const [path] = condition.exists;
    const got = resolvePath(path, ctx);
    return got !== undefined && got !== null && got !== "";
  }

  // Existing format: { index: 0 } for branch nodes - handled in traversal
  if (condition.index !== undefined) return true;

  return false;
}

// Load workflow graph with adjacency list for efficient traversal
async function loadGraph(supabase: any, workflow_id: string) {
  const [nodesRes, edgesRes] = await Promise.all([
    supabase.from("workflow_nodes").select("*").eq("workflow_id", workflow_id),
    supabase.from("workflow_edges").select("*").eq("workflow_id", workflow_id),
  ]);

  if (nodesRes.error) throw new Error(nodesRes.error.message);
  if (edgesRes.error) throw new Error(edgesRes.error.message);

  const nodes = nodesRes.data ?? [];
  const edges = edgesRes.data ?? [];

  // Build adjacency list for O(1) edge lookup
  const outgoing = new Map<string, any[]>();
  for (const e of edges) {
    const arr = outgoing.get(e.from_node_id) ?? [];
    arr.push(e);
    outgoing.set(e.from_node_id, arr);
  }

  // Find start node: named "Start" OR node with no incoming edges
  const incomingCount = new Map<string, number>();
  for (const n of nodes) incomingCount.set(n.id, 0);
  for (const e of edges) {
    incomingCount.set(e.to_node_id, (incomingCount.get(e.to_node_id) ?? 0) + 1);
  }

  let start = nodes.find((n: any) => (n.name || "").toLowerCase() === "start")?.id;
  if (!start) start = nodes.find((n: any) => (incomingCount.get(n.id) ?? 0) === 0)?.id;
  if (!start && nodes.length > 0) start = nodes[0].id;

  return { nodes, edges, outgoing, start };
}

// Load delivery settings for webhook URLs, notify phones
async function loadDeliverySettings(supabase: any, tenant_id: string) {
  const { data } = await supabase
    .from("universal_delivery_settings")
